						CONVERT(varchar,ERROR_LINE())		+ '-' +
						ERROR_MESSAGE())
			END CATCH

			SELECT	@rv						[code],
					@ret_ErrorDescription	[error_description]
		END
END
GO











CREATE PROCEDURE [dbo].[spSaleOrderWS_insertItemV2]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@wst_id			INT, --webservice
	@guid			UNIQUEIDENTIFIER,
	@stor_id		INT,
	@item_id		INT,
	@prli_id		INT,
	@item_qty		DECIMAL(18,5),
	@sdlmt_id		INT
)
AS


BEGIN


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE @comp_id	INT,
			@lang_id	INT,
			@bra_id		INT,
			@wst_id		INT,
			@stor_id	INT,
			@item_id	INT,
			@prli_id	INT,
			@item_qty	INT,
			@guid		UNIQUEIDENTIFIER

	SELECT	@comp_id	= 1,
			@lang_id	= 2,
			@bra_id		= 1,
			@wst_id		= 10,
			@stor_id	= 3,
			@item_id	= 256,
			@prli_id	= 1,
			@item_qty	= 2,
			@guid		= '1ADEA5E1-C9B7-4A76-834D-C8919D74E552'
	*/
	-- -------------------------------------------------------------------------------


	SET NOCOUNT ON


	BEGIN TRY


		DECLARE @ret_ErrorDescription	VARCHAR(1000)
		SET		@ret_ErrorDescription	= ''



		DECLARE @tis_priority INT
		EXEC spCounters_getNextValue
				@comp_id,
				@stor_id,
				1, --contador prioridades
				@counter_value = @tis_priority OUTPUT



		DECLARE @tis_itemDesc NVARCHAR(100)
		SELECT	@tis_itemDesc = ti.item_desc
			FROM	tbItem ti		WITH (NOLOCK)
			WHERE	ti.comp_id	= @comp_id
			AND		ti.item_id	= @item_id



		DECLARE @curr_id	INT,
				@tis_price  DECIMAL(19,5)
		SELECT	@curr_id	= tpli.curr_id,
				@tis_price	= tpli.prli_price
			FROM	tbPriceListItems tpli			WITH (NOLOCK)
			WHERE	tpli.comp_id	= @comp_id
			AND		tpli.prli_id	= @prli_id
			AND		tpli.item_id	= @item_id



		DECLARE	@getdate	DATETIME
		SET @getdate = GETDATE()


		DECLARE @storg_id AS INT = NULL
		DECLARE @user_id INT
		SELECT	@user_id	= tws.[user_id],
				@storg_id   = storg_id
			FROM	tbWebServices tws			WITH (NOLOCK)
			WHERE	tws.comp_id	= @comp_id
			AND		tws.wst_id	= @wst_id


		---- ----------------------------------------------------------------------------------
		-- **wlfkn23904723aNDQN4355
		-- MOS: 09-2024: 21820 IDEM a Ticket 11482, Colucci, para que tome del deposito del grupo que Tenga Stock Disponible
		---- ----------------------------------------------------------------------------------
		IF	@storg_id IS NOT NULL	AND
			@storg_id			> 0 -- MOS 12-2022: x Colucci, si tenian definidos los grupos de deposito a cambiar, NO le da pelota si es FULL
			BEGIN
				DECLARE			@stor_idTMP AS integer = NULL
				SELECT TOP 1	@stor_idTMP = stor_id
					FROM tbStorageGroupDetail AS tsgd	WITH (NOLOCK)
					WHERE	tsgd.comp_id	= @comp_id		AND
							tsgd.storg_id	= @storg_id		AND
							dbo.fnGetAStock4MaxAssociation(tsgd.comp_id,tsgd.stor_id,@item_id,999999999) > 0
					ORDER BY tsgd.storg_order4MercadoLibre	ASC

				IF @stor_idTMP IS NOT NULL
					BEGIN
						SET @stor_id = @stor_idTMP
					END
			END
		---- ----------------------------------------------------------------------------------



		DECLARE @rv INT

		DECLARE @wsID AS UNIQUEIDENTIFIER
		SET		@wsID = NEWID()

		EXEC spTempItemStock_insertData
			@comp_id,
			@guid,
			@tis_priority,
			@item_id,
			@tis_itemDesc,
			@tis_itemDesc,
			@curr_id,
			@item_qty,
			@item_qty,
			@prli_id,
			@tis_price,
			@stor_id,
			0,						--@doc_id
			@bra_id,
			@user_id,
			@getdate,				--@insertDate = null,
			@getdate,				--@lastUpdate = null,
			0,						--@tis_cost = null,
			1,						--@tis_costTax = null,
			null,					--@soh_id = null,
			null,					--@sod_id = null,
			'true',					--@to_associate = null,
			null,					--@is_id = null,
			'false',				--@tis_isMade = null,
			@wsID,'',
			-1,
			@return_value = @rv OUTPUT



		--para que no borre los items el depurador
		UPDATE tbTempItemStock		WITH (ROWLOCK)
			SET	tis_IsEditingCd = DATEADD(hour,1,GETDATE()),
				sdlmt_id		= @sdlmt_id
			WHERE tis_id = @rv


		SET		@ret_ErrorDescription	= 'Insert OK'
		--SELECT @rv [code],



	END TRY
	BEGIN CATCH

			Set @rv			= -1
			Set @ret_ErrorDescription	= 'Item_Insert - ' +
				(SELECT
				convert(varchar,ERROR_NUMBER())		+ '-' +
				convert(varchar,ERROR_SEVERITY())	+ '-' +
				convert(varchar,ERROR_STATE())		+ '-' +
				convert(varchar,ERROR_LINE())		+ '-' +
				ERROR_MESSAGE())

	END CATCH


	SELECT	@rv						[code],
			@ret_ErrorDescription	[error_description]

END

GO





-- ATENCION si se toca algo aca hacerlo tambien en : spSaleOrderWS_insertSaleOrderMercedoLibre


CREATE PROCEDURE [dbo].[spSaleOrderWS_insertSaleOrder]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@wst_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@cust_id			INT,
	@sd_id				INT
)
AS
SET NOCOUNT ON



BEGIN




	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@wst_id				INT,
			@cust_id			INT,
			@sd_id				INT

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@guid				='6455CD8D-20A5-4966-B027-F5FDF3047D19',
			@wst_id				=10,
			@cust_id			=24288,
			@sd_id				=1

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -------------------------------------------------------------------------------





	declare @return_value		INT,
			@errormessage		NVARCHAR(1000)

	set		@return_value = 0
	set		@errormessage = ''







	--obtenemos el df_id para generar el pedido
	DECLARE @df_id		INT

	SELECT	TOP 1 @df_id	= df_id

	FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)

	WHERE	sd_id			= @sd_id

	ORDER BY CASE
				WHEN is4WS = 1 THEN 0
				ELSE				1
			 END,
			 df_order






	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					FROM tbTempItemStock ttis
					WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid)

		BEGIN

			SET @return_value = -2
			SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 99

		END

	ELSE

		IF @df_id IS NULL
			BEGIN

				SET @return_value = -3
				SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 91

			END

		ELSE

	/*
			BEGIN
				--SELECT 2
				--se controla que no se supere el porcentaje de stock potencial seteado en tbwebsite_names
				--de lo que se está cargando en el pedido de cada artículo
				DECLARE cursor_tis CURSOR FOR
				SELECT	ttis.item_id, ttis.tis_qty, ttis.tis_priority
				FROM	tbTempItemStock ttis
				WHERE	ttis.comp_id = @comp_id AND ttis.tis_guid = @guid

				OPEN cursor_tis

				FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority


				WHILE @@FETCH_STATUS = 0 and @return_value = 0
				BEGIN

					SET @potential_stock = dbo.fnGetAStock(@comp_id, @stor_id, @item_id, @tis_priority)

					--SELECT '@potential_stock', @potential_stock, (@potential_stock * @ws_PotentialStockLimit / 100), @tis_qty, @stor_id



					--Si la cantidad a reservar en el pedido (@tis_qty) es mayor que el porcentaje de stock potencial disponible
					--para la venta on line (@potential_stock * @ws_PotentialStockLimit / 100) se muestra un mensaje que le
					--indica al cliente conectado que no hay stock disponible
					IF @tis_qty > (@potential_stock * @ws_PotentialStockLimit / 100)
					BEGIN
						SET @return_value = -3

						SELECT	@errormessage = tut.utexts_desc + ti.item_code + '-' + ti.item_desc
						FROM	tbsysUniqueTexts tut
								INNER JOIN tbItem ti
								ON	ti.comp_id	= @comp_id
								AND ti.item_id	= @item_id
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 98
					END


					FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority
				END
				CLOSE cursor_tis
				DEALLOCATE cursor_tis
				--SELECT 3
	*/



	--si no hubo errores por stock se genera el pedido
	IF @return_value = 0
	BEGIN

		BEGIN TRANSACTION
		BEGIN TRY



			DECLARE @rv								INT




			DECLARE @sm_id							INT,
					@st_id							INT,
					@disc_id						INT,
					@dl_id							INT,
					@curr_id_cust					INT

			SELECT	@sm_id			= tc.sm_id,
					@st_id			= tc.st_id,
					@disc_id		= tc.disc_id,
					@dl_id			= tc.dl_id,
					@curr_id_cust	= tc.curr_id

			FROM	tbCustomer		tc

			WHERE	tc.comp_id		= @comp_id
			AND		tc.cust_id		= @cust_id


			-- obtengo el documento para REMITOS asociado a este documento si es que lo tiene.. .
			DECLARE @intDFId4PackingList AS INT
			SET		@intDFId4PackingList = NULL
			SELECT  @intDFId4PackingList = tdf.df_SaleOrderPL_df_Id
				FROM tbDocumentsFile tdf  WITH (NOLOCK)
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id



			DECLARE @curr_id_branch					INT,
					@bra_PriceDecimalPlaces			INT,
					@bra_SaleOrderDisposeLimitDay	INT,
					@country_id						INT,
					@state_id						INT

			SELECT	@curr_id_branch					= tb.curr_id,
					@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
					@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
					@country_id						= tb.country_id,
					@state_id						= tb.state_id

			FROM	tbBranch		tb

			WHERE	tb.comp_id		= @comp_id
			AND		tb.bra_id		= @bra_id





			DECLARE @user_id		INT

			SELECT	@user_id	= tws.[user_id]
			FROM	tbWebServices tws
			WHERE	tws.comp_id = @comp_id
			AND		tws.wst_id	= @wst_id




			/******************************************************************************************/
			CREATE TABLE #tmpGetTotalsData
			(
				t1		INT,
				t2		DECIMAL(18,2),
				t3		DECIMAL(19,6),
				t4		DECIMAL(19,6),
				t5		DECIMAL(19,6),
				t6		DECIMAL(18,2),
				t7		DECIMAL(19,5),
				t8		INT,
				t9		DECIMAL(19,6),
				T10		NVARCHAR(4000),
				TotalNoInterest  DECIMAL(25,6)
			)

			--INSERT INTO #tmpGetTotalsData
				--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



			-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
			DECLARE	@exchange		DECIMAL(38,25)   -- MOS 01-2024 DECIMAL(19,6)

			SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')





			-- recuperar los totales generales
			INSERT INTO #tmpGetTotalsData
				EXEC	sptmpTax_calculate
						@comp_id,
						@bra_id,
						@cust_id,
						@guid,
						@curr_id_branch,
						@disc_id,
						@country_id,
						@state_id,
						@st_id,
						@curr_id_branch,
						@curr_id_cust,
						@exchange,
						'false',
						@df_id,
						'true',
						@dl_id,
						0,
						'false',
						'false',
						-1,
						-1 -- @ccp_id No INformado


			DECLARE @total					DECIMAL(19,6),
					@soh_discount			DECIMAL(19,6)

			SELECT	@total			= t2,
					@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
			FROM	#tmpGetTotalsData

			--SELECT	@total, @soh_discount
			/******************************************************************************************/






			DECLARE @getdate		DATETIME
			DECLARE @limitdate		DATETIME
			DECLARE @onlydate		DATETIME

			SET		@getdate	= GETDATE()
			SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
			SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay

			/*
			SELECT 	@guid,
					@comp_id,
					@bra_id,
					@onlydate,
					@onlydate,
					@sm_id,
					@cust_id,
					@st_id,
					@disc_id,
					@dl_id,
					@onlydate,
					@limitdate,
					@user_id,
					@getdate,
					@total,
					@df_id,
					@exchange,
					@curr_id_cust
			*/


			EXEC spSaleOrder_insertData
					-1,
					@guid,
					@comp_id,
					@bra_id,
					@onlydate,
					@onlydate,
					'',
					'',
					'',
					'',
					'false',
					@sm_id,
					@cust_id,
					@st_id,
					@disc_id,
					@dl_id,
					null,
					@onlydate,
					@limitdate,
					1,				--+------------------------------------------------------------------------------------
					'A',			--|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
					1,				--+------------------------------------------------------------------------------------
					@user_id,
					'false',
					@getdate,
					@total,
					@df_id,
					5,
					@exchange,
					@curr_id_cust,
					null,
					NULL,
					@return_value = @rv OUTPUT



			EXEC	spSaleOrderHeader_updatePL_df_id
					@comp_id,
					@bra_id,
					@rv,
					@intDFId4PackingList ,		-- MOS 04-2020
					null,
					@soh_discount,
					''



			EXEC	spSaleOrder_updateCurrExchange
					@comp_id,
					@bra_id,
					@rv,
					@curr_id_cust,
					@exchange,
					0 --@decInCash


			DELETE FROM tbtmpTax		WHERE tis_guid = @guid
			DELETE FROM tbTempItemStock WHERE tis_guid = @guid



			SET @return_value = @rv
			SET @errormessage = 'SaleOrder OK'


			COMMIT TRANSACTION


		END
		TRY BEGIN CATCH
			--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
			ROLLBACK TRANSACTION
			SET @return_value = -1
			SET @errormessage = ERROR_MESSAGE()

		END CATCH

	END


	BEGIN TRY

		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------
		-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
		----------------------------------------------------------------------------------------------------------------
		IF @return_value > 0
		BEGIN



			DECLARE @strMailTo		NVARCHAR(4000),
					@subject		NVARCHAR(800),
					@strBody		NVARCHAR(800),
					@lsm_id			INT



			--recuparamos el email y el vendedor del cliente
			SELECT	@strMailTo		= tc.cust_email,
					@lsm_id				= tc.sm_id
				FROM	tbCustomer							tc
				WHERE	tc.comp_id			= @comp_id
				AND		tc.cust_id			= @cust_id


--		IF @lsm_id IS NULL
--			SET @strMailTo = @strMailTo + ';' + (SELECT	twsn.ws_email_contact
--													FROM	tbWebSite_Names				twsn
--													WHERE	twsn.comp_id	= @comp_id
--													AND		twsn.ws_id		= @ws_id)
--
--		ELSE
--			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
--													FROM	tbSalesman					ts
--													WHERE	ts.comp_id		= @comp_id
--													AND		ts.sm_id		= @lsm_id)





			--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
			--se recupara el email del vendedor asignado al cliente

			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
														FROM	tbSalesman					ts
														WHERE	ts.comp_id		= @comp_id AND
																ts.sm_id		= @lsm_id)

			DECLARE @strFooter AS NVARCHAR(MAX)

			DECLARE @strMailFrom AS NVARCHAR(MAX)
			SELECT	@subject	= ISNULL(tws.wst_SaleOrderSubject,'Pedido Nro:'),
					@strBody	= ISNULL(tws.wst_SaleOrderBody,''),
					@strMailFrom= ISNULL(tws.wst_SaleOrderMailFrom,''),
					@strFooter  = ISNULL(tws.wst_SaleOrderFooter,'')
				FROM tbWebServices tws
			WHERE	tws.comp_id = @comp_id AND
					tws.wst_id  = @wst_id



			--agregamos al mensaje que enviaremos al body del email las siguientes partes:
			--número de pedido
			--cliente
			--vendedor si hay un vendedor asignado al clientes
			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

							(SELECT	tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

							(SELECT tswn.word_desc
							 FROM	tbSysWordsNew	tswn
							 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 297) + ' ' + convert(varchar,@cust_id) + ' - ' +
							(SELECT tc.cust_name
							 FROM	tbCustomer		tc
							 WHERE	tc.comp_id = @comp_id AND tc.cust_id = @cust_id)

			IF NOT @lsm_id IS NULL
				BEGIN
					SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

								(SELECT tswn.word_desc
								 FROM	tbSysWordsNew	tswn
								 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +
								(SELECT ts.sm_name
								 FROM	tbSalesman		ts
								 WHERE	ts.comp_id = @comp_id AND ts.sm_id = @lsm_id)
				END


			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +  @strFooter

			--se envía el correo si se recuperaron direcciones de emails
			IF NOT @strMailTo IS NULL
				BEGIN

					exec spSystem_sendEMail
							@compId						= @comp_id,
							@precipients				= @strMailTo,
							@pcopy_recipients			= null,
							@psubject					= @subject,
							@pbody_format				= 'HTML',
							@pbody						= @strBody,
							@pfile_attachments			= null,
							@pReplyTo					= @strMailFrom,
							@pblind_copy_recipients		= '',
							@pUser_Id					= @user_id

				END

		END
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------

	END TRY
	BEGIN CATCH
		SET @return_value = @return_value
	END CATCH



	--RETURN @return_value
	SELECT	@return_value	[code],
			@errormessage	[error_description]



END
GO


-- ESTO ES SOLO PARA FULLJAUS
CREATE PROCEDURE [dbo].[spSaleOrderWS_insertSaleOrder4FullJaus]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@wst_id					INT,
	@guid					UNIQUEIDENTIFIER,
	@cust_id				INT,
	--@sd_id				INT,
	@dl_id					INT,
	@disc_id				INT,
	@st_id					INT,
	@sm_id					INT,
	@soh_Observation1		NVARCHAR(200),
	@soh_Observation2		NVARCHAR(200),
	@soh_Observation3		NVARCHAR(200),
	@soh_Observation4		NVARCHAR(200),
	@IsCredit				BIT,
	@soh_note4ExternalUse	NVARCHAR(20),
	@soh_MLGUIA				AS NVARCHAR(50)
)
AS

BEGIN

	SET NOCOUNT ON


	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@wst_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@cust_id			INT,
			--@sd_id				INT,
			@dl_id				INT,
			@disc_id			INT,
			@st_id				INT,
			@sm_id				INT,
			@soh_Observation1	NVARCHAR(200),
			@soh_Observation2	NVARCHAR(200),
			@soh_Observation3	NVARCHAR(200),
			@soh_Observation4	NVARCHAR(200),
			@IsCredit			BIT

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@wst_id				= 10,
			@guid				= '6455CD8D-20A5-4966-B027-F5FDF3047D19',
			@cust_id			= 24288,
			--@sd_id				= 1,
			@dl_id				= 1,
			@disc_id			= 1,
			@st_id				= 1,
			@sm_id				= 1,
			@soh_Observation1	= '',
			@soh_Observation2	= '',
			@soh_Observation3	= '',
			@soh_Observation4	= '',
			@IsCredit			= 'False'

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -------------------------------------------------------------------------------


	-- --------------------------------------------------------------------
	-- MOS 10-2023: Si ponen en este campo se busca y reemplaza el vendedor
	-- SOLO reemplaza si es que cargaron algo y lo encuentra.
	-- --------------------------------------------------------------------
	--ICBC MALL
	--Tienda Clic
	--Tienda Supervielle
	--Megatone
	--MercadoLibre
	--Avenida+
	--Banco Patagonia
	--Frávega seller-center
	--Fulljaus
	--Tienda BNA
	--Tienda nube
	--Tienda Ciudad
	--Via Compras
	--Tienda Columbia
	--Paseo Libertad
	--Pardo
	--Provincia Compras
	--BBVA Go Shop
	--Quiero!
	--Tienda IUPP
	--Garbarino
	--Mirakl
	--Carrefour Marketplace
	-- --------------------------------------------------------------------
	SET @soh_note4ExternalUse = UPPER(dbo.fnStrAllTrim(@soh_note4ExternalUse))

	SELECT @st_id = tst.st_id
	FROM tbSalesTerms AS tst	WITH (NOLOCK)
		WHERE	tst.comp_id			=	@comp_id AND
				tst.st_WSPreference =	@soh_note4ExternalUse

	SELECT @sm_id = tst.sm_id
	FROM tbSalesMan AS tst	WITH (NOLOCK)
		WHERE	tst.comp_id			=	@comp_id AND
				tst.sm_WSPreference =	@soh_note4ExternalUse
	-- --------------------------------------------------------------------



	DECLARE
		@return_value	INT,
		@errormessage	NVARCHAR(1000)
	SET	@return_value	= 0
	SET	@errormessage	= ''

	--obtenemos el df_id para generar el pedido QUE SEA FAVORITO PARA FULLJAUS
	DECLARE
		@df_id		INT,
		@sd_id		INT

	IF @IsCredit = 'True'
		BEGIN
			SET @sd_id = 3
		END
	ELSE
		BEGIN
			SET @sd_id = 1
		END

	IF @disc_id = -1
		BEGIN
			SET @disc_id = NULL
		END

	IF @dl_id = -1
		BEGIN
			SET		@dl_id	= NULL
			SELECT	@dl_id	= dl_id		-- MOS 07-2022 x SecOne al q FJ le cargaba el transporte en -1
				FROM tbCustomer AS tc WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @cust_id
		END

	SELECT	TOP 1
		@df_id	= df_id
		FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
		WHERE	sd_id			= @sd_id
		ORDER BY CASE
					WHEN is4FJ = 1 THEN 0
					ELSE				1
				 END,
				 df_order


	-- --------------------------------------------------------
	-- 10-20-2020
	-- STL FULLJAUS QUIERE QUE LA LISTA DE PRECIOS
	-- NO SOLO SE CARGUE EN LOS ITEMS, SINO QUE TAMBIEN SE
	-- CARGUE EN EL PEDIDO, RECUPERO ACA LA LISTA DEFINIDA
	-- PARA FULLJAUS Y ACTUALIZO LA LISTA DE PRECIOS
	-- --------------------------------------------------------
	DECLARE
		@prli_id	INT
	SELECT
		@prli_id = tws.prli_id4FullJaus
		FROM tbWebServices tws						WITH (NOLOCK)
		WHERE	tws.comp_id = @comp_id AND
				tws.wst_id	= @wst_id
	-- --------------------------------------------------------


	DECLARE @intDFId4PackingList		AS INT = NULL
	DECLARE
		@bitForceSaleOrder4Preparation AS BIT  = 'False'
	SELECT
		@intDFId4PackingList			= tdf.df_SaleOrderPL_df_Id,
		@bitForceSaleOrder4Preparation	= ISNULL(tdf.df_FullJaus_SaleOrderInPreparation,'False')
		FROM tbDocumentsFile			tdf WITH(NOLOCK)
		WHERE	tdf.comp_id = @comp_id	AND
				tdf.df_id	= @df_id

	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					FROM tbTempItemStock ttis WITH (NOLOCK)
					WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid)
		BEGIN
			SET @return_value = -2
			SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 99
		END
	ELSE
		IF @df_id IS NULL
			BEGIN
				SET @return_value = -3
				SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 91
			END
		ELSE
	--si no hubo errores por stock se genera el pedido
			IF @return_value = 0
				BEGIN

					BEGIN TRANSACTION
					BEGIN TRY
						DECLARE @rv			INT
						--==
							--IMPORTANTE!
							--COMENTE EL SM_ID porque va a venir como parámetro del SP ahora, ya que tendría que ser un campo configurable a nivel de WebService
							--LO MISMO PASA CON EL ST_ID, con el bra_id y con los id de documentos
						--==

						DECLARE
							--@sm_id			INT,
							@curr_id_cust	INT

						SELECT
							--@sm_id				= tc.sm_id,
							@curr_id_cust		= tc.curr_id
							FROM	tbCustomer	tc	 WITH (NOLOCK)
							WHERE	tc.comp_id	= @comp_id
							AND		tc.cust_id	= @cust_id

						DECLARE @curr_id_branch					INT,
								@bra_PriceDecimalPlaces			INT,
								@bra_SaleOrderDisposeLimitDay	INT,
								@country_id						INT,
								@state_id						INT

						SELECT	@curr_id_branch					= tb.curr_id,
								@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
								@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
								@country_id						= tb.country_id,
								@state_id						= tb.state_id
							FROM	tbBranch		tb		 WITH (NOLOCK)
							WHERE	tb.comp_id		= @comp_id
							AND		tb.bra_id		= @bra_id


						DECLARE
							@user_id		INT

						SELECT
							@user_id			= tws.[user_id]
							FROM	tbWebServices	tws		WITH(NOLOCK)
							WHERE	tws.comp_id = @comp_id
							AND		tws.wst_id	= @wst_id


						/******************************************************************************************/
						CREATE TABLE #tmpGetTotalsData
						(
							t1		INT,
							t2		DECIMAL(18,2),
							t3		DECIMAL(19,6),
							t4		DECIMAL(19,6),
							t5		DECIMAL(19,6),
							t6		DECIMAL(18,2),
							t7		DECIMAL(19,5),
							t8		INT,
							t9		DECIMAL(19,6),
							T10		NVARCHAR(4000),
							TotalNoInterest  DECIMAL(25,6)
						)

						--INSERT INTO #tmpGetTotalsData
							--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



						-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
						DECLARE	@exchange		DECIMAL(38,25)   -- MOS 01-2024 DECIMAL(19,6)
						SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')

						-- recuperar los totales generales
						INSERT INTO #tmpGetTotalsData
							EXEC	sptmpTax_calculate
									@comp_id,
									@bra_id,
									@cust_id,
									@guid,
									@curr_id_branch,
									@disc_id,
									@country_id,
									@state_id,
									@st_id,
									@curr_id_branch,
									@curr_id_cust,
									@exchange,
									'false',
									@df_id,
									'true',
									@dl_id,
									0,
									'false',
									'false',
									-1,
									-1 -- @ccp_id No INformado


						DECLARE @total					DECIMAL(19,6),
								@soh_discount			DECIMAL(19,6)

						SELECT	@total			= t2,
								@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
						FROM	#tmpGetTotalsData

						--SELECT	@total, @soh_discount
						/******************************************************************************************/

						DECLARE @getdate		DATETIME
						DECLARE @limitdate		DATETIME
						DECLARE @onlydate		DATETIME

						SET		@getdate	= GETDATE()
						SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
						SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay


						DECLARE @ssos_id AS INT = 5
						IF @bitForceSaleOrder4Preparation = 'True'  SET @ssos_id = 20 -- Si el documento lo dice lo pongo en PREPARACION.-


						EXEC spSaleOrder_insertData
								-1,
								@guid,
								@comp_id,
								@bra_id,
								@onlydate,
								@onlydate,
								@soh_Observation1,	--+--------------------------------------------------------------------
								@soh_Observation2,	--|Estos 4 campos se agregaron para FullJaus, acá van a mandar la
								@soh_Observation3,	--|tienda desde donde se realizó la compra, en un futuro puede cambiar
								@soh_Observation4,	--+--------------------------------------------------------------------
								'false',
								@sm_id,
								@cust_id,
								@st_id,
								@disc_id,
								@dl_id,
								null,
								@onlydate,
								@limitdate,
								1,				--+------------------------------------------------------------------------------------
								'A',			--|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
								1,				--+------------------------------------------------------------------------------------
								@user_id,
								'false',
								@getdate,
								@total,
								@df_id,
								@ssos_id ,--5,
								@exchange,
								@curr_id_cust,
								null,
								NULL,
								@return_value = @rv OUTPUT



						EXEC	spSaleOrderHeader_updatePL_df_id
								@comp_id,
								@bra_id,
								@rv,
								@intDFId4PackingList,
								null,
								@soh_discount,
								''



						EXEC	spSaleOrder_updateCurrExchange
								@comp_id,
								@bra_id,
								@rv,
								@curr_id_cust,
								@exchange,
								0 --@decInCash

						--*********************************************************************************************************************
						-- FULLJAUS ACA GRABA EL MARKETPLACE QUE DESPUES VA A FILTRAR EN SALEORDERALL Y EN EL METODO QUE RECUPERA LOS PEDIDOS
						-- PEDIDO POR PABLO DE FULLJAUS 23-12-2019
						--*********************************************************************************************************************
						UPDATE tbSaleOrderHeader	WITH (ROWLOCK)
						SET
							soh_note4ExternalUse = @soh_note4ExternalUse,
							prli_id				 = @prli_id,
							soh_MLGUIA			 = CASE WHEN @soh_MLGUIA = '0' THEN NULL ELSE @soh_MLGUIA END
						WHERE	comp_id = @comp_id	AND
								bra_id	= @bra_id	AND
								soh_id	= @rv
						--*********************************************************************************************************************


						DELETE FROM tbtmpTax		WHERE tis_guid = @guid
						DELETE FROM tbTempItemStock WHERE tis_guid = @guid



						SET @return_value = @rv
						SET @errormessage = 'SaleOrder OK'


						COMMIT TRANSACTION


					END
					TRY BEGIN CATCH
						--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
						ROLLBACK TRANSACTION
						SET @return_value = -1
						SET @errormessage = ERROR_MESSAGE()

					END CATCH

				END

	BEGIN TRY
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------
		-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
		----------------------------------------------------------------------------------------------------------------
		IF @return_value > 0
		BEGIN
			DECLARE @strMailTo		NVARCHAR(4000),
					@subject		NVARCHAR(800),
					@strBody		NVARCHAR(800),
					@lsm_id			INT



			--recuparamos el email y el vendedor del cliente
			SELECT
				@strMailTo			= tc.cust_email,
				@lsm_id				= tc.sm_id
				FROM	tbCustomer	tc		 WITH(NOLOCK)
				WHERE	tc.comp_id	= @comp_id
				AND		tc.cust_id	= @cust_id

			--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
			--se recupara el email del vendedor asignado al cliente

			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
														FROM	tbSalesman					ts
														WHERE	ts.comp_id		= @comp_id AND
																ts.sm_id		= @lsm_id)

			DECLARE @strFooter AS NVARCHAR(MAX)

			DECLARE @strMailFrom AS NVARCHAR(MAX)
			SELECT	@subject	= ISNULL(tws.wst_SaleOrderSubject,'Pedido Nro:'),
					@strBody	= ISNULL(tws.wst_SaleOrderBody,''),
					@strMailFrom= ISNULL(tws.wst_SaleOrderMailFrom,''),
					@strFooter  = ISNULL(tws.wst_SaleOrderFooter,'')
				FROM tbWebServices tws	 WITH (NOLOCK)
				WHERE	tws.comp_id = @comp_id AND
						tws.wst_id  = @wst_id



			--agregamos al mensaje que enviaremos al body del email las siguientes partes:
			--número de pedido
			--cliente
			--vendedor si hay un vendedor asignado al clientes
			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

							(SELECT	tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

							(SELECT tswn.word_desc
							 FROM	tbSysWordsNew	tswn
							 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 297) + ' ' + convert(varchar,@cust_id) + ' - ' +
							(SELECT tc.cust_name
							 FROM	tbCustomer		tc
							 WHERE	tc.comp_id = @comp_id AND tc.cust_id = @cust_id)

			IF NOT @lsm_id IS NULL
				BEGIN
					SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

								(SELECT tswn.word_desc
								 FROM	tbSysWordsNew	tswn		 WITH (NOLOCK)
								 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +
								(SELECT ts.sm_name
								 FROM	tbSalesman		ts			 WITH (NOLOCK)
								 WHERE	ts.comp_id = @comp_id AND ts.sm_id = @lsm_id)
				END


			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +  @strFooter

			--se envía el correo si se recuperaron direcciones de emails
			IF NOT @strMailTo IS NULL        AND 1 = 2  -- MOS 01-04-2020
				BEGIN

					exec spSystem_sendEMail
							@compId						= @comp_id,
							@precipients				= @strMailTo,
							@pcopy_recipients			= null,
							@psubject					= @subject,
							@pbody_format				= 'HTML',
							@pbody						= @strBody,
							@pfile_attachments			= null,
							@pReplyTo					= @strMailFrom,
							@pblind_copy_recipients		= '',
							@pUser_Id					= @user_id

				END

		END
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------

	END TRY
	BEGIN CATCH
		SET @return_value = @return_value
	END CATCH



	-- ------------------------------------------------------------------------------------------------
	-- MOS 07-2022: Verifica YA AHORA que el nuevo pedido no tenga publicaciones que actualizar.
	-- **wqlknfdlqwn098765gtfc
	-- ------------------------------------------------------------------------------------------------
	BEGIN TRY
		IF EXISTS(
					SELECT TOP 1 1
						FROM tbMercadoLibre_Stores AS tmls	WITH (NOLOCK)
						WHERE	tmls.mls_disabled = 'False' AND
								ABS(DATEDIFF(day, tmls.mls_accessTokenValidUp2Date,GETDATE())) < 2
				)
			BEGIN
				UPDATE tbSaleOrderDetail
					SET	sod_MercadoLibre_MustUpdateStock = 'True'
					FROM tbSaleOrderDetail sod							WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ItemsPublicados AS tmlip	WITH (NOLOCK)
						ON	tmlip.comp_id	= sod.comp_id AND
							tmlip.item_id	= sod.item_id
					INNER JOIN tbMercadoLibre_Stores		  AS tmls	WITH (NOLOCK)
						ON	tmls.comp_id	= tmlip.comp_id AND
							tmls.mls_id		= tmlip.mls_id
					WHERE
							SOD.comp_id			= @comp_id			AND
							SOD.bra_id			= @bra_id			AND
							SOD.soh_id			= @return_value		AND
							tmls.mls_disabled	 = 'False'		AND
							ABS(DATEDIFF(day, tmls.mls_accessTokenValidUp2Date,GETDATE())) < 2	AND
							tmlip.mlp_Active	= 'True'


				EXEC spSaleOrder_MercadoLibre_VerificarItemsSinStockDisponible @comp_id,@bra_id,@return_value,@guid
				EXEC spSystem_MercadoLibreProcessQueue_4GUID @guid
			END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ------------------------------------------------------------------------------------------------















	--RETURN @return_value
	SELECT	@return_value	[code],
			@errormessage	[error_description]



END
GO





-- ATENCION si se toca algo aca hacerlo tambien en : spSaleOrderWS_insertSaleOrder


CREATE PROCEDURE [dbo].[spSaleOrderWS_insertSaleOrder4MercadoLibre]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@wst_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@cust_id			INT,
	@sd_id				INT,
	@deliveryLabel		NVARCHAR(4000),
	@xmlQuestionsAndAnswers AS NTEXT
)
AS
SET NOCOUNT ON



BEGIN




	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@wst_id				INT,
			@cust_id			INT,
			@sd_id				INT

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@guid				='6455CD8D-20A5-4966-B027-F5FDF3047D19',
			@wst_id				=10,
			@cust_id			=24288,
			@sd_id				=1

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -------------------------------------------------------------------------------





	declare @return_value		INT,
			@errormessage		NVARCHAR(1000)

	set		@return_value = 0
	set		@errormessage = ''







	--obtenemos el df_id para generar el pedido
	DECLARE @df_id		INT

	SELECT	TOP 1 @df_id	= df_id

	FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)

	WHERE	sd_id			= @sd_id

	ORDER BY df_order







	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					FROM tbTempItemStock ttis
					WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid)

		BEGIN

			SET @return_value = -2
			SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 99

		END

	ELSE

		IF @df_id IS NULL
			BEGIN

				SET @return_value = -3
				SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 91

			END

		ELSE

	/*
			BEGIN
				--SELECT 2
				--se controla que no se supere el porcentaje de stock potencial seteado en tbwebsite_names
				--de lo que se está cargando en el pedido de cada artículo
				DECLARE cursor_tis CURSOR FOR
				SELECT	ttis.item_id, ttis.tis_qty, ttis.tis_priority
				FROM	tbTempItemStock ttis
				WHERE	ttis.comp_id = @comp_id AND ttis.tis_guid = @guid

				OPEN cursor_tis

				FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority


				WHILE @@FETCH_STATUS = 0 and @return_value = 0
				BEGIN

					SET @potential_stock = dbo.fnGetAStock(@comp_id, @stor_id, @item_id, @tis_priority)

					--SELECT '@potential_stock', @potential_stock, (@potential_stock * @ws_PotentialStockLimit / 100), @tis_qty, @stor_id



					--Si la cantidad a reservar en el pedido (@tis_qty) es mayor que el porcentaje de stock potencial disponible
					--para la venta on line (@potential_stock * @ws_PotentialStockLimit / 100) se muestra un mensaje que le
					--indica al cliente conectado que no hay stock disponible
					IF @tis_qty > (@potential_stock * @ws_PotentialStockLimit / 100)
					BEGIN
						SET @return_value = -3

						SELECT	@errormessage = tut.utexts_desc + ti.item_code + '-' + ti.item_desc
						FROM	tbsysUniqueTexts tut
								INNER JOIN tbItem ti
								ON	ti.comp_id	= @comp_id
								AND ti.item_id	= @item_id
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 98
					END


					FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority
				END
				CLOSE cursor_tis
				DEALLOCATE cursor_tis
				--SELECT 3
	*/



	--si no hubo errores por stock se genera el pedido
	IF @return_value = 0
	BEGIN

		BEGIN TRANSACTION
		BEGIN TRY



			DECLARE @rv								INT




			DECLARE @sm_id							INT,
					@st_id							INT,
					@disc_id						INT,
					@dl_id							INT,
					@curr_id_cust					INT

			SELECT	@sm_id			= tc.sm_id,
					@st_id			= tc.st_id,
					@disc_id		= tc.disc_id,
					@dl_id			= tc.dl_id,
					@curr_id_cust	= tc.curr_id

			FROM	tbCustomer		tc

			WHERE	tc.comp_id		= @comp_id
			AND		tc.cust_id		= @cust_id





			DECLARE @curr_id_branch					INT,
					@bra_PriceDecimalPlaces			INT,
					@bra_SaleOrderDisposeLimitDay	INT,
					@country_id						INT,
					@state_id						INT

			SELECT	@curr_id_branch					= tb.curr_id,
					@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
					@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
					@country_id						= tb.country_id,
					@state_id						= tb.state_id

			FROM	tbBranch		tb

			WHERE	tb.comp_id		= @comp_id
			AND		tb.bra_id		= @bra_id





			DECLARE @user_id		INT

			SELECT	@user_id	= tws.[user_id]
			FROM	tbWebServices tws
			WHERE	tws.comp_id = @comp_id
			AND		tws.wst_id	= @wst_id




			/******************************************************************************************/
			CREATE TABLE #tmpGetTotalsData
			(
				t1		INT,
				t2		DECIMAL(18,2),
				t3		DECIMAL(19,6),
				t4		DECIMAL(19,6),
				t5		DECIMAL(19,6),
				t6		DECIMAL(18,2),
				t7		DECIMAL(19,5),
				t8		INT,
				t9		DECIMAL(19,6),
				T10		NVARCHAR(4000),
				TotalNoInterest		DECIMAL(25,6)
			)

			--INSERT INTO #tmpGetTotalsData
				--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



			-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
			DECLARE	@exchange		DECIMAL(38,25)   -- MOS 01-2024 DECIMAL(19,6)

			SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')





			-- recuperar los totales generales
			INSERT INTO #tmpGetTotalsData
				EXEC	sptmpTax_calculate
						@comp_id,
						@bra_id,
						@cust_id,
						@guid,
						@curr_id_branch,
						@disc_id,
						@country_id,
						@state_id,
						@st_id,
						@curr_id_branch,
						@curr_id_cust,
						@exchange,
						'false',
						@df_id,
						'true',
						@dl_id,
						0,
						'false',
						'false',
						-1,
						-1 -- @ccp_id No INformado


			DECLARE @total					DECIMAL(19,6),
					@soh_discount			DECIMAL(19,6)

			SELECT	@total			= t2,
					@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
			FROM	#tmpGetTotalsData

			--SELECT	@total, @soh_discount
			/******************************************************************************************/






			DECLARE @getdate		DATETIME
			DECLARE @limitdate		DATETIME
			DECLARE @onlydate		DATETIME

			SET		@getdate	= GETDATE()
			SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
			SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay

			/*
			SELECT 	@guid,
					@comp_id,
					@bra_id,
					@onlydate,
					@onlydate,
					@sm_id,
					@cust_id,
					@st_id,
					@disc_id,
					@dl_id,
					@onlydate,
					@limitdate,
					@user_id,
					@getdate,
					@total,
					@df_id,
					@exchange,
					@curr_id_cust
			*/


			EXEC spSaleOrder_insertData
					-1,
					@guid,
					@comp_id,
					@bra_id,
					@onlydate,
					@onlydate,
					'',
					'',
					'',
					'',
					'false',
					@sm_id,
					@cust_id,
					@st_id,
					@disc_id,
					@dl_id,
					null,
					@onlydate,
					@limitdate,
					1,				--+------------------------------------------------------------------------------------
					'A',			--|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
					1,				--+------------------------------------------------------------------------------------
					@user_id,
					'false',
					@getdate,
					@total,
					@df_id,
					5,
					@exchange,
					@curr_id_cust,
					null,
					NULL,
					@return_value = @rv OUTPUT



			EXEC	spSaleOrderHeader_updatePL_df_id
					@comp_id,
					@bra_id,
					@rv,
					null,
					null,
					@soh_discount,
					''


			EXEC	spSaleOrder_updateCurrExchange
					@comp_id,
					@bra_id,
					@rv,
					@curr_id_cust,
					@exchange,
					0 --@decInCash


			UPDATE tbSaleOrderHeader
			SET soh_MLdeliveryLabel			= @deliveryLabel ,
				soh_MLQuestionsAndAnswers	= @xmlQuestionsAndAnswers
				WHERE	comp_id = @comp_id	AND
						bra_id	= @bra_id	AND
						soh_id	= @rv


			DELETE FROM tbtmpTax		WHERE tis_guid = @guid
			DELETE FROM tbTempItemStock WHERE tis_guid = @guid



			SET @return_value = @rv
			SET @errormessage = '# of SaleOrder OK'


			COMMIT TRANSACTION


		END
		TRY BEGIN CATCH
			--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
			ROLLBACK TRANSACTION
			SET @return_value = -1
			SET @errormessage = ERROR_MESSAGE()

		END CATCH

	END


	BEGIN TRY

		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------
		-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
		----------------------------------------------------------------------------------------------------------------
		IF @return_value > 0
		BEGIN



			DECLARE @strMailTo		NVARCHAR(4000),
					@subject		NVARCHAR(800),
					@strBody		NVARCHAR(800),
					@lsm_id			INT



			--recuparamos el email y el vendedor del cliente
			SELECT	@strMailTo		= tc.cust_email,
					@lsm_id				= tc.sm_id
				FROM	tbCustomer							tc
				WHERE	tc.comp_id			= @comp_id
				AND		tc.cust_id			= @cust_id




			--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
			--se recupara el email del vendedor asignado al cliente

			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
														FROM	tbSalesman					ts
														WHERE	ts.comp_id		= @comp_id AND
																ts.sm_id		= @lsm_id)

			DECLARE @strFooter AS NVARCHAR(MAX)

			DECLARE @strMailFrom AS NVARCHAR(MAX)
			SELECT	@subject	= ISNULL(tws.wst_SaleOrderSubject,'Pedido Nro:'),
					@strBody	= ISNULL(tws.wst_SaleOrderBody,''),
					@strMailFrom= ISNULL(tws.wst_SaleOrderMailFrom,''),
					@strFooter  = ISNULL(tws.wst_SaleOrderFooter,'')
				FROM tbWebServices tws
			WHERE	tws.comp_id = @comp_id AND
					tws.wst_id  = @wst_id



			--agregamos al mensaje que enviaremos al body del email las siguientes partes:
			--número de pedido
			--cliente
			--vendedor si hay un vendedor asignado al clientes
			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

							(SELECT	tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

							(SELECT tswn.word_desc
							 FROM	tbSysWordsNew	tswn
							 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 297) + ' ' + convert(varchar,@cust_id) + ' - ' +
							(SELECT tc.cust_name
							 FROM	tbCustomer		tc
							 WHERE	tc.comp_id = @comp_id AND tc.cust_id = @cust_id)

			IF NOT @lsm_id IS NULL
				BEGIN
					SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

								(SELECT tswn.word_desc
								 FROM	tbSysWordsNew	tswn
								 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +
								(SELECT ts.sm_name
								 FROM	tbSalesman		ts
								 WHERE	ts.comp_id = @comp_id AND ts.sm_id = @lsm_id)
				END

			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' + @strFooter

			--se envía el correo si se recuperaron direcciones de emails
			IF NOT @strMailTo IS NULL
				BEGIN

					exec spSystem_sendEMail
							@compId						= @comp_id,
							@precipients				= @strMailTo,
							@pcopy_recipients			= null,
							@psubject					= @subject,
							@pbody_format				= 'HTML',
							@pbody						= @strBody,
							@pfile_attachments			= null,
							@pReplyTo					= @strMailFrom,
							@pblind_copy_recipients		= '',
							@pUser_Id					= @user_id

				END

		END
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------

	END TRY
	BEGIN CATCH
		SET @return_value = @return_value
	END CATCH



	--RETURN @return_value
	SELECT	@return_value	[code],
			@errormessage	[error_description]



END
GO






-- ATENCION si se toca algo aca hacerlo tambien en : spSaleOrderWS_insertSaleOrder


CREATE PROCEDURE [dbo].[spSaleOrderWS_insertSaleOrder4MercadoLibreV2]
(
 @comp_id					INT,
 @lang_id					INT,
 @bra_id					INT,
 @wst_id					INT,
 @guid						UNIQUEIDENTIFIER,
 @cust_id					INT,
 @sd_id						INT,
 @deliveryLabel				NVARCHAR(4000),
 @xmlQuestionsAndAnswers	AS NTEXT,
 @MLSOId					AS NVARCHAR(50),
 @PointOfSale				AS INT,
 @soh_MLGUIA				AS NVARCHAR(50),
 @dl_Id						AS INT,
 @st_Id						AS INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------------------------------
		-- Testing
		-- -------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@guid		UNIQUEIDENTIFIER,
				@wst_id		INT,
				@cust_id	INT,
				@sd_id		INT

			SELECT
				@comp_id   =1,
				@lang_id   =2,
				@bra_id    =1,
				@guid		='6455CD8D-20A5-4966-B027-F5FDF3047D19',
				@wst_id    =10,
				@cust_id   =24288,
				@sd_id		=1

			IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
		*/
		-- -------------------------------------------------------------------------------





		DECLARE
			@return_value  INT,
			@errormessage  NVARCHAR(1000)

		SET  @return_value = 0
		SET  @errormessage = ''


		-- ---------------------------------------------------------
		-- Verifica si ese numero de pedido YA esta cargado I
		-- ---------------------------------------------------------
		SET  @return_value = 0
		DECLARE @soh_bra_id AS INT
		DECLARE @soh_id		AS INT
		SELECT
			@return_value	= tsoh.soh_id,
			@soh_bra_id		= tsoh.bra_id,
			@soh_id			= tsoh.soh_id,
			@errormessage	= '#001 the SaleOrder previously has been saved with this Number'
			FROM tbSaleOrderHeader				tsoh   --WITH (NOLOCK)
			WHERE	tsoh.comp_id	= @comp_id	AND
					tsoh.soh_MLId	= @MLSOId

		IF @return_value <> 0
			BEGIN

				-- Actualizo x las dudas el nro de guia del pedido.
				UPDATE tbsaleorderheader		WITH (ROWLOCK)
					SET soh_MLGUIA					= @soh_MLGUIA,
						soh_MLQuestionsAndAnswers	= @xmlQuestionsAndAnswers,
						soh_MLdeliveryLabel			= @deliveryLabel,
						dl_id						=	CASE
															WHEN @dl_Id > 0 THEN	@dl_Id
															ELSE					dl_id
														END,
						st_id						=	CASE
															WHEN @st_Id > 0  THEN	@st_Id
															ELSE					st_id
														END
					WHERE	comp_id = @comp_id		AND
							bra_id	= @soh_bra_id	AND
							soh_id	= @soh_id

				SELECT	@return_value [code],
						@errormessage [error_description]
				RETURN
			END
		-- ---------------------------------------------------------



		-- ---------------------------------------------------------
		-- Verifica si ese numero de pedido YA esta cargado y Facturado
		-- ---------------------------------------------------------
		SET  @return_value = 0
		SELECT
			@return_value	= tsoh.soh_id,
			@soh_bra_id		= tsoh.bra_id,
			@soh_id			= tsoh.soh_id,
			@errormessage	= '#001 the SaleOrder previously has been saved with this Number and Has Been Emmited'
			FROM tbSaleOrderHeaderHistory		tsoh   --WITH (NOLOCK)
			WHERE	tsoh.comp_id	= @comp_id	AND
					tsoh.soh_MLId	= @MLSOId

		IF @return_value <> 0
			BEGIN

				-- Actualizo x las dudas el nro de guia del pedido.
				UPDATE tbsaleorderheaderHistory		WITH (ROWLOCK)
				SET
					soh_MLGUIA		= @soh_MLGUIA
					WHERE	comp_id = @comp_id		AND
							bra_id	= @soh_bra_id	AND
							soh_id	= @soh_id

				SELECT
					@return_value [code],
					@errormessage [error_description]
				RETURN
			END
		-- ---------------------------------------------------------


		-- Busca el Documento
		DECLARE
			@sm_id			INT,
			@disc_id		INT,
			@intDL_Id		INT,
			@curr_id_cust   INT

		SELECT
			@sm_id			= tc.sm_id,
			@st_id			=	CASE
									WHEN @st_Id > 0 THEN	@st_Id
									ELSE					tc.st_id
								END,
									@disc_id		= tc.disc_id,
									@intDL_Id		= tc.dl_id,
									@curr_id_cust	= tc.curr_id
			FROM tbCustomer					tc     WITH (NOLOCK)
			WHERE	tc.comp_id  = @comp_id	AND
					tc.cust_id  = @cust_id


		-- Si se especifica un pto de vta x cond de vta reemplaza al que informa producteca.
		-- Esto es para que busque 1ro los documentos disponibles de este punto de ventas en particular
		-- y si no encuentra nada q busque un documento . . .
		SELECT
			TOP 1
				@PointOfSale =	CASE
									WHEN ISNULL(tst.st_pointOfSale4MercadoLibre,0) > 0   THEN tst.st_pointOfSale4MercadoLibre
								ELSE              @PointOfSale
								END
			FROM tbSalesTerms				tst		WITH (NOLOCK)
			INNER JOIN tbDocumentsFile		tdf		WITH (NOLOCK)
				ON	tdf.comp_id = @comp_id	AND
					tdf.bra_id	= @bra_id	AND
					tdf.sd_id	= @sd_id
			WHERE	tst.comp_id = @comp_id	AND
					tst.st_id	= @st_Id    AND
			(
				(tst.st_pointOfSale4MercadoLibre  = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre > 0 )
				OR
				(tst.st_pointOfSale4MercadoLibre2 = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre2 > 0)
				OR
				(tst.st_pointOfSale4MercadoLibre3 = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre3 > 0)
				OR
				(tst.st_pointOfSale4MercadoLibre4 = tdf.df_pointOfSale AND tst.st_pointOfSale4MercadoLibre4 > 0)
			)
			AND tdf.df_Disabled = 'False'
			ORDER BY tdf.df_order





		--obtenemos el df_id para generar el pedido
		DECLARE
			@df_id  INT
		SET @df_id  = NULL
		DECLARE
			@bitForce2Preparation AS BIT
		SET @bitForce2Preparation = 0

		SELECT
			TOP 1
				@df_id = df_id
			FROM  dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
			WHERE	sd_id			= @sd_id			AND
					df_pointOfSale	= @PointOfSale

			ORDER BY	CASE
							WHEN is4ML = 1 THEN 0
							ELSE    1
						END,
						df_order

		IF @df_id IS NULL
		BEGIN
			SELECT
				TOP 1
					@df_id = df_id
				FROM  dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
				WHERE sd_id   = @sd_id
				ORDER BY
						CASE
							WHEN is4ML = 1 THEN 0
							ELSE				1
						END,
						df_order
		END



		-- obtengo el documento para REMITOS asociado a este documento si es que lo tiene.. .
		DECLARE @ssos_id				AS INT
		DECLARE @intDFId4PackingList	AS INT
		SET  @ssos_id					= 20
		SET  @intDFId4PackingList		= NULL
		SELECT
			@intDFId4PackingList = tdf.df_SaleOrderPL_df_Id,
			@ssos_id =	CASE
							WHEN tdf.df_forceOKEmission					= 'True'	THEN	50
							WHEN tdf.df_forcePreparation				= 'True'	THEN	20
							WHEN tdf.df_SaleOrderCommercialSuggests		= 'True'	THEN	10
							WHEN    tb.bra_SaleOrderCommercialSuggests	= 'True'	THEN	10
							ELSE															20
						END
		FROM tbDocumentsFile					tdf  WITH (NOLOCK)
			INNER JOIN tbBranch					tb   WITH (NOLOCK)
				ON	tb.comp_id	= tdf.comp_id	AND
					tb.bra_id	= tdf.bra_id
		WHERE	tdf.comp_id = @comp_id			AND
				tdf.df_id	= @df_id			AND
				tdf.df_Disabled = 'False'





		--se controla que haya artículos cargados en la temporal
		IF NOT EXISTS (SELECT
							TOP 1 1
							FROM tbTempItemStock				ttis  WITH (NOLOCK)
							WHERE	ttis.comp_id	= @comp_id	AND
									ttis.tis_guid	= @guid)

			BEGIN

				SET @return_value = -2
				SELECT
					@errormessage		= tut.utexts_desc
					FROM tbsysUniqueTexts				tut  WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id	AND
							tut.utexts_id	= 99

				SELECT
					@return_value [code],
					@errormessage [error_description]

				RETURN

			END



		IF @df_id IS NULL
			BEGIN

				SET @return_value = -3
				SELECT
					@errormessage		= tut.utexts_desc
					FROM tbsysUniqueTexts				tut  WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id	AND
							tut.utexts_id	= 91

				SELECT
					@return_value [code],
					@errormessage [error_description]

				RETURN
			END


		INSERT INTO tbMercadoLibre_Producteca_OrdersInserted(soh_MLId)
			VALUES (@MLSOId)


		IF @return_value = 0   --si no hubo errores por stock se genera el pedido
			BEGIN

				BEGIN TRANSACTION
				BEGIN TRY

					DECLARE @rv        INT

					IF @dl_Id > 0
						BEGIN
							SET @intDL_Id = @dl_Id
						END


					DECLARE
						@curr_id_branch					INT,
						@bra_PriceDecimalPlaces			INT,
						@bra_SaleOrderDisposeLimitDay	INT,
						@country_id						INT,
						@state_id						INT

					SELECT
						@curr_id_branch					= tb.curr_id,
						@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
						@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
						@country_id						= tb.country_id,
						@state_id						= tb.state_id
						FROM tbBranch					tb   WITH (NOLOCK)
						WHERE	tb.comp_id  = @comp_id	AND
								tb.bra_id	= @bra_id





					DECLARE	@user_id  INT
					DECLARE @bitML_cancellMailWithSaleOrderCreation BIT

					SELECT
						@user_id			= tws.[user_id],
						@bitML_cancellMailWithSaleOrderCreation = ISNULL(tws.ML_cancellMailWithSaleOrderCreation,'False')
						FROM tbWebServices				tws   WITH (NOLOCK)
						WHERE	tws.comp_id = @comp_id	AND
								tws.wst_id	= @wst_id




					/******************************************************************************************/
					CREATE TABLE #tmpGetTotalsData
					(
						t1  INT,
						t2  DECIMAL(18,2),
						t3  DECIMAL(19,6),
						t4  DECIMAL(19,6),
						t5  DECIMAL(19,6),
						t6  DECIMAL(18,2),
						t7  DECIMAL(19,5),
						t8  INT,
						t9  DECIMAL(19,6),
						T10  NVARCHAR(4000),
						TotalNoInterest  DECIMAL(25,6)
					)

					--INSERT INTO #tmpGetTotalsData
					--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



					-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
					DECLARE @exchange  DECIMAL(38,25)   -- MOS 01-2024 DECIMAL(19,6)

					SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')





					-- recuperar los totales generales
					INSERT INTO #tmpGetTotalsData
					EXEC sptmpTax_calculate
						@comp_id,
						@bra_id,
						@cust_id,
						@guid,
						@curr_id_branch,
						@disc_id,
						@country_id,
						@state_id,
						@st_id,
						@curr_id_branch,
						@curr_id_cust,
						@exchange,
						'false',
						@df_id,
						'true',
						@intDL_Id,
						0,
						'false',
						'false',
						-1,
						-1 -- @ccp_id No INformado


					DECLARE
						@total			DECIMAL(19,6),
						@soh_discount   DECIMAL(19,6)

					SELECT
						@total			= t2,
						@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
						FROM #tmpGetTotalsData

					--SELECT @total, @soh_discount
					/******************************************************************************************/






					DECLARE @getdate  DATETIME
					DECLARE @limitdate  DATETIME
					DECLARE @onlydate  DATETIME

					SET  @getdate = GETDATE()
					SELECT
						@onlydate = DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
					SET  @limitdate = @onlydate + @bra_SaleOrderDisposeLimitDay


					EXEC spSaleOrder_insertData
					-1,
					@guid,
					@comp_id,
					@bra_id,
					@onlydate,
					@onlydate,
					'',
					'',
					'',
					'',
					'false',
					@sm_id,
					@cust_id,
					@st_id,
					@disc_id,
					@intDL_Id,
					null,
					@onlydate,
					@limitdate,
					1,    --+------------------------------------------------------------------------------------
					'A',   --|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
					1,    --+------------------------------------------------------------------------------------
					@user_id,
					'false',
					@getdate,
					@total,
					@df_id,
					@ssos_id /*20*/,  -- a Preparacion directo
					@exchange,
					@curr_id_cust,
					null,
					NULL,
					@return_value = @rv OUTPUT



					EXEC spSaleOrderHeader_updatePL_df_id
					@comp_id,
					@bra_id,
					@rv,
					@intDFId4PackingList,
					null,
					@soh_discount,
					''



					EXEC spSaleOrder_updateCurrExchange
					@comp_id,
					@bra_id,
					@rv,
					@curr_id_cust,
					@exchange,
					0 --@decInCash


					UPDATE tbSaleOrderHeader	WITH (ROWLOCK)
					SET
						soh_MLdeliveryLabel			= @deliveryLabel ,
						soh_MLQuestionsAndAnswers	= @xmlQuestionsAndAnswers,
						soh_MLId					= @MLSOId,
						soh_MLGUIA					= dbo.fnGetOnlyNumbers(@soh_MLGUIA)
					WHERE	comp_id					= @comp_id AND
							bra_id					= @bra_id AND
							soh_id					= @rv


					DELETE FROM tbtmpTax  WHERE tis_guid = @guid
					DELETE FROM tbTempItemStock WHERE tis_guid = @guid



					SET @return_value = @rv
					SET @errormessage = '#000 SaleOrder OK'


					COMMIT TRANSACTION


			END
			TRY BEGIN CATCH
				--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
				ROLLBACK TRANSACTION
				SET @return_value = -1
				SET @errormessage = ERROR_MESSAGE()
			END CATCH

		END


		BEGIN TRY

			----------------------------------------------------------------------------------------------------------------
			----------------------------------------------------------------------------------------------------------------
			-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
			----------------------------------------------------------------------------------------------------------------
			IF @return_value > 0
			BEGIN

				DECLARE
					@strMailTo  NVARCHAR(MAX),
					@subject	NVARCHAR(MAX),
					@strBody	NVARCHAR(MAX),
					@lsm_id		INT



				--recuparamos el email y el vendedor del cliente
				SELECT
					@strMailTo		= tc.cust_email,
					@lsm_id			= tc.sm_id
				FROM tbCustomer					tc	WITH (NOLOCK)
				WHERE	tc.comp_id	= @comp_id	AND
						tc.cust_id	= @cust_id



				--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
				--se recupara el email del vendedor asignado al cliente

				DECLARE @strFooter AS NVARCHAR(MAX)

				SET
					@strMailTo = @strMailTo + ';' + (SELECT ts.sm_email
					FROM tbSalesman					ts		WITH (NOLOCK)
					WHERE	ts.comp_id  = @comp_id	AND
							ts.sm_id	= @lsm_id)



				DECLARE @strMailFrom AS NVARCHAR(MAX)
				SELECT
					@subject		= ISNULL(tws.wst_SaleOrderSubject,'Pedido Nro:'),
					@strBody		= ISNULL(tws.wst_SaleOrderBody,''),
					@strMailFrom	= ISNULL(tws.wst_SaleOrderMailFrom,''),
					@strFooter		= ISNULL(tws.wst_SaleOrderFooter,'')
					FROM tbWebServices				tws	WITH (NOLOCK)
					WHERE	tws.comp_id = @comp_id	AND
							tws.wst_id  = @wst_id



				--agregamos al mensaje que enviaremos al body del email las siguientes partes:
				--número de pedido
				--cliente
				--vendedor si hay un vendedor asignado al clientes
				SET @strBody = @strBody + CHAR(10) + CHAR(13) + '<br> ' +

				(SELECT
					tut.utexts_desc
					FROM tbsysUniqueTexts				tut		WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id	AND
							tut.utexts_id	= 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

				(SELECT
					tswn.word_desc
					FROM tbSysWordsNew					tswn	WITH (NOLOCK)
					WHERE	tswn.lang_id	= @lang_id	AND
							tswn.wordsi_id	= 297) + ' ' + convert(varchar,@cust_id) + ' - ' +

				(SELECT
					tc.cust_name
					FROM tbCustomer					tc			WITH (NOLOCK)
					WHERE	tc.comp_id = @comp_id	AND
							tc.cust_id = @cust_id)

				IF NOT @lsm_id IS NULL
				BEGIN
					SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br>' +

					(SELECT
						tswn.word_desc
						FROM tbSysWordsNew					tswn		WITH (NOLOCK)
						WHERE	tswn.lang_id	= @lang_id	AND
								tswn.wordsi_id	= 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +

					(SELECT
						ts.sm_name
						FROM tbSalesman					ts				WITH (NOLOCK)
						WHERE	ts.comp_id	= @comp_id	AND
								ts.sm_id	= @lsm_id)
				END


				-- Pone el detalle de los articulos.
				DECLARE	@ItemsTable	NVARCHAR(MAX)
				SET		@ItemsTable = ''
				EXEC	spSaleOrderDetail_GetHTMLTableOfItems4Mail @comp_id, @lang_id, @bra_id, @return_value, @ItemsTable OUTPUT
				SET		@ItemsTable = '<br>' + @ItemsTable


				SET @strBody = @strBody + CHAR(10) + CHAR(13) + '<br>' + @ItemsTable + ' <br> ' +  @strFooter
				SET @strBody = dbo.fnStrStripHTML(@strBody)  -- x nuevas politicas de ML si tiene HTML no manda el mail.

				--se envía el correo si se recuperaron direcciones de emails
				IF	NOT @strMailTo IS NULL								AND
					@bitML_cancellMailWithSaleOrderCreation = 'False'
					BEGIN

						EXEC spSystem_sendEMail
							@compId						= @comp_id,
							@precipients				= @strMailTo,
							@pcopy_recipients			= NULL,
							@psubject					= @subject,
							@pbody_format				= 'TEXT',
							@pbody						= @strBody,
							@pfile_attachments			= NULL,
							@pReplyTo					= @strMailFrom,
							@pblind_copy_recipients		= @strMailFrom,
							@pUser_Id					= @user_id

					END


			END
	----------------------------------------------------------------------------------------------------------------
	----------------------------------------------------------------------------------------------------------------

	END TRY
		BEGIN CATCH
		SET @return_value = @return_value
		END CATCH
	--RETURN @return_value
	SELECT
		@return_value [code],
		@errormessage [error_description]

END


GO

CREATE PROCEDURE [dbo].[spSaleOrderWS_insertSaleOrder4Producteca]
(
	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@wst_id					INT,
	@guid					UNIQUEIDENTIFIER,
	@cust_id				INT,
	--@sd_id				INT,
	@dl_id					INT,
	@disc_id				INT,
	@st_id					INT,
	@sm_id					INT,
	@soh_Observation1		NVARCHAR(200),
	@soh_Observation2		NVARCHAR(200),
	@soh_Observation3		NVARCHAR(200),
	@soh_Observation4		NVARCHAR(200),
	@IsCredit				BIT,
	@soh_note4ExternalUse	NVARCHAR(20),
	@soh_MLGUIA				AS NVARCHAR(50)
)
AS

BEGIN




	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE
			@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@wst_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@cust_id			INT,
			--@sd_id				INT,
			@dl_id				INT,
			@disc_id			INT,
			@st_id				INT,
			@sm_id				INT,
			@soh_Observation1	NVARCHAR(200),
			@soh_Observation2	NVARCHAR(200),
			@soh_Observation3	NVARCHAR(200),
			@soh_Observation4	NVARCHAR(200),
			@IsCredit			BIT

	SELECT	@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@wst_id				= 10,
			@guid				= '6455CD8D-20A5-4966-B027-F5FDF3047D19',
			@cust_id			= 24288,
			--@sd_id				= 1,
			@dl_id				= 1,
			@disc_id			= 1,
			@st_id				= 1,
			@sm_id				= 1,
			@soh_Observation1	= '',
			@soh_Observation2	= '',
			@soh_Observation3	= '',
			@soh_Observation4	= '',
			@IsCredit			= 'False'

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -------------------------------------------------------------------------------


	SET NOCOUNT ON
	DECLARE
		@return_value	INT,
		@errormessage	NVARCHAR(1000)
	SET	@return_value	= 0
	SET	@errormessage	= ''

	--obtenemos el df_id para generar el pedido QUE SEA FAVORITO PARA FULLJAUS
	DECLARE
		@df_id		INT,
		@sd_id		INT

	IF @IsCredit = 'True'
		BEGIN
			SET @sd_id = 3
		END
	ELSE
		BEGIN
			SET @sd_id = 1
		END

	IF @disc_id = -1
		BEGIN
			SET @disc_id = NULL
		END

	IF @dl_id = -1
		BEGIN
			SET		@dl_id	= NULL
			SELECT	@dl_id	= dl_id		-- MOS 07-2022 x SecOne al q FJ le cargaba el transporte en -1
				FROM tbCustomer AS tc WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @cust_id
		END

	SELECT	TOP 1
		@df_id	= df_id
		FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
		WHERE	sd_id			= @sd_id
		ORDER BY CASE
					WHEN is4FJ = 1 THEN 0
					ELSE				1
				 END,
				 df_order


	-- --------------------------------------------------------
	-- 10-20-2020
	-- STL FULLJAUS QUIERE QUE LA LISTA DE PRECIOS
	-- NO SOLO SE CARGUE EN LOS ITEMS, SINO QUE TAMBIEN SE
	-- CARGUE EN EL PEDIDO, RECUPERO ACA LA LISTA DEFINIDA
	-- PARA FULLJAUS Y ACTUALIZO LA LISTA DE PRECIOS
	-- --------------------------------------------------------
	DECLARE
		@prli_id	INT
	SELECT
		@prli_id = tws.prli_id4FullJaus
		FROM tbWebServices tws						WITH (NOLOCK)
		WHERE	tws.comp_id = @comp_id AND
				tws.wst_id	= @wst_id
	-- --------------------------------------------------------


	DECLARE @intDFId4PackingList		AS INT = NULL
	DECLARE
		@bitForceSaleOrder4Preparation AS BIT  = 'False'
	SELECT
		@intDFId4PackingList			= tdf.df_SaleOrderPL_df_Id,
		@bitForceSaleOrder4Preparation	= ISNULL(tdf.df_FullJaus_SaleOrderInPreparation,'False')
		FROM tbDocumentsFile			tdf WITH(NOLOCK)
		WHERE	tdf.comp_id = @comp_id	AND
				tdf.df_id	= @df_id

	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					FROM tbTempItemStock ttis WITH (NOLOCK)
					WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid)
		BEGIN
			SET @return_value = -2
			SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 99
		END
	ELSE
		IF @df_id IS NULL
			BEGIN
				SET @return_value = -3
				SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 91
			END
		ELSE
	--si no hubo errores por stock se genera el pedido
			IF @return_value = 0
				BEGIN

					BEGIN TRANSACTION
					BEGIN TRY
						DECLARE @rv			INT
						--==
							--IMPORTANTE!
							--COMENTE EL SM_ID porque va a venir como parámetro del SP ahora, ya que tendría que ser un campo configurable a nivel de WebService
							--LO MISMO PASA CON EL ST_ID, con el bra_id y con los id de documentos
						--==

						DECLARE
							--@sm_id			INT,
							@curr_id_cust	INT

						SELECT
							--@sm_id				= tc.sm_id,
							@curr_id_cust		= tc.curr_id
							FROM	tbCustomer	tc	 WITH (NOLOCK)
							WHERE	tc.comp_id	= @comp_id
							AND		tc.cust_id	= @cust_id

						DECLARE @curr_id_branch					INT,
								@bra_PriceDecimalPlaces			INT,
								@bra_SaleOrderDisposeLimitDay	INT,
								@country_id						INT,
								@state_id						INT

						SELECT	@curr_id_branch					= tb.curr_id,
								@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
								@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
								@country_id						= tb.country_id,
								@state_id						= tb.state_id
							FROM	tbBranch		tb		 WITH (NOLOCK)
							WHERE	tb.comp_id		= @comp_id
							AND		tb.bra_id		= @bra_id


						DECLARE
							@user_id		INT

						SELECT
							@user_id			= tws.[user_id]
							FROM	tbWebServices	tws		WITH(NOLOCK)
							WHERE	tws.comp_id = @comp_id
							AND		tws.wst_id	= @wst_id


						/******************************************************************************************/
						CREATE TABLE #tmpGetTotalsData
						(
							t1		INT,
							t2		DECIMAL(18,2),
							t3		DECIMAL(19,6),
							t4		DECIMAL(19,6),
							t5		DECIMAL(19,6),
							t6		DECIMAL(18,2),
							t7		DECIMAL(19,5),
							t8		INT,
							t9		DECIMAL(19,6),
							T10		NVARCHAR(4000),
							TotalNoInterest  DECIMAL(25,6)
						)

						--INSERT INTO #tmpGetTotalsData
							--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



						-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
						DECLARE	@exchange		DECIMAL(38,25)   -- MOS 01-2024 DECIMAL(19,6)
						SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')

						-- recuperar los totales generales
						INSERT INTO #tmpGetTotalsData
							EXEC	sptmpTax_calculate
									@comp_id,
									@bra_id,
									@cust_id,
									@guid,
									@curr_id_branch,
									@disc_id,
									@country_id,
									@state_id,
									@st_id,
									@curr_id_branch,
									@curr_id_cust,
									@exchange,
									'false',
									@df_id,
									'true',
									@dl_id,
									0,
									'false',
									'false',
									-1,
									-1 -- @ccp_id No INformado


						DECLARE @total					DECIMAL(19,6),
								@soh_discount			DECIMAL(19,6)

						SELECT	@total			= t2,
								@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
						FROM	#tmpGetTotalsData

						--SELECT	@total, @soh_discount
						/******************************************************************************************/

						DECLARE @getdate		DATETIME
						DECLARE @limitdate		DATETIME
						DECLARE @onlydate		DATETIME

						SET		@getdate	= GETDATE()
						SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
						SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay


						DECLARE @ssos_id AS INT = 5
						IF @bitForceSaleOrder4Preparation = 'True'  SET @ssos_id = 20 -- Si el documento lo dice lo pongo en PREPARACION.-


						EXEC spSaleOrder_insertData
								-1,
								@guid,
								@comp_id,
								@bra_id,
								@onlydate,
								@onlydate,
								@soh_Observation1,	--+--------------------------------------------------------------------
								@soh_Observation2,	--|Estos 4 campos se agregaron para FullJaus, acá van a mandar la
								@soh_Observation3,	--|tienda desde donde se realizó la compra, en un futuro puede cambiar
								@soh_Observation4,	--+--------------------------------------------------------------------
								'false',
								@sm_id,
								@cust_id,
								@st_id,
								@disc_id,
								@dl_id,
								null,
								@onlydate,
								@limitdate,
								1,				--+------------------------------------------------------------------------------------
								'A',			--|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
								1,				--+------------------------------------------------------------------------------------
								@user_id,
								'false',
								@getdate,
								@total,
								@df_id,
								@ssos_id ,--5,
								@exchange,
								@curr_id_cust,
								null,
								NULL,
								@return_value = @rv OUTPUT



						EXEC	spSaleOrderHeader_updatePL_df_id
								@comp_id,
								@bra_id,
								@rv,
								@intDFId4PackingList,
								null,
								@soh_discount,
								''



						EXEC	spSaleOrder_updateCurrExchange
								@comp_id,
								@bra_id,
								@rv,
								@curr_id_cust,
								@exchange,
								0 --@decInCash

						--*********************************************************************************************************************
						-- FULLJAUS ACA GRABA EL MARKETPLACE QUE DESPUES VA A FILTRAR EN SALEORDERALL Y EN EL METODO QUE RECUPERA LOS PEDIDOS
						-- PEDIDO POR PABLO DE FULLJAUS 23-12-2019
						--*********************************************************************************************************************
						UPDATE tbSaleOrderHeader	WITH (ROWLOCK)
						SET
							soh_note4ExternalUse = @soh_note4ExternalUse,
							prli_id				 = @prli_id,
							soh_MLGUIA			 = CASE WHEN @soh_MLGUIA = '0' THEN NULL ELSE @soh_MLGUIA END
						WHERE	comp_id = @comp_id	AND
								bra_id	= @bra_id	AND
								soh_id	= @rv
						--*********************************************************************************************************************


						DELETE FROM tbtmpTax		WHERE tis_guid = @guid
						DELETE FROM tbTempItemStock WHERE tis_guid = @guid



						SET @return_value = @rv
						SET @errormessage = 'SaleOrder OK'


						COMMIT TRANSACTION


					END
					TRY BEGIN CATCH
						--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
						ROLLBACK TRANSACTION
						SET @return_value = -1
						SET @errormessage = ERROR_MESSAGE()

					END CATCH

				END

	BEGIN TRY
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------
		-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
		----------------------------------------------------------------------------------------------------------------
		IF @return_value > 0
		BEGIN
			DECLARE @strMailTo		NVARCHAR(4000),
					@subject		NVARCHAR(800),
					@strBody		NVARCHAR(800),
					@lsm_id			INT



			--recuparamos el email y el vendedor del cliente
			SELECT
				@strMailTo			= tc.cust_email,
				@lsm_id				= tc.sm_id
				FROM	tbCustomer	tc		 WITH(NOLOCK)
				WHERE	tc.comp_id	= @comp_id
				AND		tc.cust_id	= @cust_id

			--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
			--se recupara el email del vendedor asignado al cliente

			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
														FROM	tbSalesman					ts
														WHERE	ts.comp_id		= @comp_id AND
																ts.sm_id		= @lsm_id)

			DECLARE @strFooter AS NVARCHAR(MAX)

			DECLARE @strMailFrom AS NVARCHAR(MAX)
			SELECT	@subject	= ISNULL(tws.wst_SaleOrderSubject,'Pedido Nro:'),
					@strBody	= ISNULL(tws.wst_SaleOrderBody,''),
					@strMailFrom= ISNULL(tws.wst_SaleOrderMailFrom,''),
					@strFooter  = ISNULL(tws.wst_SaleOrderFooter,'')
				FROM tbWebServices tws	 WITH (NOLOCK)
				WHERE	tws.comp_id = @comp_id AND
						tws.wst_id  = @wst_id



			--agregamos al mensaje que enviaremos al body del email las siguientes partes:
			--número de pedido
			--cliente
			--vendedor si hay un vendedor asignado al clientes
			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

							(SELECT	tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

							(SELECT tswn.word_desc
							 FROM	tbSysWordsNew	tswn
							 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 297) + ' ' + convert(varchar,@cust_id) + ' - ' +
							(SELECT tc.cust_name
							 FROM	tbCustomer		tc
							 WHERE	tc.comp_id = @comp_id AND tc.cust_id = @cust_id)

			IF NOT @lsm_id IS NULL
				BEGIN
					SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

								(SELECT tswn.word_desc
								 FROM	tbSysWordsNew	tswn		 WITH (NOLOCK)
								 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +
								(SELECT ts.sm_name
								 FROM	tbSalesman		ts			 WITH (NOLOCK)
								 WHERE	ts.comp_id = @comp_id AND ts.sm_id = @lsm_id)
				END


			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +  @strFooter

			--se envía el correo si se recuperaron direcciones de emails
			IF NOT @strMailTo IS NULL        AND 1 = 2  -- MOS 01-04-2020
				BEGIN

					exec spSystem_sendEMail
							@compId						= @comp_id,
							@precipients				= @strMailTo,
							@pcopy_recipients			= null,
							@psubject					= @subject,
							@pbody_format				= 'HTML',
							@pbody						= @strBody,
							@pfile_attachments			= null,
							@pReplyTo					= @strMailFrom,
							@pblind_copy_recipients		= '',
							@pUser_Id					= @user_id

				END

		END
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------

	END TRY
	BEGIN CATCH
		SET @return_value = @return_value
	END CATCH



	-- ------------------------------------------------------------------------------------------------
	-- MOS 07-2022: Verifica YA AHORA que el nuevo pedido no tenga publicaciones que actualizar.
	-- **wqlknfdlqwn098765gtfc
	-- ------------------------------------------------------------------------------------------------
	BEGIN TRY
		IF EXISTS(
					SELECT TOP 1 1
						FROM tbMercadoLibre_Stores AS tmls	WITH (NOLOCK)
						WHERE	tmls.mls_disabled = 'False' AND
								ABS(DATEDIFF(day, tmls.mls_accessTokenValidUp2Date,GETDATE())) < 2
				)
			BEGIN
				UPDATE tbSaleOrderDetail
					SET	sod_MercadoLibre_MustUpdateStock = 'True'
					FROM tbSaleOrderDetail sod							WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ItemsPublicados AS tmlip	WITH (NOLOCK)
						ON	tmlip.comp_id	= sod.comp_id AND
							tmlip.item_id	= sod.item_id
					INNER JOIN tbMercadoLibre_Stores		  AS tmls	WITH (NOLOCK)
						ON	tmls.comp_id	= tmlip.comp_id AND
							tmls.mls_id		= tmlip.mls_id
					WHERE
							SOD.comp_id			= @comp_id			AND
							SOD.bra_id			= @bra_id			AND
							SOD.soh_id			= @return_value		AND
							tmls.mls_disabled	 = 'False'		AND
							ABS(DATEDIFF(day, tmls.mls_accessTokenValidUp2Date,GETDATE())) < 2	AND
							tmlip.mlp_Active	= 'True'


				EXEC spSaleOrder_MercadoLibre_VerificarItemsSinStockDisponible @comp_id,@bra_id,@return_value,@guid
				EXEC spSystem_MercadoLibreProcessQueue_4GUID @guid
			END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ------------------------------------------------------------------------------------------------















	--RETURN @return_value
	SELECT	@return_value	[code],
			@errormessage	[error_description]



END
GO







CREATE PROCEDURE [dbo].[spSaleOrderWS_insertSaleOrderMercadoLibreHistory]
(
	@comp_id						INT,
	@lang_id						INT,
	@bra_id							INT,
	@wst_id							INT,
	@soh_MLId						NVARCHAR(50),
	@mls_status						INT,
	@strStatusDescription			NVARCHAR(250),
	@mls_isAlert					BIT,
	@mls_blockPreparation			BIT,
	@mls_blockEmmition				BIT,
	@mls_blockDelivery				BIT
)
AS

BEGIN

	SET NOCOUNT ON


	DECLARE @bitIsEmmited	AS BIT
	SET		@bitIsEmmited	= 'False'
	DECLARE @soh_id			AS INT
	SET		@soh_id			= NULL

	SELECT	@bra_id = bra_id,
			@soh_id = soh_id
		FROM tbSaleOrderHeader tsoh				WITH (NOLOCK)
		WHERE	tsoh.comp_id	= @comp_id AND
				tsoh.soh_MLId	= @soh_MLId

	IF @soh_id IS NULL
		BEGIN
			SELECT	@bra_id			= bra_id,
					@soh_id			= soh_id,
					@bitIsEmmited	= 'True'
			FROM tbSaleOrderHeaderHistory tsoh				WITH (NOLOCK)
				WHERE	tsoh.comp_id	= @comp_id	AND
						tsoh.soh_MLId	= @soh_MLId
		END



	IF @soh_id IS NOT NULL
		BEGIN

			INSERT INTO tbSaleOrderHeader_MercadoLibreHistory	WITH (ROWLOCK)
			(
				comp_id,
				bra_id,
				soh_id,
				mls_status,
				mls_desc,
				mls_isAlert,
				mls_blockPreparation,
				mls_blockEmmition,
				mls_blockDelivery
			)
			VALUES
			(
				@comp_id,
				@bra_id,
				@soh_id,
				@mls_status,
				CASE
					WHEN @bitIsEmmited = 'True' THEN	'* YA EMITIDA *'
					ELSE								''
				END + IsNULL(@strStatusDescription,''),
				@mls_isAlert,
				@mls_blockPreparation,
				@mls_blockEmmition,
				@mls_blockDelivery
			)

			SELECT 'True' [isOK]

		END
	ELSE
		BEGIN
			SELECT 'False' [isOK]
		END






END
GO





-- ATENCION si se toca algo aca hacerlo tambien en : spSaleOrderWS_insertSaleOrderMercedoLibre y spSaleOrderWS_insertSaleOrder4FullJaus


CREATE PROCEDURE [dbo].[spSaleOrderWS_insertSaleOrderV2]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@wst_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@cust_id			INT,
	@sd_id				INT,
	@dl_id				INT,
	@st_id				INT,
	@disc_id			INT
)
AS

BEGIN




	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@wst_id				INT,
			@cust_id			INT,
			@sd_id				INT

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@guid				='6455CD8D-20A5-4966-B027-F5FDF3047D19',
			@wst_id				=10,
			@cust_id			=24288,
			@sd_id				=1

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -------------------------------------------------------------------------------


	SET NOCOUNT ON



	declare @return_value		INT,
			@errormessage		NVARCHAR(1000)

	set		@return_value = 0
	set		@errormessage = ''







	--obtenemos el df_id para generar el pedido
	DECLARE @df_id		INT

	SELECT	TOP 1 @df_id	= df_id
		FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
		WHERE	sd_id			= @sd_id
		ORDER BY CASE
					WHEN is4WS = 1 THEN 0
					ELSE				1
				 END,
				 df_order






	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					FROM tbTempItemStock ttis WITH (NOLOCK)
					WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid)

		BEGIN

			SET @return_value = -2
			SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 99

		END

	ELSE

		IF @df_id IS NULL
			BEGIN

				SET @return_value = -3
				SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 91

			END

		ELSE

	/*
			BEGIN
				--SELECT 2
				--se controla que no se supere el porcentaje de stock potencial seteado en tbwebsite_names
				--de lo que se está cargando en el pedido de cada artículo
				DECLARE cursor_tis CURSOR FOR
				SELECT	ttis.item_id, ttis.tis_qty, ttis.tis_priority
				FROM	tbTempItemStock ttis
				WHERE	ttis.comp_id = @comp_id AND ttis.tis_guid = @guid

				OPEN cursor_tis

				FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority


				WHILE @@FETCH_STATUS = 0 and @return_value = 0
				BEGIN

					SET @potential_stock = dbo.fnGetAStock(@comp_id, @stor_id, @item_id, @tis_priority)

					--SELECT '@potential_stock', @potential_stock, (@potential_stock * @ws_PotentialStockLimit / 100), @tis_qty, @stor_id



					--Si la cantidad a reservar en el pedido (@tis_qty) es mayor que el porcentaje de stock potencial disponible
					--para la venta on line (@potential_stock * @ws_PotentialStockLimit / 100) se muestra un mensaje que le
					--indica al cliente conectado que no hay stock disponible
					IF @tis_qty > (@potential_stock * @ws_PotentialStockLimit / 100)
					BEGIN
						SET @return_value = -3

						SELECT	@errormessage = tut.utexts_desc + ti.item_code + '-' + ti.item_desc
						FROM	tbsysUniqueTexts tut
								INNER JOIN tbItem ti
								ON	ti.comp_id	= @comp_id
								AND ti.item_id	= @item_id
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 98
					END


					FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority
				END
				CLOSE cursor_tis
				DEALLOCATE cursor_tis
				--SELECT 3
	*/



	--si no hubo errores por stock se genera el pedido
	IF @return_value = 0
	BEGIN

		BEGIN TRANSACTION
		BEGIN TRY



			DECLARE @rv								INT




			DECLARE @sm_id							INT,
					@curr_id_cust					INT

			SELECT	@sm_id			= tc.sm_id,
					@curr_id_cust	= tc.curr_id
				FROM	tbCustomer		tc	 WITH (NOLOCK)
				WHERE	tc.comp_id		= @comp_id
				AND		tc.cust_id		= @cust_id



			-- obtengo el documento para REMITOS asociado a este documento si es que lo tiene.. .
			DECLARE @intDFId4PackingList AS INT
			SET		@intDFId4PackingList = NULL
			SELECT  @intDFId4PackingList = tdf.df_SaleOrderPL_df_Id
				FROM tbDocumentsFile tdf  WITH (NOLOCK)
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id



			DECLARE @curr_id_branch					INT,
					@bra_PriceDecimalPlaces			INT,
					@bra_SaleOrderDisposeLimitDay	INT,
					@country_id						INT,
					@state_id						INT

			SELECT	@curr_id_branch					= tb.curr_id,
					@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
					@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
					@country_id						= tb.country_id,
					@state_id						= tb.state_id
				FROM	tbBranch		tb		 WITH (NOLOCK)
				WHERE	tb.comp_id		= @comp_id
				AND		tb.bra_id		= @bra_id





			DECLARE @user_id		INT

			SELECT	@user_id	= tws.[user_id]
				FROM	tbWebServices tws		 WITH (NOLOCK)
				WHERE	tws.comp_id = @comp_id
				AND		tws.wst_id	= @wst_id




			/******************************************************************************************/
			CREATE TABLE #tmpGetTotalsData
			(
				t1		INT,
				t2		DECIMAL(18,2),
				t3		DECIMAL(19,6),
				t4		DECIMAL(19,6),
				t5		DECIMAL(19,6),
				t6		DECIMAL(18,2),
				t7		DECIMAL(19,5),
				t8		INT,
				t9		DECIMAL(19,6),
				T10		NVARCHAR(4000),
				TotalNoInterest  DECIMAL(25,6)
			)

			--INSERT INTO #tmpGetTotalsData
				--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



			-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
			DECLARE	@exchange		DECIMAL(38,25)   -- MOS 01-2024 DECIMAL(19,6)

			SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')





			-- recuperar los totales generales
			INSERT INTO #tmpGetTotalsData
				EXEC	sptmpTax_calculate
						@comp_id,
						@bra_id,
						@cust_id,
						@guid,
						@curr_id_branch,
						@disc_id,
						@country_id,
						@state_id,
						@st_id,
						@curr_id_branch,
						@curr_id_cust,
						@exchange,
						'false',
						@df_id,
						'true',
						@dl_id,
						0,
						'false',
						'false',
						-1,
						-1 -- @ccp_id No INformado


			DECLARE @total					DECIMAL(19,6),
					@soh_discount			DECIMAL(19,6)

			SELECT	@total			= t2,
					@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
			FROM	#tmpGetTotalsData

			--SELECT	@total, @soh_discount
			/******************************************************************************************/






			DECLARE @getdate		DATETIME
			DECLARE @limitdate		DATETIME
			DECLARE @onlydate		DATETIME

			SET		@getdate	= GETDATE()
			SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
			SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay

			/*
			SELECT 	@guid,
					@comp_id,
					@bra_id,
					@onlydate,
					@onlydate,
					@sm_id,
					@cust_id,
					@st_id,
					@disc_id,
					@dl_id,
					@onlydate,
					@limitdate,
					@user_id,
					@getdate,
					@total,
					@df_id,
					@exchange,
					@curr_id_cust
			*/


			EXEC spSaleOrder_insertData
					-1,
					@guid,
					@comp_id,
					@bra_id,
					@onlydate,
					@onlydate,
					'',
					'',
					'',
					'',
					'false',
					@sm_id,
					@cust_id,
					@st_id,
					@disc_id,
					@dl_id,
					null,
					@onlydate,
					@limitdate,
					1,				--+------------------------------------------------------------------------------------
					'A',			--|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
					1,				--+------------------------------------------------------------------------------------
					@user_id,
					'false',
					@getdate,
					@total,
					@df_id,
					5,
					@exchange,
					@curr_id_cust,
					null,
					NULL,
					@return_value = @rv OUTPUT



			EXEC	spSaleOrderHeader_updatePL_df_id
					@comp_id,
					@bra_id,
					@rv,
					@intDFId4PackingList, --null,  MOS 04-2020
					null,
					@soh_discount,
					''



			EXEC	spSaleOrder_updateCurrExchange
					@comp_id,
					@bra_id,
					@rv,
					@curr_id_cust,
					@exchange,
					0 --@decInCash


			DELETE FROM tbtmpTax		WHERE tis_guid = @guid
			DELETE FROM tbTempItemStock WHERE tis_guid = @guid



			SET @return_value = @rv
			SET @errormessage = 'SaleOrder OK'


			COMMIT TRANSACTION


		END
		TRY BEGIN CATCH
			--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
			ROLLBACK TRANSACTION
			SET @return_value = -1
			SET @errormessage = ERROR_MESSAGE()

		END CATCH

	END


	BEGIN TRY

		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------
		-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
		----------------------------------------------------------------------------------------------------------------
		IF @return_value > 0
		BEGIN



			DECLARE @strMailTo		NVARCHAR(4000),
					@subject		NVARCHAR(800),
					@strBody		NVARCHAR(800),
					@lsm_id			INT



			--recuparamos el email y el vendedor del cliente
			SELECT	@strMailTo		= tc.cust_email,
					@lsm_id				= tc.sm_id
				FROM	tbCustomer							tc		 WITH (NOLOCK)
				WHERE	tc.comp_id			= @comp_id
				AND		tc.cust_id			= @cust_id


--		IF @lsm_id IS NULL
--			SET @strMailTo = @strMailTo + ';' + (SELECT	twsn.ws_email_contact
--													FROM	tbWebSite_Names				twsn
--													WHERE	twsn.comp_id	= @comp_id
--													AND		twsn.ws_id		= @ws_id)
--
--		ELSE
--			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
--													FROM	tbSalesman					ts
--													WHERE	ts.comp_id		= @comp_id
--													AND		ts.sm_id		= @lsm_id)





			--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
			--se recupara el email del vendedor asignado al cliente

			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
														FROM	tbSalesman					ts
														WHERE	ts.comp_id		= @comp_id AND
																ts.sm_id		= @lsm_id)

			DECLARE @strFooter AS NVARCHAR(MAX)

			DECLARE @strMailFrom AS NVARCHAR(MAX)
			SELECT	@subject	= ISNULL(tws.wst_SaleOrderSubject,'Pedido Nro:'),
					@strBody	= ISNULL(tws.wst_SaleOrderBody,''),
					@strMailFrom= ISNULL(tws.wst_SaleOrderMailFrom,''),
					@strFooter  = ISNULL(tws.wst_SaleOrderFooter,'')
				FROM tbWebServices tws	 WITH (NOLOCK)
				WHERE	tws.comp_id = @comp_id AND
						tws.wst_id  = @wst_id



			--agregamos al mensaje que enviaremos al body del email las siguientes partes:
			--número de pedido
			--cliente
			--vendedor si hay un vendedor asignado al clientes
			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

							(SELECT	tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

							(SELECT tswn.word_desc
							 FROM	tbSysWordsNew	tswn
							 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 297) + ' ' + convert(varchar,@cust_id) + ' - ' +
							(SELECT tc.cust_name
							 FROM	tbCustomer		tc
							 WHERE	tc.comp_id = @comp_id AND tc.cust_id = @cust_id)

			IF NOT @lsm_id IS NULL
				BEGIN
					SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

								(SELECT tswn.word_desc
								 FROM	tbSysWordsNew	tswn		 WITH (NOLOCK)
								 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +
								(SELECT ts.sm_name
								 FROM	tbSalesman		ts			 WITH (NOLOCK)
								 WHERE	ts.comp_id = @comp_id AND ts.sm_id = @lsm_id)
				END


			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +  @strFooter

			--se envía el correo si se recuperaron direcciones de emails
			IF NOT @strMailTo IS NULL
				BEGIN

					exec spSystem_sendEMail
							@compId						= @comp_id,
							@precipients				= @strMailTo,
							@pcopy_recipients			= null,
							@psubject					= @subject,
							@pbody_format				= 'HTML',
							@pbody						= @strBody,
							@pfile_attachments			= null,
							@pReplyTo					= @strMailFrom,
							@pblind_copy_recipients		= '',
							@pUser_Id					= @user_id

				END

		END
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------

	END TRY
	BEGIN CATCH
		SET @return_value = @return_value
	END CATCH



	--RETURN @return_value
	SELECT	@return_value	[code],
			@errormessage	[error_description]



END
GO

