					--SELECT '@potential_stock', @potential_stock, (@potential_stock * @ws_PotentialStockLimit / 100), @tis_qty, @stor_id



					--Si la cantidad a reservar en el pedido (@tis_qty) es mayor que el porcentaje de stock potencial disponible
					--para la venta on line (@potential_stock * @ws_PotentialStockLimit / 100) se muestra un mensaje que le
					--indica al cliente conectado que no hay stock disponible
					IF @tis_qty > (@potential_stock * @ws_PotentialStockLimit / 100)
					BEGIN
						SET @return_value = -3

						SELECT	@errormessage = tut.utexts_desc + ti.item_code + '-' + ti.item_desc
						FROM	tbsysUniqueTexts tut
								INNER JOIN tbItem ti
								ON	ti.comp_id	= @comp_id
								AND ti.item_id	= @item_id
						WHERE	tut.lang_id		= @lang_id
						AND		tut.utexts_id	= 98
					END


					FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority
				END
				CLOSE cursor_tis
				DEALLOCATE cursor_tis
				--SELECT 3
	*/



	--si no hubo errores por stock se genera el pedido
	IF @return_value = 0
	BEGIN

