CREATE Procedure [dbo].[spSalesman_Profit_getReport]
(
		@comp_id					INT,
		@lang_id					INT,
		@page_id					INT,

		@sm_id						INT,
		@datefrom					DATETIME,
		@dateto						DATETIME,
		@Paydatefrom				DATETIME,
		@Paydateto					DATETIME,
		@Cancellationdatefrom		DATETIME,
		@Cancellationdateto			DATETIME,
		@option						INT,
		@bra_id						INT,
		@user_id					INT,
		@intBranch4Lang				INT


)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	set	@Paydatefrom = dbo.fnGetEnd_or_BeginOfDate(@Paydatefrom,'False')
	set	@Paydateto = dbo.fnGetEnd_or_BeginOfDate(@Paydateto,'True')

	set	@Cancellationdatefrom = dbo.fnGetEnd_or_BeginOfDate(@Cancellationdatefrom,'False')
	set	@Cancellationdateto = dbo.fnGetEnd_or_BeginOfDate(@Cancellationdateto,'True')



	-- --------------------------------------------------------------------------
	-- Testing
	-- --------------------------------------------------------------------------
/*
	Declare 	@comp_id					INT,
				@lang_id					INT,
				@page_id					INT,

				@sm_id						INT,
				@datefrom					DATETIME,
				@dateto						DATETIME,
				@Paydatefrom				DATETIME,
				@Paydateto					DATETIME,
				@Cancellationdatefrom		DATETIME,
				@Cancellationdateto			DATETIME,
				@option						INT,
				@bra_id						INT,
		    	@user_id					INT,
				@intBranch4Lang				INT


	Select		@comp_id					=1,
				@lang_id					=2,
				@page_id					=10094,
				@sm_id						=-1,
				@datefrom					='2000-10-01',
				@dateto						='2014-10-31',
				@paydatefrom				='2000-10-01',
				@paydateto					='2014-10-31',
				@Cancellationdatefrom		='2000-10-01',
				@Cancellationdateto			='2014-10-31',
				@option						= 2,
				@bra_id						= 1,
				@user_id					= 1
	*/
	-- --------------------------------------------------------------------------

	DECLARE @fun_id INT
	SET		@fun_id = 1



	--**MOS falta en el select el costo,venta_neto,venta_final,saldo,fecha ultima cobranza,profit en $ y en %.

	SELECT	dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction)		[ct_transaction],
			tct.ct_date																				[ct_date],
			tct.ct_payDate																			[ct_payDate],
			tc.cust_name																			[cust_name],
			ts.sm_name																				[sm_name],
			9999999																						[costo],
			9999999																						[venta_neto] ,
			9999999																						[venta_final],
			9999999																						[saldo] ,
			'12/12/2014'																						[Date_lastcollection],
			9999999																						[profit] ,
			9999999																						[profit_percentaje],
			isnull(tst.st_desc,'')																	[st_desc]



	FROM	tbCommercialTransactions								tct


		INNER JOIN vwCommercialTransactions_forSales				vctfs
		ON	vctfs.comp_id			= tct.comp_id			AND
			vctfs.bra_id			= tct.bra_id			AND
			vctfs.ct_transaction	= tct.ct_transaction

		LEFT JOIN vwCommercialTransactionsProfitAndMarckup			vctpam
		ON	vctpam.comp_id			= tct.comp_id			AND
			vctpam.bra_id			= tct.bra_id			AND
			vctpam.ct_transaction	= tct.ct_transaction

		INNER JOIN tbCustomer										tc
		ON  tc.comp_id				= tct.comp_id			AND
			tc.cust_id				= tct.cust_id

		INNER JOIN tbsysCurrency									tc2
		ON  tc2.curr_id				= tct.curr_id_transaction

		INNER JOIN tbSalesman										ts
		ON  ts.comp_id				= tct.comp_id			AND
			ts.sm_id				= tct.sm_id

		LEFT JOIN tbSalesTerms										tst
		ON  tst.comp_id				= tct.comp_id			AND
			tst.st_id				= tct.st_id

		LEFT JOIN tbCustomerFilterByUser							tcfbu
		ON	tcfbu.comp_id			= tct.comp_id			AND
			tcfbu.bra_id			= tct.bra_id			AND
			tcfbu.[user_id]			= @user_id				AND
			tcfbu.sm_id				= tct.sm_id

		LEFT JOIN tbUserSalesmanRelation							tusr
		ON	tusr.comp_id			= tct.comp_id			AND
			tusr.bra_id				= tct.bra_id			AND
			tusr.[user_id]			= @user_id				AND
			tusr.sm_id				= tct.sm_id

		INNER JOIN tbUsers4BranchFilter								vubf
		ON	vubf.comp_id			= tct.comp_id			AND
			vubf.bra_id				= tct.bra_id			AND
			vubf.[user_id]			= @user_id



	WHERE	tct.comp_id			= @comp_id
	AND		tct.bra_id			= @bra_id
	AND		(@sm_id				= -1 or ts.sm_id		= @sm_id)
	AND      tct.ct_date		between  @datefrom	and @dateto				-- Fecha de Emision
	AND      tct.ct_payDate		between  @paydatefrom	and @paydateto		-- Fecha de Vencimiento
	AND      tct.ct_date		between  @cancellationdatefrom	and @cancellationdateto -- **MOS Aqui poner que filtre x la fecha de cancelacion
	AND		( @option = -1 OR ((@option	 = 1 And  tct.ct_Abalance = 0) OR  -- 1-Cobrados
							   (@option	 = 2 and  tct.ct_Abalance <> 0))   -- 2-Pendientees
			)


	EXEC [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id, @page_id



	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 172
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params1],
			CASE @sm_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.sm_name
						FROM	tbSalesman ts
						WHERE	ts.comp_id = @comp_id AND ts.sm_id= @sm_id)
			END		[params2],


			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 177
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],

      		 @datefrom [DateParams1],
			--convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom)) 	[params30],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 384
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params4],

      		 @dateto [DateParams2],
			--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto)) 	[params32]

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 775
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],

      		 @paydatefrom [DateParams3],
			--convert(varchar,day(@paydatefrom)) + '/' + convert(varchar,month(@paydatefrom)) + '/' + convert(varchar,year(@paydatefrom)) 	[params30],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 776
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params6],

      		 @paydateto [DateParams4],
			--convert(varchar,day(@paydateto)) + '/' + convert(varchar,month(@paydateto)) + '/' + convert(varchar,year(@paydateto)) 	[params32]

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2721
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params7],

      		 @cancellationdatefrom [DateParams5],
			--convert(varchar,day(@cancellationdatefrom)) + '/' + convert(varchar,month(@cancellationdatefrom)) + '/' + convert(varchar,year(@cancellationdatefrom)) 	[params30],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 2722
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params8],

      		 @cancellationdateto [DateParams6],
			--convert(varchar,day(@cancellationdateto)) + '/' + convert(varchar,month(@cancellationdateto)) + '/' + convert(varchar,year(@cancellationdateto)) 	[params32]


				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 991
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params9],
			CASE @option WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc
						FROM tbsysOptionsValues tov
						WHERE tov.optval_class=329 and tov.optval_id=@option and tov.lang_id = @lang_id)
			END		[params10]





END
GO






