------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spSalesmanExcludedByProfile_GetData]
(

	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT

)
AS


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
-- -----------------------------------------------------------------------------
SET NOCOUNT ON


-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,


	SELECT		@comp_id			= 1,
				@bra_id				= 1,
				@prof_id			= 1
*/
-------------------------------------------------------------------------------------------

BEGIN

		SELECT
			tsebp.sm_id					[sm_id],
			TS.sm_name					[sm_name]

			FROM tbSalesmanExcludedByProfile				tsebp		WITH (NOLOCK)

			INNER JOIN tbSalesman							ts			WITH (NOLOCK)
			ON	ts.comp_id	= tsebp.comp_id		AND
				ts.sm_id	= tsebp.sm_id



			Where	tsebp.comp_id			= @comp_id		AND
					tsebp.bra_id			= @bra_id		AND
					tsebp.prof_id			= @prof_id		AND
					tsebp.isDisabled		= 'False'


END
GO







