-- =============================================
-- Author:  GA
-- Create date: 08/27/2010
-- Description: Reporte de "Ranking de Ventas por Cliente"
-- =============================================


CREATE PROCEDURE [dbo].[spSalesRanking_getReport]
(
 @comp_id  int,
 @lang_id  int,
 @page_id  int,

 @option   int,
 @cust_name  varchar(200),
 @fc_id   int,
 @ck_id   int,
 @prli_id  int,
 @country_id  int,
 @tnt_id   int,
 @stor_id  int,
 @curr_id  int,
 @disc_id  int,
 @st_id   int,
 @bra_id   int,
 @dl_id   int,
 @sm_id   int,
 @state_id  INT,
 @date_from      DATETIME,
 @date_to     DATETIME,
 @user_id  INT,
 @totals   INT,
 @CustomerGuid	VARCHAR(50),
 @intBranch4Lang  int

)
AS




BEGIN

 SET NOCOUNT ON
 SET DATEFORMAT 'ymd'

 -- -----------------------------------------------------------------------------
 -- Para prevenir que alguien haga un query que mate la base para todo el resto.!
 -- -----------------------------------------------------------------------------
 SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
 SET LOCK_TIMEOUT 500
 SET DEADLOCK_PRIORITY LOW
 -- -----------------------------------------------------------------------------

 set @date_from = dbo.fnGetEnd_or_BeginOfDate(@date_from,'False')
 set @date_to = dbo.fnGetEnd_or_BeginOfDate(@date_to,'True')


--------------------------------------------------------------------------------
-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
--------------------------------------------------------------------------------
/*

declare @comp_id  int,
  @lang_id  int,
  @page_id  int,

  @option   int,
  @cust_name  varchar(200),
  @fc_id   int,
  @ck_id   int,
  @prli_id  int,
  @country_id  int,
  @tnt_id   int,
  @stor_id  int,
  @curr_id  int,
  @disc_id  int,
  @st_id   int,
  @bra_id   int,
  @dl_id   int,
  @sm_id   int,
  @state_id  INT,
  @date_from      DATETIME,
  @date_to     DATETIME,
  @user_id  INT,
  @totals   INT,
  @intBranch4Lang  int

select  @comp_id  =1,
  @lang_id  =2,
  @page_id  =10072,

  @fc_id   = -1,
  @ck_id   = -1,
  @prli_id  = -1,
  @country_id  = -1,
  @tnt_id   = -1,
  @stor_id  = -1,
  @curr_id  = 1,
  @disc_id  = -1,
  @st_id   = -1,
  @bra_id   = -1,
  @dl_id   = -1,
  @sm_id   = -1,
  @state_id  = -1,
  @option   = -1,
  @cust_name  = '',
  @date_from  = '1900-01-01',
  @date_to  = '9999-12-31',
  @user_id  = 1,
  @totals   = 1



drop table #tmp
*/
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------

DECLARE @lGuid AS UNIQUEIDENTIFIER

 SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@CustomerGuid)

 -- -------------------------------------------------------------
 -- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
 -- -------------------------------------------------------------
 DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
 INSERT INTO @tblComplexFilter_Customer
  SELECT tcf.sl_id
   FROM tbComplexFilter tcf
   WHERE tcf.sl_guid = @lGuid     AND
		tcf.sl_selected = 'True'
 IF @@ROWCOUNT = 0
  BEGIN
   INSERT INTO @tblComplexFilter_Customer
	SELECT tc.cust_id
	FROM tbCustomer tc
	WHERE tc.comp_id = @comp_id
  END
 -- -------------------------------------------------------------



  select  tc.cust_id,
     tc.cust_name,

     CASE
      WHEN @totals = 0 THEN
        dbo.fnGetExchange2(@comp_id, tct.ct_total, tct.curr_id_transaction, @curr_id, tct.curr_id4Exchange,tct.curr_id_transaction,  tct.ct_curr_IdExchange,'False')
      ELSE
       dbo.fnGetExchange2(@comp_id, tct.ct_subtotal, tct.curr_id_transaction, @curr_id,  tct.curr_id4Exchange,tct.curr_id_transaction, tct.ct_curr_IdExchange,'False')

--      WHEN @totals = 0 THEN
--        dbo.fnGetExchange2(@comp_id, tct.ct_total, tct.curr_id_transaction, @curr_id, tct.curr_id_transaction, tct.curr_id4Exchange, tct.ct_curr_IdExchange,'False')
--      ELSE
--       dbo.fnGetExchange2(@comp_id, tct.ct_subtotal, tct.curr_id_transaction, @curr_id, tct.curr_id_transaction, tct.curr_id4Exchange, tct.ct_curr_IdExchange,'False')
     END *

     CASE
      WHEN vctfs.sd_id  =3    THEN -1
      ELSE           1
     END          [Facturado],
     ts.sm_name        [sm_name]


  into #tmp
  from tbCommercialTransactions tct            WITH(NOLOCK)

     INNER JOIN vwCommercialTransactions_forSales    vctfs WITH(NOLOCK)
     ON  vctfs.comp_id   = tct.comp_id AND
      vctfs.bra_id   = tct.bra_id AND
      vctfs.ct_transaction = tct.ct_transaction

     INNER JOIN tbCustomer          tc  WITH(NOLOCK)
     ON  tc.comp_id    = tct.comp_id AND
      tc.cust_id    = tct.cust_id

    INNER JOIN @tblComplexFilter_Customer	tmbC
		ON tmbC.cust_id = tct.cust_id

     LEFT JOIN tbSalesman          ts  WITH(NOLOCK)
     ON ts.comp_id    = tc.comp_id AND
      ts.sm_id    = tc.sm_id

     INNER JOIN tbUsers4BranchFilter        vubf WITH(NOLOCK)
     ON  vubf.comp_id    = tct.comp_id AND
      vubf.bra_id        = tct.bra_id AND
      vubf.[user_id]       = @user_id


  WHERE  tct.[comp_id] = @comp_id
  and  (@fc_id   = -1  or  tc.[fc_id]   = @fc_id)
  and     (@ck_id   = -1  or  tc.[ck_id]   = @ck_id)
  and  (@prli_id  = -1  or  tc.[prli_id]  = @prli_id)
  and  (@country_id = -1  or  tct.[country_id] = @country_id)
  and  (@tnt_id  = -1  or  tc.[tnt_id]   = @tnt_id)
  and  (@stor_id  = -1  or  tc.[stor_id]  = @stor_id)
  --and  (@curr_id  = -1  or  tc.[curr_id]  = @curr_id)
  and  (@disc_id  = -1  or  tct.[disc_id]  = @disc_id)
  and  (@st_id   = -1  or  tct.[st_id]   = @st_id)
  and  (@bra_id  = -1  or  tct.[bra_id]  = @bra_id)
  and  (@dl_id   = -1  or  tct.[dl_id]   = @dl_id)
  and  (@sm_id   = -1  or  tc.[sm_id]   = @sm_id)
  and  (@state_id  = -1  or  tct.[state_id]  = @state_id)
  and  (
    (@option = -1 ) or
    (@option = 0 and tc.cust_name like @cust_name + '%') or
    (@option = 1 and tc.cust_name like '%' + @cust_name + '%') or
    (@option = 2 and tc.cust_name = @cust_name) or
    (@option = 3 and tc.cust_name <> @cust_name) or
    (@option = 4 and tc.cust_name not like '%' + @cust_name + '%')
    )
  AND   vctfs.sd_id in (1,3)
  AND   tct.ct_date  BETWEEN @date_from AND @date_to


  declare @total as decimal (19,2)
  set @total = (select  sum(temp.[Facturado]) [Total] from #tmp temp)

  --select @total

  select convert(varchar,temp.cust_id)+ ' - ' + convert(varchar,temp.cust_name) [cust_name],
      sum(temp.[Facturado])             [Facturado],
      rank() OVER (ORDER BY sum(temp.[Facturado]) desc)      [Puesto Nro],
      (sum(temp.[Facturado]/dbo.fnNoZDiv(@total) * 100))      [Porcent],
      temp.sm_name                [sm_name]


  from #tmp temp

  group by temp.cust_name,temp.cust_id, temp.[sm_name]

  order by [Facturado] DESC


  exec [spReports_getData3] @comp_id,@intBranch4Lang,@lang_id,@page_id



  /* devolución de parámetros recibidos */
  DECLARE @related_page_id INT
  SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
  /*************************************************************************************************************/   /* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros   */   /*     SELECT t.ctrl_id, t.[text_de
sc]
   FROM [tbsysTexts]    t
      inner join [tbsysControls] c
      on c.[ctrl_id] = t.[ctrl_id]
    where t.[lang_id] = @lang_id
    and  t.[page_id] = @related_page_id
    and  t.[type_id] = 1
  */
  /*************************************************************************************************************/

  SELECT
    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      WHERE t.ctrl_id = 43
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params1],

    CASE @option WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (select tov.optval_desc
      from  dbo.tbsysOptionsValues tov
      where tov.optval_class =  2
      and   tov.lang_id      = @lang_id
      And   tov.optval_id    = @option)
    End [params2],

     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 370
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params3],

    CASE @fc_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  tfc.fc_desc
       FROM tbsysFiscalClass tfc
       WHERE  tfc.fc_id = @fc_id)
    END  [params4],

     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 372
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params5],

    CASE @ck_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
     (SELECT  tck.ck_name
       FROM tbCustomerKind tck
       WHERE Tck.comp_id = @comp_id AND Tck.ck_id = @ck_id)
    END  [params6],

      (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 109
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params7],

    CASE @prli_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
    (SELECT  tpl.prli_desc
       FROM tbPriceList tpl
       WHERE tpl.prli_id= @prli_id)
    END  [params8],

        (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 373
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params9],

    CASE @tnt_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
    (SELECT  ttnt.tnt_desc
       FROM tbsysTaxNumberTypes ttnt
       WHERE ttnt.tnt_id= @tnt_id)
    END  [params10],

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 57
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params11],

    CASE @country_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
       (SELECT  Tc.country_desc
       FROM tbsysCountry tc
       WHERE tc.country_id= @country_id)
    END  [params12],


    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 59
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params13],

    CASE @state_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
       (SELECT  ts.state_desc
       FROM tbsysState ts
     WHERE Ts.state_id= @state_id)
    END  [params14],

     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 175
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params15],

    CASE @st_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
       (SELECT  tst.st_desc
       FROM tbSalesTerms tst
        Where    tst.comp_id =@comp_id
       And     tst.st_id = @st_id)
    END  [params16],

      (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 173
        --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params17],

    CASE @disc_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  td.disc_desc
       FROM tbDiscount td
       WHERE td.disc_id = @disc_id)
    END  [params18],

       (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 106
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params19],

    CASE @curr_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
       (SELECT  tc.curr_desc
       FROM tbsysCurrency tc
       WHERE  tc.curr_id= @curr_id)
    END  [params20],


       (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 111
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params21],

    CASE @stor_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  ts.stor_desc
       FROM tbStorage ts
       WHERE  ts.stor_id= @stor_id)
    END  [params22],

         (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 28
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params23],

    CASE @bra_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
      (SELECT  tb2.bra_desc
       FROM tbBranch tb2
       WHERE  tb2.bra_id= @bra_id)
    END  [params24],

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 170
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params25],

    CASE @dl_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
       (SELECT  td.dl_name
       FROM tbDelivery td
       WHERE td.comp_id = @comp_id AND td.dl_id = @dl_id)
    END  [params26],

     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 172
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params27],

    CASE @sm_id WHEN -1 THEN
      (SELECT  tut.utexts_desc
       FROM tbsysUniqueTexts tut
       WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
     ELSE
        (SELECT  ts.sm_name
       FROM tbSalesman ts
       WHERE ts.comp_id = @comp_id AND Ts.sm_id = @sm_id)
    END  [params28],

    (Select @cust_name) [params29],

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 177
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1)   [params30],
        -- @date_from [DateParams1],
   convert(varchar,day(@date_from)) + '/' + convert(varchar,month(@date_from)) + '/' + convert(varchar,year(@date_from))  [DateParams1],

     (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 384
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params31],
         --@date_to [DateParams2]
   convert(varchar,day(@date_to)) + '/' + convert(varchar,month(@date_to)) + '/' + convert(varchar,year(@date_to))  [DateParams2],


   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
          WHERE t.ctrl_id = 242
          --AND t.[lang_id] = @lang_id
          and t.[page_id] = @related_page_id and t.[type_id] = 1)  [params32],

    CASE @totals WHEN 0 THEN
      (SELECT tov.optval_desc
       FROM tbsysOptionsValues tov
       WHERE tov.lang_id = @lang_id
       AND tov.optval_class = 127
       AND tov.optval_id = @totals)
     ELSE
      (SELECT tov.optval_desc
       FROM tbsysOptionsValues tov
       WHERE tov.lang_id = @lang_id
       AND tov.optval_class = 127
       AND tov.optval_id = @totals)
    END                [params33]



END
GO


CREATE Procedure [dbo].[spSalesStatistics_getReport]
(
  @comp_id			INT,
  @lang_id			INT,
  @page_id			INT,

  @cust_id			INT,
  @ck_id			INT,
  @sm_id			INT,
  @selection		INT,
  @date_from		DATETIME,
  @date_to			DATETIME,
  @option			INT,
  @bra_id			INT,
  @user_id			INT,
  @CustomerGuid		VARCHAR(50),
  @intBranch4Lang	INT

)
as


BEGIN

 set nocount on
 set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

 -- MOS 7-2012

 -- -------------------------------------------------------------
 -- Testing
 -- -------------------------------------------------------------
 /*
 Declare
   @comp_id  int,
   @lang_id  int,
   @page_id  int,
   @selection  int,
   @cust_id  int,
   @ck_id   int,
   @sm_id   int,

   @date_from      datetime,
   @date_to     DATETIME,
   @option   INT,
   @user_id        INT,
   @bra_id   INT

 Select
   @comp_id  =1,
   @lang_id  =2,
   @page_id  =10047,

   @cust_id  =-1,
   @ck_id   =-1,
   @sm_id   =-1,

   @selection  = -1,
   @date_from  ='06/01/2010',
   @date_to  ='12/31/2012',
   @option   = -1,

   @user_id        = 1,
   @bra_id   = 1
 */
 -- -------------------------------------------------------------


 DECLARE @lGuid AS UNIQUEIDENTIFIER

 SET @lGuid = CONVERT(UNIQUEIDENTIFIER,@CustomerGuid)

 -- -------------------------------------------------------------
 -- Tabla Temporal para hacer JOIN de Articulos para Filtros #8600
 -- -------------------------------------------------------------
 DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
 INSERT INTO @tblComplexFilter_Customer
  SELECT tcf.sl_id
   FROM tbComplexFilter tcf
   WHERE tcf.sl_guid = @lGuid     AND
		tcf.sl_selected = 'True'
 IF @@ROWCOUNT = 0
  BEGIN
   INSERT INTO @tblComplexFilter_Customer
	SELECT tc.cust_id
	FROM tbCustomer tc
	WHERE tc.comp_id = @comp_id
  END
 -- -------------------------------------------------------------



 DECLARE @fun_id INT
 SET @fun_id = 1

 SELECT  @date_from = dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
 SELECT  @date_to = dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')



 SELECT  convert(varchar,tc.cust_id) + '-' + convert(varchar,tc.cust_name)  [cust_name],
   tc.cust_address,
   tc.cust_city,
   tc.cust_zip,
   tc.cust_phone1,
   max(tct.ct_date)              [ct_date],
   ts.sm_name,
   SUM(dbo.fnGetExchange2(@comp_id,tct.ct_total,
         tct.curr_id_transaction,tbg.curr_id,
         tct.curr_id_transaction,tbg.curr_id,0,'False'))  [ct_total]

 FROM tbCustomer           tc
	INNER JOIN @tblComplexFilter_Customer	tmpC
		ON tmpC.cust_id = tc.cust_id

   left JOIN tbCommercialTransactions     tct
   ON tc.comp_id   = tct.comp_id
   AND tc.cust_id   = tct.cust_id
   And tct.sd_id   = 1
   --AND (@sm_id    = -1 OR tct.sm_id    = @sm_id)
   AND tct.ct_date   BETWEEN @date_from AND @date_to

   left JOIN vwCommercialTransactions_forSales   vctfs
   ON  vctfs.comp_id  = tct.comp_id
   AND vctfs.bra_id  = tct.bra_id
   AND vctfs.ct_transaction= tct.ct_transaction

--   left JOIN tbItemTransactions      tit
--   ON tit.comp_id   = tct.comp_id
--   AND tit.bra_id   = tct.bra_id
--   AND tit.ct_transaction = tct.ct_transaction

   left join tbBranch         tb
   on  tb.comp_id   = tc.comp_id
   and tb.bra_id    = tc.bra_id

   left JOIN tbBranchGroupDetail      tbgd
   ON tbgd.comp_id  = tct.comp_id
   AND tbgd.bra_id   = tct.bra_id

   left JOIN tbBranchGroup        tbg
   ON tbg.comp_id   = tct.comp_id
   AND tbg.brag_id   = tbgd.brag_id

   left JOIN tbSalesman        ts
   ON ts.comp_id   = tc.comp_id
   AND ts.sm_id   = tc.sm_id

   left JOIN tbUsers4BranchFilter      vubf
   ON vubf.comp_id  = tct.comp_id
   AND vubf.bra_id   = tct.bra_id
   AND vubf.[user_id]  = @user_id



  WHERE tc.comp_id = @comp_id
  AND  (@cust_id  = -1  or tc.cust_id    = @cust_id)
  AND  (@ck_id  = -1  or tc.ck_id     = @ck_id)
  AND  (@selection = -1  or tc.cust_inactive  = ~convert(bit,@selection))
  AND  (
    @option = -1
    OR
    (@option = 1 AND tc.cust_id IN (		SELECT distinct tct2.cust_id				-- No se a qioen mierda se le ocurrió esta ABERRACION, esca cagada hay que reghacerla !!!!!!!!
												 FROM tbCommercialTransactions tct2
												 WHERE tct2.sd_id  = 1
													AND tct2.ct_date BETWEEN @date_from AND @date_to
													AND tct2.cust_id = tc.cust_id	AND (@bra_id   = -1 OR tb.bra_id   = @bra_id) AND tct2.comp_id = @comp_id
								   ))
    OR
    (@option = 2 AND tc.cust_id NOT IN (	SELECT  distinct tct2.cust_id				-- No se a qioen mierda se le ocurrió esta ABERRACION, esca cagada hay que reghacerla !!!!!!!!
												 FROM tbCommercialTransactions tct2
												 WHERE  tct2.sd_id  = 1
													AND  tct2.ct_date BETWEEN @date_from AND @date_to
													AND  tct2.cust_id = tc.cust_id	AND (@bra_id   = -1 OR tb.bra_id   = @bra_id) AND tct2.comp_id = @comp_id
									   ))
   )

  AND (@sm_id    = -1 OR tc.sm_id    = @sm_id)
  --AND (@bra_id   = -1 OR tb.bra_id   = @bra_id)



  GROUP BY  tc.cust_id,
      tc.cust_name,
      tc.cust_address,
      tc.cust_city,
      tc.cust_zip,
     tc.cust_phone1,
      ts.sm_name


  ORDER BY [ct_total] DESC, 1







 exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id, @page_id

 /* devolución de parámetros recibidos */
 DECLARE @related_page_id INT
 SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
 /*************************************************************************************************************/  /* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros   */  /*    SELECT t.ctrl_id, t.[text_desc]

   FROM [tbsysTexts]    t
     inner join [tbsysControls] c
     on c.[ctrl_id] = t.[ctrl_id]
   where t.[lang_id] = @lang_id
   and  t.[page_id] = @related_page_id
   and  t.[type_id] = 1
 */
 /*************************************************************************************************************/

 SELECT

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 174
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params1],

   CASE @cust_id WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
     (SELECT  tc.cust_name
      FROM tbCustomer tc
      WHERE tC.comp_id = @comp_id AND tc.cust_id= @cust_id)
   END  [params2],

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 177
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params3],
   CASE @date_from WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
     @date_from
     --convert(varchar,day(@date_from)) + '/' + convert(varchar,month(@date_from)) + '/' + convert(varchar,year(@date_from))
   END  [DateParams1],--[params4],

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 384
  --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params5],
   CASE @date_to WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
     --convert(varchar,day(@date_to)) + '/' + convert(varchar,month(@date_to)) + '/' + convert(varchar,year(@date_to))
     @date_to
   END  [DateParams2],

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 372
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params7],
   CASE @ck_id WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
     (SELECT tck.ck_name
     FROM tbCustomerKind tck
     WHERE tck.comp_id = @comp_id
     AND  tck.ck_id=@ck_id)
   END  [params8],

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 172
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params9],
   CASE @sm_id WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
     (SELECT ts.sm_name
     FROM tbSalesman ts
     WHERE ts.comp_id = @comp_id
     AND  ts.sm_id=@sm_id)
   END  [params10],

   (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 1099
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params11],
   CASE @selection WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
     (SELECT tov.optval_desc
      FROM tbsysOptionsValues tov
      WHERE tov.lang_id = @lang_id
      AND   tov.optval_class = 72
      And tov.optval_id = @selection)
   END  [params12],


    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 991
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params13],

   CASE @option WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
     (SELECT tov.optval_desc
      FROM tbsysOptionsValues tov
      WHERE tov.lang_id = @lang_id
      AND   tov.optval_class = 129
      And tov.optval_id = @option)
   END  [params14],

    (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
         WHERE t.ctrl_id = 28
         --AND t.[lang_id] = @lang_id
         and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id =@fun_id )  [params15],
   CASE @bra_id WHEN -1 THEN
     (SELECT  tut.utexts_desc
      FROM tbsysUniqueTexts tut
      WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
    ELSE
      (SELECT tb.bra_desc
     FROM tbBranch tb
     WHERE tb.comp_id = @comp_id
