CREATE PROCEDURE [dbo].[spSalesTerms_getComboByProfile]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE 	@comp_id	INT, @prof_id	INT
	SELECT		@comp_id	=1, @prof_id	=2
	*/

	select		tst.st_id		[id],
				tst.st_desc		[desc]

		from		dbo.tbSalesTerms tst	WITH (NOLOCK)

		where		tst.comp_id =	@comp_id
			AND isnull(tst.st_disabled,'false')		= 'false'
			AND (tst.bra_id IS NULL OR tst.bra_id	= @bra_id OR @bra_id = -1)
			AND			(tst.st_id IN	(SELECT	tstp.st_id
	   										FROM	tbSalesTerms4Profile tstp		WITH (NOLOCK)
	   										WHERE	tstp.comp_id	= @comp_id
											AND		tstp.prof_id	= @prof_id) OR
						 NOT EXISTS		(SELECT	1
	   										FROM	tbSalesTerms4Profile tstp		WITH (NOLOCK)
	   										WHERE	tstp.comp_id	= @comp_id
											AND		tstp.prof_id	= @prof_id))

		Order By	st_desc

END
GO







