CREATE PROCEDURE [dbo].[spSalesTerms_GetDataByFilters]
(
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON


/*
DECLARE
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		int
SELECT
	@comp_id	=1,
	@bra_id		=1,
	@soh_id		=-1
*/


SELECT 	st.st_id		[id],
		st.st_desc		[desc],
