WHERE	st.comp_id	= @comp_id
AND		st.disc_id	is NOT NULL

Order By	st_desc






SELECT	tsoed.st_id,
		tsoed.total,
		tsoed.saleterm_origin

FROM	tbSaleOrderExtendedDiscounttmp tsoed

WHERE	tsoed.guid = @guid
GO






