CREATE PROCEDURE [dbo].[spSalesTerms_GetDataByFilters4ThisBranch]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id		 AS INT,
	@guid			 AS UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE 	@comp_id	INT, @prof_id	INT
	SELECT		@comp_id	=1, @prof_id	=2
	*/

	select		tst.st_id		[id],
				tst.st_desc		[desc],
				td.disc_coef

		from		dbo.tbSalesTerms tst

		LEFT JOIN tbDiscount		td
			ON td.comp_id  = tst.comp_id
			AND td.disc_id = tst.disc_id

		where		tst.comp_id =	@comp_id
			AND		tst.disc_id	is NOT NULL
			AND isnull(tst.st_disabled,'false')		= 'false'
			AND (tst.bra_id IS NULL OR tst.bra_id	= @bra_id OR @bra_id = -1)
