CREATE PROCEDURE [dbo].[spSalesTerms_getDataById]
(
	@comp_id			int			,
	@st_id				INT,
	@bra_id				INT
)
as

	select		isnull(st.prli_id4Credit,-1)												[prli_id4Credit],
			    isnull(st.st_CreditQuotaQty4Show,0)											[st_CreditQuotaQty4Show],
			    ISNULL(st.MOBBEX_fraudEnabled,'False')										[bitMOBBEX_fraudEnabled],
			    ISNULL(st.MOBBEX_multicardEnabled,'False')									[bitMOBBEX_multicardEnabled],
				st.*,
				CONVERT(BIT,ISNULL(st.st_disable4CreditControlInSalesOrder,'False'))		[disable4CreditControlInSalesOrder],
				IsNull(td.disc_coef,0)	 * 100												[decPercentage],
				CASE	WHEN tcc.cc_PaymentsQty IS NULL THEN	1
						WHEN tcc.cc_PaymentsQty = 0		THEN	1
						ELSE									tcc.cc_PaymentsQty
				END																			[cc_PaymentsQty]	,
				IsNull(st.st_MPEnabled,'False')												[MPEnabled],
				ISNULL(st.st_directCollection_cn_id_Alternative,'False')					[isCN_Alternative],
				IsNull(st.st_CreditPayDateMaxDaysOffset,0)									[st_CreditPayDateMaxDaysOffsetNOTNull],
				tct.sct_inCashRequired,
				CASE
					WHEN tct.sct_id IS NULL OR tct.sct_id = 0 THEN	'False'
					ELSE											'True'
				END																			[sct_isPersonalLoan],
				tct.sct_firstPayDateRequired,
				IsNull(st.st_OvercomeBalanceToleranceInPercent,0)							[st_OvercomeBalanceToleranceInPercent],
				CASE
					WHEN st.cc_id IS NOT NULL						THEN	'True'
					WHEN st.sct_id IN (2,4,21,25)						THEN	'True'
					WHEN st.st_collectionPaymentsAvailable = 'True' THEN	'True'
					ELSE													'False'
				END																			[bitInCashEnabled],
				IsNull(df_idAdditional,-1)													[STdf_idAdditional],
				CASE
					when st.cc_id IS NULL THEN 'False'
					ELSE 'True'
				END																			[isCreditCardAssociated],
				IsNull(st.st_collectionPaymentsAvailable,'False')							[PaymentPlanEnabled],
				IsNull(st.st_collectionDiscountsAvailable,'False')							[DiscountPlanEnabled],
				ISNULL(st.st_AuthorizationRequiredUp2Total_I,0)								[AuthorizationRequiredUp2Total_I],
				ISNULL(st.st_AuthorizationRequiredUp2Total_II,0)							[AuthorizationRequiredUp2Total_II],
				ISNULL(st.st_AuthorizationRequiredUp2Total_III,0)							[AuthorizationRequiredUp2Total_III],
				ISNULL(st.NPS_NumPayments,1)												[NPS_NumPayments],
				CASE
					when st.cc_id IS NULL	THEN	'False'
					ELSE							'True'
				END																			[isNPSCreditCardAssociated],
				ISNULL(st.NPS_cc_id	,-1)													[NPS_cc_id]	,		-- NO SE USA MAS !!!!
				ISNULL(st.cc_id,-1)															[CreditCardID],
				ISNULL(st.disc_id,-1)														[disc_idRelated],
				ISNULL(st.NPS_Enabled4Implementation,'True')								[NPS_Enabled4Implementation],
				ISNULL(st.NPS_Plan,'')														[NPS_Plan]	,
				ISNULL(st.VISATP_Enabled,'False')											[VISATP_Enabled],
				st.VISATP_Merchant,
				st.VISATP_Authorization,
				st.VISATP_URLOKTrans,
				st.VISATP_URLBack,
				st.VISATP_Enabled4Implementation,
				st.VISATP_ItemDescription,
				st.VISATP_ItemCode	,
				st.VISATP_AvailableMethods,
				ISNULL(st.st_microSite_SO4WebSiteCustomerMicroSite,'False')					[st_microSite_SO4WebSiteCustomerMicroSite],
				ISNULL(st.st_directCollectionOpenPaymentMethodType,0)						[directCollectionOpenPaymentMethodType],
				ISNULL(st.st_directCollection,'False')										[directCollection],
				ISNULL(st.st_directCollectionWithCash,'False')								[directCollectionWithCash],
				ISNULL(st.st_directCollection_currId,1)										[st_directCollection_currId],
				ISNULL(st.directCollection4NC,'False')										[intDirectCollection4NC],
				ISNULL(st.st_ML_disableBlockIfNoPayed,'False')								[st_ML_disableBlockIfNoPayed],
				ISNULL(tcc.cc_MPIsEnabled,'False')											[MPcc_MPIsEnabled],
				ISNULL(tcc.cc_MPType,-1)													[MPcc_MPType],
				ISNULL(tmls.mls_clientID,'')												[MPmls_clientID],
				isnull(tmls.mls_clientSecret,'')											[MPmls_clientSecret],
				isnull(TCC.cc_MPPointTitle,'')												[MPcc_MPPointTitle],
				ISNULL(tmls.mls_url4S2Sdialog,'')											[MPmls_url4S2Sdialog],
				ISNULL(st.st_directCollection_cc_id,-1)										[directCollection_cc_id],
				ISNULL(st.st_MEEnabled,'False')												[MEEnabled],
				ISNULL(st.st_ME_dl_id,-1)													[ME_dl_id]	,
				ISNULL(st.st_MELocalPickUp,'False')											[MELocalPickUp],
				ISNULL(st.st_MEfree_shipping,'False')										[MEfree_shipping],
				CASE
					WHEN st.currId_IncrementByPercent = 'True' AND tb.comp_id IS NOT NULL	THEN	dbo.fnGetExchange2(@comp_id,1,st.curr_id_4Increment,tb.curr_id,0,0,0,'False') * st.currId_Increment / 100
					WHEN st.currId_IncrementByPercent = 'False'								THEN	st.currId_Increment
					ELSE																			0
				END																			[CurrencyTotalIncrement],
				ISNULL(tcc.cc_MPexpires,'False')											[cc_MPexpires],
				ISNULL(tcc.cc_MPexpires_Days2Expire,0)										[cc_MPexpires_Days2Expire],
				ISNULL(tcc.cc_MPexcluded_payment_methods,'')								[cc_MPexcluded_payment_methods],
				ISNULL(tcc.cc_MPexcluded_payment_types,'')									[cc_MPexcluded_payment_types],
				ISNULL(tcc.cc_MPdefault_payment_method_id,'')								[cc_MPdefault_payment_method_id],
				ISNULL(tcc.cc_MPinstallments,0)												[cc_MPinstallments],
				ISNULL(tcc.cc_MPdefault_installments,0)										[cc_MPdefault_installments],
				ISNULL(tcc.cc_MPBotonDePago_back_urls_success,'')							[cc_MPBotonDePago_back_urls_success],
				ISNULL(tcc.cc_MPBotonDePago_back_urls_pending,'')							[cc_MPBotonDePago_back_urls_pending],
				ISNULL(tcc.cc_MPBotonDePago_back_urls_failure,'')							[cc_MPBotonDePago_back_urls_failure]	,
				ISNULL(tmls.MLUser_Id,-1)													[MLUser_Id],
				ISNULL(st.st_MPInstallMents,1)												[MPInstallMents],
				ISNULL(st.st_MPDefaultInstallMents,1)										[MPDefaultInstallMents],
				ISNULL(st.st_discountPlanCoeficient,0)									AS	st_discountPlanCoeficient,
				ISNULL(st.MOBBEX_Enabled,'')												[MOBBEX_Enabled],
				ISNULL(st.MOBBEX_APIKey,'')													[MOBBEX_APIKey],
				ISNULL(st.MOBBEX_AccessToken,'')											[MOBBEX_AccessToken],
				ISNULL(st.MOBBEX_ImageURL,'')												[MOBBEX_ImageURL],
				ISNULL(st.MOBBEX_PaymentDesc,'')											[MOBBEX_PaymentDesc],
				ISNULL(st.MOBBEX_URLOKTrans,'')												[MOBBEX_URLOKTrans],
				ISNULL(st.MOBBEX_URLBack,'')												[MOBBEX_URLBack],
				CASE
					when st.cc_id IS NULL	THEN	'False'
					ELSE							'True'
				END																			[isMobbexCreditCardAssociated]		,
				ISNULL(st.st_directCollectionWithBankingAccount,'False')					[directCollectionWithBankingAccount],
				ISNULL(st.st_directCollectionWithBankingAccount_ba_id,-1)					[directCollectionWithBankingAccount_ba_id],
				ISNULL(tba.curr_id,-1)														[directCollectionWithBankingAccount_curr_id],
				ISNULL(tcc.DECIDIRBP_enabled,'False')										[DECIDIRBP_enabled],
				tcc.DECIDIRBP_ApiKeyPublic,
				tcc.DECIDIRBP_ApiKeyPrivate,
				tcc.DECIDIRBP_developmentMode,
				tcc.DECIDIRBP_templateID,
				tcc.DECIDIRBP_installments,
				tcc.DECIDIRBP_payment_method_id,
				tcc.DECIDIRBP_payment_type,
				tcc.DECIDIRBP_success_url,
				tcc.DECIDIRBP_cancel_url,
				ISNULL(tcc.DECIDIRBP_byDefaultCustomerEMail,'')								[DECIDIRBP_byDefaultCustomerEMail],
				ISNULL(st.st_directCollection_enabled4PackingList,'False')					[directCollection_enabled4PackingList],
				ISNULL(st.st_paymentButtonInterest,0)										[st_paymentButtonInterest]




	from		dbo.tbSalesTerms				st			WITH (NOLOCK)

	LEFT JOIN tbDiscount						td			WITH (NOLOCK)
		ON		td.comp_id	= st.comp_id
			AND td.disc_id	= st.disc_id

	LEFT JOIN tbCreditCard						tcc			WITH (NOLOCK)
		ON		tcc.comp_id = st.comp_id
		AND		tcc.cc_id	= st.cc_id

	LEFT JOIN tbMercadoLibre_Stores				tmls		WITH (NOLOCK)
		ON	tmls.comp_id	= tcc.comp_id AND
			tmls.mls_id		= tcc.mls_id

	LEFT JOIN tbsysCreditTypes tct							WITH (NOLOCK)
	 ON tct.sct_id = st.sct_id

	LEFT JOIN tbBranch							tb			WITH (NOLOCK)
		ON	tb.comp_id		= @comp_id AND
			tb.bra_id		= @bra_id

	LEFT JOIN tbBankingAccounts				AS tba			WITH (NOLOCK)
		ON	tba.comp_id = st.comp_id AND
			tba.ba_id	= st.st_directCollectionWithBankingAccount_ba_id

	where		st.comp_id	=	@comp_id
			AND st.st_id	=	@st_id
GO







