CREATE PROCEDURE [dbo].[spSecurityLog_getDataByFilters]
(
	@comp_id		INT,
	@lang_id		INT,
	@user_id		INT,
	@optval_id		INT,
	@datefrom		DATETIME,
	@dateto			DATETIME,
	@prof_id		INT,
	@user2_id		INT,
	@aut_id			INT,
	@user_id_logged	INT


)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	-- -------------------------------------------------
	-- Testing
	-- -------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@lang_id	INT,
		@user_id	INT,
		@optval_id	INT,
		@datefrom	DATETIME,
		@dateto		DATETIME,
		@prof_id	INT,
		@user2_id	INT,
	@aut_id		int

	SELECT
		@comp_id	=  1,
		@lang_id	=  2,
		@user_id	=  -1,
		@optval_id  = 1000,
		@datefrom	= '2014-12-05',
		@dateto		= '2014-12-05',
		@prof_id	= -1,
		@user2_id	= -1,
		@aut_id		= -1

*/
	-- -------------------------------------------------


	SET @dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	SELECT
		CASE
			WHEN tsl.seclog_pageHTML IS NULL THEN 0
			ELSE 1
		END  [ ],
		tc.comp_desc,
		tb.bra_desc,
		tu.user_lastname + ', ' + tu.user_firstname [user_name],
		tov.optval_desc,

		CASE
			WHEN (@optval_id = 9999) THEN	tswn.word_desc
			ELSE							tsl.seclog_obs_1
		END [seclog_obs_1],

		--tsl.seclog_obs_1,
		tsl.seclog_obs_2,

		tsl.seclog_obs_3,
		tsl.seclog_obs_4,
		IsNull(tml2.mid_desc,'') + ' - ' +  isnull(tml.mid_desc,'')			[mid_desc],
		tsl.seclog_cd,
		tsl.request_ip,
		tsl.request_name,
		tu2.user_lastname + ', ' + tu2.user_firstname[user_name2],
		tsl.aure_isok,
		tp.prof_desc,
		--tct.cust_id		[cust_id],
		tsl.seclog_id [ID]

	FROM tbSecurityLog tsl								WITH (NOLOCK)

		left JOIN tbCompany tc							WITH (NOLOCK)
		ON tc.comp_id = tsl.comp_id

		left JOIN tbBranch tb							WITH (NOLOCK)
		ON tb.comp_id = tsl.comp_id
		AND tb.bra_id = tsl.bra_id

		left JOIN tbUser tu								WITH (NOLOCK)
		ON tu.[user_id] = tsl.[user_id]

		left JOIN tbUser tu2							WITH (NOLOCK)
		ON tu2.[user_id] = tsl.aure_user_id

		left JOIN tbsysOptionsValues tov				WITH (NOLOCK)
		ON tov.lang_id = @lang_id
		AND tov.optval_class = 56
		AND tov.optval_id = tsl.sysCode_id

		LEFT JOIN tbProfile tp							WITH (NOLOCK)
		ON tp.comp_id = tsl.comp_id
		AND tp.prof_id = tsl.prof_id

		LEFT JOIN tbsysTables tt						WITH (NOLOCK)
		ON tt.table_id	=  CASE
		              	       WHEN @optval_id = 1000		THEN 0
		              	       WHEN tsl.sysCode_id = 9990	THEN dbo.fnGetOnlyNumbers(tsl.seclog_obs_3)
		              	       ELSE 0
		              	   END

		LEFT JOIN tbsysNamesNew tnn						WITH (NOLOCK)
			ON	tnn.table_id = tt.table_id			AND
				tnn.[type_id] = 1					AND
				tnn.field_id IS NULL

		LEFT JOIN tbSysWordsNew tswn					WITH (NOLOCK)
			ON	tswn.lang_id = @lang_id				AND
				tswn.wordsi_id = tnn.name_desc_id

		LEFT JOIN tbsysMenuLanguage tml					WITH (NOLOCK)
			ON	tml.menu_id = tsl.menu_id			AND
				tml.lang_id = @lang_id

		LEFT JOIN tbsysMenu tm							WITH (NOLOCK)
			ON tm.menu_id = tsl.menu_id

		LEFT JOIN tbsysMenuLanguage tml2				WITH (NOLOCK)
			ON	tml2.menu_id = tm.menu_id_sup		AND
				tml2.lang_id = @lang_id

		--LEFT JOIN tbCommercialTransactions			tct
		--ON	tsl.comp_id			= tct.comp_id	AND
		--	tsl.bra_id			= tct.bra_id	AND
		--	tsl.ct_transaction	= tct.ct_transaction


		WHERE	tsl.comp_id = @comp_id								AND
				tsl.seclog_cd BETWEEN @datefrom AND @dateto			AND
				(@user_id = -1 OR tsl.[user_id] = @user_id)			AND

				(
					(@optval_id = -1 AND tsl.sysCode_id <> 1000)	OR
					 tsl.sysCode_id = @optval_id					OR
					(@optval_id = 1000 AND tsl.sysCode_id IS NULL)
				)													AND

				(@user2_id = -1 OR tsl.aure_user_id = @user2_id)	AND
				(@prof_id = -1  OR tsl.prof_id = @prof_id)			AND
				(@aut_id = -1 OR tsl.aut_id = @aut_id)				AND

				-- Se quejan que se mezclan tareas de configuracion con el resto por lo que se sacan logs de ERPAdmin y ERPSoporte
				(
						(tsl.[user_id] <> 1 AND tsl.[user_id] <> 10001 AND tsl.[user_id] <> 10002)
							OR
						tsl.[user_id] IS NULL
							OR
						@user_id_logged = 1
				)

		ORDER BY tsl.seclog_cd DESC

END
GO








CREATE PROCEDURE [dbo].[spSecurityLog_getDataForTC]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@user_id		INT,
	@prof_id		INT,
	@top_filter		INT
)
AS

SET NOCOUNT ON
------------------------------------------------------------------------
---  ACTUALIZADO CON tbSysNamesNew 26/02/2010---------------------------
------------------------------------------------------------------------



/*
DECLARE @comp_id	INT,
		@lang_id	INT,
		@bra_id		INT,
		@user_id	INT,
		@prof_id	INT,
		@top_filter	INT
SELECT 	@comp_id	=1,
		@lang_id	=2,
		@bra_id		=1,
		@user_id	=1,
		@prof_id	=1,
		@top_filter	=10
DROP TABLE #tmp1
*/



DECLARE @totalcount INT
DECLARE @max		INT




SELECT	top (@top_filter)
		count(*) [count],
		tsl.seclog_obs_1,
		tsl.seclog_obs_2,
		tsl.seclog_obs_3,
		CASE WHEN tsl.seclog_obs_1 = 'wfmGeneric' THEN tswn.word_desc ELSE tw.word_desc END [desc]


INTO	#tmp1

FROM	tbSecurityLog					tsl


		LEFT JOIN tbsysTextsNew			tt
		ON 	tt.page_id		= CONVERT(INT,ISNULL(dbo.fnSplitPosition(tsl.seclog_obs_3,'-',1), tsl.seclog_obs_3))
		AND tt.ctrl_id		= 29
		AND tt.[type_id]	= 1
		AND tt.prop_id		= 1
		AND tt.fun_id		= CONVERT	(INT,CASE WHEN ISNUMERIC(ISNULL(dbo.fnSplitPosition(tsl.seclog_obs_3,'-',2), 1)) = 1
													THEN ISNULL(dbo.fnSplitPosition(tsl.seclog_obs_3,'-',2), 1)
													ELSE 0 END
										)


		LEFT JOIN tbsysWordsNew			tw
		on tw.lang_id		= @lang_id
		AND tw.wordsi_id	= tt.wordsi_id


		LEFT JOIN tbsysNamesNew			tn
		ON 	tn.table_id		= CONVERT(INT,ISNULL(dbo.fnSplitPosition(tsl.seclog_obs_3,'-',1), tsl.seclog_obs_3))
		AND tn.ctrl_id		= 29
		AND tn.prop_id		= 1


		LEFT JOIN tbSysWordsNew			tswn
		ON tswn.lang_id		= @lang_id
		AND tswn.wordsi_id	= tn.name_desc_id


WHERE	tsl.comp_id			= @comp_id
AND		tsl.bra_id			= @bra_id
AND		tsl.[user_id]		= @user_id
AND		tsl.prof_id			= @prof_id
AND		tsl.sysCode_id		= 100
AND		(
			(tsl.seclog_obs_1 <> 'wfmGeneric') OR
			(tsl.seclog_obs_1 =  'wfmGeneric' AND tsl.seclog_obs_2 <> '')
		)
AND		tsl.seclog_cd		BETWEEN		GETDATE() - 10 AND GETDATE()


GROUP BY tsl.seclog_obs_1, tsl.seclog_obs_2, tsl.seclog_obs_3
			,tswn.word_desc,tw.word_desc

ORDER BY [count] DESC

--SELECT * FROM	#tmp1	tsl





SET		@totalcount = (SELECT SUM([COUNT])					FROM	#tmp1)
SELECT	@max		= max(tsl.[count] * 100 / @totalcount)	FROM	#tmp1	tsl






SELECT	CASE
			WHEN ((tsl.[count] * 100 / @totalcount) * 100 / @max) <  21 THEN  1
			WHEN ((tsl.[count] * 100 / @totalcount) * 100 / @max) <  41 THEN  2
			WHEN ((tsl.[count] * 100 / @totalcount) * 100 / @max) <  61 THEN  3
			WHEN ((tsl.[count] * 100 / @totalcount) * 100 / @max) <  81 THEN  4
			WHEN ((tsl.[count] * 100 / @totalcount) * 100 / @max) < 101 THEN  5
      	END										[value2],
		(tsl.[count] * 100 / @totalcount)		[value1],
		tsl.[count],
		tsl.seclog_obs_1 + '.aspx' [seclog_obs_1],
		tsl.seclog_obs_2,
		tsl.seclog_obs_3,
		case when len(tsl.[desc]) > 35 THEN SUBSTRING(tsl.[desc],0,35) + '...'
			else tsl.[desc] end [desc]
FROM	#tmp1	tsl
GO






CREATE PROCEDURE [dbo].[spSecurityLog_insertData]
(
	@comp_id				INT,
	@bra_id					INT,
	@user_id				INT,
	@seclog_obs_1			VARCHAR(1000),
	@seclog_obs_2			VARCHAR(1000),
	@seclog_obs_3			VARCHAR(1000),
	@seclog_obs_4			VARCHAR(1000),
	@aut_id					INT,
	@sysCode_id				INT,
	@menu_id				INT,
	@request_ip				VARCHAR(100),
	@request_name			VARCHAR(100),
	@aure_isok				CHAR(1),
	@aure_user_id			INT,
	@prof_id				INT,
	@aure_id				INT,
	@aure_cd				DATETIME,

	@seclog_id1				INT,
	@seclog_id2				INT,
	@seclog_id3				INT,
	@seclog_pageHTML		TEXT,

	@return_value			INT			OUTPUT
)
AS

BEGIN



	SET NOCOUNT ON

	-- =================================================================================================================
	-- Author		: MOS
	-- Update Date	: 2010-09-11
	-- Parte		: 550
	-- Description	: Para poder recuperar todos los datos necesarios correspondientes a las autorizaciones, se agregaron
	--				  los campos aure_id y aure_cd a la tabla tbSecurityLog y por lo tanto se agregan esos nuevos parámetros
	-- =================================================================================================================

	-- MOS 01-2015
	SET LOCK_TIMEOUT 500  -- **JAVIER**
	SET DEADLOCK_PRIORITY LOW  -- **JAVIER**
	set nocount on


	BEGIN TRY -- MOS 01-2015


		-- Como el enfermo HDP hizo cualquiera ahora grabo esto aca.-
		-- CVon tiempo hay que guardar el menu_id de esta pagina.
		IF @seclog_obs_1 = 'wfmGeneric'
			BEGIN
				SET @sysCode_id = 9999
			END



		DECLARE @lseclog_cd DATETIME

		IF @sysCode_id = 13
			SET @lseclog_cd = DATEADD(second, 1, GETDATE())
		ELSE
			SET @lseclog_cd = GETDATE()





		INSERT INTO dbo.tbSecurityLog		WITH (ROWLOCK)
		(
			comp_id,
			bra_id,
			[user_id],
			seclog_obs_1,
			seclog_obs_2,
			seclog_image,
			seclog_obs_3,
			seclog_obs_4,
			seclog_cd,
			aut_id,
			sysCode_id,
			menu_id,
			request_ip,
			request_name,
			aure_isok,
			aure_user_id,
			prof_id,
			aure_id,	-- Parte: 550
			aure_cd,	-- Parte: 550

			seclog_id1,
			seclog_id2,
			seclog_id3,
			seclog_pageHTML
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@user_id,
			@seclog_obs_1,
			@seclog_obs_2,
			null,
			@seclog_obs_3,
			@seclog_obs_4,
			@lseclog_cd,
			@aut_id,
			@sysCode_id,
			@menu_id,
			@request_ip,
			@request_name,
			@aure_isok,
			@aure_user_id,
			@prof_id,
			@aure_id,	-- Parte: 550
			@aure_cd,	-- Parte: 550

			@seclog_id1,
			@seclog_id2,
			@seclog_id3,
			@seclog_pageHTML

		)


		set	@return_value = @@identity

	END TRY
	BEGIN CATCH
		set	@return_value = -1
	END CATCH


END
GO





