CREATE PROCEDURE [dbo].[spSelCustomer2]
(
	@comp_id			int,
	@cust_name			Varchar (100),
	@cust_name1			Varchar (100),
	@cust_address		Varchar	(100),
	@cust_taxNumber		varchar (100),
	@cust_city			Varchar (100),
    @cust_zip			Varchar (20),
	@cust_Phone1        Varchar (100),
	@cust_Phone2		Varchar (100),
	@country_id			int,
	@state_id			int,
	@page_id			int,
	@row_count			int
)
as

/*
declare @comp_id		int,
	@cust_name			Varchar (100),
	@cust_name1			Varchar (100),
	@cust_address		Varchar	(100),
	@cust_city			Varchar (100),
    @cust_zip			Varchar (20),
	@cust_taxNumber		varchar (100),
	@cust_Phone1        Varchar (100),
	@cust_Phone2		Varchar (100),
	@country_id			int,
	@state_id			int,
	@page_id			int,
	@row_count			int

select @comp_id			=1,
	@cust_name			='',
	@cust_name1			='',
	@cust_address		='',
	@cust_city			='',
    @cust_zip			='',
	@cust_taxNumber		='',
	@cust_Phone1        ='',
	@cust_Phone2		='',
	@country_id			=-1,
	@state_id			=-1,
	@page_id			=0,
	@row_count			=10
*/
--declare @ddtt datetime
--select @ddtt = getdate()

declare		@recordCount	int,
			@startRowIndex	int

select @recordCount = (	select	count(1)
						from	tbCustomer					c
								inner join tbsysCountry		sc
								on sc.country_id			= c.country_id
								inner join tbsysState		ss
								on  ss.state_id             = c.state_id
								and ss.country_id			= c.country_id
						Where   c.comp_id				= @comp_id
						AND		isnull(c.cust_name		,'')	like '%' +  @cust_name		+ '%'
						AND		isnull(c.cust_name1		,'')	like '%' +  @cust_name1		+ '%'
						AND		isnull(c.cust_address	,'')	like '%' +  @cust_address	+ '%'
						AND		isnull(c.cust_taxNumber	,'')	like '%' +	@cust_taxNumber + '%'
						AND		isnull(c.cust_city		,'')	like '%' +  @cust_city		+ '%'
						AND		isnull(c.cust_zip		,'')	like '%' +  @cust_zip		+ '%'
						AND		isnull(c.cust_Phone1	,'')	like '%' +  @cust_Phone1	+ '%'
						AND		isnull(c.cust_Phone2	,'')	like '%' +  @cust_Phone2	+ '%'
						AND		(sc.country_id		    = @country_id	OR  @country_id     = -1)
						AND		(ss.state_id			= @state_id		OR  @state_id       = -1))

--select @recordCount



set @startRowIndex = (@page_id * @row_count)+1;
--select @startRowIndex;


WITH customerEntries AS
	(select		ROW_NUMBER() over (order by cust_name asc) as row,
				c.cust_id,
				c.cust_name,
				c.cust_name1,
				c.cust_address,
				c.cust_taxNumber,
				c.cust_city,
				c.cust_zip,
				c.cust_Phone1,
				c.cust_Phone2,
				sc.country_desc,
				ss.state_desc

	from	tbCustomer					c

			inner join tbsysCountry		sc
			on sc.country_id			= c.country_id

			inner join tbsysState		ss
			on  ss.state_id             = c.state_id
			and ss.country_id			= c.country_id

	Where   c.comp_id										=  @comp_id
	AND		isnull(c.cust_name		,'')	like '%' +  @cust_name		+ '%'
	AND		isnull(c.cust_name1		,'')	like '%' +  @cust_name1		+ '%'
	AND		isnull(c.cust_address	,'')	like '%' +  @cust_address	+ '%'
	AND		isnull(c.cust_taxNumber	,'')	like '%' +	@cust_taxNumber	+ '%'
	AND		isnull(c.cust_city		,'')	like '%' +  @cust_city		+ '%'
	AND		isnull(c.cust_zip		,'')	like '%' +  @cust_zip		+ '%'
	AND		isnull(c.cust_Phone1	,'')	like '%' +  @cust_Phone1	+ '%'
	AND		isnull(c.cust_Phone2	,'')	like '%' +  @cust_Phone2	+ '%'
	AND		(@country_id	= -1		or	sc.country_id	= @country_id	)
	AND		(@state_id		= -1		or	ss.state_id		= @state_id		)
	)


select	cust_name,
		cust_name1,
		cust_address,
		cust_taxNumber,
		cust_city,
		cust_zip,
		cust_Phone1,
		cust_Phone2,
		country_desc,
		state_desc,
		cust_id
from	customerEntries
where row between @startRowIndex and (@startRowIndex+@row_count-1)
--select getdate()-@ddtt



















GO







CREATE PROCEDURE [dbo].[spSelection_getDataById]
(
	@comp_id					int,
	@option						int,
	@desc						VARCHAR(100)


)
AS
SET NOCOUNT ON


/*
DECLARE   @comp_id			INT,
		  @cust_name		INT

SELECT @comp_id = 1,
	@cust_name=''
*/




--//ITEM//
IF @option = 0
BEGIN
	SELECT	ti.item_code
	FROM	tbItem ti

	WHERE  ti.comp_id    = @comp_id
	AND    ti.item_code  = LTRIM(@desc)
END



--//CUSTOMER//
IF @option = 1
BEGIN
	SELECT	tc.cust_id
	FROM	tbCustomer tc

	WHERE  tc.comp_id   = @comp_id
	AND    tc.cust_id =   convert(int,@desc)
END


--//SUPPLIER//
IF @option = 2
BEGIN
	SELECT	ts.supp_id
	FROM	tbSupplier ts

	WHERE  ts.comp_id   = @comp_id
	AND    ts.supp_id   = convert(int,@desc)
END



--//ACCOUNTANT//
IF @option = 3
BEGIN
	SELECT	ta.acc_code
	FROM	tbAccountant ta

	WHERE  ta.comp_id		= @comp_id
	AND    ta.acc_code  = LTRIM(@desc)
END


GO








CREATE PROCEDURE [dbo].[spSelItemAddData]
(
	@item_id			int
)

as


Select	i.item_detail,
		i.item_vendorCode,
		i.item_annotation,
		tb.brand_desc,
		tp.pres_desc,
		tc.curr_desc

From	tbItem						i

		inner join tbBrand			tb
		on  tb.comp_id				= i.comp_id
		and tb.brand_id				= i.brand_id

		inner join tbPresentation	tp
		on  tp.comp_id				= i.comp_id
		and tp.pres_id				= i.pres_id

		inner join tbsysCurrency	tc
		on tc.curr_id				= i.curr_id

Where	item_id						= @item_id





GO





















CREATE PROCEDURE [dbo].[spSelSupplier]
(
	@comp_id			int,
	@supp_name			Varchar (100),
	@supp_name1			Varchar (100),
	@supp_address		Varchar	(100),
	@supp_taxNumber     Varchar (100),
	@supp_city			Varchar (100),
    @supp_zip			Varchar (20),
	@supp_Phone1        Varchar (100),
	@supp_Phone2		Varchar (100),
	@country_id			int,
	@state_id			int
)
as
set nocount on

/*
declare @comp_id		int,
	@supp_name			Varchar (100),
	@supp_name1			Varchar (100),
	@supp_address		Varchar	(100),
	@supp_city			Varchar (100),
    @supp_zip			Varchar (20),
	@supp_taxNumber		varchar (100),
	@supp_Phone1        Varchar (100),
	@supp_Phone2		Varchar (100),
	@country_id			int,
	@state_id			int


select @comp_id			=1,
	@supp_name			='',
	@supp_name1			='',
	@supp_address		='',
	@supp_city			='',
    @supp_zip			='',
	@supp_taxNumber		='',
	@supp_Phone1        ='',
	@supp_Phone2		='',
	@country_id			=-1,
	@state_id			=-1
*/

Select		' ' [+],
			ts.supp_name,
			ts.supp_name1,
			ts.supp_address,
			ts.supp_taxNumber,
			ts.supp_city,
			ts.supp_zip,
			ts.supp_Phone1,
			ts.supp_Phone2,
			sc.country_desc,
			st.state_desc,
			ts.supp_id [ID]

From		tbSupplier					ts
			left join tbsysCountry		sc
			on sc.country_id			= ts.country_id

			left join tbsysState		st
			on st.state_id			    = ts.state_id



Where		ts.comp_id					= @comp_id
AND			isnull(ts.supp_name			,'')	like '%' +  @supp_name		+ '%'
AND			isnull(ts.supp_name1		,'')	like '%' +  @supp_name1		+ '%'
AND			isnull(ts.supp_address		,'')	like '%' +  @supp_address	+ '%'
AND			isnull(ts.supp_taxNumber	,'')	like '%' +  @supp_taxNumber + '%'
AND			isnull(ts.supp_city			,'')	like '%' +  @supp_city		+ '%'
AND			isnull(ts.supp_zip			,'')	like '%' +  @supp_zip		+ '%'
AND			isnull(ts.supp_Phone1		,'')	like '%' +  @supp_Phone1	+ '%'
AND			isnull(ts.supp_Phone2		,'')	like '%' +  @supp_Phone2	+ '%'
AND			(sc.country_id				= @country_id   OR  @country_id		= -1)
AND			(st.state_id				= @state_id     OR  @state_id		= -1)










GO

