CREATE PROCEDURE [dbo].[spSendEMailQueue_getPendingMail]
	@comp_id AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	DECLARE			@smtpJob_id AS INT = 0
	SELECT TOP 1	@comp_id	= tt.comp_id,
					@smtpJob_id = tt.smtpJob_id
		FROM tbsendEMailQueue tt	WITH (NOLOCK)
		--WHERE tt.comp_id = @comp_id    NOOOOOO    MOS   06-2020
	ORDER BY	tt.smtpJob_priority,
				tt.smtpJob_id

	SELECT seq.*,tc.smtp_maxQTYByHour4Queue
		FROM tbsendEMailQueue	AS seq	WITH (NOLOCK)
		INNER JOIN tbCompany	AS tc	WITH (NOLOCK)
			ON tc.comp_id		= seq.comp_id
		WHERE	seq.comp_id		= @comp_id AND
				seq.smtpJob_id	= @smtpJob_id

	DELETE FROM tbsendEMailQueue WITH (ROWLOCK)
		WHERE	comp_id		= @comp_id AND
				smtpJob_id	= @smtpJob_id


END
GO





