CREATE PROCEDURE [dbo].[spSendEMailQueue_InsertData]
(

	@comp_id					INT,
	@displayName				VARCHAR(1000),
	@replyTo					VARCHAR(1000),
	@sendTo						VARCHAR(4000),
	@sendToCC					VARCHAR(4000),
	@sendToCCO					VARCHAR(4000),
	@subject					VARCHAR(4000),
	@body						NTEXT,
	@user_id					INT,
	@attachment1_FileName		VARCHAR(1000),
	@attachment1_FileContent	IMAGE,
	@smtpJob_priority			INT

)
AS
SET NOCOUNT ON


BEGIN


		IF @user_id = -1 SET @user_id = NULL


		INSERT INTO tbsendEMailQueue
		(
			comp_id,
			-- smtpJob_id -- this column value is auto-generated
			[user_id],
			replyTo,
			sendTo,
			sendToCC,
			sendToCCO,
			[subject],
			body,
			displayName,
			attachment1_FileName,
			attachment1_FileContent,
			smtpJob_priority
		)
		VALUES
		(
			@comp_id,
			@user_id,
			@replyTo,
			@sendTo,
			@sendToCC,
			@sendToCCO,
			@subject,
			@body,
			@displayName,
			@attachment1_FileName,
			@attachment1_FileContent ,
			@smtpJob_priority
		)





END
GO





-- =================================================================================================================
-- Author		: GA
-- Update Date	: 03-12-2014
-- Description	: Grabar log desde el sistema
-- =================================================================================================================


CREATE PROCEDURE [dbo].[spSentEmailLog_InsertData]
(

	@comp_id				INT,
	@el_fromMail			VARCHAR(1000),
	@el_toMail				VARCHAR(4000),
	@el_toMailCC			VARCHAR(4000),
	@el_toMailCCO			VARCHAR(4000),
	@el_subject				VARCHAR(4000),
	@el_body				NTEXT,
	@el_cd					DATETIME,
	@user_id				INT,
	@el_fromSQLMAIL			BIT,
	@el_SMTPResponse		VARCHAR(4000)


)
AS
SET NOCOUNT ON


BEGIN


		IF @user_id = -1 SET @user_id = NULL


		-- MOS 06-2022 para q no crezca de gusto esta tabla
		IF DATALENGTH(@el_body) > 20000
			BEGIN
				SET @el_body = SUBSTRING(@el_body,0,19900) + ' . . .'
			END


		INSERT INTO tbsentEMailLog
		(
			comp_id,
			el_fromMail,
			el_toMail,
			el_toMailCC,
			el_toMailCCO,
			el_subject,
			el_body,
			el_cd,
			[user_id],
			el_fromSQLMAIL,
			el_SMTPResponse
		)
		VALUES
		(
			@comp_id,
			@el_fromMail,
			@el_toMail,
			@el_toMailCC,
			@el_toMailCCO,
			@el_subject,
			@el_body,
			@el_cd,
			@user_id,
			@el_fromSQLMAIL,
			@el_SMTPResponse
		)



END
GO






