CREATE PROCEDURE [dbo].[spSetupInitials_FunSetup]

(

	@comp_id										INT,
	@lang_id										INT,
	@bra_id											INT,
	@prof_id										INT,
	@user_id										INT,

	@bra_desc										nvarchar(200),
	@bra_MainDesc									nvarchar(200),
	@bra_address									nvarchar(100),
	@country_id										int,
	@state_id										int,
	@bra_phone										nvarchar(100),
	@curr_id										int,
	@bra_taxnumber									nvarchar(50),
	@fc_id											int,
	@useAccounting									bit,
	--@bra_logo										binary,

	@salesman										BIT,
	@cash											BIT,
	@administration									BIT,

	@bra_PriceDecimalPlace							int,
	@bra_costlist_type								bit,
	@bra_SaleOrderCommercialSuggests				bit,
	@bra_SaleOrderEnablePreparation					bit,
	@bra_SaleOrderFilterByUserId					bit,
	@bra_SaleOrderShowCustomerBalance				bit,
	@bra_SaleOrderBlockItemsWithNOPotentialStock	bit,
	@bra_SaleOrder_AllowCostInCero					bit,
	--aca va HABILITA SERIALIZACION DE PEDIDOS (???)
	@bra_SaleOrderItemSelectionBySize				bit,

	@factura										bit,
	@presupuesto									bit,
	@NdCred											BIT,
	@NdDeb											BIT,
	@remito											BIT,
	@remitoPend										BIT,
	@reciboManual									BIT,
	@reciboXSist									BIT,
	@saldoDeuda										BIT,
	@saldoCredito									BIT,
	@decimals										int,
	@RMA_sales										bit
)



as
set nocount on

-------------------------------------------------------------------
--  TESTING
--------------------------------------------------------------------
/*
	declare
		@comp_id		INT,
		@bra_id			INT,
		@lang_id		INT,
		@prof_id		INT,
		@user_id		INT,

	----------------------------------
	-- PARAMS BRANCH
	----------------------------------

		@bra_desc		nvarchar(200),
		@bra_MainDesc	nvarchar(200),
		@bra_address	nvarchar(100),
		@country_id		int,
		@state_id		int,
		@bra_phone		nvarchar(100),
		@curr_id		int,
		@bra_taxnumber	nvarchar(50),
		@fc_id			int,
		@useAccounting	bit, --si es FALSE, INSERTA NULL
		--@bra_logo		image
	----------------------------------

	----------------------------------
	-- PARAMS PROFILE
	----------------------------------

	@salesman			BIT,
	@cash				BIT,
	@administration		BIT,

	----------------------------------

	----------------------------------
	-- PARAMS SALES
	----------------------------------

	@bra_PriceDecimalPlace							int,
	@bra_costlist_typ								bit,
	@bra_SaleOrderCommercialSuggests				bit,
	@bra_SaleOrderEnablePreparation					bit,
	@bra_SaleOrderFilterByUserId					bit,
	@bra_SaleOrderShowCustomerBalance				bit,
	@bra_SaleOrderBlockItemsWithNOPotentialStock	bit,
	@bra_SaleOrder_AllowCostInCero					bit,
	--aca va HABILITA SERIALIZACION DE PEDIDOS (???)
	@bra_SaleOrderItemSelectionBySize				bit,

	----------------------------------

	----------------------------------
	-- PARAMS DOCUMENTS
	----------------------------------

		@factura		bit,
		@presupuesto	bit,
		@NdCred			BIT,
		@NdDeb			BIT,
		@remito			BIT,
		@remitoPend		BIT,
		@reciboManual	BIT,
		@reciboXSist	BIT,
		@saldoDeuda		BIT,
		@saldoCredito	BIT,
		@decimals		int

	----------------------------------


	select
		@comp_id	= 1,
		@bra_id		= 1,
		@lang_id	= 2,
		@prof_id	= 1,
		@user_id	= 1,

	----------------------------------
	-- PARAMS BRANCH
	----------------------------------

		@bra_desc		= 'Sucursal Prueba',
		@bra_MainDesc	= 'Sucursal Prueba Large Desc',
		@bra_address	= 'Sabadaba 123',
		@country_id		= 54,
		@state_id		= 2,
		@bra_phone		= '43569874',
		@curr_id		= 2,
		@bra_taxnumber	= '2365847',
		@fc_id			= 1,
		@useAccounting	= 'True', --si es FALSE, INSERTA NULL

	----------------------------------

	----------------------------------
	-- PARAMS PROFILE
	----------------------------------

		@salesman			= 'True',
		@cash				= 'True',
		@administration		= 'True',

	----------------------------------

	----------------------------------
	-- PARAMS SALES
	----------------------------------

		@bra_PriceDecimalPlace							= 2,
		@bra_costlist_type								= 'True',
		@bra_SaleOrderCommercialSuggests				= 'True',
		@bra_SaleOrderEnablePreparation					= 'True',
		@bra_SaleOrderFilterByUserId					= 'True',
		@bra_SaleOrderShowCustomerBalance				= 'True',
		@bra_SaleOrderBlockItemsWithNOPotentialStock	= 'True',
		@bra_SaleOrder_AllowCostInCero					= 'True',
		--aca va HABILITA SERIALIZACION DE PEDIDOS (???)
		@bra_SaleOrderItemSelectionBySize				= 'True'

	----------------------------------

	----------------------------------
	-- PARAMS DOCUMENTS
	----------------------------------

		@factura		= 'True',
		@presupuesto	= 'True',
		@NdCred			= 'True',
		@NdDeb			= 'True',
		@remito			= 'True',
		@remitoPend		= 'True',
		@reciboManual	= 'True',
		@reciboXSist	= 'True',
		@saldoDeuda		= 'True',
		@saldoCredito	= 'True',
		@decimals		= 2


	----------------------------------
*/
--------------------------------------------------------------------




--==Comienza el Stored Procedure
declare
	@enabledtoupdate	bit

select @enabledtoupdate = tb.bra_IsAvailable4InitialValues
  from tbBranch tb where tb.comp_id = @comp_id and tb.bra_id = @bra_id


if @enabledtoupdate = 'True'
BEGIN
--------------------------------------------------------------------
-- SUCURSAL
--------------------------------------------------------------------
--select @enabledtoupdate = tb.bra_IsAvailable4InitialValues
--  from tbBranch tb where tb.comp_id = @comp_id and tb.bra_id = @bra_id

		update tbBranch
		SET
			bra_desc						= @bra_desc,
			bra_MainDesc					= @bra_MainDesc,
			country_id						= @country_id,
			state_id						= @state_id,
			curr_id							= @curr_id,
			bra_address						= @bra_address,
			bra_taxNumber					= @bra_taxnumber,
			bra_phone						= @bra_phone,
			fc_id							= @fc_id,
			--ag_id = 1,
			--bra_logo						= @bra_logo,
			bra_IsAvailable4InitialValues	= 'False'

		where	comp_id = @comp_id
		and		bra_id	= @bra_id


		--==Ponemos en NULL en caso de que NO utilice CONTABILIDAD
--		if @useAccounting = 'False'
--			update tbBranch
--			set
--				ag_id = NULL
--			where	comp_id = @comp_id
--			and		bra_id	= @bra_id
--------------------------------------------------------------------

--------------------------------------------------------------------
--  PERFILES POR DEFECTO
--------------------------------------------------------------------

	if @salesman = 'False'
		update tbProfile
		SET
			prof_notInDDL = 'True'
		where prof_id = 15

	if @cash = 'False'
		update tbProfile
		SET
			prof_notInDDL = 'True'
		where prof_id = 16

	if @administration = 'False'
		update tbProfile
		SET
			prof_notInDDL = 'True'
		where prof_id = 17

--------------------------------------------------------------------

--------------------------------------------------------------------
--  VENTAS
--------------------------------------------------------------------

	update tbBranch
	SET
		bra_PriceDecimalPlaces						= @bra_PriceDecimalPlace,
		bra_costlist_type							= @bra_costlist_type,
		--aca va INFORMAR EQUIVALENTE EN USD (????)
		bra_SaleOrderCommercialSuggests				= @bra_SaleOrderCommercialSuggests,
		bra_SaleOrderEnablePreparation				= @bra_SaleOrderEnablePreparation,
		bra_SaleOrderFilterByUserId					= @bra_SaleOrderFilterByUserId,
		bra_SaleOrderShowCustomerBalance			= @bra_SaleOrderShowCustomerBalance,
		bra_SaleOrderBlockItemsWithNOPotentialStock = @bra_SaleOrderBlockItemsWithNOPotentialStock,
		bra_SaleOrder_AllowCostInCero				= @bra_SaleOrder_AllowCostInCero,
		--aca va HABILITA SERIALIZACION DE PEDIDOS (???)
		bra_SaleOrderItemSelectionBySize			= @bra_SaleOrderItemSelectionBySize


	where	comp_id		= @comp_id
	and		bra_id		= @bra_id

--------------------------------------------------------------------

--------------------------------------------------------------------
--  COMPROBANTES
--------------------------------------------------------------------

	update tbDocumentsFile
	SET
			df_Disabled = @factura,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 1

	update tbDocumentsFile
	SET
			df_Disabled = @presupuesto,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 5

	update tbDocumentsFile
	SET
			df_Disabled = @NdCred,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 3

	update tbDocumentsFile
	SET
			df_Disabled = @NdDeb,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 4

	update tbDocumentsFile
	SET
			df_Disabled = @remito,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 2

	--ACA COMO PONGO EL TEMA DEL OTRO REMITO PEND DE FACTURACION????


	update tbDocumentsFile
	SET
			df_Disabled = @reciboManual,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 13

	update tbDocumentsFile
	SET
			df_Disabled = @reciboXSist,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 6

	update tbDocumentsFile
	SET
			df_Disabled = @remito,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @saldoDeuda
	and		bra_id		= @bra_id
	and		df_id		= 21

	update tbDocumentsFile
	SET
			df_Disabled = @saldoCredito,
			df_UnitPriceDecimalPlaces = @decimals
	where	comp_id		= @comp_id
	and		bra_id		= @bra_id
	and		df_id		= 23

--------------------------------------------------------------------

--------------------------------------------------------------------
--  RMA SALES
--------------------------------------------------------------------
	update tbBranch
	SET
    bra_SaleOrderShowSO_RMA_Pendings = @RMA_sales
	where	comp_id	= @comp_id
	and		bra_id	= @bra_id
--------------------------------------------------------------------

END












GO






-- ====================================================================================
-- Author:		GA.
-- Create date: 04/01/2013.
-- Description:	Página " setup inicial de sucursal" - precargar segun la sucursal
-- ====================================================================================



create PROCEDURE [dbo].[spSetupInitials_getDataById]

(

	@comp_id										INT,
	@lang_id										INT,
	@bra_id											INT,
	@prof_id										INT,
	@user_id										INT


)


AS




set nocount on

-------------------------------------------------------------------
--  TESTING
--------------------------------------------------------------------
/*

	declare
		@comp_id		INT,
		@bra_id			INT,
		@lang_id		INT,
		@prof_id		INT,
		@user_id		INT


	select
		@comp_id	= 1,
		@bra_id		= 1,
		@lang_id	= 2,
		@prof_id	= 1,
		@user_id	= 1


*/
--------------------------------------------------------------------
BEGIN




		select  tb.bra_desc,
				tb.bra_MainDesc,
				tb.bra_address,
				tb.country_id,
				tb.state_id,
				tb.bra_phone,
				tb.curr_id,
				tb.bra_taxNumber,
				tb.fc_id,
				''[@useAccounting],
				''[@salesman],
				''[@cash] ,
				''[@administration],
				tb.bra_PriceDecimalPlaces,
				tb.bra_costlist_type,
				tb.bra_SaleOrderCommercialSuggests,
				tb.bra_SaleOrderEnablePreparation,
				tb.bra_SaleOrderFilterByUserId,
				tb.bra_SaleOrderShowCustomerBalance,
				tb.bra_SaleOrderBlockItemsWithNOPotentialStock,
				tb.bra_SaleOrder_AllowCostInCero,
				tb.bra_SaleOrderItemSelectionBySize,
				''[@factura],
				''[@presupuesto],
				''[@NdCred] ,
				''[@NdDeb],
				''[@remito],
				''[@remitoPend],
				''[@reciboManual],
				''[@reciboXSist] ,
				''[@saldoDeuda],
				''[@saldoCredito] ,
				''[@decimals],
				tb.bra_SaleOrderShowSO_RMA_Pendings

		from tbBranch tb


		left join dbo.[tbDocumentsFile]		tdf
		on	tdf.[comp_id]		=	tb.[comp_id]
		and	tdf.[bra_id]		=	tb.[bra_id]
		and	tdf.[df_id]			=	tb.[df_id]


		where	tb.comp_id  = @comp_id
		and		tb.bra_id	= @bra_id







END












GO





