CREATE PROCEDURE [dbo].[spStockAdjustment_ForcedUpdate]
(
	@comp_id	INT,
	@user_id	INT,
	@prof_id	INT,
	@item_id	INT,
	@stor_id	INT,
	@qty		INT,
	@chk		BIT,
	@desc		VARCHAR(200),
	@bra_id		INT
)
AS

BEGIN

	SET NOCOUNT ON

	DECLARE @intStorePrevious AS INT
	SET		@intStorePrevious = 0


	-- Verifica si el deposito tiene cantidad asignada
	IF NOT EXISTS(
					SELECT TOP 1  1
						FROM tbItemStorage tis		WITH (NOLOCK)
						WHERE	comp_id = @comp_id AND
								stor_id = @stor_id AND
								item_id = @item_id
					)
		BEGIN
			INSERT INTO tbItemStorage
			(
				comp_id,
				stor_id,
				item_id,
				itst_cant,
				itst_cd,
				itst_PickingLocation,
				itst_StorageLocation,
				itst_updateByInTransitStock
			)
			VALUES
			(
				@comp_id,
				@stor_id,
				@item_id,
				0,
				GETDATE(),
				'',
				'',
				'False'
			)
		END


	-- Actualiza Stock Previo
	SELECT @intStorePrevious = tis.itst_cant
		FROM tbItemStorage tis
		WHERE	tis.comp_id = @comp_id AND
				tis.stor_id = @stor_id AND
				tis.item_id = @item_id




	-- Actualiza el Deposito
	UPDATE tbItemStorage
		SET
			itst_cant	= itst_cant + @qty
		WHERE	comp_id = @comp_id AND
				stor_id = @stor_id AND
				item_id = @item_id


	-- Saca que cantidad le queda ahora con el nuevo stock
	DECLARE @intActualQty AS DECIMAL(19,6)
	SELECT  @intActualQty = SUM(tis.itst_cant)
		FROM tbItemStorage tis
		WHERE	tis.comp_id = @comp_id AND
				--tis.stor_id = @stor_id AND
				tis.item_id = @item_id


	-- -------------------------------------------------------
	-- Verificacion de DESPACHOS DISPONIBLES
	-- -------------------------------------------------------
	DECLARE @intDespachosDisponibles AS INT
	SELECT  @intDespachosDisponibles = IsNull(SUM(tid.impData_ActualQty),0)
		FROM tbImportData tid
		WHERE	tid.comp_id = @comp_id AND
				tid.item_id = @item_id AND
				tid.impData_ActualQty > 0

	IF @intDespachosDisponibles < @intActualQty
		BEGIN

			DECLARE @intImpDataId	AS INT
			DECLARE @intImpDataQty	AS DECIMAL(19,4)
			SELECT	TOP 1
					@intImpDataId	= tid.impData_id,
					@intImpDataQty	= tid.impData_ActualQty
				FROM		tbImportData tid
				WHERE		tid.comp_id = @comp_id		AND
							tid.item_id = @item_id
				ORDER BY	tid.impData_ActualQty,
							tid.impData_Number_local	DESC


			IF @intImpDataId IS NOT NULL
				BEGIN

					UPDATE tbImportData
						SET
							impData_InitialQty		= 0,
							impData_ActualQty		= 0
						WHERE	comp_id				= @comp_id		AND
								impData_id			= @intImpDataId	AND
								impData_ActualQty	< 0


					UPDATE tbImportData
						SET
							impData_InitialQty	= impData_InitialQty +  ((@intActualQty - @intDespachosDisponibles) /*- @intImpDataQty*/) ,
							impData_ActualQty	= impData_ActualQty  +  ((@intActualQty - @intDespachosDisponibles) /*- @intImpDataQty*/)
						WHERE	comp_id			= @comp_id AND
								impData_id		= @intImpDataId

				END
		END
	-- -------------------------------------------------------


	-- -------------------------------------------------------
	-- Seriales
	-- -------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1  1
					FROM	tbItem ti		WITH (NOLOCK)
					WHERE	ti.comp_id = @comp_id AND
							ti.item_id = @item_id AND
							ti.item_expser = 'True'
			  )
		BEGIN
			DECLARE @intSerialAvailable AS INT
			SELECT  @intSerialAvailable = COUNT(*)
				FROM tbItemSerials tis		WITH (NOLOCK)
				WHERE	tis.comp_id			= @comp_id	AND
						tis.item_id			= @item_id	AND
					   (   tis.is_available	= 'True'    OR
					      (tis.is_available = 'False'   AND IsNull(tis.is_serial,'') = '')
					    )
			-- -------------------------------------------------------
			IF @intSerialAvailable < @intActualQty
				BEGIN
					DECLARE @intISId AS INT
					SELECT TOP 1 @intISId = tis.is_id
						FROM     tbItemSerials			tis		WITH (NOLOCK)
						WHERE	 tis.comp_id = @comp_id AND
								 tis.item_id = @item_id
						ORDER BY tis.is_id DESC

						IF @intISId IS NOT NULL
							BEGIN

								DECLARE @intCounter AS INT
								SET @intCounter = 0
								WHILE @intCounter < (@intActualQty - @intSerialAvailable)
									BEGIN
										INSERT INTO tbItemSerials
										(
											comp_id,
											bra_id,
											ct_transaction,
											it_transaction,
											item_id,
											is_serial,
											is_cd,
											is_available,
											stor_id,
											is_guid,
											is_IsOwnGeneration,
											is_checked,
											is_printed
										)

										SELECT	tis.comp_id,
												tis.bra_id,
												tis.ct_transaction,
												tis.it_transaction,
												tis.item_id,
												'',
												GETDATE(),
												'False',
												tis.stor_id,
												tis.is_guid,
												'False',
												'False',
												'False'
											FROM tbItemSerials tis		WITH (NOLOCK)
											WHERE	tis.comp_id = @comp_id AND
													tis.is_id	= @intISId

										SET @intCounter = @intCounter + 1
									END
							END
				END
		END









	-- -----------------------------------------------------
	-- Logueamos en la tbItemStorageAdjustment
	-- -----------------------------------------------------

		--COMENTE EL IA_STOREPREVIOUS PORQUE NO SE DE DONDE
		--SACAR EL STORAGE ANTERIOR, ASUMO QUE VIENE DE TU
		--PARTE, EL BRA_ID LO DEJE AHI PARA QUE NO DE
		-- UN ERROR EL SP. STL

	INSERT INTO tbItemStorageAdjustment
	(
		comp_id,
		-- ia_id -- this column value is auto-generated,
		bra_id,
		stor_id,
		item_id,
		[user_id],
		ia_cd,
		ia_desc,
		ia_storePrevious,
		ia_Qty
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@stor_id,
		@item_id,
		@user_id,
		GETDATE(),
		@desc,
		@intStorePrevious,
		@qty
	)
	-- -----------------------------------------------------

END
GO



