CREATE PROCEDURE [dbo].[spStockControlOrder_Header_GetDataByFilters]
(
	@comp_id					INT,
	@istkcg_id					INT,
	@isClosed					INT,
	@isControlled				INT,
	@isProcessed				INT,
	@user_id					INT,
	@SheetName					NVARCHAR(300),
	@StockCalculationDateFrom	DATETIME,
	@StockCalculationDateTo		DATETIME
)
AS

	SET NOCOUNT ON

		BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

			-- -----------------------------------------------
			-- Testing
			-- -----------------------------------------------
			/*
				DECLARE
					@comp_id					INT,
					@istkcg_id					INT,
					@isClosed					INT,
					@isControlled				INT,
					@isProcessed				INT,
					@user_id					INT,
					@SheetName					NVARCHAR(300),
					--@item_id					INT,
					@StockCalculationDateFrom	DATETIME,
					@StockCalculationDateTo		DATETIME
				SELECT
					@comp_id				=  1,
					@istkcg_id				= -1,
					@isClosed				= -1,
					@isControlled			= -1,
					@isProcessed			= -1,
					@user_id				=  1
			*/
			-- -----------------------------------------------


		SET @StockCalculationDateFrom = dbo.fnGetEnd_or_BeginOfDate(@StockCalculationDateFrom,'False')
		SET @StockCalculationDateTo   = dbo.fnGetEnd_or_BeginOfDate(@StockCalculationDateTo,'True')


			SELECT
				ISNULL(tscoh.itstkpl_isClosed		,'False')	[ ],
				ISNULL(tscoh.itstkpl_isControlled	,'False')	[ ],
				ISNULL(tscoh.itstkpl_isProcessed	,'False')	[ ],
				CASE
					WHEN	tscos.itstkpl_id IS NULL THEN CONVERT(BIT,'False')
					ELSE	CONVERT(BIT,'True')
				END																	[Selected],	-- (5)
				-- ATENCION !!!!!!!!!!!!!!!!!!!!!!!!!!!!!
				-- no poner nada antes de esto !!!!




				tscoh.itstkpl_desc,
				tscg.istkcg_desc,
				ts.stor_desc,
				ISNULL(tscoh.itstkpl_useSavedStock,'False')							[itstkpl_useSavedStock],
				tscoh.itstkpl_useSavedStockDate										[itstkpl_useSavedStockDate],





				-- ATENCION !!!!!!!!!!!!!!!!!!!!!!!!!!!!!
				-- No agregar nada despues de este canmpo
				tscoh.itstkpl_isClosed,																-- count - 7
				tscoh.itstkpl_isControlled,															-- count - 6
				tscoh.itstkpl_isProcessed,															-- count - 5
				tscoh.itstkpl_note,																	-- count - 4
				ISNULL(tu2.user_lastname + ' , ' + tu2.user_firstname,'')			[user_nick],	-- count - 3				--INDICA QUIEN LO TIENE TOMADO
				ISNULL(tu2.[user_id],'0')											[user_id],		-- count - 2
				tscoh.itstkpl_id													[ID]			-- count - 1

			FROM tbStockControlOrders_Header			tscoh

--				INNER JOIN tbUser						tu
--				ON tu.[user_id]		= tscoh.[user_id]

				INNER JOIN tbBranch						tb
				ON	tb.comp_id		= tscoh.comp_id		AND
					tb.bra_id		= tscoh.bra_id

				INNER JOIN tbStockControlGroups			tscg
				ON	tscg.comp_id	= tscoh.comp_id		AND
					tscg.istkcg_id	= tscoh.istkcg_id

				INNER JOIN tbStorage					ts
				ON	ts.comp_id		= tscoh.comp_id		AND
					ts.stor_id		= tscoh.stor_id

				LEFT JOIN tbStockControlOrders_Selection	tscos
				ON	tscos.comp_id		= tscoh.comp_id	    AND
					tscos.itstkpl_id	= tscoh.itstkpl_id	--AND
					--tscos.[user_id]		= @user_id

				LEFT JOIN tbUser							tu2
				on	tu2.[user_id]		= tscos.[user_id]

			WHERE	tscoh.comp_id	= @comp_id															AND
					(@istkcg_id		= -1 OR tscoh.istkcg_id				= @istkcg_id)					AND
					(@isClosed		= -1 OR tscoh.itstkpl_isClosed		= @isClosed)					AND
					(@isControlled	= -1 OR tscoh.itstkpl_isControlled	= @isControlled)				AND
					(@isProcessed	= -1 OR tscoh.itstkpl_isProcessed	= @isProcessed)					AND
					(@SheetName		= '' OR tscoh.itstkpl_desc LIKE '%' + @SheetName + '%')				AND
					(
						CASE
							WHEN tscoh.itstkpl_useSavedStock = 'True'THEN tscoh.itstkpl_useSavedStockDate
							ELSE tscoh.itstkpl_cd
						END
						 BETWEEN @StockCalculationDateFrom AND @StockCalculationDateTo
					)

			ORDER BY tscos.os_order

		END
GO


CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_CheckOrUncheckItems]
(
	@guid			UNIQUEIDENTIFIER,
	@item_id		INT,
	@Type			INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------
		-- TESTING
		-- --------------------------------------------
		/*
			DECLARE
				@guid		UNIQUEIDENTIFIER,
				@item_id	INT,
				@Type		INT
			SELECT
				@guid		= 'e73882f6-0d1e-4530-98a6-35e09183dddd',
				@item_id	= 492,
				@Type		= 2
		*/
		-- --------------------------------------------


		IF EXISTS (SELECT 1 FROM tbTemporarySelection tts WHERE tts.tmpGUID = @guid AND tts.tmpID = @item_id AND tts.tmpType = 2)
			BEGIN
				DELETE FROM tbTemporarySelection
				WHERE	tmpGUID = @guid			AND
						tmpID	= @item_id		AND
						tmpType = 2
			END
		ELSE
			BEGIN
				INSERT INTO tbTemporarySelection
				(
					tmpGUID,
					tmpID,
					tmpType,
					tmpCD
				)
				VALUES
				(
					@guid,
					@item_id,
					@Type,
					GETDATE()
				)
			END

	END


GO




CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_CloseAllItems]
(
	@comp_id	INT,
	@lang_id	INT,
	@itstkpl_id	INT,
	@user_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN

			-- --------------------------------------------------
			-- Testing
			-- --------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@lang_id	INT,
					@itstkpl_id	INT,
					@user_id	INT

				SELECT
					@comp_id	= 1,
					@lang_id	= 2,
					@itstkpl_id	= 144,
					@user_id	= 119
			*/
			-- --------------------------------------------------


			UPDATE tbStockControlOrders_Detail
				SET
					itstkpld_isClosed		= 'True',
					user_id_isClosed		= @user_id,
					itstkpld_isClosedCD		= GETDATE(),
					itstkpld_isInRecount	= 'False'

				WHERE	comp_id			= @comp_id		AND
						itstkpl_id		= @itstkpl_id




			--MANDAMOS MAIL AL MANAGER DEL GRUPO


			--OBTENEMOS EL MAIL DEL MANAGER DEL GRUPO DE LA HOJA DE LA
			--QUE SE CERRARON TODOS LOS ITEMS
			DECLARE @ManagerMail	VARCHAR(200)
			SET		@ManagerMail = ''

			SELECT
				@ManagerMail = tscg.istkcg_managerMail
				FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
					INNER JOIN tbStockControlGroups				tscg	WITH(NOLOCK)
					ON	tscg.comp_id		= tscoh.comp_id		AND
						tscg.istkcg_id		= tscoh.istkcg_id
				WHERE	tscoh.comp_id		= @comp_id			AND
						tscoh.itstkpl_id	= @itstkpl_id		AND
						tscg.istkcg_managerMail_enabled4Mail = 'True'


			--OBTENEMOS LOS DATOS DEL USUARIO QUE LA CERRO
			DECLARE @user_name	VARCHAR(200)
			SELECT
				@user_name = tu.user_lastname + ',' + tu.user_firstname
				FROM tbUser										tu		WITH(NOLOCK)
				WHERE	tu.[user_id]		= @user_id


			--OBTENEMOS EL NOMBRE DE LA HOJA QUE SE CERRÓ
			DECLARE @SheetName	VARCHAR(200)

			SELECT
				@SheetName = tscoh.itstkpl_desc
				FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
				WHERE	tscoh.comp_id		= @comp_id			AND
						tscoh.itstkpl_id	= @itstkpl_id


			--ENVIAMOS EL MAIL CON LA INFORMACIÓN
			DECLARE
				@subject	VARCHAR(200),
				@MailBody	VARCHAR(500),
				@str1		VARCHAR(100),
				@str2		VARCHAR(100),
				@str3		VARCHAR(100)


				SELECT
					@subject = tut.utexts_desc
				FROM tbsysUniqueTexts tut	WITH(NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30544


				SELECT
					@str1 = tut.utexts_desc
				FROM tbsysUniqueTexts tut	WITH(NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30544

				SELECT
					@str2 = tut.utexts_desc
				FROM tbsysUniqueTexts tut	WITH(NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30545

				SELECT
					@str3 = tut.utexts_desc
				FROM tbsysUniqueTexts tut	WITH(NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30546


				SET @MailBody = @str1 + ' ' + '"' + @SheetName + '"' + ' ' + @str2 + ' ' + @user_name + ' ' + @str3 + ' ' + CONVERT(VARCHAR,GETDATE())



			exec spSystem_sendEMail
						@compId				= @comp_id,
						@precipients		= @ManagerMail,
						@pcopy_recipients	= '',
						@psubject			= @subject,
						@pbody_format		= 'HTML',
						@pbody				= @MailBody,
						@pfile_attachments	= NULL,
						@pReplyTo			= NULL,
						@pblind_copy_recipients='',
						@pUser_Id			= @user_id



		END

GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_GetCountedTotals]
(
		@comp_id	INT,
		@itstkpl_id	INT,
		@status		INT
)
AS

	SET NOCOUNT ON


		BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

			-- -----------------------------------------------------------------
			-- Testing
			-- -----------------------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@itstkpl_id	INT,
					@status		INT
				SELECT
					@comp_id	= 1,
					@itstkpl_id = 175,
					@status		= 2
			*/
			-- -----------------------------------------------------------------


			SELECT
				ISNULL(SUM(tscod.itstkpld_qtyCounted),0)	[itstkpld_qtyCountedTotal]

			FROM tbStockControlOrders_Detail				tscod

				INNER JOIN tbItem							ti
				ON	ti.comp_id			= tscod.comp_id		AND
					ti.item_id			= tscod.item_id

				INNER JOIN tbStockControlOrders_Header		tscoh
				ON	tscoh.comp_id		= tscod.comp_id		AND
					tscoh.itstkpl_id	= tscod.itstkpl_id

				LEFT JOIN tbUser							tu
				ON tu.[user_id]			= tscod.user_id_isClosed

			WHERE	tscod.comp_id		= @comp_id			AND
					tscod.itstkpl_id	= @itstkpl_id		AND
					--tscoh.itstkpl_id	= @itstkpl_id		AND
					(
						(@status		= 1	AND tscod.itstkpld_isClosed = 'False')	OR	--NO CERRADOS
						(@status		= 2)														OR  --TODOS
						(@status		= 3)														OR	--RECONTEO ?????
						(@status		= 4	AND tscod.itstkpld_isClosed = 'True')
					)
		END

GO




