CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_GetData4StorageUpdate]
(
	@comp_id	INT,
	@user_id	INT,
	@item_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN
			-- ------------------------------------------------------------
			-- TESTING
			-- ------------------------------------------------------------
			/*
			DECLARE
				@comp_id	INT,
				@guid		UNIQUEIDENTIFIER,
				@item_id	INT

			SELECT
				@comp_id	= 1,
				@guid		= '4D17C843-B411-48C7-973B-BA6B15B72FA2',
				@item_id	= 256
			*/
			-- ------------------------------------------------------------


			SELECT
				ts.stor_id,
				ts.stor_desc,
				SUM(ISNULL(tscod.itstkpld_qtyCounted,0))	[Qty],
				ISNULL(tscod.itstkpld_noteOfController,'')	[itstkpld_noteOfController],
				ISNULL(tscod.itstkpld_noteOfManager,'')		[itstkpld_noteOfManager],
				ti.item_code,
				ti.item_desc

			FROM tbItem										ti		WITH(NOLOCK)

				INNER JOIN tbStockControlOrders_Detail		tscod	WITH(NOLOCK)
				ON	tscod.comp_id		= ti.comp_id		AND
					tscod.item_id		= ti.item_id

				INNER JOIN tbStockControlOrders_Header		tscoh	WITH(NOLOCK)
				ON	tscoh.comp_id		= tscod.comp_id		AND
					tscoh.itstkpl_id	= tscod.itstkpl_id

				INNER JOIN tbStockControlOrders_Selection	tscos	WITH(NOLOCK)
				ON	tscos.comp_id		= tscoh.comp_id		AND
					tscos.itstkpl_id	= tscoh.itstkpl_id	AND
					tscos.[user_id]		= @user_id

				INNER JOIN tbStorage						ts		WITH(NOLOCK)
				ON	ts.comp_id			= tscoh.comp_id		AND
					ts.stor_id			= tscoh.stor_id

			WHERE	ti.comp_id			= @comp_id			AND
					tscos.[user_id]		= @user_id			AND
					ti.item_id			= @item_id

			GROUP BY tscos.os_order,ts.stor_id,ts.stor_desc, tscod.itstkpld_noteOfController, tscod.itstkpld_noteOfManager, ti.item_code, ti.item_desc
			ORDER BY tscos.os_order

		END


GO




CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_GetDataByFilters]
(
		@comp_id	INT,
		@itstkpl_id	INT,
		@status		INT
)
AS

	SET NOCOUNT ON



		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		BEGIN

			-- -----------------------------------------------------------------
			-- Testing
			-- -----------------------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@itstkpl_id	INT,
					@status		INT
				SELECT
					@comp_id	= 1,
					@itstkpl_id = 144,
					@status		= 2
			*/
			-- -----------------------------------------------------------------


			SELECT
				ISNULL(tscod.itstkpld_isClosed,'False')		[ ],				--SI ESTA CERRADO EL DETAIL
				ISNULL(tscoh.itstkpl_isClosed,'False')		[ ],				--SI ESTA CERRADO EL HEADER
				ISNULL(tscoh.itstkpl_isControlled,'False')	[ ],				--SI ESTA CONTROLADO EL HEADER
				ti.item_code,
				ti.item_desc,
				--ISNULL(tscod.itstkpld_qtyAtGeneration,0)	[itstkpld_qtyAtGeneration],
				ISNULL(tscod.itstkpld_qtyCounted,0)			[itstkpld_qtyCounted],
				--ISNULL(tscod.itstkpld_countNumber,0)		[itstkpld_countNumber],
				ISNULL(tu.user_nick,'')						[user_nick],
				ISNULL(tscod.itstkpld_isClosed,'False')		[itstkpld_isClosed],
				tscod.itstkpld_lastStockCountAt				[itstkpld_lastStockCountAt],
				CONVERT(VARCHAR,tscod.comp_id)				+ '|' +
				CONVERT(VARCHAR,tscod.itstkpl_id)			+ '|' +
				CONVERT(VARCHAR,tscod.itstkpld_id)			[ID]


			FROM tbStockControlOrders_Detail				tscod

				INNER JOIN tbItem							ti
				ON	ti.comp_id			= tscod.comp_id		AND
					ti.item_id			= tscod.item_id

				INNER JOIN tbStockControlOrders_Header		tscoh
				ON	tscoh.comp_id		= tscod.comp_id		AND
					tscoh.itstkpl_id	= tscod.itstkpl_id

				LEFT JOIN tbUser							tu
				ON tu.[user_id]			= tscod.user_id_isClosed

			WHERE	tscod.comp_id		= @comp_id			AND
					tscoh.itstkpl_id	= @itstkpl_id		AND
					(
						(@status		= 1	AND ISNULL(tscod.itstkpld_isClosed,'False') = 'False')	OR	--NO CERRADOS
						(@status		= 2)														OR  --TODOS
						(@status		= 3)														OR	--RECONTEO ?????
						(@status		= 4	AND ISNULL(tscod.itstkpld_isClosed,'False') = 'True')
					)


		END


GO


CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_GetDataByGuid4Grid]
(
	@comp_id	INT,
	@user_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@Checked	INT,
	@item_idP	INT,
	@bra_id		INT
)
AS



BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	-- ATENCION!!!!!
	-- NO AGREGAR COLMNAS AL SELECT FINAL!!!!!!!!!!!!!!!!!!!!!!!!!

	-- ------------------------------------------------------------
	-- TESTING
	-- ------------------------------------------------------------
	/*
		DECLARE
			@comp_id	INT,
			@user_id	INT,
			@item_idP	INT,
			@guid		UNIQUEIDENTIFIER,
			@Checked	INT

		SELECT
			@comp_id	= 1,
			@user_id	= 1,
			@item_idP	= -1,
			@guid		= 'e73882f6-0d1e-4530-98a6-35e09183dddd',
			@Checked	= -1

		--DROP TABLE #tmpStorageData
	*/
	-- ------------------------------------------------------------


	SET NOCOUNT ON

	-- Cantidad de decimales para trabajar.
	-- Cuando se requiera ponerlos configurables en Sucursal
	DECLARE @bitWorkWithDecimals AS BIT
	--SET		@bitWorkWithDecimals = 'False'
	--#09082018STL
	SELECT
		@bitWorkWithDecimals  = ISNULL(tb.bra_StockControlWithDecimals,'False')
	FROM tbBranch					tb
	WHERE	tb.comp_id	= @comp_id	AND
			tb.bra_id	= @bra_id

	DECLARE @intPadZeroes AS INT
	SET		@intPadZeroes = 7

	-- -------------------------------------------------------------------
	-- CREAMOS LA TABLA EN DONDE SE VAN A GUARDAR LOS DATOS
	-- AL INICIO SOLO CARGAMOS LOS CAMPOS QUE POR DEFECTO SABEMOS
	-- QUE VAMOS A TENER
	-- -------------------------------------------------------------------
		--DROP TABLE #tmpStorageData
		CREATE TABLE #tmpStorageData
		(
			Item_Id		INT,
			Item_Code	VARCHAR(50),
			Item_Desc	VARCHAR(200)
		)
		CREATE NONCLUSTERED INDEX #tmpStorageData ON dbo.#tmpStorageData(Item_Id) INCLUDE(Item_Desc)
	-- -------------------------------------------------------------------


	-- -------------------------------------------------------------------
	-- Variables para el Cursor
	-- -------------------------------------------------------------------
		DECLARE
			@stor_id					INT,
			@stor_desc					VARCHAR(200),
			@order						INT
	-- -------------------------------------------------------------------

												  -- MOS NUEBVO 12-2-15
		DECLARE Cursor_ModTMPTable4Columns CURSOR LOCAL FAST_FORWARD FOR

			SELECT
				DISTINCT
				ts.stor_id,
				ts.stor_desc,
				tscos.os_order
			FROM tbStorage									ts		WITH(NOLOCK)
				INNER JOIN tbStockControlOrders_Header		tscoh	WITH(NOLOCK)
				ON	tscoh.comp_id = ts.comp_id AND
					tscoh.stor_id = ts.stor_id
				INNER JOIN tbStockControlOrders_Selection	tscos	WITH(NOLOCK)
				ON	tscos.comp_id = tscoh.comp_id AND
					tscos.itstkpl_id = tscoh.itstkpl_id	AND
					tscos.[user_id]  = @user_id
			WHERE ts.comp_id = @comp_id
			ORDER BY tscos.os_order



		OPEN Cursor_ModTMPTable4Columns

		FETCH NEXT FROM Cursor_ModTMPTable4Columns

		INTO
			@stor_id,
			@stor_desc,
			@order

		WHILE @@FETCH_STATUS = 0
			BEGIN

				DECLARE @ColName	NVARCHAR(100)
				DECLARE @TableMod	VARCHAR(500)
				--SET @TableMod = 'ALTER TABLE #tmpStorageData ADD [' + '(' + CONVERT(VARCHAR,@stor_id) + ') ' + CAST(@ColName AS NVARCHAR(100)) +   '] NVARCHAR(100) DEFAULT ' + '''' + '0.0000  | 0.0000' + ''''
				SET @ColName = @stor_desc
																																			--**ACATAMBIEN
				SET @TableMod = 'ALTER TABLE #tmpStorageData ADD ['+ CAST(@ColName AS NVARCHAR(2000)) +   '] NVARCHAR(2000) DEFAULT ' + '''' + '0000000 | 0000000 | 0000000 ' + ''''

				EXEC (@TableMod)

				FETCH NEXT FROM Cursor_ModTMPTable4Columns
				INTO
					@stor_id,
					@stor_desc,
					@order
			END

		CLOSE Cursor_ModTMPTable4Columns
		DEALLOCATE Cursor_ModTMPTable4Columns


		-- AGREGO LAS ULTIMAS 3 COLUMNAS QUE MUESTRAN
		-- 1º TOTAL CONTADO
		-- 2º TOTAL FISICO
		-- 3º DIFERENCIA ENTRE AMBOS VALORES (CONTADO - FISICO)

		IF @bitWorkWithDecimals = 'true'
			BEGIN
				EXEC ('ALTER TABLE #tmpStorageData ADD [Total_Físico]	DECIMAL(19,4) NULL')
				EXEC ('ALTER TABLE #tmpStorageData ADD [Total_Contado]	DECIMAL(19,4) NULL')
				EXEC ('ALTER TABLE #tmpStorageData ADD [Diferencias]	DECIMAL(19,4) NULL')
				EXEC ('ALTER TABLE #tmpStorageData ADD [QtyAjuste]		DECIMAL(19,4) NULL')
			END
		ELSE
			BEGIN
				EXEC ('ALTER TABLE #tmpStorageData ADD [Total_Físico]	DECIMAL(19,0) NULL')
				EXEC ('ALTER TABLE #tmpStorageData ADD [Total_Contado]	DECIMAL(19,0) NULL')
				EXEC ('ALTER TABLE #tmpStorageData ADD [Diferencias]	DECIMAL(19,0) NULL')
				EXEC ('ALTER TABLE #tmpStorageData ADD [QtyAjuste]		DECIMAL(19,0) NULL')
			END


	-- PROCEDO A INSERTAR LA INFORMACIÓN ORDENADA
	-- SELECT * FROM #tmpStorageData
	-- PRESTAR ATENCION A LA CANTIDAD CONTADA CORREGIR CON MOS
	-- URGENTE

		INSERT INTO #tmpStorageData
		(
			Item_Id,
			Item_Code,
			Item_Desc,
			[Total_Físico],
			[Total_Contado],
			[Diferencias],
			[QtyAjuste]
		)
		SELECT
			DISTINCT
			ti.item_id,
			ti.item_code,
			ti.item_desc,
			SUM(ISNULL(tscod.itstkpld_qtyAtGeneration,0))	[Total],
			SUM(ISNULL(tscod.itstkpld_qtyCounted,0))		[Contado],
			SUM(ABS(ISNULL(tscod.itstkpld_qtyCounted,0) - ISNULL(tscod.itstkpld_qtyAtGeneration,0))),
			SUM(ISNULL(tscod.itstkpld_qty4Adjust,0))		[itstkpld_qty4Adjust]
			FROM tbStockControlOrders_Detail					tscod	WITH(NOLOCK)
				INNER JOIN tbItem								ti		WITH(NOLOCK)
				ON	ti.comp_id			= tscod.comp_id			AND
					ti.item_id			= tscod.item_id
				INNER JOIN tbStockControlOrders_Header			tscoh	WITH(NOLOCK)
				ON	tscoh.comp_id		= tscod.comp_id			AND
					tscoh.itstkpl_id	= tscod.itstkpl_id
				INNER JOIN tbStockControlOrders_Selection		tscos	WITH(NOLOCK)
				ON	tscos.comp_id		= tscod.comp_id			AND
					tscos.itstkpl_id	= tscoh.itstkpl_id		AND
					tscos.[user_id]		= @user_id


			GROUP BY ti.item_id, ti.item_code, ti.item_desc--, tscod.itstkpld_qty4Adjust

		--SELECT * FROM #tmpStorageData
	-- ----------------------------------------------------------------------------------
	-- CURSOR DONDE VAMOS A CARGAR LOS VALORES DE LOS RESULTADOS POR DEPOSITO PARA
	-- CADA ARTICULO
	-- ----------------------------------------------------------------------------------

	-- ------------------------------------------------
	-- Variables para el Cursor
	-- ------------------------------------------------
		DECLARE
			@item_id					INT,
			@item_code					VARCHAR(30),
			@item_desc					VARCHAR(300),
			@stor_id_1					INT,
			@stor_desc_1				VARCHAR(300),
			@DataColumn					NVARCHAR(3000)
		DECLARE @itstkpld_qtyAtGeneration
										DECIMAL(19,4)
		DECLARE @bitWithNotes			AS BIT

	-- ------------------------------------------------


		DECLARE Cursor_LoadStockControlData CURSOR LOCAL FAST_FORWARD FOR

			SELECT
				CASE
				    WHEN LEN(ISNULL(tscod.itstkpld_noteOfController,'')) > 0  THEN  'True'
				    ELSE															'False'
				END ,
				ti.item_id,
				ti.item_code,
				ti.item_desc,
				ts.stor_id,
				ts.stor_desc,
				REPLACE(ISNULL(     dbo.fnStrFromDecimal( tscod.itstkpld_qtyAtGeneration/*tis.itst_cant*/,19,visd.item_decimals4Stock,@intPadZeroes) + '  |  '  +
									dbo.fnStrFromDecimal((SELECT SUM(
															ISNULL(tscod2.itstkpld_qtyCounted,0))
															FROM tbStockControlOrders_Detail					tscod2	WITH(NOLOCK)
																INNER JOIN tbStockControlOrders_Header			tscoh2	WITH(NOLOCK)
																ON	tscoh2.comp_id		 = tscod2.comp_id		AND
																	tscoh2.itstkpl_id	 = tscod2.itstkpl_id	AND
																	tscoh2.stor_id		 = ts.stor_id
																INNER JOIN tbStockControlOrders_Selection		tscos2	WITH(NOLOCK)
																ON	tscos2.comp_id		 = tscod2.comp_id		AND
																	tscos2.[user_id]	 = @user_id				AND
																	tscos2.itstkpl_id	 = tscoh2.itstkpl_id

															WHERE	tscod2.comp_id		= @comp_id				AND
																	--tscod2.itstkpl_id	= @itstkpl_id			AND
																	tscod2.item_id		= tscod.item_id )
											,19,visd.item_decimals4Stock,@intPadZeroes) ,
									dbo.fnStrFromDecimal(tscod.itstkpld_qtyAtGeneration/*tis.itst_cant*/,19,visd.item_decimals4Stock,@intPadZeroes) + '  |  ' + visd.item_Stock0InString)+ ' | ' +
									ISNULL(dbo.fnStrFromDecimal(tscod.itstkpld_qty4Adjust,19,visd.item_decimals4Stock,@intPadZeroes),visd.item_Stock0InString),'.',',')
									+ '*' + ISNULL(tscod.itstkpld_noteOfManager,'')  + '  |  ' + ISNULL(tscod.itstkpld_noteOfController,'')  + ' | ' + dbo.fnStrFromDecimal(IsNull(tscod.itstkpld_qtyCountedLast,0),25,visd.item_decimals4Stock,@intPadZeroes) 	[Qty Counted | Qty Storage],

				--CANTIDAD QUE SE REGISTRO PARA LA HOJA DEL ARTICULO, DEPOSITO
				ISNULL(tscod.itstkpld_qtyAtGeneration,0) 																								[qtyAtGeneration]

			FROM tbStockControlOrders_Detail				tscod		WITH(NOLOCK)

				INNER JOIN tbStockControlOrders_Selection	tscos		WITH(NOLOCK)
				ON	tscos.comp_id		= tscod.comp_id		AND
					tscos.itstkpl_id	= tscod.itstkpl_id	--AND
					--tscos.[user_id]		= @user_id

				INNER JOIN tbStockControlOrders_Header		tscoh		WITH(NOLOCK)
				ON	tscoh.comp_id		= tscod.comp_id		AND
					tscoh.itstkpl_id	= tscod.itstkpl_id

				INNER JOIN tbStorage						ts			WITH(NOLOCK)
				ON	ts.comp_id			= tscoh.comp_id		AND
					ts.stor_id			= tscoh.stor_id

				INNER JOIN tbItemStorage					tis			WITH(NOLOCK)
				ON	tis.comp_id			= ts.comp_id		AND
					tis.stor_id			= ts.stor_id		AND
					tis.item_id			= tscod.item_id

				INNER JOIN tbItem							ti			WITH(NOLOCK)
				ON	ti.comp_id			= tscod.comp_id		AND
					ti.item_id			= tscod.item_id

				INNER JOIN vwItemsStockDecimals visd					WITH(NOLOCK)
					ON	visd.comp_id	= tscod.comp_id AND
						visd.item_id	= tscod.item_id

			WHERE	tscos.comp_id		= @comp_id			AND
					tscos.[user_id]		= @user_id
			ORDER BY tscos.os_order

		OPEN Cursor_LoadStockControlData

		FETCH NEXT FROM Cursor_LoadStockControlData

		INTO
			@bitWithNotes,
			@item_id,
			@item_code,
			@item_desc,
			@stor_id_1,
			@stor_desc_1,
			@DataColumn,
			@itstkpld_qtyAtGeneration

		WHILE @@FETCH_STATUS = 0
			BEGIN


--==
--SELECT @item_code
----==
				-- NOMBRE DE LA COLUMNA A ACTUALIZAR
				DECLARE @ColName2Compare VARCHAR(200)
				--SET @ColName2Compare = '(' + CONVERT(VARCHAR,@stor_id_1) + ') ' + @stor_desc_1
				SET @ColName2Compare = @stor_desc_1

				-- STRING DINAMICA PARA ACTUALIZAR EL REGISTRO
				DECLARE @DynamicExec2UpdateStockData VARCHAR(MAX)

				--SELECT @item_id

				SET @DynamicExec2UpdateStockData = 'UPDATE #tmpStorageData SET [' + @ColName2Compare + '] =' + '''' + @DataColumn  + '''' + ' WHERE ITEM_ID = ' + CONVERT(VARCHAR,@item_id)

				--SELECT @DynamicExec2UpdateStockData

				EXEC (@DynamicExec2UpdateStockData)

				IF @bitWithNotes = 'true'
					BEGIN
						UPDATE #tmpStorageData SET Item_Desc = Item_Desc + ' *[NOTES]*' WHERE Item_Id = @item_id AND Item_Desc NOT LIKE ' *[NOTES]*%'
					END

				FETCH NEXT FROM Cursor_LoadStockControlData
				INTO
					@bitWithNotes,
					@item_id,
					@item_code,
					@item_desc,
					@stor_id_1,
					@stor_desc_1,
					@DataColumn,
					@itstkpld_qtyAtGeneration
			END

		CLOSE Cursor_LoadStockControlData
		DEALLOCATE Cursor_LoadStockControlData


	-- MOS: Saca lo que esta en CERO
	-- Lo saco MOS el 17-03-2016 para ver si es lo que dice Martina que NO VE.  Antes lo habgia pedido ella misma.
	-- DELETE FROM #tmpStorageData WHERE Total_Físico = 0 AND Total_Contado = 0 AND Diferencias = 0



	SELECT
			' ' [ ],
			' ' [ ],
			' ' [ ],
			' ' [ ],
			' ' [ ],
			CASE
				WHEN tts.tmpID IS NULL THEN CONVERT(BIT,'False')
				ELSE CONVERT(BIT,'True')
			END														[Checked],
			*,
			TMP.Item_Id	[ID]
		FROM #tmpStorageData			TMP
		LEFT JOIN tbTemporarySelection	tts
		ON	tts.tmpGUID	= @guid			AND
			tts.tmpID	= tmp.Item_Id	AND
			tts.tmpType	= 2
		WHERE (
				@item_idP	= -1 OR
				tmp.Item_Id = @item_idP
			  )							AND
			 (
				@Checked	= -1 OR									--TODOS
				(@Checked	= 1  AND tts.tmpGUID IS NOT NULL) OR	--SOLO MARCADOS
				(@Checked	= 0  AND tts.tmpGUID IS NULL)			--SOLO DESMARCADOS
			 )

	DROP TABLE #tmpStorageData

END
GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_GetDataByID]
(
	@comp_id		INT,
	@itstkpld_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


			SELECT
				tscod.comp_id,
				tscod.itstkpl_id,
				tscod.itstkpld_id,
				tscod.item_id,
				ISNULL(tscod.itstkpld_qtyAtGeneration,0)	[itstkpld_qtyAtGeneration],
				ISNULL(tscod.itstkpld_qtyCounted,0)			[itstkpld_qtyCounted],
				tscod.user_id_lastCount,
				ISNULL(tscod.itstkpld_countNumber,0)		[itstkpld_countNumber],
				ISNULL(tscod.itstkpld_isClosed,'False')		[itstkpld_isClosed],
				tscod.user_id_isClosed,
				tscod.itstkpld_isClosedCD,
				ISNULL(tscod.itstkpld_noteOfController,'')	[itstkpld_noteOfController],
				ISNULL(tscod.itstkpld_noteOfManager,'')		[itstkpld_noteOfManager],
				tscod.itstkpld_qty4Adjust


			FROM tbStockControlOrders_Detail			tscod
			WHERE	tscod.comp_id		= @comp_id		AND
					tscod.itstkpld_id	= @itstkpld_id

		END

GO



