CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_GetTotals]
(
	@comp_id	INT,
	@user_id	INT,
	@item_idP	INT
)
AS

	SET NOCOUNT ON

		BEGIN
			-- ------------------------------
			-- TESTING
			-- ------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@user_id	INT,
					@item_idP	INT
				SELECT
					@comp_id	= 1,
					@user_id	= 119,
					@item_idP	= 542
			*/
			-- ------------------------------



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


			SELECT
				DISTINCT
			--	ti.item_id,
			--	ti.item_code,
			--	ti.item_desc,
				SUM(ISNULL(tscod.itstkpld_qtyAtGeneration,0))	[Total],
				SUM(ISNULL(tscod.itstkpld_qtyCounted,0))		[Contado]--,
				--SUM(ISNULL(tscod.itstkpld_qtyCounted,0)) - SUM(ISNULL(tscod.itstkpld_qtyAtGeneration,0)),
				--SUM(ISNULL(tscod.itstkpld_qty4Adjust,0))		[itstkpld_qty4Adjust]
			FROM tbStockControlOrders_Detail					tscod	WITH(NOLOCK)
				INNER JOIN tbItem								ti		WITH(NOLOCK)
				ON	ti.comp_id			= tscod.comp_id			AND
					ti.item_id			= tscod.item_id
				INNER JOIN tbStockControlOrders_Header			tscoh	WITH(NOLOCK)
				ON	tscoh.comp_id		= tscod.comp_id			AND
					tscoh.itstkpl_id	= tscod.itstkpl_id
				INNER JOIN tbStockControlOrders_Selection		tscos	WITH(NOLOCK)
				ON	tscos.comp_id		= tscod.comp_id			AND
					tscos.[user_id]		= @user_id				AND
					tscos.itstkpl_id	= tscoh.itstkpl_id

			WHERE	tscod.comp_id	= @comp_id					AND
					(@item_idP		= -1 OR tscod.item_id = @item_idP)

			--GROUP BY ti.item_id, ti.item_code, ti.item_desc--, tscod.itstkpld_qty4Adjust

		END
GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_InsertData]
(
	@comp_id					INT,
	@itstkpl_id					INT,
	@item_id					INT,
	@itstkpld_qtyAtGeneration	INT,
	@itstkpld_qtyCounted		INT,
	@user_id_lastCount			INT,
	@itstkpld_countNumber		INT,
	@itstkpld_isClosed			BIT,
	@user_id_isClosed			INT,
	@itstkpld_noteOfController	NVARCHAR(MAX),
	@itstkpld_noteOfManager		NVARCHAR(MAX),
	@itstkpld_qty4Adjust		INT,
	@return_value				INT OUTPUT
)
AS
	SET NOCOUNT ON

		BEGIN

			INSERT INTO tbStockControlOrders_Detail
			(
				comp_id,
				itstkpl_id,
				-- itstkpld_id -- this column value is auto-generated,
				item_id,
				itstkpld_qtyAtGeneration,
				itstkpld_qtyCounted,
				user_id_lastCount,
				itstkpld_countNumber,
				itstkpld_isClosed,
				user_id_isClosed,
				itstkpld_isClosedCD,
				itstkpld_noteOfController,
				itstkpld_noteOfManager,
				itstkpld_qty4Adjust
			)
			VALUES
			(
				@comp_id,
				@itstkpl_id,
				@item_id,
				@itstkpld_qtyAtGeneration,
				@itstkpld_qtyCounted,
				@user_id_lastCount,
				@itstkpld_countNumber,
				@itstkpld_isClosed,
				@user_id_isClosed,
				GETDATE(),
				@itstkpld_noteOfController,
				@itstkpld_noteOfManager,
				@itstkpld_qty4Adjust
			)

			SET @return_value = @@IDENTITY

		END
GO




CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_IsItemInSheet]
(
	@comp_id		INT,
	@itstkpl_id		INT,
	@ItemCodeOrEan	VARCHAR(100),
	@bra_id			INT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------

		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@itstkpl_id		INT,
				@ItemCodeOrEan	VARCHAR(100)
			SELECT
				@comp_id		= 1,
				@itstkpl_id		= 227,
				@ItemCodeOrEan	= '0000003570'
		*/
		-- -----------------------------------------

		--RECUPERAMOS EL ITEM_ID EN BASE AL CODIGO QUE NOS ENVIAN
		--PARA SABER SI ESTA EN LA HOJA DE CONTROL DE INVENTARIO
		DECLARE @lItem_Id INT
		SELECT TOP 1
			@lItem_Id = ti.item_id
			FROM tbItem									ti	WITH(NOLOCK)
				LEFT JOIN tbItemEAN						tie	WITH(NOLOCK)
					ON	tie.comp_id = ti.comp_id		AND
						tie.item_id = ti.item_id
				LEFT JOIN tbItemSerials					tis	WITH(NOLOCK)
					ON  tis.comp_id		= ti.comp_id	AND
						tis.item_id		= ti.item_id
			WHERE	ti.comp_id = @comp_id AND
					(
						ti.item_code	= @ItemCodeOrEan OR
						tie.ie_ean		= @ItemCodeOrEan OR
						tis.is_serial	= @ItemCodeOrEan
					)
		-- ---------------------------------------------------------------------
		-- busca x Codigo del Proveedor o Alternativo si lo Admite la Sucursal.
		-- ---------------------------------------------------------------------
		IF @lItem_Id IS NULL
			BEGIN
				SET @lItem_Id = ( select TOP 1 ti.item_id
										from tbItem		ti		WITH (NOLOCK)
										INNER JOIN tbBranch tb	WITH (NOLOCK)
											ON	tb.comp_id	= @comp_id	AND
												tb.bra_id	= @bra_id
										WHERE	ti.comp_id	= @comp_id									AND
												tb.bra_StockControlSearchByAlternativeCodes = 'True'	AND
											(
												ti.item_vendorCode			= @ItemCodeOrEan
											OR
												ti.item_codeAlternative		= @ItemCodeOrEan
											)
				)
			END
		-- ---------------------------------------------------------------------


		IF EXISTS (SELECT
					TOP 1 ti.item_id
					FROM tbItem										ti		WITH(NOLOCK)
					INNER JOIN tbStockControlOrders_Detail			tscod	WITH(NOLOCK)
						ON	tscod.comp_id		= ti.comp_id		AND
							tscod.item_id		= ti.item_id		AND
							tscod.itstkpl_id	= @itstkpl_id

					WHERE	ti.comp_id		= @comp_id		AND
							ti.item_id		= @lItem_Id)
							--ti.item_code	= @ItemCodeOrEan)
			BEGIN
				SELECT 'True'
			END
		ELSE
			BEGIN
				SELECT 'False'
			END

	END
GO



