CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_UpdateRecountItems]
(
	@comp_id	INT,
	@lang_id	INT,
	@user_id	INT,
	@item_id	INT,
	@stor_id	INT
)
AS

	SET NOCOUNT ON

		BEGIN

			-- ---------------------------------------------------------------
			-- TESTING
			-- ---------------------------------------------------------------
			/*
				DECLARE
					@comp_id	INT,
					@item_id	INT,
					@stor_id	INT,
					@guid		UNIQUEIDENTIFIER,
					@user_id	INT,
					@lang_id	INT


				SELECT
					@comp_id	= 1,
					@item_id	= 256,
					@stor_id	= 4,
					@guid		= '566521D6-CF0B-4843-985A-3B4D9390F935',
					@user_id	= 119,
					@lang_id	= 2

				DROP TABLE #tmpIDS
			*/
			-- ---------------------------------------------------------------



			SELECT
				tscos.itstkpl_id
			INTO #tmpIDS

			FROM tbStockControlOrders_Selection				tscos	WITH(NOLOCK)
				INNER JOIN tbStockControlOrders_Header		tscoh	WITH(NOLOCK)
				ON	tscoh.comp_id		= tscos.comp_id		AND
					tscoh.itstkpl_id	= tscos.itstkpl_id
				INNER JOIN tbStockControlOrders_Detail		tscod	WITH(NOLOCK)
				ON	tscod.comp_id		= tscoh.comp_id		AND
					tscod.itstkpl_id	= tscoh.itstkpl_id

			WHERE	tscos.comp_id		= @comp_id	AND
					tscos.[user_id]		= @user_id	AND
					tscoh.stor_id		= @stor_id	AND
					tscod.item_id		= @item_id
			ORDER BY tscos.os_order

			--SELECT * FROM  #tmpIDS


			UPDATE tbStockControlOrders_Detail	WITH (ROWLOCK)
			SET
				itstkpld_qtyCounted		 = 0,
				itstkpld_isClosed		 = 'False',
				user_id_isClosed		 = NULL,
				itstkpld_isClosedCD		 = NULL,
				itstkpld_qtyCountedLast  = itstkpld_qtyCounted,
				itstkpld_qtyCountedCount = ISNULL(itstkpld_qtyCountedCount,0) + 1,
				itstkpld_qty4Adjust		 = 0,
				itstkpld_isInRecount	 = 'True'

			WHERE	comp_id			= @comp_id AND
					item_id			= @item_id AND
					itstkpl_id		IN (SELECT
											itstkpl_id
		          						FROM #tmpIDS)






						--ENVIAMOS POR MAIL AL MANAGER DEL GRUPO Y A LOS USUARIOS DEL MISMO LA INFORMACIÓN

				--OBTENEMOS EL MAIL DEL MANAGER DEL GRUPO DE LA HOJA DE LA
				--QUE SE CERRARON TODOS LOS ITEMS
				DECLARE @ManagerMail	VARCHAR(200)
				SET		@ManagerMail	= ''
				SELECT
					@ManagerMail = tscg.istkcg_managerMail
				FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
					INNER JOIN tbStockControlGroups				tscg	WITH(NOLOCK)
					ON	tscg.comp_id		= tscoh.comp_id		AND
						tscg.istkcg_id		= tscoh.istkcg_id
				WHERE	tscoh.comp_id		= @comp_id			AND
						tscoh.itstkpl_id	IN (SELECT
													itstkpl_id
		          								FROM #tmpIDS)	AND
		          		tscg.istkcg_managerMail_enabled4Mail = 'True'


				--OBTENEMOS LOS DATOS DEL USUARIO QUE LA CERRO
				DECLARE @user_name	VARCHAR(200)
				SELECT
					@user_name = tu.user_lastname + ',' + tu.user_firstname
					FROM tbUser										tu		WITH(NOLOCK)
					WHERE	tu.[user_id]		= @user_id


				--OBTENEMOS EL NOMBRE DE LA HOJA QUE SE CERRÓ
				DECLARE @SheetName	VARCHAR(200)

				SELECT
					@SheetName = tscoh.itstkpl_desc
				FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
				WHERE	tscoh.comp_id		= @comp_id			AND
						tscoh.itstkpl_id	IN (SELECT
													itstkpl_id
		          								FROM #tmpIDS)


				--OBTENEMOS LOS MAILS DE LOS USUARIOS QUE CORRESPONDEN AL GRUPO
				DECLARE
					@strMails varchar(MAX)
				SET @strMails = ''

				SELECT
					@strMails  = @strMails +  tu.user_email + ';'
					FROM tbStockControlUsersByGroups tscubg					WITH (NOLOCK)
						INNER JOIN tbUser tu								WITH (NOLOCK)
							ON tu.[user_id] = tscubg.[user_id]
						INNER JOIN tbStockControlOrders_Header	tscoh		WITH (NOLOCK)
							ON	tscoh.comp_id		= @comp_id			AND
								tscoh.itstkpl_id	IN (SELECT
																itstkpl_id
		          												FROM #tmpIDS)
						WHERE	tscoh.comp_id				= @comp_id AND
								tscubg.istkcg_id			= tscoh.istkcg_id AND
								tscubg.istkcg_enabled4Mail	= 'True'

				--SELECT @strMails


				--ENVIAMOS EL MAIL CON LA INFORMACIÓN
				DECLARE
					@subject	VARCHAR(200),
					@Recipients	varchar(MAX),
					@MailBody	VARCHAR(500),
					@str1		VARCHAR(100),
					@str2		VARCHAR(100),
					@str3		VARCHAR(100),
					@str4		varchar(100)

					--SUBJECT
					SELECT
						@subject = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30561


					-- ----------------------------------------------------------
					-- BODY DEL MAIL
					-- ----------------------------------------------------------
					SELECT
						@str1 = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30562

					SELECT
						@str2 = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30563

					SELECT
						@str3 = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30564

					SELECT
						@str4 = tut.utexts_desc
					FROM tbsysUniqueTexts tut
					WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30565

					-- -----------------------------------------------------------

					--DESTINATARIOS MANAGER + USUARIOS DEL GRUPO DE CONTROL DE STOCK
					SET @Recipients = @ManagerMail + ';' + @strMails
					--select @Recipients
					--CUERPO DEL MAIL
					SET @MailBody	= @str1 + ' ' + '"' + @SheetName + '"' + ' ' + @str2 + ' ' + @str3 + ' ' + CONVERT(VARCHAR,GETDATE()) + ' ' + @str4 + ' ' +  @user_name



				exec spSystem_sendEMail
							@compId				= @comp_id,
							@precipients		= @Recipients,
							@pcopy_recipients	= '',
							@psubject			= @subject,
							@pbody_format		= 'HTML',
							@pbody				= @MailBody,
							@pfile_attachments	= NULL,
							@pReplyTo			= NULL,
							@pblind_copy_recipients='',
							@pUser_Id			= @user_id





		END
GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_UpdateStatus]
(
	@comp_id		INT,
	@itstkpld_id	INT,
	@user_id		INT,
	@itstkpl_id		INT
)
AS
	SET NOCOUNT ON

		BEGIN
			--ENTIENDO QUE PUEDE "NO" HABER LA CANTIDAD QUE SE INFORMA EN LA PLANILLA
			--PUEDE FIGURAR QUE HAY 100 PELOTITAS PERO EN EL CONTEO HAY 78
			--STL NOTAS PARA NO SER BOLUDO xD
			--PUEDE ACTUALIZAR TODOS O UNO EN PARTICULAR, TODO DEPENDE DE QUE ENVÍA DESDE LA PÁGINA

			UPDATE tbStockControlOrders_Detail
			SET
				itstkpld_isClosed		= 'True',
				user_id_isClosed		= @user_id,
				itstkpld_isClosedCD		= GETDATE(),
				itstkpld_isInRecount	= 'False'
			WHERE	comp_id		= @comp_id		AND
					itstkpl_id	= @itstkpl_id	AND
					(@itstkpld_id = -1 OR itstkpld_id = @itstkpld_id)

		END
GO




CREATE PROCEDURE [dbo].[spStockControlOrders_Detail_UpdtCount]
(
	@comp_id		INT,
	@itstkpl_id		INT,
	@user_id		INT,
	@ItemCodeOrEan	VARCHAR(100),
	@qty			DECIMAL(19,4),
	@guid			UNIQUEIDENTIFIER,
	@bra_id			INT
)
AS

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	-- ---------------------------------------------------------
	-- Test
	-- ---------------------------------------------------------
	/*
	DECLARE 	@comp_id		INT,
				@itstkpl_id		INT,
				@user_id		INT,
				@ItemCodeOrEan	VARCHAR(100),
				@qty			DECIMAL(19,4),
				@guid			UNIQUEIDENTIFIER


	select 	@comp_id = 1,
			@itstkpl_id	= 5309,
			@user_id = 45		,
			@ItemCodeOrEan	= '2500000010880',
			@qty			= 1,
			@guid			= 	'ef88c29f-ed41-4e30-9d85-144f8916a546'
			*/
	-- ---------------------------------------------------------




	BEGIN


			--mos
			--llamas a sp
			--si es = -1 lo que tiene strean RETURN
			--SET @item_id = buscar @strEAN en item_code
			--si existe seguir
			--sino, return2

				DECLARE @qty_CheckingTable	AS DECIMAL(19,4)
				DECLARE @item_id			AS INT

				IF @ItemCodeOrEan <> ''

					BEGIN

						exec [spItemPartsCheckingProcess]@comp_id,@guid ,@qty OUTPUT,@ItemCodeOrEan OUTPUT

						SET @qty_CheckingTable = @qty

						IF @ItemCodeOrEan = '-1'
							BEGIN
								RETURN
							END
						ELSE
							BEGIN
								SET @item_id = ( select TOP 1 ti.item_id
													 from tbItem		ti		WITH (NOLOCK)
													 LEFT JOIN tbItemEAN tie	WITH (NOLOCK)
														ON	tie.comp_id = ti.comp_id AND
															tie.item_id = ti.item_id

													 WHERE ti.comp_id	= @comp_id AND
														   (
														   		ti.item_code = @ItemCodeOrEan
														   	OR
														   		tie.ie_ean   = @ItemCodeOrEan
														   	)
												)

							END
					END




			-- busca x Numero de Serie MOS 01-2016
			IF @item_id IS NULL
				BEGIN
					SELECT @item_id = tis.item_id
						FROM tbItemSerials tis WITH (NOLOCK)
						WHERE	tis.comp_id		= @comp_id AND
								tis.is_serial	= @ItemCodeOrEan
					IF @item_id IS NOT NULL SET @qty = 1	-- si es un Numero de serie la cantidad es solo UNO
				END


			-- busca x Codigo del Proveedor o Alternativo si lo Admite la Sucursal.
			IF @item_id IS NULL
				BEGIN
					SET @item_id = ( select TOP 1 ti.item_id
											from tbItem		ti		WITH (NOLOCK)
											INNER JOIN tbBranch tb	WITH (NOLOCK)
												ON	tb.comp_id	= @comp_id	AND
													tb.bra_id	= @bra_id
											WHERE	ti.comp_id	= @comp_id									AND
													tb.bra_StockControlSearchByAlternativeCodes = 'True'	AND
												(
													ti.item_vendorCode			= @ItemCodeOrEan
												OR
													ti.item_codeAlternative		= @ItemCodeOrEan
												)
									)
					IF @item_id IS NOT NULL SET @qty = 1	-- si es un Numero de serie la cantidad es solo UNO
				END




			-- Si no encontro ninguno se va
			IF @item_id IS NULL
				BEGIN
					RETURN
				END
			ELSE	-- Si encontro alguno lo procesa como contado
				BEGIN




					--ACTUALIZAMOS LA DETAIL CON EL ITEM_ID OBTENIDO ARRIBA
					UPDATE tbStockControlOrders_Detail
						SET
							itstkpld_qtyCounted		= ISNULL(itstkpld_qtyCounted,0) + @qty,
							user_id_lastCount		= @user_id,
							itstkpld_lastStockCountAt = GETDATE()

						WHERE	comp_id								= @comp_id		AND
								itstkpl_id							= @itstkpl_id	AND
								item_id								= @item_id		AND
								itstkpld_isClosed					= 'False'

					--LIBERAMOS LAS PARTES QUE SE HAYAN CONTADO
					EXEC spItemPartsCheckingProcess_FreeParts @comp_id, @guid, @item_id, @qty
				END

		END
GO



CREATE PROCEDURE spStockControlOrders_Detail_UpdtCountByItemId
(
	@comp_id		INT,
	@itstkpl_id		INT,
	@user_id		INT,
	@item_id		INT,
	@qty			DECIMAL(19,4)
)
AS
	SET NOCOUNT ON

		BEGIN
			--ACTUALIZAMOS LA DETAIL CON EL ITEM_ID
			UPDATE tbStockControlOrders_Detail
			SET
				itstkpld_qtyCounted		= itstkpld_qtyCounted + @qty,
				user_id_lastCount		= @user_id

			WHERE	comp_id								= @comp_id		AND
					itstkpl_id							= @itstkpl_id	AND
					item_id								= @item_id		AND
					ISNULL(itstkpld_isClosed,'False')	= 'False'

		END
GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_canSelectRecord4Grid]
(
	@comp_id	INT,
	@itstkpl_id	INT,
	@user_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			-- ----------------------------------------------
			-- Testing
			-- ----------------------------------------------
			/*
			DECLARE
				@comp_id	INT,
				@itstkpl_id	INT

			SELECT
				@comp_id	= 1,
				@itstkpl_id	= 141
			*/
			-- ----------------------------------------------




-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


			-- ---------------------------------------------
			-- Variables de Trabajo
			-- ---------------------------------------------
				DECLARE
					@stor_id	INT
			-- ---------------------------------------------

			SELECT
					@stor_id			= tscoh.stor_id
			FROM tbStockControlOrders_Header			tscoh	WITH(NOLOCK)
			WHERE	tscoh.comp_id		= @comp_id		AND
					tscoh.itstkpl_id	= @itstkpl_id

			IF EXISTS (SELECT 1 FROM tbStockControlOrders_Selection tscos WHERE tscos.itstkpl_id = @itstkpl_id AND tscos.[user_id] = @user_id)
				BEGIN
					--SI EXISTE EN LA LISTA DE SELECCIONADOS, QUE PERMITA DESTILDARLO
					SELECT 'True'
				END
			ELSE
				BEGIN
					IF EXISTS (SELECT 1
					           FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
								INNER JOIN tbStockControlOrders_Selection	tscos	WITH(NOLOCK)
								ON	tscos.comp_id	    = tscoh.comp_id		AND
									tscos.itstkpl_id    = tscoh.itstkpl_id
					           WHERE	tscoh.comp_id   = @comp_id			AND
										tscoh.stor_id   = @stor_id			AND
										tscos.[user_id] = @user_id
					)
						BEGIN
							SELECT 'False'
						END
					ELSE

						BEGIN
							SELECT 'True'
						END
				END
		END
--					IF EXISTS (SELECT
--								1
--							   FROM tbStockControlOrders_Detail				tscod	WITH(NOLOCK)
--								INNER JOIN tbStockControlOrders_Header		tscoh	WITH(NOLOCK)
--								ON	tscoh.comp_id		= tscod.comp_id		AND
--									tscoh.itstkpl_id	= tscod.itstkpl_id
--								INNER JOIN tbStockControlOrders_Selection	tscos	WITH(NOLOCK)
--								ON	tscos.comp_id		= tscoh.comp_id		AND
--									tscos.itstkpl_id	= tscoh.itstkpl_id
--							   WHERE	tscod.comp_id	= @comp_id			AND
--										tscod.item_id   IN(SELECT
--																tscod2.item_id
--														   FROM tbStockControlOrders_Detail					tscod2
--															INNER JOIN tbStockControlOrders_Header			tscoh2
--															ON	tscoh2.comp_id			= tscod2.comp_id	AND
--																tscoh2.itstkpl_id		= tscod2.itstkpl_id
--														   WHERE tscod2.comp_id			= @comp_id			AND
--																	tscoh2.itstkpl_id	= @itstkpl_id)		AND
--										tscoh.stor_id	= @stor_id)
--						BEGIN
--							--SI YA EXISTE ESE ID PARA ALGUNA HOJA YA SELECCIONADA, NO LO PERMITIMOS
--							SELECT 'False'
--
--						END
--
--					ELSE
--
--						BEGIN
--							--SI NO EXISTE LA HOJA Y LAS QUE ESTAN SELECCIONADAS NO COMPARTEN STOR_ID E ITEM_ID CON LA QUE SE DESEA SELECCIONAR
--							--LA MARCAMOS
--							SELECT 'True'
