GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_CanUseSecondaryGridButtons]
(
	@comp_id	INT,
	@user_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

			-- ----------------------------
			-- TESTING
			-- ----------------------------
			/*
				DECLARE
					@comp_id	INT,
					@user_id	INT,
					@itstkpl_id	INT
				SELECT
					@comp_id	= 1,
					@user_id	= 119,
					@itstkpl_id	= 163
			*/
			-- ----------------------------

			SELECT
				COUNT(*)
			FROM tbStockControlOrders_Header						tscoh
				INNER JOIN tbStockControlOrders_Selection			tscos
				ON	tscos.comp_id				= tscoh.comp_id		AND
					tscos.itstkpl_id			= tscoh.itstkpl_id

			WHERE	tscoh.comp_id				= @comp_id			AND
					--tscoh.itstkpl_isControlled	= 'True' <-- ANTES ERA ASi, LO MODIFIQUE PARA QUE NO PUEDA USAR LOS BOTONES DE LA GRILLA SECUNDARIA
															  -- SI ESTA CERRADA O CONTROLADA
					(tscoh.itstkpl_isClosed = 'True' OR tscoh.itstkpl_isControlled	= 'True')			AND
					tscos.[user_id]				= @user_id

		END



GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_DeleteData]
(
	@comp_id	INT,
	@itstkpl_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			--SI NO EXISTE Y NO ESTA CONTADO, NI PROCESADO, NI NIVELADO, BORRAMOS HEADER Y DETAIL
			IF NOT EXISTS (SELECT
								1
			               FROM tbStockControlOrders_Header tscoh		WITH (NOLOCK)
			               WHERE	tscoh.comp_id = @comp_id							AND
									tscoh.itstkpl_id = @itstkpl_id						AND
									(
										ISNULL(itstkpl_isClosed,'False')	= 'True'	OR
										ISNULL(itstkpl_isControlled,'False')= 'True'	OR
										ISNULL(itstkpl_isProcessed,'False')	= 'True'
									)
							)

				BEGIN
					--BORRAMOS LA DETAIL
					DELETE FROM tbStockControlOrders_Detail		WITH (ROWLOCK)
					WHERE	comp_id								= @comp_id		AND
							itstkpl_id							= @itstkpl_id

					--BORRAMOS LA HEADER
					DELETE FROM tbStockControlOrders_Header		WITH (ROWLOCK)
					WHERE	comp_id								= @comp_id		AND
							itstkpl_id							= @itstkpl_id

				END


		END
GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_getCombo]
(
	@comp_id	INT
)
AS

	SET NOCOUNT ON

		BEGIN

			SELECT
				tscoh.itstkpl_desc							[Desc],
				tscoh.itstkpl_id							[Id]

			FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
			WHERE	tscoh.comp_id							= @comp_id	AND
					ISNULL(tscoh.itstkpl_isClosed,'False')	= 'False'

		END


GO




CREATE PROCEDURE [dbo].[spStockControlOrders_Header_getComboByUser]
(
	@comp_id	INT,
	@user_id	INT,
	@status		INT,
	@bra_id		INT
)
AS

	--AGREGUE EL BRA_ID

	SET NOCOUNT ON

		BEGIN

			-- ------------------------
			-- Testing
			-- ------------------------
			/*
				DECLARE
					@comp_id	INT,
					@user_id	INT,
					@status		INT
				SELECT
					@comp_id	= 1,
					@user_id	= 1,
					@status		= 3
			*/
			-- ------------------------

			-- -------------------------
			-- ESTADOS
			-- -------------------------
				-- TODOS		= 2
				-- NO CERRADOS	= 1
				-- CERRADOS		= 3
			-- -------------------------


			SELECT
				tscoh.itstkpl_desc							[Desc],
				tscoh.itstkpl_id							[Id]

			FROM tbStockControlOrders_Header				tscoh		WITH(NOLOCK)
			INNER JOIN tbStockControlUsersByStorage			tus			WITH(NOLOCK)
				ON	tus.comp_id		= @comp_id AND
					tus.[user_id]	= @user_id AND
					tus.stor_id		= tscoh.stor_id
			WHERE	tscoh.comp_id							= @comp_id	AND
					--tscoh.bra_id							= @bra_id	AND   NOOOOOOOOOOOOOOOOO
					ISNULL(tscoh.itstkpl_isClosed,'False')	= 'False'	AND
					tscoh.istkcg_id							IN (SELECT
																	tscubg.istkcg_id
																FROM tbStockControlUsersByGroups tscubg		WITH(NOLOCK)
																WHERE	tscubg.comp_id		= @comp_id AND
																		tscubg.[user_id]	= @user_id)			AND
					(
						(@status = 1						AND EXISTS (SELECT 1
			            												FROM tbStockControlOrders_Detail									tscod	WITH(NOLOCK)
			            												WHERE	tscod.comp_id							= @comp_id			AND
																				tscod.itstkpl_id						= tscoh.itstkpl_id  AND
																				ISNULL(tscod.itstkpld_isClosed,'False') = 'False'))					OR
						(@status = 2)																												OR
						(@status = 4						AND EXISTS (SELECT 1
			            												FROM tbStockControlOrders_Detail									tscod	WITH(NOLOCK)
			            												WHERE	tscod.comp_id							= @comp_id			AND
																				tscod.itstkpl_id						= tscoh.itstkpl_id  AND
																				ISNULL(tscod.itstkpld_isClosed,'False') = 'True'))
					)

		END



GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_GetDataByID]
(
	@comp_id	INT,
	@itstkpl_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				tscoh.comp_id,
				tscoh.itstkpl_id,
				tscoh.itstkpl_desc,
				tscoh.itstkpl_cd,
				tscoh.[user_id],
				tscoh.bra_id,
				tscoh.istkcg_id,
				ISNULL(tscoh.itstkpl_isClosed,'False')		[itstkpl_isClosed],
				tscoh.user_id_isClosed,
				ISNULL(tscoh.itstkpl_isControlled,'False')	[itstkpl_isControlled],
				tscoh.user_id_isControlled,
				ISNULL(tscoh.itstkpl_isProcessed,'False')	[itstkpl_isProcessed],
				tscoh.user_id_isProcessed,
				ISNULL(tscoh.itstkpl_note,'')				[itstkpl_note],
				tscoh.itstkpl_useSavedStock,
				tscoh.itstkpl_useSavedStockDate,
				tscoh.stor_id,
				tscg.[user_id]								[user_id_manager],
				tscoh.itstkpl_guid

			FROM tbStockControlOrders_Header			tscoh			WITH (NOLOCK)

				INNER JOIN tbStockControlGroups				tscg		WITH (NOLOCK)
				ON	tscg.comp_id	= tscoh.comp_id			AND
					tscg.istkcg_id	= tscoh.istkcg_id

			WHERE	tscoh.comp_id		= @comp_id		AND
					tscoh.itstkpl_id	= @itstkpl_id

		END


GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_GetDataBySheet]
(
	@comp_id	INT,
	@itstkpl_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


			-- ---------------------------
			-- Testing
			-- ---------------------------
			/*
				DECLARE
					@comp_id	INT,
					@itstkpl_id	INT
				SELECT
					@comp_id	= 1,
					@itstkpl_id	= 145
			*/
			-- ---------------------------

			SELECT
				tscod.comp_id,
				tscod.itstkpl_id,
				tscod.itstkpld_id,
				tscod.item_id,
				tscod.itstkpld_qtyAtGeneration,
				tscod.itstkpld_qtyCounted,
				tscod.user_id_lastCount,
				tscod.itstkpld_countNumber,
				tscod.itstkpld_isClosed,
				tscod.user_id_isClosed,
				tscod.itstkpld_isClosedCD,
				tscod.itstkpld_noteOfController,
				tscod.itstkpld_noteOfManager,
				tscod.itstkpld_qty4Adjust,
				tscod.itstkpld_qtyCountedLast,
				tscod.itstkpld_qtyCountedCount,
				tscod.itstkpld_isInRecount,
				tscoh.stor_id

			FROM tbStockControlOrders_Detail				tscod
				INNER JOIN tbStockControlOrders_Header		tscoh
				ON	tscoh.comp_id		= tscod.comp_id		AND
					tscoh.itstkpl_id	= tscod.itstkpl_id
			WHERE	tscod.comp_id		= @comp_id		AND
					tscod.itstkpl_id	= @itstkpl_id

		END


GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_InsertData]
(
	@comp_id					INT,
	@lang_id					INT,
	@itstkpl_desc				VARCHAR(300),
	@user_id					INT,
	@bra_id						INT,
	@istkcg_id					INT,
	--@itstkpl_isClosed			BIT,
	--@user_id_isClosed			INT,
	--@itstkpl_isControlled		BIT,
	--@user_id_isControlled		INT,
	--@itstkpl_isProcessed		BIT,
	--@user_id_isProcessed		INT,
	--@itstkpl_note				NVARCHAR(MAX),
	--@itstkpl_useSavedStock		BIT,
	--@itstkpl_useSavedStockDate	DATETIME,
	@stor_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@radOption					BIT,
	@radDate					DATETIME,
	@bitSOClosedDiscount		BIT,
	@return_value				INT OUTPUT
)

AS


BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'
	SET @radDate = dbo.fnGetEnd_or_BeginOfDate(@radDate,'True')



	INSERT INTO tbStockControlOrders_Header
	(
		comp_id,
		itstkpl_desc,
		itstkpl_cd,
		[user_id],
		bra_id,
		istkcg_id,
--				itstkpl_isClosed,
--				user_id_isClosed,
--				itstkpl_isControlled,
--				user_id_isControlled,
--				itstkpl_isProcessed,
--				user_id_isProcessed,
--				itstkpl_note,
				itstkpl_useSavedStock,
				itstkpl_useSavedStockDate,
		stor_id
	)
	VALUES
	(
		@comp_id,
		@itstkpl_desc,
		GETDATE(),
		@user_id,
		@bra_id,
		@istkcg_id,
--				@itstkpl_isClosed,
--				@user_id_isClosed,
--				@itstkpl_isControlled,
--				@user_id_isControlled,
--				@itstkpl_isProcessed,
--				@user_id_isProcessed,
--				@itstkpl_note,
		CASE @radOption
			WHEN 'True' THEN 'True'
			ELSE			 'False'
		END,
		CASE @radOption
			WHEN 'True' THEN @radDate
			ELSE			 GETDATE()
		END,
		@stor_id
	)

	SET @return_value = @@IDENTITY


		--INSERTAMOS EN LA DETAIL TODOS LOS ARTÍCULOS EN CASO DE TENERLOS
		--OPCIÓNDE RADIO BUTTON
		-- TRUE  = CON EL STOCK EN CIERTA FECHA
		-- FALSE = CON EL STOCK DE LA GETSTOCKOFSTORAGEGROUP
		IF (SELECT COUNT(*) FROM tbComplexFilter tcf WITH (NOLOCK) WHERE tcf.sl_guid = @guid) > 0
			BEGIN

				INSERT INTO tbStockControlOrders_Detail
				(
					comp_id,
					itstkpl_id,
					-- itstkpld_id -- this column value is auto-generated,
					item_id,
					itstkpld_qtyAtGeneration,
					itstkpld_qtyCounted,
					user_id_lastCount,
					itstkpld_countNumber,
					--itstkpld_isClosed,
					user_id_isClosed,
					itstkpld_isClosedCD,
					itstkpld_noteOfController,
					itstkpld_noteOfManager,
					itstkpld_qty4Adjust,
					itstkpld_StockAt
				)
				SELECT
					@comp_id,
					@@IDENTITY,
					tcf.sl_id,
					(
						CASE @radOption
							WHEN 'True' THEN dbo.fnGetStockHistory(@comp_id, @stor_id, tcf.sl_id, @radDate)
							ELSE			 dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id, tcf.sl_id)
						END
						-
						CASE
							WHEN @bitSOClosedDiscount = 'False' THEN
								0
							ELSE
								(	SELECT SUM(tsod.sod_qty)
										FROM tbSaleOrderDetail tsod								WITH (NOLOCK)
										INNER JOIN tbSaleOrderHeader				tsoh		WITH (NOLOCK)
											ON	tsoh.comp_id	= tsod.comp_id	AND
												tsoh.bra_id		= tsod.bra_id	AND
												tsoh.soh_id		= tsod.soh_id
										INNER JOIN tbDocumentsFile					tdf			WITH (NOLOCK)
											ON	tdf.comp_id		= tsoh.comp_id	AND
												tdf.df_id		= tsoh.df_id
										WHERE	tsod.comp_id	= @comp_id		AND
												tsod.stor_id	= @stor_id		AND
												tsod.item_id	= tcf.sl_id		AND
												tdf.sd_id IN (1,2,4,31,80)		AND
												tsoh.ssos_id    = 50  -- Pedidos Cerrados.!
								)

						END
					),
					NULL,
					NULL,
					NULL,
					--'False',
					NULL,
					NULL,
					NULL,
					NULL,
					0	,
					CASE @radOption
						WHEN 'True'		THEN @radDate
						ELSE			GETDATE()	-- Es la fecha y hora actual y no la de la sucursal, ojo !!!
					END
					FROM tbComplexFilter						tcf			WITH (NOLOCK)
					INNER JOIN tbItem							ti			WITH (NOLOCK)
						ON	ti.comp_id				= @comp_id	AND
							ti.item_id				= tcf.sl_id
					WHERE	tcf.sl_guid				= @guid		AND
							ti.item_disabled		= 'False'	AND
							ti.item_NoStockCheck	= 'False'

			END



	-- ----------------------------------------------------------------------------------
	--ENVIAMOS POR MAIL AL MANAGER DEL GRUPO Y A LOS USUARIOS DEL MISMO LA INFORMACIÓN
	-- ----------------------------------------------------------------------------------

		--OBTENEMOS EL MAIL DEL MANAGER DEL GRUPO DE LA HOJA DE LA
		--QUE SE CERRARON TODOS LOS ITEMS
		DECLARE @ManagerMail	VARCHAR(200)
		SET		@ManagerMail	= ''
		SELECT
			@ManagerMail = tscg.istkcg_managerMail
			FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
				INNER JOIN tbStockControlGroups				tscg	WITH(NOLOCK)
				ON	tscg.comp_id		= tscoh.comp_id		AND
					tscg.istkcg_id		= tscoh.istkcg_id
			WHERE	tscoh.comp_id		= @comp_id			AND
					tscoh.itstkpl_id	= @return_value		AND
					tscg.istkcg_managerMail_enabled4Mail = 'True'


		DECLARE @AuditorMail	VARCHAR(200)
		SET		@AuditorMail	= ''
		SELECT
			@AuditorMail = tscg.istkcg_auditorMail
			FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
				INNER JOIN tbStockControlGroups				tscg	WITH(NOLOCK)
				ON	tscg.comp_id		= tscoh.comp_id		AND
					tscg.istkcg_id		= tscoh.istkcg_id
			WHERE	tscoh.comp_id		= @comp_id			AND
					tscoh.itstkpl_id	= @return_value		AND
					tscg.istkcg_auditorMail_enabled4Mail = 'True'


		--OBTENEMOS LOS DATOS DEL USUARIO QUE LA CERRO
		DECLARE @user_name	VARCHAR(200)
		SELECT
			@user_name = tu.user_lastname + ',' + tu.user_firstname
			FROM tbUser										tu		WITH(NOLOCK)
			WHERE	tu.[user_id]		= @user_id


		--OBTENEMOS EL NOMBRE DE LA HOJA QUE SE CERRÓ
		DECLARE @SheetName	VARCHAR(200)

		SELECT
			@SheetName = tscoh.itstkpl_desc
		FROM tbStockControlOrders_Header				tscoh	WITH(NOLOCK)
		WHERE	tscoh.comp_id		= @comp_id			AND
				tscoh.itstkpl_id	= @return_value


		--OBTENEMOS LOS MAILS DE LOS USUARIOS QUE CORRESPONDEN AL GRUPO
		DECLARE
			@strMails varchar(MAX)
		SET @strMails = ''

		SELECT
			@strMails  = @strMails + dbo.fnStrAllTrim( tu.user_email ) + ';'
			FROM tbStockControlUsersByGroups tscubg			WITH (NOLOCK)
				INNER JOIN tbUser tu						WITH (NOLOCK)
				ON tu.[user_id] = tscubg.[user_id]
			WHERE	tscubg.comp_id				= @comp_id		AND
					tscubg.istkcg_id			= @istkcg_id	AND
					tscubg.istkcg_enabled4Mail	= 'True'




		--SELECT @strMails  Sacado por MOS 01-2016


		--ENVIAMOS EL MAIL CON LA INFORMACIÓN
		DECLARE
			@subject	VARCHAR(200),
			@Recipients	varchar(MAX),
			@MailBody	VARCHAR(500),
			@str1		VARCHAR(100),
			@str2		VARCHAR(100),
			@str3		VARCHAR(100)

			--SUBJECT
			SELECT
				@subject = tut.utexts_desc
				FROM tbsysUniqueTexts tut			WITH (NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30557


			-- ----------------------------------------------------------
			-- BODY DEL MAIL
			-- ----------------------------------------------------------
			SELECT
				@str1 = tut.utexts_desc
				FROM tbsysUniqueTexts tut				WITH (NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30558

			SELECT
				@str2 = tut.utexts_desc
				FROM tbsysUniqueTexts tut				WITH (NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30559

			SELECT
				@str3 = tut.utexts_desc
				FROM tbsysUniqueTexts tut				WITH (NOLOCK)
				WHERE tut.lang_id = @lang_id AND tut.utexts_id = 30560

			-- -----------------------------------------------------------

			--DESTINATARIOS MANAGER + USUARIOS DEL GRUPO DE CONTROL DE STOCK
			SET @Recipients = @ManagerMail + ';' + @strMails + ';' + @AuditorMail
			--CUERPO DEL MAIL
			SET @MailBody	= @str1 + ' ' + '"' + @SheetName + '"' + ' ' + @str2 + ' ' + @user_name + ' ' + @str3 + ' ' + CONVERT(VARCHAR,GETDATE())



		EXEC spSystem_sendEMail
					@compId				= @comp_id,
					@precipients		= @Recipients,
					@pcopy_recipients	= '',
					@psubject			= @subject,
					@pbody_format		= 'HTML',
					@pbody				= @MailBody,
					@pfile_attachments	= NULL,
					@pReplyTo			= NULL,
					@pblind_copy_recipients='',
					@pUser_Id			= @user_id


	-- ----------------------------------------------------------------------------------

END


GO



CREATE PROCEDURE spStockControlOrders_Header_OpenSheet
(
	@comp_id	INT,
	@itstkpl_id	INT,
	@user_id	INT
)
AS
	SET NOCOUNT ON

		BEGIN

			UPDATE tbStockControlOrders_Header
			SET
				itstkpl_isClosed		= 'False',
				user_id_lastOpener		= @user_id,
				itstkpl_lastOpenerCD	= GETDATE()

			WHERE	comp_id				= @comp_id AND
					itstkpl_id			= @itstkpl_id


		END
GO



CREATE PROCEDURE spStockControlOrders_Header_UpdateNote
(
