			UPDATE tbStockControlOrders_Header
				SET
					itstkpl_note			= @note
				WHERE	comp_id				= @comp_id AND
						itstkpl_id			= @itstkpl_id
		END
GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Header_UpdateStatus]
(
	@comp_id	INT,
	@itstkpl_id	INT,
	@user_id	INT,
	@option		INT,
	@status		BIT,
	@note		VARCHAR(8000)
)
AS
	SET NOCOUNT ON

		BEGIN
			IF @option = 2 --CONTROLA
				BEGIN
					UPDATE tbStockControlOrders_Header
					SET
						itstkpl_isControlled	= @status,
						user_id_isControlled	= @user_id--,
						--itstkpl_note			= @note
					WHERE	comp_id				= @comp_id AND
							itstkpl_id			= @itstkpl_id

				END
			ELSE
				IF @option = 1 --CIERRA
					BEGIN
						UPDATE tbStockControlOrders_Header
						SET
							itstkpl_isClosed	= 'True',
							user_id_isClosed	= @user_id--,
							--itstkpl_note		= @note
						WHERE	comp_id			= @comp_id AND
								itstkpl_id		= @itstkpl_id

					END
				ELSE
					IF @option = 3 --NIVELA
						BEGIN
							UPDATE tbStockControlOrders_Header
							SET
								itstkpl_isProcessed = @status,
								user_id_isProcessed = @user_id--,
								--itstkpl_note		= @note
							WHERE	comp_id			= @comp_id AND
									itstkpl_id		= @itstkpl_id
						END
		END
GO


CREATE PROCEDURE spStockControlOrders_Header_UpdateStatus_Transactional
(
	@comp_id				INT,
	@itstkpl_id				INT,
	@user_id				INT,
	@status					BIT,
	@note					VARCHAR(8000),
	@return_value			INT				OUTPUT,
	@ret_ErrorCode			INT				OUTPUT,
	@ret_ErrorDescription	VARCHAR(200)	OUTPUT
)
AS
	BEGIN

		SET NOCOUNT ON;

		SET @return_value			= 0
		SET @ret_ErrorCode			= 0
		SET @ret_ErrorDescription	= ''

    SAVE TRANSACTION traPROTECT
		BEGIN TRANSACTION
			BEGIN TRY
				UPDATE tbStockControlOrders_Header
				SET
					itstkpl_isControlled	= @status,
					user_id_isControlled	= @user_id--,
					--itstkpl_note			= @note
				WHERE	comp_id				= @comp_id AND
						itstkpl_id			= @itstkpl_id
			END TRY
		BEGIN CATCH
			ROLLBACK TRANSACTION traPROTECT
			DECLARE @ErrorMessage   NVARCHAR(4000)
			DECLARE @ErrorSeverity  INT
			DECLARE @ErrorState     INT
			SELECT  @ErrorMessage    = ERROR_MESSAGE(),
					@ErrorSeverity   = ERROR_SEVERITY(),
					@ErrorState      = ERROR_STATE()
			IF      @ErrorState      = 0 SET @ErrorState = 1
			RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState)

		END CATCH
		 IF @@TRANCOUNT > 0 COMMIT TRANSACTION traPROTECT

	END
GO



CREATE PROCEDURE [dbo].[spStockControlOrders_Selection_InsertOrDeleteSelection]
(
	@comp_id		INT,
	@user_id		INT,
	@itstkpl_id		INT
)
AS

	SET NOCOUNT ON

		BEGIN

			IF NOT EXISTS (SELECT 1
						   FROM tbStockControlOrders_Selection			tscos		WITH (NOLOCK)
						   WHERE	tscos.comp_id		= @comp_id		AND
									--tscos.[user_id]		= @user_id			AND
									tscos.itstkpl_id	= @itstkpl_id)
				BEGIN

					INSERT INTO tbStockControlOrders_Selection
					(
						comp_id,
						itstkpl_id,
						[user_id]
					)
					VALUES
					(
						@comp_id,
						@itstkpl_id,
						@user_id
					)

				END

			ELSE

				BEGIN

					DELETE FROM tbStockControlOrders_Selection
					WHERE	comp_id			= @comp_id AND
							--[user_id]		= @user_id AND
							itstkpl_id		= @itstkpl_id

				END

		END


GO



CREATE PROCEDURE [dbo].[spStockProcess_getData]
(
	@comp_id					INT,
	@item_code					NVARCHAR(50),
	@qty						DECIMAL,
	@stor_id					INT,
	@strprefix					NVARCHAR(50)	-- Prefijo para el codigo de articulos.


)
AS

---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE 	@comp_id					INT,
			@item_code					NVARCHAR(50),
			@qty						DECIMAL,
			@curr_id					INT,
			@stor_id					INT





SELECT 		@comp_id					= 1,
			@qty						= 0,
			@item_code					= 'D1',
			@curr_id					= 1,
			@stor_id					= 3
*/
---------------------------------------------------------------------------------


set nocount on


BEGIN

	DECLARE @bolIsOK AS BIT
	SET     @bolIsOK = 'True'

	-----------------------------------------------------------------------------------------------------------
	---- Si no le llega la moneda o no existe el id le pone por defecto la primera
	--IF NOT EXISTS (	SELECT	tc.curr_id
	--           		FROM tbsysCurrency tc WITH (NOLOCK)
	--				WHERE	tc.curr_id = @curr_id)
	--			BEGIN
	--				SET @curr_id = ( SELECT TOP 1 tc.curr_id
	--				                 FROM	tbsysCurrency tc
	--				                 ORDER BY tc.curr_id
	--				                )
	--			END
	-----------------------------------------------------------------------------------------------------------


	SET @item_code = dbo.fnStrAllTrim(@strprefix) + dbo.fnStrAllTrim(@item_code)


	---------------------------------------------------------------------------------------------------------
	--Recuperamos el item_id mediante el codigo
	DECLARE @litem_id AS INT

	SELECT
		@litem_id = ti.item_id

		FROM tbitem  ti	WITH (NOLOCK)

		WHERE	ti.comp_id		= @comp_id		AND
				ti.item_code	= @item_code
				--AND
				--@qty			<> 0

	---------------------------------------------------------------------------------------------------------


	---------------------------------------------------------------------------------------------------------
	--Recuperamos la cantidad que se va a grabar
	DECLARE @lqtyfinal AS DECIMAL(18,4)

	SELECT
		@lqtyfinal = @qty - tis.itst_cant

		FROM	tbItemStorage	tis WITH (NOLOCK)

		WHERE	tis.comp_id		= @comp_id		AND
				tis.stor_id 	= @stor_id		AND
				tis.item_id		= @litem_id
				--AND
				--@qty			<> 0

	---------------------------------------------------------------------------------------------------------


	IF @litem_id IS NULL
		BEGIN
			SET @bolIsOK = 'False'
		END

	--IF @qty = 0
	--BEGIN
	--	SET @bolIsOK = 'False'
	--END

	IF @lqtyfinal = 0
	BEGIN
		SET @bolIsOK = 'False'
	END


	-- 1 : SI , PUEDE INSERTAR
	-- 0 : NO, NO TIENE QUE HACER NADA
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1								[bolIsOK],
				@litem_id						[item_id],
				@qty							[qty],
				ISNULL(@lqtyfinal,@qty)			[qtyfinal]
		END
	ELSE
		BEGIN
			SELECT
				0								[bolIsOK],
				@litem_id						[item_id],
				@qty							[qty],
				ISNULL(@lqtyfinal,@qty)			[qtyfinal]
		END


END


















GO









