CREATE PROCEDURE [dbo].[spStorage_getCombo4BranchTransferAdditional]
(
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			int
)
AS

BEGIN


	SET NOCOUNT ON

	-- ------------------------------------------------
	-- Testing
	-- ------------------------------------------------
	/*

	DECLARE 	@comp_id			INT,
				@bra_id				INT

	SELECT 		@comp_id			=1,
				@bra_id				=1

	*/
	-- ------------------------------------------------


	IF EXISTS(	-- Se cambio el comportamiento de la tabla a Depositos HABILITADOS!!!!!!!
				SELECT 1
					FROM tbBranch2Customer4StockImport_StorageDisableByProfile tbcsisdbp
					WHERE	tbcsisdbp.comp_id	= @comp_id	AND
							tbcsisdbp.bra_id	= @bra_id	AND
							tbcsisdbp.prof_id	= @prof_id
			)
		BEGIN
			SELECT	tbcsisdbp.stor_id	[id],
					ts.stor_desc		[desc]
				FROM tbBranch2Customer4StockImport_StorageDisableByProfile tbcsisdbp	WITH (NOLOCK)
				INNER JOIN tbStorage ts													WITH (NOLOCK)
					ON	ts.comp_id = tbcsisdbp.comp_id	AND
						ts.stor_id = tbcsisdbp.stor_id
				WHERE	tbcsisdbp.comp_id	= @comp_id	AND
						tbcsisdbp.bra_id	= @bra_id	AND
						tbcsisdbp.prof_id	= @prof_id
		END
	ELSE
		BEGIN

			select		ts.stor_id			[id],
						ts.stor_desc		[desc]
				--INTO #tmpStorage
				from		dbo.tbStorage			ts					WITH (NOLOCK)
				/*
							INNER JOIN tbBranch		tb
							ON	tb.comp_id	= ts.comp_id
							AND tb.stor_id	= ts.stor_id
							AND tb.bra_id	<> @bra_id
				*/
				WHERE 		ts.comp_id													= @comp_id
				AND			Isnull(ts.stor_available4BranchTransferAdditional,'false')	= 'true'
				and			IsNull(ts.stor_disabled4Selection,'False') = 'False'
				AND			ts.stor_id NOT IN (SELECT tb.stor_id
		   										   FROM tbBranch tb
   												   WHERE	tb.comp_id	= ts.comp_id
														AND tb.bra_id	= @bra_id)

			UNION

				select		ts.stor_id			[id],
							ts.stor_desc		[desc]

					from		dbo.tbStorage			ts					WITH (NOLOCK)
								INNER JOIN tbBranch		tb						WITH (NOLOCK)
								ON	tb.comp_id	= ts.comp_id
								AND tb.stor_id	= ts.stor_id
								AND tb.bra_id	= @bra_id

					where		ts.comp_id	= @comp_id
					and			IsNull(ts.stor_disabled4Selection,'False') = 'False'



				Order By	ts.stor_desc

		END



--	-- Borra depositos des-habilitadoa para este perfil y sucursal
