--		FROM #tmpStorage tmp
--		INNER JOIN tbBranch2Customer4StockImport_StorageDisableByProfile t1
--			ON	t1.comp_id	= @comp_id		AND
--				t1.bra_id	= @bra_id		AND
--				t1.prof_id	= @prof_id		AND
--				t1.stor_id  = tmp.id
--
--
--	SELECT DISTINCT	*
--	FROM #tmpStorage


END
GO













