CREATE PROCEDURE [dbo].[spStorage_getComboByProfile]
(
	@comp_id			INT,
	@prof_id			INT,
	@stor_id			INT
)
AS



BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON


	-- -----------------------------------------------
	-- tESTING
	-- -----------------------------------------------
	/*
	DECLARE 	@comp_id			INT,
				@prof_id			INT,
				@stor_id			INT
	SELECT		@comp_id=1,
				@prof_id=2,
				@stor_id=115
	*/
	-- -----------------------------------------------

		select		ts.stor_id		[id],
					ts.stor_desc	[desc]

		from		dbo.tbStorage ts		WITH (NOLOCK)

		where		ts.comp_id =	@comp_id	AND
				(
					(
						IsNull(ts.stor_disabled4Selection,'False') = 'False'	AND
						(ts.stor_id IN (SELECT	tsp.stor_id
   										  FROM		tbStorage4Profile tsp		WITH (NOLOCK)
   										  WHERE		tsp.comp_id	= @comp_id
											AND		tsp.prof_id	= @prof_id) OR
						 NOT EXISTS (	SELECT TOP 1	1
	   									  FROM		tbStorage4Profile tsp		WITH (NOLOCK)
	   									  WHERE		tsp.comp_id	= @comp_id
										  AND		tsp.prof_id	= @prof_id))
					)

					OR

					ts.stor_id = @stor_id

				)


		Order By	stor_desc

END
GO








