)
AS SET NOCOUNT ON

/*

DECLARE
	@comp_id	INT,
	@item_id	INT
SELECT
	@comp_id	= 1,
	@item_id	= 256

*/

SELECT
	ts.stor_id		[id],
	ts.stor_desc	[desc]

	FROM tbStorage ts				WITH(NOLOCK)

