CREATE PROCEDURE [dbo].[spStorage_TransferConfiguration_UpdateCompleted]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@stt_id				INT,
	@ct_transaction		int

)
as



BEGIN



	-----------------------------------------
	-- parametros de test
	-----------------------------------------
	/*
	declare @comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@stt_id				INT


	select  @comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,
			@stt_id				= 23
	*/
	-----------------------------------------
	-- parametros de test
	-----------------------------------------


	update tbStorage_TransferTransactions
	SET
		user_id_Receptor		= @user_id,
		stt_isCompleted			= 'true',
		stt_isRejected			= 'false',
		stt_dateOfComplete		= getdate(),
		stt_isRequestPending	= 'false',
		ct_transaction			= @ct_transaction


	where comp_id = @comp_id
	and   stt_id = @stt_id


END


GO







