-- stock fisico
----------------------------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spStorage_TransferConfiguration4Request_GetStock_InsertData]
(

	@comp_id				INT,
	@bra_id					INT,
	@stor_id				INT,
	@item_id				INT,
	@stt_qty				decimal(19,4),
	@user_id_Sender			INT,
	@user_id_Receptor		INT,
	@stt_isCompleted		bit,
	@stt_isRejected			bit,
	@stt_dateOfSending		datetime,
	@stt_dateOfComplete		datetime,
	@stt_dateOfReject		datetime,
	@stor_id_from			INT,
	@user_id_Request		INT,
	@stt_isRequestPending	bit,
	@stt_dateOfRequest		datetime,
	@stt_Note				nvarchar(2000),
	@return_value			INT OUTPUT

)
as



BEGIN

	IF dbo.fnGetStock(@comp_id,@stor_id_from,@item_id) /*- dbo.fnGetStorageTransfer_Pending(@comp_id,@stor_id_from,@item_id)*/ >= @stt_qty
		BEGIN

			insert into tbStorage_TransferTransactions

			(
				comp_id,
				bra_id,
				stor_id,
				item_id,
				stt_qty,
				user_id_Sender,
				user_id_Receptor,
				stt_isCompleted,
				stt_isRejected,
				stt_dateOfSending,
				stt_dateOfComplete,
				stt_dateOfReject,
				stor_id_From,
				user_id_Request,
				stt_isRequestPending,
				stt_dateOfRequest,
				stt_Note,
				soh_bra_id,
				soh_id

			)

			VALUES
			(

				@comp_id,
				@bra_id,
				@stor_id,
				@item_id,
				@stt_qty,
				NULL,
				NULL,
				@stt_isCompleted,
				@stt_isRejected,
				NULL,
				NULL,
				NULL,
				@stor_id_from,
				@user_id_Request,
				@stt_isRequestPending,
				getdate(),
				@stt_Note,
				NULL,
				NULL

			)

				SET @return_value = @@IDENTITY

		END
	ELSE
		BEGIN
			SET @return_value = -1
		END

END
GO







