				@stt_qty,
				NULL,
				NULL,
				@stt_isCompleted,
				@stt_isRejected,
				NULL,
				NULL,
				NULL,
				@stor_id_from,
				@user_id_Request,
				@stt_isRequestPending,
				getdate(),
				@stt_Note,
				NULL,
				NULL

			)

				SET @return_value = @@IDENTITY

		END
	ELSE
		BEGIN
			SET @return_value = -1
		END

END
