--Author:		GA.
--Create date: 10/06/2013.
--Description:	Transferencia internas de mercaderias . AGREGAR REQUERIMIENTO ENVIO por pedido
-----------------------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spStorage_TransferConfiguration4SaleOrder_InsertData]
(

	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@stor_id				INT,
	@user_id_Sender			INT,
	@user_id_Receptor		INT,
	@stt_isCompleted		bit,
	@stt_isRejected			bit,
	@stt_dateOfSending		datetime,
	@stt_dateOfComplete		datetime,
	@stt_dateOfReject		datetime,
	@stor_id_from			INT,
	@user_id_Request		INT,
	@stt_isRequestPending	bit,
	@stt_dateOfRequest		datetime,
	@stt_Note				nvarchar(2000),
	@soh_bra_id				int,
	@soh_id					int,
	@prof_id				int,
	@return_value			INT OUTPUT

)
as



BEGIN


	set nocount on

	--SET @return_value = 0


--------------------------------------------------------
-------------parametros de prueba-----------------------
-------------------------------------------------------
/*

DECLARE		@comp_id				INT,
			@lang_id				INT,
			@bra_id					INT,
			@stor_id				INT,
			@user_id_Sender			INT,
			@user_id_Receptor		INT,
			@stt_isCompleted		bit,
			@stt_isRejected			bit,
			@stt_dateOfSending		datetime,
			@stt_dateOfComplete		datetime,
			@stt_dateOfReject		datetime,
			@stor_id_from			INT,
			@user_id_Request		INT,
			@stt_isRequestPending	bit,
			@stt_dateOfRequest		datetime,
			@stt_Note				nvarchar(2000),
			@soh_bra_id				int,
			@soh_id					int,
			@prof_id				int,
			@return_value			INT


SELECT		@comp_id				= 1,
			@lang_id				= 2,
			@bra_id					= 1,
			@stor_id				= 4,
			@user_id_Sender			= 1,
			@user_id_Receptor		= 1,
			@stt_isCompleted		= 'false',
			@stt_isRejected			= 'false',
			@stt_dateOfSending		= '2013-06-24',
			@stt_dateOfComplete		= '2013-06-24',
			@stt_dateOfReject		= '2013-06-24',
			@stor_id_from			= 10,
			@user_id_Request		= 1,
			@stt_isRequestPending	= 'true',
			@stt_dateOfRequest		= '2013-06-24',
			@stt_Note				= 'C',
			@soh_Bra_id				= 1,
			@soh_id					= 32943,
			@prof_id				= 1
*/
--------------------------------------------------------
--------------------------------------------------------
--------------------------------------------------------

	declare @lintstor_id INT

	declare @lSaleOrder_Storage_Error BIT

	SET		@lSaleOrder_Storage_Error = 'False'

	declare @lSaleOrder_Stock_Error BIT

	SET		@lSaleOrder_Stock_Error = 'False'

	declare @lSaleOrder_Stock_Error_Items NVARCHAR(200)

	SET		@lSaleOrder_Stock_Error_Items = ''


	--SELECT @lSaleOrder_Storage_Error

	-- ---------------------------------------------
	-- Crea una tabla temporal para ser usada en el cursor
	-- ---------------------------------------------
		declare @tbStorage_TransferTransactions  TABLE (
														[comp_id] [int] NOT NULL,
														[stor_id] [int] NULL,
														[item_id] [int] NULL,
														[stt_qty] [decimal](19, 4) NULL,
														[user_id_Sender] [int] NULL,
														[user_id_Receptor] [int] NULL,
														[stt_isCompleted] [bit] NULL,
														[stt_isRejected] [bit] NULL,
														[stt_dateOfSending] [datetime] NULL,
														[stt_dateOfComplete] [datetime] NULL,
														[stt_dateOfReject] [datetime] NULL,
														[stor_id_From] [int] NULL,
														[bra_id] [int] NULL,
														[ct_transaction] [int] NULL,
														[user_id_Request] [int] NULL,
														[stt_isRequestPending] [bit] NULL,
														[stt_dateOfRequest] [datetime] NULL,
														[stt_Note] [nvarchar](2000) NULL,
														[soh_bra_id] [int] NULL,
														[soh_id] [int] NULL)

	-- ---------------------------------------------




	--declare para el cursor
	DECLARE @litem_id INT ,@lqty_id INT, @lstor_id INT

	--cursor para recorrer SaleOrderDetail
	DECLARE stock_storage CURSOR LOCAL FAST_FORWARD FOR

			SELECT  ti.item_id,
					tsod.sod_qty,
					tsod.stor_id

				FROM   tbSaleOrderDetail			tsod			WITH (NOLOCK)

				inner join tbStorage				ts				WITH (NOLOCK)
				on  ts.comp_id  = tsod.comp_id and
				    ts.stor_id  = tsod.stor_id

				inner join tbItem					ti				WITH (NOLOCK)
				on  ti.comp_id  = tsod.comp_id and
				    ti.item_id  = tsod.item_id

				where tsod.comp_id		= @comp_id		AND
					  tsod.bra_id		= @soh_bra_id	AND
				      tsod.soh_id		= @soh_id




		OPEN stock_storage

		-- lectura anticipada del cursor
		FETCH stock_storage INTO @litem_id,@lqty_id,@lstor_id
		WHILE @@FETCH_STATUS = 0
		BEGIN


			IF @lstor_id <> @stor_id -- Si el HACIA deposito es diferente al del pedido, cancela
				BEGIN
					SET		@lSaleOrder_Storage_Error = 'True'
				END

				set	@lintstor_id	= null
				set	@lintstor_id	= (	SELECT top 1	tstcr.stor_id
											FROM	tbStorage_TransferConfiguration4Request tstcr  WITH (NOLOCK)
											where   tstcr.comp_id	= @comp_id
											and		tstcr.bra_id	= @bra_id
											and		tstcr.prof_id	= @prof_id
											and		tstcr.[user_id] = @user_id_Request
											and		(dbo.fnGetAStock(@comp_id,tstcr.stor_id,@litem_id, 9999999999) /*- dbo.fnGetStorageTransfer_Pending(@comp_id,tstcr.stor_id,@litem_id)*/) >= @lqty_id
											order by
													case when tstcr.stor_id  = @stor_id_from then -99999 end ASC,
													case when tstcr.stor_id <> @stor_id_from then tstcr.stc4r_order end ASC

										)

				if @lintstor_id is NULL
				BEGIN
					SET		@lSaleOrder_Stock_Error = 'True'
					SET		@lSaleOrder_Stock_Error_Items = LTRIM(@lSaleOrder_Stock_Error_Items + ' ( ' +  ( SELECT ti.item_code
					   																						  FROM tbItem							ti
					   																						  WHERE	ti.comp_id = @comp_id	AND
					   																								ti.item_id = @litem_id
																											 )+ ' ) '
																	)
				END

				if @lintstor_id is NOT NULL

						insert into @tbStorage_TransferTransactions

							(
								comp_id,
								bra_id,
								stor_id,
								item_id,
								stt_qty,
								user_id_Sender,
								user_id_Receptor,
								stt_isCompleted,
								stt_isRejected,
								stt_dateOfSending,
								stt_dateOfComplete,
								stt_dateOfReject,
								stor_id_From,
								user_id_Request,
								stt_isRequestPending,
								stt_dateOfRequest,
								stt_Note,
								soh_bra_id,
								soh_id

							)

							VALUES
							(

								@comp_id,
								@bra_id,
								@stor_id,
								@litem_id,
								@lqty_id,
								NULL,
								NULL,
								@stt_isCompleted,
								@stt_isRejected,
								NULL,
								NULL,
								NULL,
								@lintstor_id,
								@user_id_Request,
								@stt_isRequestPending,
								getdate(),
								@stt_Note,
								@soh_bra_id,
								@soh_id

							)

								SET @return_value = @@IDENTITY



			FETCH stock_storage INTO @litem_id,@lqty_id,@lstor_id
		END
		CLOSE stock_storage
		DEALLOCATE stock_storage


		if @lSaleOrder_Storage_Error = 'True'
			BEGIN
				SET @return_value = -1

				SELECT @return_value [Value],(select tut.utexts_desc FROM tbsysUniqueTexts tut WITH (NOLOCK) WHERE tut.lang_id = @lang_id AND tut.utexts_id = 29001) [Error]
			END
		ELSE

			if @lSaleOrder_Stock_Error = 'True'
			BEGIN
				SET @return_value = -2

				SELECT @return_value [Value], @lSaleOrder_Stock_Error_Items [Error]
			END

		ELSE

			BEGIN

					insert into tbStorage_TransferTransactions

						(
							comp_id,
							bra_id,
							stor_id,
							item_id,
							stt_qty,
							user_id_Sender,
							user_id_Receptor,
							stt_isCompleted,
							stt_isRejected,
							stt_dateOfSending,
							stt_dateOfComplete,
							stt_dateOfReject,
							stor_id_From,
							user_id_Request,
							stt_isRequestPending,
							stt_dateOfRequest,
							stt_Note,
							soh_bra_id,
							soh_id

						)

						SELECT
							comp_id,
							bra_id,
							stor_id,
							item_id,
							stt_qty,
							user_id_Sender,
							user_id_Receptor,
							stt_isCompleted,
							stt_isRejected,
							stt_dateOfSending,
							stt_dateOfComplete,
							stt_dateOfReject,
							stor_id_From,
							user_id_Request,
							stt_isRequestPending,
							stt_dateOfRequest,
							stt_Note,
							soh_bra_id,
							soh_id

						FROM @tbStorage_TransferTransactions

						SET @return_value = 0

						SELECT @return_value [Value],' ' [Error]

				END





END
GO







