--Create date: 03/04/2013.
--Description:	Transferencia internas de mercaderias . ANULAR ENVIO
------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spStorage_TransferConfiguration4Send_DeleteData]
(

	@comp_id			INT,
	@stt_id				INT

)
as



BEGIN


	-----------------------------------------
	-- parametros de test
	-----------------------------------------
	/*
	declare @comp_id INT,
			@stt_id  int


	select @comp_id			= 1,
		   @stt_id			= 2
	*/
	-----------------------------------------
	-- parametros de test
	-----------------------------------------

	IF EXISTS(

				select 1
					from tbStorage_TransferTransactions			WITH (NOLOCK)
					where	comp_id			= @comp_id	AND
							stt_id			= @stt_id	AND
							stt_isCompleted = 'false'	AND
							stt_isRejected  = 'false'

			 )

		BEGIN

			delete from tbStorage_TransferTransactions
				where	comp_id			= @comp_id	AND
						stt_id			= @stt_id

		END


END


GO









CREATE PROCEDURE [dbo].[spStorage_TransferConfiguration4Send_getCombo]
(
	@comp_id			int	,
	@bra_id				INT,
	@prof_id			INT		,
	@user_id			INT
)
as



	select		distinct ts.stor_id	[id],
				ts.stor_desc		[desc]

	from		dbo.tbStorage							ts			WITH (NOLOCK)

	inner join tbStorage_TransferConfiguration4Send		tstcs		WITH (NOLOCK)
	on  tstcs.comp_id	= ts.comp_id and
		tstcs.stor_id	= ts.stor_id AND
		tstcs.[user_id] = @user_id AND
		tstcs.prof_id   = @prof_id AND
		tstcs.bra_id	= @bra_id

	where		ts.comp_id =	@comp_id
--	AND			ts.stor_id NOT IN (SELECT tstc.stor_id
--									 FROM tbStorage_TransferConfiguration tstc
--									 WHERE tstc.comp_id = ts.comp_id
--									 AND  tstc.stor_id = ts.stor_id)

	Order By	stor_desc






GO








------------------------------------------------------------------------------
--Author:		GA.
--Create date: 26/03/2013.
--Description:	Transferencia internas de mercaderias . grilla enviar.
------------------------------------------------------------------------------


CREATE PROCEDURE [dbo].[spStorage_TransferConfiguration4Send_getDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@option				INT,
	@soh_Bra_id			int,
	@soh_id				int,
	@stor_id_to			int

)
AS

SET NOCOUNT ON


BEGIN

set nocount on
set dateformat 'ymd'


--------------------------------------------------------
-------------parametros de prueba-----------------------
-------------------------------------------------------
/*
DECLARE		@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@prof_id			INT,
			@user_id			INT,
			@option				INT,
			@soh_Bra_id			int,
			@soh_id				INT,
			@stor_id_to			int


SELECT		@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 1,
			@option				= -1,
			@soh_Bra_id			= 0,
			@soh_id				= 0,
			@stor_id_to			=-1

*/
--------------------------------------------------------
--------------------------------------------------------
--------------------------------------------------------




	-- Pongo en una temporal los depositos en los que puedo recibir con mi perfil.
	DECLARE @tmpStorage4Recive TABLE(stor_id INT PRIMARY KEY)
	INSERT INTO @tmpStorage4Recive
	SELECT distinct tstc.stor_id
		FROM tbStorage_TransferConfiguration tstc			WITH (NOLOCK)
		WHERE	tstc.comp_id	= @comp_id AND
				tstc.bra_id		= @bra_id  AND
				tstc.[user_id]	= @user_id AND
				tstc.prof_id	= @prof_id


	select  ' ' [ ],
			' ' [ ],
			tu.user_lastname + ', ' + tu.user_firstname							[from_User_name],
			tsfrom.stor_desc													[stor_From],
			tsTo.stor_desc														[stor_To],
			ti.item_code  + ' - ' +  ti.item_desc								[item_desc],
			tstt.stt_qty														[stt_qty],
			tov.optval_desc														[stt_isCompleted],
			tov2.optval_desc													[stt_isRejected],
			tstt.stt_dateOfSending												[stt_dateOfSending],
			tstt.stt_dateOfComplete												[stt_dateOfComplete],
			tstt.stt_dateOfReject												[stt_dateOfReject],
			tstt.stt_Note														[stt_Note],
			tu2.user_lastname + ', ' + tu2.user_firstname						[User_Request],
			tov3.optval_desc													[stt_isRequestPending],
			tstt.stt_dateOfRequest												[stt_dateOfRequest],
			tstt.soh_bra_id														[soh_bra_id],
			tstt.soh_id															[soh_id],
			IsNull(tisFrom.itst_cant,0)											[Stock_From],
			ISNULL(tisTo.itst_cant,0)											[Stock_To],
			tstt.stt_id															[ID]


		from tbStorage_TransferTransactions					tstt			WITH (NOLOCK)

		inner join tbStorage								tsTo			WITH (NOLOCK)
		on  tsTo.comp_id = tstt.comp_id
		and tsTo.stor_id = tstt.stor_id

		inner join tbStorage								tsFrom			WITH (NOLOCK)
		on  tsFrom.comp_id = tstt.comp_id
		and tsFrom.stor_id = tstt.stor_id_From

		inner join tbItem									ti				WITH (NOLOCK)
		on  ti.comp_id = tstt.comp_id
		AND ti.item_id = tstt.item_id

		left join tbUser									tu				WITH (NOLOCK)
		on tu.[user_id] = tstt.user_id_Receptor

		left join tbUser									tu2				WITH (NOLOCK)
		on tu2.[user_id] = tstt.user_id_Request

		inner join tbsysOptionsValues						tov				WITH (NOLOCK)
		on  tov.lang_id			= @lang_id
		and tov.optval_id		= tstt.stt_isCompleted
		and tov.optval_class	= 1

		inner join tbsysOptionsValues						tov2			WITH (NOLOCK)
		on  tov2.lang_id		= @lang_id
		and tov2.optval_id		= tstt.stt_isRejected
		and tov2.optval_class	= 1

		inner join tbsysOptionsValues						tov3			WITH (NOLOCK)
		on  tov3.lang_id		= @lang_id
		and tov3.optval_id		= tstt.stt_isRequestPending
		and tov3.optval_class	= 1


		INNER JOIN @tmpStorage4Recive tmp
		ON	tmp.stor_id = tstt.stor_id_From

		LEFT  JOIN tbItemStorage tisFrom									WITH (NOLOCK)
			ON	tisFrom.comp_id = @comp_id			AND
				tisFrom.stor_id = tstt.stor_id_From AND
				tisFrom.item_id = tstt.item_id

		LEFT  JOIN tbItemStorage tisTo										WITH (NOLOCK)
			ON	tisTo.comp_id   = @comp_id			AND
				tisTo.stor_id   = tstt.stor_id		AND
				tisTo.item_id   = tstt.item_id


	Where	tstt.comp_id		= @comp_id
	--AND		tstt.bra_id			= @bra_id
	--AND		(tstt.user_id_Sender	= @user_id or tstt.user_id_Request = @user_id)
	AND		(
			(@option = -1) or
			(@option = 1 and tstt.stt_isCompleted = 'False' and tstt.stt_isRejected = 'False' ) or
			(@option = 2 and tstt.stt_isCompleted = 'true' ) or
			(@option = 3 and tstt.stt_isRejected = 'true')
			)
	AND		(@soh_Bra_id = 0 OR @soh_id = 0 or tstt.soh_bra_id = @soh_Bra_id and tstt.soh_id = @soh_id)

	AND		(@stor_id_to = -1 or tsTo.stor_id = @stor_id_to)




END





GO







------------------------------------------------------------------------------
--Author:		GA.
--Create date: 03/04/2013.
--Description:	Transferencia internas de mercaderias . AGREGAR ENVIO
------------------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spStorage_TransferConfiguration4Send_InsertData]
(

	@comp_id			int,
	@bra_id				INT,
	@stor_id			int,
	@item_id			int,
	@stt_qty			decimal(19,4),
	@user_id_Sender		int,
	@user_id_Receptor   int,
	@stt_isCompleted    bit,
	@stt_isRejected		bit,
	@stt_dateOfSending	datetime,
	@stt_dateOfComplete datetime,
	@stt_dateOfReject   datetime,
	@stor_id_from		int,
	@stt_note			nvarchar(2000),
	@return_value		INT OUTPUT

)
as



BEGIN

	insert into tbStorage_TransferTransactions
	(
		comp_id,
		bra_id,
		stor_id,
		item_id,
		stt_qty,
		user_id_Sender,
		user_id_Receptor,
		stt_isCompleted,
		stt_isRejected,
		stt_dateOfSending,
		stt_dateOfComplete,
		stt_dateOfReject,
		stor_id_From,
		stt_isRequestPending,
		stt_Note
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@stor_id,
		@item_id,
		@stt_qty,
		@user_id_Sender,
		null,
		@stt_isCompleted,
		@stt_isRejected,
		getdate(),
		NULL,
		NULL,
		@stor_id_from,
		'False',
		@stt_note

	)

		SET @return_value = @@IDENTITY


END
GO






