CREATE PROCEDURE [dbo].[spStorage_TransferTransactions_getDataById]
(
	@comp_id			INT,
	@stt_id				INT
)
AS


	SET NOCOUNT ON


BEGIN

	--------------------------------------------------------
	-------------parametros de prueba-----------------------
	--------------------------------------------------------
	/*
	declare		@comp_id		INT,
				@stt_id			INT

	select		@comp_id		= 1,
				@stt_id			= 77
	*/
	--------------------------------------------------------
	--------------------------------------------------------
	--------------------------------------------------------


	SELECT  tstt.comp_id,
			tstt.stt_id,
			tstt.stor_id,
			tstt.item_id,
			tstt.stt_qty,
			isnull(tstt.user_id_Sender,'') [user_id_Sender],
			isnull(tstt.user_id_Receptor,'') [user_id_Receptor],
			isnull(tstt.stt_isCompleted,'False') [stt_isCompleted],
			isnull(tstt.stt_isRejected,'False') [stt_isRejected],
			tstt.stt_dateOfSending ,
			tstt.stt_dateOfComplete,
	        tstt.stt_dateOfReject,
			tstt.stor_id_From,
			isnull(tstt.user_id_Request,'') [user_id_Request],
			isnull(tstt.stt_isRequestPending,'') [stt_isRequestPending],
			tstt.stt_dateOfRequest,
			tstt.stt_Note

	from tbStorage_TransferTransactions tstt		WITH (NOLOCK)

	WHERE	tstt.comp_id		= @comp_id
	AND		tstt.stt_id			= @stt_id

END



GO







CREATE PROCEDURE [dbo].[spStorage_TransferTransactions_InsertOneData]
(
	@comp_id							as int,
	@bra_id								as int,
	@ct_transaction						as int,
	@item_id							as Int,
	@it_qty								as decimal(19,5),
	@curr_id							as int,
	@stor_id							as Int
)
AS

	SET NOCOUNT ON

/*
Declare
	@comp_id							as Int,
	@bra_id								as int,
	@ct_transaction						as int,
	@item_id							as Int,
	@it_qty								as decimal(19,5),
	@curr_id							as int,
	@stor_id							as Int,

	@return_value						as int			,
	@ret_ErrorCode						as int			,
	@ret_ErrorDescription				as varchar(200)
Select  @comp_id							=1,
	@bra_id								=1,
	@ct_transaction						=1876,
	@item_id							=282,
	@it_qty								=10,
	@curr_id							=1,
	@stor_id							=4
*/


/* recuperamos el stock anterior para cagarlo en itemtransaction */
declare @it_storePrevious as decimal(19,5)



If Exists (Select 1
           From	tbItemStorage tis		WITH (NOLOCK)
			Where	tis.comp_id = @comp_id
			And		tis.stor_id = @stor_id
			And		tis.item_id = @item_id)

	Select	@it_storePrevious = tis.itst_cant
	From	tbItemStorage tis		WITH (NOLOCK)
	Where	tis.comp_id = @comp_id
	And		tis.stor_id = @stor_id
	And		tis.item_id = @item_id

Else
	Begin
		Insert into tbItemStorage
		(	comp_id,stor_id,item_id,itst_cant,itst_cd)
		VALUES
		(	@comp_id,@stor_id,@item_id,0,Getdate())

		Set @it_storePrevious = 0
	End


		Insert Into dbo.tbItemTransactions
			(
				comp_id,
				bra_id,
				ct_transaction,
				it_cd,
				it_packingInvoicePend,
				item_id,
				it_qty,
				it_priceWithOutOthers,
				it_price,
				curr_id,
				it_priceOfCost,
				it_priceOfCostPP,
				it_priceOfCostLastPurchase,
				it_priceBOfCost,
				it_priceBOfCostPP,
				it_priceBOfCostLastPurchase,
				it_OriginalPrice,
				it_OriginalPriceCurrency,
				stor_id,
				it_storePrevious,
				prli_id,
				byor_id,
				it_isProduction,
				it_isAssociation,
				it_order,
				so_id,
				it_guarantee,
				it_exchangeToOriginalPriceCurrency,
				it_itemDiscountTotal,
				it_totalDiscountTotal,
				it_CreditInt,
				it_CreditIntPlus
			 )
			Values
			(
				@comp_id,
				@bra_id,
				@ct_transaction,
				getdate(),
				'false',
				@item_id,
				@it_qty,
				0,
				0,
				@curr_id,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				@curr_id,
				@stor_id,
				@it_storePrevious,
				NULL,
				NULL,
				'false',
				'false',
				0,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL
			 )



GO







CREATE Procedure [dbo].[spStorage_TransferTransactions_SaleOrder_getData]
(

	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@soh_id				INT,
	@item_id			INT,
	@stor_id			INT



)
AS



BEGIN

	set nocount On

	-- - ---------------------------------------------------------------------------------------
	-- - Testing
	-- - ---------------------------------------------------------------------------------------
	/*
	declare			@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@prof_id			INT,
					@user_id			INT,
					@soh_id				INT,
					@item_id			INT,
					@stor_id			INT



	Select			@comp_id		=1,
					@lang_id		=2,
					@stor_id		=-1,
					@bra_id			=-1,
					@user_id		=-1,
					@item_id		=-1,
					@coslis_id		=-1,
					@soh_id			=-1

*/
	-- - ---------------------------------------------------------------------------------------




--select * from tbSaleOrderDetail tsod

--select * from tbSaleOrderHeader tsoh


--recorrer la tbSaleOrderDetail
--filtrando por Compañía, Sucursal, Soh_id y por cada ítem
--busque en los depósitos en el orden que da la tabla



DECLARE @litem_id INT ,@lqty_id INT ,@lstor_id int

DECLARE stock_storage CURSOR  LOCAL FAST_FORWARD FOR



		SELECT  ti.item_id,
				tis.itst_cant,
				ts.stor_id

		FROM   tbSaleOrderDetail			tsod			WITH (NOLOCK)

		inner join tbStorage				ts				WITH (NOLOCK)
		on  ts.comp_id  = tsod.comp_id
		AND ts.stor_id  = tsod.stor_id

		inner join tbItem					ti				WITH (NOLOCK)
		on  ti.comp_id  = tsod.comp_id
		and ti.item_id  = tsod.item_id

		inner join tbItemStorage			tis				WITH (NOLOCK)
		on  tis.comp_id = ts.comp_id
		and tis.stor_id = ts.stor_id
		AND	tis.item_id = ti.item_id

		where tsod.comp_id		= @comp_id
		and   tsod.soh_id		= @soh_id
		and   tsod.bra_id		= @bra_id




	OPEN stock_storage
	FETCH stock_storage INTo @litem_id,@lqty_id,@lstor_id
	WHILE @@FETCH_STATUS = 0
	BEGIN









		FETCH stock_storage INTo @litem_id,@lqty_id,@lstor_id
	END
	CLOSE stock_storage
	DEALLOCATE stock_storage










END
GO






-- =================================================================
-- Author:		GA
-- Da de alta el articulo en el deposito o actualiza la cantidad
-- =================================================================

CREATE  PROCEDURE [dbo].[spStorage_TransferTransactions_updateQty]
(
	@comp_id					As Int,
	@item_id					As Int,
	@stor_id					As Int,
	@itst_cant					As Decimal(18,4)

)

as


	set nocount ON

BEGIN







	IF NOT EXISTS (	SELECT	1
	              	FROM	tbItemStorage tis				WITH (NOLOCK)
	              	WHERE 	tis.comp_id = @comp_id
	              	AND		tis.item_id = @item_id
             		AND		tis.stor_id = @stor_id )

		-- Da de alta si no existe el item en el deposito
		INSERT INTO tbItemStorage
		(
			comp_id,
			stor_id,
			item_id,
			itst_cant,
			itst_cd
		)
		VALUES
		(
			@comp_id,
			@stor_id,
			@item_id,
			@itst_cant,
			GETDATE()
		)

	ELSE

		-- Actualiza la cantidad
		UPDATE	tbItemStorage
		SET		itst_cant	= (itst_cant + @itst_cant)
		WHERE	comp_id		= @comp_id
		AND		stor_id		= @stor_id
		AND		item_id		= @item_id


END
GO




-- =============================================
-- Author:		MOS
-- Create date: 07-2013
-- Description:	Actualiza stock en transito
-- segun los remitos de transferencia no ingresados
-- que sean del mismo deposito totalizador
-- =============================================


CREATE PROCEDURE [dbo].[spStorage_updateInTransitStock]
	@comp_id	AS INT,
	@df_id		AS INT
AS


BEGIN


	-- -------------------------------------------
	-- -------------------------------------------
/*
	DECLARE 	@comp_id	AS INT,
				@df_id		AS INT
	SET @comp_id = 1
	SET @df_id	 = 283
*/
	-- -------------------------------------------



	SET NOCOUNT ON;

	-- Busca si el documento original tiene un deposito totalizador
	DECLARE @sotr_id4BranchTransferTotalizer AS INT
	SET		@sotr_id4BranchTransferTotalizer	= NULL
	SELECT	@sotr_id4BranchTransferTotalizer	= tdf.sotr_id4BranchTransferTotalizer
		FROM tbDocumentsFile tdf		WITH (NOLOCK)
		INNER JOIN tbStorage ts			WITH (NOLOCK)
			ON	ts.comp_id									= tdf.comp_id							AND
				ts.stor_id									= tdf.sotr_id4BranchTransferTotalizer
		WHERE	tdf.comp_id									= @comp_id	AND
				tdf.df_id									= @df_id	AND
				tdf.df_isInterBranchDocument				= 1			AND
				ts.stor_isAvailable4BranchTransferTotalizer	= 1



	IF @sotr_id4BranchTransferTotalizer IS NOT NULL
		BEGIN



			SELECT	tit.comp_id,
					tit.item_id,
					sum(tit.it_qty) [Qty]
				INTO #tmpIntransit
				FROM tbItemTransactions tit								WITH (NOLOCK)
				INNER JOIN tbCommercialTransactions tct					WITH (NOLOCK)
					ON	tct.comp_id			= tit.comp_id	AND
						--tct.bra_id			= tit.bra_id	AND  MOS 01-2020
						tct.ct_transaction	= tit.ct_transaction

				INNER JOIN tbDocumentsFile tdf							WITH (NOLOCK)
					ON	tdf.comp_id			= tct.comp_id	AND
						tdf.df_id			= tct.df_id

				INNER JOIN tbCustomer tc								WITH (NOLOCK)
					ON	tc.comp_id			= tct.comp_id	AND
						tc.cust_id			= tct.cust_id

			WHERE	tct.comp_id							= @comp_id		AND
					tct.ct_Pending						= 1				AND
					ISNULL(tct.ct_isCancelled,'False')	= 'False'		AND
					tct.sd_id							= 2				AND
					tc.cust_SaleOrderBranchTransfer		= 1				AND
					tdf.df_isInterBranchDocument		= 1				AND
					tdf.sotr_id4BranchTransferTotalizer = @sotr_id4BranchTransferTotalizer	AND
					tit.item_id							IS NOT NULL
			GROUP BY tit.comp_id,tit.item_id


			CREATE NONCLUSTERED INDEX ix_tmpIntransit ON #tmpIntransit (comp_id,item_id)  -- MOS 05-2020



			-- Inserta items que no esten en ese deposito
			INSERT INTO tbItemStorage	WITH (ROWLOCK)
			(
				comp_id,
				stor_id,
				item_id,
				itst_cant,
				itst_cd,
				itst_PickingLocation,
				itst_StorageLocation
			)
			SELECT	tmp.comp_id,
					@sotr_id4BranchTransferTotalizer,
					tmp.item_id,
					0,
					GETDATE(),
					'',
					''
				FROM #tmpIntransit		tmp
				LEFT JOIN tbitemstorage tis	WITH (NOLOCK)		-- MOS 01-2020
					ON tis.comp_id = tmp.comp_id						AND
					   tis.stor_id = @sotr_id4BranchTransferTotalizer	AND
					   tis.item_id = tmp.item_id
				WHERE  tis.comp_id IS NULL								--AND
					   --tmp.item_id IS NOT NULL

			--WHERE NOT EXISTS(	SELECT 1
			--                 		FROM tbItemStorage tis	WITH (NOLOCK)
			--                 		WHERE	tis.comp_id = tmp.comp_id AND
			--                 				tis.stor_id = @sotr_id4BranchTransferTotalizer AND
			--                 				tis.item_id = tmp.item_id )
			--          AND
			--      tmp.item_id IS NOT NULL


			-- Pone en 0 el stock del deposito TOTALIZADOR y deja una marca x las dudas diciendo q se actualizo por aquí
			SET CONTEXT_INFO 0x784435  -- DISABLE TRIGGER  MOS 01-2020  (Es como una variable de sesion de sql)
			UPDATE tbItemStorage	WITH (ROWLOCK)
				SET
					itst_cant					= 0,
					itst_updateByInTransitStock = 1
				WHERE	comp_id = @comp_id							AND
						stor_id = @sotr_id4BranchTransferTotalizer	AND
						itst_cant <> 0
			SET CONTEXT_INFO 0x

			-- Actualiza el Stock en transito.
			SET CONTEXT_INFO 0x784435
			UPDATE tbItemStorage	WITH (ROWLOCK)
				SET
					itst_cant = IsNull(tmp.Qty,0)
				FROM  tbItemStorage			its
				INNER JOIN #tmpIntransit	tmp
					ON	tmp.comp_id = its.comp_id AND
						tmp.item_id = its.item_id
			WHERE	its.comp_id = @comp_id AND
					its.stor_id = @sotr_id4BranchTransferTotalizer
			SET CONTEXT_INFO 0x

			DROP TABLE #tmpIntransit

		END






END
GO





CREATE PROCEDURE [dbo].[spStorageCheckStock_PriceLabel_ComplexFilter]
	@comp_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@guid				UNIQUEIDENTIFIER,
	@stor_id			INT


AS


-- -----------------------------------------------------
--
-- -----------------------------------------------------
/*

DECLARE 		@comp_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@guid				UNIQUEIDENTIFIER,
				@stor_id			INT

SELECT			@comp_id			=1,
				@bra_id				=1,
				@prof_id			=1,
				@user_id			=1,
				@guid				='567B82E9-A855-43F2-AF11-AB06152EA021',
				@stor_id			=2

*/
-- -----------------------------------------------------





BEGIN

	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	DECLARE @tmpItemWithOutStock TABLE(item_id INT PRIMARY KEY)

	 --Recupero los items seleccionados en la complex filter que no tienen stock
	INSERT INTO @tmpItemWithOutStock (item_id)	SELECT tcf.sl_id
	                                          	FROM tbComplexFilter						tcf		WITH (NOLOCK)

	                                          	INNER JOIN tbItemStorage					tis		WITH (NOLOCK)
												ON tis.comp_id = @comp_id		AND
												   tis.stor_id = @stor_id		AND
												   tis.item_id = tcf.sl_id

                                         		WHERE  tcf.sl_guid	  = @guid	AND
                                         			   tis.itst_cant <= 0



	-- -------------------------------------------------------------------------------------


			--declare para el cursor
			DECLARE @litem_id INT

			DECLARE cursor_ItemWithOutStock CURSOR LOCAL FAST_FORWARD FOR

					SELECT item_id

					FROM @tmpItemWithOutStock

				OPEN cursor_ItemWithOutStock

				-- lectura anticipada del cursor
				FETCH cursor_ItemWithOutStock INTO @litem_id
				WHILE @@FETCH_STATUS = 0
				BEGIN

						--DELETE FROM tbComplexFilter

						--WHERE sl_guid	= @guid AND
						--	  sl_id		= @litem_id


							  UPDATE tbComplexFilter
							  SET
							  	sl_selected = 'False'

							  WHERE sl_guid		= @guid AND
									sl_id		= @litem_id

						FETCH cursor_ItemWithOutStock INTO @litem_id


			END

			CLOSE cursor_ItemWithOutStock
			DEALLOCATE cursor_ItemWithOutStock


END
GO
















