CREATE PROCEDURE [dbo].[spStoragePositions_GetCombo4TransferOrigin]
(
	@comp_id	INT,
	@stor_id	INT,
	@item_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@stor_id	INT,
				@item_id	INT
			SELECT
				@comp_id	= 1,
				@stor_id	= 807,
				@item_id	= 16084
		*/
		-- ------------------------------------------------

		SELECT
			tsp.storp_nick	 + ' -> (' + dbo.fnStrAllTrim( CONVERT(VARCHAR(20), CONVERT(DECIMAL(19,2),tisp.itstp_cant)))  + ')'	[Desc],
			tsp.storp_id																				[Id]
			FROM tbStoragePositions											AS tsp	WITH(NOLOCK)

			INNER JOIN tbStoragePositionsRelations							AS tspr	WITH(NOLOCK)
				ON	tspr.comp_id						= tsp.comp_id		AND
					tspr.storp_id						= tsp.storp_id

			INNER JOIN tbItemStoragePositions								AS tisp	WITH(NOLOCK)
				ON	tisp.comp_id						= tspr.comp_id		AND
					tisp.stor_id						= tspr.stor_id		AND
					tisp.storp_id						= tspr.storp_id		AND
					tisp.item_id						= @item_id

			WHERE	tspr.comp_id						= @comp_id			AND
					tspr.stor_id						= @stor_id			AND
					ISNULL(tsp.storp_disabled,'False')	= 'False'			AND
					tisp.itstp_cant						> 0

	END





GO


--LOG STL 10-09-2024 Más adelante hay que ver de que no tome posiciones que ya tengan otro artículo y que soporten solo 1 artículo


CREATE PROCEDURE [dbo].[spStoragePositions_GetComboByStorID]
(
	@comp_id	INT,
	@stor_id	INT,
	@posNick	NVARCHAR(30)
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@stor_id	INT,
				@posNick	NVARCHAR(50)
			SELECT
				@comp_id	= 1,
				@stor_id	= 809,
				@posNick	= 'WMS-POS-TEST-2'
		*/
		-- ------------------------------------------------
		SET @posNick = dbo.fnStrAllTrim(@posNick)

		SELECT TOP 50
			tsp.storp_nick											[Desc],
			tsp.storp_id											[Id]
			FROM tbStoragePositions									AS tsp	WITH(NOLOCK)
			INNER JOIN tbStoragePositionsRelations					AS tspr	WITH(NOLOCK)
				ON	tspr.comp_id	= tsp.comp_id					AND
					tspr.storp_id	= tsp.storp_id
			WHERE	tspr.comp_id						= @comp_id	AND
					tspr.stor_id						= @stor_id	AND
					ISNULL(tsp.storp_disabled,'False')	= 'False'
			ORDER BY	CASE
							WHEN	tsp.storp_nick = @posNick	THEN	0
							ELSE										1
						END,
						tsp.storp_priority4Input





	END





GO


-- Log
-- MOS 09-2024: Trae depositos para salida manual que tengan stock disponible


CREATE PROCEDURE [dbo].[spStoragePositions_getComboByStorID4ManualOutputSelection]
(
	@comp_id		AS INT,
	@item_id		AS INT,
	@stor_id		AS INT,
	@storp_idActual	AS INT,
	@posNick		AS NVARCHAR(30),
	@decQTY			AS DECIMAL(19,4)
)
AS

	BEGIN

		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@stor_id	INT,
				@posNick	NVARCHAR(50)
			SELECT
				@comp_id	= 1,
				@stor_id	= 809,
				@posNick	= 'WMS-POS-TEST-2'
		*/
		-- ------------------------------------------------



		SET @posNick = dbo.fnStrAllTrim(@posNick)

		SELECT TOP 50
			tsp.storp_nick	+ ' -> (' + dbo.fnStrAllTrim( CONVERT(VARCHAR(20), CONVERT(DECIMAL(19,2),tisp.itstp_cant)))  + ')'							[Desc],
			tsp.storp_id								[Id]
			FROM		tbStoragePositions				AS tsp	WITH(NOLOCK)
			INNER JOIN	tbStoragePositionsRelations		AS tspr	WITH(NOLOCK)
				ON	tspr.comp_id	= tsp.comp_id		AND
					tspr.storp_id	= tsp.storp_id
			INNER JOIN	tbItemStoragePositions AS tisp
				ON	tisp.comp_id	= tsp.comp_id		AND
					tisp.storp_id	= tsp.storp_id		AND
					tisp.item_id	= @item_id			AND
					tisp.stor_id	= @stor_id
			LEFT JOIN	tbItemStoragePositionsTMP		AS tmp	WITH (NOLOCK)
				ON	tmp.comp_id		= tspr.comp_id		AND
					tmp.item_id		= @item_id			AND
					tmp.stor_id		= @stor_id			AND
					tmp.storp_id	= tspr.storp_id
			WHERE	tisp.comp_id						= @comp_id AND
					tisp.stor_id						= @stor_id AND
					ISNULL(tsp.storp_disabled,'False')	= 'False'  AND
					tisp.storp_id                       <> @storp_idActual
			GROUP BY  tsp.storp_nick, tsp.storp_id, tsp.storp_priority4Output,tisp.itstp_cant
			-- MOS 09-2024: Que muestre todas las que tiene disponible y en el poden 1ro las q tienen stock para TODO.  las parciales deberan dar error al validar.
			HAVING (
						tisp.itstp_cant -
						SUM(ISNULL(tmp.tmp_QTY, 0))
					) > 0
			--HAVING (
			--			tisp.itstp_cant -
			--			SUM(ISNULL(tmp.tmp_QTY, 0)) -
			--			@decQTY
			--		) > 0
			ORDER BY	CASE
							WHEN	tsp.storp_nick = @posNick	THEN	0
							ELSE										1
						END,
						CASE
							WHEN	(
										tisp.itstp_cant -
										SUM(ISNULL(tmp.tmp_QTY, 0)) -
										@decQTY
									) > 0									THEN 0
							ELSE 1
						END,
						tsp.storp_priority4Output






	END





GO

CREATE PROCEDURE [dbo].[spStoragePositionsGroups_GetCombo]
(
	@comp_id	INT
)
AS
	BEGIN
