CREATE PROCEDURE spSubCategory_getAllSubCategoriesAndCategories
(
	@comp_id	INT
)
AS
	SET	NOCOUNT ON

	BEGIN

		SELECT
			tc.cat_desc + '-' + tsc.subcat_desc [Desc],
			tsc.subcat_id						[Id]
		FROM tbCategory					tc

		INNER JOIN tbSubCategory		tsc
		ON	tsc.comp_id = tc.comp_id	AND
			tsc.cat_id	= tc.cat_id

		WHERE tc.comp_id	= @comp_id
		ORDER BY tc.cat_desc, tsc.subcat_desc

	END
GO







CREATE PROCEDURE [dbo].[spSubCategory_getCombo]
(
	@comp_id			int,
	@cat_id				int
)
AS

BEGIN



	set nocount on

	-- ------------------------------------------
	-- ------------------------------------------
	/*
	declare		@comp_id			int,
				@cat_id				int
	select 		@comp_id			= 1,
				@cat_id				= 3
	*/
	-- ------------------------------------------

	select		subcat_id			[id],
				subcat_desc			[desc]
		from		tbSubCategory	WITH (NOLOCK)
		where	comp_id = @comp_id
			and	(cat_id	= -1	or cat_id = @cat_id )
		order by	subcat_desc


END




GO







CREATE PROCEDURE [dbo].[spSubCategory_getData]
(
	@comp_id			INT,
    @cat_id				INT
)
AS
SET NOCOUNT ON

/*
DECLARE @comp_id			INT,
		@cat_id				INT
select	@comp_id			= 1,
		@cat_id				= -1
*/

	select	tsc.comp_id,
			tc.cat_desc,
			tsc.subcat_id,
			tsc.subcat_desc,
			tsc.cat_id,
			tsc.bra_id,
			ta.acc_desc,
			tsc.subcat_image,
			tsc.subcat_commission,
			isnull(tsc.subcat_web,'false')			[subcat_web],
			ISNULL(tsc.subcat_pcConfigType,-1)		[subcat_pcConfigType]

	 FROM	tbSubCategory						tsc

			INNER JOIN tbCategory				tc
			ON	tc.comp_id		= tsc.comp_id
			AND tc.cat_id		= tsc.cat_id

--			INNER JOIN tbItem					ti
--			ON	ti.comp_id		= tsc.comp_id
--			AND ti.cat_id		= tsc.cat_id
--			AND ti.subcat_id	= tsc.subcat_id

			LEFT JOIN tbAccountant				ta
			ON	ta.comp_id		= tsc.comp_id
			AND ta.acc_count_id = tsc.acc_count_id

	WHERE	tsc.comp_id = @comp_id
	AND		((@cat_id = -1) OR (tsc.cat_id = @cat_id))

	ORDER BY tc.cat_desc,
			tsc.subcat_desc









GO









CREATE PROCEDURE [dbo].[spSubCategory_getDataByItems]
(
	@comp_id				INT,
    @cat_id					INT,
	@stor_id				INT,
	@showzerostock			BIT,
	@potentialstocklimit	INT,
	@ws_id					INT
)
AS

BEGIN


	SET NOCOUNT ON


	-- ---------------------------------------------------------------------
	--  Testing
	-- ---------------------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@cat_id			INT,
			@stor_id		INT,
			@showzerostock	BIT,
			@potentialstocklimit INT
	SELECT 	@comp_id		= 1,
			@cat_id			= 1 ,
			@stor_id		= 1,
			@showzerostock	='false',
			@potentialstocklimit = 600
	*/
	-- ---------------------------------------------------------------------


	--ISNULL(tsc.subcat_WebSite_desc,tsc.subcat_desc)
	SELECT	--DISTINCT
			tsc.comp_id,
			REPLACE(tc.cat_desc, '''', ' ')				[cat_desc],
			tsc.subcat_id,
			REPLACE(dbo.fnGetWordsCutByChar(
					CASE WHEN tsc.subcat_WebSite_desc IS NULL				 THEN tsc.subcat_desc
						 WHEN LEN(LTRIM(RTRIM(tsc.subcat_WebSite_desc))) = 0 THEN tsc.subcat_desc
						 ELSE tsc.subcat_WebSite_desc
					END
					,' ',20), '''', ' ')				[subcat_desc],
			tsc.cat_id,
			tsc.bra_id,
			--ta.acc_desc,
			--tsc.subcat_image,
			tsc.subcat_commission,
			isnull(tsc.subcat_web,'false')				[subcat_web],
			isnull(tc.cat_web_order,999999999)			[cat_web_order],
			isnull(tsc.subcat_web_order,999999999)		[subcat_web_order]--,
			--CASE WHEN ti.brand_id IS NULL THEN 'false' ELSE 'true' END		[haveBrand]


	FROM	tbSubCategory						tsc

			INNER JOIN tbCategory				tc
			ON	tc.comp_id		= tsc.comp_id
			AND tc.cat_id		= tsc.cat_id
			AND isnull(tc.cat_web,'false')		= 'true'

			--LEFT JOIN tbItem					ti
			--ON	ti.comp_id		= tsc.comp_id
			--AND ti.subcat_id	= tsc.subcat_id
			--AND ti.cat_id		= tsc.cat_id


	WHERE	tsc.comp_id = @comp_id
	AND		((@cat_id = -1) OR (tsc.cat_id = @cat_id))
	AND		isnull(tsc.subcat_web,'false')		= 'true'

	AND		tsc.subcat_id IN (SELECT	ti.subcat_id
   								FROM	tbItem				ti
   								LEFT JOIN tbItemStorage tis
   									ON		tis.comp_id = ti.comp_id
   										AND tis.item_id = ti.item_id
   										AND tis.stor_id = @stor_id
--   								LEFT JOIN tbItemAssociation tia
--   									ON		tia.comp_id = ti.comp_id
--   										AND tia.item_id = ti.item_id

   								WHERE	ti.comp_id		= tsc.comp_id
								AND		ti.cat_id		= tsc.cat_id
								AND		ISNULL(ti.item_web,'false')			= 'true'
								AND		ISNULL(ti.item_disabled,'false')	= 'false'
								AND		ISNULL(ti.item_not4Sale,'false')	= 'false'
								--AND		tia.comp_id IS NULL

								AND		(
											(@showzerostock = 'true') OR
											(@showzerostock = 'false' AND tis.itst_cant > 0)
										)
								)


	AND		tsc.subcat_id NOT IN (SELECT	DISTINCT isnull(twscsd.subcat_id, -1)
	   								FROM	tbWebSite_Cat_Subcat_Disabled twscsd
	   								WHERE	twscsd.comp_id = tsc.comp_id
									AND		twscsd.ws_id = @ws_id)


	ORDER BY	[cat_web_order]		,
				[cat_desc]			,
				[subcat_web_order]	,
				[subcat_desc]



END
GO






