CREATE PROCEDURE [dbo].[spSubCategory_Process_Auto]
(

	@comp_id						INT,
	@lang_id						INT,
	@bra_id4session					INT,
	@user_id						INT,
	@prof_id						INT,

	@subcat_desc					NVARCHAR(50),
	@cat_id							INT,
	@bra_id							INT,
	@acc_count_id					INT,
	@subcat_Days4Ageing				INT,
	@subcat_commission				DECIMAL(19,6),
	@subcat_commission_byReceive	DECIMAL(19,6),
	@subcat_WebSite_desc			NVARCHAR(50),
	@subcat_web						BIT,
	@subcat_isAvailable4FullJaus	BIT,
	@subcat_web_order				INT,
	@subcat_disabledInBalance		BIT,
	@subcat_necessary				BIT,
	@subcat_enough					BIT,
	@subcat_exclude4Made			BIT,
	@subcat_pcConfigType			INT,
	@subcat_WebSite_NOTE1			NVARCHAR(1000),
	@subcat_WebSite_NOTE2			NVARCHAR(1000),
	@tn_categoryID					INT,
	@subcat_originalCODE			NVARCHAR(20),

	@guid							UNIQUEIDENTIFIER,
	@intROW							INT,
	@bolIsOK						BIT


)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id4session				= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,


	@bolIsOK					='True',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 1000

---------------------------------------------------------------------------------
*/
SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN



	 --Si la categoría y la subcategoría  se importaron con sus importadores pueden tener un código original y
	 --tomará primero esa categoria y subcategoria relacionada a ese codigo original
	 IF @subcat_originalCODE <> ''
		BEGIN

			declare @lcat_originalCODE	INT
			SET @lcat_originalCODE		= -1

			SET @lcat_originalCODE =  (SELECT top 1
											tc.cat_id
											FROM tbCategory 		tc		WITH (NOLOCK)
											WHERE	tc.comp_id				= @comp_id		AND
													tc.cat_originalCODE		= @subcat_originalCODE)


			if	@lcat_originalCODE		IS NULL  SET @lcat_originalCODE			= -1

			IF @lcat_originalCODE <> -1
				BEGIN
					set @cat_id = @lcat_originalCODE
				END


		END




	declare @return_value	INT


	if	@bra_id					= -1  SET @bra_id						= NULL
	if	@acc_count_id			= -1  SET @acc_count_id					= NULL
	if	@subcat_pcConfigType	= -1  SET @subcat_pcConfigType			= NULL


				BEGIN TRY

				INSERT INTO tbSubCategory
				(
					comp_id,
					cat_id,
					subcat_desc,
					bra_id,
					acc_count_id,
					subcat_commission,
					subcat_commission_byReceive,
					subcat_web,
					subcat_necessary,
					subcat_enough,
					subcat_web_order,
					subcat_exclude4Made,
					subcat_WebSite_desc,
					subcat_Days4Ageing,
					subcat_disabledInBalance,
					subcat_pcConfigType,
					subcat_WebSite_NOTE1,
					subcat_WebSite_NOTE2,
					subcat_migrationID,
					user_id4Insert,
					user_id4LastUpdate,
					user_LastUpdate,
					tn_categoryID,
					subcat_isAvailable4FullJaus,
					subcat_originalCODE
				)
				VALUES
				(
					@comp_id,
					@cat_id,
					@subcat_desc,
					@bra_id,
					@acc_count_id,
					@subcat_commission,
					@subcat_commission_byReceive,
					@subcat_web,
					@subcat_necessary,
					@subcat_enough,
					@subcat_web_order,
					@subcat_exclude4Made,
					@subcat_WebSite_desc,
					@subcat_Days4Ageing,
					@subcat_disabledInBalance,
					@subcat_pcConfigType,
					@subcat_WebSite_NOTE1,
					@subcat_WebSite_NOTE2,
					@subcat_originalCODE,
					@user_id,
					@user_id,
					GETDATE(),
					@tn_categoryID,
					@subcat_isAvailable4FullJaus,
					@subcat_originalCODE
				)




			set	@return_value = IDENT_CURRENT('tbSubCategory')   -- @@identity

			END TRY
			BEGIN CATCH
				set	@return_value = 0
			END CATCH



END


















GO





--------------------------------------------------------------------------
-- Date  : 09/10/19
-- Author: GA
-- Data  :Importacion de SubCategorias - Insert data - Validaciones
--------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSubCategory_Process_Auto_Validate]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@cat_id						INT,
	@bra_id						INT,
	@acc_count_id				INT,
	@subcat_pcConfigType		INT,
	@subcat_originalCODE		NVARCHAR(20),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@curr_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT



SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''


	declare @lcat_originalCODE	INT
	SET @lcat_originalCODE		= -1
	 --Si la categoría y la subcategoría  se importaron con sus importadores pueden tener un código original y
	 --tomará primero esa categoria y subcategoria relacionada a ese codigo original
	 IF @subcat_originalCODE <> ''
		BEGIN
			SET @lcat_originalCODE =  (SELECT top 1
											tc.cat_id
											FROM tbCategory 		tc		WITH (NOLOCK)
											WHERE	tc.comp_id				= @comp_id		AND
													tc.cat_originalCODE		= @subcat_originalCODE)


			if	@lcat_originalCODE		IS NULL  SET @lcat_originalCODE			= -1

			--IF @lcat_originalCODE <> -1
			--	BEGIN
			--		set @cat_id = @lcat_originalCODE
			--	END


		END


	-----------------------------------------------------------------------------------------------------------------
	--Categoría
	-----------------------------------------------------------------------------------------------------------------
	IF @lcat_originalCODE = -1
			BEGIN

				if	@cat_id	<> -1
				BEGIN

				IF NOT EXISTS (SELECT tb.cat_id
								FROM tbCategory  tb		WITH (NOLOCK)
									WHERE   tb.comp_id			= @comp_id and
		               						tb.cat_id			= @cat_id)
						BEGIN
							SET	@bolIsOK		= 'False'
							SET @errormessage	= @errormessage + '---' + 'El ID de Categoría es incorrecto'
						END

				END
			END

	-----------------------------------------------------------------------------------------------------------------


	-----------------------------------------------------------------------------------------------------------------
	--Sucursal
	-----------------------------------------------------------------------------------------------------------------
	if	@bra_id	<> -1
	BEGIN

	IF NOT EXISTS (SELECT tb.bra_id
	               FROM tbBranch tb		WITH (NOLOCK)
						WHERE   tb.comp_id			= @comp_id and
		               			tb.bra_id			= @bra_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Sucursal es incorrecto'
			END

	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	--Cuenta Contable
	-----------------------------------------------------------------------------------------------------------------
	if	@acc_count_id	<> -1
	BEGIN
	IF NOT EXISTS (SELECT ta.acc_count_id
			        FROM tbAccountant ta		WITH (NOLOCK)
						WHERE   ta.comp_id			= @comp_id and
		               			ta.acc_count_id		= @acc_count_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Cuenta Contable es incorrecto'
			END
	END

	-----------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------
	--Tipo de SubCategoria
	-----------------------------------------------------------------------------------------------------------------
	if	@subcat_pcConfigType	<> -1
	BEGIN
	IF NOT EXISTS (SELECT tov.optval_id
	               FROM tbsysOptionsValues tov		WITH (NOLOCK)
						WHERE   tov.lang_id			= @lang_id				AND
		               			tov.optval_id		= @subcat_pcConfigType	AND
								tov.optval_class	= 533)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Tipo de SubCategoría es incorrecto'
			END
	END


	-----------------------------------------------------------------------------------------------------------------




	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Fila],
				@errormessage	[Error],
				'True'			[Exists]
		END
	ELSE
		BEGIN

			--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Fila],
				@errormessage	[Error],
				'False'			[Exists]
		END


END


















GO






