CREATE PROCEDURE [dbo].[spSubCategoryAux_getImages]
(
	@comp_id				INT,
	@bolGetNullImages		BIT
)
AS

BEGIN


	SET NOCOUNT ON


	SELECT
		tsc.subcataux_id					[Id],
		tsc.subcataux_image					[Image]
		FROM tbSubCategoryaux tsc		WITH (NOLOCK)
		WHERE	tsc.comp_id = @comp_id			AND
				( @bolGetNullImages = 'True' OR
				  tsc.subcataux_image IS NOT NULL )


END
GO







