CREATE PROCEDURE [dbo].[spSupplier_getDataByFilters]
(
	@comp_id			int,
	@supp_name			Varchar (100),
	@supp_name1			Varchar (100),
	@supp_address		Varchar	(100),
	@supp_taxNumber		varchar (100),
	@supp_city			Varchar (100),
    @supp_zip			Varchar (20),
	@supp_Phone1        Varchar (100),
	@supp_Phone2		Varchar (100),
	@country_id			int,
	@state_id			int
)
as


	select
			' ' [+],
			s.supp_name,
			s.supp_name1,
			s.supp_taxNumber,
			s.supp_address,
			s.supp_city,
			s.supp_zip,
			s.supp_Phone1,
			s.supp_Phone2,
			sc.country_desc,
			ss.state_desc,
			s.supp_id[ID]


	from	dbo.tbSupplier			s

			inner join tbsysCountry		sc
			on sc.country_id			= s.country_id

			inner join tbsysState		ss
			on  ss.state_id             = s.state_id
			and ss.country_id			= s.country_id


	Where   s.comp_id				 =  @comp_id
	AND		isnull(s.supp_name		,'')	like '%' +  @supp_name      + '%'
	AND		isnull(s.supp_name1		,'')	like '%' +  @supp_name1     + '%'
	AND		isnull(s.supp_address	,'')	like '%' +  @supp_address   + '%'
	AND		isnull(s.supp_taxNumber	,'')	like '%' +  @supp_taxNumber + '%'
	AND		isnull(s.supp_city		,'')	like '%' +  @supp_city      + '%'
	AND		isnull(s.supp_zip		,'')	like '%' +  @supp_zip       + '%'
	AND		isnull(s.supp_Phone1	,'')    like '%' +  @supp_Phone1    + '%'
	AND		isnull(s.supp_Phone2	,'')    like '%' +  @supp_Phone2    + '%'
	AND		(sc.country_id			 =  @country_id OR  @country_id		= -1)
	AND		(ss.state_id			 =  @state_id   OR  @state_id		= -1)

























GO








CREATE PROCEDURE [dbo].[spSupplier_getDataById]
(
	@comp_id		INT,
	@supp_id		INT
)
AS
SET NOCOUNT ON



-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2010-07-28
-- Parte		: 408
-- Description	: Para cumplir el requerimiento solicitado, se agregó el left join tbsysFiscalClass para
--				  recuperar el fc_KindOf relacionado al proveedor solicitado
-- =================================================================================================================



SELECT 	ts.comp_id,
		ts.supp_id,
		ts.supp_name,
		ts.supp_name1,
		ts.fc_id,
		ts.supp_taxNumber,
		ts.curr_id,
		isnull(ts.supp_web,'')							[supp_web],
		ts.puco_id,
		isnull(ts.supp_partnerOf,'')					[supp_partnerOf],
		isnull(ts.supp_contact,'')						[supp_contact],
		ts.supp_address,
		ts.supp_city,
		ts.supp_zip,
		ts.supp_Phone1,
		ts.supp_Phone2,
		isnull(ts.supp_email,'')						[supp_email],
		ts.supp_fax,
		ts.supp_picture,
		ts.country_id,
		ts.state_id,
		ts.acc_count_id,
		ts.supp_inactive,
		ts.supp_isEditing,
		ts.supp_isEditingCd,
		ts.supp_isEditingUserId,
		tc.country_desc,
		ts2.state_desc,
		ts.stcIB_Id,
		ts.supp_cai,
		ts.supp_caiDate,
		isnull(tfc.fc_KindOf,' ')						[fc_KindOf],			--2010-07-28 - Parte 408
		isnull(tfc.fc_KindOf4Purchase,' ')				[fc_KindOf4Purchase],	-- MOS 08-2010
		ISNULL(ts.supp_purOrd_Disc1,0)					[supp_purOrd_Disc1],	-- Parte 1053/1054
		ISNULL(ts.supp_purOrd_Disc2,0)					[supp_purOrd_Disc2],
		ISNULL(ts.supp_purOrd_Disc3,0)					[supp_purOrd_Disc3],
		ISNULL(ts.supp_purOrd_Disc4,0)					[supp_purOrd_Disc4],
		ISNULL(ts.supp_isAvailable4Associated,'FALSE')  [supp_isAvailable4Associated],
		ts.pt_id										[pt_id],
		ts.tnt_id,
		ts.supp_guid,
		isnull(ts.supp_por_onlyCheckPO,'False')			[supp_por_onlyCheckPO],
		ISNULL(ts.cc_code,-1)							[cc_code],
		ISNULL(ts.ptr_id,-1)							[ptr_id],
		ISNULL(ts.supp_is4Import,'False')				[supp_is4Import],
		ISNULL(ts.supp_days2Pay,0)						[supp_days2Pay]

FROM 	dbo.tbSupplier							ts			WITH (NOLOCK)

		LEFT JOIN dbo.tbsysCountry				tc			WITH (NOLOCK)
		ON	tc.country_id	= ts.country_id

		LEFT JOIN tbsysState ts2							WITH (NOLOCK)
		ON ts2.country_id	= ts.country_id
		AND ts2.state_id	=	ts.state_id

		LEFT JOIN tbsysFiscalClass				tfc			WITH (NOLOCK)		--2010-07-28 - Parte 408
		ON	tfc.fc_id		= ts.fc_id								--2010-07-28 - Parte 408


WHERE 	ts.comp_id			= @comp_id
AND 	ts.supp_id			= @supp_id







GO





CREATE PROCEDURE [dbo].[spSupplier_getDataByText]
(
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT,
	@comp_id AS INT,
	@bra_id  AS INT

)
AS

BEGIN

	SET NOCOUNT ON


	-- ---------------------------------------
	-- ---------------------------------------
	/*
	DECLARE
		@text		VARCHAR(300),
		@count		INT,
		@lang_id	INT
	SELECT
		@text		= 'M',
		@count		= 2,
		@lang_id	= 2
	*/
	-- ---------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR LOCAL FAST_FORWARD FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------



	SELECT TOP (@count)
				Upper(dbo.PadRightString(ts.supp_name ,'.',50)) + ' | ' + isnull(convert(varchar,ts.supp_id),'') + ' | ' + isnull(convert(varchar,ts.supp_taxNumber),'') [supp_name],
				ts.supp_id
	FROM tbSupplier ts

	WHERE		ts.comp_id = @comp_id			AND
				--ts.supp_name LIKE @text+'%'		AND

				(

					CASE
					    WHEN @selection_method = 0 AND ts.supp_name LIKE @text + '%'	 THEN	'True'
					    WHEN @selection_method = 1 AND ts.supp_name LIKE '%' + @text1 + '%'	 THEN	'True'
					    WHEN @selection_method = 2 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%'		 THEN	'True'
					    WHEN @selection_method = 3 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%'	 THEN	'True'
					    WHEN @selection_method = 4 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%'		 THEN	'True'
					    WHEN @selection_method = 5 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%'		 THEN	'True'
					    WHEN @selection_method = 6 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%'	 THEN	'True'
					    WHEN @selection_method = 7 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%'	 THEN	'True'
					    WHEN @selection_method = 8 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%' AND ts.supp_name LIKE '%' + @text8 + '%'		 THEN	'True'
					    WHEN @selection_method = 9 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%' AND ts.supp_name LIKE '%' + @text8 + '%' AND ts.supp_name LIKE '%' + @text9 + '%'		 THEN	'True'
					    WHEN @selection_method =10 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%' AND ts.supp_name LIKE '%' + @text8 + '%' AND ts.supp_name LIKE '%' + @text9 + '%' AND ts.supp_name LIKE '%' + @text10 + '%'		 THEN 'True'
					    ELSE	'False'
					END	= 'True'

					OR

					ts.supp_taxNumber	LIKE '%' + @text + '%'
				)


END
GO






create PROCEDURE [dbo].[spSupplier_getDataForMail]
(
	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON

/*
DECLARE
	@comp_id	INT,
	@country_id	INT,
	@state_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@pQuestion	BIT

SELECT
	@comp_id	= 1,
	@country_id	= -1,--54,
	@state_id	= -1,--54011,
	@guid		= '04af870b-a20b-41f6-a373-3949b02b640e',
	@pQuestion	= 'True'
*/

SELECT	tc.supp_email

FROM	tbSupplier								tc

		INNER JOIN tbMail_Recipients			tmr
		ON	tc.comp_id			= tmr.comp_id
		AND tc.supp_id			= tmr.mr_recipientId
		AND tmr.guid			= @guid

WHERE	tc.comp_id		=	@comp_id
AND		NOT tc.supp_email IS NULL
AND		tc.supp_email	<>	''
AND		tmr.mr_checked	=	'True'
GO



CREATE PROCEDURE [dbo].[spSupplier_GetDocumentBySerial]
(
	@comp_id	INT,
	@lang_id	INT,
	@ItemSerial	NVARCHAR(100)
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@ItemSerial	NVARCHAR(100)
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@ItemSerial	= 'f1121217'
		*/
		-- ----------------------------------------

		SELECT
			tct.supp_id,
			ts.comp_id, ts.supp_name,
			dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id, tct.ct_transaction)	[Document]
			FROM tbItemSerials										tis		WITH (NOLOCK)
				INNER JOIN tbCommercialTransactions					tct		WITH (NOLOCK)
					ON	tct.comp_id			= tis.comp_id			AND
						tct.ct_transaction	= tis.ct_transaction
				INNER JOIN tbSupplier								ts		WITH (NOLOCK)
					ON	ts.comp_id			= tct.comp_id			AND
						ts.supp_id			= tct.supp_id
			WHERE	tis.comp_id				= @comp_id				AND
					tis.is_serial			= @ItemSerial
	END
GO







