CREATE PROCEDURE [dbo].[spSupplier_getMailingList]
(
	@comp_id		INT,
	@where			VARCHAR(8000),
	@guid			UNIQUEIDENTIFIER,
	@pQuestion		BIT					-- TRUE = DESCHECKEA // FALSE = MANTIENE LOS QUE YA ESTABAN CHECKEADOS
)
AS

BEGIN

	SET NOCOUNT ON

	-- ----------------------------------------------------------
	-- testing
	-- ----------------------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@where		VARCHAR(8000),
		@guid		UNIQUEIDENTIFIER,
		@pQuestion	BIT

	SELECT
		@comp_id	= 1,
		@where		= '((-1 = -1) or ([country_id] = ''-1''))  ',
		@guid		= 'a7a0b132-379d-4954-8106-75ae9680715b',
		@pQuestion	= 'True'
	*/
	-- ----------------------------------------------------------

	-- Verifica que la tabla tbMail_Recipients tenga algo
	IF NOT EXISTS(	SELECT 1
						FROM tbMail_Recipients tmr WITH (NOLOCK)
	              		WHERE	tmr.comp_id = @comp_id AND
	              				tmr.guid	= @guid)
		BEGIN
			INSERT INTO tbMail_Recipients
				(	comp_id,		[guid],		mr_checked,		mr_recipientId	)
					SELECT	tc.comp_id,
							@guid ,
							'False',
							tc.supp_id
					FROM tbSupplier tc WITH (NOLOCK)
		END


	DECLARE @strWhere VARCHAR(8000)
	SET @strWhere = ' WHERE tmr.comp_id = ' + convert( varchar(10),@comp_id) + ' AND tmr.guid = ''' +  CAST(@guid AS VARCHAR(36))  + ''''


	If @pQuestion = 'True'
		BEGIN

			EXEC (	'UPDATE tbMail_Recipients
						SET	mr_checked = 0
						FROM tbMail_Recipients tmr
						 ' + @strWhere )
		END


	IF CHARINDEX('=', @where) > 0 SET @strWhere = @strWhere + ' and ' + @where


	CREATE TABLE #tmpSupplierFiltered (supp_id INT PRIMARY KEY)

	DECLARE @strAux AS VARCHAR(MAX)
	SET @strAux = CASE
			              WHEN	@where = '' THEN '1 = 1'
			              ELSE	@where
			          END
	EXEC ( '
	INSERT INTO #tmpSupplierFiltered
		SELECT supp_id
			FROM tbSupplier 	WITH (NOLOCK)
			WHERE ' + @strAux
		)



	SELECT	' ' [ ],
			tmr.mr_checked,
			tc.supp_name,
			tc.supp_email,
			tc2.country_desc,
			ts.state_desc,
			tmr.mr_id			[ID]
			FROM	tbMail_Recipients						tmr				WITH (NOLOCK)
					INNER JOIN tbSupplier 					tc				WITH (NOLOCK)
					ON	tmr.comp_id			= tc.comp_id	AND
						tmr.mr_recipientId	= tc.supp_id
					INNER JOIN tbsysCountry					tc2				WITH (NOLOCK)
					ON	tc2.country_id		= tc.country_id
					INNER JOIN tbsysState					ts				WITH (NOLOCK)
					ON  ts.country_id		= tc.country_id	AND
						ts.state_id			= tc.state_id
					INNER JOIN #tmpSupplierFiltered			tmp
						ON tmp.supp_id		= tmr.mr_recipientId
			WHERE	tmr.comp_id				= @comp_id		AND
					tmr.guid				= @guid

					--AND
					--ISNULL(tc.cust_excludeOfCustomerMailing,'False')	<> 'True'
			DROP TABLE #tmpSupplierFiltered

END
GO






CREATE PROCEDURE [dbo].[spSupplier_getReport]
(
		@comp_id		int,
		@lang_id		int,
		@page_id		int,

		@option			int,
		@supp_name		varchar(200),
		@fc_id			int,
		@country_id		int,
		@tnt_id			int,
		@curr_id		int,
		@state_id		int,
		@puco_id		INT,
		@guid			VARCHAR(50),
		@bra_id			INT,
		@intBranch4Lang	int

)
AS

SET NOCOUNT ON

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------
/*
DECLARE		    @comp_id		int,
				@lang_id		int,
				@page_id		int,
				@fc_id			int,
				@country_id		int,
				@tnt_id			int,
				@curr_id		int,
				@state_id		int,
				@puco_id		Int,
				@option			int,
				@supp_name		Varchar(200),
				@bra_id			INT

SELECT			@comp_id		= 1,
				@lang_id		= 2,
				@page_id		= 10007,
				@option			=0,
				@fc_id			= -1,
				@country_id		= -1,
				@tnt_id			= -1,
				@curr_id		= -1,
				@state_id		= -1,
				@puco_id		= -1,
				@supp_name		= '',
				@bra_id			=-1

*/
-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------

	DECLARE @lGuid_Supp AS UNIQUEIDENTIFIER
	SET @lGuid_Supp = CONVERT(UNIQUEIDENTIFIER,@guid)
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid_Supp     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
				FROM tbSupplier ts
					WHERE ts.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


DECLARE @fun_id INT
SET @fun_id = 1


SELECT		SP.supp_name,
			SP.supp_name1,
			FC.fc_desc,
			SP.supp_taxNumber,
			CR.curr_desc,
			SP.supp_web,
			PC.puco_desc,
			SP.supp_partnerOf,
			SP.supp_contact,
			SP.supp_address,
			SP.supp_city,
			SP.supp_zip,
			SP.supp_phone1,
			SP.supp_phone2,
			SP.supp_fax,
			SP.supp_email,
			CNT.country_desc,
			STT.state_desc,
			O.[optval_desc] [supp_inactive],
			TNT.tnt_desc

FROM	tbSupplier								SP

		INNER JOIN @tblComplexFilter_Supplier tcfs
		ON tcfs.supp_id = SP.supp_id

		left join tbsysFiscalClass				FC
		ON SP.[fc_id]	= FC.[fc_id]

		left join tbsysCurrency					CR
		ON SP.[curr_id] = CR.[curr_id]

		left join tbPurchaseConcept				PC
		ON SP.[puco_id]	= PC.[puco_id]

		left join tbsysCountry					CNT
		on SP.[country_id] = CNT.[country_id]

		left join [tbsysState]					STT
		ON SP.[state_id] = STT.[state_id]

		left join [tbsysOptionsValues]			O
		on O.[optval_id]	= SP.[supp_inactive]
		and		O.[optval_class]	= 1
		and     O.[lang_id]			= @lang_id

		left join tbsysTaxNumberTypes		TNT
		ON SP.[tnt_id] = TNT.[tnt_id]

WHERE	SP.[comp_id]	= @comp_id
and		(@fc_id			= -1		or		SP.[fc_id]		= @fc_id)
and		(@country_id	= -1		or		SP.[country_id]	= @country_id)
and		(@tnt_id		= -1		or		SP.[tnt_id]		= @tnt_id)
and		(@curr_id		= -1		or		SP.[curr_id]	= @curr_id)
and		(@state_id		= -1		or		SP.[state_id]	= @state_id)
and		(@puco_id		= -1		or		SP.[puco_id]	= @puco_id)
and		(
		(@option = -1 ) or
		(@option = 0 and SP.supp_name like @supp_name + '%') or
		(@option = 1 and SP.supp_name like '%' + @supp_name + '%') or
		(@option = 2 and SP.supp_name = @supp_name) or
		(@option = 3 and SP.supp_name <> @supp_name) or
		(@option = 4 and SP.supp_name not like '%' + @supp_name + '%')
		)

order by 1

exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id,	@page_id
/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
/*************************************************************************************************************/
/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
/*
		SELECT	t.ctrl_id,	t.[text_desc]
		FROM	[tbsysTexts]				t
				inner join [tbsysControls]	c
				on c.[ctrl_id] = t.[ctrl_id]
		where	t.[lang_id]	= @lang_id
		and		t.[page_id]	= @related_page_id
		and		t.[type_id]	= 1
*/
/*************************************************************************************************************/

SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 43
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @option WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT tov.optval_desc FROM tbsysOptionsValues tov
					WHERE tov.optval_class = 2 AND tov.lang_id = @lang_id AND tov.optval_id = @option)
		End	[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 388
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

		CASE @fc_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(Select tfc.fc_desc
					FROM	tbsysFiscalClass tfc
					WHERE	tfc.fc_id= @fc_id)

		END		[params4],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 373
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

		CASE @tnt_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
								(Select ttnt.tnt_desc
					FROM	tbsysTaxNumberTypes ttnt
					WHERE	ttnt.tnt_id= @tnt_id)

		END		[params6],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 57
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

		CASE @country_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(Select tc.country_desc

					FROM	tbsysCountry tc
					WHERE	tc.country_id= @country_id)

		END		[params8],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 59
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

		CASE @state_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
									(Select ts.state_desc
					FROM	tbsysState ts
					WHERE	ts.country_id= @country_id
									And ts.state_id = @state_id)

		END		[params10],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 389
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

		CASE @puco_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE

									(Select tpc.puco_desc
					FROM	tbPurchaseConcept tpc
					WHERE	tpc.comp_id= @comp_id
									And tpc.puco_id = @puco_id)

		END		[params12],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 106
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

		CASE @curr_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE

									(Select tc.curr_desc
					FROM	tbsysCurrency tc
					WHERE	tc.curr_id = @curr_id )

		END		[params14]
GO






-- --------------------------------------------------------------
-- MOS  03-2009
-- Pone IsEditing en Falso de los Proveedores
-- --------------------------------------------------------------

CREATE pROCEDURE [dbo].[spSupplier_IsEditingPurgeStatus]
as


BEGIN

	set nocount on
	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD(minute, -3, getdate())

	UPDATE tbSupplier	WITH(ROWLOCK)
		SET
			supp_isEditing = 'false',
			supp_isEditingCd = GETDATE()

		Where   supp_isEditing = 'True'
			and	supp_isEditingCd < @DeleteTime

END


GO








CREATE PROCEDURE [dbo].[spSupplier_IsValidTaxNumber]
(
	@comp_id			INT,
	@supp_id			INT,
	@tnt_id				INT,
	@supp_taxNumber		NVARCHAR(100),
	@lang_id			INT,
	@return_value		int				output,
	@ret_ErrorCode		int				output,
	@ret_ErrorDescription	varchar(200)	output

)
AS

BEGIN



	set nocount on


	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''

	-- ----------------------------------------------
	-- Testing
	-- ----------------------------------------------
	/*
	DECLARE		@comp_id			INT,
				@supp_id			INT,
				@supp_cai			VARCHAR(20),
				@supp_caiDate		DATETIME


	SELECT		@comp_id			=1,
				@supp_id			=8103,
				@supp_cai			=1,
				@supp_caiDate		=GETDATE()
	*/
	-- ----------------------------------------------

		IF /*@tnt_id <> 51 AND*/ @tnt_id <> 61 -- CUIT - Opcion 5 S/V o Cuit Duplicado.
		BEGIN

			IF EXISTS (
							SELECT 1
								FROM tbSupplier ts	WITH (NOLOCK)
								WHERE	ts.comp_id			= @comp_id	AND
										ts.supp_id			<> @supp_id	AND
										ts.tnt_id			= @tnt_id	and
										ts.supp_taxNumber	= @supp_taxNumber
						)
				BEGIN
					SET @return_value			= -1
					SET @ret_ErrorCode			= -1
					SELECT  @ret_ErrorDescription = tut.utexts_desc
						FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						WHERE	tut.lang_id		= @lang_id AND
								tut.utexts_id	= 1003
				END

		END


END
GO





-- =============================================
-- Author:		GA
-- Create date: 09/09/2010
-- Description:	Reporte de "Ranking de Ventas por Proveedor"
-- =============================================


CREATE PROCEDURE [dbo].[spSupplier_SalesRanking_getReport]
(
	@comp_id		int,
	@lang_id		int,
	@page_id		int,

	@option			int,
	@supp_name		varchar(200),
	@fc_id			int,
	@country_id		int,
	@tnt_id			int,
	@curr_id		int,
	@state_id		int,
	@puco_id		INT,
	@date_from      DATETIME,
	@date_to		DATETIME,
	@guid			VARCHAR(50),
	@bra_id			INT,
	@user_id		INT,
	@intBranch4Lang	int



)
as


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------




	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
	/*


	declare	@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@option			int,
			@supp_name		varchar(200),
			@fc_id			int,
			@country_id		int,
			@tnt_id			int,
			@curr_id		int,
			@state_id		int,
			@puco_id		int,
			@date_from      DATETIME,
			@date_to		DATETIME,
			@bra_id			INT,
			@user_id		INT,
			@guid			VARCHAR(50),
			@intBranch4Lang	INT

	select 	@comp_id		=1,
			@lang_id		=2,
			@page_id		=10073,

			@option			= -1,
			@fc_id			= -1,
			@country_id		= -1,
			@tnt_id			= -1,
			@curr_id		= 1,
			@state_id		= -1,
			@puco_id		= -1,
			@supp_name		= '',
			@date_from		='2000-01-01',
			@date_to		='9999-12-31',
			@bra_id			=-1,
			@user_id		= 1,
			@guid			= 'bdab1d08-81ea-4214-a7a4-945ac9bb7e54',
			@intBranch4Lang	= 1




	drop table #tmp
	*/
	--------------------------------------------------------------------------------
	--------------------------------------------------------------------------------

BEGIN

	set	@date_from = dbo.fnGetEnd_or_BeginOfDate(@date_from,'False')
	set	@date_to = dbo.fnGetEnd_or_BeginOfDate(@date_to,'True')

	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------

	DECLARE @lGuid_Supp AS UNIQUEIDENTIFIER
	SET @lGuid_Supp = CONVERT(UNIQUEIDENTIFIER,@guid)
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid_Supp     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
				FROM tbSupplier ts
					WHERE ts.comp_id = @comp_id
		END
	-- -------------------------------------------------------------


	select		ts.supp_id,
				ts.supp_name,
				tc.curr_symbol,
				dbo.fnGetExchange2(@comp_id,tct.ct_total,tct.curr_id_transaction, @curr_id, 0,0, 0,'False') *
				CASE
					WHEN vctfs.sd_id  = 103    THEN -1
					ELSE						     1
				END									[Facturado]


	into #tmp

	from tbCommercialTransactions									tct		WITH(NOLOCK)
		INNER JOIN vwCommercialTransactions_forPurchase 			vctfs	WITH(NOLOCK)
		ON  vctfs.comp_id			= tct.comp_id
		AND vctfs.bra_id			= tct.bra_id
		AND vctfs.ct_transaction	= tct.ct_transaction
		INNER JOIN tbSupplier										ts
		on  ts.comp_id				= tct.comp_id
		AND ts.supp_id				= tct.supp_id

		INNER JOIN @tblComplexFilter_Supplier tcfs
		ON tcfs.supp_id = ts.supp_id


		INNER JOIN tbsysCurrency tc
		ON tc.curr_id = @curr_id


		INNER JOIN tbUsers4BranchFilter vubf
		ON vubf.comp_id	= tct.comp_id
		AND vubf.bra_id		= tct.bra_id
		AND vubf.[user_id]  = @user_id




	WHERE	 ts.[comp_id]	= @comp_id
	and		(@fc_id			= -1		or		ts.[fc_id]		= @fc_id)
	and		(@country_id	= -1		or		ts.[country_id]	= @country_id)
	and		(@tnt_id		= -1		or		ts.[tnt_id]		= @tnt_id)
	--and		(@curr_id		= -1		or		ts.[curr_id]	= @curr_id)
	and		(@state_id		= -1		or		ts.[state_id]	= @state_id)
	and		(@puco_id		= -1		or		ts.[puco_id]	= @puco_id)
	and		(
			(@option = -1 ) or
			(@option = 0 and ts.supp_name like @supp_name + '%') or
			(@option = 1 and ts.supp_name like '%' + @supp_name + '%') or
			(@option = 2 and ts.supp_name = @supp_name) or
			(@option = 3 and ts.supp_name <> @supp_name) or
			(@option = 4 and ts.supp_name not like '%' + @supp_name + '%')
			)
	AND			vctfs.sd_id in (101,103)
	AND			tct.ct_date		between @date_from and @date_to

	declare @total as decimal (19,2)
	set @total = (select  sum(temp.[Facturado]) [Total] from #tmp temp)

	--select @total

	select convert(varchar,temp.supp_id)+ ' - ' + convert(varchar,temp.supp_name) [Supp_Name],
		   sum(temp.[Facturado])[Facturado],
		   rank() OVER (ORDER BY sum(temp.[Facturado]) desc) [Puesto Nro],
		   (sum(temp.[Facturado]/@total*100 ))  [Porcent],
		   temp.curr_symbol



	from #tmp temp

	group by temp.supp_name,temp.supp_id,curr_symbol

	order by [Facturado] desc

	exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id,@page_id



	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 43
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

			CASE @option WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT tov.optval_desc FROM tbsysOptionsValues tov
						WHERE tov.optval_class = 2 AND tov.lang_id = @lang_id AND tov.optval_id = @option)
			End	[params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 388
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params3],

			CASE @fc_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(Select tfc.fc_desc
						FROM	tbsysFiscalClass tfc
						WHERE	tfc.fc_id= @fc_id)

			END		[params4],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 373
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],

			CASE @tnt_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
									(Select ttnt.tnt_desc
						FROM	tbsysTaxNumberTypes ttnt
						WHERE	ttnt.tnt_id= @tnt_id)

			END		[params6],

					(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 57
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

			CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
						(Select tc.country_desc

						FROM	tbsysCountry tc
						WHERE	tc.country_id= @country_id)

			END		[params8],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 59
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],

			CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
										(Select ts.state_desc
						FROM	tbsysState ts
						WHERE	ts.country_id= @country_id
										And ts.state_id = @state_id)

			END		[params10],

						(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 389
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params11],

			CASE @puco_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE

										(Select tpc.puco_desc
						FROM	tbPurchaseConcept tpc
						WHERE	tpc.comp_id= @comp_id
										And tpc.puco_id = @puco_id)

			END		[params12],



			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 106
      		 --AND t.[lang_id] = @lang_id
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params13],

			CASE @curr_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE

										(Select tc.curr_desc
						FROM	tbsysCurrency tc
						WHERE	tc.curr_id = @curr_id )

			END		[params14],



		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  		 WHERE t.ctrl_id = 177
  		 --AND t.[lang_id] = @lang_id
  		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)			[params15],
  		 --@date_from [DateParams1],
		convert(varchar,day(@date_from)) + '/' + convert(varchar,month(@date_from)) + '/' + convert(varchar,year(@date_from)) 	[DateParams1],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
  		 WHERE t.ctrl_id = 384
  		 --AND t.[lang_id] = @lang_id
  		 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params16],
  		-- @date_to [DateParams2]
		convert(varchar,day(@date_to)) + '/' + convert(varchar,month(@date_to)) + '/' + convert(varchar,year(@date_to)) 	[DateParams2]



END

END
GO








CREATE PROCEDURE [dbo].[spSupplier_UpdateCai]
(
	@comp_id			INT,
	@supp_id			INT,
	@supp_cai			VARCHAR(20),
	@supp_caiDate		DATETIME,
	@return_value		int				output,
	@ret_ErrorCode		int				output,
	@ret_ErrorDescription	varchar(200)	output

)
as

set nocount on


SET @return_value			= 0
SET @ret_ErrorCode			= 0
SET @ret_ErrorDescription	= ''

/*
DECLARE		@comp_id			INT,
			@supp_id			INT,
			@supp_cai			VARCHAR(20),
			@supp_caiDate		DATETIME


SELECT		@comp_id			=1,
			@supp_id			=8103,
			@supp_cai			=1,
			@supp_caiDate		=GETDATE()
*/

BEGIN TRY
	Update	dbo.tbSupplier

	Set		supp_cai	 = @supp_cai,
			supp_caiDate = @supp_caiDate

	Where	comp_id = @comp_id
	And	    supp_id = @supp_id
END TRY

BEGIN CATCH
	SET @return_value			= -1
	SET @ret_ErrorCode			= -1
	SET @ret_ErrorDescription	= '01 - ' + ERROR_MESSAGE()
END CATCH
GO





