-- Description:	Actualiza isEditing en Clientes
-- =============================================


CREATE PROCEDURE [dbo].[spSupplier_updateIsEditing]
	@comp_id			as int,
	@supp_id			as int,
	@user_id			as int,
	@supp_isediting		as bit,
	@ForceActualization AS bit
AS

BEGIN




	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	/*
	declare @comp_id			as int,
			@supp_id			as int,
			@user_id			as int,
			@supp_isediting		as bit
	select 	@comp_id			=1,
			@supp_id			=8103,
			@user_id			=1,
			@supp_isediting		='False'
	*/


	update	dbo.[tbSupplier]

	set		supp_isediting			= @supp_isediting,
			supp_iseditingCd		= getdate(),
			supp_isEditingUserId	= @user_id

	where	comp_id					= @comp_id
	and		supp_id					= @supp_id
	AND (@ForceActualization = 'True' OR supp_isediting = 'true')


END
GO







create PROCEDURE [dbo].[spSupplierAssociated_GetCombo]
(
	@comp_id			INT,
	@supp_id			int
)



as


BEGIN


		----------------------------------------
		----------------------------------------
		/*
		DECLARE		@comp_id			INT,
					@supp_id			INT


		SELECT		@comp_id			= 1,
					@supp_id			= 8110
		*/
		----------------------------------------
		----------------------------------------



	select		tsa.suppa_id		[id],
				case when len(tsa.suppa_name) > 40 THEN SUBSTRING(tsa.suppa_name,1,40) + '...'
				ELSE tsa.suppa_name
				END  [desc]

	from		dbo.tbSupplierAssociated	tsa

	INNER JOIN tbSupplier					ts
	ON	ts.comp_id = tsa.comp_id AND
		ts.supp_id = tsa.supp_id

	where		tsa.comp_id =	@comp_id AND
				tsa.supp_id	= @supp_id


	Order By	tsa.suppa_name



END












GO






