create PROCEDURE [dbo].[spSupplierAssociated_getDataById]
(
	@comp_id		INT,
	@suppa_id		INT
)
AS
SET NOCOUNT ON



SELECT  tsa.comp_id,
		tsa.supp_id,
		tsa.suppa_id,
		tsa.suppa_name,
		tsa.suppa_address,
		tsa.suppa_city,
		tsa.suppa_zip,
		tsa.suppa_phone1,
		tsa.suppa_email,
		tsa.suppa_contact,
		tsa.country_id,
		tsa.state_id,
		tsa.puco_id,
		tsa.fc_id,
		tsa.suppa_TaxNumber,
		tsa.suppa_cd

FROM	dbo.tbSupplierAssociated tsa

WHERE 	tsa.comp_id				= @comp_id
AND 	tsa.suppa_id			= @suppa_id







GO






CREATE Procedure [dbo].[spSupplierBalanceAging_getReport]
(
		@comp_id		int,
		@lang_id		int,
		@page_id		int,

		@bra_id				int,
		@country_id			int,
		@state_id			int,
		@custsupp			INT,
		@user_id			Int,
		@intBranch4Lang		int
--		@date_from      datetime,
--		@date_to	    datetime
)
as


BEGIN


	set nocount ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set dateformat 'ymd'

-- -------------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------------
	/*
	Declare
			@comp_id		int,
			@lang_id		int,
			@page_id		int,



			@custsupp		INT,
			@country_id		int,
			@state_id		int,
			@bra_id			int,
	--		@ck_id			int,
	--		@sm_id			int,
	--		@dl_id			int,
	--		@date_from      datetime,
	--		@date_to	    datetime,
			@user_id         INT





	Select
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10024,

			@custsupp		=-1,
	--		@ck_id			=-1,
	--		@sm_id			=-1,
	--		@dl_id			=-1,
			@country_id		=-1,
			@state_id		=-1,
	--		@date_from		='01/01/2000',
	--		@date_to		='31/12/2009',
			@user_id        = 1

	*/
-- -------------------------------------------------------------------------


	DECLARE @fun_id INT
	SET @fun_id = 1

	DECLARE @datProcessingDate AS DATETIME
	SELECT  @datProcessingDate = tb.bra_processingDate
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id


	DECLARE @bra_curr_id INT
	SELECT @bra_curr_id = curr_id FROM tbBranch tb WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id

	Select  convert(varchar,VWCT.supp_id) [supp_id],
			S.supp_name,
			sum(isnull(Case
				When CT.ct_PayDate <= @datProcessingDate Then  (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [A Fecha],
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate and CT.ct_PayDate <= @datProcessingDate+30 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [30 Dias],
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate+30 and CT.ct_PayDate <= @datProcessingDate+60 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False')* Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [60 Dias],
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate+60 and CT.ct_PayDate <= @datProcessingDate+90 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [90 Dias],
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate+90 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [+ 90 Dias]

			INTO #tmp_BalanceAging

	From	dbo.vwCommercialTransactions_forPurchase	VWCT

			inner join dbo.tbCommercialTransactions			CT
			on  VWCT.comp_id		= CT.comp_id
			AND VWCT.bra_id			= CT.bra_id
			and VWCT.ct_transaction	= CT.ct_transaction

			inner join dbo.tbSupplier					S
			on  VWCT.comp_id		= S.comp_id
			and VWCT.supp_id		= S.supp_id
			and (@country_id		= -1 or S.country_id	= @country_id)
			and (@state_id			= -1 or S.state_id		= @state_id)

			inner join tbUsers4BranchFilter vubf
			ON  vubf.comp_id    = CT.comp_id
			AND vubf.bra_id     = CT.bra_id
			AND vubf.[user_id]  = @user_id


	Where	VWCT.comp_id	= @comp_id
	--and		CT.bra_id		= @bra_id	MOS
	and		(@custsupp		= -1 or VWCT.supp_id	= @custsupp)
	and		(@country_id	= -1 or S.country_id	= @country_id)
	and		(@state_id		= -1 or S.state_id		= @state_id)


	Group By 	VWCT.supp_id, S.supp_name
	order by	S.supp_name


	SELECT
		tmp.supp_id,
		tmp.supp_name,
		tmp.[A Fecha],
		tmp.[30 Dias],
		tmp.[60 Dias],
		tmp.[90 Dias],
		tmp.[+ 90 Dias]

	FROM #tmp_BalanceAging tmp

	WHERE tmp.[A Fecha]		<> 0
	   OR tmp.[30 Dias]		<> 0
	   OR tmp.[60 Dias]		<> 0
	   OR tmp.[90 Dias]		<> 0
	   OR tmp.[+ 90 Dias]	<> 0




	exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 402
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )	[params1],

			CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	     		ELSE
										(Select Ts.supp_name
						FROM	tbSupplier ts
						WHERE	Ts.comp_id = @comp_id
						AND		Ts.supp_id = @custsupp)

			END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 57
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],
			CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		Tc.country_desc
						FROM	tbsysCountry tc
						WHERE	tc.country_id= @country_id)
			END		[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 59
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
		CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	tbsysState ts
						WHERE	Ts.state_id= @state_id)
			END		[params6],

		(SELECT tswn.word_desc FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id and tswn.wordsi_id = 3632)		[params7]


END
GO








CREATE Procedure [dbo].[spSupplierBalanceAging4Past_getReport]
(
		@comp_id			int,
		@lang_id			int,
		@page_id			int,
		@custsupp			INT,
		@country_id			int,
		@state_id			int,
		@guid				VARCHAR(50),
		@bra_id				int,
		@user_id			Int,
		@intBranch4Lang		INT

--		@date_from      datetime,
--		@date_to	    datetime
)
as


BEGIN


	set nocount on

	set dateformat 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


-- -------------------------------------------------------------------------
-- Testing
-- -------------------------------------------------------------------------

	/*
	Declare
			@comp_id		int,
			@lang_id		int,
			@page_id		int,

			@custsupp		INT,
			@country_id		int,
			@state_id		int,
			@bra_id			int,
			@user_id         INT

	Select
			@comp_id		=1,
			@lang_id		=2,
			@page_id		=10087,

			@custsupp		=-1,
			@country_id		=-1,
			@state_id		=-1,
			@user_id        = 1


drop table #tmp_BalanceAging

*/


-- -------------------------------------------------------------------------
	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------

	DECLARE @lGuid_Supp AS UNIQUEIDENTIFIER
	SET @lGuid_Supp = CONVERT(UNIQUEIDENTIFIER,@guid)
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid_Supp     AND
						  tcf.sl_selected = 'True'
	IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @tblComplexFilter_Supplier
				SELECT ts.supp_id
				FROM tbSupplier ts
					WHERE ts.comp_id = @comp_id
		END
	-- -------------------------------------------------------------

	DECLARE @fun_id INT
	SET @fun_id = 1

	DECLARE @datProcessingDate AS DATETIME
	SELECT  @datProcessingDate = tb.bra_processingDate
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id

	SET @datProcessingDate = DATEADD(DAY,-91, @datProcessingDate)

	DECLARE @bra_curr_id INT
	SELECT @bra_curr_id = curr_id FROM tbBranch tb WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id

	Select  convert(varchar,VWCT.supp_id) [supp_id],
			S.supp_name,
			sum(isnull(Case
				When CT.ct_PayDate <= @datProcessingDate Then  (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [+ 90 Dias],			--[A Futuro]
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate and CT.ct_PayDate <= @datProcessingDate+30 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [90 Dias],		--[30 Dias]
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate+30 and CT.ct_PayDate <= @datProcessingDate+60 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False')* Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [60 Dias],		--[60 Dias]
			sum(isnull(Case
				When CT.ct_PayDate > @datProcessingDate+60 and CT.ct_PayDate < @datProcessingDate+90 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [30 Dias],		--[90 Dias]
			sum(isnull(Case
				When CT.ct_PayDate >= @datProcessingDate+90 then (dbo.fnGetExchange2(@comp_id,CT.ct_abalance,CT.ct_ACurrency,@bra_curr_id,CT.ct_ACurrency,@bra_curr_id,0,'False') * Case When VWCT.sd_isCredit = 'False' Then 1 Else -1 End)
			end,0)) [A Futuro]		--[+ 90 Dias]

			INTO #tmp_BalanceAging

	From	dbo.vwCommercialTransactions_forPurchase		VWCT

			inner join dbo.tbCommercialTransactions			CT
			on  VWCT.comp_id		= CT.comp_id
			AND VWCT.bra_id			= CT.bra_id
			and VWCT.ct_transaction	= CT.ct_transaction

			inner join dbo.tbSupplier						S
			on  VWCT.comp_id		= S.comp_id
			and VWCT.supp_id		= S.supp_id
			and (@country_id		= -1 or S.country_id	= @country_id)
			and (@state_id			= -1 or S.state_id		= @state_id)

			INNER JOIN @tblComplexFilter_Supplier			tcfs
			ON tcfs.supp_id = S.supp_id

			inner join tbUsers4BranchFilter					vubf
			ON  vubf.comp_id    = CT.comp_id
			AND vubf.bra_id     = CT.bra_id
			AND vubf.[user_id]  = @user_id


	Where	VWCT.comp_id	= @comp_id
	--and		CT.bra_id		= @bra_id	MOS
	and		(@custsupp		= -1 or VWCT.supp_id	= @custsupp)
	and		(@country_id	= -1 or S.country_id	= @country_id)
	and		(@state_id		= -1 or S.state_id		= @state_id)


	Group By 	VWCT.supp_id, S.supp_name
	order by	S.supp_name


	SELECT
		tmp.supp_id,
		tmp.supp_name,
		tmp.[A Futuro],
		tmp.[30 Dias],
		tmp.[60 Dias],
		tmp.[90 Dias],
		tmp.[+ 90 Dias]

	FROM #tmp_BalanceAging tmp

	WHERE tmp.[A Futuro]	<> 0
	   OR tmp.[30 Dias]		<> 0
	   OR tmp.[60 Dias]		<> 0
	   OR tmp.[90 Dias]		<> 0
	   OR tmp.[+ 90 Dias]	<> 0




	exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id, @page_id


	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	SELECT
			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 402
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id )	[params1],

			CASE @custsupp WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
	     		ELSE
										(Select Ts.supp_name
						FROM	tbSupplier ts
						WHERE	Ts.comp_id = @comp_id
						AND		Ts.supp_id = @custsupp)

			END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		WHERE t.ctrl_id = 57
      		--AND t.[lang_id] = @lang_id
      		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params3],
			CASE @country_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		Tc.country_desc
						FROM	tbsysCountry tc
						WHERE	tc.country_id= @country_id)
			END		[params4],

		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
		WHERE t.ctrl_id = 59
		--AND t.[lang_id] = @lang_id
		and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =@fun_id)		[params5],
		CASE @state_id WHEN -1 THEN
					(SELECT		tut.utexts_desc
						FROM	tbsysUniqueTexts tut
						WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE
					(SELECT		ts.state_desc
						FROM	tbsysState ts
						WHERE	Ts.state_id= @state_id)
			END		[params6],

		(SELECT tswn.word_desc FROM tbSysWordsNew tswn WHERE tswn.lang_id = @lang_id and tswn.wordsi_id = 3632)		[params7]


END
GO



create PROCEDURE [dbo].[spSupplierDigitalDocumentsType_GetCombo]
(
	@comp_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN
			-- ------------------------------------------------------
			-- Testing
			-- ------------------------------------------------------
			/*
				DECLARE
					@comp_id									INT,
					@item_id									INT
				SELECT
					@comp_id									= 1,
					@item_id									= 1
			*/
			-- ------------------------------------------------------

			SELECT
				tsddt.suppdk_id						[Id],
				tsddt.suppdk_desc					[Desc]

			FROM tbSupplierDigitalDocumentsType tsddt

			WHERE	tsddt.comp_id			= @comp_id

			ORDER BY tsddt.suppdk_desc

		END
