CREATE PROCEDURE [dbo].[spSupplierRelated2Brand_getDataByText]
(
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT,
	@comp_id AS INT,
	@bra_id  AS INT,
	@brand_id AS INT

)
AS

BEGIN

	SET NOCOUNT ON


	DECLARE @tmpSupplier TABLE(comp_id INT,supp_id INT PRIMARY KEY)

	INSERT INTO @tmpSupplier(comp_id, supp_id)
		SELECT	ts.comp_id,
				ts.supp_id
			FROM tbSupplier ts
			INNER JOIN tbSupplierBrandRelation tsbr
				ON	tsbr.comp_id = ts.comp_id AND
					tsbr.supp_id = ts.supp_id
			WHERE	ts.comp_id		= @comp_id AND
					tsbr.brand_id	= @brand_id

	IF @@ROWCOUNT = 0
		BEGIN

			INSERT INTO @tmpSupplier(comp_id, supp_id)
				SELECT	ts.comp_id,
						ts.supp_id
					FROM tbSupplier ts
					WHERE ts.comp_id = @comp_id

		END


	-- ---------------------------------------
	-- ---------------------------------------
	/*
	DECLARE
		@text		VARCHAR(300),
		@count		INT,
		@lang_id	INT
	SELECT
		@text		= 'M',
		@count		= 2,
		@lang_id	= 2
	*/
	-- ---------------------------------------

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- --------------------------------------------------------------------------------------------
	-- Seleccion Multiple
	-- --------------------------------------------------------------------------------------------
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')
	SET @text = REPLACE(@text,'++','+')



	DECLARE @selection_method	INT  --0:búsqueda normal  >0:búsqueda múltiple

	--se verifica si hay cadena '++'
	SELECT	@selection_method = CHARINDEX('+',@text) --COUNT(*) from dbo.fnSplitTable(@text,'++')

	--si hay alguna cadena '++' se recupera la cantidad
	IF @selection_method > 0
		SELECT @selection_method = COUNT(*) from dbo.fnSplitTable(@text,'+')


	--se recuperan todos los textos spliteados de la cadena '++'
	DECLARE @text0	varchar(300)
	DECLARE @text1	varchar(300)
	DECLARE @text2	varchar(300)
	DECLARE @text3	varchar(300)
	DECLARE @text4	varchar(300)
	DECLARE @text5	varchar(300)
	DECLARE @text6	varchar(300)
	DECLARE @text7	varchar(300)
	DECLARE @text8	varchar(300)
	DECLARE @text9	varchar(300)
	DECLARE @text10	varchar(300)

	IF @selection_method > 0
	BEGIN

		DECLARE cursor_data CURSOR FOR
		SELECT fst.items FROM dbo.fnSplitTable(@text,'+') fst
		OPEN cursor_data
		FETCH cursor_data INTO @text0
		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @text1 IS NULL SET @text1 = @text0 else
			IF @text2 IS NULL SET @text2 = @text0 else
			IF @text3 IS NULL SET @text3 = @text0 else
			IF @text4 IS NULL SET @text4 = @text0 else
			IF @text5 IS NULL SET @text5 = @text0 else
			IF @text6 IS NULL SET @text6 = @text0 else
			IF @text7 IS NULL SET @text7 = @text0 else
			IF @text8 IS NULL SET @text8 = @text0 else
			IF @text9 IS NULL SET @text9 = @text0 else
			IF @text10 IS NULL SET @text10 = @text0

			FETCH cursor_data INTO @text0
		END

		CLOSE cursor_data
		DEALLOCATE cursor_data
	end
	-- --------------------------------------------------------------------------------------------



	SELECT TOP (@count)
				Upper(dbo.PadRightString(ts.supp_name ,'.',50)) + ' | ' + isnull(convert(varchar,ts.supp_id),'') + ' | ' + isnull(convert(varchar,ts.supp_taxNumber),'') [supp_name],
				ts.supp_id
	FROM tbSupplier ts
	INNER JOIN @tmpSupplier tmp
		ON	tmp.comp_id = ts.comp_id AND
			tmp.supp_id = ts.supp_id

	WHERE		ts.comp_id = @comp_id			AND
				--ts.supp_name LIKE @text+'%'		AND

				(

					CASE
					    WHEN @selection_method = 0 AND ts.supp_name LIKE @text + '%'	 THEN	'True'
					    WHEN @selection_method = 1 AND ts.supp_name LIKE '%' + @text1 + '%'	 THEN	'True'
					    WHEN @selection_method = 2 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%'		 THEN	'True'
					    WHEN @selection_method = 3 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%'	 THEN	'True'
					    WHEN @selection_method = 4 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%'		 THEN	'True'
					    WHEN @selection_method = 5 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%'		 THEN	'True'
					    WHEN @selection_method = 6 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%'	 THEN	'True'
					    WHEN @selection_method = 7 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%'	 THEN	'True'
					    WHEN @selection_method = 8 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%' AND ts.supp_name LIKE '%' + @text8 + '%'		 THEN	'True'
					    WHEN @selection_method = 9 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%' AND ts.supp_name LIKE '%' + @text8 + '%' AND ts.supp_name LIKE '%' + @text9 + '%'		 THEN	'True'
					    WHEN @selection_method =10 AND ts.supp_name LIKE '%' + @text1 + '%' AND ts.supp_name LIKE '%' + @text2 + '%' AND ts.supp_name LIKE '%' + @text3 + '%' AND ts.supp_name LIKE '%' + @text4 + '%' AND ts.supp_name LIKE '%' + @text5 + '%' AND ts.supp_name LIKE '%' + @text6 + '%' AND ts.supp_name LIKE '%' + @text7 + '%' AND ts.supp_name LIKE '%' + @text8 + '%' AND ts.supp_name LIKE '%' + @text9 + '%' AND ts.supp_name LIKE '%' + @text10 + '%'		 THEN 'True'
					    ELSE	'False'
					END	= 'True'
				)


END
GO





