---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,
	@cust_name					NVARCHAR(200),
	@cust_name1					NVARCHAR(200),
	@cust_address				NVARCHAR(150),
	@cust_city					NVARCHAR(60),
	@cust_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@cust_phone1				NVARCHAR(200),
	@cust_phone2				NVARCHAR(200),
	@cust_fax					NVARCHAR(200),

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,
	@cust_taxIBNumber			NVARCHAR(50),
	@cust_web					NVARCHAR(500),
	@cust_partnerOf				NVARCHAR(100),
	@cust_contact				NVARCHAR(100),
	@cust_email					NVARCHAR(300),
	@cust_credit_max			NUMERIC(17,2),
	@cust_credit_own			NUMERIC(17,2),
	@cust_note1					NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT





SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@item_code					='1637 hs999',
	@cat_id						= 40 ,
	@subcat_id					= 3823 ,
	@subcataux_id				= -1 ,
	@ic_id						= 2  ,
	@item_desc					='desc',
	@item_detail				='detail',
	@item_vendorCode			='vendor code',
	@brand_id					= 75 ,
	@pres_id					= 69,
	@item_codeAlternative		='alternative code',
	@curr_id					= 1,
	@supp_id					= 8110 ,
	@item_trigger_tax_id		= 1,
	@item_upb					= 1,
	@item_upp					= 1,
	@item_mult					= 1,
	@item_commission			= 1,
	@item_commission_byReceive  = 1,
	@item_liquidation			= 1,
	@item_newness				= 0,
	@item_outlet				= 0,
	@item_expser				= 0,
	@item_expean				= 1,
	@item_disabled				= 0,
	@item_comboDisc_Cant1		= 1,
	@item_comboDisc_Cant2		= 1,
	@item_comboDisc_Disc1		= 1,
	@item_comboDisc_Disc2		= 1,
	@item_purOrd_Disc1			= 1,
	@item_purOrd_Disc2			= 1,
	@item_purOrd_Disc3			= 1,
	@item_markup_1				= 0,
	@item_markup_2				= 0,
	@item_markup_3				= 0,
	@item_markup_4				= 0,
	@item_markup_5				= 0,
	@item_markup_6				= 0,
	@item_markup_7				= 0,
	@item_markup_8				= 0,
	@item_annotation1			='anotation1',
	@item_annotation2			='',
	@item_WebSite_desc			='',
	@item_WebSite_vendorPage	='',
	@item_WebSite_vendorDrivers	='@item_WebSite_vendorDrivers',
	@item_WebSite_url4Image1	='@item_WebSite_url4Image1',
	@item_WebSite_url4Image2	='@item_WebSite_url4Image2',
	@item_WebSite_url4Image3	='@item_WebSite_url4Image3',
	@item_WebSite_url4Image4	='@item_WebSite_url4Image4',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10

*/
---------------------------------------------------------------------------------


set nocount on



BEGIN
	declare @return_value	INT

	if	@pt_id		= -1  SET @pt_id	= NULL
	if	@stcIB_Id	= -1  SET @stcIB_Id = 1
	if	@sk_id		= -1  SET @sk_id	= NULL
	if	@puco_id	= -1  SET @puco_id	= NULL
	if	@pd_id		= -1  SET @pd_id	= NULL


				BEGIN TRY

					INSERT INTO tbSupplier

						(
							comp_id,curr_id, supp_name, supp_name1, supp_address,
							supp_city, supp_zip, country_id, state_id, supp_phone1,
							supp_phone2, supp_fax,supp_email, pt_id, fc_id, tnt_id,
							supp_taxNumber,stcIB_Id,
							supp_taxIBNumber, supp_web, supp_partnerOf, supp_contact,
							supp_eMail_PurchaseSector,
							supp_annotation,sk_id,supp_migrationID,supp_paymentAddress,supp_RMA_address,
							puco_id,pd_id

						)
						VALUES
						(
							@comp_id,
							@curr_id,
							@supp_name,
							@supp_name1	,
							@supp_address,
							@supp_city,
							@supp_zip,
							@country_id	,
							@state_id	,
							@supp_phone1,
							@supp_phone2,
							@supp_fax,
							@supp_email,
							@pt_id,
							@fc_id,
							@tnt_id	,
							@supp_taxNumber	,
							@stcIB_Id,
							@supp_taxIBNumber,
							@supp_web,
							@supp_partnerOf	,
							@supp_contact,
							@supp_eMail_PurchaseSector,
							@supp_annotation,
							@sk_id,
							@supp_migrationID,
							@supp_paymentAddress,
							@supp_RMA_address,
							@puco_id,
							@pd_id
						)

						set	@return_value = IDENT_CURRENT('tbSupplier')   -- @@identity

					END TRY
					BEGIN CATCH
						set	@return_value = 0
					END CATCH

					IF @return_value <> 0
						BEGIN
							--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL

							EXEC [spSysScript_Suppliers_Cities]


						END



END


















GO





