CREATE PROCEDURE [dbo].[spSuppliers_Process_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@curr_id					INT,
	@supp_name					NVARCHAR(200),
	@supp_name1					NVARCHAR(200),
	@supp_address				NVARCHAR(150),
	@supp_city					NVARCHAR(60),
	@supp_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@supp_phone1				NVARCHAR(200),
	@supp_phone2				NVARCHAR(200),
	@supp_fax					NVARCHAR(200),
	@supp_email					NVARCHAR(300),
	@pt_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@supp_taxNumber				NVARCHAR(50),
	@stcIB_Id					INT,
	@supp_taxIBNumber			NVARCHAR(50),
	@supp_web					NVARCHAR(500),
	@supp_partnerOf				NVARCHAR(100),
	@supp_contact				NVARCHAR(100),
	@supp_eMail_PurchaseSector	NVARCHAR(4000),
	@supp_annotation			NVARCHAR(100),
	@sk_id						INT,
	@puco_id					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@curr_id					INT,
	@supp_name					NVARCHAR(200),
	@supp_name1					NVARCHAR(200),
	@supp_address				NVARCHAR(150),
	@supp_city					NVARCHAR(60),
	@supp_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@supp_phone1				NVARCHAR(200),
	@supp_phone2				NVARCHAR(200),
	@supp_fax					NVARCHAR(200),
	@supp_email					NVARCHAR(300),
	@pt_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@supp_taxNumber				NVARCHAR(50),
	@stcIB_Id					INT,
	@supp_taxIBNumber			NVARCHAR(50),
	@supp_web					NVARCHAR(500),
	@supp_partnerOf				NVARCHAR(100),
	@supp_contact				NVARCHAR(100),
	@supp_eMail_PurchaseSector	NVARCHAR(4000),
	@supp_annotation			NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT



SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@bra_id						INT,
	@curr_id					INT,
	@cust_name					NVARCHAR(200),
	@cust_name1					NVARCHAR(200),
	@cust_address				NVARCHAR(150),
	@cust_city					NVARCHAR(60),
	@cust_zip					NVARCHAR(50),
	@country_id					INT,
	@state_id					INT,
	@cust_phone1				NVARCHAR(200),
	@cust_phone2				NVARCHAR(200),
	@cust_fax					NVARCHAR(200),

	@st_id						INT,
	@disc_id					INT,
	@dl_id						INT,
	@ck_id						INT,
	@sm_id						INT,
	@act_id						INT,
	@ss_id						INT,
	@fc_id						INT,
	@tnt_id						INT,
	@cust_taxNumber				NVARCHAR(50),
	@cust_inactive				BIT,
	@stcIB_Id					INT,
	@cust_taxIBNumber			NVARCHAR(50),
	@cust_web					NVARCHAR(500),
	@cust_partnerOf				NVARCHAR(100),
	@cust_contact				NVARCHAR(100),
	@cust_email					NVARCHAR(300),
	@cust_credit_max			NUMERIC(17,2),
	@cust_credit_own			NUMERIC(17,2),
	@cust_note1					NVARCHAR(100),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''


	------Moneda-----------------------------------------------------------------------------------------------------------
	if	@curr_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Moneda'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.curr_id
			               FROM		tbsysCurrency tc		WITH (NOLOCK)
							WHERE	tc.curr_id		= @curr_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Moneda es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Nombre de Proveedor-----------------------------------------------------------------------------------------------------------
	if	@supp_name	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Nombre del Proveedor'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Domicilio-----------------------------------------------------------------------------------------------------------
	if	@supp_address	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Domicilio'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Localidad-----------------------------------------------------------------------------------------------------------
	if	@supp_city	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Localidad'
		END
	-----------------------------------------------------------------------------------------------------------------------

	------Pais-----------------------------------------------------------------------------------------------------------
	if	@country_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID País'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.country_id
			               FROM tbsysCountry		tc		WITH (NOLOCK)
							WHERE	tc.country_id		= @country_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de País es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Provincia-----------------------------------------------------------------------------------------------------------
	if	@state_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID Provincia'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tc.state_id
			               FROM tbsysState 	tc		WITH (NOLOCK)
			               WHERE tc.country_id = @country_id and
			               		 tc.state_id   = @state_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Provincia es incorrecto o no está relacionada al País'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	--------EMAIL-----------------------------------------------------------------------------------------------------------
	--if	@supp_email	= ''
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó el Email'
	--	END
	-------------------------------------------------------------------------------------------------------------------------


	--------Telefono-----------------------------------------------------------------------------------------------------------
	--if	@supp_phone1	= ''
	--	BEGIN
	--		SET	@bolIsOK		= 'False'
	--		SET @errormessage	= @errormessage + '---' + 'No ingresó el Teléfono'
	--	END
	-------------------------------------------------------------------------------------------------------------------------

	------Condicion de Compra-----------------------------------------------------------------------------------------------------------
	if	@pt_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Condición de Compra'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tpt.pt_id
			               FROM tbPurchaseTerms tpt		WITH (NOLOCK)
			               WHERE tpt.comp_id = @comp_id and
			               		 tpt.pt_id   = @pt_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Condición de Compra es incorrecto'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Clase Fiscal -----------------------------------------------------------------------------------------------------------
	if	@fc_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Clase Fiscal'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tfc.fc_id
			               FROM tbsysFiscalClass tfc		WITH (NOLOCK)
			               WHERE tfc.fc_id			= @fc_id AND
								 tfc.country_id		= @country_id)
				BEGIN
					IF NOT EXISTS (SELECT tfc.fc_id
			               FROM tbsysFiscalClass tfc		WITH (NOLOCK)
			               WHERE tfc.fc_id			= @fc_id AND
								 tfc.country_id		IS NULL )
								 BEGIN
								 	SET	@bolIsOK		= 'False'
									SET @errormessage	= @errormessage + '---' + 'El ID de Clase Fiscal es incorrecto o no corresponde al País adecuado'
								 END

				END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Tipo de Documento-----------------------------------------------------------------------------------------------------------
	if	@tnt_id	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Tipo de Documento'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT ttnt.tnt_id
			               FROM tbsysTaxNumberTypes								ttnt		WITH (NOLOCK)
			               INNER JOIN tbsysFiscalClassAvailableTaxNumberTypes	sfcatnt		WITH (NOLOCK)
						   ON sfcatnt.tnt_id	=	ttnt.tnt_id

			               WHERE ttnt.tnt_id	= @tnt_id AND
								 sfcatnt.fc_id	= @fc_id)
				BEGIN
					SET	@bolIsOK		= 'False'
					SET @errormessage	= @errormessage + '---' + 'El ID de Tipo de Documento es incorrecto o no corresponde a la Clase Fiscal adecuada'
				END
		END

	-----------------------------------------------------------------------------------------------------------------------


	------Nro de Doc-----------------------------------------------------------------------------------------------------------
	if	@fc_id <> 99999999 and @tnt_id <> 8 and @supp_taxNumber	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó # Identificación tributaria'
		END
	ELSE
		BEGIN
			IF EXISTS (SELECT tc.supp_id
			           FROM	 tbSupplier 			tc		WITH (NOLOCK)
			           WHERE tc.comp_id			= @comp_id			AND
			                 tc.supp_taxNumber	= @supp_taxNumber	AND
			                 tc.tnt_id			= @tnt_id)
					 BEGIN
                 		SET	@bolIsOK		= 'False'
						SET @errormessage	= @errormessage + '---' + '# Identificación tributaria(Con mismo Tipo de Documento) ya existe ' + @supp_taxNumber
					 END

				--END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Clase de Proveedor-----------------------------------------------------------------------------------------------------------
	IF	@sk_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT tsk.sk_id
					   FROM tbSupplierKind tsk		WITH (NOLOCK)
						WHERE	tsk.comp_id		= @comp_id AND
								tsk.sk_id		= @sk_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Clase de Proveedor es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------

	------Concepto de compra-----------------------------------------------------------------------------------------------------------
	IF	@puco_id	<> -1
		BEGIN
			IF NOT EXISTS (SELECT tpc.puco_id
			               FROM tbPurchaseConcept tpc		WITH (NOLOCK)
						WHERE	tpc.comp_id		= @comp_id AND
								tpc.puco_id		= @puco_id)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Concepto de Compra es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------

	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO



