-- MOS: 09-2008

CREATE PROCEDURE [dbo].[spSysAuthorizations_getDataById]
(
	@comp_id	as	int,
	@bra_id		as	int,
	@lang_id    as  int,
	@aut_id		as	int,
	@user_id	as  INT,
	@prof_id	AS	INT
)

as

/*
declare 	@comp_id	as	int,
			@bra_id		as	int,
			@lang_id    as  int,
			@aut_id		as	int,
			@user_id	as  INT

select		@aut_id			= 76,
			@comp_id		= 1,
			@bra_id			= 1,
			@lang_id		= 2,
			@user_id		= 1
*/

Select	SA.aut_id,
		IsNull(OV.optval_desc,SA.aut_desc)	[aut_desc]

	From	dbo.tbsysAuthorizations					SA			WITH (NOLOCK)

	Left Join dbo.tbAuthorizationsQualification		SAQ			WITH (NOLOCK)-- Verifica si esta des-habilitada para una determinada sucursal
		On		SA.aut_id	= SAQ.aut_id
			and SAQ.comp_id = @comp_id
			and SAQ.bra_id	= @bra_id

	Inner Join dbo.tbsysOptionsValues				OV			WITH (NOLOCK)-- Traduce
		On		OV.lang_id	= @lang_id
			and optval_class= 30
			and optval_id	= @aut_id

	INNER JOIN tbUser tu										WITH (NOLOCK)
		ON tu.[user_id] = @user_id

	Where		SA.aut_id	= @aut_id
			and IsNull(SAQ.aut_disabled,'False') = 'False'
			and (
					dbo.fnUserNeedAuthorizationByProfile(@comp_id,@bra_id,@user_id,@aut_id,@prof_id) = 'True'
						OR
					tu.user_mustAuthorizateOwnAuthorizations = 'True'
				)




--SELECT * FROM tbsysAuthorizations ta





















GO







-- Modificada x MOS  09-2008

CREATE PROCEDURE [dbo].[spSysAuthorizationsPages_getDataByPage]
(
	@page_id		as int,
	@comp_id		as int,
	@bra_id			as int,
	@lang_id		as int,
	@user_id		as INT,
	@prof_id		AS INT
)
as

/*
declare @page_id		int
select @page_id			= 11
*/

select	AP.aut_id								,
		IsNull(SOV.optval_desc,'*unTranslated*') [aut_desc]

from	dbo.tbSysAuthorizationsPages					AP
		Inner Join dbo.tbsysAuthorizations				A
			On A.aut_id	=	AP.aut_id
		Left  Join dbo.tbAuthorizationsQualification	AQ
			On		AQ.comp_id = @comp_id
				and AQ.bra_id  = @bra_id
			    and AQ.aut_id = A.aut_id
		Left  Join dbo.tbsysOptionsValues				SOV
			On SOV.optval_id	= A.aut_id	AND
			   sov.optval_class = 30		AND
			   sov.lang_id		= @lang_id
		INNER JOIN tbUser tu
			ON tu.[user_id] = @user_id

Where	AP.page_id						= @page_id
	and	isNull(AQ.aut_disabled,'false')	= 'false'
	and isNull(SOV.optval_class,30)  	= 30
	and isNull(SOV.lang_id,@lang_id)	= @lang_id
	AND (
			dbo.fnUserNeedAuthorizationByProfile(@comp_id,@bra_id,@user_id,AP.aut_id,@prof_id) = 'True'
				OR
			tu.user_mustAuthorizateOwnAuthorizations = 'True'
		)

	--and dbo.fnUserNeedAuthorization(@comp_id,@bra_id,@user_id,AP.aut_id) = 'True'

order by A.aut_id
























GO








