CREATE PROCEDURE [dbo].[spSysCountry_getCombo]
(
	@country_id		INT
)
AS

BEGIN

	DECLARE @tbCountry AS TABLE([id] INT,[desc] NVARCHAR(50))

	INSERT INTO @tbCountry

		select	country_id		[id],
				country_desc	[desc]

		from	tbsysCountry
		WHERE country_id = @country_id



	INSERT INTO @tbCountry
		select	country_id		[id],
				country_desc	[desc]

		from	tbsysCountry
		WHERE country_id <> @country_id
		Order By country_desc


	SELECT * FROM @tbCountry

END






GO







CREATE PROCEDURE [dbo].[spSysCountry_getComboByCustomer]
(
	@comp_id		INT,
	@cust_id		INT
)
AS

BEGIN

	SET NOCOUNT ON

	/*
	DECLARE		@comp_id		INT,
				@cust_id		INT
	SELECT		@comp_id		=1,
				@cust_id		=24288
	*/

	IF  @cust_id = -1
		select	tsc.country_id		[id],
				tsc.country_desc	[desc]

		from	tbsysCountry tsc

		Order By tsc.country_desc
	ELSE
		select	tsc.country_id		[id],
				tsc.country_desc	[desc]

		from	tbsysCountry tsc
				INNER JOIN tbCustomer tc
				ON	tc.country_id = tsc.country_id
				AND tc.comp_id = @comp_id
				AND tc.cust_id = @cust_id

		Order By tsc.country_desc

END
GO







