CREATE PROCEDURE [dbo].[spSysCurrency_getAllSymbols]
(
	@comp_id		INT,
	@bra_id			INT,
	@cust_id		INT,
	@supp_id		INT
)
AS
SET NOCOUNT ON


/*
DECLARE	@comp_id		INT,
		@bra_id			INT,
		@cust_id		INT,
		@supp_id		INT
SELECT	@comp_id		=1,
		@bra_id			=1,
		@cust_id		=0,
		@supp_id		=0
*/



SELECT	ISNULL((SELECT tc.curr_symbol
		FROM	tbBranch tb
				INNER JOIN tbsysCurrency tc
				ON tc.curr_id = tb.curr_id
		WHERE	tb.comp_id = @comp_id AND tb.bra_id  = @bra_id),'')		[(CB)],
		ISNULL((SELECT tc.curr_symbol
		FROM	tbCustomer tb
				INNER JOIN tbsysCurrency tc
				ON tc.curr_id = tb.curr_id
		WHERE	tb.comp_id = @comp_id AND tb.cust_id = @cust_id),'')	[(CC)],
		ISNULL((SELECT tc.curr_symbol
		FROM	tbSupplier tb
				INNER JOIN tbsysCurrency tc
				ON tc.curr_id = tb.curr_id
		WHERE	tb.comp_id = @comp_id AND tb.supp_id = @supp_id),'')	[(CS)]
GO






