-- Create date: 08-2009
-- Description:	Getcombo rapido de Development
-- =============================================
CREATE PROCEDURE [dbo].[spsysDevelopment_getCombo]
	@intEntity AS INT
AS
BEGIN
	SET NOCOUNT ON;

	/*
		1- Customer
		2- Developer
		3- Distributor
		4- Kind
		5- Status
		6- Urgency
	*/


	IF @intEntity = 1
		BEGIN
			SELECT	 tdc.sdc_id			[Id],
					 tdc.sdc_desc		[desc]
				FROM tbsysDevelopment_Customer		tdc
		END
	ELSE IF @intEntity = 2
		BEGIN
			SELECT	 tdc.sdd_id			[Id],
					 tdc.sdd_desc		[desc]
				FROM tbsysDevelopment_Developer		tdc
		END
	ELSE IF @intEntity = 3
		BEGIN
			SELECT	 tdc.sddi_id		[Id],
					 tdc.sddi_desc		[desc]
				FROM tbsysDevelopment_Distributor	tdc

		END
	ELSE IF @intEntity = 4
		BEGIN
			SELECT	 tdc.sdk_id			[Id],
					 tdc.sdk_desc		[desc]
				FROM tbsysDevelopment_Kind			tdc
				ORDER BY tdc.sdk_order
		END

	ELSE IF @intEntity = 5
		BEGIN
			SELECT	 tdc.sds_id			[Id],
					 tdc.sds_desc		[desc]
				FROM tbsysDevelopment_Status		tdc
				ORDER BY tdc.sds_order
		END

	ELSE IF @intEntity = 6
		BEGIN
			SELECT	 tdc.sdu_id			[Id],
					 tdc.sdu_desc		[desc]
				FROM tbsysDevelopment_Urgency		tdc
				ORDER BY tdc.sdu_order
		END


END

GO











