CREATE  PROCEDURE [dbo].[spSysERPMenuExeptions_deleteData]
(
	@sevt_id		int,
	@menu_id		int,
	@level			int
)
as

BEGIN



	set nocount on

	if @level = -1
	begin

		Delete	dbo.tbSysERPMenuExeptions
		where  sevt_id 	=	@sevt_id
		and		(@menu_id = -1 or menu_id_Excluded =	@menu_id)

	end
	else
	begin
	--Begin Transaction spAccountTransactionHead_deleteData

	Set @level = @level + 1

	-- -----------------------
	-- Para Evitar StackFault
	If @level > 30
	Begin
		Return
	End
	-- -----------------------


	Delete	dbo.tbSysERPMenuExeptions
	where	sevt_id					=	@sevt_id
	and		menu_id_Excluded		=	@menu_id


	declare @lmenu_id	int

	Declare @varCursor Cursor
	Set @varCursor = Cursor local FAST_FORWARD for
		Select menu_id From [tbSysMenu] where menu_id_sup = @menu_id

	Open @varCursor

	Fetch Next From @varCursor
	Into @lmenu_id

	While @@FETCH_STATUS = 0
	Begin

		Exec spSysERPMenuExeptions_deleteData @sevt_id, @lmenu_id,	@level

		Fetch Next From @varCursor
		Into @lmenu_id

	End

	Close @varCursor
	Deallocate @varCursor



	--IF @@Error = 0
	--	Commit Transaction spAccountTransactionHead_deleteData
	--Else
	--	ROLLBACK TRANSACTION spAccountTransactionHead_deleteData

	end

END
GO








CREATE  PROCEDURE [dbo].[spSysERPMenuExeptions_getData]
(
	@comp_id				int,
	@lang_id				int,
	@sevt_id				int,
	@menu_id_sup			INT
)
AS

/*

--select * from tbSysERPMenuExeptions tsee
--select * from tbsysMenu tm where tm.menu_id = 418

------------------------------------------------------------------

declare 	@comp_id				int,
			@lang_id				int,
			@menu_id_sup			INT,
			@sevt_id				INT

select 		@comp_id				=1,
			@lang_id				=2,
			@menu_id_sup			=0,
			@sevt_id				=10



	IF NOT OBJECT_ID('tempdb.dbo.#tmptbsysmenuparameters')		IS NULL DROP TABLE #tmptbsysmenuparameters

------------------------------------------------------------------
*/



BEGIN
	set nocount on
	select	distinct mp.menu_id,
			--tooltip3
			isnull((select	t.ptype_desc + '=' + v.[desc] + ','
					from	tbsysmenuparameters							m
							inner join tbsysparameterstype				t
							on	m.ptype_id		= t.ptype_id
							inner join [vwSysParametersTypeLangValuesClear]	v
							on	v.[type_id]		= m.[ptype_id]
							and	v.id			= m.ptypevalue_id
							AND v.lang_id		= @lang_id
					where	m.menu_id = mp.menu_id		and		m.ptype_id = 21),'')	+
			--tooltip4
			isnull((select	t.ptype_desc + '=' + v.[desc] + ','
					from	tbsysmenuparameters							m
							inner join tbsysparameterstype				t
							on	m.ptype_id		= t.ptype_id
							inner join [vwSysParametersTypeLangValuesClear]	v
							on	v.[type_id]		= m.[ptype_id]
							and	v.id			= m.ptypevalue_id
							AND v.lang_id		= @lang_id
					where	m.menu_id = mp.menu_id		and		m.ptype_id = 22),'') +
			--tooltip5
			isnull((select	t.ptype_desc + '=' + v.[desc] + ','
					from	tbsysmenuparameters							m
							inner join tbsysparameterstype				t
							on	m.ptype_id		= t.ptype_id
							inner join [vwSysParametersTypeLangValuesClear]	v
							on	v.[type_id]		= m.[ptype_id]
							and	v.id			= m.ptypevalue_id
							AND v.lang_id		= @lang_id
					where	m.menu_id = mp.menu_id		and		m.ptype_id = 32),'') [parameters]
	INTO	#tmptbsysmenuparameters
	FROM 	tbsysmenuparameters		mp
	WHERE	mp.ptype_id IN (21,22,32)



	select	distinct
			M.menu_id,
			M.menu_id_sup,
			M.menu_order,
			M.menu_type,
			isnull(L.mid_desc,M.menu_desc)					[menu_desc],
			CASE SUBSTRING(P.page_desc,1,3)
				WHEN 'wfm' then	isnull(P.page_desc + '.aspx', '')
				WHEN 'htm' THEN ISNULL(P.page_desc + '.htm', '')
				ELSE isnull(P.page_desc + '.aspx', '')
			end												[menu_page],
			case
				when MP.parameters is null					then ''
				when len(ltrim(rtrim(MP.parameters))) = 0	then ''
				else substring(MP.parameters,1,len(MP.parameters)-1)
			end	 +
			case
				when ttsmp.parameters is null					then ''
				when len(ltrim(rtrim(ttsmp.parameters))) = 0	then ''
				else ',' + substring(ttsmp.parameters,1,len(ttsmp.parameters)-1)
			end	 +
			case
				when M.menu_parameters is null					then ''
				when len(ltrim(rtrim(M.menu_parameters)))	= 0	then ''
				ELSE
					CASE WHEN LEN(MP.parameters) > 0 OR LEN(ttsmp.parameters) > 0 THEN ',' ELSE '' END
						+ M.menu_parameters
			end												[menu_parameters],

			M.menu_destiny,
			M.menu_imageurl_path


	from 	 tbsysMenu										M


			left join dbo.tbsysMenuLanguage					L
			on	L.menu_id				= M.menu_id
			and	L.lang_id				= @lang_id

			left join dbo.vwMenuParameters					MP
			on	MP.menu_id				= M.menu_id

			LEFT JOIN #tmptbsysmenuparameters				ttsmp
			ON	MP.menu_id				= ttsmp.menu_id

			left join dbo.tbsysPages						P
			on	P.page_id				= M.page_id

			inner join tbSysERPMenuExeptions				tsee
			on  tsee.sevt_id			= @sevt_id
			and tsee.menu_id_Excluded	= m.menu_id



	where	M.menu_id_sup		= @menu_id_sup

	order by [menu_order]

END
GO







CREATE  PROCEDURE [dbo].[spSysERPMenuExeptions_insertData]
(
	@sevt_id		int,
	@menu_id		int,
	@level			int
)
as

BEGIN



	set nocount on

	if @level = -1
	begin

		if not exists(SELECT TOP 1 1 from dbo.tbSysERPMenuExeptions
						where sevt_id = @sevt_id  and menu_id_Excluded = @menu_id)
		begin
			insert into dbo.tbSysERPMenuExeptions	(sevt_id,menu_id_Excluded)
			values									(@sevt_id,@menu_id)
		end

	end
	else
	begin


	Set @level = @level + 1

	-- -----------------------
	-- Para Evitar StackFault
	If @level > 30
	Begin
		Return
	End
	-- -----------------------


	insert into dbo.tbSysERPMenuExeptions
	(sevt_id,menu_id_Excluded)
	values
	(@sevt_id,@menu_id)


	declare @lmenu_id	int

	Declare @varCursor Cursor
	Set @varCursor = CURSOR LOCAL FAST_FORWARD for Select menu_id From [tbSysMenu] where menu_id_sup = @menu_id

	Open @varCursor

	Fetch Next From @varCursor
	Into @lmenu_id

	While @@FETCH_STATUS = 0
	Begin

		Exec spSysERPMenuExeptions_insertData @sevt_id,@lmenu_id,@level

		Fetch Next From @varCursor
		Into @lmenu_id

	End

	Close @varCursor
	Deallocate @varCursor



	end


END











GO







