--				WHEN ts.stcIB_Id = 10	THEN '2'
--				ELSE		 '1'		-- No tienen definido a que clase de Ingresos Brutos Corresponde.!!! , van como Contribuyente Local
--			End +

--			--: 13 :Nro Inscripción IB:::
