--				WHEN tc.stcIB_Id =	1	THEN RIGHT(@zeros + Replace(replace(tc.cust_taxIBNumber,'-',''),' ',''),11)
--				WHEN tc.stcIB_Id = 10	THEN RIGHT(@zeros + Replace(replace(tc.cust_taxIBNumber,'-',''),' ',''),11)
--				WHEN ts.stcIB_Id =	1	THEN RIGHT(@zeros + Replace(replace(ts.supp_taxIBNumber,'-',''),' ',''),11)
--				WHEN ts.stcIB_Id = 10	THEN RIGHT(@zeros + Replace(replace(ts.supp_taxIBNumber,'-',''),' ',''),11)
--				Else RIGHT(@zeros,11)
