--			 +

--			--: *18 :Monto sujeto a Ret./Percep.
--			replace(RIGHT(@zeros + convert(Varchar(12),convert(Decimal(11,2),Sum(ttm.tm_subtotal))),16),'.',',') +

--			--: 19 :Alícuota:::
