--				WHEN ttm.percentaje > 35 OR ttm.percentaje = 0 THEN replace(RIGHT(@zeros + convert(Varchar(5),convert(Decimal(24,2),ttm.tm_total / dbo.fnNoZDiv(ttm.tm_subtotal) / 100)),5),'.',',')
