--			--: *21 :Total Monto Retenido:::
--			replace(RIGHT(@zeros + convert(Varchar(12),convert(Decimal(11,2),dbo.fnSysExportData_getARCIBA20(Sum(ttm.tm_subtotal),ttm.percentaje, Sum(ttm.tm_total)) )),16),'.',',')
