CREATE PROCEDURE [dbo].[spSysExportData_getCITICompras]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			DATETIME,
	@brag_id			INT
)
as


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------





	-- -------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------
	/*
	DECLARE		@comp_id			Int,
				@lang_id			Int,
				@bra_id				Int,
				@sed_id				Int,
				@date_from			Datetime,
				@date_to			Datetime,
				@brag_id			INT

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@bra_id				=-1,
				@sed_id				=114,
				@date_from			='2015-01-01',
				@date_to			='2015-01-31',
				@brag_id			= 5
	*/
	-- -------------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------


	-- Genero tabla tamporal eliminando los numeros de comprobantes DUPLICADOS.  No se puede lograr con un Distinct
	SELECT	DISTINCT
			tct.comp_id,
			tct.ct_transaction,
			tct.supp_id,
			tct.ct_docNumber,
			0					[intID]
		INTO #tmpTable
		FROM tbCommercialTransactions tct
		INNER JOIN tbSupplier ts
			ON		ts.comp_id = tct.comp_id
				AND ts.supp_id = tct.supp_id
		WHERE	tct.comp_id = @comp_id
			--AND tct.bra_id  = @bra_id
			And		(
				(@brag_id = -1	AND		tct.bra_id	= @bra_id) OR
				(@brag_id <> -1 AND		EXISTS( SELECT 1
				                   					FROM	@tblBranchs tmpb
				                   					WHERE	tmpb.bra_id = tct.bra_id ))
					)
			AND tct.ct_taxDate BETWEEN @date_from AND @date_to
			and	dbo.fnTaxMovements_IVAOfCommercialTransaction(tct.comp_id,tct.bra_id,tct.ct_transaction) >= 1
			AND tct.ct_kindOf IN ('A','M')
			AND tct.sd_id IN (101,/*103,*/104,130,131)
			AND ts.tnt_id IN (1,21,31,41,51)
			AND dbo.fnStrAllTrim(IsNull(tct.ct_docNumber,'')) <> ''


	-- Genero una identidad virtual
	DELETE
		FROM #tmpTable
		FROM #tmpTable		 tmp
	WHERE EXISTS(	SELECT 1
						FROM #tmpTable tmp2
	             		WHERE	tmp2.ct_transaction <> tmp.ct_transaction
							AND dbo.fnStrPADL(dbo.fnGetOnlyNumbers(dbo.fnStrAllTrim(tmp.ct_docNumber)),20,'0') = dbo.fnStrPADL(dbo.fnGetOnlyNumbers(dbo.fnStrAllTrim(tmp2.ct_docNumber)),20,'0')
							AND tmp.supp_id = tmp2.supp_id)



	-- Impuesto mayor a 500 pesos
	SELECT	CASE
				WHEN tct.sd_id=101 AND tct.ct_kindOf = 'A'	THEN '01'
				WHEN tct.sd_id=103 AND tct.ct_kindOf = 'A'	THEN '03'
				WHEN tct.sd_id=104 AND tct.ct_kindOf = 'A'	THEN '02'
				WHEN tct.sd_id=101 AND tct.ct_kindOf = 'M'	THEN '51'
				WHEN tct.sd_id=103 AND tct.ct_kindOf = 'M'	THEN '53'
				WHEN tct.sd_id=104 AND tct.ct_kindOf = 'M'	THEN '52'
				WHEN tct.sd_id=130							THEN '39'   -- Despacho de Importacion
			END															+
			dbo.fnStrPADL(tct.ct_pointOfSale,4,'0')						+
			dbo.fnStrPADL(dbo.fnGetOnlyNumbers(dbo.fnStrAllTrim(tct.ct_docNumber)),20,'0')	+
			--dbo.fnStrPADL(dbo.fnStrAllTrim(tct.ct_docNumber),20,'0') +
			dbo.fnStrPADL(YEAR(tct.ct_taxDate),4,'0') + dbo.fnStrPADL(MONTH(tct.ct_taxDate),2,'0') + dbo.fnStrPADL(Day(tct.ct_taxDate),2,'0')	+
			dbo.fnStrPADL(replace(ts.supp_taxNumber,'-',''),11,'0')     +
			substring(dbo.fnStrPADR(substring(dbo.fnGetOnlyAlfaText( ts.supp_name),1,25),25,' '),1,25)							+
			dbo.fnStrPADL(Replace(Replace( CONVERT(DECIMAL(12,2), dbo.fnTaxMovements_IVAOfCommercialTransaction(tct.comp_id,tct.bra_id,tct.ct_transaction)),'.',''),',',''),12,'0')     +
			'00000000000' +
			'                         ' +
			'000000000000'


		FROM tbCommercialTransactions tct

		INNER JOIN vwSupplier ts
			ON		ts.comp_id			= tct.comp_id
				AND ts.supp_id			= tct.supp_id
				AND ts.ct_transaction	= tct.ct_transaction
		INNER JOIN #tmpTable tmp
			ON		tmp.comp_id			=		 tct.comp_id
				AND tmp.ct_transaction	= tct.ct_transaction

	WHERE ABS(dbo.fnTaxMovements_IVAOfCommercialTransaction(  tct.comp_id,tct.bra_id,tct.ct_transaction)) > 500


	UNION


	-- Impuesto menor o igual a 500 pesos
	SELECT	'00'														+
			dbo.fnStrPADL('',4,'0')						+
			dbo.fnStrPADL(dbo.fnGetOnlyNumbers(dbo.fnStrAllTrim('')),20,'0')	+
			--dbo.fnStrPADL(dbo.fnStrAllTrim(tct.ct_docNumber),20,'0') +
			'00000000'	+
			dbo.fnStrPADL(replace(ts.supp_taxNumber,'-',''),11,'0')     +
			substring(dbo.fnStrPADR(substring(dbo.fnGetOnlyAlfaText( ts.supp_name),1,25),25,' '),1,25)							+
			dbo.fnStrPADL(Replace(Replace( CONVERT(DECIMAL(12,2), SUM(dbo.fnTaxMovements_IVAOfCommercialTransaction(tct.comp_id,tct.bra_id,tct.ct_transaction))),'.',''),',',''),12,'0')     +
			'00000000000' +
			'                         ' +
			'000000000000'


		FROM tbCommercialTransactions tct

		INNER JOIN vwSupplier ts
			ON		ts.comp_id			= tct.comp_id
				AND ts.supp_id			= tct.supp_id
				AND ts.ct_transaction	= tct.ct_transaction
		INNER JOIN #tmpTable tmp
			ON		tmp.comp_id			=		 tct.comp_id
				AND tmp.ct_transaction	= tct.ct_transaction

	WHERE ABS(dbo.fnTaxMovements_IVAOfCommercialTransaction(  tct.comp_id,tct.bra_id,tct.ct_transaction)) <= 500
	GROUP BY tct.supp_id,tct.sd_id,tct.comp_id,
			 ts.supp_taxNumber,ts.supp_name


	DROP TABLE #tmpTable


END



-- ticket 1143 , se agregó la funciòn para obtener sòlo nùmeros ( fnGetOnlyNumbers )
-- al nùmero de despacho ( ct_docNumber ) . GA
GO





