CREATE PROCEDURE [dbo].[spSysExportData_getCITIVentas]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			DATETIME,
	@brag_id			INT
)
as



BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- -------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------
	/*
	DECLARE		@comp_id			Int,
				@lang_id			Int,
				@bra_id				Int,
				@date_from			Datetime,
				@date_to			DATETIME,
				@brag_id			INT

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@bra_id				=1,
				@date_from			='2014-06-01',
				@date_to			='2014-06-30',
				@brag_id			= 4
	DROP TABLE #tmp
	Drop table #tmpB
	DROP TABLE #tmpTaxMovements
	DROP TABLE #tmpTaxMovementsOtherTaxes
	*/
	-- -------------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------


	-- -----------------------------------------------------------------------------------------------------
	-- Crea un nuevo tbTaxmovements con la suma total por impuesto del subtotal, total y alicuota
	-- -----------------------------------------------------------------------------------------------------
	SELECT	ttm.comp_id,
			ttm.ct_transaction,
			ttm.tax_id,
			Sum(ttm.tm_subtotal)	[tm_subtotal] ,
			ttm.percentaje,
			Sum(ttm.tm_total)		[tm_total]
		Into #tmpTaxMovements
		FROM tbTaxMovements ttm
		Inner Join tbCommercialTransactions tct
				ON ttm.comp_id			= tct.comp_id
				AND ttm.bra_id			= tct.bra_id
				AND ttm.ct_transaction	= tct.ct_transaction
		INNER JOIN vwCommercialTransactions_forSales vctfs
			ON	vctfs.comp_id			= tct.comp_id
			AND vctfs.bra_id			= tct.bra_id
			AND	vctfs.ct_transaction	= tct.ct_transaction

		Inner Join tbTaxName								ttn
		On ttn.comp_id				= ttm.comp_id
		And ttn.tax_id				= ttm.tax_id

		Inner Join vwsysTaxClassIVA_Taxes					vtcit
		On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id
			And		tct.ct_date		Between		@date_from And @date_to
			AND ttm.tm_total <> 0
			--AND	   (ttm.tm_total <> 0 AND ttm.tm_total IS NOT NULL)
		GROUP BY ttm.comp_id,ttm.ct_transaction,ttm.tax_id,ttm.percentaje
	-- -----------------------------------------------------------------------------------------------------



--==
--SELECT * FROM #tmpTaxMovements
----==


	-- -----------------------------------------------------------------------------------------------------
	-- Crea un nuevo tbTaxmovements con la suma total por impuesto del subtotal, total y alicuota que no sean IVA
	-- -----------------------------------------------------------------------------------------------------
	SELECT	ttm.comp_id,
			ttm.ct_transaction,
			Sum(ttm.tm_subtotal)	[tm_subtotal] ,
			Sum(ttm.tm_total)		[tm_total]
		Into #tmpTaxMovementsOtherTaxes
		FROM tbTaxMovements ttm
		Inner Join tbCommercialTransactions tct
				ON ttm.comp_id			= tct.comp_id
				AND ttm.bra_id			= tct.bra_id
				AND ttm.ct_transaction	= tct.ct_transaction
		INNER JOIN vwCommercialTransactions_forSales vctfs
			ON	vctfs.comp_id			= tct.comp_id
			AND vctfs.bra_id			= tct.bra_id
			AND	vctfs.ct_transaction	= tct.ct_transaction

		Inner Join tbTaxName								ttn
		On ttn.comp_id				= ttm.comp_id
		And ttn.tax_id				= ttm.tax_id

		left Join vwsysTaxClassIVA_Taxes					vtcit
		On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id
			And		tct.ct_date		Between		@date_from And @date_to
			AND vtcit.tax_class IS NULL
			AND ttm.tm_total <> 0
		GROUP BY ttm.comp_id,ttm.ct_transaction
	ORDER BY ttm.ct_transaction
	-- -----------------------------------------------------------------------------------------------------

--==
--SELECT * FROM #tmpTaxMovementsOtherTaxes
--==


	Select asa.ct_transaction, Count(*) [Alicuotas]
	Into #tmpB
	from
	(Select ttm.ct_transaction
		From tbTaxMovements ttm
			Inner Join tbCommercialTransactions tct
				ON ttm.comp_id			= tct.comp_id
				AND ttm.bra_id			= tct.bra_id
				AND ttm.ct_transaction	= tct.ct_transaction
			INNER JOIN vwCommercialTransactions_forSales vctfs
				ON	vctfs.comp_id			= tct.comp_id
				AND vctfs.bra_id			= tct.bra_id
				AND	vctfs.ct_transaction	= tct.ct_transaction

			Inner Join tbTaxName								ttn
			On ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

			Inner Join vwsysTaxClassIVA_Taxes					vtcit
			On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id
			And		tct.ct_date		Between		@date_from And @date_to
			AND		ttm.tm_total <> 0
--==
--AND  ttm.ct_transaction = 987859
--==
		Group By ttm.ct_transaction, ttm.tax_id) [asa]

	Group By asa.ct_transaction


--==
--SELECT * FROM #tmpB
--==

	-- Saca el maximo taxId ya que luego se debe poner el importe total solo en el renglon final.
	SELECT	tct.ct_transaction, max(isnull(ttm.tax_id,0)) tax_id, 1 [marca]
	INTO	#tmp
	FROM	tbCommercialTransactions tct
			INNER JOIN vwCommercialTransactions_forSales vctfs
			ON	vctfs.comp_id			= tct.comp_id
			AND vctfs.bra_id			= tct.bra_id
			AND	vctfs.ct_transaction	= tct.ct_transaction
			inner JOIN tbTaxMovements ttm
			ON ttm.comp_id			= vctfs.comp_id
			AND ttm.bra_id			= vctfs.bra_id
			AND ttm.ct_transaction	= vctfs.ct_transaction

			Inner Join tbTaxName								ttn
			On ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

			Inner Join vwsysTaxClassIVA_Taxes					vtcit
			On	vtcit.tax_class			= ttn.tax_class

	where		tct.comp_id		=	@comp_id
		And		tct.ct_date		Between		@date_from And @date_to
		AND		ttm.tm_total <> 0
--==
--and ttm.ct_transaction = 987859
--==

	GROUP BY tct.ct_transaction
	ORDER BY 1,2

--==
--SELECT * FROM #tmp
--==





	Select	'1' +

			--::02 -Fecha de Comprobante::
			RIGHT(@zeros + convert(Varchar(4),datepart(Year	,tct.ct_date)),4) +
			RIGHT(@zeros + convert(Varchar(2),datepart(month,tct.ct_date)),2) +
			RIGHT(@zeros + convert(Varchar(2),datepart(Day	,tct.ct_date)),2) +

			--::03 -Tipo de Comprobante::
			RIGHT(@zeros   + convert(Varchar(2),isnull(TDF.tacd_id,0)),2) +

			--::04 -Contador Fiscal::
			RIGHT(@spaces, 1) +

			--::05 -NºPunto de Venta::
			RIGHT(@zeros + convert(Varchar(4),tct.ct_pointOfSale),4) +

			--::06 -NºComprobante Desde::
			RIGHT(@zeros + convert(Varchar(20),tct.ct_docNumber),20) +

			--::07 -NºComprobante Hasta::
			RIGHT(@zeros + convert(Varchar(20),tct.ct_docNumber),20) +

			--::08 -Código de documento identificatorio del comprador::
			RIGHT(@zeros   + convert(Varchar(2),isnull(ttnt.tnt_afip,0)),2) +

			--::09 -Nº de Identificación del comprador::
			RIGHT(@zeros + convert(Varchar(11),dbo.fnGetOnlyNumbers( isnull(replace(tc.cust_taxNumber,'-',''),0))    ),11) +

			--::10 -Apellido y Nombre o denominación del comprador::
			left( convert(Varchar(30),dbo.fnGetOnlyAlfaText( isnull(tc.cust_name,''))) + @spaces ,30)+

			--::11 -Importe total de la operación::
			CASE WHEN a.[marca] = 1 THEN
				RIGHT(@zeros + convert(Varchar(15),convert(Int,isnull(tct.ct_Total,0)*100)),15)
			ELSE
				RIGHT(@zeros,15)
			END +

			--:::12 -Total de conceptos que no integran el precio neto::
			CASE WHEN a.[marca] = 1 THEN
				RIGHT(@zeros + convert(Varchar(15),convert(Int,isnull(impalt.tm_Total,0)*100)),15)
			ELSE
				RIGHT(@zeros,15)
			END +

			--:::13 - Importe neto gavado::
			CASE WHEN isnull(ttm.percentaje,0) > 0 THEN
				RIGHT(@zeros + convert(Varchar(15),convert(Int,isnull(ttm.tm_subtotal,0)*100)),15)
			ELSE
				RIGHT(@zeros,15)
			End +




			--:::14 -Alicuota de IVA::::
			RIGHT(@zeros   + convert(Varchar(4),convert(Int,isnull(ttm.percentaje,0)*100)),4)+

			--::::15 -Impuesto Liquidado:::
			Case when isnull(ttm.percentaje,0) > 0 then
				RIGHT(@zeros + convert(Varchar(15),convert(Int,isnull(ttm.tm_total,0)*100)),15)
				Else
				RIGHT(@zeros + convert(Varchar(15),convert(Int,0)),15)
			End +


			--:::16 -Impuesto lquidado a RNI o perc. ano categoriz.::: << NO INFORMAR
			RIGHT(@zeros,15)	 +

			--:::17 -Importe de operaciones exentas:::
			CASE WHEN a.[marca] = 1 AND ttm.percentaje = 0 THEN
				RIGHT(@zeros   + convert(Varchar(15),convert(Int,isnull(ttm.tm_subtotal,0)*100)),15)
			ELSE
				RIGHT(@zeros,15)
			END +

			--:::18 -Importe de percep. o pagos a cta de impuesto nac.::: << NO INFORMAR
			RIGHT(@zeros,15)	 +

			--:::19 -::Importe de percepciones de Ingresos Brutos::: << NO INFORMAR
			RIGHT(@zeros,15)	 +

			--:::20 -Importe de percepciones de ingresos Municipales::: << NO INFORMAR
			RIGHT(@zeros,15)	 +

			--:::21 -Importe de impuestos internos::: << NO INFORMAR
			RIGHT(@zeros,15)	 +

			--:::22 -Tipo de Responsable::: << NO INFORMAR
			RIGHT(@zeros,2)	 +

			--:::23 -Código de Moneda::: << NO INFORMAR
			RIGHT(@spaces,3)	+

			--::24 -Tipo de Cambio::: << NO INFORMAR
			RIGHT(@zeros,10)	 +

			--:::25 -Cantidad de alicuotas de IVA::
			--RIGHT(@zeros,1)	 +

			RIGHT(@zeros + convert(Varchar(1),convert(Int,b.alicuotas)),1) +


			--:::26 -Código de operación::: << NO INFORMAR
			RIGHT(@spaces,1)	+

			--:::27 -CAI::: << NO INFORMAR
			RIGHT(@zeros,14) +

			--:::28 -Fecha de Vencimiento:: << NO INFORMAR
			RIGHT(@zeros,8)	+

			--::29 -Fecha de anulación del comprobante:: << NO INFORMAR
			RIGHT(@zeros,8)	 +

			--::30 -Informacion Adicional:: << NO INFORMAR
			RIGHT(@spaces,75)	+
			--::31 -Fecha de Pago de Retención::
			RIGHT(@zeros,8)	+
			--::32 -Importe Retención::
			RIGHT(@zeros,15)



	FROM	tbCommercialTransactions							tct

			Inner Join	vwCommercialTransactions_forSales		vctfs
			On	vctfs.comp_id			= tct.comp_id
			And vctfs.bra_id			= tct.bra_id
			And vctfs.ct_transaction	= tct.ct_transaction

			Inner Join	tbDocumentsFile							tdf
			On	tdf.comp_id				= tct.comp_id
			And	tdf.bra_id				= tct.bra_id
			AND tdf.df_id				= tct.df_id

			Inner Join	tbCustomer								tc
			On	tc.comp_id				= tct.comp_id
			And tc.cust_id				= tct.cust_id

--			Inner Join tbsysFiscalClassAvailableTaxNumberTypes	tfcatnt
--			On 	tfcatnt.fc_id			= tc.fc_id

			Inner Join	tbsysTaxNumberTypes						ttnt
			On	ttnt.tnt_id				=  tc.tnt_id -- tfcatnt.tnt_id

			inner Join #tmpTaxMovements							ttm
			ON		ttm.comp_id				= vctfs.comp_id
				AND ttm.ct_transaction		= vctfs.ct_transaction

			Inner Join tbTaxName								ttn
			On ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

			left JOIN #tmpTaxMovementsOtherTaxes impalt
				ON impalt.ct_transaction = tct.ct_transaction

			Inner Join vwsysTaxClassIVA_Taxes					vtcit
			On	vtcit.tax_class			= ttn.tax_class

			left Join #tmp										a
			ON  a.ct_transaction		= tct.ct_transaction
			AND a.tax_id				= isnull(ttm.tax_id,0)

			inner Join #tmpB										b
			ON  b.ct_transaction		=  isnull(tct.ct_transaction,0)

			Left Join tbsysTaxAFIP tta
			On tta.afip_cuit = replace(rtrim(tc.cust_taxNumber),'-','')


	Where	tct.comp_id			=  @comp_id
		AND	ISNULL(tc.cust_excludeInCITI,'false') = 'False'
		And	tct.ct_date	 Between   @date_from And @date_to
		AND tct.ct_total		<> 0
		And	tdf.tacd_id		    >  0
		--AND isnull(ttm.tm_subtotal,0) <> 0
		And b.[Alicuotas]		>  0
		And	tct.ct_docNumber	<>  ''
		And ((tdf.df_kindof		= 'A' And (tta.afip_impiva='AC'))
				or
			 (tdf.df_kindof		= 'B' And (tta.afip_impiva='EX' OR tta.afip_impiva IS NULL OR IsNull(tta.afip_impmon,'') <> ''))
			)

		AND 	(
					(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id))		OR

					(@brag_id	<> -1	AND	tct.bra_id IN (	SELECT	bgd.bra_id
															FROM	tbBranchGroupDetail bgd
															WHERE	bgd.brag_id = @brag_id))
				)

	GROUP BY tct.ct_transaction, a.[marca], tct.ct_date, tct.ct_pointOfSale,
			tct.ct_docNumber, tct.ct_Total, ttm.tm_subtotal, tct.ct_taxes,
			ttm.tm_total,ttm.percentaje,tdf.tacd_id, ttnt.tnt_afip, tc.cust_taxNumber, tc.cust_name,b.[alicuotas],tdf.df_toDate,impalt.tm_total


	ORDER BY tct.ct_date, tct.ct_transaction, a.[marca]


	-- Archivo de datos con errores.!


	Select  RIGHT(@zeros + convert(Varchar(5),isnull(tc.cust_id,0)),5)							[cust_id],
			tc.cust_name,
			tc.cust_taxNumber,
			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction),

			RIGHT(@zeros + convert(Varchar(2),datepart(Day	,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(2),datepart(month,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(4),datepart(Year	,tct.ct_date)),4)					[ct_date],

			convert(Decimal(14,4),isnull(tct.ct_total,0))										[ct_total]


	From tbCommercialTransactions tct

		Inner Join tbcustomer tc
		On  tc.comp_id = tct.comp_id
		and tc.cust_id = tct.cust_id

		Left Join tbsysTaxAFIP tta
		On tta.afip_cuit = replace(rtrim(tc.cust_taxNumber),'-','')

		Inner Join tbDocumentsFile tdf
		On  tdf.comp_id = tct.comp_id
		And tdf.df_id = tct.df_id

--			-- MOS 12-2012
--			left Join #tmp										a
--			ON  a.ct_transaction		= tct.ct_transaction
--			AND a.tax_id				= isnull(ttm.tax_id,0)
--
--			inner Join #tmpB										b
--			ON  b.ct_transaction		=  isnull(tct.ct_transaction,0)


	Where	tct.comp_id		=	@comp_id
	AND		ISNULL(tc.cust_excludeInCITI,'false') = 'False'
	And		tct.ct_date		Between		@date_from And @date_to
	And		tdf.tacd_id		> 0
	--And		b.[Alicuotas]			>  0
	And		TCT.ct_docNumber	<> ''
	AND     tct.ct_total <> 0
	AND 	(
				(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id))		OR

				(@brag_id	<> -1	AND	tct.bra_id IN (	SELECT	bgd.bra_id
														FROM	tbBranchGroupDetail bgd
														WHERE	bgd.brag_id = @brag_id))
			)

	And (	(tdf.df_kindof			= 'A' And tta.afip_impiva<>'AC')
				or
			(tdf.df_kindof			= 'B' And NOT (tta.afip_impiva='EX' OR tta.afip_impiva IS null OR IsNull(tta.afip_impmon,'') <> ''))
		)


END
GO












CREATE PROCEDURE [dbo].[spSysExportData_GetCombo]
(
	@comp_id			Int,
	@sed_appl			int
)
as

SET NOCOUNT ON

/*
DECLARE		@comp_id			INT,
			@sed_appl			int
SELECT 		@comp_id			= 1,
			@sed_appl			= 1
*/


	select		ted.sed_id		[id],
				ted.sed_desc	[desc]

		from		dbo.tbsysExportData ted				WITH (NOLOCK)

					--Inner JOIN tbCompany tc2
					--On tc2. = ted.country_id

		Where		ted.sed_appl	= @sed_appl

		Order BY	ted.sed_order	--ted.sed_desc
















GO






----------------------------------------------------------------------------
-- Para las FECHAS se convierte con dbo.fnSIAP_ConvertDate2StringAaAAMMDD(Fecha,'')
-- Para los NUMEROS se convierte con fnSIAP_ConvertDecimal2String(NUMERO,LONGITUD)
-- Para los CaraCTERES se convierte CON fnSIAP_ConvertString2FIXLength( String,Longitud )
-- Si hay que poner 16 ceros, poner el string sin el convert a char....

-- http://www.arba.gov.ar/Apartados/Agentes/remitoelectr%C3%B3nico.asp?lugar=E
----------------------------------------------------------------------------
--- ARBA - COT
--- MOS 04-2014
----------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSysExportData_getCOT]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@ds_id				INT,
	@OnlyCOT4State		BIT,
	@state_id4Filter	int
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE	@comp_id			INT
	DECLARE	@lang_id			INT
	DECLARE @bra_id				INT
	DECLARE @ds_id				INT
	DECLARE @OnlyCOT4State		BIT
	DECLARE @state_id4Filter	int

	SET		@comp_id			= 1
	SET		@lang_id			= 2
	SET		@bra_id				= 1
	SET		@ds_id				= 22
	SET		@OnlyCOT4State		= 'False'
	SET		@state_id4Filter	= 54002

	*/
	-- ----------------------------------------------------------



	-- Modo de Obtener Comprobantes Disponibles
	-- 0: Normal
	-- 1: Todas Las Sucursales
	-- 2: Todas Las Sucursales con sdlme=Enviar
	DECLARE @intMode AS INT
	SET		@intMode = 0
	SELECT  @intMode =  IsNull(tb.bra_deliverySheetMode,0)
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id





	DECLARE @tblCOT TABLE(Record NVARCHAR(1000), intOrder INT IDENTITY(1,1))

	-- 1er registro, cuit empresa
	-- Cursort para leer los remitos incluidos en la planilla
	-- por cada uno generar reqgistros del tipo 2 y del tipo 3
	--grabar registro del tipo 4 con la cuenta total
	-- hacer un select * de la temporal
	-- grabarlo en /temp y llamar al web service



	--VARIABLES DE TRABAJO
	DECLARE
		@cuit		VARCHAR(20),
		@planta		VARCHAR(20),			--Nº de Planta
		@puerta		VARCHAR(20),			--Nº de Puerta
		@AFIPDoc_CD	DATETIME,		--Fecha de Creación del Documento
		@secNumber	INT,			--Nº Secuencial

		@fileName	NVARCHAR(500),	--Nombre del Archivo Completo

		@RecordType1	CHAR(2),
		@RecordType2	CHAR(2),
		@RecordType3	CHAR(2),
		@RecordType4	CHAR(2)

	--CONSTANTES DE REGISTROS
	SET @RecordType1 = '01'
	SET @RecordType2 = '02'
	SET @RecordType3 = '03'
	SET @RecordType4 = '04'

	DECLARE @dl_id	INT
	SET @dl_id = NULL
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- DATOS PARA LA GENERACIÓN DEL NOMBRE DEL ARCHIVO
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @arba_cot_cust_id_alternativeDestiny AS INT
	--CUIT
	SELECT
		@cuit		= ISNULL(td.arba_cot_ORIGEN_CUIT,''),
		@planta		= ISNULL(td.arba_cot_Planta,''),
		@puerta		= ISNULL(td.arba_cot_Puerta,''),
		@secNumber	= ISNULL(td.arba_cot_Counter,0),
		@dl_id		= td.dl_id,
		@arba_cot_cust_id_alternativeDestiny = td.arba_cot_cust_id_alternativeDestiny
	FROM tbDelivery							td		WITH(NOLOCK)
		INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
		ON	tdsh.comp_id	= td.comp_id	AND
			tdsh.dl_id		= td.dl_id
	WHERE	tdsh.ds_id		= @ds_id


	UPDATE tbDelivery
		SET
			arba_cot_Counter = @secNumber + 1
		WHERE dl_id = @dl_id


	SELECT @AFIPDoc_CD = dbo.fnSIAP_ConvertDate2StringAaAAMMDD(GETDATE(),'')

	SELECT @fileName =	'TB'							+ '_' +
						CONVERT(VARCHAR,@cuit)			+ '_' +
						CONVERT(VARCHAR,@planta)		+ '' +									--STL ANTES TENIA ESTO EN LUGAR DE LO QUE ESTA AHORA + '_' +
						CONVERT(VARCHAR,@puerta)		+ '_' +
						REPLACE(CONVERT(VARCHAR, GETDATE(), 111), '/','') + '_' +
						dbo.fnSIAP_ConvertString2FIXLength2(CONVERT(VARCHAR,@secNumber), 6,'0')

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- OBTENEMOS LA CANTIDAD DE REMITOS QUE TIENE EL DS_ID ASOCIADOS
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		DECLARE
			@lIntDocumentCounter	INT

		SELECT @lIntDocumentCounter = COUNT(*)
			FROM tbDeliverySheetDetail tdsd
			INNER JOIN tbCommercialTransactions tct
				ON	tct.comp_id			= tdsd.comp_id AND
					tct.ct_transaction	= tdsd.ds_ct_transaction
			INNER JOIN tbCustomer tc
				ON	tc.comp_id			= tct.comp_id AND
					tc.cust_id			= tct.cust_id
			WHERE	tdsd.comp_id	= @comp_id	AND
					tdsd.ds_id		= @ds_id	AND
					(
						tct.state_id		= @state_id4Filter
							OR
						@OnlyCOT4State = 'False'
					)
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------
	-- Registro Tipo 01
	-- ---------------------------------------------------------
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType1 + '|' +
		CONVERT(VARCHAR,@cuit)
	-- ---------------------------------------------------------


	--VARIABLES DEL CURSOR
	DECLARE
			@emissionDate								DATETIME,

			@ds_ct_transaction							INT,

			@arba_cot_Fecha_Hora_Salida_Transporte		DATETIME,

			@esConsumidorFinal							BIT,

			@arba_cot_SUJETO_GENERADOR_IsDestiny		CHAR(1),

			@arba_cot_ORIGEN_CUIT						VARCHAR(11),
			@arba_cot_ORIGEN_RAZON_SOCIAL				VARCHAR(50),
			@arba_cot_EMISOR_TENEDOR					BIT,

			@arba_cot_ORIGEN_DOMICILIO_CALLE			VARCHAR(40),
			@arba_cot_ORIGEN_DOMICILIO_NUMERO			VARCHAR(5),
			@arba_cot_ORIGEN_DOMICILIO_COMPLE			VARCHAR(200),
			@arba_cot_ORIGEN_DOMICILIO_PISO				VARCHAR(3),
			@arba_cot_ORIGEN_DOMICILIO_DTO				VARCHAR(4),
			@arba_cot_ORIGEN_DOMICILIO_BARRIO			VARCHAR(30),
			@arba_cot_ORIGEN_DOMILILIO_CODIGOP			VARCHAR(8),
			@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD		VARCHAR(50),

			@arba_cot_ORIGEN_DOMICILIO_PROVINCIA		VARCHAR(1),  --dario 16/10/2018

			@arba_cot_TIPO_RECORRIDO					CHAR(1),
			@arba_cot_RECORRIDO_LOCALIDAD				VARCHAR(50),
			@arba_cot_RECORRIDO_CALLE					VARCHAR(40),
			@arba_cot_RECORRIDO_RUTA					VARCHAR(40),

			@arba_cot_PATENTE_VEHICULO					VARCHAR(7),
			@arba_cot_PATENTE_ACOPLADO					VARCHAR(7),
			@arba_cot_Counter							INT,
			@TRANSPORTISTA_CUIT							VARCHAR(11),
			@IMPORTE									DECIMAL(19,2),
			@state_id									INT


	DECLARE DocumentsHeader_Cursor CURSOR LOCAL FAST_FORWARD FOR

		--ACA VA EL SELECT
		SELECT

			tct.ct_date,						--FECHA EMISIÓN

			tdsd.ds_ct_transaction,

			tdsh.arba_cot_Fecha_Hora_Salida_Transporte,

			CASE tc.fc_id
				WHEN	2 THEN		1			--CONSUMIDOR FINAL
				ELSE				0
			END,
			CASE td.arba_cot_SUJETO_GENERADOR_IsDestiny
				WHEN	1 THEN		'D'
				ELSE				'E'
			END,

			td.arba_cot_ORIGEN_CUIT,
			td.arba_cot_ORIGEN_RAZON_SOCIAL,
			td.arba_cot_EMISOR_TENEDOR,

			td.arba_cot_ORIGEN_DOMICILIO_CALLE,
			td.arba_cot_ORIGEN_DOMICILIO_NUMERO,
			td.arba_cot_ORIGEN_DOMICILIO_COMPLE,
			td.arba_cot_ORIGEN_DOMICILIO_PISO,
			td.arba_cot_ORIGEN_DOMICILIO_DTO,
			td.arba_cot_ORIGEN_DOMICILIO_BARRIO,
			td.arba_cot_ORIGEN_DOMILILIO_CODIGOP,
			td.arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,

			ISNULL(ts.state_arba_cot,' ') as arba_cot_ORIGEN_DOMICILIO_PROVINCIA,

			--td.arba_cot_EMISOR_TENEDOR,
			--td.arba_cot_ORIGEN_CUIT,
			--td.arba_cot_ORIGEN_RAZON_SOCIAL,

			tdsh.arba_cot_TIPO_RECORRIDO,
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_LOCALIDAD,50),



			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_CALLE,40),
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_RUTA,40),

			td.arba_cot_PATENTE_VEHICULO,
			td.arba_cot_PATENTE_ACOPLADO,
			td.arba_cot_Counter,
			ISNULL(td.dl_taxNumber,' '),
			--tct.ct_total,
			CASE	-- MOS 12-2022 x GN 17647
				WHEN tdf.df_COT_isOverNETO = 'True' THEN	tct.ct_total
				ELSE										tct.ct_subtotal
			END,
			tct.state_id

		FROM tbDelivery							td		WITH(NOLOCK)

			INNER JOIN tbsysState				ts      WITH(NOLOCK)   --dario 16/10/2018
			ON	ts.country_id	= td.country_id AND
				ts.state_id		= td.state_id

			INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
			ON	tdsh.comp_id	= td.comp_id	AND
				tdsh.dl_id		= td.dl_id
			INNER JOIN tbDeliverySheetDetail	tdsd	WITH(NOLOCK)
			ON	tdsd.comp_id	= tdsh.comp_id	AND
				--tdsd.bra_id		= tdsh.bra_id	AND
				tdsd.ds_id		= tdsh.ds_id

			INNER JOIN tbCommercialTransactions	tct		WITH(NOLOCK)
			ON	tct.comp_id			= td.comp_id				AND
				tct.ct_transaction	= tdsd.ds_ct_transaction	--AND
				--tct.sd_id			IN (2)

			-- MOS 12-2022 x GN 17647
			LEFT JOIN tbDocumentsFile		 AS tdf		WITH (NOLOCK)
				ON	tdf.comp_id		= tct.comp_id AND
					tdf.df_id		= tct.df_id



			INNER JOIN tbCustomer				tc		WITH(NOLOCK)
			ON	tc.comp_id		= tct.comp_id	AND
				tc.cust_id		= tct.cust_id

		WHERE	tdsh.comp_id	= @comp_id		AND
				tdsh.ds_id		= @ds_id		AND
			   (tct.state_id	= @state_id4Filter OR @OnlyCOT4State = 'False')
			   --(tc.state_id		= 54020 OR @OnlyCOT4State = 'False')


	OPEN DocumentsHeader_Cursor

	FETCH NEXT FROM DocumentsHeader_Cursor
	INTO
		@emissionDate,

		@ds_ct_transaction,

		@arba_cot_Fecha_Hora_Salida_Transporte,

		@esConsumidorFinal,

		@arba_cot_SUJETO_GENERADOR_IsDestiny,

		@arba_cot_ORIGEN_CUIT,
		@arba_cot_ORIGEN_RAZON_SOCIAL,
		@arba_cot_EMISOR_TENEDOR,

		@arba_cot_ORIGEN_DOMICILIO_CALLE,
		@arba_cot_ORIGEN_DOMICILIO_NUMERO,
		@arba_cot_ORIGEN_DOMICILIO_COMPLE,
		@arba_cot_ORIGEN_DOMICILIO_PISO,
		@arba_cot_ORIGEN_DOMICILIO_DTO,
		@arba_cot_ORIGEN_DOMICILIO_BARRIO,
		@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
		@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
		@arba_cot_ORIGEN_DOMICILIO_PROVINCIA, --Dario 16/10/2018

		@arba_cot_TIPO_RECORRIDO,
		@arba_cot_RECORRIDO_LOCALIDAD,
		@arba_cot_RECORRIDO_CALLE,
		@arba_cot_RECORRIDO_RUTA,

		@arba_cot_PATENTE_VEHICULO,
		@arba_cot_PATENTE_ACOPLADO,
		@arba_cot_Counter,
		@TRANSPORTISTA_CUIT,
		@IMPORTE,
		@state_id

		WHILE @@FETCH_STATUS = 0
			BEGIN



				-- ----------------------------------------------------------------------------------------------------------------
				-- PARA VER SI TIENE ARTICULOS EN EL CT_TRANSACTION O TENGO QUE IR A BUSCARLO A "ct_transaction_packinglist"
				-- ----------------------------------------------------------------------------------------------------------------
				DECLARE
					@lCT_TRANSACTION	INT

				IF (SELECT COUNT(*)
						FROM tbCommercialTransactions						tct	WITH(NOLOCK)
							INNER JOIN tbItemTransactions					tit	WITH(NOLOCK)
							ON	tit.comp_id			= tct.comp_id			AND
								tit.ct_transaction	= tct.ct_transaction
						WHERE	tct.comp_id			= @comp_id				AND
								tct.ct_transaction	= @ds_ct_transaction	AND
								CASE
									WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
									WHEN @intMode <> 2						THEN 1
									ELSE 0
								END	= 1
					) = 0

					BEGIN

						--SI ES UN REMITO Y NO TIENE ARTÍCULOS LE ASIGNA EL PACKINK_LIST
						SELECT
							@lCT_TRANSACTION		= tct.ct_transaction_PackingList
						  FROM tbCommercialTransactions						tct
						WHERE	tct.comp_id			= @comp_id				AND
								tct.ct_transaction	= @ds_ct_transaction
					END


				ELSE
					BEGIN
						--SINO, SETEA EL MISMO CT_TRANSACTION
						SET @lCT_TRANSACTION = @ds_ct_transaction
					END


--==
--SELECT '@lCT_TRANSACTION:', @lCT_TRANSACTION
--==

				-- ----------------------------------------------------------------------------------------------------------------

				--ARMAMOS EL CODIGO_UNICO

				DECLARE
					@CODIGO_UNICO	VARCHAR(16)
				DECLARE @strDeliveryAddress AS NVARCHAR(4000)



				SELECT @strDeliveryAddress =
												CASE
													WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
														 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
													WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
													WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
													WHEN ISNULL(cust.cust_address4Delivery,'') <> ''	THEN cust.cust_address4Delivery
													ELSE													 cust.cust_address
												END
					FROM tbCommercialTransactions CT

					LEFT join dbo.tbCommercialTransactionNotes		CTN
					on	CTN.comp_id				= CT.comp_id
					and	CTN.bra_id				= CT.bra_id
					and CTN.ct_transaction		= CT.ct_transaction


					LEFT join dbo.tbCustomer						cust
					on  cust.comp_id				= ct.comp_id AND
						cust.cust_id				= ct.cust_id


					LEFT JOIN tbCustomerFamily tcf
						ON	tcf.comp_id		= ct.comp_id AND
							tcf.cust_id		= ct.cust_id AND
							tcf.custf_id	= ct.custf_id

					LEFT JOIN tbCustomerBranch tcb
						ON		tcb.comp_id = ct.comp_id
							AND tcb.cust_id = ct.cust_id
							AND tcb.cb_id	= ct.cb_id

					WHERE	CT.comp_id			= @comp_id AND
							CT.ct_transaction	= @ds_ct_transaction



				SELECT
					@CODIGO_UNICO = CASE
										WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '091'
										WHEN tct.sd_id = 2						    THEN '094'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '001'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '006'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '011'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '051'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '060'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '061'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '093'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '058'

										ELSE										    '099'
									END

										/*'91 R'*/ + '' +
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 5,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]		NEW de 4 a 5
					--@CODIGO_UNICO = CASE
					--					WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '91 R'
					--					WHEN tct.sd_id = 2						    THEN '94 X'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '01 A'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '06 B'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '92 C'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '51 M'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '60 A'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '61 B'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '93 C'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '58 M'

					--					ELSE										    '97 E'
					--				END

					--					/*'91 R'*/ + '' +
					--dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 4,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_docNumber, 8,'0')									--[NUMERO_DOCNUMBER]

					FROM tbCommercialTransactions tct

					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction --@lCT_TRANSACTION

				-- ----------------------------------------------------------------------------------------------------------------


				--OBTENEMOS LOS DATOS DEL CLIENTE
				DECLARE @lcust_id	INT
				SELECT @lcust_id = tct.cust_id
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction


				-- Se usa para el caso de Entregar a un transporte en el que la mercaderia sale de nuestra empresa pero el
				-- destino NO es el cliente sino que es el transporte.
				IF @arba_cot_cust_id_alternativeDestiny IS NOT NULL
					BEGIN
						SET @lcust_id = @arba_cot_cust_id_alternativeDestiny
					END



				DECLARE
					@DESTINATARIO_TIPO_DOCUMENTO		VARCHAR(3),
					@DESTINATARIO_DOCUMENTO				VARCHAR(11),
					@DESTINATARIO_CUIT					VARCHAR(11),
					@DESTINATARIO_RAZON_SOCIAL			VARCHAR(50),
					@DESTINATARIO_TENEDOR				BIT,
					@DESTINO_DOMICILIO_CALLE			VARCHAR(40),
					@DESTINO_DOMICILIO_NUMERO			VARCHAR(5),
					@DESTINO_DOMICILIO_COMPLE			VARCHAR(5),
					@DESTINO_DOMICILIO_PISO				VARCHAR(3),
					@DESTINO_DOMICILIO_DTO				VARCHAR(4),
					@DESTINO_DOMICILIO_BARRIO			VARCHAR(30),
					@DESTINO_DOMICILIO_CODIGOP			VARCHAR(8),
					@DESTINO_DOMICILIO_LOCALIDAD		VARCHAR(50),
					@DESTINO_DOMICILIO_PROVINCIA		VARCHAR(1),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	VARCHAR(50)

				-- *************************************************************************************
				-- SEPARAMOS EL NUMERO DE LA DIRECCION
				-- NOTA: SEPARA TODOS LOS NUMEROS, POR ENDE SI LA DIRECCION ES '25 de Mayo 3323'
				--       EL RESULTADO SERA '253323' <-- TODOS LOS NUMEROS CONCATENADOS
				--       DE MOMENTO NO HAY UNA SOLUCION MEJOR
				-- *************************************************************************************
				DECLARE @thestring VARCHAR(50)
				SET @thestring = @strDeliveryAddress --(SELECT tc.cust_address FROM tbCustomer tc WHERE tc.comp_id = @comp_id AND tc.cust_id = @lcust_id)
				DECLARE @final VARCHAR(50)
				SET @final = ''

				SELECT @final = @final + x.thenum
				FROM
				(
					SELECT SUBSTRING(@thestring, number, 1) AS thenum, number
					FROM master..spt_values
					WHERE substring(@thestring, number, 1) LIKE '[0-9]' AND TYPE='P'
				) x
				ORDER BY x.number
				DECLARE
					@DESTINO_DOMICILIO_NUMEROFINAL VARCHAR(5)
				SET @DESTINO_DOMICILIO_NUMEROFINAL = @final
				-- *************************************************************************************



				SELECT
					@DESTINATARIO_TIPO_DOCUMENTO		= ISNULL(ttnt.tnt_ARBACOT,' '),
					@DESTINATARIO_DOCUMENTO				= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_CUIT					= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_RAZON_SOCIAL			= ISNULL(tc.cust_name,' '),
					@DESTINATARIO_TENEDOR				= CASE @esConsumidorFinal
															  WHEN 1 THEN 0
															  ELSE        1
					                     				  END,	--SI ES CONSUMIDOR FINAL es CERO, SINO es 1
					@DESTINO_DOMICILIO_CALLE			= ISNULL(@strDeliveryAddress /*tc.cust_address*/,' '), --COMO SEPARO EL NUMERO DE LA CALLE PARA PONERLO ABAJO????
					@DESTINO_DOMICILIO_NUMERO			= ISNULL(@DESTINO_DOMICILIO_NUMEROFINAL,' '),
					@DESTINO_DOMICILIO_COMPLE			= 'S/N', --ISNULL(tc.cust_address,' '),
					@DESTINO_DOMICILIO_PISO				= ' ',
					@DESTINO_DOMICILIO_DTO				= ' ',
					@DESTINO_DOMICILIO_BARRIO			= ' ',
					@DESTINO_DOMICILIO_CODIGOP			= ISNULL(tc.cust_zip,' '),
					@DESTINO_DOMICILIO_LOCALIDAD		= ISNULL(tc.cust_city,' '),
					@DESTINO_DOMICILIO_PROVINCIA		= ISNULL(ts.state_arba_cot,' '),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	= ' '

					FROM tbCustomer							tc
						INNER JOIN tbsysState				ts			WITH (NOLOCK)
							ON ts.state_id = @state_id
						--ON	ts.country_id	= tc.country_id AND
						--	ts.state_id		= tc.state_id

						INNER JOIN tbsysTaxNumberTypes		ttnt
						ON	ttnt.tnt_id		= tc.tnt_id

				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @lcust_id



				SET @arba_cot_Fecha_Hora_Salida_Transporte = GETDATE()


				IF @DESTINATARIO_TIPO_DOCUMENTO = ''
					BEGIN
						SET @DESTINATARIO_DOCUMENTO	 = ''
					END

				IF @esConsumidorFinal = 1
					BEGIN
						set @DESTINATARIO_CUIT = ''
					END
				IF @esConsumidorFinal = 0
					BEGIN
						set @DESTINATARIO_TIPO_DOCUMENTO = ''
						set @DESTINATARIO_DOCUMENTO		 = ''
					END
				set @DESTINATARIO_CUIT = REPLACE(@DESTINATARIO_CUIT,'-','')

				if @DESTINO_DOMICILIO_COMPLE = 'S/N'
					BEGIN
						set @DESTINO_DOMICILIO_NUMERO = ''
					END


				--INSERTAMOS EL SEGUNDO REGISTRO CON LOS DATOS DEL TRANSPORTE Y DE A QUIEN SE LO ENVIAMOS
				--SELECT @lCT_TRANSACTION
				INSERT INTO @tblCOT
				(
					Record
				)
				SELECT
					@RecordType2																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @emissionDate, 111), '/',''),' ')							+ '|' +		--FECHA
					@CODIGO_UNICO																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 111), '/',''),' ')	+ '|' +		--FECHA
					substring(ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 108), ':',''),'    '),1,4)	+ '|' +		--HORA
					@arba_cot_SUJETO_GENERADOR_IsDestiny														+ '|' +		--SUJETO_GENERADOR E(emisor) D(destinatario)
					ISNULL(CONVERT(VARCHAR,@esConsumidorFinal),' ')												+ '|' +
					ISNULL(@DESTINATARIO_TIPO_DOCUMENTO,' ')													+ '|' +
					ISNULL(@DESTINATARIO_DOCUMENTO,' ')															+ '|' +
					ISNULL(@DESTINATARIO_CUIT,' ')																+ '|' +
					ISNULL(@DESTINATARIO_RAZON_SOCIAL,' ')														+ '|' +
					ISNULL(CONVERT(VARCHAR,@DESTINATARIO_TENEDOR),' ')											+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CALLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_NUMERO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_COMPLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PISO,' ')															+ '|' +
					ISNULL(@DESTINO_DOMICILIO_DTO	,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_BARRIO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CODIGOP,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PROVINCIA,' ')													+ '|' +
					ISNULL(@PROPIO_DESTINO_DOMICILIO_CODIGO,' ')												+ '|' +
					'NO'																						+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					ISNULL(@arba_cot_ORIGEN_CUIT,' ')															+ '|' +
					ISNULL(@arba_cot_ORIGEN_RAZON_SOCIAL,' ')													+ '|' +
					ISNULL(CONVERT(VARCHAR,@arba_cot_EMISOR_TENEDOR),' ')										+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_CALLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_NUMERO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_COMPLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PISO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_DTO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_BARRIO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMILILIO_CODIGOP,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,' ')											+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,' ')													+ '|' + --Dario 16/10/2018
					@TRANSPORTISTA_CUIT																			+ '|' +		--TAX_NUMBER de DELIVERY
					ISNULL(@arba_cot_TIPO_RECORRIDO	,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@arba_cot_RECORRIDO_CALLE,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_RUTA,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_VEHICULO,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_ACOPLADO,' ')														+ '|' +
					'0'																							+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					dbo.fnSIAP_ConvertDecimal2String(CONVERT(VARCHAR,@IMPORTE), 10)												--IMPORTE


				-- ---------------------------------------------------------------------------------------------------------------
				-- CURSOR DE PROCESAMIENTO DE ARTÍCULOS DE CADA REMITO
				-- ---------------------------------------------------------------------------------------------------------------

				DECLARE
					@arbaCOT_Nomenclador	VARCHAR(15),
					@item_measureARBA		VARCHAR(15),
					@qty					INT,
					@item_code				VARCHAR(25),
					@item_desc				VARCHAR(40),
					@item_measure			VARCHAR(20)




				DECLARE DocumentItemsDetail_Cursor CURSOR FOR

					--ACA VA EL SELECT
					SELECT
						ISNULL(ti.arbaCOT_Nomenclador,' '),
						ISNULL(tamu.cot_um_id,' '),
						ISNULL(tit.it_qty,' '),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_code,' '),25),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_desc,' '),40),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(tmu.mu_shortDesc,' '),20)


					FROM tbItemTransactions							tit		WITH(NOLOCK)
						INNER JOIN tbItem							ti		WITH(NOLOCK)
						ON  ti.comp_id			= tit.comp_id		AND
							ti.item_id			= tit.item_id
						LEFT JOIN tbMetricUnits						tmu		WITH(NOLOCK)
						ON	tmu.comp_id			= ti.comp_id		AND
							tmu.mu_id			= ti.mu_id
						INNER JOIN tbsysARBACOT_MetricUnit			tamu	WITH(NOLOCK)
						ON	tamu.cot_um_id		= tmu.cot_um_id


					WHERE	tit.comp_id			= @comp_id			AND
							--tit.bra_id			= @bra_id			AND
							tit.ct_transaction	= @lCT_TRANSACTION	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1									AND
							IsNull(ti.arbaCOT_Nomenclador,'') <> ''


				OPEN DocumentItemsDetail_Cursor
				FETCH NEXT FROM DocumentItemsDetail_Cursor
				INTO
					@arbaCOT_Nomenclador,
					@item_measureARBA,
					@qty,
					@item_code,
					@item_desc,
					@item_measure

				WHILE @@FETCH_STATUS = 0
					BEGIN


						INSERT INTO @tblCOT
						(
							Record
						)
						SELECT
							@RecordType3															+ '|' +
							@arbaCOT_Nomenclador													+ '|' +
							@item_measureARBA														+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	+ '|' +
							CONVERT(VARCHAR,@item_code)												+ '|' +
							CONVERT(VARCHAR,@item_desc)												+ '|' +
							CONVERT(VARCHAR,@item_measure)											+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	--CONVERTIMOS A VARCHAR PARA PODER CONCATENARLO



						FETCH NEXT FROM DocumentItemsDetail_Cursor
						INTO
							@arbaCOT_Nomenclador,
							@item_measureARBA,
							@qty,
							@item_code,
							@item_desc,
							@item_measure

					END



				CLOSE DocumentItemsDetail_Cursor
				DEALLOCATE DocumentItemsDetail_Cursor

				-- ---------------------------------------------------------------------------------------------------------------


				FETCH NEXT FROM DocumentsHeader_Cursor
				INTO
					@emissionDate,

					@ds_ct_transaction,

					@arba_cot_Fecha_Hora_Salida_Transporte,

					@esConsumidorFinal,

					@arba_cot_SUJETO_GENERADOR_IsDestiny,

					@arba_cot_ORIGEN_CUIT,
					@arba_cot_ORIGEN_RAZON_SOCIAL,
					@arba_cot_EMISOR_TENEDOR,

					@arba_cot_ORIGEN_DOMICILIO_CALLE,
					@arba_cot_ORIGEN_DOMICILIO_NUMERO,
					@arba_cot_ORIGEN_DOMICILIO_COMPLE,
					@arba_cot_ORIGEN_DOMICILIO_PISO,
					@arba_cot_ORIGEN_DOMICILIO_DTO,
					@arba_cot_ORIGEN_DOMICILIO_BARRIO,
					@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
					@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
					@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,  --Dario 16/10/2018

					@arba_cot_TIPO_RECORRIDO,
					@arba_cot_RECORRIDO_LOCALIDAD,
					@arba_cot_RECORRIDO_CALLE,
					@arba_cot_RECORRIDO_RUTA,

					@arba_cot_PATENTE_VEHICULO,
					@arba_cot_PATENTE_ACOPLADO,
					@arba_cot_Counter,
					@TRANSPORTISTA_CUIT,
					@IMPORTE,
					@state_id

			END

		CLOSE DocumentsHeader_Cursor
	DEALLOCATE DocumentsHeader_Cursor

	--INSERTAMOS EL CUARTO REGISTRO
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType4							+ '|' +
		CONVERT(VARCHAR,@lIntDocumentCounter)


	SELECT @fileName
	SELECT tmp.Record  FROM @tblCOT tmp ORDER BY tmp.intOrder

END
--1
GO





----------------------------------------------------------------------------
-- Para las FECHAS se convierte con dbo.fnSIAP_ConvertDate2StringAaAAMMDD(Fecha,'')
-- Para los NUMEROS se convierte con fnSIAP_ConvertDecimal2String(NUMERO,LONGITUD)
-- Para los CaraCTERES se convierte CON fnSIAP_ConvertString2FIXLength( String,Longitud )
-- Si hay que poner 16 ceros, poner el string sin el convert a char....

-- http://www.arba.gov.ar/Apartados/Agentes/remitoelectr%C3%B3nico.asp?lugar=E
----------------------------------------------------------------------------
--- ARBA - COT
--- MOS 04-2014
----------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSysExportData_getCOTAGIP]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@ds_id				INT,
	@OnlyCOT4State		BIT
)
As



BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE	@comp_id			INT
	DECLARE	@lang_id			INT
	DECLARE @bra_id				INT
	DECLARE @ds_id				INT

	SET		@comp_id			= 1
	SET		@lang_id			= 2
	SET		@bra_id				= 1
	SET		@ds_id				= 22
	*/
	-- ----------------------------------------------------------



	-- Modo de Obtener Comprobantes Disponibles
	-- 0: Normal
	-- 1: Todas Las Sucursales
	-- 2: Todas Las Sucursales con sdlme=Enviar
	DECLARE @intMode AS INT
	SET		@intMode = 0
	SELECT  @intMode =  IsNull(tb.bra_deliverySheetMode,0)
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id





	DECLARE @tblCOT TABLE(Record NVARCHAR(1000), intOrder INT IDENTITY(1,1))

	-- 1er registro, cuit empresa
	-- Cursort para leer los remitos incluidos en la planilla
	-- por cada uno generar reqgistros del tipo 2 y del tipo 3
	--grabar registro del tipo 4 con la cuenta total
	-- hacer un select * de la temporal
	-- grabarlo en /temp y llamar al web service



	--VARIABLES DE TRABAJO
	DECLARE
		@cuit		VARCHAR(20),
		@planta		VARCHAR(20),			--Nº de Planta
		@puerta		VARCHAR(20),			--Nº de Puerta
		@AFIPDoc_CD	DATETIME,		--Fecha de Creación del Documento
		@secNumber	INT,			--Nº Secuencial

		@fileName	NVARCHAR(500),	--Nombre del Archivo Completo

		@RecordType1	CHAR(2),
		@RecordType2	CHAR(2),
		@RecordType3	CHAR(2),
		@RecordType4	CHAR(2)

	--CONSTANTES DE REGISTROS
	SET @RecordType1 = '01'
	SET @RecordType2 = '02'
	SET @RecordType3 = '03'
	SET @RecordType4 = '04'

	DECLARE @dl_id	INT
	SET @dl_id = NULL
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- DATOS PARA LA GENERACIÓN DEL NOMBRE DEL ARCHIVO
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @arba_cot_cust_id_alternativeDestiny AS INT
	--CUIT
	SELECT
		@cuit		= ISNULL(td.arba_cot_ORIGEN_CUIT,''),
		@planta		= ISNULL(td.arba_cot_Planta,''),
		@puerta		= ISNULL(td.arba_cot_Puerta,''),
		@secNumber	= ISNULL(td.arba_cot_Counter,0),
		@dl_id		= td.dl_id,
		@arba_cot_cust_id_alternativeDestiny = td.arba_cot_cust_id_alternativeDestiny
	FROM tbDelivery							td		WITH(NOLOCK)
		INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
		ON	tdsh.comp_id	= td.comp_id	AND
			tdsh.dl_id		= td.dl_id
	WHERE	tdsh.ds_id		= @ds_id


	UPDATE tbDelivery
		SET
			arba_cot_Counter = @secNumber + 1
		WHERE dl_id = @dl_id


	SELECT @AFIPDoc_CD = dbo.fnSIAP_ConvertDate2StringAaAAMMDD(GETDATE(),'')

	SELECT @fileName =	'TB'							+ '_' +
						CONVERT(VARCHAR,@cuit)			+ '_' +
						CONVERT(VARCHAR,@planta)		+ '' +									--STL ANTES TENIA ESTO EN LUGAR DE LO QUE ESTA AHORA + '_' +
						CONVERT(VARCHAR,@puerta)		+ '_' +
						REPLACE(CONVERT(VARCHAR, GETDATE(), 111), '/','') + '_' +
						dbo.fnSIAP_ConvertString2FIXLength2(CONVERT(VARCHAR,@secNumber), 6,'0')

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- OBTENEMOS LA CANTIDAD DE REMITOS QUE TIENE EL DS_ID ASOCIADOS
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		DECLARE
			@lIntDocumentCounter	INT

		SELECT @lIntDocumentCounter = COUNT(*)
			FROM tbDeliverySheetDetail tdsd
			INNER JOIN tbCommercialTransactions tct
				ON	tct.comp_id			= tdsd.comp_id AND
					tct.ct_transaction	= tdsd.ds_ct_transaction
			INNER JOIN tbCustomer tc
				ON	tc.comp_id			= tct.comp_id AND
					tc.cust_id			= tct.cust_id
			WHERE	tdsd.comp_id	= @comp_id	AND
					tdsd.ds_id		= @ds_id	AND
				   (tct.state_id		= 54019		OR @OnlyCOT4State = 'False')
				   --(tc.state_id		= 54019		OR @OnlyCOT4State = 'False')
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------
	-- Registro Tipo 01
	-- ---------------------------------------------------------
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType1 + '|' +
		CONVERT(VARCHAR,@cuit)
	-- ---------------------------------------------------------


	--VARIABLES DEL CURSOR
	DECLARE
			@emissionDate								DATETIME,

			@ds_ct_transaction							INT,

			@arba_cot_Fecha_Hora_Salida_Transporte		DATETIME,

			@esConsumidorFinal							BIT,

			@arba_cot_SUJETO_GENERADOR_IsDestiny		CHAR(1),

			@arba_cot_ORIGEN_CUIT						VARCHAR(11),
			@arba_cot_ORIGEN_RAZON_SOCIAL				VARCHAR(50),
			@arba_cot_EMISOR_TENEDOR					BIT,

			@arba_cot_ORIGEN_DOMICILIO_CALLE			VARCHAR(40),
			@arba_cot_ORIGEN_DOMICILIO_NUMERO			VARCHAR(5),
			@arba_cot_ORIGEN_DOMICILIO_COMPLE			VARCHAR(200),
			@arba_cot_ORIGEN_DOMICILIO_PISO				VARCHAR(3),
			@arba_cot_ORIGEN_DOMICILIO_DTO				VARCHAR(4),
			@arba_cot_ORIGEN_DOMICILIO_BARRIO			VARCHAR(30),
			@arba_cot_ORIGEN_DOMILILIO_CODIGOP			VARCHAR(8),
			@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD		VARCHAR(50),

			@arba_cot_ORIGEN_DOMICILIO_PROVINCIA		VARCHAR(1),  --dario 16/10/2018

			@arba_cot_TIPO_RECORRIDO					CHAR(1),
			@arba_cot_RECORRIDO_LOCALIDAD				VARCHAR(50),
			@arba_cot_RECORRIDO_CALLE					VARCHAR(40),
			@arba_cot_RECORRIDO_RUTA					VARCHAR(40),

			@arba_cot_PATENTE_VEHICULO					VARCHAR(7),
			@arba_cot_PATENTE_ACOPLADO					VARCHAR(7),
			@arba_cot_Counter							INT,
			@TRANSPORTISTA_CUIT							VARCHAR(11),
			@IMPORTE									DECIMAL(19,2),
			@state_id									INT


	DECLARE DocumentsHeader_Cursor CURSOR FOR

		--ACA VA EL SELECT
		SELECT

			tct.ct_date,						--FECHA EMISIÓN

			tdsd.ds_ct_transaction,

			tdsh.arba_cot_Fecha_Hora_Salida_Transporte,

			CASE tc.fc_id
				WHEN	2 THEN		1			--CONSUMIDOR FINAL
				ELSE				0
			END,
			CASE td.arba_cot_SUJETO_GENERADOR_IsDestiny
				WHEN	1 THEN		'D'
				ELSE				'E'
			END,

			td.arba_cot_ORIGEN_CUIT,
			td.arba_cot_ORIGEN_RAZON_SOCIAL,
			td.arba_cot_EMISOR_TENEDOR,

			td.arba_cot_ORIGEN_DOMICILIO_CALLE,
			td.arba_cot_ORIGEN_DOMICILIO_NUMERO,
			td.arba_cot_ORIGEN_DOMICILIO_COMPLE,
			td.arba_cot_ORIGEN_DOMICILIO_PISO,
			td.arba_cot_ORIGEN_DOMICILIO_DTO,
			td.arba_cot_ORIGEN_DOMICILIO_BARRIO,
			td.arba_cot_ORIGEN_DOMILILIO_CODIGOP,
			td.arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,

			ISNULL(ts.state_arba_cot,' ') as arba_cot_ORIGEN_DOMICILIO_PROVINCIA,

			--td.arba_cot_EMISOR_TENEDOR,
			--td.arba_cot_ORIGEN_CUIT,
			--td.arba_cot_ORIGEN_RAZON_SOCIAL,

			tdsh.arba_cot_TIPO_RECORRIDO,
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_LOCALIDAD,50),



			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_CALLE,40),
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_RUTA,40),

			td.arba_cot_PATENTE_VEHICULO,
			td.arba_cot_PATENTE_ACOPLADO,
			td.arba_cot_Counter,
			ISNULL(td.dl_taxNumber,' '),
			--tct.ct_total,
			CASE	-- MOS 12-2022 x GN 17647
				WHEN tdf.df_COT_isOverNETO = 'True' THEN	tct.ct_total
				ELSE										tct.ct_subtotal
			END,
			tct.state_id

		FROM tbDelivery							td		WITH(NOLOCK)

			INNER JOIN tbsysState				ts      WITH(NOLOCK)   --dario 16/10/2018
			ON	ts.country_id	= td.country_id AND
				ts.state_id		= td.state_id

			INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
			ON	tdsh.comp_id	= td.comp_id	AND
				tdsh.dl_id		= td.dl_id
			INNER JOIN tbDeliverySheetDetail	tdsd	WITH(NOLOCK)
			ON	tdsd.comp_id	= tdsh.comp_id	AND
				--tdsd.bra_id		= tdsh.bra_id	AND
				tdsd.ds_id		= tdsh.ds_id

			INNER JOIN tbCommercialTransactions	tct		WITH(NOLOCK)
			ON	tct.comp_id			= td.comp_id				AND
				tct.ct_transaction	= tdsd.ds_ct_transaction	--AND
				--tct.sd_id			IN (2)

			-- MOS 12-2022 x GN 17647
			LEFT JOIN tbDocumentsFile		 AS tdf		WITH (NOLOCK)
				ON	tdf.comp_id		= tct.comp_id AND
					tdf.df_id		= tct.df_id

			INNER JOIN tbCustomer				tc		WITH(NOLOCK)
			ON	tc.comp_id		= tct.comp_id	AND
				tc.cust_id		= tct.cust_id

		WHERE	tdsh.comp_id	= @comp_id		AND
				tdsh.ds_id		= @ds_id		AND
			   (tct.state_id	= 54019 OR @OnlyCOT4State = 'False')
			   --(tc.state_id		= 54019 OR @OnlyCOT4State = 'False')


	OPEN DocumentsHeader_Cursor

	FETCH NEXT FROM DocumentsHeader_Cursor
	INTO
		@emissionDate,

		@ds_ct_transaction,

		@arba_cot_Fecha_Hora_Salida_Transporte,

		@esConsumidorFinal,

		@arba_cot_SUJETO_GENERADOR_IsDestiny,

		@arba_cot_ORIGEN_CUIT,
		@arba_cot_ORIGEN_RAZON_SOCIAL,
		@arba_cot_EMISOR_TENEDOR,

		@arba_cot_ORIGEN_DOMICILIO_CALLE,
		@arba_cot_ORIGEN_DOMICILIO_NUMERO,
		@arba_cot_ORIGEN_DOMICILIO_COMPLE,
		@arba_cot_ORIGEN_DOMICILIO_PISO,
		@arba_cot_ORIGEN_DOMICILIO_DTO,
		@arba_cot_ORIGEN_DOMICILIO_BARRIO,
		@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
		@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
		@arba_cot_ORIGEN_DOMICILIO_PROVINCIA, --Dario 16/10/2018

		@arba_cot_TIPO_RECORRIDO,
		@arba_cot_RECORRIDO_LOCALIDAD,
		@arba_cot_RECORRIDO_CALLE,
		@arba_cot_RECORRIDO_RUTA,

		@arba_cot_PATENTE_VEHICULO,
		@arba_cot_PATENTE_ACOPLADO,
		@arba_cot_Counter,
		@TRANSPORTISTA_CUIT,
		@IMPORTE,
		@state_id

		WHILE @@FETCH_STATUS = 0
			BEGIN



				-- ----------------------------------------------------------------------------------------------------------------
				-- PARA VER SI TIENE ARTICULOS EN EL CT_TRANSACTION O TENGO QUE IR A BUSCARLO A "ct_transaction_packinglist"
				-- ----------------------------------------------------------------------------------------------------------------
				DECLARE
					@lCT_TRANSACTION	INT

				IF (SELECT COUNT(*)
				    FROM tbCommercialTransactions						tct	WITH(NOLOCK)
						INNER JOIN tbItemTransactions					tit	WITH(NOLOCK)
						ON	tit.comp_id			= tct.comp_id			AND
							tit.ct_transaction	= tct.ct_transaction
				    WHERE	tct.comp_id			= @comp_id				AND
							tct.ct_transaction	= @ds_ct_transaction	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1
					) = 0

					BEGIN

						--SI ES UN REMITO Y NO TIENE ARTÍCULOS LE ASIGNA EL PACKINK_LIST
						SELECT
							@lCT_TRANSACTION		= tct.ct_transaction_PackingList
						  FROM tbCommercialTransactions						tct
						WHERE	tct.comp_id			= @comp_id				AND
								tct.ct_transaction	= @ds_ct_transaction
					END


				ELSE
					BEGIN
						--SINO, SETEA EL MISMO CT_TRANSACTION
						SET @lCT_TRANSACTION = @ds_ct_transaction
					END


--==
--SELECT '@lCT_TRANSACTION:', @lCT_TRANSACTION
--==

				-- ----------------------------------------------------------------------------------------------------------------

				--ARMAMOS EL CODIGO_UNICO

				DECLARE
					@CODIGO_UNICO	VARCHAR(16)
				DECLARE @strDeliveryAddress AS NVARCHAR(4000)



				SELECT @strDeliveryAddress =
												CASE
													WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
														 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
													WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
													WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
													WHEN ISNULL(cust.cust_address4Delivery,'') <> ''	THEN cust.cust_address4Delivery
													ELSE													 cust.cust_address
												END
					FROM tbCommercialTransactions CT

					LEFT join dbo.tbCommercialTransactionNotes		CTN
					on	CTN.comp_id				= CT.comp_id
					and	CTN.bra_id				= CT.bra_id
					and CTN.ct_transaction		= CT.ct_transaction


					LEFT join dbo.tbCustomer						cust
					on  cust.comp_id				= ct.comp_id AND
						cust.cust_id				= ct.cust_id


					LEFT JOIN tbCustomerFamily tcf
						ON	tcf.comp_id		= ct.comp_id AND
							tcf.cust_id		= ct.cust_id AND
							tcf.custf_id	= ct.custf_id

					LEFT JOIN tbCustomerBranch tcb
						ON		tcb.comp_id = ct.comp_id
							AND tcb.cust_id = ct.cust_id
							AND tcb.cb_id	= ct.cb_id

					WHERE	CT.comp_id			= @comp_id AND
							CT.ct_transaction	= @ds_ct_transaction



				SELECT
					@CODIGO_UNICO = CASE
										WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '091'
										WHEN tct.sd_id = 2						    THEN '094'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '001'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '006'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '011'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '051'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '060'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '061'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '093'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '058'

										ELSE										    '099'
									END

										/*'91 R'*/ + '' +
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 5,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]		NEW de 4 a 5
					--@CODIGO_UNICO = CASE
					--					WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '91 R'
					--					WHEN tct.sd_id = 2						    THEN '94 X'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '01 A'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '06 B'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '92 C'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '51 M'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '60 A'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '61 B'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '93 C'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '58 M'

					--					ELSE										    '97 E'
					--				END

					--					/*'91 R'*/ + '' +
					--dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 4,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_docNumber, 8,'0')									--[NUMERO_DOCNUMBER]

					FROM tbCommercialTransactions tct

					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction --@lCT_TRANSACTION

				-- ----------------------------------------------------------------------------------------------------------------


				--OBTENEMOS LOS DATOS DEL CLIENTE
				DECLARE @lcust_id	INT
				SELECT @lcust_id = tct.cust_id
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction


				-- Se usa para el caso de Entregar a un transporte en el que la mercaderia sale de nuestra empresa pero el
				-- destino NO es el cliente sino que es el transporte.
				IF @arba_cot_cust_id_alternativeDestiny IS NOT NULL
					BEGIN
						SET @lcust_id = @arba_cot_cust_id_alternativeDestiny
					END



				DECLARE
					@DESTINATARIO_TIPO_DOCUMENTO		VARCHAR(3),
					@DESTINATARIO_DOCUMENTO				VARCHAR(11),
					@DESTINATARIO_CUIT					VARCHAR(11),
					@DESTINATARIO_RAZON_SOCIAL			VARCHAR(50),
					@DESTINATARIO_TENEDOR				BIT,
					@DESTINO_DOMICILIO_CALLE			VARCHAR(40),
					@DESTINO_DOMICILIO_NUMERO			VARCHAR(5),
					@DESTINO_DOMICILIO_COMPLE			VARCHAR(5),
					@DESTINO_DOMICILIO_PISO				VARCHAR(3),
					@DESTINO_DOMICILIO_DTO				VARCHAR(4),
					@DESTINO_DOMICILIO_BARRIO			VARCHAR(30),
					@DESTINO_DOMICILIO_CODIGOP			VARCHAR(8),
					@DESTINO_DOMICILIO_LOCALIDAD		VARCHAR(50),
					@DESTINO_DOMICILIO_PROVINCIA		VARCHAR(1),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	VARCHAR(50)

				-- *************************************************************************************
				-- HDP: Como se nota que no sabes programar y copiaste esto de internet.
				--      Usar GetOnlyNumbers para esto...
				-- SEPARAMOS EL NUMERO DE LA DIRECCION
				-- NOTA: SEPARA TODOS LOS NUMEROS, POR ENDE SI LA DIRECCION ES '25 de Mayo 3323'
				--       EL RESULTADO SERA '253323' <-- TODOS LOS NUMEROS CONCATENADOS
				--       DE MOMENTO NO HAY UNA SOLUCION MEJOR
				-- *************************************************************************************
				DECLARE @thestring VARCHAR(50)
				SET @thestring = @strDeliveryAddress --(SELECT tc.cust_address FROM tbCustomer tc WHERE tc.comp_id = @comp_id AND tc.cust_id = @lcust_id)
				DECLARE @final VARCHAR(50)
				SET @final = ''

				SELECT @final = @final + x.thenum
				FROM
				(
					SELECT SUBSTRING(@thestring, number, 1) AS thenum, number
					FROM master..spt_values
					WHERE substring(@thestring, number, 1) LIKE '[0-9]' AND TYPE='P'
				) x
				ORDER BY x.number
				DECLARE
					@DESTINO_DOMICILIO_NUMEROFINAL VARCHAR(5)
				SET @DESTINO_DOMICILIO_NUMEROFINAL = @final
				-- *************************************************************************************



				SELECT
					@DESTINATARIO_TIPO_DOCUMENTO		= ISNULL(ttnt.tnt_ARBACOT,' '),
					@DESTINATARIO_DOCUMENTO				= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_CUIT					= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_RAZON_SOCIAL			= ISNULL(tc.cust_name,' '),
					@DESTINATARIO_TENEDOR				= CASE @esConsumidorFinal
															  WHEN 1 THEN 0
															  ELSE        1
					                     				  END,	--SI ES CONSUMIDOR FINAL es CERO, SINO es 1
					@DESTINO_DOMICILIO_CALLE			= ISNULL(@strDeliveryAddress /*tc.cust_address*/,' '), --COMO SEPARO EL NUMERO DE LA CALLE PARA PONERLO ABAJO????
					@DESTINO_DOMICILIO_NUMERO			= ISNULL(@DESTINO_DOMICILIO_NUMEROFINAL,' '),
					@DESTINO_DOMICILIO_COMPLE			= 'S/N', --ISNULL(tc.cust_address,' '),
					@DESTINO_DOMICILIO_PISO				= ' ',
					@DESTINO_DOMICILIO_DTO				= ' ',
					@DESTINO_DOMICILIO_BARRIO			= ' ',
					@DESTINO_DOMICILIO_CODIGOP			= ISNULL(tc.cust_zip,' '),
					@DESTINO_DOMICILIO_LOCALIDAD		= ISNULL(tc.cust_city,' '),
					@DESTINO_DOMICILIO_PROVINCIA		= ISNULL(ts.state_arba_cot,' '),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	= ' '

					FROM tbCustomer							tc
						INNER JOIN tbsysState				ts			WITH (NOLOCK)
							ON ts.state_id = @state_id
						--ON	ts.country_id	= tc.country_id AND
						--	ts.state_id		= tc.state_id

						INNER JOIN tbsysTaxNumberTypes		ttnt
						ON	ttnt.tnt_id		= tc.tnt_id

				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @lcust_id



				SET @arba_cot_Fecha_Hora_Salida_Transporte = GETDATE()


				IF @DESTINATARIO_TIPO_DOCUMENTO = ''
					BEGIN
						SET @DESTINATARIO_DOCUMENTO	 = ''
					END

				IF @esConsumidorFinal = 1
					BEGIN
						set @DESTINATARIO_CUIT = ''
					END
				IF @esConsumidorFinal = 0
					BEGIN
						set @DESTINATARIO_TIPO_DOCUMENTO = ''
						set @DESTINATARIO_DOCUMENTO		 = ''
					END
				set @DESTINATARIO_CUIT = REPLACE(@DESTINATARIO_CUIT,'-','')

				if @DESTINO_DOMICILIO_COMPLE = 'S/N'
					BEGIN
						set @DESTINO_DOMICILIO_NUMERO = ''
					END


				--INSERTAMOS EL SEGUNDO REGISTRO CON LOS DATOS DEL TRANSPORTE Y DE A QUIEN SE LO ENVIAMOS
				--SELECT @lCT_TRANSACTION
				INSERT INTO @tblCOT
				(
					Record
				)
				SELECT
					@RecordType2																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @emissionDate, 111), '/',''),' ')							+ '|' +		--FECHA
					@CODIGO_UNICO																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 111), '/',''),' ')	+ '|' +		--FECHA
					substring(ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 108), ':',''),'    '),1,4)	+ '|' +		--HORA
					@arba_cot_SUJETO_GENERADOR_IsDestiny														+ '|' +		--SUJETO_GENERADOR E(emisor) D(destinatario)
					ISNULL(CONVERT(VARCHAR,@esConsumidorFinal),' ')												+ '|' +
					ISNULL(@DESTINATARIO_TIPO_DOCUMENTO,' ')													+ '|' +
					ISNULL(@DESTINATARIO_DOCUMENTO,' ')															+ '|' +
					ISNULL(@DESTINATARIO_CUIT,' ')																+ '|' +
					ISNULL(@DESTINATARIO_RAZON_SOCIAL,' ')														+ '|' +
					ISNULL(CONVERT(VARCHAR,@DESTINATARIO_TENEDOR),' ')											+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CALLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_NUMERO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_COMPLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PISO,' ')															+ '|' +
					ISNULL(@DESTINO_DOMICILIO_DTO	,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_BARRIO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CODIGOP,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PROVINCIA,' ')													+ '|' +
					ISNULL(@PROPIO_DESTINO_DOMICILIO_CODIGO,' ')												+ '|' +
					'NO'																						+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					ISNULL(@arba_cot_ORIGEN_CUIT,' ')															+ '|' +
					ISNULL(@arba_cot_ORIGEN_RAZON_SOCIAL,' ')													+ '|' +
					ISNULL(CONVERT(VARCHAR,@arba_cot_EMISOR_TENEDOR),' ')										+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_CALLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_NUMERO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_COMPLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PISO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_DTO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_BARRIO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMILILIO_CODIGOP,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,' ')											+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,' ')													+ '|' + --Dario 16/10/2018
					@TRANSPORTISTA_CUIT																			+ '|' +		--TAX_NUMBER de DELIVERY
					ISNULL(@arba_cot_TIPO_RECORRIDO	,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@arba_cot_RECORRIDO_CALLE,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_RUTA,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_VEHICULO,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_ACOPLADO,' ')														+ '|' +
					'0'																							+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					dbo.fnSIAP_ConvertDecimal2String(CONVERT(VARCHAR,@IMPORTE), 10)												--IMPORTE


				-- ---------------------------------------------------------------------------------------------------------------
				-- CURSOR DE PROCESAMIENTO DE ARTÍCULOS DE CADA REMITO
				-- ---------------------------------------------------------------------------------------------------------------

				DECLARE
					@arbaCOT_Nomenclador	VARCHAR(15),
					@item_measureARBA		VARCHAR(15),
					@qty					INT,
					@item_code				VARCHAR(25),
					@item_desc				VARCHAR(40),
					@item_measure			VARCHAR(20)




				DECLARE DocumentItemsDetail_Cursor CURSOR FOR

					--ACA VA EL SELECT
					SELECT
						ISNULL(ti.arbaCOT_Nomenclador,' '),
						ISNULL(tamu.cot_um_id,' '),
						ISNULL(tit.it_qty,' '),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_code,' '),25),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_desc,' '),40),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(tmu.mu_shortDesc,' '),20)


					FROM tbItemTransactions							tit		WITH(NOLOCK)
						INNER JOIN tbItem							ti		WITH(NOLOCK)
						ON  ti.comp_id			= tit.comp_id		AND
							ti.item_id			= tit.item_id
						LEFT JOIN tbMetricUnits						tmu		WITH(NOLOCK)
						ON	tmu.comp_id			= ti.comp_id		AND
							tmu.mu_id			= ti.mu_id
						INNER JOIN tbsysARBACOT_MetricUnit			tamu	WITH(NOLOCK)
						ON	tamu.cot_um_id		= tmu.cot_um_id


					WHERE	tit.comp_id			= @comp_id			AND
							--tit.bra_id			= @bra_id			AND
							tit.ct_transaction	= @lCT_TRANSACTION	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1									AND
							IsNull(ti.arbaCOT_Nomenclador,'') <> ''


				OPEN DocumentItemsDetail_Cursor
				FETCH NEXT FROM DocumentItemsDetail_Cursor
				INTO
					@arbaCOT_Nomenclador,
					@item_measureARBA,
					@qty,
					@item_code,
					@item_desc,
					@item_measure

				WHILE @@FETCH_STATUS = 0
					BEGIN


						INSERT INTO @tblCOT
						(
							Record
						)
						SELECT
							@RecordType3															+ '|' +
							@arbaCOT_Nomenclador													+ '|' +
							@item_measureARBA														+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	+ '|' +
							CONVERT(VARCHAR,@item_code)												+ '|' +
							CONVERT(VARCHAR,@item_desc)												+ '|' +
							CONVERT(VARCHAR,@item_measure)											+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	--CONVERTIMOS A VARCHAR PARA PODER CONCATENARLO



						FETCH NEXT FROM DocumentItemsDetail_Cursor
						INTO
							@arbaCOT_Nomenclador,
							@item_measureARBA,
							@qty,
							@item_code,
							@item_desc,
							@item_measure

					END



				CLOSE DocumentItemsDetail_Cursor
				DEALLOCATE DocumentItemsDetail_Cursor

				-- ---------------------------------------------------------------------------------------------------------------


				FETCH NEXT FROM DocumentsHeader_Cursor
				INTO
					@emissionDate,

					@ds_ct_transaction,

					@arba_cot_Fecha_Hora_Salida_Transporte,

					@esConsumidorFinal,

					@arba_cot_SUJETO_GENERADOR_IsDestiny,

					@arba_cot_ORIGEN_CUIT,
					@arba_cot_ORIGEN_RAZON_SOCIAL,
					@arba_cot_EMISOR_TENEDOR,

					@arba_cot_ORIGEN_DOMICILIO_CALLE,
					@arba_cot_ORIGEN_DOMICILIO_NUMERO,
					@arba_cot_ORIGEN_DOMICILIO_COMPLE,
					@arba_cot_ORIGEN_DOMICILIO_PISO,
					@arba_cot_ORIGEN_DOMICILIO_DTO,
					@arba_cot_ORIGEN_DOMICILIO_BARRIO,
					@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
					@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
					@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,  --Dario 16/10/2018

					@arba_cot_TIPO_RECORRIDO,
					@arba_cot_RECORRIDO_LOCALIDAD,
					@arba_cot_RECORRIDO_CALLE,
					@arba_cot_RECORRIDO_RUTA,

					@arba_cot_PATENTE_VEHICULO,
					@arba_cot_PATENTE_ACOPLADO,
					@arba_cot_Counter,
					@TRANSPORTISTA_CUIT,
					@IMPORTE,
					@state_id

			END

		CLOSE DocumentsHeader_Cursor
	DEALLOCATE DocumentsHeader_Cursor

	--INSERTAMOS EL CUARTO REGISTRO
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType4							+ '|' +
		CONVERT(VARCHAR,@lIntDocumentCounter)


	SELECT @fileName
	SELECT tmp.Record  FROM @tblCOT tmp ORDER BY tmp.intOrder

END
--1
GO





----------------------------------------------------------------------------
-- Para las FECHAS se convierte con dbo.fnSIAP_ConvertDate2StringAaAAMMDD(Fecha,'')
-- Para los NUMEROS se convierte con fnSIAP_ConvertDecimal2String(NUMERO,LONGITUD)
-- Para los CaraCTERES se convierte CON fnSIAP_ConvertString2FIXLength( String,Longitud )
-- Si hay que poner 16 ceros, poner el string sin el convert a char....

-- http://www.arba.gov.ar/Apartados/Agentes/remitoelectr%C3%B3nico.asp?lugar=E
----------------------------------------------------------------------------
--- ARBA - COT
--- MOS 04-2014
----------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSysExportData_getCOTMendoza]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@ds_id				INT,
	@OnlyCOT4State		BIT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE	@comp_id			INT
	DECLARE	@lang_id			INT
	DECLARE @bra_id				INT
	DECLARE @ds_id				INT

	SET		@comp_id			= 1
	SET		@lang_id			= 2
	SET		@bra_id				= 1
	SET		@ds_id				= 22
	*/
	-- ----------------------------------------------------------



	-- Modo de Obtener Comprobantes Disponibles
	-- 0: Normal
	-- 1: Todas Las Sucursales
	-- 2: Todas Las Sucursales con sdlme=Enviar
	DECLARE @intMode AS INT
	SET		@intMode = 0
	SELECT  @intMode =  IsNull(tb.bra_deliverySheetMode,0)
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id





	DECLARE @tblCOT TABLE(Record NVARCHAR(1000), intOrder INT IDENTITY(1,1))

	-- 1er registro, cuit empresa
	-- Cursort para leer los remitos incluidos en la planilla
	-- por cada uno generar reqgistros del tipo 2 y del tipo 3
	--grabar registro del tipo 4 con la cuenta total
	-- hacer un select * de la temporal
	-- grabarlo en /temp y llamar al web service



	--VARIABLES DE TRABAJO
	DECLARE
		@cuit		VARCHAR(20),
		@planta		VARCHAR(20),			--Nº de Planta
		@puerta		VARCHAR(20),			--Nº de Puerta
		@AFIPDoc_CD	DATETIME,		--Fecha de Creación del Documento
		@secNumber	INT,			--Nº Secuencial

		@fileName	NVARCHAR(500),	--Nombre del Archivo Completo

		@RecordType1	CHAR(2),
		@RecordType2	CHAR(2),
		@RecordType3	CHAR(2),
		@RecordType4	CHAR(2)

	--CONSTANTES DE REGISTROS
	SET @RecordType1 = '01'
	SET @RecordType2 = '02'
	SET @RecordType3 = '03'
	SET @RecordType4 = '04'

	DECLARE @dl_id	INT
	SET @dl_id = NULL
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- DATOS PARA LA GENERACIÓN DEL NOMBRE DEL ARCHIVO
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @arba_cot_cust_id_alternativeDestiny AS INT
	--CUIT
	SELECT
		@cuit		= ISNULL(td.arba_cot_ORIGEN_CUIT,''),
		@planta		= ISNULL(td.arba_cot_Planta,''),
		@puerta		= ISNULL(td.arba_cot_Puerta,''),
		@secNumber	= ISNULL(td.arba_cot_Counter,0),
		@dl_id		= td.dl_id,
		@arba_cot_cust_id_alternativeDestiny = td.arba_cot_cust_id_alternativeDestiny
	FROM tbDelivery							td		WITH(NOLOCK)
		INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
		ON	tdsh.comp_id	= td.comp_id	AND
			tdsh.dl_id		= td.dl_id
	WHERE	tdsh.ds_id		= @ds_id


	UPDATE tbDelivery
		SET
			arba_cot_Counter = @secNumber + 1
		WHERE dl_id = @dl_id


	SELECT @AFIPDoc_CD = dbo.fnSIAP_ConvertDate2StringAaAAMMDD(GETDATE(),'')

	SELECT @fileName =	'TB'							+ '_' +
						CONVERT(VARCHAR,@cuit)			+ '_' +
						CONVERT(VARCHAR,@planta)		+ '' +									--STL ANTES TENIA ESTO EN LUGAR DE LO QUE ESTA AHORA + '_' +
						CONVERT(VARCHAR,@puerta)		+ '_' +
						REPLACE(CONVERT(VARCHAR, GETDATE(), 111), '/','') + '_' +
						dbo.fnSIAP_ConvertString2FIXLength2(CONVERT(VARCHAR,@secNumber), 6,'0')

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- OBTENEMOS LA CANTIDAD DE REMITOS QUE TIENE EL DS_ID ASOCIADOS
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		DECLARE
			@lIntDocumentCounter	INT

		SELECT @lIntDocumentCounter = COUNT(*)
			FROM tbDeliverySheetDetail tdsd
			INNER JOIN tbCommercialTransactions tct
				ON	tct.comp_id			= tdsd.comp_id AND
					tct.ct_transaction	= tdsd.ds_ct_transaction
			INNER JOIN tbCustomer tc
				ON	tc.comp_id			= tct.comp_id AND
					tc.cust_id			= tct.cust_id
			WHERE	tdsd.comp_id	= @comp_id	AND
					tdsd.ds_id		= @ds_id	AND
				   (tct.state_id		= 54002		OR @OnlyCOT4State = 'False')
				   --(tc.state_id		= 54002		OR @OnlyCOT4State = 'False')
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------
	-- Registro Tipo 01
	-- ---------------------------------------------------------
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType1 + '|' +
		CONVERT(VARCHAR,@cuit)
	-- ---------------------------------------------------------


	--VARIABLES DEL CURSOR
	DECLARE
			@emissionDate								DATETIME,

			@ds_ct_transaction							INT,

			@arba_cot_Fecha_Hora_Salida_Transporte		DATETIME,

			@esConsumidorFinal							BIT,

			@arba_cot_SUJETO_GENERADOR_IsDestiny		CHAR(1),

			@arba_cot_ORIGEN_CUIT						VARCHAR(11),
			@arba_cot_ORIGEN_RAZON_SOCIAL				VARCHAR(50),
			@arba_cot_EMISOR_TENEDOR					BIT,

			@arba_cot_ORIGEN_DOMICILIO_CALLE			VARCHAR(40),
			@arba_cot_ORIGEN_DOMICILIO_NUMERO			VARCHAR(5),
			@arba_cot_ORIGEN_DOMICILIO_COMPLE			VARCHAR(200),
			@arba_cot_ORIGEN_DOMICILIO_PISO				VARCHAR(3),
			@arba_cot_ORIGEN_DOMICILIO_DTO				VARCHAR(4),
			@arba_cot_ORIGEN_DOMICILIO_BARRIO			VARCHAR(30),
			@arba_cot_ORIGEN_DOMILILIO_CODIGOP			VARCHAR(8),
			@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD		VARCHAR(50),

			@arba_cot_ORIGEN_DOMICILIO_PROVINCIA		VARCHAR(1),  --dario 16/10/2018

			@arba_cot_TIPO_RECORRIDO					CHAR(1),
			@arba_cot_RECORRIDO_LOCALIDAD				VARCHAR(50),
			@arba_cot_RECORRIDO_CALLE					VARCHAR(40),
			@arba_cot_RECORRIDO_RUTA					VARCHAR(40),

			@arba_cot_PATENTE_VEHICULO					VARCHAR(7),
			@arba_cot_PATENTE_ACOPLADO					VARCHAR(7),
			@arba_cot_Counter							INT,
			@TRANSPORTISTA_CUIT							VARCHAR(11),
			@IMPORTE									DECIMAL(19,2),
			@state_id									INT


	DECLARE DocumentsHeader_Cursor CURSOR FOR

		--ACA VA EL SELECT
		SELECT

			tct.ct_date,						--FECHA EMISIÓN

			tdsd.ds_ct_transaction,

			tdsh.arba_cot_Fecha_Hora_Salida_Transporte,

			CASE tc.fc_id
				WHEN	2 THEN		1			--CONSUMIDOR FINAL
				ELSE				0
			END,
			CASE td.arba_cot_SUJETO_GENERADOR_IsDestiny
				WHEN	1 THEN		'D'
				ELSE				'E'
			END,

			td.arba_cot_ORIGEN_CUIT,
			td.arba_cot_ORIGEN_RAZON_SOCIAL,
			td.arba_cot_EMISOR_TENEDOR,

			td.arba_cot_ORIGEN_DOMICILIO_CALLE,
			td.arba_cot_ORIGEN_DOMICILIO_NUMERO,
			td.arba_cot_ORIGEN_DOMICILIO_COMPLE,
			td.arba_cot_ORIGEN_DOMICILIO_PISO,
			td.arba_cot_ORIGEN_DOMICILIO_DTO,
			td.arba_cot_ORIGEN_DOMICILIO_BARRIO,
			td.arba_cot_ORIGEN_DOMILILIO_CODIGOP,
			td.arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,

			ISNULL(ts.state_arba_cot,' ') as arba_cot_ORIGEN_DOMICILIO_PROVINCIA,

			--td.arba_cot_EMISOR_TENEDOR,
			--td.arba_cot_ORIGEN_CUIT,
			--td.arba_cot_ORIGEN_RAZON_SOCIAL,

			tdsh.arba_cot_TIPO_RECORRIDO,
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_LOCALIDAD,50),



			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_CALLE,40),
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_RUTA,40),

			td.arba_cot_PATENTE_VEHICULO,
			td.arba_cot_PATENTE_ACOPLADO,
			td.arba_cot_Counter,
			ISNULL(td.dl_taxNumber,' '),
			--tct.ct_total,
			CASE	-- MOS 12-2022 x GN 17647
				WHEN tdf.df_COT_isOverNETO = 'True' THEN	tct.ct_total
				ELSE										tct.ct_subtotal
			END,
			tct.state_id

		FROM tbDelivery							td		WITH(NOLOCK)

			INNER JOIN tbsysState				ts      WITH(NOLOCK)   --dario 16/10/2018
			ON	ts.country_id	= td.country_id AND
				ts.state_id		= td.state_id

			INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
			ON	tdsh.comp_id	= td.comp_id	AND
				tdsh.dl_id		= td.dl_id
			INNER JOIN tbDeliverySheetDetail	tdsd	WITH(NOLOCK)
			ON	tdsd.comp_id	= tdsh.comp_id	AND
				--tdsd.bra_id		= tdsh.bra_id	AND
				tdsd.ds_id		= tdsh.ds_id

			INNER JOIN tbCommercialTransactions	tct		WITH(NOLOCK)
			ON	tct.comp_id			= td.comp_id				AND
				tct.ct_transaction	= tdsd.ds_ct_transaction	--AND
				--tct.sd_id			IN (2)

			-- MOS 12-2022 x GN 17647
			LEFT JOIN tbDocumentsFile		 AS tdf		WITH (NOLOCK)
				ON	tdf.comp_id		= tct.comp_id AND
					tdf.df_id		= tct.df_id



			INNER JOIN tbCustomer				tc		WITH(NOLOCK)
			ON	tc.comp_id		= tct.comp_id	AND
				tc.cust_id		= tct.cust_id

		WHERE	tdsh.comp_id	= @comp_id		AND
				tdsh.ds_id		= @ds_id		AND
			   (tct.state_id	= 54002 OR @OnlyCOT4State = 'False')
			   --(tc.state_id		= 54002 OR @OnlyCOT4State = 'False')


	OPEN DocumentsHeader_Cursor

	FETCH NEXT FROM DocumentsHeader_Cursor
	INTO
		@emissionDate,

		@ds_ct_transaction,

		@arba_cot_Fecha_Hora_Salida_Transporte,

		@esConsumidorFinal,

		@arba_cot_SUJETO_GENERADOR_IsDestiny,

		@arba_cot_ORIGEN_CUIT,
		@arba_cot_ORIGEN_RAZON_SOCIAL,
		@arba_cot_EMISOR_TENEDOR,

		@arba_cot_ORIGEN_DOMICILIO_CALLE,
		@arba_cot_ORIGEN_DOMICILIO_NUMERO,
		@arba_cot_ORIGEN_DOMICILIO_COMPLE,
		@arba_cot_ORIGEN_DOMICILIO_PISO,
		@arba_cot_ORIGEN_DOMICILIO_DTO,
		@arba_cot_ORIGEN_DOMICILIO_BARRIO,
		@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
		@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
		@arba_cot_ORIGEN_DOMICILIO_PROVINCIA, --Dario 16/10/2018

		@arba_cot_TIPO_RECORRIDO,
		@arba_cot_RECORRIDO_LOCALIDAD,
		@arba_cot_RECORRIDO_CALLE,
		@arba_cot_RECORRIDO_RUTA,

		@arba_cot_PATENTE_VEHICULO,
		@arba_cot_PATENTE_ACOPLADO,
		@arba_cot_Counter,
		@TRANSPORTISTA_CUIT,
		@IMPORTE,
		@state_id

		WHILE @@FETCH_STATUS = 0
			BEGIN



				-- ----------------------------------------------------------------------------------------------------------------
				-- PARA VER SI TIENE ARTICULOS EN EL CT_TRANSACTION O TENGO QUE IR A BUSCARLO A "ct_transaction_packinglist"
				-- ----------------------------------------------------------------------------------------------------------------
				DECLARE
					@lCT_TRANSACTION	INT

				IF (SELECT COUNT(*)
				    FROM tbCommercialTransactions						tct	WITH(NOLOCK)
						INNER JOIN tbItemTransactions					tit	WITH(NOLOCK)
						ON	tit.comp_id			= tct.comp_id			AND
							tit.ct_transaction	= tct.ct_transaction
				    WHERE	tct.comp_id			= @comp_id				AND
							tct.ct_transaction	= @ds_ct_transaction	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1
					) = 0

					BEGIN

						--SI ES UN REMITO Y NO TIENE ARTÍCULOS LE ASIGNA EL PACKINK_LIST
						SELECT
							@lCT_TRANSACTION		= tct.ct_transaction_PackingList
						  FROM tbCommercialTransactions						tct
						WHERE	tct.comp_id			= @comp_id				AND
								tct.ct_transaction	= @ds_ct_transaction
					END


				ELSE
					BEGIN
						--SINO, SETEA EL MISMO CT_TRANSACTION
						SET @lCT_TRANSACTION = @ds_ct_transaction
					END


--==
--SELECT '@lCT_TRANSACTION:', @lCT_TRANSACTION
--==

				-- ----------------------------------------------------------------------------------------------------------------

				--ARMAMOS EL CODIGO_UNICO

				DECLARE
					@CODIGO_UNICO	VARCHAR(16)
				DECLARE @strDeliveryAddress AS NVARCHAR(4000)



				SELECT @strDeliveryAddress =
												CASE
													WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
														 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
													WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
													WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
													WHEN ISNULL(cust.cust_address4Delivery,'') <> ''	THEN cust.cust_address4Delivery
													ELSE													 cust.cust_address
												END
					FROM tbCommercialTransactions CT

					LEFT join dbo.tbCommercialTransactionNotes		CTN
					on	CTN.comp_id				= CT.comp_id
					and	CTN.bra_id				= CT.bra_id
					and CTN.ct_transaction		= CT.ct_transaction


					LEFT join dbo.tbCustomer						cust
					on  cust.comp_id				= ct.comp_id AND
						cust.cust_id				= ct.cust_id


					LEFT JOIN tbCustomerFamily tcf
						ON	tcf.comp_id		= ct.comp_id AND
							tcf.cust_id		= ct.cust_id AND
							tcf.custf_id	= ct.custf_id

					LEFT JOIN tbCustomerBranch tcb
						ON		tcb.comp_id = ct.comp_id
							AND tcb.cust_id = ct.cust_id
							AND tcb.cb_id	= ct.cb_id

					WHERE	CT.comp_id			= @comp_id AND
							CT.ct_transaction	= @ds_ct_transaction



				SELECT
					@CODIGO_UNICO = CASE
										WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '091'
										WHEN tct.sd_id = 2						    THEN '094'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '001'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '006'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '011'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '051'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '060'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '061'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '093'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '058'

										ELSE										    '099'
									END

										/*'91 R'*/ + '' +
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 5,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]		NEW de 4 a 5
					--@CODIGO_UNICO = CASE
					--					WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '91 R'
					--					WHEN tct.sd_id = 2						    THEN '94 X'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '01 A'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '06 B'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '92 C'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '51 M'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '60 A'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '61 B'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '93 C'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '58 M'

					--					ELSE										    '97 E'
					--				END

					--					/*'91 R'*/ + '' +
					--dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 4,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_docNumber, 8,'0')									--[NUMERO_DOCNUMBER]

					FROM tbCommercialTransactions tct

					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction --@lCT_TRANSACTION

				-- ----------------------------------------------------------------------------------------------------------------


				--OBTENEMOS LOS DATOS DEL CLIENTE
				DECLARE @lcust_id	INT
				SELECT @lcust_id = tct.cust_id
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction


				-- Se usa para el caso de Entregar a un transporte en el que la mercaderia sale de nuestra empresa pero el
				-- destino NO es el cliente sino que es el transporte.
				IF @arba_cot_cust_id_alternativeDestiny IS NOT NULL
					BEGIN
						SET @lcust_id = @arba_cot_cust_id_alternativeDestiny
					END



				DECLARE
					@DESTINATARIO_TIPO_DOCUMENTO		VARCHAR(3),
					@DESTINATARIO_DOCUMENTO				VARCHAR(11),
					@DESTINATARIO_CUIT					VARCHAR(11),
					@DESTINATARIO_RAZON_SOCIAL			VARCHAR(50),
					@DESTINATARIO_TENEDOR				BIT,
					@DESTINO_DOMICILIO_CALLE			VARCHAR(40),
					@DESTINO_DOMICILIO_NUMERO			VARCHAR(5),
					@DESTINO_DOMICILIO_COMPLE			VARCHAR(5),
					@DESTINO_DOMICILIO_PISO				VARCHAR(3),
					@DESTINO_DOMICILIO_DTO				VARCHAR(4),
					@DESTINO_DOMICILIO_BARRIO			VARCHAR(30),
					@DESTINO_DOMICILIO_CODIGOP			VARCHAR(8),
					@DESTINO_DOMICILIO_LOCALIDAD		VARCHAR(50),
					@DESTINO_DOMICILIO_PROVINCIA		VARCHAR(1),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	VARCHAR(50)

				-- *************************************************************************************
				-- SEPARAMOS EL NUMERO DE LA DIRECCION
				-- NOTA: SEPARA TODOS LOS NUMEROS, POR ENDE SI LA DIRECCION ES '25 de Mayo 3323'
				--       EL RESULTADO SERA '253323' <-- TODOS LOS NUMEROS CONCATENADOS
				--       DE MOMENTO NO HAY UNA SOLUCION MEJOR
				-- *************************************************************************************
				DECLARE @thestring VARCHAR(50)
				SET @thestring = @strDeliveryAddress --(SELECT tc.cust_address FROM tbCustomer tc WHERE tc.comp_id = @comp_id AND tc.cust_id = @lcust_id)
				DECLARE @final VARCHAR(50)
				SET @final = ''

				SELECT @final = @final + x.thenum
				FROM
				(
					SELECT SUBSTRING(@thestring, number, 1) AS thenum, number
					FROM master..spt_values
					WHERE substring(@thestring, number, 1) LIKE '[0-9]' AND TYPE='P'
				) x
				ORDER BY x.number
				DECLARE
					@DESTINO_DOMICILIO_NUMEROFINAL VARCHAR(5)
				SET @DESTINO_DOMICILIO_NUMEROFINAL = @final
				-- *************************************************************************************



				SELECT
					@DESTINATARIO_TIPO_DOCUMENTO		= ISNULL(ttnt.tnt_ARBACOT,' '),
					@DESTINATARIO_DOCUMENTO				= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_CUIT					= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_RAZON_SOCIAL			= ISNULL(tc.cust_name,' '),
					@DESTINATARIO_TENEDOR				= CASE @esConsumidorFinal
															  WHEN 1 THEN 0
															  ELSE        1
					                     				  END,	--SI ES CONSUMIDOR FINAL es CERO, SINO es 1
					@DESTINO_DOMICILIO_CALLE			= ISNULL(@strDeliveryAddress /*tc.cust_address*/,' '), --COMO SEPARO EL NUMERO DE LA CALLE PARA PONERLO ABAJO????
					@DESTINO_DOMICILIO_NUMERO			= ISNULL(@DESTINO_DOMICILIO_NUMEROFINAL,' '),
					@DESTINO_DOMICILIO_COMPLE			= 'S/N', --ISNULL(tc.cust_address,' '),
					@DESTINO_DOMICILIO_PISO				= ' ',
					@DESTINO_DOMICILIO_DTO				= ' ',
					@DESTINO_DOMICILIO_BARRIO			= ' ',
					@DESTINO_DOMICILIO_CODIGOP			= ISNULL(tc.cust_zip,' '),
					@DESTINO_DOMICILIO_LOCALIDAD		= ISNULL(tc.cust_city,' '),
					@DESTINO_DOMICILIO_PROVINCIA		= ISNULL(ts.state_arba_cot,' '),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	= ' '

					FROM tbCustomer							tc
						INNER JOIN tbsysState				ts			WITH (NOLOCK)
							ON ts.state_id = @state_id
						--ON	ts.country_id	= tc.country_id AND
						--	ts.state_id		= tc.state_id

						INNER JOIN tbsysTaxNumberTypes		ttnt
						ON	ttnt.tnt_id		= tc.tnt_id

				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @lcust_id



				SET @arba_cot_Fecha_Hora_Salida_Transporte = GETDATE()


				IF @DESTINATARIO_TIPO_DOCUMENTO = ''
					BEGIN
						SET @DESTINATARIO_DOCUMENTO	 = ''
					END

				IF @esConsumidorFinal = 1
					BEGIN
						set @DESTINATARIO_CUIT = ''
					END
				IF @esConsumidorFinal = 0
					BEGIN
						set @DESTINATARIO_TIPO_DOCUMENTO = ''
						set @DESTINATARIO_DOCUMENTO		 = ''
					END
				set @DESTINATARIO_CUIT = REPLACE(@DESTINATARIO_CUIT,'-','')

				if @DESTINO_DOMICILIO_COMPLE = 'S/N'
					BEGIN
						set @DESTINO_DOMICILIO_NUMERO = ''
					END


				--INSERTAMOS EL SEGUNDO REGISTRO CON LOS DATOS DEL TRANSPORTE Y DE A QUIEN SE LO ENVIAMOS
				--SELECT @lCT_TRANSACTION
				INSERT INTO @tblCOT
				(
					Record
				)
				SELECT
					@RecordType2																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @emissionDate, 111), '/',''),' ')							+ '|' +		--FECHA
					@CODIGO_UNICO																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 111), '/',''),' ')	+ '|' +		--FECHA
					substring(ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 108), ':',''),'    '),1,4)	+ '|' +		--HORA
					@arba_cot_SUJETO_GENERADOR_IsDestiny														+ '|' +		--SUJETO_GENERADOR E(emisor) D(destinatario)
					ISNULL(CONVERT(VARCHAR,@esConsumidorFinal),' ')												+ '|' +
					ISNULL(@DESTINATARIO_TIPO_DOCUMENTO,' ')													+ '|' +
					ISNULL(@DESTINATARIO_DOCUMENTO,' ')															+ '|' +
					ISNULL(@DESTINATARIO_CUIT,' ')																+ '|' +
					ISNULL(@DESTINATARIO_RAZON_SOCIAL,' ')														+ '|' +
					ISNULL(CONVERT(VARCHAR,@DESTINATARIO_TENEDOR),' ')											+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CALLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_NUMERO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_COMPLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PISO,' ')															+ '|' +
					ISNULL(@DESTINO_DOMICILIO_DTO	,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_BARRIO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CODIGOP,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PROVINCIA,' ')													+ '|' +
					ISNULL(@PROPIO_DESTINO_DOMICILIO_CODIGO,' ')												+ '|' +
					'NO'																						+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					ISNULL(@arba_cot_ORIGEN_CUIT,' ')															+ '|' +
					ISNULL(@arba_cot_ORIGEN_RAZON_SOCIAL,' ')													+ '|' +
					ISNULL(CONVERT(VARCHAR,@arba_cot_EMISOR_TENEDOR),' ')										+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_CALLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_NUMERO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_COMPLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PISO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_DTO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_BARRIO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMILILIO_CODIGOP,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,' ')											+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,' ')													+ '|' + --Dario 16/10/2018
					@TRANSPORTISTA_CUIT																			+ '|' +		--TAX_NUMBER de DELIVERY
					ISNULL(@arba_cot_TIPO_RECORRIDO	,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@arba_cot_RECORRIDO_CALLE,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_RUTA,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_VEHICULO,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_ACOPLADO,' ')														+ '|' +
					'0'																							+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					dbo.fnSIAP_ConvertDecimal2String(CONVERT(VARCHAR,@IMPORTE), 10)												--IMPORTE


				-- ---------------------------------------------------------------------------------------------------------------
				-- CURSOR DE PROCESAMIENTO DE ARTÍCULOS DE CADA REMITO
				-- ---------------------------------------------------------------------------------------------------------------

				DECLARE
					@arbaCOT_Nomenclador	VARCHAR(15),
					@item_measureARBA		VARCHAR(15),
					@qty					INT,
					@item_code				VARCHAR(25),
					@item_desc				VARCHAR(40),
					@item_measure			VARCHAR(20)




				DECLARE DocumentItemsDetail_Cursor CURSOR FOR

					--ACA VA EL SELECT
					SELECT
						ISNULL(ti.arbaCOT_Nomenclador,' '),
						ISNULL(tamu.cot_um_id,' '),
						ISNULL(tit.it_qty,' '),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_code,' '),25),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_desc,' '),40),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(tmu.mu_shortDesc,' '),20)


					FROM tbItemTransactions							tit		WITH(NOLOCK)
						INNER JOIN tbItem							ti		WITH(NOLOCK)
						ON  ti.comp_id			= tit.comp_id		AND
							ti.item_id			= tit.item_id
						LEFT JOIN tbMetricUnits						tmu		WITH(NOLOCK)
						ON	tmu.comp_id			= ti.comp_id		AND
							tmu.mu_id			= ti.mu_id
						INNER JOIN tbsysARBACOT_MetricUnit			tamu	WITH(NOLOCK)
						ON	tamu.cot_um_id		= tmu.cot_um_id


					WHERE	tit.comp_id			= @comp_id			AND
							--tit.bra_id			= @bra_id			AND
							tit.ct_transaction	= @lCT_TRANSACTION	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1									AND
							IsNull(ti.arbaCOT_Nomenclador,'') <> ''


				OPEN DocumentItemsDetail_Cursor
				FETCH NEXT FROM DocumentItemsDetail_Cursor
				INTO
					@arbaCOT_Nomenclador,
					@item_measureARBA,
					@qty,
					@item_code,
					@item_desc,
					@item_measure

				WHILE @@FETCH_STATUS = 0
					BEGIN


						INSERT INTO @tblCOT
						(
							Record
						)
						SELECT
							@RecordType3															+ '|' +
							@arbaCOT_Nomenclador													+ '|' +
							@item_measureARBA														+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	+ '|' +
							CONVERT(VARCHAR,@item_code)												+ '|' +
							CONVERT(VARCHAR,@item_desc)												+ '|' +
							CONVERT(VARCHAR,@item_measure)											+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	--CONVERTIMOS A VARCHAR PARA PODER CONCATENARLO



						FETCH NEXT FROM DocumentItemsDetail_Cursor
						INTO
							@arbaCOT_Nomenclador,
							@item_measureARBA,
							@qty,
							@item_code,
							@item_desc,
							@item_measure

					END



				CLOSE DocumentItemsDetail_Cursor
				DEALLOCATE DocumentItemsDetail_Cursor

				-- ---------------------------------------------------------------------------------------------------------------


				FETCH NEXT FROM DocumentsHeader_Cursor
				INTO
					@emissionDate,

					@ds_ct_transaction,

					@arba_cot_Fecha_Hora_Salida_Transporte,

					@esConsumidorFinal,

					@arba_cot_SUJETO_GENERADOR_IsDestiny,

					@arba_cot_ORIGEN_CUIT,
					@arba_cot_ORIGEN_RAZON_SOCIAL,
					@arba_cot_EMISOR_TENEDOR,

					@arba_cot_ORIGEN_DOMICILIO_CALLE,
					@arba_cot_ORIGEN_DOMICILIO_NUMERO,
					@arba_cot_ORIGEN_DOMICILIO_COMPLE,
					@arba_cot_ORIGEN_DOMICILIO_PISO,
					@arba_cot_ORIGEN_DOMICILIO_DTO,
					@arba_cot_ORIGEN_DOMICILIO_BARRIO,
					@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
					@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
					@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,  --Dario 16/10/2018

					@arba_cot_TIPO_RECORRIDO,
					@arba_cot_RECORRIDO_LOCALIDAD,
					@arba_cot_RECORRIDO_CALLE,
					@arba_cot_RECORRIDO_RUTA,

					@arba_cot_PATENTE_VEHICULO,
					@arba_cot_PATENTE_ACOPLADO,
					@arba_cot_Counter,
					@TRANSPORTISTA_CUIT,
					@IMPORTE,
					@state_id

			END

		CLOSE DocumentsHeader_Cursor
	DEALLOCATE DocumentsHeader_Cursor

	--INSERTAMOS EL CUARTO REGISTRO
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType4							+ '|' +
		CONVERT(VARCHAR,@lIntDocumentCounter)


	SELECT @fileName
	SELECT tmp.Record  FROM @tblCOT tmp ORDER BY tmp.intOrder

END
--1
GO






----------------------------------------------------------------------------
-- Para las FECHAS se convierte con dbo.fnSIAP_ConvertDate2StringAaAAMMDD(Fecha,'')
-- Para los NUMEROS se convierte con fnSIAP_ConvertDecimal2String(NUMERO,LONGITUD)
-- Para los CaraCTERES se convierte CON fnSIAP_ConvertString2FIXLength( String,Longitud )
-- Si hay que poner 16 ceros, poner el string sin el convert a char....

-- http://www.arba.gov.ar/Apartados/Agentes/remitoelectr%C3%B3nico.asp?lugar=E
----------------------------------------------------------------------------
--- ARBA - COT
--- MOS 04-2014
----------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSysExportData_getCOTNew]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@ds_id				INT,
	@OnlyCOT4State		BIT,
	@state_id4Filter	int
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE	@comp_id			INT
	DECLARE	@lang_id			INT
	DECLARE @bra_id				INT
	DECLARE @ds_id				INT

	SET		@comp_id			= 1
	SET		@lang_id			= 2
	SET		@bra_id				= 1
	SET		@ds_id				= 22
	*/
	-- ----------------------------------------------------------



	-- Modo de Obtener Comprobantes Disponibles
	-- 0: Normal
	-- 1: Todas Las Sucursales
	-- 2: Todas Las Sucursales con sdlme=Enviar
	DECLARE @intMode AS INT
	SET		@intMode = 0
	SELECT  @intMode =  IsNull(tb.bra_deliverySheetMode,0)
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id





	DECLARE @tblCOT TABLE(Record NVARCHAR(1000), intOrder INT IDENTITY(1,1))

	-- 1er registro, cuit empresa
	-- Cursort para leer los remitos incluidos en la planilla
	-- por cada uno generar reqgistros del tipo 2 y del tipo 3
	--grabar registro del tipo 4 con la cuenta total
	-- hacer un select * de la temporal
	-- grabarlo en /temp y llamar al web service



	--VARIABLES DE TRABAJO
	DECLARE
		@cuit		VARCHAR(20),
		@planta		VARCHAR(20),			--Nº de Planta
		@puerta		VARCHAR(20),			--Nº de Puerta
		@AFIPDoc_CD	DATETIME,		--Fecha de Creación del Documento
		@secNumber	INT,			--Nº Secuencial

		@fileName	NVARCHAR(500),	--Nombre del Archivo Completo

		@RecordType1	CHAR(2),
		@RecordType2	CHAR(2),
		@RecordType3	CHAR(2),
		@RecordType4	CHAR(2)

	--CONSTANTES DE REGISTROS
	SET @RecordType1 = '01'
	SET @RecordType2 = '02'
	SET @RecordType3 = '03'
	SET @RecordType4 = '04'

	DECLARE @dl_id	INT
	SET @dl_id = NULL
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- DATOS PARA LA GENERACIÓN DEL NOMBRE DEL ARCHIVO
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @arba_cot_cust_id_alternativeDestiny AS INT
	--CUIT
	SELECT
		@cuit		= ISNULL(td.arba_cot_ORIGEN_CUIT,''),
		@planta		= ISNULL(td.arba_cot_Planta,''),
		@puerta		= ISNULL(td.arba_cot_Puerta,''),
		@secNumber	= ISNULL(td.arba_cot_Counter,0),
		@dl_id		= td.dl_id,
		@arba_cot_cust_id_alternativeDestiny = td.arba_cot_cust_id_alternativeDestiny
	FROM tbDelivery							td		WITH(NOLOCK)
		INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
		ON	tdsh.comp_id	= td.comp_id	AND
			tdsh.dl_id		= td.dl_id
	WHERE	tdsh.ds_id		= @ds_id


	UPDATE tbDelivery
		SET
			arba_cot_Counter = @secNumber + 1
		WHERE dl_id = @dl_id


	SELECT @AFIPDoc_CD = dbo.fnSIAP_ConvertDate2StringAaAAMMDD(GETDATE(),'')

	SELECT @fileName =	'TB'							+ '_' +
						CONVERT(VARCHAR,@cuit)			+ '_' +
						CONVERT(VARCHAR,@planta)		+ '' +									--STL ANTES TENIA ESTO EN LUGAR DE LO QUE ESTA AHORA + '_' +
						CONVERT(VARCHAR,@puerta)		+ '_' +
						REPLACE(CONVERT(VARCHAR, GETDATE(), 111), '/','') + '_' +
						dbo.fnSIAP_ConvertString2FIXLength2(CONVERT(VARCHAR,@secNumber), 6,'0')

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- OBTENEMOS LA CANTIDAD DE REMITOS QUE TIENE EL DS_ID ASOCIADOS
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		DECLARE
			@lIntDocumentCounter	INT

		SELECT @lIntDocumentCounter = COUNT(*)
			FROM tbDeliverySheetDetail tdsd	WITH (NOLOCK)
			INNER JOIN tbCommercialTransactions tct	WITH (NOLOCK)
				ON	tct.comp_id			= tdsd.comp_id AND
					tct.ct_transaction	= tdsd.ds_ct_transaction
			INNER JOIN tbCustomer tc	WITH (NOLOCK)
				ON	tc.comp_id			= tct.comp_id AND
					tc.cust_id			= tct.cust_id
			WHERE	tdsd.comp_id	= @comp_id	AND
					tdsd.ds_id		= @ds_id	AND
				   (
						tct.state_id		= @state_id4Filter
							OR
						@OnlyCOT4State = 'False'
					)
				   --(tc.state_id		= 54020		OR @OnlyCOT4State = 'False')
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------
	-- Registro Tipo 01
	-- ---------------------------------------------------------
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType1 + '|' +
		CONVERT(VARCHAR,@cuit)
	-- ---------------------------------------------------------


	--VARIABLES DEL CURSOR
	DECLARE
			@emissionDate								DATETIME,

			@ds_ct_transaction							INT,

			@arba_cot_Fecha_Hora_Salida_Transporte		DATETIME,

			@esConsumidorFinal							BIT,

			@arba_cot_SUJETO_GENERADOR_IsDestiny		CHAR(1),

			@arba_cot_ORIGEN_CUIT						VARCHAR(11),
			@arba_cot_ORIGEN_RAZON_SOCIAL				VARCHAR(50),
			@arba_cot_EMISOR_TENEDOR					BIT,

			@arba_cot_ORIGEN_DOMICILIO_CALLE			VARCHAR(40),
			@arba_cot_ORIGEN_DOMICILIO_NUMERO			VARCHAR(5),
			@arba_cot_ORIGEN_DOMICILIO_COMPLE			VARCHAR(200),
			@arba_cot_ORIGEN_DOMICILIO_PISO				VARCHAR(3),
			@arba_cot_ORIGEN_DOMICILIO_DTO				VARCHAR(4),
			@arba_cot_ORIGEN_DOMICILIO_BARRIO			VARCHAR(30),
			@arba_cot_ORIGEN_DOMILILIO_CODIGOP			VARCHAR(8),
			@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD		VARCHAR(50),

			@arba_cot_ORIGEN_DOMICILIO_PROVINCIA		VARCHAR(1),  --dario 16/10/2018

			@arba_cot_TIPO_RECORRIDO					CHAR(1),
			@arba_cot_RECORRIDO_LOCALIDAD				VARCHAR(50),
			@arba_cot_RECORRIDO_CALLE					VARCHAR(40),
			@arba_cot_RECORRIDO_RUTA					VARCHAR(40),

			@arba_cot_PATENTE_VEHICULO					VARCHAR(7),
			@arba_cot_PATENTE_ACOPLADO					VARCHAR(7),
			@arba_cot_Counter							INT,
			@TRANSPORTISTA_CUIT							VARCHAR(11),
			@IMPORTE									DECIMAL(19,2),
			@state_id									INT


	DECLARE DocumentsHeader_Cursor CURSOR LOCAL FAST_FORWARD FOR

		--ACA VA EL SELECT
		SELECT

			tct.ct_date,						--FECHA EMISIÓN

			tdsd.ds_ct_transaction,

			tdsh.arba_cot_Fecha_Hora_Salida_Transporte,

			CASE tc.fc_id
				WHEN	2 THEN		1			--CONSUMIDOR FINAL
				ELSE				0
			END,
			CASE td.arba_cot_SUJETO_GENERADOR_IsDestiny
				WHEN	1 THEN		'D'
				ELSE				'E'
			END,

			td.arba_cot_ORIGEN_CUIT,
			td.arba_cot_ORIGEN_RAZON_SOCIAL,
			td.arba_cot_EMISOR_TENEDOR,

			td.arba_cot_ORIGEN_DOMICILIO_CALLE,
			td.arba_cot_ORIGEN_DOMICILIO_NUMERO,
			td.arba_cot_ORIGEN_DOMICILIO_COMPLE,
			td.arba_cot_ORIGEN_DOMICILIO_PISO,
			td.arba_cot_ORIGEN_DOMICILIO_DTO,
			td.arba_cot_ORIGEN_DOMICILIO_BARRIO,
			td.arba_cot_ORIGEN_DOMILILIO_CODIGOP,
			td.arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,

			ISNULL(ts.state_arba_cot,' ') as arba_cot_ORIGEN_DOMICILIO_PROVINCIA,

			--td.arba_cot_EMISOR_TENEDOR,
			--td.arba_cot_ORIGEN_CUIT,
			--td.arba_cot_ORIGEN_RAZON_SOCIAL,

			tdsh.arba_cot_TIPO_RECORRIDO,
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_LOCALIDAD,50),



			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_CALLE,40),
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_RUTA,40),

			td.arba_cot_PATENTE_VEHICULO,
			td.arba_cot_PATENTE_ACOPLADO,
			td.arba_cot_Counter,
			ISNULL(td.dl_taxNumber,' '),
			--tct.ct_total,
			CASE	-- MOS 12-2022 x GN 17647
				WHEN tdf.df_COT_isOverNETO = 'True' THEN	tct.ct_total
				ELSE										tct.ct_subtotal
			END,
			tct.state_id

		FROM tbDelivery							td		WITH(NOLOCK)

			INNER JOIN tbsysState				ts      WITH(NOLOCK)   --dario 16/10/2018
			ON	ts.country_id	= td.country_id AND
				ts.state_id		= td.state_id

			INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
			ON	tdsh.comp_id	= td.comp_id	AND
				tdsh.dl_id		= td.dl_id
			INNER JOIN tbDeliverySheetDetail	tdsd	WITH(NOLOCK)
			ON	tdsd.comp_id	= tdsh.comp_id	AND
				--tdsd.bra_id		= tdsh.bra_id	AND
				tdsd.ds_id		= tdsh.ds_id

			INNER JOIN tbCommercialTransactions	tct		WITH(NOLOCK)
			ON	tct.comp_id			= td.comp_id				AND
				tct.ct_transaction	= tdsd.ds_ct_transaction	--AND
				--tct.sd_id			IN (2)

			-- MOS 12-2022 x GN 17647
			LEFT JOIN tbDocumentsFile		 AS tdf		WITH (NOLOCK)
				ON	tdf.comp_id		= tct.comp_id AND
					tdf.df_id		= tct.df_id

			INNER JOIN tbCustomer				tc		WITH(NOLOCK)
			ON	tc.comp_id		= tct.comp_id	AND
				tc.cust_id		= tct.cust_id

		WHERE	tdsh.comp_id	= @comp_id		AND
				tdsh.ds_id		= @ds_id		AND
			   (tct.state_id	= @state_id4Filter OR @OnlyCOT4State = 'False')
			   --(tc.state_id		= 54020 OR @OnlyCOT4State = 'False')


	OPEN DocumentsHeader_Cursor

	FETCH NEXT FROM DocumentsHeader_Cursor
	INTO
		@emissionDate,

		@ds_ct_transaction,

		@arba_cot_Fecha_Hora_Salida_Transporte,

		@esConsumidorFinal,

		@arba_cot_SUJETO_GENERADOR_IsDestiny,

		@arba_cot_ORIGEN_CUIT,
		@arba_cot_ORIGEN_RAZON_SOCIAL,
		@arba_cot_EMISOR_TENEDOR,

		@arba_cot_ORIGEN_DOMICILIO_CALLE,
		@arba_cot_ORIGEN_DOMICILIO_NUMERO,
		@arba_cot_ORIGEN_DOMICILIO_COMPLE,
		@arba_cot_ORIGEN_DOMICILIO_PISO,
		@arba_cot_ORIGEN_DOMICILIO_DTO,
		@arba_cot_ORIGEN_DOMICILIO_BARRIO,
		@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
		@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
		@arba_cot_ORIGEN_DOMICILIO_PROVINCIA, --Dario 16/10/2018

		@arba_cot_TIPO_RECORRIDO,
		@arba_cot_RECORRIDO_LOCALIDAD,
		@arba_cot_RECORRIDO_CALLE,
		@arba_cot_RECORRIDO_RUTA,

		@arba_cot_PATENTE_VEHICULO,
		@arba_cot_PATENTE_ACOPLADO,
		@arba_cot_Counter,
		@TRANSPORTISTA_CUIT,
		@IMPORTE,
		@state_id

		WHILE @@FETCH_STATUS = 0
			BEGIN



				-- ----------------------------------------------------------------------------------------------------------------
				-- PARA VER SI TIENE ARTICULOS EN EL CT_TRANSACTION O TENGO QUE IR A BUSCARLO A "ct_transaction_packinglist"
				-- ----------------------------------------------------------------------------------------------------------------
				DECLARE
					@lCT_TRANSACTION	INT

				IF (SELECT COUNT(*)
				    FROM tbCommercialTransactions						tct	WITH(NOLOCK)
						INNER JOIN tbItemTransactions					tit	WITH(NOLOCK)
						ON	tit.comp_id			= tct.comp_id			AND
							tit.ct_transaction	= tct.ct_transaction
				    WHERE	tct.comp_id			= @comp_id				AND
							tct.ct_transaction	= @ds_ct_transaction	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1
					) = 0

					BEGIN

						--SI ES UN REMITO Y NO TIENE ARTÍCULOS LE ASIGNA EL PACKINK_LIST
						SELECT
							@lCT_TRANSACTION		= tct.ct_transaction_PackingList
						  FROM tbCommercialTransactions						tct	WITH (NOLOCK)
						WHERE	tct.comp_id			= @comp_id				AND
								tct.ct_transaction	= @ds_ct_transaction
					END


				ELSE
					BEGIN
						--SINO, SETEA EL MISMO CT_TRANSACTION
						SET @lCT_TRANSACTION = @ds_ct_transaction
					END


--==
--SELECT '@lCT_TRANSACTION:', @lCT_TRANSACTION
--==

				-- ----------------------------------------------------------------------------------------------------------------

				--ARMAMOS EL CODIGO_UNICO

				DECLARE
					@CODIGO_UNICO	VARCHAR(16)
				DECLARE @strDeliveryAddress AS NVARCHAR(4000)



				SELECT @strDeliveryAddress =
												CASE
													WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
														 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
													WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
													WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
													WHEN ISNULL(cust.cust_address4Delivery,'') <> ''	THEN cust.cust_address4Delivery
													ELSE													 cust.cust_address
												END
					FROM tbCommercialTransactions CT	WITH (NOLOCK)

					LEFT join dbo.tbCommercialTransactionNotes		CTN	WITH (NOLOCK)
					on	CTN.comp_id				= CT.comp_id
					and	CTN.bra_id				= CT.bra_id
					and CTN.ct_transaction		= CT.ct_transaction


					LEFT join dbo.tbCustomer						cust	WITH (NOLOCK)
					on  cust.comp_id				= ct.comp_id AND
						cust.cust_id				= ct.cust_id


					LEFT JOIN tbCustomerFamily tcf	WITH (NOLOCK)
						ON	tcf.comp_id		= ct.comp_id AND
							tcf.cust_id		= ct.cust_id AND
							tcf.custf_id	= ct.custf_id

					LEFT JOIN tbCustomerBranch tcb	WITH (NOLOCK)
						ON		tcb.comp_id = ct.comp_id
							AND tcb.cust_id = ct.cust_id
							AND tcb.cb_id	= ct.cb_id

					WHERE	CT.comp_id			= @comp_id AND
							CT.ct_transaction	= @ds_ct_transaction



				SELECT
					--@CODIGO_UNICO = CASE
					--					WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '91 R'
					--					WHEN tct.sd_id = 2						    THEN '94 X'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '01 A'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '06 B'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '92 C'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '51 M'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '60 A'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '61 B'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '93 C'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '58 M'

					--					ELSE										    '97 E'
					--				END


					-- MOS 03-2022.  Se puso el resto de los COT iguales a este.
					-- chrome-extension://efaidnbmnnnibpcajpcglclefindmkaj/viewer.html?pdfurl=https%3A%2F%2Fwww.arba.gov.ar%2Farchivos%2FPublicaciones%2Fnuevodiseniodearchivotxt.pdf&clen=531562&chunk=true
					@CODIGO_UNICO = CASE
										WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '091'
										WHEN tct.sd_id = 2						    THEN '094'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '001'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '006'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '011'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '051'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '060'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '061'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '093'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '058'

										ELSE										    '099'
									END

										/*'91 R'*/ + '' +
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 5,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]		NEW de 4 a 5
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_docNumber  , 8,'0')									--[NUMERO_DOCNUMBER]

					FROM tbCommercialTransactions tct	WITH (NOLOCK)

					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction --@lCT_TRANSACTION

				-- ----------------------------------------------------------------------------------------------------------------


				--OBTENEMOS LOS DATOS DEL CLIENTE
				DECLARE @lcust_id	   INT
				DECLARE @lcustf_ID	AS INT
				DECLARE @lCB_Id		AS INT
				SELECT  @lcust_id = tct.cust_id,
						@lcustf_ID= tct.custf_id,
						@lCB_Id   = tct.cb_id
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction


				-- Se usa para el caso de Entregar a un transporte en el que la mercaderia sale de nuestra empresa pero el
				-- destino NO es el cliente sino que es el transporte.
				IF @arba_cot_cust_id_alternativeDestiny IS NOT NULL
					BEGIN
						SET @lcust_id = @arba_cot_cust_id_alternativeDestiny
					END



				DECLARE
					@DESTINATARIO_TIPO_DOCUMENTO		VARCHAR(3),
					@DESTINATARIO_DOCUMENTO				VARCHAR(11),
					@DESTINATARIO_CUIT					VARCHAR(11),
					@DESTINATARIO_RAZON_SOCIAL			VARCHAR(50),
					@DESTINATARIO_TENEDOR				BIT,
					@DESTINO_DOMICILIO_CALLE			VARCHAR(40),
					@DESTINO_DOMICILIO_NUMERO			VARCHAR(5),
					@DESTINO_DOMICILIO_COMPLE			VARCHAR(5),
					@DESTINO_DOMICILIO_PISO				VARCHAR(3),
					@DESTINO_DOMICILIO_DTO				VARCHAR(4),
					@DESTINO_DOMICILIO_BARRIO			VARCHAR(30),
					@DESTINO_DOMICILIO_CODIGOP			VARCHAR(8),
					@DESTINO_DOMICILIO_LOCALIDAD		VARCHAR(50),
					@DESTINO_DOMICILIO_PROVINCIA		VARCHAR(1),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	VARCHAR(50)

				-- *************************************************************************************
				-- SEPARAMOS EL NUMERO DE LA DIRECCION
				-- NOTA: SEPARA TODOS LOS NUMEROS, POR ENDE SI LA DIRECCION ES '25 de Mayo 3323'
				--       EL RESULTADO SERA '253323' <-- TODOS LOS NUMEROS CONCATENADOS
				--       DE MOMENTO NO HAY UNA SOLUCION MEJOR
				-- *************************************************************************************
				DECLARE @thestring VARCHAR(50)
				SET @thestring = @strDeliveryAddress --(SELECT tc.cust_address FROM tbCustomer tc WHERE tc.comp_id = @comp_id AND tc.cust_id = @lcust_id)
				DECLARE @final VARCHAR(50)
				SET @final = ''

				SELECT @final = @final + x.thenum
				FROM
				(
					SELECT SUBSTRING(@thestring, number, 1) AS thenum, number
					FROM master..spt_values
					WHERE substring(@thestring, number, 1) LIKE '[0-9]' AND TYPE='P'
				) x
				ORDER BY x.number
				DECLARE
					@DESTINO_DOMICILIO_NUMEROFINAL VARCHAR(5)
				SET @DESTINO_DOMICILIO_NUMEROFINAL = @final
				-- *************************************************************************************



				SELECT
					@DESTINATARIO_TIPO_DOCUMENTO		= ISNULL(ttnt.tnt_ARBACOT,' '),
					@DESTINATARIO_DOCUMENTO				= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_CUIT					= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_RAZON_SOCIAL			= ISNULL(tc.cust_name,' '),
					@DESTINATARIO_TENEDOR				= CASE @esConsumidorFinal
															  WHEN 1 THEN 0
															  ELSE        1
					                     				  END,	--SI ES CONSUMIDOR FINAL es CERO, SINO es 1
					@DESTINO_DOMICILIO_CALLE			= ISNULL(@strDeliveryAddress /*tc.cust_address*/,' '), --COMO SEPARO EL NUMERO DE LA CALLE PARA PONERLO ABAJO????
					@DESTINO_DOMICILIO_NUMERO			= ISNULL(@DESTINO_DOMICILIO_NUMEROFINAL,' '),
					@DESTINO_DOMICILIO_COMPLE			= 'S/N', --ISNULL(tc.cust_address,' '),
					@DESTINO_DOMICILIO_PISO				= ' ',
					@DESTINO_DOMICILIO_DTO				= ' ',
					@DESTINO_DOMICILIO_BARRIO			= ' ',
					@DESTINO_DOMICILIO_CODIGOP			= ISNULL(tcb.custb_zip,  ISNULL(tc.cust_zip,' ')),
					@DESTINO_DOMICILIO_LOCALIDAD		= ISNULL(tcb.custb_city, ISNULL(tc.cust_city,' ')),
					@DESTINO_DOMICILIO_PROVINCIA		= ISNULL(ts.state_arba_cot,' '),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	= ' '

					FROM tbCustomer							tc		WITH (NOLOCK)
					INNER JOIN tbsysState				ts			WITH (NOLOCK)
						ON ts.state_id = @state_id
					LEFT JOIN tbCustomerBranch		AS tcb			WITH (NOLOCK)
						ON	tcb.comp_id = tc.comp_id	AND
							tcb.cust_id = @lcust_id		AND
							tcb.cb_id	= @lCB_Id

						INNER JOIN tbsysTaxNumberTypes		ttnt	WITH (NOLOCK)
						ON	ttnt.tnt_id		= tc.tnt_id

				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @lcust_id



				SET @arba_cot_Fecha_Hora_Salida_Transporte = GETDATE()


				IF @DESTINATARIO_TIPO_DOCUMENTO = ''
					BEGIN
						SET @DESTINATARIO_DOCUMENTO	 = ''
					END

				IF @esConsumidorFinal = 1
					BEGIN
						set @DESTINATARIO_CUIT = ''
					END
				IF @esConsumidorFinal = 0
					BEGIN
						set @DESTINATARIO_TIPO_DOCUMENTO = ''
						set @DESTINATARIO_DOCUMENTO		 = ''
					END
				set @DESTINATARIO_CUIT = REPLACE(@DESTINATARIO_CUIT,'-','')

				if @DESTINO_DOMICILIO_COMPLE = 'S/N'
					BEGIN
						set @DESTINO_DOMICILIO_NUMERO = ''
					END


				--INSERTAMOS EL SEGUNDO REGISTRO CON LOS DATOS DEL TRANSPORTE Y DE A QUIEN SE LO ENVIAMOS
				--SELECT @lCT_TRANSACTION
				INSERT INTO @tblCOT
				(
					Record
				)
				SELECT
					@RecordType2																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @emissionDate, 111), '/',''),' ')							+ '|' +		--FECHA
					@CODIGO_UNICO																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 111), '/',''),' ')	+ '|' +		--FECHA
					substring(ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 108), ':',''),'    '),1,4)	+ '|' +		--HORA
					@arba_cot_SUJETO_GENERADOR_IsDestiny														+ '|' +		--SUJETO_GENERADOR E(emisor) D(destinatario)
					ISNULL(CONVERT(VARCHAR,@esConsumidorFinal),' ')												+ '|' +
					ISNULL(@DESTINATARIO_TIPO_DOCUMENTO,' ')													+ '|' +
					ISNULL(@DESTINATARIO_DOCUMENTO,' ')															+ '|' +
					ISNULL(@DESTINATARIO_CUIT,' ')																+ '|' +
					ISNULL(@DESTINATARIO_RAZON_SOCIAL,' ')														+ '|' +
					ISNULL(CONVERT(VARCHAR,@DESTINATARIO_TENEDOR),' ')											+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CALLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_NUMERO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_COMPLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PISO,' ')															+ '|' +
					ISNULL(@DESTINO_DOMICILIO_DTO	,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_BARRIO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CODIGOP,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PROVINCIA,' ')													+ '|' +
					ISNULL(@PROPIO_DESTINO_DOMICILIO_CODIGO,' ')												+ '|' +
					'NO'																						+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					ISNULL(@arba_cot_ORIGEN_CUIT,' ')															+ '|' +
					ISNULL(@arba_cot_ORIGEN_RAZON_SOCIAL,' ')													+ '|' +
					ISNULL(CONVERT(VARCHAR,@arba_cot_EMISOR_TENEDOR),' ')										+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_CALLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_NUMERO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_COMPLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PISO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_DTO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_BARRIO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMILILIO_CODIGOP,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,' ')											+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,' ')													+ '|' + --Dario 16/10/2018
					@TRANSPORTISTA_CUIT																			+ '|' +		--TAX_NUMBER de DELIVERY
					ISNULL(@arba_cot_TIPO_RECORRIDO	,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@arba_cot_RECORRIDO_CALLE,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_RUTA,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_VEHICULO,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_ACOPLADO,' ')														+ '|' +
					'0'																							+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					dbo.fnSIAP_ConvertDecimal2String(CONVERT(VARCHAR,@IMPORTE), 12)												--IMPORTE  NEW de 10 a 12


				-- ---------------------------------------------------------------------------------------------------------------
				-- CURSOR DE PROCESAMIENTO DE ARTÍCULOS DE CADA REMITO
				-- ---------------------------------------------------------------------------------------------------------------

				DECLARE
					@arbaCOT_Nomenclador	VARCHAR(15),
					@item_measureARBA		VARCHAR(15),
					@qty					INT,
					@item_code				VARCHAR(25),
					@item_desc				VARCHAR(40),
					@item_measure			VARCHAR(20)




				DECLARE DocumentItemsDetail_Cursor CURSOR FOR

					--ACA VA EL SELECT
					SELECT
						ISNULL(ti.arbaCOT_Nomenclador,' '),
						ISNULL(tamu.cot_um_id,' '),
						ISNULL(tit.it_qty,' '),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_code,' '),25),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_desc,' '),40),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(tmu.mu_shortDesc,' '),20)


					FROM tbItemTransactions							tit		WITH(NOLOCK)
						INNER JOIN tbItem							ti		WITH(NOLOCK)
						ON  ti.comp_id			= tit.comp_id		AND
							ti.item_id			= tit.item_id
						LEFT JOIN tbMetricUnits						tmu		WITH(NOLOCK)
						ON	tmu.comp_id			= ti.comp_id		AND
							tmu.mu_id			= ti.mu_id
						INNER JOIN tbsysARBACOT_MetricUnit			tamu	WITH(NOLOCK)
						ON	tamu.cot_um_id		= tmu.cot_um_id


					WHERE	tit.comp_id			= @comp_id			AND
							--tit.bra_id			= @bra_id			AND
							tit.ct_transaction	= @lCT_TRANSACTION	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1									AND
							IsNull(ti.arbaCOT_Nomenclador,'') <> ''


				OPEN DocumentItemsDetail_Cursor
				FETCH NEXT FROM DocumentItemsDetail_Cursor
				INTO
					@arbaCOT_Nomenclador,
					@item_measureARBA,
					@qty,
					@item_code,
					@item_desc,
					@item_measure

				WHILE @@FETCH_STATUS = 0
					BEGIN


						INSERT INTO @tblCOT
						(
							Record
						)
						SELECT
							@RecordType3															+ '|' +
							@arbaCOT_Nomenclador													+ '|' +
							@item_measureARBA														+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	+ '|' +
							CONVERT(VARCHAR,@item_code)												+ '|' +
							CONVERT(VARCHAR,@item_desc)												+ '|' +
							CONVERT(VARCHAR,@item_measure)											+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	--CONVERTIMOS A VARCHAR PARA PODER CONCATENARLO



						FETCH NEXT FROM DocumentItemsDetail_Cursor
						INTO
							@arbaCOT_Nomenclador,
							@item_measureARBA,
							@qty,
							@item_code,
							@item_desc,
							@item_measure

					END



				CLOSE DocumentItemsDetail_Cursor
				DEALLOCATE DocumentItemsDetail_Cursor

				-- ---------------------------------------------------------------------------------------------------------------


				FETCH NEXT FROM DocumentsHeader_Cursor
				INTO
					@emissionDate,

					@ds_ct_transaction,

					@arba_cot_Fecha_Hora_Salida_Transporte,

					@esConsumidorFinal,

					@arba_cot_SUJETO_GENERADOR_IsDestiny,

					@arba_cot_ORIGEN_CUIT,
					@arba_cot_ORIGEN_RAZON_SOCIAL,
					@arba_cot_EMISOR_TENEDOR,

					@arba_cot_ORIGEN_DOMICILIO_CALLE,
					@arba_cot_ORIGEN_DOMICILIO_NUMERO,
					@arba_cot_ORIGEN_DOMICILIO_COMPLE,
					@arba_cot_ORIGEN_DOMICILIO_PISO,
					@arba_cot_ORIGEN_DOMICILIO_DTO,
					@arba_cot_ORIGEN_DOMICILIO_BARRIO,
					@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
					@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
					@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,  --Dario 16/10/2018

					@arba_cot_TIPO_RECORRIDO,
					@arba_cot_RECORRIDO_LOCALIDAD,
					@arba_cot_RECORRIDO_CALLE,
					@arba_cot_RECORRIDO_RUTA,

					@arba_cot_PATENTE_VEHICULO,
					@arba_cot_PATENTE_ACOPLADO,
					@arba_cot_Counter,
					@TRANSPORTISTA_CUIT,
					@IMPORTE,
					@state_id

			END

		CLOSE DocumentsHeader_Cursor
	DEALLOCATE DocumentsHeader_Cursor

	--INSERTAMOS EL CUARTO REGISTRO
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType4							+ '|' +
		CONVERT(VARCHAR,@lIntDocumentCounter)


	SELECT @fileName
	SELECT tmp.Record  FROM @tblCOT tmp ORDER BY tmp.intOrder

END
--1
GO





----------------------------------------------------------------------------
-- Para las FECHAS se convierte con dbo.fnSIAP_ConvertDate2StringAaAAMMDD(Fecha,'')
-- Para los NUMEROS se convierte con fnSIAP_ConvertDecimal2String(NUMERO,LONGITUD)
-- Para los CaraCTERES se convierte CON fnSIAP_ConvertString2FIXLength( String,Longitud )
-- Si hay que poner 16 ceros, poner el string sin el convert a char....

-- http://www.arba.gov.ar/Apartados/Agentes/remitoelectr%C3%B3nico.asp?lugar=E
----------------------------------------------------------------------------
--- ARBA - COT
--- MOS 04-2014
----------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spSysExportData_getCOTSantaFe]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@ds_id				INT,
	@OnlyCOT4State		BIT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE	@comp_id			INT
	DECLARE	@lang_id			INT
	DECLARE @bra_id				INT
	DECLARE @ds_id				INT

	SET		@comp_id			= 1
	SET		@lang_id			= 2
	SET		@bra_id				= 1
	SET		@ds_id				= 22
	*/
	-- ----------------------------------------------------------



	-- Modo de Obtener Comprobantes Disponibles
	-- 0: Normal
	-- 1: Todas Las Sucursales
	-- 2: Todas Las Sucursales con sdlme=Enviar
	DECLARE @intMode AS INT
	SET		@intMode = 0
	SELECT  @intMode =  IsNull(tb.bra_deliverySheetMode,0)
		FROM tbBranch tb
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id





	DECLARE @tblCOT TABLE(Record NVARCHAR(1000), intOrder INT IDENTITY(1,1))

	-- 1er registro, cuit empresa
	-- Cursort para leer los remitos incluidos en la planilla
	-- por cada uno generar reqgistros del tipo 2 y del tipo 3
	--grabar registro del tipo 4 con la cuenta total
	-- hacer un select * de la temporal
	-- grabarlo en /temp y llamar al web service



	--VARIABLES DE TRABAJO
	DECLARE
		@cuit		VARCHAR(20),
		@planta		VARCHAR(20),			--Nº de Planta
		@puerta		VARCHAR(20),			--Nº de Puerta
		@AFIPDoc_CD	DATETIME,		--Fecha de Creación del Documento
		@secNumber	INT,			--Nº Secuencial

		@fileName	NVARCHAR(500),	--Nombre del Archivo Completo

		@RecordType1	CHAR(2),
		@RecordType2	CHAR(2),
		@RecordType3	CHAR(2),
		@RecordType4	CHAR(2)

	--CONSTANTES DE REGISTROS
	SET @RecordType1 = '01'
	SET @RecordType2 = '02'
	SET @RecordType3 = '03'
	SET @RecordType4 = '04'

	DECLARE @dl_id	INT
	SET @dl_id = NULL
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- DATOS PARA LA GENERACIÓN DEL NOMBRE DEL ARCHIVO
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @arba_cot_cust_id_alternativeDestiny AS INT
	--CUIT
	SELECT
		@cuit		= ISNULL(td.arba_cot_ORIGEN_CUIT,''),
		@planta		= ISNULL(td.arba_cot_Planta,''),
		@puerta		= ISNULL(td.arba_cot_Puerta,''),
		@secNumber	= ISNULL(td.arba_cot_Counter,0),
		@dl_id		= td.dl_id,
		@arba_cot_cust_id_alternativeDestiny = td.arba_cot_cust_id_alternativeDestiny
	FROM tbDelivery							td		WITH(NOLOCK)
		INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
		ON	tdsh.comp_id	= td.comp_id	AND
			tdsh.dl_id		= td.dl_id
	WHERE	tdsh.ds_id		= @ds_id


	UPDATE tbDelivery
		SET
			arba_cot_Counter = @secNumber + 1
		WHERE dl_id = @dl_id


	SELECT @AFIPDoc_CD = dbo.fnSIAP_ConvertDate2StringAaAAMMDD(GETDATE(),'')

	SELECT @fileName =	'TB'							+ '_' +
						CONVERT(VARCHAR,@cuit)			+ '_' +
						CONVERT(VARCHAR,@planta)		+ '' +									--STL ANTES TENIA ESTO EN LUGAR DE LO QUE ESTA AHORA + '_' +
						CONVERT(VARCHAR,@puerta)		+ '_' +
						REPLACE(CONVERT(VARCHAR, GETDATE(), 111), '/','') + '_' +
						dbo.fnSIAP_ConvertString2FIXLength2(CONVERT(VARCHAR,@secNumber), 6,'0')

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- OBTENEMOS LA CANTIDAD DE REMITOS QUE TIENE EL DS_ID ASOCIADOS
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		DECLARE
			@lIntDocumentCounter	INT

		SELECT @lIntDocumentCounter = COUNT(*)
			FROM tbDeliverySheetDetail tdsd
			INNER JOIN tbCommercialTransactions tct
				ON	tct.comp_id			= tdsd.comp_id AND
					tct.ct_transaction	= tdsd.ds_ct_transaction
			INNER JOIN tbCustomer tc
				ON	tc.comp_id			= tct.comp_id AND
					tc.cust_id			= tct.cust_id
			WHERE	tdsd.comp_id	= @comp_id	AND
					tdsd.ds_id		= @ds_id	AND
				   (tct.state_id		= 54024		OR @OnlyCOT4State = 'False')
				   --(tc.state_id		= 54024		OR @OnlyCOT4State = 'False')
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------
	-- Registro Tipo 01
	-- ---------------------------------------------------------
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType1 + '|' +
		CONVERT(VARCHAR,@cuit)
	-- ---------------------------------------------------------


	--VARIABLES DEL CURSOR
	DECLARE
			@emissionDate								DATETIME,

			@ds_ct_transaction							INT,

			@arba_cot_Fecha_Hora_Salida_Transporte		DATETIME,

			@esConsumidorFinal							BIT,

			@arba_cot_SUJETO_GENERADOR_IsDestiny		CHAR(1),

			@arba_cot_ORIGEN_CUIT						VARCHAR(11),
			@arba_cot_ORIGEN_RAZON_SOCIAL				VARCHAR(50),
			@arba_cot_EMISOR_TENEDOR					BIT,

			@arba_cot_ORIGEN_DOMICILIO_CALLE			VARCHAR(40),
			@arba_cot_ORIGEN_DOMICILIO_NUMERO			VARCHAR(5),
			@arba_cot_ORIGEN_DOMICILIO_COMPLE			VARCHAR(200),
			@arba_cot_ORIGEN_DOMICILIO_PISO				VARCHAR(3),
			@arba_cot_ORIGEN_DOMICILIO_DTO				VARCHAR(4),
			@arba_cot_ORIGEN_DOMICILIO_BARRIO			VARCHAR(30),
			@arba_cot_ORIGEN_DOMILILIO_CODIGOP			VARCHAR(8),
			@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD		VARCHAR(50),

			@arba_cot_ORIGEN_DOMICILIO_PROVINCIA		VARCHAR(1),  --dario 16/10/2018

			@arba_cot_TIPO_RECORRIDO					CHAR(1),
			@arba_cot_RECORRIDO_LOCALIDAD				VARCHAR(50),
			@arba_cot_RECORRIDO_CALLE					VARCHAR(40),
			@arba_cot_RECORRIDO_RUTA					VARCHAR(40),

			@arba_cot_PATENTE_VEHICULO					VARCHAR(7),
			@arba_cot_PATENTE_ACOPLADO					VARCHAR(7),
			@arba_cot_Counter							INT,
			@TRANSPORTISTA_CUIT							VARCHAR(11),
			@IMPORTE									DECIMAL(19,2),
			@state_id									INT


	DECLARE DocumentsHeader_Cursor CURSOR FOR

		--ACA VA EL SELECT
		SELECT

			tct.ct_date,						--FECHA EMISIÓN

			tdsd.ds_ct_transaction,

			tdsh.arba_cot_Fecha_Hora_Salida_Transporte,

			CASE tc.fc_id
				WHEN	2 THEN		1			--CONSUMIDOR FINAL
				ELSE				0
			END,
			CASE td.arba_cot_SUJETO_GENERADOR_IsDestiny
				WHEN	1 THEN		'D'
				ELSE				'E'
			END,

			td.arba_cot_ORIGEN_CUIT,
			td.arba_cot_ORIGEN_RAZON_SOCIAL,
			td.arba_cot_EMISOR_TENEDOR,

			td.arba_cot_ORIGEN_DOMICILIO_CALLE,
			td.arba_cot_ORIGEN_DOMICILIO_NUMERO,
			td.arba_cot_ORIGEN_DOMICILIO_COMPLE,
			td.arba_cot_ORIGEN_DOMICILIO_PISO,
			td.arba_cot_ORIGEN_DOMICILIO_DTO,
			td.arba_cot_ORIGEN_DOMICILIO_BARRIO,
			td.arba_cot_ORIGEN_DOMILILIO_CODIGOP,
			td.arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,

			ISNULL(ts.state_arba_cot,' ') as arba_cot_ORIGEN_DOMICILIO_PROVINCIA,

			--td.arba_cot_EMISOR_TENEDOR,
			--td.arba_cot_ORIGEN_CUIT,
			--td.arba_cot_ORIGEN_RAZON_SOCIAL,

			tdsh.arba_cot_TIPO_RECORRIDO,
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_LOCALIDAD,50),



			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_CALLE,40),
			dbo.fnSIAP_ConvertString2FIXLength(tdsh.arba_cot_RECORRIDO_RUTA,40),

			td.arba_cot_PATENTE_VEHICULO,
			td.arba_cot_PATENTE_ACOPLADO,
			td.arba_cot_Counter,
			ISNULL(td.dl_taxNumber,' '),
			--tct.ct_total,
			CASE	-- MOS 12-2022 x GN 17647
				WHEN tdf.df_COT_isOverNETO = 'True' THEN	tct.ct_total
				ELSE										tct.ct_subtotal
			END,
			tct.state_id

		FROM tbDelivery							td		WITH(NOLOCK)

			INNER JOIN tbsysState				ts      WITH(NOLOCK)   --dario 16/10/2018
			ON	ts.country_id	= td.country_id AND
				ts.state_id		= td.state_id

			INNER JOIN tbDeliverySheetHeader	tdsh	WITH(NOLOCK)
			ON	tdsh.comp_id	= td.comp_id	AND
				tdsh.dl_id		= td.dl_id
			INNER JOIN tbDeliverySheetDetail	tdsd	WITH(NOLOCK)
			ON	tdsd.comp_id	= tdsh.comp_id	AND
				--tdsd.bra_id		= tdsh.bra_id	AND
				tdsd.ds_id		= tdsh.ds_id

			INNER JOIN tbCommercialTransactions	tct		WITH(NOLOCK)
			ON	tct.comp_id			= td.comp_id				AND
				tct.ct_transaction	= tdsd.ds_ct_transaction	--AND
				--tct.sd_id			IN (2)

			-- MOS 12-2022 x GN 17647
			LEFT JOIN tbDocumentsFile		 AS tdf		WITH (NOLOCK)
				ON	tdf.comp_id		= tct.comp_id AND
					tdf.df_id		= tct.df_id


			INNER JOIN tbCustomer				tc		WITH(NOLOCK)
			ON	tc.comp_id		= tct.comp_id	AND
				tc.cust_id		= tct.cust_id

		WHERE	tdsh.comp_id	= @comp_id		AND
				tdsh.ds_id		= @ds_id		AND
			   (tct.state_id	= 54024 OR @OnlyCOT4State = 'False')
			   --(tc.state_id		= 54024 OR @OnlyCOT4State = 'False')


	OPEN DocumentsHeader_Cursor

	FETCH NEXT FROM DocumentsHeader_Cursor
	INTO
		@emissionDate,

		@ds_ct_transaction,

		@arba_cot_Fecha_Hora_Salida_Transporte,

		@esConsumidorFinal,

		@arba_cot_SUJETO_GENERADOR_IsDestiny,

		@arba_cot_ORIGEN_CUIT,
		@arba_cot_ORIGEN_RAZON_SOCIAL,
		@arba_cot_EMISOR_TENEDOR,

		@arba_cot_ORIGEN_DOMICILIO_CALLE,
		@arba_cot_ORIGEN_DOMICILIO_NUMERO,
		@arba_cot_ORIGEN_DOMICILIO_COMPLE,
		@arba_cot_ORIGEN_DOMICILIO_PISO,
		@arba_cot_ORIGEN_DOMICILIO_DTO,
		@arba_cot_ORIGEN_DOMICILIO_BARRIO,
		@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
		@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
		@arba_cot_ORIGEN_DOMICILIO_PROVINCIA, --Dario 16/10/2018

		@arba_cot_TIPO_RECORRIDO,
		@arba_cot_RECORRIDO_LOCALIDAD,
		@arba_cot_RECORRIDO_CALLE,
		@arba_cot_RECORRIDO_RUTA,

		@arba_cot_PATENTE_VEHICULO,
		@arba_cot_PATENTE_ACOPLADO,
		@arba_cot_Counter,
		@TRANSPORTISTA_CUIT,
		@IMPORTE,
		@state_id

		WHILE @@FETCH_STATUS = 0
			BEGIN



				-- ----------------------------------------------------------------------------------------------------------------
				-- PARA VER SI TIENE ARTICULOS EN EL CT_TRANSACTION O TENGO QUE IR A BUSCARLO A "ct_transaction_packinglist"
				-- ----------------------------------------------------------------------------------------------------------------
				DECLARE
					@lCT_TRANSACTION	INT

				IF (SELECT COUNT(*)
				    FROM tbCommercialTransactions						tct	WITH(NOLOCK)
						INNER JOIN tbItemTransactions					tit	WITH(NOLOCK)
						ON	tit.comp_id			= tct.comp_id			AND
							tit.ct_transaction	= tct.ct_transaction
				    WHERE	tct.comp_id			= @comp_id				AND
							tct.ct_transaction	= @ds_ct_transaction	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1
					) = 0

					BEGIN

						--SI ES UN REMITO Y NO TIENE ARTÍCULOS LE ASIGNA EL PACKINK_LIST
						SELECT
							@lCT_TRANSACTION		= tct.ct_transaction_PackingList
						  FROM tbCommercialTransactions						tct
						WHERE	tct.comp_id			= @comp_id				AND
								tct.ct_transaction	= @ds_ct_transaction
					END


				ELSE
					BEGIN
						--SINO, SETEA EL MISMO CT_TRANSACTION
						SET @lCT_TRANSACTION = @ds_ct_transaction
					END


--==
--SELECT '@lCT_TRANSACTION:', @lCT_TRANSACTION
--==

				-- ----------------------------------------------------------------------------------------------------------------

				--ARMAMOS EL CODIGO_UNICO

				DECLARE
					@CODIGO_UNICO	VARCHAR(16)
				DECLARE @strDeliveryAddress AS NVARCHAR(4000)



				SELECT @strDeliveryAddress =
												CASE
													WHEN ctn.ctn_deliveryAddressOfSaleOrder IS NOT NULL AND
														 ctn.ctn_deliveryAddressOfSaleOrder <> ''		THEN ctn.ctn_deliveryAddressOfSaleOrder
													WHEN tcf.comp_id IS NOT NULL						THEN tcf.custf_address
													WHEN tcb.comp_id IS NOT NULL						THEN tcb.custb_address
													WHEN ISNULL(cust.cust_address4Delivery,'') <> ''	THEN cust.cust_address4Delivery
													ELSE													 cust.cust_address
												END
					FROM tbCommercialTransactions CT

					LEFT join dbo.tbCommercialTransactionNotes		CTN
					on	CTN.comp_id				= CT.comp_id
					and	CTN.bra_id				= CT.bra_id
					and CTN.ct_transaction		= CT.ct_transaction


					LEFT join dbo.tbCustomer						cust
					on  cust.comp_id				= ct.comp_id AND
						cust.cust_id				= ct.cust_id


					LEFT JOIN tbCustomerFamily tcf
						ON	tcf.comp_id		= ct.comp_id AND
							tcf.cust_id		= ct.cust_id AND
							tcf.custf_id	= ct.custf_id

					LEFT JOIN tbCustomerBranch tcb
						ON		tcb.comp_id = ct.comp_id
							AND tcb.cust_id = ct.cust_id
							AND tcb.cb_id	= ct.cb_id

					WHERE	CT.comp_id			= @comp_id AND
							CT.ct_transaction	= @ds_ct_transaction



				SELECT
					@CODIGO_UNICO = CASE
										WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '091'
										WHEN tct.sd_id = 2						    THEN '094'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '001'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '006'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '011'
										WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '051'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '060'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '061'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '093'
										WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '058'

										ELSE										    '099'
									END

										/*'91 R'*/ + '' +
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 5,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]		NEW de 4 a 5
					--@CODIGO_UNICO = CASE
					--					WHEN tct.sd_id = 2  AND tct.ct_kindOf = 'R' THEN '91 R'
					--					WHEN tct.sd_id = 2						    THEN '94 X'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'A' THEN '01 A'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'B' THEN '06 B'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'C' THEN '92 C'
					--					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'M' THEN '51 M'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'A' THEN '60 A'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'B' THEN '61 B'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'C' THEN '93 C'
					--					WHEN tct.sd_id = 31 AND tct.ct_kindOf = 'M' THEN '58 M'

					--					ELSE										    '97 E'
					--				END

					--					/*'91 R'*/ + '' +
					--dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_pointOfSale, 4,'0')				+ '' +				--[PREFIJO_PUNTODEVENTA]
					dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_docNumber, 8,'0')									--[NUMERO_DOCNUMBER]

					FROM tbCommercialTransactions tct

					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction --@lCT_TRANSACTION

				-- ----------------------------------------------------------------------------------------------------------------


				--OBTENEMOS LOS DATOS DEL CLIENTE
				DECLARE @lcust_id	INT
				SELECT @lcust_id = tct.cust_id
					FROM tbCommercialTransactions tct		WITH (NOLOCK)
					WHERE	tct.comp_id			= @comp_id AND
							tct.ct_transaction	= @ds_ct_transaction


				-- Se usa para el caso de Entregar a un transporte en el que la mercaderia sale de nuestra empresa pero el
				-- destino NO es el cliente sino que es el transporte.
				IF @arba_cot_cust_id_alternativeDestiny IS NOT NULL
					BEGIN
						SET @lcust_id = @arba_cot_cust_id_alternativeDestiny
					END



				DECLARE
					@DESTINATARIO_TIPO_DOCUMENTO		VARCHAR(3),
					@DESTINATARIO_DOCUMENTO				VARCHAR(11),
					@DESTINATARIO_CUIT					VARCHAR(11),
					@DESTINATARIO_RAZON_SOCIAL			VARCHAR(50),
					@DESTINATARIO_TENEDOR				BIT,
					@DESTINO_DOMICILIO_CALLE			VARCHAR(40),
					@DESTINO_DOMICILIO_NUMERO			VARCHAR(5),
					@DESTINO_DOMICILIO_COMPLE			VARCHAR(5),
					@DESTINO_DOMICILIO_PISO				VARCHAR(3),
					@DESTINO_DOMICILIO_DTO				VARCHAR(4),
					@DESTINO_DOMICILIO_BARRIO			VARCHAR(30),
					@DESTINO_DOMICILIO_CODIGOP			VARCHAR(8),
					@DESTINO_DOMICILIO_LOCALIDAD		VARCHAR(50),
					@DESTINO_DOMICILIO_PROVINCIA		VARCHAR(1),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	VARCHAR(50)

				-- *************************************************************************************
				-- SEPARAMOS EL NUMERO DE LA DIRECCION
				-- NOTA: SEPARA TODOS LOS NUMEROS, POR ENDE SI LA DIRECCION ES '25 de Mayo 3323'
				--       EL RESULTADO SERA '253323' <-- TODOS LOS NUMEROS CONCATENADOS
				--       DE MOMENTO NO HAY UNA SOLUCION MEJOR
				-- *************************************************************************************
				DECLARE @thestring VARCHAR(50)
				SET @thestring = @strDeliveryAddress --(SELECT tc.cust_address FROM tbCustomer tc WHERE tc.comp_id = @comp_id AND tc.cust_id = @lcust_id)
				DECLARE @final VARCHAR(50)
				SET @final = ''

				SELECT @final = @final + x.thenum
				FROM
				(
					SELECT SUBSTRING(@thestring, number, 1) AS thenum, number
					FROM master..spt_values
					WHERE substring(@thestring, number, 1) LIKE '[0-9]' AND TYPE='P'
				) x
				ORDER BY x.number
				DECLARE
					@DESTINO_DOMICILIO_NUMEROFINAL VARCHAR(5)
				SET @DESTINO_DOMICILIO_NUMEROFINAL = @final
				-- *************************************************************************************



				SELECT
					@DESTINATARIO_TIPO_DOCUMENTO		= ISNULL(ttnt.tnt_ARBACOT,' '),
					@DESTINATARIO_DOCUMENTO				= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_CUIT					= Replace(ISNULL(tc.cust_taxNumber,' '),'-',''),
					@DESTINATARIO_RAZON_SOCIAL			= ISNULL(tc.cust_name,' '),
					@DESTINATARIO_TENEDOR				= CASE @esConsumidorFinal
															  WHEN 1 THEN 0
															  ELSE        1
					                     				  END,	--SI ES CONSUMIDOR FINAL es CERO, SINO es 1
					@DESTINO_DOMICILIO_CALLE			= ISNULL(@strDeliveryAddress /*tc.cust_address*/,' '), --COMO SEPARO EL NUMERO DE LA CALLE PARA PONERLO ABAJO????
					@DESTINO_DOMICILIO_NUMERO			= ISNULL(@DESTINO_DOMICILIO_NUMEROFINAL,' '),
					@DESTINO_DOMICILIO_COMPLE			= 'S/N', --ISNULL(tc.cust_address,' '),
					@DESTINO_DOMICILIO_PISO				= ' ',
					@DESTINO_DOMICILIO_DTO				= ' ',
					@DESTINO_DOMICILIO_BARRIO			= ' ',
					@DESTINO_DOMICILIO_CODIGOP			= ISNULL(tc.cust_zip,' '),
					@DESTINO_DOMICILIO_LOCALIDAD		= ISNULL(tc.cust_city,' '),
					@DESTINO_DOMICILIO_PROVINCIA		= ISNULL(ts.state_arba_cot,' '),
					@PROPIO_DESTINO_DOMICILIO_CODIGO	= ' '

					FROM tbCustomer							tc
						INNER JOIN tbsysState				ts			WITH (NOLOCK)
							ON ts.state_id = @state_id
						--ON	ts.country_id	= tc.country_id AND
						--	ts.state_id		= tc.state_id

						INNER JOIN tbsysTaxNumberTypes		ttnt
						ON	ttnt.tnt_id		= tc.tnt_id

				WHERE	tc.comp_id = @comp_id AND
						tc.cust_id = @lcust_id



				SET @arba_cot_Fecha_Hora_Salida_Transporte = GETDATE()


				IF @DESTINATARIO_TIPO_DOCUMENTO = ''
					BEGIN
						SET @DESTINATARIO_DOCUMENTO	 = ''
					END

				IF @esConsumidorFinal = 1
					BEGIN
						set @DESTINATARIO_CUIT = ''
					END
				IF @esConsumidorFinal = 0
					BEGIN
						set @DESTINATARIO_TIPO_DOCUMENTO = ''
						set @DESTINATARIO_DOCUMENTO		 = ''
					END
				set @DESTINATARIO_CUIT = REPLACE(@DESTINATARIO_CUIT,'-','')

				if @DESTINO_DOMICILIO_COMPLE = 'S/N'
					BEGIN
						set @DESTINO_DOMICILIO_NUMERO = ''
					END


				--INSERTAMOS EL SEGUNDO REGISTRO CON LOS DATOS DEL TRANSPORTE Y DE A QUIEN SE LO ENVIAMOS
				--SELECT @lCT_TRANSACTION
				INSERT INTO @tblCOT
				(
					Record
				)
				SELECT
					@RecordType2																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @emissionDate, 111), '/',''),' ')							+ '|' +		--FECHA
					@CODIGO_UNICO																				+ '|' +
					ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 111), '/',''),' ')	+ '|' +		--FECHA
					substring(ISNULL(REPLACE(CONVERT(VARCHAR, @arba_cot_Fecha_Hora_Salida_Transporte, 108), ':',''),'    '),1,4)	+ '|' +		--HORA
					@arba_cot_SUJETO_GENERADOR_IsDestiny														+ '|' +		--SUJETO_GENERADOR E(emisor) D(destinatario)
					ISNULL(CONVERT(VARCHAR,@esConsumidorFinal),' ')												+ '|' +
					ISNULL(@DESTINATARIO_TIPO_DOCUMENTO,' ')													+ '|' +
					ISNULL(@DESTINATARIO_DOCUMENTO,' ')															+ '|' +
					ISNULL(@DESTINATARIO_CUIT,' ')																+ '|' +
					ISNULL(@DESTINATARIO_RAZON_SOCIAL,' ')														+ '|' +
					ISNULL(CONVERT(VARCHAR,@DESTINATARIO_TENEDOR),' ')											+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CALLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_NUMERO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_COMPLE,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PISO,' ')															+ '|' +
					ISNULL(@DESTINO_DOMICILIO_DTO	,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_BARRIO,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_CODIGOP,' ')														+ '|' +
					ISNULL(@DESTINO_DOMICILIO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@DESTINO_DOMICILIO_PROVINCIA,' ')													+ '|' +
					ISNULL(@PROPIO_DESTINO_DOMICILIO_CODIGO,' ')												+ '|' +
					'NO'																						+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					ISNULL(@arba_cot_ORIGEN_CUIT,' ')															+ '|' +
					ISNULL(@arba_cot_ORIGEN_RAZON_SOCIAL,' ')													+ '|' +
					ISNULL(CONVERT(VARCHAR,@arba_cot_EMISOR_TENEDOR),' ')										+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_CALLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_NUMERO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_COMPLE,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PISO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_DTO,' ')													+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_BARRIO,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMILILIO_CODIGOP,' ')												+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,' ')											+ '|' +
					ISNULL(@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,' ')													+ '|' + --Dario 16/10/2018
					@TRANSPORTISTA_CUIT																			+ '|' +		--TAX_NUMBER de DELIVERY
					ISNULL(@arba_cot_TIPO_RECORRIDO	,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_LOCALIDAD,' ')													+ '|' +
					ISNULL(@arba_cot_RECORRIDO_CALLE,' ')														+ '|' +
					ISNULL(@arba_cot_RECORRIDO_RUTA,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_VEHICULO,' ')														+ '|' +
					ISNULL(@arba_cot_PATENTE_ACOPLADO,' ')														+ '|' +
					'0'																							+ '|' +		--AGREGAR COMO CAMPO EN LA TABLA
					dbo.fnSIAP_ConvertDecimal2String(CONVERT(VARCHAR,@IMPORTE), 10)												--IMPORTE


				-- ---------------------------------------------------------------------------------------------------------------
				-- CURSOR DE PROCESAMIENTO DE ARTÍCULOS DE CADA REMITO
				-- ---------------------------------------------------------------------------------------------------------------

				DECLARE
					@arbaCOT_Nomenclador	VARCHAR(15),
					@item_measureARBA		VARCHAR(15),
					@qty					INT,
					@item_code				VARCHAR(25),
					@item_desc				VARCHAR(40),
					@item_measure			VARCHAR(20)




				DECLARE DocumentItemsDetail_Cursor CURSOR FOR

					--ACA VA EL SELECT
					SELECT
						ISNULL(ti.arbaCOT_Nomenclador,' '),
						ISNULL(tamu.cot_um_id,' '),
						ISNULL(tit.it_qty,' '),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_code,' '),25),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(ti.item_desc,' '),40),
						dbo.fnSIAP_ConvertString2FIXLength(ISNULL(tmu.mu_shortDesc,' '),20)


					FROM tbItemTransactions							tit		WITH(NOLOCK)
						INNER JOIN tbItem							ti		WITH(NOLOCK)
						ON  ti.comp_id			= tit.comp_id		AND
							ti.item_id			= tit.item_id
						LEFT JOIN tbMetricUnits						tmu		WITH(NOLOCK)
						ON	tmu.comp_id			= ti.comp_id		AND
							tmu.mu_id			= ti.mu_id
						INNER JOIN tbsysARBACOT_MetricUnit			tamu	WITH(NOLOCK)
						ON	tamu.cot_um_id		= tmu.cot_um_id


					WHERE	tit.comp_id			= @comp_id			AND
							--tit.bra_id			= @bra_id			AND
							tit.ct_transaction	= @lCT_TRANSACTION	AND
							CASE
								WHEN @intMode = 2 AND tit.sdlmt_id = 2	THEN 1
								WHEN @intMode <> 2						THEN 1
								ELSE 0
							END	= 1									AND
							IsNull(ti.arbaCOT_Nomenclador,'') <> ''


				OPEN DocumentItemsDetail_Cursor
				FETCH NEXT FROM DocumentItemsDetail_Cursor
				INTO
					@arbaCOT_Nomenclador,
					@item_measureARBA,
					@qty,
					@item_code,
					@item_desc,
					@item_measure

				WHILE @@FETCH_STATUS = 0
					BEGIN


						INSERT INTO @tblCOT
						(
							Record
						)
						SELECT
							@RecordType3															+ '|' +
							@arbaCOT_Nomenclador													+ '|' +
							@item_measureARBA														+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	+ '|' +
							CONVERT(VARCHAR,@item_code)												+ '|' +
							CONVERT(VARCHAR,@item_desc)												+ '|' +
							CONVERT(VARCHAR,@item_measure)											+ '|' +
							dbo.fnSIAP_ConvertDecimal2String(@qty, 15)	--CONVERTIMOS A VARCHAR PARA PODER CONCATENARLO



						FETCH NEXT FROM DocumentItemsDetail_Cursor
						INTO
							@arbaCOT_Nomenclador,
							@item_measureARBA,
							@qty,
							@item_code,
							@item_desc,
							@item_measure

					END



				CLOSE DocumentItemsDetail_Cursor
				DEALLOCATE DocumentItemsDetail_Cursor

				-- ---------------------------------------------------------------------------------------------------------------


				FETCH NEXT FROM DocumentsHeader_Cursor
				INTO
					@emissionDate,

					@ds_ct_transaction,

					@arba_cot_Fecha_Hora_Salida_Transporte,

					@esConsumidorFinal,

					@arba_cot_SUJETO_GENERADOR_IsDestiny,

					@arba_cot_ORIGEN_CUIT,
					@arba_cot_ORIGEN_RAZON_SOCIAL,
					@arba_cot_EMISOR_TENEDOR,

					@arba_cot_ORIGEN_DOMICILIO_CALLE,
					@arba_cot_ORIGEN_DOMICILIO_NUMERO,
					@arba_cot_ORIGEN_DOMICILIO_COMPLE,
					@arba_cot_ORIGEN_DOMICILIO_PISO,
					@arba_cot_ORIGEN_DOMICILIO_DTO,
					@arba_cot_ORIGEN_DOMICILIO_BARRIO,
					@arba_cot_ORIGEN_DOMILILIO_CODIGOP,
					@arba_cot_ORIGEN_DOMICILIO_LOCALIDAD,
					@arba_cot_ORIGEN_DOMICILIO_PROVINCIA,  --Dario 16/10/2018

					@arba_cot_TIPO_RECORRIDO,
					@arba_cot_RECORRIDO_LOCALIDAD,
					@arba_cot_RECORRIDO_CALLE,
					@arba_cot_RECORRIDO_RUTA,

					@arba_cot_PATENTE_VEHICULO,
					@arba_cot_PATENTE_ACOPLADO,
					@arba_cot_Counter,
					@TRANSPORTISTA_CUIT,
					@IMPORTE,
					@state_id

			END

		CLOSE DocumentsHeader_Cursor
	DEALLOCATE DocumentsHeader_Cursor

	--INSERTAMOS EL CUARTO REGISTRO
	INSERT INTO @tblCOT
	(
		Record
	)
	SELECT
		@RecordType4							+ '|' +
		CONVERT(VARCHAR,@lIntDocumentCounter)


	SELECT @fileName
	SELECT tmp.Record  FROM @tblCOT tmp ORDER BY tmp.intOrder

END
--1
GO







CREATE PROCEDURE [dbo].[spSysExportData_GetData]
(
	@comp_id			Int,
	@lang_id			INT,
	@bra_id				Int,
	@sed_id				Int,
	@date_from			Datetime,
	@date_to			DATETIME,
	@tax_toGenerate     INT,
	@brag_id			INT
)
AS


BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
	/*
	DECLARE		@comp_id			Int,
				@lang_id			INT,
				@bra_id				Int,
				@sed_id				Int,
				@date_from			Datetime,
				@date_to			Datetime,
				@tax_toGenerate     INT,
				@brag_id			INT

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@bra_id				=1,
				@sed_id				=114,
				@date_from			=GETDATE() - 100,
				@date_to			=GETDATE() + 100,
				@tax_toGenerate     =-1,
				@brag_id			=-1

	*/
-- --------------------------------------------------------------------


	Declare
			@sp		Varchar(200),
			@id_sed INT

	Select
		   @sp     = ted.sed_sp,
		   @id_sed = ted.sed_id

	FROM tbsysExportData ted
	Where ted.sed_id = @sed_id


	--Execute @sp @comp_id, @lang_id, @bra_id, @date_from, @date_to


--	-- Si el id es 111 'ARCIBA y ARBA Vtas' Ejecuta con un parametro mas @tax_togenerate
--	IF @id_sed = 111
--
--		BEGIN
--			-- Ejecuta store ARCIBA
--				Execute @sp @comp_id, @lang_id, @bra_id, @date_from, @date_to,@tax_toGenerate
--		END
--
--	ELSE IF @id_sed = 112
--		BEGIN
--				Execute @sp @comp_id, @lang_id, @bra_id, @date_from, @date_to,@tax_toGenerate,@brag_id
--		END
--
--	ELSE IF @id_sed = 115 OR @id_sed = 116 OR @id_sed = 100
--		BEGIN
--			-- Ejecuta store de SIAP - SI.FE.RE. Retenciones Percibidas  (Cobranzas) - spSysExportData_getSIFERE_Retenciones
--			-- Ejecuta store de SIAP - SI.FE.RE. Percepciones Percibidas  (Compras) - spSysExportData_getSIFERE_Percepciones
--			-- Ejecuta con un parametro mas @brag_id
--			Execute @sp @comp_id, @lang_id, @bra_id, @date_from, @date_to,@brag_id
--		END
--
--	ELSE
--		BEGIN
--			-- Ejecuta Otro store
--			Execute @sp @comp_id, @lang_id, @bra_id, @date_from, @date_to
--		END




--		100	SIAP - C.I.T.I. Ventas V1	spSysExportData_getCITIVentas
--		111	ARCIBA	spSysExportData_getARCIBA
--		112	SIAP - ARBA - Percepciones I.Brutos por Ventas	spSysExportData_getARBAPercepciones
--		113	SIAP - ARBA - Retenciones I.Brutos por Pagos	spSysExportData_getARBA_Retenciones
--		114	SIAP - C.I.T.I. Compras V4	spSysExportData_getCITICompras
--		115	SIAP - SI.FE.RE. Retenciones Percibidas  (Cobranzas)	spSysExportData_getSIFERE_Retenciones
--		116	SIAP - SI.FE.RE. Percepciones Percibidas  (Compras)	spSysExportData_getSIFERE_Percepciones
--      122 Argentina: WEB ARBA - Percepciones I.Brutos por Ventas V2 (Quincenal)
	IF @id_sed = 111 OR @id_sed = 112 OR @id_sed = 119 OR @id_sed = 129 OR @id_sed = 120 OR @id_sed = 122
		BEGIN
				Execute @sp @comp_id, @lang_id, @bra_id, @date_from, @date_to,@tax_toGenerate,@brag_id
		END
	ELSE
		BEGIN
			-- Ejecuta Otro stores
			-- sed_id = 113 114 115 116 100
			Execute @sp @comp_id, @lang_id, @bra_id, @date_from, @date_to,@brag_id
		END






END
GO





create PROCEDURE [dbo].[spSysExportData_GetDataById]
(
	@comp_id			Int,
	@lang_id			INT,
	@bra_id				Int,
	@sed_id				Int
)
AS

BEGIN



	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
	/*
	DECLARE		@comp_id			Int,
				@lang_id			INT,
				@bra_id				Int,
				@sed_id				Int

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@bra_id				=1,
				@sed_id				=114

*/
-- --------------------------------------------------------------------



SELECT  ted.country_id			[country_id],
		ted.sed_id				[sed_id],
		ted.sed_desc			[sed_desc],
		ted.sed_sp				[sed_sp],
		ted.sed_appl			[sed_appl],
		isnull(ted.sed_help,'') [sed_help]

FROM tbsysExportData								ted

WHERE ted.sed_id = @sed_id




END
GO





