	-- Borro las pruebas o cosas raras menores a 5 centavos
	DELETE FROM @tmpData WHERE abs(xx_total) < 0.05



	-- Genera Tabla temporal con IVAS para reemplazar la tbTaxMovements
	SELECT	ttm.comp_id,
			ttm.ct_transaction,
			SUM(Round(isnull(ttm.tm_subtotal,0),2))	[tm_subtotal],
			CASE
				WHEN tct.sd_id      = 142	THEN tt.strcv_value -- Liquidacion de T. Credito   01-2019
				WHEN tct.sd_id      = 141	THEN tt.strcv_value
				WHEN tct.sd_id      = 140	THEN tt.strcv_value
				when ttm.percentaje = 0		THEN '0003'
				WHEN ttm.tm_total   = 0		THEN '0003'
				ELSE tt.strcv_value
			END										[tmpAlicuota],
			ttn.tax_percentage						[taxPer],				 --**99
			SUM(Round(isnull(ttm.tm_Total,0),2))	[tm_Total],
			ISNULL(ttn.tax_TaxEngineColumn4ThisTaxIsNoGravado,'False')		[tax_TaxEngineColumn4ThisTaxIsNoGravado]	-- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021
		INTO #tbTaxMovements_tmp1
		FROM tbTaxMovements ttm								WITH (NOLOCK)
		INNER JOIN @tmpData tmp
		ON	tmp.comp_id			= ttm.comp_id AND
			tmp.ct_transaction	= ttm.ct_transaction
		INNER JOIN tbcommercialtransactions tct				WITH (NOLOCK)
			ON	tct.comp_id			= tmp.comp_id AND
				tct.ct_transaction	= tmp.ct_transaction
		INNER JOIN tbTaxName ttn							WITH (NOLOCK)
			ON	ttn.comp_id		= ttm.comp_id and
				ttn.tax_id		= ttm.tax_id  AND
				ttn.tax_class	= 1	-- Solo IVA
		INNER JOIN tbsysSIAP_RG3685V_AlicuotaCode tt
			ON tt.strcv_id = ttn.strcv_id
		GROUP BY ttm.comp_id,ttm.ct_transaction,ttm.percentaje,tt.strcv_value,ttm.tm_total,ttn.tax_percentage,tct.sd_id,ttn.tax_TaxEngineColumn4ThisTaxIsNoGravado

