	-- Pone el NETO para los impuestos del tipo IVA de las liquidaciones de Tarjetas de Crédito
	UPDATE		#tbTaxMovements_tmp1										--**99
		SET		tm_subtotal = tm_Total * 100 / dbo.fnNoZDiv(tmp.taxPer)
		FROM	#tbTaxMovements_tmp1 tmp
		INNER JOIN tbCommercialTransactions tct				WITH (NOLOCK)
			ON	tmp.comp_id			= tct.comp_id			AND
				tmp.ct_transaction  = tct.ct_transaction
		WHERE tct.sd_id = 142 OR tct.sd_id = 141 OR tct.sd_id = 140



	DELETE #tbTaxMovements_tmp1
		FROM #tbTaxMovements_tmp1 tmp
		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
			ON	tct.comp_id			= tmp.comp_id AND
				tct.ct_transaction	= tmp.ct_transaction
		--INNER JOIN tbSupplier ts
