		--		(ts.supp_id = tct.supp_id OR ts.supp_id = tct.supp_id4CreditCardLiquidation)  --ts.supp_id = tct.supp_id			***999
		WHERE   tmp.tmpAlicuota = '0003' AND
			   (
			   		tct.ct_kindOf = 'C'
			   			OR
			   		tct.ct_kindOf = 'B'
			   )


	-- -------------------------------------------------
