							)

	UPDATE @tmpData
		SET decSUMOfTaxesIVA0	= SumOfTaxes,
			decSUMOfNetoIVA0	= SumOfNeto,
			decForce2NoGravado	=	ISNULL(decForce2NoGravado,0) + -- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021
									CASE
										WHEN tmp1.tax_TaxEngineColumn4ThisTaxIsNoGravado = 1 THEN 	SumOfNeto
										ELSE 0
									END
		FROM @tmpData tmp
		INNER JOIN tmpSumTaxes2 tmp1
			ON	tmp1.comp_id		= tmp.comp_id AND
				tmp1.ct_transaction = tmp.ct_transaction
