	-- -------------------------------------------------
	;WITH tmpUpdate4Municipal AS (	SELECT	tmp.ct_transaction,
										SUM(ttm.tm_total)		[ImpuestoMunicipal]
									FROM @tmpData tmp
									INNER JOIN tbCommercialTransactions tct
										ON	tct.comp_id				= tmp.comp_id AND
