									INNER JOIN tbTaxMovements ttm
										ON ttm.ct_transaction		= tmp.ct_transaction
	                        		INNER JOIN tbtaxname ttn
	                        			ON	ttn.tax_id				= ttm.tax_id AND
	                        				ttn.comp_id				= ttm.comp_id
	                        		WHERE ttn.tax_class = 183 -- Impuestos Minicipales
									GROUP BY tmp.ct_transaction
						)
	UPDATE @tmpData
		SET decPercMUN = tmp2.ImpuestoMunicipal
