	--UPDATE @tmpData
	--	SET decSUMOfIVATaxes = tmp1.IVA
	--	FROM @tmpData tmp
	--	INNER JOIN tmpSumOfIvaTax tmp1
	--		ON	tmp1.comp_id		= tmp.comp_id AND
	--			tmp1.ct_transaction = tmp.ct_transaction
	---- -------------------------------------------------


	-- -------------------------------------------------
	-- Pone Importe TOTAL de IVA
	-- -------------------------------------------------
	;WITH tmpSumOfIvaTax AS (	SELECT	tmp1.comp_id,
										tmp1.ct_transaction,
										SUM(tmp1.tm_total)	    [IVA],
										SUM(tmp1.tm_subtotal)   [NETO]
									FROM @tmpData tmp
									INNER JOIN #tbTaxMovements_tmp1 tmp1
										ON	tmp1.comp_id		= tmp.comp_id AND
											tmp1.ct_transaction = tmp.ct_transaction
									GROUP BY
											tmp1.comp_id,
											tmp1.ct_transaction
							)


	UPDATE @tmpData
		SET decSUMOfIVATaxes = tmp1.IVA,
		    decSumOfIVANeto  = tmp1.NETO
		FROM @tmpData tmp
		INNER JOIN tmpSumOfIvaTax tmp1									WITH (NOLOCK)
			ON	tmp1.comp_id		= tmp.comp_id AND
				tmp1.ct_transaction = tmp.ct_transaction
	-- -------------------------------------------------



	-- -------------------------------------------------
	-- Importes que NO integran el Neto Gravado y Exento
	-- -------------------------------------------------
	;WITH tmpUpdate4NOTax AS (	SELECT	tmp.ct_transaction,
										tct.ct_total,
										tct.ct_subtotal,
										tct.ct_discount,
										SUM(	CASE
													WHEN ttm.percentaje <> 0 THEN	ttm.tm_subtotal
													ELSE							0
												END )											[ImporteGravado],
										SUM(	CASE
													WHEN ttm.percentaje = 0 THEN	ttm.tm_subtotal
													ELSE							0
												END )											[ImporteExento]
									FROM @tmpData tmp
									INNER JOIN tbCommercialTransactions tct
										ON	tct.comp_id				= tmp.comp_id AND
											tct.ct_transaction		= tmp.ct_transaction
									INNER JOIN tbTaxMovements ttm
										ON	ttm.comp_id				= tmp.comp_id			AND
											ttm.ct_transaction		= tmp.ct_transaction
									INNER JOIN tbTaxName ttn
										ON	ttn.comp_id = ttm.comp_id	AND
											ttn.tax_id	= ttm.tax_id	AND
											ttn.tax_class = 1 -- Solo IVA
									--INNER JOIN  vwTaxMovements_IVATax vtmti
									--	ON	vtmti.comp_id			= ttm.comp_id			AND
									--		vtmti.bra_id			= ttm.bra_id			AND
									--		vtmti.tm_transaction	= ttm.tm_transaction
									GROUP BY tmp.ct_transaction,ttm.ct_transaction,tct.ct_subtotal,tct.ct_discount,tct.ct_total
						)
	UPDATE @tmpData
		SET decNoGravado =	tmp2.ct_total
							-
							(tmp2.ImporteGravado + tmp2.ImporteExento + tmp.decSUMOfIVATaxes + tmp.decPerNoCat + tmp.decPercNac + tmp.decPercIVA + tmp.decPercIIBB + tmp.decPercMUN + tmp.decImpInternos),
			decExento	 = tmp2.ImporteExento

		FROM @tmpData tmp
		INNER JOIN tmpUpdate4NOTax tmp2
			ON tmp2.ct_transaction = tmp.ct_transaction
	-- -------------------------------------------------


	-- -------------------------------------------------
	-- Ahora saca de EXENTO (IVA 0 % ) el total de neto
	-- -------------------------------------------------
	UPDATE @tmpData
		SET decExento = (decExento - decSUMOfNetoIVA0)
	-- -------------------------------------------------


	-- -- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021
	UPDATE @tmpData SET decForce2NoGravado	= ISNULL(decForce2NoGravado,0)
	UPDATE @tmpData SET decNoGravado		= ISNULL(decNoGravado,0)		+ decForce2NoGravado WHERE decForce2NoGravado <> 0
	UPDATE @tmpData SET decSumOfIVANeto		= decSumOfIVANeto				- decForce2NoGravado WHERE decForce2NoGravado <> 0



	-- Si la factura era muy chica no se calcula IVA por lo que se los pone como EXENTOS
	UPDATE @tmpdata
		SET decExento = tct.ct_total
		FROM @tmpData tmp
		INNER JOIN tbCommercialTransactions tct
			ON	tct.comp_id			= tmp.comp_id AND
				tct.ct_transaction	= tmp.ct_transaction
		WHERE tct.ct_taxes = 0 AND abs(tct.ct_total) < 1




	UPDATE @tmpdata
		SET decExento = 0
		FROM @tmpData tmp
		INNER JOIN tbCommercialTransactions tct
			ON	tct.comp_id			= tmp.comp_id AND
				tct.ct_transaction	= tmp.ct_transaction
		WHERE tct.ct_kindOf = 'B' OR tct.ct_kindOf = 'C'



	-- Modificacion  3/4/2017
	UPDATE @tmpdata SET decCredFisComput = decSUMOfIVATaxes




	-- ---------------------------------------------------------------------------------------------------------
	-- Para los ENFERMOS HDP que cargan mierda y ponen comprobantes A,E o M sin IVAS del 0% aunque sea,
	-- lo agrega sino explota y despues se quejan como nenas mariconas.!
	-- ---------------------------------------------------------------------------------------------------------
	INSERT INTO #tbTaxMovements_tmp1 (
										comp_id,ct_transaction,[tm_subtotal],[tmpAlicuota],	[tm_Total],tax_TaxEngineColumn4ThisTaxIsNoGravado		-- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021
									 )
				SELECT DISTINCT
						ttm.comp_id,
						ttm.ct_transaction,
						tct.ct_subtotal						    [tm_subtotal],
						'0003'									[tmpAlicuota],
						0										[tm_Total],
						'False'		-- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021

					FROM @tmpData ttm
					INNER JOIN tbCommercialTransactions	tct
						on	tct.comp_id			= @comp_id and
							tct.ct_transaction	= ttm.ct_transaction
					INNER JOIN tbTaxName ttn
						ON	ttn.comp_id		= ttm.comp_id and
							ttn.tax_class	= 1			  AND -- Solo IVA
							ttn.strcv_id	= 3				  -- IVA 0 %
					INNER JOIN tbsysSIAP_RG3685V_AlicuotaCode tt
						ON tt.strcv_id = ttn.strcv_id
					WHERE  'AEM' like '%' +  tct.ct_kindOf  + '%'	AND
							ttm.intIVAQty = 0						AND
							NOT EXISTS (	-- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021*
											SELECT TOP 1 1
												FROM @tmpData AS td
												WHERE td.ct_transaction = tct.ct_transaction	AND
													  td.xx_total		= td.decForce2NoGravado
									  )

	update @tmpData
		set intIVAQty = 1
		FROM @tmpData ttm
		INNER JOIN tbCommercialTransactions	tct
			on	tct.comp_id			= @comp_id and
				tct.ct_transaction	= ttm.ct_transaction
		INNER JOIN tbTaxName ttn
			ON	ttn.comp_id		= ttm.comp_id and
				ttn.tax_class	= 1			  AND -- Solo IVA
				ttn.strcv_id	= 3				  -- IVA 0 %
		INNER JOIN tbsysSIAP_RG3685V_AlicuotaCode tt
			ON tt.strcv_id = ttn.strcv_id
		where  'AEM' like '%' +  tct.ct_kindOf  + '%'  AND
				ttm.intIVAQty = 0	AND
				NOT EXISTS (	-- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021*
								SELECT TOP 1 1
									FROM @tmpData AS td
									WHERE td.ct_transaction = tct.ct_transaction	AND
										  td.xx_total		= td.decForce2NoGravado
							)

	-- ---------------------------------------------------------------------------------------------------------


	-- ---------------------------------------------------------------------------------------------------------
	-- 99
	-- Pone en el TOTAL de las liquidaciones de T.Credito el importe correspondiente a la suma de los netos mas impuestos.
	-- ---------------------------------------------------------------------------------------------------------
	-- MOS 12-2022: Informado x Cemsi

	UPDATE @tmpdata
		SET xx_total =	--ISNULL(tmp.decNoGravado,0) +	 MOS 10-2021 x MF
						--ISNULL(tmp.decNoGravado,0) +   CEMSI 12-2022
						ISNULL(tmp.decPerNoCat,0) +
						ISNULL(tmp.decExento,0) +
						ISNULL(tmp.decPercNac,0) +
						ISNULL(tmp.decPercIVA,0) +
						ISNULL(tmp.decPercIIBB,0) +
						ISNULL(tmp.decPercMUN,0) +
						ISNULL(tmp.decImpInternos,0) +
						ISNULL(tmp.decOtrosTrib,0) +
						--ISNULL(tmp.decCredFisComput,0)  +
						ISNULL(tmp.decSUMOfNetoIVA0,0)	+
						ISNULL(tmp.decSUMOfIVATaxes,0)
						,decNoGravado = 0

		FROM @tmpData tmp
		INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
			ON	tct.comp_id			= tmp.comp_id			AND
				tct.ct_transaction	= tmp.ct_transaction	AND
				(tct.sd_id = 142 OR tct.sd_id = 141 OR tct.sd_id = 140)

	--UPDATE @tmpdata
	--	SET xx_total =	--ISNULL(tmp.decNoGravado,0) +	 MOS 10-2021 x MF
	--					ISNULL(tmp.decNoGravado,0) +
	--					ISNULL(tmp.decPerNoCat,0) +
	--					ISNULL(tmp.decExento,0) +
	--					ISNULL(tmp.decPercNac,0) +
	--					ISNULL(tmp.decPercIVA,0) +
	--					ISNULL(tmp.decPercIIBB,0) +
	--					ISNULL(tmp.decPercMUN,0) +
	--					ISNULL(tmp.decImpInternos,0) +
	--					ISNULL(tmp.decOtrosTrib,0) +
	--					ISNULL(tmp.decCredFisComput,0)  +
	--					ISNULL(tmp.decSUMOfNetoIVA0,0)
	--	FROM @tmpData tmp
	--	INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
	--		ON	tct.comp_id			= tmp.comp_id			AND
	--			tct.ct_transaction	= tmp.ct_transaction	AND
	--			(tct.sd_id = 142 OR tct.sd_id = 141 OR tct.sd_id = 140)

	-- ---------------------------------------------------------------------------------------------------------

	----99
	---- Pone en el TOTAL de las liquidaciones de T.Credito el importe correspondiente a la suma de los netos mas impuestos.
	--UPDATE @tmpdata
	--	SET xx_total =	--ISNULL(tmp.decNoGravado,0) +   MOS 10-2021 x MF
	--					ISNULL(tmp.decNoGravado,0) +
	--					ISNULL(tmp.decPerNoCat,0) +
	--					ISNULL(tmp.decExento,0) +
	--					ISNULL(tmp.decPercNac,0) +
	--					ISNULL(tmp.decPercIVA,0) +
	--					ISNULL(tmp.decPercIIBB,0) +
	--					ISNULL(tmp.decPercMUN,0) +
	--					ISNULL(tmp.decImpInternos,0) +
	--					ISNULL(tmp.decOtrosTrib,0) +
	--					ISNULL(tmp.decCredFisComput,0)  +
	--					ISNULL(tmp.decSUMOfNetoIVA0,0)
	--	FROM @tmpData tmp
	--	INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
	--		ON	tct.comp_id			= tmp.comp_id			AND
	--			tct.ct_transaction	= tmp.ct_transaction	AND
	--			(tct.sd_id = 142 OR tct.sd_id = 141 OR tct.sd_id = 140)




	-- Borra TODOS los movimientos SIN IVA del extracto bancario
	DELETE FROM @tmpData
		FROM @tmpData tmp
		INNER JOIN tbCommercialTransactions tct WITH (NOLOCK)
			ON tct.ct_transaction = tmp.ct_transaction
		WHERE	tct.sd_id IN (140,141)					AND
				ISNULL(tmp.decSUMOfIVATaxes,0) = 0



	SELECT	/*01*/	dbo.fnSIAP_ConvertDate2StringAAAAMMDD(tct.ct_date, '') +
			/*02*/
					CASE


						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'A' AND tmp.intIVAQty = 0 THEN '006'
						--WHEN tct.sd_id = 101 AND dbo.fnStrAllTrim(tct.ct_kindOf = '')  AND tmp.intIVAQty = 0 THEN '006'

						-- Facturas
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'A' THEN '001'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'B' THEN '006'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'C' THEN '011'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'M' THEN '051'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'E' THEN '019'		-- ERROR


						-- Notas de Credito
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'A' THEN '003'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'B' THEN '008'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'C' THEN '013'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'M' THEN '053'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'E' THEN '021'		-- ERROR

						-- Notas de Debito
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'A' THEN '002'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'B' THEN '007'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'C' THEN '012'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'M' THEN '052'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'E' THEN '020'

						-- Liquido Producto
						WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'A' THEN '060'
						WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'B' THEN '061'
						WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'M' THEN '058'

						-- Despacho de Importacion
						WHEN tct.sd_id = 130						 THEN '066'


						-- Liquidación de Tarjetas de Crédito
						WHEN tct.sd_id = 142						 THEN '099'
						WHEN tct.sd_id = 141						 THEN '099'
						WHEN tct.sd_id = 140						 THEN '099'


						ELSE											'ERR'
					END +
			/*03*/	CASE
						WHEN tct.sd_id IN (101,103,104,131,142,141,140) AND tct.ct_pointOfSale = 0 THEN '00001'
						ELSE																dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(10),tct.ct_pointOfSale) , 5,'0')
					END +
			/*04*/	CASE
						WHEN tct.sd_id = 130						 THEN   REPLICATE('0',20)
						ELSE												dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(20),dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')) ) , 20,'0')
					END					+
			/*05*/  CASE
						WHEN tct.sd_id = 130						 THEN	dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(16),replace(tct.ct_docNumber,'-','') ) , 16,'0')
						ELSE												REPLICATE(' ',16)
					END	+
			/*06*/	CONVERT(nvarchar(2),ttnt.tnt_afip) +
			/*07*/  CASE
						WHEN tsa.comp_id IS NOT NULL	THEN	dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(  replace(replace(tsa.suppa_TaxNumber,'-',''),'.','')),20,'0')
														ELSE	dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(  replace(replace(tc.supp_taxNumber,'-',''),'.','')),20,'0')
					END	+
			/*08*/  CASE
						WHEN tsa.comp_id IS NOT NULL	THEN	dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(30),dbo.fnGetOnlyAlfaText( tsa.suppa_name)) ,30,' ')
														ELSE	dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(30),dbo.fnGetOnlyAlfaText( tc.supp_name)) ,30,' ')
					END +
			--/*09*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tct.ct_Total,0),2),15) +
			/*09*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(														--99
																	CASE
																		WHEN tct.sd_id = 142 THEN	(ISNULL(tmp.decSumOfIVANeto,0) + ISNULL(tmp.xx_total,0))
																		WHEN tct.sd_id = 141 THEN	(ISNULL(tmp.decSumOfIVANeto,0) + ISNULL(tmp.xx_total,0))
																		WHEN tct.sd_id = 140 THEN	(ISNULL(tmp.decSumOfIVANeto,0) + ISNULL(tmp.xx_total,0))
																		ELSE						tct.ct_Total
																	END
																	,0),2),15) +
			/*10*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decNoGravado,0),2),15) +

			/*11*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decExento,0),2),15) +

			/*12*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decPercIVA,0),2),15) +

			/*13*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decPercNac,0),2),15) +
			/*14*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decPercIIBB,0),2),15) +
			/*15*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decPercMUN,0),2),15) +
			/*16*/  dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decImpInternos,0),2),15) +
			/*17*/	'PES' +
			/*18*/  '0001000000' +
			/*19*/  CONVERT(CHAR(1),tmp.intIVAQty ) +
			/*20*/  CASE
						--WHEN tmp.intIVAQty = 0 AND tc.fc_id = 4 THEN 'E'	-- Exento con 0 Alicuotas de IVA
						WHEN EXISTS(	SELECT 1
						            		FROM #tbTaxMovements_tmp1 xxx
						            		WHERE	xxx.comp_id			= tct.comp_id AND
						            				xxx.ct_transaction	= tct.ct_transaction AND
						            				xxx.tmpAlicuota     = '0003'
									)						THEN 'E'
						WHEN tmp.decExento		<> 0		THEN 'E'
						WHEN tmp.decNoGravado	<> 0		THEN 'N'
						ELSE									 '0' --	 tsrco.srg3685v_AFIPCode
					END +
		/*21*/	dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decCredFisComput,0),2),15) +  -- poner 0
			/*22*/	dbo.fnSIAP_ConvertDecimal2String(Round(isnull(tmp.decOtrosTrib,0),2),15) +
			/*23*/	REPLICATE('0',11) +
			/*24*/  REPLICATE(' ',30) +
			/*25*/  REPLICATE('0',15)


		FROM tbCommercialTransactions tct
		INNER JOIN @tmpData tmp
			ON	tmp.comp_id		   = tct.comp_id			AND
				tmp.ct_transaction = tct.ct_transaction
		INNER JOIN tbSupplier tc			WITH (NOLOCK)
			ON	tc.comp_id = @comp_id AND
				tc.supp_id = tmp.supp_id
			--ON	tc.comp_id = tct.comp_id AND
			--	(tc.supp_id = tct.supp_id OR tc.supp_id = tct.supp_id4CreditCardLiquidation)  --tc.supp_id = tct.supp_id			***999
		LEFT JOIN tbSupplierAssociated tsa	WITH (NOLOCK)
			ON	tsa.supp_id		= tct.supp_id AND
				tsa.comp_id		= tct.comp_id AND
				tsa.suppa_id	= tct.suppa_id
		INNER JOIN tbsysTaxNumberTypes ttnt		WITH (NOLOCK)
			ON ttnt.tnt_id = tc.tnt_id
		ORDER BY tct.ct_transaction



	-- ------------------
	-- IVA de Facturas
	-- ------------------
	SELECT
			/*01*/
					CASE
						-- Facturas
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'A' THEN '001'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'B' THEN '006'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'C' THEN '011'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'M' THEN '051'
						WHEN tct.sd_id = 101 AND tct.ct_kindOf = 'E' THEN '019'		-- ERROR


						-- Notas de Credito
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'A' THEN '003'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'B' THEN '008'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'C' THEN '013'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'M' THEN '053'
						WHEN tct.sd_id = 103 AND tct.ct_kindOf = 'E' THEN '021'		-- ERROR

						-- Notas de Debito
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'A' THEN '002'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'B' THEN '007'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'C' THEN '012'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'M' THEN '052'
						WHEN tct.sd_id = 104 AND tct.ct_kindOf = 'E' THEN '020'

						-- Liquido Producto
						WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'A' THEN '060'
						WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'B' THEN '061'
						WHEN tct.sd_id = 131 AND tct.ct_kindOf = 'M' THEN '058'

						-- Despacho de Importacion
						WHEN tct.sd_id = 130						 THEN '066'

						-- Liquidación de Tarjetas de Crédito
						WHEN tct.sd_id = 142						 THEN '099'
						WHEN tct.sd_id = 141						 THEN '099'
						WHEN tct.sd_id = 140						 THEN '099'

						ELSE											'ERR'
					END +
			/*02*/	CASE
						WHEN tct.sd_id IN (101,103,104,131,142,141,140) AND tct.ct_pointOfSale = 0 THEN '00001'
						ELSE																dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(10),tct.ct_pointOfSale) , 5,'0')
					END +
			/*03*/	dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(20),dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')) ) , 20,'0') +
			/*04*/	CONVERT(nvarchar(2),ttnt.tnt_afip) +
			/*05*/  CASE
						WHEN tsa.comp_id IS NOT NULL	THEN	dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(  replace(replace(tsa.suppa_TaxNumber,'-',''),'.','')),20,'0')
														ELSE	dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(  replace(replace(tc.supp_taxNumber,'-',''),'.','')),20,'0')
					END	+



			/*06*/  dbo.fnSIAP_ConvertDecimal2String(SUM(Round(isnull(ttm.tm_subtotal,0),2)),15) +
			/*07*/	ttm.tmpAlicuota +

			/*08*/  dbo.fnSIAP_ConvertDecimal2String(SUM(Round(isnull(ttm.tm_Total,0),2)),15)


		FROM tbCommercialTransactions tct
		INNER JOIN @tmpData tmp
			ON	tmp.comp_id		   = tct.comp_id			AND
				tmp.ct_transaction = tct.ct_transaction
		INNER JOIN #tbTaxMovements_tmp1 ttm
			ON	ttm.comp_id			= tct.comp_id			AND
				ttm.ct_transaction	= tct.ct_transaction
			--ON	ttm.ct_transaction	= tct.ct_transaction	AND
			--	ttm.comp_id			= tct.comp_id

		INNER JOIN tbSupplier tc				WITH (NOLOCK)
			ON	tc.comp_id = @comp_id AND
				tc.supp_id = tmp.supp_id
			--ON	tc.comp_id = tct.comp_id AND
			--	(tc.supp_id = tct.supp_id OR tc.supp_id = tct.supp_id4CreditCardLiquidation)  --tc.supp_id = tct.supp_id
		LEFT JOIN tbSupplierAssociated tsa		WITH (NOLOCK)
			ON	tsa.supp_id		= tct.supp_id AND
				tsa.comp_id		= tct.comp_id AND
				tsa.suppa_id	= tct.suppa_id
		INNER JOIN tbsysTaxNumberTypes ttnt		WITH (NOLOCK)
			ON ttnt.tnt_id = tc.tnt_id

	WHERE tct.sd_id = 130

		GROUP BY	tct.comp_id,
					tct.bra_id,
					tct.ct_transaction,
					tct.sd_id,
					tct.ct_kindOf,
					tct.ct_pointOfSale,
					tct.ct_docNumber,
					ttm.tmpAlicuota,
					tc.supp_taxNumber,
					ttnt.tnt_afip,
					tsa.suppa_TaxNumber,
					tsa.comp_id
		ORDER BY tct.ct_transaction
	-- ------------------









	-- ------------------
	-- IVA de Despachos
	-- ------------------
	SELECT
			/*01*/	dbo.fnSIAP_ConvertString2FIXLength2(convert(nvarchar(16),replace(tct.ct_docNumber,'-','') ) , 16,'0') +
			/*02*/  dbo.fnSIAP_ConvertDecimal2String(SUM(Round(isnull(ttm.tm_subtotal,0),2)),15) +
			/*03*/	ttm.tmpAlicuota +
			/*04*/  dbo.fnSIAP_ConvertDecimal2String(SUM(Round(isnull(ttm.tm_Total,0),2)),15)


		FROM tbCommercialTransactions tct
		INNER JOIN @tmpData tmp
			ON	tmp.comp_id		   = tct.comp_id			AND
				tmp.ct_transaction = tct.ct_transaction
		INNER JOIN #tbTaxMovements_tmp1 ttm
			ON	ttm.comp_id			= tct.comp_id			AND
				ttm.ct_transaction	= tct.ct_transaction
			--ON	ttm.ct_transaction	= tct.ct_transaction	AND
			--	ttm.comp_id			= tct.comp_id

		INNER JOIN tbSupplier tc				WITH (NOLOCK)
			ON	tc.comp_id = @comp_id AND
				tc.supp_id = tmp.supp_id
			--ON	tc.comp_id = tct.comp_id AND
			--	(tc.supp_id = tct.supp_id OR tc.supp_id = tct.supp_id4CreditCardLiquidation)  --tc.supp_id = tct.supp_id
		INNER JOIN tbsysTaxNumberTypes ttnt		WITH (NOLOCK)
			ON ttnt.tnt_id = tc.tnt_id
		WHERE tct.sd_id = 130	AND
			  ttm.tax_TaxEngineColumn4ThisTaxIsNoGravado = 0	-- Para los FORROS ENFERMOS de DF q quieren que el puto neto quede como No Gravado.  05-2021

		GROUP BY	tct.comp_id,
					tct.bra_id,
					tct.ct_transaction,
					tct.sd_id,
					tct.ct_kindOf,
					tct.ct_pointOfSale,
					tct.ct_docNumber,
					ttm.tmpAlicuota
		ORDER BY tct.ct_transaction
	-- ------------------





	DROP TABLE #tbTaxMovements_tmp1




END







