	;WITH tmpUpdate4PerIVA AS (	SELECT	tmp.ct_transaction,
										SUM(ttm.tm_total)		[PercepcionIVA]
									FROM @tmpData tmp
									INNER JOIN tbCommercialTransactions tct
										ON	tct.comp_id		   = tmp.comp_id AND
											tct.ct_transaction = tmp.ct_transaction
									INNER JOIN tbTaxMovements ttm
										ON	ttm.comp_id				= tmp.comp_id			AND
											ttm.ct_transaction		= tmp.ct_transaction
									INNER JOIN tbTaxName ttn
										ON	ttn.tax_id	= ttm.tax_id AND
											ttn.comp_id = ttm.comp_id
									INNER JOIN tbsysTaxClass ttc
										ON ttc.tax_class = ttn.tax_class
	                            	WHERE ttc.taxcl_isPerception = 'True' AND ttc.taxcl_isIVA = 'True'
									GROUP BY tmp.ct_transaction
						)
	UPDATE  @tmpData
		SET decPercIVA = tmp2.PercepcionIVA
		FROM @tmpData tmp
		INNER JOIN tmpUpdate4PerIVA tmp2
			ON tmp2.ct_transaction = tmp.ct_transaction
	-- -------------------------------------------------


	-- -------------------------------------------------
	-- Percepcion de IIBB
	-- -------------------------------------------------
	;WITH tmpUpdate4PerIIBB AS (	SELECT	tmp.ct_transaction,
