-- -----------------------------------------------
-- Retenciones de GANANCIAS realizadas por Pagos.!
-- y Percepciones realizadas por VENTAS
-- -----------------------------------------------

CREATE PROCEDURE [dbo].[spSysExportData_getSICORE_RetencionesYPercepcionesV9]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE		@comp_id			Int,
				@lang_id			Int,
				@bra_id				Int,
				@date_from			Datetime,
				@date_to			Datetime,
				@brag_id			INT

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@bra_id				=1,
				@date_from			='2023-06-01',
				@date_to			='2023-09-30',
				@brag_id			= 13
	*/
	-- ----------------------------------------------------------


	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	Select CONVERT(CHAR(198),

			--::01 Codigo del Comprobante, 06, Orden de Pago
			CASE
			    WHEN tct.sd_id = 106 THEN '06'
			    WHEN tct.sd_id = 001 THEN '01'
			    WHEN tct.sd_id = 003 THEN '03'
			    WHEN tct.sd_id = 004 THEN '04'
			    ELSE					  '**'	-- No deberia pasar nunca, si pasa que de error!!!
			END +
			--::02 Fecha de Emisión
			RIGHT(@zeros + convert(Varchar(2),datepart(Day	,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(2),datepart(month,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(4),datepart(Year	,tct.ct_date)),4) +
			--::03 -Número de Comprobante
			CASE
			    WHEN tct.sd_id = 106 THEN	RIGHT(@zeros + convert(Varchar(16),dbo.fnStrAllTrim(dbo.fnGetOnlyNumbers(ttm.tm_docNumber))),16)  -- Se puso este numero por recomendacion de estudio de auditoria ya que el aplicativo genera su propio numero de comprobante de retencion y no hay manera de enlazar el numero generado por el aplicativo con el numero del comprobante fisico.
			    ELSE						RIGHT(@zeros + convert(Varchar(16),dbo.fnStrAllTrim(dbo.fnGetOnlyNumbers( dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction )))),16)
			END +
			--::04- Importe Retenido o Percibido
			dbo.fnStrPADL(dbo.fnStrSTRTRAN(convert(Varchar(16),convert(DECIMAL(16,2), tct.ct_total ))  , '.',',',1,100,0),16,'0') +
			--::05: Codigo de Impuersto
			dbo.fnStrPADL(CONVERT(VARCHAR(4),ISNULL(ttn.sysSICORE_TaxCode,0) ),4,'0') +
			--::06: Codigo de Regimem
			dbo.fnStrPADL(CONVERT(VARCHAR(3),ISNULL(ttn.sysSICORE_RegimenCode ,0) ),3,'0') +
			--::07: Codigo de Operacion
			CASE
			    WHEN tct.sd_id = 106 THEN	'1'	--Retencion
			    ELSE						'2'	-- Percepcion
			END		+
			--::08: Base de Calculo
			dbo.fnStrPADL(dbo.fnStrSTRTRAN(convert(Varchar(14),convert(DECIMAL(14,2), SUM(IsNull(ttm.tm_subtotal,0)) ))  , '.',',',1,100,0),14,'0') +
			--::09  Fecha de Retencion
			RIGHT(@zeros + convert(Varchar(2),datepart(Day	,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(2),datepart(month,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(4),datepart(Year	,tct.ct_date)),4) +
			--::10 Codigo de Condicion
			dbo.fnStrPADL(CONVERT(VARCHAR(2),ISNULL(ttn.sysSICORE_CondicionCode,0) ),2,'0') +
			--::11 retencion practidada a sujetos .....
			dbo.fnStrPADL(CONVERT(VARCHAR(1),ISNULL(ttn.sysSICORE_SujetosSuspendidosCode ,0) ),1,'0') +
			--::12  Importe de la retencion
			dbo.fnStrPADL(dbo.fnStrSTRTRAN(convert(Varchar(14),convert(DECIMAL(14,2), SUM(ttm.tm_total) ))  , '.',',',1,100,0),14,'0') +
			--::13 Porcentaje de Exclusion
			'000,00' +
			--::14 Fecha de Emision del boletin
			'0000000000' +
			--::15  Tipo de documento del retenido
			CASE
			    WHEN tct.sd_id = 106 THEN	dbo.fnStrPADL(CONVERT(VARCHAR(2),ISNULL(ttntSupp.tnt_afip,0) ),2,'0')
			    ELSE						dbo.fnStrPADL(CONVERT(VARCHAR(2),ISNULL(ttntCust.tnt_afip,0) ),2,'0')
			END	+
			--::16  Numero de documento del retenido
			CASE
			    WHEN tct.sd_id = 106 THEN	RIGHT(@zeros + convert(Varchar(20),dbo.fnGetOnlyNumbers( substring(dbo.fnStrAllTrim( ts.supp_taxNumber),1,20)) ),20)
			    ELSE						RIGHT(@zeros + convert(Varchar(20),dbo.fnGetOnlyNumbers( substring(dbo.fnStrAllTrim( tc.cust_taxNumber ),1,20))),20)
			END +
			--::17: Numero de certificado original   14
			'00000000000000'  +
			--::18  Denominacion del ordenante       30
			'000000000000000000000000000000' +
			--::19  Acrecentamiento                   1
			'0' +
			--::20  CUIT del pais retenido           11
			'00000000000' +
			--::21  CUIT del Ordenante               11
			'00000000000'
			)


	From tbTaxMovements ttm							WITH (NOLOCK)

	INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
		On	tct.comp_id = ttm.comp_id	AND
			tct.ct_transaction = ttm.ct_transaction

	LEFT Join tbSupplier ts							WITH (NOLOCK)
		On  ts.comp_id = tct.comp_id	AND
			ts.supp_id = tct.supp_id

	LEFT JOIN tbsysTaxNumberTypes ttntSupp			WITH (NOLOCK)
		ON ttntSupp.tnt_id = ts.tnt_id

	LEFT JOIN tbCustomer tc
		ON	tc.comp_id = tct.comp_id	AND
			tc.cust_id = tct.cust_id

	LEFT JOIN tbsysTaxNumberTypes ttntCust			WITH (NOLOCK)
		ON ttntCust.tnt_id = tc.tnt_id

	Inner Join tbTaxName ttn						WITH (NOLOCK)
		On  ttn.comp_id = ttm.comp_id	AND
			ttn.tax_id  = ttm.tax_id

	WHERE	tct.comp_id		=  @comp_id
	And		(
				(@brag_id = -1	AND		tct.bra_id	= @bra_id) OR
				(@brag_id <> -1 AND		EXISTS( SELECT TOP 1  1
				                   					FROM	@tblBranchs tmpb
				                   					WHERE	tmpb.bra_id = tct.bra_id ))
			)
	And		tct.ct_date	 Between   @date_from And @date_to
	-- 05-2017, que incluya las que dicen abajo segun el impuesto configurado.!And     ttn.tax_class	IN (180,280)   -- Percepcion o Retencion de Ganancias
	AND		CASE
	   		    WHEN tct.sd_id = 106 THEN	ttntSupp.tnt_afip
	   		    ELSE						ttntCust.tnt_afip
	   		END IN (80,86,83,87,84)
	AND	-- MOS 07-2023: x Vileni q no le salian las percepciones de IVA.
	(
		(
			ttm.tm_docNumber IS NOT NULL
			AND
			ttm.tm_docNumber <> ''
		)
		OR
		(tct.sd_id IN (1,3,4))
	)
	--AND ttm.tm_docNumber IS NOT NULL
	--AND ttm.tm_docNumber <> ''
	AND ttm.tm_total <> 0
	AND tct.sd_id IN (106,1,3,4)
	AND CASE
	        WHEN tct.sd_id =  106		AND ttn.sysSICORE_RetentionInclude	= 'True'  THEN	'True'
	        WHEN tct.sd_id IN (1,3,4)	AND ttn.sysSICORE_PerceptionInclude = 'True'  THEN	'True'
	        ELSE																			'False'
	    END	 = 'True'

	-- MOS 07-2023 x Vileni x q multiplicaba x renglon cada cpte. ( igual deberioa andar )  Se puso los SUm de arriba en los totales.
	GROUP BY	tct.sd_id,tct.ct_date,ttm.tm_docNumber,tct.comp_id,tct.ct_transaction,tct.ct_total,ttn.sysSICORE_TaxCode,
				ttn.sysSICORE_RegimenCode,ttn.sysSICORE_CondicionCode,ttn.sysSICORE_SujetosSuspendidosCode,ttntcust.tnt_afip,ttntSupp.tnt_afip,
				ts.supp_taxNumber,tc.cust_taxNumber
	ORDER BY
			CASE
			    WHEN tct.sd_id = 106 THEN	RIGHT(@zeros + convert(Varchar(16),dbo.fnStrAllTrim(dbo.fnGetOnlyNumbers(ttm.tm_docNumber))),16)
			    ELSE						RIGHT(@zeros + convert(Varchar(16),dbo.fnStrAllTrim(dbo.fnGetOnlyNumbers( dbo.fnGetCommercialTransactionDescription(tct.comp_id,2,tct.ct_transaction )))),16)
			END


END
GO




CREATE PROCEDURE [dbo].[spSysExportData_getSIFERE_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE		@comp_id			Int,
				@lang_id			Int,
				@bra_id				Int,
				@date_from			Datetime,
				@date_to			Datetime,
				@brag_id			INT

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@bra_id				=1,
				@date_from			='2012-08-01',
				@date_to			='2012-08-31',
				@brag_id			=4
	*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	Select CONVERT(CHAR(51),

			-- ::01 -Jurisdiccion
			CONVERT(CHAR(3),ts.state_jurisdiccion) +


			--::02 -CUIT del contribuyente retenido::
			RIGHT(@zeros + convert(Varchar(13),tc.supp_taxNumber),13) +

			--::02 -Fecha de la percepción::
			RIGHT(@zeros + convert(Varchar(2),datepart(Day	,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(2),datepart(month,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(4),datepart(Year	,tct.ct_taxDate)),4) +

			--::03 -Número de Sucursal::
			RIGHT(@zeros +convert(Varchar(4),tct.ct_pointOfSale),4) +

			--::04 -Número de Emisión::
			RIGHT(@zeros + convert(Varchar(8), dbo.fnGetOnlyNumbers(tct.ct_docNumber )),8) +

			CASE
				WHEN tct.sd_id = 101 THEN 'F'
				WHEN tct.sd_id = 103 THEN 'C'
				WHEN tct.sd_id = 104 THEN 'D'
			END +

			convert(char(1),tct.ct_kindOf) +


			--::05 -Importe de percepción::
			CASE
				WHEN tct.sd_id = 103 THEN
					'-' +
					dbo.fnStrPADL
						(dbo.fnStrSTRTRAN
							(CONVERT(Varchar(11),convert(DECIMAL(11,2),(ttm.tm_total))),'.',',',1,100,0),11,'0')

				ELSE
					dbo.fnStrPADL
						(dbo.fnStrSTRTRAN
							(CONVERT(Varchar(11),convert(DECIMAL(11,2),(ttm.tm_total))),'.',',',1,100,0),11,'0')
			END +


			'A')

	From tbTaxMovements ttm	WITH (NOLOCK)

	left Join tbCommercialTransactions tct	WITH (NOLOCK)
		On		tct.comp_id			= ttm.comp_id
			AND tct.ct_transaction	= ttm.ct_transaction

	INNER JOIN tbSupplier tc	WITH (NOLOCK)
		ON		tc.comp_id = tct.comp_id
			AND tc.supp_id = tct.supp_id

--	INNER JOIN tbsysState ts
--		ON		ts.country_id	= ttm.Country_Id
--			AND ts.state_id		= ttm.State_Id
--			AND not ts.state_jurisdiccion IS NULL

	Inner Join dbo.tbsysTaxNumberTypes ttnt	WITH (NOLOCK)
	On ttnt.tnt_id = tc.tnt_id

	Inner Join tbTaxName ttn	WITH (NOLOCK)
	On  ttn.comp_id						= ttm.comp_id
	And ttn.tax_id						= ttm.tax_id
	AND ttn.tax_isSIFERE_Percepciones	= 'True'

	INNER JOIN tbsysTaxClass ttc	WITH (NOLOCK)
		ON		ttc.tax_class			= ttn.tax_class
			AND ttc.taxcl_isPerception	= 'True'
			AND ttc.taxcl_isIB			= 'True'

	INNER JOIN tbsysState ts	WITH (NOLOCK)
		ON		ts.country_id			= ttc.country_id
			AND ts.state_id				= ttc.state_id
			AND not ts.state_jurisdiccion IS NULL



	WHERE	tct.comp_id			=		@comp_id
	AND 	tct.ct_taxDate		BETWEEN	@date_from And @date_to
	AND		tct.sd_id			IN		(101,103,104)	-- Solo Factura, NC y ND
	AND 	(
				(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id))		OR

				(@brag_id	<> -1	AND	tct.bra_id IN (	SELECT	bgd.bra_id
														FROM	tbBranchGroupDetail bgd	WITH (NOLOCK)
														WHERE	bgd.brag_id = @brag_id))
			)



--	GROUP BY	tc.cust_taxNumber,
--				tct.ct_date,
--				tct.sd_id,
--				tct.ct_kindOf,
--				tct.ct_pointOfSale,
--				tct.ct_docNumber


END
GO







CREATE PROCEDURE [dbo].[spSysExportData_getSIFERE_Retenciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As



BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE		@comp_id			Int,
				@lang_id			Int,
				@bra_id				Int,
				@date_from			Datetime,
				@date_to			Datetime,
				@brag_id			INT

	SELECT		@comp_id			=1,
				@lang_id			=2,
				@bra_id				=1,
				@date_from			='2009-01-02',
				@date_to			='2016-01-01',
				@brag_id			=-1
	*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	Select CONVERT(CHAR(79),

			-- ::01 -Jurisdiccion
			CONVERT(CHAR(3),ts.state_jurisdiccion) +


			--::02 -CUIT del contribuyente retenido::
			RIGHT(@zeros + convert(Varchar(13),tc.cust_taxNumber),13) +

			--::02 -Fecha de la percepción::
			RIGHT(@zeros + convert(Varchar(2),datepart(Day	,ttm.tm_docDate)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(2),datepart(month,ttm.tm_docDate)),2) + '/' +
			RIGHT(@zeros + convert(Varchar(4),datepart(Year	,ttm.tm_docDate)),4) +

			--::03 -Número de Sucursal::
			RIGHT(@zeros +convert(Varchar(4),tct.ct_pointOfSale),4) +

			--::04 -Número de Emisión::
			RIGHT(@zeros + convert(Varchar(16), dbo.fnGetOnlyNumbers(ttm.tm_docNumber)),16) +

			'O' + -- Otro
			'C' + -- Recibo

			RIGHT(@zeros + convert(Varchar(20), dbo.fnGetOnlyNumbers(ttm.tm_docNumber)),20) +		-- Comprobante de Origen

			--::05 -Importe de percepción::
			dbo.fnStrPADL(dbo.fnStrSTRTRAN(convert(Varchar(11),convert(DECIMAL(11,2), (ttm.tm_total)))  , '.',',',1,100,0),11,'0') +
			'A')

	From tbTaxMovements ttm

	left Join tbCommercialTransactions tct
		On		tct.comp_id			= ttm.comp_id
			AND tct.ct_transaction	= ttm.ct_transaction

	INNER JOIN tbCustomer tc
		ON		tc.comp_id = tct.comp_id
			AND tc.cust_id = tct.cust_id


	Inner Join dbo.tbsysTaxNumberTypes ttnt
	On ttnt.tnt_id = tc.tnt_id

	Inner Join tbTaxName ttn
	On  ttn.comp_id						= ttm.comp_id
	And ttn.tax_id						= ttm.tax_id
	AND ttn.tax_isSIFERE_Retenciones	= 'True'

	INNER JOIN tbsysTaxClass ttc
		ON		ttc.tax_class			= ttn.tax_class
			AND ttc.taxcl_isRetention	= 'True'
			AND ttc.taxcl_isIB			= 'True'

	INNER JOIN tbsysState ts
		ON		ts.country_id			= ttc.country_id
			AND ts.state_id				= ttc.state_id
			AND not ts.state_jurisdiccion IS NULL


--	INNER JOIN tbsysState ts
--		ON		ts.country_id	= ttm.Country_Id
--			AND ts.state_id		= ttm.State_Id
--			AND not ts.state_jurisdiccion IS NULL



	WHERE	tct.comp_id		=		@comp_id
	AND 	tct.ct_taxDate	BETWEEN	@date_from And @date_to
	AND		tct.sd_id		IN		(6,13)	-- Solo Recibos de Cobranza
	AND 	(
				(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

				(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
														FROM tbBranchGroupDetail bgd
														WHERE bgd.brag_id = @brag_id))
	)

--	GROUP BY	tc.cust_taxNumber,
--				tct.ct_date,
--				tct.sd_id,
--				tct.ct_kindOf,
--				tct.ct_pointOfSale,
--				tct.ct_docNumber


END
GO






