CREATE PROCEDURE [dbo].[spSysExportData_getSIRED]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
/*
		DECLARE		@comp_id			Int,
					@lang_id			Int,
					@bra_id				Int,
					@date_from			Datetime,
					@date_to			Datetime,
					@brag_id			INT

		SELECT		@comp_id			=1,
					@lang_id			=2,
					@bra_id				=1,
					@date_from			='2009-01-02',
					@date_to			='2016-01-01',
					@brag_id			=-1


		DROP TABLE #tmp
		Drop table #tmpB
		DROP TABLE #tmpTaxMovements
		DROP TABLE #tmpTaxMovementsOtherTaxes

		DROP TABLE #tmpPurchase
		Drop table #tmpBPurchase
		DROP TABLE #tmpPurchase_TaxMovements
		DROP TABLE #tmpPurchase_TaxMovementsOtherTaxes

*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	-- -----------------------------------------------------------------------------------------------------
	-- VENTAS- Crea un nuevo tbTaxmovements con la suma total por impuesto del subtotal, total y alicuota
	-- -----------------------------------------------------------------------------------------------------
	SELECT	ttm.comp_id,
			ttm.ct_transaction,
			ttm.tax_id,
			Sum(ttm.tm_subtotal)	[tm_subtotal] ,
			ttm.percentaje,
			Sum(ttm.tm_total)		[tm_total]

		Into #tmpTaxMovements

		FROM tbTaxMovements									ttm				WITH (NOLOCK)

		Inner Join tbCommercialTransactions					tct				WITH (NOLOCK)
			ON ttm.comp_id			= tct.comp_id
			AND ttm.bra_id			= tct.bra_id
			AND ttm.ct_transaction	= tct.ct_transaction

		INNER JOIN vwCommercialTransactions_forSales		vctfs			WITH (NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id
			AND vctfs.bra_id			= tct.bra_id
			AND	vctfs.ct_transaction	= tct.ct_transaction

		Inner Join tbTaxName								ttn				WITH (NOLOCK)
			On ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

		Inner Join vwsysTaxClassIVA_Taxes					vtcit			WITH (NOLOCK)
			On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id							AND
					tct.ct_date		Between		@date_from And @date_to		AND
					ttm.tm_total	<> 0

		GROUP BY ttm.comp_id,ttm.ct_transaction,ttm.tax_id,ttm.percentaje
	-- -----------------------------------------------------------------------------------------------------


--==
--SELECT * FROM #tmpTaxMovements
--==


	-- -----------------------------------------------------------------------------------------------------
	-- VENTAS- Crea un nuevo tbTaxmovements con la suma total por impuesto del subtotal, total y alicuota que no sean IVA
	-- -----------------------------------------------------------------------------------------------------
	SELECT	ttm.comp_id,
			ttm.ct_transaction,
			Sum(ttm.tm_subtotal)	[tm_subtotal] ,
			Sum(ttm.tm_total)		[tm_total]

		Into #tmpTaxMovementsOtherTaxes

		FROM tbTaxMovements									ttm					WITH (NOLOCK)

		Inner Join tbCommercialTransactions tct
			ON ttm.comp_id			= tct.comp_id
			AND ttm.bra_id			= tct.bra_id
			AND ttm.ct_transaction	= tct.ct_transaction
		INNER JOIN vwCommercialTransactions_forSales		vctfs				WITH (NOLOCK)
			ON	vctfs.comp_id			= tct.comp_id
			AND vctfs.bra_id			= tct.bra_id
			AND	vctfs.ct_transaction	= tct.ct_transaction

		Inner Join tbTaxName								ttn					WITH (NOLOCK)
			On ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

		left Join vwsysTaxClassIVA_Taxes					vtcit				WITH (NOLOCK)
			On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id							AND
					tct.ct_date		Between		@date_from And @date_to		AND
					vtcit.tax_class IS NULL									AND
					ttm.tm_total <> 0
		GROUP BY ttm.comp_id,ttm.ct_transaction
		ORDER BY ttm.ct_transaction
	-- -----------------------------------------------------------------------------------------------------

--==
--SELECT * FROM #tmpTaxMovementsOtherTaxes
--==

	-- -----------------------------------------------------------------------------------------------------
	--VENTAS-  Cantidad de Alicuitas por Transaccion
	-- -----------------------------------------------------------------------------------------------------
	Select asa.ct_transaction, Count(*) [Alicuotas]
	Into #tmpB
		from
		(
			Select ttm.ct_transaction
				From tbTaxMovements										ttm				WITH (NOLOCK)
					Inner Join tbCommercialTransactions tct
						ON ttm.comp_id			= tct.comp_id
						AND ttm.bra_id			= tct.bra_id
						AND ttm.ct_transaction	= tct.ct_transaction

					INNER JOIN vwCommercialTransactions_forSales		vctfs			WITH (NOLOCK)
						ON	vctfs.comp_id			= tct.comp_id
						AND vctfs.bra_id			= tct.bra_id
						AND	vctfs.ct_transaction	= tct.ct_transaction

					Inner Join tbTaxName								ttn				WITH (NOLOCK)
						On ttn.comp_id				= ttm.comp_id
						And ttn.tax_id				= ttm.tax_id

					Inner Join vwsysTaxClassIVA_Taxes					vtcit			WITH (NOLOCK)
						On	vtcit.tax_class			= ttn.tax_class

				where		tct.comp_id		=	@comp_id							AND
							tct.ct_date		Between		@date_from And @date_to		AND
							ttm.tm_total	<> 0
							--==
							--AND  ttm.ct_transaction = 987859
							--==
				Group By ttm.ct_transaction, ttm.tax_id
		) [asa]
		Group By asa.ct_transaction
	-- -----------------------------------------------------------------------------------------------------

--==
--SELECT * FROM #tmpB
--==



	-- -----------------------------------------------------------------------------------------------------
	--VENTAS-  Saca el maximo taxId ya que luego se debe poner el importe total solo en el renglon final.
	-- -----------------------------------------------------------------------------------------------------
	SELECT	tct.ct_transaction, max(isnull(ttm.tax_id,0)) tax_id, 1 [marca]

		INTO	#tmp

		FROM	tbCommercialTransactions							tct			WITH (NOLOCK)

				INNER JOIN vwCommercialTransactions_forSales vctfs
					ON	vctfs.comp_id			= tct.comp_id
					AND vctfs.bra_id			= tct.bra_id
					AND	vctfs.ct_transaction	= tct.ct_transaction

				inner JOIN tbTaxMovements							ttm			WITH (NOLOCK)
					ON ttm.comp_id			= vctfs.comp_id
					AND ttm.bra_id			= vctfs.bra_id
					AND ttm.ct_transaction	= vctfs.ct_transaction

				Inner Join tbTaxName								ttn			WITH (NOLOCK)
					On ttn.comp_id				= ttm.comp_id
					And ttn.tax_id				= ttm.tax_id

				Inner Join vwsysTaxClassIVA_Taxes					vtcit		WITH (NOLOCK)
					On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id								AND
					tct.ct_date		Between		@date_from And @date_to			AND
					ttm.tm_total <> 0
		--==
		--and ttm.ct_transaction = 987859
		--==

		GROUP BY tct.ct_transaction
		ORDER BY 1,2
	-- -----------------------------------------------------------------------------------------------------





	-- -----------------------------------------------------------------------------------------------------
	-- COMPRAS - crea un nuevo tbTaxmovements con la suma total por impuesto del subtotal, total y alicuota
	-- -----------------------------------------------------------------------------------------------------
	SELECT	ttm.comp_id,
			ttm.ct_transaction,
			ttm.tax_id,
			Sum(ttm.tm_subtotal)	[tm_subtotal] ,
			ttm.percentaje,
			Sum(ttm.tm_total)		[tm_total]

		Into #tmpPurchase_TaxMovements

		FROM tbTaxMovements									ttm				WITH (NOLOCK)

		Inner Join tbCommercialTransactions					tct				WITH (NOLOCK)
			ON ttm.comp_id			= tct.comp_id
			--AND ttm.bra_id			= tct.bra_id
			AND ttm.ct_transaction	= tct.ct_transaction

		INNER JOIN vwCommercialTransactions_forPurchase vctfp				WITH (NOLOCK)
			ON	vctfp.comp_id			= tct.comp_id
			--AND vctfp.bra_id			= tct.bra_id
			AND	vctfp.ct_transaction	= tct.ct_transaction

		Inner Join tbTaxName								ttn				WITH (NOLOCK)
			On ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

		Inner Join vwsysTaxClassIVA_Taxes					vtcit			WITH (NOLOCK)
			On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id							AND
					tct.ct_date		Between		@date_from And @date_to		AND
					ttm.tm_total	<> 0

		GROUP BY ttm.comp_id,ttm.ct_transaction,ttm.tax_id,ttm.percentaje
	-- -----------------------------------------------------------------------------------------------------


--SELECT * FROM #tmpPurchase_TaxMovements


	-- ----------------------------------------------------------------------------------------------------
	-- COMPRAS - Crea un nuevo tbTaxmovements con la suma total por impuesto del subtotal, total y alicuota que no sean IVA
	-- -----------------------------------------------------------------------------------------------------
	SELECT	ttm.comp_id,
			ttm.ct_transaction,
			Sum(ttm.tm_subtotal)	[tm_subtotal] ,
			Sum(ttm.tm_total)		[tm_total]

		Into #tmpPurchase_TaxMovementsOtherTaxes

		FROM tbTaxMovements									ttm					WITH (NOLOCK)

		Inner Join tbCommercialTransactions					tct					WITH (NOLOCK)
			ON ttm.comp_id			= tct.comp_id
			--AND ttm.bra_id			= tct.bra_id
			AND ttm.ct_transaction	= tct.ct_transaction

		INNER JOIN vwCommercialTransactions_forPurchase		vctfp				WITH (NOLOCK)
			ON	vctfp.comp_id			= tct.comp_id
			--AND vctfp.bra_id			= tct.bra_id
			AND	vctfp.ct_transaction	= tct.ct_transaction

		Inner Join tbTaxName								ttn					WITH (NOLOCK)
			On  ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

		left Join vwsysTaxClassIVA_Taxes					vtcit				WITH (NOLOCK)
			On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id							AND
					tct.ct_date		Between		@date_from And @date_to		AND
					vtcit.tax_class IS NULL									AND
					ttm.tm_total <> 0

		GROUP BY ttm.comp_id,ttm.ct_transaction
		ORDER BY ttm.ct_transaction
	-- -----------------------------------------------------------------------------------------------------
--SELECT * FROM #tmpPurchase_TaxMovementsOtherTaxes

	-- -----------------------------------------------------------------------------------------------------
	--Compras-  Cantidad de Alicuitas por Transaccion
	-- -----------------------------------------------------------------------------------------------------
	Select asa.ct_transaction, Count(*) [Alicuotas]
	Into #tmpBPurchase
		from
		(
			Select ttm.ct_transaction
				From tbTaxMovements										ttm				WITH (NOLOCK)
					Inner Join tbCommercialTransactions tct
						ON ttm.comp_id			= tct.comp_id
						--AND ttm.bra_id			= tct.bra_id
						AND ttm.ct_transaction	= tct.ct_transaction

						INNER JOIN vwCommercialTransactions_forPurchase		vctfp		WITH (NOLOCK)
						ON	vctfp.comp_id			= tct.comp_id
						--AND vctfp.bra_id			= tct.bra_id
						AND	vctfp.ct_transaction	= tct.ct_transaction

					Inner Join tbTaxName								ttn				WITH (NOLOCK)
						On ttn.comp_id				= ttm.comp_id
						And ttn.tax_id				= ttm.tax_id

					Inner Join vwsysTaxClassIVA_Taxes					vtcit			WITH (NOLOCK)
						On	vtcit.tax_class			= ttn.tax_class

				where		tct.comp_id		=	@comp_id							AND
							tct.ct_date		Between		@date_from And @date_to		AND
							ttm.tm_total	<> 0
							--==
							--AND  ttm.ct_transaction = 987859
							--==
				Group By ttm.ct_transaction, ttm.tax_id
		) [asa]
		Group By asa.ct_transaction
	-- -----------------------------------------------------------------------------------------------------

--SELECT * FROM #tmpBPurchase






	-- -----------------------------------------------------------------------------------------------------
	--Compras-  Saca el maximo taxId ya que luego se debe poner el importe total solo en el renglon final.
	-- -----------------------------------------------------------------------------------------------------
	SELECT	tct.ct_transaction, max(isnull(ttm.tax_id,0)) tax_id, 1 [marca]

		INTO	#tmpPurchase

		FROM	tbCommercialTransactions							tct			WITH (NOLOCK)

			INNER JOIN vwCommercialTransactions_forPurchase			vctfp		WITH (NOLOCK)
			ON	vctfp.comp_id			= tct.comp_id
			--AND vctfp.bra_id			= tct.bra_id
			AND	vctfp.ct_transaction	= tct.ct_transaction

			inner JOIN tbTaxMovements							ttm				WITH (NOLOCK)
				ON ttm.comp_id			= vctfp.comp_id
				--AND ttm.bra_id			= vctfp.bra_id
				AND ttm.ct_transaction	= vctfp.ct_transaction

			Inner Join tbTaxName								ttn				WITH (NOLOCK)
				On ttn.comp_id				= ttm.comp_id
				And ttn.tax_id				= ttm.tax_id

			Inner Join vwsysTaxClassIVA_Taxes					vtcit			WITH (NOLOCK)
					On	vtcit.tax_class			= ttn.tax_class

		where		tct.comp_id		=	@comp_id								AND
					tct.ct_date		Between		@date_from And @date_to			AND
					ttm.tm_total <> 0
		--==
		--and ttm.ct_transaction = 987859
		--==

		GROUP BY tct.ct_transaction
		ORDER BY 1,2
	-- -----------------------------------------------------------------------------------------------------

--SELECT * FROM #tmpPurchase





	--***----------------------------------------------------------------
	--***
	--*** INTERFACE DE CABECERA ( CABECERA_AAAAMM.TXT) REGISTRO TIPO 1
	--*** Longitud : 290
	--***----------------------------------------------------------------


SELECT (	'1' +																																		--Tipo de Registro
		dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_date,'') +																							--Fecha de Comprobante
		dbo.fnSIAP_ConvertString2FIXLength(isnull(td.sd_ARCIBA_DocumentType,'00'),2)+																	--Tipo de Comprobante-segun tabla
		dbo.fnSIAP_ConvertString2FIXLength(	CASE
												WHEN dbo.fnSIAP_ConvertString2FIXLength(isnull(tdf.df_Fiscal_IsFiscalPrinter,'0'),1) = 1 THEN 'C'
												ELSE									''
											End ,1)+																									--Controlador Fiscal
		dbo.fnSIAP_ConvertString2FIXLength(tdf.df_pointOfSale,4)+																			--Punto de Venta
		dbo.fnSIAP_ConvertString2FIXLength(tct.ct_docNumber,8)+																				--Nº de Comprobante
		dbo.fnSIAP_ConvertString2FIXLength(tct.ct_docNumber,8)+																				--Nº de Comprobante registrado
		dbo.fnSIAP_ConvertString2FIXLength('001',3)+																						--Cantidad de hojas
		dbo.fnSIAP_ConvertString2FIXLength(ttnt.tnt_afip,2)+																				--Codigo de doc indentificatorio del comprador	-segun tabla
		dbo.fnSIAP_ConvertString2FIXLength(tc.cust_taxNumber,11)+																			--Nº de indentifiacion del comprador			-segun tabla
		dbo.fnSIAP_ConvertString2FIXLength(tc.cust_name,30)+																				--Apellido y nombre o denominacion del comprador
		dbo.fnSIAP_ConvertDecimal2String(isnull(tct.ct_Total,0)*100,15)+																				--Importe Total de la operacion
		dbo.fnSIAP_ConvertDecimal2String(isnull(impalt.tm_Total,0)*100,15)+																				--importe total de conceptos que no integran el precio neto gravado
	    (select CASE WHEN isnull(ttm.percentaje,0)*100 > 0 THEN
					dbo.fnSIAP_ConvertDecimal2String(isnull(ttm.tm_subtotal,0)*100,15)
				ELSE
					dbo.fnSIAP_ConvertDecimal2String(0,15)
				End )+																																	--importe neto gravado
		(select CASE WHEN isnull(ttm.percentaje,0) > 0 THEN
					dbo.fnSIAP_ConvertDecimal2String(isnull(ttm.tm_total,0)*100,15)
				ELSE
					dbo.fnSIAP_ConvertDecimal2String(0,15)
				End )+																																	--impuesto liquidado
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+																				--impuesto liquidado a RNI o percepcion a no categorizados
		(select	CASE
					WHEN a.[marca] = 1 AND isnull(ttm.percentaje,0) = 0  THEN
						dbo.fnSIAP_ConvertDecimal2String(isnull(ttm.tm_subtotal,0)*100,15)
					ELSE
						dbo.fnSIAP_ConvertDecimal2String(0,15)
				End )+																																	--importe de operaciones exentas
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+																				--importe de percepciones o pagos a cta de impuestos nacionales
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+																				--importe de percepcion de ingresos brutos
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+																				--Importe de percepcion por impuestos municipales
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+																				--Importe de impuestos internos
				dbo.fnSIAP_ConvertString2FIXLength(isnull(td2.dl_name,''),15)+																			--Transporte
				(SELECT  case when tc.fc_id = 1  THEN
										dbo.fnSIAP_ConvertString2FIXLength('01',2)  -- Responsable Inscripto
								  when tc.fc_id = 2  THEN
							  			dbo.fnSIAP_ConvertString2FIXLength('05',2)  -- Consumidor Final
								  when tc.fc_id = 3  THEN
										dbo.fnSIAP_ConvertString2FIXLength('06',2)  -- Monotributista
								  when tc.fc_id = 4  THEN
							  			dbo.fnSIAP_ConvertString2FIXLength('04',2)  -- IVA exento
								  when tc.fc_id = 7  THEN
										dbo.fnSIAP_ConvertString2FIXLength('03',2)  -- IVA no responsable
								  when tc.fc_id = 14  THEN
							  			dbo.fnSIAP_ConvertString2FIXLength('07',2)  -- No categorizado
								  when tc.fc_id = 15  THEN
										dbo.fnSIAP_ConvertString2FIXLength('09',2)  -- Cliente del exterior
								  when tc.country_id <> 54  THEN
							  			dbo.fnSIAP_ConvertString2FIXLength('08',2)  -- Proveedor del Exterior
				         END)+																															--Tipo de Responsable-segun tabla
						dbo.fnSIAP_ConvertString2FIXLength(tc2.curr_symbolFEx,3)+															--Codigo de Moneda-segun tabla
						dbo.fnSIAP_ConvertString2FIXLength('0000000000',10)+																			--tipo de cambio
						dbo.fnSIAP_ConvertString2FIXLength(b.alicuotas,1)+																				--cantidad de alicuotas de iva
						dbo.fnSIAP_ConvertString2FIXLength('1',1)+																						--codigo de operacion
						dbo.fnSIAP_ConvertString2FIXLength(tct.ct_CAI,14)+																	--CAI
						dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_payDate,'') +																		--Fecha de Vencimiento
						dbo.fnSIAP_ConvertDate2StringAaAAMMDD('','')																					--Fecha de Anulacion de comprobante

				) [Cabecera]

		FROM tbCommercialTransactions							tct			WITH (NOLOCK)


			Inner Join	vwCommercialTransactions_forSales		vctfs		WITH (NOLOCK)
				On	vctfs.comp_id			= tct.comp_id
				--And vctfs.bra_id			= tct.bra_id
				And vctfs.ct_transaction	= tct.ct_transaction

			inner JOIN tbsysDocuments							td			WITH (NOLOCK)
				ON	td.sd_id				= tct.sd_id

			Inner Join	tbDocumentsFile							tdf			WITH (NOLOCK)
				On	tdf.comp_id				= tct.comp_id
				AND tdf.df_id				= tct.df_id

			Inner Join	tbCustomer								tc			WITH (NOLOCK)
				On	tc.comp_id				= tct.comp_id
				And tc.cust_id				= tct.cust_id

			Inner Join	tbsysTaxNumberTypes						ttnt		WITH (NOLOCK)
				On	ttnt.tnt_id				= tc.tnt_id

			LEFT Join #tmpTaxMovements							ttm			WITH (NOLOCK)
				ON	ttm.comp_id				= vctfs.comp_id
				AND ttm.ct_transaction		= vctfs.ct_transaction

			LEFT Join tbTaxName								ttn				WITH (NOLOCK)
				On  ttn.comp_id				= ttm.comp_id
				And ttn.tax_id				= ttm.tax_id

			left JOIN #tmpTaxMovementsOtherTaxes				impalt		WITH (NOLOCK)
				ON impalt.ct_transaction	= tct.ct_transaction

			LEFT Join vwsysTaxClassIVA_Taxes					vtcit		WITH (NOLOCK)
				On	vtcit.tax_class			= ttn.tax_class

			INNER JOIN tbsysCurrency							tc2			WITH (NOLOCK)
			ON	tc2.curr_id			= tc.curr_id

			LEFT JOIN tbDelivery								td2			WITH (NOLOCK)
			ON  td2.comp_id			= tct.comp_id
			AND td2.dl_id			= tct.dl_id

			left Join #tmp										a
			ON  a.ct_transaction		= tct.ct_transaction
			AND a.tax_id				= isnull(ttm.tax_id,0)

			inner Join #tmpB									b
			ON  b.ct_transaction		=  isnull(tct.ct_transaction,0)

			INNER JOIN tbsysState								ts			WITH (NOLOCK)
			ON	ts.country_id			= tct.country_id AND
				ts.state_id				= tct.state_id


		WHERE	tct.comp_id		=		@comp_id
		AND 	tct.ct_taxDate	BETWEEN	@date_from And @date_to
		AND 	(
					(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

					(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
																FROM tbBranchGroupDetail bgd	WITH (NOLOCK)
																WHERE bgd.brag_id = @brag_id))
				)




	--***----------------------------------------------------------------
	--***
	--*** INTERFACE DE DETALLE ( DETALLE_AAAAMM.TXT)
	--*** Longitud : 189
	--***----------------------------------------------------------------
	select (dbo.fnSIAP_ConvertString2FIXLength(isnull(td.sd_ARCIBA_DocumentType,'00'),2)+														--Tipo de comprobante-segun tabla
								dbo.fnSIAP_ConvertString2FIXLength(	CASE
												WHEN dbo.fnSIAP_ConvertString2FIXLength(isnull(tdf.df_Fiscal_IsFiscalPrinter,'0'),1) = 1 THEN 'C'
												ELSE									''
											End ,1)+																							--Controlador Fiscal
							dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_date,'') +																--Fecha de comprobante
							dbo.fnSIAP_ConvertString2FIXLength(isnull(tdf.df_pointOfSale,''),4)+												--Punto de Venta
							dbo.fnSIAP_ConvertString2FIXLength(isnull(tct.ct_docNumber,''),8)+													--Nº de Comprobante
							dbo.fnSIAP_ConvertString2FIXLength(isnull(tct.ct_docNumber,''),8)+													--Nº de Comprobante registrado
							dbo.fnSIAP_ConvertDecimal2String(isnull(it.it_qty,0),12)+															--Cantidad
							dbo.fnSIAP_ConvertString2FIXLength('07',2)+																			--Unidad de medida	-segun tabla
							dbo.fnSIAP_ConvertDecimal2String(isnull(it.it_price,0),16) +														--Precio Unitario
							dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+															--Importe de Bonificacion
							dbo.fnSIAP_ConvertString2FIXLength('000000000000000',16)+															--Importe de Ajuste
							dbo.fnSIAP_ConvertString2FIXLength('000000000000000',16)+															--subtotal del registro
							dbo.fnSIAP_ConvertDecimal2String(isnull(ttn.tax_percentage,'0000'),4)+												--Alicuota de iva aplicable	-segun tabla
							dbo.fnSIAP_ConvertString2FIXLength('',1)+																			--indicacion de exento,gravado o no gravado
							dbo.fnSIAP_ConvertString2FIXLength('',1)+																			--indicacion de de anulacion
							dbo.fnSIAP_ConvertString2FIXLength(isnull(ti.item_desc,''),75)														--Diseño Libre ,desc
					)[Detalle]



  From		dbo.tbItemTransactions							it						WITH (NOLOCK)


			INNER JOIN tbCommercialTransactions				tct						WITH (NOLOCK)
			ON	tct.comp_id			= it.comp_id			AND
				--tct.bra_id			= it.bra_id				AND
				tct.ct_transaction	= it.ct_transaction

			Inner Join	vwCommercialTransactions_forSales	vctfs					WITH (NOLOCK)
			On	vctfs.comp_id		 = tct.comp_id			AND
				--vctfs.bra_id		 = tct.bra_id			AND
				vctfs.ct_transaction = tct.ct_transaction

			inner JOIN tbsysDocuments						td						WITH (NOLOCK)
			ON	td.sd_id			 = tct.sd_id

			inner JOIN tbDocumentsFile						tdf						WITH (NOLOCK)
			ON	tdf.sd_id			 = td.sd_id

			inner Join dbo.tbItemTransactionDetails			itd						WITH (NOLOCK)
			ON	itd.comp_id			=	it.comp_id			AND
				--itd.bra_id			=   it.bra_id			AND
				itd.it_transaction	=	it.it_transaction

			LEFT join dbo.tbItem							ti						WITH (NOLOCK)
			on  ti.comp_id			=	it.comp_id			AND
				ti.item_id			=	it.item_id

			LEFT join dbo.[tbsysCurrency]					SC						WITH (NOLOCK)
			on	SC.curr_id			=	it.curr_id

			inner Join #tmpTaxMovements						ttm
			ON	ttm.comp_id			= vctfs.comp_id			AND
				ttm.ct_transaction	= vctfs.ct_transaction

			LEFT Join tbTaxName								ttn						WITH (NOLOCK)
			On  ttn.comp_id			= ttm.comp_id			And
				ttn.tax_id			= ttm.tax_id


		WHERE	tct.comp_id		=		@comp_id
		AND 	tct.ct_taxDate	BETWEEN	@date_from And @date_to
		AND 	(
					(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

					(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
																FROM tbBranchGroupDetail bgd	WITH (NOLOCK)
																WHERE bgd.brag_id = @brag_id))
		)


	----***----------------------------------------------------------------
	----***
	----*** INTERFACE DE VENTAS ( VENTAS_AAAAMM.TXT) REGISTRO TIPO 1
	----*** Longitud : 375
	----***----------------------------------------------------------------

	SELECT	(	'1'+																						--Tipo de Registro
				dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_date,'') +										--Fecha de Comprobante
				dbo.fnSIAP_ConvertString2FIXLength(isnull(td.sd_ARCIBA_DocumentType,'00'),2)+				--Tipo de Comprobante-segun tabla
				dbo.fnSIAP_ConvertString2FIXLength(	CASE
														WHEN dbo.fnSIAP_ConvertString2FIXLength(isnull(tdf.df_Fiscal_IsFiscalPrinter,'0'),1) = 1 THEN 'C'
														ELSE									''
													End ,1)+												--Controlador Fiscal
				dbo.fnSIAP_ConvertString2FIXLength(tdf.df_pointOfSale,4)+									--Punto de Venta
				dbo.fnSIAP_ConvertString2FIXLength(tct.ct_docNumber,20)+									--Nº de Comprobante
				dbo.fnSIAP_ConvertString2FIXLength(tct.ct_docNumber,20)+									--Nº de Comprobante registrado
				dbo.fnSIAP_ConvertString2FIXLength(ttnt.tnt_afip,2)+										--Codigo de doc indentificatorio del comprador	-segun tabla
				dbo.fnSIAP_ConvertString2FIXLength(tc.cust_taxNumber,11)+									--Nº de indentifiacion del comprador			-segun tabla
				dbo.fnSIAP_ConvertString2FIXLength(tc.cust_name,30)+										--Apellido y nombre o denominacion del comprador
				dbo.fnSIAP_ConvertDecimal2String(tct.ct_total,15)+											--Importe Total de la operacion
				dbo.fnSIAP_ConvertDecimal2String(impalt.tm_Total,15)+										--importe total de conceptos que no integran el precio neto gravado
				dbo.fnSIAP_ConvertDecimal2String(	CASE
														WHEN isnull(ttm.percentaje,0) > 0 THEN	isnull(ttm.tm_subtotal,0)*100
														ELSE									0
													End ,15)+												--importe neto gravado
				dbo.fnSIAP_ConvertDecimal2String(ttn.tax_percentage,4) +									--Alicuota de iva aplicable					-segun tabla
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+									--impuesto liquidado
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+									--impuesto liquidado a rni o percepcion a no categorizados
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+									--importe de operaciones exentas
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+									--importe de percepciones o pagos a cta de impuestos nacionales
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+									--importe de percepcion de ingresos brutos
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+									--Importe de percepcion por impuestos municipales
				dbo.fnSIAP_ConvertString2FIXLength('00000000000000',15)+									--Importe de impuestos internos
				dbo.fnSIAP_ConvertString2FIXLength(	case
														when tc.fc_id = 1  THEN	'01'  -- Responsable Inscripto
														when tc.fc_id = 2  THEN	'05'  -- Consumidor Final
														when tc.fc_id = 3  THEN	'06'  -- Monotributista
														when tc.fc_id = 4  THEN	'04'  -- IVA exento
														when tc.fc_id = 7  THEN	'03'  -- IVA no responsable
														when tc.fc_id = 14  THEN	'07'  -- No categorizado
														when tc.fc_id = 15  THEN	'09'  -- Cliente del exterior
														when tc.state_id <> 54  THEN	'08'  -- Proveedor del Exterior	                        	      --
													END,2) +												--Tipo de Responsable		-segun tabla
				dbo.fnSIAP_ConvertString2FIXLength(tc2.curr_symbolFEx,3)+									--Codigo de Moneda-segun tabla
				dbo.fnSIAP_ConvertString2FIXLength('0000000000',10)+										--tipo de cambio
				dbo.fnSIAP_ConvertString2FIXLength(b.alicuotas,1)+											--cantidad de alicuotas de iva
				dbo.fnSIAP_ConvertString2FIXLength('1',1)+													--codigo de operacion
				dbo.fnSIAP_ConvertString2FIXLength(tct.ct_CAI,14)+											--CAI
				dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_payDate,'') +									--Fecha de Vencimiento
				dbo.fnSIAP_ConvertDate2StringAaAAMMDD('','')+												--Fecha de Anulacion de comprobante
				dbo.fnSIAP_ConvertString2FIXLength(tctn.ctn_note1,75)										--Informacion Adicional
		)			[Ventas]






	FROM	tbCommercialTransactions							tct					WITH (NOLOCK)


			Inner Join	vwCommercialTransactions_forSales		vctfs				WITH (NOLOCK)
			On	vctfs.comp_id			= tct.comp_id
			--And vctfs.bra_id			= tct.bra_id
			And vctfs.ct_transaction	= tct.ct_transaction

			LEFT JOIN tbCommercialTransactionNotes				tctn				WITH (NOLOCK)
			ON  tctn.comp_id			= tct.comp_id	 AND
				--tctn.bra_id				= tct.bra_id	 AND
				tctn.ct_transaction		= tct.ct_transaction

			inner JOIN tbsysDocuments							td					WITH (NOLOCK)
			ON	td.sd_id				= tct.sd_id

			Inner Join	tbDocumentsFile							tdf					WITH (NOLOCK)
			On	tdf.comp_id				= tct.comp_id
			--And	tdf.bra_id				= tct.bra_id
			AND tdf.df_id				= tct.df_id

			Inner Join	tbCustomer								tc					WITH (NOLOCK)
			On	tc.comp_id				= tct.comp_id
			And tc.cust_id				= tct.cust_id

			Inner Join	tbsysTaxNumberTypes						ttnt				WITH (NOLOCK)
			On	ttnt.tnt_id				= tc.tnt_id

			LEFT Join #tmpTaxMovements							ttm
			ON	ttm.comp_id				= vctfs.comp_id
			AND ttm.ct_transaction		= vctfs.ct_transaction

			LEFT Join tbTaxName									ttn					WITH (NOLOCK)
			On  ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

			left JOIN #tmpTaxMovementsOtherTaxes				impalt
			ON impalt.ct_transaction	= tct.ct_transaction

			INNER JOIN tbsysCurrency							tc2					WITH (NOLOCK)
				ON	tc2.curr_id			= tc.curr_id

			LEFT JOIN tbDelivery								td2					WITH (NOLOCK)
				ON  td2.comp_id			= tct.comp_id
				AND td2.dl_id			= tct.dl_id

			left Join #tmp										a
				ON  a.ct_transaction		= tct.ct_transaction
				AND a.tax_id				= isnull(ttm.tax_id,0)

			LEFT Join #tmpB										b
				ON  b.ct_transaction		=  isnull(tct.ct_transaction,0)

			INNER JOIN tbsysState								ts					WITH (NOLOCK)
				ON	ts.country_id		= tct.country_id AND
				ts.state_id				= tct.state_id

		WHERE	tct.comp_id		=		@comp_id
		AND 	tct.ct_date	BETWEEN	@date_from And @date_to
		AND 	(
					(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

					(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
																FROM tbBranchGroupDetail bgd	WITH (NOLOCK)
																WHERE bgd.brag_id = @brag_id))
				)



	----***----------------------------------------------------------------
	----***
	----*** INTERFACE DE COMPRAS ( COMPRAS_AAAAMM.TXT) REGISTRO TIPO 1
	----*** Longitud : 369
	----***----------------------------------------------------------------


select (				'1'			+																											--Tipo de Registro
					dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_date,'') +																		--Fecha de Comprobante
					dbo.fnSIAP_ConvertString2FIXLength(isnull(td.sd_ARCIBA_DocumentType,'00'),2)+												--Tipo de Comprobante-segun tabla
					dbo.fnSIAP_ConvertString2FIXLength(	CASE
										WHEN dbo.fnSIAP_ConvertString2FIXLength(isnull(tdf.df_Fiscal_IsFiscalPrinter,'0'),1) = 1 THEN 'C'
										ELSE									''
									End ,1)+																									--Controlador Fiscal
					dbo.fnSIAP_ConvertString2FIXLength(tdf.df_pointOfSale,4)+																	--Punto de Venta
					dbo.fnSIAP_ConvertString2FIXLength(tct.ct_docNumber,20)+																	--Nº de Comprobante
					dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_processingDate,'') +															--fecha de registracion contable
					dbo.fnSIAP_ConvertString2FIXLength('',3)+																					--Codigo de Aduana	-segun tabla
					dbo.fnSIAP_ConvertString2FIXLength('',4)+																					--Codigo de destinacion-segun tabla
					dbo.fnSIAP_ConvertString2FIXLength('',6)+																					--Numero de despacho
					dbo.fnSIAP_ConvertString2FIXLength('',1)+																					--Digito verificador del numero de  despacho
					dbo.fnSIAP_ConvertString2FIXLength(ttnt.tnt_afip,2) +																		--Codigo de doc indentificatorio del vendedor-segun tabla
					dbo.fnSIAP_ConvertString2FIXLength(ts.supp_taxNumber,11) +																	--Nºde Indentifiacion del vendedor-segun tabla
					dbo.fnSIAP_ConvertString2FIXLength(ts.supp_name,30) + 																		--Apellido y nombre o denominacion del vendedor
					dbo.fnSIAP_ConvertDecimal2String(isnull(tct.ct_Total,0)*100,15)+															--Importe Total de la operacion
					dbo.fnSIAP_ConvertDecimal2String(isnull(impalt.tm_Total,0)*100,15)+															--importe total de conceptos que no integran el precio neto gravado
						    (select CASE WHEN isnull(ttm.percentaje,0)*100 > 0 THEN
										dbo.fnSIAP_ConvertDecimal2String(isnull(ttm.tm_subtotal,0)*100,15)
									ELSE
										dbo.fnSIAP_ConvertDecimal2String(0,15)
									End )+																										--importe neto gravado
					dbo.fnSIAP_ConvertString2FIXLength('1050',4)+																				--Alicuota de IVA -segun tabla
					dbo.fnSIAP_ConvertDecimal2String(	CASE
															WHEN isnull(ttm.percentaje,0) > 0 THEN	isnull(ttm.tm_subtotal,0)*100
															ELSE
																dbo.fnSIAP_ConvertDecimal2String(0,15)
														End ,15)+																				--importe neto gravado
					dbo.fnSIAP_ConvertDecimal2String(	CASE
															WHEN isnull(ttm.percentaje,0) > 0 THEN	isnull(ttm.tm_total,0)*100
															ELSE
																dbo.fnSIAP_ConvertDecimal2String(0,15)
														End ,15)+																				--impuesto liquidado
					dbo.fnSIAP_ConvertDecimal2String(0,15)+																	--impuesto liquidado a rni o percepcion a no categorizados
					(select	CASE
								WHEN a.[marca] = 1 AND isnull(ttm.percentaje,0) = 0  THEN
									dbo.fnSIAP_ConvertDecimal2String(isnull(ttm.tm_subtotal,0)*100,15)
								ELSE
									dbo.fnSIAP_ConvertDecimal2String(0,15)
							End )+																												--importe de operaciones exentas
					dbo.fnSIAP_ConvertDecimal2String(0,15)+																						--importe de percepciones o pagos a cta de impuestos nacionales
					dbo.fnSIAP_ConvertDecimal2String(0,15)+																						--importe de percepcion de ingresos brutos
					dbo.fnSIAP_ConvertDecimal2String(0,15)+																						--Importe de percepcion por impuestos municipales
					dbo.fnSIAP_ConvertDecimal2String(0,15)+																						--Importe de impuestos internos
					dbo.fnSIAP_ConvertString2FIXLength(	case
														when ts.fc_id = 1 THEN	'01'  -- Responsable Inscripto
														when ts.fc_id = 2  THEN	'05'  -- Consumidor Final
														when ts.fc_id = 3  THEN	'06'  -- Monotributista
														when ts.fc_id = 4  THEN	'04'  -- IVA exento
														when ts.fc_id = 7  THEN	'03'  -- IVA no responsable
														when ts.fc_id = 14  THEN	'07'  -- No categorizado
														when ts.fc_id = 15  THEN	'09'  -- Cliente del exterior
														when ts.state_id <> 54  THEN	'08'  -- Proveedor del Exterior	                        	      --
													END,2) +																					--Tipo de Responsable		-segun tabla
					dbo.fnSIAP_ConvertString2FIXLength(tc2.curr_symbolFEx,3)+																	--Codigo de Moneda-segun tabla
					dbo.fnSIAP_ConvertString2FIXLength('0000000000',10)+																		--tipo de cambio
					dbo.fnSIAP_ConvertString2FIXLength(isnull(b.alicuotas,'0'),1)+ 																			--cantidad de alicuotas de iva
					dbo.fnSIAP_ConvertString2FIXLength('1',1)+																					--codigo de operacion
					dbo.fnSIAP_ConvertString2FIXLength(tct.ct_CAI,14)+																			--CAI
					dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_payDate,'') +																	--Fecha de Vencimiento
					dbo.fnSIAP_ConvertDate2StringAaAAMMDD('','')+																				--Fecha de Anulacion de comprobante
					dbo.fnSIAP_ConvertString2FIXLength(tctn.ctn_note1,75)																		--Informacion Adicional
			)				[Compras]



	FROM	tbCommercialTransactions							tct				WITH (NOLOCK)

		inner JOIN tbsysDocuments									td				WITH (NOLOCK)
			ON	td.sd_id				= tct.sd_id

--		Inner Join	tbDocumentsFile									tdf				WITH (NOLOCK)
--			On	tdf.comp_id				= tct.comp_id
--			--And	tdf.bra_id				= tct.bra_id
--			AND tdf.df_id				= tct.df_id

		Inner JOIN vwCommercialTransactions_forPurchase				vctfp			WITH (NOLOCK)
			On	vctfp.comp_id			= tct.comp_id
			And vctfp.bra_id			= tct.bra_id
			And vctfp.ct_transaction	= tct.ct_transaction

		LEFT JOIN tbCommercialTransactionNotes						tctn			WITH (NOLOCK)
			ON  tctn.comp_id			= tct.comp_id
			--AND tctn.bra_id				= tct.bra_id
			AND tctn.ct_transaction		= tct.ct_transaction

		LEFT Join #tmpPurchase_TaxMovements							ttm
			ON	ttm.comp_id				= vctfp.comp_id
			AND ttm.ct_transaction		= vctfp.ct_transaction

		left JOIN #tmpPurchase_TaxMovementsOtherTaxes				impalt
			ON impalt.ct_transaction	= tct.ct_transaction

		left Join tbTaxName										ttn				WITH (NOLOCK)
			On  ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

		INNER JOIN tbSupplier 										ts				WITH (NOLOCK)
			ON	ts.comp_id			= tct.comp_id
			AND ts.supp_id			= tct.supp_id

		Inner Join	tbsysTaxNumberTypes								ttnt			WITH (NOLOCK)
			On	ttnt.tnt_id				= ts.tnt_id

		INNER JOIN tbsysCurrency									tc2				WITH (NOLOCK)
			ON	tc2.curr_id			= TS.curr_id

		INNER JOIN tbsysState										ts2				WITH (NOLOCK)
			ON	ts2.country_id		= tct.country_id
			AND ts2.state_id		= tct.state_id


		left Join #tmp												a
		ON  a.ct_transaction		= tct.ct_transaction
		AND a.tax_id				= isnull(ttm.tax_id,0)

		left Join #tmpBPurchase										b
		ON  b.ct_transaction		=  isnull(tct.ct_transaction,0)

	WHERE	tct.comp_id		=		@comp_id
	AND 	tct.ct_taxDate	BETWEEN	@date_from And @date_to
	AND 	(
				(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

				(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
															FROM tbBranchGroupDetail bgd  WITH (NOLOCK)
															WHERE bgd.brag_id = @brag_id))
			)







END

















