	-- -----------------------------------------------------------------------------------------------------





	--***----------------------------------------------------------------
	--***
	--*** INTERFACE DE DETALLE ( DETALLE_AAAAMM.TXT)
	--*** Longitud : 189
	--***----------------------------------------------------------------
	select  CONVERT(CHAR(189),CONVERT(CHAR(2),isnull(td.sd_ARCIBA_DocumentType,'00'))+		--Tipo de comprobante						-segun tabla
							CONVERT(CHAR(1),isnull(tdf.df_Fiscal_IsFiscalPrinter,'')) +		--Controlador Fiscal
							CONVERT(CHAR(8),tct.ct_date,120)+								--Fecha de comprobante
							CONVERT(CHAR(4),isnull(tdf.df_pointOfSale,''))+					--Punto de Venta
							CONVERT(CHAR(8),isnull(tct.ct_docNumber,''))+					--Nº de comprobante
							CONVERT(CHAR(8),isnull(tct.ct_docNumber,''))+					--Nº de comprobante registrado
							CONVERT(CHAR(12),isnull(it.it_qty,0))+							--Cantidad
							CONVERT(CHAR(2),'07') +											--Unidad de medida							-segun tabla
							CONVERT(CHAR(16),isnull(it.it_price,0)) +						--Precio Unitario
							CONVERT(CHAR(15),'0000000000000000') +							--Importe de Bonificacion
							CONVERT(CHAR(16),'00000000000000000') +							--Importe de Ajuste
							CONVERT(CHAR(16),'00000000000000000') +							--subtotal del registro
							dbo.fnSIAP_ConvertDecimal2String(ttn.tax_percentage,4) +								--Alicuota de iva aplicable					-segun tabla
							CONVERT(CHAR(1),'') +											--indicacion de exento,gravado o no gravado
							CONVERT(CHAR(1),'') +											--indicacion de de anulacion
							CONVERT(CHAR(75),isnull(ti.item_desc,''))						--Diseño Libre ,desc
					)[Detalle]



  From		dbo.tbItemTransactions							it


			INNER JOIN tbCommercialTransactions				tct
				ON	tct.comp_id			= it.comp_id
				AND tct.bra_id			= it.bra_id
				AND tct.ct_transaction	= it.ct_transaction

			Inner Join	vwCommercialTransactions_forSales	vctfs
				On	vctfs.comp_id		= tct.comp_id
				And vctfs.bra_id		= tct.bra_id
				And vctfs.ct_transaction = tct.ct_transaction

			inner JOIN tbsysDocuments						td
			ON	td.sd_id			= tct.sd_id

			inner JOIN tbDocumentsFile						tdf
			ON	tdf.sd_id			= td.sd_id

			Left Join dbo.tbItemTransactionDetails			itd
				ON	itd.comp_id			=	it.comp_id
				and	itd.bra_id			=   it.bra_id
				and itd.it_transaction	=	it.it_transaction

			left join dbo.tbItem							ti
				on  ti.comp_id			=	it.comp_id
				AND ti.item_id			=	it.item_id

			left join dbo.[tbsysCurrency]					SC
				on	SC.curr_id			=	it.curr_id

			LEFT JOIN vwTaxMovements_TotalIVATax			vtt
				ON	vtt.comp_id			= it.comp_id
				AND vtt.bra_id			= it.bra_id
				AND vtt.ct_transaction	= it.ct_transaction
				AND vtt.it_transaction	= it.it_transaction

			inner Join #tmpTaxMovements						ttm
				ON	ttm.comp_id			= vctfs.comp_id
				AND ttm.ct_transaction	= vctfs.ct_transaction

			Inner Join tbTaxName							ttn
				On  ttn.comp_id			= ttm.comp_id
				And ttn.tax_id			= ttm.tax_id

		WHERE	tct.comp_id		=		@comp_id
		AND 	tct.ct_taxDate	BETWEEN	@date_from And @date_to
		AND 	(
					(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

					(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
															FROM tbBranchGroupDetail bgd
															WHERE bgd.brag_id = @brag_id))
		)



	----***----------------------------------------------------------------
	----***
	----*** INTERFACE DE VENTAS ( VENTAS_AAAAMM.TXT) REGISTRO TIPO 1
	----*** Longitud : 375
	----***----------------------------------------------------------------

	select  CONVERT(CHAR(375),
							CONVERT(CHAR(1),'1')+													--Tipo de Registro
							dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_date,'') +										--Fecha de Comprobante
							CONVERT(CHAR(2),isnull(td.sd_ARCIBA_DocumentType,'00')) +				--Tipo de Comprobante							-segun tabla
							CONVERT(CHAR(1),isnull(tdf.df_Fiscal_IsFiscalPrinter,''))+				--Controlador Fiscal
							CONVERT(CHAR(4),isnull(tdf.df_pointOfSale,''))+							--Punto de Venta
							CONVERT(CHAR(20),isnull(tct.ct_docNumber,''))+							--Nº de Comprobante
							CONVERT(CHAR(20),isnull(tct.ct_docNumber,''))+							--Nº de Comprobante hasta
							CONVERT(CHAR(2),isnull(ttnt.tnt_afip,'')) +								--Codigo de doc indentificatorio del comprador	-segun tabla
							CONVERT(CHAR(11),isnull(tc.cust_taxNumber,''))+							--Nº de indentifiacion del comprador			-segun tabla
							CONVERT(CHAR(30),Substring(isnull(tc.cust_name,''),1,30))+								--Apellido y nombre o denominacion del comprador
							dbo.fnSIAP_ConvertDecimal2String(tct.ct_total,15)+							--Importe Total de la operacion
							dbo.fnSIAP_ConvertDecimal2String(impalt.tm_Total,15)+						--importe total de conceptos que no integran el precio neto gravado
							dbo.fnSIAP_ConvertDecimal2String(	CASE
																	WHEN isnull(ttm.percentaje,0) > 0 THEN	isnull(ttm.tm_subtotal,0)*100
																	ELSE									0
																End ,15)+												--importe neto gravado
							dbo.fnSIAP_ConvertDecimal2String(ttn.tax_percentage,4) +										--Alicuota de iva aplicable					-segun tabla
							CONVERT(CHAR(15),'000000000000000') +									--impuesto liquidado
							CONVERT(CHAR(15),'000000000000000') +									--impuesto liquidado a rni o percepcion a no categorizados
							CONVERT(CHAR(15),'000000000000000') +									--importe de operaciones exentas
							CONVERT(CHAR(15),'000000000000000') +									--importe de percepciones o pagos a cta de impuestos nacionales
							CONVERT(CHAR(15),'000000000000000') +									--importe de percepcion de ingresos brutos
							CONVERT(CHAR(15),'000000000000000') +									--Importe de percepcion por impuestos municipales
							CONVERT(CHAR(15),'000000000000000') +									--Importe de impuestos internos
							CONVERT(CHAR(2),(	case
													when tc.fc_id = 1  THEN	'01'  -- Responsable Inscripto
													when tc.fc_id = 2  THEN	'05'  -- Consumidor Final
													when tc.fc_id = 3  THEN	'06'  -- Monotributista
													when tc.fc_id = 4  THEN	'04'  -- IVA exento
													when tc.fc_id = 7  THEN	'03'  -- IVA no responsable
													when tc.state_id <> 54  THEN	'08'  -- Proveedor del Exterior
													when tc.fc_id = 14  THEN	'07'  -- No categorizado
													when tc.fc_id = 15  THEN	'09'  -- Cliente del exterior
												END)) +										--Tipo de Responsable		-segun tabla
							CONVERT(CHAR(3),tc2.curr_symbolFEx) +									--Codigo de Moneda			-segun tabla
							CONVERT(CHAR(10),'0000000000') +										--tipo de cambio
							CONVERT(CHAR(1),b.alicuotas) +											--cantidad de alicuotas de iva
							CONVERT(CHAR(1),'1') +													--codigo de operacion
							CONVERT(CHAR(14),isnull(tct.ct_CAI,'')) +								--CAI
							dbo.fnSIAP_ConvertDate2StringAaAAMMDD(tct.ct_payDate,'')+									--Fecha de Vencimiento
							CONVERT(CHAR(8),'        ')	+											--Fecha de Anulacion de comprobante
							CONVERT(CHAR(75),isnull(tctn.ctn_note1,''))								--Informacion Adicional
					)			[Ventas]



	FROM	tbCommercialTransactions							tct


			Inner Join	vwCommercialTransactions_forSales		vctfs
			On	vctfs.comp_id			= tct.comp_id
			And vctfs.bra_id			= tct.bra_id
			And vctfs.ct_transaction	= tct.ct_transaction

			LEFT JOIN tbCommercialTransactionNotes				tctn
			ON  tctn.comp_id			= tct.comp_id	 AND
				--tctn.bra_id				= tct.bra_id	 AND
				tctn.ct_transaction		= tct.ct_transaction

			inner JOIN tbsysDocuments							td
			ON	td.sd_id				= tct.sd_id

			Inner Join	tbDocumentsFile							tdf
			On	tdf.comp_id				= tct.comp_id
			--And	tdf.bra_id				= tct.bra_id
			AND tdf.df_id				= tct.df_id

			Inner Join	tbCustomer								tc
			On	tc.comp_id				= tct.comp_id
			And tc.cust_id				= tct.cust_id

			Inner Join	tbsysTaxNumberTypes						ttnt
			On	ttnt.tnt_id				= tc.tnt_id

			LEFT Join #tmpTaxMovements							ttm
			ON	ttm.comp_id				= vctfs.comp_id
			AND ttm.ct_transaction		= vctfs.ct_transaction

			LEFT Join tbTaxName									ttn
			On  ttn.comp_id				= ttm.comp_id
			And ttn.tax_id				= ttm.tax_id

			left JOIN #tmpTaxMovementsOtherTaxes				impalt
			ON impalt.ct_transaction	= tct.ct_transaction

			INNER JOIN tbsysCurrency							tc2
				ON	tc2.curr_id			= tc.curr_id

			LEFT JOIN tbDelivery								td2
				ON  td2.comp_id			= tct.comp_id
				AND td2.dl_id			= tct.dl_id

			left Join #tmp										a
				ON  a.ct_transaction		= tct.ct_transaction
				AND a.tax_id				= isnull(ttm.tax_id,0)

			LEFT Join #tmpB										b
				ON  b.ct_transaction		=  isnull(tct.ct_transaction,0)

			INNER JOIN tbsysState								ts
				ON	ts.country_id		= tct.country_id AND
				ts.state_id				= tct.state_id

		WHERE	tct.comp_id		=		@comp_id
		AND 	tct.ct_date	BETWEEN	@date_from And @date_to
		AND 	(
					(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

					(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
															FROM tbBranchGroupDetail bgd
															WHERE bgd.brag_id = @brag_id))
				)





	----***----------------------------------------------------------------
	----***
	----*** INTERFACE DE COMPRAS ( COMPRAS_AAAAMM.TXT) REGISTRO TIPO 1
	----*** Longitud : 369
	----***----------------------------------------------------------------


	select  CONVERT(CHAR(369),
							CONVERT(CHAR(1),'1')			+										--Tipo de Registro
							CONVERT(CHAR(8),tct.ct_taxDate,120) +										--Fecha de Comprobante o fecha de oficializacion
							CONVERT(CHAR(2),isnull(td.sd_ARCIBA_DocumentType,'00')) +				--Tipo de Comprobante								-segun tabla
							CONVERT(CHAR(1),isnull(tdf.df_Fiscal_IsFiscalPrinter,'')) +				--Controlador Fiscal
							CONVERT(CHAR(4),isnull(tdf.df_pointOfSale,''))+							--Punto de Venta
							CONVERT(CHAR(20),isnull(tct.ct_docNumber,''))+							--Nº de Comprobante
							CONVERT(CHAR(8),tct.ct_processingDate,120)+								--fecha de registracion contable
							CONVERT(CHAR(3),'')+													--Codigo de Aduana									-segun tabla
							CONVERT(CHAR(4),'')+													--Codigo de destinacion								-segun tabla
							CONVERT(CHAR(6),'')+													--Numero de despacho
							CONVERT(CHAR(1),'')+													--Digito verificador del numero de  despacho
							CONVERT(CHAR(2),isnull(ttnt.tnt_afip,'')) +								--Codigo de doc indentificatorio del vendedor		-segun tabla
							CONVERT(CHAR(11),isnull(ts.supp_taxNumber,''))+							--Nºde Indentifiacion del vendedor					-segun tabla
							CONVERT(CHAR(30),isnull(ts.supp_name,''))+								--Apellido y nombre o denominacion del vendedor
							CONVERT(CHAR(15),isnull(tct.ct_Total,0)*100)+							--Importe Total de la operacion
							CONVERT(CHAR(15),isnull(impalt.tm_Total,0)*100) +						--importe total de conceptos que no integran el precio neto gravado
							CONVERT(CHAR(15),'000000000000000') +									--importe neto gravado
							CONVERT(CHAR(4),'1050') +												--Alicuota de IVA -segun tabla
							CONVERT(CHAR(15),(	CASE
													WHEN isnull(ttm.percentaje,0) > 0 THEN	isnull(ttm.tm_subtotal,0)*100
													ELSE									0
												End ))+						--importe neto gravado
							CONVERT(CHAR(15),(	CASE
													WHEN isnull(ttm.percentaje,0) > 0 THEN	isnull(ttm.tm_total,0)*100
													ELSE									0
												End )) +					--impuesto liquidado
							CONVERT(CHAR(15),'') +													--impuesto liquidado a rni o percepcion a no categorizados
							CONVERT(CHAR(15),'000000000000000') +									--importe de operaciones exentas
							CONVERT(CHAR(15),'') +													--importe de percepciones o pagos a cta de impuestos nacionales
							CONVERT(CHAR(15),'000000000000000') +									--importe de percepcion de ingresos brutos
							CONVERT(CHAR(15),'000000000000000') +									--Importe de percepcion por impuestos municipales
							CONVERT(CHAR(15),'000000000000000') +									--Importe de impuestos internos
								CONVERT(CHAR(2),(	case
														when ts.fc_id = 1		THEN	'01'  -- Responsable Inscripto
														when ts.fc_id = 2		THEN	'05'  -- Consumidor Final
														when ts.fc_id = 3		THEN	'06'  -- Monotributista
														when ts.fc_id = 4		THEN	'04'  -- IVA exento
														when ts.fc_id = 7		THEN	'03'  -- IVA no responsable
														when ts.state_id <> 54  THEN	'08'  -- Proveedor del Exterior
														when ts.fc_id = 14		THEN	'07'  -- No categorizado
														when ts.fc_id = 15		THEN	'09'  -- Cliente del exterior
													 END)) +										--Tipo de Responsable		-segun tabla
							CONVERT(CHAR(3),tc2.curr_symbolFEx) +									--Codigo de Moneda			-segun tabla
							CONVERT(CHAR(10),'0000000000') +										--tipo de cambio
							CONVERT(CHAR(1),b.alicuotas) +											--cantidad de alicuotas de iva
							CONVERT(CHAR(1),'1') +													--codigo de operacion
							CONVERT(CHAR(14),isnull(tct.ct_CAI,'')) +								--CAI
							CONVERT(CHAR(8),tct.ct_payDate,120)+									--Fecha de Vencimiento
							CONVERT(CHAR(8),'        ')	+											--Fecha de Anulacion de comprobante
							CONVERT(CHAR(75),isnull(tctn.ctn_note1,''))								--Informacion Adicional
					)				[Compras]



	FROM	tbCommercialTransactions							tct

	inner JOIN tbsysDocuments									td
		ON	td.sd_id				= tct.sd_id

	Inner Join	tbDocumentsFile									tdf
		On	tdf.comp_id				= tct.comp_id
		And	tdf.bra_id				= tct.bra_id
		AND tdf.df_id				= tct.df_id

	Inner JOIN vwCommercialTransactions_forPurchase vctfp
		On	vctfp.comp_id			= tct.comp_id
		And vctfp.bra_id			= tct.bra_id
		And vctfp.ct_transaction	= tct.ct_transaction

	LEFT JOIN tbCommercialTransactionNotes						tctn
		ON  tctn.comp_id			= tct.comp_id
		--AND tctn.bra_id				= tct.bra_id
		AND tctn.ct_transaction		= tct.ct_transaction
-- NO, recalcula las temporales con respecto a compras o hace otras nuevas y referencialas aca.!
	left JOIN #tmpTaxMovementsOtherTaxes						impalt
		ON impalt.ct_transaction	= tct.ct_transaction

	inner Join #tmpTaxMovements									ttm
		ON	ttm.comp_id				= vctfp.comp_id
		AND ttm.ct_transaction		= vctfp.ct_transaction

	Inner Join tbTaxName										ttn
		On  ttn.comp_id				= ttm.comp_id
		And ttn.tax_id				= ttm.tax_id

	INNER JOIN tbSupplier 										ts
		ON	ts.comp_id			= tct.comp_id
		AND ts.supp_id			= tct.supp_id

	Inner Join	tbsysTaxNumberTypes								ttnt
		On	ttnt.tnt_id				= ts.tnt_id

	INNER JOIN tbsysCurrency									tc2
		ON	tc2.curr_id			= TS.curr_id

	INNER JOIN tbsysState										ts2
		ON	ts2.country_id		= tct.country_id
		AND ts2.state_id			= tct.state_id

--	INNER JOIN tbsysFiscalClass									tfc
--		ON  tfc.state_id		= ts2.state_id AND
--			tfc.country_id		= ts2.country_id

	inner Join #tmpB											b
		ON  b.ct_transaction		=  isnull(tct.ct_transaction,0)

	WHERE	tct.comp_id		=		@comp_id
	AND 	tct.ct_taxDate	BETWEEN	@date_from And @date_to
	AND 	(
				(@brag_id	= -1	AND (@bra_id = -1 OR tct.bra_id = @bra_id)) OR

				(@brag_id	<> -1	AND tct.bra_id IN (	SELECT bgd.bra_id
															FROM tbBranchGroupDetail bgd
															WHERE bgd.brag_id = @brag_id))
			)

*/

GO


-- =============================================
-- Author:		GA
-- Create date: 20/07/22
-- Description:	 Exportación de percepciones de MENDOZA
-- =============================================



CREATE PROCEDURE [dbo].[spSysExportData_Mendoza_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-08-01',
					@date_to			= '2015-08-31',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT
		/*01 -- NUMERO DE RENGLON (Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +

		/*02 - tipo de comprobante 3 */
		--1 Factura
		--2 Nota de Débito
		--3 Recibo
		--4 Nota de Venta al Contado
		--5 Factura Exportación
		--6 Nota Débito para operaciones c/exterior
		--7 Liquidación
		--20 Otros Comprobantes de Débito
		--102 Nota Crédito
		--106 Nota Crédito para operaciones c/exterior
		--120 Otros Comprobantes de Crédito
			CASE
					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'			THEN '005'		-- Factura Exportacion
					WHEN tct.sd_id = 1									THEN '001'		-- Factura
					WHEN tct.sd_id = 4  AND tct.ct_kindOf = 'E'			THEN '006'		-- Nota de debito
					WHEN tct.sd_id = 4									THEN '002'		-- Nota de debito
					WHEN tct.sd_id = 6									THEN '003'		-- Recibo
					--WHEN tct.sd_id = 0								THEN '7'		-- Liquidacion
					--WHEN tct.sd_id = 0								THEN '20'		-- Otros comprobantes de Debito
					WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'			THEN '106'		-- Nota de credito para operaciones con exterior
					WHEN tct.sd_id = 3									THEN '102'		-- Nota de credito
					--WHEN tct.sd_id = 0								THEN '120'		-- Otros comprobantes de credito
			ELSE														'000'
			END + ',' +

		/*03 - LETRA DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_kindOf,1,'') + ',' +
		/*04 - NUMERO DE COMPROBANTE 12 */
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') +
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),8,'0') + ',' +
		--dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE PERCEPCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	12*/
			--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'0') + ',' +
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0)) + ',' +
		/*08 - ALICUOTA	6*/
		   CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2)) + ',' +
		/*09 - MONTO PERCIBIDO 12*/
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0) ) + ',' +

		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ts.state_jurisdiccion,3,'0')


	From tbTaxMovements												ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id		--AND
				--ttn.tax_isSIFERE_Percepciones	= 'True'

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL



	WHERE	tct.comp_id			=		@comp_id											AND
			tct.ct_taxDate		BETWEEN	@date_from AND @date_to								AND
			tct.sd_id						IN		(1,3,4,6)								AND -- Solo Factura, NC y ND
		 	ttn.tax_class		= 113															-- Percepcion IB Mendoza


	GROUP BY	ttm.tax_id,
				ttm.ct_transaction,
				tct.ct_docNumber,
				tct.ct_transaction,
				tct.ct_kindOf,
				tct.sd_id,
				tct.ct_taxDate,
				ttn.sysSICORE_RegimenCode,
				ts.state_jurisdiccion,
				tc.cust_taxNumber,
				vwct.PlusOrMinus,
				tct.ct_pointOfSale

	ORDER BY ttm.ct_transaction

END
GO


-- =============================================
-- Author:		GA
-- Create date: 22/07/22
-- Description:	 Exportación de RETENCIONES de Mendoza
-- =============================================


CREATE PROCEDURE [dbo].[spSysExportData_Mendoza_Retenciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para  todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-01-01',
					@date_to			= '2016-01-01',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------




		SELECT
		/*01 -- NUMERO DE RENGLON (Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +

		/*02 - Origen del Comprobante 1 */

		--1 Comprobante Generado por Software propio del Agente
		--2 Comprobante Generado por Sistema SIRCAR
			dbo.fnSIAP_ConvertString2FIXLength2(1,1,'') + ',' +

			--CASE '?'
			--	WHEN 1	THEN	'1'	--Comprobante Generado por Software propio del Agente
			--	WHEN 2	THEN	'2'	-- Comprobante Generado por Sistema SIRCAR
			--END	+ ',' +

		/*03 - TIPO DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(1,1,'') + ',' +
			--1 Comprobante de Retención
			--2 Comprobante de Anulación de Retención

			--CASE '?'
			--	WHEN 1	THEN	'1'	--Comprobante de Retención
			--	WHEN 2	THEN	'2'	--Comprobante de Anulación de Retención
			--END	+ ',' +

		/*04 - NUMERO DE COMPROBANTE 12 */
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts.supp_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE RETENCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	12*/
			--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'0') + ',' +
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal),2),0)) + ',' +
		/*08 - ALICUOTA	6*/
		   CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2)) + ',' +
		/*09 - MONTO PERCIBIDO 12*/
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total) ,2),0) ) + ',' +

		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			--dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
			dbo.fnSIAP_ConvertString2FIXLength2(101,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(tstate.state_jurisdiccion,3,'0')

			From tbTaxMovements													ttm		WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
				ON	tct.comp_id						= ttm.comp_id		AND
					tct.ct_transaction				= ttm.ct_transaction

			INNER JOIN @tblBranchs												tblb
				ON	tblb.bra_id			= tct.bra_id

			INNER JOIN dbo.vwCommercialTransactions_forPurchase 				vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

			INNER JOIN tbSupplier												ts		WITH (NOLOCK)
				ON  ts.comp_id						= tct.comp_id		AND
					ts.supp_id						= tct.supp_id

			INNER JOIN tbsysTaxNumberTypes										ttnt	WITH (NOLOCK)
				ON	ttnt.tnt_id						= ts.tnt_id

			INNER JOIN tbTaxName												ttn		WITH (NOLOCK)
				ON  ttn.comp_id						= ttm.comp_id		AND
					ttn.tax_id						= ttm.tax_id

			INNER JOIN tbsysTaxClass											ttc		WITH (NOLOCK)
			ON	ttc.tax_class						= ttn.tax_class		AND
				ttc.taxcl_isRetention				= 'True'			AND
				ttc.taxcl_isIB						= 'True'

			INNER JOIN tbsysState												tstate	WITH (NOLOCK)
			ON	tstate.country_id					= ttc.country_id	AND
				tstate.state_id						= ttc.state_id		AND
				NOT tstate.state_jurisdiccion		IS NULL


			WHERE
				tct.comp_id				=  @comp_id							AND
				tct.sd_id				= 106								AND --???????????????
				tct.ct_date				BETWEEN  @date_from AND @date_to	AND
				ttn.tax_class			= 213 -- Retencion IB Mendoza

			GROUP BY
				 ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 tstate.state_jurisdiccion,
				 ts.supp_taxNumber,
				 vwct.PlusOrMinus



END
GO


-- ATENCIÓN , NO SE USA ESTE SP. SE USA EL V2
CREATE PROCEDURE [dbo].[spSysExportData_Misiones_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2000-08-01',
					@date_to			= '2015-08-31',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------

		-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
	SELECT
		DISTINCT	bra_id
		FROM		tbBranchGroupDetail			tbgd	WITH (NOLOCK)
		WHERE		tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT
		/*01 -- NUMERO DE RENGLON(Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +
		/*02 - tipo de comprobante 3 */
			CASE
					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'		THEN '005'		-- Factura Exportacion
					WHEN tct.sd_id = 1								THEN '001'		-- Factura
					WHEN tct.sd_id = 4  AND tct.ct_kindOf = 'E'		THEN '006'		-- Nota de debito
					WHEN tct.sd_id = 4								THEN '002'		-- Nota de debito
					WHEN tct.sd_id = 6								THEN '003'		-- Recibo
					--WHEN tct.sd_id = 0							THEN '7'		-- Liquidacion
				 --	WHEN tct.sd_id = 0								THEN '20'		-- Otros comprobantes de Debito
					WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'		THEN '106'		-- Nota de credito para operaciones con exterior
					WHEN tct.sd_id = 3								THEN '102'		-- Nota de credito
					--WHEN tct.sd_id = 0							THEN '120'		-- Otros comprobantes de credito
			ELSE														 '000'
			END + ',' +
		/*03 - LETRA DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_kindOf,1,'') + ',' +
		/*04 - NUMERO DE COMPROBANTE 12 */
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE PERCEPCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	*/
			dbo.fnStrAllTrim(dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(14,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),14,'')) + ',' +
		/*08 - ALICUOTA	*/
		    dbo.fnStrAllTrim(dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2),6,'')) + ',' +
		/*09 - MONTO PERCIBIDO */
			--dbo.fnSIAP_ConvertString2FIXLength2(Convert(Decimal(12,2),(ISNULL(ttm.tm_total,0) * ISNULL(ttm.percentaje,0)) / 100,2) ,12,'') +  ',' +
			dbo.fnStrAllTrim(dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(14,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0),14,'')) + ',' +
		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ts.state_jurisdiccion,3,'0')

		From tbTaxMovements											ttm		WITH (NOLOCK)

		LEFT JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id		--AND
				--ttn.tax_isSIFERE_Percepciones	= 'True'

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		WHERE	tct.comp_id						=		@comp_id					AND
				tct.ct_taxDate					BETWEEN	@date_from AND @date_to		AND
				tct.sd_id						IN		(1,3,4,6)					AND	-- Solo Factura, NC, ND y RECIBOS
				ttn.tax_class					= 114									-- Percepcion IB MISIONES

		GROUP BY ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 ts.state_jurisdiccion,
				 tc.cust_taxNumber,
				 vwct.PlusOrMinus
		ORDER BY ttm.ct_transaction


END
GO



CREATE PROCEDURE [dbo].[spSysExportData_Misiones_PercepcionesV2]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2000-08-01',
					@date_to			= '2015-08-31',
					@brag_id			= 4
*/
	-- ----------------------------------------------------------

		-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
		SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
		SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
		DECLARE @zeros	VARCHAR(30)
		SET @zeros	= REPLICATE('0', 30)
		DECLARE @spaces VARCHAR(100)
		SET @spaces = REPLICATE(' ', 100)

		DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
		INSERT INTO @tblBranchs
		SELECT
			DISTINCT	bra_id
			FROM		tbBranchGroupDetail			tbgd	WITH (NOLOCK)
			WHERE		tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

		SELECT
		--Campo 1: Fecha.

		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +

		--Campo 2: Tipo de Comprobante: (
		--FA_A/
		--FA_B/
		--FA_C/

		--ND_A/
		--ND_B/
		--ND_C/

		--NC_A/
		--NC_B/
		--NC_C/

		--FCE_A/
		--FCE_B/
		--FCE_C/

		--NDE_A/
		--NDE_B/
		--NDE_C/

		--NCE_A/
		--NCE_B/
		--NCE_C/

		--OTRO)
		CASE
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'A'								THEN 'FA_A'		-- Factura A
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'B'								THEN 'FA_B'		-- Factura B
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'C'								THEN 'FA_C'		-- Factura B

				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'E'								THEN 'FCE_A'	-- Factura Exportacion

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'A'								THEN 'NC_A'		-- Nota de credito A
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'B'								THEN 'NC_B'		-- Nota de credito B
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'C'								THEN 'NC_C'		-- Nota de credito C

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'A'								THEN 'ND_A'		-- Nota de debito A
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'B'								THEN 'ND_B'		-- Nota de debito B
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'C'								THEN 'ND_C'		-- Nota de debito C

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

		ELSE																				 'OTRO'
		END + ',' +

		--Campo 3: Número.

		dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')) + ',' +

		--Campo 4: Razón Social.

		dbo.fnSIAP_ConvertString2FIXLength(tc.cust_name,30) + ',' +

		--Campo 5: CUIT.

		tc.cust_taxNumber + ',' +

		--Campo 6: Monto de la Operación.

		CONVERT(Varchar(16),ISNULL(Convert(Decimal(14,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus) ,2),0) ) + ',' +

		--Campo 7: Alícuota.

		CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2))


		From tbTaxMovements											ttm		WITH (NOLOCK)

		LEFT JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		WHERE	tct.comp_id						=		@comp_id					AND
				tct.ct_taxDate					BETWEEN	@date_from AND @date_to		AND
				tct.sd_id						IN		(1,3,4,6)					AND	-- Solo Factura, NC, ND y RECIBOS
				ttn.tax_class					= 114									-- Percepcion IB MISIONES

		GROUP BY ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 ts.state_jurisdiccion,
				 tc.cust_taxNumber,
				 vwct.PlusOrMinus,
				 tc.cust_name

		ORDER BY ttm.ct_transaction


END
GO



CREATE PROCEDURE [dbo].[spSysExportData_Misiones_PercepcionesV2_NewVersion2023]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2024-02-01',
					@date_to			= '2024-02-29',
					@brag_id			= 4
*/
	-- ----------------------------------------------------------

		-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
		SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
		SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
		DECLARE @zeros	VARCHAR(30)
		SET @zeros	= REPLICATE('0', 30)
		DECLARE @spaces VARCHAR(100)
		SET @spaces = REPLICATE(' ', 100)

		DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
		INSERT INTO @tblBranchs
		SELECT
			DISTINCT	bra_id
			FROM		tbBranchGroupDetail			tbgd	WITH (NOLOCK)
			WHERE		tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

		SELECT
		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 1: Fecha.
		-----------------------------------------------------------------------------------------------------------------------------------------
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 2: Tipo de Comprobante: (
		-----------------------------------------------------------------------------------------------------------------------------------------
		--FA_A/--FA_B/--FA_C/    --ND_A/--ND_B/--ND_C/

		--NC_A/--NC_B/--NC_C/    --FCE_A/--FCE_B/--FCE_C/

		--NDE_A/--NDE_B/--NDE_C/  --NCE_A/--NCE_B/--NCE_C/--OTRO)

		CASE
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'A'								THEN 'FA_A'		-- Factura A
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'B'								THEN 'FA_B'		-- Factura B
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'C'								THEN 'FA_C'		-- Factura B

				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'E'								THEN 'FCE_A'	-- Factura Exportacion

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'A'								THEN 'NC_A'		-- Nota de credito A
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'B'								THEN 'NC_B'		-- Nota de credito B
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'C'								THEN 'NC_C'		-- Nota de credito C

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'A'								THEN 'ND_A'		-- Nota de debito A
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'B'								THEN 'ND_B'		-- Nota de debito B
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'C'								THEN 'ND_C'		-- Nota de debito C

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

		ELSE																				 'OTRO'
		END + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 3: Número.
		-----------------------------------------------------------------------------------------------------------------------------------------

		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') + CONVERT(Varchar(16),dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-',''))) + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 4: Razón Social.
		-----------------------------------------------------------------------------------------------------------------------------------------

		CONVERT(Varchar(100),tc.cust_name) + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 5: CUIT.
		-----------------------------------------------------------------------------------------------------------------------------------------

		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 6: Monto de la Operación.
		-----------------------------------------------------------------------------------------------------------------------------------------

		--CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus) ,2),0) ) + ',' + -- tkt 19726
		CONVERT(Varchar(16),ISNULL(Convert(Decimal(14,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus) ,2),0) ) + ',' +   -- 07/03/24 Fiesa importe mayor por eso se puso 16 de longitud

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 7: Alícuota.
		-----------------------------------------------------------------------------------------------------------------------------------------

		CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2))  + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 8: Tipo de comprobante original
		--Obligatorio - unicamente en caso de que el tipo de comprobante corresponda a una NC
		-----------------------------------------------------------------------------------------------------------------------------------------

		--'****' + CONVERT(Varchar(100),tct.sd_id) + ',' + CONVERT(Varchar(100),tct2.sd_id)+ ',' + CONVERT(Varchar(100),tct2.ct_kindOf) + '****' +

		CASE
			WHEN tct.sd_id = 3	THEN
					CASE
							WHEN tct2.sd_id = 1	AND tct2.ct_kindOf = 'A'								THEN 'FA_A'		-- Factura A
							WHEN tct2.sd_id = 1	AND tct2.ct_kindOf = 'B'								THEN 'FA_B'		-- Factura B
							WHEN tct2.sd_id = 1	AND tct2.ct_kindOf = 'C'								THEN 'FA_C'		-- Factura B

							WHEN tct2.sd_id = 1	AND tct2.ct_kindOf = 'E'								THEN 'FCE_A'	-- Factura Exportacion

							WHEN tct2.sd_id = 3	AND tct2.ct_kindOf = 'A'								THEN 'NC_A'		-- Nota de credito A
							WHEN tct2.sd_id = 3	AND tct2.ct_kindOf = 'B'								THEN 'NC_B'		-- Nota de credito B
							WHEN tct2.sd_id = 3	AND tct2.ct_kindOf = 'C'								THEN 'NC_C'		-- Nota de credito C

							WHEN tct2.sd_id = 3	AND tct2.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

							WHEN tct2.sd_id = 4	AND tct2.ct_kindOf = 'A'								THEN 'ND_A'		-- Nota de debito A
							WHEN tct2.sd_id = 4	AND tct2.ct_kindOf = 'B'								THEN 'ND_B'		-- Nota de debito B
							WHEN tct2.sd_id = 4	AND tct2.ct_kindOf = 'C'								THEN 'ND_C'		-- Nota de debito C

							WHEN tct2.sd_id = 4	AND tct2.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

					ELSE																					 'OTRO'
					END
			ELSE
					' '
			END + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 9:Nro de comprobante original
		--Obligatorio - unicamente en caso de que el tipo de comprobante corresponda a una NC
		-----------------------------------------------------------------------------------------------------------------------------------------

		CASE
		WHEN tct.sd_id = 3	THEN
				dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_pointOfSale,'-','')),4,'0') +
				 CONVERT(Varchar(16),dbo.fnGetOnlyNumbers(replace(tct2.ct_docNumber,'-','')))  	-- Nota de credito
		ELSE
				' '
		END + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------

		---------------------------------------------------------------------------------------------------------------------------------------
		--Campo 10:Fecha de comprobante original
		--Obligatorio - unicamente en caso de que el tipo de comprobante corresponda a una NC
		---------------------------------------------------------------------------------------------------------------------------------------
		CASE
			WHEN tct.sd_id = 3	THEN
				CASE
					WHEN tct2.ct_taxDate IS NOT NULL THEN
						RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct2.ct_taxDate)),2) + '-' +
						RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct2.ct_taxDate)),2) + '-' +
						RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct2.ct_taxDate)),4)
					ELSE
						' '
				END
		ELSE
					' '
		END + ',' +
		---------------------------------------------------------------------------------------------------------------------------------------

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 11:CUIT de comprobante original
		--Obligatorio - unicamente en caso de que el tipo de comprobante corresponda a una NC
		-----------------------------------------------------------------------------------------------------------------------------------------
		CASE
		WHEN tct.sd_id = 3	THEN
				dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc2.cust_taxNumber,'-',''),'.','')),11,'0')
		ELSE
				' '
		END
		-----------------------------------------------------------------------------------------------------------------------------------------

		From tbTaxMovements											ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		OUTER APPLY dbo.fnCommercialTransactions_GETOnlyOneApplyDocument(tct.comp_id, tct.ct_transaction)  tmpa

		LEFT JOIN tbCommercialTransactions							tct2	WITH (NOLOCK)
			ON	tct2.comp_id					= tct.comp_id		AND
				tct2.ct_transaction				= tmpa.ct_transaction_applied

		LEFT JOIN tbCustomer										tc2		WITH (NOLOCK)
			ON	tc2.comp_id						= tct2.comp_id		AND
				tc2.cust_id						= tct2.cust_id

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL



		WHERE	tct.comp_id						=		@comp_id					AND
				tct.ct_taxDate					BETWEEN	@date_from AND @date_to		AND
				tct.sd_id						IN		(1,3,4,6)					AND	-- Solo Factura, NC, ND y RECIBOS
				ttn.tax_class					= 114									-- Percepcion IB MISIONES

		GROUP BY ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 ts.state_jurisdiccion,
				 tc.cust_taxNumber,
				 vwct.PlusOrMinus,
				 tc.cust_name,
				 tct.ct_pointOfSale,
				 tct2.ct_kindOf,
				 tct2.ct_pointOfSale,
				 tct2.ct_docNumber,
				 tct2.ct_taxDate,
				 tc2.cust_taxNumber,
				 tct2.sd_id

		ORDER BY ttm.ct_transaction


END
GO



-- ATENCIÓN , NO SE USA ESTE SP. SE USA EL V2
CREATE PROCEDURE [dbo].[spSysExportData_Misiones_Retenciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2000-01-01',
					@date_to			= '2019-01-01',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	--SELECT
	--		--::01 -- Fecha
	--		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY	,tct.ct_taxDate)),2) + '-' +
	--		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '-' +
	--		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR	,tct.ct_taxDate)),4) + ',' +

	--		--::02 - Constancia
	--		CONVERT(VARCHAR,ISNULL(ttm.tm_docNumber,'')) + ',' +

	--		--::03 - Razon Social
	--		LEFT(CONVERT(VARCHAR(30),dbo.fnGetOnlyAlfaText(ISNULL(ts.supp_name,''))) + @spaces ,30) + ',' +

	--		--::04 - Domicilio
	--		ISNULL(ts.supp_address,'') + ',' +

	--		--::05 - CUIT
	--		ts.supp_taxNumber + ',' +

	--		--::06 - Monto
	--		dbo.fnSIAP_ConvertDecimal2String(Round(ISNULL(tct.ct_Total,0),2),15) + ',' +

	--		--::07 - Alicuota
	--		RIGHT(@zeros   + CONVERT(VARCHAR(4),CONVERT(INT,ISNULL(ttm.percentaje,0)*100)),4)

	--From tbTaxMovements									ttm

	--	LEFT JOIN tbCommercialTransactions				tct
	--		ON	tct.comp_id			= ttm.comp_id		AND
	--			tct.ct_transaction	= ttm.ct_transaction

	--	INNER JOIN tbSupplier							ts
	--		ON  ts.comp_id			= tct.comp_id		AND
	--			ts.supp_id			= tct.supp_id

	--	INNER JOIN tbsysTaxNumberTypes					ttnt
	--		ON	ttnt.tnt_id			= ts.tnt_id

	--	INNER JOIN tbTaxName							ttn
	--		ON  ttn.comp_id			= ttm.comp_id		AND
	--			ttn.tax_id			= ttm.tax_id

	--	INNER JOIN @tblBranchs							tblb
	--		ON	tblb.bra_id			= tct.bra_id

	--WHERE	tct.comp_id		=  @comp_id						AND
	--		tct.sd_id		= 106							AND
	--		tct.ct_date	 BETWEEN  @date_from AND @date_to	AND
	--		ttn.tax_class	= 214

	--GROUP BY	ts.supp_taxNumber,
	--			tct.ct_date,
	--			tct.sd_id,
	--			tct.ct_kindOf,
	--			tct.ct_pointOfSale,
	--			tct.ct_docNumber







	------------------------

	--NUEVO



		SELECT
		/*01 -- NUMERO DE RENGLON (Unico por archivo) ---------5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +

		/*02 - Origen del comprobante : 1 - Por Software , 2 - SIRCAR ---------1*/
			dbo.fnSIAP_ConvertString2FIXLength2('1',1,'') + ',' +
		/*03 - TIPO DEL COMPROBANTE 1 RETENCION,2 ANULACION DE RETENCION ---------1 */
			dbo.fnSIAP_ConvertString2FIXLength2('1',1,'') + ',' +

		/*04 - NUMERO DE COMPROBANTE 12 */
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts.supp_taxNumber ,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE PERCEPCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	*/
		dbo.fnStrAllTrim(dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'')) + ',' +
		/*08 - ALICUOTA	*/
		    dbo.fnStrAllTrim(dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2),6,'')) + ',' +
		/*09 - MONTO PERCIBIDO */
			--dbo.fnSIAP_ConvertString2FIXLength2(Convert(Decimal(12,2),(ISNULL(ttm.tm_total,0) * ISNULL(ttm.percentaje,0)) / 100,2) ,12,'') +  ',' +
			dbo.fnStrAllTrim(dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0),12,'')) + ',' +
		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(tstate.state_jurisdiccion,3,'0')



			From tbTaxMovements													ttm		WITH (NOLOCK)

			LEFT JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
				ON	tct.comp_id						= ttm.comp_id		AND
					tct.ct_transaction				= ttm.ct_transaction

			INNER JOIN dbo.vwCommercialTransactions_forPurchase 				vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

			INNER JOIN tbSupplier												ts		WITH (NOLOCK)
				ON  ts.comp_id						= tct.comp_id		AND
					ts.supp_id						= tct.supp_id

			INNER JOIN tbsysTaxNumberTypes										ttnt	WITH (NOLOCK)
				ON	ttnt.tnt_id						= ts.tnt_id

			INNER JOIN tbTaxName												ttn		WITH (NOLOCK)
				ON  ttn.comp_id						= ttm.comp_id		AND
					ttn.tax_id						= ttm.tax_id		AND
					ttn.tax_isSIFERE_Retenciones	= 'True'

			INNER JOIN tbsysTaxClass											ttc		WITH (NOLOCK)
			ON	ttc.tax_class						= ttn.tax_class		AND
				ttc.taxcl_isRetention				= 'True'			AND
				ttc.taxcl_isIB						= 'True'

			INNER JOIN tbsysState												tstate	WITH (NOLOCK)
			ON	tstate.country_id					= ttc.country_id	AND
				tstate.state_id						= ttc.state_id		AND
				NOT tstate.state_jurisdiccion		IS NULL

			INNER JOIN @tblBranchs												tblb
				ON	tblb.bra_id			= tct.bra_id

			WHERE
				tct.comp_id				=  @comp_id							AND
				tct.sd_id				= 106								AND
				tct.ct_date				BETWEEN  @date_from AND @date_to	AND
				ttn.tax_class			= 214 -- Retencion IB Misiones

			GROUP BY
				 ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 tstate.state_jurisdiccion,
				 ts.supp_taxNumber,
				 vwct.PlusOrMinus









END
GO




CREATE PROCEDURE [dbo].[spSysExportData_Misiones_RetencionesV2]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2000-01-01',
					@date_to			= '2019-01-01',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------
		SELECT
		--Campo 1: Fecha.

		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +

		--Campo 2: Tipo de Comprobante: (
		--FA_A/
		--FA_B/
		--FA_C/

		--ND_A/
		--ND_B/
		--ND_C/

		--NC_A/
		--NC_B/
		--NC_C/

		--FCE_A/
		--FCE_B/
		--FCE_C/

		--NDE_A/
		--NDE_B/
		--NDE_C/

		--NCE_A/
		--NCE_B/
		--NCE_C/

		--OTRO)
		CASE
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'A'								THEN 'FA_A'		-- Factura A
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'B'								THEN 'FA_B'		-- Factura B
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'C'								THEN 'FA_C'		-- Factura B

				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'E'								THEN 'FCE_A'	-- Factura Exportacion

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'A'								THEN 'NC_A'		-- Nota de credito A
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'B'								THEN 'NC_B'		-- Nota de credito B
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'C'								THEN 'NC_C'		-- Nota de credito C

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'A'								THEN 'ND_A'		-- Nota de debito A
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'B'								THEN 'ND_B'		-- Nota de debito B
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'C'								THEN 'ND_C'		-- Nota de debito C

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

		ELSE																				 'OTRO'
		END + ',' +

		--Campo 3: Número.

		dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')) + ',' +

		--Campo 4: Razón Social.

		dbo.fnSIAP_ConvertString2FIXLength(ts.supp_name,30) + ',' +

		--Campo 5: CUIT.

		ts.supp_taxNumber + ',' +

		--Campo 6: Monto de la Operación.

		CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0) ) + ',' +

		--Campo 7: Alícuota.

		CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2))



			From tbTaxMovements													ttm		WITH (NOLOCK)

			LEFT JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
				ON	tct.comp_id						= ttm.comp_id		AND
					tct.ct_transaction				= ttm.ct_transaction

			INNER JOIN dbo.vwCommercialTransactions_forPurchase 				vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

			INNER JOIN tbSupplier												ts		WITH (NOLOCK)
				ON  ts.comp_id						= tct.comp_id		AND
					ts.supp_id						= tct.supp_id

			INNER JOIN tbsysTaxNumberTypes										ttnt	WITH (NOLOCK)
				ON	ttnt.tnt_id						= ts.tnt_id

			INNER JOIN tbTaxName												ttn		WITH (NOLOCK)
				ON  ttn.comp_id						= ttm.comp_id		AND
					ttn.tax_id						= ttm.tax_id

			INNER JOIN tbsysTaxClass											ttc		WITH (NOLOCK)
			ON	ttc.tax_class						= ttn.tax_class		AND
				ttc.taxcl_isRetention				= 'True'			AND
				ttc.taxcl_isIB						= 'True'

			INNER JOIN tbsysState												tstate	WITH (NOLOCK)
			ON	tstate.country_id					= ttc.country_id	AND
				tstate.state_id						= ttc.state_id		AND
				NOT tstate.state_jurisdiccion		IS NULL

			INNER JOIN @tblBranchs												tblb
				ON	tblb.bra_id			= tct.bra_id

			WHERE
				tct.comp_id				=  @comp_id							AND
				tct.sd_id				= 106								AND
				tct.ct_date				BETWEEN  @date_from AND @date_to	AND
				ttn.tax_class			= 214										-- Retencion IB Misiones

			GROUP BY
				 ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 tstate.state_jurisdiccion,
				 ts.supp_taxNumber,
				 vwct.PlusOrMinus,
				 ts.supp_name









END
GO




CREATE PROCEDURE [dbo].[spSysExportData_Misiones_RetencionesV2_NewVersion2023]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2000-01-01',
					@date_to			= '2019-01-01',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------
		SELECT
		--Campo 1: Fecha.

		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +

		--Campo 2: Tipo de Comprobantes: (
		--(Comprobante de Retencion, Comprobante de Anulacion de Retencion)

		CASE
				WHEN tct.sd_id = 106						THEN 'CR'		-- CR Comprobante de Retencion
				WHEN tct.sd_id = 156						THEN 'CAR'		-- CAR Comprobante de Anulacion de Retencion

		ELSE													 ''
		END + ',' +

		--Campo 3: Punto de Venta + Nro de Comprobante

		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') + CONVERT(Varchar(16),dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-',''))) + ',' +

		--Campo 4: Razón Social.

		CONVERT(Varchar(100),ts.supp_name) + ',' +

		--Campo 5: CUIT.

		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts.supp_taxNumber,'-',''),'.','')),11,'0') + ',' +

		--Campo 6: Monto de la Operación.

		--CONVERT(Varchar(17),ISNULL(Convert(Decimal(14,2),SUM(tct.ct_total) ,2),0) ) + ',' + no total de la factura
		CONVERT(Varchar(17),ISNULL(Convert(Decimal(14,2),SUM(ttm.tm_subtotal) ,2),0) ) + ',' + -- valor neto de la ret

		--Campo 7: Alícuota.

		CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2)) + ',' +


		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 8: Tipo de comprobante original CR
		--Obligatorio unicamente en caso de que el tipo de comprobante corresponda a un CAR
		-----------------------------------------------------------------------------------------------------------------------------------------

		CASE
				 --Comprobante de Anulacion de Retencion CAR
				 WHEN tct.sd_id = 156							THEN 'CR'		-- Comprobante de Retencion

		ELSE													''
		END + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 9:Nro de comprobante original
		--Obligatorio unicamente en caso de que el tipo de comprobante corresponda a un CAR
		-----------------------------------------------------------------------------------------------------------------------------------------

		CASE
		WHEN tct.sd_id = 156	THEN
				dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_pointOfSale,'-','')),4,'0') +
				 CONVERT(Varchar(16),dbo.fnGetOnlyNumbers(replace(tct2.ct_docNumber,'-','')))  	--Comprobante de Anulacion de Retencion CAR
		ELSE
				''
		END + ',' +

		-----------------------------------------------------------------------------------------------------------------------------------------

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 10:Fecha de comprobante original
		--Obligatorio unicamente en caso de que el tipo de comprobante corresponda a un CAR
		-----------------------------------------------------------------------------------------------------------------------------------------
		CASE
			WHEN tct.sd_id = 156	THEN
				CASE
					WHEN tct2.ct_taxDate IS NOT NULL THEN
					RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct2.ct_taxDate)),2) + '-' +
					RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct2.ct_taxDate)),2) + '-' +
					RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct2.ct_taxDate)),4)
					ELSE
						' '
				END
		ELSE
					''
		END + ',' +
		-----------------------------------------------------------------------------------------------------------------------------------------

		-----------------------------------------------------------------------------------------------------------------------------------------
		--Campo 11:CUIT de comprobante original
		--Obligatorio unicamente en caso de que el tipo de comprobante corresponda a un CAR
		-----------------------------------------------------------------------------------------------------------------------------------------
		CASE
		WHEN tct.sd_id = 156	THEN
				dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts2.supp_taxNumber,'-',''),'.','')),11,'0')
		ELSE
				''
			END
		-----------------------------------------------------------------------------------------------------------------------------------------



		From tbTaxMovements													ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs												tblb
			ON	tblb.bra_id						= tct.bra_id


		CROSS APPLY dbo.fnCommercialTransactions_GETOnlyOneApplyDocument(tct.comp_id, tct.ct_transaction)  tmpa

		LEFT JOIN tbCommercialTransactions									tct2	WITH (NOLOCK)
			ON	tct2.comp_id					= tct.comp_id		AND
				tct2.ct_transaction				= tmpa.ct_transaction_applied

		INNER JOIN dbo.vwCommercialTransactions_forPurchase 				vwct	WITH (NOLOCK)
		ON  tct.comp_id						= vwct.comp_id		AND
			tct.bra_id						= vwct.bra_id		AND
			tct.ct_transaction				= vwct.ct_transaction

			LEFT JOIN tbSupplier											ts2		WITH (NOLOCK)
		ON	ts2.comp_id						= tct2.comp_id		AND
			ts2.supp_id						= tct2.supp_id

		INNER JOIN tbSupplier												ts		WITH (NOLOCK)
			ON  ts.comp_id						= tct.comp_id		AND
				ts.supp_id						= tct.supp_id

		INNER JOIN tbsysTaxNumberTypes										ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= ts.tnt_id

		INNER JOIN tbTaxName												ttn		WITH (NOLOCK)
			ON  ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id

		INNER JOIN tbsysTaxClass											ttc		WITH (NOLOCK)
		ON	ttc.tax_class						= ttn.tax_class		AND
			ttc.taxcl_isRetention				= 'True'			AND
			ttc.taxcl_isIB						= 'True'

		INNER JOIN tbsysState												tstate	WITH (NOLOCK)
		ON	tstate.country_id					= ttc.country_id	AND
			tstate.state_id						= ttc.state_id		AND
			NOT tstate.state_jurisdiccion		IS NULL



		WHERE
			tct.comp_id				=  @comp_id							AND
			tct.sd_id				= 106								AND
			tct.ct_date				BETWEEN  @date_from AND @date_to	AND
			ttn.tax_class			= 214											-- Retencion IB Misiones

		GROUP BY
				ttm.tax_id,
				ttm.ct_transaction,
				tct.ct_docNumber,
				tct.ct_transaction,
				tct.ct_kindOf,
				tct.sd_id,
				tct.ct_taxDate,
				ttn.sysSICORE_RegimenCode,
				tstate.state_jurisdiccion,
				ts.supp_taxNumber,
				vwct.PlusOrMinus,
				tct.ct_pointOfSale,ts.supp_name,tct2.ct_kindOf,tct2.ct_pointOfSale,tct2.ct_docNumber,tct2.ct_taxDate,ts2.supp_taxNumber



END
GO




CREATE PROCEDURE [dbo].[spSysExportData_Neuquen_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-08-01',
					@date_to			= '2019-08-31',
					@brag_id			= 4
*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
	SELECT
		DISTINCT	bra_id
		FROM		tbBranchGroupDetail			tbgd	WITH (NOLOCK)
		WHERE		tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT
		/*01 -- NUMERO DE RENGLON(Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +
		/*02 - tipo de comprobante 3 */
			CASE
					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'		THEN '005'		-- Factura Exportacion
					WHEN tct.sd_id = 1								THEN '001'		-- Factura
					WHEN tct.sd_id = 4  AND tct.ct_kindOf = 'E'		THEN '006'		-- Nota de debito
					WHEN tct.sd_id = 4								THEN '002'		-- Nota de debito
					WHEN tct.sd_id = 6								THEN '003'		-- Recibo
					--WHEN tct.sd_id = 0							THEN '7'		-- Liquidacion
				 --	WHEN tct.sd_id = 0								THEN '20'		-- Otros comprobantes de Debito
					WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'		THEN '106'		-- Nota de credito para operaciones con exterior
					WHEN tct.sd_id = 3								THEN '102'		-- Nota de credito
					--WHEN tct.sd_id = 0							THEN '120'		-- Otros comprobantes de credito
			ELSE														 '000'
			END + ',' +
		/*03 - LETRA DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_kindOf,1,'') + ',' +
		/*04 - NUMERO DE COMPROBANTE 12 */
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE PERCEPCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	*/
			dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'') + ',' +
		/*08 - ALICUOTA	*/
		    dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2),6,'') + ',' +
		/*09 - MONTO PERCIBIDO */
			--dbo.fnSIAP_ConvertString2FIXLength2(Convert(Decimal(12,2),(ISNULL(ttm.tm_total,0) * ISNULL(ttm.percentaje,0)) / 100,2) ,12,'') +  ',' +
			dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0),12,'') + ',' +
		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ts.state_jurisdiccion,3,'0')


		From tbTaxMovements											ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id		AND
				ttn.tax_isSIFERE_Percepciones	= 'True'

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL



		WHERE	tct.comp_id						=		@comp_id					AND
				tct.ct_taxDate					BETWEEN	@date_from AND @date_to		AND
				tct.sd_id						IN		(1,3,4,6)					AND		 -- Solo Factura, NC, ND y RECIBOS
				ttn.tax_class					= 115										 -- Percepcion IB Neuquen

		GROUP BY ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 ts.state_jurisdiccion,
				 tc.cust_taxNumber,
				 vwct.PlusOrMinus



END











		----::01 -- NUMERO DE RENGLON 5
		--dbo.fnSIAP_ConvertString2FIXLength2( ROW_NUMBER() OVER(ORDER BY tct.ct_transaction), 5,'') +
		--dbo.fnSIAP_ConvertString2FIXLength2( 123456, 5,'') +
		----::02 - tipo de comprobante 3
		--CASE tct.sd_id
		--	WHEN 1	THEN 'FA_' + tct.ct_kindOf
		--	WHEN 3	THEN 'NC_' + tct.ct_kindOf
		--	WHEN 4	THEN 'ND_' + tct.ct_kindOf
		--ELSE
		--	'OTRO'
		--END + ',' +
		----RIGHT(@zeros + CONVERT(VARCHAR(4),tct.ct_pointOfSale),4) + ',' +

		----::03 - LETRA DEL COMPROBANTE 1
		--CONVERT(VARCHAR(15),tct.ct_docNumber) + ',' +

		----::04 - NUMERO DE COMPROBANTE 12
		--LEFT( CONVERT(VARCHAR(30),dbo.fnGetOnlyAlfaText(ISNULL(tc.cust_name,''))) + @spaces ,30) + ',' +

		----::05 - CUIT 11
		--tc.cust_taxNumber + ',' +

		----::06 - FECHA DE PERCEPCION 10
		--RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY	,tct.ct_taxDate)),2) + '/' +
		--RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
		--RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR	,tct.ct_taxDate)),4) + ',' +


		--dbo.fnSIAP_ConvertDecimal2String(ROUND(ISNULL(tct.ct_Total,0),2),15) + ',' +

		----::07 - MONTO SUJETO A PERCECPCION
		--dbo.fnSIAP_ConvertDecimal2String(ROUND(ISNULL(tct.ct_Total,0),2),15) + ',' +

		----::08 - ALICUOTA
		--RIGHT(@zeros   + CONVERT(VARCHAR(4),CONVERT(INT,ISNULL(ttm.percentaje,0)* 100)),4) + ',' +
		----::09 - MONTO PERCIBIDO

		--((ROUND(ISNULL(tct.ct_Total,0),2),15) * (CONVERT(INT,ISNULL(ttm.percentaje,0)*100)) / 100) + ',' +


		----::10 - TIPO DE REGIMEN DE PERCEPCION 3

		----::11 - JURIDICCION 3
		--ts.state_jurisdiccion
GO






-- =============================================
-- Author:		GA
-- Create date: 07/12/21
-- Description:	 Exportación de percepciones de SALTA
-- =============================================

-- ATENCIÓN , NO SE USA ESTE SP. SE USA EL V2

CREATE PROCEDURE [dbo].[spSysExportData_Salta_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-08-01',
					@date_to			= '2019-08-31',
					@brag_id			=4

		*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
	SELECT
		DISTINCT	bra_id
		FROM		tbBranchGroupDetail			tbgd	WITH (NOLOCK)
		WHERE		tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT

		/*01 - FECHA - 8 */
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) +
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) +
		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +

		/*02 - tipo de comprobante 4 */
		CASE
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'A'								THEN 'FA_A'		-- Factura A
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'B'								THEN 'FA_B'		-- Factura B
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'C'								THEN 'FA_C'		-- Factura B

				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'E'								THEN 'FCE_A'	-- Factura Exportacion

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'A'								THEN 'NC_A'		-- Nota de credito A
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'B'								THEN 'NC_B'		-- Nota de credito B
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'C'								THEN 'NC_C'		-- Nota de credito C

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'A'								THEN 'ND_A'		-- Nota de debito A
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'B'								THEN 'ND_B'		-- Nota de debito B
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'C'								THEN 'ND_C'		-- Nota de debito C

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

		ELSE																				 'OTRO'
		END + ',' +


		/*03 - NUMERO DE COMPROBANTE 20 */
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),20,'0') + ',' +

		/*04 - NOMBRE 60 */
		dbo.fnSIAP_ConvertString2FIXLength(tc.cust_name,60) + ',' +

		/*05 - CUIT 11	*/
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ',' +

		/*06 - MONTO 16	*/
		dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(16,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),16,'0') + ',' +

		/*07 - ALICUOTA	5 , 4 y por fuera el '%' */
		--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(5,2),MAX(ttm.percentaje),2),0) , 5, '.' ) + /*'%' +*/ ',' +

		dbo.fnStrPADR(MAX(ttm.percentaje),2,'.') + RIGHT((ISNULL(Convert(Decimal(5,2),MAX(ttm.percentaje),2),0)),3)     + ',' +

		/*08 - IMPORTE 16 */
		dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(16,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0),16,'0')

		From tbTaxMovements											ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		WHERE	tct.comp_id						=		@comp_id					AND
				tct.ct_taxDate					BETWEEN	@date_from AND @date_to		AND
				tct.sd_id						IN		(1,3,4,6)					AND		 -- Solo Factura, NC, ND y RECIBOS
				ttn.tax_class					= 117										 -- Percepcion IB SALTA

		GROUP BY ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tc.cust_name,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 ts.state_jurisdiccion,
				 tc.cust_taxNumber,
				 vwct.PlusOrMinus
		ORDER BY ttm.ct_transaction



END




GO


CREATE PROCEDURE [dbo].[spSysExportData_Salta_PercepcionesV2]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'

	-- ----------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-08-01',
					@date_to			= '2019-08-31',
					@brag_id			=4

	*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
	SELECT
		DISTINCT	bra_id
		FROM		tbBranchGroupDetail			tbgd	WITH (NOLOCK)
		WHERE		tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT

		/*01 - FECHA - 8 */
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) +
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) +
		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + '' +

		/*02 - tipo de comprobante 4 */
		CASE
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'A'								THEN 'FA_A'		-- Factura A
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'B'								THEN 'FA_B'		-- Factura B
				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'C'								THEN 'FA_C'		-- Factura B

				WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'E'								THEN 'FCE_A'	-- Factura Exportacion

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'A'								THEN 'NC_A'		-- Nota de credito A
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'B'								THEN 'NC_B'		-- Nota de credito B
				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'C'								THEN 'NC_C'		-- Nota de credito C

				WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'A'								THEN 'ND_A'		-- Nota de debito A
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'B'								THEN 'ND_B'		-- Nota de debito B
				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'C'								THEN 'ND_C'		-- Nota de debito C

				WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

		ELSE																				 'OTRO'
		END + '' +


		/*03 - NUMERO DE COMPROBANTE 20 */
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),20,'0') + '' +

		/*04 - NOMBRE 60 */
		dbo.fnSIAP_ConvertString2FIXLength(tc.cust_name,60) + '' +

		/*05 - CUIT 11	*/
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + '' +

		/*06 - MONTO 16	*/
		dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(16,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),16,' ') + '' +

		/*07 - ALICUOTA	5 , 4 y por fuera el '%' */
		--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(5,2),MAX(ttm.percentaje),2),0) , 5, '.' ) + /*'%' +*/ ',' +

		--dbo.fnStrPADR(MAX(ttm.percentaje),2,'.') + RIGHT((ISNULL(Convert(Decimal(5,2),MAX(ttm.percentaje),2),0)),3) + '' +

		CASE  WHEN (Convert(Decimal(5,2),MAX(ttm.percentaje))) > 10 THEN
	 			 dbo.fnstrpadl(Convert(Decimal(5,2),MAX(ttm.percentaje),2),5, '0')
			  WHEN (Convert(Decimal(5,2),MAX(ttm.percentaje))) > 1 THEN
				CONVERT(VARCHAR(5), dbo.fnstrpadl(Convert(Decimal(5,2),MAX(ttm.percentaje),2) ,6, '0'))
			  WHEN (Convert(Decimal(5,2),MAX(ttm.percentaje))) = 0.00 THEN
				'00.01'
			 ELSE
			 dbo.fnstrpadl( Convert(Decimal(5,2),MAX(ttm.percentaje),2) ,5, '0')
		END + '' +

		/*08 - IMPORTE 16 */
		dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(16,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0),16,' ')

		From tbTaxMovements											ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL



		WHERE	tct.comp_id						=		@comp_id					AND
				tct.ct_taxDate					BETWEEN	@date_from AND @date_to		AND
				tct.sd_id						IN		(1,3,4,6)					AND		 -- Solo Factura, NC, ND y RECIBOS
				ttn.tax_class					= 117										 -- Percepcion IB SALTA

		GROUP BY ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tc.cust_name,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 ts.state_jurisdiccion,
				 tc.cust_taxNumber,
				 vwct.PlusOrMinus
		ORDER BY ttm.ct_transaction



END
GO


-- =============================================
-- Author:		GA
-- Create date: 01/04/23
-- Description:	 Exportación de percepciones de San Luis
-- =============================================



CREATE PROCEDURE [dbo].[spSysExportData_SanLuis_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
AS

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '1900-01-01',
					@date_to			= '2023-08-31',
					@brag_id			= 4


--DROP TABLE #tmpLeyendaenTop
--DROP TABLE #tmpMainData
*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------




	DECLARE @tblMainData TABLE (Orden INT, sd_id INT, ct_transaction INT, DATOS NVARCHAR(MAX))

		INSERT INTO @tblMainData
		(
			Orden,
			[DATOS]
		)
		VALUES
		(
			1,
			'VERSION.1.0'
		)

		INSERT INTO @tblMainData
		(
			Orden,
			sd_id,
			ct_transaction,
			DATOS
		)
		SELECT
			2,
			tct.sd_id,
			tct.ct_transaction,

			--1 	1 	11 	10 	Fecha del Documento Fiscal 	DD/MM/YYYY
				RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
				RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
				RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ' ' +

			--2 	12 	14 	2 	Tipo Documento Fiscal Origen 	****
				CASE
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'A'								THEN 'FA'		-- Factura A
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'B'								THEN 'FA'		-- Factura B
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'C'								THEN 'FC'		-- Factura C
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'M'								THEN 'FM'		-- Factura M
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'T'								THEN 'FT'		-- Factura T

						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'E'								THEN 'FE'		-- Factura Exportacion

						WHEN tct.sd_id = 3	AND tct2.ct_kindOf = 'A'								THEN 'A '		-- Nota de credito A
						WHEN tct.sd_id = 3	AND tct2.ct_kindOf = 'B'								THEN 'B '		-- Nota de credito B
						WHEN tct.sd_id = 3	AND tct2.ct_kindOf = 'C'								THEN 'C '		-- Nota de credito C
						WHEN tct.sd_id = 3	AND tct2.ct_kindOf = 'M'								THEN 'M '		-- Nota de credito M
						WHEN tct.sd_id = 3	AND tct2.ct_kindOf = 'T'								THEN 'T '		-- Nota de credito T


						--WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

						WHEN tct.sd_id = 4	AND tct2.ct_kindOf = 'A'								THEN 'A '		-- Nota de debito A
						WHEN tct.sd_id = 4	AND tct2.ct_kindOf = 'B'								THEN 'B '		-- Nota de debito B
						WHEN tct.sd_id = 4	AND tct2.ct_kindOf = 'C'								THEN 'C '		-- Nota de debito C
						WHEN tct.sd_id = 4	AND tct2.ct_kindOf = 'M'								THEN 'M '		-- Nota de debito M
						WHEN tct.sd_id = 4	AND tct2.ct_kindOf = 'T'								THEN 'T '		-- Nota de debito T

					--	WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

				ELSE																				REPLICATE(' ', 2)
				END + ' ' +

			--3 	15 	19 	4 	Punto Venta Documento Fiscal Origen 	****

				CASE

						WHEN tct.sd_id = 4	THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_pointOfSale,'-','')),4,'0') 	-- Nota de debito
						WHEN tct.sd_id = 3	THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_pointOfSale,'-','')),4,'0') 	-- Nota de credito
				ELSE														REPLICATE(' ', 4)
				END + ' ' +


			--4 	20 	42 	22 	Número Documento Fiscal Origen 	****

			CASE

						WHEN tct.sd_id = 4	THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_docNumber,'-','')),22,'0')	-- Nota de debito
						WHEN tct.sd_id = 3	THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_docNumber,'-','')),22,'0') 	-- Nota de credito
				ELSE														REPLICATE(' ', 22)
				END + ' ' +

			--5 	43 	46 	3 	Tipo de Documento Fiscal

			CASE
						WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'			THEN '006'		-- Factura de credito electronica
						WHEN tct.sd_id = 1									THEN '002'		-- Factura
						WHEN tct.sd_id = 4									THEN '005'		-- Nota de debito
						--WHEN tct.sd_id = 0								THEN '007'		-- Liquidacion Primaria de granos
						--WHEN tct.sd_id = 0								THEN '008'		-- Liquidacion secundaria de granos
						WHEN tct.sd_id = 3									THEN '003'		-- Nota de credito
				ELSE														'000'
				END + ' ' +

			--6 	47 	50 	3 	Concepto
			CASE
					WHEN ISNULL(ttch.sts_conID,0)		= 1										THEN '001'		-- ART 10 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 2										THEN '002'		-- ART 11 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 3										THEN '003'		-- ART 11 RESOL. 039-DPIP-2020 (CON REBAJA DE ALICUOTA)
					WHEN ISNULL(ttch.sts_conID,0)		= 4										THEN '004'		-- ART 12 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 5										THEN '005'		-- ART 13 INCISO (A) RESOL. 039-DPIP-2020 (SUJETO PERCIBIDO ES DISTRIBUIDOR, MAYORISTA O INTERMEDIARIO)
					WHEN ISNULL(ttch.sts_conID,0)		= 6										THEN '006'		-- ART 13 INCISO (B) RESOL. 039-DPIP-2020 (SUJETO PERCIBIDO ES COMERCIANTE EN LA ETAPA MINORISTA)
					WHEN ISNULL(ttch.sts_conID,0)		= 7										THEN '007'		-- ART 14 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 8										THEN '008'		-- ART 15 INCISO (A) RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 9										THEN '009'		-- ART 15 INCISO (B) RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 10									THEN '010'		-- ART 16 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 11									THEN '011'		-- ART. 17 RESOL 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 12									THEN '012'		-- ART. 17 RESOL 039-DPIP-2020 (AGENTE DE PERCEPCIÓN CUENTE CON ESTABLECIMIENTO RADICADO EN LA PROVINCIA DE SAN LUIS)
					WHEN ISNULL(ttch.sts_conID,0)		= 13									THEN '013'		-- ART 18 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 14									THEN '014'		-- ART 19 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 15									THEN '015'		-- ART 20 RESOL. 039-DPIP-2020
			ELSE																					 '000'
			END + ' ' +
			--7 	51 	54 	3 	Tipo de Sujeto

			CASE
					WHEN ISNULL(ttss.sts_sujID,0)		= 1										THEN '001'		-- PASIBLE DE PERCEPCIÓN
					WHEN ISNULL(ttss.sts_sujID,0)		= 2										THEN '002'		-- DESARROLLA ACTIVIDAD COMPRENDIDA EN LOS ARTS. 190 INCS. A), C) Y D) 191 Y 192 DEL CODIGO TRIBUTARIO (LEY VI-0490-2005) Y MODIFICACIONES
					WHEN ISNULL(ttss.sts_sujID,0)		= 3										THEN '003'		-- EMPRESA INCORPORADA EN EL ANEXO I DE LA RESOLUCIÓN 039-DPIP-2020
					WHEN ISNULL(ttss.sts_sujID,0)		= 4										THEN '004'		-- EXCLUIDO POR CERTIFICADO OTORGADO POR LA DPIP SAN LUIS
					WHEN ISNULL(ttss.sts_sujID,0)		= 5										THEN '005'		-- CONTRIBUYENTE DE CONVENIO MULTILATERAL CON COEFICIENTE PARA SAN LUIS INFERIOR A 0,1000
					WHEN ISNULL(ttss.sts_sujID,0)		= 6										THEN '006'		-- EXENTO, DESGRAVADO O NO ALCANZADO POR EL GRAVAMEN
					WHEN ISNULL(ttss.sts_sujID,0)		= 7										THEN '007'		-- ESTADO NACIONAL, PROVINCIALES Y MUNICIPALES, SUS DEPENDENCIAS, REPARTICIONES AUTÁRQUICAS Y DESCENTRALIZADAS
					WHEN ISNULL(ttss.sts_sujID,0)		= 8										THEN '008'		-- ESTADO NACIONAL, PROVINCIALES Y MUNICIPALES, SUS DEPENDENCIAS, REPARTICIONES AUTÁRQUICAS Y DESCENTRALIZADAS (cuya actividad fundamental consista en la producción y/o comercialización de bienes y/o prestación de servicios que hagan adquirir al mismo carácter comercial y/o industrial.
					WHEN ISNULL(ttss.sts_sujID,0)		= 9										THEN '009'		-- SUJETO QUE DESARROLLA SUS ACTIVIDADES INTEGRAMENTE FUERA DE LA JURISDICCIÓN SAN LUIS
					WHEN ISNULL(ttss.sts_sujID,0)		= 10									THEN '010'		-- CONSUMIDOR FINAL
					WHEN ISNULL(ttss.sts_sujID,0)		= 11									THEN '011'		-- ESTACIÓN DE SERVICIO
					WHEN ISNULL(ttss.sts_sujID,0)		= 12									THEN '012'		-- ESTACIÓN DE SERVICIO (COMISIONISTA O INTERMEDIARIO)
			ELSE																				dbo.fnStrPADR('000',3, ' ')
			END + ' ' +


			--8 	55 	75 	20 	Monto de la Operación

				dbo.fnStrPADR(ISNULL(Convert(Decimal(22,2),SUM(tct.ct_total),2),0),20,' ') + ' ' +

			--9 	76 	96 	20 	Monto sujeto a Percepción

				dbo.fnStrPADR(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_subtotal),2),0),20,' ') + ' ' +

			--10 	97 	102 	5 	Alícuota

				dbo.fnStrPADR(ISNULL(Convert(Decimal(7,1),MAX(ttm.percentaje),7),0),5, ' ') + ' ' +

			--11 	103 	123 	20 	Monto Percibido

				dbo.fnStrPADR(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_total),2),0),20,' ') + ' ' +

			--12 	124 	135 	11 	CUIT del Percibido
				dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ' ' +

			--13 	136 	196 	60 	Apellido y Nombre

				CONVERT(char(60),tc.cust_name) + ' ' +

			--14 	197 	212 	15 	Número de Inscripción

				dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxIBNumber,'-',''),'.','')),15,'0') + ' ' +
			--15 	213 	263 	50 	Domicilio

				dbo.fnStrPADR(tc.cust_address,50,' ') + ' ' +

			--16 	264 	314 	50 	Localidad

				dbo.fnStrPADR(tc.cust_city,50,' ') + ' ' +

			--17 	315 	345 	30 	Provincia

				dbo.fnStrPADR(tys.state_desc,30,' ') + ' ' +

			--18 	346 	350 	4 	Código Postal

				CONVERT(Varchar(4),tc.cust_zip) + ' ' +

			--19 	351 	361 	10 	Fecha Emisión Comprobante 	DD/MM/YYYY
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_date)),4) + ' ' +

			--20 	362 	364 	2 	Tipo Documento Fiscal
			CASE
					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'			THEN 'E '		-- Factura de credito electronica
					WHEN tct.sd_id = 1									THEN 'A '		-- Factura
					WHEN tct.sd_id = 4									THEN 'ND'		-- Nota de debito
					--WHEN tct.sd_id = 0								THEN '007'		-- Liquidacion Primaria de granos
					--WHEN tct.sd_id = 0								THEN '008'		-- Liquidacion secundaria de granos
					WHEN tct.sd_id = 3									THEN 'NC'		-- Nota de credito
			ELSE														'NN'
			END + ' ' +

			--21 	365 	369 	4 	Punto Venta documento Fiscal
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') + ' ' +

			--22 	370 	392 	22 	Número Documento Fiscal 	8 dígitos como emite AFIP

			--dbo.fnStrPADR(replace(tct.ct_docNumber,'-','0') ,22, '0') [DATOS]
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tct.ct_docNumber,'-',''),'.','')),8,'0') [DATOS]

	From tbTaxMovements												ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		OUTER APPLY dbo.fnCommercialTransactions_GETOnlyOneApplyDocument(tct.comp_id, tct.ct_transaction)  tmpa

		LEFT JOIN tbCommercialTransactions							tct2	WITH (NOLOCK)
			ON	tct2.comp_id					= tct.comp_id		AND
				tct2.ct_transaction				= tmpa.ct_transaction_applied

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN tbsysState										tys		WITH (NOLOCK)
		ON		tys.country_id					= tc.country_id AND
				tys.state_id					= tc.state_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id

		LEFT JOIN tbsysTaxSANLUISConceptos							ttch	WITH (NOLOCK)
		ON	ttch.sts_conID						= ttn.sts_conID

		LEFT JOIN tbsysTaxSANLUISTipodeSujeto						ttss	WITH (NOLOCK)
		ON	ttss.sts_sujID						= ISNULL(tc.sts_sujID,ttn.sts_sujID)


		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL



	WHERE	tct.comp_id			=		@comp_id											AND
			tct.ct_taxDate		BETWEEN	@date_from AND @date_to								AND
			tct.sd_id						IN		(1,3,4,6)								AND -- Solo Factura, NC y ND
		 	ttn.tax_class		= 119															-- Percepcion IB SAN LUIS


	GROUP BY	ttm.tax_id,
				ttm.ct_transaction,
				tct.ct_docNumber,
				tct.ct_transaction,
				tct.ct_kindOf,
				tct.sd_id,
				tct.ct_taxDate,
				ttn.sysSICORE_RegimenCode,
				ts.state_jurisdiccion,
				tc.cust_taxNumber,tc.cust_taxIBNumber,
				vwct.PlusOrMinus,
				tct.ct_pointOfSale,tct2.ct_pointOfSale,tct2.ct_docNumber,
				ttch.sts_conID,
				ttss.sts_sujID,
				tc.cust_name,tc.cust_address,tc.cust_city,tys.state_desc,tc.cust_zip,
				tct.ct_date,
				tct2.ct_kindOf

	ORDER BY tct.sd_id, ttm.ct_transaction


SELECT
	tmd.DATOS

	FROM @tblMainData AS tmd
	ORDER BY tmd.Orden, tmd.sd_id, tmd.ct_transaction























