					--WHEN tct.sd_id = 0								THEN '008'		-- Liquidacion secundaria de granos
					WHEN tct.sd_id = 3									THEN 'NC'		-- Nota de credito
			ELSE														'NN'
			END + ' ' +

		--21 	365 	369 	4 	Punto Venta documento Fiscal
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') + ' ' +

		--22 	370 	392 	22 	Número Documento Fiscal 	8 dígitos como emite AFIP

		--dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),22,'0')

		dbo.fnStrPADR(replace(tct.ct_docNumber,'-','') ,22, ' ') AS datos



	From tbTaxMovements												ttm		WITH (NOLOCK)

		LEFT JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN tbsysState										tys		WITH (NOLOCK)
		ON		tys.country_id					= tc.country_id AND
				tys.state_id					= tc.state_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id		--AND
				--ttn.tax_isSIFERE_Percepciones	= 'True'

		LEFT JOIN tbsysTaxSANLUISConceptos							ttch	WITH (NOLOCK)
		ON	ttch.sts_conID						= ttn.sts_conID

		LEFT JOIN tbsysTaxSANLUISTipodeSujeto						ttss	WITH (NOLOCK)
		ON	ttss.sts_sujID						= ISNULL(tc.sts_sujID,ttn.sts_sujID)


		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

	WHERE	tct.comp_id			=		@comp_id											AND
			tct.ct_taxDate		BETWEEN	@date_from AND @date_to								AND
			tct.sd_id						IN		(1,3,4,6)

			--AND -- Solo Factura, NC y ND
		 	--ttn.tax_class		= 119															-- Percepcion IB SAN LUIS


	GROUP BY	ttm.tax_id,
				ttm.ct_transaction,
				tct.ct_docNumber,
				tct.ct_transaction,
				tct.ct_kindOf,
				tct.sd_id,
				tct.ct_taxDate,
				ttn.sysSICORE_RegimenCode,
				ts.state_jurisdiccion,
				tc.cust_taxNumber,
				vwct.PlusOrMinus,
				tct.ct_pointOfSale,
				ttch.sts_conID,
				ttss.sts_sujID,
				tc.cust_name,tc.cust_address,tc.cust_city,tys.state_desc,tc.cust_zip,
				tct.ct_date

	--ORDER BY tct.sd_id, ttm.ct_transaction


	--ORDER

	--TODOS los comprobantes de percepción sobre FACTURAS deben colocarse primero,
	--luego TODOS los comprobantes de percepción sobre NOTAS DE CRÉDITO y
	--por último TODOS los comprobantes de NOTAS DE DÉBITO.


	SELECT 1,2 FROM #tmpMainData





	----------------------------------------------------------------------------------------------------
	----------------------
	-- Con orden y temporales
	----------------------
	----------------------------------------------------------------------------------------------------
	/*

	SELECT
		1						[Orden],
		'Version 1.0'			[Data]
		Into #tmpLeyendaenTop

	UNION

	SELECT		2 				[Orden],
			--1 	1 	11 	10 	Fecha del Documento Fiscal 	DD/MM/YYYY
				RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
				RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
				RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ' ' +

			--2 	12 	14 	2 	Tipo Documento Fiscal Origen 	****
				CASE
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'A'								THEN 'FA'		-- Factura A
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'B'								THEN 'FA'		-- Factura B
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'C'								THEN 'FC'		-- Factura C
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'M'								THEN 'FM'		-- Factura M
						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'T'								THEN 'FT'		-- Factura T

						--WHEN tct.sd_id = 1	AND tct.ct_kindOf = 'E'								THEN 'FE'		-- Factura Exportacion

						WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'A'								THEN 'CA'		-- Nota de credito A
						WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'B'								THEN 'CB'		-- Nota de credito B
						WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'C'								THEN 'CC'		-- Nota de credito C
						WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'M'								THEN 'CM'		-- Nota de credito M
						WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'T'								THEN 'CT'		-- Nota de credito T


						--WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

						WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'A'								THEN 'DA'		-- Nota de debito A
						WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'B'								THEN 'DB'		-- Nota de debito B
						WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'C'								THEN 'DC'		-- Nota de debito C
						WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'M'								THEN 'DM'		-- Nota de debito M
						WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'T'								THEN 'DT'		-- Nota de debito T

					--	WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior

				ELSE																				REPLICATE(' ', 2)
				END + ' ' +
			--3 	15 	19 	4 	Punto Venta Documento Fiscal Origen 	****

				CASE

						WHEN tct.sd_id = 4									THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') 	-- Nota de debito
						WHEN tct.sd_id = 3									THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') 	-- Nota de credito
				ELSE														REPLICATE(' ', 4)
				END + ' ' +


			--4 	20 	42 	22 	Número Documento Fiscal Origen 	****

			CASE

						WHEN tct.sd_id = 4									THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),22,'0')		-- Nota de debito
						WHEN tct.sd_id = 3									THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),22,'0') 	-- Nota de credito
				ELSE														REPLICATE(' ', 22)
				END + ' ' +

			--5 	43 	46 	3 	Tipo de Documento Fiscal

			CASE
						WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'			THEN '006'		-- Factura de credito electronica
						WHEN tct.sd_id = 1									THEN '002'		-- Factura
						WHEN tct.sd_id = 4									THEN '005'		-- Nota de debito
						--WHEN tct.sd_id = 0								THEN '007'		-- Liquidacion Primaria de granos
						--WHEN tct.sd_id = 0								THEN '008'		-- Liquidacion secundaria de granos
						WHEN tct.sd_id = 3									THEN '003'		-- Nota de credito
				ELSE														'000'
				END + ' ' +

			--6 	47 	50 	3 	Concepto


			CASE
					WHEN ISNULL(ttch.sts_conID,0)		= 1										THEN '001'		-- ART 10 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 2										THEN '002'		-- ART 11 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 3										THEN '003'		-- ART 11 RESOL. 039-DPIP-2020 (CON REBAJA DE ALICUOTA)
					WHEN ISNULL(ttch.sts_conID,0)		= 4										THEN '004'		-- ART 12 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 5										THEN '005'		-- ART 13 INCISO (A) RESOL. 039-DPIP-2020 (SUJETO PERCIBIDO ES DISTRIBUIDOR, MAYORISTA O INTERMEDIARIO)
					WHEN ISNULL(ttch.sts_conID,0)		= 6										THEN '006'		-- ART 13 INCISO (B) RESOL. 039-DPIP-2020 (SUJETO PERCIBIDO ES COMERCIANTE EN LA ETAPA MINORISTA)
					WHEN ISNULL(ttch.sts_conID,0)		= 7										THEN '007'		-- ART 14 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 8										THEN '008'		-- ART 15 INCISO (A) RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 9										THEN '009'		-- ART 15 INCISO (B) RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 10									THEN '010'		-- ART 16 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 11									THEN '011'		-- ART. 17 RESOL 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 12									THEN '012'		-- ART. 17 RESOL 039-DPIP-2020 (AGENTE DE PERCEPCIÓN CUENTE CON ESTABLECIMIENTO RADICADO EN LA PROVINCIA DE SAN LUIS)
					WHEN ISNULL(ttch.sts_conID,0)		= 13									THEN '013'		-- ART 18 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 14									THEN '014'		-- ART 19 RESOL. 039-DPIP-2020
					WHEN ISNULL(ttch.sts_conID,0)		= 15									THEN '015'		-- ART 20 RESOL. 039-DPIP-2020
			ELSE																					 '000'
			END + ' ' +
			--7 	51 	54 	3 	Tipo de Sujeto

			CASE
					WHEN ISNULL(ttss.sts_sujID,0)		= 1										THEN '001'		-- PASIBLE DE PERCEPCIÓN
					WHEN ISNULL(ttss.sts_sujID,0)		= 2										THEN '002'		-- DESARROLLA ACTIVIDAD COMPRENDIDA EN LOS ARTS. 190 INCS. A), C) Y D) 191 Y 192 DEL CODIGO TRIBUTARIO (LEY VI-0490-2005) Y MODIFICACIONES
					WHEN ISNULL(ttss.sts_sujID,0)		= 3										THEN '003'		-- EMPRESA INCORPORADA EN EL ANEXO I DE LA RESOLUCIÓN 039-DPIP-2020
					WHEN ISNULL(ttss.sts_sujID,0)		= 4										THEN '004'		-- EXCLUIDO POR CERTIFICADO OTORGADO POR LA DPIP SAN LUIS
					WHEN ISNULL(ttss.sts_sujID,0)		= 5										THEN '005'		-- CONTRIBUYENTE DE CONVENIO MULTILATERAL CON COEFICIENTE PARA SAN LUIS INFERIOR A 0,1000
					WHEN ISNULL(ttss.sts_sujID,0)		= 6										THEN '006'		-- EXENTO, DESGRAVADO O NO ALCANZADO POR EL GRAVAMEN
					WHEN ISNULL(ttss.sts_sujID,0)		= 7										THEN '007'		-- ESTADO NACIONAL, PROVINCIALES Y MUNICIPALES, SUS DEPENDENCIAS, REPARTICIONES AUTÁRQUICAS Y DESCENTRALIZADAS
					WHEN ISNULL(ttss.sts_sujID,0)		= 8										THEN '008'		-- ESTADO NACIONAL, PROVINCIALES Y MUNICIPALES, SUS DEPENDENCIAS, REPARTICIONES AUTÁRQUICAS Y DESCENTRALIZADAS (cuya actividad fundamental consista en la producción y/o comercialización de bienes y/o prestación de servicios que hagan adquirir al mismo carácter comercial y/o industrial.
					WHEN ISNULL(ttss.sts_sujID,0)		= 9										THEN '009'		-- SUJETO QUE DESARROLLA SUS ACTIVIDADES INTEGRAMENTE FUERA DE LA JURISDICCIÓN SAN LUIS
					WHEN ISNULL(ttss.sts_sujID,0)		= 10									THEN '010'		-- CONSUMIDOR FINAL
					WHEN ISNULL(ttss.sts_sujID,0)		= 11									THEN '011'		-- ESTACIÓN DE SERVICIO
					WHEN ISNULL(ttss.sts_sujID,0)		= 12									THEN '012'		-- ESTACIÓN DE SERVICIO (COMISIONISTA O INTERMEDIARIO)
			ELSE																				dbo.fnStrPADR('000',3, ' ')
			END + ' ' +


			--8 	55 	75 	20 	Monto de la Operación

				dbo.fnStrPADR(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0) ,20, ' ') + ' ' +

				--CONVERT(Varchar(20),ISNULL(Convert(Decimal(20,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0) ) + ' ' +
				--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0),22,'') + ' ' +

			--9 	76 	96 	20 	Monto sujeto a Percepción
				--CONVERT(Varchar(20),ISNULL(Convert(Decimal(20,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0)) + ' ' +
				dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus) ,2),0),22,'') + ' ' +
			--10 	97 	102 	5 	Alícuota
			 CONVERT(Varchar(5),ISNULL(Convert(Decimal(7,2),MAX(ttm.percentaje),0),7)) + ' ' +

			--11 	103 	123 	20 	Monto Percibido
				--CONVERT(Varchar(20),ISNULL(Convert(Decimal(20,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0) ) + ' ' +
				dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0),22,'') + ' ' +
			--12 	124 	135 	11 	CUIT del Percibido
				dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ' ' +

			--13 	136 	196 	60 	Apellido y Nombre
			 CONVERT(Varchar(60),tc.cust_name) + ' ' +

			--14 	197 	212 	15 	Número de Inscripción
			 REPLICATE(' ', 15) + ' ' +

			--15 	213 	263 	50 	Domicilio
			 --CONVERT(Varchar(50),tc.cust_address) + ' ' +
			 dbo.fnSIAP_ConvertString2FIXLength2(tc.cust_address,50,'') + ' ' +

			--16 	264 	314 	50 	Localidad
			-- CONVERT(Varchar(50),tc.cust_city) + ' ' +
			 dbo.fnSIAP_ConvertString2FIXLength2(tc.cust_city,50,'') + ' ' +

			--17 	315 	345 	30 	Provincia
			-- CONVERT(Varchar(30),tys.state_desc) + ' ' +
			 dbo.fnSIAP_ConvertString2FIXLength2(tys.state_desc,30,'') + ' ' +
			--18 	346 	350 	4 	Código Postal
			 CONVERT(Varchar(4),tc.cust_zip) + ' ' +

			--19 	351 	361 	10 	Fecha Emisión Comprobante 	DD/MM/YYYY
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_date)),4) + ' ' +

			--20 	362 	364 	2 	Tipo Documento Fiscal
			CASE
						WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'			THEN 'E '		-- Factura de credito electronica
						WHEN tct.sd_id = 1									THEN 'A '		-- Factura
						WHEN tct.sd_id = 4									THEN 'ND'		-- Nota de debito
						--WHEN tct.sd_id = 0								THEN '007'		-- Liquidacion Primaria de granos
						--WHEN tct.sd_id = 0								THEN '008'		-- Liquidacion secundaria de granos
						WHEN tct.sd_id = 3									THEN 'NC'		-- Nota de credito
				ELSE														'NN'
				END + ' ' +

			--21 	365 	369 	4 	Punto Venta documento Fiscal
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') + ' ' +

			--22 	370 	392 	22 	Número Documento Fiscal 	8 dígitos como emite AFIP

			--dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),22,'0')

			dbo.fnStrPADR(replace(tct.ct_docNumber,'-','') ,22, ' ') [Data]


		Into #tmpMainData
		From tbTaxMovements												ttm		WITH (NOLOCK)



			LEFT JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
				ON	tct.comp_id						= ttm.comp_id		AND
					tct.ct_transaction				= ttm.ct_transaction

			INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
				ON  tct.comp_id						= vwct.comp_id		AND
					tct.bra_id						= vwct.bra_id		AND
					tct.ct_transaction				= vwct.ct_transaction

			INNER JOIN tbCustomer										tc		WITH (NOLOCK)
				ON	tc.comp_id						= tct.comp_id		AND
					tc.cust_id						= tct.cust_id

			INNER JOIN tbsysState										tys		WITH (NOLOCK)
			ON		tys.country_id					= tc.country_id AND
					tys.state_id					= tc.state_id

			INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
				ON	ttnt.tnt_id						= tc.tnt_id

			INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
				ON	ttn.comp_id						= ttm.comp_id		AND
					ttn.tax_id						= ttm.tax_id		--AND
					--ttn.tax_isSIFERE_Percepciones	= 'True'

			LEFT JOIN tbsysTaxSANLUISConceptos							ttch	WITH (NOLOCK)
			ON	ttch.sts_conID						= ttn.sts_conID

			LEFT JOIN tbsysTaxSANLUISTipodeSujeto						ttss	WITH (NOLOCK)
			ON	ttss.sts_sujID						= ISNULL(tc.sts_sujID,ttn.sts_sujID)


			INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
				ON	ttc.tax_class					= ttn.tax_class		AND
					ttc.taxcl_isPerception			= 'True'			AND
					ttc.taxcl_isIB					= 'True'

			INNER JOIN tbsysState										ts		WITH (NOLOCK)
				ON	ts.country_id					= ttc.country_id	AND
					ts.state_id						= ttc.state_id		AND
					NOT ts.state_jurisdiccion		IS NULL

			INNER JOIN @tblBranchs										tblb
				ON	tblb.bra_id						= tct.bra_id

		WHERE	tct.comp_id			=		@comp_id											AND
				tct.ct_taxDate		BETWEEN	@date_from AND @date_to								AND
				tct.sd_id						IN		(1,3,4,6)

				--AND -- Solo Factura, NC y ND
		 		--ttn.tax_class		= 119															-- Percepcion IB SAN LUIS


		GROUP BY	ttm.tax_id,
					ttm.ct_transaction,
					tct.ct_docNumber,
					tct.ct_transaction,
					tct.ct_kindOf,
					tct.sd_id,
					tct.ct_taxDate,
					ttn.sysSICORE_RegimenCode,
					ts.state_jurisdiccion,
					tc.cust_taxNumber,
					vwct.PlusOrMinus,
					tct.ct_pointOfSale,
					ttch.sts_conID,
					ttss.sts_sujID,
					tc.cust_name,tc.cust_address,tc.cust_city,tys.state_desc,tc.cust_zip,
					tct.ct_date

	--	ORDER BY tct.sd_id, ttm.ct_transaction


-----------------------------------------------------------------------------------



SELECT tmplt.[Data] FROM #tmpLeyendaenTop tmplt
UNION
SELECT tmpmd.[Data] FROM #tmpMainData tmpmd
--ORDER BY orden


	*/





	*/






END
GO


-- =============================================
-- Author:		GA
-- Create date: 01/04/23
-- Description:	 Exportación de RETENCIONES de San Luis
-- =============================================


CREATE PROCEDURE [dbo].[spSysExportData_SanLuis_Retenciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para  todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2023-04-01',
					@date_to			= '2023-04-30',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------



	DECLARE @tblMainData TABLE (Orden INT, sd_id INT, ct_transaction INT, DATOS NVARCHAR(MAX))

		INSERT INTO @tblMainData
		(
			Orden,
			[DATOS]
		)
		VALUES
		(
			1,
			'VERSION.1.0'
		)

		INSERT INTO @tblMainData
		(
			Orden,
			sd_id,
			ct_transaction,
			DATOS
		)
		SELECT
			2,
			tct.sd_id,
			tct.ct_transaction,


			--1	1	2	1	Identificador de fila
			CONVERT(CHAR(1),'C') + ' ' +

			--'ct relacionado a tax: ' + CONVERT(Varchar,ttm.ct_transaction) +
			--CONVERT(CHAR(1),'//C') + '*' + CONVERT(Varchar,ISNULL(tct.sd_id,0)) + '-'+ CONVERT(Varchar,ISNULL(tct.ct_kindOf,0)) + CONVERT(Varchar,ISNULL(tct.ct_transaction,0)) + '-----comp asociado:' +
			--CONVERT(Varchar,ISNULL(tct2.sd_id,0)) + '-'+ CONVERT(Varchar,ISNULL(tct2.ct_kindOf,0)) + CONVERT(Varchar,ISNULL(tct2.ct_transaction,0)) +

			--2	3	5	2	Tipo de Documento Fiscal

			CASE
						WHEN tct2.sd_id = 101	AND tct2.ct_kindOf = 'A'								THEN 'FC'		-- Factura
						WHEN tct2.sd_id = 101	AND tct2.ct_kindOf = 'B'								THEN 'FC'		-- Factura
						WHEN tct2.sd_id = 101	AND tct2.ct_kindOf = 'C'								THEN 'FC'		-- Factura
						WHEN tct2.sd_id = 101	AND tct2.ct_kindOf = 'M'								THEN 'FC'		-- Factura
						WHEN tct2.sd_id = 101	AND tct2.ct_kindOf = 'T'								THEN 'FC'		-- Factura

						WHEN tct2.sd_id = 101	AND tct2.ct_kindOf = 'E'								THEN 'FC'		-- Factura Exportacion

						WHEN tct2.sd_id = 103	AND tct2.ct_kindOf = 'A'								THEN 'NC'		-- Nota de credito A
						WHEN tct2.sd_id = 103	AND tct2.ct_kindOf = 'B'								THEN 'NC'		-- Nota de credito B
						WHEN tct2.sd_id = 103	AND tct2.ct_kindOf = 'C'								THEN 'NC'		-- Nota de credito C
						WHEN tct2.sd_id = 103	AND tct2.ct_kindOf = 'M'								THEN 'NC'		-- Nota de credito M
						WHEN tct2.sd_id = 103	AND tct2.ct_kindOf = 'T'								THEN 'NC'		-- Nota de credito T


						--WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'								THEN 'NDE_A'	-- Nota de credito para operaciones con exterior

						WHEN tct2.sd_id = 104	AND tct2.ct_kindOf = 'A'								THEN 'ND'		-- Nota de debito A
						WHEN tct2.sd_id = 104	AND tct2.ct_kindOf = 'B'								THEN 'ND'		-- Nota de debito B
						WHEN tct2.sd_id = 104	AND tct2.ct_kindOf = 'C'								THEN 'ND'		-- Nota de debito C
						WHEN tct2.sd_id = 104	AND tct2.ct_kindOf = 'M'								THEN 'ND'		-- Nota de debito M
						WHEN tct2.sd_id = 104	AND tct2.ct_kindOf = 'T'								THEN 'ND'		-- Nota de debito T

					--	WHEN tct.sd_id = 4	AND tct.ct_kindOf = 'E'								THEN 'NCE_A'	-- Nota de debito para operaciones con exterior
					--			FE	FACTURA DE CRÉDITO ELECTRÓNICA
					--LP	LIQUIDACIÓN PRIMARIA DE GRANOS
					--LS	LIQUIDACIÓN SECUNDARIA DE GRANOS
				ELSE																				REPLICATE(' ', 2)
				END + ' ' +


			--3	6	8	2	Tipo Documento Fiscal Origen	*


			CASE
						WHEN tct.sd_id = 103	AND  tct2.sd_id =  101				THEN 'C '		-- Orden de Pago - Factura
						WHEN tct.sd_id = 103	AND  tct2.sd_id =  104				THEN 'C '		-- Orden de Pago - Factura
						WHEN tct.sd_id = 104	AND  tct2.sd_id =  101				THEN 'ND'		-- Nota de debito
						WHEN tct.sd_id = 104	AND  tct2.sd_id =  103				THEN 'ND'		-- Nota de debito

				ELSE																	 '  '
				END + ' ' +

			--4	9	13	4	Punto Venta Documento Fiscal Origen	*

			CASE

						WHEN tct.sd_id = 104		THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_pointOfSale,'-','')),4,'0') 	-- Nota de debito
						WHEN tct.sd_id = 103		THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_pointOfSale,'-','')),4,'0') 	-- Nota de credito
				ELSE														REPLICATE(' ', 4)
				END + ' ' +

			--5	14	36	22	Numero Documento Fiscal Origen	*
			CASE

						WHEN tct.sd_id = 104		THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_docNumber,'-','')),22,'0')		-- Nota de debito
						WHEN tct.sd_id = 103		THEN dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct2.ct_docNumber,'-','')),22,'0') 	-- Nota de credito
				ELSE														REPLICATE(' ', 22)
				END + ' ' +

			--6	37	47	10	Fecha del Documento Fiscal	DD/MM/YYYY

			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ' ' +

			--7	48	52	4	Concepto

			CASE
					WHEN ISNULL(ttch.sts_conEID,0)		= 1										THEN '0001'		-- ALICUOTA GENERAL
					WHEN ISNULL(ttch.sts_conEID,0)		= 2										THEN '0002'		-- ACTIVIDAD DE CONSTRUCCION
					WHEN ISNULL(ttch.sts_conEID,0)		= 3										THEN '0003'		-- OPERACIONES INDIVIDUALIZADAS EN LOS INCISOS C), D), E), F) Y G) DEL ARTICULO 2°
					WHEN ISNULL(ttch.sts_conEID,0)		= 4										THEN '0004'		-- AGENTES INCLUIDOS EN EL ANEXO IV
					WHEN ISNULL(ttch.sts_conEID,0)		= 5										THEN '0005'		-- OPERACIONES INDIVIDUALIZADAS EN EL INCISO O) DEL ARTICULO 2°
					WHEN ISNULL(ttch.sts_conEID,0)		= 6										THEN '0006'		-- OPERACIONES INDIVIDUALIZADAS EN EL INCISO Q) DEL ARTICULO 2°
					WHEN ISNULL(ttch.sts_conEID,0)		= 7										THEN '0007'		-- REGÍMENES ESPECIALES DE CM Y/O ALÍCUOTAS DIFERENCIALES EN EL INCISO E) ARTICULO 11°
			ELSE																					 '0000'
			END + ' ' 	+


			--8	53	73	20	Bruto Pagado

			dbo.fnStrPADR(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_subtotal),2),0),20,' ') + ' ' +

			--9	74	79	5	Base Imponible

			dbo.fnStrPADR(ISNULL(Convert(Decimal(7,1),0,7),0),5, ' ') + ' ' +

			--10	80	100	20	Monto Sujeto a Retención

			dbo.fnStrPADR(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_subtotal),2),0),20,' ') + ' ' +

			--11	101	106	5	Alícuota

			dbo.fnStrPADR(ISNULL(Convert(Decimal(7,1),MAX(ttm.percentaje),7),0),5, ' ') + ' ' +

			--12	107	127	20	Monto Retenido

			dbo.fnStrPADR(ISNULL(Convert(Decimal(22,2),SUM(ttm.tm_total),2),0),20,' ') + ' ' +

			--13	128	139	11	CUIT del Retenido

			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts.supp_taxNumber,'-',''),'.','')),11,'0') + ' ' +

			--14	140	200	60	Apellido y Nombre

			CONVERT(char(60),ts.supp_name) + ' ' +

			--15	201	216	15	Número de Inscripción

			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts.supp_taxIBNumber,'-',''),'.','')),15,'0') + ' ' +

			--16	217	267	50	Domicilio

			dbo.fnStrPADR(ts.supp_address,50,' ') + ' ' +

			--17	268	318	50	Localidad

			dbo.fnStrPADR(ts.supp_city,50,' ') + ' ' +

			--18	319	349	30	Provincia

			dbo.fnStrPADR(tys.state_desc,30,' ') + ' ' +

			--19	350	354	4	Código Postal

			CONVERT(Varchar(4),ts.supp_zip) + ' ' +

			--20	355	375	20	Total DOPRO

			REPLICATE(' ', 20) + ' ' +

			--21	376	386	10	Fecha Emisión Comprobante	DD/MM/YYYY

			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_date)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_date)),4) + ' ' +

			--22	387	389	2	Tipo Documento Fiscal	. En ejemplos le pasa C de comprobante
			CASE
						WHEN tct.sd_id = 101  AND tct.ct_kindOf = 'E'			THEN 'E '		-- Factura de credito electronica
						WHEN tct.sd_id = 101									THEN 'C '		-- Factura
						WHEN tct.sd_id = 104									THEN 'ND'		-- Nota de debito
						WHEN tct.sd_id = 106									THEN 'C '		-- Orde de Pago - Factura
						--WHEN tct.sd_id = 0								THEN '007'		-- Liquidacion Primaria de granos
						--WHEN tct.sd_id = 0								THEN '008'		-- Liquidacion secundaria de granos
						WHEN tct.sd_id = 103									THEN 'NC'		-- Nota de credito
				ELSE															'NN'
				END + ' ' +

			--23	390	394	4	Punto Venta Documento Fiscal

			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') + ' ' +

			--24	395	417	22	Número Documento Fiscal	8 dígitos como lo emite AFIP.

			--dbo.fnStrPADR(replace(tct.ct_docNumber,'-','0') ,22, '0') [DATOS]
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tct.ct_docNumber,'-',''),'.','')),8,'0') [DATOS]


			From tbTaxMovements													ttm		WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
				ON	tct.comp_id						= ttm.comp_id		AND
					tct.ct_transaction				= ttm.ct_transaction

			INNER JOIN @tblBranchs												tblb
				ON	tblb.bra_id			= tct.bra_id

			CROSS APPLY dbo.fnCommercialTransactions_GETOnlyOneApplyDocument(tct.comp_id, tct.ct_transaction)  tmpa

			LEFT JOIN tbCommercialTransactions									tct2	WITH (NOLOCK)
				ON	tct2.comp_id					= tct.comp_id AND
					tct2.ct_transaction				= tmpa.ct_transaction_applied

			INNER JOIN dbo.vwCommercialTransactions_forPurchase 				vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

			INNER JOIN tbSupplier												ts		WITH (NOLOCK)
				ON  ts.comp_id						= tct.comp_id		AND
					ts.supp_id						= tct.supp_id

			INNER JOIN tbsysState												tys		WITH (NOLOCK)
			ON	tys.country_id					= ts.country_id AND
				tys.state_id					= ts.state_id

			INNER JOIN tbsysTaxNumberTypes										ttnt	WITH (NOLOCK)
				ON	ttnt.tnt_id						= ts.tnt_id

			INNER JOIN tbTaxName												ttn		WITH (NOLOCK)
				ON  ttn.comp_id						= ttm.comp_id		AND
					ttn.tax_id						= ttm.tax_id

			LEFT JOIN tbsysTaxSANLUISConceptosEstado 							ttch	WITH (NOLOCK)
				ON	ttch.sts_conEID					= ttn.sts_conEID

			INNER JOIN tbsysTaxClass											ttc		WITH (NOLOCK)
			ON	ttc.tax_class						= ttn.tax_class		AND
				ttc.taxcl_isRetention				= 'True'			AND
				ttc.taxcl_isIB						= 'True'

			INNER JOIN tbsysState												tstate	WITH (NOLOCK)
			ON	tstate.country_id					= ttc.country_id	AND
				tstate.state_id						= ttc.state_id		AND
				NOT tstate.state_jurisdiccion		IS NULL



			WHERE
				tct.comp_id				=  @comp_id							AND
				tct.sd_id				IN (101,103,104,106)								AND -- Solo Factura, NC ,ND y OP
				tct.ct_date				BETWEEN  @date_from AND @date_to	AND
				ttn.tax_class			= 219 -- Retencion IB San Luis

			GROUP BY
				ttm.tax_id,
				ttm.ct_transaction,
				tct.ct_docNumber,
				tct.ct_transaction,tct2.ct_transaction,
				tct.ct_kindOf,
				tct.sd_id,tct2.sd_id,
				tct.ct_taxDate,
				ts.supp_taxNumber,ts.supp_taxIBNumber,
				vwct.PlusOrMinus,
				tct.ct_pointOfSale,tct2.ct_pointOfSale,tct2.ct_kindOf,
				ttch.sts_conEID,
				ts.supp_name,ts.supp_address,ts.supp_city,tys.state_desc,ts.supp_zip,
				tct.ct_date,tct2.ct_docNumber

	ORDER BY tct.sd_id, ttm.ct_transaction


SELECT
	tmd.DATOS

	FROM @tblMainData AS tmd
	ORDER BY tmd.Orden, tmd.sd_id, tmd.ct_transaction


END
GO



-- ATENCIÓN , NO SE USA ESTE SP. SE USA EL type1

CREATE PROCEDURE [dbo].[spSysExportData_SantaFe_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-08-01',
					@date_to			= '2015-08-31',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT
		--::01 -- Fecha
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY	,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '-' +
		RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR	,tct.ct_taxDate)),4) + ',' +

		--::02 - tipo de comprobante
		CASE tct.sd_id
			WHEN 1	THEN 'FA_' + tct.ct_kindOf
			WHEN 3	THEN 'NC_' + tct.ct_kindOf
			WHEN 4	THEN 'ND_' + tct.ct_kindOf
		ELSE
			'OTRO'
		END + ',' +
		--RIGHT(@zeros + CONVERT(VARCHAR(4),tct.ct_pointOfSale),4) + ',' +

		--::03 - Numero
		CONVERT(VARCHAR(15),tct.ct_docNumber) + ',' +

		--::04 - Razon Social
		LEFT( CONVERT(VARCHAR(30),dbo.fnGetOnlyAlfaText(ISNULL(tc.cust_name,''))) + @spaces ,30) + ',' +

		--::05 - CUIT
		tc.cust_taxNumber + ',' +

		--::06 - Monto
		dbo.fnSIAP_ConvertDecimal2String(ROUND(ISNULL(tct.ct_Total,0),2),15) + ',' +

		--::07 - Alicuota
		RIGHT(@zeros   + CONVERT(VARCHAR(4),CONVERT(INT,ISNULL(ttm.percentaje,0)*100)),4)


	From tbTaxMovements												ttm

		LEFT JOIN tbCommercialTransactions							tct
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN tbCustomer										tc
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id		--AND
				--ttn.tax_isSIFERE_Percepciones	= 'True'

		INNER JOIN tbsysTaxClass									ttc
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

	WHERE	tct.comp_id			=		@comp_id											AND
			tct.ct_taxDate		BETWEEN	@date_from AND @date_to								AND
			tct.sd_id			IN		(1,3,4)												AND -- Solo Factura, NC y ND
		 	ttn.tax_class		= 121
	ORDER BY ttm.ct_transaction

END
GO


-- =============================================
-- Author:		GA
-- Create date: 04/03/22
-- Description:	 Exportación de percepciones de SANTA FE
-- =============================================



CREATE PROCEDURE [dbo].[spSysExportData_SantaFe_Percepciones_Type1]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-08-01',
					@date_to			= '2015-08-31',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT
		/*01 -- NUMERO DE RENGLON (Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +

		/*02 - tipo de comprobante 3 */
		--1 Factura
		--2 Nota de Débito
		--3 Recibo
		--4 Nota de Venta al Contado
		--5 Factura Exportación
		--6 Nota Débito para operaciones c/exterior
		--7 Liquidación
		--20 Otros Comprobantes de Débito
		--102 Nota Crédito
		--106 Nota Crédito para operaciones c/exterior
		--120 Otros Comprobantes de Crédito
			CASE
					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'			THEN '005'		-- Factura Exportacion
					WHEN tct.sd_id = 1									THEN '001'		-- Factura
					WHEN tct.sd_id = 4  AND tct.ct_kindOf = 'E'			THEN '006'		-- Nota de debito
					WHEN tct.sd_id = 4									THEN '002'		-- Nota de debito
					WHEN tct.sd_id = 6									THEN '003'		-- Recibo
					--WHEN tct.sd_id = 0								THEN '7'		-- Liquidacion
					--WHEN tct.sd_id = 0								THEN '20'		-- Otros comprobantes de Debito
					WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'			THEN '106'		-- Nota de credito para operaciones con exterior
					WHEN tct.sd_id = 3									THEN '102'		-- Nota de credito
					--WHEN tct.sd_id = 0								THEN '120'		-- Otros comprobantes de credito
			ELSE														'000'
			END + ',' +

		/*03 - LETRA DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_kindOf,1,'') + ',' +
		/*04 - NUMERO DE COMPROBANTE 12 */
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE PERCEPCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	12*/
			--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'0') + ',' +
			CONVERT(Varchar(14),ISNULL(Convert(Decimal(14,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0)) + ',' +
		/*08 - ALICUOTA	6*/
		   CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2)) + ',' +
		/*09 - MONTO PERCIBIDO 12*/
			CONVERT(Varchar(14),ISNULL(Convert(Decimal(14,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0) ) + ',' +

		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(559,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ts.state_jurisdiccion,3,'0')


	From tbTaxMovements												ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id		--AND
				--ttn.tax_isSIFERE_Percepciones	= 'True'

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL



	WHERE	tct.comp_id			=		@comp_id											AND
			tct.ct_taxDate		BETWEEN	@date_from AND @date_to								AND
			tct.sd_id						IN		(1,3,4,6)								AND -- Solo Factura, NC y ND
		 	ttn.tax_class		= 121															-- Percepcion IB Santa Fe


	GROUP BY	ttm.tax_id,
				ttm.ct_transaction,
				tct.ct_docNumber,
				tct.ct_transaction,
				tct.ct_kindOf,
				tct.sd_id,
				tct.ct_taxDate,
				ttn.sysSICORE_RegimenCode,
				ts.state_jurisdiccion,
				tc.cust_taxNumber,
				vwct.PlusOrMinus

	ORDER BY ttm.ct_transaction

END
GO


-- ATENCIÓN , NO SE USA ESTE SP. SE USA EL type1
CREATE PROCEDURE [dbo].[spSysExportData_SantaFe_Retenciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para  todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-01-01',
					@date_to			= '2016-01-01',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT
			1,					--TIPO DE OPERACION -DEJAMOS VALOR 1 POR SER RETENCION
			ttm.tm_cd,			--FECHA DE RETENCION?
			111,				--CODIGO ARTICULO INCISO POR EL QUE RETIENE

			CASE tct.sd_id
				WHEN 1	THEN '01'	--FACTURA
				WHEN 4	THEN '02'	--NOTA DE DEBITO
				WHEN 1	THEN '03'	--ORDEN DE PAGO
				WHEN 1	THEN '04'	--BOLETA DE DEPOSITO
				WHEN 1	THEN '05'	--LIQUIDACION DE PAGO
				WHEN 1	THEN '06'	--CERTIFICADO DE OBRA
				WHEN 1	THEN '07'	--RECIBO
				WHEN 1	THEN '08'	--CONSTANCIA DE RETENCION
				WHEN 1	THEN '09'	--OTRO COMPROBANTE
				WHEN 1	THEN '10'	--REINTEGRO RETENCIONES / PERCEPCIONES
			ELSE
				'09'				--OTRO COMPROBANTE
			END,					--TIPO DE COMPROBANTE

			tct.ct_kindOf,		--LETRA DE COMPROBANTE
			tct.ct_docNumber,	--NUMERO DE COMPROBANTE
			tct.ct_date,		--FECHA DE COMPROBANTE
			tct.ct_total,		--MONTO DE COMPROBANTE


			CASE ts.tnt_id
				WHEN 1	THEN	'3'	--C.U.I.T.
				WHEN 2	THEN	'2'	--C.U.I.L.
				WHEN 9	THEN	'1' --C.D.I.
			END,					--TIPO DE DOCUMENTO

			ts.supp_taxNumber,	--NUMERO DE DOCUMENTO

			1,					--CONDICION FRENTE A INGRESOS BRUTOS

			CASE 1
				WHEN 1 THEN '12345678910'	--SI EN EL CAMPO ANTERIOR ES 1, PONE EL NUMERO, SINO SOLO CEROS
			ELSE
				'0000000000'
			END,				--NUMERO DE INSCRIPCION EN INGRESOSO BRUTOS

			CASE ts.fc_id
				WHEN 1	THEN 1	--RESPONSABLE INSCRIPTO
				WHEN 3	THEN 4	--MONOTRIBUTO
				WHEN 4	THEN 3	--EXCENTO
			ELSE
				0				--NO CORRESPONDE
			END,					--SITUACION FRENTE AL IVA

			1,					--MARCA INSCRIPCION OTROS GRAVAMENES
			1,					--MARCA INSCRIPCION DREL
			111111111.11,		--IMPORTE OTROS GRAVAMENES
			111111111.11,		--IMPORTE IVA
			11111111111.11,		--BASE IMPONIBLE PARA EL CALCULO
			11.11,				--ALICUOTA
			11111111111.11,		--IMPUESTO DETERMINADO
			111111111.11,		--DERECHO REGISTRO E INSPECCION
			11111111111.11,		--MONTO RETENIDO
			111,				--ARTICULO/INCISO PARA EL CALCULO
			1,					--TIPO DE EXENCION
			1111,				--AÑO DE EXENCION
			'AAAAAA',			--NUMERO DE CERTIFICADO DE EXENCION
			'AAAAAAAAAAAA',		--NUMERO DE CERTIFICADO PROPIO



			--::01 -- Fecha
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY	,tct.ct_taxDate)),2) + '-' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '-' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR	,tct.ct_taxDate)),4) + ',' +

			--::02 - Constancia
			CONVERT(VARCHAR,ISNULL(ttm.tm_docNumber,'')) + ',' +

			--::03 - Razon Social
			LEFT(CONVERT(VARCHAR(30),dbo.fnGetOnlyAlfaText(ISNULL(ts.supp_name,''))) + @spaces ,30) + ',' +

			--::04 - Domicilio
			ISNULL(ts.supp_address,'') + ',' +

			--::05 - CUIT
			ts.supp_taxNumber + ',' +

			--::06 - Monto
			dbo.fnSIAP_ConvertDecimal2String(Round(ISNULL(tct.ct_Total,0),2),15) + ',' +

			--::07 - Alicuota
			RIGHT(@zeros   + CONVERT(VARCHAR(4),CONVERT(INT,ISNULL(ttm.percentaje,0)*100)),4)

	From tbTaxMovements									ttm

		LEFT JOIN tbCommercialTransactions				tct
			ON	tct.comp_id			= ttm.comp_id		AND
				tct.ct_transaction	= ttm.ct_transaction

		INNER JOIN tbSupplier							ts
			ON  ts.comp_id			= tct.comp_id		AND
				ts.supp_id			= tct.supp_id

		INNER JOIN tbsysTaxNumberTypes					ttnt
			ON	ttnt.tnt_id			= ts.tnt_id

		INNER JOIN tbTaxName							ttn
			ON  ttn.comp_id			= ttm.comp_id		AND
				ttn.tax_id			= ttm.tax_id

		INNER JOIN @tblBranchs							tblb
			ON	tblb.bra_id			= tct.bra_id

	WHERE	tct.comp_id		=  @comp_id						AND
			tct.sd_id		= 106							AND
			tct.ct_date	 BETWEEN  @date_from AND @date_to	AND
			ttn.tax_class	= 221

	--GROUP BY	ts.supp_taxNumber,
	--			tct.ct_date,
	--			tct.sd_id,
	--			tct.ct_kindOf,
	--			tct.ct_pointOfSale,
	--			tct.ct_docNumber


END
GO


-- =============================================
-- Author:		GA
-- Create date: 04/03/22
-- Description:	 Exportación de RETENCIONES de SANTA FE
-- =============================================


CREATE PROCEDURE [dbo].[spSysExportData_SantaFe_Retenciones_Type1]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para  todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-01-01',
					@date_to			= '2016-01-01',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------




		SELECT
		/*01 -- NUMERO DE RENGLON (Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +

		/*02 - Origen del Comprobante 1 */

		--1 Comprobante Generado por Software propio del Agente
		--2 Comprobante Generado por Sistema SIRCAR
			dbo.fnSIAP_ConvertString2FIXLength2(1,1,'') + ',' +

			--CASE '?'
			--	WHEN 1	THEN	'1'	--Comprobante Generado por Software propio del Agente
			--	WHEN 2	THEN	'2'	-- Comprobante Generado por Sistema SIRCAR
			--END	+ ',' +

		/*03 - TIPO DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(1,1,'') + ',' +
			--1 Comprobante de Retención
			--2 Comprobante de Anulación de Retención

			--CASE '?'
			--	WHEN 1	THEN	'1'	--Comprobante de Retención
			--	WHEN 2	THEN	'2'	--Comprobante de Anulación de Retención
			--END	+ ',' +

		/*04 - NUMERO DE COMPROBANTE 12 */
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts.supp_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE RETENCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	12*/
			--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'0') + ',' +
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal),2),0)) + ',' +
		/*08 - ALICUOTA	6*/
		   CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2)) + ',' +
		/*09 - MONTO PERCIBIDO 12*/
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total) ,2),0) ) + ',' +

		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(515,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(tstate.state_jurisdiccion,3,'0')

			From tbTaxMovements													ttm		WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
				ON	tct.comp_id						= ttm.comp_id		AND
					tct.ct_transaction				= ttm.ct_transaction

			INNER JOIN @tblBranchs												tblb
				ON	tblb.bra_id						= tct.bra_id

			INNER JOIN dbo.vwCommercialTransactions_forPurchase 				vwct	WITH (NOLOCK)
			ON  tct.comp_id							= vwct.comp_id		AND
				tct.bra_id							= vwct.bra_id		AND
				tct.ct_transaction					= vwct.ct_transaction

			INNER JOIN tbSupplier												ts		WITH (NOLOCK)
				ON  ts.comp_id						= tct.comp_id		AND
					ts.supp_id						= tct.supp_id

			INNER JOIN tbsysTaxNumberTypes										ttnt	WITH (NOLOCK)
				ON	ttnt.tnt_id						= ts.tnt_id

			INNER JOIN tbTaxName												ttn		WITH (NOLOCK)
				ON  ttn.comp_id						= ttm.comp_id		AND
					ttn.tax_id						= ttm.tax_id

			INNER JOIN tbsysTaxClass											ttc		WITH (NOLOCK)
			ON	ttc.tax_class						= ttn.tax_class		AND
				ttc.taxcl_isRetention				= 'True'			AND
				ttc.taxcl_isIB						= 'True'

			INNER JOIN tbsysState												tstate	WITH (NOLOCK)
			ON	tstate.country_id					= ttc.country_id	AND
				tstate.state_id						= ttc.state_id		AND
				NOT tstate.state_jurisdiccion		IS NULL



			WHERE
				tct.comp_id				=  @comp_id							AND
				tct.sd_id				= 106								AND --???????????????
				tct.ct_date				BETWEEN  @date_from AND @date_to	AND
				ttn.tax_class			= 221 -- Retencion IB Santa Fe

			GROUP BY
				 ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 tstate.state_jurisdiccion,
				 ts.supp_taxNumber,
				 vwct.PlusOrMinus



END
GO


-- =====================================================================
-- Author:		GA
-- Create date: 13/05/24
-- Description:	 Exportación de percepciones de Santiago del Estero
-- =====================================================================



CREATE PROCEDURE [dbo].[spSysExportData_SantiagodelEstero_Percepciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As

BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-08-01',
					@date_to			= '2015-08-31',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------

	SELECT
		/*01 -- NUMERO DE RENGLON (Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +

		/*02 - tipo de comprobante 3 */
		--1 Factura
		--2 Nota de Débito
		--3 Recibo
		--4 Nota de Venta al Contado
		--5 Factura Exportación
		--6 Nota Débito para operaciones c/exterior
		--7 Liquidación
		--20 Otros Comprobantes de Débito
		--102 Nota Crédito
		--106 Nota Crédito para operaciones c/exterior
		--120 Otros Comprobantes de Crédito
			CASE
					WHEN tct.sd_id = 1  AND tct.ct_kindOf = 'E'			THEN '005'		-- Factura Exportacion
					WHEN tct.sd_id = 1									THEN '001'		-- Factura
					WHEN tct.sd_id = 4  AND tct.ct_kindOf = 'E'			THEN '006'		-- Nota de debito
					WHEN tct.sd_id = 4									THEN '002'		-- Nota de debito
					WHEN tct.sd_id = 6									THEN '003'		-- Recibo
					--WHEN tct.sd_id = 0								THEN '7'		-- Liquidacion
					--WHEN tct.sd_id = 0								THEN '20'		-- Otros comprobantes de Debito
					WHEN tct.sd_id = 3	AND tct.ct_kindOf = 'E'			THEN '106'		-- Nota de credito para operaciones con exterior
					WHEN tct.sd_id = 3									THEN '102'		-- Nota de credito
					--WHEN tct.sd_id = 0								THEN '120'		-- Otros comprobantes de credito
			ELSE														'000'
			END + ',' +

		/*03 - LETRA DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(tct.ct_kindOf,1,'') + ',' +
		/*04 - NUMERO DE COMPROBANTE 12 */
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_pointOfSale,'-','')),4,'0') +
		dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),8,'0') + ',' +
		--dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(tc.cust_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE PERCEPCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	12*/
			--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'0') + ',' +
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0)) + ',' +
		/*08 - ALICUOTA	6*/
		   CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2)) + ',' +
		/*09 - MONTO PERCIBIDO 12*/
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total * vwct.PlusOrMinus) ,2),0) ) + ',' +

		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(ts.state_jurisdiccion,3,'0')


	From tbTaxMovements												ttm		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions							tct		WITH (NOLOCK)
			ON	tct.comp_id						= ttm.comp_id		AND
				tct.ct_transaction				= ttm.ct_transaction

		INNER JOIN @tblBranchs										tblb
			ON	tblb.bra_id						= tct.bra_id

		INNER JOIN dbo.vwCommercialTransactions_forSales			vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

		INNER JOIN tbCustomer										tc		WITH (NOLOCK)
			ON	tc.comp_id						= tct.comp_id		AND
				tc.cust_id						= tct.cust_id

		INNER JOIN dbo.tbsysTaxNumberTypes							ttnt	WITH (NOLOCK)
			ON	ttnt.tnt_id						= tc.tnt_id

		INNER JOIN tbTaxName										ttn		WITH (NOLOCK)
			ON	ttn.comp_id						= ttm.comp_id		AND
				ttn.tax_id						= ttm.tax_id		--AND
				--ttn.tax_isSIFERE_Percepciones	= 'True'

		INNER JOIN tbsysTaxClass									ttc		WITH (NOLOCK)
			ON	ttc.tax_class					= ttn.tax_class		AND
				ttc.taxcl_isPerception			= 'True'			AND
				ttc.taxcl_isIB					= 'True'

		INNER JOIN tbsysState										ts		WITH (NOLOCK)
			ON	ts.country_id					= ttc.country_id	AND
				ts.state_id						= ttc.state_id		AND
				NOT ts.state_jurisdiccion		IS NULL



	WHERE	tct.comp_id			=		@comp_id											AND
			tct.ct_taxDate		BETWEEN	@date_from AND @date_to								AND
			tct.sd_id						IN		(1,3,4,6)								AND -- Solo Factura, NC y ND
		 	ttn.tax_class		= 122															-- Percepcion IB Santiago del Estero


	GROUP BY	ttm.tax_id,
				ttm.ct_transaction,
				tct.ct_docNumber,
				tct.ct_transaction,
				tct.ct_kindOf,
				tct.sd_id,
				tct.ct_taxDate,
				ttn.sysSICORE_RegimenCode,
				ts.state_jurisdiccion,
				tc.cust_taxNumber,
				vwct.PlusOrMinus,
				tct.ct_pointOfSale

	ORDER BY ttm.ct_transaction

END
GO


