-- Author:		GA
-- Create date: 13/05/24
-- Description:	 Exportación de RETENCIONES de Santiago del Estero
-- ===============================================================================


CREATE PROCEDURE [dbo].[spSysExportData_SantiagodelEstero_Retenciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
As


BEGIN

	SET NOCOUNT ON

	SET DATEFORMAT 'YMD'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para  todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
		DECLARE		@comp_id			INT,
					@lang_id			INT,
					@bra_id				INT,
					@date_from			DATETIME,
					@date_to			DATETIME,
					@brag_id			INT

		SELECT		@comp_id			= 1,
					@lang_id			= 2,
					@bra_id				= 1,
					@date_from			= '2009-01-01',
					@date_to			= '2016-01-01',
					@brag_id			= 4
	*/
	-- ----------------------------------------------------------



	-- -----------------------------------------------------------------
	-- Varios
	-- -----------------------------------------------------------------
	SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
	SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
	DECLARE @zeros	VARCHAR(30)
	SET @zeros	= REPLICATE('0', 30)
	DECLARE @spaces VARCHAR(100)
	SET @spaces = REPLICATE(' ', 100)

	DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
	INSERT INTO @tblBranchs
		SELECT DISTINCT	bra_id
			FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
			WHERE tbgd.brag_id = @brag_id
	-- -----------------------------------------------------------------




		SELECT
		/*01 -- NUMERO DE RENGLON (Unico por archivo) 5  */
			dbo.fnSIAP_ConvertString2FIXLength2(ROW_NUMBER() OVER(ORDER BY tct.ct_transaction),5,'0') + ',' +

		/*02 - Origen del Comprobante 1 */

		--1 Comprobante Generado por Software propio del Agente
		--2 Comprobante Generado por Sistema SIRCAR
			dbo.fnSIAP_ConvertString2FIXLength2(1,1,'') + ',' +

			--CASE '?'
			--	WHEN 1	THEN	'1'	--Comprobante Generado por Software propio del Agente
			--	WHEN 2	THEN	'2'	-- Comprobante Generado por Sistema SIRCAR
			--END	+ ',' +

		/*03 - TIPO DEL COMPROBANTE 1 */
			dbo.fnSIAP_ConvertString2FIXLength2(1,1,'') + ',' +
			--1 Comprobante de Retención
			--2 Comprobante de Anulación de Retención

			--CASE '?'
			--	WHEN 1	THEN	'1'	--Comprobante de Retención
			--	WHEN 2	THEN	'2'	--Comprobante de Anulación de Retención
			--END	+ ',' +

		/*04 - NUMERO DE COMPROBANTE 12 */
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(tct.ct_docNumber,'-','')),12,'0') + ',' +
		/*05 - CUIT 11	*/
			dbo.fnSIAP_ConvertString2FIXLength2(dbo.fnGetOnlyNumbers(replace(replace(ts.supp_taxNumber,'-',''),'.','')),11,'0') + ',' +
		/*06 - FECHA DE RETENCION 10 */
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(DAY,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(2),DATEPART(MONTH,tct.ct_taxDate)),2) + '/' +
			RIGHT(@zeros + CONVERT(VARCHAR(4),DATEPART(YEAR,tct.ct_taxDate)),4) + ',' +
		/*07 - MONTO SUJETO A PERCECPCION	12*/
			--dbo.fnSIAP_ConvertString2FIXLength2(ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal * vwct.PlusOrMinus),2),0),12,'0') + ',' +
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_subtotal),2),0)) + ',' +
		/*08 - ALICUOTA	6*/
		   CONVERT(Varchar(6),ISNULL(Convert(Decimal(6,2),MAX(ttm.percentaje),0),2)) + ',' +
		/*09 - MONTO PERCIBIDO 12*/
			CONVERT(Varchar(12),ISNULL(Convert(Decimal(12,2),SUM(ttm.tm_total) ,2),0) ) + ',' +

		/*10 - TIPO DE REGIMEN DE PERCEPCION 3 */
			--dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
			dbo.fnSIAP_ConvertString2FIXLength2(ttn.sysSICORE_RegimenCode,3,'0') + ',' +
		/*11 - JURIDICCION 3 */
			dbo.fnSIAP_ConvertString2FIXLength2(tstate.state_jurisdiccion,3,'0')

			From tbTaxMovements													ttm		WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions									tct		WITH (NOLOCK)
				ON	tct.comp_id						= ttm.comp_id		AND
					tct.ct_transaction				= ttm.ct_transaction

			INNER JOIN @tblBranchs												tblb
				ON	tblb.bra_id			= tct.bra_id

			INNER JOIN dbo.vwCommercialTransactions_forPurchase 				vwct	WITH (NOLOCK)
			ON  tct.comp_id						= vwct.comp_id		AND
				tct.bra_id						= vwct.bra_id		AND
				tct.ct_transaction				= vwct.ct_transaction

			INNER JOIN tbSupplier												ts		WITH (NOLOCK)
				ON  ts.comp_id						= tct.comp_id		AND
					ts.supp_id						= tct.supp_id

			INNER JOIN tbsysTaxNumberTypes										ttnt	WITH (NOLOCK)
				ON	ttnt.tnt_id						= ts.tnt_id

			INNER JOIN tbTaxName												ttn		WITH (NOLOCK)
				ON  ttn.comp_id						= ttm.comp_id		AND
					ttn.tax_id						= ttm.tax_id

			INNER JOIN tbsysTaxClass											ttc		WITH (NOLOCK)
			ON	ttc.tax_class						= ttn.tax_class		AND
				ttc.taxcl_isRetention				= 'True'			AND
				ttc.taxcl_isIB						= 'True'

			INNER JOIN tbsysState												tstate	WITH (NOLOCK)
			ON	tstate.country_id					= ttc.country_id	AND
				tstate.state_id						= ttc.state_id		AND
				NOT tstate.state_jurisdiccion		IS NULL


			WHERE
				tct.comp_id				=  @comp_id							AND
				tct.sd_id				= 106								AND --???????????????
				tct.ct_date				BETWEEN  @date_from AND @date_to	AND
				ttn.tax_class			= 222									-- Retencion IB Santiago del Estero

			GROUP BY
				 ttm.tax_id,
				 ttm.ct_transaction,
				 tct.ct_docNumber,
				 tct.ct_transaction,
				 tct.ct_kindOf,
				 tct.sd_id,
				 tct.ct_taxDate,
				 ttn.sysSICORE_RegimenCode,
				 tstate.state_jurisdiccion,
				 ts.supp_taxNumber,
				 vwct.PlusOrMinus



END
GO




CREATE PROCEDURE [dbo].[spSysExportData_SUSS_Retenciones]
(
	@comp_id			Int,
	@lang_id			Int,
	@bra_id				Int,
	@date_from			Datetime,
	@date_to			Datetime,
	@brag_id			INT
)
AS

	SET NOCOUNT ON

		BEGIN

			SET NOCOUNT ON

			SET DATEFORMAT 'YMD'

			-- -----------------------------------------------------------------------------
			-- Para prevenir que alguien haga un query que mate la base para  todo el resto.!
			-- -----------------------------------------------------------------------------
			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
			-- -----------------------------------------------------------------------------

			-- ----------------------------------------------------------
			-- Testing
			-- ----------------------------------------------------------
			/*
				DECLARE		@comp_id			INT,
							@lang_id			INT,
							@bra_id				INT,
							@date_from			DATETIME,
							@date_to			DATETIME,
							@brag_id			INT

				SELECT		@comp_id			= 1,
							@lang_id			= 2,
							@bra_id				= 1,
							@date_from			= '2009-01-01',
							@date_to			= '2016-01-01',
							@brag_id			= 4
			*/
			-- ----------------------------------------------------------

			-- -----------------------------------------------------------------
			-- Varios
			-- -----------------------------------------------------------------
			SET @date_from	= dbo.fnGetEnd_or_BeginOfDate(@date_from, 'False')
			SET @date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
			DECLARE @zeros	VARCHAR(30)
			SET @zeros	= REPLICATE('0', 30)
			DECLARE @spaces VARCHAR(100)
			SET @spaces = REPLICATE(' ', 100)

			DECLARE @tblBranchs TABLE( bra_id  INT PRIMARY KEY )
			INSERT INTO @tblBranchs
				SELECT DISTINCT	bra_id
					FROM tbBranchGroupDetail tbgd	WITH (NOLOCK)
					WHERE tbgd.brag_id = @brag_id
			-- -----------------------------------------------------------------

			SELECT
				dbo.fnSIAP_ConvertString2FIXLength2(REPLACE(ts.supp_taxNumber,'-',''),11,'')	+ '' +	--CUIT AGENTE DE RETENCIÓN
				dbo.fnSIAP_ConvertDate2StringAAAAMMDD(ttm.tm_cd,'')								+ '' +	--FECHA(AAAAMMDD)
				dbo.fnSIAP_ConvertString2FIXLength(dbo.fnGetOnlyNumbers(ttm.tm_docNumber),25)	+ '' +	--NUMERO DE CERTIFICADO (NUMERICO)
				dbo.fnSIAP_ConvertDecimal2String(ttm.tm_total,15)										--IMPORTE


			From tbTaxMovements										ttm

					LEFT JOIN tbCommercialTransactions				tct
						ON	tct.comp_id			= ttm.comp_id		AND
							tct.ct_transaction	= ttm.ct_transaction

					INNER JOIN tbSupplier							ts
						ON  ts.comp_id			= tct.comp_id		AND
							ts.supp_id			= tct.supp_id

					INNER JOIN tbsysTaxNumberTypes					ttnt
						ON	ttnt.tnt_id			= ts.tnt_id

					INNER JOIN tbTaxName							ttn
						ON  ttn.comp_id			= ttm.comp_id		AND
							ttn.tax_id			= ttm.tax_id

					INNER JOIN @tblBranchs							tblb
						ON	tblb.bra_id			= tct.bra_id

				WHERE	tct.comp_id		=  @comp_id							AND
						tct.sd_id		= 106								AND
						tct.ct_date		BETWEEN  @date_from AND @date_to	AND
						ttn.tax_class	= 282
		END
GO







CREATE PROCEDURE [dbo].[spSysExportData_Yobel_Interface_GetData]
(
	@comp_id			Int,
	@lang_id			Int,
	@ds_id				int

)
As


BEGIN


	SET NOCOUNT ON
	SET DATEFORMAT 'YMD'
	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
/*
	DECLARE		@comp_id			Int,
				@lang_id			Int,
				@ds_id				int

	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@ds_id				= 8

	*/
	-- ----------------------------------------------------------


--***----------------------------------------------------------------
--***
--*** INTERFACE DE PEDIDOS ( AIPCAB_AAAAMMDDHHMMSS.TXT)
--***
--***----------------------------------------------------------------

	select  CONVERT(CHAR(137),CONVERT(CHAR(3),isnull(tdf.df_Yobel_cabcia,''))+
								CONVERT(CHAR(10),tct.ct_processingDate,120) +
								CONVERT(CHAR(2),isnull(tdf.df_Yobel_cabctr,''))+
								CONVERT(CHAR(15),(SELECT  case when tct2.ct_docNumber IS NULL THEN
																	isnull(tct.ct_docNumber,'')
															ELSE
																	isnull(tct2.ct_docNumber,'')
															END))+
								CONVERT(CHAR(30),isnull(replace(tc.cust_taxNumber,'-',''),''))+
								CONVERT(CHAR(10),tct.ct_date,120)+
								DBO.fnStrPADL(DBO.fnStrAllTrim(CONVERT(CHAR(7),COUNT(tit.it_transaction))), 7,' ') +
								DBO.fnStrPADL(DBO.fnStrAllTrim(CONVERT(CHAR(9),CONVERT(DECIMAL,isnull(SUM(tit.it_qty),0)))), 9,' ')+
								CONVERT(CHAR(10),'')+
								CONVERT(CHAR(8),'') +
								CONVERT(CHAR(10),'') +
								CONVERT(CHAR(8),'')+
								CONVERT(CHAR(15),'')
					)[Pedido]

	FROM tbCommercialTransactions							tct

	left JOIN tbCommercialTransactions						tct2
	ON	tct2.comp_id			= tct.comp_id			AND
		tct2.ct_transaction		= tct.ct_transaction_PackingList

	inner JOIN tbBranch										tb
	ON	tb.comp_id				= tct.comp_id			AND
		tb.bra_id				= tct.bra_id

	left JOIN tbItemTransactions							tit
	ON	tit.comp_id				= tct.comp_id			AND
		tit.bra_id				= tct.bra_id			AND
		tit.ct_transaction		= tct.ct_transaction

	left join tbItem										ti
	on  ti.comp_id				=	tit.comp_id			AND
		ti.item_id				=	tit.item_id

	left join tbItemTransactionDetails						titd
	ON	titd.comp_id			=	tit.comp_id			AND
		titd.bra_id				=	tit.bra_id			AND
		titd.ct_transaction		=	tit.ct_transaction	AND
		titd.it_transaction		=	tit.it_transaction

	inner JOIN tbDeliverySheetDetail						tdsd
	ON  tdsd.comp_id			= tct.comp_id			AND
	 	tdsd.bra_id				= tct.bra_id			AND
	 	tdsd.ds_ct_transaction	= tct.ct_transaction	and
		tdsd.ds_id				= @ds_id

	left JOIN tbDocumentsFile								tdf
	ON	tdf.comp_id				= tct.comp_id			AND
		tdf.bra_id				= tct.bra_id			AND
		tdf.df_id				= tct.df_id

	left JOIN tbCustomer									tc
	ON	tc.comp_id				= tct.comp_id			AND
		tc.cust_id				= tct.cust_id






GROUP BY tct.ct_docNumber,
		 tct2.ct_docNumber,
		 tct.ct_processingDate,
		 tit.it_transaction,
		 tct.ct_date,
		 tc.cust_taxNumber,
		 tdf.df_Yobel_cabcia,
		 tdf.df_Yobel_cabctr


--SELECT 'KOD2013-05-31810010022643     20518679121                   2013-05-31      3       50                                                                                                                                                                        '

--*******************************************************************************************************


--***----------------------------------------------------------------
--***
--*** INTERFACE DE DETALLE DE PEDIDOS ( AIPDET_AAAAMMDDHHMMSS.TXT)
--***
--***----------------------------------------------------------------


select		CONVERT(CHAR(129),CONVERT(CHAR(3),isnull(tdf.df_Yobel_cabcia,''))+
								CONVERT(CHAR(10),tct.ct_processingDate,120)+
								CONVERT(CHAR(2),isnull(tdf.df_Yobel_cabctr,''))+
								CONVERT(CHAR(15),(SELECT  case when tct2.ct_docNumber IS NULL THEN
																	isnull(tct.ct_docNumber,'')
															ELSE
																	isnull(tct2.ct_docNumber,'')
															END))+
								CONVERT(CHAR(35),isnull(tdf.df_Yobel_cabcpr,'')+ isnull(ti.item_code,''))+
								CONVERT(CHAR(25),'') +
								CONVERT(CHAR(8),isnull(CONVERT(DECIMAL,tit.it_qty),0))+
								CONVERT(CHAR(3),'') +
								CONVERT(CHAR(20),'')+
								CONVERT(CHAR(2),'') +
								CONVERT(CHAR(6),'')
					) [Detalle_Pedido]



	FROM tbCommercialTransactions							tct

	left JOIN tbCommercialTransactions						tct2
	ON	tct2.comp_id			= tct.comp_id			AND
		tct2.ct_transaction		= tct.ct_transaction_PackingList

	left JOIN tbBranch										tb
	ON	tb.comp_id				= tct.comp_id			AND
		tb.bra_id				= tct.bra_id

	left JOIN tbItemTransactions							tit
	ON	tit.comp_id				= tct.comp_id			AND
		tit.bra_id				= tct.bra_id			AND
		tit.ct_transaction		= tct.ct_transaction

	left join tbItem										ti
	on  ti.comp_id				=	tit.comp_id			AND
		ti.item_id				=	tit.item_id

	INNER JOIN tbDeliverySheetDetail						tdsd
	ON  tdsd.comp_id			= tct.comp_id			AND
	 	tdsd.bra_id				= tct.bra_id			AND
	 	tdsd.ds_ct_transaction	= tct.ct_transaction	and
		tdsd.ds_id				= @ds_id

	left JOIN tbDocumentsFile								tdf
	ON	tdf.comp_id				= tct.comp_id			AND
		tdf.bra_id				= tct.bra_id			AND
		tdf.df_id				= tct.df_id

	left JOIN tbCustomer									tc
	ON	tc.comp_id				= tct.comp_id			AND
		tc.cust_id				= tct.cust_id



GROUP BY tct.ct_docNumber,
		 tct2.ct_docNumber,
		 tct.ct_processingDate,
		 tit.it_transaction,
		 tct.ct_date,
		 ti.item_code,
		 tdf.df_Yobel_cabcia,
		 tdf.df_Yobel_cabctr,
		 tdf.df_Yobel_cabcpr,
		 tit.it_qty



--SELECT 'KOD2013-05-31810010022643     P8ZT-60403-10L                  50                                                                                                                                                                                            '

--*******************************************************************************************************



--***----------------------------------------------------------------
--***
--*** INTERFACE DE MAESTRO DE DESTINO ( AIPCLI_AAAAMMDDHHMMSS.TXT)
--***
--***----------------------------------------------------------------

	select		CONVERT(CHAR(508),CONVERT(CHAR(3),isnull(tdf.df_Yobel_cabcia,''))+
									CONVERT(CHAR(10),tct.ct_processingDate,120)+
									CONVERT(CHAR(30),isnull(replace(tcu.cust_taxNumber,'-',''),''))+
									CONVERT(CHAR(75),isnull(tcu.cust_name,''))+
									CONVERT(CHAR(70),isnull(tcu.cust_address4Delivery,isnull(tcu.cust_address,'')))+
									CONVERT(CHAR(10),isnull(td.state_id,''))+
									CONVERT(CHAR(75),isnull(tcu.cust_name1,''))+
									CONVERT(CHAR(70),isnull(tcu.cust_address,'')+ ' '+ isnull(tcu.cust_zip,'') + ' '+ isnull(tcu.cust_city,''))+
									CONVERT(CHAR(10),isnull(ts.state_id,''))+
									CONVERT(CHAR(15),isnull(replace(tcu.cust_taxNumber,'-',''),''))+
									CONVERT(CHAR(70),'')+
									CONVERT(CHAR(70),'')

						) [Maestro_Destino]


			FROM tbCommercialTransactions							tct

			INNER JOIN tbDeliverySheetDetail						tdsd
			ON  tdsd.comp_id			= tct.comp_id			AND
	 			tdsd.bra_id				= tct.bra_id			AND
	 			tdsd.ds_ct_transaction	= tct.ct_transaction	and
				tdsd.ds_id				= @ds_id

			left JOIN tbDocumentsFile								tdf
			ON	tdf.comp_id				= tct.comp_id			AND
				tdf.bra_id				= tct.bra_id			AND
				tdf.df_id				= tct.df_id

			left join dbo.tbCustomer								tcu
			on	tcu.comp_id				= tct.comp_id			and
				tcu.cust_id				= tct.cust_id

			left join tbsysCountry									tsc
			on 	tsc.country_id			= tcu.country_id

			left join tbsysState									ts
			on	ts.state_id				= tcu.state_id

			left join tbDelivery									td
			on  td.comp_id				= tcu.comp_id			and
				td.dl_id				= tcu.dl_id


--SELECT 'KOD2013-05-3120518679121                   CORPORACION SERCOPLUS S.A.C..       AV. GARCILAZO DE LA VEGA NRO. 1225 INT. 313                           150101    CORPORACION SERCOPLUS S.A.C..                                              AV. GARCILAZO DE LA VEGA NRO. 1225 INT. 313                           150101    20518679121    '

END
GO





CREATE PROCEDURE spSysFEConceptos_getCombo
(
