CREATE PROCEDURE [dbo].[spSysFields_getCombo]
(
	@table_id		int,
	@lang_id		int,
	@quantity		int
)
AS
SET NOCOUNT ON
------------------------------------------------------------------------
---  ACTUALIZADO CON tbSysNamesNew 26/02/2010---------------------------
------------------------------------------------------------------------



/*
@quantity = 0  trae los que faltan con nombres físicos de campo
@quantity = 1  trae todos con nombre físico de campo
@quantity = 2  trae todos con nombres lógicos en el lenguaje que se pasa como parámetro
*/



/*
DECLARE @table_id		INT,
		@lang_id		INT,
		@quantity		INT
SELECT  @table_id		=130,
		@lang_id		=2,
		@quantity		=0
*/



SELECT  f.[field_id]										[id],
		CASE WHEN @quantity = 2 THEN tswn.word_desc --tn.name_desc
								ELSE f.[field_name] END 	[desc]

FROM  	[tbsysFields]					f
		LEFT JOIN tbsysNamesNew			tn
		ON	--tn.lang_id	= @lang_id
		--AND
			tn.table_id = f.table_id
		AND tn.field_id = f.field_id
		AND @quantity	= 2
		LEFT JOIN tbSysWordsNew tswn
		ON tswn.lang_id	= @lang_id
		AND tswn.wordsi_id = tn.name_desc_id

WHERE 	f.table_id	= @table_id
AND 	((@quantity = 0 AND (@lang_id = -1 or f.field_id not in (SELECT field_id FROM [tbsysNames]
   																	WHERE	[table_id]	= @table_id
   																	AND		[lang_id]	= @lang_id
   																	AND NOT [field_id]	IS NULL)))
   		OR (@quantity = 1)
   		OR (@quantity = 2 AND tswn.word_desc <> ''))

ORDER BY 2
GO







-- -----------------------------------------------------------------
-- Modif. MOS 05-2008
-- OJO!!!!!    Si se agregan campos, agregarlos entre las etiquetas
-- de lugar de campos admitidos. JAMAS en otro lugar
-- porque hay problermas con la grilla de pedidos.-
