CREATE PROCEDURE [dbo].[spSysFields_getData]
(
	@table_id			int
)
as

/*
declare @table_id int
select @table_id = 4
*/


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------



select	' ' [ ], ' ' [ ],
		--f.table_id,
		--t.[table_desc],
		field_name,
		field_order,
		field_mrc_filter,
		field_type,
		field_lenght,
		field_visible,
		field_validator_type,
		field_validator_properties,
		field_nullenable,
		field_function,
		field_updateable,
		f.field_only4Insert,
		f.field_nullenable_textWithAll,
		f.field_HeightInPixels,
		f.field_WidthInPixels,
		f.field_disabledOnInsert,
		f.field_disabledOnInheritsInsert,
		f.field_isCalculated,
		field_id	--el id tiene que estar obligatoriamente en última posición

from	dbo.[tbsysFields]			f
		inner join [tbsysTables]	t
		on t.[table_id] = f.[table_id]

where	f.table_id		=	@table_id

order by f.[field_order]




















GO







-- -----------------------------------------------------------------
-- Modif. MOS 05-2008
-- OJO!!!!!    Si se agregan campos, agregarlos entre las etiquetas
-- de lugar de campos admitidos. JAMAS en otro lugar
-- porque hay problermas con la grilla de pedidos.-
-- -----------------------------------------------------------------


CREATE PROCEDURE [dbo].[spSysFields_getDataById]
(
	@field_id			int
)
as

/*
declare @table_id int
select @table_id = 5
*/


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


select	--' ' [ ], ' ' [ ],
		f.table_id,
		t.[table_desc],
		field_name,
		field_order,
		field_mrc_filter,
		field_type,
		isnull(field_lenght,0)														[field_lenght],
		field_visible,
		isnull(field_validator_type,'')												[field_validator_type],
		field_validator_properties,
		field_nullenable,
		field_function,
		field_updateable,
		f.field_only4Insert,
		isnull(f.field_nullenable_textWithAll,'False')								[field_nullenable_textWithAll],
		isnull(f.field_HeightInPixels,0)											[field_HeightInPixels],
		isnull(f.field_WidthInPixels,0)												[field_WidthInPixels],
		isnull(f.field_FontBold,'False')											[field_FontBold],
		isnull(f.field_notIncludeInDetail,'False')									[field_notIncludeInDetail],
		UPPER(dbo.fnStrAllTrim( isnull(tfc.field_FontColor,'')))					[field_FontColor],
		--isnull(f.field_FontColor,'')												[field_FontColor],
		ISNULL(f.field_disabledOnInsert,'')											[field_disabledOnInsert],
		ISNULL(f.field_disabledOnInheritsInsert,'False')							[field_disabledOnInheritsInsert],
		ISNULL(f.field_isCalculated,'False')										[field_isCalculated]
		--field_id	--el id tiene que estar obligatoriamente en última posición

from	dbo.[tbsysFields]			f
		inner join [tbsysTables]	t
		on t.[table_id] = f.[table_id]
		INNER JOIN tbsysFieldsColors AS tfc
			ON tfc.sfc_id = f.field_FontColorID

where	f.field_id		=	@field_id

--order by f.[field_id]




















GO







CREATE  PROCEDURE [dbo].[spSysFields_insertData]
(
		@table_id						int,
		@field_name						varchar(200),
		@field_order					int,
		@field_mrc_filter				bit,
		@field_type						char(2),
		@field_lenght					int,
		@field_visible					bit,
		@field_validator_type			varchar(10),
		@field_validator_properties		varchar(500),
		@field_nullenable				bit,
		@field_function					char(1),
		@field_updateable				bit,
		@field_only4Insert				bit,
		@field_nullenable_textWithAll	bit,
		@field_HeightInPixels			int,
		@field_WidthInPixels			int,
		@field_FontBold					BIT,
		@field_notIncludeInDetail		BIT,
		@field_FontColor				varchar(10),
		@field_disabledOnInsert			BIT,
		@field_disabledOnInheritsInsert	BIT,
		@field_isCalculated				BIT,
		@return_value					int output
)
as

insert into dbo.[tbsysFields]
(table_id, field_name, field_order, field_mrc_filter, field_type, field_lenght,
field_visible, field_validator_type, field_validator_properties, field_nullenable,
field_function, field_updateable, field_only4Insert, field_nullenable_textWithAll,
field_HeightInPixels, field_WidthInPixels,field_FontBold, field_notIncludeInDetail,
field_FontColor,field_disabledOnInsert, field_disabledOnInheritsInsert,field_isCalculated,field_FontColorID)

values
(@table_id, @field_name, @field_order, @field_mrc_filter, @field_type, @field_lenght,
@field_visible, @field_validator_type, @field_validator_properties, @field_nullenable,
@field_function, @field_updateable, @field_only4Insert, @field_nullenable_textWithAll,
@field_HeightInPixels, @field_WidthInPixels,@field_FontBold,@field_notIncludeInDetail,
@field_FontColor,@field_disabledOnInsert, @field_disabledOnInheritsInsert,@field_isCalculated,

										(	SELECT tfc.sfc_id
		                 						FROM tbsysFieldsColors AS tfc
		                 				   		WHERE dbo.fnStrAllTrim(tfc.field_FontColor) = dbo.fnStrAllTrim (@field_FontColor))


)

set	@return_value = @@identity
GO








CREATE  PROCEDURE [dbo].[spSysFields_updateData]
(
		@field_id						int,
		@field_name						varchar(200),
		@field_order					int,
		@field_mrc_filter				bit,
		@field_type						char(2),
		@field_lenght					int,
		@field_visible					bit,
		@field_validator_type			varchar(10),
		@field_validator_properties		varchar(500),
		@field_nullenable				bit,
		@field_function					char(1),
		@field_updateable				bit,
		@field_only4Insert				bit,
		@field_nullenable_textWithAll	bit,
		@field_HeightInPixels			int,
		@field_WidthInPixels			INT,
		@field_FontBold					BIT,
		@field_notIncludeInDetail		BIT,
		@field_FontColor				varchar(10),
		@field_disabledOnInsert			BIT,
		@field_disabledOnInheritsInsert bit,
		@field_isCalculated				BIT
)
as







update	dbo.[tbsysFields]

set		field_name						= @field_name,
		field_order						= @field_order,
		field_mrc_filter				= @field_mrc_filter ,
		field_type						= @field_type,
		field_lenght					= @field_lenght,
		field_visible					= @field_visible,
		field_validator_type			= @field_validator_type,
		field_validator_properties		= @field_validator_properties,
		field_nullenable				= @field_nullenable,
		field_function					= @field_function,
		field_updateable				= @field_updateable,
		field_only4Insert				= @field_only4Insert,
		field_nullenable_textWithAll	= @field_nullenable_textWithAll,
		field_HeightInPixels			= @field_HeightInPixels,
		field_WidthInPixels				= @field_WidthInPixels,
		field_FontBold					= @field_FontBold,
		field_notIncludeInDetail		= @field_notIncludeInDetail,
		field_FontColor					= @field_FontColor,
		field_disabledOnInsert			= @field_disabledOnInsert,
		field_disabledOnInheritsInsert  = @field_disabledOnInheritsInsert,
		field_isCalculated				= @field_isCalculated,
		field_FontColorID				= (	SELECT tfc.sfc_id
		                 						FROM tbsysFieldsColors AS tfc
		                 				   		WHERE dbo.fnStrAllTrim(tfc.field_FontColor) = dbo.fnStrAllTrim (@field_FontColor))

where	field_id					= @field_id

GO







