CREATE PROCEDURE [dbo].[spSysFiscalClass_getCombo]
(
	@comp_id			int,
	@country_id			int,
	@state_id			int
)
as
SET NOCOUNT ON

/*
declare @comp_id			int,
		@country_id			int,
		@state_id			int

select 	@comp_id			=1,
		@country_id			=-1,
		@state_id			=-1
*/

select	SFC.fc_id   [id],
		SFC.fc_desc	[desc]

from	tbsysFiscalClass						SFC
		Left Join	dbo.tbsysState				SS
		On	SS.state_id		= SFC.state_id
		Left Join	dbo.tbsysCountry			SC
		On	SC.country_id	= SFC.country_id

where	(@country_id	= -1 or (SFC.country_id	=	@country_id or SFC.country_id IS NULL))
and		(@state_id		= -1 or (SFC.state_id	=	@state_id	or SFC.state_id   IS NULL))

order by sfc.fc_order









GO







