CREATE PROCEDURE [dbo].[spSysGBPUpgrades_getGenericGridData]
(
	@lang_id	INT,
	@upg_id		INT
)
AS SET NOCOUNT ON


---------------------------------------------

/*
declare @lang_id	INT,
		@upg_id		INT

select @lang_id = 2,
	   @upg_id  = 15
*/

--------------------------------------------

SELECT  tg.upg_detail,
		tg.upg_desc,
		tov.optval_desc [upg_actReq]


FROM tbsysGBPUpgrades tg


inner join tbsysOptionsValues tov
on  tov.lang_id = @lang_id
and tov.optval_id = tg.upg_actReq
and tov.optval_class = 300


WHERE tg.upg_id		= @upg_id
AND   tg.lang_id	= @lang_id
GO







CREATE PROCEDURE [dbo].[spSysGBPUpgrades_getGridData]
(
	@lang_id	INT
)
AS SET NOCOUNT ON


-- --------------------------------------------------
-- Testing
-- --------------------------------------------------
/*
	DECLARE @lang_id	INT


	SELECT  @lang_id	= 2
*/
-- --------------------------------------------------

SELECT
	' '				[ ],
	tg.upg_date,
	tc.country_desc,
	tl.lang_desc,
	tg.upg_detail,
	tg.upg_id		[ID]

FROM tbsysGBPUpgrades tg

INNER JOIN tbsysCountry tc
ON tc.country_id = tg.country_id

INNER JOIN tbsysLanguage tl
ON tl.lang_id = tg.lang_id

WHERE tg.lang_id = @lang_id

order by tg.upg_date desc
GO





create  PROCEDURE [dbo].[spSysGeneric_deleteData]
(
	@name_id	int
)
as



declare @field_id int

select @field_id = field_id from [tbsysNames] where [name_id] = @name_id

exec spSysNames_deleteData @name_id

exec spSysFields_deleteData @field_id

GO







CREATE PROCEDURE [dbo].[spSysGeneric_getData]
(
	@lang_id			int,
	@table_id			int
)
as

/*
declare 	@lang_id			int,
			@table_id			int
select		@lang_id			=2,
			@table_id			=5

drop table #tmpfields
drop table #tmpnames
*/



--crear temporal para datos de tbsysFields
create table [#tmpfields]
(
	table_id					int,
	field_name					varchar(200),
	field_order					int,
	field_mrc_filter			bit,
	field_type					char(2),
	field_lenght				int,
	field_visible				bit,
	field_validator_type		varchar(10),
	field_validator_properties	varchar(500),
	field_nullenable			bit,
	field_function				char(1),
	field_id					int
)

--cargar temporal con datos de tbsysFields para la tabla seleccionada
insert [#tmpfields]
(
	table_id, field_name, field_order, field_mrc_filter, field_type, field_lenght, field_visible,
	field_validator_type, field_validator_properties, field_nullenable, field_function, field_id
)
exec [spsysfields_getdata] @table_id


--crear temporal para datos de tbsysNames
CREATE TABLE [#tmpnames]
(
	[lang_id]				int,
	[table_id]				int,
	[tab_id]				int,
	[tab_desc]				varchar(100),
	[field_id]				int				null,
	[field_name]			varchar(200),
	[type_id]				int				null,
	[type_desc]				varchar(100)	null,
	[name_desc]				varchar(200)	null,
	[name_reference]		varchar(1000)	null,
	[name_filterselect]		varchar(1000)	null,
	[name_join]				varchar(5000)	null,
	[name_combo]			varchar(5000)	null,
	[name_column]			varchar(1000)	null,
	[name_comboact]			varchar(5000)	null,
	[name_errormessage]		varchar(500)	null,
	[name_filtername]		varchar(50)		null,
	[ctrl_id]				int				null,
	[ctrl_desc]				varchar(200)	null,
	[prop_id]				int				null,
	[prop_desc]				varchar(100)	null,
	[name_id]				int
)

--cargar temporal con datos de tbsysNames para la tabla y el lenguaje seleccionados
INSERT [#tmpnames]
(
	lang_id, table_id, tab_id, tab_desc, [field_id], field_name, type_id, type_desc, name_desc,
	name_reference, name_filterselect, name_join, name_combo, name_column, name_comboact,
	name_errormessage, name_filtername, ctrl_id, ctrl_desc, prop_id, prop_desc, name_id
)
exec [spSysNames_getData] @lang_id, @table_id


--select * from [#tmpfields]
--select * from [#tmpnames]



--obtener los datos de unificados entre las temporales de Fields y Names por medio de join y agregar por medio
--de union los registros de la temporal de Names que no joinean con Fields por los campos tienen valor NULL
SELECT		f.table_id,				f.field_id,						f.field_order,
			f.field_mrc_filter,		f.field_type,					f.field_lenght, 	f.field_visible,
			f.field_validator_type, f.field_validator_properties,	f.field_nullenable, f.field_function, n.tab_id, n.field_id,				n.type_id,						n.name_desc,		n.name_reference,
			n.name_filterselect,	n.name_join,					n.name_combo,		n.name_column,
			n.name_comboact,		n.name_errormessage,			n.ctrl_id,
			n.prop_id, n.name_id

FROM		[#tmpnames]					n
			right join [#tmpfields]		f
			on		n.table_id	= f.[table_id]
			and		n.field_id	= f.[field_id]


union


SELECT		n.table_id,	null, null, null, null, null, null, null, null, null, null,
			n.tab_id, n.field_id, n.type_id, n.name_desc,
			n.name_reference, n.name_filterselect, n.name_join, n.name_combo, n.name_column,
			n.name_comboact, n.name_errormessage, n.ctrl_id, n.prop_id,	n.name_id
FROM        [#tmpnames]					n
WHERE		n.[field_id] is null

order by	n.[type_id], f.[field_order]



GO





create  PROCEDURE [dbo].[spSysGeneric_insertData]
(
		@lang_id						int,
		@table_id						int,
		@tab_id							int,
		@type_id						int,
		@name_desc						varchar(200),
		@name_reference					varchar(1000),
		@name_filterselect				varchar(1000),
		@name_join						varchar(5000),
		@name_combo						varchar(5000),
		@name_column					varchar(1000),
		@name_comboact					varchar(5000),
		@name_errormessage				varchar(500),
		@name_filtername				varchar(50),
		@ctrl_id						int,
		@prop_id						int,
		@field_name						varchar(200),
		@field_order					int,
		@field_mrc_filter				bit,
		@field_type						char(2),
		@field_lenght					int,
		@field_visible					bit,
		@field_validator_type			varchar(10),
		@field_validator_properties		varchar(500),
		@field_nullenable				bit,
		@field_function					char(1),
		@return_value					int output
)
as


declare		@rvF	int,
			@rvN	int

exec spSysFields_insertData
	@table_id, @field_name, @field_order, @field_mrc_filter, @field_type,
	@field_lenght, @field_visible, @field_validator_type, @field_validator_properties,
	@field_nullenable, @field_function, @return_value = @rvF output


exec spSysNames_insertData
	@lang_id, @table_id, @tab_id, @rvF, @type_id, @name_desc, @name_reference,
	@name_filterselect, @name_join, @name_combo, @name_column, @name_comboact,
	@name_errormessage, @name_filtername, @ctrl_id, @prop_id, @return_value = @rvN output

set @return_value = @rvN
GO







