CREATE  PROCEDURE [dbo].[spSysMenu_getDataAll]
(
	@lang_id		int,
	@menu_id_sup	int
)
AS



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on
/*
declare	@comp_id		int,
		@lang_id		int,
		@prof_id		int,
		@menu_id_sup	int
select 	@comp_id		= 1,
		@lang_id		= 2,
		@prof_id		= 2,
		@menu_id_sup	= 17
*/

select	M.menu_id,
		M.menu_id_sup,
		M.menu_order,
		M.menu_type,
		isnull(L.mid_desc,M.menu_desc)					[menu_desc],
		isnull(P.page_desc + '.aspx', '')				[menu_page],
		case
			when MP.parameters is null					then ''
			when len(ltrim(rtrim(MP.parameters))) = 0	then ''
			else substring(MP.parameters,1,len(MP.parameters)-1)
		end												[menu_parameters],
		M.menu_destiny,
		M.menu_imageurl_path

from 	dbo.tbsysMenu							M		WITH (NOLOCK)

		left join dbo.tbsysMenuLanguage			L		WITH (NOLOCK)
		on	L.menu_id		= M.menu_id
		and	L.lang_id		= @lang_id

		left JOIN tbsysMenuParametersFromView	MP		WITH (NOLOCK)	-- dbo.vwMenuParameters			MP
		on	MP.menu_id		= M.menu_id

		left join dbo.tbsysPages				P		WITH (NOLOCK)
		on	P.page_id		= M.page_id

where	(M.menu_id_sup		= @menu_id_sup OR @menu_id_sup = -1)


order by [menu_order]
GO







CREATE  PROCEDURE [dbo].[spSysMenu_getDataAllNotDisabled]
(
	@lang_id		int,
	@menu_id_sup	int
)
AS



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on
/*
declare	@comp_id		int,
		@lang_id		int,
		@prof_id		int,
		@menu_id_sup	int
select 	@comp_id		= 1,
		@lang_id		= 2,
		@prof_id		= 2,
		@menu_id_sup	= 17
*/

select	M.menu_id,
		M.menu_id_sup,
		M.menu_order,
		M.menu_type,
		isnull(L.mid_desc,M.menu_desc)					[menu_desc],
		isnull(P.page_desc + '.aspx', '')				[menu_page],
		case
			when MP.parameters is null					then ''
			when len(ltrim(rtrim(MP.parameters))) = 0	then ''
			else substring(MP.parameters,1,len(MP.parameters)-1)
		end												[menu_parameters],
		M.menu_destiny,
		M.menu_imageurl_path

from 	dbo.tbsysMenu							M		WITH (NOLOCK)

		left join dbo.tbsysMenuLanguage			L		WITH (NOLOCK)
		on	L.menu_id		= M.menu_id
		and	L.lang_id		= @lang_id

		left JOIN tbsysMenuParametersFromView	MP		WITH (NOLOCK)	-- dbo.vwMenuParameters			MP
		on	MP.menu_id		= M.menu_id

		left join dbo.tbsysPages				P		WITH (NOLOCK)
		on	P.page_id		= M.page_id

where	(M.menu_id_sup		= @menu_id_sup OR @menu_id_sup = -1) AND m.menu_disabled = 'False'


order by [menu_order]
GO
/****************************************************************************************/
/**** ATENCION: ESTE PROCEDIMIENTO ESTA BAJO CONTROL DE CRC                 *************/
/**** ANTE CUALQUIER MODIFICACION VOLVER A CALCULAR EL CRC CORRESPONDIENTE  *************/
/****************************************************************************************/
CREATE   PROCEDURE [dbo].[spSysMenu_getDataGranted]
(
	@comp_id				int,
	@lang_id				int,
	@prof_id				int,
	@menu_id_sup			INT,
	@bitMenu_allEntries AS	BIT,
	@sevt_id				INT,
	@isAdmin				BIT
)
AS
BEGIN
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------	
	set nocount ON
	DECLARE @tmpParameters AS TABLE (menu_id INT PRIMARY KEY,parameters	NVARCHAR(MAX))
	INSERT  @tmpParameters
	(
		menu_id,parameters
	)
	select	distinct mp.menu_id,
	--tooltip3
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and		m.ptype_id = 21),'') +
	--tooltip4
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and		
					m.ptype_id = 22),'') +
	--tooltip4
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and		
					m.ptype_id = 57),'') +
	--tooltip5
	isnull((select	t.ptype_desc +'='+ v.[desc] +','
			from	tbsysmenuparameters m											WITH (NOLOCK)
					inner join tbsysparameterstype t								WITH (NOLOCK)
					on	m.ptype_id		= t.ptype_id
					inner join [tbSysParametersTypeLangValuesClearFromView]	v		WITH (NOLOCK)
					on	v.[type_id]		= m.[ptype_id]
					and	v.id			= m.ptypevalue_id
					AND v.lang_id		= @lang_id
			where	m.menu_id = mp.menu_id		and		m.ptype_id = 32),'') [parameters]
	FROM 	tbsysmenuparameters		mp												WITH (NOLOCK)
	WHERE	mp.ptype_id  = 21 OR 
			mp.ptype_id  = 22 OR
			mp.ptype_id  = 32 OR
			mp.ptype_id  = 57 

	IF @sevt_id = 10		-- Es GBP Express ?
		BEGIN
			select	DISTINCT
				M.menu_id,
				@menu_id_sup									[menu_id_sup], --M.menu_id_sup,
				CASE 
					 WHEN tmc.menu_id_sup IS NOT null	THEN	1000000
					 ELSE									0
				END + m.menu_order								[menu_order],
				M.menu_type,
				isnull(L.mid_desc,M.menu_desc)					[menu_desc],
				CASE SUBSTRING(P.page_desc,1,3)
					WHEN 'wfm' then	isnull(P.page_desc + '.aspx', '')
					WHEN 'htm' THEN ISNULL(P.page_desc + '.htm', '')
					WHEN 'hel' THEN ISNULL(P.page_desc + '.htm', '')
					ELSE isnull(P.page_desc + '.aspx', '')
				end												[menu_page],
				case
					when MP.parameters is null					then ''
					when len(ltrim(rtrim(MP.parameters))) = 0	then ''
					else substring(MP.parameters,1,len(MP.parameters)-1)
				end	 +
				case
					when ttsmp.parameters is null					then ''
					when len(ltrim(rtrim(ttsmp.parameters))) = 0	then ''
					else ',' + substring(ttsmp.parameters,1,len(ttsmp.parameters)-1)
				end	 +											
				case
					when M.menu_parameters is null					then ''
					when len(ltrim(rtrim(M.menu_parameters)))	= 0	then ''
					ELSE
						CASE WHEN LEN(MP.parameters) > 0 OR LEN(ttsmp.parameters) > 0 THEN ',' ELSE '' END 
							+ M.menu_parameters
				end												[menu_parameters],
				M.menu_destiny,
				M.menu_imageurl_path,
				IsNull(L.mid_tooltip,'')						[menu_tooltip]
		from	tbsysMenu M																		WITH (NOLOCK)
				LEFT JOIN tbsysMenuClone tmc													WITH (NOLOCK)
					ON	tmc.menu_id		= m.menu_id			AND 
						tmc.menu_id_sup = @menu_id_sup		AND
						@sevt_id <> 10		-- Siempre y cuando NO sea GBP Express
				left JOIN tbMenuGrants tmg														WITH (NOLOCK)
					ON  tmg.comp_id		= @comp_id
					AND tmg.prof_id		= @prof_id
					AND tmg.menu_id		= m.menu_id
				LEFT JOIN tbSysERPMenuExeptions tsee											WITH (NOLOCK)
					ON	tsee.sevt_id			= @sevt_id	and 
						tsee.menu_id_Excluded	= m.menu_id AND
						m.menu_type				= 'false'
				LEFT JOIN tbSysERPMenuExeptions tsee2											WITH (NOLOCK)
					ON	tsee2.sevt_id			= @sevt_id	and 
						tsee2.menu_id_Excluded	= m.menu_id AND
						m.menu_type				= 'True'					
				left join tbsysMenuParametersFromView MP										WITH (NOLOCK)
					on MP.menu_id		= M.menu_id
				LEFT JOIN @tmpParameters ttsmp 
					ON MP.menu_id		= ttsmp.menu_id
				left join tbsysPages P															WITH (NOLOCK)
					on P.page_id		= M.page_id						
				inner join tbCompany tc															WITH (NOLOCK)
					on tc.comp_id = @comp_id
				INNER join tbsysMenuLanguage L													WITH (NOLOCK)
					on	L.menu_id		= M.menu_id
					and	L.lang_id		= @lang_id
				INNER JOIN tbProfile tp															WITH (NOLOCK)
					ON		tp.comp_id	= @comp_id 
					AND		tp.prof_id	= @prof_id
				--INNER JOIN tbUser tu															WITH (NOLOCK)
				--	ON tu.[user_id]		= @user_id
		where	
				(	
					M.menu_id_sup	= @menu_id_sup 
						OR  
					tmc.menu_id_sup = @menu_id_sup
				)
				AND 
					(
						(
							@bitMenu_allEntries ='True' 
								AND 
							(
								tp.prof_isSA	='True' 
									OR 
								@isAdmin		= 'True'
							)
						) 
							OR 
						tmg.comp_id				= @comp_id --IS NOT NULL 
					)
				AND		CASE		-- Si es EXPRESS al reves
							WHEN @sevt_id = 10  AND tsee.menu_id_Excluded IS NOT NULL						THEN 1
							WHEN @sevt_id <> 10 AND tsee.menu_id_Excluded IS     NULL						THEN 1
							WHEN @isAdmin = 'True'															THEN 1
							WHEN @sevt_id = 10  AND tsee2.menu_id_Excluded IS NOT NULL						THEN 1   -- Si MENU va siempre
							ELSE																				 0
						END	= 1
					
				AND m.menu_disabled = 'False'
			ORDER BY menu_order		
		END
	ELSE		-- es GBP NO Express ?
		BEGIN
			
			select	DISTINCT
					M.menu_id,
					@menu_id_sup									[menu_id_sup], --M.menu_id_sup,
					CASE 
						 WHEN tmc.menu_id_sup IS NOT null	THEN	1000000
						 ELSE									0
					END + m.menu_order								[menu_order],
					M.menu_type,
					isnull(L.mid_desc,M.menu_desc)					[menu_desc],
					CASE SUBSTRING(P.page_desc,1,3)
						WHEN 'wfm' then	isnull(P.page_desc + '.aspx', '')
						WHEN 'htm' THEN ISNULL(P.page_desc + '.htm', '')
						WHEN 'hel' THEN ISNULL(P.page_desc + '.htm', '')
						ELSE isnull(P.page_desc + '.aspx', '')
					end												[menu_page],
					case
						when MP.parameters is null					then ''
						when len(ltrim(rtrim(MP.parameters))) = 0	then ''
						else substring(MP.parameters,1,len(MP.parameters)-1)
					end	 +
					case
						when ttsmp.parameters is null					then ''
						when len(ltrim(rtrim(ttsmp.parameters))) = 0	then ''
						else ',' + substring(ttsmp.parameters,1,len(ttsmp.parameters)-1)
					end	 +											
					case
						when M.menu_parameters is null					then ''
						when len(ltrim(rtrim(M.menu_parameters)))	= 0	then ''
						ELSE
							CASE WHEN LEN(MP.parameters) > 0 OR LEN(ttsmp.parameters) > 0 THEN ',' ELSE '' END 
								+ M.menu_parameters
					end												[menu_parameters],
					M.menu_destiny,
					M.menu_imageurl_path,
					IsNull(L.mid_tooltip,'')						[menu_tooltip]
			from	tbsysMenu M		
					INNER join tbsysMenuLanguage L													WITH (NOLOCK)
						on	L.menu_id		= M.menu_id
						and	L.lang_id		= @lang_id
					INNER JOIN tbProfile tp															WITH (NOLOCK)
						ON		tp.comp_id	= @comp_id 
						AND		tp.prof_id	= @prof_id
					LEFT JOIN tbsysMenuClone tmc													WITH (NOLOCK)
						ON	tmc.menu_id		= m.menu_id			AND 
							tmc.menu_id_sup = @menu_id_sup		
					left JOIN tbMenuGrants tmg														WITH (NOLOCK)
						ON  tmg.comp_id		= @comp_id
						AND tmg.prof_id		= @prof_id
						AND tmg.menu_id		= m.menu_id
					LEFT JOIN tbSysERPMenuExeptions tsee											WITH (NOLOCK)
						ON	tsee.sevt_id			= @sevt_id	and 
							tsee.menu_id_Excluded	= m.menu_id AND
							m.menu_type				= 'false'
					left join tbsysMenuParametersFromView MP										WITH (NOLOCK)
						on MP.menu_id		= M.menu_id
					LEFT JOIN @tmpParameters ttsmp 
						ON MP.menu_id		= ttsmp.menu_id
					left join tbsysPages P															WITH (NOLOCK)
						on P.page_id		= M.page_id						

			where	
					(	
						M.menu_id_sup	= @menu_id_sup 
							OR  
						tmc.menu_id_sup = @menu_id_sup
					)
					AND 
					(
						(
							@bitMenu_allEntries ='True' 
								AND 
							(
								tp.prof_isSA	='True' 
									OR 
								@isAdmin		= 'True'
							)
						) 
							OR 
						tmg.comp_id				= @comp_id --IS NOT NULL 
					)
					AND		CASE		-- Si es EXPRESS al reves
								WHEN tsee.menu_id_Excluded IS NULL												THEN 1
								WHEN @isAdmin = 'True'															THEN 1
								ELSE																				 0
							END	= 1					
					AND m.menu_disabled = 0
				ORDER BY menu_order
			
			
		END



END


GO







