CREATE PROCEDURE [dbo].[spSysMenu_getFreeMenu]
(
	@comp_id			int,
	@prof_id			int,
	@lang_id			int
)
as



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

set nocount on

/*
declare 	@comp_id			int,
	        @prof_id			int,
			@lang_id			int

select		@comp_id			=2,
			@prof_id			=3,
			@lang_id			=2
*/


select	m.menu_id			[id],
		ml.mid_desc			[desc]

from 	dbo.tbsysMenu		m

		inner join dbo.tbsysMenuLanguage ml
		on ml.[menu_id] = m.[menu_id]

where	ml.[lang_id] = @lang_id
and		m.menu_id not in (select distinct a.menu_id
							from	[tbMenuGrants]		a
							where	a.prof_id			= @prof_id
							and		a.comp_id			= @comp_id)

order by ml.mid_desc


GO






CREATE procedure [dbo].[spSysMenu_GrantsForGridImage]
(
	@comp_id	int,
	@lang_id	INT,
	@prof_id	INT,
	@menu_id	int
)
as


BEGIN

	set nocount ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



	-- ----------------------------------------------------
	-- Testing
	-- ----------------------------------------------------
	/*
		declare
			@comp_id	int,
			@bra_id		INT,
			@lang_id	INT,
			@prof_id	INT,
			@user_id	INT,
			@menu_id	int

		select
			@comp_id	= 1,
			@bra_id		= 1,
			@lang_id	= 2,
			@prof_id	= 1,
			@user_id	= 1,
			@menu_id	= 163
	*/
	-- ----------------------------------------------------

	DECLARE @strGLBP AS NVARCHAR(150)
	SELECT @strGLBP = tut.utexts_desc
		FROM tbsysUniqueTexts tut	WITH (NOLOCK)
		WHERE tut.lang_id = @lang_id AND tut.utexts_id = 52505

	declare	@bitEnabled	 as BIT = 'False'

	if exists (	select 1
	           		from	tbMenuGrants			tmg	WITH (NOLOCK)
					where
						tmg.comp_id		= @comp_id	AND
						tmg.menu_id		= @menu_id	AND
						tmg.prof_id		= @prof_id
				)
		set @bitEnabled = 'True'
	else
		set @bitEnabled = 'False'


	IF @bitEnabled = 'False'
		BEGIN
			SELECT @bitEnabled = ISNULL(tp.prof_isSA,'False')
				FROM tbProfile tp		WITH (NOLOCK)
				WHERE	tp.comp_id = @comp_id AND
						tp.prof_id = @prof_id
		END


	select
		tm.menu_id,
		tml.mid_desc,
		tp.page_desc,
		ISNULL(tml.mid_tooltip,tml.mid_desc)	[mid_tooltip],
		@bitEnabled	[Enabled],
		tm.menu_id	,
		@strGLBP	[GBPE]
		from tbsysMenu						tm	WITH (NOLOCK)
			inner join tbsysPages			tp	WITH (NOLOCK)
				on tp.page_id = tm.page_id
			inner join tbsysMenuLanguage	tml	WITH (NOLOCK)
				on	tml.menu_id = tm.menu_id	AND
					tml.lang_id = @lang_id
		where tm.menu_id  = @menu_id


END
GO







