CREATE procedure [dbo].[spSysMenuRelations_GetDataByFilters]
(
	@comp_id	int,
	@lang_id	int,
	@bra_id		int,
	@user_id	int,
	@prof_id	int,
	@table_id	int
)
as


BEGIN



	set nocount on

		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		-- -----------------------------------------------------------------------------

	--------------------------------
	-- Testing
	--------------------------------
		/*
		declare
			@comp_id	int,
			@bra_id		int,
			@lang_id	int,
			@user_id	int,
			@prof_id	int,
			@table_id	int

		select
			@comp_id	= 1,
			@bra_id		= 1,
			@lang_id	= 2,
			@user_id	= 1,
			@prof_id	= 1,
			@table_id	= 43
		*/
	--------------------------------





	DECLARE @tablamenu AS TABLE (menu_id INT PRIMARY KEY,
									menu_id_sup INT,
									menu_order INT,
									menu_type INT,
									menu_desc NVARCHAR(200),
									menu_page NVARCHAR(1000),
									menu_parameters NVARCHAR(1000),
									menu_destiny BIT,
									menu_imageurl_path 	NVARCHAR(1000))


	INSERT INTO @tablamenu (menu_id , menu_id_sup, menu_order, menu_type, menu_desc,
				menu_page, menu_parameters, menu_destiny, menu_imageurl_path)
	EXEC spSysMenu_getDataAll	@lang_id, -1

	--SELECT * FROM @tablamenu




	SELECT DISTINCT
		tsml.mid_desc +  ' ( '+ isnull(tml4.mid_desc,'') +
								case when len(isnull(tml4.mid_desc,'')) > 0 then ', ' else '' end +
								isnull(tml3.mid_desc,'') +
								case when len(isnull(tml3.mid_desc,'')) > 0 then ', ' else '' end +
 								isnull(tml2.mid_desc,'') +
								case when len(isnull(tml2.mid_desc,'')) > 0 then ', ' else '' end +
								isnull(tml.mid_desc,'') + ' )'  [desc],
		tmenu.menu_page,
		tmenu.menu_parameters,
		tsmr.mr_order


		FROM tbsysMenu						tm						WITH (NOLOCK)

			INNER JOIN tbProfile tp									WITH (NOLOCK)
				ON		tp.comp_id = @comp_id
					and tp.prof_id = @prof_id

			inner join tbsysmenurelations	tsmr					WITH (NOLOCK)
			on tsmr.menu_id		= tm.menu_id

			inner join tbsysmenulanguage	tsml					WITH (NOLOCK)
			on tsml.menu_id		= tsmr.menu_id_related

			inner join tbmenugrants			tmg						WITH (NOLOCK)
			on	   tmg.menu_id	= tsmr.menu_id_related
				OR tp.prof_isSA = 'True'

			INNER JOIN  @tablamenu tmenu
			ON tsmr.menu_id_related = tmenu.menu_id

			--primer nivel
			left join tbsysMenu tm2									WITH (NOLOCK)
			on tm2.menu_id	=tsmr.menu_id_related

			left join tbsysMenuLanguage tml							WITH (NOLOCK)
			on tml.menu_id = tm2.menu_id_sup and tml.lang_id = @lang_id

			--segundo nivel
			left join tbsysMenu tm3									WITH (NOLOCK)
			on tm3.menu_id = tm2.menu_id_sup

			left join tbsysMenuLanguage tml2						WITH (NOLOCK)
			on tml2.menu_id = tm3.menu_id_sup and tml2.lang_id = @lang_id

			--tercer nivel
			left join tbsysMenu tm4									WITH (NOLOCK)
			on tm4.menu_id = tm3.menu_id_sup

			left join tbsysMenuLanguage tml3						WITH (NOLOCK)
			on tml3.menu_id = tm4.menu_id_sup and tml3.lang_id = @lang_id

			--cto. nivel
			left join tbsysMenu tm5									WITH (NOLOCK)
			on tm5.menu_id = tm4.menu_id_sup

			left join tbsysMenuLanguage tml4						WITH (NOLOCK)
			on tml4.menu_id = tm5.menu_id_sup and tml4.lang_id = @lang_id

			INNER JOIN tbUser tu									WITH (NOLOCK)
				ON tu.[user_id] = @user_id


			INNER JOIN tbsysMenuParameters tmp						WITH (NOLOCK)
			 ON tmp.ptype_id		= 1				AND
			 	tmp.ptypevalue_id	= @table_id		AND
			 	tmp.menu_id			= tm.menu_id


		WHERE tmg.comp_id	= @comp_id
		and	  (tmg.prof_id	= @prof_id OR tu.user_sysAdmin='true')
		and	  tsml.lang_id	= @lang_id

		order by tsmr.mr_order asc



END
GO






