CREATE PROCEDURE [dbo].[spSysNames_getDataById]
(
	@name_id			int
)
as



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


/*
declare	@name_id			int
select	@name_id			= 2
*/

select	n.lang_id,
		l.[lang_desc],
		n.table_id,
		ta.[table_desc],
		n.tab_id,
		t.[tab_desc],
		n.field_id,
		f.[field_name],
		n.type_id,
		y.[type_desc],
		isnull(n.name_desc,	'')					[name_desc],
		isnull(n.name_join, '')					[name_join],
		isnull(n.name_combo, '')				[name_combo],
		isnull(n.name_column, '')				[name_column],
		isnull(n.name_comboact, '')				[name_comboact],
		isnull(n.name_errormessage, '')			[name_errormessage],
		isnull(n.name_errormessage2, '')		[name_errormessage2],
		n.ctrl_id,
		c.[ctrl_desc],
		n.prop_id,
		p.[prop_desc],
		n.name_id		--el id tiene que estar obligatoriamente en última posición

from	dbo.[tbsysNames]					n			WITH (NOLOCK)

		left join dbo.[tbsysTables]			ta			WITH (NOLOCK)
		on	ta.[table_id]	= n.table_id

		left join dbo.[tbsysLanguage]		l			WITH (NOLOCK)
		on	l.[lang_id]		= n.lang_id

		left join dbo.[tbsysTabs]			t			WITH (NOLOCK)
		on	t.[table_id]	= n.table_id
		and t.[tab_id]		= n.tab_id

		left join dbo.[tbsysFields]			f			WITH (NOLOCK)
		on	f.[table_id]	= n.table_id
		and f.[field_id]	= n.field_id

		left join dbo.[tbsysTypes]			y			WITH (NOLOCK)
		on	y.[type_id]		= n.type_id

		left join dbo.[tbsysControls]		c			WITH (NOLOCK)
		on	c.[ctrl_id]		= n.ctrl_id

		left join dbo.[tbsysProperties]	p				WITH (NOLOCK)
		on	p.[prop_id]		= n.prop_id

where	n.name_id			= @name_id





















GO







CREATE PROCEDURE [dbo].[spSysNames_getDataByTab]
(
	@lang_id		int,
	@table_id		int,
	@tab_id			INT,
	@country_id		INT
)
as

BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	set nocount on

	/*
	declare	@lang_id		int,
			@table_id		int,
			@tab_id			int
	select	@lang_id		=2,
			@table_id		=115,
			@tab_id			=-1

	*/

	select	n.field_id,
			n.type_id,
			t.type_desc,
			dbo.fnSysWordsNew_GetText(@lang_id,@country_id,n.name_desc_id) [name_desc],
			n.name_join ,
			n.name_combo,
		--	n.name_errormessage_id,

			dbo.fnSysWordsNew_GetText(@lang_id,@country_id,n.name_desc_id) [name_column],
			n.name_comboact,
			dbo.fnSysWordsNew_GetText(@lang_id,@country_id,n.name_errormessage_id) [name_errormessage],
			dbo.fnSysWordsNew_GetText(@lang_id,@country_id,n.name_errormessage2_id)[name_errormessage2],
			n.ctrl_id,
			c.ctrl_desc,
			n.prop_id,
			p.prop_desc


--			tswn1.word_desc [name_column],
--			n.name_comboact,
--			tswn2.word_desc [name_errormessage],
--			tswn3.word_desc [name_errormessage2],
--			n.ctrl_id,
--			c.ctrl_desc,
--			n.prop_id,
--			p.prop_desc
--

	from	dbo.tbsysNamesNew 				n		WITH (NOLOCK)
			LEFT JOIN dbo.tbsysControls	c
			on	c.ctrl_id		= n.ctrl_id

			LEFT JOIN dbo.tbsysProperties	p		WITH (NOLOCK)
			on	p.prop_id		= n.prop_id

			INNER JOIN 	dbo.tbsysTypes		t		WITH (NOLOCK)
			on	t.type_id		= n.type_id

--			LEFT JOIN tbSysWordsNew tswn1
--			ON n.name_desc_id = tswn1.wordsi_id
--			AND tswn1.lang_id = @lang_id

--			LEFT JOIN tbSysWordsNew tswn2
--			ON n.name_errormessage_id = tswn2.wordsi_id
--			AND tswn2.lang_id = @lang_id

--			LEFT JOIN tbSysWordsNew tswn3
--			ON n.name_errormessage2_id = tswn3.wordsi_id
--			AND tswn3.lang_id = @lang_id





	where	--n.lang_id			= @lang_id
	--and
			n.table_id			= @table_id
	and		(n.tab_id			= @tab_id
	or	    (n.tab_id			= (select	tab_id			from tbsystabs
									where	table_id		= @table_id
									and		tab_isHidden	= 'True'))
	and		@tab_id = -1				)


END
GO







CREATE  PROCEDURE [dbo].[spSysNames_insertData]
(
		@lang_id						int,
		@table_id						int,
		@tab_id							int,
		@field_id						int,
		@type_id						int,
		@name_desc						varchar(200),
		@name_join						varchar(5000),
		@name_combo						varchar(5000),
		@name_column					varchar(1000),
		@name_comboact					varchar(5000),
		@name_errormessage				varchar(500),
		@name_errormessage2				varchar(500),
		@ctrl_id						int,
		@prop_id						int,
		@return_value					int output
)
as

insert into dbo.[tbsysNames]
(lang_id, table_id, tab_id, field_id, type_id, name_desc,
name_join, name_combo, name_column, name_comboact, name_errormessage,
name_errormessage2, ctrl_id, prop_id)

values
