CREATE PROCEDURE [dbo].[spSysNamesNew_getData]
(
	@table_id			int
)
as


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

set nocount on


/*
declare	@lang_id			int,
		@table_id			int
select	@lang_id			= 2,
		@table_id			= 5
*/
--tswn.word_desc,
select
		n.table_id,
		n.tab_id,
		t.[tab_desc],
		n.field_id,
		f.[field_name],
		n.type_id,
		y.[type_desc],
		n.name_desc_id,
		n.name_join,
		n.name_combo,
		n.name_comboact,
		n.name_errormessage_id,
		n.name_errormessage2_id,
		n.ctrl_id,
		c.[ctrl_desc],
		n.prop_id,
		p.[prop_desc],
		n.name_id

from	dbo.[tbsysNamesNew]					n

		left join dbo.[tbsysTabs]			t
		on	t.[table_id]	= n.table_id
		and t.[tab_id]		= n.tab_id

		left join dbo.[tbsysFields]			f
		on	f.[table_id]	= n.table_id
		and f.[field_id]	= n.field_id

		left join dbo.[tbsysTypes]			y
		on	y.[type_id]		= n.type_id

		left join dbo.[tbsysControls]		c
		on	c.[ctrl_id]		= n.ctrl_id

		left join dbo.[tbsysProperties]		p
		on	p.[prop_id]		= n.prop_id


		LEFT JOIN tbSysWordsNew tswn
		ON tswn.wordsi_id	= n.name_desc_id
		AND tswn.lang_id	= 2


where	n.table_id			= @table_id

order by n.type_id,	n.field_id




















GO







