CREATE PROCEDURE [dbo].[spSysNamesNew_getDataById]
(
	@name_id			int
)
AS

/*
declare	@name_id			int
select	@name_id			= 71
*/



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------

SELECT	n.table_id,
		ta.[table_desc],
		n.tab_id,
		t.[tab_desc],
		n.field_id,
		f.[field_name],
		n.type_id,
		y.[type_desc],
		isnull(n.name_desc_id, 0)				[name_desc],
		isnull(n.name_join, '')					[name_join],
		isnull(n.name_combo, '')				[name_combo],
		isnull(n.name_comboact, '')				[name_comboact],
		isnull(n.name_errormessage_id, 0)		[name_errormessage],
		isnull(n.name_errormessage2_id, 0)		[name_errormessage2],
		n.ctrl_id,
		c.[ctrl_desc],
		n.prop_id,
		p.[prop_desc],
		n.name_id

from	dbo.tbsysNamesNew					n

		left join dbo.[tbsysTables]			ta
		on	ta.[table_id]	= n.table_id

		left join dbo.[tbsysTabs]			t
		on	t.[table_id]	= n.table_id
		and t.[tab_id]		= n.tab_id

		left join dbo.[tbsysFields]			f
		on	f.[table_id]	= n.table_id
		and f.[field_id]	= n.field_id

		left join dbo.[tbsysTypes]			y
		on	y.[type_id]		= n.type_id

		left join dbo.[tbsysControls]		c
		on	c.[ctrl_id]		= n.ctrl_id

		left join dbo.[tbsysProperties]		p
		on	p.[prop_id]		= n.prop_id


		LEFT JOIN tbSysWordsNew tswn
		ON tswn.wordsi_id	= n.name_desc_id
		AND tswn.lang_id	= 2


where	n.name_id			= @name_id





















GO







