CREATE PROCEDURE [dbo].[spSysPageControls_getCombo]
(
		@comp_id		int,
		@lang_id		int,
		@bra_id			int,
		@prof_id		int,
		@page_id		int,
		@fun_id			int
)
AS


BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	SET NOCOUNT ON



	-- -------------------------------------
	-- -------------------------------------
	/*
	declare		@comp_id int,
				@lang_id int,
				@bra_id int,
				@prof_id int,
				@page_id int,
				@fun_id INT

	select		@comp_id =1,
				@lang_id =2,
				@bra_id  =1,
				@prof_id =1,
				@page_id =269,
				@fun_id =1
	*/
	-- -------------------------------------




	select	'(' +dbo.fnStrPADL( CONVERT(VARCHAR,pc.ctrl_id),5,'0') + ') '  + tw.word_desc			[desc],
			convert(varchar(9),pc.ctrl_id) + '-' + convert(varchar(9),t.prop_id)					[id],
			c.[type_id],
			t.prop_id,
			tw.word_desc	[Order]


		from	dbo.tbSysPageControls					pc			WITH (NOLOCK)

				inner join tbsysControls				c			WITH (NOLOCK)
				on	c.ctrl_id			=	pc.ctrl_id

				inner join tbsysTypes					st			WITH (NOLOCK)
				on	st.[type_id]		=	c.[type_id]

				inner join [tbsysTextsNew]				t			WITH (NOLOCK)
				on	t.[page_id]			=	pc.page_id
				and t.[ctrl_id]			=	c.[ctrl_id]
				and t.[type_id]			=	c.[type_id]
				and t.[prop_id]			IN	(1,20,2)	--(text,enabled,tooltip)

				INNER JOIN tbsysWordsNew				tw			WITH (NOLOCK)
				ON tw.lang_id			= @lang_id
				AND tw.wordsi_id		= t.wordsi_id

		WHERE   pc.page_id				=	@page_id
		AND 	t.fun_id				=	@fun_id
		AND 	st.type_candisabled		=	'True'

		-- ----------------------------------------------------------------------------------------
		-- ATENCION:
		-- Si se modifica algo aquí, copiar exactamente lo mismo al sp [spControlProfiles_getCombo]
		-- ----------------------------------------------------------------------------------------

		AND     ((t.type_id = 5		AND	t.prop_id = 2 )	or
				 (t.type_id = 3		AND	t.prop_id = 2 )	or
				 (t.type_id = 23	AND t.prop_id = 2 ) or
				 (t.type_id = 6  	AND t.prop_id = 2 ) or
				 (t.type_id = 59	AND t.prop_id = 20) or
				 (t.type_id = 61					  ) or
				 (t.type_id = 62					  ) or
				 (t.type_id <> 5	AND	t.prop_id = 1)  or
				 (t.type_id = 34  	AND t.prop_id = 2 ) )
				 AND t.type_id <> 40

		-- ----------------------------------------------------------------------------------------
		AND		pc.ctrl_id NOT IN ( SELECT	cp.ctrl_id
   									FROM	tbControlProfiles cp		WITH (NOLOCK)
									WHERE	cp.comp_id		=	@comp_id
									AND		cp.bra_id		=	@bra_id
									AND		cp.prof_id		=	@prof_id
									AND		cp.page_id		=	@page_id
									AND		cp.[type_id]	=	c.[type_id]
									AND		cp.prop_id		=	20 --enabled
									AND		cp.fun_id		=	@fun_id	)



	/**********************************************************************************************************/
	/* se agrega este union para recuperar los datos de los controles del toolbox relacionado a cada página   */

	UNION

	SELECT 	tov.optval_desc															[desc],
			CONVERT(VARCHAR(9),pc.ctrl_id) + '-' + CONVERT(VARCHAR(9),2)			[id],
			c.[type_id],
			2 [prop_id],
			optval_desc				[Order]


		FROM	dbo.tbSysPageControls					pc			WITH (NOLOCK)

				INNER JOIN tbsysControls				c			WITH (NOLOCK)
				ON	c.ctrl_id			=	pc.ctrl_id
				AND (c.ctrl_desc = 'imgExportToExcel' OR c.ctrl_desc = 'imgPrint' OR c.ctrl_desc = 'imgCopy')

				INNER JOIN tbsysTypes					st			WITH (NOLOCK)
				ON  st.[type_id]		=	c.[type_id]

				INNER JOIN tbsysOptionsValues			tov			WITH (NOLOCK)
				ON  tov.optval_class	= 5
				AND (
						(tov.optval_id = 5 AND c.ctrl_desc = 'imgCopy')				OR
						(tov.optval_id = 6 AND c.ctrl_desc = 'imgExportToExcel')	OR
						(tov.optval_id = 7 AND c.ctrl_desc = 'imgPrint')
					)


		WHERE   pc.page_id				=	@page_id
		AND 	tov.[lang_id]			=	@lang_id
		AND 	st.type_candisabled		=	'True'

		AND		pc.ctrl_id NOT IN ( SELECT	cp.ctrl_id
   										FROM	tbControlProfiles cp			WITH (NOLOCK)
										WHERE	cp.comp_id		=	@comp_id
										AND		cp.bra_id		=	@bra_id
										AND		cp.prof_id		=	@prof_id
										AND		cp.page_id		=	@page_id
										AND		cp.[type_id]	=	c.[type_id]
										AND		cp.prop_id		=	20 --enabled
										AND		cp.fun_id		=	@fun_id	)


	/**********************************************************************************************************/



	ORDER BY [Order]


END
GO











