CREATE PROCEDURE [dbo].[spSysPages_getDataCombo]
(
	@lang_id		int
)
AS




BEGIN



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	set nocount on


	-- -----------------------------------------------------
	-- Test
	-- -----------------------------------------------------
	/*
	declare  	@lang_id	int
	select		@lang_id	= 2
	*/
	-- -----------------------------------------------------


	/*Constantes utilizadas en el procedimiento*/
	declare		@ctrl_id		int,
				@type_id		INT,
				@prop_id		int

	select		@ctrl_id		= 29,
				@type_id		= 1,
				@prop_id		= 1



	select	distinct
			dbo.fnStrPADL( convert(varchar(9),sp.page_id),6,'0') + ': '  +
			--'(' +dbo.fnStrPADL( convert(varchar(9),sp.page_id),5,'0') + ') '  +   MOS 01-2022
				--tswn.word_desc
				ISNULL(
				(
					SELECT TOP 1 tswn2.word_desc
						FROM tbSysWordsNew tswn2	WITH (NOLOCK)
						INNER JOIN tbsysTextsNew ttn	WITH (NOLOCK)
							ON	ttn.page_id		= pc.page_id	AND
								ttn.ctrl_id		= 29			AND
								ttn.fun_id		= t.fun_id		AND
								tswn2.wordsi_id = ttn.wordsi_id	AND
								tswn2.lang_id	= @lang_id
				),CONVERT(NVARCHAR(20),t.fun_id))
																									[desc],
			convert(varchar(9),sp.page_id) + '-' + convert(varchar(9),t.fun_id)						[id] ,
			sp.page_order,
			sp.page_desc,
			(
					SELECT TOP 1 tswn2.word_desc
						FROM tbSysWordsNew tswn2	WITH (NOLOCK)
						INNER JOIN tbsysTextsNew ttn	WITH (NOLOCK)
							ON	ttn.page_id		= pc.page_id	AND
								ttn.ctrl_id		= 29			AND
								ttn.fun_id		= t.fun_id		AND
								tswn2.wordsi_id = ttn.wordsi_id	AND
								tswn2.lang_id	= @lang_id
			)																						[word_desc]

	INTO #tmpOrder
	from	dbo.tbSysPageControls		pc	WITH (NOLOCK)

			inner join dbo.tbsysPages	sp	WITH (NOLOCK)
			on pc.page_id			= sp.[page_id]

			--inner join tbsysControls	c
			--on	c.ctrl_id			= pc.ctrl_id

			--inner join tbsystypes		st
			--on c.type_id			= st.[type_id]

			inner join [tbsysTextsNew]		t	WITH (NOLOCK)
			on	t.[page_id]			= sp.[page_id]   AND
				t.ctrl_id			= pc.ctrl_id

			INNER JOIN tbSysWordsNew tswn	WITH (NOLOCK)
			ON tswn.lang_id			= @lang_id
			AND tswn.wordsi_id		= t.wordsi_id


			--inner join [tbsysTextsNew]		tp
			--on	tp.[page_id]			= sp.[page_id]   AND
			--	tp.ctrl_id				= 29		-- Titulo de la Pagina

			--INNER JOIN tbSysWordsNew pswn
			--ON	pswn.lang_id			= @lang_id
			--AND pswn.wordsi_id			= tp.wordsi_id




	WHERE	tswn.lang_id			= @lang_id

--	and		t.[ctrl_id]				= @ctrl_id
--	and		t.[type_id]				= @type_id
	and		t.[prop_id]				IN (1,20,2) --@prop_id
--	and		st.type_candisabled		= 'True'

	/*caso especial sólo para saleorder hasta encontrar un mejor método de filtrado*/
	AND		(
				(t.page_id <> 11) OR
				(t.page_id = 11 AND t.fun_id = 1)
			)
	/**********************************************************************************/

--AND pc.page_id = 128

	--Order BY sp.page_order,sp.page_desc,[desc]
	Order BY sp.page_desc


	SELECT tmp.[desc],tmp.id FROM #tmpOrder tmp ORDER BY [word_desc]

	DROP TABLE #tmpOrder

END
GO






CREATE procedure [dbo].[spSysPages_GrantsForGridImage]
(
	@comp_id	int,
	@lang_id	INT,
	@prof_id	INT,
	@page_desc	nvarchar(1000)
)
as



-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


set nocount on

-- ----------------------------------------------------
-- Testing
-- ----------------------------------------------------
/*
	declare
		@comp_id		int,
		@page_desc		nvarchar(1000),
		@prof_id		int,
		@lang_id		int

	select
		@comp_id		= 1,
		@lang_id		= 2,
		@prof_id		= 1,
		@page_desc		= 'wfmSaleOrderAllLoad'
*/
-- ----------------------------------------------------
declare
	@enabled	bit

if exists ( SELECT TOP 1  1 from tbsysMenu				tm		WITH (NOLOCK)
					inner join tbsysPages				tp		WITH (NOLOCK)
					on tp.page_id = tm.page_id
					inner join tbsysMenuLanguage		tml		WITH (NOLOCK)
					on tml.menu_id = tm.menu_id
					left join	tbMenuGrants			tmg		WITH (NOLOCK)
					on tmg.menu_id = tm.menu_id
			where	tml.lang_id		= @lang_id
			and		tp.page_desc	like @page_desc
			and		tmg.prof_id		= @prof_id)
	set @enabled = 'True'
else
	set @enabled = 'False'

select
	tm.menu_id,
	tml.mid_desc,
	tp.page_desc,
	@enabled	[Enabled]
--	tmg.menu_id

from tbsysMenu						tm		WITH (NOLOCK)

	inner join tbsysPages			tp		WITH (NOLOCK)
	on tp.page_id = tm.page_id

	inner join tbsysMenuLanguage	tml		WITH (NOLOCK)
	on tml.menu_id = tm.menu_id

--	left join	tbMenuGrants tmg
--	on tmg.menu_id = tm.menu_id

where	tml.lang_id		= @lang_id
and		tp.page_desc	= @page_desc
--and		tmg.prof_id = @prof_id
GO













