CREATE PROCEDURE [dbo].[spsysRMAProcType_getCombo]
(
	@lang_id			INT,
	@All				BIT,
	@All2				BIT
)
AS

BEGIN


	SET NOCOUNT ON


	/*
	declare		@lang_id	INT,
				@All		BIT,
				@All2		BIT

	select		@lang_id	= 2,
				@All		= 'true',
				@All2		= 'true'
	*/


	-- Enfermo HIJO DE PUTA!!!!!
	-- @All2 = False -> RMA CLIENTES
	-- @All2 = True  -> RMA Proveedores



	SELECT	s.srpt_id			[Id] ,
			o.[optval_desc]		[desc]
		FROM	dbo.tbsysRMAProcType			s
				INNER JOIN [tbsysOptionsValues] o
				ON	o.[optval_id]		= s.srpt_id
				AND o.lang_id			= @lang_id
				AND o.optval_class		= 109
		WHERE	(@All = 'true'	AND @All2 = 'false' AND s.srpt_id < 1000
			OR	(@All = 'false' AND @All2 = 'false' AND s.srpt_id < 1000)		-- IDIOTA ES AL PEDO!!!!!
			OR	(@All = 'false' AND @All2 = 'true'	AND s.srpt_id > 1000)
			OR	(@All = 'true'	AND @All2 = 'true'	AND s.srpt_id not BETWEEN '10' AND '200' ))
		ORDER BY [desc]


END
GO








