CREATE procedure [dbo].[spSysScript_Contacts_Cities]

as
SET NOCOUNT ON


BEGIN


	DECLARE @strExecute AS NVARCHAR(4000)

	SET @strExecute = '
	INSERT      INTO tbCities ( comp_id,  country_id,       state_id,         city_desc )
	SELECT      DISTINCT        1,  tc.country_id,    tc.state_id,      tc.contact_city
	FROM  tbContact        tc
	WHERE not tc.country_id is null
	AND         not tc.state_id         IS NULL
	and         not tc.contact_city  IS NULL
	and         tc.contact_city            <> ''''
	AND         NOT EXISTS (SELECT 1 FROM vwCities tc1
							WHERE tc1.country_id    = tc.country_id
							AND         tc1.state_id      = tc.state_id
							AND         ltrim(rtrim(tc1.city_desc))  = ltrim(rtrim(tc.contact_city))
							COLLATE Modern_Spanish_CI_AI )
					'
	EXEC (@strExecute)

	DECLARE @strExecute2 AS NVARCHAR(4000)

	SET @strExecute2 = '
	UPDATE      tbContact
		SET         city_id = tc2.city_id
		FROM  tbContact tc
			INNER JOIN vwCities tc2
				ON    tc2.country_id    = tc.country_id
				AND tc2.state_id  = tc.state_id
				AND ltrim(rtrim(tc2.city_desc))    = ltrim(rtrim(tc.contact_city))
				COLLATE Modern_Spanish_CI_AI
		WHERE tc.city_id IS NULL
					'
	EXEC (@strExecute2)





END
GO







