CREATE PROCEDURE [dbo].[spSysState_getCombo]
(
	@country_id			INT,
	@state_id			int
)
as

BEGIN

	set nocount on

	DECLARE @tbState AS TABLE([id] INT,[desc] NVARCHAR(50))

	/*
	declare @country_id			int
	select  @country_id			=2
	*/


	INSERT INTO @tbState

		select	state_id		[id],
				state_desc		[desc]

		from 	tbsysState

		where	country_id	=	@country_id AND state_id = @state_id

		Order By state_desc


	INSERT INTO @tbState

		select	state_id		[id],
				state_desc		[desc]

		from 	tbsysState

		where	country_id	=	@country_id AND state_id <> @state_id

		Order By state_desc


	SELECT * FROM @tbState

END
GO





