			tswn.word_desc												[desc]

	from 	[tbsysTables]					t

			INNER JOIN tbsysNamesNew			tn
			ON	tn.table_id	= t.table_id
			AND tn.ctrl_id	= 29
			AND tn.prop_id	= 1

