CREATE  procedure [dbo].[spSysTables_getData]
(

		@comp_id			INT,
		@table_name			NVARCHAR(MAX),
		@table_where		NVARCHAR(MAX),
		@table_orderby		NVARCHAR(MAX)


)
as

BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	/*
	declare	@comp_id			INT,
			@table_name			NVARCHAR(MAX),
			@table_where		NVARCHAR(MAX),
			@table_orderby		NVARCHAR(MAX)


	select	@comp_id = 1, @table_name		= 'tbCompany_unWorkDays', @table_where = 'WHERE nld_id = 2' , @table_orderby = ''


	*/



		DECLARE @strwhereandorderby AS NVARCHAR(MAX)
		SELECT	@strwhereandorderby = ' ' + @table_where + ' ' + @table_orderby + ' '


		DECLARE @strTableName AS NVARCHAR(200)
		SELECT	@strTableName = @table_name


		IF	UPPER(@strTableName) = 'TBCOMPANY'						OR
			UPPER(@strTableName) = 'TBUSER'							OR
			UPPER(@strTableName) = 'TBBRANCH'						OR
			UPPER(@strTableName) = 'TBCUSTOMER'						OR
			UPPER(@strTableName) = 'tbUserMailsAccountsRelation'	OR
			UPPER(@strTableName) = 'tbSMTPConfigurationByReplyTo'
			RETURN

		ELSE
			BEGIN

				IF @strTableName LIKE '%website%'
					BEGIN
						EXEC('
						SELECT  *
							FROM ' + @strTableName  + @strwhereandorderby
						  )

					END
				ELSE
					BEGIN
						EXEC('
						SELECT TOP 20 *
							FROM ' + @strTableName  + @strwhereandorderby
						  )

					END

			END



END
GO






CREATE  procedure [dbo].[spSysTables_getDataByFilters]
(
		@table_desc		varchar(200)
)
as


set nocount on

/*
declare	@table_desc		varchar(100)
select	@table_desc		= 'tbSysPrueba'
*/


if convert(bit,isnumeric(@table_desc)) = 'True'

	select 	table_desc,
			table_validation_routine,
			table_applycomp,
			table_applycountry,
			table_height,
			table_width

	from 	tbSysTables				WITH (NOLOCK)

	where 	table_id					= convert(integer,ltrim(rtrim(@table_desc)))

else

	select 	table_desc,
			table_validation_routine,
			table_applycomp,
			table_applycountry,
			table_height,
			table_width

	from 	tbSysTables				WITH (NOLOCK)

	where 	ltrim(rtrim(table_desc))	= ltrim(rtrim(@table_desc))


GO







CREATE  procedure [dbo].[spSysTables_getDataById]
(
		@table_id		int
)
as

	BEGIN

		/*
		declare	@table_desc		varchar(100)
		select	@table_desc		='tbsysprueba  '
		*/

		select 	table_desc,
				table_validation_routine,
				table_applycomp,
				table_applycountry,
				table_height,
				table_width,
				table_class,
				isnull(table_SPName,'')				[table_SPName],
				COUNT(tt.tab_id)					[QTYTabs],
				tb.table_PreSaveButtonAvailable,
				tb.table_NoTransaction,
				tb.table_SaveAndContinueButtonAvailable,
				ISNULL(tb.table_user_field,'')				[table_user_field],
				ISNULL(tb.table_user_field4Insert,'')		[table_user_field4Insert],
				ISNULL(tb.table_lastUpdateCD,'')			[table_lastUpdateCD]

			from 		tbSysTables		tb							WITH (NOLOCK)
			INNER JOIN	tbsysTabs		tt							WITH (NOLOCK)
				ON	tt.table_id		= tb.table_id AND
					tt.tab_isHidden = 'False'

			where 	tb.table_id	= @table_id
			GROUP BY 	table_desc,
						table_validation_routine,
						table_applycomp,
						table_applycountry,
						table_height,
						table_width,
						table_class,
						isnull(table_SPName,'')	,
						table_PreSaveButtonAvailable,
						tb.table_NoTransaction,
						tb.table_SaveAndContinueButtonAvailable,
						tb.table_user_field,
						tb.table_user_field4Insert,
						tb.table_lastUpdateCD

	END

GO






