CREATE PROCEDURE [dbo].[spsysTax_ChileActividad_Process_Auto]
(

	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@stca_id					INT,
	@stca_desc					NVARCHAR(150),
	@afeiva						NVARCHAR(5),
	@stca_cattrib				INT,
	@disint						NVARCHAR(50),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


)
AS


---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,
	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	stca_id						INT,
	stca_desc					NVARCHAR(150),
	afeiva						NVARCHAR(5),
	stca_cattrib				INT,
	disint						NVARCHAR(50),

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT,
	@bolIsOK					BIT


SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id4session				= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,

	@bra_id						= -1 ,


	@bolIsOK					='True',
	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 1000

---------------------------------------------------------------------------------
*/
SET NOCOUNT ON
SET DATEFORMAT 'YMD'


BEGIN
	declare @return_value	INT

				BEGIN TRY




					IF  EXISTS (SELECT tc.stca_id
					            FROM tbsysTax_ChileActividad		tc		WITH (NOLOCK)
							WHERE	tc.stca_id		= @stca_id)


						BEGIN
								UPDATE tbsysTax_ChileActividad
								SET
									stca_desc		= @stca_desc,
									afeiva			= @afeiva,
									stca_cattrib	= @stca_cattrib,
									disint			= @disint

									WHERE stca_id	= @stca_id

								set	@return_value = 1

						END

				ELSE
					BEGIN



					INSERT INTO tbsysTax_ChileActividad
					(
						stca_id,
						stca_desc,
						afeiva,
						stca_cattrib,
						disint
					)
					VALUES
					(
						@stca_id,
						@stca_desc,
						@afeiva,
						@stca_cattrib,
						@disint
					)

					set	@return_value = IDENT_CURRENT('tbsysTax_ChileActividad')   -- @@identity


					END

				END TRY
				BEGIN CATCH
					set	@return_value = 0
				END CATCH




				--IF @return_value <> 0
				--	BEGIN

				--		--EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL

				--		--EXEC [spSysScript_Contacts_Cities]


				--	END



END


















GO





