-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	Incorpora el Padron AFIP
--				desde la carpeta del Google Drive
-- =============================================

CREATE PROCEDURE [dbo].[spsysTaxAFIP_BulkInsertData]
	@Option								AS INT,
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS


BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '0'


	BEGIN TRY



		BEGIN TRANSACTION
		TRUNCATE	TABLE	tbsysTaxAFIPtmp
		DELETE		FROM	tbsysTaxAFIPtmp

		TRUNCATE	TABLE	tbsysTaxAFIP
		DELETE		FROM	tbsysTaxAFIP

-- SELECT * FROM tbsysTaxAFIPtmp
		DECLARE @strExec AS VARCHAR(MAX)
		SET @strExec  = 'BULK	INSERT  tbsysTaxAFIPtmp
			FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\PadronAFIP.txt''
			WITH ( ROWTERMINATOR=''0x0a'', FIELDTERMINATOR = ''|'',  CODEPAGE = ''1252'' )'

		EXEC (@strExec)

		INSERT INTO tbsysTaxAFIP
			(
				afip_cuit,
				afip_nombre,
				afip_impgan,
				afip_impiva,
				afip_impmon,
				afip_sociedad,
				afip_empleados
			)

				SELECT	substring(tta.afip_tmp,1,11)	[C1],	-- CUIT
					substring(tta.afip_tmp,12,30)	[C2],	-- DENOMINACION
					substring(tta.afip_tmp,42,2)	[C3],	-- IMP GANANCIAS			EX
					substring(tta.afip_tmp,44,2)	[C4],	-- IMP IVA					AC
					substring(tta.afip_tmp,46,2)	[C5],	-- MONOTRIBUTO				NI
					substring(tta.afip_tmp,48,1)	[C6],	-- INTEGRANTE SOC			N
					substring(tta.afip_tmp,49,1)	[C7]	-- EMPLEADOR				S

					FROM tbsysTaxAFIPTmp tta	WITH (NOLOCK)

--30545681508MUNICIPALIDAD DE GRAL SAN MARTEXACNINS00
--20215871313SARACCO MARTIN OLIDEN         NINIF NN08	 MONOTRIBUTO
--30711317283ASOCIACION CIVIL ONTOLOGICA PAACEXNINN00    EXENTO
--30545894838ASOCIACION DE BOMBEROS VOLUNTAEXEXNINS00    EXENTO

-- select * from tbsysTaxAFIP where afip_cuit = '30715805576'

		UPDATE tbsystaxafip
			SET afip_fiscalClass =
									CASE
										WHEN afip_impiva =  'AC'									THEN  1	-- OK
										WHEN afip_impiva IN('EX','XN') /*AND afip_impmon =  'NI'*/	THEN  4
										WHEN afip_impiva IN('AN') 									THEN  5
										WHEN afip_impiva =  'NI' AND afip_impmon <> 'NI'			THEN  3	-- OK
										ELSE															  2 -- 10-2019 MOS
									END

		TRUNCATE	TABLE	tbsysTaxAFIPtmp
		DELETE		FROM	tbsysTaxAFIPtmp
		COMMIT TRANSACTION

	END TRY

	BEGIN CATCH

		Set @return_value			= -1
		Set @ret_ErrorCode			= -1
		Set @ret_ErrorDescription	= 'Error Importando Datos de AFIP - Padron C.U.I.T.' +
		(
		SELECT
			--ERROR_NUMBER() AS ErrorNumber,
			--ERROR_SEVERITY() AS ErrorSeverity,
			--ERROR_STATE() AS ErrorState,
			--ERROR_PROCEDURE() AS ErrorProcedure,
			--ERROR_LINE() AS ErrorLine,
			ERROR_MESSAGE() AS ErrorMessage
		--Select 'AFIP Files NOT Imported  . . .'
		)
		ROLLBACK TRANSACTION
	END CATCH

END

GO






