-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	Incorpora el Padron AGIP
--				de percepciones y retenciones
--				desde la carpeta del servidor
--		'C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\Padron.txt'
--    Instalar un Google Drive con Usuario gbp.taxes@gmail.com
-- =============================================
CREATE PROCEDURE [dbo].[spsysTaxAGIP_BulkInsertData]
	@Option								AS INT,
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '0'
	DECLARE @strExec AS VARCHAR(MAX)

	BEGIN TRY
		SET @ret_ErrorDescription = '0'



		BEGIN TRANSACTION
		--Select 'Deleting  AGIP Files . . .'
		TRUNCATE	TABLE	tbsysTaxAGIP
		DELETE		FROM	tbsysTaxAGIP
		--Select 'Importing AGIP Files . . .'
		set @strExec  = 'BULK	INSERT  tbsysTaxAGIP
				FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\PadronAGIP.txt''
				WITH (FIELDTERMINATOR ='';'')'
        EXEC (@strExec)

		--Select 'AGIP Files Imported  . . .'
		COMMIT TRANSACTION
	END TRY

	BEGIN CATCH

		Set @return_value			= -1
		Set @ret_ErrorCode			= -1
		--Set @ret_ErrorDescription	= 'Error Importando Datos de *AGIP* , Padron Retenciones.-'
		Set @ret_ErrorDescription	= 'Error Importando Datos de AGIP - Padron Retenciones.-' +
			(SELECT
			--convert(varchar,ERROR_NUMBER())  + '-' +
			--convert(varchar,ERROR_SEVERITY())  + '-' +
			--convert(varchar,ERROR_STATE()) + '-' +
			--convert(varchar,ERROR_PROCEDURE())  + '-' +
			--convert(varchar,ERROR_LINE())  + '-' +
			ERROR_MESSAGE()
            )
		--Select 'AGIP Files NOT Imported  . . .'
		ROLLBACK TRANSACTION
	END CATCH

END
/*
BEGIN try
SELECT 1/0
END TRY
BEGIN catch
SELECT
			convert(varchar,ERROR_NUMBER())  + '-' +
			convert(varchar,ERROR_SEVERITY())  + '-' +
			convert(varchar,ERROR_STATE()) + '-' +
			--convert(varchar,ERROR_PROCEDURE())  + '-' +
