-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	Incorpora el Padron ARBA
--				de percepciones y retenciones
--				desde la carpeta del servidor
--				C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles--              qUE ESTA SINCRONIZADA CON gOOGLE dRIVE
-- =============================================
CREATE PROCEDURE [dbo].[spsysTaxARBA_BulkInsertData]
	@Option								AS INT,
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '0'
	DECLARE @strExec AS VARCHAR(MAX)

	BEGIN TRY



		BEGIN TRANSACTION
		--Select 'Deleting  ARBA Files . . .'
		TRUNCATE	TABLE	tbsysTaxARBAtmp
		DELETE		FROM	tbsysTaxARBAtmp
		TRUNCATE	TABLE	tbsysTaxARBA
		DELETE		FROM	tbsysTaxARBA
		--Select 'Importing ARBA Files . . .'

--==
--DECLARE @strExec VARCHAR(MAX)
--==

		set @strExec  = '  BULK	INSERT  tbsysTaxARBAtmp
							FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\PadronARBA_Per.txt''
							WITH (FIELDTERMINATOR ='';'',ROWTERMINATOR=''0x0a'' )'
		exec (@strExec)

		-- Inserta las Percepciones
		INSERT INTO tbsysTaxARBA		WITH (ROWLOCK)
		(
			arba_fromDate,
			arba_toDate,
			arba_cuit,
			arba_percepcion,
			arba_percepcionCode,
			arba_retencion,
			arba_retencionCode
		)
			SELECT	tta.arba_fromDate,
					tta.arba_toDate,
					tta.arba_cuit,
					tta.arba_impuesto,
					tta.arba_impuestoCode,
					0,
					0
				FROM tbsysTaxARBAtmp tta		WITH (NOLOCK)


		TRUNCATE	TABLE	tbsysTaxARBAtmp
		DELETE		FROM	tbsysTaxARBAtmp

		set @strExec  = '  BULK	INSERT  tbsysTaxARBAtmp
							FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\PadronARBA_Ret.txt''
							WITH (FIELDTERMINATOR ='';'',ROWTERMINATOR=''0x0a'' )'
		exec (@strExec)


		-- Inserta los que pudiesen no estar
		INSERT INTO tbsysTaxARBA	WITH (ROWLOCK)
		(
			arba_fromDate,
			arba_toDate,
			arba_cuit,
			arba_percepcion,
			arba_percepcionCode,
			arba_retencion,
			arba_retencionCode
		)
			SELECT	tta.arba_fromDate,
					tta.arba_toDate,
					tta.arba_cuit,
					0,
					0,
					0,
					0
				FROM tbsysTaxARBAtmp tta		WITH (NOLOCK)
				INNER JOIN tbsysTaxARBA tta2	WITH (NOLOCK)
					ON tta2.arba_cuit = tta.arba_cuit
				WHERE tta2.arba_cuit IS NULL

		-- Actualiza los % de retencion
		UPDATE tbsysTaxARBA		--WITH (ROWLOCK)
		SET
			arba_retencion		= tta2.arba_impuesto ,
			arba_retencionCode	= tta2.arba_impuestoCode
		FROM tbsysTaxARBA			tta			WITH (NOLOCK)
		INNER JOIN tbsysTaxARBAtmp tta2			WITH (NOLOCK)
			ON tta2.arba_cuit	= tta.arba_cuit



		--Select 'ARBA Files Imported  . . .'
		COMMIT TRANSACTION
	END TRY

	BEGIN CATCH

		Set @return_value			= -1
		Set @ret_ErrorCode			= -1
		Set @ret_ErrorDescription	= 'Error Importando Datos de ARBA - Padron Retenciones.-' +

		(SELECT
			--ERROR_NUMBER() AS ErrorNumber,
			--ERROR_SEVERITY() AS ErrorSeverity,
			--ERROR_STATE() AS ErrorState,
			--ERROR_PROCEDURE() AS ErrorProcedure,
			--ERROR_LINE() AS ErrorLine,
			ERROR_MESSAGE() AS ErrorMessage
		)
		--Select 'ARBA Files NOT Imported  . . .'
		ROLLBACK TRANSACTION
	END CATCH

END

GO





