CREATE PROCEDURE [dbo].[spsysTaxARBAEmbargos_BulkInsertData]
	@Option								AS INT,
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '0'
	DECLARE @strExec AS VARCHAR(MAX)

	BEGIN TRY
		SET @ret_ErrorDescription = '0'



		BEGIN TRANSACTION
		--Select 'Deleting  AGIP Files . . .'
		TRUNCATE	TABLE	tbsysTaxARBAEmbargos
		DELETE		FROM	tbsysTaxARBAEmbargos
		TRUNCATE	TABLE	tbsysTaxARBAEmbargosTMP
		DELETE		FROM	tbsysTaxARBAEmbargosTMP



		--Select 'Importing ARBA Files . . .'
		set @strExec  = 'BULK	INSERT  tbsysTaxARBAEmbargosTMP
				FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\padronembargosarba.txt''
				WITH (FIELDTERMINATOR ='';'')'
        EXEC (@strExec)


		INSERT INTO tbsysTaxARBAEmbargos (	stea_date,
											stea_cuit,
											stea_total,
											stea_descOfCustomer
										)

				SELECT	substring(tta.stea_tmp,1,8)	[C1],
					substring(tta.stea_tmp,9,11)	[C2],
					convert(decimal(19,2),substring(tta.stea_tmp,20,11) + '.' + substring(tta.stea_tmp,31,2))	[C3],
					substring(tta.stea_tmp,33,120)	[C4]

					FROM tbsysTaxARBAEmbargosTMP tta		WITH (NOLOCK)

		TRUNCATE	TABLE	tbsysTaxARBAEmbargosTMP
		DELETE		FROM	tbsysTaxARBAEmbargosTMP

		--Select 'AGIP Files Imported  . . .'
		COMMIT TRANSACTION
	END TRY

	BEGIN CATCH

		Set @return_value			= -1
		Set @ret_ErrorCode			= -1

		Set @ret_ErrorDescription	= 'Error Importando Datos de ARBA - Padron de Embargos.-' +
			(SELECT
			--convert(varchar,ERROR_NUMBER())  + '-' +
			--convert(varchar,ERROR_SEVERITY())  + '-' +
			--convert(varchar,ERROR_STATE()) + '-' +
			--convert(varchar,ERROR_PROCEDURE())  + '-' +
			--convert(varchar,ERROR_LINE())  + '-' +
			ERROR_MESSAGE()
            )
		--Select 'AGIP Files NOT Imported  . . .'
		ROLLBACK TRANSACTION
	END CATCH

END
/*
BEGIN try
SELECT 1/0
END TRY
BEGIN catch
SELECT
			convert(varchar,ERROR_NUMBER())  + '-' +
			convert(varchar,ERROR_SEVERITY())  + '-' +
			convert(varchar,ERROR_STATE()) + '-' +
			--convert(varchar,ERROR_PROCEDURE())  + '-' +
			convert(varchar,ERROR_LINE())  + '-' +
			ERROR_MESSAGE()
END CATCH
*/
GO




