-- Update : Se agregó la opcion de JUJUY
-- GA
-- 06/11/18
-----------------------

CREATE PROCEDURE [dbo].[spSysTaxBook_getDataByID]
(
		@option       INT,
		@agip_cuit    VARCHAR(20)
)

AS
SET NOCOUNT ON

/*
DECLARE

	@agip_cuit    VARCHAR(20)

SELECT

    @agip_cuit = 20000000230
*/

IF @option = 1
	 BEGIN
 		-- === AGIP ===
		SELECT  tta.agip_percepcion,
				tta.agip_retencion

		FROM	tbsysTaxAGIP tta

		WHERE   tta.agip_cuit =  @agip_cuit
	 END

	ELSE

	-- === ARBA ===
	IF @option = 2
		 BEGIN

			SELECT      tta.arba_percepcion,
						tta.arba_retencion

			FROM	tbsysTaxARBA tta

			WHERE   tta.arba_cuit =  @agip_cuit

		 END
	ELSE

	IF @option = 3
		-- === TUCUMAN ===
		BEGIN
			SELECT      ttt.tucuman_coeficiente

			FROM tbsysTaxTUCUMAN ttt

			WHERE   ttt.afip_cuit =  @agip_cuit
		END

	ELSE
		-- === JUJUY ===
		BEGIN
			SELECT      ttj.percepcion,
						ttj.retencion

			FROM tbsysTaxJUJUY ttj

			WHERE   ttj.cuit =  @agip_cuit
		END






GO



-----------------------
-- Update : Se agregó la opcion de JUJUY
-- GA
-- 06/11/18
-----------------------


CREATE PROCEDURE [dbo].[spSysTaxBook_Update]
(
	@agip_cuit           VARCHAR(20),
	@agip_percepcion	 VARCHAR (100),
	@agip_retencion		 VARCHAR (100),
    @option				 INT
)

AS
SET NOCOUNT ON

/*
DECLARE

	@agip_percepcion	 VARCHAR (100),
	@agip_retencion		 VARCHAR (100),
	@agip_cuit			 VARCHAR  (20),
	@option			     INT

SELECT

    @agip_cuit = 20000000230,
    @agip_percepcion = -1,
    @agip_retencion  = -1
	@option = 1
*/


      IF @option = 1
			BEGIN
				-- === AGIP ===
				UPDATE  tbsysTaxAGIP

				SET 	agip_percepcion = @agip_percepcion,
						agip_retencion  = @agip_retencion

				WHERE   agip_cuit =  @agip_cuit
			END
		ELSE

			IF @option = 2

				BEGIN
					-- === ARBA ===
					UPDATE tbsysTaxARBA

					SET  arba_percepcion =  @agip_percepcion,
						 arba_retencion  =  @agip_retencion

					WHERE arba_cuit = @agip_cuit
				END
			ELSE

				IF @option = 3

				BEGIN
					-- === TUCUMAN ===
					UPDATE tbsysTaxTUCUMAN

					SET tucuman_coeficiente = @agip_percepcion

					WHERE afip_cuit = @agip_cuit
				END
			ELSE

				IF @option = 4

				BEGIN
					-- === JUJUY ===
					UPDATE tbsysTaxJUJUY

					SET percepcion = @agip_percepcion,
						retencion  = @agip_retencion

					WHERE cuit = @agip_cuit
				END









GO





