-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	Incorpora el Padron AFIP
--				desde la carpeta del Google Drive
-- =============================================

CREATE  PROCEDURE [dbo].[spsysTaxCORDOBA_Retenciones_BulkInsertData]
	@Option								AS INT,
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS


BEGIN

	-- ----------------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------------
	/*
	declare @Option								AS INT = 0,
			@return_value						as int	= 0		,
			@ret_ErrorCode						as int	= 0		,
			@ret_ErrorDescription				as varchar(200) = ''
	*/
	-- ----------------------------------------------------------------------






	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '0'


	BEGIN TRY

		BEGIN TRANSACTION

		TRUNCATE	TABLE	tbsysTaxCORDOBA_Retenciones
		DELETE		FROM	tbsysTaxCORDOBA_Retenciones

		TRUNCATE	TABLE	tbsysTaxCORDOBA_RetencionesTMP
		DELETE		FROM	tbsysTaxCORDOBA_RetencionesTMP

		BULK	INSERT  tbsysTaxCORDOBA_RetencionesTMP
					FROM 'C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\padronCORDOBA_Ret.txt'
					WITH ( ROWTERMINATOR='0x0a', FIRSTROW = 0 )

		INSERT INTO tbsysTaxCORDOBA_Retenciones
						(	cuit,
							loc_conv,
							alicuota
						)
				SELECT 	DISTINCT
						substring(tta.tmp,30,11)	[C1],	-- CUIT
						substring(tta.tmp,42,1)		[C2],
						CONVERT(DECIMAL(5,2), dbo.fnGetOnlyNumbersAndPoint(REPLACE(substring(tta.tmp,48,5),',','.')) ) [C4]	-- Los FORROS CORDOBESES y CHORROS NO saben generar un CSV y armaron un reputo archivo posicional con MIERDA metida entre medio que revienta los numeros
						FROM tbsysTaxCORDOBA_RetencionesTMP tta	WITH (NOLOCK)

		TRUNCATE	TABLE	tbsysTaxCORDOBA_RetencionesTMP
		DELETE		FROM	tbsysTaxCORDOBA_RetencionesTMP



		-- MOS 06-2024: Borra duplicados con alicuota cero ya que los FORROS estos ponian el mismo cuit con dos alicuotas.. en unos 20 casos en todo el padron.
		SELECT cuit
			INTO #tmpFile
			FROM tbsysTaxCORDOBA_Retenciones
			GROUP BY cuit HAVING COUNT(*) > 1
		DELETE tbsysTaxCORDOBA_Retenciones
			FROM tbsysTaxCORDOBA_Retenciones ori
			INNER JOIN #tmpFile tmp
				ON tmp.cuit = ori.cuit
			WHERE ori.alicuota = 0
		DROP TABLE #tmpFile
		-- MOS 06-2024: Borra duplicados con alicuota cero ya que los FORROS estos ponian el mismo cuit con dos alicuotas.. en unos 20 casos en todo el padron.


		COMMIT TRANSACTION

	END TRY

	BEGIN CATCH

		Set @return_value			= -1
		Set @ret_ErrorCode			= -1
		Set @ret_ErrorDescription	= 'Error Importando Datos de AFIP - Padron C.U.I.T.' +
		(
		SELECT
			--ERROR_NUMBER() AS ErrorNumber,
			--ERROR_SEVERITY() AS ErrorSeverity,
			--ERROR_STATE() AS ErrorState,
			--ERROR_PROCEDURE() AS ErrorProcedure,
			--ERROR_LINE() AS ErrorLine,
			ERROR_MESSAGE() AS ErrorMessage
		--Select 'AFIP Files NOT Imported  . . .'
		)
		ROLLBACK TRANSACTION
	END CATCH

END

GO





