CREATE PROCEDURE [dbo].[spSysTaxNumberTypes_getCombo]
(
	@comp_id		INT,
	@prof_id		INT,
	@fc_id			INT
)
AS
BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	set nocount on

	/*
	DECLARE 	@fc_id			integer
	SELECT		@fc_id			= 15
	*/

	select		stnt.tnt_id						[Id],
				stnt.tnt_desc					[desc]

		from		dbo.tbsysTaxNumberTypes								stnt		WITH (NOLOCK)

					INNER JOIN tbsysFiscalClassAvailableTaxNumberTypes	sfcatnt		WITH (NOLOCK)
					ON sfcatnt.tnt_id	=	stnt.tnt_id

					LEFT JOIN tbTaxNumberTypedDisabledByProfile ttntdbp				WITH (NOLOCK)
						ON	ttntdbp.comp_id = @comp_id AND
							ttntdbp.prof_id = @prof_id AND
							ttntdbp.tnt_id  = stnt.tnt_id

		WHERE		sfcatnt.fc_id		=	@fc_id AND
					ttntdbp.comp_id		IS NULL
		ORDER BY stnt.tnt_order, stnt.tnt_desc

	-- No POner Pls.
	--order by	stnt.tnt_desc

END




















GO





