-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	Incorpora el Padron AFIP
--				desde la carpeta del Google Drive
-- =============================================

CREATE PROCEDURE [dbo].[spsysTaxTUCUMAN_BulkInsertData]
	@Option								AS INT,
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS

BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;



	-- ----------------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------------
	/*
	DECLARE
		@Option								AS INT,
		@return_value						as INT,
		@ret_ErrorCode						as INT,
		@ret_ErrorDescription				as varchar(200)
	*/
	-- ----------------------------------------------------------------







	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '0'
	DECLARE @strExec AS VARCHAR(MAX)

	BEGIN TRY




		BEGIN TRANSACTION



			TRUNCATE	TABLE	tbsysTaxTUCUMANtmp
			DELETE		FROM	tbsysTaxTUCUMANtmp

			TRUNCATE	TABLE	tbsysTaxTUCUMAN
			DELETE		FROM	tbsysTaxTUCUMAN

			set @strExec  = 'BULK	INSERT  tbsysTaxTUCUMANtmp
				FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\archivocoefrg116.TXT''
				WITH ( ROWTERMINATOR=''\n'', FIELDTERMINATOR = ''|'' )'

			EXEC (@strExec)


			INSERT INTO tbsysTaxTUCUMAN
			(
				afip_cuit,
				tucuman_fecha,
				tucuman_coeficiente,
				tucuman_porcentaje
			)
					SELECT	DISTINCT
							substring(tta.tucuman_tmp,1,11)	,
							substring(tta.tucuman_tmp,25,6),
							CASE
								WHEN ISNUMERIC(substring(tta.tucuman_tmp,15,09)) = 1 THEN convert(decimal(10,4),substring(tta.tucuman_tmp,15,09))
								ELSE 	0
							END,
							CASE
								WHEN ISNUMERIC(substring(tta.tucuman_tmp,185,09)) = 1 THEN convert(decimal(10,4),substring(tta.tucuman_tmp,185,09))
								ELSE	0
							END

						FROM tbsysTaxTUCUMANtmp tta	WITH (NOLOCK)
						WHERE ISNUMERIC(substring(tta.tucuman_tmp,3,3))		= 1	--AND
							  --ISNUMERIC(substring(tta.tucuman_tmp,15,09))	= 1


			--UPDATE tbsysTaxTUCUMAN
			--	SET tucuman_coeficiente = 0.1
			--	WHERE tucuman_coeficiente = 0




			TRUNCATE	TABLE	tbsysTaxTUCUMANtmp
			DELETE		FROM	tbsysTaxTUCUMANtmp

			TRUNCATE	TABLE	tbsysTaxTUCUMAN_General
			DELETE		FROM	tbsysTaxTUCUMAN_General




			set @strExec  = 'BULK	INSERT  tbsysTaxTUCUMANtmp
				FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\ACREDITAN.TXT''
				WITH ( ROWTERMINATOR=''\n'', FIELDTERMINATOR = ''|'' )'

			EXEC (@strExec)





			INSERT INTO tbsysTaxTUCUMAN_General
			(
				cuit,
				tuge_isExento,
				tuge_Tipo,
				tuge_fecha,
				tuge_porcentaje
			)
					SELECT	DISTINCT
							substring(tta.tucuman_tmp,1,11)	,
							CASE
								WHEN substring(tta.tucuman_tmp,14,1) = 'E' THEN 1
								ELSE 0
							END,
							substring(tta.tucuman_tmp,17,2),
							substring(tta.tucuman_tmp,21,8),
							CASE
								WHEN ISNUMERIC(substring(tta.tucuman_tmp,193,09)) = 1 THEN convert(decimal(10,4),substring(tta.tucuman_tmp,193,09))
								ELSE 	0
							END

						FROM tbsysTaxTUCUMANtmp tta	WITH (NOLOCK)
						WHERE ISNUMERIC(substring(tta.tucuman_tmp,3,3))		= 1



			TRUNCATE	TABLE	tbsysTaxTUCUMANtmp
			DELETE		FROM	tbsysTaxTUCUMANtmp
		COMMIT TRANSACTION

	END TRY

	BEGIN CATCH

		Set @return_value			= -1
		Set @ret_ErrorCode			= -1
		Set @ret_ErrorDescription	= 'Error Importando Datos de AFIP - Padron C.U.I.T.' +
		(
		SELECT
			--ERROR_NUMBER() AS ErrorNumber,
			--ERROR_SEVERITY() AS ErrorSeverity,
			--ERROR_STATE() AS ErrorState,
			--ERROR_PROCEDURE() AS ErrorProcedure,
			--ERROR_LINE() AS ErrorLine,
			ERROR_MESSAGE() AS ErrorMessage
		--Select 'AFIP Files NOT Imported  . . .'
		)
		ROLLBACK TRANSACTION
	END CATCH

END

GO





-- =============================================
-- Author:		MOS
-- Create date: 06-2011
-- Description:	Redondea Asientos a 2 Decimales
-- Es para ejecutar de manera manual si se debe
-- redondear asientos viejos efectuados a 4
-- decimales cuando en realidad debian estar a
-- DOS.!
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_AccountantRoundTo2Decimals]
	@comp_id AS INT,
	@bra_id  AS INT,
	@ccCode	 AS INT,
	@userId  AS INT
AS
BEGIN
	SET NOCOUNT ON;

	UPDATE tbAccountTransactionDetail
	SET
		dacc_debit	= ROUND(dacc_debit,2),
		dacc_credit = ROUND(dacc_credit,2)


	Declare @SumCredit		As Decimal(29,6)
	Declare @SumDebit		As Decimal(29,6)
	Declare @Acc_Count_id	As Int
	Declare @dacc_debit		As Decimal(29,6)
	Declare @dacc_credit	As Decimal(29,6)
	DECLARE @intHACC		AS INT


	DECLARE curAccountant
	CURSOR  LOCAL FAST_FORWARD FOR SELECT tath.hacc_transaction FROM tbAccountTransactionHead tath

	OPEN curAccountant
	FETCH curAccountant INTO @intHACC

	WHILE @@FETCH_STATUS = 0
		BEGIN

			Select @SumCredit	= Sum(dacc_credit),
				   @SumDebit	= Sum(dacc_Debit)
				From dbo.tbAccountTransactionDetail
				Where   comp_id			= @comp_id
					AND hacc_transaction= @intHACC

			If (@SumCredit - @SumDebit) <> 0
				Begin
							Select @Acc_Count_id = Acc_Count_id
								From dbo.tbAccountManagementRelations
								Where	comp_id = @comp_id
									and	bra_id  = @bra_id
									and samr_id = 25

							If @Acc_Count_id is Null
								Begin
									SELECT 'Error de Cuenta de Ajuste'
								End
							Else
								-- efectua Imputacion Contable x Redondeo
								Begin

									If @SumCredit > @SumDebit
										Begin
											Set @dacc_debit		= @SumCredit - @SumDebit
											Set @dacc_Credit	= 0
										End
									Else
										Begin
											Set @dacc_debit		= 0
											Set @dacc_Credit	= @SumDebit - @SumCredit
										End


									INSERT INTO dbo.tbAccountTransactionDetail
										   (comp_id,
											bra_id,
											hacc_transaction,
											acc_count_id,
											cc_code,
											dacc_debit,
											dacc_credit,
											user_id,
											dacc_cd,
											hacc_software,
											ct_transaction,
											acc_detail1,
											acc_detail2,
											dacc_order)
									 VALUES
										   (@comp_id,
											@bra_id,
											@intHACC,
											@acc_count_id,
											@ccCode,
											@dacc_debit,
											@dacc_credit,
											@userId,
											getdate(),
											'True',
											NULL,
											'Ajuste x Redondeo a 2 Decimales.!',
											'',
											30)



								End
						End

			FETCH curAccountant INTO @intHACC
		END
	CLOSE  curAccountant
	DEALLOCATE  curAccountant

END

GO





-- --------------------------------------
-- Escribe un Texto en el HD del Servidor
-- MOS   10-2009
-- --------------------------------------

CREATE PROCEDURE spSystem_AppendToFile(
	@strFileName	as varchar(255),
	@strText2Save		as varchar(max))
AS

BEGIN

	DECLARE @FS				as int
	declare @objOLEResult	as INT
	DECLARE @FileID			as int


	EXECUTE @objOLEResult = sp_OACreate 'Scripting.FileSystemObject', @FS OUT
	IF @objOLEResult <> 0 PRINT 'Error en Scripting.FileSystemObject'

	-- Abre Archivo de Texto
	execute @objOLEResult = sp_OAMethod @FS, 'OpenTextFile', @FileID OUT, @strFileName, 8, 1
	IF @objOLEResult <> 0 PRINT 'Error en OpenTextFile'

	--Escribe el Texto
	execute @objOLEResult = sp_OAMethod @FileID, 'WriteLine', Null, @strText2Save
	IF @objOLEResult <> 0 PRINT 'Error en WriteLine'

	EXECUTE @objOLEResult = sp_OADestroy @FileID
	EXECUTE @objOLEResult = sp_OADestroy @FS

END
GO






