-- =============================================
-- Author:		MOS
-- Create date: Verifica saltos de numeracion de comprobantes de ventas
-- =============================================
CREATE PROCEDURE spSystem_CheckDocumentNumberFaults
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @intDocumentNumberFrom	AS INT
	DECLARE @intDocumentNumberTo	AS INT
	DECLARE @intCounter				AS INT
	DECLARE @intPointOfSale			AS INT
	DECLARE @strKindOf				AS NVARCHAR(1)
	DECLARE @intSD_ID				AS INT
	DECLARE @intErrorCount			AS INT

	-- --------------------------------------------
	-- Datos a Validar
	-- --------------------------------------------
	SET @strKindOf				= 'B'
	SET @intPointOfSale			= 21
	SET @intSD_ID				= 1
	SET @intDocumentNumberFrom	= 20000
	SET @intDocumentNumberTo    = 20010
	-- --------------------------------------------
	SET @intErrorCount			= 0
	SET @intCounter = @intDocumentNumberFrom
	WHILE @intCounter <= @intDocumentNumberTo
		BEGIN
			IF NOT EXISTS(	SELECT 1
		              			FROM tbCommercialTransactions tct
		              			WHERE	tct.ct_kindOf		= @strKindOf
		              				AND tct.ct_pointOfSale	= @intPointOfSale
		              				AND tct.sd_id			= @intSD_ID
		              				AND tct.ct_docNumber	= convert(NVARCHAR(20), @intCounter)
						)
				BEGIN
					SELECT @intCounter
					SET @intErrorCount = @intErrorCount + 1
				END
			SET @intCounter = @intCounter + 1
		END

	SELECT 'Errores de salto de numeracion:',@intErrorCount


END
GO





