-- =============================================
CREATE PROCEDURE [dbo].[spSystem_ConfigureSQLEmailByReplyTo]
(
	@comp_id		INT,
	@smtp_id		INT
)
AS
BEGIN


	-- MOS 03-2022
	RETURN

	-- ---------------------------------------------------------
	--  ATENCION
	--  Si se configura algo diferente aqui ver tambien en
	--  [spSystem_ConfigureSQLEmailByReplyTo]
	--  [spSystem_ConfigureSQLEmail]
	-- ---------------------------------------------------------

	SET NOCOUNT ON;

	DECLARE @strDataBase			AS VARCHAR(MAX)
	DECLARE @strSMTPHost			AS NVARCHAR(MAX)
	DECLARE @intPort				AS INT
	DECLARE @strEmail_address		AS NVARCHAR(2000)
	DECLARE @strReplyto_address		AS NVARCHAR(2000)
	DECLARE @strDisplay_name		AS NVARCHAR(2000)
	DECLARE @strUsername			AS NVARCHAR(2000)
	DECLARE @strPassword			AS NVARCHAR(2000)
	DECLARE @strProfile				AS NVARCHAR(2000)
	DECLARE @strProfileName			AS NVARCHAR(2000)
	DECLARE @bitEnable_ssl			AS BIT

	SET		@strDataBase		= DB_NAME()
	SELECT
			@intPort			= tc.smtp_port,
			@strSMTPHost		= tc.smtp_host,
			@strEmail_address	= IsNull(tc.smtp_ReplyTo,''),
			@strReplyto_address = IsNull(tc.smtp_ReplyTo,''),
			@strDisplay_name	= IsNull(tc.smtp_defaultFromText,''),
			@strUsername		= case
									WHEN tc.smtp_ValidationRequired='True' THEN  tc.smtp_user
									ELSE ''
								  END,
			@strPassword		= case
									when tc.smtp_ValidationRequired='true' THEN  tc.smtp_password
									ELSE ''
								  END,
			@bitEnable_ssl		= tc.smtp_ssc,
			@strProfile			= IsNull(tc.smtp_profileName,'GBP')
		FROM tbSMTPConfigurationByReplyTo tc
	WHERE	tc.comp_id = @comp_id AND
			tc.smtp_id = @smtp_id

	IF @strProfile <> ''
		BEGIN

				SET @strProfileName = @strProfile + '_Profile'

				exec sp_configure 'show advanced options', 1
				RECONFIGURE;

				exec sp_configure 'Database Mail XPs', 1
				RECONFIGURE;

				BEGIN TRY
					exec msdb.dbo.sysmail_delete_account_sp @account_name			= @strProfile
				END TRY
				BEGIN CATCH
					SELECT 'No hay definidos Servidores de EMail.1'
				END CATCH

				BEGIN TRY
					exec msdb.dbo.sysmail_delete_profile_sp @profile_name			= @strProfileName
				END TRY
				BEGIN CATCH
					SELECT 'No hay definidos Servidores de EMail.2'
				END CATCH

				BEGIN TRY
					exec msdb.dbo.sysmail_delete_profileaccount_sp @profile_name	= @strProfileName
				END TRY
				BEGIN CATCH
					SELECT 'No hay definidos Servidores de EMail.3'
				END CATCH

				BEGIN TRY
					exec msdb.dbo.sysmail_delete_principalprofile_sp @profile_name	= @strProfileName
				END TRY
				BEGIN CATCH
					SELECT 'No hay definidos Servidores de EMail.4'
				END CATCH




				DECLARE @strProfileNameGBP AS NVARCHAR(MAX)
				SET @strProfileNameGBP = 'GBP Mail Account: '  + @strProfileName

				exec msdb.dbo.sysmail_add_account_sp	@account_name			= @strProfile,
														@description			= @strProfileNameGBP,
														@email_address			= @strEmail_address,
														@replyto_address		= @strReplyto_address,
														@display_name			= @strDisplay_name,
														@mailserver_name		= @strSMTPHost,
														@port					= @intPort,
														@username				= @strUsername,
														@password				= @strPassword,
														@enable_ssl				= @bitEnable_ssl,
														@use_default_credentials=0;

				exec msdb.dbo.sysmail_add_profile_sp	@profile_name = @strProfileName ,
														@description  = 'Profile used for administrative mail.';

				exec msdb.dbo.sysmail_add_profileaccount_sp @profile_name = @strProfileName,
															@account_name = @strProfile,
															@sequence_number =1;

				exec msdb.dbo.sysmail_add_principalprofile_sp	@profile_name = @strProfileName,
																@principal_name = 'public', @is_default = 0;

				RECONFIGURE;

		END

END
GO



-- =============================================
