-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE spSystem_CreateFTS4tbItem
AS
BEGIN

			-- ---------------------------------------------------------------------------
			-- Reference:
			-- ---------------------------------------------------------------------------
			IF  EXISTS(
							SELECT 1
					   			FROM tbSystem_DatabaseVersion tsdv
								WHERE ISNULL(tsdv.isFTS4ItemEnabled,0) = 0
						 )
				BEGIN

					IF (FULLTEXTSERVICEPROPERTY('IsFullTextInstalled') = 1)
						BEGIN TRY

							EXECUTE sp_fulltext_database 'enable'
							EXECUTE sp_fulltext_database 'enable'
							exec sp_fulltext_catalog N'catITEM', N'create';
							exec sp_fulltext_table N'[dbo].[tbItem]', N'create', N'catITEM', N'IX_tbItem_ItemIdUNIQUE';
							exec sp_fulltext_column N'[dbo].[tbItem]', N'item_desc', N'add', 3082;
							exec sp_fulltext_table N'[dbo].[tbItem]', N'activate';
							exec sp_fulltext_catalog N'catITEM', N'start_full';
							SELECT 'FTS 4 Items ENABLED !'

							UPDATE tbSystem_DatabaseVersion
								SET	isFTS4ItemEnabled = 'TRUE'

						END TRY
						BEGIN CATCH
							SELECT 'FTS NO ACTIVO !!!!!!!!!!!!!!'
						END CATCH


				END
END
GO






-- MOS
CREATE procedure spSystem_CrossTab (
									@strSelect varchar(max),
									@strPivotCol varchar(max),
									@strSummaries varchar(max),
									@strGroupBy varchar(max),
									@strOtherCols varchar(max) = Null)
AS

BEGIN


-- -------------------------------------------------
-- Testing
-- ATENCION, en @strSummaries debe haber solo un espacio
-- entre el ) y el [ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
-- -------------------------------------------------
/*
	DECLARE 	@strSelect varchar(1000),
				@strPivotCol varchar(100),
				@strSummaries varchar(100),
				@strGroupBy varchar(100),
				@strOtherCols varchar(100)

	SELECT 		@strSelect = 'Select * from tbPriceListItems',
				@strPivotCol ='prli_id',
				@strSummaries = 'SUM(prli_price) [_Precio]',
				@strGroupBy = 'prli_id',
				@strOtherCols = NULL
*/
-- -------------------------------------------------


	set nocount on
	set ansi_warnings off

	declare @Vals as varchar(8000);
	set @Vals = ''

	set @strOtherCols= isNull(', ' + @strOtherCols,'')

	create table #tmpData  (fldPivot varchar(100))

	insert into #tmpData
	exec ('select distinct convert(varchar(100),' + @strPivotCol + ') as fldPivot FROM (' + @strSelect + ') A')


	--SELECT * FROM #tmpData
	-- drop table #tmpData
	-- return

	select @Vals =	@Vals + ', ' +
					replace(
							replace(
									@strSummaries,'(','(CASE WHEN ' + @strPivotCol + '=''' +
									fldPivot +  ''' THEN '
									)	,') [', '  END) as [' + fldPivot
							)
	from #tmpData
	order by fldPivot

	drop table #tmpData

	--SELECT @Vals
	-- RETURN
	SET @Vals =  'select ' + @strGroupBy + @strOtherCols + @Vals +
		   ' from (' + @strSelect + ') A GROUP BY ' + @strGroupBy

--	return
	exec ( @Vals )


	--SELECT @Vals
	set nocount off
	set ansi_warnings ON

END
GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
--
-- IMPORTANTE:
-- Seria bueno que NO se reciclen POOLES despues del horario de backup
--  y si se programa un reciclado se haga 15 minutos ANTES de los backups
-- ya que al depurarse sessionInSql y no estar al reciclar el pool, se cuelga el sistema.
--
-- =============================================

CREATE  PROCEDURE [dbo].[spsystem_dailyDatabaseMaintenance]
AS

BEGIN

	SET NOCOUNT ON;
	SET DATEFORMAT	'YMD'
	SET DATEFIRST	7	-- Domingo x Defecto

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	-- -----------------------------------------------------
	-- Si es Express borra cosas que la hace crecer de mas.
	-- para no llegar tan rapido a los 10GB
	-- -----------------------------------------------------
	DECLARE @bolIsExpress AS BIT = 'False'	-- Es SQL Express?
	IF (@@version LIKE '%EXPRESS%' OR @@VERSION LIKE '%Server 2005%') SET @bolIsExpress = 'True'
	-- -----------------------------------------------------

	DECLARE @intRowCount AS INT = 0




	-- ----------------------------------
	-- Depurar lo muy viejo menor a DOS dias
	-- ----------------------------------
	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD( day, -2, getdate())
	-- ----------------------------------



	DECLARE @datBeginDate AS DATETIME = GETDATE()

	-- NO debe ejecutarse en estos horarios
	IF DATEPART(hour,GETDATE()) > 7 AND
	   DATEPART(hour,GETDATE()) < 18 RETURN




	-- -----------------------------------------------------
	-- Si es Express borra cosas que la hace crecer de mas.
	-- -----------------------------------------------------
	IF	@bolIsExpress = 'True' AND
		DATEPART(hour ,GETDATE()) BETWEEN 2 AND 6
		BEGIN
			truncate table tbWebSiteII_RequestLog
		END

	IF (SELECT COUNT(*) FROM tbWebSiteII_ActivityLOG) > 400000 AND
		DATEPART(hour ,GETDATE()) BETWEEN 1 AND 6
		BEGIN
			SELECT 'TRUNCATE TABLE tbWebSiteII_ActivityLOG'
			TRUNCATE TABLE tbWebSiteII_ActivityLOG
		END
	-- -----------------------------------------------------




	SELECT '001.tbMercadoLibre_callbackHistory'
	SET @datBeginDate = GETDATE()
	BEGIN TRY
			WHILE 1 = 1
				BEGIN
					IF @bolIsExpress = 'True'
						BEGIN
							--BEGIN TRANSACTION
								DELETE TOP (500)  FROM	tbMercadoLibre_callbackHistory		WITH (TABLOCK)
									WHERE  MLLog_cd < DATEADD(day,-3,GETDATE())
								SET @intRowCount = @@ROWCOUNT
							--COMMIT TRANSACTION
							--CHECKPOINT
						END
					ELSE
						BEGIN
							--BEGIN TRANSACTION
								DELETE TOP (500)  FROM	tbMercadoLibre_callbackHistory		WITH (TABLOCK)
									WHERE  MLLog_cd < DATEADD(day,-5,GETDATE())
								SET @intRowCount = @@ROWCOUNT
							--COMMIT TRANSACTION
							--CHECKPOINT
						END
					IF @introwCount < 500 BREAK;
					IF ABS(DATEDIFF(minute,@datBeginDate,GETDATE())) > 3 BREAK;
				END
	END TRY
	BEGIN CATCH
		SELECT 'ERROR 001'
	END CATCH

	SELECT '002.tbMercadoLibre_updateQueue'
	IF DATEPART(hour,GETDATE()) > 2 AND
	   DATEPART(hour,GETDATE()) < 8
	BEGIN

		DECLARE @bitCanIDoIt AS BIT = 'False'
		EXEC	spSystem_LastExecutionControl_CanDoIt	-1,
														-1,
														55345,	-- Depurado de Cola de Procesos de MeLi
				   										1200,	-- q vez x dia informa las categorias de meli
														@bitCanIDoIt OUTPUT

		IF @bitCanIDoIt = 'True'
			BEGIN

				BEGIN TRY


						SELECT *
							INTO #tmpMercadoLibre_updateQueue
							FROM tbMercadoLibre_updateQueue		WITH (NOLOCK)
							WHERE mlproc_cd  >=  DATEADD(hour,
																CASE
																	WHEN mlproc_isProcessed = 'True' THEN -48
																	ELSE								  -96
																END
															 ,GETDATE())


						BEGIN TRY
							BEGIN TRY
								TRUNCATE TABLE tbMercadoLibre_updateQueue
							END TRY
							BEGIN CATCH
								--BEGIN TRANSACTION
									DELETE FROM tbMercadoLibre_updateQueue
								--COMMIT TRANSACTION
								--CHECKPOINT
							END CATCH
						END TRY
						BEGIN CATCH
						END CATCH



						--BEGIN TRANSACTION
						SET IDENTITY_INSERT tbMercadoLibre_updateQueue ON
						INSERT INTO tbMercadoLibre_updateQueue( comp_id, mlproc_id, mlp_id, mlproc_cd,
									[user_id], mlproc_option, mlproc_stringValue,
									mlproc_integerValue, mlproc_decimalValue,
									mlproc_isProcessed, mlproc_isProcessedCD,
									mlproc_isCancelled, mlproc_priority, mlproc_isWithError,
									mlproc_isWithErrorTryNumber, mlproc_guid,
									mlproc_bigintegerValue, mlproc_textValue,
									mlproc_imageValue, mlproc_integerValue2, mlproc_URL,
									mlproc_isProcessedWithError,
									mlproc_ProcessedWithErrorDescription,
									mlproc_ProcessedWithErrorNumber, mlproc_internalID,
									mlproc_response, mlproc_JSON)

									SELECT comp_id,mlproc_id, mlp_id, mlproc_cd,
									[user_id], mlproc_option, mlproc_stringValue,
									mlproc_integerValue, mlproc_decimalValue,
									mlproc_isProcessed, mlproc_isProcessedCD,
									mlproc_isCancelled, mlproc_priority, mlproc_isWithError,
									mlproc_isWithErrorTryNumber, mlproc_guid,
									mlproc_bigintegerValue,
									CASE
										 WHEN mlproc_isProcessed = 'True' THEN ''
										 ELSE									mlproc_textValue
									END 				/* mlproc_textValue*/,
									mlproc_imageValue, mlproc_integerValue2, mlproc_URL,
									mlproc_isProcessedWithError,
									mlproc_ProcessedWithErrorDescription,
									mlproc_ProcessedWithErrorNumber, mlproc_internalID,
									mlproc_response,
									CASE
										 WHEN	mlproc_isProcessed = 'True'								AND
												DATEDIFF(DAY,mlproc_isProcessedCD,GETDATE())	> 2		AND
												DATALENGTH(mlproc_JSON)							> 100	/*MOS 08-2023, para seguir viendo que pasó*/ THEN  SUBSTRING(mlproc_JSON,0,98) + '...'
										 ELSE																												mlproc_JSON
									END  /*mlproc_JSON*/
									FROM #tmpMercadoLibre_updateQueue
									--ORDER BY mlproc_cd
            			SET IDENTITY_INSERT tbMercadoLibre_updateQueue OFF
						DROP TABLE #tmpMercadoLibre_updateQueue
						--COMMIT TRANSACTION
						--CHECKPOINT
				END TRY
				BEGIN CATCH
					SELECT 'ERROR 002'
					--BEGIN TRANSACTION
						UPDATE tbMercadoLibre_updateQueue
							SET mlproc_JSON = ''
							WHERE mlproc_isProcessed = 'True' AND DATALENGTH(mlproc_JSON) > 50
					--COMMIT TRANSACTION
					--CHECKPOINT
				END CATCH

				BEGIN TRY
					--BEGIN TRANSACTION
						UPDATE tbMercadoLibre_updateQueue	WITH (ROWLOCK)
							SET mlproc_ProcessedWithErrorDescription = ''
							WHERE	mlproc_isProcessed						= 1 AND
									mlproc_ProcessedWithErrorDescription	<> ''   -- MOS 07-2020
					--COMMIT TRANSACTION
					--CHECKPOINT
				END TRY
				BEGIN CATCH
					SELECT 'ERROR 002.5'
				END CATCH

			END


		-- -------------------------------------------------------------------------------
		-- MOS 06-2022: Hace que si hay combos q suman el precio de las partes,
		-- se ejecute el trigger de tbItems
		-- -------------------------------------------------------------------------------
		SET @bitCanIDoIt = 'False'
		EXEC	spSystem_LastExecutionControl_CanDoIt	-1,
														-1,
														563429,	-- Fuerza el recalculo de Combos que sumen el precio de las partes
				   										1200,	-- q vez x dia informa las categorias de meli
														@bitCanIDoIt OUTPUT

		IF @bitCanIDoIt = 'True'
			BEGIN

				BEGIN TRY
					-- **lkfn980732464dlqndlnqwlqw32452
					DECLARE @intCompID AS INT
					DECLARE @intItemID AS INT
					DECLARE curItems  CURSOR LOCAL FAST_FORWARD FOR
						SELECT comp_id,item_id
							FROM tbItem AS ti	WITH (NOLOCK)
							WHERE	item_ifHasItemAssociationSumPrices	= 'true'	AND
									item_disabled						= 'False'

						OPEN curItems
						FETCH NEXT FROM curItems INTO @intCompID,@intItemID
						WHILE @@FETCH_STATUS = 0
							BEGIN
								UPDATE tbitem
									SET item_lastUpdate_byProcess = GETDATE()
									WHERE	comp_id = @intCompID AND
											item_id = @intItemID
								FETCH NEXT FROM curItems INTO @intCompID,@intItemID
							END
						CLOSE		curItems
						DEALLOCATE	curItems
				END TRY
				BEGIN CATCH
				END CATCH

			END
		-- -------------------------------------------------------------------------------

	END

	SELECT '003.tbMercadoLibre_ItemsPublicados'
	--BEGIN TRANSACTION
		UPDATE tbMercadoLibre_ItemsPublicados
			SET mlp_lastJSonValidation = ''
			WHERE	DATALENGTH(mlp_lastJSonValidation)			> 0		AND
					ABS(DATEDIFF(day,mlp_lastUpdate,GETDATE()))	> 7
	--COMMIT TRANSACTION
	--CHECKPOINT

	SELECT '003.tbsentEMailLog'
  	IF DATEPART(weekday,GETDATE()) IN (1,3,5) AND DATEPART(hour,GETDATE()) < 6
  		BEGIN

			SET		@bitCanIDoIt = 'False'
			EXEC	spSystem_LastExecutionControl_CanDoIt	-1,
															-1,
															93856740,	-- Depurado de Cola de Procesos de MeLi
				   											1200,	-- q vez x dia informa las categorias de meli
															@bitCanIDoIt OUTPUT
  			IF @bitCanIDoIt = 'True'
  				BEGIN
					BEGIN TRY
							WHILE 1 = 1
								BEGIN
									--BEGIN TRANSACTION
										DELETE TOP(500) FROM 	tbsentEMailLog		WITH (TABLOCK)
											WHERE el_cd  < DATEADD(day,-14,GETDATE())
										SET @intRowCount = @@ROWCOUNT
									--COMMIT TRANSACTION
									--CHECKPOINT
									IF @intRowCount < 500 BREAK;
								END
					END TRY
					BEGIN CATCH
						SELECT 'ERROR 003'
					END CATCH
  				END
		END


	SELECT '004.tbAutorizationRequest_History'
  	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  	BEGIN
		BEGIN TRY

			IF @bolIsExpress = 'True'
				BEGIN
					--BEGIN TRANSACTION
						UPDATE tbAutorizationRequest_History							WITH (ROWLOCK)
							SET aure_pageHTML	= '',
								aure_image		= NULL,
								aure_Link		= '',
								aure_pageHTMLPlus = '',
								aure_auxString	  = ''
							WHERE	aure_cd  < DATEADD(month,-2,GETDATE()) AND
									(
										DATALENGTH(aure_pageHTML)		> 0  OR
										DATALENGTH(aure_Link)			> 0  OR
										DATALENGTH(aure_pageHTMLPlus)	> 0  OR
										DATALENGTH(aure_auxString)		> 0
									)
					--COMMIT TRANSACTION
					--CHECKPOINT
				END
			ELSE
				BEGIN
					--BEGIN TRANSACTION
						UPDATE tbAutorizationRequest_History							WITH (ROWLOCK)
							SET aure_pageHTML	= '',
								aure_image		= NULL,
								aure_Link		= '',
								aure_pageHTMLPlus = '',
								aure_auxString	  = ''
							WHERE	aure_cd  < DATEADD(month,-4,GETDATE()) AND
									(
										DATALENGTH(aure_pageHTML)		> 0  OR
										DATALENGTH(aure_Link)			> 0  OR
										DATALENGTH(aure_pageHTMLPlus)	> 0  OR
										DATALENGTH(aure_auxString)		> 0
									)
					--COMMIT TRANSACTION
					--CHECKPOINT
				END
		END TRY
		BEGIN CATCH
			SELECT 'ERROR 004'
		END CATCH
	END

	SELECT '005.tbAutorizationRequest_History'
  	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  	BEGIN
		BEGIN TRY
			WHILE 1 = 1
				BEGIN

					IF @bolIsExpress = 'True'
						BEGIN
							--BEGIN TRANSACTION
								DELETE TOP (500) FROM tbAutorizationRequest_History						WITH (TABLOCK)
									WHERE aure_cd < DATEADD(year,-1,GETDATE())  -- @DeleteTime
								SET @intRowCount = @@ROWCOUNT
							--COMMIT TRANSACTION
							--CHECKPOINT
						END
					ELSE
						BEGIN
							--BEGIN TRANSACTION
								DELETE TOP (500) FROM tbAutorizationRequest_History						WITH (TABLOCK)
									WHERE aure_cd < DATEADD(year,-2,GETDATE())  -- @DeleteTime
								SET @intRowCount = @@ROWCOUNT
							--COMMIT TRANSACTION
							--CHECKPOINT
						END
					IF @introwCount < 500 BREAK;
				END
		END TRY
		BEGIN CATCH
			SELECT 'ERROR 005'
		END CATCH
	END




	--SELECT '006.tbAutorizationRequest_PendingSaleOrders'
 -- 	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
 -- 	BEGIN
	--	BEGIN TRY
	--			WHILE 1 = 1
	--				BEGIN
	--					BEGIN TRANSACTION
	--						DELETE TOP(500) FROM tbAutorizationRequest_PendingSaleOrders						WITH (TABLOCK)
	--							WHERE aure_cd < DATEADD(year,-1,GETDATE())  -- @DeleteTime
	--						SET @intRowCount = @@ROWCOUNT
	--					COMMIT TRANSACTION
	--					CHECKPOINT
	--					IF @introwCount < 500 BREAK;
	--				END
	--	END TRY
	--	BEGIN CATCH
	--		SELECT 'ERROR 006'
	--	END CATCH
	--END

	SELECT '007.tbAutorizationRequest_PendingSaleOrders'
  	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  	BEGIN
		BEGIN TRY

			IF @bolIsExpress = 'True'
				BEGIN
					--BEGIN TRANSACTION
						UPDATE tbAutorizationRequest_PendingSaleOrders			WITH (ROWLOCK)
							SET aure_pageHTML = '', aure_image = NULL, aure_Link = '', aure_pageHTMLPlus = ''
							WHERE aure_cd  < DATEADD(month,-6,GETDATE())  -- @DeleteTime
					--COMMIT TRANSACTION
					--CHECKPOINT
				END
			ELSE
				BEGIN
					--BEGIN TRANSACTION
						UPDATE tbAutorizationRequest_PendingSaleOrders			WITH (ROWLOCK)
							SET aure_pageHTML = '', aure_image = NULL, aure_Link = '', aure_pageHTMLPlus = ''
							WHERE aure_cd  < DATEADD(month,-8,GETDATE())  -- @DeleteTime
					--COMMIT TRANSACTION
					--CHECKPOINT
				END

		END TRY
		BEGIN CATCH
			SELECT 'ERROR 007'
		END CATCH
	END

	SELECT '008.tbSecurityLog'
  	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  		BEGIN
			BEGIN TRY
				IF @bolIsExpress = 'True'
					BEGIN
						--BEGIN TRANSACTION
							UPDATE tbSecurityLog			WITH (ROWLOCK)
								SET  seclog_pageHTML = '', seclog_pageHTMLPlus = '',seclog_obs_2 = ''
							WHERE	seclog_cd  < DATEADD(month,-3,GETDATE()) AND  -- @DeleteTime
									(
										DATALENGTH(seclog_pageHTML)		> 0 OR
										DATALENGTH(seclog_pageHTMLPlus)	> 0
									)
						--COMMIT TRANSACTION
						--CHECKPOINT
					END
				ELSE
					BEGIN
						--BEGIN TRANSACTION
							UPDATE tbSecurityLog			WITH (ROWLOCK)
								SET  seclog_pageHTML = '', seclog_pageHTMLPlus = '',seclog_obs_2 = ''
							WHERE	seclog_cd  < DATEADD(month,-6,GETDATE()) AND  -- @DeleteTime
									(
										DATALENGTH(seclog_pageHTML)		> 0 OR
										DATALENGTH(seclog_pageHTMLPlus)	> 0
									)
						--COMMIT TRANSACTION
						--CHECKPOINT
					END

				DELETE FROM tbSecurityLog WHERE seclog_obs_1 = 'Close Daily' AND seclog_cd  < DATEADD(month,-3,GETDATE())

			END TRY
			BEGIN CATCH
				SELECT 'ERROR 008'
			END CATCH
		END

	SELECT '009.tbSecurityLog'
  	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						IF @bolIsExpress = 'True'
							BEGIN
								--BEGIN TRANSACTION
									DELETE TOP(500) FROM tbSecurityLog						WITH (TABLOCK)
										WHERE seclog_cd < DATEADD(month,-6,GETDATE())  -- @DeleteTime
									SET @intRowCount = @@ROWCOUNT
								--COMMIT TRANSACTION
								--CHECKPOINT
								IF @introwCount < 500 BREAK;
							END
						ELSE
							BEGIN
								--BEGIN TRANSACTION
									DELETE TOP(500) FROM tbSecurityLog						WITH (TABLOCK)
										WHERE seclog_cd < DATEADD(month,-12,GETDATE())  -- @DeleteTime
									SET @intRowCount = @@ROWCOUNT
								--COMMIT TRANSACTION
								--CHECKPOINT
								IF @introwCount < 500 BREAK;
							END
					END
			END TRY
			BEGIN CATCH
				SELECT 'ERROR 009'
			END CATCH
		END




	SELECT '010.tbWebSiteII_ActivityLOG'
  	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						IF @bolIsExpress = 'True'
							BEGIN
								--BEGIN TRANSACTION
									DELETE TOP (500) FROM tbWebSiteII_ActivityLOG						WITH (TABLOCK)
									WHERE	wsm_cd < DATEADD(day,-3,GETDATE())	AND
											cust_id IS NULL							AND
											contact_id IS NULL						AND
											--[user_id] IS NULL						AND		-- 05-2020
											camp_id IS NULL							AND
											item_id IS NULL
									SET @intRowCount = @@ROWCOUNT
								--COMMIT TRANSACTION
								--CHECKPOINT
							END
						ELSE
							BEGIN
								--BEGIN TRANSACTION
									DELETE TOP (500) FROM tbWebSiteII_ActivityLOG						WITH (TABLOCK)
									WHERE	wsm_cd < DATEADD(day,-12,GETDATE())	AND
											cust_id IS NULL							AND
											contact_id IS NULL						AND
											--[user_id] IS NULL						AND		-- 05-2020
											camp_id IS NULL							AND
											item_id IS NULL
									SET @intRowCount = @@ROWCOUNT
								--COMMIT TRANSACTION
								--CHECKPOINT
							END
						IF @introwCount < 500 BREAK;
					END
			END TRY
			BEGIN CATCH
				SELECT 'ERROR 010'
			END CATCH
		END

	SELECT '011.tbWebSiteII_RequestLog'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						--BEGIN TRANSACTION
							DELETE TOP (500) FROM tbWebSiteII_RequestLog						WITH (TABLOCK)
								WHERE	wslog_cd < DATEADD(month,-1,GETDATE())
							SET @intRowCount = @@ROWCOUNT
						--COMMIT TRANSACTION
						--CHECKPOINT
						IF @introwCount < 500 BREAK;
					END
			END TRY
			BEGIN CATCH
				SELECT 'ERROR 011'
			END CATCH
		END

	SELECT '012.tbGenerics_ExecLog'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
  		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						IF @bolIsExpress = 'True'
							BEGIN
								--BEGIN TRANSACTION
									DELETE TOP(100) FROM tbGenerics_ExecLog							WITH (TABLOCK)
										WHERE	dateBegin < DATEADD(month,-2,GETDATE())
