	-- Borra historial de mails enviados por sql server.
	SELECT '017.sysmail_delete_mailitems_sp'
	BEGIN TRY
		-- select * from msdb.dbo.sysmail_allitems  para ver todo
		DECLARE @datDeleteMailsBefore AS DATETIME
		SET		@datDeleteMailsBefore = DATEADD(hour, -2, GETDATE())
		EXEC msdb.dbo.sysmail_delete_mailitems_sp @datDeleteMailsBefore,'sent'
		EXEC msdb.dbo.sysmail_delete_mailitems_sp @datDeleteMailsBefore,'unsent'
		EXEC msdb.dbo.sysmail_delete_mailitems_sp @datDeleteMailsBefore,'retrying'
		EXEC msdb.dbo.sysmail_delete_mailitems_sp @datDeleteMailsBefore,'failed'
	END TRY
	BEGIN CATCH
		SELECT 'ERROR 017'
	END CATCH




