	SELECT '035.tbItemStorageUpdates'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6 AND @bolIsExpress = 'False'
		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						--BEGIN TRANSACTION
							DELETE TOP(500) FROM tbItemStorageUpdates 		WITH (TABLOCK)
							WHERE itsa_cd  < DATEADD(day,-360,GETDATE())
