			BEGIN CATCH
			END CATCH
		END
	ELSE IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6 AND @bolIsExpress = 'True'
		BEGIN
			BEGIN TRY
				TRUNCATE table tbItemStorageUpdates
			END TRY
			BEGIN CATCH
			END CATCH
		END

	SELECT '036.tbItemStorageHistory4CloseDaily'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
		BEGIN
			BEGIN TRY
				IF @bolIsExpress = 'True'
					BEGIN
						WHILE 1 = 1
							BEGIN
								--BEGIN TRANSACTION
									DELETE TOP(500) FROM tbItemStorageHistory4CloseDaily 		WITH (TABLOCK)
										WHERE ith_cd  < DATEADD(month,-18,GETDATE())
									SET @intRowCount = @@ROWCOUNT
								--COMMIT TRANSACTION
								--CHECKPOINT
								IF @introwCount < 500 BREAK;
							END
					END
				ELSE
					BEGIN
						WHILE 1 = 1
							BEGIN
								--BEGIN TRANSACTION
									DELETE TOP(500) FROM tbItemStorageHistory4CloseDaily 		WITH (TABLOCK)
										WHERE ith_cd  < DATEADD(year,-3,GETDATE())
									SET @intRowCount = @@ROWCOUNT
								--COMMIT TRANSACTION
								--CHECKPOINT
								IF @introwCount < 500 BREAK;
							END
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END


	SELECT '035.tbItemStoragePhoto'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6 AND @bolIsExpress = 'False'
		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						--BEGIN TRANSACTION
							DELETE TOP(500)  tbItemStoragePhoto 		WITH (TABLOCK)
								FROM  tbItemStoragePhoto isp
								INNER JOIN tbItemTransactions AS tit
								 ON tit.comp_id			= isp.comp_id AND
									tit.it_transaction	= isp.it_transaction
								WHERE tit.it_cd  < DATEADD(month,-36,GETDATE())
							SET @intRowCount = @@ROWCOUNT
						--COMMIT TRANSACTION
						--CHECKPOINT
						IF @introwCount < 500 BREAK;
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END



	SELECT '037.tbWorkflow'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6 AND @bolIsExpress = 'True'
		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						--BEGIN TRANSACTION
							DELETE TOP(500) FROM tbWorkflow 		WITH (TABLOCK)
							WHERE	wf_isProcessed = 1 AND
									wf_dateOfAssigned IS NOT NULL AND
									wf_dateOfAssigned  < DATEADD(year,-2,GETDATE())
