				--COMMIT TRANSACTION
				--CHECKPOINT
			END TRY
			BEGIN CATCH
			END CATCH
		END

	-- Borra Cotizaciones DUPLICADAS para la MISMA fecha.   BORRA DUPLICADOS
	SELECT '039.tbCurrencyExchangeUpdateHistory'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6 --AND @bolIsExpress = 'True'
		BEGIN
			DELETE E
				FROM tbCurrencyExchangeUpdateHistory E
					 INNER JOIN
				(
					SELECT *,
						   RANK() OVER(PARTITION BY YEAR(ceu_cd),
													MONTH(ceu_cd),
													DAY(ceu_cd),
													ceu_usd,
													ceu_eur
						   ORDER BY ceu_id) rank
					FROM tbCurrencyExchangeUpdateHistory
				) T ON E.ceu_id = t.ceu_id
				WHERE rank > 1;
		END


  	-- Borra Cotizaciones DUPLICADAS para la MISMA fecha.   BORRA DUPLICADOS
	SELECT '040.tbCurExchHistory'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6 --AND @bolIsExpress = 'True'
		BEGIN
			DELETE E
				FROM tbCurExchHistory E
					 INNER JOIN
				(
					SELECT *,
						   RANK() OVER(PARTITION BY YEAR(ceh_cd),
													MONTH(ceh_cd),
													DAY(ceh_cd),
													ceh_exchange,
													ceh_exchange_purchase,
													comp_id, curr_id_1, curr_id_2
						   ORDER BY ceh_id) rank
					FROM tbCurExchHistory
				) T ON E.ceh_id = t.ceh_id
				WHERE rank > 1;
		END


	-- ----------------------------------
	-- Si NO hay nadie logeado que borre estas tablas
	-- ----------------------------------
	SELECT '041.tbCashMovementsTmp,tbCheckPortfolioTmp,tbCreditCardMovementsTmp,tbBankingTransactionsTmp,tbAccountantMovementsTMP'
	IF NOT EXISTS (
					SELECT TOP 1 1
						FROM tbUser tu	WITH (NOLOCK)
