				TRUNCATE TABLE tbCashMovementsTmp
			END TRY
			BEGIN CATCH
			END CATCH
			BEGIN TRY
				TRUNCATE TABLE tbCheckPortfolioTmp
			END TRY
			BEGIN CATCH
			END CATCH
			BEGIN TRY
				TRUNCATE TABLE tbCreditCardMovementsTmp
			END TRY
			BEGIN CATCH
			END CATCH
			BEGIN TRY
				TRUNCATE TABLE tbBankingTransactionsTmp
			END TRY
			BEGIN CATCH
			END CATCH
			BEGIN TRY
				TRUNCATE TABLE tbAccountantMovementsTMP
			END TRY
			BEGIN CATCH
			END CATCH
			BEGIN TRY
				TRUNCATE TABLE tbCollection_ExchDiffTMPValues
			END TRY
			BEGIN CATCH
			END CATCH
		END
	-- ----------------------------------




	SELECT '042.tbElectronicInvoice_TicketTransactions'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						--BEGIN TRANSACTION
							DELETE TOP(500)  tbElectronicInvoice_TicketTransactions 		WITH (TABLOCK)
							WHERE ta_cd   < DATEADD(month,-2,GETDATE())
							SET @intRowCount = @@ROWCOUNT
						--COMMIT TRANSACTION
						--CHECKPOINT
						IF @introwCount < 500 BREAK;
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END



	SELECT '043.tbItemTransactionSerials'	-- MOS 12-2022: quedan registros de fc de venta que NO se toman los numeros de serie en doc que NO serializan datos ocupando demasiado lugar.
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
		BEGIN
			BEGIN TRY
				WHILE 1 = 1
					BEGIN
						--BEGIN TRANSACTION

							DELETE TOP(500)	tbItemTransactionSerials
								FROM tbItemTransactionSerials AS tits	WITH (NOLOCK)
								INNER JOIN tbCommercialTransactions AS tct WITH (NOLOCK)
									ON	tct.comp_id			= tits.comp_id AND
										tct.ct_transaction	= tits.ct_transaction
								WHERE	tits.is_id IS NULL		AND
										tits.impData_id IS NULL AND
										tits.import_id  IS NULL	AND
										tct.ct_cd <	DATEADD(YEAR,-2,GETDATE())

							SET @intRowCount = @@ROWCOUNT
						--COMMIT TRANSACTION
						--CHECKPOINT
						IF @introwCount < 500 BREAK;
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END


  	SELECT '044.tbSaleOrderDetailHistory'	-- MOS 12-2022: Borra el historial de Pedidos mayor a 6 años
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
		BEGIN
			BEGIN TRY
				DELETE FROM tbSaleOrderDetailHistory
					WHERE sod_lastUpdate < DATEADD(YEAR,-5,GETDATE())
				DELETE  tbSaleOrderHeaderHistory
					FROM  tbSaleOrderHeaderHistory tsoh WITH (NOLOCK )
					LEFT JOIN tbSaleOrderDetailHistory AS tsod WITH (NOLOCK)
						ON	tsod.comp_id	= tsoh.comp_id AND
							tsod.bra_id		= tsoh.bra_id AND
							tsod.soh_id		= tsoh.soh_id
					WHERE tsod.comp_id IS NULL
			END TRY
			BEGIN CATCH
			END CATCH
		END


	SELECT '045.tbAutorizationRequest_PendingSaleOrders'	-- MOS 01-2023: Borra  Autorizaciones de Pedidos mayor a 1 meses de pedidos que YA NO EXISTEN
	BEGIN TRY
		DELETE tbAutorizationRequest_PendingSaleOrders
			FROM tbAutorizationRequest_PendingSaleOrders	AS tarpso	WITH (NOLOCK)
			LEFT JOIN tbSaleOrderHeader						AS tsoh		WITH (NOLOCK)
			ON	tsoh.comp_id	= tarpso.comp_id		AND
				tsoh.bra_id		= tarpso.soh_bra_id		AND
				tsoh.soh_id		= tarpso.soh_id
			WHERE	tsoh.comp_id IS  NULL				AND
					--tarpso.aure_isok = 'P'				AND
					tarpso.soh_bra_id	IS NOT NULL		AND
					tarpso.soh_id		IS NOT NULL		AND
					tarpso.aure_cd < DATEADD(MONTH,-1,GETDATE())
	END TRY
	BEGIN CATCH
	END CATCH


	SELECT '046.tbTiendaNube_Orders'	-- Deja a lo sumo 15 dias de JSon
	BEGIN TRY
		UPDATE tbTiendaNube_Orders
			SET tno_JSon  = ''
		WHERE	DATALENGTH(tno_JSon) > 0				AND
				tno_cd < DATEADD(day,-15,GETDATE())
	END TRY
	BEGIN CATCH
	END CATCH


  	SELECT '047.tbTiendaNube_webHookCallHistory'
	IF DATEPART(weekday,GETDATE()) = 1 AND DATEPART(hour,GETDATE()) < 6
		BEGIN
			BEGIN TRY
				DELETE FROM  tbTiendaNube_webHookCallHistory
				WHERE webHook_CD  < DATEADD(DAY,-30,GETDATE())
			END TRY
			BEGIN CATCH
			END CATCH
		END





	-- -------------------------------------------------------------------------------------------------------------------------------------------------
	-- MOS 06-2024: Los FORROS de bon no se que MIERDA hacen y tenian 4GB de historial de listas de precios actualizadas. Hacen mierda todo esos HDRMP
	-- -------------------------------------------------------------------------------------------------------------------------------------------------
	SET		@bitCanIDoIt = 'False'
	EXEC	spSystem_LastExecutionControl_CanDoIt	-1,
													-1,
													93476740,	-- Depurado de Cola de Procesos de MeLi
				   									1200,	-- q vez x dia informa las categorias de meli
													@bitCanIDoIt OUTPUT

	IF	DATEPART(weekday,GETDATE()) = 1			AND
		DATEPART(hour,GETDATE())    < 6			AND
		@bolIsExpress				= 'True'	AND
		@bitCanIDoIt				= 'True'
		BEGIN

			SELECT '048.tbPriceListHistory'

			BEGIN TRY
				BEGIN TRANSACTION
					SELECT comp_id, prli_id, item_id, plh_lote, plh_price, curr_id,
					       plh_cd, user_id_lastUpdate, plh_ruleUpdate,plh_id
						INTO	#tabla_temporal
						FROM	tbPriceListHistory	WITH (NOLOCK)
						WHERE	plh_cd >= DATEADD(year,-2,GETDATE())
						ORDER BY plh_id

					-- Truncar la tabla original
					TRUNCATE TABLE tbPriceListHistory

					-- Volver a insertar los datos
					INSERT INTO tbPriceListHistory(comp_id, prli_id, item_id, plh_lote, plh_price, curr_id,
					       plh_cd, user_id_lastUpdate, plh_ruleUpdate)
						SELECT comp_id, prli_id, item_id, plh_lote, plh_price, curr_id,
					       plh_cd, user_id_lastUpdate, plh_ruleUpdate
						FROM #tabla_temporal
						ORDER BY plh_id
					DROP TABLE #tabla_temporal
				COMMIT TRANSACTION
			END TRY
			BEGIN CATCH
				SELECT 'ERROR 001', ERROR_MESSAGE()
				ROLLBACK TRANSACTION
			END CATCH

		END
	-- -------------------------------------------------------------------------------------------------------------------------------------------------


	-- ----------------------------------
	-- Si NO hay nadie logeado que borre estas tablas
	-- ----------------------------------
	SELECT '049.tbSaleOrderDetailtmp'
	IF NOT EXISTS (
					SELECT TOP 1 1
						FROM tbUser tu	WITH (NOLOCK)
						WHERE tu.user_login = 'True'
					)
		BEGIN
			BEGIN TRY
				TRUNCATE TABLE tbSaleOrderDetailtmp
			END TRY
			BEGIN CATCH
			END CATCH
		END
	-- ----------------------------------


	-- ----------------------------------
	-- Si NO hay nadie logeado que borre estas tablas
	-- ----------------------------------
	SELECT '050.tbcommercialtransactions->ct_guid'
	IF NOT EXISTS (
					SELECT TOP 1 1
						FROM tbUser tu	WITH (NOLOCK)
						WHERE tu.user_login = 'True'
					)
		BEGIN
			BEGIN TRY
				UPDATE tbcommercialtransactions SET ct_guid = NULL WHERE ct_guid IS NOT NULL AND ct_ABalance = 0 AND sd_id <> 2 AND YEAR(ct_date) <> YEAR(GETDATE())
			END TRY
			BEGIN CATCH
			END CATCH
		END
	-- ----------------------------------


	-- ----------------------------------
	-- Si NO hay nadie logeado que borre estas tablas
	-- ----------------------------------
	SELECT '051.tbTemporarySelection'
	IF NOT EXISTS (
					SELECT TOP 1 1
						FROM tbUser tu	WITH (NOLOCK)
						WHERE tu.user_login = 'True'
					)
		BEGIN
			BEGIN TRY
				TRUNCATE TABLE  tbTemporarySelection
			END TRY
			BEGIN CATCH
			END CATCH
		END
	-- ----------------------------------


	-- ----------------------------------
	-- Si NO hay nadie logeado que borre estas tablas
	-- ----------------------------------
	SELECT '052.tbTempSaleOrderSerial'
	IF NOT EXISTS (
					SELECT TOP 1 1
						FROM tbUser tu	WITH (NOLOCK)
						WHERE tu.user_login = 'True'
					)
		BEGIN
			BEGIN TRY
				TRUNCATE TABLE  tbTempSaleOrderSerial
			END TRY
			BEGIN CATCH
			END CATCH
		END
	-- ----------------------------------


	-- ----------------------------------
	-- Si NO hay nadie logeado que borre estas tablas
	-- ----------------------------------
	SELECT '053.tbItemTransactionsTmp'
	IF NOT EXISTS (
					SELECT TOP 1 1
						FROM tbUser tu	WITH (NOLOCK)
						WHERE tu.user_login = 'True'
					)
		BEGIN
			BEGIN TRY
				TRUNCATE TABLE  tbItemTransactionsTmp
			END TRY
			BEGIN CATCH
			END CATCH
		END
	-- ----------------------------------





	SELECT 'Depurado Finalizado OK'


END
GO






CREATE PROCEDURE  [dbo].[spSystem_DatabaseVersion_getData]
--(
--	@comp_id			INT,
--	@bra_id				INT,
--	@DateUpdate			DATETIME,
--	@user_id			INT,
--	@prof_id			INT,
--	@return_value		INT OUTPUT
--)
AS

BEGIN

	SET NOCOUNT ON

	SELECT TOP 1  tsdv.version,
		   isnull(tsdv.isUpdated,'false')   [isUpdated],
		   ISNULL(tsdv.isFixed_2,'false')	[isFixed_2],
		   ISNULL(tsdv.closeDaily_PurificatingOrders,'False')	[closeDaily_PurificatingOrders]

	FROM tbSystem_DatabaseVersion tsdv	WITH (NOLOCK)

END

GO









