-- =============================================
CREATE PROCEDURE [dbo].[spSystem_DumpTransactionLog]
	-- Add the parameters for the stored procedure here
	@strDataBaseName	as VarChar(200)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Declare @strExec as Varchar(MAX)

	Set @strExec = 'dump tran ' + @strDataBaseName  + 'with truncate_only'
	exec (@strExec)
	--DBCC SHRINKFILE(dbISDERP20071207_log,2)

END




GO







CREATE PROCEDURE [dbo].[spSystem_ExportWebSite]
(
		@comp_id_origen		INT,
		@comp_id_destino	INT,
		@ws_id				INT,
		@name				VARCHAR(200)
)
AS



/*
DECLARE @comp_id_origen		INT,
		@comp_id_destino	INT,
		@ws_id				INT,
		@name				VARCHAR(200)
SELECT 	@comp_id_origen		= 1,
		@comp_id_destino	= 1,
		@ws_id				= 28,
		@name				= 'ISD'
*/



SET NOCOUNT ON


DECLARE @query				NVARCHAR(4000),
		@wss_id				INT,
		@wsp_id				INT,
        @lang_id			INT,
        @wssrl_id			INT,
        @wsspr_id			INT,
        @wswi_id			INT,
        @swsc_id			INT,
        @swscc_id			INT,
        @wsplr_id			INT,
        @wspcc_id			INT,
        @wsdet_id			INT,
        @wsdat_id			INT,
        @ith_id				INT,
        @itd_id				INT,
        @wssprh_id			INT,
        @wsm_id				INT



SET @lang_id = 2

--SET @name = LTRIM(RTRIM(@name)) + 'Web'




----------------------------------------------------------------------------------------------------------------------------------------------
SELECT 'SET NOCOUNT ON


BEGIN TRANSACTION
BEGIN TRY



DECLARE --@comp_id	INT,
 		@name		VARCHAR(200)
SELECT 	--@comp_id	= ' + CONVERT(VARCHAR,@comp_id_destino) + ',
		@name		= ''' + @name + ''''

		--@ws_id_' + CONVERT(VARCHAR,@ws_id) + '		INT,
		--@ws_id_' + CONVERT(VARCHAR,@ws_id) + '		= ' + CONVERT(VARCHAR,@ws_id) + ',


----------------------------------------------------------------------------------------------------------------------------------------------
SELECT '
DECLARE @sd_id		INT,
		@prli_id	INT,
		@stor_id	INT,
		@prof_id	INT,
		@bra_id		INT,
		@count		INT,
		@count1		INT

SELECT 	@sd_id		= -1,
		@prli_id	= -1,
		@stor_id	= -1,
		@prof_id	= -1,
		@count		= 0,
		@count1		= 0


SELECT @sd_id = 1


SELECT TOP 1 @prli_id = tpl.prli_id
FROM tbPriceList tpl
WHERE tpl.comp_id = '	+ convert(varchar,@comp_id_destino) + '

SELECT TOP 1 @stor_id = ts.stor_id
FROM tbStorage ts
WHERE ts.comp_id = '	+ convert(varchar,@comp_id_destino) + '

SELECT TOP 1 @prof_id = tp.prof_id
FROM tbProfile tp
WHERE tp.comp_id = '	+ convert(varchar,@comp_id_destino) + '

SELECT TOP 1 @bra_id = tb.bra_id
FROM tbBranch tb
WHERE tb.comp_id = '	+ convert(varchar,@comp_id_destino)







----------------------------------------------------------------------------------------------------------------------------------------------

SET @query = ''
SET @query = LTRIM(RTRIM('declare @ws_id_' + CONVERT(VARCHAR,@ws_id) + ' int ')) + CHAR(10) + CHAR(13)

--SET @tbWebSite_Names_query =
SELECT @query = @query +
		'insert into tbWebSite_Names
		(
		comp_id,						ws_desc,							bra_id,
		ws_page_bgcolor_id,				ws_page_bgimage_url,				ws_bgcolor_id,
		ws_bordercolor_id,				ws_borderstyle_id,					ws_borderwidth_id,
		ws_prli_id,						ws_stor_id,							ws_showstock,
		ws_showpricelist,				ws_showzerostockitems,				ws_showcart,
		ws_email_contact,				[user_id],							ws_decimals4Stock,
		ws_decimals4Price,				ws_PotentialStockLimit,				prof_id,
		ws_startuphome,					ws_itemsformat,						ws_showpricewithtax,
		ws_menulevel,					ws_css,								sd_id,
		ws_datashowonitemtab,			ws_showCurrentAccountCustomer,		ws_griddesign_cells,
		ws_griddesign_rows,				ws_griddesign_cellpadding,			ws_griddesign_cellspacing,
		ws_griddesign_maxlength_desc,	ws_itemsformat_all,					ws_itemsformat_newness,
		ws_itemsformat_offer,			ws_change_back_to_fore_onbuttons,	ws_itemdetailformat_all,
		ws_itemdetailformat_newness,	ws_itemdetailformat_offer,			ws_notfound_image_url,
		ws_files2TempUpdated,			ws_maxitemsbyquery,					ws_showitemimageonMycart,

		ws_showcatimageonMenu,			ws_brand_griddesign_cells,			ws_brand_griddesign_rows,
		ws_brand_griddesign_cellpadding,ws_brand_griddesign_cellspacing,	ws_brand_griddesign_maxlength_desc,

		ws_newclient_option,			ws_newclient_cust_id,				ws_newclient_checkpending,
		ws_newclient_emailcontact,		ws_newclient_phonecontact
		) '	+ CHAR(10) +
		'values (' +
		CONVERT(VARCHAR,@comp_id_destino)		+ ',''' +
		CONVERT(VARCHAR,@name)					+ ''',' +
		CONVERT(VARCHAR,ISNULL('@bra_id',-1))	+ ','	+ CHAR(10) +

		CONVERT(VARCHAR,ISNULL(twsn.ws_page_bgcolor_id,-1))		+ ',''' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_page_bgimage_url,''))	+ ''',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_bgcolor_id,-1))			+ ','	+ CHAR(10) +

		CONVERT(VARCHAR,ISNULL(twsn.ws_bordercolor_id,-1)) + ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_borderstyle_id,-1)) + ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_borderwidth_id,-1)) + ',' + CHAR(10) +

		CONVERT(VARCHAR,ISNULL('@prli_id',-1))						+ ',' +
		CONVERT(VARCHAR,ISNULL('@stor_id',-1))						+ ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_showstock,1)))	+ ',' + CHAR(10) +

		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_showpricelist,1)))		+ ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_showzerostockitems,1)))	+ ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_showcart,1)))			+ ',' + CHAR(10) +

		+ '''' + ISNULL(LTRIM(RTRIM(twsn.ws_email_contact)),'') + ''',' +
		CONVERT(VARCHAR,ISNULL(twsn.[user_id],-1))				+ ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_decimals4Stock,-1))		+ ',' + CHAR(10) +

		CONVERT(VARCHAR,ISNULL(twsn.ws_decimals4Price,-1))		+ ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_PotentialStockLimit,-1)) + ',' +
		CONVERT(VARCHAR,ISNULL('@prof_id',-1))					+ ',' + CHAR(10) +

		CONVERT(VARCHAR,ISNULL(twsn.ws_startuphome,-1))						+ ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_itemsformat,-1))						+ ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_showpricewithtax,1)))	+ ',' + CHAR(10) +

		CONVERT(VARCHAR,ISNULL(twsn.ws_menulevel,-1))	+ ',''' +
		CONVERT(NVARCHAR(200),ISNULL(twsn.ws_css,''))	+ ''',' +
		CONVERT(VARCHAR,ISNULL('@sd_id',-1))			+ ','	+ CHAR(10) +

		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_datashowonitemtab,1)))			+ ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_showCurrentAccountCustomer,0)))	+ ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_griddesign_cells,0))							+ ',' + CHAR(10) +

		CONVERT(VARCHAR,ISNULL(twsn.ws_griddesign_rows,0))			+ ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_griddesign_cellpadding,0))	+ ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_griddesign_cellspacing,0))	+ ',' + CHAR(10) +

		CONVERT(VARCHAR,ISNULL(twsn.ws_griddesign_maxlength_desc,0)) + ',' +
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsn.ws_itemsformat_all,0))		= '0' THEN 'NULL'
			ELSE	CONVERT(VARCHAR,ISNULL(twsn.ws_itemsformat_all,0))
		END + ',' +
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsn.ws_itemsformat_newness,0))	= '0' THEN 'NULL'
			ELSE	CONVERT(VARCHAR,ISNULL(twsn.ws_itemsformat_newness,0))
		END + ',' + CHAR(10) +


		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsn.ws_itemsformat_offer,0))	= '0' THEN 'NULL'
			ELSE	CONVERT(VARCHAR,ISNULL(twsn.ws_itemsformat_offer,0))
		END + ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_change_back_to_fore_onbuttons,0))) + ',' +


		'NULL' + ',' + CHAR(10) +

		/*
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsn.ws_itemdetailformat_all,0))		= '0' THEN 'NULL'
			ELSE	CONVERT(VARCHAR,ISNULL(twsn.ws_itemdetailformat_all,0))
		END + ',' + CHAR(10) +


		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsn.ws_itemdetailformat_newness,0))	= '0' THEN 'NULL'
			ELSE	CONVERT(VARCHAR,ISNULL(twsn.ws_itemdetailformat_newness,0))
		END + ',' +
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsn.ws_itemdetailformat_offer,0))	= '0' THEN 'NULL'
			ELSE	CONVERT(VARCHAR,ISNULL(twsn.ws_itemdetailformat_offer,0))
		END + ',' +
		*/

		'NULL' + ',' +
		'NULL' + ',' +

		+ '''' + CONVERT(VARCHAR,ISNULL(twsn.ws_notfound_image_url,''))					+ ''',' + CHAR(10) +


		CONVERT(VARCHAR,CONVERT(BIT,0))											+ ',' +
		CONVERT(VARCHAR,ISNULL(twsn.ws_maxitemsbyquery,0))						+ ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_showitemimageonMycart,0)))	+ ',' + CHAR(10) +


		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsn.ws_showcatimageonMenu,0))	= '0' THEN 'NULL'
			ELSE	CONVERT(VARCHAR,ISNULL(twsn.ws_showcatimageonMenu,0))
		END + ',' +
		CONVERT(VARCHAR,isnull(twsn.ws_brand_griddesign_cells,0))	+ ',' +
		CONVERT(VARCHAR,isnull(twsn.ws_brand_griddesign_rows,0)) 	+ ',' + CHAR(10) +


		CONVERT(VARCHAR,isnull(twsn.ws_brand_griddesign_cellpadding,0))			+ ',' +
		CONVERT(VARCHAR,isnull(twsn.ws_brand_griddesign_cellspacing,0))			+ ',' +
		CONVERT(VARCHAR,isnull(twsn.ws_brand_griddesign_maxlength_desc,0))		+ ',' +


		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_newclient_option,0)))		+ ',' +
		CONVERT(VARCHAR,isnull(twsn.ws_newclient_cust_id,-1))					+ ',' +
		CONVERT(VARCHAR,CONVERT(BIT,ISNULL(twsn.ws_newclient_checkpending,0)))	+ ',''' +
		ISNULL(twsn.ws_newclient_emailcontact,'')								+ ''',''' +
		ISNULL(twsn.ws_newclient_phonecontact,'')

		+ ''')'

FROM	tbWebSite_Names  twsn
WHERE	twsn.comp_id = @comp_id_origen and twsn.ws_id = @ws_id

SET @query = replace(@query,'-1','NULL') + CHAR(10) + CHAR(13)

SET @query = @query + 'set @ws_id_' + CONVERT(VARCHAR,@ws_id) + ' = @@identity'  + CHAR(10)

SET @query = @query + 'select @count = @count + 1' + CHAR(10)

SELECT @query

SELECT 'Select ''Registros actualizados tbWebSite_Names : '' + convert(varchar,@count)
		set @count = 0'






