DECLARE cursor_tbWebSite_Section CURSOR FOR
SELECT	twss.wss_id --, twss.wss_desc, twss.sws_id
FROM	tbWebSite_Section twss
WHERE	twss.comp_id = @comp_id_origen
AND		twss.wss_id IN (SELECT twsnsr.wss_id
						FROM tbWebSite_NameSectionsRelation twsnsr
						WHERE twss.comp_id = @comp_id_origen AND twsnsr.ws_id = @ws_id)

OPEN		cursor_tbWebSite_Section

FETCH cursor_tbWebSite_Section INTO @wss_id --, @wss_desc, @sws_id

WHILE @@FETCH_STATUS = 0
BEGIN

	SET @query = ''

	SET @query = LTRIM(RTRIM('declare @wss_id_' + CONVERT(VARCHAR,@wss_id) + ' int ')) + CHAR(10) + CHAR(13)

	SELECT @query = @query +
					'INSERT INTO tbWebSite_Section
					(
						comp_id, wss_desc,	sws_id
					)' + CHAR(10) +
					'values (' +
					CONVERT(VARCHAR,@comp_id_destino) + ',''' +
					@name + ' ' + CONVERT(VARCHAR,ISNULL(twss.wss_desc,'')) + ''',' +
					CONVERT(VARCHAR,ISNULL(twss.sws_id,-1))
					+ ')'
					FROM	tbWebSite_Section	twss
					WHERE	twss.comp_id = @comp_id_origen
					and		twss.wss_id = @wss_id

	SET @query = replace(@query,'-1','NULL') + CHAR(10) + CHAR(13)

	SET @query = @query + 'set @wss_id_' + CONVERT(VARCHAR,@wss_id) + ' = @@identity' + CHAR(10)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)

	SELECT @query


	FETCH cursor_tbWebSite_Section INTO @wss_id --, @wss_desc, @sws_id

END

CLOSE		cursor_tbWebSite_Section
DEALLOCATE	cursor_tbWebSite_Section

SELECT 'Select ''Registros actualizados tbWebSite_Section : '' + convert(varchar,@count)
		set @count = 0'







