						WHERE	twsspr.comp_id = @comp_id_origen
						AND		twsspr.ws_id	= @ws_id
						AND		twsspr.wss_id	IN (SELECT	twss.wss_id
													FROM	tbWebSite_Section twss
													WHERE	twss.comp_id	= @comp_id_origen
													AND		twss.wss_id		IN (SELECT twsnsr.wss_id
																				FROM tbWebSite_NameSectionsRelation twsnsr
																				WHERE twss.comp_id = @comp_id_origen AND twsnsr.ws_id = @ws_id)))

