	SET @query = ''

	SET @query = LTRIM(RTRIM('declare @wsp_id_' + CONVERT(VARCHAR,@wsp_id) + ' int ')) + CHAR(10) + CHAR(13)

	SELECT @query = @query +
	'INSERT INTO tbWebSite_Paragraph
	(
		comp_id,					wsp_desc,			wsp_width,
		wsp_align,					wsp_inUpdatePanel,	wsp_columnspan,
		wsp_load_orientation_id,	wsp_rowspan
