	'values (' +
	CONVERT(VARCHAR,@comp_id_destino) + ',''' +
	@name + ' ' + ISNULL(twsp.wsp_desc,'') + ''',' +
	CONVERT(VARCHAR,ISNULL(twsp.wsp_width,-1)) + ',' +
	CONVERT(VARCHAR,ISNULL(twsp.wsp_align,-1)) + ',' +
	CONVERT(VARCHAR,ISNULL(twsp.wsp_inUpdatePanel,-1)) + ',' +
	CONVERT(VARCHAR,ISNULL(twsp.wsp_columnspan,-1)) + ',' +
	CONVERT(VARCHAR,ISNULL(twsp.wsp_load_orientation_id,-1)) + ',' +
	CONVERT(VARCHAR,ISNULL(twsp.wsp_rowspan,1))
	+ ')'
	FROM	tbWebSite_Paragraph twsp
	WHERE	twsp.comp_id	= @comp_id_origen
	AND 	twsp.wsp_id		= @wsp_id

	SET @query = replace(@query,'-1','NULL') + CHAR(10) + CHAR(13)

	SET @query = @query + 'set @wsp_id_' + CONVERT(VARCHAR,@wsp_id) + ' = @@identity' + CHAR(10)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)

	SELECT @query


	FETCH cursor_tbWebSite_Paragraph INTO @wsp_id

END

CLOSE		cursor_tbWebSite_Paragraph
