DECLARE cursor_tbWebSite_WordsIni CURSOR FOR
SELECT	twswi.wswi_id
FROM	tbWebSite_WordsIni twswi
WHERE	twswi.wswi_id IN (SELECT DISTINCT twspccd.wspcc_wswi_id
							FROM tbWebSite_ParagraphComponentsControlsData twspccd
							WHERE twspccd.comp_id=@comp_id_origen AND twspccd.ws_id=@ws_id AND not twspccd.wspcc_wswi_id IS NULL
							UNION
							SELECT DISTINCT twsdd.wsdat_wswi_id
							FROM tbWebSite_DetailData twsdd
							WHERE twsdd.comp_id=@comp_id_origen AND twsdd.ws_id=@ws_id AND NOT twsdd.wsdat_wswi_id IS NULL
							UNION
							SELECT DISTINCT twspcr.wspcr_text_wswi_id
							FROM tbWebSite_ParagraphComponentsRelation twspcr
							WHERE twspcr.comp_id=@comp_id_origen AND twspcr.ws_id=@ws_id AND NOT twspcr.wspcr_text_wswi_id IS null
							)

OPEN cursor_tbWebSite_WordsIni

FETCH cursor_tbWebSite_WordsIni INTO @wswi_id

WHILE @@FETCH_STATUS = 0
BEGIN

	SET @query = ''

	SET @query = LTRIM(RTRIM('declare @wswi_id_' + CONVERT(VARCHAR,@wswi_id) + ' int ')) + CHAR(10) + CHAR(13)

	SELECT @query = @query +
	'INSERT INTO tbWebSite_WordsIni	(wswi_enabled)' + CHAR(10) +
	'values (''True'')'
	FROM	tbWebSite_WordsIni twswi
	WHERE	twswi.wswi_id = @wswi_id

	SET @query = replace(@query,'-1','NULL') + CHAR(10) + CHAR(13)

	SET @query = @query + 'set @wswi_id_' + CONVERT(VARCHAR,@wswi_id) + ' = @@identity' + CHAR(10)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)

	SELECT @query





	SET @query = ''

	--SET @query = LTRIM(RTRIM('declare @wswi_id_' + CONVERT(VARCHAR,@wswi_id) + ' int ')) + CHAR(10) + CHAR(13)

	SELECT @query = @query +
	'INSERT INTO tbWebSite_WordsNew(lang_id,wswi_id,wswn_desc)' + CHAR(10) +
	'values (' +
	CONVERT(VARCHAR,ISNULL(twswn.lang_id,'-1')) + ',' +
	'@wswi_id_' + CONVERT(VARCHAR,ISNULL(@wswi_id,'-1')) + ',''' +
	CONVERT(NVARCHAR(4000),
				replace(ISNULL(twswn.wswn_desc,''),'''','''''')
			)
	+ ''')'
	FROM	tbWebSite_WordsNew twswn
	WHERE	twswn.lang_id = @lang_id
	AND		twswn.wswi_id = @wswi_id
	--twswn.wswi_id
	SET @query = replace(@query,'-1','NULL') + CHAR(10) + CHAR(13)

	SET @query = @query + 'select @count1 = @count1 + 1' + CHAR(10)

	SELECT @query


	FETCH cursor_tbWebSite_WordsIni INTO @wswi_id
END

CLOSE		cursor_tbWebSite_WordsIni
DEALLOCATE	cursor_tbWebSite_WordsIni

SELECT 'Select ''Registros actualizados tbWebSite_WordsIni : '' + convert(varchar,@count)
		set @count = 0'
SELECT 'Select ''Registros actualizados tbWebSite_WordsNew : '' + convert(varchar,@count1)
		set @count1 = 0'





