	SELECT @query = @query +
	'INSERT INTO tbWebSite_ParagraphComponentsRelation
	(
		comp_id,				wsp_id,					swsc_id,
		swsc_id_outputContainer,wspcr_order,			wspcr_width,
		wspcr_height,			wspcr_url,				wspcr_text_wswi_id,
		ws_id,					wspcr_newTable,			wspcr_newRow,
		wspcr_newCell,			wspcr_verticalLoad,		wspcr_image_repet
	)' + CHAR(10) +
	'values (' +
	CONVERT(VARCHAR,ISNULL(@comp_id_destino,'-1')) + ',' +
	'@wsp_id_' + CONVERT(VARCHAR,ISNULL(twspcr.wsp_id,'-1')) + ',' +
	CONVERT(VARCHAR,ISNULL(twspcr.swsc_id,'-1')) + ',' +
	CONVERT(VARCHAR,ISNULL(twspcr.swsc_id_outputContainer,'-1')) + ',' +
	CONVERT(VARCHAR,ISNULL(twspcr.wspcr_order,'-1')) + ',' +
	CONVERT(VARCHAR,ISNULL(twspcr.wspcr_width,'-1')) + ',' +
	CONVERT(VARCHAR,ISNULL(twspcr.wspcr_height,'-1')) + ',''' +
	ISNULL(twspcr.wspcr_url,'') + ''',' +

	--'@wspcc_wswi_id_' + CONVERT(VARCHAR,ISNULL(twspcr.wspcr_text_wswi_id,'-1'))
	CASE WHEN twspcr.wspcr_text_wswi_id IS NULL
		THEN '-1'
		ELSE '@wswi_id_' + CONVERT(VARCHAR,twspcr.wspcr_text_wswi_id)
	END

	+ ',' +
	'@ws_id_' + CONVERT(VARCHAR,@ws_id)

	+ ',' +
	/*
	CONVERT(VARCHAR,ISNULL(wspcr_newTable,'NULL')) + ',' +
	CONVERT(VARCHAR,ISNULL(wspcr_newRow,'NULL')) + ',' +
	CONVERT(VARCHAR,ISNULL(wspcr_newCell,'NULL')) + ',' +
	CONVERT(VARCHAR,ISNULL(wspcr_verticalLoad,'NULL'))
	*/
	CASE WHEN wspcr_newTable IS NULL THEN 'null'
		WHEN wspcr_newTable = 'true' THEN '''true'''
		WHEN wspcr_newTable = 'false' THEN '''false'''
	END + ',' +
	CASE WHEN wspcr_newRow IS NULL THEN 'null'
		WHEN wspcr_newRow = 'true' THEN '''true'''
		WHEN wspcr_newRow = 'false' THEN '''false'''
	END + ',' +
	CASE WHEN wspcr_newCell IS NULL THEN 'null'
		WHEN wspcr_newCell = 'true' THEN '''true'''
		WHEN wspcr_newCell = 'false' THEN '''false'''
	END + ',' +
	CASE WHEN wspcr_verticalLoad IS NULL THEN 'null'
		WHEN wspcr_verticalLoad = 'true' THEN '''true'''
		WHEN wspcr_verticalLoad = 'false' THEN '''false'''
	END	+ ',' +

	CASE WHEN	CONVERT(VARCHAR,ISNULL(twspcr.wspcr_image_repet,-1))	= '-1' THEN 'NULL'
		ELSE	CONVERT(VARCHAR,ISNULL(twspcr.wspcr_image_repet,0))
	END

	+ ')'
	FROM	tbWebSite_ParagraphComponentsRelation twspcr
	WHERE	twspcr.comp_id	= @comp_id_origen
	AND		twspcr.wsplr_id = @wsplr_id

	SET @query = replace(@query,'-1','NULL') + CHAR(10) --+ CHAR(13)

	SET @query = @query + 'set @wsplr_id_' + CONVERT(VARCHAR,@wsplr_id) + ' = @@identity' + CHAR(10)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)

	SELECT @query


	FETCH cursor_tbWebSite_ParagraphComponentsRelation INTO @wsplr_id

END

CLOSE		cursor_tbWebSite_ParagraphComponentsRelation
DEALLOCATE	cursor_tbWebSite_ParagraphComponentsRelation

SELECT 'Select ''Registros actualizados tbWebSite_ParagraphComponentsRelation : '' + convert(varchar,@count)
		set @count = 0'







