	CONVERT(VARCHAR,ISNULL(twspccd.swscc_id,'-1')) + ',''' +
	ISNULL(twspccd.wspcc_image_url,'') + ''',''' +
	ISNULL(twspccd.wspcc_flash_url,'') + ''',' +

	--'@wspcc_wswi_id_' + CONVERT(VARCHAR,ISNULL(twspccd.wspcc_wswi_id,'-1'))
	CASE WHEN twspccd.wspcc_wswi_id IS NULL
		THEN '-1'
		ELSE '@wswi_id_' + CONVERT(VARCHAR,twspccd.wspcc_wswi_id)
