	+ ',' +
	'@ws_id_' + CONVERT(VARCHAR,ISNULL(twspccd.ws_id,'-1')) + ',''' +
	ISNULL(twspccd.wspcc_href,'') + ''',' +
	CONVERT(VARCHAR,ISNULL(twspccd.wspcc_height,'-1')) + ',' +
