	END  + ',' +

	CASE WHEN	CONVERT(VARCHAR,ISNULL(twspccd.ith_id,0))	= '0' THEN 'NULL'
		ELSE	CONVERT(VARCHAR,ISNULL(twspccd.ith_id,0))
	END  + ',' +
	CASE WHEN	CONVERT(VARCHAR,ISNULL(twspccd.wspcc_action,0))	= '0' THEN 'NULL'
		ELSE	CONVERT(VARCHAR,ISNULL(twspccd.wspcc_action,0))
	END

	+ ')'
	FROM	tbWebSite_ParagraphComponentsControlsData twspccd
	WHERE	twspccd.comp_id		= @comp_id_origen
	AND		twspccd.wspcc_id	= @wspcc_id

	SET @query = replace(@query,'-1','NULL') + CHAR(10) --+ CHAR(13)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)

