DECLARE cursor_tbWebSite_DetailData CURSOR FOR
SELECT	twsdd.wsdat_id
FROM	tbWebSite_DetailData twsdd
WHERE	twsdd.comp_id	= @comp_id_origen
AND		twsdd.ws_id		= @ws_id


OPEN cursor_tbWebSite_DetailData

FETCH cursor_tbWebSite_DetailData INTO @wsdat_id

WHILE @@FETCH_STATUS = 0
BEGIN

	SET @query = ''


	SELECT @query = @query +
	'INSERT INTO tbWebSite_DetailData
	(
		comp_id,			ws_id,			wsdet_id,
		wsdat_order,		wsdat_data1,	wsdat_data2,
		wsdat_image_url,	optval_id,		wsdat_image_order,
		wsdat_wswi_id,		wsdat_height,	wsdat_width,
		wsdat_newTable,		wsdat_newRow,	wsdat_newCell,
		wsdat_verticalLoad,	wsdat_colspan,	wsdat_rowspan
	)' + CHAR(10) +
	'values
	(' +
		CONVERT(VARCHAR,ISNULL(@comp_id_destino,'-1')) + ',' +
		'@ws_id_' + CONVERT(VARCHAR,ISNULL(twsdd.ws_id,'-1')) + ',' +
		'@wsdet_id_' + CONVERT(VARCHAR,ISNULL(twsdd.wsdet_id,'-1')) + ',' +

		CONVERT(VARCHAR,ISNULL(twsdd.wsdat_order,'0')) + ',''' +
		ISNULL(twsdd.wsdat_data1,'') + ''',''' +
		ISNULL(twsdd.wsdat_data2,'') + ''',''' +

		ISNULL(twsdd.wsdat_image_url,'') + ''',' +
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.optval_id,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.optval_id,0))
		END		+ ',' +
		--CONVERT(VARCHAR,ISNULL(twsdd.optval_id,'NULL')) + ''',''' +


		--CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_image_order,0))	= '0' THEN '-1'
		--	ELSE
				CONVERT(VARCHAR,ISNULL(twsdd.wsdat_image_order,0))
		--END
		+ ',' +
		--CONVERT(VARCHAR,ISNULL(twsdd.wsdat_wswi_id,'NULL')) + ''',' +



		CASE	WHEN twsdd.wsdat_wswi_id IS NULL				THEN '-1'
				WHEN twsdd.wsdat_wswi_id = 0					THEN '-1'
				ELSE '@wswi_id_' + CONVERT(VARCHAR,twsdd.wsdat_wswi_id)
		END + ',' +

		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_height,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_height,0))
		END		+ ',' +
		--CONVERT(VARCHAR,ISNULL(twsdd.wsdat_height,'0')) + ',' +

		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_width,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_width,0))
		END		+ ',' +
		--CONVERT(VARCHAR,ISNULL(twsdd.wsdat_width,'0'))	+ ',''' +


		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_newTable,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_newTable,0))
		END		+ ',' +
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_newRow,0))		= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_newRow,0))
		END		+ ',' +
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_newCell,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_newCell,0))
		END		+ ',' +
		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_verticalLoad,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_verticalLoad,0))
		END		+ ',' +


		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_colspan,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_colspan,0))
		END		+ ',' +
		--CONVERT(VARCHAR,ISNULL(twsdd.wsdat_colspan,'NULL')) + ',' +

		CASE WHEN	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_rowspan,0))	= '0' THEN '-1'
			ELSE	CONVERT(VARCHAR,ISNULL(twsdd.wsdat_rowspan,0))
		END		--+ '' +
		--CONVERT(VARCHAR,ISNULL(twsdd.wsdat_rowspan,'NULL'))


	+ ')'
	FROM	tbWebSite_DetailData	twsdd
	WHERE	twsdd.comp_id		= @comp_id_origen
	AND		twsdd.wsdat_id		= @wsdat_id

	SET @query = replace(@query,'-1','NULL') + CHAR(10) --+ CHAR(13)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)

	SELECT @query


	FETCH cursor_tbWebSite_DetailData INTO @wsdat_id

END

CLOSE		cursor_tbWebSite_DetailData
DEALLOCATE	cursor_tbWebSite_DetailData

SELECT 'Select ''Registros actualizados tbWebSite_DetailData : '' + convert(varchar,@count)
		set @count = 0'





