					CASE
						WHEN twsdd.ws_id IS NULL THEN '-1'
						ELSE '@ws_id_' + CONVERT(VARCHAR,twsdd.ws_id)
					END														+ ',' +
					'-1'													+ ',' +
					CONVERT(VARCHAR,ISNULL(twsdd.itimg_order,'-1'))					+ ',' +
					CONVERT(VARCHAR,ISNULL(twsdd.itd_order,'-1'))					+ ',' +
