DECLARE cursor_tbWebSite_Menu CURSOR FOR
SELECT	twss.wsm_id
FROM	tbWebSite_Menu twss
WHERE	twss.comp_id	= @comp_id_origen
AND		twss.ws_id		= @ws_id

ORDER BY twss.wsm_id_sup, twss.wsm_id


OPEN	cursor_tbWebSite_Menu


FETCH	cursor_tbWebSite_Menu INTO @wsm_id



WHILE @@FETCH_STATUS = 0
BEGIN

	SET @query = ''


	SET @query = LTRIM(RTRIM('declare @wsm_id_' + CONVERT(VARCHAR,@wsm_id) + ' int ')) + CHAR(10) + CHAR(13)



	SELECT @query = @query +
					'INSERT INTO tbWebSite_Menu
					(
						comp_id,		ws_id,			wsm_id_sup,
						wsm_order,		wsm_desc,		wsm_link,
						wsm_startup,	wsm_action
 					)' + CHAR(10) +
					'values (' +
					CONVERT(VARCHAR,@comp_id_destino)					+ ',' +
					'@ws_id_'	+ CONVERT(VARCHAR,@ws_id)				+ ',' +

					CASE WHEN twss.wsm_id_sup = 0 THEN '0'
						ELSE '@wsm_id_'	+ CONVERT(VARCHAR,twss.wsm_id_sup)
					END													+ ',' +

					CONVERT(VARCHAR,ISNULL(twss.wsm_order,'0'))			+ ',''' +
					CONVERT(NVARCHAR(200),ISNULL(twss.wsm_desc,''))			+ ''',''' +
					CONVERT(NVARCHAR(1000),ISNULL(twss.wsm_link,''))			+ ''',' +
					CASE WHEN	CONVERT(VARCHAR,ISNULL(twss.wsm_startup,0))	= '0' THEN '-1'
						ELSE	CONVERT(VARCHAR,ISNULL(twss.wsm_startup,0))
					END		+ ',' +

					CONVERT(VARCHAR,ISNULL(twss.wsm_action,'-1'))
					+ ')'
					FROM	tbWebSite_Menu	twss
					WHERE	twss.comp_id	= @comp_id_origen
					AND	    twss.ws_id		= @ws_id
					and		twss.wsm_id		= @wsm_id



	SET @query = replace(@query,'-1','NULL')  + CHAR(10) + CHAR(13)

	SET @query = @query + 'set @wsm_id_' + CONVERT(VARCHAR,@wsm_id) + ' = @@identity' + CHAR(10)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)

	SELECT @query



	SET @query = ''
	SELECT 'UPDATE tbWebSite_Menu
			SET	wsm_detail1 = ''' +
			replace(isnull(twss.wsm_detail1,''),'''','''''') + ''' ' +
			'where wsm_id = @wsm_id_' + CONVERT(VARCHAR,@wsm_id)
			FROM	tbWebSite_Menu	twss
					WHERE	twss.comp_id	= @comp_id_origen
					AND	    twss.ws_id		= @ws_id
					and		twss.wsm_id		= @wsm_id
	SELECT @query




	SET @query = ''
	SELECT 'UPDATE tbWebSite_Menu
			SET	wsm_detail2 = ''' +
			replace(isnull(twss.wsm_detail2,''),'''','''''') + ''' ' +
			'where wsm_id = @wsm_id_' + CONVERT(VARCHAR,@wsm_id)
			FROM	tbWebSite_Menu	twss
					WHERE	twss.comp_id	= @comp_id_origen
					AND	    twss.ws_id		= @ws_id
					and		twss.wsm_id		= @wsm_id
	SELECT @query





	SET @query = ''
	SELECT 'UPDATE tbWebSite_Menu
			SET	wsm_detail3 = ''' +
			replace(isnull(twss.wsm_detail3,''),'''','''''') + ''' ' +
			'where wsm_id = @wsm_id_' + CONVERT(VARCHAR,@wsm_id)
			FROM	tbWebSite_Menu	twss
					WHERE	twss.comp_id	= @comp_id_origen
					AND	    twss.ws_id		= @ws_id
					and		twss.wsm_id		= @wsm_id
	SELECT @query



	SET @query = ''
	SELECT 'UPDATE tbWebSite_Menu
			SET	wsm_detail4 = ''' +
			replace(isnull(twss.wsm_detail4,''),'''','''''') + ''' ' +
			'where wsm_id = @wsm_id_' + CONVERT(VARCHAR,@wsm_id)
			FROM	tbWebSite_Menu	twss
					WHERE	twss.comp_id	= @comp_id_origen
					AND	    twss.ws_id		= @ws_id
					and		twss.wsm_id		= @wsm_id
	SELECT @query



	FETCH	cursor_tbWebSite_Menu INTO @wsm_id

END

CLOSE		cursor_tbWebSite_Menu
DEALLOCATE	cursor_tbWebSite_Menu


SELECT 'Select ''Registros actualizados tbWebSite_Menu : '' + convert(varchar,@count)
		set @count = 0'








