DECLARE @color_id_original	INT


DECLARE cursor_color CURSOR FOR
SELECT	twsn.ws_page_bgcolor_id		[color_id]
FROM	tbWebSite_Names twsn
WHERE	twsn.comp_id			= @comp_id_origen
AND		twsn.ws_id				= @ws_id
AND		twsn.ws_page_bgcolor_id > 9999
UNION
SELECT	twsn.ws_bgcolor_id
FROM	tbWebSite_Names twsn
WHERE	twsn.comp_id			= @comp_id_origen
AND		twsn.ws_id				= @ws_id
AND		twsn.ws_bgcolor_id		> 9999
UNION
SELECT	twsn.ws_bordercolor_id
FROM	tbWebSite_Names twsn
WHERE	twsn.comp_id			= @comp_id_origen
AND		twsn.ws_id				= @ws_id
AND		twsn.ws_bordercolor_id	> 9999

UNION

SELECT	twsspr.bc_id
FROM	tbWebSite_SectionParagraphRelation twsspr
WHERE	twsspr.comp_id			= @comp_id_origen
AND		twsspr.ws_id			= @ws_id
AND		twsspr.bc_id			> 9999
UNION
SELECT	twsspr.color_id
FROM	tbWebSite_SectionParagraphRelation twsspr
WHERE	twsspr.comp_id			= @comp_id_origen
AND		twsspr.ws_id			= @ws_id
AND		twsspr.color_id			> 9999
UNION
SELECT	twsspr.fb_id
FROM	tbWebSite_SectionParagraphRelation twsspr
WHERE	twsspr.comp_id			= @comp_id_origen
AND		twsspr.ws_id			= @ws_id
AND		twsspr.fb_id			> 9999

UNION

SELECT	twss.color_id
FROM	tbWebSite_Styles twss
WHERE	twss.comp_id			= @comp_id_origen
AND		twss.ws_id				= @ws_id
AND		twss.color_id			> 9999
UNION
SELECT	twss.bc_id
FROM	tbWebSite_Styles twss
WHERE	twss.comp_id			= @comp_id_origen
AND		twss.ws_id				= @ws_id
AND		twss.bc_id				> 9999
UNION
SELECT	twss.fb_id
FROM	tbWebSite_Styles twss
WHERE	twss.comp_id			= @comp_id_origen
AND		twss.ws_id				= @ws_id
AND		twss.fb_id				> 9999

OPEN cursor_color

FETCH cursor_color INTO @color_id_original

WHILE @@FETCH_STATUS = 0
BEGIN

--		@color_id			INT,
--		@color_desc			NVARCHAR(200),
--		@color_value		NVARCHAR(10)


	SET @query = ''

	SET @query = LTRIM(RTRIM('declare @color_id_' + CONVERT(VARCHAR,@color_id_original) + ' int ')) + CHAR(10) + CHAR(13)

	SELECT @query = @query +
			'	IF EXISTS (SELECT 1 FROM tbWebSite_Colors twsc
			 	           WHERE twsc.color_value = ''' + CONVERT(VARCHAR,ISNULL(twsc.color_value,'')) + ''')					SELECT TOP 1 @color_id_' + CONVERT(VARCHAR,@color_id_original) + ' = twsc.color_id
					FROM tbWebSite_Colors twsc
					WHERE twsc.color_value = '''+ CONVERT(VARCHAR,ISNULL(twsc.color_value,'')) + '''
				ELSE
				BEGIN ' +
					'INSERT INTO tbWebSite_Colors ( color_desc, color_value )' + CHAR(10) +
					'values (''' +
								CONVERT(VARCHAR,ISNULL(twsc.color_desc,''))		+ ''',''' +
								CONVERT(VARCHAR,ISNULL(twsc.color_value,''))	+ ''')

					set @color_id_' + CONVERT(VARCHAR,@color_id_original) + ' = @@identity
				END'



			FROM	tbWebSite_Colors twsc
			WHERE	twsc.color_id = @color_id_original


	SET @query = replace(@query,'-1','NULL') + CHAR(10) + CHAR(13)

	--SET @query = @query + 'set @color_id_' + CONVERT(VARCHAR,@color_id_original) + ' = @@identity' + CHAR(10)

	SET @query = @query + 'select @count = @count + 1' + CHAR(10)


	SET @query = @query + '	UPDATE	tbWebSite_Names
							SET		ws_page_bgcolor_id	= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id				= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		ws_page_bgcolor_id	= ' + CONVERT(VARCHAR,@color_id_original) + '

							UPDATE	tbWebSite_Names
							SET		ws_bgcolor_id		= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id				= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		ws_bgcolor_id		= ' + CONVERT(VARCHAR,@color_id_original) + '

							UPDATE	tbWebSite_Names
							SET		ws_bordercolor_id	= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id				= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		ws_bordercolor_id	= ' + CONVERT(VARCHAR,@color_id_original) + '


							UPDATE	tbWebSite_SectionParagraphRelation
							SET		fb_id		= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id		= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		fb_id		= ' + CONVERT(VARCHAR,@color_id_original) + '

							UPDATE	tbWebSite_SectionParagraphRelation
							SET		bc_id		= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id		= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		bc_id		= ' + CONVERT(VARCHAR,@color_id_original) + '

							UPDATE	tbWebSite_SectionParagraphRelation
							SET		color_id	= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id		= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		color_id	= ' + CONVERT(VARCHAR,@color_id_original) + '


							UPDATE	tbWebSite_Styles
							SET		fb_id		= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id		= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		fb_id		= ' + CONVERT(VARCHAR,@color_id_original) + '

							UPDATE	tbWebSite_Styles
							SET		color_id	= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id		= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		color_id	= ' + CONVERT(VARCHAR,@color_id_original) + '

							UPDATE	tbWebSite_Styles
							SET		bc_id		= @color_id_' + CONVERT(VARCHAR,@color_id_original) + '
							WHERE	ws_id		= @ws_id_' + CONVERT(VARCHAR,@ws_id) + '
							AND		bc_id		= ' + CONVERT(VARCHAR,@color_id_original) + '
							' + CHAR(10)

	SELECT @query





	FETCH cursor_color INTO @color_id_original

END

CLOSE cursor_color
DEALLOCATE cursor_color



SELECT
'
	COMMIT TRANSACTION


END
TRY BEGIN CATCH
	ROLLBACK TRANSACTION
	SELECT	ERROR_LINE(), ERROR_MESSAGE()
END CATCH
'




