CREATE PROCEDURE spSystem_ExportWebSite_Files
(@ws_id INT)
AS

SET NOCOUNT ON


DECLARE @table_image AS TABLE(ws_file_id INT)

INSERT INTO @table_image (ws_file_id)

SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT twsd.wsdet_image_url
							FROM tbWebSite_Detail twsd
							WHERE twsd.ws_id = @ws_id AND isnull(twsd.wsdet_image_url,'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT twsl.wslang_url
							FROM tbWebSite_Languages twsl
							WHERE twsl.ws_id = @ws_id AND isnull(twsl.wslang_url,'') <> '' )

UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT	twsn.ws_page_bgimage_url
							FROM	tbWebSite_Names twsn
							WHERE twsn.ws_id = @ws_id AND isnull(twsn.ws_page_bgimage_url,'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT dbo.fnSplitPosition(twsn.ws_css,';',1)
							FROM	tbWebSite_Names twsn
							WHERE twsn.ws_id = @ws_id AND isnull(dbo.fnSplitPosition(twsn.ws_css,';',1),'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT dbo.fnSplitPosition(twsn.ws_css,';',2)
							FROM	tbWebSite_Names twsn
							WHERE twsn.ws_id = @ws_id AND isnull(dbo.fnSplitPosition(twsn.ws_css,';',2),'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT dbo.fnSplitPosition(twsn.ws_css,';',3)
                           FROM tbWebSite_Names twsn
							WHERE twsn.ws_id = @ws_id AND isnull(dbo.fnSplitPosition(twsn.ws_css,';',3),'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT dbo.fnSplitPosition(twsn.ws_css,';',4)
							FROM	tbWebSite_Names twsn
							WHERE twsn.ws_id = @ws_id AND isnull(dbo.fnSplitPosition(twsn.ws_css,';',4),'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT	twsn.ws_notfound_image_url
							FROM	tbWebSite_Names twsn
							WHERE twsn.ws_id = @ws_id AND isnull(twsn.ws_notfound_image_url,'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT twspccd.wspcc_image_url
							FROM tbWebSite_ParagraphComponentsControlsData twspccd
							WHERE twspccd.ws_id = @ws_id AND isnull(twspccd.wspcc_image_url,'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT twspccd.wspcc_flash_url
							FROM tbWebSite_ParagraphComponentsControlsData twspccd
							WHERE twspccd.ws_id = @ws_id AND isnull(twspccd.wspcc_flash_url,'') <> '')
UNION
SELECT twsf.ws_fileId
FROM tbWebSite_Files twsf
WHERE twsf.ws_fileName IN (SELECT twssprs.wsst_url
                           FROM tbWebSite_SectionParagraphRelationStyles twssprs
							WHERE twssprs.ws_id = @ws_id AND isnull(twssprs.wsst_url,'') <> '')

SELECT twsf.*
FROM @table_image ti
INNER JOIN tbWebSite_Files twsf ON twsf.ws_fileId = ti.ws_file_id

GO






