-- =============================================
-- Author:		MOS
-- Create date: 09-2013
-- Description:	Libera Procesos Inactivos
-- (Mas de 60 minutos)
-- =============================================
--
create PROCEDURE [dbo].[spSystem_FreeProcesses]
AS
BEGIN

	DECLARE @v_spid INT

	DECLARE Users CURSOR

	FAST_FORWARD FOR

	SELECT SPID

	FROM master.dbo.sysprocesses (NOLOCK)

	WHERE spid>50

	AND status='sleeping'

	AND DATEDIFF(mi,last_batch,GETDATE())>=60 --Check sleeping connections that exists before 60 min..

	AND spid<>@@spid

	OPEN Users

	FETCH NEXT FROM Users INTO @v_spid

	WHILE (@@FETCH_STATUS=0)

	BEGIN

	PRINT 'KILLing '+CONVERT(VARCHAR,@v_spid)+'...'

	EXEC('KILL '+@v_spid)

	FETCH NEXT FROM Users INTO @v_spid

	END

	CLOSE Users

	DEALLOCATE Users

END
GO


-- =============================================
-- Author:		MOS
-- Create date: 08-2009
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GenerateDatabaseBackup]

AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @strDataBase AS VARCHAR(MAX)
	DECLARE @strDestiny  AS VARCHAR(MAX)
	SELECT  @strDataBase = DB_NAME()
	SELECT  @strDestiny  = 'C:\GlobalBluePoint.Backup\' + @strDataBase + '.bak'


	-- ----------------------------------
	-- Es SQL Express ?
	-- ----------------------------------
	DECLARE @bolIsExpress AS BIT = 'False'
	IF (@@version LIKE '%EXPRESS%' OR @@VERSION LIKE '%Server 2005%')
		SET @bolIsExpress = 'True'
	-- ----------------------------------

	-- ----------------------------------
	-- Mantenimiento de la BD
	-- ----------------------------------
	EXEC spsystem_dailyDatabaseMaintenance
	-- ----------------------------------

	-- ----------------------------------
	-- Vacia el Log
	-- ----------------------------------
	EXEC spSystem_GenerateDatabaseBackupTruncateLog
	-- ----------------------------------

	-- ----------------------------------
	-- Backup de la BD
	-- ----------------------------------
	DECLARE @strExecute AS NVARCHAR(1000)

	IF @bolIsExpress = 'True'
		BEGIN
			SET @strExecute = '
								BACKUP DATABASE ' + @strDataBase  + ' TO DISK=''' + @strDestiny  + ''' WITH FORMAT'

		END
	ELSE
		BEGIN
			SET @strExecute = '
								BACKUP DATABASE ' + @strDataBase  + ' TO DISK=''' + @strDestiny  + ''' WITH FORMAT, COMPRESSION'

		END

	select @strExecute
	EXEC  (@strExecute)
	-- ----------------------------------



END
GO





