-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GenerateDatabaseBackupTruncateLog]
AS
BEGIN
	SET NOCOUNT ON;



	-- ATENCION
	-- Si se modifica algo hacerlo en :
	-- spSystem_GenerateDatabaseUpdateTruncateLog
	-- [spSystem_GenerateDatabaseBackupTruncateLog


	-- ---------------------------------------------------------
	-- Vaciar el LOG de Transacciones
	-- ---------------------------------------------------------
	IF DATEPART(hour ,GETDATE()) >= 16 OR DATEPART(hour ,GETDATE()) <= 7
		BEGIN
			DECLARE @strExecute			AS NVARCHAR(1000)
			DECLARE @strDatabaseLogName as nvarchar(300)
			SELECT	@strDatabaseLogName = name
				FROM sys.master_files		WITH (NOLOCK)
				WHERE database_id = db_id()
					AND type = 1

			SET @strExecute = '
								DBCC SHRINKFILE (N''' + @strDatabaseLogName + ''' , 0, TRUNCATEONLY)	  '

			EXEC (@strExecute)
		END
	-- ---------------------------------------------------------


END
GO






-- =============================================
-- Author:		MOS
-- Create date: 01-2015
-- Description:	Graba Checksum inicial de imagenes
-- =============================================
--
CREATE PROCEDURE [dbo].[spSystem_GenerateDatabaseImageCheckSum]
AS
BEGIN

	UPDATE tbbrand			SET brand_imageChecksum		= dbo.fnChecksum4Image(brand_image)		WHERE brand_imageChecksum IS NULL

	UPDATE tbcategory		SET cat_imageChecksum		= dbo.fnChecksum4Image(cat_image)		WHERE cat_imageChecksum IS NULL
	UPDATE tbSubcategory	SET subcat_imageChecksum	= dbo.fnChecksum4Image(subcat_image)	WHERE subcat_imageChecksum IS NULL
	UPDATE tbItem			SET item_imageChecksum		= dbo.fnChecksum4Image(item_picture)	WHERE item_imageChecksum IS NULL
	UPDATE tbItemImages		SET itimg_imageChecksum		= dbo.fnChecksum4Image(itimg_image)		WHERE itimg_imageChecksum IS NULL

	UPDATE tbCustomer		SET cust_imageChecksum		= dbo.fnChecksum4Image(cust_picture)	WHERE cust_imageChecksum IS NULL



END
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2010
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GenerateDatabaseOwner]

AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @strDataBase AS VARCHAR(MAX)
	SELECT  @strDataBase = DB_NAME()

	-- Que se ejecute SIEMPRE
	-- Por si el que crea la BD no lo hace como sa
	DECLARE @strExec AS VARCHAR(MAX)
	SET @strExec = '
	ALTER AUTHORIZATION ON DATABASE::' + @strDataBase + ' TO sa'
	EXEC (@strExec)

	SET @strExec = '
	ALTER DATABASE ' + @strDataBase + ' SET TRUSTWORTHY ON'
	EXEC (@strExec)

	SET @strExec = '
					sp_configure ''clr ENABLED'', 1;
					'
	EXEC (@strExec)

	SET @strExec = '
					RECONFIGURE;
					'
	EXEC (@strExec)


	SET @strExec = '
					sp_configure ''show advanced options'', 1;
					'
	EXEC (@strExec)

	SET @strExec = '
					RECONFIGURE;
					'
	EXEC (@strExec)

	SET @strExec = '
					sp_configure ''xp_cmdshell'', 1;
					'
	EXEC (@strExec)

	SET @strExec = '
					RECONFIGURE;
					'
	EXEC (@strExec)



END
GO

-- =============================================
-- Author:		Reindexa la Base de Datos
-- =============================================
CREATE PROCEDURE spSystem_GenerateDatabaseReindex

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- Hace primero una copia de seguridad
	Select 'Efectuando Copia de seguridad . . .'
	EXEC spSystem_GenerateDatabaseBackup

    DECLARE @TableName varchar(255)
	DECLARE TableCursor CURSOR FOR
	SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES
	WHERE TABLE_TYPE = 'base table'
	OPEN TableCursor
	FETCH NEXT FROM TableCursor INTO @TableName
	WHILE @@FETCH_STATUS = 0
	BEGIN
	PRINT 'Reindexing ' + @TableName
	DBCC DBREINDEX(@TableName,' ' ,90)
	FETCH NEXT FROM TableCursor INTO @TableName
	END
	CLOSE TableCursor
	DEALLOCATE TableCursor

END
GO





