-- =============================================
-- Author:		MOS
-- Create date: 07-2013
-- Informa el Peso de cada tabla
-- =============================================
create PROCEDURE [dbo].[spSystem_GenerateDatabaseStatusReport]

AS
BEGIN

	SET NOCOUNT ON;

		select name

			  ,(select top 1 row_count from sys.dm_db_partition_stats where object_id=s.object_id)

			  ,modify_date

			  ,(select  convert(decimal(8,2),(SUM (	CASE

			WHEN (index_id < 2) THEN (in_row_data_page_count + lob_used_page_count + row_overflow_used_page_count)

			ELSE lob_used_page_count + row_overflow_used_page_count

			END

			)*0.0078125 ))

		FROM sys.dm_db_partition_stats

		WHERE object_id = s.object_id) as PESO_TABLA

		from sys.tables s

		where type_desc = 'USER_TABLE'

		order by PESO_TABLA desc


END
GO



