					EXEC ('
					UPDATE tbItemTransactions
						SET	it_deliveryCharge = 0
						')

					EXEC ('
					UPDATE tbItemTransactions
						SET	it_deliveryCharge = 1
						FROM tbItemTransactions it
						INNER JOIN tbDeliveryCharges tdc
							ON	tdc.comp_id					 = it.comp_id AND
								tdc.dlc_charge_itemIDFreight = it.item_id
						')

					EXEC ('
