					INSERT INTO tbPurchaseTransport
					(
						comp_id,
						ptr_name,
						ptr_disabled
					)
						SELECT	tc.comp_id,
								''Generic'',
								''FALSE''
							FROM tbCompany tc
							WHERE NOT EXISTS(
												SELECT tpt.comp_id
													FROM tbPurchaseTransport tpt
													WHERE tpt.comp_id = tc.comp_id
											)

						')


					EXEC('
					UPDATE tbsupplier
						SET ptr_id = (	SELECT TOP 1 tpt.ptr_id
											FROM tbPurchaseTransport tpt
						              		WHERE tpt.comp_id = ts.comp_id
									 )
						FROM tbsupplier	ts
						WHERE ts.ptr_id IS NULL
						')


					EXEC('
					UPDATE tbPurchaseOrderHeader
						SET ptr_id = ts.ptr_id
						FROM tbPurchaseOrderHeader tpoh
						INNER JOIN tbSupplier ts
							ON	ts.comp_id = tpoh.comp_id AND
								ts.supp_id = tpoh.supp_id
						WHERE tpoh.ptr_id IS NULL
							')

					UPDATE tbSystem_DatabaseVersion
						SET version			= 1950
					SET @DataBaseVersion	= 1950

					SELECT 'Updated to Version 1950'
				END



