						FROM tbUser tu
						WHERE tu.user_nick	= 'ERPSoporte'

					IF @intUserID IS NOT NULL
						BEGIN

							DBCC CHECKIDENT('tbUser', RESEED, 10001)


							--DECLARE @strExecNew AS VARCHAR(MAX)

							SET @strExecNew = '


								INSERT INTO tbUser
								(
