					INSERT INTO tbMercadoLibre_updateQueue	WITH (ROWLOCK)
						(
							comp_id,
							mlp_id,
							mlproc_option,
							mlproc_integerValue,
							mlproc_isProcessed,
							mlproc_isCancelled,
