								ttn.tax_id,
								NULL,
								1,
								1,
								NULL,
								NULL,
								GETDATE()
							FROM tbTaxName ttn
							INNER JOIN vwsysTaxClassALL_Retentions vtcar
								ON vtcar.tax_class = ttn.tax_class
							INNER JOIN tbsysFiscalClass tfc
								ON tfc.country_id = ttn.country_id
							LEFT JOIN tbTaxByFiscalClass ti
								ON	ti.comp_id	= ttn.comp_id	AND
									ti.tax_id	= ttn.tax_id	AND
									ti.fc_id	= tfc.fc_id		AND
									ti.bra_id IS NULL			AND
									ti.fc_PurchaseOrSale = 1
