					ALTER TABLE dbo.tbItemTaxes ADD
						tax_class int NULL

					EXEC('
					UPDATE tbItemTaxes
						SET tax_class = ttn.tax_class
						FROM tbItemTaxes AS tit
						INNER JOIN tbTaxName AS ttn
							ON	ttn.tax_id	= tit.tax_id AND
								ttn.comp_id = tit.comp_id
						')

					CREATE NONCLUSTERED INDEX IX_tbItemTaxes_2ll ON dbo.tbItemTaxes
						(
						tax_class
						) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]



					EXEC('UPDATE tbItemTaxes SET tax_itemComposed = 0 WHERE tax_itemComposed IS NULL')

					EXEC('
					UPDATE tbItemTaxes
					SET tax_itemComposed = 0
					FROM tbItemTaxes AS tit
					WHERE tit.tax_itemComposed = 1 AND
									NOT EXISTS (
												SELECT 1
													FROM tbItemTaxes AS tit2
													WHERE	tit2.comp_id = tit.comp_id	AND
															tit2.item_id = tit.item_id	AND
															tit2.tax_id  = tit.tax_id	AND
															ISNULL(tit2.bra_id,-1)	= ISNULL(tit.bra_id,-1)	AND
															tit2.tax_itemComposed	= 0
												)
						')


					UPDATE tbSystem_DatabaseVersion
						SET version			= 2327
					SET @DataBaseVersion	= 2327

					SELECT 'Updated to Version 2327'
				END


