				EXEC('
					SET NOCOUNT ON
					DECLARE @strScript4Statistics AS NVARCHAR(MAX) = ''''

					-- ------------------------------------
					-- Genera Script para Borrar Todas las Estadisticas Creadas
					-- ------------------------------------
					;WITH tmpDrop AS (
						SELECT DISTINCT  ''DROP STATISTICS ''
						+ SCHEMA_NAME(ob.Schema_id) + ''.''
						+ OBJECT_NAME(s.object_id) + ''.'' +
						s.name DropStatisticsStatement
						FROM sys.stats s
						INNER JOIN sys.Objects ob ON ob.Object_id = s.object_id
						WHERE SCHEMA_NAME(ob.Schema_id) <> ''sys''
						AND Auto_Created = 0 AND User_Created = 1
									)
					-- ------------------------------------

					SELECT @strScript4Statistics = @strScript4Statistics + tmp.DropStatisticsStatement +  CHAR(13) + CHAR(10)
						FROM tmpDrop tmp

					SELECT @strScript4Statistics
					EXEC(@strScript4Statistics)
				')




					UPDATE tbSystem_DatabaseVersion
						SET version			= 2352
					SET @DataBaseVersion	= 2352

					SELECT 'Updated to Version 2352'
				END

