			-- ---------------------------------------------------------------------------
			-- Reference: otra Vez para que quede bien MOS 03-2022:
			-- Si por migracion tenian en 1 las sucursales molestaba con esto x lo que
			-- puse q solo se activen si tienen alguna sucursal <> 1 ( x defecto )
			-- o si tienen grupos de sucursales asignados.
			-- ---------------------------------------------------------------------------
			IF @DataBaseVersion < 2631
				BEGIN





							IF EXISTS(SELECT TOP 1 1 FROM tbbranch WHERE bra_enableCustomerByBranchSearch = 1)
								BEGIN


									UPDATE tbBranch
										SET  bra_enableCustomerByBranchSearch = 0

									-- INdice Temporal
									CREATE NONCLUSTERED INDEX IX_tbcustomer_TempUpdate ON dbo.tbcustomer
																(
																comp_id,
																bra_id
																)
																WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]

									EXEC('
									UPDATE tbBranch
											SET  bra_enableCustomerByBranchSearch = 1
											FROM tbBranch AS tb	WITH (NOLOCK)
											WHERE EXISTS(SELECT TOP 1  1
															FROM tbcustomer rt	WITH (NOLOCK)
															WHERE	rt.comp_id = tb.comp_id AND
																	(
																		rt.brag_id  IS NOT NULL		-- Si tiene algun Grupo de Sucursales
																			OR
																		(							-- Si tiene mas de 20 clientes que tienen asignadas dos sucursales o mas
																			SELECT COUNT(*)
																				FROM tbBranch AS tb2 	WITH (NOLOCK)
																				WHERE	tb2.comp_id = tb.comp_id AND
																						EXISTS(
																								SELECT TOP 1 1
																									FROM tbCustomer AS tc	WITH (NOLOCK,INDEX(IX_tbcustomer_TempUpdate))
																									WHERE	tc.comp_id  = rt.comp_id	AND
																											tc.comp_id	= tb2.comp_id	AND
																											tc.bra_id	= tb2.bra_id	AND
																											tc.bra_id IS NOT NULL
																								)
																		) >= 2
																	)
																	HAVING COUNT(*) > 20
													)
											')

									DROP INDEX IX_tbcustomer_TempUpdate ON dbo.tbcustomer
								END




					--EXEC('

					--		IF EXISTS(SELECT TOP 1 1 FROM tbbranch WHERE bra_enableCustomerByBranchSearch = 1)
					--			BEGIN


					--				UPDATE tbBranch
					--					SET  bra_enableCustomerByBranchSearch = 0

					--				CREATE NONCLUSTERED INDEX IX_tbcustomer_TempUpdate ON dbo.tbcustomer
					--											(
					--											comp_id,
					--											bra_id
