					SELECT DISTINCT ti.comp_id,ti.pres_id
						FROM tbItem AS ti
						LEFT JOIN tbPresentation AS tp
							ON	tp.comp_id = ti.comp_id AND
								tp.pres_id = ti.pres_id
						WHERE tp.pres_id IS NULL


					--SELECT * FROM @tmpPresentations AS tp

					SET IDENTITY_INSERT tbPresentation ON

					INSERT INTO tbPresentation
					(
						comp_id,
						pres_id,
						pres_desc,
						bra_id
					)

					SELECT	tp.comp_id,
							tp.pres_id,
							CONVERT(VARCHAR(10),tp.pres_id) + ':Bad Imported',
							NULL
