				IF  EXISTS (SELECT * FROM sys.triggers WHERE object_id = OBJECT_ID(N'[dbo].[trItemAfterInsert]'))
					BEGIN
						EXEC sys.sp_settriggerorder trItemAfterInsert, 'First', 'INSERT'
					END

				IF  EXISTS (SELECT * FROM sys.triggers WHERE object_id = OBJECT_ID(N'[dbo].[trItemAfterInsertAndUpdate]'))
					BEGIN
						EXEC sys.sp_settriggerorder trItemAfterInsertAndUpdate, 'Last', 'INSERT'
