DECLARE @intMenuCounter AS INT
SET 	@intMenuCounter = 0
WHILE   @intMenuCounter < 30
BEGIN
	INSERT INTO tbMenuGrants
		(
			comp_id,
			prof_id,
			menu_id
		)
		SELECT DISTINCT		tmg.comp_id,
							tmg.prof_id,
							tm.menu_id_sup
			FROM tbMenuGrants tmg
			INNER JOIN tbsysMenu tm
				ON tm.menu_id = tmg.menu_id
			WHERE NOT EXISTS(
								SELECT TOP 1 1
									FROM tbMenuGrants jjj
									WHERE	jjj.comp_id = tmg.comp_id AND
											jjj.prof_id = tmg.prof_id AND
											jjj.menu_id = tm.menu_id_sup
							)						AND
				  tm.menu_id_sup IS NOT NULL		AND
				  ISNULL(tm.menu_disabled,'False') = 'FALSE'
	SET @intMenuCounter = @intMenuCounter + 1
END


