-- ------------------------------------------------------------------------------------------
-- actualiza perfiles de mail de SMTP
-- ------------------------------------------------------------------------------------------

	DECLARE
		@comp_id_1					INT,
		@smtp_id					INT,
		@smtp_ReplyTo				NVARCHAR(300)


	DECLARE cursor_SMTPConfigurationByReplyTo CURSOR FOR

		SELECT
			tsbrt.comp_id,
			tsbrt.smtp_id,
			tsbrt.smtp_ReplyTo
			FROM tbSMTPConfigurationByReplyTo tsbrt
			WHERE	tsbrt.smtp_profileName IS NOT NULL AND
					tsbrt.smtp_profileName <> ''

		OPEN	cursor_SMTPConfigurationByReplyTo

		FETCH	cursor_SMTPConfigurationByReplyTo
		INTO
			@comp_id_1,
			@smtp_id,
			@smtp_ReplyTo

		WHILE   @@FETCH_STATUS = 0
			BEGIN

				EXEC spSystem_ConfigureSQLEmailByReplyTo @comp_id_1, @smtp_id

				FETCH	cursor_SMTPConfigurationByReplyTo
					INTO
						@comp_id_1,
						@smtp_id,
						@smtp_ReplyTo
			END

		CLOSE		cursor_SMTPConfigurationByReplyTo
		DEALLOCATE	cursor_SMTPConfigurationByReplyTo

