DECLARE
	@tm_trans		INT,
	@ct_trans		INT,
	@it_trans		INT,
	@pcm_id			INT,
	@tm_subtotal	DECIMAL(19,6)

DECLARE cursor_TM_Taxes CURSOR FOR


--Recupero los datos de la tbTaxMovements (solo Purchase)

	SELECT
		ttm.tm_transaction,
		ttm.ct_transaction,
		ttm.it_transaction,
		ttm.tm_subtotal,
		ttm.pcm_id


	FROM tbTaxMovements ttm

		INNER JOIN vwCommercialTransactions_forPurchase vctfp
		ON	vctfp.comp_id			= ttm.comp_id
		AND vctfp.bra_id			= ttm.bra_id
		AND vctfp.ct_transaction	= ttm.ct_transaction

	WHERE	ttm.pcm_id IS NULL
	AND		ttm.it_transaction IS NULL


OPEN cursor_TM_Taxes

FETCH NEXT FROM cursor_TM_Taxes
INTO @tm_trans,
	 @ct_trans,
	 @it_trans,
	 @tm_subtotal,
	 @pcm_id

--  loop por Tax Movements
WHILE @@FETCH_STATUS = 0
BEGIN


	--Pregunto por las dos variables si estan en NULL
	--IF (@pcm_id IS NULL) AND (@it_trans IS NULL)

		--BEGIN
			--Si existe registro en la tbPurchaseConceptMovements y concuerda CT_TRANS y TOTAL "ACTUALIZA POR ACÁ"
			IF EXISTS (SELECT TOP 1 1 FROM tbPurchaseConceptMovements tpcm WHERE tpcm.ct_transaction = @ct_trans)
				BEGIN

					UPDATE tbTaxMovements
					SET
						pcm_id = (SELECT TOP 1 tpcm.pcm_id
						          FROM tbPurchaseConceptMovements tpcm
						          WHERE tpcm.ct_transaction = @ct_trans
								  AND tpcm.pcm_total		= @tm_subtotal
								  AND isnull(tpcm.tmp_fixed,'False') = 'False')

					WHERE	tm_transaction = @tm_trans
					AND		ct_transaction = @ct_trans

					IF @ct_trans = 3230 SELECT @tm_subtotal


					UPDATE tbPurchaseConceptMovements
					SET
						tmp_fixed = 'True'

					WHERE ct_transaction = @ct_trans
					AND   pcm_total		 = @tm_subtotal



					INSERT INTO zTest
					(
						-- id -- this column value is auto-generated,
						dato,
						fecha,
						puntaje,
						valor,
						valorWithDecimal
					)
					VALUES
					(
						'PURCHASE' + ' ' + convert(varchar,@ct_trans),
						GETDATE(),
						0,
						0,
						@tm_subtotal
					)

				END
			ELSE
				--Si existe registro en la tbItemTransactions y concuerda con CT_TRANS y TOTAL "Actualiza por ACÁ"
				IF EXISTS (SELECT TOP 1 1 FROM tbItemTransactions tit WHERE tit.ct_transaction = @ct_trans)
					BEGIN

						UPDATE tbTaxMovements
						SET
							it_transaction = (SELECT tit.it_transaction
							                  FROM tbItemTransactions tit
							                  WHERE tit.ct_transaction = @ct_trans
											  AND (tit.it_qty * tit.it_price) = @tm_subtotal
											  AND isnull(tit.tmp_fixed,'False')= 'False')
						WHERE	tm_transaction = @tm_trans
						AND		ct_transaction = @ct_trans

					UPDATE tbItemTransactions
					SET
						tmp_fixed = 'True'

					WHERE ct_transaction		= @ct_trans
					AND   (it_qty * it_price)	= @tm_subtotal


					INSERT INTO zTest
					(
						-- id -- this column value is auto-generated,
						dato,
						fecha,
						puntaje,
						valor,
						valorWithDecimal
					)
					VALUES
					(
						'ITEM_TRANS' + ' ' + convert(varchar,@ct_trans),
						GETDATE(),
						0,
						0,
						@tm_subtotal
					)


					END

		--END


--Pasa al siguiente registro para evaluar TODOS los Datos
FETCH NEXT FROM cursor_TM_Taxes
	INTO @tm_trans,
		 @ct_trans,
		 @it_trans,
		 @tm_subtotal,
		 @pcm_id



END
CLOSE		cursor_TM_Taxes
DEALLOCATE	cursor_TM_Taxes


