-- ---------------------------------------------------------------------------




CREATE PROCEDURE [dbo].[spSystem_GenerateDatabaseUpdate_70_450]
AS
BEGIN

	SET DATEFORMAT 'ymd'

	DECLARE @strExecute AS VARCHAR(MAX)
	Declare @DataBaseVersion			AS INT
	DECLARE @DatabaseOriginalVersion	AS INT
	SELECT TOP 1 @DataBaseVersion	= IsNull(version,0)
		   FROM tbSystem_DatabaseVersion
	SET @DatabaseOriginalVersion	= @DataBaseVersion

	SELECT '.'
	SELECT '.'

	SELECT 'Database Original Version: ' + Cast(@DataBaseVersion AS VARCHAR)

	If @DataBaseVersion >= 0
	BEGIN

		SELECT 'Poner aca los select viejos'


	END
END
GO


-- =============================================
-- Author:		MOS
-- Create date: 11-2007
-- Description:	Indices para Vistas
-- OJO que si se usan TABLAS tbSYS... en las vistas y estas se referencian con WITH (INDEX_DE_VISTA...) en un SP,
-- la vista debe generarse en el SP [spSystem_GenerateDatabaseUpdateIndex4Views_PreSPActualization] y la VISTA NO
-- puede tener la referencia a la tabla tbSys...
-- =============================================

CREATE PROCEDURE [dbo].[spSystem_GenerateDatabaseUpdateIndex4Views]

AS

BEGIN


SET NOCOUNT on

SET ANSI_NULLS ON


SET QUOTED_IDENTIFIER ON



	-- OK
IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_forSalesII')
	BEGIN
		DROP INDEX CIX_vwCommercialTransactions_forSalesII ON  vwCommercialTransactions_forSales
	END
	CREATE UNIQUE CLUSTERED INDEX CIX_vwCommercialTransactions_forSalesII
		ON vwCommercialTransactions_forSales( comp_id, ct_transaction)


	-- OK
IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_forSalesIII')
	BEGIN
		DROP INDEX CIX_vwCommercialTransactions_forSalesIII ON  vwCommercialTransactions_forSales
	END
	CREATE  INDEX CIX_vwCommercialTransactions_forSalesIII
		ON vwCommercialTransactions_forSales( comp_id, bra_id, ct_transaction)


	-- OK
IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_forSalesIV')
	BEGIN
		DROP INDEX CIX_vwCommercialTransactions_forSalesIV ON  vwCommercialTransactions_forSales
	END
	CREATE  INDEX CIX_vwCommercialTransactions_forSalesIV
		ON vwCommercialTransactions_forSales( ct_transaction)



	-- OK
	IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_forPurchase_TaxEngine')
	BEGIN
		DROP INDEX CIX_vwCommercialTransactions_forPurchase_TaxEngine ON  vwCommercialTransactions_forPurchase_TaxEngine
	END
	CREATE UNIQUE CLUSTERED INDEX CIX_vwCommercialTransactions_forPurchase_TaxEngine
		ON vwCommercialTransactions_forPurchase_TaxEngine( comp_id, ct_transaction)

	-- OK
	IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_forSales_TaxEngine')
	BEGIN
		DROP INDEX CIX_vwCommercialTransactions_forSales_TaxEngine ON  vwCommercialTransactions_forSales_TaxEngine
	END
	CREATE UNIQUE CLUSTERED INDEX CIX_vwCommercialTransactions_forSales_TaxEngine
