-- =============================================
-- Author:		MOS
-- Create date: 11-2007
-- Description:	Indices para Vistas
--
-- I m p o r t a n t e ! ! ! !
--
-- Generar aca las que se usan en clausulas WITH (INDEX()) en SP.
-- El resto van en spSystem_GenerateDatabaseUpdateIndex4Views como siempre que se ejecuta AL FINAL de la actualizacion.
-- Recordemos que al actualizar una vista se borran los indices y hay que regenerarlos.
-- Tener cuidado que estas vistas NO deben contener tablas SYS ya que, de lo contrario, NO se actulizan las SYS porque da error de borrado ya que tienen un indice de vista asociado.!
-- =============================================

CREATE PROCEDURE [dbo].[spSystem_GenerateDatabaseUpdateIndex4Views_PreSPActualization]

AS

BEGIN


	SET NOCOUNT on
	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON



		-- OK
	IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_forSalesII')
		BEGIN
			DROP INDEX CIX_vwCommercialTransactions_forSalesII ON  vwCommercialTransactions_forSales
		END
		CREATE UNIQUE CLUSTERED INDEX CIX_vwCommercialTransactions_forSalesII
			ON vwCommercialTransactions_forSales( comp_id, ct_transaction)




	-- OK  MOS 08-2023
	IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_forPurchase')
	BEGIN
		DROP INDEX CIX_vwCommercialTransactions_forPurchase ON  vwCommercialTransactions_forPurchase
	END
	CREATE UNIQUE CLUSTERED INDEX CIX_vwCommercialTransactions_forPurchase
		ON vwCommercialTransactions_forPurchase( comp_id, ct_transaction)




	-- OK
	IF EXISTS(SELECT * FROM sysindexes AS s WHERE s.name = 'CIX_vwCommercialTransactions_PaymentOnAccount')
	BEGIN
		DROP INDEX CIX_vwCommercialTransactions_PaymentOnAccount ON  vwCommercialTransactions_PaymentOnAccount
	END
	CREATE UNIQUE CLUSTERED INDEX CIX_vwCommercialTransactions_PaymentOnAccount
		ON vwCommercialTransactions_PaymentOnAccount( comp_id, ct_transaction)



END
GO

