-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
Create PROCEDURE [dbo].[spSystem_GenerateDatabaseUpdateTruncateLog]
AS
BEGIN
	SET NOCOUNT ON;


	-- ATENCION
	-- Si se modifica algo hacerlo en :
	-- spSystem_GenerateDatabaseUpdateTruncateLog
	-- [spSystem_GenerateDatabaseBackupTruncateLog



	-- ---------------------------------------------------------
	-- Vaciar el LOG de Transacciones
	-- ---------------------------------------------------------
	--IF DATEPART(hour ,GETDATE()) >= 17 OR DATEPART(hour ,GETDATE()) <= 6
		BEGIN
			DECLARE @strExecute			AS NVARCHAR(1000)
			DECLARE @strDatabaseLogName as nvarchar(300)
			SELECT	@strDatabaseLogName = name
				FROM sys.master_files		WITH (NOLOCK)
				WHERE database_id = db_id()
					AND type = 1

			SET @strExecute = '
								DBCC SHRINKFILE (N''' + @strDatabaseLogName + ''' , 0, TRUNCATEONLY)	  '

			EXEC (@strExecute)
		END
	-- ---------------------------------------------------------


END
GO






CREATE PROCEDURE [dbo].[spSystem_GenerateDBUpdateSpVwFn]

AS
BEGIN

	SET NOCOUNT ON
	-- Borra y Crea Stored Procedures Existentes
	--	SELECT 'IF EXISTS(SELECT ' + '''' + so.[name] + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + so.name + '''' + ')' + ' DROP PROCEDURE ' + SO.[name]
	--		FROM sysobjects SO WHERE xtype = 'P'
	--
	-- Borra y Crea Vistas Existentes
	--	SELECT 'IF EXISTS(SELECT ' + '''' + so.[name] + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + so.name + '''' + ')' + ' DROP VIEW ' + SO.[name]
	--		FROM sysobjects SO WHERE xtype = 'V'
	-- Borra y Crea Funciones Existentes
	--	SELECT 'IF EXISTS(SELECT ' + '''' + so.[name] + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + so.name + '''' + ')' + ' DROP FUNCTION ' + SO.[name]
	--		FROM sysobjects SO WHERE xtype = 'FN'


	-- Generacion de Scripts
	DECLARE @strNAME		AS VARCHAR(MAX)
	DECLARE @strNAMESCHEMA	AS VARCHAR(MAX)

	SELECT '-- ------------------------------------------------------------------------------'
	SELECT '--      GlobalBluePoint ERP - Actualizador de Software de Base de Datos		   --'
	SELECT '-- ------------------------------------------------------------------------------'
	SELECT 'SET NOCOUNT ON'
	SELECT 'GO'


	-- Generacion de Vistas
	DECLARE cursor_S_GDBUSVF  CURSOR LOCAL FAST_FORWARD FOR	SELECT so.[name]
	                                    		FROM sysobjects so
	                                    		WHERE so.xtype = 'V'
	OPEN cursor_S_GDBUSVF

	FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
	WHILE @@FETCH_STATUS >= 0
		BEGIN

			SET @strNAMESCHEMA = @strNAME

			IF @strNAME LIKE '%vwbi_%'
				BEGIN
					SET @strNAMESCHEMA = 'dbi.' + @strNAME
				END


			SELECT 'IF EXISTS(SELECT ' + '''' + @strNAME + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + @strNAME + '''' + ')'
			SELECT '   DROP VIEW ' + @strNAMESCHEMA

			SELECT ''
			SELECT 'SET ANSI_NULLS ON'
			SELECT 'GO'
			SELECT ''
			SELECT 'SET QUOTED_IDENTIFIER ON'
			SELECT 'GO'
			SELECT ''

			SELECT 'EXEC dbo.sp_executesql @statement = N' + ''''
			EXEC spSystem_GenerateDBUpdateSpVwFn_GetSpForExecute @strNAMESCHEMA
			SELECT ''''
			FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
		END

	CLOSE cursor_S_GDBUSVF
	DEALLOCATE  cursor_S_GDBUSVF



	-- ------------------------------------------------------------------------------------------------------------------------------
	-- Generacion de SP spSystem_GenerateDatabaseUpdateIndex4Views para que los indices generados sean los correctos.
	-- Verificar si es que se uso alguna funcion NO CREADA aun en el indice, de ponerla aca en duro generada tal como se esta haciendo con este SP
	-- ------------------------------------------------------------------------------------------------------------------------------
	DECLARE cursor_S_GDBUSVF  CURSOR LOCAL FAST_FORWARD  FOR	SELECT so.[name]
	                                    		FROM sysobjects so
	                                    		WHERE	so.xtype	= 'P'
	                                    			AND SO.[name]	= 'spSystem_GenerateDatabaseUpdateIndex4Views_PreSPActualization'
	OPEN cursor_S_GDBUSVF

	FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
	WHILE @@FETCH_STATUS >= 0
		BEGIN

			SELECT 'IF EXISTS(SELECT ' + '''' + @strNAME + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + @strNAME + '''' + ')'
			SELECT '   DROP PROCEDURE ' + @strNAME

			SELECT ''
			SELECT 'SET ANSI_NULLS ON'
			SELECT 'GO'
			SELECT 'SET QUOTED_IDENTIFIER ON'
			SELECT 'GO'
			SELECT ''

			SELECT 'EXEC dbo.sp_executesql @statement = N' + ''''
			EXEC spSystem_GenerateDBUpdateSpVwFn_GetSpForExecute @strNAME
			SELECT ''''
			FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
		END

	CLOSE cursor_S_GDBUSVF
	DEALLOCATE  cursor_S_GDBUSVF
	-- ------------------------------------------------------------------------------------------------------------------------------

	-- ------------------------------------------------------------------------------------------------------------------------------
	-- INDEXO las Vistas
	-- Se indexan aca ya que, sino, si se usa un indice en un SP con INDEX() y NO esta generado, explota el actualizador
	-- ------------------------------------------------------------------------------------------------------------------------------
	SELECT 'SELECT ''  Re-Generando los Índices de las Vistas ...''    '
	SELECT 'GO'
	SELECT '
		 EXEC spSystem_GenerateDatabaseUpdateIndex4Views_PreSPActualization
			'
	SELECT 'GO'
	SELECT 'SELECT ''    Actualizando Stored Procedures .........''    '
	SELECT 'GO'
	-- ------------------------------------------------------------------------------------------------------------------------------




	DECLARE @schemaDeletePrevious AS NVARCHAR(4000)
	-- Generacion de Funciones
	DECLARE cursor_S_GDBUSVF  CURSOR LOCAL FAST_FORWARD  FOR	SELECT so.[name],ISNULL(sch.schemaDeletePrevious,'')
	                                    		FROM sysobjects so
	                                    		LEFT JOIN tbSystem_GenerateDBUpdateSpVwFn_Order sch
	                                    			ON sch.schemaName = so.[name]
	                                    		WHERE (so.xtype = 'FN' OR so.xtype = 'TF' OR so.xtype = 'FT' /*OR so.xtype = 'FS'*/ OR so.xtype = 'AF' OR so.xtype = 'IF')
	                                    		ORDER BY
	                                    					CASE
	                                    						WHEN sch.schemaorder4GenerationSP IS NOT NULL THEN sch.schemaorder4GenerationSP
	                                    						ELSE 0
	                                    					END,
	                                    					so.[name]

	DECLARE @tmpTable TABLE(schemaDeletePrevious NVARCHAR(200))

	OPEN cursor_S_GDBUSVF

	FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME,@schemaDeletePrevious
	WHILE @@FETCH_STATUS >= 0
		BEGIN

			-- ---------------------------------------------
			-- MOS 2021
			-- Las funciones con SchemaBinding son mas performantes que sin ese tag. pero, si una funcion depende de otra la segunda tambien debe ser con schema y la 1ra NO debe existir para que se pueda escribir la segunda.
			-- por eso en la tabla tbSystem_GenerateDBUpdateSpVwFn_Order se DEBEN definir para el caso en que sea necesario estas relaciones, en las funciones PRIMARIAS o de menor nivel o las llamadas dentro de otras funciones
			-- para que BORREN las funciones padres o DEFINIR un orden de recreacion de funciones ya que, en desarrollo, tal vez se puedan poner los schemabinding pero en los deployments darían error.
			-- EJ: en fnGetCommercialTransactionsDescription se usa PadString.   para que PadString se pueda recrear NO debe existir fnGetCommercialTransactionDescription ya que las DOS tienen WITH SchemaBinding
			IF @schemaDeletePrevious <> ''
				DELETE FROM @tmpTable
				BEGIN
					INSERT INTO @tmpTable(schemaDeletePrevious)
					SELECT items
						FROM dbo.fnSplitTable(@schemaDeletePrevious,';')
					IF @@ROWCOUNT > 0
						BEGIN
							SELECT 'IF EXISTS(SELECT ' + '''' + tmp.schemaDeletePrevious + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + tmp.schemaDeletePrevious + '''' + ') ' +  '   EXEC(''DROP FUNCTION ' + tmp.schemaDeletePrevious + ' '')'
							FROM @tmpTable tmp
						END
				END
			-- ---------------------------------------------



			SELECT 'IF EXISTS(SELECT ' + '''' + @strNAME + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + @strNAME + '''' + ')'
			SELECT '   DROP FUNCTION ' + @strNAME

			SELECT ''
			SELECT 'SET ANSI_NULLS ON'
			SELECT 'GO'
			SELECT 'SET QUOTED_IDENTIFIER ON'
			SELECT 'GO'
			SELECT ''


			SELECT 'EXEC dbo.sp_executesql @statement = N' + ''''
			EXEC spSystem_GenerateDBUpdateSpVwFn_GetSpForExecute @strNAME
			SELECT ''''
			FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME,@schemaDeletePrevious
		END

	CLOSE cursor_S_GDBUSVF
	DEALLOCATE  cursor_S_GDBUSVF


	-- Generacion de SP
	DECLARE cursor_S_GDBUSVF  CURSOR LOCAL FAST_FORWARD  FOR	SELECT so.[name]
	                                    		FROM sysobjects so
	                                    		WHERE	so.xtype	= 'P'
	                                    			AND SO.[name]	<> 'spUser_getNeedAuthorization.UnUsed'
	                                    			AND SO.[name]	<> 'spSystem_GenerateDatabaseUpdate'
	                                    			AND SO.[name]	<> 'spSystem_GenerateDatabaseVersionUpdate'
	                                    			AND SO.[name]	<> 'spSystem_GenerateDatabaseUpdate_70_450'
	                                    			AND SO.[name]	<> 'spSystem_GenerateDatabaseUpdate70_600'
	                                    			AND SO.[name]	<> 'spSystem_GenerateDatabaseUpdate70_1300'
	                                    			AND SO.[name]   NOT LIKE '%sp_USERSP_%'
	OPEN cursor_S_GDBUSVF

	FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
	WHILE @@FETCH_STATUS >= 0
		BEGIN

			SELECT 'IF EXISTS(SELECT ' + '''' + @strNAME + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + @strNAME + '''' + ')'
			SELECT '   DROP PROCEDURE ' + @strNAME

			SELECT ''
			SELECT 'SET ANSI_NULLS ON'
			SELECT 'GO'
			SELECT 'SET QUOTED_IDENTIFIER ON'
			SELECT 'GO'
			SELECT ''

			SELECT 'EXEC dbo.sp_executesql @statement = N' + ''''
			EXEC spSystem_GenerateDBUpdateSpVwFn_GetSpForExecute @strNAME
			SELECT ''''
			FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
		END

	CLOSE cursor_S_GDBUSVF
	DEALLOCATE  cursor_S_GDBUSVF



	-- Generacion de TR
	DECLARE cursor_S_GDBUSVF  CURSOR LOCAL FAST_FORWARD  FOR	SELECT so.[name]
	                                    		FROM sysobjects so
	             		WHERE so.xtype = 'TR'
	OPEN cursor_S_GDBUSVF

	FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
	WHILE @@FETCH_STATUS >= 0
		BEGIN

			SELECT 'IF EXISTS(SELECT ' + '''' + @strNAME + '''' + ' FROM sysobjects ESO WHERE ESO.name = ' + '''' + @strNAME + '''' + ')' + ' DROP TRIGGER ' + @strNAME


			SELECT ''
			SELECT 'SET ANSI_NULLS ON'
			SELECT 'GO'
			SELECT 'SET QUOTED_IDENTIFIER ON'
			SELECT 'GO'
			SELECT ''


			SELECT 'EXEC dbo.sp_executesql @statement = N' + ''''
			EXEC spSystem_GenerateDBUpdateSpVwFn_GetSpForExecute @strNAME
			SELECT ''''
			FETCH NEXT FROM cursor_S_GDBUSVF INTO @strNAME
		END

	CLOSE cursor_S_GDBUSVF
	DEALLOCATE  cursor_S_GDBUSVF


	-- Genera Actualizacion de Version de compilacion y actualiza historicos de compilaciones.-
	DECLARE @intVersionOfGeneration AS integer
	UPDATE tbSystem_DatabaseVersion
	SET
		versionOfGeneration = versionOfGeneration + 1 ,
		actualizationDate = GETDATE()

	SELECT @intVersionOfGeneration = tsdv.versionOfGeneration
		FROM tbSystem_DatabaseVersion tsdv

	INSERT INTO tbSystem_CompilationHistory
	(
		DatabaseVersion,
		GenerationVersion
	)
	(
		SELECT tsdv.version,tsdv.versionOfGeneration
		  FROM tbSystem_DatabaseVersion tsdv
	)

	SELECT 'Select ''Updating Generation Version'''

	SELECT '
	UPDATE tbSystem_DatabaseVersion
	SET
		versionOfGeneration = ' + convert( VARCHAR ,@intVersionOfGeneration) + ',
		actualizationDate   = GETDATE()
			'

END




