-- Se usa para que cada vez que se genera una
-- actualizacion, previamente se ejecute
-- este SP.
-- Ejemplo: Cargar algo en alguna sys, etc.-
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GeneratePreSetup]

AS
BEGIN

	SET NOCOUNT ON;

	SELECT 'GBP- PreSetup Realizado.'

	exec sp_configure 'show advanced options', 1
	RECONFIGURE;
	exec sp_configure 'Ole Automation Procedures', 1
	RECONFIGURE;


	-- Rehaciendo tablas de Menu Nuevas
	EXEC [spSystem_GeneratePreSetupTablesFromViews]

END
GO





-- =============================================
-- Author:		MOS
-- Recalcula estas tablas para que el menu
-- se cargue mas rapido y no tarde
-- mil años
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GeneratePreSetupTablesFromViews]

AS
BEGIN

	SET NOCOUNT ON;

	TRUNCATE TABLE tbSysParametersTypeLangValuesClearFromView
	TRUNCATE TABLE tbsysMenuParametersFromView

	INSERT INTO tbSysParametersTypeLangValuesClearFromView ([type_id],
															id,
															lang_id,
															[desc])
		SELECT tmp.[type_id], tmp.id, tmp.lang_id, tmp.[desc]
		  FROM  vwSysParametersTypeLangValuesClear tmp

	INSERT INTO tbsysMenuParametersFromView (menu_id, parameters)
		SELECT tmp.menu_id, tmp.parameters
			FROM vwMenuParameters tmp

END
GO





