		END
--
	--IF EXISTS ( SELECT  *
	--			FROM    sys.objects
	--			WHERE   object_id = OBJECT_ID(N'spUser_getLoginFailCheck')
	--					AND type IN ( N'P', N'PC' ) )
	--	BEGIN
	--		DROP PROCEDURE spUser_getLoginFailCheck
	--	END
--
	IF EXISTS ( SELECT  *
					FROM    sys.objects
					WHERE   object_id = OBJECT_ID(N'spUser_getLogin')
							AND type IN ( N'P', N'PC' ) )
			BEGIN
				DROP PROCEDURE spUser_getLogin
