					FROM    sys.objects
					WHERE   object_id = OBJECT_ID(N'spIsEditingPurgeStatus')
							AND type IN ( N'P', N'PC' ) )
			BEGIN
				DROP PROCEDURE spIsEditingPurgeStatus
			END
