-- =============================================
-- Author:		MOS
-- Create date: 05-2024
-- Se debe EJECUTAR lo que está entre BEGIN-END
-- reemplazando: dbOriginalDatabaseName y tbOriginalTableName
-- y luego generando a mano los INDICES correspondientes a la tabla de Destino
-- ATENCION
--			Usar esto para las tablas sysTaxAFIP, etc. o para FINALES del arbol de tablas que NO tengan dependencias.
--          Por ejemplo, tbDigitalizations
-- Esto se usa para liberar lugar de BD y que NO se tengan que pasar a SQL Full por estar
-- digitalizando o teniendo impuestos de gusto ocupando lugar.
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GenerateSynonymOfTableinOtherDatabase]
	@OriginalDatabaseName	NVARCHAR(128),
	@TableName				NVARCHAR(128)
AS
BEGIN

	--RETURN

	SET NOCOUNT ON;

	-- Variables de USO
	--DECLARE @OriginalDatabaseName	NVARCHAR(128) = 'dbOriginalDatabaseName';  -- Nombre de la base de datos original
	--DECLARE @TableName				NVARCHAR(128) = 'tbOriginalTableName';    -- Nombre de la tabla
	DECLARE @NewDatabaseName		NVARCHAR(128);
	DECLARE @SelectIntoScript		NVARCHAR(MAX);
	DECLARE @DropTableScript		NVARCHAR(MAX);
	DECLARE @CreateSynonymScript	NVARCHAR(MAX);
	DECLARE @CreateDatabaseScript	NVARCHAR(MAX);

	-- Generar el nombre de la nueva base de datos
	SET @NewDatabaseName = @OriginalDatabaseName + '_addTables';

	-- Paso 1: Crear la nueva base de datos si no existe
	IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = @NewDatabaseName)
	BEGIN
		SET @CreateDatabaseScript = 'CREATE DATABASE ' + QUOTENAME(@NewDatabaseName);
		EXEC sp_executesql @CreateDatabaseScript;
	END

	-- Paso 2: Generar el script SELECT INTO para copiar la tabla y los datos
	SET @SelectIntoScript = 'SELECT * INTO ' + QUOTENAME(@NewDatabaseName) + '.dbo.' + QUOTENAME(@TableName) +
							' FROM ' + QUOTENAME(@OriginalDatabaseName) + '.dbo.' + QUOTENAME(@TableName) + ';';

	-- Imprimir el script para depuración
	PRINT @SelectIntoScript;

	-- Ejecutar el script para copiar la tabla y los datos
	EXEC sp_executesql @SelectIntoScript;

	-- Paso 3: Eliminar la tabla original de la base de datos origen
	SET @DropTableScript = 'DROP TABLE ' + QUOTENAME(@OriginalDatabaseName) + '.dbo.' + QUOTENAME(@TableName) + ';';

	-- Ejecutar el script para eliminar la tabla original
	EXEC sp_executesql @DropTableScript;


	-- estanso parado SOBRE la base de ORIGEN
	-- Crear un sinónimo en la base de datos origen que apunte a la nueva tabla en la base de datos destino
	SET @CreateSynonymScript = 'CREATE SYNONYM dbo.' + QUOTENAME(@TableName) +
							   ' FOR ' + QUOTENAME(@NewDatabaseName) + '.dbo.' + QUOTENAME(@TableName) + ';';

	-- Ejecutar el script para crear el sinónimo
	EXEC sp_executesql @CreateSynonymScript;

	PRINT 'Proceso completado exitosamente.';


END














