-- =============================================
-- Author:		MOS
-- Create date: 07-2019
-- Debe tener acceso FULL en la carpeta de destino.
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GenerateSystemDatabaseBackup]

AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @name VARCHAR(50) -- database name
	DECLARE @path VARCHAR(256) -- path for backup files
	DECLARE @fileName VARCHAR(256) -- filename for backup
	DECLARE @instanceName NVARCHAR(50) -- used for file name

	-- specify database backup directory
	SET @path = 'C:\GlobalBluePoint.Backup\'

	-- specify filename format
	SET  @instanceName = CONVERT(NVARCHAR(50),SERVERPROPERTY ('InstanceName'))

	DECLARE db_cursor CURSOR READ_ONLY FOR
	SELECT name
	FROM master.sys.databases
	WHERE name  IN ('master','model','msdb')  -- exclude these databases
	AND state = 0 -- database is online
	AND is_in_standby = 0 -- database is not read only for log shipping

	OPEN db_cursor
	FETCH NEXT FROM db_cursor INTO @name

	WHILE @@FETCH_STATUS = 0
	BEGIN


	   SET @fileName = @path + @instanceName + '_' + @name + '.BAK'
		SELECT @fileName

	   BACKUP DATABASE @name TO DISK = @fileName   WITH FORMAT

	   FETCH NEXT FROM db_cursor INTO @name
	END


	CLOSE db_cursor
	DEALLOCATE db_cursor
END
GO





