CREATE PROCEDURE [dbo].[spSystem_GenerateSystemTables1]
	-- Add the parameters for the stored procedure here
--	@strDataBaseName	as VarChar(200)
AS


BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	--	Select 'USE ' + @strDataBaseName

	SELECT 'SET NOCOUNT ON'
	SELECT 'GO'

	SELECT 'IF EXISTS (SELECT * FROM sysobjects WHERE xtype = ''U'' AND NAME =''' + (TABLE_NAME) + ''')'    + ' ALTER TABLE ' + QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME) + ' NOCHECK CONSTRAINT ALL;'
	FROM INFORMATION_SCHEMA.TABLES
	WHERE
	OBJECTPROPERTY(OBJECT_ID(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)), 'IsMSShipped') = 0
	AND TABLE_TYPE = 'BASE TABLE'

SELECT '-- Insertando Datos en tablas SYS --'
	SELECT 'SET NOCOUNT ON'
	SELECT 'GO'
