-- =============================================
-- Author:		MOS
-- Create date: 11-2008
-- Description:	Insert de datos para Tablas de
--              una Nueva Base de Datos
-- =============================================

CREATE PROCEDURE [dbo].[spSystem_GenerateSystemTables2]
	-- Add the parameters for the stored procedure here
--	@strDataBaseName	as VarChar(200)
AS


BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	--	Select 'USE ' + @strDataBaseName
	SELECT 'SET NOCOUNT ON'
	SELECT 'GO'
	SELECT 'IF EXISTS (SELECT * FROM sysobjects WHERE xtype = ''U'' AND NAME =''' + (TABLE_NAME) + ''')'    + ' ALTER TABLE ' + QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME) + ' NOCHECK CONSTRAINT ALL;'
	FROM INFORMATION_SCHEMA.TABLES
	WHERE
	OBJECTPROPERTY(OBJECT_ID(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)), 'IsMSShipped') = 0
	AND TABLE_TYPE = 'BASE TABLE'

SELECT '-- Insertando Datos en tablas SYS (2) --'
	SELECT 'SET NOCOUNT ON'
	SELECT 'GO'
/**************************************************************************************************/

-- ------------------------------------------------------------------------------------------------
-- Con este Script puedo generar las lineas siguientes de EXEC para todas las tablas sys
-- por si en algun momento hace falta generar nuevamente los mismos.
-- ------------------------------------------------------------------------------------------------
--SELECT  'EXEC dbo.sp_generate_inserts ''' +  name  + ''',@include_column_list=1,@ommit_images=1,@disable_constraints=0,@ommit_computed_cols=1,@deleteData=1'
--	FROM sysobjects
--	WHERE	xtype = 'U'
--		AND [name] LIKE '%tbsys%'
--		AND NAME <> 'tbsysTaxAFIP'
--		AND NAME <> 'tbsysTaxARBA'
--		AND NAME <> 'tbsysTaxAFIPTmp'
--		AND NAME <> 'tbsysExceptionLog'
--      AND NAME <> 'tbSystem_DatabaseVersion'
--		AND  ([name] NOT LIKE '%tbsysPru%')
--	ORDER BY name
-- ------------------------------------------------------------------------------------------------
--

-- Genera los 3 SP de actualizacion de las sys
SET NOCOUNT ON

DECLARE @tmpTable AS TABLE(Id INT IDENTITY (1,1) PRIMARY KEY CLUSTERED,exectext VARCHAR(8000))
DECLARE @strCreateSP AS VARCHAR(8000)

if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateSystemTables2_Execs1') DROP PROCEDURE spSystem_GenerateSystemTables2_Execs1
if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateSystemTables2_Execs2') DROP PROCEDURE spSystem_GenerateSystemTables2_Execs2
if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateSystemTables2_Execs3') DROP PROCEDURE spSystem_GenerateSystemTables2_Execs3
if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateSystemTables2_Execs4') DROP PROCEDURE spSystem_GenerateSystemTables2_Execs4
if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateSystemTables2_Execs5') DROP PROCEDURE spSystem_GenerateSystemTables2_Execs5


INSERT INTO @tmpTable (exectext)

SELECT  'EXEC dbo.sp_generate_inserts ''' +  name  + ''',@include_column_list=1,@ommit_images=1,@disable_constraints=0,@ommit_computed_cols=1,@deleteData=1'  [exectext]
	FROM sysobjects
	WHERE	xtype = 'U'
		AND
		(		NAME = 'tbSysWordsNew'
		--	OR	NAME = 'tbsysOptionsValues'
		)


/*
        AND CHARINDEX('new',NAME)		= 0
        AND NAME <> 'tbSysWordsIni'
*/
		AND  ([name] NOT LIKE '%tbsysPru%')

	ORDER BY name

 -----------

SET @strCreateSP = N'Create Procedure dbo.spSystem_GenerateSystemTables2_Execs1
As
Begin
	Select ''''
	'

SELECT @strCreateSP = COALESCE(@strCreateSP + CHAR(13) + CHAR(10), '' ) + tmt.exectext
	FROM	@tmpTable tmt
	WHERE	tmt.Id <= 30

SET @strCreateSP = @strCreateSP + '
End'

EXEC (@strCreateSP)

SET @strCreateSP = N'Create Procedure dbo.spSystem_GenerateSystemTables2_Execs2
As
Begin
	'

SELECT @strCreateSP = COALESCE(@strCreateSP + CHAR(13) + CHAR(10), '' ) + tmt.exectext
	FROM	@tmpTable tmt
	WHERE	tmt.Id > 30 and tmt.Id <= 60

SET @strCreateSP = @strCreateSP + '
End'

--EXEC (@strCreateSP)


SET @strCreateSP = N'Create Procedure dbo.spSystem_GenerateSystemTables2_Execs3
As
Begin
	Select ''''
	'

SELECT @strCreateSP = COALESCE(@strCreateSP + CHAR(13) + CHAR(10), '' ) + tmt.exectext
	FROM	@tmpTable tmt
	WHERE	tmt.Id > 60 and tmt.Id <= 90

SET @strCreateSP = @strCreateSP + '
End'

--EXEC (@strCreateSP)



SET @strCreateSP = N'Create Procedure dbo.spSystem_GenerateSystemTables2_Execs4
As
Begin
	Select ''''
	'

SELECT @strCreateSP = COALESCE(@strCreateSP + CHAR(13) + CHAR(10), '' ) + tmt.exectext
	FROM	@tmpTable tmt
	WHERE	tmt.Id > 90 and tmt.Id <= 120

SET @strCreateSP = @strCreateSP + '
End'

--EXEC (@strCreateSP)


SET @strCreateSP = N'Create Procedure dbo.spSystem_GenerateSystemTables2_Execs5
As
Begin
	Select ''''
	'

SELECT @strCreateSP = COALESCE(@strCreateSP + CHAR(13) + CHAR(10), '' ) + tmt.exectext
	FROM	@tmpTable tmt
	WHERE	tmt.Id > 120 and tmt.Id <= 150

