-- ===========================================================
-- Author:		MOS
-- Create date: 11-2010
-- Description:	Generacion de Scripts para NUEVO WEBSITE!!!
-- ===========================================================

CREATE PROCEDURE [dbo].[spSystem_GenerateWebSiteByIDTables]
(
	@ws_id				INT
)
	-- Add the parameters for the stored procedure here
	-- @strDataBaseName	as VarChar(200)
AS

BEGIN

/*
DECLARE @ws_id INT
SET		@ws_id = 9
*/

SET NOCOUNT ON;



	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- quitando todas las constraints de la base
	SELECT 'IF EXISTS (SELECT * FROM sysobjects WHERE xtype = ''U'' AND NAME =''' + (TABLE_NAME) + ''')'    + ' ALTER TABLE ' + QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME) + ' NOCHECK CONSTRAINT ALL;'
	FROM INFORMATION_SCHEMA.TABLES
	WHERE
	OBJECTPROPERTY(OBJECT_ID(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)), 'IsMSShipped') = 0
	AND TABLE_TYPE = 'BASE TABLE'
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------




	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- generando todas las tablas de resguardo y cargándolas con los datos del website recibido por parámetro
	DECLARE @name VARCHAR(200)

	DECLARE cursor_website_tables CURSOR FOR
	SELECT	[name]
	FROM	sysobjects
	WHERE	xtype = 'U'
	AND		[name] LIKE 'tbWebSite%'

	OPEN  cursor_website_tables
	FETCH cursor_website_tables INTO @name

	WHILE @@FETCH_STATUS = 0
	BEGIN

		-- se elimina la tabla de resguardo
		EXEC 	('IF EXISTS (SELECT 1 FROM sysobjects s WHERE s.xtype = ''U'' AND s.[name] = ''tmp' + @name + ''') drop table tmp' + @name)


		-- generar y cargar las tablas de resguardo con todos
		BEGIN TRY
			EXEC 	('SELECT * INTO tmp' + @name + ' FROM ' + @name + ' where ws_id = ' + @ws_id)
		END TRY
		BEGIN CATCH
			EXEC 	('SELECT * INTO tmp' + @name + ' FROM ' + @name)
		END CATCH


		FETCH cursor_website_tables INTO @name
	END

	CLOSE cursor_website_tables
	DEALLOCATE cursor_website_tables
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------






	SELECT '-- Insertando Datos en tablas tbWebSite* --'



	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- Genera SP de actualizacion de las sys
	SET NOCOUNT ON

	DECLARE @tmpTable AS TABLE(Id INT IDENTITY (1,1) PRIMARY KEY CLUSTERED,exectext VARCHAR(8000))
	DECLARE @strCreateSP AS VARCHAR(8000)

	if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateWebSiteTables_FromID1') DROP PROCEDURE spSystem_GenerateWebSiteTables_FromID1
	if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateWebSiteTables_FromID2') DROP PROCEDURE spSystem_GenerateWebSiteTables_FromID2
	if exists (SELECT * FROM sysobjects s WHERE s.[name] = 'spSystem_GenerateWebSiteTables_FromID3') DROP PROCEDURE spSystem_GenerateWebSiteTables_FromID3


	INSERT INTO @tmpTable (exectext)

	SELECT  'EXEC dbo.sp_generate_inserts ''' +  name  + ''',@include_column_list=1,@ommit_images=1,@disable_constraints=0,@ommit_computed_cols=1,@deleteData=1'  [exectext]
		FROM sysobjects
		WHERE	xtype = 'U'
			AND [name] LIKE 'tmptbWebSite%'
			--AND NAME <> 'tbWebSitePrueba'

		ORDER BY name
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------





	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- creando sp que genera el script de actualización
	SET @strCreateSP = N'Create Procedure dbo.spSystem_GenerateWebSiteTables_FromID1
	As
	Begin
		'

	SELECT @strCreateSP = COALESCE(@strCreateSP + CHAR(13) + CHAR(10), '' ) + tmt.exectext
		FROM	@tmpTable tmt
		WHERE	tmt.Id <= 50

	SET @strCreateSP = @strCreateSP + '
	End'

	EXEC (@strCreateSP)
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------




	EXEC spSystem_GenerateWebSiteTables_FromID1
	--EXEC spSystem_GenerateWebSiteTables_FromID2
	--EXEC spSystem_GenerateWebSiteTables_FromID3





	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--eliminación de las tablas de resguardo generadas al comienzo del script
	DECLARE cursor_backup_tables CURSOR FOR
	SELECT	[name]
	FROM	sysobjects
	WHERE	xtype = 'U'
	AND		[name] LIKE 'tmptbWebSite%'

	OPEN  cursor_backup_tables

	FETCH cursor_backup_tables INTO @name

	WHILE @@FETCH_STATUS = 0
	BEGIN

		-- se elimina la tabla de resguardo
		EXEC 	('IF EXISTS (SELECT 1 FROM sysobjects s WHERE s.xtype = ''U'' AND s.[name] = ''' + @name + ''') drop table ' + @name)

		FETCH cursor_backup_tables INTO @name

	END

	CLOSE cursor_backup_tables
	DEALLOCATE cursor_backup_tables
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------





	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- restaurando las constraints de la base
	SELECT 'IF EXISTS (SELECT * FROM sysobjects WHERE xtype = ''U'' AND NAME =''' + (TABLE_NAME) + ''')'    + ' ALTER TABLE ' + QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME) + ' CHECK CONSTRAINT ALL;'
	FROM INFORMATION_SCHEMA.TABLES
	WHERE
	OBJECTPROPERTY(OBJECT_ID(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)), 'IsMSShipped') = 0
	AND TABLE_TYPE = 'BASE TABLE'
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


END
GO





