CREATE PROCEDURE [dbo].[spSystem_GetCustomerEmails]

AS
BEGIN

	SET NOCOUNT ON;

	SELECT lower(tc.cust_email)
		FROM tbCustomer tc
	WHERE	tc.cust_email LIKE '%@%' AND
			tc.cust_email LIKE '%.%' AND
			tc.cust_email not LIKE '%.gob%' AND
			tc.cust_email not LIKE '%.gov%' AND
			tc.cust_email not LIKE '%.edu%'

	UNION

	SELECT lower(tc.supp_email)
		FROM tbSupplier tc
		WHERE	tc.supp_email LIKE '%@%' AND
				tc.supp_email LIKE '%.%' AND
				tc.supp_email not LIKE '%.gob%' AND
				tc.supp_email not LIKE '%.gov%' AND
				tc.supp_email not LIKE '%.edu%'


END
GO


