-- Author:		MOS
-- Create date: 10-2010
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_GetTableSize]

AS
BEGIN

	SET NOCOUNT ON;

	SELECT
		t.NAME AS TableName,
		s.Name AS SchemaName,
		p.rows AS RowCounts,
		SUM(a.total_pages) * 8 AS TotalSpaceKB,
		SUM(a.used_pages) * 8 AS UsedSpaceKB,
		(SUM(a.total_pages) - SUM(a.used_pages)) * 8 AS UnusedSpaceKB
	FROM
		sys.tables t
	INNER JOIN
		sys.indexes i ON t.OBJECT_ID = i.object_id
	INNER JOIN
		sys.partitions p ON i.object_id = p.OBJECT_ID AND i.index_id = p.index_id
	INNER JOIN
		sys.allocation_units a ON p.partition_id = a.container_id
	LEFT OUTER JOIN
		sys.schemas s ON t.schema_id = s.schema_id
	WHERE
		t.NAME NOT LIKE 'dt%'
		AND t.is_ms_shipped = 0
		AND i.OBJECT_ID > 255
		--AND isnull(i.[name], 'Heap') = 'Heap'
	GROUP BY
		t.Name, s.Name, p.Rows
	ORDER BY
		SUM(a.total_pages) * 8 DESC

END
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE  PROCEDURE [dbo].[spSystem_getTempDBQueryUse]
	-- Add the parameters for the stored procedure here

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;



	SELECT SUM(unallocated_extent_page_count) AS [free pages],
	(SUM(unallocated_extent_page_count)*1.0/128) AS [free space in MB]
	FROM sys.dm_db_file_space_usage;




	SELECT tb.name AS [Temporary table name],
	stt.row_count AS [Number of rows],
	stt.used_page_count * 8 AS [Used space (KB)],
	stt.reserved_page_count * 8 AS [Reserved space (KB)] FROM tempdb.sys.partitions AS prt
	INNER JOIN tempdb.sys.dm_db_partition_stats AS stt
	ON prt.partition_id = stt.partition_id
	AND prt.partition_number = stt.partition_number
	INNER JOIN tempdb.sys.tables AS tb
	ON stt.object_id = tb.object_id
ORDER BY tb.name




-- ---------------------------------------------------------------


SELECT
  (SUM(unallocated_extent_page_count)/128) AS [Free space (MB)],
  SUM(internal_object_reserved_page_count)*8 AS [Internal objects (KB)],
  SUM(user_object_reserved_page_count)*8 AS [User objects (KB)],
  SUM(version_store_reserved_page_count)*8 AS [Version store (KB)]
  FROM sys.dm_db_file_space_usage
  --database_id '2' represents tempdb
  WHERE database_id = 2




	SELECT (SUM(unallocated_extent_page_count)*1.0/128) AS TempDB_FreeSpaceAmount_InMB
	FROM sys.dm_db_file_space_usage;

	SELECT (SUM(version_store_reserved_page_count)*1.0/128) AS TempDB_VersionStoreSpaceAmount_InMB
	FROM sys.dm_db_file_space_usage;

	SELECT (SUM(internal_object_reserved_page_count)*1.0/128) AS TempDB_InternalObjSpaceAmount_InMB
	FROM sys.dm_db_file_space_usage;

	SELECT (SUM(user_object_reserved_page_count)*1.0/128) AS TempDB_UserObjSpaceAmount_InMB
	FROM sys.dm_db_file_space_usage;





	SELECT

	st.dbid AS QueryExecutionContextDBID,

	DB_NAME(st.dbid) AS QueryExecContextDBNAME,

	st.objectid AS ModuleObjectId,

	SUBSTRING(st.TEXT,

	dmv_er.statement_start_offset/2 + 1,

	(CASE WHEN dmv_er.statement_end_offset = -1

	THEN LEN(CONVERT(NVARCHAR(MAX),st.TEXT)) * 2

	ELSE dmv_er.statement_end_offset

	END - dmv_er.statement_start_offset)/2) AS Query_Text,

	dmv_tsu.session_id ,

	dmv_tsu.request_id,

	dmv_tsu.exec_context_id,

	(dmv_tsu.user_objects_alloc_page_count - dmv_tsu.user_objects_dealloc_page_count) AS OutStanding_user_objects_page_counts,

	(dmv_tsu.internal_objects_alloc_page_count - dmv_tsu.internal_objects_dealloc_page_count) AS OutStanding_internal_objects_page_counts,

	dmv_er.start_time,

	dmv_er.command,

	dmv_er.open_transaction_count,

	dmv_er.percent_complete,

	dmv_er.estimated_completion_time,

	dmv_er.cpu_time,

	dmv_er.total_elapsed_time,

	dmv_er.reads,dmv_er.writes,

	dmv_er.logical_reads,

	dmv_er.granted_query_memory,

	dmv_es.HOST_NAME,

	dmv_es.login_name,

	dmv_es.program_name

	FROM sys.dm_db_task_space_usage dmv_tsu

	INNER JOIN sys.dm_exec_requests dmv_er

	ON (dmv_tsu.session_id = dmv_er.session_id AND dmv_tsu.request_id = dmv_er.request_id)

	INNER JOIN sys.dm_exec_sessions dmv_es

	ON (dmv_tsu.session_id = dmv_es.session_id)

	CROSS APPLY sys.dm_exec_sql_text(dmv_er.sql_handle) st

		WHERE (dmv_tsu.internal_objects_alloc_page_count + dmv_tsu.user_objects_alloc_page_count) > 0

		ORDER BY (dmv_tsu.user_objects_alloc_page_count - dmv_tsu.user_objects_dealloc_page_count) + (dmv_tsu.internal_objects_alloc_page_count - dmv_tsu.internal_objects_dealloc_page_count) DESC












END
GO




-- =============================================
-- Author:		MOS
-- Create date: 10-2020
-- =============================================
create PROCEDURE [dbo].[spSystem_GetTopResourceConsumingDatabases]

AS
BEGIN

	SET NOCOUNT ON;

	-- Comprobar el consumo reciente de CPU en SQL Server
	-- Válido para SQL Server 2008, SQL Server 2005, SQL Server 2000
	--
	--
	-- Notas:
	--  1) Debe especificarse el valor deseado para la variable @count
	--     el cual indica el número de muestras que desean tomarse de sysprocesses.
	--
	--  2) Debe especificarse el valor deseado para la variable @delay,
	--     el cual indica el tiempo a esperar entre cada muestra de sysprocesses,
	--     debiendo ser un valor múltiplo de un segundo.
	--
	-- GuilleSQL - Un portal sobre Microsoft SQL Server en Castellano
	-- http://www.guillesql.es
	--

	declare @delay as datetime
	declare @count as int

	set @delay='00:00:02'
	set @count=120


	-- ******************************************************************************
	-- ***  Obtener la información de sysprocesses, a través de varias muestras,  ***
	-- ***  para poder estimar el reparto del consumo de CPU reciente             ***
	-- ******************************************************************************

	-- ***  Si existe la tabla temporal => La eliminamos, para luego poder crearla con SELECT INTO  ***
	if object_id('tempdb..#tmp_sysprocesses') is not null
	   drop table #tmp_sysprocesses


	-- ***  Creamos la tabla temporal, con una primera muestra de la info de sysprocesses  ***
	select spid, sid, loginame, login_time, dbid, hostname, program_name, hostprocess, cmd, cpu, physical_io, getdate() as actual_date
	INTO #tmp_sysprocesses
	from  sysprocesses

	-- ***  Iteramos el número de veces solicitadas. Para cada iteración:         ***
	-- ***     - Esperamos la franja de tiempo solicitada                         ***
	-- ***     - Almacenamos en la tabla temporal, otra muestra de sysprocesses   ***
	while (@count>0)
	begin

	   WAITFOR DELAY @delay

	   insert INTO #tmp_sysprocesses
	   select spid, sid, loginame, login_time, dbid, hostname, program_name, hostprocess, cmd, cpu, physical_io, getdate() as actual_date
	   from  sysprocesses

	   set @count = @count-1
	end


	-- ****************************************************************************
	-- ***  Mostrar la info de las conexiones, con el consumo de CPU realizado  ***
	-- ****************************************************************************
	select spid, loginame, DB_NAME(dbid) dbname, login_time, hostname, program_name, hostprocess, max(cpu)-min(cpu) cpu, max(physical_io)-min(physical_io) physical_io, count(*) veces
	from  #tmp_sysprocesses
	group by spid, sid, loginame, login_time, dbid, hostname, program_name, hostprocess
	having max(cpu)-min(cpu)>0
	order by max(cpu)-min(cpu) desc, max(physical_io)-min(physical_io) desc


	-- **************************************************************************************
	-- ***  Mostrar el consumo de CPU por cada BBDD, para ayudar a localizar el problema  ***
	-- **************************************************************************************
	SELECT dbname, sum(cpu) as cpu
	from
	(
	select spid, loginame, DB_NAME(dbid) dbname, login_time, max(cpu)-min(cpu) cpu, max(physical_io)-min(physical_io) physical_io, count(*) veces
	from  #tmp_sysprocesses
	group by spid, sid, loginame, login_time, dbid, hostname, program_name, hostprocess
	having max(cpu)-min(cpu)>0
	) DRV_TBL
	group by dbname
	order by cpu desc


	-- select * from #tmp_sysprocesses where spid=208


END
GO




