CREATE PROCEDURE [dbo].[spSystem_GetTopTimeConsumingQueryes]

AS
BEGIN

	SET NOCOUNT ON;

	SELECT total_worker_time, execution_count, last_worker_time, dest.TEXT,last_execution_time,last_logical_writes,last_logical_reads,max_logical_writes,max_logical_reads,min_logical_writes,min_logical_reads,last_elapsed_time,min_elapsed_time,max_elapsed_time
		FROM sys.dm_exec_query_stats AS deqs
		CROSS APPLY sys.dm_exec_sql_text(deqs.sql_handle) AS dest
		ORDER BY total_worker_time DESC;


	-- Todos
	-- SELECT *
	--	FROM sys.dm_exec_query_stats
	--		order by total_worker_time DESC;


END
GO



