-- -------------------------------------------------------
-- Verifica si un ID ya se ejecuto hace x minutos
-- -------------------------------------------------------
-- ID:
--	10901: Recalculo de stock Potencial
--  10958: Recalculo Items de Sitios Web
-- -------------------------------------------------------


CREATE PROCEDURE [dbo].[spSystem_LastExecutionControl_CanDoIt]
(
	@comp_id				as int,
	@bra_id					as int,
	@intID					as int,
	@intMinutes				AS INT,
	@bitCanExecute			as bit output
)
as

BEGIN


	SET @bitCanExecute = 'False'

	-- Si no existe lo crea y retorna TRUE
	IF NOT EXISTS(
					SELECT TOP 1  1
						FROM tbSystem_LastExecutionControl lec WITH (NOLOCK)
						WHERE	lec.comp_id = @comp_id	AND
								lec.bra_id	= @bra_id	AND
								lec.id		= @intID
					)
		BEGIN
			SELECT @bitCanExecute = 'True'
			INSERT INTO tbSystem_LastExecutionControl   WITH (ROWLOCK)
				VALUES (@comp_id,@bra_id,@intID,GETDATE())
			RETURN
		END

	-- Si existe y paso el tiempo, retorna TRUE y actualiza la hora
	IF		EXISTS(
					SELECT TOP 1  1
						FROM tbSystem_LastExecutionControl lec	WITH (NOLOCK)
						WHERE	lec.comp_id = @comp_id	AND
								lec.bra_id	= @bra_id	AND
								lec.id		= @intID	AND
								DATEDIFF(mi, lec.id_date,GETDATE()) >= @intMinutes
					)
		BEGIN
			SELECT @bitCanExecute = 'True'
			UPDATE tbSystem_LastExecutionControl	WITH (ROWLOCK)
				SET
						id_date = GETDATE()
				WHERE	comp_id = @comp_id	AND
						bra_id	= @bra_id	AND
						id		= @intID

			RETURN
		END

	RETURN @bitCanExecute

END
GO



