-- Author:		MOS
-- Create date: 07-2017
-- Activa la Actualización de todas las tiendas
-- activas
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_MercadoLibreProcessQueue]

AS
BEGIN

	SET NOCOUNT ON;

	EXEC spMercadoLibre_verifications4updateQueue

	DECLARE @strDBName AS nVARCHAR(100)
	SET @strDBName = db_name()
	DECLARE @URL		VARCHAR(8000)
	DECLARE @Response	varchar(8000)
	DECLARE @XML		xml
	DECLARE @Obj		int
	DECLARE @Result		int
	DECLARE @HTTPStatus int
	DECLARE @ErrorMsg	varchar(MAX)


	BEGIN TRY
		DECLARE curStoresToProcess CURSOR LOCAL FAST_FORWARD FOR
			SELECT	DISTINCT
						dbo.fnStrAllTrim (tmls.mls_url4Mercadolibre_processQueue) +
						CASE	-- MOS 04-2024: algunos FORROS de los implementadores les CHUPA UN HUEVO respetar la barra o no al final de la puta URL entonces lo verificamos acá
							WHEN RIGHT(dbo.fnStrAllTrim(tmls.mls_url4Mercadolibre_processQueue), 1) = '/' THEN ''
							ELSE '/'
						END
				FROM	tbMercadoLibre_Stores tmls	WITH (NOLOCK)
				WHERE	tmls.mls_disabled = 0							AND
						tmls.mls_url4Mercadolibre_processQueue <> ''	AND
						tmls.mls_url4Mercadolibre_processQueue IS NOT NULL

		OPEN curStoresToProcess
		FETCH NEXT FROM curStoresToProcess INTO @URL
		WHILE @@FETCH_STATUS = 0
			BEGIN

				-- En realidad la Caller llama a la queue pero con un timeout muy chico para que no atrase al resto de las ejecuciones de este proceso en BAT o JOB
				SELECT	@URL =  dbo.fnStrAllTrim(@url) + 'wfmMercadolibre_processQueueCaller.aspx?NoInitialRefresh=1'		-- MOS 02-2024: Le saqué la barra del final ya que VENIA con barra de la BD
				SELECT  dbo.clrActivateURL(@url)

				-- SELECT 'Ejecutando: ' + @url


				UPDATE tbMercadoLibre_Stores	WITH (ROWLOCK)
					SET	mls_System_MercadoLibreProcessQueue_lastCicleExecution = GETDATE()
					WHERE	mls_disabled = 0							AND
							mls_url4Mercadolibre_processQueue <> ''	AND
							mls_url4Mercadolibre_processQueue IS NOT NULL

				--SELECT	@URL,@HTTPStatus,@Obj,@Result

				FETCH NEXT FROM curStoresToProcess INTO @URL
			END
		CLOSE		curStoresToProcess
		DEALLOCATE	curStoresToProcess
	END TRY
	BEGIN CATCH
	END CATCH



	-- ---------------------------------------------------------------------------------------------------------------------
	-- MERCADOPAGO VERIFICACIONES Mercado Pago
	-- Verifica si DEBE hacer una verificacion de pagos x tema de cupones de pago que NO recibieron notificaciones de MeLi
	-- ---------------------------------------------------------------------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbMercadoLibre_Stores AS tmls	WITH (NOLOCK)
					WHERE	tmls.mls_disabled							= 'False'	AND
							tmls.mls_enabled4MercadoPagoVerifications	= 'True'	AND
							--DATEDIFF(hour,ISNULL(tmls.mls_enabled4MercadoPagoVerificationsLastExecution, DATEADD(day,-10, GETDATE()) ),GETDATE()) >= 24	AND
							(DATEPART(hour,GETDATE() )  BETWEEN 1 AND 8 OR DATEPART(hour,GETDATE() )  BETWEEN 13 AND 14)
			)
		AND
		EXISTS(
				SELECT TOP 1 1
					FROM tbSystem_DatabaseVersion AS tsdv	WITH (NOLOCK)
					WHERE ABS(DATEDIFF(hour,tsdv.lastMercadoPagoVerificationsOfPayments,GETDATE())) >= 10
				)
		BEGIN

			SELECT TOP 1 @URL = tmls.mls_url4Mercadolibre_processQueue
				FROM tbMercadoLibre_Stores AS tmls	WITH (NOLOCK)
				WHERE	tmls.mls_disabled							= 'False'	AND
						tmls.mls_enabled4MercadoPagoVerifications	= 'True'

			UPDATE tbSystem_DatabaseVersion
				SET lastMercadoPagoVerificationsOfPayments = GETDATE()

			SELECT	@URL =  @url + '/wfmMercadolibre_processQueueCaller.aspx?PaymentsVerifications=1'
			SELECT 'Ejecutando Verificación en: ' + @URL
			SELECT  dbo.clrActivateURL(@url)
		END
	-- ---------------------------------------------------------------------------------------------------------------------

END
GO



