CREATE PROCEDURE [dbo].[spSystem_POP3Emails]
as



BEGIN

	RETURN
	-- No se usa mas, se reemplazo por wfmCRM_GetEmails


	SET NOCOUNT ON;

	DECLARE @intCompId				AS INT
	DECLARE @intUserId				AS INT
	DECLARE @strServerName			AS NVARCHAR(4000)
	DECLARE @strUserName			AS NVARCHAR(4000)
	DECLARE @strUserPassword		AS NVARCHAR(4000)
	DECLARE @intPortNumber			AS INT
	DECLARE @bitDeleteMessage		AS BIT
	DECLARE @strConnectionString	AS NVARCHAR(4000)
	DECLARE @bitSSL					AS BIT
	DECLARE @strResponse			AS NVARCHAR(1000)

	DECLARE @intUE_Id	AS INT
	DECLARE @intMinutes AS INT



	DECLARE curUserToEMailTest	CURSOR LOCAL FAST_FORWARD  FOR
								SELECT tumar.ue_id,tumar.ue_testIntervalInMinutes
									FROM tbUserMailsAccountsRelation tumar			WITH (NOLOCK)
										inner JOIN tbCompany tc							WITH (NOLOCK)
											ON tc.comp_id	= tumar.comp_id
										INNER JOIN tbuser	tu							WITH (NOLOCK)
											ON tu.[user_id] = tumar.[user_id]
									WHERE
										    IsNull(tc.comp_connectionString4Pop3Emails,'') <> ''
										AND tumar.ue_disabled = 'False'
										AND IsNull(tu.user_Blocked,'False') = 'False'

	OPEN curUserToEMailTest
	FETCH curUserToEMailTest INTO @intUE_Id,@intMinutes

	WHILE @@FETCH_STATUS = 0
		BEGIN

			SELECT	@intCompId					= tumar.comp_id,
					@intUserId					= tumar.[user_id],
					@strServerName				= tumar.ue_pop3ServerName,
					@strUserName				= tumar.ue_UserName,
					@strUserPassword			= tumar.ue_UserPassword,
					@intPortNumber				= tumar.ue_PortNumber,
					@bitDeleteMessage			= 'True',
					@strConnectionString		= tc.comp_connectionString4Pop3Emails,
					@bitSSL						= tumar.ue_SSL

				FROM tbUserMailsAccountsRelation tumar			WITH (NOLOCK)
				INNER JOIN tbUser tu
					ON tu.[user_id] = tumar.[user_id]
				INNER JOIN tbCompany tc							WITH (NOLOCK)
					ON	tc.comp_id	= tumar.comp_id
				WHERE
						tumar.ue_id = @intUE_Id

			IF NOT EXISTS(	SELECT 1
								FROM tbUserMailLastPop tumlp		WITH (NOLOCK)
			              		WHERE	tumlp.comp_id	= @intCompId AND
			              				tumlp.[user_id] = @intUserId AND
			              				tumlp.ue_id		= @intUE_Id)
				BEGIN
					INSERT INTO tbUserMailLastPop
					(
						comp_id,
						[user_id],
						ue_id,
						ueMC_cd
					)
					VALUES
					(
						@intCompId,
						@intUserId,
						@intUE_Id,
						GETDATE() - 1000
					)
				END



			IF (SELECT TOP 1 DATEDIFF(minute, tumlp.ueMC_cd,GETDATE())
					FROM tbUserMailLastPop tumlp			WITH (NOLOCK)
							WHERE tumlp.ue_id = @intUE_Id
							ORDER BY tumlp.ueMC_cd DESC
					) > @intUE_Id

				BEGIN




					SET @strResponse = dbo.clrSys_MailManage_GetMailsFromUser(  @intCompId,
																				@intUserId,
																				@strServerName,
																				@strUserName,
																				@strUserPassword,
																				@intPortNumber,
																				@bitDeleteMessage,
																				@strConnectionString)




					UPDATE tbUserMailLastPop
						SET
							ueMC_cd		= GETDATE()
						WHERE	 comp_id	= @intCompId AND
								[user_id]	= @intUserId AND
								 ue_id		= @intUE_Id

					SELECT @strResponse

					FETCH curUserToEMailTest INTO @intUE_Id,@intMinutes

				END
			FETCH curUserToEMailTest INTO @intUE_Id,@intMinutes

		END

	CLOSE 		curUserToEMailTest
	DEALLOCATE	curUserToEMailTest

END










GO





CREATE PROCEDURE [dbo].[spSystem_ReindexTables]
AS



BEGIN

	DECLARE @strDNBame AS NVARCHAR(MAX)
	SET @strDNBame = DB_NAME()







	-- ------------------------------------------
	-- Regenera  los indices de NUEVO
	-- ------------------------------------------
	DECLARE @MyTable VARCHAR(255)
	DECLARE myCursor
	CURSOR LOCAL FAST_FORWARD FOR
	SELECT table_name
		FROM information_schema.tables
		WHERE table_type = 'base table'
	OPEN myCursor
		FETCH NEXT
		FROM myCursor INTO @MyTable
	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'Database:' + @strDNBame + ' Reindexing Table:  ' + @MyTable
		--DBCC DBREINDEX(@MyTable, '', 80)
		exec('ALTER INDEX ALL ON ' + @MyTable + ' REBUILD;')
		FETCH NEXT
		FROM myCursor INTO @MyTable
	END
	CLOSE myCursor
	DEALLOCATE myCursor
	-- ------------------------------------------


	-- ------------------------------------------
	-- Actualiza estadisticas
	-- ------------------------------------------
	PRINT 'Actualizando Estadísticas'
	EXEC sp_updatestats @resample = 'resample';
	-- ------------------------------------------

	-- ------------------------------------------
	-- Recompila SP
	-- ------------------------------------------
	PRINT 'Recompilando Stored Procedures'
	EXEC spSystem_SetStoredProceduresRecompilation
	-- ------------------------------------------



	-- ------------------------------------------
	-- Comprime la Base de Datos
	-- ------------------------------------------
	EXEC ('DBCC SHRINKDATABASE(' + @strDNBame + ')')
	-- ------------------------------------------

	-- ------------------------------------------
	-- Trunca el LOG
	-- ------------------------------------------
	BEGIN
			DECLARE @strExecute			AS NVARCHAR(1000)
			DECLARE @strDatabaseLogName as nvarchar(300)
			SELECT	@strDatabaseLogName = name
				FROM sys.master_files		WITH (NOLOCK)
				WHERE database_id = db_id()
					AND type = 1

			SET @strExecute = '
								DBCC SHRINKFILE (N''' + @strDatabaseLogName + ''' , 0, TRUNCATEONLY)	  '

			EXEC (@strExecute)
		END
	-- ------------------------------------------


END
GO
-- ATENCION: CRC  CRC  CRC  CRC NO MODIFICAR --
CREATE PROCEDURE [dbo].[spSystem_sendEMail]
(
	@compId					AS INT,
	@precipients			AS NVARCHAR(MAX),
	@pcopy_recipients		AS NVARCHAR(MAX),
	@psubject				AS NVARCHAR(MAX),
	@pbody_format			AS VARCHAR(4),
	@pbody					AS NVARCHAR(MAX),
	@pfile_attachments		AS NVARCHAR(MAX),
	@pReplyTo				AS NVARCHAR(MAX),
	@pblind_copy_recipients AS NVARCHAR(MAX),
	@pUser_Id				AS INT					
)
AS
BEGIN
	
	IF	@compId <= 0	OR 
		@compId IS NULL OR 
		EXISTS(	SELECT TOP 1 1 
		       		FROM tbCompany AS tc		WITH (NOLOCK) 
		       		WHERE tc.comp_id = @compId AND 
		       		tc.comp_disabled = 1
			  )
		BEGIN
			RETURN 
		END
	
	
	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	
	
	IF DATALENGTH(@psubject) > 500
		BEGIN
			SET @psubject = SUBSTRING(@psubject,1,490)
		END
	
	
	
	SET @precipients			= REPLACE(@precipients,'soporte@implementador.com','')
	SET @pcopy_recipients		= REPLACE(@pcopy_recipients,'soporte@implementador.com','')
	SET @pblind_copy_recipients = REPLACE(@pblind_copy_recipients,'soporte@implementador.com','')
	
	
	IF @pbody_format NOT IN ('HTML','TEXT') SET @pbody_format ='HTML'
	IF  isnull(@precipients,'') = '' AND ISNULL(@pcopy_recipients,'') = '' RETURN
	SET @pbody = ISNULL(@pbody,'*')
	SET @precipients			= dbo.fnstrEmailCheck(ISNULL(@precipients,''))
	SET @pcopy_recipients		= dbo.fnstrEmailCheck(ISNULL(@pcopy_recipients,''))
	SET @pblind_copy_recipients = dbo.fnstrEmailCheck(ISNULL(@pblind_copy_recipients,''))
	SET @precipients			= dbo.fnSTRDistinctList(@precipients,';','')
	SET @pblind_copy_recipients = dbo.fnSTRDistinctList(@pblind_copy_recipients,';',@precipients)		-- sin dup.
	SET @pcopy_recipients		= dbo.fnSTRDistinctList(@pcopy_recipients,';',@precipients)				
	SET @pcopy_recipients		= dbo.fnSTRDistinctList(@pcopy_recipients,';',@pblind_copy_recipients)	
	IF @pblind_copy_recipients <> '' AND @precipients = '' AND @pcopy_recipients = ''
		BEGIN
			SET @precipients			= @pblind_copy_recipients
			SET @pblind_copy_recipients = ''
		END
	SET @pbody = @pbody + IsNull(	(	SELECT TOP 1 tu.user_emailSignature
											FROM tbUser tu	WITH (NOLOCK)
	                             			WHERE tu.[user_id] = @pUser_Id)  ,'')
	set @pfile_attachments =    '' 
	DECLARE @profilename NVARCHAR(4000)
	DECLARE @strReplyTo  NVARCHAR(4000)
	DECLARE @bitType	 BIT
	DECLARE @smtp_sendByDatabaseService AS BIT = 'False'
	SELECT	@profilename				= tc.smtp_profileName,
			@strReplyTo					= tc.smtp_defaultFromEMail,
			@bitType					= 'False',  --dbo.clrGetAM(tc.comp_id,94, tc.comp_am , CONVERT(NVARCHAR(50), tc.comp_guid)), NO IDIOTA , NO MAS PAVADAS !!!!! DEPCO
			@smtp_sendByDatabaseService = ISNULL(tc.smtp_sendByDatabaseService,'False')
		FROM tbCompany tc	WITH (NOLOCK)
		WHERE tc.comp_id = @compId

	IF @precipients		 LIKE '%@mail.mercadolibre.com%' OR
	   @pcopy_recipients LIKE '%@mail.mercadolibre.com%'
	   BEGIN
			SET @pbody_format='TEXT'
	   END
	IF @pbody_format='TEXT' SET @bitType = 2
	IF @smtp_sendByDatabaseService = 'True'	SET @pbody = @pbody + dbo.fnGetEMailPoweredBy(@bitType,1)
	IF @pReplyTo IS NOT NULL AND @pReplyTo <> '' SET @strReplyTo = @pReplyTo

	IF @pbody_format='TEXT'
		BEGIN
			SET @pbody = dbo.fnStrStripHTML(@pbody)
		END
		
	DECLARE 
		@strSmtp_Host			AS NVARCHAR(1000),
		@strSmpt_User			AS NVARCHAR(250),
		@strSmtp_Password		AS NVARCHAR(250),
		@intSmtp_Port			AS INT,
		@bitSmtp_Ssl			AS BIT		
		
	
	SELECT 
			@strSmtp_Host			= ISNULL(rt.smtp_host,tc.smtp_host),		
			@strSmpt_User			= ISNULL(rt.smtp_user,tc.smtp_user),
			@strSmtp_Password		= ISNULL(rt.smtp_password,tc.smtp_password),
			@intSmtp_Port			= ISNULL(rt.smtp_port,tc.smtp_port),
			@bitSmtp_Ssl			= ISNULL(rt.smtp_ssc,tc.smtp_ssc)
		FROM		tbCompany						tc WITH (NOLOCK)
		LEFT JOIN	tbSMTPConfigurationByReplyTo	rt WITH (NOLOCK)
			ON	rt.comp_id		= @compId AND 
				LOWER(dbo.fnStrAllTrim(rt.smtp_ReplyTo)) = LOWER(dbo.fnStrAllTrim(@strReplyTo))
		WHERE tc.comp_id = @compId
		
	IF ISNULL(@pUser_Id,0) <= 0 SET @pUser_Id = NULL			
		
	IF	(@precipients <> '' OR @pcopy_recipients <> '' OR @pblind_copy_recipients <> '') 
		BEGIN
			BEGIN TRY
		
				DECLARE @strStatus AS NVARCHAR(MAX) = '0'
		
				IF @smtp_sendByDatabaseService = 'True'
					BEGIN
						
						SET @profilename = @profilename + '_Profile'
						EXEC msdb.dbo.sp_send_dbmail
								@profile_name			= @profilename		,
								@reply_to				= @strReplyTo,
								@from_address			= @strReplyTo,
								@recipients				= @precipients		,
								@copy_recipients		= @pcopy_recipients	,
								@subject				= @psubject			,
								@body_format			= @pbody_format		,
								@body					= @pbody			,
								@file_attachments		= @pfile_attachments,
								@blind_copy_recipients	= @pblind_copy_recipients,
								@importance='High'	
							
				
						-- Solo si manda desde SQL, sino q guarde al enviarlos.
						INSERT INTO tbsentEMailLog
						(
							comp_id,
							el_fromMail,
							el_toMail,
							el_toMailCC,
							el_toMailCCO,
							el_subject,
							el_body,
							[user_id],
							el_fromSQLMAIL, 
							el_profileMailName, 
							el_SMTPResponse
						)
						VALUES
						(
							@compId,
							@strReplyTo,
							@precipients,
							@pcopy_recipients,
							@pblind_copy_recipients,
							@psubject,
							@pbody,
							@pUser_Id,
							'True',
							@profilename,
							@strStatus
						)
							
											
					END
				ELSE
					BEGIN
				
						INSERT INTO tbsendEMailQueue
						(
							comp_id,
							[user_id],
							replyTo,
							sendTo,
							sendToCC,
							sendToCCO,
							[subject],
							body,
							displayName
						)
						VALUES
						(
							@compId,
							@pUser_Id,
							@strReplyTo,
							@precipients,
							@pcopy_recipients,
							@pblind_copy_recipients,
							@psubject,
							@pbody,
							@strReplyTo
						)
					
						-- EXEC spTMPFiles_SMTP_sendEmails    NOOO, que se manden cuando corra el spIsEditingPurgeStatus sino FRENAN la Ejecución del Sistema.! ! !  MOS 06-2020
					END
						
			END TRY
			BEGIN CATCH
			END CATCH
		END
END

-- EXEC spSystem_sendEMail 1,'martin@globalbluepoint.com','','Test de este Mail','HTML','Body del Mail 5','','soporte@globalbluepoint.com','saraccomartin@yahoo.com.ar',-1
GO





