CREATE PROCEDURE [dbo].[spSystem_SessionInSQL_DeleteData]
	@sedb_id AS UNIQUEIDENTIFIER
AS
BEGIN

	SET LOCK_TIMEOUT 300
	SET DEADLOCK_PRIORITY LOW  -- **JAVIER**
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	BEGIN TRY
		DELETE		tbSystem_SessionInSQL	WITH (ROWLOCK)
			FROM	tbSystem_SessionInSQL	tmp	--WITH (NOLOCK)
			WHERE	tmp.sedb_id = @sedb_id
	END TRY
	BEGIN CATCH
	END CATCH

END
GO





