-- Create date: 03-2010
-- Description:	Viewstate in DB
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_SessionInSQL_InsertData]
	@sedb_id AS UNIQUEIDENTIFIER,
	@sedb_count AS INT	,
	@sedb_name AS NVARCHAR(500),
	@sedb_value AS NVARCHAR(MAX)

AS
BEGIN




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON;


	BEGIN TRY
		-- Por si por algun motivo intenta grabar 2 veces el mismo juego de valores.-
		IF @sedb_count = 0
											--AND  EXISTS(	SELECT TOP 1 1
											--FROM tbSystem_SessionInSQL tssis	WITH (NOLOCK)
											--WHERE tssis.sedb_id = @sedb_id)
			BEGIN
				DELETE tbSystem_SessionInSQL	WITH (ROWLOCK)
					FROM tbSystem_SessionInSQL tmp --WITH (NOLOCK)
					WHERE tmp.sedb_id = @sedb_id
			END

		INSERT INTO tbSystem_SessionInSQL	--WITH (ROWLOCK) lo saque el 25-12-2020
		(
			sedb_id,
			sedb_name,
			sedb_value,
			sedb_cd
		)
		VALUES
		(
			@sedb_id,
			@sedb_name,
			@sedb_value,
			GETDATE()
		)

	END TRY
	BEGIN CATCH
	END CATCH


END
GO





