-- =============================================
CREATE PROCEDURE [dbo].[spSystem_SetSQLPerformanceParameters]
AS
BEGIN
	SET NOCOUNT ON;


RETURN
--	SELECT * FROM sys.dm_os_sys_info
--
--	DECLARE @CPUs int;
--	DECLARE @NumaNodes int;
--	DECLARE @ServerRAMInMB int;
--
--	SET @ServerRAMinMB = (SELECT (i.physical_memory_in_bytes / 1048576) AS ServerMemory
--		FROM sys.dm_os_sys_info i);
--	SET @CPUs = (SELECT i.cpu_count from sys.dm_os_sys_info i);
--	SET @NumaNodes = (SELECT MAX(c.memory_node_id) + 1 FROM sys.dm_os_memory_clerks c
