-- =============================================
-- Author:		MOS
-- Create date: 12-2013
-- Description:	Volver a recompilar los SP
-- =============================================


CREATE PROCEDURE [dbo].[spSystem_SetStoredProceduresRecompilation]
AS


BEGIN

	SET NOCOUNT ON;

	DBCC DROPCLEANBUFFERS
	DBCC FREEPROCCACHE
	DECLARE @intDBID INTEGER

	SET @intDBID = DB_ID()

	DBCC FLUSHPROCINDB (@intDBID)

	declare @procNames Table (procName varchar(MAX))

	insert into @procNames
		select name
			from sysObjects WITH (NOLOCK)
			where xtype in ('V','P','U','FN','TF','TR' )   AND   --and status > 0
					 name NOT LIKE '%vwbi_%'

	set nocount off


	DECLARE RecompilableItemsCursor CURSOR FAST_FORWARD	READ_ONLY
		FOR select procName from @procNames

	DECLARE @RecompilableItem varchar(MAX)

	OPEN RecompilableItemsCursor

	FETCH NEXT FROM RecompilableItemsCursor INTO @RecompilableItem
	WHILE (@@fetch_status <> -1)
		BEGIN
			IF (@@fetch_status <> -2)
				BEGIN
					DECLARE @sql varchar(MAX)
					select @sql = 'Exec sp_recompile ' + @RecompilableItem

					IF NOT @sql LIKE '%spUser_getNeedAuthorization.UnUsed%'
						BEGIN
							--print @sql
							exec (@sql)
						END

				END
			FETCH NEXT FROM RecompilableItemsCursor INTO @RecompilableItem
		END
	CLOSE RecompilableItemsCursor
	DEALLOCATE RecompilableItemsCursor

END
GO





