CREATE PROCEDURE [dbo].[spSystem_SetTaxesIVAPercentValues]
AS
BEGIN

	SET NOCOUNT ON;


	UPDATE tbtaxname
		SET strcv_id = tsrac.strcv_id
		FROM tbtaxname ttt
		INNER JOIN tbsysSIAP_RG3685V_AlicuotaCode tsrac
			ON tsrac.strcv_percentage	= ttt.tax_percentage
		WHERE	ttt.tax_class	= 1 AND
			    ttt.strcv_id IS NULL



END
