-- =============================================
-- Author:		MOS
-- Create date: 009-2018
-- Activa la Actualización de todas las tiendas
-- activas
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_TiendaNubeProcessQueue]

AS
BEGIN

	SET NOCOUNT ON;


	DECLARE @strDBName AS nVARCHAR(100)
	SET		@strDBName = db_name()
	DECLARE @URL		VARCHAR(8000)
	DECLARE @Response	varchar(8000)
	DECLARE @XML		xml
	DECLARE @Obj		int
	DECLARE @Result		int
	DECLARE @HTTPStatus int
	DECLARE @ErrorMsg	varchar(MAX)
	DECLARE @comp_id	INT
	DECLARE @tn_id		INT

	DECLARE curStoresToProcess CURSOR LOCAL  FAST_FORWARD FOR
		SELECT		tmls.tn_url4TiendaNube_processQueue, tmls.comp_id, tmls.tn_id
			FROM	tbTiendaNube_Stores 	 tmls	WITH (NOLOCK)
			WHERE	tmls.tn_disabled = 0							AND
					tmls.tn_url4TiendaNube_processQueue <> ''	AND
					tmls.tn_url4TiendaNube_processQueue IS NOT NULL

	OPEN curStoresToProcess
	FETCH NEXT FROM curStoresToProcess INTO @URL,@comp_id,@tn_id
	WHILE @@FETCH_STATUS = 0
		BEGIN

			SELECT	@URL =  @url + '/wfmTiendaNube_processQueueCaller.aspx?CHECKALL=1&COMPID=' + CONVERT(VARCHAR(10),@comp_id) + '&TNID=' + CONVERT(VARCHAR(10),@tn_id)
			SELECT  dbo.clrActivateURL(@URL)

			FETCH NEXT FROM curStoresToProcess INTO @URL,@comp_id,@tn_id
		END
	CLOSE		curStoresToProcess
	DEALLOCATE	curStoresToProcess




END
GO





