-- =============================================
-- Author:		MOS
-- Create date: 03-2010
-- Description:	Viewstate in DB
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_ViewStateInSQL_InsertData]
	@vsdb_id AS UNIQUEIDENTIFIER,
	@vsdb_value AS NVARCHAR(MAX)
AS
BEGIN

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON;


	BEGIN TRY
		IF NOT EXISTS(SELECT TOP 1 1
						FROM tbSystem_ViewStateInSQL  WITH (NOLOCK)
						WHERE vsdb_id = @vsdb_id)

			BEGIN
				INSERT INTO tbSystem_ViewStateInSQL	--WITH (ROWLOCK)	lo saque el 25-12-2020
				(
					vsdb_id,
					vsdb_value,
					vsdb_cd
				)
				VALUES
				(
					@vsdb_id,
					@vsdb_value,
					GETDATE()
				)
			END

		ELSE
			BEGIN
				UPDATE tbSystem_ViewStateInSQL	--WITH (ROWLOCK)  lo saque el 25-12-2020
					--SET vsdb_value = @vsdb_value  MOS 05-2020
					SET vsdb_value	.WRITE( @vsdb_value,0,NULL),	-- MUUUUCHO MAS RAPIDO y NO GRABA FORRADAS en el LOG
						vsdb_cd		= GETDATE()						-- MOS 25-12-2020, se agrega la ultima fecha de actualizacion para que al depurar en el backup no quede arriba en la header en blanco o en alguna otra pagina mal los VS
					WHERE vsdb_id = @vsdb_id
			END

	END TRY
	BEGIN CATCH
	END CATCH



END
GO



-- =============================================
-- Author:		MOS
-- Create date: 009-2018
-- Activa la Actualización de todas las tiendas
-- activas
-- =============================================
CREATE PROCEDURE [dbo].[spSystem_WhatsAppProcessQueue]

AS
BEGIN

	SET NOCOUNT ON;



	IF NOT EXISTS (SELECT TOP 1 1 FROM  tbCompany AS tc WHERE ISNULL(tc.comp_ServerFULLURL4wfmWhatsapp_processQueueExec,'') <> '')
		BEGIN
			SELECT 'No hay URL para Whatsapp definida en Compañías'
			RETURN
		END




	DECLARE @strDBName  nVARCHAR(100) = db_name()
	DECLARE @URL		VARCHAR(8000)
	DECLARE @Response	varchar(8000)
	DECLARE @XML		xml
	DECLARE @Obj		int
	DECLARE @Result		int
	DECLARE @HTTPStatus int
	DECLARE @ErrorMsg	varchar(MAX)
	DECLARE @comp_id	INT
	DECLARE @tn_id		INT

	DECLARE curStoresToProcess CURSOR LOCAL  FAST_FORWARD FOR
		SELECT DISTINCT tc.comp_ServerFULLURL4wfmWhatsapp_processQueueExec ,
						tc.comp_id
			FROM tbWhatsapp_Chats			AS twt	WITH (NOLOCK,INDEX(IX_tbWhatsapp_Chats_Pending4Envie))
			INNER JOIN tbCompany			AS tc	WITH (NOLOCK)
				ON	tc.comp_id	= twt.comp_id
			--INNER JOIN tbWhatsapp_Numbers	AS twn	WITH (NOLOCK)
			--	ON	twn.comp_id = twt.comp_id AND
			--		twn.wapn_id = twt.wapn_id
			WHERE	twt.wach_isPending4Envie = 'True' AND
					tc.comp_ServerFULLURL4wfmWhatsapp_processQueueExec IS NOT NULL AND
					tc.comp_ServerFULLURL4wfmWhatsapp_processQueueExec <> ''



	OPEN curStoresToProcess
	FETCH NEXT FROM curStoresToProcess INTO @URL,@comp_id
	WHILE @@FETCH_STATUS = 0
		BEGIN

			SELECT	@URL =  dbo.fnStrAllTrim(@url) + 'wfmWhatsapp_processQueueCaller.aspx?CHECKALL=1'
			SELECT  dbo.clrActivateURL(@URL)

			--SELECT 'Ejecutando: ' + @URL

			FETCH NEXT FROM curStoresToProcess INTO @URL,@comp_id
		END
	CLOSE		curStoresToProcess
	DEALLOCATE	curStoresToProcess




END
GO













-- =================================================================
-- Author:		MOS
-- Create date: 19-02-2008
-- Description:	Trae Valores por ID de conf. del sistema
-- Si no encuentra el dato por compañia y por sucursal
-- lo busca solo por compañia y sucursal 1
-- la cual estara cargada por script inicial del sistema
-- Como  lo pide por rango, tiene que respetar esto ultimo
-- =================================================================

CREATE PROCEDURE  [dbo].[spSystemConfiguration_getDataByFilters]
	-- Parameters
(
	@comp_id				int,
	@lang_id				int,
	@bra_id					int,
	@ssc_from_parameter_id	int,
	@ssc_to_parameter_id	int

)

AS

Begin

-- --------------------------------------------------------------------
--   Comienzo de la Consulta
-- --------------------------------------------------------------------

	SET NOCOUNT ON

/*
declare 	@comp_id			int ,
	@bra_id				int,
	@ssc_from_parameter_id	int,
	@ssc_to_parameter_id	int,
	@lang_id			int
select
	@comp_id			=1,
	@bra_id				=1,
	@ssc_from_parameter_id	=100,
	@ssc_to_parameter_id	=199,
	@lang_id			=2
*/

-----------------------------------------
-- Sacar los parametros del sistema
-----------------------------------------
--drop table #tmptbsysSystemConfiguration

	Select
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image

	Into #tmptbsysSystemConfiguration

	From	dbo.tbsysSystemConfiguration

	Where	ssc_parameter_id  between  @ssc_from_parameter_id and @ssc_to_parameter_id
--select * from #tmptbsysSystemConfiguration
-----------------------------------------



-----------------------------------------
-- Ahora mira los de la Compañia
-----------------------------------------
--drop table #tmptbSystemConfiguration

	Select
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image

	Into #tmptbSystemConfiguration

	From	dbo.tbSystemConfiguration

	Where	comp_id = @comp_id and
			ssc_parameter_id  between  @ssc_from_parameter_id and @ssc_to_parameter_id
--select * from #tmptbSystemConfiguration
-----------------------------------------



-----------------------------------------
-- Ahora mira los de la sucursal en si
-----------------------------------------
--drop table #tmptbSystemConfigurationByBranch

	Select
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image

	Into #tmptbSystemConfigurationByBranch

	From	dbo.tbSystemConfigurationByBranch

	Where	comp_id = @comp_id and
			bra_id = @bra_id  and
			ssc_parameter_id  between  @ssc_from_parameter_id and @ssc_to_parameter_id

-----------------------------------------


--drop Table #tmpAllSystemConfiguration

Select *	Into #tmpAllSystemConfiguration
			From #tmptbsysSystemConfiguration

			Where ssc_parameter_id  = 0


Insert Into #tmpAllSystemConfiguration
			 (ssc_parameter_id,
			 sc_int,
			 sc_decimal,
			 sc_varchar,
			 sc_bit,
			 sc_image)
		Select a.ssc_parameter_id,
			a.sc_int,
			a.sc_decimal,
			a.sc_varchar,
			a.sc_bit,
			a.sc_image
		From #tmptbsysSystemConfiguration a
		Where		a.ssc_parameter_id not In (Select b.ssc_parameter_id
												From #tmptbSystemConfigurationByBranch b)
				and a.ssc_parameter_id Not In (Select c.ssc_parameter_id From #tmptbSystemConfiguration c)


Insert Into #tmpAllSystemConfiguration
			 (ssc_parameter_id,
			 sc_int,
			 sc_decimal,
			 sc_varchar,
			 sc_bit,
			 sc_image)
		Select a.ssc_parameter_id,
			a.sc_int,
			a.sc_decimal,
			a.sc_varchar,
			a.sc_bit,
			a.sc_image
		From #tmptbSystemConfiguration a
		Where		a.ssc_parameter_id not In (Select b.ssc_parameter_id
												From #tmptbSystemConfigurationByBranch b)


Insert Into #tmpAllSystemConfiguration
			 (ssc_parameter_id,
			 sc_int,
			 sc_decimal,
			 sc_varchar,
			 sc_bit,
			 sc_image)
		Select a.ssc_parameter_id,
			a.sc_int,
			a.sc_decimal,
			a.sc_varchar,
			a.sc_bit,
			a.sc_image
		From #tmptbSystemConfigurationByBranch a



------------------------------------------------------------------------------
-- Ahora añade la columna correspondiente a la descripcion segun el lenguaje
-- Esta es la tabla 3 de tbsysTables !!!!!!!!!!!!!!!!!!!!!!!!!!!!!
------------------------------------------------------------------------------
Select
	   A.ssc_parameter_id,
       B.description,
	   A.sc_int,
	   A.sc_decimal,
	   A.sc_varchar,
	   A.sc_bit,
	   A.sc_image
From	#tmpAllSystemConfiguration  A
		Inner Join	dbo.tbsysLangRelation  B
		On	B.id_id		= A.ssc_parameter_id
		and	B.table_id	= 3
		and	B.lang_id	= @lang_id
------------------------------------------------------------------------------


-- --------------------------------------------------------------------
--   FIN de la Consulta
-- --------------------------------------------------------------------


End
GO









-- =================================================================
-- Author:		MOS
-- Create date: 19-02-2008
-- Description:	Trae Valores por ID de conf. del sistema
-- Si no encuentra el dato por compañia y por sucursal
-- lo busca solo por compañia y sucursal 1
-- la cual estara cargada por script inicial del sistema
-- =================================================================

CREATE PROCEDURE  [dbo].[spSystemConfiguration_getDataById]
	-- Parameters
(
	@comp_id			int,
	@lang_id			int,
	@bra_id				int,
	@ssc_parameter_id	int

)

AS

	SET NOCOUNT ON

Begin

/*
declare 	@comp_id			int ,
	@bra_id				int,
	@ssc_parameter_id	int,
	@lang_id			int
select
	@comp_id			=7777,
	@bra_id				=66,
	@ssc_parameter_id	=100,
	@lang_id			=2

*/

Drop Table #tmptbSystemConfiguration
-- 1ro busca si el valor esta en la sucursal
	Select
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image

	Into #tmptbSystemConfiguration

	From	dbo.tbSystemConfigurationByBranch

	Where	comp_id = @comp_id and
			bra_id = @bra_id  and
			ssc_parameter_id = @ssc_parameter_id
--select * from #tmptbSystemConfiguration


-- 2do busca si el valor esta definido x compañia
	If @@ROWCOUNT = 0
	Begin

		Truncate Table #tmptbSystemConfiguration

		Insert Into #tmptbSystemConfiguration
		 (
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image
		 )
		Select
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image
		From	dbo.tbSystemConfiguration
		Where	comp_id = @comp_id and
				ssc_parameter_id = @ssc_parameter_id


-- 3ro busca si el valor esta definido a nivel de sistema

	If @@ROWCOUNT = 0
	Begin

		Truncate Table [#tmptbSystemConfiguration]

		Insert Into #tmptbSystemConfiguration
		 (
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image
		 )
		Select
			ssc_parameter_id,
			sc_int,
			sc_decimal,
			sc_varchar,
			sc_bit,
			sc_image
		From	dbo.tbsysSystemConfiguration
		Where	ssc_parameter_id = @ssc_parameter_id

	End
	End


-- Ahora añade la columna correspondiente a la descripcion segun el lenguaje
-- Esta es la tabla 3 de tbsysTables !!!!!!!!!!!!!!!!!!!!!!!!!!!!!

Select
	   A.ssc_parameter_id,
       B.description,
	   A.sc_int,
	   A.sc_decimal,
	   A.sc_varchar,
	   A.sc_bit,
	   A.sc_image
From	#tmptbSystemConfiguration  A
		Inner Join	dbo.tbsysLangRelation  B
		On	B.id_id		= A.ssc_parameter_id
		and	B.table_id	= 3
		and	B.lang_id	= @lang_id



End



GO





CREATE PROCEDURE [dbo].[spSysTexts_convertNumberToLetters]
(
	@lang_id		INT,
	@import			DECIMAL(19,2),
	@letters		VARCHAR(8000) OUTPUT
)
AS
SET NOCOUNT ON

/*
DECLARE	@lang_id	INT,
		@import		DECIMAL(19,2),
		@letters	VARCHAR(8000)
SELECT	@lang_id	=2,
		@import		=12345678901234567.23
*/

SELECT	@letters = ''

DECLARE	@intPart	BIGINT,
		@decPart	INT

--obtener la parte entera del importe
SET @intPart = CONVERT(BIGINT, @import)

--obtener la parte decimal del importe
SET @decPart = (@import - @intPart) * 100


--llamar al traductor de numeros a letras según el lenguaje
IF @lang_id = 1 --english
	EXEC spSysTexts_convertNumberToLettersSP @intPart, @letters OUTPUT
ELSE
IF @lang_id = 2 --español
	BEGIN
		EXEC spSysTexts_convertNumberToLettersSP @intPart, @letters OUTPUT
		IF RIGHT(@letters,2) = 'UN'
		BEGIN
			SET @letters = @letters + 'O'
		END
		IF @decPart > 0
		BEGIN
			SET @letters = @letters + ' con ' + CONVERT(VARCHAR,@decPart) + '/100'
		END
		IF LEN (@letters) > 2
		BEGIN
			SET @letters = @letters + '.'
		END
	END

--retonar el impore en letras
--SELECT @letters
GO





CREATE PROCEDURE [dbo].[spSysTexts_convertNumberToLettersSP]
(
	@integerValue			BIGINT,
	@Num2Text				VARCHAR(8000) OUTPUT
)
AS
SET NOCOUNT ON
DECLARE @num2text2 VARCHAR(8000)
SET @num2text2 = ''
Select	@Num2Text2 = case
					When @integerValue = 0					then 'CERO'
					When @integerValue = 1					then 'UN'
					When @integerValue = 2					then 'DOS'
					When @integerValue = 3					then 'TRES'
					When @integerValue = 4					then 'CUATRO'
					When @integerValue = 5					then 'CINCO'
					When @integerValue = 6					then 'SEIS'
					When @integerValue = 7					then 'SIETE'
					When @integerValue = 8					then 'OCHO'
					When @integerValue = 9					then 'NUEVE'
					When @integerValue = 10					then 'DIEZ'
					When @integerValue = 11					then 'ONCE'
					When @integerValue = 12					then 'DOCE'
					When @integerValue = 13					then 'TRECE'
					When @integerValue = 14					then 'CATORCE'
					When @integerValue = 15					then 'QUINCE'
					When @integerValue < 20					then 'DIECI'
					When @integerValue = 20					then 'VEINTE'
					When @integerValue < 30					then 'VEINTI'
					When @integerValue = 30					then 'TREINTA'
					When @integerValue = 40					then 'CUARENTA'
					When @integerValue = 50					then 'CINCUENTA'
					When @integerValue = 60					then 'SESENTA'
					When @integerValue = 70					then 'SETENTA'
					When @integerValue = 80					then 'OCHENTA'
					When @integerValue = 90					then 'NOVENTA'
					When @integerValue < 100				then ''
					When @integerValue = 100				then 'CIEN'
					When @integerValue < 200				then 'CIENTO '

					When @integerValue = 200				then ''
					When @integerValue = 300				then ''
					When @integerValue = 400				then ''
					When @integerValue = 600				then ''
					When @integerValue = 800				then ''

					When @integerValue = 500				then 'QUINIENTOS'
					When @integerValue = 700				then 'SETECIENTOS'
					When @integerValue = 900				then 'NOVECIENTOS'
					When @integerValue < 1000				then ''
					--When 1000 then @Num2Text = 'UN MIL'
					When @integerValue = 1000				then 'UN MIL'
					--When Is < 2000 then @Num2Text = 'UN MIL ' & @Num2Text(integerValue Mod 1000)
					When @integerValue < 2000				then 'UN MIL '
					--When Is < 1000000 then @Num2Text = @Num2Text(Int(integerValue \ 1000)) & ' MIL'
					When @integerValue < 1000000			then ''
					--When 1000000 then @Num2Text = 'UN MILLON'
					When @integerValue = 1000000			then 'UN MILLON'
					--When Is < 2000000 then @Num2Text = 'UN MILLON ' & @Num2Text(integerValue Mod 1000000)
					When @integerValue < 2000000			then 'UN MILLON '
					--When Is < 1000000000000.0# then @Num2Text = @Num2Text(Int(integerValue / 1000000)) & ' MILLONES '
					When @integerValue < 1000000000000		then ''
					--When 1000000000000.0# then @Num2Text = 'UN BILLON'
					When @integerValue = 1000000000000		then 'UN BILLON'
					--When Is < 2000000000000.0# then @Num2Text = 'UN BILLON ' & @Num2Text(integerValue - Int(integerValue / 1000000000000.0#) * 1000000000000.0#)
					WHEN @integerValue < 2000000000000		then 'UN BILLON '
					WHEN @integerValue < 1000000000000000000	THEN ''
					ELSE										'*'
					END


DECLARE @integerValue2 BIGINT
--SELECT @@NESTLEVEL

SET @Num2Text = @Num2Text + @Num2Text2

IF (@integerValue > 15 AND @integerValue < 20)
BEGIN
	SET @integerValue2 = @integerValue - 10
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END
IF (@integerValue > 20 AND @integerValue < 30)
BEGIN
	SET @integerValue2 = @integerValue - 20
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END
IF (@integerValue > 30 AND @integerValue < 100 AND @integerValue <> 30 AND @integerValue <> 40
	AND @integerValue <> 50 AND @integerValue <> 60 AND @integerValue <> 70 AND @integerValue <> 80 AND @integerValue <> 90)
BEGIN
	SET @integerValue2 = CONVERT(BIGINT,(@integerValue / 10)) * 10
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	set @Num2Text = @Num2Text + ' Y '
	SET @integerValue2 = @integerValue % 10
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END
IF (@integerValue > 100 AND @integerValue < 200)
BEGIN
	SET @integerValue2 = @integerValue - 100
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END

--		When 200, 300, 400, 600, 800 then @Num2Text = @Num2Text(Int(integerValue \ 100)) & 'CIENTOS'
IF (@integerValue = 200 or @integerValue = 300 or @integerValue = 400 or @integerValue = 600 or @integerValue = 800)
BEGIN
	SET @integerValue2 = CONVERT(BIGINT,(@integerValue / 100))
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	set @Num2Text = @Num2Text + 'CIENTOS'
END

--		When Is < 1000 then @Num2Text = @Num2Text(Int(integerValue \ 100) * 100) & ' ' & @Num2Text(integerValue Mod 100)
IF (@integerValue > 200 and @integerValue < 1000 and @integerValue <> 200 and @integerValue <> 300
	and @integerValue <> 400 and @integerValue <> 500 and @integerValue <> 600 and @integerValue <> 700
	and @integerValue <> 800 and @integerValue <> 900 )
BEGIN
	SET @integerValue2 = CONVERT(BIGINT,(@integerValue / 100)) * 100
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	set @Num2Text = @Num2Text + ' '
	SET @integerValue2 = @integerValue % 100
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END

--		When Is < 2000 then @Num2Text = 'UN MIL ' & @Num2Text(integerValue Mod 1000)
IF (@integerValue > 1000 and @integerValue < 2000)
BEGIN
	SET @integerValue2 = @integerValue % 1000
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END

--		When Is < 1000000 then @Num2Text = @Num2Text(Int(integerValue \ 1000)) & ' MIL'
IF (@integerValue > 1999 and @integerValue < 1000000)
BEGIN
	SET @integerValue2 = CONVERT(BIGINT,(@integerValue / 1000))
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	set @Num2Text = @Num2Text + ' MIL'
	--			If integerValue Mod 1000 Then @Num2Text = @Num2Text & ' ' & @Num2Text(integerValue Mod 1000)
	IF (@integerValue % 1000) > 0
	BEGIN
		SET @Num2Text = @Num2Text + ' '
		SET @integerValue2 = @integerValue % 1000
		EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	END
END

--When Is < 2000000 then @Num2Text = 'UN MILLON ' & @Num2Text(integerValue Mod 1000000)
IF (@integerValue > 1000000 and @integerValue < 2000000)
BEGIN
	SET @integerValue2 = @integerValue % 1000000
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END

--When Is < 1000000000000.0# then @Num2Text = @Num2Text(Int(integerValue / 1000000)) & ' MILLONES '
IF (@integerValue > 1999999 and @integerValue < 1000000000000)
BEGIN
	SET @integerValue2 = CONVERT(BIGINT,(@integerValue / 1000000))
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	set @Num2Text = @Num2Text + ' MILLONES '
	--If (integerValue - Int(integerValue / 1000000) * 1000000) Then @Num2Text = @Num2Text & ' ' & @Num2Text(integerValue - Int(integerValue / 1000000) * 1000000)
	If	   (@integerValue - (convert(BIGINT,@integerValue / 1000000) * 1000000) > 0)
	BEGIN
		--set @Num2Text = @Num2Text + ' '
		SET @integerValue2 = @integerValue - (convert(BIGINT,@integerValue / 1000000) * 1000000)
		EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	END
END

--When Is < 2000000000000.0# then @Num2Text = 'UN BILLON ' & @Num2Text(integerValue - Int(integerValue / 1000000000000.0#) * 1000000000000.0#)
IF (@integerValue > 1000000000000 and @integerValue < 2000000000000)
BEGIN
	SET @integerValue2 = @integerValue - (CONVERT(BIGINT,(@integerValue / 1000000000000)) * 1000000000000)
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
END

--When Else then @Num2Text = @Num2Text(Int(integerValue / 1000000000000.0#)) & ' BILLONES'
IF (@integerValue > 1999999999999 AND @integerValue < 1000000000000000000)
BEGIN
	SET @integerValue2 = CONVERT(BIGINT,(@integerValue / 1000000000000))
	EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	set @Num2Text = @Num2Text + ' BILLONES'
	--If											(integerValue - Int(integerValue / 1000000000000.0#) * 1000000000000.0#)
	-- Then @Num2Text = @Num2Text & ' ' & @Num2Text(integerValue - Int(integerValue / 1000000000000.0#) * 1000000000000.0#)
	If	   (@integerValue - (convert(BIGINT,@integerValue / 1000000000000) * 1000000000000) > 0)
	BEGIN
		set @Num2Text = @Num2Text + ' '
		SET @integerValue2 = @integerValue - (convert(BIGINT,@integerValue / 1000000000000) * 1000000000000)
		EXEC  spSysTexts_convertNumberToLettersSP @integerValue2, @Num2Text OUTPUT
	END
END






GO







CREATE procedure [dbo].[spSysTexts_getDataById]
(
	@lang_id int, @page_id int
)
as

/*declare @lang_id int, @page_id int
select	@lang_id = 2, @page_id = 48*/

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

SELECT		t.lang_id,
			t.page_id,
			p.[page_desc],
			t.ctrl_id,
			c.[ctrl_desc],
			t.type_id,
			y.[type_desc],
			t.prop_id,
			r.[prop_desc],
			t.fun_id,
			t.text_desc

FROM        tbsysTexts t
			inner join [tbsysPages] p on p.[page_id] = t.page_id
			inner join [tbsysControls] c on c.[ctrl_id] = t.ctrl_id
			inner join [tbsysTypes] y on y.[type_id] = t.type_id
			inner join [tbsysProperties] r on r.[prop_id] = t.prop_id

WHERE		t.lang_id = @lang_id and t.page_id = @page_id

ORDER BY lang_id, page_id, ctrl_id, type_id, prop_id, fun_id
GO







CREATE procedure [dbo].[spSysTexts_getDataByText]
(
	@text		NVARCHAR(50),
	@count		INT,
	@lang_id	INT
)
as
SET NOCOUNT ON



/*
DECLARE	@text		NVARCHAR(50),
		@count		INT,
		@lang_id	INT
SELECT	@text		= '[R',
		@count		= 10,
		@lang_id	= 2
*/

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


SET @text = REPLACE(@text,'[','[[]')
--SET @text = REPLACE(@text,']','[]]')
--SELECT	@text



SELECT		TOP (@count)
			t.word_desc,
			t.wordsi_id
FROM        tbSysWordsNew	t
WHERE		t.lang_id	=		@lang_id
AND			t.word_desc	LIKE	@text + '%'

ORDER BY	t.word_desc


GO








CREATE PROCEDURE [dbo].[spSysTexts_getTextForControl]
(
	@lang_id			int,
	@page_id			int,
	@type_id			int,
	@ctrl_id			int,
	@fun_id				int
)
as
set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

/*
declare	@lang_id		int,
		@page_id		int,
		@type_id		int,
		@ctrl_id		int,
		@fun_id			int
select	@lang_id		=2,
		@page_id		=15,
		@type_id		=1,
		@ctrl_id		=253,
		@fun_id			=1
*/



select	T.page_id		,
		P.page_desc		,
		T.ctrl_id		,
		C.ctrl_desc		,
		T.[type_id]		,
		Ty.type_desc	,
		T.prop_id		,
		Pr.prop_desc	,
		tswn.word_desc  [text_desc]
		--T.text_desc

from	dbo.tbSysTextsNew					T
		inner join dbo.tbSysPages			P
		on	P.page_id		= T.page_id
		inner join dbo.tbSysControls		C
		on	C.ctrl_id		= T.ctrl_id
		inner join dbo.tbSysTypes			Ty
		on	Ty.[type_id]	= T.[type_id]
		inner join dbo.tbSysProperties		Pr
		on	Pr.prop_id		= T.prop_id
		INNER JOIN tbSysWordsNew			tswn
		ON	tswn.lang_id	= @lang_id
		AND tswn.wordsi_id	= t.wordsi_id

where	--T.lang_id			= @lang_id
--and
		T.page_id			= @page_id
and		T.[type_id]			= @type_id
and		T.ctrl_id			= @ctrl_id
and		T.fun_id			= @fun_id




GO






