CREATE PROCEDURE [dbo].[spSysVideos_getData]
(
	@lang_id int
)
AS
SET NOCOUNT ON


/*
declare @lang_id int
select	@lang_id = 2
*/




SELECT  tv.sv_id,
		tl.lang_desc,
		tv.sv_Name,
		tv.sv_link,
		tv.optval_id,
		tov.optval_desc,
		IsNull(tv.sv_content,'')  [sv_content],
		tv.sv_order

from	tbsysVideos								tv

		inner join tbsysLanguage				tl
		on		tv.lang_id			= tl.lang_id

		inner join tbsysOptionsValues			tov
		on		tov.optval_id		= tv.optval_id
		and		tov.lang_id			= @lang_id
		and		tov.optval_class	= 200

where tv.lang_id = @lang_id AND tv.sv_disabled = 'False'

ORDER BY tov.optval_order, TV.optval_id,tv.sv_order

GO









