CREATE procedure [dbo].[spSysView_Columns_getCombo]
(
	@name		varchar(200),
	@quantity	int
)
as



set nocount on
/*
si @quantity = 0 retorna sólo los campos de sys.columns que no fueron cargados en la tabla tbSysFields
si @quantity = 1 retorna todos los registros de sys.columns
*/

/*
declare		@name			varchar(200),
			@quantity		int
select		@name			= '62',
			@quantity		= 0
*/

declare @table_name varchar(100)
select @table_name = table_desc from [tbsysTables] where [table_id] = convert(int,ltrim(rtrim(@name)))
--select @table_name

if (@quantity = 0)
	begin
		select	c.column_id		[id],
				c.name			[desc]

		from	sys.tables				t

				inner join sys.columns	c
				on c.object_id = t.object_id

		where	t.name	= @table_name
		and	    c.name not in (	select	f.[field_name]
								from	[tbSysTables]				tt
										inner join [tbsysFields]	f
										on f.[table_id] = tt.table_id
								where	tt.table_id	= @name )
	end
else
	begin
		select	c.column_id		[id],
				c.name			[desc]

		from	sys.tables				t

				inner join sys.columns	c
				on c.object_id = t.object_id

		where	t.name	= @table_name
	end
GO






