CREATE PROCEDURE [dbo].[spSysWordsNew_getIdByDesc]
(
	@desc			NVARCHAR(4000)
)
AS

BEGIN

-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 500
SET DEADLOCK_PRIORITY LOW
-- -----------------------------------------------------------------------------


	SET NOCOUNT ON

	/*

	DECLARE @desc		NVARCHAR(4000)
	SET @desc ='Tipo de Costo.'
	*/

	IF EXISTS (SELECT	1
			   FROM	    tbSysWordsNew tswn
			   WHERE	LTRIM(RTRIM(tswn.word_desc)) = LTRIM(RTRIM(@desc))
			   AND		tswn.lang_id = 2)

		BEGIN

			SELECT	top 1 tswn.wordsi_id		[ID]
			FROM	tbSysWordsNew tswn
			WHERE	LTRIM(RTRIM(tswn.word_desc)) = LTRIM(RTRIM(@desc))
			AND		tswn.lang_id = 2

		END
	ELSE
		BEGIN

			INSERT INTO tbSysWordsIni
			(
			 wordsi_enabled
			)
			VALUES
			(
			'true'
			)

			DECLARE @id AS INT
			SET @id = @@IDENTITY

			INSERT tbSysWordsNew
			(
			 lang_id,
			 wordsi_id,
			 word_desc,
			 wordn_isTranslated,
			 wordn_translateDate
			)
			VALUES
			(
			 2,
			 @id,
			 @desc,
			 NULL,
			 NULL
			)

			SELECT @id

		END

		/*
	if @@ROWCOUNT = 0
	BEGIN



	--	--primero insertar en dbo.tbSysWordsIni
	--	--recuperar	@@IDENTITY
	--	--insertar en dbo.tbSysWordsNew con lenguaje 2, el id recuperado, la descripción recibida
	--	--devolver el id recuperado
	--
	END
	*/


END
GO




