CREATE PROCEDURE spTableButtonsDisabled4Profiles_getDataById

	@comp_id	AS INT,
	@bra_id		AS INT,
	@prof_id	AS INT,
	@table_id	AS INT,
	@intType	AS INT

AS
BEGIN

	SET NOCOUNT ON;


	IF EXISTS(	SELECT 1
	          		FROM	tbTableButtonsDisabled4Profiles ttbdp	WITH (NOLOCK)
	          		WHERE	ttbdp.comp_id	= @comp_id	AND
	          				ttbdp.bra_id	= @bra_id	AND
	          				ttbdp.prof_id	= @prof_id	AND
	          				ttbdp.table_id	= @table_id AND
	          				ttbdp.acc_type	= @intType
			)
		SELECT 'True'
	ELSE
		SELECT 'False'

END
GO






