-- =============================================
-- Author:		MOS
-- Description:	Pone un ID de Ultima Actualizacion para poder retornar por ejemplo en un ws los ULTIMOS modificados desde un determinado ID.
-- =============================================
CREATE PROCEDURE [dbo].[spTableLastUpdate_updateData]
	@comp_id AS INT,
	@table_id AS INT,
	@item_id AS INT,
	@prli_id AS INT,
	@stor_id AS INT,
	@user_id AS INT
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 50
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	IF @comp_id IS NULL RETURN


	BEGIN TRY

		DECLARE @lastUpdate AS BIGINT = 0
		SELECT	@lastUpdate = ISNULL(MAX(lastUpdate),0) + 1
			FROM tbTableLastUpdate		WITH (NOLOCK)

		--UPDATE tbSystem_DatabaseVersion
		--	SET	lastUpgrade = lastUpgrade + 1
		--SELECT TOP 1 @lastUpdate = lastUpgrade
		--	FROM  tbSystem_DatabaseVersion	WITH (NOLOCK)

		-- ----------------------------------
		-- Actualizar SOLO lo que corresponda
		-- ----------------------------------

		-- Si es de Articulos
		IF @stor_id IS NULL AND @prli_id IS NULL
			BEGIN
				UPDATE tbTableLastUpdate		WITH (ROWLOCK)
					SET
						lastUpdate	= @lastUpdate,
						lastUpdateCD= GETDATE(),
						[user_id]	= @user_id
				WHERE	comp_id		= @comp_id	AND
						table_id	= @table_id AND
						item_id		= @item_id	AND
						stor_id		IS NULL		AND
						prli_id		IS NULL

				IF @@ROWCOUNT = 0
					BEGIN
						INSERT INTO tbTableLastUpdate(	comp_id,
														table_id,
														item_id,
														stor_id,
														prli_id,
														lastUpdate,
														lastUpdateCD,
														[user_id]		)
							VALUES(	@comp_id,
									@table_id,
									@item_id,
									NULL,
									NULL,
									@lastUpdate,
									GETDATE(),
									@user_id)
					END

				RETURN

			END


		-- Si es de Depositos
		IF @stor_id IS NOT NULL AND @prli_id IS NULL
			BEGIN
				UPDATE tbTableLastUpdate		WITH (ROWLOCK)
					SET
						lastUpdate	= @lastUpdate,
						lastUpdateCD= GETDATE(),
						[user_id]	= @user_id
				WHERE	comp_id		= @comp_id	AND
						table_id	= @table_id AND
						item_id		= @item_id	AND
						stor_id		= @stor_id

				IF @@ROWCOUNT = 0
					BEGIN
						INSERT INTO tbTableLastUpdate(	comp_id,
														table_id,
														item_id,
														stor_id,
														prli_id,
														lastUpdate,
														lastUpdateCD,
														[user_id]		)
							VALUES(	@comp_id,
									@table_id,
									@item_id,
									@stor_id,
									NULL,
									@lastUpdate,
									GETDATE(),
									@user_id)
					END

				RETURN

			END


		-- Si es de Lista de Precios
		IF @stor_id IS NULL AND @prli_id IS NOT NULL
			BEGIN
				UPDATE tbTableLastUpdate		WITH (ROWLOCK)
					SET
						lastUpdate	= @lastUpdate,
						lastUpdateCD= GETDATE(),
						[user_id]	= @user_id
				WHERE	comp_id		= @comp_id	AND
						table_id	= @table_id AND
						item_id		= @item_id	AND
						prli_id     = @prli_id

				IF @@ROWCOUNT = 0
					BEGIN
						INSERT INTO tbTableLastUpdate(	comp_id,
														table_id,
														item_id,
														stor_id,
														prli_id,
														lastUpdate,
														lastUpdateCD,
														[user_id]		)
							VALUES(	@comp_id,
									@table_id,
									@item_id,
									NULL,
									@prli_id,
									@lastUpdate,
									GETDATE(),
									@user_id)
					END

				RETURN

			END
		-- ----------------------------------





	END TRY
	BEGIN CATCH
	END CATCH

END
GO







