--------------------------------------------------------------------------

create PROCEDURE [dbo].[spTariffPosition_Auto_Validate]
(

	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,

	@posara_desc				NVARCHAR(200),
    @posara_code				NVARCHAR(15),
    @tax_id4IVA					INT,

	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,


	@guid						UNIQUEIDENTIFIER,
	@intROW						INT



SELECT
	@comp_id					INT,

	@lang_id					INT,
	@bra_id4session				INT,
	@user_id					INT,
	@prof_id					INT,



	@guid						UNIQUEIDENTIFIER,
	@intROW						INT

*/
---------------------------------------------------------------------------------


set nocount on

BEGIN
	DECLARE @errormessage   NVARCHAR(4000)
	DECLARE @return_value	INT
	DECLARE @bolIsOK		BIT

	SET     @bolIsOK		= 'True'
	SET		@errormessage	= ''


	------Desc-----------------------------------------------------------------------------------------------------------
	if	@posara_desc	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó la Descripción'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------Code-----------------------------------------------------------------------------------------------------------
	if	@posara_code	= ''
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el Código'
		END
	-----------------------------------------------------------------------------------------------------------------------


	------IMPUESTO-----------------------------------------------------------------------------------------------------------
	if	@tax_id4IVA	= -1
		BEGIN
			SET	@bolIsOK		= 'False'
			SET @errormessage	= @errormessage + '---' + 'No ingresó el ID de Impuesto'
		END
	ELSE
		BEGIN
			IF NOT EXISTS (SELECT tpc.tax_id
			               FROM tbTaxName tpc		WITH (NOLOCK)
							WHERE	tpc.comp_id		= @comp_id		AND
									tpc.tax_id		= @tax_id4IVA)
			BEGIN
				SET	@bolIsOK		= 'False'
				SET @errormessage	= @errormessage + '---' + 'El ID de Impuesto es incorrecto'
			END
		END

	-----------------------------------------------------------------------------------------------------------------------

	-- 1 True  : Todo ok para insertar.
	-- 0 False : Hay uno o varios registros que estan mal por ende no se puede realizar la importacion.
	IF @bolIsOK = 'True'
		BEGIN
			SELECT
				1				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END
	ELSE
		BEGIN

			EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,NULL,@errormessage

			SELECT
				0				[bolIsOK],
				@intROW			[Nº Fila],
				@errormessage	[Error]
		END


END


















GO





