CREATE PROCEDURE [dbo].[sptariffPosition_Process_Auto]
(

	@comp_id						INT,
	@lang_id						INT,
	@bra_id4session					INT,
	@user_id						INT,
	@prof_id						INT,

	@posara_desc					NVARCHAR(200),
    @posara_code					NVARCHAR(15),
    @posara_dutiesPercentage		DECIMAL(10,6),
    @posara_statisticsPercentage	DECIMAL(10,6),
    @posara_statisticsMaxValue		DECIMAL(21,8),
    @posara_hasInternalTaxes		BIT,
    @posara_hasDumping				BIT,
    @posara_hasNoAutomaticLicense	BIT,
    @tax_id4IVA						INT,

	@guid							UNIQUEIDENTIFIER,
	@intROW							INT,
	@bolIsOK						BIT




)
AS



---------------------------------------------------------------------------------
-- PARAMETROS DE TESTING
---------------------------------------------------------------------------------
/*
DECLARE
	@comp_id						INT,
	@lang_id						INT,
	@bra_id4session					INT,
	@user_id						INT,
	@prof_id						INT,

	@posara_desc					NVARCHAR(200),
    @posara_code					NVARCHAR(15),
    @posara_dutiesPercentage		DECIMAL,
    @posara_statisticsPercentage	DECIMAL,
    @posara_statisticsMaxValue		DECIMAL,
    @posara_hasInternalTaxes		BIT,
    @posara_hasDumping				BIT,
    @posara_hasNoAutomaticLicense	BIT,
    @tax_id4IVA						INT,

	@guid							UNIQUEIDENTIFIER,
	@intROW							INT,
	@bolIsOK						BIT



SELECT
	@comp_id					= 1 ,

	@lang_id					= 2 ,
	@bra_id						= 1 ,
	@user_id					= 1 ,
	@prof_id					= 1 ,


	@guid						='01b880c3-a129-4675-8da0-3ac973b68132',
	@intROW						= 10

*/
---------------------------------------------------------------------------------


set nocount on



BEGIN
	declare @return_value	INT




		IF EXISTS (
					SELECT
						TOP 1 tbitp.posara_id
						FROM tbImport_tariffPosition				tbitp WITH(NOLOCK)
						WHERE	tbitp.comp_id		= @comp_id		AND
								tbitp.posara_code	= @posara_code
					)


				BEGIN

					DECLARE @lposara_id AS INT
					SET @lposara_id = (SELECT
											TOP 1 tbitp.posara_id
											FROM tbImport_tariffPosition				tbitp WITH(NOLOCK)
											WHERE	tbitp.comp_id		= @comp_id		AND
													tbitp.posara_code	= @posara_code
										 )


					UPDATE tbImport_tariffPosition
					SET
						posara_desc						= @posara_desc,
						posara_dutiesPercentage			= @posara_dutiesPercentage,
						posara_statisticsPercentage		= @posara_statisticsPercentage,
						posara_statisticsMaxValue		= @posara_statisticsMaxValue,
						posara_hasInternalTaxes			= @posara_hasInternalTaxes,
						posara_hasDumping				= @posara_hasDumping,
						posara_hasNoAutomaticLicense	= @posara_hasNoAutomaticLicense,
						tax_id4IVA						= @tax_id4IVA

					WHERE	comp_id		= @comp_id		AND
							posara_id	= @lposara_id
				END

		ELSE
			BEGIN


				BEGIN TRY


					INSERT INTO tbImport_tariffPosition
					(
						comp_id,
						posara_desc,
						posara_code,
						posara_dutiesPercentage,
						posara_statisticsPercentage,
						posara_statisticsMaxValue,
						posara_hasInternalTaxes,
						posara_hasDumping,
						posara_hasNoAutomaticLicense,
						tax_id4IVA
					)
					VALUES
					(
						@comp_id,
						@posara_desc,
						@posara_code,
						@posara_dutiesPercentage,
						@posara_statisticsPercentage,
						@posara_statisticsMaxValue,
						@posara_hasInternalTaxes,
						@posara_hasDumping,
						@posara_hasNoAutomaticLicense,
						@tax_id4IVA
					)


					set	@return_value = IDENT_CURRENT('tbImport_tariffPosition')  -- @@identity

					END TRY
					BEGIN CATCH
						set	@return_value = 0
					END CATCH

					--IF @return_value <> 0
					--	BEGIN
					--		EXEC [spItems_Process_ImportLog_InsertData] @comp_id,@guid,@user_id,@intROW,@return_value,NULL

					--		--	EXEC [spSysScript_Suppliers_Cities]


					--	END


			END


END


















GO



-------------------------------------------

CREATE PROCEDURE [dbo].[spTariffPosition_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------

BEGIN



	SELECT
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO







