CREATE PROCEDURE [dbo].[spTaxFree4Customers_getAData]
(
	@comp_id	INT,
	@cust_id	INT,
	@bra_id		INT
)
AS

SET NOCOUNT ON


-----------------------------------------------------------------------------
/*
DECLARE @comp_id	INT,
		@cust_id	INT,
		@bra_id		INT

SELECT	@comp_id	= 1,
		@cust_id	= 24311,
		@bra_id		= 1
*/
-----------------------------------------------------------------------------



SELECT
	ttn.tax_id [ID],
	ttn.tax_desc + ' - ' + isnull(tb.bra_desc,'Todos') + ' - ' + replace(convert(varchar,ttfc.percentaje),'.',',') + ' %' + ' - ' +  convert(varchar,isnull(ttfc.tffc_up2Date,getdate()),106)[desc]

FROM	dbo.tbTaxFree4Customers ttfc

INNER JOIN	dbo.tbTaxName ttn
ON			ttn.tax_id = ttfc.tax_id

INNER JOIN	tbCustomer tc
ON			tc.cust_id	= ttfc.cust_id

LEFT JOIN dbo.tbBranch tb
ON			tb.bra_id	= ttfc.bra_id

WHERE      ttfc.comp_id = @comp_id	AND
		   ttfc.cust_id = @cust_id	AND
		   (@bra_id	 = -1 OR ttfc.bra_id = @bra_id)

GO





