CREATE PROCEDURE spTaxFree4Customers_InsertSecLogData
(
	@comp_id	INT,
	@bra_id		INT,
	@taxbra_id	INT,
	@prof_id	INT,
	@user_id	INT,
	@cust_id	INT,
	@tax_id		INT,
	@percentage	DECIMAL(19,4),
	@Date		DATETIME,
	@isInsert	BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- --------------------------------------------------------
		-- TESTING
		-- --------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@taxbra_id	INT,
				@prof_id	INT,
				@user_id	INT,
				@cust_id	INT,
				@tax_id		INT,
				@percentage	DECIMAL(19,4),
				@Date		DATETIME,
				@isInsert	BIT
		*/
		-- --------------------------------------------------------


		SET DATEFORMAT 'ymd'
		-- --------------------------------------
		-- Variables de Trabajo
		-- --------------------------------------
		DECLARE
			@lCustName			NVARCHAR(100),
			@lBranchDesc		NVARCHAR(100),
			@lTaxDesc			NVARCHAR(100),
			@lMessage			NVARCHAR(2000)
		-- --------------------------------------

		-- --------------------------------------
		-- Recupero los datos del Cliente
		-- --------------------------------------
		SELECT
			@lCustName = CONVERT(VARCHAR,@cust_id) + ' - ' + tc.cust_name
			FROM tbCustomer					AS tc WITH(NOLOCK)
			WHERE	tc.comp_id = @comp_id	AND
					tc.cust_id = @cust_id
		-- --------------------------------------

		-- --------------------------------------
		-- Recupero los datos del Impuesto
		-- --------------------------------------
		SELECT
			@lTaxDesc = CONVERT(VARCHAR,@tax_id) + ' - '  + ttn.tax_desc
			FROM tbTaxName AS ttn WITH(NOLOCK)
			WHERE	ttn.comp_id = @comp_id AND
					ttn.tax_id	= @tax_id
		-- --------------------------------------

		-- --------------------------------------
		-- Recupero los Datos de la Sucursal
		-- --------------------------------------
		IF @taxbra_id = -1
			BEGIN
				SET @lBranchDesc = 'Todas'
			END
		ELSE
			BEGIN
				SELECT
					@lBranchDesc = CONVERT(VARCHAR,@bra_id) + ' - ' + tb.bra_desc
					FROM tbBranch					AS tb	WITH(NOLOCK)
					WHERE	tb.comp_id	= @comp_id	AND
							tb.bra_id	= @bra_id
			END
		-- --------------------------------------
		IF @isInsert = 'True'
			BEGIN
				SET @lMessage = ' Se ha insertado para el Cliente: '	+ @lCustName +
								' Sucursal de Asignación: '				+ @lBranchDesc +
								' Impuesto Asignado: '					+ @lTaxDesc +
								' Porcentaje de Exención: '				+ CONVERT(VARCHAR,@percentage) +
								' Válido hasta Fecha: '					+ CONVERT(VARCHAR,@Date)
			END
		ELSE
			BEGIN
				SET @lMessage = ' Se ha eliminado para el Cliente: '	+ @lCustName +
								' Sucursal de Asignación: '				+ @lBranchDesc +
								' Impuesto Asignado: '					+ @lTaxDesc

			END


		INSERT INTO tbSecurityLog
		(
			comp_id,
			bra_id,
			user_id,
			seclog_obs_1,
			seclog_obs_2,
			seclog_image,
			seclog_obs_3,
			seclog_obs_4,
			seclog_cd,
			aut_id,
			sysCode_id,
			menu_id,
			menu_ts,
			request_ip,
			request_name,
			aure_isok,
			aure_user_id,
			seclog_pageHTML,
			prof_id,
			aure_cd,
			aure_id,
			seclog_id1,
			seclog_id2,
			seclog_id3
		)
		VALUES
		(
			@comp_id,
			@bra_id,
			@user_id,
			@lMessage,
			NULL,
			NULL,
			NULL,
			NULL,
			GETDATE(),
			NULL,
			2900,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL,
			@prof_id,
			NULL,
			NULL,
			NULL,
			NULL,
			NULL
		)

	END



GO





