CREATE PROCEDURE [dbo].[spTaxFree4Suppliers_getAData]
(
	@supp_id	INT,
	@bra_id		INT
)
AS


SET NOCOUNT ON

/*
DECLARE
	@supp_id	INT,
	@bra_id		INT

SELECT
	@supp_id	= 8103,
	@bra_id		= 134

*/

DECLARE @comp_id AS INT
SELECT @comp_id = tb.comp_id
	FROM tbBranch tb
	WHERE tb.bra_id = @bra_id




SELECT
	ttn.tax_id [ID],
	ttn.tax_desc + ' - ' + tb.bra_desc + ' - ' + replace(convert(varchar,ttfs.percentaje),'.',',') + ' %' + ' - ' +  convert(varchar,isnull(ttfs.tffs_up2Date,getdate()),106) [desc]

FROM	dbo.tbTaxFree4Suppliers ttfs

INNER JOIN	dbo.tbTaxName ttn
ON			ttn.tax_id = ttfs.tax_id

INNER JOIN	dbo.tbSupplier ts
ON			ts.supp_id	= ttfs.supp_id

INNER JOIN dbo.tbBranch tb
ON			tb.bra_id	= ttfs.bra_id

WHERE	ttfs.supp_id = @supp_id
AND		(@bra_id	 = -1 OR ttfs.bra_id = @bra_id)
AND ttn.comp_id = @comp_id

GO





CREATE PROCEDURE [dbo].[spTaxFree4Suppliers_getUData]
(
	@supp_id	INT,
	@bra_id		INT
)
