create PROCEDURE [dbo].[spTAXI_Cars_GetHistoryData]
(
	@comp_id	INT,
	@lang_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@txcar_id	INT
)
as set nocount on





-- -----------------------------------------------
-- Testing
-- -----------------------------------------------
/*
	declare
		@comp_id	INT,
		@txcar_id	INT
	select
		@comp_id	= 1,
		@txcar_id	= 1
*/
-- -----------------------------------------------


select  ttch.txau_brand,
		ttch.txau_model,
		ttch.txau_type,
		ttch.txau_domain,
		ttch.txau_engine,
		ttch.txau_chassis,
		ttch.txau_yearOfMade,
		ttrt.txrt_desc,
		ttch.txau_radioNumber,
		ttch.txau_licenseNumber,
		ttch.txau_licenseExpirationDate,
		ttch.txau_tecnicalNumber,
		ttch.txau_tecnicalExpirationDate,
		ttch.txau_insuranceNumber,
		ttch.txau_insuranceExpirationDate,
		ttc2.txem_name,
		ttch.txau_purchaseDate,
		ttch.txau_saleDate


from tbTAXI_CarsHistory ttch


	inner join tbTAXI_Cars ttc
	on	ttc.comp_id  = ttch.comp_id
	AND ttc.txcar_id = ttch.txcar_id

	inner join tbTAXI_Company ttc2
	on  ttc2.comp_id = ttc.comp_id
    AND ttc2.txem_id = ttc.txem_id

	inner join tbTAXI_RadioTaxi ttrt
	on  ttrt.comp_id = ttc.comp_id
    AND ttrt.txrt_id = ttc.txrt_id



where	ttch.comp_id  = @comp_id
and		ttch.txcar_id = @txcar_id
GO











