CREATE PROCEDURE [dbo].[spTaxIBCustomer_ForSales_deleteData]
(
	@comp_id			int,
	@bra_id				int,
	@cust_id			int,
	@country_id			INT,
	@state_id			INT

)

AS

BEGIN



	set nocount on

	-- ---------------------------------------------
	-- ---------------------------------------------
	/*
	declare
		@comp_id			int,
		@bra_id				int,
		@cust_id			int,
		@country_id			INT,
		@state_id			INT


	select
		@comp_id			=1,
		@bra_id				=1,
		@cust_id			=24288,
		@country_id			=54,
		@state_id			=54017
	*/
		-- ---------------------------------------------


	IF @bra_id = -1 SET @bra_id = null

	DELETE dbo.tbTaxIBCustomers_ForSales
	where	comp_id			= @comp_id
	AND		(
				bra_id			= @bra_id OR
			   	(
			   		bra_id IS NULL
			   			AND
			   		@bra_id IS NULL
			   	)
			)
	and     cust_id			= @cust_id
	and		country_id		= @country_id
	AND		state_id		= @state_id



	UPDATE tbcustomer	WITH (ROWLOCK)
		SET cust_hasCM05Configurations =	CASE
												WHEN ttifs.comp_id IS NULL THEN 0
												ELSE							1
											END
		FROM tbCustomer						tc
		LEFT JOIN tbTaxIBCustomers_ForSales ttifs		WITH (NOLOCK)
			ON	ttifs.comp_id = tc.comp_id AND
				ttifs.cust_id = tc.cust_id
		WHERE	tc.comp_id = @comp_id AND
				tc.cust_id = @cust_id


END
GO






CREATE PROCEDURE [dbo].[spTaxIBCustomers_ForSales_getAData]
(
	@cust_id	INT
)
AS

SET NOCOUNT ON

/*
DECLARE
	@cust_id	INT

SELECT
	@cust_id	= 24294

*/


SELECT
	ttifs.state_id [ID],
	ts.state_desc + ' - ' + CONVERT(VARCHAR,ttifs.percentaje) + '%' + ' - ' + isnull(tb.bra_desc,'Todos') [desc]

FROM	dbo.tbTaxIBCustomers_ForSales ttifs

INNER JOIN	tbsysState ts
ON			ts.state_id		= ttifs.state_id

--antes hacia join con el COUNTRY ID, por si se quiere volver el cambio hacia atras
INNER JOIN	tbCustomer tc
ON	tc.cust_id	= ttifs.cust_id

LEFT JOIN tbBranch tb
ON	tb.comp_id	= ttifs.comp_id AND
	tb.bra_id	= ttifs.bra_id

WHERE	ttifs.cust_id = @cust_id
AND		tc.stcIB_Id	  = 10

ORDER BY [desc]
GO







CREATE PROCEDURE [dbo].[spTaxIBCustomers_ForSales_getUData]
(
	@cust_id	INT
)
AS

SET NOCOUNT ON

/*
DECLARE
	@cust_id	INT

SELECT
	@cust_id	=24288

*/
SELECT
	ts.state_id [ID],
	ts.state_desc [desc]

FROM	dbo.tbsysCountry tc

INNER JOIN	tbsysState ts
ON		ts.country_id	= tc.country_id

INNER JOIN	tbCustomer tc2
ON		tc2.country_id	= tc.country_id

WHERE	tc2.cust_id	= @cust_id
AND		tc2.stcIB_Id = 10
AND		ts.state_id NOT IN (SELECT
							ttifs.state_id
							FROM	dbo.tbTaxIBCustomers_ForSales ttifs
							INNER JOIN	tbsysState ts
							ON			ts.state_id		= ttifs.state_id
							INNER JOIN	tbCustomer tc
							ON			tc.country_id	= ttifs.country_id
							WHERE	ttifs.cust_id = @cust_id
							AND		tc.stcIB_Id	  = 10)


ORDER BY [desc]
GO





CREATE PROCEDURE [dbo].[spTaxIBCustomers_ForSales_insertData]
(
	@comp_id	INT,
	@bra_id		INT,
	@cust_id	INT,
	@country_id	INT,
	@state_id	INT,
	@percentaje	DECIMAL(19,4)
)
AS

BEGIN


	set nocount on

	-- ---------------------------------------------
	-- ---------------------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@cust_id	INT,
		@country_id	INT,
		@state_id	INT,
		@percentaje	DECIMAL

	SELECT
		@comp_id	=1,
		@bra_id		=1,
		@cust_id	=24288,
		@country_id	=54,
		@state_id	=54003,
		@percentaje	=50
	*/
	-- ---------------------------------------------
	IF @bra_id = -1 SET @bra_id = null

	INSERT  INTO 	dbo.tbTaxIBCustomers_ForSales
			(comp_id,
			bra_id,
			cust_id,
			country_id,
			state_id,
			percentaje)

	VALUES
			(@comp_id,
			@bra_id,
			@cust_id,
			@country_id,
			@state_id,
			@percentaje)


	UPDATE tbcustomer	WITH (ROWLOCK)
		SET cust_hasCM05Configurations =	CASE
												WHEN ttifs.comp_id IS NULL THEN 0
												ELSE							1
											END
		FROM tbCustomer						tc
		LEFT JOIN tbTaxIBCustomers_ForSales ttifs		WITH (NOLOCK)
			ON	ttifs.comp_id = tc.comp_id AND
				ttifs.cust_id = tc.cust_id
		WHERE	tc.comp_id = @comp_id	AND
				tc.cust_id = @cust_id


END
GO





