CREATE PROCEDURE [dbo].[spTaxIBSuppliers_ForPayment_getAData]
(
	@supp_id	INT
)
AS

SET NOCOUNT ON

/*
DECLARE
	@supp_id	INT

SELECT
	@supp_id	=8103
*/


SELECT
	ttifs.state_id [ID],
	ts.state_desc + ' - ' + CONVERT(varchar,ttifs.percentaje) + '%' [desc]

FROM	dbo.tbTaxIBSuppliers_ForPayment ttifs

--INNER JOIN	tbSupplier tc
--ON	tc.country_id	= ttifs.country_id

INNER JOIN	tbsysState ts
ON	ts.state_id		= ttifs.state_id


WHERE	ttifs.supp_id = @supp_id
--AND		tc.stcIB_Id	  = 10

ORDER BY [desc]
GO






CREATE PROCEDURE [dbo].[spTaxIBSuppliers_ForPayment_getUData]
(
	@supp_id	INT
)
AS

SET NOCOUNT ON

/*
DECLARE
	@supp_id	INT

SELECT
	@supp_id	=8106

*/

SELECT
	ts.state_id [ID],
	ts.state_desc [desc]

FROM	dbo.tbsysCountry tc

INNER JOIN	tbsysState ts
ON		ts.country_id	= tc.country_id

INNER JOIN	dbo.tbSupplier ts2
ON		ts2.country_id	= tc.country_id

WHERE	ts2.supp_id	 = @supp_id
AND		ts2.stcIB_id = 10
AND		ts.state_id NOT IN (SELECT
							ttifs.state_id
							FROM	dbo.tbTaxIBSuppliers_ForPayment ttifs
							INNER JOIN	tbsysState ts
							ON			ts.state_id		= ttifs.state_id
							INNER JOIN	tbSupplier tc
							ON			tc.country_id	= ttifs.country_id
							WHERE		ttifs.supp_id	= @supp_id
							AND			tc.stcIB_Id		= 10)

ORDER BY [desc]
GO







CREATE PROCEDURE [dbo].[spTaxMovement_getReport]
(
	@comp_id			INT,
	@lang_id			INT,
    @page_id			INT,
    @tax_id				INT,
    @bg_id				INT,
    @user_id			INT,
	@tax_datefrom		DATETIME,
    @tax_dateto			DATETIME,
    @ct_datefrom		DATETIME,
	@ct_dateto			DATETIME,
	@guid_cust			VARCHAR(50),
	@guid_supp  		VARCHAR(50),
    @option				INT,
    @bra_id				INT,
	@intBranch4Lang		INT,
	@DocumentType		INT				-- TODOS = -1 / FACTURAS = 1 / NOTAS DE CRÉDITO = 2 / NOTAS DE DÉBITO = 3

)
AS


BEGIN



	SET NOCOUNT ON

	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------


	--------------------------------------------------------------------------------
	-- PARAMETROS PARA PRUEBAS -----------------------------------------------------
	--------------------------------------------------------------------------------
/*
	DECLARE
			@comp_id      AS INT,
			@lang_id      AS INT,
			@page_id      AS INT,
			@tax_id		  AS INT,
			@ct_dateto    AS DATETIME,
			@ct_datefrom  AS DATETIME,
			@tax_dateto   AS DATETIME,
			@tax_datefrom AS DATETIME,
			@bg_id        AS INT,
			@option		  AS INT,
			@user_id      AS INT,
			@bra_id		  AS INT,
			@intBranch4Lang	 int,
			@DocumentType		INT	,
			@guid_cust			VARCHAR(50),
			@guid_supp  		VARCHAR(50)


	SELECT  @comp_id		= 1,
			@lang_id		= 2,
			@page_id		= 10063,
			@tax_id			= 142,
		    @ct_datefrom	= '2019-01-01',
			@ct_dateto		= '9999-12-31',
		    @tax_datefrom	= '2019-01-01',
			@tax_dateto		= '9999-12-31',
		    @bg_id			= 5,
			@option			= 1,	--	0-Compras  1-Ventas
			@user_id		= 1,
			@bra_id			= -1,
			@DocumentType   = -1

			DROP TABLE #TmpQuery
*/
	--------------------------------------------------------------------------------






	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Clientes para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @lGuid_Cust AS UNIQUEIDENTIFIER
	SET @lGuid_Cust = CONVERT(UNIQUEIDENTIFIER,@guid_cust)
	DECLARE @tblComplexFilter_Customer TABLE (cust_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Customer
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid_Cust     AND
						  tcf.sl_selected = 'True'
	--IF @@ROWCOUNT = 0
	--	BEGIN
	--		INSERT INTO @tblComplexFilter_Customer
	--			SELECT tc.cust_id
	--			FROM tbCustomer tc
	--				WHERE tc.comp_id = @comp_id
	--	END
	-- -------------------------------------------------------------


	-- -------------------------------------------------------------
	-- Tabla Temporal para hacer JOIN de Proveedores para Filtros #8600
	-- -------------------------------------------------------------
	DECLARE @lGuid_Supp AS UNIQUEIDENTIFIER
	SET @lGuid_Supp = CONVERT(UNIQUEIDENTIFIER,@guid_supp)
	DECLARE @tblComplexFilter_Supplier TABLE (supp_id INT PRIMARY KEY)
	INSERT INTO @tblComplexFilter_Supplier
		SELECT tcf.sl_id
			FROM tbComplexFilter tcf
			WHERE tcf.sl_guid = @lGuid_Supp     AND
						  tcf.sl_selected = 'True'
	--IF @@ROWCOUNT = 0
	--	BEGIN
	--		INSERT INTO @tblComplexFilter_Supplier
	--			SELECT ts.supp_id
	--			FROM tbSupplier ts
	--				WHERE ts.comp_id = @comp_id
	--	END
	-- -------------------------------------------------------------




	set	@tax_datefrom	=  dbo.fnGetEnd_or_BeginOfDate( @tax_datefrom	,'False')
	set	@ct_datefrom	=  dbo.fnGetEnd_or_BeginOfDate( @ct_datefrom	,'False')
	set	@ct_dateto		=  dbo.fnGetEnd_or_BeginOfDate( @ct_dateto		,'True')
	set	@tax_dateto		=  dbo.fnGetEnd_or_BeginOfDate( @tax_dateto		,'True')

	SELECT
			IsNull(ttm.tm_docDate,tct.ct_taxDate)											[ct_taxDate],
			case
				WHEN @option = 0 THEN	case
											when ts.supp_name is null then	tba.ba_desc
											else							ts.supp_name
				                     	end

				ELSE					 tc.cust_name
			END																				[cust_name],
			case
				WHEN @option = 0 THEN	ts.supp_taxNumber
				ELSE					tc.cust_taxNumber
			END																				[cust_taxNumber],
			DBO.fnGetCommercialTransactionDescription(@comp_id,@lang_id,tct.ct_transaction)	[ct_desc],
			isnull(ttm.tm_docNumber,'')														[tm_docNumber],
			tct.ct_date																		[tm_cd],
			ttn.tax_desc,

			CASE WHEN td.sd_isCredit = 'true'
				THEN ttm.tm_subtotal * -1
				ELSE ttm.tm_subtotal
			END																				[tm_subtotal],
			ttm.percentaje																	[tax_percentage],

			CASE WHEN td.sd_isCredit = 'true'
				THEN ttm.tm_total * -1
				ELSE ttm.tm_total
			END																				[tm_total],
			isnull(ttm.tm_originalDocument,'')												[tm_originalDocument],
			ttn.tax_class,
			tct.cust_id,
			tct.supp_id

	INTO #TmpQuery

	FROM	tbTaxMovements										ttm

			INNER JOIN tbTaxName								ttn
			ON  ttn.tax_id			= ttm.tax_id
			AND ttn.comp_id			= ttm.comp_id

			INNER JOIN tbCommercialTransactions					tct
			ON  tct.comp_id			= ttm.comp_id
			--AND tct.bra_id          = ttm.bra_id
			AND tct.ct_transaction	= ttm.ct_transaction

--			left JOIN tbBranchGroupDetail						tbgd
--			ON	tbgd.comp_id		= ttm.comp_id
--			AND (@bg_id				= -1 OR  tbgd.brag_id = @bg_id)
--			AND tbgd.bra_id			= tct.bra_id

			left JOIN tbCustomer								tc
			ON	tc.comp_id			= tct.comp_id
			AND tc.cust_id			= tct.cust_id

			LEFT JOIN vwSupplier								ts
			ON	ts.comp_id			= tct.comp_id			AND
				ts.bra_id			= tct.bra_id			AND
				ts.ct_transaction	= tct.ct_transaction	AND
				ts.supp_id			= tct.supp_id



			INNER JOIN tbsysDocuments							td
			ON	td.sd_id			= tct.sd_id

			INNER JOIN tbUsers4BranchFilter						vubf
			ON	vubf.comp_id		= tct.comp_id
			AND vubf.bra_id			= tct.bra_id
			AND vubf.[user_id]		= @user_id

			left join tbBankingAccounts							tba
			on  tba.comp_id			= tct.comp_id
			AND tba.ba_id			= tct.ba_id



	WHERE	tct.comp_id			= @comp_id	AND
			ttn.tax_disabledInTaxMovementsReport = 'False'
	AND		(tct.sd_id IN (1,3,4,6,13,101,103,104,106,130,140,141,142, 31, 33))
	AND     (@tax_id			= -1 OR ttn.tax_id		= @tax_id)
	--AND     (@bg_id				= -1 OR tbgd.brag_id	= @bg_id )-- mos 02-2013
	AND     (@bg_id				= -1 OR EXISTS(	SELECT 1
	               				       		FROM tbBranchGroupDetail tbgd
	               				               		WHERE	tbgd.comp_id	= tct.comp_id	AND
	               				               				tbgd.bra_id		= tct.bra_id	AND
	               				               				tbgd.brag_id	= @bg_id) )
	AND 	ISNULL(tct.ct_taxDate,tct.ct_date) BETWEEN   @ct_datefrom AND       @ct_dateto
	AND		ISNULL(ttm.tm_docDate,ISNULL(tct.ct_taxDate,tct.ct_date)) BETWEEN   @tax_datefrom		AND    @tax_dateto
	AND     ((@option			= 0 AND td.sd_isPurchase = 'true')	OR
			(@option			= 1 AND td.sd_isPurchase = 'false'))
	AND		CASE
	   		    WHEN @DocumentType = -1  THEN 1
	   		    WHEN @DocumentType =  1 AND tct.sd_id IN (1,101) THEN 1			--Fc
	   		    WHEN @DocumentType =  2 AND tct.sd_id IN (3,103) THEN 1 	   	--Nc
	   			WHEN @DocumentType =  3 AND tct.sd_id IN (4,104) THEN 1			--Nd
	   		    ELSE						  0
	   		END = 1



	ORDER BY	ttm.tm_docDate,
				tct.ct_kindOf,
				tct.ct_pointOfSale,
				tct.ct_docNumber,
				ttn.tax_desc






	-- Borra los que NO NECESITA LISTAR
	IF @option = 0 AND EXISTS(	SELECT 1
									FROM @tblComplexFilter_Supplier)
		BEGIN
			DELETE FROM #TmpQuery
				FROM #TmpQuery tmp
				LEFT JOIN @tblComplexFilter_Supplier tmp2
					ON tmp.supp_id = tmp2.supp_id
				WHERE tmp2.supp_id IS NULL
		END
	ELSE if @option <> 0 AND
			EXISTS(	SELECT 1
						FROM @tblComplexFilter_Customer)
		BEGIN
			DELETE FROM #TmpQuery
				FROM #TmpQuery tmp
				LEFT JOIN @tblComplexFilter_Customer tmp2
					ON tmp.cust_id = tmp2.cust_id
				WHERE tmp2.cust_id IS NULL
		END




	SELECT	tmp.ct_taxDate,
			tmp.cust_name,
			tmp.cust_taxNumber,
			tmp.ct_desc,
			tmp.tm_docNumber,
			tmp.tm_cd,
			tmp.tax_desc,
			sum(tmp.tm_subtotal)		[tm_subtotal],
			tax_percentage,
			SUM(tmp.tm_total)			[tm_total],
			tmp.tm_originalDocument

		FROM #TmpQuery tmp

		GROUP BY
				tmp.tax_class,
				tmp.ct_taxDate,
				tmp.cust_name,
				tmp.cust_taxNumber,
				tmp.ct_desc,
				tmp.tm_docNumber,
				tmp.tm_cd,
				tmp.tax_percentage,
				tmp.tax_desc,
				tmp.tm_originalDocument

		ORDER BY	tmp.tax_class,
					tmp.ct_taxDate,
					tmp.tm_docNumber,
					tmp.ct_desc

	exec [spReports_getData3]@comp_id,@intBranch4Lang, @lang_id,@page_id



	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

	SELECT	(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 577 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params1],

			 CASE @tax_id WHEN -1
				THEN	(SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
			    			WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE	(Select	tn.tax_desc FROM dbo.tbTaxName tn
							inner join dbo.tbsysTaxClass tc on tc.tax_class = tn.tax_class
							WHERE tn.comp_id = @comp_id AND tn.tax_id = @tax_id) END									[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 991 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params3],

			(Select tov.optval_desc From dbo.tbsysOptionsValues tov
				WHERE tov.optval_class = 73 AND tov.optval_id = @option AND tov.lang_id = @lang_id)						[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t
				INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      			WHERE t.ctrl_id = 1336 and t.[page_id] = @related_page_id and t.[type_id] = 1 AND t.fun_id = 1)			[params5],

			 CASE @bg_id WHEN -1
				THEN (SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
						WHERE tut.lang_id=@lang_id AND tut.utexts_id = 1)
				ELSE (SELECT tbg.brag_desc From tbBranchGroup tbg
						WHERE tbg.comp_id = @comp_id AND tbg.brag_id = @bg_id) END										[params6],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1332
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )		[params7],

      		 @ct_datefrom [DateParams1],
			 --convert(varchar,day(@ct_datefrom))+'/'+convert(varchar,month(@ct_datefrom))+'/'+convert(varchar,year(@ct_datefrom))		[params41],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1333
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )		[params9],

      		 @ct_dateto	[DateParams2],
			 --convert(varchar,day(@ct_dateto))+'/'+convert(varchar,month(@ct_dateto))+'/'+convert(varchar,year(@ct_dateto))		[params10],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1334
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )		[params11],

      		 @tax_datefrom [DateParams3],

	--		 convert(varchar,day(@tax_datefrom))+'/'+convert(varchar,month(@tax_datefrom))+'/'+convert(varchar,year(@tax_datefrom))		[params12],

			 (SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      		 WHERE t.ctrl_id = 1335
      		 and t.[page_id] = @related_page_id and t.[type_id]	= 1 AND t.fun_id =1 )		[params13],
			 --convert(varchar,day(@tax_dateto))+'/'+convert(varchar,month(@tax_dateto))+'/'+convert(varchar,year(@tax_dateto))		[params14]
			 @tax_dateto [DateParams4]

END
GO








CREATE PROCEDURE [dbo].[spTaxMovements_getDataById]
(
	@comp_id			int,
	@tm_transaction		int

)
as

/*
declare 	@comp_id		int,
			@tm_transaction			int

select 		@comp_id		=1,
			@tm_transaction	=3294


*/

	select  ttm.comp_id,
			ttm.bra_id,
			ttm.tm_transaction,
			ttm.ct_transaction,
			ttm.it_transaction,
			ttm.pcm_id,
			ttm.tm_cd,
			ttm.tax_id,
			ttm.tm_subtotal,
			ttm.percentaje,
			isnull(ttm.tm_total,0)					[tm_total],
			ttm.curr_id,
			ttm.tm_exchangeToBranchCurrency,
			isnull(ttm.tm_docKindOf,'')				[tm_docKindOf],
			isnull(ttm.tm_docPointOfSale,-1) 		[tm_docPointOfSale],
			isnull(ttm.tm_docNumber,'')				[tm_docNumber],
			isnull(ttm.tm_docDate,GETDATE())		[tm_docDate],
			isnull(ttm.tm_originalDocument,'')		[tm_originalDocument],
			isnull(ttm.State_Id,-1)					[State_Id],
			isnull(ttm.Country_Id,-1)				[Country_Id],
			ttm.tm_originalDocumentTypeOf,
			isnull(ttm.puco_id,-1)					[puco_id],
			ttm.tm_inSIAP,
			tct.sd_id

	from		tbTaxMovements								ttm

	LEFT JOIN tbCommercialTransactions						tct
	ON	tct.comp_id			= ttm.comp_id			AND
		tct.bra_id			= ttm.bra_id			AND
		tct.ct_transaction  = ttm.ct_transaction

	where		ttm.comp_id				=	@comp_id
	and			ttm.tm_transaction		=	@tm_transaction











GO






CREATE PROCEDURE [dbo].[spTaxMovements_getReportForTaxPosition]
(
		@comp_id	INT,
		@lang_id	INT,
		@page_id	INT,


		@brag_id	INT,
		@datefrom	DATETIME,
		@dateto		DATETIME,
		@bra_id		INT,
		@user_id	INT,
		@intBranch4Lang	int
)

as

BEGIN

	 set nocount on

	set DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'true')

		DECLARE @fun_id INT
		SET @fun_id = 1

	-- ----------------------------------------
	-- TESTING
	-- ----------------------------------------
	/*
		declare
			@comp_id	INT,
			@lang_id	INT,
			@page_id	INT,
			@bra_id		INT,
			@user_id	INT,
			@brag_id	INT,
			@datefrom	DATETIME,
			@dateto		DATETIME

		select
			@comp_id	= 1,
			@lang_id	= 2,
			@page_id	= 10092,
			@bra_id		= 1,
			@user_id	= 1,
			@brag_id	= 3,
			@datefrom	= '2000-01-01',
			@dateto		= '2012-12-31'
	*/
	-- ----------------------------------------


	DECLARE @tblBranch AS TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tblBranch (bra_id)
	SELECT DISTINCT
		tbgd.bra_id
		from tbBranchGroupDetail tbgd
		where	tbgd.comp_id = @comp_id	AND
				tbgd.brag_id = @brag_id


	select
		ttn.tax_desc,
		sum(
		case
			when tct.sd_id < 100 then	isnull(ttm.tm_total,0) * IsNull(vsales.PlusOrMinus,0)
			else						0
		end
			)[DEBITO],
		sum(
		case
			when tct.sd_id >= 100 then	isnull(ttm.tm_total,0) * IsNull(vctfpte.PlusOrMinus,0)
			else						0
		end
			)[CREDITO]

	from tbCommercialTransactions				tct
	INNER JOIN @tblBranch hhh
		ON hhh.bra_id = tct.bra_id
	LEFT JOIN vwCommercialTransactions_forSales_TaxEngine vsales
		ON	vsales.comp_id			= tct.comp_id	AND
			vsales.bra_id			= tct.bra_id	AND
			vsales.ct_transaction	= tct.ct_transaction

	LEFT JOIN vwCommercialTransactions_forPurchase_TaxEngine vctfpte
		ON	vctfpte.comp_id			= tct.comp_id	AND
			vctfpte.bra_id			= tct.bra_id	AND
			vctfpte.ct_transaction	= tct.ct_transaction

	inner join tbsysDocuments					td
	on	td.sd_id			= tct.sd_id

	inner join tbTaxMovements					ttm
	on  ttm.comp_id			= tct.comp_id
	AND ttm.bra_id			= tct.bra_id
	AND ttm.ct_transaction	= tct.ct_transaction

	inner join tbTaxName						ttn
	on  ttn.comp_id			= ttm.comp_id
	AND ttn.tax_id			= ttm.tax_id

	inner join tbsysTaxClass					ttc
	on	ttc.tax_class		= ttn.tax_class

	inner join tbUsers4BranchFilter				vubf
	on  vubf.comp_id		= tct.comp_id
	and vubf.bra_id			= tct.bra_id
	and vubf.user_id		= @user_id

	where	tct.comp_id	= @comp_id	AND
			CASE
				WHEN tct.sd_id < 100 THEN	tct.ct_date
				ELSE						tct.ct_taxDate
			END
			/*isnull(tct.ct_taxDate,tct.ct_date)*/ between @datefrom and @dateto

	group by ttm.tax_id, ttn.tax_desc,ttn.tax_class,ttc.taxcl_isIVA,ttn.tax_id
	ORDER BY ttc.taxcl_isIVA,ttn.tax_class,ttn.tax_id



	exec [spReports_getData3] @comp_id,@intBranch4Lang, @lang_id,	@page_id

	/* devolución de parámetros recibidos */
	DECLARE @related_page_id INT
	SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id
	/*************************************************************************************************************/
	/* query para saber los ids de los controles a tener en cuenta para los labels de los parámetros			*/
	/*
			SELECT	t.ctrl_id,	t.[text_desc]
			FROM	[tbsysTexts]				t
					inner join [tbsysControls]	c
					on c.[ctrl_id] = t.[ctrl_id]
			where	t.[lang_id]	= @lang_id
			and		t.[page_id]	= @related_page_id
			and		t.[type_id]	= 1
	*/
	/*************************************************************************************************************/

	select
				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
					 WHERE t.ctrl_id = 639
					 and t.[page_id] = @related_page_id
					and t.[type_id]	 = 1
					AND t.fun_id     = @fun_id )						[params1],

				(select tbg.brag_desc
				 from tbBranchGroup tbg
				where tbg.comp_id = @comp_id
				and tbg.brag_id = @brag_id)						        [params2],

				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
					 WHERE t.ctrl_id = 177
					 and t.[page_id] = @related_page_id
					 and t.[type_id] = 1
					 AND t.fun_id	 = @fun_id )						[params3],



				(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
					 WHERE t.ctrl_id = 384
					 and t.[page_id] = @related_page_id
					 and t.[type_id] = 1
					 AND t.fun_id	= @fun_id )							[params5],

				@datefrom												[DateParams1],

				@dateto													[DateParams2]

	----------------------------------------------------


END
GO







CREATE  PROCEDURE [dbo].[spTaxMovements_insertData]
(
		@comp_id						int,
		@bra_id							int,
		@ct_transaction					int,
		@it_transaction					int,
		@pcm_id							int,
		@tm_cd							datetime,
		@tax_id							int,
		@tm_total						decimal(19,6),
		@percentaje						decimal(19,6),
		@curr_id						int,
		@tm_docKindOf					varchar(10),
		@tm_docPointOfSale				int,
		@tm_docNumber					varchar(40),
		@tm_docDate						datetime,
		@tm_originalDocument			varchar(200),
		@State_Id						int,
		@Country_Id						int,
		@tm_originalDocumentTypeOf		varchar(30),
		@return_value					int output
)
as
set nocount on

insert into dbo.tbTaxMovements	WITH (ROWLOCK)
( comp_id, bra_id, ct_transaction, it_transaction, pcm_id,
 tm_cd, tax_id, tm_total, percentaje, curr_id, tm_docKindOf,
 tm_docPointOfSale, tm_docNumber, tm_docDate, tm_originalDocument,
 State_Id, Country_Id, tm_originalDocumentTypeOf )

values
( @comp_id, @bra_id, @ct_transaction, @it_transaction, @pcm_id,
 @tm_cd, @tax_id, @tm_total, @percentaje, @curr_id, @tm_docKindOf,
 @tm_docPointOfSale, @tm_docNumber, @tm_docDate, @tm_originalDocument,
 @State_Id, @Country_Id, @tm_originalDocumentTypeOf )

set	@return_value = @@identity
GO






-- Alter :  MOS
--          06-2009
CREATE  PROCEDURE [dbo].[spTaxMovements_insertData_ForPurchase]
(
		@comp_id				int,
		@bra_id					int,
		@ct_transaction			int,
		@guid					uniqueidentifier,
		@currSupplier			int,
		@currBranch				int,
		@exchange				decimal(18,5),
		@return_value			as int			output,
		@ret_ErrorCode			as int			output,
		@ret_ErrorDescription	as varchar(200) output
)
AS

BEGIN



	set nocount on

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''


	BEGIN TRY



		-- Moneda de la Sucursal.!!!!!
		SELECT @currBranch = curr_id
			FROM tbBranch tb		WITH (NOLOCK)
			WHERE	tb.comp_id = @comp_id
				AND tb.bra_id = @bra_id


		-- para bancos-----
		-- en caso de ser imputacion bancaria (entrada o salida ) y si no efectua asiento contable se pone en true Available4bankingTotals
		DECLARE @Available4bankingTotals AS BIT
		DECLARE @lbra_Banks_InputOutputCharges_DisableAccounting AS BIT
		DECLARE @lsd_id AS INT

		SET @Available4bankingTotals = 'False'

		--DOCUMENTO
		SELECT @lsd_id = tct.sd_id
				FROM tbCommercialTransactions	tct	WITH (NOLOCK)
				WHERE	tct.comp_id			= @comp_id			AND
						tct.ct_transaction	= @ct_transaction

		--Asiento contable deshabilitado?
		SELECT @lbra_Banks_InputOutputCharges_DisableAccounting = tb.bra_Banks_InputOutputCharges_DisableAccounting
					FROM tbBranch tb	WITH (NOLOCK)
					WHERE	tb.comp_id	= @comp_id AND
							tb.bra_id	= @bra_id


		IF @lsd_id = 140 OR @lsd_id = 141
			BEGIN
				IF @lbra_Banks_InputOutputCharges_DisableAccounting = 'True'
					BEGIN
						SET @Available4bankingTotals = 'True'
					END
			END
		-------------




		insert into dbo.tbTaxMovements
		   (comp_id,
			bra_id,
			ct_transaction,
			it_transaction,
			pcm_id,
			tm_cd,
			tax_id,
			tm_subtotal,
			percentaje,
			tm_total,
			curr_id,
			tm_docKindOf,
			tm_docPointOfSale,
			tm_docNumber,
			tm_docDate,
			tm_originalDocument,
			State_Id,
			Country_Id,
			tm_originalDocumentTypeOf,
			puco_id,
			tm_exchangeToBranchCurrency,
			tm_available4BankingTotals,
			tm_id_original)

				select
					@comp_id,
					@bra_id,
					@ct_transaction,
					(SELECT TOP 1 tit.it_transaction
						FROM tbItemTransactions tit				WITH (NOLOCK)
						WHERE	tit.comp_id			= @comp_id				AND
								tit.ct_transaction	= @ct_transaction		AND
								tit.tmp_tis_id		= tmtmp.tis_id) [it_transaction],			--Verificar si esto no mata al insert.!!!!
					(SELECT TOP 1 pcm.pcm_id
						FROM tbPurchaseConceptMovements pcm		WITH (NOLOCK)
						WHERE	pcm.comp_id			= @comp_id				AND
								pcm.ct_transaction	= @ct_transaction		AND
								pcm.tmp_pcmt_id		= tmtmp.pcmt_id) [pcm_id],					--Verificar si esto no mata al insert.!!!!
					tmtmp.tmt_cd,
					tmtmp.tax_id,
					tmtmp.tmt_subtotal   /*CASE WHEN percentaje = 0 THEN 0 ELSE tmt_total * 100 / percentaje END*/,
					tmtmp.percentaje,
					tmtmp.tmt_total,
					tmtmp.curr_id,
					tmtmp.tmt_docKindOf,
					tmtmp.tmt_docPointOfSale,
					tmtmp.tmt_docNumber,
					tmtmp.tmt_docDate,
					tmtmp.tmt_originalDocument,
					tmtmp.State_Id,
					tmtmp.Country_Id,
					tmtmp.tmt_originalDocumentTypeOf,
					tmtmp.puco_id,
					dbo.fnGetExchange(@comp_id, 1, tmtmp.curr_id, @currBranch, @currSupplier, @exchange, 0),
					@Available4bankingTotals,
					tmtmp.tm_id_original

					from	dbo.tbTaxMovementsTmp			tmtmp			WITH (NOLOCK)
					where	tmtmp.comp_id		=	@comp_id
						and	tmtmp.tmt_guid		=   @guid


		-- Borrado de Temporales.!!

		delete	dbo.tbTaxMovementsTmp
			where	comp_id		=	@comp_id
			and		tmt_guid	=   @guid

		delete dbo.tbPurchaseConceptMovementsTmp
			where	comp_id		= @comp_id
				and pcmt_guid	= @guid

		/* eliminamos la temporal de items cargados desde el front end*/
		delete	dbo.tbItemTransactionsTmp
			where	comp_id		=	@comp_id
			and		tis_guid	=   @guid




	END TRY
	BEGIN CATCH
			Set @return_value			= -1
			Set @ret_ErrorCode			= -1
			Set @ret_ErrorDescription	= 'spTaxMovements_insertData_ForPurchase-' +
				(SELECT
				convert(varchar,ERROR_NUMBER())		+ '-' +
				convert(varchar,ERROR_SEVERITY())	+ '-' +
				convert(varchar,ERROR_STATE())		+ '-' +
				convert(varchar,ERROR_LINE())		+ '-' +
				ERROR_MESSAGE())
	END CATCH



END
GO






