CREATE Procedure [dbo].[spTaxMovements_InsertDataFromtbTmpTax]
	(
	  @comp_id					as int,
      @bra_id					as int,
	  @ct_date					as datetime,
	  @tis_guid					as uniqueidentifier,
	  @ct_transaction			as int,
	  @ret_Identity				as int			output,
	  @ret_ErrorCode			as int			output,
	  @ret_ErrorDescription		as varchar(200) output
	 )

as


Begin

	Set noCount On


	Set @ret_Identity			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= ''



	Select
				@comp_id		[comp_id],
				@bra_id			[bra_id],
				@ct_transaction	[ct_transaction],
				ttis.it_transaction, /*(Select it_transaction From dbo.tbTempItemStock B Where B.comp_id = A.comp_id and B.tis_id = A.tis_id)*/
				@ct_date		[tm_cd],
				A.tax_id,
				A.tm_amount,
				A.percentage,
				A.curr_id,
				A.tm_subtotal
				INTO #tbtmpTax
			From dbo.tbtmpTax A							WITH (NOLOCK)

			INNER JOIN tbTempItemStock ttis				WITH (NOLOCK)
				ON		ttis.comp_id = a.comp_id
					AND ttis.tis_id  = A.tis_id
			INNER JOIN tbTaxName ttn					WITH (NOLOCK)
				ON ttn.comp_id = A.comp_id
					AND ttn.tax_id = A.tax_id
			Where   A.comp_id  = @comp_id
				and A.tis_guid = @tis_guid

	IF EXISTS(SELECT 1 FROM #tbtmpTax)
	BEGIN

		INSERT INTO dbo.tbTaxMovements
				   (comp_id,
					bra_id,
					ct_transaction,
					it_transaction,
					tm_cd,
					tax_id,
					tm_total,
					percentaje,
					curr_id,
					tm_subtotal)
			SELECT * FROM #tbtmpTax

		Set @ret_Identity =  @@identity

	END

	DROP TABLE #tbtmpTax


End
GO







CREATE PROCEDURE [dbo].[spTaxMovements_UpdateTaxName]
(
	@comp_id		as INT,
	@tax_id			as INT,
	@tm_transaction	as INT,
	@user_id		AS INT,
	@lang_id		AS INT,
	@tm_subtotal	AS DECIMAL(19,6),
	@percentaje     AS DECIMAL(19,6)
)

AS


BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------------
/*
		DECLARE
				@comp_id		as INT,
				@tax_id			as INT,
				@tm_transaction	as INT
		SELECT
				@comp_id				= 1,
				@tax_id					= 1,
				@tm_transaction			= 6662
*/
	-- -----------------------------------------------------------------------



		-- ------------------------------------------------------------------
		-- Intenta generar una reversion a la cuenta corecta del asiento contable
		-- que se hara SOLO si no se modifico la cta contable en la que imputa
		-- el impuesto original.
		-- ------------------------------------------------------------------

		DECLARE @dacc_transactionOriginal	AS INT
		SET		@dacc_transactionOriginal = NULL
		DECLARE @ct_transaction				AS INT
		DECLARE @decTotal					AS DECIMAL(30,6)
		DECLARE @acc_count_id				AS INT
		DECLARE @acc_count_id_original		AS INT
		DECLARE @tax_id_Original			AS INT
		DECLARE @bra_id						AS INT
		DECLARE @sd_id						AS INT


		-- Obtengo la transaccion, el total y el impuesto
		SELECT	@ct_transaction = ttm.ct_transaction,
				@decTotal		= ttm.tm_total,
				@tax_id_Original= ttm.tax_id,
				@bra_id			= ttm.bra_id,
				@sd_id			= tct.sd_id
			FROM tbTaxMovements ttm
			INNER JOIN tbCommercialTransactions tct
				ON	tct.comp_id			= ttm.comp_id AND
					tct.ct_transaction	= ttm.ct_transaction
			WHERE	ttm.comp_id			= @comp_id AND
					tm_transaction		= @tm_transaction




			BEGIN


				-- Obtengo la cuenta contable original
				SELECT		@acc_count_id_original = tabtn.acc_count_id_forPurchase
					FROM tbAccountByTaxName tabtn
					WHERE	tabtn.comp_id	= @comp_id	AND
							tabtn.bra_id	= @bra_id	AND
							tabtn.tax_id	= @tax_id_Original


				-- Obtengo la cuenta contable destino
				SELECT		@acc_count_id	= tabtn.acc_count_id_forPurchase
					FROM tbAccountByTaxName tabtn
					WHERE	tabtn.comp_id	= @comp_id	AND
							tabtn.bra_id	= @bra_id	AND
							tabtn.tax_id	= @tax_id



				-- Obtengo la imputacion contable que se hizo
				SELECT @dacc_transactionOriginal = tatd.dacc_transaction
					FROM tbAccountTransactionDetail tatd
					WHERE	tatd.comp_id		= @comp_id AND
							tatd.ct_transaction = @ct_transaction AND
							tatd.acc_count_id	= @acc_count_id_original AND
						   (
			   				tatd.dacc_debit		= @decTotal OR
							tatd.dacc_credit	= @decTotal
						   )
					ORDER BY tatd.dacc_debit, tatd.dacc_credit


				IF @acc_count_id IS NOT NULL
					BEGIN

						INSERT INTO tbAccountTransactionDetail
						(
							comp_id,
							bra_id,
							hacc_transaction,
							-- dacc_transaction -- this column value is auto-generated,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							[user_id],
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order,
							dacc_2ndCurrencyExchange
						)

						SELECT	tatd.comp_id,
								tatd.bra_id,
								tatd.hacc_transaction,
								tatd.acc_count_id,
								tatd.cc_code,
								tatd.dacc_credit,
								tatd.dacc_debit,
								tatd.[user_id],
								tatd.dacc_cd,
								tatd.hacc_software,
								tatd.ct_transaction,
								tatd.acc_detail1,
								'*TUO* / ' + IsNull(tatd.acc_detail2,''),
								tatd.dacc_order,
								tatd.dacc_2ndCurrencyExchange
							FROM tbAccountTransactionDetail tatd
							WHERE	tatd.comp_id			= @comp_id AND
									tatd.dacc_transaction	= @dacc_transactionOriginal


						INSERT INTO tbAccountTransactionDetail
						(
							comp_id,
							bra_id,
							hacc_transaction,
							-- dacc_transaction -- this column value is auto-generated,
							acc_count_id,
							cc_code,
							dacc_debit,
							dacc_credit,
							[user_id],
							dacc_cd,
							hacc_software,
							ct_transaction,
							acc_detail1,
							acc_detail2,
							dacc_order,
							dacc_2ndCurrencyExchange
						)

						SELECT	tatd.comp_id,
								tatd.bra_id,
								tatd.hacc_transaction,
								@acc_count_id,
								tatd.cc_code,
								tatd.dacc_debit,
								tatd.dacc_credit,
								tatd.[user_id],
								tatd.dacc_cd,
								tatd.hacc_software,
								tatd.ct_transaction,
								tatd.acc_detail1,
								'*TUN* / ' + IsNull(tatd.acc_detail2,''),
								tatd.dacc_order,
								tatd.dacc_2ndCurrencyExchange
							FROM tbAccountTransactionDetail tatd
							WHERE	tatd.comp_id			= @comp_id AND
									tatd.dacc_transaction	= @dacc_transactionOriginal

					END
			END
		-- ------------------------------------------------------------------




		-- Actualiza el Movimiento
		update tbTaxMovements
			SET		tax_id		= @tax_id,
					tm_subtotal = @tm_subtotal,
					percentaje	= @percentaje

			where tm_transaction = @tm_transaction



END

GO






