CREATE PROCEDURE [dbo].[spTaxMovementsTmp_getDataByFilters]
(
	@tmt_guid		uniqueidentifier
)
AS

	BEGIN



	set nocount on

	/*
	declare	@tmt_guid		uniqueidentifier
	select	@tmt_guid		= '45b7f584-70ae-4d17-981d-392a3b8c75e9'
	*/

	declare @d int
	set		@d = 2


	select	' ' [ ], ' ' [ ],
			tmt.tmt_guid,
			tmt.ct_transaction,
			tmt.it_transaction,
			tmt.tmt_cd,
			tmt.tax_id,
			tn.tax_desc + ' -> ' + ISNULL(tpc.puco_desc,'')				[tax_desc],
			convert(decimal(18,2),round(ISNULL(tmt.tmt_subtotal,0),@d))	[tmt_subtotal],
			tmt.percentaje,
			convert(decimal(18,2),round(tmt.tmt_total,@d))				[tmt_total],
			tmt.curr_id,
			sc.curr_desc,
			tmt.tmt_docKindOf,
			tmt.tmt_docPointOfSale,
			tmt.tmt_docNumber,
			tmt.tmt_docDate,
			tmt.tmt_originalDocument,
			tmt.State_Id,
			tmt.Country_Id,
			tmt.tmt_originalDocumentTypeOf	[tmt_originalDocTypeOf],
			tmt.puco_id,
			tmt.isCalculated,
			tmt.tmt_transaction [ID3]

	from	dbo.tbTaxMovementsTmp				tmt			WITH (NOLOCK)

			LEFT JOIN tbPurchaseConcept tpc					WITH (NOLOCK)
				ON tpc.comp_id = tmt.comp_id AND tpc.puco_id = tmt.puco_id

			left join dbo.tbTaxName				tn			WITH (NOLOCK)
			on tn.comp_id	= tmt.comp_id
			and tn.tax_id	= tmt.tax_id

			left join dbo.tbsysCurrency			sc			WITH (NOLOCK)
			on sc.curr_id	= tmt.curr_id

	where	tmt.tmt_guid	= @tmt_guid

	order by tmt.tmt_transaction


	END
GO






CREATE PROCEDURE [dbo].[spTaxMovementsTmp_getDataById]
(
