		tmt.tmt_docPointOfSale,
		tmt.tmt_docNumber,
		tmt.tmt_docDate,
		tmt.tmt_originalDocument,
		tmt.State_Id,
		tmt.Country_Id,
		tmt.tmt_originalDocumentTypeOf,
		tmt.puco_id,
		tmt.tmt_transaction,
		tmt.tmt_subtotal


from	dbo.tbTaxMovementsTmp		tmt

		left join dbo.tbTaxName		tn
		on tn.comp_id	= tmt.comp_id
		and tn.tax_id	= tmt.tax_id

		left join dbo.tbsysCurrency		sc
		on sc.curr_id	= tmt.curr_id


where	tmt.tmt_transaction	=	@tmt_transaction

order by tmt.tmt_transaction






















GO






-- Updated: MOS  03-2009
-- wfmPurchaseDocs
CREATE  PROCEDURE [dbo].[spTaxMovementsTmp_insertData]
(
		@comp_id						int,
		@bra_id							int,
		@tmt_guid						uniqueidentifier,
		@ct_transaction					int,
		@it_transaction					int,
		@tmt_cd							datetime,
		@tax_id							int,
		@tmt_total						decimal(19,6),
		@percentaje						decimal(19,6),
		@curr_id						int,
		@tmt_docKindOf					varchar(10),
		@tmt_docPointOfSale				int,
		@tmt_docNumber					varchar(40),
		@tmt_docDate					datetime,
		@tmt_originalDocument			varchar(200),
		@State_Id						int,
		@Country_Id						int,
		@tmt_originalDocumentTypeOf		varchar(30),
		@puco_id						int,
		@tmt_subtotal					decimal(19,6),
		@tm_id_original					INT,
		@return_value					int output

)
AS

BEGIN




	set nocount on



	IF @curr_id IS NULL
	begin
	Declare @BranchCurrency As integer
	Select @BranchCurrency	=  tb.curr_id
		From tbBranch tb
		Where	tb.comp_id	= @comp_id
			And tb.bra_id	= @bra_id

	If Isnull(@curr_id,0) = 0
		BEGIN
			Set @curr_id = @BranchCurrency
		END
	END



	-- Si los impuestos tienen un pais y provincia asignados, los re-asigna.!!!!
	DECLARE @intStateID		AS INT
	DECLARE @intCountryID	AS INT

	SELECT @intStateID		= ttc.state_id,
		   @intCountryID	= ttc.country_id
		FROM tbTaxName ttn
		INNER JOIN tbsysTaxClass ttc
			ON ttc.tax_class = ttn.tax_class
		WHERE	ttn.comp_id = @comp_id
			AND ttn.tax_id	= @tax_id


	-- Si el impuesto dice que pertenece a un pais y provincia, lo fuerza por mas que hayan seleccionado otra cosa.
	IF @intCountryID IS NOT NULL AND @intStateID IS NOT NULL SET @State_Id		= @intStateID
	IF @intCountryID IS NOT NULL AND @intStateID IS NOT NULL SET @Country_Id	= @intCountryID



	insert into dbo.tbTaxMovementsTmp

	( comp_id, bra_id, tmt_guid, ct_transaction, it_transaction, tmt_cd,
	 tax_id, tmt_total, percentaje, curr_id, tmt_docKindOf, tmt_docPointOfSale,
	 tmt_docNumber, tmt_docDate, tmt_originalDocument, State_Id, Country_Id,
	 tmt_originalDocumentTypeOf, puco_id, tmt_subtotal, tm_id_original)

	values

	( @comp_id, @bra_id, @tmt_guid, @ct_transaction, @it_transaction, GETDATE(),
	 @tax_id, @tmt_total, @percentaje, @curr_id, @tmt_docKindOf, @tmt_docPointOfSale,
	 @tmt_docNumber, @tmt_docDate, @tmt_originalDocument, @State_Id,
	 @Country_Id, @tmt_originalDocumentTypeOf, @puco_id,@tmt_subtotal, @tm_id_original)

	set	@return_value = @@identity


END
GO








CREATE PROCEDURE [dbo].[spTaxMovementsTmp_updateData]
(
		@tmt_transaction				int,
		@tmt_guid						uniqueidentifier,
		@ct_transaction					int,
		@it_transaction					int,
		@tax_id							int,
		@tmt_cd							datetime,
		@tmt_total						decimal(19,6),
		@percentaje						decimal(19,6),
		@curr_id						int,
		@tmt_docKindOf					varchar(10),
		@tmt_docPointOfSale				int,
		@tmt_docNumber					varchar(40),
		@tmt_docDate					datetime,
		@tmt_originalDocument			varchar(200),
		@State_Id						int,
		@Country_Id						int,
		@tmt_originalDocumentTypeOf		varchar(30),
		@puco_id						INT,
		@tmt_subtotal					decimal(19,6)

)
AS

BEGIN

	set nocount on

	--recuperar la moneda de la sucursal si la moneda no es informada
	IF @curr_id IS NULL
	BEGIN
		DECLARE		@comp_id		INT,
					@bra_id			INT

		SELECT	@comp_id	=	comp_id,
				@bra_id		=	bra_id
		FROM	tbTaxMovementsTmp ttmt		WITH (NOLOCK)
		where	tmt_guid					=	@tmt_guid
		and	    tmt_transaction				=	@tmt_transaction



		Declare @BranchCurrency As integer
		Select @BranchCurrency	=  tb.curr_id
			From tbBranch tb	WITH (NOLOCK)
			Where	tb.comp_id	= @comp_id
				And tb.bra_id	= @bra_id

		If Isnull(@curr_id,0) = 0
			BEGIN
				Set @curr_id = @BranchCurrency
			END
	END


	-- ---------------------------------------------------------------------------
	-- Si los impuestos tienen un pais y provincia asignados, los re-asigna.!!!!
	-- ---------------------------------------------------------------------------
	DECLARE @intStateID		AS INT
	DECLARE @intCountryID	AS INT

	SELECT @intStateID		= ttc.state_id,
		   @intCountryID	= ttc.country_id
		FROM tbTaxName ttn				WITH (NOLOCK)
		INNER JOIN tbsysTaxClass ttc	WITH (NOLOCK)
			ON ttc.tax_class = ttn.tax_class
		WHERE	ttn.comp_id = @comp_id
			AND ttn.tax_id	= @tax_id

	IF @intStateID		IS NOT NULL SET @State_Id	= @intStateID
	IF @intCountryID	IS NOT NULL SET @Country_Id = @intCountryID
	-- ---------------------------------------------------------------------------


	update	dbo.tbTaxMovementsTmp

	set		ct_transaction				=	@ct_transaction,
			it_transaction				=	@it_transaction,
			tax_id						=	@tax_id,
			tmt_total					=	@tmt_total,
			percentaje					=	@percentaje,
			tmt_cd						=	@tmt_cd,
			curr_id						=	@curr_id,
			tmt_docKindOf				=	@tmt_docKindOf,
			tmt_docPointOfSale			=	@tmt_docPointOfSale,
			tmt_docNumber				=	@tmt_docNumber,
			tmt_docDate					=	@tmt_docDate,
			tmt_originalDocument		=	@tmt_originalDocument,
			State_Id					=	@State_Id,
			Country_Id					=	@Country_Id,
			tmt_originalDocumentTypeOf	=	@tmt_originalDocumentTypeOf,
			puco_id						=	@puco_id,
			tmt_subtotal				=	@tmt_subtotal

	where	tmt_guid					=	@tmt_guid
	and	    tmt_transaction				=	@tmt_transaction



END
GO







