-- MOS
-- 08-2008
-- OJO, este es el unico stored procedure que funciona sin vistas, el resto funciona con las vistas.!!!

CREATE PROCEDURE [dbo].[spTaxname_getCombo]
(
	@comp_id				int,
	@type					int
)


AS


BEGIN


	Set NoCount ON




	-- ---------------------------------------------
	-- Testing
	-- ---------------------------------------------
	/*
	DECLARE 	@comp_id				int,
				@type					int


	select 		@comp_id				=1,
				@type					=19
*/
	-- ---------------------------------------------




		--cantidad agrupada por guid,stor e item
	DECLARE @tmpTaxesInclOnPurchase TABLE(tax_id  INT,tax_desc NVARCHAR(50),tax_order int)

	INSERT INTO @tmpTaxesInclOnPurchase
	(
		tax_id,
		tax_desc,
		tax_order
	)

	SELECT
		tn.tax_id								[tax_id],
		tn.tax_desc								[tax_desc],
		ISNULL(tn.tax_order,0)  /*+ 9999999*/   [tax_order]

		FROM tbTaxName							tn			WITH (NOLOCK)
		WHERE  tn.comp_id										= @comp_id AND
			   IsNull(tn.tax_includeOnPurchaseTaxes,'False')	= 'True'


	INSERT INTO @tmpTaxesInclOnPurchase
	(
		tax_desc,
		tax_id,
		tax_order
	)

	Select	t.tax_desc		[desc],
			t.tax_id		[ID],
			t.tax_order

		From	dbo.tbTaxName					t			WITH (NOLOCK)

		inner join  dbo.tbsysTaxClass			tc			WITH (NOLOCK)
		on	tc.tax_class	= t.tax_class

		Where	(
				t.comp_id						= @comp_id
		and		IsNull(t.tax_disabled,'False') = 'False'
		and	   ((@type = 1  and tc.taxcl_isPerception	= 'True')
		or		(@type = 2  and tc.taxcl_isRetention	= 'True')
		or		(@type = 3  and tc.taxcl_isIVA			= 'True')
		or		(@type = 4  and tc.taxcl_isIB			= 'True')
		or		(@type = 5  and tc.taxcl_isGan			= 'True')
		or		(@type = 6  and tc.taxcl_isIVA			= 'True' and taxcl_isPerception = 'False' and taxcl_isRetention = 'False' )
		or		(@type = 7  and tc.taxcl_isIB			= 'True' and taxcl_isPerception = 'False' and taxcl_isRetention = 'False' )
		or		(@type = 8  and tc.taxcl_isGAN			= 'True' and taxcl_isPerception = 'False' and taxcl_isRetention = 'False' )
		or		(@type = 9  and tc.taxcl_isIVA			= 'True' and taxcl_isPerception = 'True'  and taxcl_isRetention = 'False' )
		or		(@type = 10 and tc.taxcl_isIB			= 'True' and taxcl_isPerception = 'True'  and taxcl_isRetention = 'False' )
		or		(@type = 11 and tc.taxcl_isGAN			= 'True' and taxcl_isPerception = 'True'  and taxcl_isRetention = 'False' )
		or		(@type = 12 and tc.taxcl_isIVA			= 'True' and taxcl_isPerception = 'False' and taxcl_isRetention = 'True'  )
		or		(@type = 13 and tc.taxcl_isIB			= 'True' and taxcl_isPerception = 'False' and taxcl_isRetention = 'True'  )
		or		(@type = 14 and tc.taxcl_isGAN			= 'True' and taxcl_isPerception = 'False' and taxcl_isRetention = 'True'  )
		or		(@type = 18 AND tc.taxcl_isRetention='false'  )
		OR		(@type = 19  and (tc.taxcl_isPerception	= 'True' OR tc.tax_class = 20 OR tc.tax_class = 30 ))		-- Si es Percepcion, Impuestos Internos o ITC
		or		(@type = 15 and isnull(t.btt_id,-1) <> -1 )
		or		(@type = 20 and (taxcl_isPerception		= 'True' OR taxcl_isRetention	= 'True'  ))
		OR		(@type = 21  and (tc.taxcl_isPerception	= 'True' OR tc.tax_class		= 20 OR tc.tax_class = 30 OR t.tax_class = 1 ))		-- Si es Percepcion, Impuestos Internos o ITC o IVA
		or      (@type = 0))
				)
		AND NOT EXISTS (	SELECT 1
		                		FROM @tmpTaxesInclOnPurchase tmpg
		                		WHERE tmpg.tax_id = t.tax_id )








	SELECT
		tmp.tax_desc	[desc],
		tmp.tax_id		[Id]

		FROM @tmpTaxesInclOnPurchase tmp
		Order by tmp.tax_order, tmp.tax_desc



END
GO






