CREATE PROCEDURE [dbo].[spTaxName_getTaxes]
(
	@comp_id	INT,
	@item_id	INT,
	@bra_id		INT
)
as

SET NOCOUNT ON

/*
DECLARE
	@comp_id	INT,
	@item_id	INT,
	@bra_id		INT

SELECT
	@comp_id	=1,
	@item_id	=238,
	@bra_id		=-1
*/

SELECT
	ttn.tax_id [Id],
	ttn.tax_desc [desc]

FROM	dbo.tbTaxName ttn

WHERE	ttn.comp_id = @comp_id
AND		ttn.tax_id NOT IN (SELECT
							tit.tax_id [Id]
							FROM	dbo.tbItemTaxes tit
							INNER JOIN	dbo.tbTaxName ttn
							ON		ttn.comp_id	= tit.comp_id
							AND		ttn.tax_id	= tit.tax_id
							LEFT JOIN	dbo.tbBranch tb
							ON		tb.comp_id	= tit.comp_id
							AND		tb.bra_id	= tit.bra_id
							WHERE	tit.comp_id = @comp_id
							AND		tit.item_id = @item_id
							AND		(tit.bra_id	IS NULL or tit.bra_id	= @bra_id))

ORDER BY 1
GO






CREATE PROCEDURE [dbo].[spTaxName_validateData]
(
	@comp_id			INT,
	@lang_id			INT,
	@tax_class			INT,
	@tax_percentage		DECIMAL(19,6),
	@errormessage		VARCHAR(200) OUTPUT
)
as
SET NOCOUNT ON

/*
DECLARE 	@comp_id			INT,
	@lang_id			INT,
	@tax_class			INT,
	@tax_percentage		DECIMAL(19,6),
	@errormessage		VARCHAR(200)

SELECT 	@comp_id			=1,
	@lang_id			=2,
	@tax_class			=1,
	@tax_percentage		=0

drop table #tmp
*/



declare @return_value int
set @return_value = 0
set @errormessage = ''




--crear tabla temporal para descripciones de posibles errores
CREATE TABLE #tmp (	[field_id]				[int]			null,
					[type_id]				[int]			null,
					[type_desc]				[varchar](200)	null,
					[name_desc]				[varchar](200)	null,
					[name_join]				[varchar](200)	null,
					[name_combo]			[varchar](200)	null,
					[name_column]			[varchar](200)	null,
					[name_comboact]			[varchar](200)	null,
					[name_errormessage]		[varchar](200)	null,
					[name_errormessage2]	[varchar](200)	null,
					[ctrl_id]				[int]			null,
					[ctrl_desc]				[varchar](200)	null,
					[prop_id]				[int]			null,
					[prop_desc]				[varchar](200)	null)

--select * from [#tmp]

--recuperar las descripciones de los posibles errores que pudieran ocurrir en la validación
INSERT #tmp
(	[field_id],[type_id],[type_desc],[name_desc],
	[name_join],[name_combo],[name_column],[name_comboact],[name_errormessage], [name_errormessage2],
	[ctrl_id],[ctrl_desc],[prop_id],[prop_desc])
		exec dbo.spSysNames_getDataByTab @lang_id, 21 , -1 ,-1


IF EXISTS (	SELECT 1
           		FROM vwsysTaxClassIB_Perceptions vtcip
				WHERE @tax_class = 102
				--vtcip.tax_class = @tax_class
		  )
	AND @tax_percentage <> 0

	begin
		set	@errormessage = (select [name_errormessage] from #tmp where ctrl_id = 287)
		set @return_value = 287
	end


return @return_value
--select @return_value, @errormessage



















GO








CREATE PROCEDURE [dbo].[spTaxNameRetentionCounters_getNextValue]
(
	@comp_id		as int,
	@bra_id			as int,
	@tax_id			as INT,
	@counter_value  AS NVARCHAR(100) OUTPUT
)
as

BEGIN

	set nocount on

	--DECLARE @counter_value INT
	SET @counter_value = 0

	IF NOT EXISTS (
						SELECT 1
							FROM tbTaxName4RetentionRelations tmp
							WHERE	comp_id = @comp_id	AND
									bra_id	= @bra_id	AND
									tax_id	= @tax_id
					)
		BEGIN
			INSERT INTO tbTaxName4RetentionRelations
			(
				comp_id,
				bra_id,
				tax_id,
				ret_prefijo,
				ret_Counter
			)
			VALUES
			(
				@comp_id,
				@bra_id,
				@tax_id,
				'XXXX-',
				0
			)

		END


	-- ------------------------------------------------------------------------------------
	-- Verifica si debe tomar el numero de otro contador.  De ser asi cambia el @tax_id
	-- ------------------------------------------------------------------------------------
	SELECT @tax_id = CASE
	                     WHEN ttnrr.tax_id_4Number IS NOT NULL THEN ttnrr.tax_id_4Number
	                     ELSE @tax_id
	                 END
		FROM tbTaxName4RetentionRelations ttnrr
		WHERE	ttnrr.comp_id	= @comp_id	AND
				ttnrr.bra_id	= @bra_id	AND
				ttnrr.tax_id	= @tax_id
	-- ------------------------------------------------------------------------------------


	UPDATE tbTaxName4RetentionRelations
		SET
			ret_Counter = (ret_Counter + 1)
		WHERE	comp_id = @comp_id	AND
				bra_id	= @bra_id	AND
				tax_id	= @tax_id

	SELECT @counter_value = tmp.ret_Counter
		FROM tbTaxName4RetentionRelations tmp
		WHERE	comp_id = @comp_id	AND
				bra_id	= @bra_id	AND
				tax_id	= @tax_id


	Return  @counter_value

END
GO






