CREATE PROCEDURE [dbo].[sptbAccountant_getDataByText]
(
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT
)
AS SET NOCOUNT ON


/*
DECLARE
	@text		VARCHAR(300),
	@count		INT,
	@lang_id	INT
SELECT
	@text		= 'R',
	@count		= 2,
	@lang_id	= 2

*/

SELECT		TOP (@count)
			ta.acc_desc + ' | ' + isnull(convert(varchar,ta.acc_code),'') [acc_desc],
			ta.acc_code

FROM		tbAccountant ta

WHERE		ta.acc_desc LIKE @text+'%'

ORDER BY	ta.acc_desc
GO





CREATE PROCEDURE [dbo].[sptbCustomerPriceListBySOItemType_Process_ImportLog_getDataByFilters]
(
	@comp_id			int,
	@guid				UNIQUEIDENTIFIER,
	@lang_id			INT

)
as

set nocount on


--------------------------------------------------------------------------------------------------
--PARAMETROS DE TESTING
--------------------------------------------------------------------------------------------------
/*
declare	@comp_id		int,
		@guid			UNIQUEIDENTIFIER,
		@lang_id			INT


select	@comp_id		= 1,
		@guid			='E011017D-8C70-400D-A241-C5B0E9B921FA',
		@lang_id		= 2

*/
--------------------------------------------------------------------------------------------------


BEGIN



	SELECT
			CONVERT(VARCHAR,TC.cust_id) + '-' + CONVERT(VARCHAR,tc.prli_id)	 + '-' + CONVERT(VARCHAR,tc.tipi_id)		[cust_name],
			tpclil.code4Import										[code4Import],
			tu.user_lastname + ', ' + tu.user_firstname				[User_Name],
			tpclil.pli_cd											[pli_cd],
			isnull(tpclil.info,tut.utexts_desc)						[Error],
			tpclil.pli_idn											[ID]


	FROM	tbPriceCostListImportLog					tpclil	WITH (NOLOCK)

	LEFT JOIN tbCustomerPriceListBySOItemType			tc		WITH (NOLOCK)
		ON	tc.comp_id		= tpclil.comp_id	AND
			tc.cust_id		= tpclil.item_id

	LEFT JOIN tbUser									tu		WITH (NOLOCK)
		ON	tu.[user_id]	= tpclil.[user_id]

	LEFT JOIN tbsysUniqueTexts							tut		WITH (NOLOCK)
		ON	tut.lang_id		= @lang_id			AND
			tut.utexts_id	= 40151



	where	tpclil.comp_id = @comp_id AND
			tpclil.pli_id  = @guid


	ORDER BY tpclil.pli_id asc




END
GO

create PROCEDURE [dbo].[sptbMercadoLibre_Branchs_GetCombo]
(
	@comp_id	INT
)
AS
	BEGIN
