GO

CREATE PROCEDURE sptbMercadoLibre_ItemsPublicadosVariations_ExistsData
(
	@comp_id							INT,
	@mlp_id								INT,
	@item_id							INT
)
AS
	BEGIN
		SET NOCOUNT ON

		IF EXISTS(SELECT
					1
		          FROM tbMercadoLibre_ItemsPublicadosVariations tmlipv
		          WHERE tmlipv.comp_id	= @comp_id				AND
						tmlipv.mlp_id	= @mlp_id				AND
						tmlipv.item_id	= @item_id)
			BEGIN
				SELECT 'True'	[Exists]
			END
		ELSE
			BEGIN
				SELECT 'False'	[Exists]
			END

	END
GO








