CREATE procedure sptbSaleOrderItemGuidRelation4MultipleItemAdd_ChangeStatus
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@item_id	INT
)
as set nocount on

------------------------------------------------------------
-- Testing
------------------------------------------------------------
/*
	declare
		@comp_id	int,
		@guid		UNIQUEIDENTIFIER,
		@item_id	INT
	select
		@comp_id	= 1,
		@guid		= '0f8fad5b-d9cb-469f-a165-70867728950e',
		@item_id	= 256
*/
------------------------------------------------------------


if exists(select 1
		  from tbSaleOrderItemGuidRelation4MultipleItemAdd tsoigrmia
		  where tsoigrmia.comp_id	= @comp_id
		  and tsoigrmia.sor_guid	= @guid
		  and tsoigrmia.item_id		= @item_id
		 )

	begin
		delete from tbSaleOrderItemGuidRelation4MultipleItemAdd
		where	comp_id		= @comp_id
		and		sor_guid	= @guid
		and		item_id		= @item_id
	end
else
	begin
		insert into tbSaleOrderItemGuidRelation4MultipleItemAdd
		(comp_id,	sor_guid,	item_id)
		VALUES
		(@comp_id, 	@guid,		@item_id)
	end
GO






CREATE procedure [dbo].[sptbSaleOrderItemGuidRelation4MultipleItemAdd_GetStatus]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@item_id	INT,
	@bra_id		INT
)
as

BEGIN



	set nocount on

	------------------------------------------------------------
	-- Testing
	------------------------------------------------------------
	/*
		declare
			@comp_id	int,
			@guid		UNIQUEIDENTIFIER,
			@item_id	INT
		select
			@comp_id	= 1,
			@guid		= '0f8fad5b-d9cb-469f-a165-70867728950e',
			@item_id	= 256
	*/
	------------------------------------------------------------


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



	DECLARE @datProcessingDate AS DATETIME
	SELECT	@datProcessingDate = tb.bra_processingDate
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_Id AND
				tb.bra_id	= @bra_Id


	-- -----------------------------------------
	-- Verifica si tiene Impuestos internos
	-- -----------------------------------------
	DECLARE @bitHasInternalTaxes AS BIT
	SET @bitHasInternalTaxes = 'False'
	SELECT @bitHasInternalTaxes = 'True'
		FROM	tbItemTaxes tit		WITH (NOLOCK)
		INNER JOIN tbTaxName ttn	WITH (NOLOCK)
			ON	ttn.comp_id		= tit.comp_id AND
				ttn.tax_id		= tit.tax_id
		WHERE	tit.comp_id		= @comp_id AND
				tit.item_id		= @item_id AND
				ttn.tax_class	= 20
	-- -----------------------------------------


	-- ------------------------------------------------------
	-- Detecta si esta en una posible Publicacion
	-- ------------------------------------------------------
	DECLARE @bitIsPublication AS BIT
	SET		@bitIsPublication = 'False'
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbItemPublicationActiveItems tipai	WITH (NOLOCK)
					WHERE	tipai.comp_id = @comp_id AND
							tipai.item_id = @item_id
			)
		BEGIN
			SET @bitIsPublication = 'True'
		END
	-- ------------------------------------------------------

	-- ------------------------------------------------------
	-- Detecta si esta en una posible campaña
	-- ------------------------------------------------------
	DECLARE @bitIsInPossibleCampaign AS BIT
	IF EXISTS(
										SELECT TOP 1  1
											FROM tbItem	ti
												INNER JOIN tbItem_CommercialCampaign ticc	WITH (NOLOCK)
													ON	ticc.comp_id		= @comp_Id	AND
														(ticc.bra_id IS NULL OR  ticc.bra_id = @bra_Id)	AND
														ticc.camp_disabled	=	'False' AND
														ticc.camp_active    =   'True'  AND
														@datProcessingDate BETWEEN  ticc.camp_validFrom AND ticc.camp_validTo

											WHERE	ti.comp_id = @comp_id															AND
													ti.item_id = @item_id															AND
												   (ticc.item_id	IS NULL		OR  ti.item_id		= ticc.item_id)					AND
												   (ticc.cat_id		IS NULL		OR  ti.cat_id		= ticc.cat_id )	                AND
												   (ticc.subcat_id	IS NULL		OR  ti.subcat_id	= ticc.subcat_id)				AND
												   (ticc.supp_id	IS NULL		OR  ti.supp_id		= ticc.supp_id)					AND
												   (ticc.brand_id	IS NULL		OR  ti.brand_id		= ticc.brand_id)				AND
												   (ticc.camp_qtyCheck = 'False' OR (ticc.camp_qtyAvailable >= 1))
											)
		BEGIN
			SET @bitIsInPossibleCampaign = 'True'
		END
	ELSE
		BEGIN
			SET @bitIsInPossibleCampaign = 'False'
		END
	-- ------------------------------------------------------


	-- ------------------------------------------------------
	-- Detecta si tierne O.Compra Pendientes de Ingreso
	-- ------------------------------------------------------
	DECLARE @bitHavePurchaseorders AS BIT
	SET @bitHavePurchaseorders		= 'False'
	SELECT @bitHavePurchaseorders	= 'True'
		FROM tbPurchaseOrderDetail tpod	WITH (NOLOCK)
		WHERE	tpod.comp_id			= @comp_id	AND
				tpod.item_id			= @item_id	AND
				tpod.pod_isProcessed	= 'False'	AND
				tpod.pod_qty			> 0
	-- ------------------------------------------------------


	SELECT	CASE
				WHEN EXISTS (select TOP 1 1
								from tbSaleOrderItemGuidRelation4MultipleItemAdd tsoigrmia	WITH (NOLOCK)
								where tsoigrmia.comp_id		= @comp_id		AND
									  tsoigrmia.sor_guid	= @guid			AND
									  tsoigrmia.item_id		= @item_id
							)			THEN	1
				ELSE							0
			END														[IsSelected],
			IsNull(ti.item_newness,'False')							[IsNewNess],
			IsNull(ti.item_liquidation,'False')						[IsLiquidation],
			ISNULL(ti.item_outlet,'False')							[IsOutlet],
			ISNULL(ti.item_InAgeing,'False')						[InAgeIng],
			@bitIsInPossibleCampaign								[IsInCommercialCampaign],
			CASE
				WHEN EXISTS (
								SELECT TOP 1  1
									FROM tbItemExtendedWarranty tiew	WITH (NOLOCK)
									WHERE	tiew.comp_id = ti.comp_id AND
											tiew.item_id = ti.item_id

							)	THEN	1
				ELSE					0
			END														[IsExtendedWarranty],
			IsNull(@bitHavePurchaseorders,'False')					[HavePurchaseOrders],
			IsNull(@bitHasInternalTaxes,'False')					[HaveInternalTaxes],
			@bitIsPublication										[IsPublication],
			ISNULL(ti.item_cantMin,0)								[item_cantMin],
			ISNULL(ti.item_cantOpt,0)								[item_cantOpt],
			ISNULL(ti.item_daysWithOutSales,0)						[item_daysWithOutSales]
		FROM tbItem ti	WITH (NOLOCK)
		WHERE	ti.comp_id = @comp_id AND
				ti.item_id = @item_id







--	if exists(select 1
--				from tbSaleOrderItemGuidRelation4MultipleItemAdd tsoigrmia
--				where tsoigrmia.comp_id		= @comp_id			AND
--				      tsoigrmia.sor_guid	= @guid			AND
--				      tsoigrmia.item_id		= @item_id
--			 )
--
--		begin
--			SELECT 1
--		end
--	else
--		begin
--			SELECT 0
--		end



END
GO






CREATE PROCEDURE [dbo].[sptbsysControlPanelDetail_getDataByFilters]
(
	 @comp_id       INT,
	 @lang_id		INT,
	 @bra_id	    INT,
	 @brag_id       INT,
	 @dateFrom      DATETIME,
	 @dateTo		DATETIME,
	 @dateActual	DATETIME,
	 @id2Grid	    INT,
	 @id2Grid2	    INT,
	 @scpm_id	    INT,
	 @user_id		INT
)
as

set nocount on
SET DATEFORMAT 'ymd'


/*
DECLARE	@comp_id    INT,
		@lang_id	INT,
		@bra_id	    INT,
		@brag_id    INT,
		@scpm_id	INT,
		@dateFrom   DATETIME,
		@dateTo		DATETIME,
		@dateActual	DATETIME,
		@id2Grid	INT,
		@id2Grid2	INT

SELECT	@comp_id    = 1,
		@lang_id	= 2,
		@bra_id	    = 1,
		@brag_id    = 2,
		@scpm_id	= 1001000,
		@dateFrom   = '2009/01/01',
		@dateTo     = '2009/12/31',
		@dateActual = '2009/07/25',
		@id2Grid	= 54012,
		@id2Grid2	= 2
*/




DECLARE @name		    VARCHAR(8000),
		@case_id		INT,
		@rank			INT



SELECT 	@name			= tcpm.scpm_SPName4Grid,
		@case_id		= isnull(tcpm.scpm_case,0),
		@rank			= isnull(tcpm.scpm_rank,0)
FROM	dbo.tbsysControlPanelMeasures tcpm
WHERE	tcpm.scpm_id	= @scpm_id




IF	@case_id IN (4,8)
	EXEC @name @comp_id, @lang_id, @bra_id, @brag_id, @dateFrom, @dateTo,
			@dateActual, @id2Grid, @id2Grid2, @case_id, @rank, @user_id
ELSE
	EXEC @name @comp_id, @lang_id, @bra_id, @brag_id, @dateFrom, @dateTo,
			@dateActual, @id2Grid, @id2Grid2, @case_id, @user_id


GO










