-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	Incorpora el Padron ARBA
--				de Embargos a Proveedores
--				desde la carpeta del servidor
--		'C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\padronembargosarba.txt'
--    Instalar un Google Drive con Usuario gbp.taxes@gmail.com
-- =============================================
CREATE PROCEDURE [dbo].[sptbsysTaxJUJUY_BulkInsertData]
	@Option								AS INT,
	@return_value						as int			output,
	@ret_ErrorCode						as int			output,
	@ret_ErrorDescription				as varchar(200) output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	Set @return_value			= 0
	Set @ret_ErrorCode			= 0
	Set @ret_ErrorDescription	= '0'
	DECLARE @strExec AS VARCHAR(MAX)

	BEGIN TRY
		SET @ret_ErrorDescription = '0'

		EXEC sp_configure 'xp_cmdshell', 1
		RECONFIGURE


		BEGIN TRANSACTION
		--Select 'Deleting  AGIP Files . . .'
		TRUNCATE	TABLE	tbsysTaxJUJUY


		----Select 'Importing ARBA Files . . .'
		--set @strExec  = 'BULK	INSERT  tbsysTaxJUJUY
		--		FROM ''C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\PADRONJUJUY.txt''
		--		WITH (FIELDTERMINATOR ='','')'
		--      EXEC (@strExec)

		BULK	INSERT  tbsysTaxJUJUY
				FROM 'C:\GlobalBluePoint.GDrive\Google Drive\TaxFiles\PADRONJUJUY.txt'
				WITH (CODEPAGE='ACP',FIELDTERMINATOR =',',ROWTERMINATOR='\n',FIRSTROW = 2)




		--Select 'AGIP Files Imported  . . .'
		COMMIT TRANSACTION
	END TRY

	BEGIN CATCH

		Set @return_value			= -1
		Set @ret_ErrorCode			= -1

		Set @ret_ErrorDescription	= 'Error Importando Datos de ARBA - Padron de Embargos.-' +
			(SELECT
			--convert(varchar,ERROR_NUMBER())  + '-' +
			--convert(varchar,ERROR_SEVERITY())  + '-' +
			--convert(varchar,ERROR_STATE()) + '-' +
			--convert(varchar,ERROR_PROCEDURE())  + '-' +
			--convert(varchar,ERROR_LINE())  + '-' +
			ERROR_MESSAGE()
            )
		--Select 'AGIP Files NOT Imported  . . .'
		ROLLBACK TRANSACTION
	END CATCH

END
/*
BEGIN try
SELECT 1/0
END TRY
BEGIN catch
SELECT
			convert(varchar,ERROR_NUMBER())  + '-' +
			convert(varchar,ERROR_SEVERITY())  + '-' +
			convert(varchar,ERROR_STATE()) + '-' +
			--convert(varchar,ERROR_PROCEDURE())  + '-' +
			convert(varchar,ERROR_LINE())  + '-' +
			ERROR_MESSAGE()
END CATCH
*/
GO








CREATE PROCEDURE [dbo].[spTempItemStock_CheckExistence]
(


    @comp_id		INT,
	@item_id		INT,
	@guid			UNIQUEIDENTIFIER

)
AS



BEGIN

SET NOCOUNT ON

	-- ---------------------------------------------------------------
	-- Testing
	-- ---------------------------------------------------------------
	/*
	DECLARE 	@comp_id		INT,
				@item_id		INT,
				@guid			UNIQUEIDENTIFIER

	SELECT      @comp_id		= 1,
				@item_id		= 220,
				@guid			= '32d20995-5247-4a4c-a43d-942b703be4b0'
	*/
	-- ---------------------------------------------------------------



	if exists (SELECT TOP 1 	1
			from	dbo.tbTempItemStock tit			WITH (NOLOCK)
			where	tit.comp_id		= @comp_id
			AND		tit.tis_guid	= @guid
			AND		tit.item_id		= @item_id
			)


			begin
				SELECT 1
			end
	else
			begin
				SELECT 0
			end




END



GO


CREATE PROCEDURE [dbo].[spTempItemStock_ClearEnvioPackItems]
(
	@comp_id				INT,
	@tis_guid				UNIQUEIDENTIFIER
)
AS

BEGIN


	SET NOCOUNT ON

	-- Borra todos los items de este pedido que tengan que ver con enviopack
	DELETE
		FROM tbTempItemStock		WITH (ROWLOCK)
		FROM tbTempItemStock tis
		INNER JOIN tbDelivery td	WITH (ROWLOCK)
			ON	td.comp_id				= tis.comp_id	AND
				td.ENVIOPACK_item_id	= tis.item_id
		WHERE	td.comp_id				= @comp_id		AND
				tis.tis_guid			= @tis_guid



END
GO





