CREATE PROCEDURE [dbo].[spTempItemStock_Ctrl4PreInvoice]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@df_id			AS INT,
	@ct_transaction AS INT,
	@guid			AS UNIQUEIDENTIFIER,
	@curr_id				as int,
	@forcedExchangeCurrency as int,
	@forcedExchange			as decimal(19,6),
	@purchaseExchange		as bit
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @intDF_ID4PreInvoice AS INT
	SET		@intDF_ID4PreInvoice = NULL
	SELECT	@intDF_ID4PreInvoice = tdf.df_SaleOrder_InvoiceFirstPacking_df_id
			from tbDocumentsFile tdf												WITH (NOLOCK)
			LEFT JOIN tbDocumentsFile tdfPL											WITH (NOLOCK)
				ON	tdfPL.comp_id = @comp_id AND
					tdfPL.df_id = tdf.df_SaleOrder_InvoiceFirstPacking_df_id
		WHERE	tdf.comp_id		= @comp_id	AND
				tdf.df_id		= @df_id	AND
				tdf.sd_id		= 1								  AND 	-- Solo si es FACTURA el oroginal
				tdfPL.sd_id		= 2								  AND	-- y si el destino es REMITO
				tdfpl.df_SaleOrder_IsInvoiceFirstPacking = 'True'		-- y esta habilitado como remito de Fc. Adelantada


	-- Saca los parametros para grabar costos.
	DECLARE @intCosLisId	AS INT
	DECLARE	@bitIsPPP		AS BIT
	DECLARE @branch_curr_id AS integer
	SELECT	@intCosLisId	= tb.coslis_id,
			@bitIsPPP		= tb.bra_costlist_type,
			@branch_curr_id = tb.curr_id
		FROM	tbBranch tb			WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id





   IF @intDF_ID4PreInvoice IS NOT NULL
	BEGIN
		UPDATE tbTempItemStock	WITH (ROWLOCK)
			SET item_idfromPreInvoice = tmp.item_id,
				-- Eliminado por MOS 03-2017
				--tis_cost =  dbo.fnGetExchange2(@comp_id,
				--								CASE
				--									WHEN @bitIsPPP = 'True' THEN	ticl.coslis_price_aw
				--									ELSE							ticl.coslis_price
				--								END,
				--								ticl.curr_id,
				--								@curr_id,
				--								@branch_curr_id,
				--								@forcedExchangeCurrency,
				--								@forcedExchange,
				--								@purchaseExchange),
				tax_id	= vitooit.tax_id ,
				stor_id = NULL,
				item_id = NULL,
				-- Agregado por MOS 03-2017 ya que en [spItemTransactions_InsertData] se hace el tipo de cambio
				--tis_cost=	CASE
				--				WHEN @bitIsPPP = 'True' THEN	ticl.coslis_price_aw
				--				ELSE							ticl.coslis_price
				--			END	,
				--curr_id = ticl.curr_id
				tis_cost =  dbo.fnGetExchange2(@comp_id,
								CASE
									WHEN @bitIsPPP = 'True' THEN	ISNULL(ticl.coslis_price_aw,0)
									ELSE							ISNULL(ticl.coslis_price,0)
								END,
								ticl.curr_id,
								tmp.curr_id,
								@branch_curr_id,
								@forcedExchangeCurrency,
								@forcedExchange,
								@purchaseExchange)

		FROM tbTempItemStock tmp													--WITH (NOLOCK)
		LEFT JOIN vwItemTaxesOnlyOneIvaTax vitooit								WITH (NOLOCK)
		--INNER JOIN vwItemTaxesOnlyOneIvaTax vitooit								WITH (NOLOCK)
			ON	vitooit.comp_id = tmp.comp_id AND
				vitooit.item_id = tmp.item_id
		LEFT JOIN tbItemCostList ticl											WITH (NOLOCK)
			ON	ticl.comp_id	= @comp_id		AND
				ticl.coslis_id	= @intCosLisId	AND
				ticl.item_id	= tmp.item_id
		WHERE	tmp.tis_guid		= @guid	AND
				tmp.item_id			IS NOT NULL

		SELECT 10 [errorCode]	-- MOS 10-2021
		RETURN
		--RETURN 10
	END


	SELECT 1 [errorCode]		-- MOS 10-2021
	RETURN
   --RETURN 1
END
GO






