CREATE  PROCEDURE [dbo].[spTempItemStock_deleteData]
(
		@comp_id		int,
		@tis_id			int
)
as

BEGIN


	-- Borra calculo de cuotas de credito personal.
	DELETE FROM tbSaleOrderLoanTMP WHERE tis_id = @tis_id


	-- Se guarda cual es el tis_id_origin ya que en el website borra solo los que tienen un item_id y en pedidos solo los que no lo tienen.-
	DECLARE @intTis_Id_Origin			AS INT
	DECLARE @df_id						AS INT
	DECLARE @tis_qty					AS DECIMAL(19,6) = 0
	DECLARE @tis_canDeleteCOMBOInSO		AS BIT = 'False'  -- En realidad se usa para poder BORRAR un ITEM de un combo en una SO
	SELECT	@intTis_Id_Origin		= ttis.tis_id_origin,
			@df_id					= ttis.df_id,
			@tis_qty				= ttis.tis_qty,
			@tis_canDeleteCOMBOInSO = ISNULL(ttis.tis_canDeleteCOMBOInSO,'False')
		FROM tbTempItemStock ttis		WITH (NOLOCK)
		WHERE ttis.tis_id = @tis_id

	-- Deschequea los remitos pendientes de facturación
	DECLARE @lit_transaction INT

	SELECT @lit_transaction = ttis.it_transaction
		FROM tbTempItemStock ttis			WITH (NOLOCK)
		WHERE ttis.comp_id	= @comp_id
		AND ttis.tis_id		= @tis_id


		-- Des Selecciona SOLO si se borra un remito a facturar SIN DIVIDIR.
		update	dbo.tbItemTransactions
			set	   	it_packingInvoiceSelected		= 'false',
					it_packingInvoiceSelectedGuid	= NULL
					--,
					--it_packingInvoicePend		= 'true'   -- MOS 24-05-2019
			WHERE	comp_id			=	@comp_id				AND
					it_transaction	=	@lit_transaction		AND
					it_qty			= @tis_qty

	----

	Delete	dbo.tbtmpTax
		where	comp_id			= @comp_id
			and tis_id			= @tis_id


	Delete	dbo.tbTempItemStock
		where	comp_id			= @comp_id
			and tis_id			= @tis_id

	--MOS para poder borrar los items asociados
	Delete	dbo.tbtmpTax
		FROM dbo.tbtmpTax tt
			INNER JOIN dbo.tbTempItemStock ttis
			ON	ttis.comp_id		= tt.comp_id
			AND ttis.tis_id			= tt.tis_id

		where	tt.comp_id			= @comp_id
			and ttis.tis_id_origin 	= @tis_id

	Delete	dbo.tbSaleOrderLoanTMP
		FROM dbo.tbSaleOrderLoanTMP tt
			INNER JOIN dbo.tbTempItemStock ttis
			ON	ttis.comp_id		= tt.comp_id
			AND ttis.tis_id			= tt.tis_id

		where	tt.comp_id			= @comp_id
			and ttis.tis_id_origin 	= @tis_id




	Delete	dbo.tbTempItemStock
		where	comp_id				= @comp_id
			and tis_id_origin		= @tis_id



	-- ---------------------------------------------------------------------------------------
	-- Si en Documentos dice que borra todos los items si se borra alguno asociado, hace eso.!
	-- ---------------------------------------------------------------------------------------
	DECLARE @bitSaleOrderItemAsociation_DeleteAllIfDeleteOne AS BIT
	SELECT  @bitSaleOrderItemAsociation_DeleteAllIfDeleteOne = ISNULL(tdf.df_SaleOrderItemAsociation_DeleteAllIfDeleteOne,'False')
		FROM tbDocumentsFile tdf	WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id
			AND tdf.df_id	= @df_id
	IF	@bitSaleOrderItemAsociation_DeleteAllIfDeleteOne = 'True'		AND
		@tis_canDeleteCOMBOInSO							 = 'False'				-- Si se PERMITE borrar SOLO UN ITEM, NO borra el resto asociado.
		BEGIN

			BEGIN TRY

				Delete	dbo.tbtmpTax
					FROM dbo.tbtmpTax tt							WITH (NOLOCK)
						INNER JOIN dbo.tbTempItemStock ttis			WITH (NOLOCK)
						ON	ttis.comp_id		= tt.comp_id
						AND ttis.tis_id			= tt.tis_id
					where	tt.comp_id			= @comp_id
						and ttis.tis_id_origin 	= @intTis_Id_Origin

				Delete	dbo.tbTempItemStock
					where	comp_id				= @comp_id
						and tis_id_origin		= @intTis_Id_Origin

			END TRY
			BEGIN CATCH
			END CATCH

		END
	-- ---------------------------------------------------------------------------------------


END
GO






CREATE  PROCEDURE [dbo].[spTempItemStock_DeleteData_From_Packing]
(
	@comp_id		INT,
	@guid			UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON



DELETE 	dbo.tbtmpTax	WITH (ROWLOCK)
FROM	dbo.tbtmpTax							tt
		INNER JOIN dbo.tbTempItemStock			ttis		WITH (NOLOCK)
		ON	ttis.comp_id			= tt.comp_id
		AND ttis.tis_guid			= tt.tis_guid
		AND ttis.tis_id				= tt.tis_id
		AND NOT ttis.tis_function	IS NULL

WHERE 	ttis.comp_id	= @comp_id
AND   	ttis.tis_guid	= @guid



DELETE  tbTempItemStock	WITH (ROWLOCK)
WHERE	comp_id			= @comp_id
AND		tis_guid		= @guid
AND NOT tis_function	IS NULL





GO



