-- =============================================
-- Author:		MOS
-- Create date: 1-2011
-- Description:	Libera la TempItemStock al SALIR de un pedido
-- =============================================
CREATE PROCEDURE [dbo].[spTempItemStock_deleteDataByGuid]
	@comp_id	AS INT,
	@guid		AS UNIQUEIDENTIFIER
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	BEGIN TRY

		DELETE FROM tbtmpTax
			WHERE	comp_id		= @comp_id
				AND tis_guid	= @guid

		DELETE FROM tbSaleOrderLoanTMP
			WHERE	comp_id		= @comp_id AND
					tis_guid	= @guid

		DELETE FROM tbTempItemStock
			WHERE	comp_id		= @comp_id
				AND tis_guid	= @guid



	END TRY
	BEGIN CATCH
	END CATCH


END
GO






-- =============================================
-- Author:
--              MOS  07-2008
-- Borra los temporales una vez que grabo
-- todos los datos y pone el isediting
-- del cliente en falso.-
-- =============================================


CREATE  PROCEDURE [dbo].[spTempItemStock_deleteDataTByGuid]
(
		@comp_id		as int,
		@tis_guid		as uniqueidentifier,
		@cust_id		as int
)
as

Begin

	Set NoCount on

	BEGIN TRY


		-- Borra Temporal de Cuotas de Credito Personal-
		DELETE FROM tbSaleOrderLoanTMP	WITH (ROWLOCK)
			WHERE tis_guid = @tis_guid

		-- Estaba Ultima
		Delete dbo.tbAutorizationRequest	WITH (ROWLOCK)
			Where aure_guid = @tis_guid


		Delete	dbo.tbtmpTax	WITH (ROWLOCK)
		where	comp_id			= @comp_id
			and tis_guid		= @tis_guid

		DELETE dbo.tbSaleOrderExtendedDiscountTmp	WITH (ROWLOCK)
		WHERE comp_id			= @comp_id
			AND guid			= @tis_guid

		Delete	dbo.tbTempItemStock	WITH (ROWLOCK)
		where	comp_id			= @comp_id
			and tis_guid		= @tis_guid

		Update dbo.tbCustomer	WITH (ROWLOCK)
			Set cust_isEditing = 'False'
			Where	comp_id = @comp_id
				and cust_id = @cust_id

	END TRY
	BEGIN CATCH
		/*
			SELECT
				ERROR_NUMBER() AS ErrorNumber,
				ERROR_SEVERITY() AS ErrorSeverity,
				ERROR_STATE() AS ErrorState,
				ERROR_PROCEDURE() AS ErrorProcedure,
				ERROR_LINE() AS ErrorLine,
				ERROR_MESSAGE() AS ErrorMessage
		*/
	END CATCH




End
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spTempItemStock_DeleteItem4Loan]
	@comp_id			INT,
	@tis_guid			UNIQUEIDENTIFIER,
	@item_id			INT,
	@df_id4debitNote	INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	DELETE		tbSaleOrderLoanTMP
		FROM	tbSaleOrderLoanTMP tmp
		INNER JOIN tbTempItemStock ttis
			ON	ttis.comp_id	= tmp.comp_id AND
				ttis.tis_id		= tmp.tis_id
		WHERE	ttis.tis_guid	= @tis_guid


	DELETE tbtmpTax
		FROM tbtmpTax tmp
		INNER JOIN tbTempItemStock ttis
			ON	ttis.comp_id	= tmp.comp_id AND
				ttis.tis_id		= tmp.tis_id
		WHERE	ttis.tis_guid	= @tis_guid




	DELETE FROM tbTempItemStock
		WHERE	tis_guid	= @tis_guid AND
				item_id		= @item_id


	UPDATE tbTempItemStock
		SET	tis_3rdSales_NoGenerateCharges	= 'True',
			tis_3rdSales_CeroLoanPercent	= 'True',
			tis_3rdSales_NoEraseCharges		= 'True'
		WHERE tis_guid = @tis_guid

END
GO

-- =============================================
-- Author:		MOS: 11-2019  Idiota de Bed Coll
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE spTempItemStock_DeleteItemWithStorageNotInMyStorages
	@comp_id	AS INT,
	@guid		AS UNIQUEIDENTIFIER,
	@bra_id		AS INT,
	@prof_id	AS INT,
	@user_id	AS INT
AS
BEGIN

	SET NOCOUNT ON;

	DELETE   tbTempItemStock
		FROM tbTempItemStock							ttis	WITH (NOLOCK)
		LEFT JOIN tbStorage_TransferConfiguration4Send 	tstc	WITH (NOLOCK)
		ON	tstc.comp_id		= ttis.comp_id	AND
			tstc.bra_id			= @bra_id		AND
			tstc.[user_id]		= @user_id		AND
			tstc.prof_id		= @prof_id		AND
			tstc.stor_id		= ttis.stor_id
		WHERE	ttis.comp_id	= @comp_id		AND
				ttis.tis_guid	= @guid			AND
				tstc.comp_id IS NULL

END
GO


