CREATE PROCEDURE [dbo].[spTempItemStock_divideItem]
(
		@tis_id			int,
		@tis_qty		decimal(19,5),
		@return_value   int output
)
AS


BEGIN


	set nocount on


	/*
	declare @tis_id		int,
			@tis_qty	decimal(19,5)
	select	@tis_id		=133,
			@tis_qty	=20
	*/



	/*************************************************************************************************/
	/* declarar las variables para almacenar los valores originales **********************************/
	/*************************************************************************************************/
	declare	@lcomp_id		int,
			@ltis_guid		uniqueidentifier,
			@ltis_priority	decimal(14,4),
			@litem_id		int,
			@ltis_itemDesc	varchar(100),
			@ltis_detail	varchar(100),
			@lcurr_id		int,
			@ltis_initQty	decimal(19,5),
			@ltis_qty		decimal(19,5),
			@lprli_id		int,
			@ltis_price		decimal(19,6),
			@lstor_id		int,
			@lbra_id		int,
			@luser_id		int,
			@ltis_CD		datetime,
			@lsoh_id		int,
			@ldoc_id		int,
			@lrv			int,
			@soh_id			int,
			@tis_cost		decimal(19,6),
			@tis_costTax	INT,
			@sod_id			INT,
			@ltis_IsMade	BIT
	/*************************************************************************************************/



	/*************************************************************************************************/
	/* recuperar los valores del id original en las variables declaradas *****************************/
	/*************************************************************************************************/
	select	@lcomp_id		= comp_id,
			@ltis_guid		= tis_guid,
			@ltis_priority	= tis_priority,
			@litem_id		= item_id,
			@ltis_itemDesc	= tis_itemDesc,
			@ltis_detail	= tis_detail,
			@lcurr_id		= curr_id,
			@ltis_initQty	= tis_initQty,
			@ltis_qty		= tis_qty,
			@lprli_id		= prli_id,
			@ltis_price		= tis_price,
			@lstor_id		= stor_id,
			@ldoc_id		= doc_id,
			@ltis_CD		= tis_CD,
			@lbra_id		= bra_id,
			@lsoh_id		= soh_id,
			@luser_id		= user_id,
			@ldoc_id		= doc_id,
			@soh_id			= soh_id,
			@tis_cost	    = tis_cost,
			@tis_costTax	= tis_costTax,
			@ltis_isMade	= tis.tis_isMade,
			@sod_id			= tis.sod_id

	from	dbo.tbTempItemStock				tis		WITH (NOLOCK)
	where	tis.tis_id	=	@tis_id
	/*************************************************************************************************/



	/*************************************************************************************************/
	/* obtener el máximo valor de prioridad, a partir del que se calcularán los nuevos valores *******/
	/*************************************************************************************************/
	declare @max_priority	decimal(14,4)
	select	@max_priority = max(tis_priority)
	from	dbo.tbTempItemStock
	where	tis_priority between cast(@ltis_priority as integer) and cast(@ltis_priority as integer) + 0.9999
	/*************************************************************************************************/



	/*************************************************************************************************/
	/*************************************************************************************************/
	/*************************************************************************************************/
	declare @qty	decimal(19,5)
	select	@qty = (@ltis_qty-@tis_qty)
	/*************************************************************************************************/



	/*************************************************************************************************/
	/*************************************************************************************************/
	/*************************************************************************************************/
	set @ltis_priority = @max_priority + 0.0001
	/*************************************************************************************************/



	/*************************************************************************************************/
	/* actualización del ítem original con la cantidad original menos la solicitada ******************/
	/*************************************************************************************************/
	exec	dbo.spTempItemStock_updateData
				@tis_id,
				@ltis_priority,
				@litem_id,
				@ltis_itemDesc,
				@ltis_detail,
				@lcurr_id,
				@qty,
				@lprli_id,
				@ltis_price,
				@tis_cost,
				@tis_costTax,
				@lstor_id,
				@lbra_id,
				@ldoc_id,
				@luser_id,
				@lcomp_id,
				@ltis_IsMade

	/*************************************************************************************************/



	/*************************************************************************************************/
	/*************************************************************************************************/
	/*************************************************************************************************/
	set @ltis_priority = @max_priority + 0.0002
	/*************************************************************************************************/



	/*************************************************************************************************/
	/* generación del nuevo ítem con la cantidad seleccionada ****************************************/
	/*************************************************************************************************/
	declare @tmpDate as datetime
	Set @tmpDate = getdate()



	INSERT INTO tbTempItemStock
	(
		comp_id,
		-- tis_id -- this column value is auto-generated
		tis_guid,
		tis_priority,
		item_id,
		tis_detail,
		curr_id,
		tis_initQty,
		tis_qty,
		prli_id,
		tis_priceInBranchCurrency,
		tax_id,
		tis_cost,
		tis_costTax,
		stor_id,
		doc_id,
		tis_CD,
		bra_id,
		soh_id,
		tis_insertDate,
		[user_id],
		aure_id,
		aure_itemComposed,
		tis_itemDiscount,
		tis_CreditInt,
		tis_CreditIntPlus,
		tis_itemDiscountTotal,
		tis_totalDiscountTOTAL,
		tis_isQuotation,
		tis_isCredit,
		tis_IsEditing,
		tis_IsEditingCd,
		tis_production,
		so_id,
		it_transaction,
		tis_note1,
		tis_note2,
		tis_function,
		sod_id,
		tis_id_origin,
		tis_item_id_origin,
		tis_isParentAssociate,
		is_id,
		it_transaction_original,
		it_transaction_NoStockDiscount,
		tis_order,
		tis_isMade,
		rmah_id,
		rmad_id,
		tis_expirationDate,
		df_id,
		acc_count_id,
		tis_StockStatus,
		tis_PackagesQty,
		tis_DeliveryCharge,
		cust_id,
		tis_priceInBranchCurrencyWithDiscount,
		item_id_EW,
		tis_idOfThisEW,
		tis_costForced2All,
		camp_id,
		tis_price,
		impData_Number_localPreAssignedByFiscal,
		impData_Custom_localPreAssignedByFiscal,
		sdlmt_id,
		sreas_id,
		tis_loanNumberOfPays,
		tis_loanDateOfFirstPay,
		tis_loanDayOfMonthOfNextPays,
		tis_tmpTAX4Credit,
		sod_itemDeliveryDate,
		sod_isFromPCConfigCTRLId,
		st_id,
		sct_id,
		sod_EWAddress,
		tis_inCash,
		tis_3rdSales_NoGenerateCharges,
		tis_3rdSales_CeroLoanPercent,
		tis_3rdSales_NoEraseCharges,
		ccp_id,
		tis_CreditIntPercentage,
		tis_CreditIntPlusPercentage,
		tis_itemIDOfThisEW,
		tis_disableEraseOfDeliveryCharges,
		sod_PCCOnfigIsTransfered2Branch,
		item_idfromPreInvoice,
		sod_MLCost,
		tis_divideOrder,
		tis_itemAssociationCoeficient,
		ws_IPFrom,
		-- tis_totalPriceInBranchCurrency -- this column value is auto-generated
		ws_price,
		ws_curr_Id,
		sops_id,
		mlo_id,
		sops_supp_id,
		sops_bra_id,
		sops_date,
		sod_MECost,
		sod_MPCost,
		tis_isDivided,
		tis_isDivided_Date,
		user_id_division,
		sodi_id,
		tis_isDivided_costCoeficient,
		tis_itemDesc,
		sops_poh_bra_id,
		sops_poh_id,
		sops_note,
		sops_user_id,
		sops_lastUpdate,
		ct_transaction,
		ct_transaction_SelectFromPacking,
		sodt_qty,
		tis_disablePrintInEmmition,
		tis_comboCoeficient,
		tis_isEnvioPackItem
	)

		SELECT
		 comp_id  ,
		 tis_guid  ,
		 @ltis_priority  ,
		 item_id  ,
		 tis_detail  ,
		 curr_id  ,
		 tis_initQty  ,
		 @tis_qty  ,
		 prli_id  ,
		 tis_priceInBranchCurrency  ,
		 tax_id  ,
		 tis_cost  ,
		 tis_costTax  ,
		 stor_id  ,
		 doc_id  ,
		 tis_CD  ,
		 bra_id  ,
		 soh_id  ,
		 tis_insertDate  ,
		 [user_id]  ,
		 aure_id  ,
		 aure_itemComposed  ,
		 tis_itemDiscount  ,
		 tis_CreditInt  ,
		 tis_CreditIntPlus  ,
		 tis_itemDiscountTotal  ,
		 tis_totalDiscountTOTAL  ,
		 tis_isQuotation  ,
		 tis_isCredit  ,
		 tis_IsEditing  ,
		 tis_IsEditingCd  ,
		 tis_production  ,
		 so_id  ,
		 it_transaction  ,
		 tis_note1  ,
		 tis_note2  ,
		 tis_function  ,
		 sod_id  ,
		 tis_id_origin  ,
		 tis_item_id_origin  ,
		 tis_isParentAssociate  ,
		 is_id  ,
		 it_transaction_original  ,
		 it_transaction_NoStockDiscount  ,
		 tis_order  ,
		 tis_isMade  ,
		 rmah_id  ,
		 rmad_id  ,
		 tis_expirationDate  ,
		 df_id  ,
		 acc_count_id  ,
		 tis_StockStatus  ,
		 tis_PackagesQty  ,
		 tis_DeliveryCharge  ,
		 cust_id  ,
		 tis_priceInBranchCurrencyWithDiscount  ,
		 item_id_EW  ,
		 tis_idOfThisEW  ,
		 tis_costForced2All  ,
		 camp_id  ,
		 tis_price  ,
		 impData_Number_localPreAssignedByFiscal  ,
		 impData_Custom_localPreAssignedByFiscal  ,
		 sdlmt_id  ,
		 sreas_id  ,
		 tis_loanNumberOfPays  ,
		 tis_loanDateOfFirstPay  ,
		 tis_loanDayOfMonthOfNextPays  ,
		 tis_tmpTAX4Credit  ,
		 sod_itemDeliveryDate  ,
		 sod_isFromPCConfigCTRLId  ,
		 st_id  ,
		 sct_id  ,
		 sod_EWAddress  ,
		 tis_inCash  ,
		 tis_3rdSales_NoGenerateCharges  ,
		 tis_3rdSales_CeroLoanPercent  ,
		 tis_3rdSales_NoEraseCharges  ,
		 ccp_id  ,
		 tis_CreditIntPercentage  ,
		 tis_CreditIntPlusPercentage  ,
		 tis_itemIDOfThisEW  ,
		 tis_disableEraseOfDeliveryCharges  ,
		 sod_PCCOnfigIsTransfered2Branch  ,
		 item_idfromPreInvoice  ,
		 sod_MLCost  ,
		 tis_divideOrder  ,
		 tis_itemAssociationCoeficient  ,
		 ws_IPFrom  ,
		 ws_price  ,
		 ws_curr_Id  ,
		 sops_id  ,
		 mlo_id  ,
		 sops_supp_id  ,
		 sops_bra_id  ,
		 sops_date  ,
		 sod_MECost  ,
		 sod_MPCost  ,
		 tis_isDivided  ,
		 tis_isDivided_Date  ,
		 user_id_division  ,
		 sodi_id  ,
		 tis_isDivided_costCoeficient  ,
		 tis_itemDesc  ,
		 sops_poh_bra_id  ,
		 sops_poh_id  ,
		 sops_note  ,
		 sops_user_id  ,
		 sops_lastUpdate  ,
		 ct_transaction  ,
		 ct_transaction_SelectFromPacking  ,
		 sodt_qty  ,
		 tis_disablePrintInEmmition  ,
		 tis_comboCoeficient  ,
		 tis_isEnvioPackItem
		FROM tbTempItemStock ttis	WITH (NOLOCK)
		WHERE	ttis.comp_id	= @lcomp_id AND
				ttis.tis_id		= @tis_id



	set	@return_value = @@IDENTITY



END
GO



