						ISNULL(ttis.item_id,-1)				[item_id]
						FROM tbTempItemStock								ttis		WITH (NOLOCK)
						WHERE	ttis.comp_id					= @comp_id	AND
								ttis.tis_guid					= @guid		AND
								ttis.sod_isFromPCConfigCTRLId	= 99

			END
		ELSE
			BEGIN
				SELECT 'False'
			END
	END
GO





-- =============================================
-- Author:		MOS
-- Create date: 06-2013
-- Description:	Recalcula precios si se cambia la lista
-- =============================================
CREATE PROCEDURE [dbo].[spTempItemStock_ForcePrice2ListByGuid]
	@comp_id	AS INT,
	@guid		AS UNIQUEIDENTIFIER,
	@prli_id	AS INT,
	@df_id		AS INT
AS
BEGIN

	SET NOCOUNT ON;

	UPDATE tbTempItemStock
		SET
			curr_id		= tpli.curr_id,
			prli_id		= @prli_id,
			tis_price	= tpli.prli_price * -- Si en el documento dice q al cambiar de lista en pedidos recalcule por coeficiente lo hace
											CASE
												WHEN tdf.df_saleOrder_PriceListChangeCOMBORecalculateByCoeficient = 'True' THEN		ISNULL(ttis.tis_itemAssociationCoeficient,1)
												ELSE																				1
											END

		FROM tbTempItemStock ttis
		INNER JOIN tbDocumentsFile tdf				WITH (NOLOCK)
			ON	tdf.comp_id		= @comp_id AND
				tdf.df_id		= @df_id
		INNER JOIN vwPriceListItems tpli			WITH (NOLOCK)
			ON	tpli.comp_id	= @comp_id					AND
				tpli.prli_id	= @prli_id					AND
				tpli.item_id	= ttis.item_id
		WHERE	ttis.comp_id	= @comp_id					AND
				ttis.tis_guid	= @guid						AND
				(
					tdf.df_SaleOrder_ChangePriceOnPriceListChange = 1 OR
				   (tdf.df_SaleOrder_ChangePriceOnPriceListChange = 2 AND
						(
							ttis.curr_id	<> tpli.curr_id		OR
							ttis.tis_price	<  tpli.prli_price
						)
				   )
				)

END
GO


CREATE PROCEDURE [dbo].[spTempItemStock_funExistsItemFromOtherDocument]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	BEGIN
		SET NOCOUNT ON
		IF EXISTS (
					SELECT TOP 1
						1
						FROM tbTempItemStock								ttis		WITH (NOLOCK)
						WHERE	ttis.comp_id					= @comp_id	AND
								ttis.tis_guid					= @guid		AND
								ttis.it_transaction	IS NOT NULL
				  )
			BEGIN
					SELECT 1								[Status]
			END
		ELSE
			BEGIN
				SELECT 0
			END
	END
GO







-- -----------------------------------------------------------------
-- Modif. MOS 05-2008
-- OJO!!!!!    Si se agregan campos, agregarlos entre las etiquetas
-- de lugar de campos admitidos. JAMAS en otro lugar
-- porque hay problermas con la grilla de pedidos.-
-- -----------------------------------------------------------------


CREATE PROCEDURE [dbo].[spTempItemStock_getData]
(
	@comp_id			int,
	@tis_guid			uniqueidentifier,
	@intMaxItems		INT
)
AS


BEGIN

	SET NOCOUNT ON


-- --------------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------------
	/*
	declare @comp_id			int,
			@tis_guid			uniqueidentifier,
			@intMaxItems		INT
	select	@comp_id			=1,
			@tis_guid			='70CA7C36-977D-4C7B-8EF9-18796F0BFE1F',
			@intMaxItems		=10
	*/
-- --------------------------------------------------------------------

	DECLARE @intPlusIva AS INT
	SET @intPlusIva = 1



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @bithideDecimalsOnStock AS BIT
	SELECT	@bithideDecimalsOnStock = tc.comp_hideDecimalsOnStock
		FROM tbCompany tc		WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id



	-- ATENCION!!!!!!!!!!!!
	-- No poner ningun campo nuevo aqui sin que MOS lo vea!
	-- OJO que hay lugares en SALEORDER que hacen referencia a los campos por INDEX y no se puede hacer por NOMBRE. OJOOOOOOOO


	select	TOP (@intMaxItems)
			ISNULL(tis.tis_id_origin, -1) [_a],
			' ' [_b],
			' ' [_c],
			' ' [_d],
			' '	[_e],
			tis.tis_guid,
			tis.tis_priority,
			tis.item_id,
			dbo.fnStrPADR(tis.tis_itemDesc,50,' ') +
														CASE
															WHEN tis.camp_id IS NOT NULL THEN '*CC*'
															ELSE ''
														END
																	[tis_itemDesc],
			CASE
				WHEN ewi.item_id IS NOT NULL THEN ewi.item_desc
				WHEN tis.tis_idOfThisEW IS NOT NULL THEN ':' + CONVERT(NVARCHAR(10),tis.tis_idOfThisEW)
				WHEN EXISTS(SELECT TOP 1  1
								FROM tbItemExtendedWarranty tiew WITH (NOLOCK)
								WHERE	tiew.comp_id = tis.comp_id AND
										tiew.item_id = tis.item_id) THEN '*EW*'
				ELSE '*--*'														  -- A T E N C I O N!!!!!!!!!!
			END													[EWItemId],  -- Campo (11) wfmSaleOrder **EW.  Este es el campo 11, si se pone algo antes hay que modificar el orden en la etiqueta indicada.!!!
			s.stor_desc,
			Convert( decimal(19,4),tis.tis_qty)					[tis_qty],  -- Campo (13)  Cantidad sin decimales !!!
			pl.prli_desc,


			Convert( DECIMAL(19,4), ROUND(( tis.tis_price
											+
											ROUND((tis.tis_CreditInt / dbo.fnNoZDiv(tis.tis_qty)  )*(tis.tis_price / dbo.fnNoZDiv( tis.tis_priceInBranchCurrency)),2) -- Intereses en moneda Original
																			+ dbo.fntbTempItemStock_getIVA(@comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,tis.tis_priceInBranchCurrency / dbo.fnNoZDiv( tis.tis_price ),tis.tis_qty )
										- (((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv( tis.tis_priceInBranchCurrency / dbo.fnNoZDiv(tis.tis_price )) ) / dbo.fnNoZDiv(tis.tis_qty) )	),tdf.df_PriceDecimalPlaces )	 )																																[tis_price],



			Convert( DECIMAL(19,4), ROUND( tis.tis_price,tdf.df_PriceDecimalPlaces 	 ))																																																																								[tis_priceNoTax],
			c.curr_symbol																																																																																							[curr_desc],


			Convert( decimal(19,4), ROUND((  (tis.tis_priceInBranchCurrency + (tis_CreditInt / dbo.fnNoZDiv(tis.tis_qty) ))	 + dbo.fntbTempItemStock_getIVA(@comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,1,tis.tis_qty )												- ((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv(tis.tis_qty))	),tdf.df_PriceDecimalPlaces ))					[tis_priceInBC2Show],


			Convert( decimal(19,2), ROUND((  (tis.tis_priceInBranchCurrency + (tis_CreditInt / dbo.fnNoZDiv(tis.tis_qty) ))  + dbo.fntbTempItemStock_getIVA(@comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,1,tis.tis_qty )												- ((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv(tis.tis_qty))	),2 )*  tis.tis_qty )  							[tis_priceInBC2ShowTotal],


			tis.tis_detail,
			tis.curr_id,
			Convert( decimal(19,3),tis_itemDiscount)			[tis_itemDiscount],
			Convert( decimal(19,3),tis.tis_itemDiscountTotal)	[tis_itemDiscountTotal],
			Convert( decimal(19,3),tis_CreditInt)				[tis_CreditInt],
			Convert( decimal(19,3),tis_CreditIntPlus)			[tis_CreditIntPlus],
			isnull(i.item_code,'')			[item_code],
			tis.tis_initQty,
			tis.prli_id,
			tis.stor_id,
			tis.doc_id,
			tis.tis_CD,
			tis.bra_id,
			b.bra_desc,
			tis.soh_id,
			tis.tis_insertDate,
			tis.user_id,
			tis.aure_id,
			tis.tax_id,
			ISNULL(ttn.tax_desc,ISNULL(ttnm.tax_desc,'*'))		[tax_desc],
			aure_itemComposed,
			tis.tis_itemDesc	+	CASE	-- Pone un * si es por cuenta y orden
										WHEN tib.comp_id IS NOT NULL	THEN ' *'
										WHEN i.byor_id IS NOT NULL		THEN '*'
										ELSE								 ''
									END								[CompleteItemDesc],

			-- ----------------------------------------------------
			-- Agregar aca campos nuevos
			--
			-- A t e n c i o n !!!!!!!!!!!!!
			--
			-- Para ver donde hay que sacar columnas en el codigo vb buscar: **TIS-COL
			--
			-- ATENCION: Sacar las columnas nuevas de **SAJI778PO56 en VB
			--
			-- ----------------------------------------------------
			Convert( decimal(19,4),ROUND(
								(
									tis.tis_priceInBranchCurrency	+ dbo.fntbTempItemStock_getIVA(@comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,1,tis.tis_qty )															  - ((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv(tis.tis_qty))
								) + tis_CreditInt + tis_CreditIntPlus

							 ,tdf.df_PriceDecimalPlaces
							)	 )								[tis_priceInBC2ShowWithLOANCharges],
			tis.tis_loanNumberOfPays,

			tis.is_id,
			isnull(tis2.is_serial,'')							[is_serial],
			tis.tis_order,




			IsNull(I.item_guarantee,0)							[Warranty],

			-- MOS 22-02-2022
			tis.sod_itemDeliveryDate,

			-- MOS 03-2023
			ISNULL(tu.user_lastname,'') + ', ' +
			ISNULL(tu.user_firstname,'')						[userName],








			-- ----------------------------------------------------------------------------------------
			-- ATENCIONNNN!!!!!!!!
			-- MOS 02-2022:
			-- NO poner nada después de acá.
			-- ----------------------------------------------------------------------------------------
			ISNULL(tdf.df_Fiscal_ItemCodeFirstInPrint,'False')	[df_Fiscal_ItemCodeFirstInPrint],
			CASE
				WHEN	tis.sod_isFromPCConfigCTRLId IS NULL THEN 'False'
				ELSE										      'True'
			END													[sod_isFromPCConfig],
			CASE
				WHEN	tis.sod_isFromPCConfigCTRLId IS NOT NULL		AND
						tsc.subcat_pcConfigType = 1								THEN	tis.tis_qty
				WHEN	tis.sod_isFromPCConfigCTRLId IS NOT NULL		AND
						tsc.subcat_pcConfigType <> 1							THEN	0
				WHEN	tis.sod_isFromPCConfigCTRLId IS     NULL		AND
						tsc.subcat_pcConfigType = 1								THEN	tis.tis_qty
				ELSE																	0
			END													[sod_isFromPCConfigQTY],


			-- ----------------------------------------------------








			-- ATENCION!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
			-- Si tocas este orden final... se arma..!!!
			-- !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!



			--Count - 12
			IsNull(tis.tis_DeliveryCharge,'False')   [tis_DeliveryCharge],

			--COUNT - 11
			tis.tis_priceInBranchCurrency,

			--COUNT - 10
			CONVERT(DECIMAL(19,2),
			CASE
				WHEN tdf.sd_id  = 80 THEN tis.tis_StockStatus
				ELSE dbo.fnGetStock(@comp_id, tis.stor_id, tis.item_id)
			END		)	 [STK],
			--COUNT - 9
			tis.tis_qty  [TISQTY],

			--COUNT - 8
			tis.stor_id [STORID],

			-- COUNT - 7
			tis.item_id [ITEMID],

			--COUNT - 6
			tis.it_transaction				[it_transaction],	-- Para poder saber si se saco de algo pendiente de facturar o pendiente de hacer una nota de credito

			-- Count - 5
			CONVERT(DECIMAL(19,2),
			CASE
			    WHEN tis.item_id IS NOT null  THEN tis.tis_StockStatus
			    ELSE 0
			END		)						[on_hand_included],
--			dbo.fnGetAStock(@comp_id,
--						tis.stor_id,
--						tis.item_id,
--						case
--							WHEN tis.it_transaction IS NULL THEN  tis.tis_priority
--							ELSE 999999999
--						end) as on_hand_included,

			-- Count - 4
			isnull((select	1
					from	dbo.tbAutorizationRequest	ar	WITH (NOLOCK)
					where	ar.comp_id			=	tis.comp_id
					and		ar.aure_guid		=	tis.tis_guid
					and		ar.aure_genericId	=	tis.tis_id
					and		ar.aure_isok		=	'P'
					group by ar.aure_isok),0)  [P],
			-- Count - 3
			isnull((select	1
					from	dbo.tbAutorizationRequest	ar	WITH (NOLOCK)
					where	ar.comp_id			=	tis.comp_id
					and		ar.aure_guid		=	tis.tis_guid
					and		ar.aure_genericId	=	tis.tis_id
					and		ar.aure_isok		=	'A'
					group by ar.aure_isok),0)  [A],
			-- Count - 2
			isnull((select	1
					from	dbo.tbAutorizationRequest	ar		WITH (NOLOCK)
					where	ar.comp_id			=	tis.comp_id
					and		ar.aure_guid		=	tis.tis_guid
					and		ar.aure_genericId	=	tis.tis_id
					and		ar.aure_isok		=	'U'
					group by ar.aure_isok),0)   [U],


			tis.tis_id --el id tiene que estar obligatoriamente en última posición



	from	dbo.tbTempItemStock				tis					WITH (NOLOCK)

			left join tbSysCurrency		c						WITH (NOLOCK)
			on	c.curr_id	= tis.curr_id

			left join dbo.tbPriceList		pl					WITH (NOLOCK)
			on	pl.comp_id	= tis.comp_id
			and pl.prli_id	= tis.prli_id

			left join dbo.tbStorage		s						WITH (NOLOCK)
			on	s.comp_id	= tis.comp_id
			and s.stor_id	= tis.stor_id

			left join dbo.tbBranch			b					WITH (NOLOCK)
			on	b.comp_id	= tis.comp_id
			and b.bra_id	= tis.bra_id

			left join dbo.tbItem			i					WITH (NOLOCK)
			on	i.comp_id	= tis.comp_id
			and i.item_id   = tis.item_id

			LEFT JOIN tbSubCategory tsc							WITH (NOLOCK)
			ON	tsc.comp_id		= i.comp_id AND
				tsc.cat_id		= i.cat_id	AND
				tsc.subcat_id	= i.subcat_id

			LEFT JOIN vwItemTaxesOnlyOneIvaTax	tmpt			WITH (NOLOCK)
				ON	tmpt.comp_id = i.comp_id AND
					tmpt.item_id = i.item_id

			LEFT JOIN tbTaxName ttn								WITH (NOLOCK)
				ON	ttn.comp_id = tmpt.comp_id AND
					ttn.tax_id	= tmpt.tax_id

			LEFT JOIN tbTaxName ttnm							WITH (NOLOCK)
				ON	ttnm.comp_id	= tis.comp_id AND
					ttnm.tax_id		= tis.tis_costTax

			LEFT JOIN tbItemSerials tis2						WITH (NOLOCK)
			ON  tis2.comp_id = tis.comp_id AND
				tis2.is_id   = tis.is_id


			LEFT JOIN tbitem ewi								WITH (NOLOCK)
			ON  ewi.comp_id = tis.comp_id AND
				ewi.item_id = tis.item_id_EW

			INNER JOIN tbDocumentsFile tdf						WITH (NOLOCK)
				ON	tdf.comp_id = tis.comp_id AND
					tdf.df_id	= tis.df_id


			LEFT JOIN tbItemByOrderByBranch tib					WITH (NOLOCK)
				ON	tib.comp_id = @comp_id		AND
					tib.bra_id	= tis.bra_id	AND
					tib.item_id = tis.item_id

			LEFT JOIN tbUser							AS tu	WITH (NOLOCK)
				ON tu.[user_id] = tis.[user_id]

	where	--tis.comp_id		=	@comp_id
			tis.tis_guid	=	@tis_guid				-- x como esta el indice es mas rapido asi


	order by tis.tis_order,tis.tis_id


END
GO



CREATE PROCEDURE [dbo].[spTempItemStock_GetDataByGuid4PCConfig]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER
)
AS
	SET NOCOUNT ON
		BEGIN
			SELECT
				ttis.tis_id,
				ttis.tis_guid,
				ttis.item_id,
				ttis.tis_qty,
				CONVERT(DECIMAL(19,2),ttis.tis_price)	[tis_price],
				ttis.sod_isFromPCConfigCTRLId,
				tc.curr_symbol

			FROM tbTempItemStock					ttis
				INNER JOIN tbsysCurrency			tc
					ON	tc.curr_id	= ttis.curr_id

			WHERE	ttis.comp_id					= @comp_id		AND
					ttis.tis_guid					= @guid			AND
					ttis.sod_isFromPCConfigCTRLId	IS NOT NULL

			ORDER BY ttis.sod_isFromPCConfigCTRLId ASC
		END

GO



CREATE PROCEDURE [dbo].[spTempItemStock_GetDataByGuidAndControl4PCConfig]
(
	@comp_id	INT,
	@guid		UNIQUEIDENTIFIER,
	@control_id	INT
)
AS
	SET NOCOUNT ON
		BEGIN

			SELECT
				ttis.tis_id,
				ttis.item_id,
				ttis.tis_qty,
				ttis.sod_isFromPCConfigCTRLId,
				ttis.stor_id,
				ttis.prli_id

			FROM tbTempItemStock									ttis
			WHERE	ttis.comp_id					= @comp_id		AND
					ttis.tis_guid					= @guid			AND
					ttis.sod_isFromPCConfigCTRLId	= @control_id

		END

GO







-- ---------------------------------------------------------------------------
-- MOS 05-2008
-- ---------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spTempItemStock_getDataById]
(
		@comp_id		int,
		@tis_id			int
)
AS


BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------




	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Test
	-- -----------------------------------------------------------------------------
	/*
	declare @comp_id		int,
			@tis_id			int
	select	@comp_id		=1,
			@tis_id			=52028
	*/
	-- -----------------------------------------------------------------------------



	DECLARE @bitNoQTYUpdate AS BIT
	DECLARE @intComp_id		AS INT
	DECLARE @intBra_id		AS INT
	declare @intSoh_id		AS INT
	DECLARE @intSod_id		AS INT
	DECLARE @intRowQty		AS INT
	DECLARE @bitHasPurchaseOrderRelated AS BIT = 'False'







	SELECT  @intComp_id		= ttis.comp_id,
			@intBra_id		= ttis.bra_id,
			@intSoh_id		= ttis.soh_id,
			@intSod_id		= ttis.sod_id
		FROM tbTempItemStock ttis				WITH (NOLOCK)
		WHERE ttis.tis_id = @tis_id



	SELECT @intRowQty = COUNT(*)
		FROM tbTempItemStock ttis				WITH (NOLOCK)
		WHERE	@intComp_id		= ttis.comp_id AND
				@intBra_id		= ttis.bra_id  AND
				@intSoh_id		= ttis.soh_id  AND
				@intSod_id		= ttis.sod_id

	SELECT TOP 1 @bitHasPurchaseOrderRelated = 'True'
		FROM tbSaleOrderHeader_PurchaseOrderRelation AS  tsoh	WITH (NOLOCK)
		WHERE	(
					 tsoh.comp_id	= @intComp_id	AND
					 tsoh.so_bra_id	= @intBra_id	AND
					 tsoh.so_soh_id	= @intSoh_id	AND
					 tsoh.so_sod_id	= @intSod_id	AND
					 tsoh.posor_POReceived = 'False'
				 )
				 OR
				 (
					tsoh.comp_id	= @comp_id	AND
					tsoh.tis_id		= @tis_id	AND
					tsoh.posor_POReceived = 'False'
				 )


	SET @bitNoQTYUpdate = 'False'
	IF @intRowQty > 1 SET @bitNoQTYUpdate = 'True'


	SELECT	TOP 1
			' ' [ ],
			' ' [ ],
			tis.tis_priority,
			isnull(tis.item_id,-1)			[item_id],
			tis.tis_itemDesc,
			tis.tis_detail,
			tis.curr_id,
			c.curr_desc,
			tis.tis_initQty,
			tis.tis_qty,
			isnull(tis.prli_id,-1)			[prli_id],
			isnull(pl.prli_desc,'')			[prli_desc],
			tis.tis_price,
			ISNULL(tis.tis_cost,0)			[tis_cost],
			isnull(tis.tis_costTax,-1)		[tis_costTax],
			isnull(tis.stor_id,-1)			[stor_id],
			isnull(s.stor_desc,'')			[stor_desc],
			tis.doc_id,
			tis.tis_CD,
			b.bra_desc,
			tis.soh_id,
			tis.tis_insertDate,
			tis.user_id,
			i.item_code,
			tis.it_transaction,
			tis.tis_id,
			isnull(cli.coslis_price,0)		[coslis_price],
			isnull(cli.coslis_price_aw,0)	[coslis_price_aw],
			IsNull(cli.curr_id,tis.curr_id)	[coslis_Curr_Id],
			isnull(tis.tis_itemDiscount,0)	[tis_itemDiscount],
			isnull(tis.tis_note1,'')		[tis_note1],
			isnull(tis.tis_note2,'')		[tis_note2],
			tis.tis_isParentAssociate,
			tis.tis_order,
			tis.is_id,
			ISNULL(tis.tis_isMade,'False')	[tis_isMade],
			@bitNoQTYUpdate						[tis_UpdateQTYDisabled],
			tis.sdlmt_id,
			ISNULL(tis.tis_loanNumberOfPays,0)	[tis_loanNumberOfPays],
			ISNULL(tis.sreas_id,0)				[sreas_id],
			tis.tis_loanDateOfFirstPay,
			isnull(tis.tis_loanDayOfMonthOfNextPays,0)	[tis_loanDayOfMonthOfNextPays],
			IsNull(tis.sod_itemDeliveryDate,GETDATE())	[sod_itemDeliveryDate],
			ISNULL(tis.tis_idOfThisEW,-1)				[tis_idOfThisEW],
			ISNULL(tisR.item_id,-1)						[itemID4ExtWarranty],
			CASE
				WHEN	tis.sod_isFromPCConfigCTRLId IS NULL THEN 'False'
				ELSE										      'True'
			END													[sod_isFromPCConfig],
			CASE
				WHEN tipd.comp_id IS NOT NULL THEN	ISNULL(tipd.CreditQuotaQtyMaximum,1)
				WHEN IsNull(i.CreditQuotaQtyMaximum,1) > 0 THEN IsNull(i.CreditQuotaQtyMaximum,1)
				ELSE											ISNULL(br.CreditQuotaQtyMaximum,1)
			END											[CreditQuotaQtyMaximum]	,
			tis.tis_priceInBranchCurrency,
			IsNull(tis.sod_EWAddress,'')				[sod_EWAddress],
			ISNULL(tis.tis_divideOrder,'False')			[tis_divideOrder],
			ISNULL(tis.tis_id_origin,-1)				[tis_id_origin],
			ISNULL(tis.mlo_id,-1)						[mlo_id],
			ISNULL(tdf.df_pcConfigMode_AllowItemUpdate,'False')	[df_pcConfigMode_AllowItemUpdate],
			tis.sod_montlyPaymentFrom,
			tis.sod_montlyPaymentTo,
			ISNULL(tis.tis_exclude4AvailableStock,'False')				[tis_exclude4AvailableStock],
			ISNULL(tis.tis_pending4pod_IdRelation,'False')				[tis_pending4pod_IdRelation],
			@bitHasPurchaseOrderRelated									[hasPurchaseOrderRelated],
			ISNULL(i.item_RMA_enableSaleOrderPriceEdition,'False')		[item_RMA_enableSaleOrderPriceEdition],
			CASE
				WHEN tis.rmah_id IS NOT NULL THEN	'True'
				ELSE								'False'
			END															[isRMA],
			ISNULL(tis.tis_itemDiscount2,0)								[tis_itemDiscount2]
		From	dbo.tbTempItemStock				tis			WITH (NOLOCK)

				INNER JOIN tbDocumentsFile		tdf			WITH (NOLOCK)
					ON	tdf.comp_id = tis.comp_id AND
						tdf.df_id	= tis.df_id

				left join dbo.tbStorage			s			WITH (NOLOCK)
					on	s.comp_id	= tis.comp_id
					and s.stor_id	= tis.stor_id

				left join tbSysCurrency			c			WITH (NOLOCK)
					on	c.curr_id	= tis.curr_id

				left join dbo.tbPriceList		pl			WITH (NOLOCK)
					on	pl.comp_id	= tis.comp_id
					and pl.prli_id	= tis.prli_id

				LEFT JOIN vwPriceListItems vpli				WITH (NOLOCK)
					ON	vpli.comp_id = tis.comp_id AND
						vpli.prli_id = tis.prli_id AND
						vpli.item_id = tis.item_id

				LEFT JOIN tbItemPublicationDetail tipd		WITH (NOLOCK)
					ON	tipd.comp_id = vpli.comp_id AND
						tipd.pubh_id = vpli.pubh_id AND
						tipd.pubd_id = vpli.pubd_id

				left join dbo.tbBranch			b			WITH (NOLOCK)
					on	b.comp_id	= tis.comp_id
					and b.bra_id	= tis.bra_id

				left join dbo.tbItem			i			WITH (NOLOCK)
					on i.comp_id    = tis.comp_id
					and i.item_id   = tis.item_id

				left join dbo.tbBrand			br			WITH (NOLOCK)
					on	br.comp_id		= i.comp_id	AND
						br.brand_id		= i.brand_id


				LEFT JOIN tbItemSizeColorRelation	tire	WITH (NOLOCK)
					ON tire.comp_id			= tis.comp_id AND
					   tire.item_id_child	= tis.item_id

				left join dbo.vwItemCostList	cli			WITH (NOLOCK)
					on	cli.comp_id		= tis.comp_id
					and cli.coslis_id	= ISNULL(s.coslis_id,b.coslis_id)
					and	(
							cli.item_id	=	i.item_id OR
							tire.comp_id IS NOT NULL

						 -- MOS 12/2015
						 --EXISTS(
						 --			SELECT 1
						 --				FROM tbItemSizeColorRelation tiscr	WITH (NOLOCK)
						 --				WHERE	tiscr.comp_id		= tis.comp_id AND
						 --						tiscr.item_id_child = tis.item_id
						 --		)
						 --cli.item_id IN (SELECT tiscr.item_id
							--				FROM tbItemSizeColorRelation tiscr		WITH (NOLOCK)
							--				WHERE tiscr.comp_id = tis.comp_id AND tiscr.item_id_child = tis.item_id  )
						)

				LEFT JOIN tbTempItemStock tisR				WITH (NOLOCK) -- ID relacionado a la garantia extendida
					ON tisr.tis_idOfThisEW  = tis.tis_id


		Where	tis.comp_id     =	@comp_id AND
				tis.tis_id		=	@tis_id

		--Order by tis.tis_id



END
GO




CREATE PROCEDURE [dbo].[spTempItemStock_getDataById4FactoryProcessing]
(
		@comp_id		int,
		@tis_id			int
)
AS

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON


	/*
	declare @comp_id		int,
			@tis_id			int
	select	@comp_id		=1,
			@tis_id			=537
	*/



	DECLARE @bitNoQTYUpdate AS BIT
	DECLARE @intComp_id		AS INT
	DECLARE @intBra_id		AS INT
	declare @intSoh_id		AS INT
	DECLARE @intSod_id		AS INT
	DECLARE @intRowQty		AS INT




	SELECT  @intComp_id		= ttis.comp_id,
			@intBra_id		= ttis.bra_id,
			@intSoh_id		= ttis.soh_id,
			@intSod_id		= ttis.sod_id
		FROM tbTempItemStock ttis
		WHERE ttis.tis_id = @tis_id


	SELECT @intRowQty = COUNT(*)
		FROM tbTempItemStock ttis
		WHERE	@intComp_id		= ttis.comp_id AND
				@intBra_id		= ttis.bra_id  AND
				@intSoh_id		= ttis.soh_id  AND
				@intSod_id		= ttis.sod_id


	SET @bitNoQTYUpdate = 'False'
	IF @intRowQty > 1 SET @bitNoQTYUpdate = 'True'


	Select	' ' [ ],
			' ' [ ],
			tis.tis_priority,
			isnull(tis.item_id,-1)			[item_id],
			tis.tis_itemDesc,
			tis.tis_detail,
			tis.curr_id,
			c.curr_desc,
			tis.tis_initQty,
			tis.tis_qty,
			isnull(tis.prli_id,-1)			[prli_id],
			isnull(pl.prli_desc,'')			[prli_desc],
			tis.tis_price,
			tis.tis_cost,
			isnull(tis.tis_costTax,-1)		[tis_costTax],
			isnull(tis.stor_id,-1)			[stor_id],
			isnull(s.stor_desc,'')			[stor_desc],
			tis.doc_id,
			tis.tis_CD,
			b.bra_desc,
			tis.soh_id,
			tis.tis_insertDate,
			tis.user_id,
			i.item_code,
			tis.it_transaction,
			tis.tis_id,
			isnull(cli.coslis_price,0)		[coslis_price],
			isnull(cli.coslis_price_aw,0)	[coslis_price_aw],
			IsNull(cli.curr_id,tis.curr_id)	[coslis_Curr_Id],
			isnull(tis.tis_itemDiscount,0)	[tis_itemDiscount],
			isnull(tis.tis_note1,'')		[tis_note1],
			isnull(tis.tis_note2,'')		[tis_note2],
			tis.tis_isParentAssociate,
			tis.tis_order,
			tis.is_id,
			tis.tis_isMade,
			@bitNoQTYUpdate					[tis_UpdateQTYDisabled],
			tis.sod_id,
			tit.ct_transaction

		From	dbo.tbTempItemStock				tis

				left join dbo.tbStorage			s
					on	s.comp_id	= tis.comp_id
					and s.stor_id	= tis.stor_id

				left join tbSysCurrency			c
					on	c.curr_id	= tis.curr_id

				left join dbo.tbPriceList		pl
					on	pl.comp_id	= tis.comp_id
					and pl.prli_id	= tis.prli_id


				left join dbo.tbBranch			b
					on	b.comp_id	= tis.comp_id
					and b.bra_id	= tis.bra_id

				left join dbo.tbItem			i
					on i.comp_id    = tis.comp_id
					and i.item_id   = tis.item_id

				left join dbo.tbItemCostList	cli
					on	cli.comp_id		=	tis.comp_id
					and cli.coslis_id	= ISNULL(s.coslis_id,b.coslis_id)
					and	(cli.item_id	=	i.item_id OR
						 cli.item_id IN (SELECT tiscr.item_id
											FROM tbItemSizeColorRelation tiscr
											WHERE tiscr.comp_id = tis.comp_id AND tiscr.item_id_child = tis.item_id  ))

				LEFT JOIN tbItemTransactions				tit
				ON	tit.comp_id			= tis.comp_id		AND
					tit.it_transaction	= tis.it_transaction


		Where	tis.tis_id		=	@tis_id
			and tis.comp_id     =	@comp_id

		Order by tis.tis_id



END
GO







