CREATE PROCEDURE [dbo].[spTempItemStock_getDataForWebSite]
(
	@comp_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@ws_id						INT,
	@cust_id					INT,
	@returnresultsets			INT
)
AS

SET NOCOUNT ON
/*
* @returnresultsets: valores posibles	-1: todos los resultsets
*										 1: detalle de artículos
*										 2: totales artículos
*										 3: totales compra
*/




/*
declare @comp_id	INT,
		@guid		UNIQUEIDENTIFIER,
		@ws_id		INT,
		@cust_id	INT,
		@returnresultsets			INT
select	@comp_id	=1,
		@guid		='DFB6FBB5-C93E-400D-8A06-A127DC49FC91',
		@ws_id		=11,
		@cust_id	=24288,
		@returnresultsets=-1
*/




IF @returnresultsets IN (-1,1)
BEGIN

	select	--' ' [ ],
			tis.item_id,
			i.item_picture,
			i.item_desc,

			twsn.ws_decimals4Stock,
			tis.tis_qty,

			twsn.ws_decimals4Price,
			LTRIM(RTRIM(c.curr_symbol))			[curr_symbol],
			tpli.prli_price,

			tis.tis_qty * tpli.prli_price		[item_total],

			tis.tis_id


	from	dbo.tbTempItemStock					tis

			left join dbo.tbPriceListItems		tpli
			ON	tpli.comp_id	= tis.comp_id
			AND tpli.item_id	= tis.item_id
			AND tpli.prli_id	= tis.prli_id

			left join tbSysCurrency				c
			on	c.curr_id		= tpli.curr_id

			left join dbo.tbItem				i
			on	i.comp_id		= tis.comp_id
			and i.item_id		= tis.item_id

			LEFT JOIN tbWebSite_Names			twsn
			ON  twsn.comp_id	= tis.comp_id
			AND twsn.ws_id		= @ws_id


	where	tis.comp_id		= @comp_id
	and		tis.tis_guid	= @guid


	order by tis.tis_id

END



IF @returnresultsets IN (-1,2)
BEGIN

	select	ltrim(rtrim(c.curr_symbol))			[curr_symbol],
			twsn.ws_decimals4Price,
			sum(tis.tis_qty * dbo.fnGetExchange2(@comp_id,
													tis.tis_price,
													tis.curr_id,
													tb.curr_id,
													tb.curr_id,
													tb.curr_id,
													0,
													'false'))		[item_total]


	from	dbo.tbTempItemStock					tis

			left join dbo.tbPriceListItems		tpli
			ON	tpli.comp_id	= tis.comp_id
			AND tpli.item_id	= tis.item_id
			AND tpli.prli_id	= tis.prli_id

			left join dbo.tbItem				i
			on	i.comp_id		= tis.comp_id
			and i.item_id		= tis.item_id

			LEFT JOIN tbWebSite_Names			twsn
			ON  twsn.comp_id	= tis.comp_id
			AND twsn.ws_id		= @ws_id

			LEFT JOIN tbBranch					tb
			ON tb.comp_id = tis.comp_id
			AND tb.bra_id = twsn.bra_id

			left join tbSysCurrency				c
			on	c.curr_id		= tb.curr_id


	where	tis.comp_id		= @comp_id
	and		tis.tis_guid	= @guid

	GROUP BY c.curr_symbol, twsn.ws_decimals4Price

END




IF @returnresultsets IN (-1,3)
BEGIN

	DECLARE	@bra_id				INT,
			@curr_id			INT,
			@disc_id			INT,
			@country_id			INT,
			@state_id			INT,
			@st_id				INT,
			@cust_curr_id		INT,
			@exchange			DECIMAL(19,6),
			@df_id				INT,
			@prof_id			INT,
			@dl_id				INT,
			@sd_id				INT,
			@ccp_id				INT



	-- recuperar datos de website
	SELECT	@bra_id			= twsn.bra_id,
			@curr_id		= tb.curr_id,
			@country_id		= tb.country_id,
			@state_id		= tb.state_id,
			@prof_id		= twsn.prof_id,
			@sd_id			= twsn.sd_id

	FROM	tbWebSite_Names				twsn
			INNER JOIN tbBranch			tb
			ON	tb.comp_id	= twsn.comp_id
			AND tb.bra_id	= twsn.bra_id

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id





	--obtenemos el df_id para generar el pedido
	SELECT	TOP 1 @df_id	= df_id

	FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)

	WHERE	sd_id			= @sd_id

	ORDER BY df_order


	--SELECT @sd_id, @df_id


	-- recuperar datos del cliente
	SELECT	@disc_id		= tc.disc_id,
			@st_id			= tc.st_id,
			@cust_curr_id	= tc.curr_id,
			@dl_id			= tc.dl_id,
			@ccp_id			= -1

	FROM	tbCustomer					tc

	WHERE	tc.comp_id		= @comp_id
	AND		tc.cust_id		= @cust_id



	-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
	SELECT @exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id, @cust_curr_id, 0, 0, 'false')



	-- recuperar el df_id correspondiente
--	SELECT 	top 1 @df_id = df.df_id
--
--	FROM 	dbo.tbDocumentsFile						DF
--
--			Inner Join vwsysDocuments_forSaleOrder	VDF
--			ON 	VDF.sd_id		= DF.sd_id
--
--			INNER JOIN tbDocumentsFileByProfile		tdfbp
--			ON	tdfbp.comp_id	= df.comp_id
--			AND tdfbp.bra_id	= df.bra_id
--			AND tdfbp.prof_id	= 1--@prof_id
--			AND tdfbp.df_id		= df.df_id
--
--	WHERE 	DF.comp_id			= @comp_id
--	AND		DF.bra_id			= @bra_id
--	AND		DF.df_Disabled		= 'False'
--	AND		(dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id)) LIKE '%' + DF.df_kindOf  + '%'
--			OR DF.df_kindof = 'R'
--			OR DF.df_kindof = 'X')
--			--@sd_id              --@sd_id
--	AND		DF.sd_id			= 1




	-- recuperar los totales generales
	EXEC	sptmpTax_calculate
			@comp_id,
			@bra_id,
			@cust_id,
			@guid,
			@curr_id,
			@disc_id,
			@country_id,
			@state_id,
			@st_id,
			@curr_id,
			@cust_curr_id,
			@exchange,
			'false',
			@df_id,
			'true',
			@dl_id,
			0,
			'false',
			'false',
			-1,
			@ccp_id		-- esta en -1 ya que no esta informado

END











GO







CREATE PROCEDURE [dbo].[spTempItemStock_getDataForWebSiteMycart]
(
	@comp_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@ws_id						INT,
	@cust_id					INT,
	@returnresultsets			INT,
	@st_id						INT,
	@dl_id						INT
)
AS

SET NOCOUNT ON
/*
* @returnresultsets: valores posibles	-1: todos los resultsets
*										 1: detalle de artículos
*										 2: totales artículos
*										 3: totales compra
*/




/*
declare @comp_id	INT,
		@guid		UNIQUEIDENTIFIER,
		@ws_id		INT,
		@cust_id	INT,
		@returnresultsets			INT,
	@st_id						INT,
	@dl_id						INT

select	@comp_id			=1,
		@guid				='d1e178d9-58bc-47f7-bf78-4b1ed20414be',
		@ws_id				=23,
		@cust_id			=24288,
		@returnresultsets	=-1,
		@st_id				=3,
		@dl_id				=13
*/




IF @returnresultsets IN (-1,3)
BEGIN

	DECLARE	@bra_id				INT,
			@curr_id			INT,
			@disc_id			INT,
			@country_id			INT,
			@state_id			INT,
			--@st_id				INT,
			@cust_curr_id		INT,
			@exchange			DECIMAL(19,6),
			@df_id				INT,
			@prof_id			INT,
			--@dl_id				INT,
			@sd_id				INT



	-- recuperar datos de website
	SELECT	@bra_id			= twsn.bra_id,
			@curr_id		= tb.curr_id,
			@country_id		= tb.country_id,
			@state_id		= tb.state_id,
			@prof_id		= twsn.prof_id,
			@sd_id			= twsn.sd_id

	FROM	tbWebSite_Names				twsn
			INNER JOIN tbBranch			tb
			ON	tb.comp_id	= twsn.comp_id
			AND tb.bra_id	= twsn.bra_id

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id





	--obtenemos el df_id para generar el pedido
	SELECT	TOP 1 @df_id	= df_id

	FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)

	WHERE	sd_id			= @sd_id

	ORDER BY df_order


	--SELECT @sd_id, @df_id


	-- recuperar datos del cliente
	SELECT	@disc_id		= tc.disc_id,
			--@st_id			= tc.st_id,
			@cust_curr_id	= tc.curr_id--,
			--@dl_id			= tc.dl_id

	FROM	tbCustomer					tc

	WHERE	tc.comp_id		= @comp_id
	AND		tc.cust_id		= @cust_id



	-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
	SELECT @exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id, @cust_curr_id, 0, 0, 'false')






	IF EXISTS(SELECT 1 FROM tbTempItemStock ttis
	          WHERE ttis.comp_id = @comp_id
				AND ttis.tis_guid = @guid)
	BEGIN

		-- recuperar los totales generales
		EXEC	sptmpTax_calculate
				@comp_id,
				@bra_id,
				@cust_id,
				@guid,
				@curr_id,
				@disc_id,
				@country_id,
				@state_id,
				@st_id,
				@curr_id,
				@cust_curr_id,
				@exchange,
				'false',
				@df_id,
				'true',
				@dl_id,
				0,
				'false',
				'false',
				-1,
				-1	-- ccp_id no informado

	END

	ELSE

	BEGIN
		--si no hay datos en la tempitemstock para el guid correspondiente
		-- se retorna un select cualquiera porque dentro del código se están
		--esperando 3 tablas
		SELECT 1

	END

END




IF @returnresultsets IN (-1,1)
BEGIN

	select	--' ' [ ],
			tis.item_id,
			i.item_picture,
			i.item_desc,

			twsn.ws_decimals4Stock,
			tis.tis_qty,

			twsn.ws_decimals4Price,
			LTRIM(RTRIM(c.curr_symbol))						[curr_symbol],
			tis.tis_priceInBranchCurrency					[prli_price] ,--tpli.prli_price,

			tis.tis_qty * tis.tis_priceInBranchCurrency		[item_total],

			tis.tis_id


	from	dbo.tbTempItemStock					tis

			INNER JOIN tbBranch tb
				ON	tb.comp_id	= tis.comp_id AND
					tb.bra_id	= tis.bra_id

			left join dbo.tbPriceListItems		tpli
			ON	tpli.comp_id	= tis.comp_id
			AND tpli.item_id	= tis.item_id
			AND tpli.prli_id	= tis.prli_id

--			left join tbSysCurrency				c
--			on	c.curr_id		= tpli.curr_id

			left join tbSysCurrency				c
				on	c.curr_id		= tb.curr_id

			left join dbo.tbItem				i
			on	i.comp_id		= tis.comp_id
			and i.item_id		= tis.item_id

			LEFT JOIN tbWebSite_Names			twsn
			ON  twsn.comp_id	= tis.comp_id
			AND twsn.ws_id		= @ws_id


	where	tis.comp_id		= @comp_id
	and		tis.tis_guid	= @guid
	AND		tis.item_id IS NOT NULL


	order by tis.tis_id

END



IF @returnresultsets IN (-1,2)
BEGIN

	select	ltrim(rtrim(c.curr_symbol))			[curr_symbol],
			twsn.ws_decimals4Price,
			sum(tis.tis_qty * dbo.fnGetExchange2(@comp_id,
													tis.tis_priceInBranchCurrency,
													tis.curr_id,
													tb.curr_id,
													tb.curr_id,
													tb.curr_id,
													0,
													'false'))		[item_total]


	from	dbo.tbTempItemStock					tis

			left join dbo.tbPriceListItems		tpli
			ON	tpli.comp_id	= tis.comp_id
			AND tpli.item_id	= tis.item_id
			AND tpli.prli_id	= tis.prli_id

			left join dbo.tbItem				i
			on	i.comp_id		= tis.comp_id
			and i.item_id		= tis.item_id

			LEFT JOIN tbWebSite_Names			twsn
			ON  twsn.comp_id	= tis.comp_id
			AND twsn.ws_id		= @ws_id

			LEFT JOIN tbBranch					tb
			ON tb.comp_id = tis.comp_id
			AND tb.bra_id = twsn.bra_id

			left join tbSysCurrency				c
			on	c.curr_id		= tb.curr_id


	where	tis.comp_id		= @comp_id
	and		tis.tis_guid	= @guid

	GROUP BY c.curr_symbol, twsn.ws_decimals4Price

END






	-- recuperar el df_id correspondiente
--	SELECT 	top 1 @df_id = df.df_id
