-- Retorna el volumen total de los articulos de un determinado guid en una tbTempItemStock
CREATE PROCEDURE [dbo].spTempItemStock_getFirstItemDescription
(
	@comp_id					INT,
	@guid						UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON

	SELECT TOP 1 ttis.tis_itemDesc
		FROM tbTempItemStock	ttis	WITH (NOLOCK)
		--INNER JOIN tbItem		ti		WITH (NOLOCK)
		--	ON	ti.comp_id = ttis.comp_id			AND
		--		ti.item_id = ttis.item_id
		WHERE	ttis.comp_id			= @comp_id	AND
				ttis.tis_guid			= @guid		AND
				ttis.tis_DeliveryCharge = 'False'	AND
				ttis.tis_isEnvioPackItem= 'False'
		ORDER BY ttis.tis_order

END
GO





-- ATENCION.!!!    Si por algun motivo se debe fijar un costo que reemplace al resto se debe poner en el campo: tis_costForced2All

CREATE PROCEDURE [dbo].[spTempItemStock_getPercentProfit]
(
	@comp_id					INT,
	@bra_id						INT,
	@guid						UNIQUEIDENTIFIER,
	@forcedExchangeCurrency		INT,
    @forcedExchange				DECIMAL(19,5),
    @prof_id					INT
)
AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------



-- ------------------------------------------------------------------------
-- Testing
-- ------------------------------------------------------------------------
/*
	DECLARE @comp_id					INT,
			@bra_id						INT,
			@guid						UNIQUEIDENTIFIER,
			@forcedExchangeCurrency		INT,
			@forcedExchange				DECIMAL(19,5),
			@prof_id					INT

	SELECT	@guid			= '32784529-B004-4542-A921-794F0A0A9648',
			@bra_id			= 1,
			@comp_id		= 1,
			@forcedExchangeCurrency = 2,
			@forcedExchange	= 5.38,
			@prof_id		= 1
	DROP TABLE #tmpTIS
*/
-- ------------------------------------------------------------------------


	DECLARE @bitShowPrice AS BIT
	SET @bitShowPrice = 'True'
	if EXISTS	(
									SELECT TOP 1 1
										FROM tbControlProfiles tcp1		WITH (NOLOCK)
										WHERE	tcp1.comp_id = @comp_id
											AND tcp1.bra_id  = @bra_id
											AND tcp1.prof_id = @prof_id
											AND tcp1.page_id = 787878
											AND tcp1.ctrl_id = 1695


				)
		BEGIN
			SET @bitShowPrice = 'False'
		END



	DECLARE @lcoslis_id INT,
			@lcoslist_type BIT,
			@lbra_curr_id INT

	SELECT	@lcoslis_id			= tb.coslis_id,
			@lcoslist_type		= tb.bra_costlist_type,
			@lbra_curr_id		= tb.curr_id
		FROM	tbBranch		tb	WITH (NOLOCK)
		WHERE	tb.comp_id		= @comp_id	AND
				tb.bra_id		= @bra_id


	SELECT	isnull(ti.item_code,'')																									[item_code],
			isnull(ti.item_desc, ttis.tis_itemDesc)																					[item_desc],


			(SELECT ltrim(rtrim(curr_symbol)) FROM tbsysCurrency tc WHERE tc.curr_id = ttis.curr_id)								[curr_price],
			CONVERT(DECIMAL(19,4),ttis.tis_price)																					[price],


			(SELECT ltrim(rtrim(curr_symbol)) FROM tbsysCurrency tc WHERE tc.curr_id = @lbra_curr_id)								[curr_priceBranchCurr],
			CONVERT(DECIMAL(19,4),ttis.tis_priceInBranchCurrencyWithDiscount * ttis.tis_qty)										[priceBranchCurr],


			ISNULL(ticln.coslis_desc,'')																							[coslis_desc],


			(SELECT ltrim(rtrim(curr_symbol))
				FROM tbsysCurrency tc  WITH (NOLOCK)
				WHERE tc.curr_id =	CASE
										WHEN ttis.tis_costForced2All <> 0	THEN @lbra_curr_id
										WHEN ttis.item_id IS NULL THEN ttis.curr_id
										WHEN ttis.tis_DeliveryCharge = 1	THEN ttis.curr_id
										ELSE ticl.curr_id
									END)
																																	[curr_cost],
			CONVERT(DECIMAL(19,4),	CASE
										WHEN ttis.tis_costForced2All <> 0	THEN ttis.tis_costForced2All
										WHEN ttis.tis_DeliveryCharge = 1	THEN ttis.tis_cost
										WHEN ttis.item_id IS NULL			THEN ttis.tis_cost
										ELSE
											CASE
												WHEN @lcoslist_type = 'false' THEN ticl.coslis_price
												ELSE ticl.coslis_price_aw
											END
									END)													[cost],


			(SELECT ltrim(rtrim(curr_symbol)) FROM tbsysCurrency tc WHERE tc.curr_id = @lbra_curr_id)								[curr_costBranchCurr],
			CASE
				WHEN ttis.tis_costForced2All <> 0												THEN CONVERT(DECIMAL(19,4), ttis.tis_qty * ttis.tis_costForced2All )
				WHEN ttis.item_id IS NULL THEN
												CONVERT(DECIMAL(19,4),
													ttis.tis_qty *
													dbo.fnGetExchange2 (ttis.comp_id,
    																   ttis.tis_cost,
																	   ttis.curr_id,
																	   @lbra_curr_id,
																	   @forcedExchangeCurrency,
																	   @lbra_curr_id,
																	   @forcedExchange,
																	   'false'))
				ELSE
												CONVERT(DECIMAL(19,4),
													ttis.tis_qty *
													dbo.fnGetExchange2(ttis.comp_id,
														CASE
															WHEN @lcoslist_type = 'false'		THEN	ticl.coslis_price
															ELSE										ticl.coslis_price_aw
														END,
														ticl.curr_id, @lbra_curr_id, @forcedExchangeCurrency, @lbra_curr_id, @forcedExchange, 'false'))
			END  																						[costBranchCurr],

			(ISNULL(ttis.sod_MECost,0) + ISNULL(ttis.sod_MPCost,0) + (ISNULL(ttis.sod_MLCost,0) * ttis.tis_qty)) 			[MLTotalCost],


			CASE
				WHEN ttis.tis_costForced2All <> 0						THEN	convert(varchar,((ttis.tis_priceInBranchCurrencyWithDiscount /
																				dbo.fnNoZDiv( ttis.tis_costForced2All ) ) - 1) * 100)
				WHEN ttis.item_id IS NULL								THEN
																				convert(varchar,CONVERT(DECIMAL(19,2),
																					CASE
																						WHEN	ttis.tis_cost = 0 THEN 0
																						ELSE
																								((ttis.tis_priceInBranchCurrencyWithDiscount /
																									dbo.fnNoZDiv(dbo.fnGetExchange2(ttis.comp_id,ttis.tis_cost,@lbra_curr_id, ttis.curr_id, @forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false') )
																								) - 1) * 100
																					END))
																					+ ' %'
				ELSE
					convert(varchar,CONVERT(DECIMAL(19,2),
						CASE
							WHEN @lcoslist_type = 'false'	THEN
								case
									when isnull(ticl.coslis_price,0) = 0	THEN 0
																			ELSE
	 									 ((ttis.tis_priceInBranchCurrencyWithDiscount /
											dbo.fnNoZDiv(	dbo.fnGetExchange2(ttis.comp_id,ticl.coslis_price,ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')	)
										 ) - 1) * 100
								END
						ELSE
							CASE
								WHEN isnull(ticl.coslis_price_aw,0) = 0 THEN 0
								ELSE
	 																		 ((ttis.tis_priceInBranchCurrencyWithDiscount /
																				dbo.fnNoZDiv(	dbo.fnGetExchange2(ttis.comp_id,ticl.coslis_price_aw,ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false') )
																			 ) - 1) * 100
							 END
						END))
						+ ' %'
			END																			[Markup],


			CASE
				WHEN ttis.tis_costForced2All <> 0		THEN  convert(varchar,(ttis.tis_costForced2All / dbo.fnNoZDiv( ttis.tis_priceInBranchCurrencyWithDiscount) -1) * -100)
				WHEN ttis.item_id IS NULL				THEN
														convert(varchar,CONVERT(DECIMAL(19,2),
															CASE
																WHEN ttis.tis_cost = 0 THEN 0
																ELSE
																	((dbo.fnGetExchange2(ttis.comp_id,ttis.tis_cost,@lbra_curr_id, ttis.curr_id, @forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
																	/ dbo.fnNoZDiv( ttis.tis_priceInBranchCurrencyWithDiscount)) -1) * -100
															END))
															+ ' %'
				ELSE
					convert(varchar,CONVERT(DECIMAL(19,2),
						CASE
							WHEN @lcoslist_type = 'false'	THEN
																CASE
																	when ttis.tis_priceInBranchCurrencyWithDiscount = 0 THEN 0
																	ELSE
																		 ((dbo.fnGetExchange2(ttis.comp_id,isnull(ticl.coslis_price,0),ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
																		 / dbo.fnNoZDiv( ttis.tis_priceInBranchCurrencyWithDiscount)) -1) * -100
																END
						ELSE
							CASE
								when ttis.tis_priceInBranchCurrencyWithDiscount = 0 THEN 0
								ELSE
							 ((dbo.fnGetExchange2(ttis.comp_id,isnull(ticl.coslis_price_aw,0),ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
							 / dbo.fnNoZDiv( ttis.tis_priceInBranchCurrencyWithDiscount)) -1) * -100

							END
						END))
						+ ' %'
			END																										[Profit],
			ttis.tis_qty,
			ttis.tis_DeliveryCharge ,


			convert(decimal(19,4),0) [MarkUpML],
			convert(decimal(19,4),0) [ProfitML]	,
			(ISNULL(ttis.sod_MECost,0) + ISNULL(ttis.sod_MPCost,0) + ISNULL(ttis.sod_MLCost,0)) * ttis.tis_qty		[MECost],
			ISNULL(ttis.sod_MECost,0) * ttis.tis_qty																[sod_MECost],
			ISNULL(ttis.sod_MPCost,0) * ttis.tis_qty																[sod_MPCost],
			ISNULL(ttis.sod_MLCost,0) * ttis.tis_qty																[sod_MLCost],
			CASE
				WHEN tidfrmc.comp_id IS NULL THEN 0
				ELSE tidfrmc.mkp_greenFrom
			END																										[mkp_greenFrom],
			CASE
				WHEN tidfrmc.comp_id IS NULL THEN 0
				ELSE tidfrmc.mkp_yellowFrom
			END																										[mkp_yellowFrom],
			CASE
				WHEN tidfrmc.comp_id IS NULL THEN 0
				ELSE tidfrmc.mkp_redFrom
			END																										[mkp_redFrom],
			0																										[mkp_colourID]






	INTO	#tmpTIS

	FROM	tbTempItemStock						ttis	WITH (NOLOCK)
	LEFT JOIN tbItem					ti		WITH (NOLOCK)
		ON	ti.comp_id		= ttis.comp_id	AND
			ti.item_id		= ttis.item_id

	LEFT JOIN tbStorage					ts	WITH (NOLOCK)
		ON		ts.comp_id = ttis.comp_id
			AND ts.stor_id = ttis.stor_id

	LEFT JOIN tbCustomer				tc	WITH (NOLOCK)
		ON		tc.comp_id = @comp_id
			AND tc.cust_id = ttis.cust_id

	LEFT JOIN vwItemCostList			ticl	WITH (NOLOCK)
		ON	ticl.comp_id	= ti.comp_id
		AND ticl.item_id	= ti.item_id
		AND ticl.coslis_id	= ISNULL(tc.coslis_id,isnull(ts.coslis_id, @lcoslis_id))

	LEFT JOIN tbItemCostListName		ticln	WITH (NOLOCK)
		ON	ticln.comp_id	= ticl.comp_id
		AND ticln.coslis_id = ticl.coslis_id

	LEFT JOIN tbItemDocumentsFileRelations4MarkupColour AS tidfrmc	WITH (NOLOCK)
		ON	tidfrmc.comp_id = ttis.comp_id AND
			tidfrmc.item_id = ttis.item_id AND
			tidfrmc.df_id	= ttis.df_id

	WHERE	ttis.comp_id	= @comp_id	AND
			ttis.tis_guid	= @guid		AND
			ISNULL(ttis.tis_DeliveryCharge,0) = 0
	ORDER BY ttis.tis_order
	-- ----------------------------------------------------------------------------------






	-- ----------------------------------------------------------------------------------
	-- Mal calculados arriba : MOS  02-2011
	-- ----------------------------------------------------------------------------------
	UPDATE #tmpTIS
		SET Markup = Round((([priceBranchCurr]   / dbo.fnNoZDiv( [costBranchCurr]))  -1) * 100,2),
		    Profit  = Round((([costBranchCurr]	  / dbo.fnNoZDiv( [priceBranchCurr])) -1) * -100,2),
		    MarkUpML= Round((([priceBranchCurr]   / dbo.fnNoZDiv( [costBranchCurr]  + [MECost]))  -1) * 100,2),
		    ProfitML= Round(((([costBranchCurr] + [MECost])	  / dbo.fnNoZDiv( [priceBranchCurr] ))  -1) * -100,2)
	-- ----------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------------------
	-- Poner COLORES a la grilla
	-- ----------------------------------------------------------------------------------
	UPDATE #tmpTIS
		SET mkp_colourID =	CASE
								WHEN Markup >= mkp_greenFrom		THEN 3
								WHEN Markup >= mkp_yellowFrom		THEN 2
								WHEN Markup >= mkp_redFrom			THEN 1
								ELSE									 0
		                  	END
	-- ----------------------------------------------------------------------------------





	-- ----------------------------------------------------------------------------------
	/*datos para grilla*/
	-- ----------------------------------------------------------------------------------
	SELECT	[item_code],
			[item_desc],
			[curr_price]			+' '+CONVERT(VARCHAR,CASE WHEN @bitShowPrice ='True' THEN [price]			ELSE 0 END)	[price],
			[curr_priceBranchCurr]	+' '+CONVERT(VARCHAR,CASE WHEN @bitShowPrice ='True' THEN [priceBranchCurr] ELSE 0 END) [priceBranchCurr],
			[coslis_desc],
			[curr_cost]				+' '+CONVERT(VARCHAR,CASE WHEN @bitShowPrice ='True' THEN [cost]			ELSE 0 END)	[cost],
			[curr_costBranchCurr]	+' '+CONVERT(VARCHAR,CASE WHEN @bitShowPrice ='True' THEN [costBranchCurr]	ELSE 0 END)	[costBranchCurr],
			[Markup],
			[Profit],
			CONVERT(DECIMAL(19,2),tis_qty)		[tis_qty],
			MarkUpML,		-- ATENCION, **54f6wefwef6e, se usa para controlar el Markup MINIMO !!!! ( Column 10 )
			ProfitML,
			sod_MECost		[sod_MECost],
			sod_MPCost		[sod_MPCost],
			sod_MLCost		[sod_MLCost],
			mkp_colourID

		FROM	#tmpTIS
	-- ----------------------------------------------------------------------------------






	-- ----------------------------------------------------------------------------------
	/*datos para totales*/
	-- ----------------------------------------------------------------------------------
	SELECT	''		[item_code],		--0

			''		[item_desc],		--1

			''		[price],			--2

			[curr_priceBranchCurr]	+' '+CONVERT(VARCHAR,SUM(CASE WHEN @bitShowPrice ='True' THEN [priceBranchCurr]	ELSE 0 END))
					[priceBranchCurr],	--3

			''		[coslis_desc],		--4

			''		[cost],				--5

			ISNULL(
			[curr_costBranchCurr]	+' '+CONVERT(VARCHAR,SUM(CASE WHEN @bitShowPrice ='True' THEN [costBranchCurr]	ELSE 0 END)),'')
					[costBranchCurr],	--6

			ISNULL(
			CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),
			CASE WHEN SUM([costBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([priceBranchCurr]) / dbo.fnNoZDiv( SUM([costBranchCurr])))  -1) * 100) END ))+ ' %','')
					[Markup],			--7

			ISNULL(
			CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),
			CASE WHEN SUM([priceBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([costBranchCurr])	 / dbo.fnNoZDiv( SUM([priceBranchCurr]))) -1) * -100) END ))+ ' %','')
					[Profit],			--8
			SUM(tis_qty)		[tis_qty],	-- 9


			ISNULL(
			CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),
			CASE WHEN SUM([costBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([priceBranchCurr]) / dbo.fnNoZDiv( SUM([costBranchCurr] + [MECost])))  -1) * 100) END ))+ ' %','')
					[MarkupML],			--10

			ISNULL(
			CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),
			CASE WHEN SUM([priceBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([costBranchCurr] + [MECost]) 	 / dbo.fnNoZDiv( SUM([priceBranchCurr]))) -1) * -100) END ))+ ' %','')
					[ProfitML],			-- 11

			SUM(sod_MECost)		[sod_MECost],
			SUM(sod_MPCost)		[sod_MPCost],
			SUM(sod_MLCost)		[sod_MLCost]


		FROM	#tmpTIS
		GROUP BY [curr_priceBranchCurr],
				 [curr_costBranchCurr]
	-- ----------------------------------------------------------------------------------




	-- ----------------------------------------------------------------------------------
	-- Este se usa para las claves de markup ya que NO tiene strings en los totales y son numeros
	-- ----------------------------------------------------------------------------------
	SELECT	''																								[item_code],
			''																								[item_desc],
			''																								[price],
			[curr_priceBranchCurr]	+' '+CONVERT(VARCHAR,SUM([priceBranchCurr]))							[priceBranchCurr],
			''																								[coslis_desc],
			''																								[cost],
			[curr_costBranchCurr]	+' '+CONVERT(VARCHAR,SUM([costBranchCurr]))								[costBranchCurr],

			--CONVERT(VARCHAR,
			ISNULL(
			CONVERT(DECIMAL(19,6),
			CASE WHEN SUM([costBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([priceBranchCurr]) / dbo.fnNoZDiv( SUM([costBranchCurr])))  -1) * 100) END ),0)			[Markup],
			--)+ ' %'

			--CONVERT(VARCHAR,
			ISNULL(
			CONVERT(DECIMAL(19,6),
			CASE WHEN SUM([priceBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([costBranchCurr])	 / dbo.fnNoZDiv( SUM([priceBranchCurr]))) -1) * -100) END ),0)		[Profit],
			--)+ ' %'
			SUM(tis_qty)		[tis_qty],	-- 9


			ISNULL(
			CONVERT(DECIMAL(19,2),
			CASE WHEN SUM([costBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([priceBranchCurr]) / dbo.fnNoZDiv( SUM([costBranchCurr] + [MECost])))  -1) * 100) END ),0)
					[MarkupML],			--10

			ISNULL(
			CONVERT(DECIMAL(19,2),
			CASE WHEN SUM([priceBranchCurr]) = 0 THEN 0 ELSE
			(((SUM([costBranchCurr] + [MECost]) 	 / dbo.fnNoZDiv( SUM([priceBranchCurr]))) -1) * -100) END ),0)
					[ProfitML]			-- 11

		FROM	#tmpTIS
		GROUP BY [curr_priceBranchCurr],[curr_costBranchCurr]

	-- ----------------------------------------------------------------------------------

END
GO


-- Log
-- STL 09-2024: Para que no realice una validación de que tiene pendientes turnos de armado cuando en el campo SREAS_ID tiene que NO REQUIERE ARMADO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spTempItemStock_getStatus]
	@comp_id	AS INT,
	@user_id	AS INT,
	@prof_id	AS INT,
	@tis_guid	AS UNIQUEIDENTIFIER

AS
BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET NOCOUNT ON;

	DECLARE @bitIsTurnsOK AS BIT
	SET @bitIsTurnsOK = 'True'

	SELECT
		@bitIsTurnsOK			= 'False'
		FROM tbTempItemStock					ttis		WITH(NOLOCK)
		INNER JOIN tbItem						ti			WITH(NOLOCK)
			ON	ti.comp_id		= ttis.comp_id	AND
				ti.item_id		= ttis.item_id
		LEFT JOIN tbAssembly_Turns4Assembly		tata		WITH(NOLOCK)
			ON	tata.comp_id	= ttis.comp_id	AND
				tata.tis_id		= ttis.tis_id
		WHERE	tata.comp_id	IS NULL			AND -- No tenga turno aun creado
				ttis.tis_guid	= @tis_guid		AND
				ti.item_assemblyType IN (1,2)	AND	-- Armado en Taller o en Domicilio
				ttis.sdlmt_id	<> 1			AND	-- Que NO sea Retira YA
				ttis.sdlmt_id	<> 3			AND	-- Que NO sea AVISA RETIRO
				ttis.sreas_id	<> 0				-- STL 09-2024: Para que no realice una validación de que tiene pendientes turnos de armado cuando en el campo SREAS_ID tiene que NO REQUIERE ARMADO

	SELECT @bitIsTurnsOK [bitIsAssemblyTurnsOK]		-- Indica que NO falta asignar ningun turno de armado

END
GO




-- ATENCION:
