CREATE  PROCEDURE [dbo].[spTempItemStock_insertData]
(
	@comp_id			INT,
	@tis_guid			UNIQUEIDENTIFIER,
	@tis_priority		DECIMAL(14,4),
	@item_id			INT,
	@tis_itemDesc		VARCHAR(500),
	@tis_detail			VARCHAR(200),
	@curr_id			INT,
	@tis_initQty		DECIMAL(19,5),
	@tis_qty			DECIMAL(19,5),
	@prli_id			INT,
	@tis_price			DECIMAL(25,10),
	@stor_id			INT,
	@doc_id				INT,
	@bra_id				INT,
	@user_id			INT,
	@insertDate			DATETIME,
	@lastUpdate			DATETIME,
	@tis_cost			DECIMAL(19,5),
	@tis_costTax		INT,
	@soh_id				INT,
	@sod_id				INT,
	@to_associate		BIT,
	@is_id				INT,
	@tis_isMade			BIT,
	@ws_id				UNIQUEIDENTIFIER,
	@ws_IPFrom			NVARCHAR(50),
	@cust_id			INT,
	@return_value		INT OUTPUT
)
AS

BEGIN




	SET NOCOUNT ON



	-- --------------------------------------------------------------------------------
	-- test
	-- --------------------------------------------------------------------------------
/*
	DECLARE	@comp_id		int,
			@tis_guid		uniqueidentifier,
			@tis_priority	decimal(14,4),
			@item_id		int,
			@tis_itemDesc	varchar(100),
			@tis_detail		varchar(100),
			@curr_id		int,
			@tis_initQty	decimal(19,5),
			@tis_qty		decimal(19,5),
			@prli_id		int,
			@tis_price		decimal(19,6),
			@stor_id		int,
			@doc_id			int,
			@bra_id			int,
			@user_id		int,
			@insertDate		datetime,
			@lastUpdate		datetime,
			@tis_cost		decimal(19,5),
			@tis_costTax	int,
			@soh_id			int,
			@sod_id			INT,
			@to_associate	BIT,
			@is_id			INT,
			@tis_isMade			BIT,
			@return_value   int

	SELECT	@comp_id		= 1,
			@tis_guid		= '8D5AA877-3676-4713-B5BA-D2D842317DE5',
			@tis_priority	= 10455,
			@item_id		= 220,
			@tis_itemDesc	= 'Chevrolet Spark  *------------------------------------------------------------------------*',
			@tis_detail		= 'Detalle',
			@curr_id		= 1,
			@tis_initQty	= 1,
			@tis_qty		= 1,
			@prli_id		= 1,
			@tis_price		= 3332,
			@stor_id		= 1,
			@doc_id			= 4,
			@bra_id			= 1,
			@user_id		= 1,
			@insertDate		= '2012-09-01',
			@lastUpdate		= '2012-09-01',
			@tis_cost		= 0,
			@tis_costTax	= 1,
			@soh_id			= null,
			@sod_id			= null,
			@to_associate	= 'true',
			@is_id			= NULL,
			@tis_isMade		= 'false'
		DROP TABLE #tmpItemAssociation
*/
	-- --------------------------------------------------------------------------------


	-- --------------------------------------------------------------------------------------------------------
	-- Evitar Bloqueo de Interprocesos - CONSULTAR a Aquitecto
	-- --------------------------------------------------------------------------------------------------------
	SET LOCK_TIMEOUT 25000			-- 10 segundos
	SET DEADLOCK_PRIORITY HIGH		-- Tomar en cuenta para ULTIMA Opcion de Eliminación
	-- --------------------------------------------------------------------------------------------------------






	-- --------------------------------------------------------------------------------
	-- Verifica si viene de MercadoLibre para que SI o SI cargue el pedido
	-- --------------------------------------------------------------------------------
	DECLARE @bitIsFromMercadoLibre AS BIT
	SET		@bitIsFromMercadoLibre = 'False'
	IF @user_id < 0
		BEGIN
			SET @user_id = @user_id * -1
			SET	@bitIsFromMercadoLibre = 'True'
		END
	-- --------------------------------------------------------------------------------

	-- --------------------------------------------------------------------------------
	-- Verifica si viene de Web Services para que SI o Si Prorratee el Pedido
	-- y lleve el COMBO al importe que viene en el caso q un COMBO sume el precio de las partes
	-- --------------------------------------------------------------------------------
	DECLARE @bitIsFromWebServices AS BIT	= 'False'
	IF		@stor_id < 0
		BEGIN
			SET @stor_id = @stor_id * -1
			SET	@bitIsFromWebServices		= 'True'
		END
	-- --------------------------------------------------------------------------------

	-- --------------------------------------------------------------------------------
	-- Verifica si viene de Web Services para que SI o Si Prorratee el Pedido
	-- y lleve el COMBO al importe que viene en el caso q un COMBO sume el precio de las partes
	-- --------------------------------------------------------------------------------
	DECLARE @bitNotIncludeInAvailableStock AS BIT	= 'False'  -- MOS 05-2022 x S1
	IF		@prli_id < 0
		BEGIN
			SET @prli_id = @prli_id * -1
			SET	@bitNotIncludeInAvailableStock		= 'True'
		END
	-- --------------------------------------------------------------------------------







	DECLARE @bolItemWithDecimals	AS BIT = 'False'
	DECLARE @intItemMult			AS INT = 1
	DECLARE @bitIsManualItem		AS BIT = 'True'			-- MOS 01-2024: x los forros de Fulljaus q no se como MIERDA insertaron un item_id = 0
	SELECT	@bolItemWithDecimals = ISNULL(ti.item_withDecimal,'False'),
			@intItemMult		 = ISNULL(ti.item_mult,1),
			@bitIsManualItem	= 'False'
		FROM tbItem AS ti	WITH (NOLOCK)
		WHERE	ti.comp_id	= @comp_id AND
				ti.item_id	= @item_id


	-- MOS 01-2024: x los forros de Fulljaus q no se como MIERDA insertaron un item_id = 0
	IF @bitIsManualItem = 'True' AND @item_id IS NOT NULL
		BEGIN
			SET @item_id = NULL
		END


	-- --------------------------------------------------------------------------------
	-- Si llega un pedido de Stock con Decimales y el artículo NO los admite, pide la cantidad inmediata superior.
	-- --------------------------------------------------------------------------------
	IF @tis_qty <> CONVERT(INT,@tis_qty) AND @bolItemWithDecimals = 'False'
		BEGIN
			SET @tis_qty = CEILING(@tis_qty)
		END
	--IF @tis_qty <> CONVERT(INT,@tis_qty)
	--	BEGIN
	--		IF EXISTS(	SELECT TOP 1 1
	--          				FROM tbItem ti	WITH (NOLOCK)
	--          				WHERE	ti.comp_id			= @comp_id AND
	--          						ti.item_id			= @item_id AND
	--          						ti.item_withDecimal = 'False'
	--				)
	--			BEGIN
	--				SET @tis_qty = CEILING(@tis_qty)
	--			END
	--	END
	-- --------------------------------------------------------------------------------






	-- --------------------------------------------------------------------------------
	-- En Pedidos desde Sitio WEB controla si hay disponible para el pedido actual.
	-- Si se modifica algo hacerlo tambien en **LKNLKN23523LKddw
	-- --------------------------------------------------------------------------------
	DECLARE @stor_id4AvailableStock					AS INT = -1
	DECLARE @bitIsWebSiteSaleOrder					AS BIT = 'False'
	DECLARE @ws_saleOrderBlockUp2AvailableStorage	AS BIT
	DECLARE @ws_saleOrderBlockIfNOTAvailable		AS BIT
	DECLARE @ws_internalID							AS INT
	SET     @ws_saleOrderBlockUp2AvailableStorage	= 'False'
	SET     @ws_saleOrderBlockIfNOTAvailable		= 'False'

	SELECT
		@stor_id4AvailableStock					= ISNULL(twsin.stor_id4AvailableStock,@stor_id),
		@ws_saleOrderBlockUp2AvailableStorage	= twsin.ws_saleOrderBlockUp2AvailableStorage,
		@ws_saleOrderBlockIfNOTAvailable		= twsin.ws_saleOrderBlockIfNOTAvailable,
		@bitIsWebSiteSaleOrder					= 'True',
		@ws_internalID							= twsin.ws_internalID
		FROM tbWebSiteII_Names twsin			WITH (NOLOCK)
		WHERE	twsin.comp_id	= @comp_id AND
				twsin.ws_id		= @ws_id



	-- MOS 02-2023 para que segun lo q pide N1, se pueda depurar correct6amente si el pedido es de sitios web
	IF @ws_internalID IS NOT NULL
		BEGIN
			SET @insertDate = GETDATE()
			SET @lastUpdate = GETDATE()
		END




	-- --------------------------------------------------------------------------------
	-- Si el Artículo controla Multiplicidad, que NO lo permita si está mal
	-- --------------------------------------------------------------------------------
	IF	@bitIsFromMercadoLibre = 'False'	AND
		@bitIsWebSiteSaleOrder = 'False'    AND
		@intItemMult  > 1					AND
		@tis_qty     <> 1
		BEGIN
			IF (CONVERT(INT,(@tis_qty / @intItemMult)) * @intItemMult) <> @tis_qty
				BEGIN
					SET @return_value = -15
					RETURN
				END
		END
	-- --------------------------------------------------------------------------------





	IF	@bitIsFromMercadoLibre			= 'False' AND
		@bitNotIncludeInAvailableStock	= 'False' AND	-- MOS 05-2022 x S1
		(
			@ws_saleOrderBlockIfNOTAvailable		= 'True' OR
			@ws_saleOrderBlockUp2AvailableStorage	= 'True'
		)
		BEGIN
			DECLARE @decAvailableQTY AS DECIMAL(29,4)
			SET		@decAvailableQTY = dbo.fnGetAStock4MaxAssociation(@comp_id, @stor_id4AvailableStock /*@stor_id*/ ,@item_id,899999999)
			IF		@decAvailableQTY < 0 SET @decAvailableQTY = 0
			-- Si bloquea directamente SALE
			IF	@ws_saleOrderBlockIfNOTAvailable = 'True' AND
			    @tis_qty > @decAvailableQTY
				BEGIN
					SET @return_value = -1
					RETURN
				END
			IF  @ws_saleOrderBlockUp2AvailableStorage = 'True' AND
			    @tis_qty > @decAvailableQTY
				BEGIN
					IF @decAvailableQTY > 0
						BEGIN
							SET @tis_qty = @decAvailableQTY
						END
					ELSE
						BEGIN
							SET @return_value = -1
							RETURN
						END
				END
		END
	-- --------------------------------------------------------------------------------




	-- ---------------------------------------------------------------------
	-- Obtiene el tipo de ensamblado que requiere el articulo.
	-- ---------------------------------------------------------------------
	DECLARE @sreas_id as INT
	DECLARE @sdlmt_id AS INT
	DECLARE @SaleOrderBlockItemsWithNOPotentialStock_BlockStockChk AS BIT = 'False'
	SET @sreas_id = 0
	SELECT	@sreas_id = IsNull(ti.item_assemblyType,0),
			@sdlmt_id = IsNull(ti.sdlmt_id,1),
			@SaleOrderBlockItemsWithNOPotentialStock_BlockStockChk = ISNULL(ti.bra_SaleOrderBlockItemsWithNOPotentialStock_BlockStockChk,'False')

		FROM tbItem ti			WITH (NOLOCK)
		WHERE	ti.comp_id = @comp_id AND
				ti.item_id = @item_id
	-- ---------------------------------------------------------------------


	DECLARE @intDF_Id AS INT
	SET		@intDF_Id = @doc_id


	-- ---------------------------------------------------------------------
	-- Da de alta el item con cantidad 0 en el deposito, si es que no existe
	-- ---------------------------------------------------------------------
	If Isnull(@item_id,0) > 0
	BEGIN
		Exec spItemStorage_insertData
			@comp_id ,
			@item_id,
			@stor_id ,
			0
	END

	-- --------------------------------------------------------------------
	DECLARE @ltis_costTax AS INT
	If @item_id is Null
			Set @ltis_costTax = @tis_costTax
	ELSE
			Set @ltis_costTax = NULL




	DECLARE @lbra_SaleOrderItemCompByMarkUp				AS BIT
	DECLARE @bitSaleOrderBlockItemsWithNOPotentialStock AS BIT

	SELECT	@lbra_SaleOrderItemCompByMarkUp				= IsNull(tb.bra_SaleOrderItemCompByMarkUp,'false'),
			@bitSaleOrderBlockItemsWithNOPotentialStock	= ISNULL(tb.bra_SaleOrderBlockItemsWithNOPotentialStock,'false')
			FROM tbBranch tb		WITH (NOLOCK)
			WHERE	tb.comp_id	= @comp_id AND
					tb.bra_id	= @bra_id


	IF @bitIsWebSiteSaleOrder = 'true'  -- MOS : Si es pedido desde Sitio WEB NO debe hacer este control, de ultima q lo pongan a nivel de Sitio WEB
		BEGIN
			SET @bitSaleOrderBlockItemsWithNOPotentialStock = 'False'
		END


	-- MOS 04-2024: por el FORRO HIJO DE RE MIL PUTAS ENFERMO CAGADOR DE MIERDA de NG cd C1 y la RECONCHA DE TU REPUTA MADRE FORRO MERDOSO !!!!!!!
	IF @SaleOrderBlockItemsWithNOPotentialStock_BlockStockChk = 'True'
		BEGIN
			SET @bitSaleOrderBlockItemsWithNOPotentialStock = 'False'
		END



	-- -------------------------------------------------------------------------------
	-- Si @bitSaleOrderBlockItemsWithNOPotentialStock = TRUE entonces solo si el item
	-- no tiene ni composicion ni asociacion verifica que tenga SI o SI stock
	-- de no tener bloquea el alta.-
	-- -------------------------------------------------------------------------------
	DECLARE @bitIsCombo AS BIT
	SET		@bitIsCombo = 'False'
	SELECT TOP 1 @bitIsCombo =	CASE
									WHEN tia.item_id_1 IS NULL THEN 'False'
									ELSE							'True'
								END
		FROM tbItemAssociation tia		WITH (NOLOCK)
		WHERE	tia.comp_id = @comp_id AND
				tia.item_id = @item_id
	-- -------------
	IF	@bitIsFromMercadoLibre						= 'False'	AND
		@bitNotIncludeInAvailableStock				= 'False'	AND		-- MOS 05-2022 x S1
		@bitSaleOrderBlockItemsWithNOPotentialStock = 'True'	AND
		@item_id IS NOT NULL									AND
		@bitIsCombo									= 'False'
		BEGIN

			-- si el documento es factura o remito y lo que queda de potencial es menor que la cantidad solicitada, retorna error y no graba nada.-
			IF dbo.fnGetAStock(@comp_id,@stor_id,@item_id,@tis_priority) < @tis_qty AND ( (	SELECT sd_id
																								FROM tbDocumentsFile tdf	WITH (NOLOCK)
			                                                                               		WHERE tdf.comp_id = @comp_id AND tdf.df_id = @intDF_Id) IN (1,2))
				BEGIN
					set	@return_value = -1
					RETURN
				END
		END


	-- Idem para COMBOS   10-2017 MOS
	IF	@bitIsFromMercadoLibre						= 'False'	AND
		@bitSaleOrderBlockItemsWithNOPotentialStock = 'True'	AND
		@item_id IS NOT NULL									AND
		@bitIsCombo									= 'True'
		BEGIN

			-- si el documento es factura o remito y lo que queda de potencial es menor que la cantidad solicitada, retorna error y no graba nada.-
			IF	@bitNotIncludeInAvailableStock = 'False' AND -- MOS 05-2022 x S1
				dbo.fnGetAStock4MaxAssociation(@comp_id,@stor_id,@item_id,@tis_priority) < @tis_qty AND ( (	SELECT sd_id
																												FROM tbDocumentsFile tdf	WITH (NOLOCK)
			                                                                               						WHERE tdf.comp_id = @comp_id AND tdf.df_id = @intDF_Id) IN (1,2))
				BEGIN
					set	@return_value = -1
					RETURN
				END
		END
	-- -------------------------------------------------------------------------------



	-- -------------------------------------------------------------------------------
	-- Verifica si el documento dice que agrupo articulos iguales.
	-- -------------------------------------------------------------------------------
	DECLARE @bitGroupItemDefinedByDFID AS BIT
	SET		@bitGroupItemDefinedByDFID = 'False'
	SELECT	@bitGroupItemDefinedByDFID = ISNULL(tdf.df_SaleOrder_GroupEqualItems,'False')
		FROM tbDocumentsFile tdf WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @intDF_Id

	-- Si viene nun Nro de Serien infpormado NO AGRUPA!!
	IF iSnULL(@is_id,-1) > 0
		BEGIN
			SET @bitGroupItemDefinedByDFID = 'False'
		END
	-- -------------------------------------------------------------------------------

	----------------------------------------------------------------------------------
	---- Permite saber si tienen items asociados
	DECLARE @litem_id				INT
	DECLARE @tis_item_id_origin		INT
	DECLARE @lstor_id				INT
	DECLARE @ltis_price				DECIMAL(25,10) --




	IF EXISTS (	SELECT TOP 1 1
					FROM tbItemAssociation tia  WITH (NOLOCK)
	           		WHERE	tia.comp_id		= @comp_id  AND
	           				tia.item_id		= @item_id) AND
	           				@to_associate	= 'true'
		BEGIN

			SET @tis_item_id_origin = @item_id
			SET @litem_id			= NULL
			SET @lstor_id			= NULL
			SET @ltis_costTax		= NULL
			SET @ltis_price			= 0

		END
	ELSE
		BEGIN

			SET @tis_item_id_origin = NULL
			SET @litem_id			= @item_id
			SET @lstor_id			= @stor_id
			SET @ltis_price			= @tis_price

		END
	----------------------------------------------------------------------------------




	-- ------------------------------------------------------
	-- Si hacemos un INSERT de un articulo que AGRUPA
	-- ------------------------------------------------------
	DECLARE @tis_id4GroupItem AS INT
	SET		@tis_id4GroupItem = NULL
	IF @litem_id IS NOT NULL
		BEGIN
			SELECT  @tis_id4GroupItem = ttis.tis_id
				FROM tbTempItemStock ttis	WITH (NOLOCK)
				WHERE	ttis.comp_id	= @comp_id	AND
						ttis.tis_guid	= @tis_guid AND
						ttis.item_id	= @litem_id	AND
						ttis.stor_id	= @stor_id
		END

	IF	@litem_id IS NOT NULL	AND

			(
				@bitGroupItemDefinedByDFID = 'True'
				 OR

				EXISTS(	SELECT TOP 1  1
							FROM tbitem			WITH (NOLOCK)
	       					WHERE	comp_id					= @comp_id	AND
	       							item_id					= @litem_id AND
	       							item_expean				= 'True'	AND
	       							item_expeanGroupInSO	= 'True')
			)					AND
			@tis_id4GroupItem IS NOT NULL
		BEGIN
			-- 7799145004839
			UPDATE tbTempItemStock --WITH (ROWLOCK) le sdaque esto 02-2023
				SET	tis_qty			= tis_qty + @tis_qty,
					tis_IsEditingCd = GETDATE()    --@lastUpdate  MOS 02-2023 para que no lo ponga en hora 0
				WHERE	comp_id = @comp_id				AND
						tis_id	= @tis_id4GroupItem

			RETURN

		END
	ELSE -- Sino lo agrega como siempre
		BEGIN


			-- ------------------------------------------------------------------------------------------------
			-- MOS 03-2023 FIESA!!!!!  LRPM: Solo haga esta MIERDA si el cliente tiene alguna MIERDA de estas relacionada.
			-- y SEGUIMOS metiendo MIERDA x estos FORROS q solo comen recursos AL PEDO en todos los sistemas... LKRPMQTRMP!
			-- ------------------------------------------------------------------------------------------------
			DECLARE @intCustomer_tipi_discount	AS DECIMAL(19,4) = 0
			IF @bitIsWebSiteSaleOrder = 'True'	-- Solo si es por sitio web ya que en el pedido lo busca y lo pone en la wfmSaleOrderDetail en el item correspondiente
				BEGIN
					SELECT  TOP 1
							@intCustomer_tipi_discount	= ISNULL(lpqtp.tipi_discount,0)	-- MOS 03-2023 x FIESA, como siempre, para que se cargue en items individuales.
						FROM tbCustomer AS						tc		WITH (NOLOCK)
						INNER JOIN tbPriceListItemByItemType	lpqtp	WITH (NOLOCK)
							ON	lpqtp.comp_id	= tc.comp_id AND
								lpqtp.cust_id	= @cust_id
						WHERE	tc.comp_id		= @comp_id AND
								tc.cust_id		= @cust_id AND
								lpqtp.item_id	= @litem_id
				END
			-- ------------------------------------------------------------------------------------------------


			-- --------------------------------------------------
			--** ATENCION, Actualizar tambien en **wsehfjkhweweq
			-- --------------------------------------------------
			insert into dbo.tbTempItemStock WITH (ROWLOCK)
			(	comp_id, 						tis_guid,
				tis_priority,					item_id,
				tis_itemDesc,					tis_detail,
				curr_id,						tis_initQty,
				tis_qty,						prli_id,
				tis_price,						tis_cost,
				tis_costTax,					stor_id,
				doc_id,							tis_CD,
				bra_id,							soh_id,
				tis_insertDate,					tis_itemDiscount,
				tis_IsEditingCd,				USER_ID,
				sod_id,							tis_item_id_origin,
				is_id,							tis_isMade,
				tis_IsEditing,					tis_order,
				sdlmt_id,
				tis_loanNumberOfPays,
				sreas_id,						ws_IPFrom,
				ws_price,						ws_curr_Id,
				ws_internalID,					df_id,
				tis_MercadoLibre_MustUpdateStock)
			values
			(	@comp_id,						@tis_guid,
				@tis_priority,					@litem_id,
				@tis_itemDesc,					@tis_detail,
				@curr_id,						@tis_initQty,
				@tis_qty,						@prli_id,
				@ltis_price,					@tis_cost,
				@ltis_costTax,					@lstor_id,
				@doc_id,						@insertDate,
				@bra_id,						@soh_id,
				@lastUpdate,					@intCustomer_tipi_discount /*0*/, -- MOS 03-2023 x los FORROS de FIESA, espero que no joda a otra gente...
				getdate(),						@user_id,
				@sod_id	,						@tis_item_id_origin,
				@is_id,							@tis_isMade,
				'true',							77777777,
				@sdlmt_id,
				0,
				@sreas_id,						@ws_IPFrom,
				@ltis_price,					@curr_id,
				@ws_internalID,					@intDF_Id,
				'True'
			)

			-- --------------------------------------------------



		END
	-- ------------------------------------------------------



	set	@return_value = @@IDENTITY  --recupero el tis_id generado por el insert anterior
	--SELECT @return_value








	--si recibe la marca que debe asociar artículos los genera automáticamente
	IF @to_associate = 'true'
		BEGIN


			-- Averigua si debe prorratear impuestos internos para este documento.
			DECLARE @intDocumenHasInternalTaxes AS INT
			SET		@intDocumenHasInternalTaxes = 0
			SELECT  @intDocumenHasInternalTaxes = 1
				FROM tbTaxByDocumentsFile ttbdf	WITH (NOLOCK)
				INNER JOIN tbTaxName ttn		WITH (NOLOCK)
				ON	ttn.comp_id = ttbdf.comp_id AND
					ttn.tax_id	= ttbdf.tax_id
				WHERE	ttbdf.comp_id	= @comp_id	AND
						ttbdf.df_id		= @intDF_Id	AND
						ttn.tax_class   = 20 -- Impuestos Internos

			-- -- Items Asociados	--
			-- declaración de variables para obtener los datos del cursor
			DECLARE @tis_id_origin  INT
			DECLARE	@liasso_qty		DECIMAL(19,5) --INT 06-2020
			DECLARE @lcomp_id		INT
			DECLARE @litem_id_1		INT
			DECLARE @lNewPrice		DECIMAL(19,5)
			DECLARE @litem_desc		VARCHAR(100)


			-- ------------------------------------------------------------------------------------------------
			-- FIESA!!!!!  LRPM: Solo haga esta MIERDA si el cliente tiene alguna MIERDA de estas relacionada.
			-- ------------------------------------------------------------------------------------------------
			DECLARE @intCustomer_prli_id		AS INT = -1
			SELECT  TOP 1
					@intCustomer_prli_id		= tc.prli_id
				FROM tbCustomer AS						tc		WITH (NOLOCK)
				INNER JOIN tbPriceListItemByItemType	lpqtp	WITH (NOLOCK)
					ON	lpqtp.comp_id	= tc.comp_id AND
						lpqtp.cust_id	= @cust_id
				WHERE	tc.comp_id		= @comp_id AND
						tc.cust_id		= @cust_id
			IF @bitIsFromMercadoLibre	= 'True'	-- Si viene de Meli que NO ponga ninguna de estas FORRADAS!!!!
				BEGIN
					SET @intCustomer_prli_id = -1
				END
			-- ------------------------------------------------------------------------------------------------



			-- por si algun FORRO PELOTUDO no le carga los putos precios a las partes del combo ponga como precio 1 y prorratee sobre eso.
			DECLARE @decPrecioIfNull AS DECIMAL = 1
			DECLARE @intMonedaIfNull AS INT		= 1

			--cargo en la temporal todos los valores necesarios para el proceso
			SELECT	tia.item_id_1,
					--id de item asociado

					convert(decimal(19,6),dbo.fnGetExchange2(@comp_id,ISNULL(
																				ISNULL(tpli.prli_price,tpli2.prli_price)
																								,@decPrecioIfNull),ISNULL(
																															ISNULL(tpli.curr_id,tpli2.curr_id)
																																		,@intMonedaIfNull),@curr_id, 0,0,0,'false') * tia.iasso_qty)	[PriceQty],
					--precio de lista en la moneda recibida por la cantidad del item asociado

					convert(decimal(19,6),dbo.fnGetExchange2(@comp_id,ISNULL(
																				ISNULL(tpli.prli_price,tpli2.prli_price)
																								,@decPrecioIfNull) +
																								(ISNULL(
																											ISNULL(tpli.prli_price,tpli2.prli_price)
																															,@decPrecioIfNull) * IsNull(	(	SELECT TOP 1 ttn.tax_percentage
																																									FROM tbItemTaxes		tit		WITH (NOLOCK)
																																									INNER JOIN tbTaxName	ttn		WITH (NOLOCK)
																																										ON		ttn.comp_id = @comp_id
																																											AND ttn.tax_id	= tit.tax_id
	                                                   																												WHERE	tit.comp_id		= @comp_id
	                                                   																													AND tit.item_id		= ti.item_id
	                                         																															AND ttn.tax_class	= 1				-- Solo Tipo IVA
																								                                                   	 				ORDER BY	CASE	-- MOS 08-2020, para que 1ro tome el iva  de combo si es que está definido
																								                                                   	 								WHEN tit.tax_itemComposed = 'True' THEN 0
																								                                                   	 								ELSE									1
																								                                                   	 							END,
																								                                                   	 							ttn.tax_order
	                                                   												),0) / 100
																								)
--	MOS 07-2018																				  +
																						+
																								( @intDocumenHasInternalTaxes *
																								  ISNULL(
																								  		 ISNULL(tpli.prli_price,tpli2.prli_price)
																								  					    ,@decPrecioIfNull) * IsNull(	(	SELECT TOP 1 ttn.tax_percentage
																																								FROM tbItemTaxes		tit		WITH (NOLOCK)
																																								INNER JOIN tbTaxName	ttn		WITH (NOLOCK)
																																									ON		ttn.comp_id = @comp_id
																																										AND ttn.tax_id	= tit.tax_id
	                                                   																											WHERE	tit.comp_id		= @comp_id
	                                                   																												AND tit.item_id		= ti.item_id
	                                         																														AND ttn.tax_class	= 20				-- Solo Tipo Impuestos Internos
																																									AND
																																									   (tit.bra_id IS NULL OR
																																										tit.bra_id = @bra_id
																																										)
	                                                         	 																								ORDER BY ttn.tax_order
	                                                   												),0) / 100
																								)
																			 ,ISNULL(
																			 		 ISNULL(tpli.curr_id,tpli2.curr_id)
																			 					 ,@intMonedaIfNull),@curr_id, 0,0,0,'false') * tia.iasso_qty)	[PriceQtyWTax],

					CASE
						WHEN ti.item_withDecimal = 'True' THEN tia.iasso_qty
						ELSE round(tia.iasso_qty,0)
					END
					/*tia.iasso_qty*/																															[qty],
					--cantidad del item asociado (lo utilicé para ver si las cuentas a mano daban igual)

					convert(decimal(19,6),dbo.fnGetExchange2(@comp_id,ISNULL(
																			 ISNULL(tpli.prli_price,tpli2.prli_price)
																						    ,@decPrecioIfNull),ISNULL(
																						    							ISNULL(tpli.curr_id,tpli2.curr_id)
																						    										 ,@intMonedaIfNull),@curr_id, 0,0,0,'false')) [OriginalPrice],
					--precio para las cuentas manuales

					convert(decimal(19,6),0.0)		[NewPrice],
					--es un campo que se va a actualizar más abajo
					tia.itema_id,
					ISNULL(tpli.prli_id,tpli2.prli_id)																[prli_id]
				INTO	#tmpItemAssociation
				FROM	tbItemAssociation						tia		WITH (NOLOCK)
				INNER JOIN tbItem								ti		WITH (NOLOCK)
					ON	ti.comp_id	= tia.comp_id	AND
						ti.item_id	= tia.item_id_1

				-- ---
				-- MOS: 02-2022 x FIESA y LRPM&%&#%$#%$#
				-- ---
				LEFT JOIN tbPriceListItemByItemType tmpPriceByItemType	WITH (NOLOCK)
					ON	tmpPriceByItemType.comp_id = @comp_id AND
						tmpPriceByItemType.cust_id = @cust_id AND
						tmpPriceByItemType.item_id = ti.item_id			-- MOS 15-03-2022 @item_id

				LEFT JOIN vwPriceListItems			tpli				WITH (NOLOCK)
					ON	tpli.comp_id = ti.comp_id	AND
						tpli.item_id = ti.item_id	AND
						tpli.prli_id = ISNULL(tmpPriceByItemType.prli_id, @prli_id)	-- MOS 02-2022 x FIESA

				LEFT JOIN vwPriceListItems			AS tpli2			WITH (NOLOCK)
					ON	tpli2.comp_id = ti.comp_id	AND
						tpli2.item_id = ti.item_id	AND
						tpli2.prli_id = @intCustomer_prli_id	-- MOS 03-2022 x FIESA, me hacen CAGAR la performance el REPUTO SISTEMA



				-- ---

				WHERE	tia.comp_id = @comp_id		AND
						tia.item_id	= @item_id		AND
						CASE
							WHEN @bitIsFromMercadoLibre = 'True'												THEN 1
							WHEN @bitIsFromMercadoLibre = 'False' AND tpli.comp_id IS NOT NULL					THEN 1
							WHEN @bitIsFromMercadoLibre = 'False' AND tmpPriceByItemType.comp_id IS NOT NULL	THEN 1
							ELSE 0
						END = 1

				--SELECT * FROM #tmpItemAssociation --SÓLO PARA VER LOS DATOS







			--obtener el coeficiente entre el precio cargado original y la sumatoria de los items asociados
			DECLARE @coeficiente			as DECIMAL(19,6)
			DECLARE @decPriceWithTax		AS DECIMAL(19,6)
			--DECLARE @decPriceTotalWithTax	AS DECIMAL(19,6)
			SET		@decPriceWithTax =
								@tis_price +   (
												(@tis_price * IsNull(	(	SELECT TOP 1 ttn.tax_percentage
																				FROM tbItemTaxes		tit		WITH (NOLOCK)
																				INNER JOIN tbTaxName	ttn		WITH (NOLOCK)
																					ON		ttn.comp_id = tit.comp_id	AND
																							ttn.tax_id	= tit.tax_id
	                                                   							WHERE	tit.comp_id		= @comp_id
	                                                   								AND tit.item_id		= @item_id
	                                                   								AND ttn.tax_class	= 1				-- Solo Tipo IVA
	                                                         	 				ORDER BY
	                                                         	 					CASE	-- MOS 08-2020, para que 1ro tome el iva  de combo si es que está definido
																						WHEN tit.tax_itemComposed = 'True' THEN 0
																						ELSE									1
																					END,
																					ttn.tax_order
	                                                   					)
																  ,0) / 100
												)
												   -- -----------------------------------------------------------
												+  -- Impuestos Internos MOS 05-2017
												   -- -----------------------------------------------------------
												( @intDocumenHasInternalTaxes *
												  @tis_price * IsNull(	(	SELECT TOP 1 ttn.tax_percentage
																				FROM tbItemTaxes		tit		WITH (NOLOCK)
																				INNER JOIN tbTaxName	ttn		WITH (NOLOCK)
																					ON		ttn.comp_id = tit.comp_id		AND
																							ttn.tax_id	= tit.tax_id
	                                                   							WHERE	tit.comp_id		= @comp_id	AND
	                                                   									tit.item_id		= @item_id	AND
	                                                   									ttn.tax_class	= 20		AND
	                                                   								   (tit.bra_id IS NULL OR
	                                                   								    tit.bra_id = @bra_id
	                                                   								    )		-- Solo Impuestos Internos
	                                                         	 				ORDER BY ttn.tax_order
	                                                   					)
																   ,0) / 100
												)
											   )
												-- -----------------------------------------------------------

			SET @coeficiente = (SELECT @decPriceWithTax / dbo.fnNoZDiv( SUM(tmp.[PriceQtyWTax]))
									FROM #tmpItemAssociation tmp)


			-- Si el articulo dice que sume precios y no prorratee pone el coeficiente en 1.
			IF EXISTS (	SELECT TOP 1 1
			           		FROM tbItem ti	WITH (NOLOCK)
			           		WHERE	ti.comp_id								= @comp_id AND
			           				ti.item_id								= @item_id AND
			           				ti.item_ifHasItemAssociationSumPrices	= 'True'
					   )
				BEGIN
					IF @bitIsFromWebServices = 'False'	-- MOS 01-2021 x sonnos x combo de Balcony q Suma precios de partes pero DEBE cargarse con el importe que llega de Balcony
						BEGIN
							SET @coeficiente = 1
						END
				END


			--SET @coeficiente = (SELECT @tis_price / SUM(tmp.[PriceQty]) FROM #tmpItemAssociation tmp)
			--SELECT @coeficiente --SÓLO PARA VER LOS DATOS


			-- Si es Actualizacion por Coeficiente
			IF	@lbra_SaleOrderItemCompByMarkUp  = 'false'
				BEGIN
					--actualización de la temporal con el nuevo precio para que den las cuentas con el valor original
					UPDATE	#tmpItemAssociation
						SET		[NewPrice] = @coeficiente * [OriginalPrice]
					--SELECT * FROM #tmpItemAssociation --SÓLO PARA VER LOS DATOS
				END
			ELSE
			-- Si es Actualizacion por MarkUp segun Reglas de Actualizacion de Precios.
				BEGIN

					SET		@coeficiente = 1		-- En este caso si recalculan precios en pedidos se pondran a precios de LISTA!!!
					DECLARE @lMarkup DECIMAL(19,6)
					DECLARE @decCost DECIMAL(19,6)
					DECLARE @item_id_tmp AS INT
					DECLARE @lcurr_id AS int

					SELECT TOP 1
							@lMarkup =  isnull(vipbcbar.MarkUp_N,0)

						FROM vwItemPriceByCostByActRules vipbcbar		WITH (NOLOCK)

							INNER JOIN tbBranch tb						WITH (NOLOCK)
							ON tb.comp_id	= vipbcbar.comp_id
							AND tb.bra_id	= @bra_id

						WHERE vipbcbar.comp_id	= @comp_id
						AND	  vipbcbar.item_id	= @item_id
						AND   vipbcbar.coslis_id= tb.coslis_id
						AND   vipbcbar.prli_id	= @prli_id


					declare cursor_Markup CURSOR LOCAL FAST_FORWARD FOR
						SELECT item_id_1 FROM #tmpItemAssociation

					open	cursor_Markup
					fetch	cursor_Markup
						into	@item_id_tmp
					while   @@fetch_status = 0
						BEGIN

							SELECT
									@decCost = isnull(
													CASE
														WHEN tb.bra_costlist_type	= 'true'	THEN ticl.coslis_price_aw
														ELSE ticl.coslis_price
													END,0),
									@lcurr_id = ticl.curr_id

			--						@lcurr_id = isnull(ticl.curr_id,
			--										(SELECT ti.curr_id
			--											FROM tbItem ti
			--											WHERE	ti.comp_id = @comp_id
			--												AND ti.item_id = @item_id))


								FROM vwItemPriceByCostByActRules vipbcbar			WITH (NOLOCK)
									INNER JOIN tbItemCostList ticl					WITH (NOLOCK)
									ON ticl.comp_id		= vipbcbar.comp_id
									AND ticl.item_id	= vipbcbar.item_id
									AND ticl.coslis_id	= vipbcbar.coslis_id

									INNER JOIN tbBranch tb							WITH (NOLOCK)
									ON tb.comp_id	= vipbcbar.comp_id
									AND tb.bra_id	= @bra_id

								WHERE vipbcbar.comp_id = @comp_id
								AND	  vipbcbar.item_id = @item_id_tmp --@item_id
								AND   vipbcbar.coslis_id= tb.coslis_id
								AND   vipbcbar.prli_id	= @prli_id

							SET @decCost = 	dbo.fnGetExchange2(@comp_id,@decCost,@lcurr_id,@curr_id, 0,0,0,'false')

							UPDATE	#tmpItemAssociation
								SET		[NewPrice] =  IsNull(@decCost + (@decCost * @lMarkup /100),0)
								WHERE item_id_1 = @item_id_tmp

							fetch	cursor_Markup
							into	@item_id_tmp
						END
					close cursor_Markup
					deallocate cursor_Markup


				END



			DECLARE @isAssociated BIT
			SET @isAssociated  = 'false'
			DECLARE @itema_discountPercentage4PriceListSUM					AS DECIMAL(15,4)
			DECLARE @itema_canDeleteInSO									AS BIT
			DECLARE @item_isForAssociation_discountPercentage4PriceListSUM	AS DECIMAL(15,4)
			DECLARE @item_ifHasItemAssociationSumPrices						AS BIT
			DECLARE @prli_id4FIESA											AS INT = NULL
			DECLARE @tipi_discount											AS DECIMAL(15,4)

			declare cursor_items CURSOR LOCAL FAST_FORWARD for
			select	tia.comp_id,
					tia.item_id,
					tia.item_id_1,
					tia.iasso_qty,
					IA.[NewPrice],
					ti.item_desc,
					ISNULL(tia.itema_discountPercentage4PriceListSUM,0),
					ISNULL(tia.itema_canDeleteInSO,'False'),
					ISNULL(tiCombo.item_isForAssociation_discountPercentage4PriceListSUM,0),
					ISNULL(tiCombo.item_ifHasItemAssociationSumPrices,'False'),
					IA.prli_id,
					ISNULL(prFIE.tipi_discount,0)

				FROM	tbItemAssociation					tia		WITH (NOLOCK)
				INNER JOIN #tmpItemAssociation		IA
					ON	tia.item_id_1	= IA.item_id_1 AND
						tia.itema_id    = IA.itema_id
				INNER JOIN tbItem					ti			WITH (NOLOCK)
					ON	ti.comp_id		= tia.comp_id	AND
						ti.item_id		= tia.item_id_1
				INNER JOIN tbItem					tiCombo		WITH (NOLOCK)
					ON	tiCombo.comp_id	= tia.comp_id	AND
						tiCombo.item_id	= tia.item_id
				LEFT JOIN tbPriceListItemByItemType prFIE		WITH (NOLOCK) -- MOS 01-2023 x FIESA ticket 18160 para que tome el descuento en cada item de combo que esta puesto en esa tabla para ese cliente
					ON	prFIE.comp_id	= tia.comp_id		AND
						prFIE.item_id	= tia.item_id_1		AND
						prFIE.cust_id	= @cust_id			AND
						prFIE.prli_id	= ISNULL(@prli_id4FIESA,@prli_id)
				where	tia.comp_id		= @comp_id
				and		tia.item_id		= @item_id


			open	cursor_items

			-- lectura anticipada del cursor
			fetch	cursor_items
			into	@lcomp_id,
					@litem_id,
					@litem_id_1,
					@liasso_qty,
					@lNewPrice,
					@litem_desc,
					@itema_discountPercentage4PriceListSUM,
					@itema_canDeleteInSO,
					@item_isForAssociation_discountPercentage4PriceListSUM	,
					@item_ifHasItemAssociationSumPrices,
					@prli_id4FIESA,
					@tipi_discount


			while   @@fetch_status = 0
				BEGIN

					--marca que indica que el item original tiene items asociados
					SET @isAssociated = 'true'




					-- --------------------------------------------------
					--** ATENCION, Actualizar tambien en **wsehfjkhweweq
					-- --------------------------------------------------
					insert into dbo.tbTempItemStock WITH (ROWLOCK )
						(	comp_id, 			tis_guid,
							tis_priority,		item_id,
							tis_itemDesc,		tis_detail,
							curr_id,			tis_initQty,
							tis_qty,			prli_id,
							tis_price,			tis_cost,
							tis_costTax,		stor_id,
							doc_id,				tis_CD,
							bra_id,				soh_id,
							tis_insertDate,		tis_itemDiscount,
							tis_IsEditingCd,	USER_ID,
							sod_id,				tis_item_id_origin,
							tis_id_origin,		tis_isParentAssociate	,
							tis_order,			tis_IsEditing,
							tis_isMade,			sdlmt_id,
							tis_loanNumberOfPays,
							sreas_id, tis_itemAssociationCoeficient, ws_IPFrom,
							ws_price, ws_curr_Id,
							ws_internalID,df_id,tis_MercadoLibre_MustUpdateStock,
							tis_canDeleteCOMBOInSO)
					values
						(	@comp_id,			@tis_guid,
							@tis_priority,		@litem_id_1,
							@litem_desc,		@tis_detail,
							@curr_id,
							@tis_qty * @liasso_qty,
							@tis_qty * @liasso_qty,

							-- FIESA MOS 15-03-2022 quieren ademas la REPUTA LISTA con que hicieron la REPUTA VENTA.  SIGAN HACIENDO SUBIR LA REPUTA ENTROPÏA DEL REPUTO SISTEMA y LRPMQLP
							ISNULL(@prli_id4FIESA,@prli_id),
							--@prli_id,

							@lNewPrice,			@tis_cost,
							null,				@stor_id,
							@doc_id,			@insertDate,
							@bra_id,			@soh_id,
							@lastUpdate,		CASE			-- MOS 06-2020
													WHEN	@item_ifHasItemAssociationSumPrices = 'True'	AND
															@bitIsFromWebServices				= 'False'		-- SOLO deben ponerse si es que NO se cargan x ws 19-01-2021 MOS
															--AND																																							-- MOS 01-2023 x ticket  18160
															/*@bitIsFromMercadoLibre				= 'False'*/		THEN (@itema_discountPercentage4PriceListSUM + @item_isForAssociation_discountPercentage4PriceListSUM + @tipi_discount)
													ELSE															 0
												END
												/*0*/ ,
							getdate(),			@user_id,
							@sod_id,			@litem_id_1 ,
							@return_value,		'false',
							77777777,			'True',
							@tis_isMade,		@sdlmt_id,
							0 ,
							@sreas_id,
							@coeficiente,		@ws_IPFrom,
							@lNewPrice,			@curr_id,
							@ws_internalID,		@intDF_Id,
							'True',
							@itema_canDeleteInSO)		-- MOS 07-2024: Faltaba guardar este campo.  se habia puesto en el cursor pero NO se estaba guardando.
					-- --------------------------------------------------



					fetch	cursor_items
					into	@lcomp_id,
							@litem_id,
							@litem_id_1,
							@liasso_qty,
							@lNewPrice,
							@litem_desc,
							@itema_discountPercentage4PriceListSUM,
							@itema_canDeleteInSO,
							@item_isForAssociation_discountPercentage4PriceListSUM,
							@item_ifHasItemAssociationSumPrices,
							@prli_id4FIESA,
							@tipi_discount


				end

			close cursor_items
			deallocate cursor_items





			-- ----------------------------------------------------------------------------------------------------------
			--si la marca @isAssociated = 'true' significa que el item ingresado tenía items asociados,
			--entonces se deben actualizar los campos el tis_id_origin con su propio tis_id (@return_value)
			--y el tis_isParentAssociate con 'true', lo que indica que ítem ingresado es le padre de una asociación
			-- ----------------------------------------------------------------------------------------------------------
			IF @isAssociated = 'true'
				BEGIN

					UPDATE	tbTempItemStock	WITH (ROWLOCK)
						SET		tis_id_origin			= @return_value,
								tis_isParentAssociate	= 'true'
						WHERE	comp_id					= @comp_id
						AND		tis_id					= @return_value

					-- MOS 02-2022: saque el 77777780 de las partes de arriba y lo deje en 77777777 como antes para q no desordene.   El FORRO de las cervezas QUE SE CAGUE!!
					--UPDATE	tbTempItemStock	WITH (ROWLOCK)
					--	SET		tis_order				= 77777780
					--	WHERE	comp_id					= @comp_id
					--	AND		tis_id_origin			= @return_value

				END
			-- ----------------------------------------------------------------------------------------------------------




		END
	ELSE
		BEGIN


				--si la marca que debe asociar artículos es 'false' y están informados el soh_id y el sod_id
				--se deben actualizar el registro insertado

				DECLARE @ltis_id_origin INT,
						@ltis_item_id_origin INT,
						@ltis_isParentAssociate BIT




				SELECT	@ltis_id_origin			= tsod.sod_tis_id_origin,
						@ltis_item_id_origin	= tsod.sod_item_id_origin,
						@ltis_isParentAssociate	= tsod.sod_isParentAssociate

					FROM	tbSaleOrderDetail tsod			WITH (NOLOCK)

					WHERE	tsod.comp_id	= @comp_id
					AND		tsod.bra_id		= @bra_id
					AND		tsod.soh_id		= @soh_id
					AND		tsod.sod_id		= @sod_id



				IF @ltis_isParentAssociate = 'true' --es el padre de una asociación de ítems
					BEGIN

						update	tbSaleOrderDetail	WITH (ROWLOCK)
							SET		sod_tis_id_origin	= @return_value
							WHERE	comp_id				= @comp_id
							AND		bra_id				= @bra_id
							AND		soh_id				= @soh_id
							AND	    sod_tis_id_origin	= @ltis_id_origin


							UPDATE	tbTempItemStock	WITH (ROWLOCK)
								SET		tis_id_origin			= @return_value,
										tis_item_id_origin		= @ltis_item_id_origin,
										tis_isParentAssociate	= @ltis_isParentAssociate
								WHERE	comp_id			= @comp_id
								AND		tis_id			= @return_value

					END
				ELSE
					BEGIN

						UPDATE	tbTempItemStock	WITH (ROWLOCK)
							SET		tis_id_origin			= @ltis_id_origin,
									tis_item_id_origin		= @ltis_item_id_origin,
									tis_isParentAssociate	= @ltis_isParentAssociate
							WHERE	comp_id			= @comp_id
							AND		tis_id			= @return_value

					END




		END

		-- --------------------------------------------------------------------------
		-- MOS 06-2020
		-- Si es un REMITO de transferencia, y es un COMBO, borra el item MANUAL
		-- --------------------------------------------------------------------------
		IF @return_value > 0 AND
			EXISTS(
					SELECT TOP 1 1
						FROM tbDocumentsFile tdf	WITH (NOLOCK)
						WHERE	tdf.comp_id		= @comp_id		AND
								tdf.df_id		= @intDF_Id		AND
								tdf.df_isInterBranchDocument = 'True' AND
								tdf.sd_id = 2
					)
			BEGIN
				DELETE FROM tbTempItemStock		WITH (ROWLOCK)
					WHERE	tis_id	= @return_value AND
							item_id IS NULL
			END
		-- --------------------------------------------------------------------------



		-- --------------------------------------------------------------------------
		-- FIESA: que al guardar un item en un pedido si es un dcto y un deposito, reemplace ese deposito x otro
		-- --------------------------------------------------------------------------
		UPDATE tbTempItemStock
			SET stor_id = tar.stor_id_Destiny
			FROM tbTempItemStock AS ttis
			INNER JOIN tbStorage4SOAutoReplace   tar
				ON	tar.comp_id				= ttis.comp_id	AND
					tar.df_id				= ttis.df_id	AND
					tar.stor_id_Selected	= ttis.stor_id
			WHERE ttis.tis_guid = @tis_guid
		-- --------------------------------------------------------------------------



END
GO




-- BOTON OK de pagina de Detail de seleccion de remitos pendientes de facturacion.-


CREATE  PROCEDURE [dbo].[spTempItemStock_insertData_From_Packing]
(
		@comp_id		INT,
		@lang_id		INT,
		@cust_id		INT,
		@guid			UNIQUEIDENTIFIER,
		@option			INT,
		@df_id			INT,
		@stor_id		INT,
		@bra_id			INT
)
AS




BEGIN

	SET NOCOUNT ON
-- -----------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------
/*
	--DELETE FROM tbTempItemStock
	DECLARE		@comp_id		INT,
				@cust_id		INT,
				@guid			UNIQUEIDENTIFIER,
				@option			INT,
				@lang_id		INT,
				@df_id			INT,
				@stor_id		INT,
				@bra_id			INT

	SELECT 		@comp_id		= 1,
				@cust_id		= 1,
				@guid			= 'ba3c2524-06ee-4ec1-b552-e9cd83de4821',
				@option			= 3,
				@lang_id		= 2,
				@df_id			= 5,
				@stor_id		= 1,
				@bra_id			= 0
	--UPDATE tbItemTransactions
	--SET it_packingInvoiceSelected = 'False'
*/
-- -----------------------------------------------------------------

	-- Obtiene el Orden de Insercion
	DECLARE @intOrder AS INT
	SELECT	@intOrder = MAX(IsNull(ttis.tis_order,0)) + 100
		FROM tbTempItemStock ttis	WITH (NOLOCK)
		WHERE ttis.tis_guid = @guid
	IF @intOrder IS NULL SET @intOrder = 0


	DECLARE @intActualQTYInserted AS INT
	SET		@intActualQTYInserted = 0
	SELECT  @intActualQTYInserted = count(*)
		FROM tbTempItemStock ttis	WITH (NOLOCK)
		WHERE	ttis.tis_guid		= @guid



	DECLARE @intTaxIdByDefault AS INT
	SELECT Top 1 @intTaxIdByDefault = ttn.tax_id
		FROM tbTaxName ttn			WITH (NOLOCK)
		WHERE	ttn.comp_id		= @comp_id
			AND ttn.tax_class	= 1
		ORDER BY ttn.tax_order
	--SELECT @intTaxIdByDefault


	DECLARE @intMaxItemQty AS INT
	SET		@intMaxItemQty = 0

	DECLARE @df_PreInvoice_CreditNoteRestoreStockIfPLEmitted						AS BIT = 'False'	-- MOS:04-2022 Tomar esto del documento NC para decir si haco NC x Fc Anticipada con remito EMITIDO por CODIGO y no x concepto.
	DECLARE @df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms	AS BIT = 'False'
	DECLARE @bitSaleOrder_CreditNoteFromInvoiceStorageByHeader						AS BIT
	DECLARE @df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount				AS BIT = 'False'
	DECLARE @bra_saleOrder_InvoiceFromPackingWithOriginalExchang					AS BIT = 'False'
	DECLARE @intStorId AS INT
	SET		@intStorId	= -1

	SELECT  @df_PreInvoice_CreditNoteRestoreStockIfPLEmitted 						= ISNULL(df_PreInvoice_CreditNoteRestoreStockIfPLEmitted,'False'),
			@df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms	= ISNULL(tdf.df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms,'False'),
			@intStorId																= IsNull(tdf.df_SaleOrder_Storage4CreditNoteReplacement,-1),
			@bitSaleOrder_CreditNoteFromInvoiceStorageByHeader						= ISNULL(tdf.df_SaleOrder_CreditNoteFromInvoiceStorageByHeader,'False'),
			@intMaxItemQty															= ISNULL(tdf.df_maxItems,0),
			@df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount				= ISNULL(tdf.df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount,'False'),
			@bra_saleOrder_InvoiceFromPackingWithOriginalExchang					= ISNULL(tdf.bra_saleOrder_InvoiceFromPackingWithOriginalExchange,'True')
		FROM tbDocumentsFile tdf	 WITH (NOLOCK)
		WHERE   tdf.comp_id = @comp_id	AND
				tdf.df_id	= @df_id


	IF @df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms = 'True'
		BEGIN
			SET @df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount	= 'False'
			SET @bra_saleOrder_InvoiceFromPackingWithOriginalExchang		= 'False'
		END


	DECLARE @intTop4Insert AS INT
	SET		@intTop4Insert = 1
	SET		@intTop4Insert = @intMaxItemQty - @intActualQTYInserted

	IF @bitSaleOrder_CreditNoteFromInvoiceStorageByHeader = 'True' AND @stor_id IS NOT NULL AND @stor_id <> -1 AND @intStorId = -1
		BEGIN
			SET @intStorId = @stor_id
		END

	if @bitSaleOrder_CreditNoteFromInvoiceStorageByHeader = 'False'
		BEGIN
			SET @intStorId = -1
		END




	BEGIN TRANSACTION
	BEGIN TRY


		-- ------------------------------------
		-- Bloquear la base antes de hacer nada
		-- ------------------------------------
		DECLARE @intLock AS INT
		SELECT @intLock = tce.sb_id
			FROM tbsysBlockPage4IsoTran  tce
		-- ------------------------------------

		DECLARE @intNewTIS_Id AS INT	= NULL
		SELECT	@intNewTIS_Id			= IDENT_CURRENT('tbTempItemStock') + IDENT_INCR('tbTempItemStock')

--SELECT 1 / 0

		INSERT INTO tbTempItemStock
		(
			comp_id,				tis_guid,				tis_priority,
			item_id,				tis_itemDesc,			tis_detail,
			curr_id,
			tis_initQty,			tis_qty,
			prli_id,
			tis_price,
			tis_priceInBranchCurrency,
			tax_id,					tis_cost,				tis_costTax,
			stor_id,				doc_id,					tis_CD,
			bra_id,					soh_id,					tis_insertDate,
			[user_id],				aure_id,				aure_itemComposed,
			tis_itemDiscount,		tis_CreditInt,			tis_CreditIntPlus,
			tis_itemDiscountTotal,	tis_totalDiscountTOTAL,	tis_isQuotation,
			tis_isCredit,			tis_IsEditing,			tis_IsEditingCd,
			tis_production,			so_id,					it_transaction,
			tis_note1,				tis_note2,				tis_function, tis_order , ct_transaction_original,
			tis_item_id_origin,
			tis_id_origin,tis_isParentAssociate,
			item_idfromPreInvoice

		)
			SELECT DISTINCT TOP(@intTop4Insert)
						@comp_id,				@guid,					0,

						--tit.item_id,
						-- MOS 04-2022: Si TIENE el remito de Fc anticipada EMITIDO, que ponga el ITEM_ID que corresponde.  si NO se emitió, que ponga x concepto como estaba hasta el momento de hacer esta modificacion.
						CASE
							--WHEN @df_PreInvoice_CreditNoteRestoreStockIfPLEmitted = 'True' THEN tit.item_id
							--  Si tiene item_id que lo ponga
							WHEN tit.item_id IS NOT NULL																						THEN tit.item_id
							--  Si es una Fc Anticipada y SI tiene emitido el remito, que haga x item_id4Preinvoice asi recompone el stock que ya salio x el remito.
							WHEN tit.item_id IS NULL AND tit.item_idfromPreInvoice IS NOT NULL AND vFA.it_transaction_packingList IS NOT NULL	THEN tit.item_idfromPreInvoice

							--  MOS 07-2022 Si es una Fc Anticipada y NO tiene emitido el remito, que haga x item_id4Preinvoice al deposito fantasma stor_id4SaleOrderpreInvoiceCreditNote del documento(que SOLO debe usarse para esto !!!).
							WHEN tit.item_id IS NULL AND tit.item_idfromPreInvoice IS NOT NULL AND vFA.it_transaction_packingList IS     NULL AND
								 tdf.stor_id4SaleOrderpreInvoiceCreditNote IS NOT NULL AND
								 tdf.sd_id = 1																									THEN tit.item_idfromPreInvoice

							ELSE tit.item_id	-- como estaba
						END,

						CASE
							WHEN  tit.item_id IS NULL THEN	titd.itm_desc
							else							ti.item_desc
						end,
						ti.item_detail,
						CASE
							WHEN  /*ISNULL(TB.bra_SaleOrder_PLProcInOrlCurr,'True')*/
								@bra_saleOrder_InvoiceFromPackingWithOriginalExchang = 'TRUE'	 THEN	ISNULL(tit.it_SalesCurrId4exchangeToBranchCurrency ,	tit.it_OriginalPriceCurrency)
							ELSE																	tit.curr_id
						END,
						--tit.curr_id,
						0,
						-- MOS 04-2022: Si TIENE el remito de Fc anticipada EMITIDO, que ponga el ITEM_ID que corresponde.  si NO se emitió, que ponga x concepto como estaba hasta el momento de hacer esta modificacion.
						-- Puede darse que un renglon de una factura se haga en 3 remitos diferentes.   al llamar para NC a la factura debe poner la qty y articulo que fue en cada remito de salida.
						CASE
							WHEN tit2.comp_id IS NOT NULL THEN tit2.it_qty
							ELSE tit.it_qty - ISNULL(tit.it_packingInvoiceQTYInvoiced,0)
						END,
						--tit.it_qty - ISNULL(tit.it_packingInvoiceQTYInvoiced,0),
						tit.prli_id,
						CASE
							WHEN  /*ISNULL(TB.bra_SaleOrder_PLProcInOrlCurr,'True')*/
								@bra_saleOrder_InvoiceFromPackingWithOriginalExchang = 'TRUE'	 THEN
								-- Busca el precio al tipo de cambio de la moneda original
								-- Se puso asi dado que hasta aqui, 11-2010, no se grababan los campos it_exchangeToBranchCurrency y it_SalesCurrId4exchangeToBranchCurrency
								dbo.fnGetExchange2(	@comp_id,
													tit.it_price,
													tit.curr_id,
													ISNULL(tit.it_SalesCurrId4exchangeToBranchCurrency ,	tit.it_OriginalPriceCurrency),
													CASE
														when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_OriginalPriceCurrency
														ELSE tit.it_SalesCurrId4exchangeToBranchCurrency
													END	,
													tit.curr_id,
													CASE
														when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_exchangeToOriginalPriceCurrency
														ELSE tit.it_exchangeToBranchCurrency
													END,
													'false')
								--tit.it_price / dbo.fnNoZDiv(tit.it_exchangeToOriginalPriceCurrency)
							ELSE
								--BEGIN
									CASE -- Solo si no convierte segun el tipo de cambio original...
										WHEN @df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms	= 'True'	THEN  tit.it_priceWithOutOthers
										WHEN @df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount				= 'True'	THEN  tit.it_priceWithOutOthers
										ELSE 																						  tit.it_price
									END
								--END
						END,
						CASE -- Solo si no convierte segun el tipo de cambio original...
							WHEN @df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms	= 'True'	THEN  tit.it_priceWithOutOthers
							WHEN @df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount				= 'True'	THEN  tit.it_priceWithOutOthers
							ELSE 																						  tit.it_price
						END, -- Se recalcula luego via tax_calculate
						CASE	--Busca el Tax Id
							WHEN tit.item_id IS NULL THEN
															case
																WHEN tn.tax_id IS NULL THEN @intTaxIdByDefault
																ELSE tn.tax_id
															end
							ELSE NULL
						END ,

						-- ---------
						-- Costo
						-- OJO
						-- ---------
						CASE
							WHEN  /*ISNULL(TB.bra_SaleOrder_PLProcInOrlCurr,'True')*/
								  @bra_saleOrder_InvoiceFromPackingWithOriginalExchang = 'TRUE'	 THEN -- Por Moneda Original

								CASE -- Busca el Costo
									WHEN IsNull(tb.bra_costlist_type,'False') = 'False' THEN --tit.it_priceOfCost
										dbo.fnGetExchange2(	@comp_id,
															tit.it_priceOfCost,
															tit.curr_id,
															ISNULL(tit.it_SalesCurrId4exchangeToBranchCurrency ,	tit.it_OriginalPriceCurrency),
															CASE
																when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_OriginalPriceCurrency
																ELSE tit.it_SalesCurrId4exchangeToBranchCurrency
															END	,
															tit.curr_id,
															CASE
																when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_exchangeToOriginalPriceCurrency
																ELSE tit.it_exchangeToBranchCurrency
															END,
															'false')

									ELSE --tit.it_priceOfCostPP

										dbo.fnGetExchange2(	@comp_id,
															tit.it_priceOfCostPP,
															tit.curr_id,
															ISNULL(tit.it_SalesCurrId4exchangeToBranchCurrency ,	tit.it_OriginalPriceCurrency),
															CASE
																when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_OriginalPriceCurrency
																ELSE tit.it_SalesCurrId4exchangeToBranchCurrency
															END	,
															tit.curr_id,
															CASE
																when tit.it_exchangeToBranchCurrency IS NULL THEN tit.it_exchangeToOriginalPriceCurrency
																ELSE tit.it_exchangeToBranchCurrency
															END,
															'false')


								END

							ELSE
								CASE -- Busca el Costo
									WHEN IsNull(tb.bra_costlist_type,'False') = 'False' THEN tit.it_priceOfCost
									ELSE tit.it_priceOfCostPP
								END
						END,
						-- ---------


						CASE	--Busca el Tax Id para el costo
							WHEN tit.item_id IS NULL THEN
															case
																WHEN tn.tax_id IS NULL THEN @intTaxIdByDefault
																ELSE tn.tax_id
															end
							ELSE NULL
						END ,
						CASE
							-- MOS: 07-2022: Si es Factura Anticipada y NO se emitio el remito y está definido el Deposito: stor_id4SaleOrderpreInvoiceCreditNote en el Documento del tipo Factura, el item lo pone a ese deposito ya que se hara la NC al mismo, el cual NO se toma en cuenta para stock!!!
							WHEN tit.item_id IS NULL AND tit.item_idfromPreInvoice IS NOT NULL AND vFA.it_transaction_packingList IS     NULL AND tdf.stor_id4SaleOrderpreInvoiceCreditNote IS NOT NULL AND tdf.sd_id = 1  THEN tdf.stor_id4SaleOrderpreInvoiceCreditNote
							WHEN @intStorId <> -1 THEN	@intStorId		-- Si el documento dice que debo traerlos en otro deposito, lo hago.!!!
							ELSE						ISNULL(tit.stor_id,tit2.stor_id)	-- Si es rm de fc anticipada, toma el deposito del remito en caso de estar disponible.
						END,
						NULL,
						tit.it_cd,
						tit.bra_id,				tit.it_soh_id,			tit.it_cd,
						NULL,					NULL,					'FALSE',


						-- Descuento por Item
						CASE
							WHEN @df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms = 'True'	THEN tit.it_Discount1
							WHEN @df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount				= 'True'	THEN tit.it_Discount1
							ELSE 0
						END,




						tit.it_CreditInt,		tit.it_CreditIntPlus,
						tit.it_itemDiscountTotal,	tit.it_totalDiscountTotal,	'false',
						'false',				'true',					GETDATE(),
						tit.it_isProduction, 	tit.so_id,				tit.it_transaction,
						tit.it_note1,			dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tit.ct_transaction)	[doc],
						case
							when @option = 1 then 1
							ELSE 2
						END,
						tit.it_order + @intOrder ,
						tct.ct_transaction,					-- Solo para poder saber si son todos del mismo ct_transaction
						tit.it_item_id_origin,
						CASE	-- MOS 01-2021 x NT
							WHEN @intNewTIS_Id IS NOT NULL AND @intNewTIS_Id > 0 AND tit.it_item_id_origin IS NOT NULL THEN @intNewTIS_Id
							ELSE NULL
						END,
						CASE	-- MOS 01-2021 x NT
							WHEN @intNewTIS_Id IS NOT NULL AND @intNewTIS_Id > 0 AND tit.it_item_id_origin IS NOT NULL AND tit.item_id IS NULL  THEN 1
							ELSE 0
						END,
						tit.item_idfromPreInvoice


					FROM	tbItemTransactions tit

							INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
								ON  tct.comp_id			= tit.comp_id
								AND tct.bra_id			= tit.bra_id
								AND tct.ct_transaction	= tit.ct_transaction

							INNER JOIN tbDocumentsFile		 AS tdf			WITH (NOLOCK)
								ON	tdf.comp_id			= tct.comp_id AND
									tdf.df_id			= tct.df_id

							inner JOIN tbBranch tb							WITH (NOLOCK)
								ON		TB.comp_id	= TIT.comp_id
									AND TB.bra_id	= TIT.bra_id

							left JOIN tbTaxMovements ttm					WITH (NOLOCK)
								ON	ttm.ct_transaction	= tct.ct_transaction
								AND ttm.bra_id			= tct.bra_id
								AND ttm.comp_id			= tct.comp_id
								AND ttm.it_transaction  = tit.it_transaction

			--				LEFT JOIN vwTaxMovements_IVAFirstTax vtmit
			--					ON		vtmit.comp_id = tit.comp_id
			--						and	vtmit.bra_id  = tit.bra_id
			--						AND vtmit.ct_transaction = tit.ct_transaction
			--						AND vtmit.it_transaction = tit.it_transaction

							left JOIN tbtaxname tn							WITH (NOLOCK) --Solo necesito saber el iva a que salio el item
								ON tn.comp_id = ttm.comp_id
								AND tn.tax_id = ttm.tax_id
								--AND		tn.tax_class					= 1


							left JOIN tbItem ti								WITH (NOLOCK)
								ON ti.comp_id	= tit.comp_id
								AND ti.item_id	= tit.item_id

							left JOIN tbItemTransactionDetails titd			WITH (NOLOCK)
								ON titd.comp_id = tit.comp_id
								AND titd.bra_id = tit.bra_id
								AND titd.ct_transaction = tit.ct_transaction
								AND titd.it_transaction = tit.it_transaction


							-- ---------------------------------------------------------------------------------------------------------
							-- MOS 04-2022: Si se hace NC de Fc Anticipada y NO se emitió el remito, trae los ITEMS. Sino hace la NC x CONCEPTO.
							-- ---------------------------------------------------------------------------------------------------------
							LEFT JOIN vwCommercialTransactions_preInvoice_PackingListRelation vFA		WITH (NOLOCK)
								ON	vFA.comp_id						= tit.comp_id			AND
									vFA.ct_transaction_preInvoice	= tit.ct_transaction	AND
									vFA.it_transaction_preInvoice	= tit.it_transaction	AND
									vFA.it_transaction_packingList IS NOT NULL				AND
									@df_PreInvoice_CreditNoteRestoreStockIfPLEmitted = 'True'
							LEFT JOIN tbItemTransactions								AS tit2			WITH (NOLOCK)
								ON	tit2.comp_id		= vFA.comp_id AND
									tit2.it_transaction = vFA.it_transaction_packingList
							-- ---------------------------------------------------------------------------------------------------------

					WHERE 	tit.comp_id						= @comp_id
					AND		tit.it_packingInvoiceSelected	= 'true'
					AND		tct.cust_id						= @cust_id
					AND		isnull(tn.tax_class,1)			= 1
					AND		NOT EXISTS (SELECT TOP 1  1
		   									FROM tbTempItemStock ttis		WITH (NOLOCK)
		   									WHERE ttis.it_transaction	= tit.it_transaction  AND
		   										  ttis.tis_guid			= @guid)

					ORDER BY tit.it_order + @intOrder



		-- MOS 04-2022: para que avise al que emite la NC que se va a emitir la NC recomponiendo stock.
		DECLARE  @bitHASPreInvoiceEmmitedPackingList AS BIT = 'False'
		IF EXISTS(
					SELECT TOP  1 1
						FROM tbTempItemStock tmp	WITH (NOLOCK)
						WHERE	tmp.tis_guid = @guid AND
								tmp.item_id IS NOT NULL AND
								tmp.item_idfromPreInvoice IS NOT NULL
				)
			BEGIN
				SET @bitHASPreInvoiceEmmitedPackingList = 'True'
			END








			-- -------------------------------------------------------------
			-- INserta Numeros de Serie del comprobante original si los tuviese.
			-- -------------------------------------------------------------
			INSERT INTO tbTempSaleOrderSerial
				(
					guid, is_id
				)
				(
					-- MOS
					SELECT @guid, tits.is_id
						FROM tbTempItemStock ttis						WITH (NOLOCK)
						INNER JOIN tbItemTransactionSerials tits		WITH (NOLOCK)
							ON		tits.comp_id		= @comp_id
								AND tits.it_transaction = ttis.it_transaction
						WHERE	ttis.tis_guid = @guid
							AND tits.is_id IS NOT NULL
							AND tits.is_id NOT IN (	SELECT is_id
														FROM tbTempSaleOrderSerial ttsos WITH (NOLOCK)
							                       		WHERE ttis.tis_guid = @guid)
							AND @option IN (3)
				)
			-- -------------------------------------------------------------



			-- -------------------------------------------------------------
			-- MOS 08-2022 INserta los que salieron por Remito de Fc Anticipada	**lwsdfnl&%$#wdfqw234
			-- -------------------------------------------------------------
			INSERT INTO tbTempSaleOrderSerial
				(
					guid, is_id
				)
				(
					-- MOS
					SELECT @guid, tits.is_id
						FROM tbTempItemStock ttis						WITH (NOLOCK)

						-- ---------------------------------------------------------------------------------------------------------
						-- MOS 08-2022: Si se hace NC de Fc Anticipada y NO se emitió el remito, trae los ITEMS. Sino hace la NC x CONCEPTO.
						-- ---------------------------------------------------------------------------------------------------------
						INNER JOIN vwCommercialTransactions_preInvoice_PackingListRelation vFA		WITH (NOLOCK)
							ON	vFA.comp_id						= ttis.comp_id			AND
								vFA.ct_transaction_preInvoice	= ttis.ct_transaction	AND
								vFA.it_transaction_preInvoice	= ttis.it_transaction	AND
								vFA.it_transaction_packingList IS NOT NULL				AND
								@df_PreInvoice_CreditNoteRestoreStockIfPLEmitted = 'True'
						INNER JOIN tbItemTransactions								AS tit2			WITH (NOLOCK)
							ON	tit2.comp_id		= vFA.comp_id AND
								tit2.it_transaction = vFA.it_transaction_packingList
						-- ---------------------------------------------------------------------------------------------------------
						INNER JOIN tbItemTransactionSerials tits		WITH (NOLOCK)
							ON		tits.comp_id		= @comp_id
								AND tits.it_transaction = tit2.it_transaction
						WHERE	ttis.tis_guid = @guid
							AND tits.is_id IS NOT NULL
							AND tits.is_id NOT IN (	SELECT is_id
														FROM tbTempSaleOrderSerial ttsos WITH (NOLOCK)
							                       		WHERE ttis.tis_guid = @guid)
							AND @option IN (3)
				)
			-- -------------------------------------------------------------









		DECLARE @bitSalesTermsDiscountInformed AS BIT = 'False'

		-- Si tengo MAS de un ct_transaction BORRO TODO ya que pueden NO  coincidir las cond de vta y descuentos de todos los items seleccionados
		IF @df_saleOrder_CreditNoteFromInvoiceWithOriginalPriceDiscountSalesTerms = 'True'
			BEGIN
				IF (
					 SELECT COUNT(DISTINCT ttis.ct_transaction_original )  --SELECT COUNT(*)
						FROM tbTempItemStock ttis	WITH (NOLOCK)
						WHERE	ttis.comp_id	= @comp_id AND
								ttis.tis_guid	= @guid
						--GROUP BY ttis.ct_transaction_original
					) > 1
					BEGIN
						DELETE FROM tbTempItemStock
							WHERE comp_id = @comp_id AND tis_guid = @guid
					END
				ELSE
					BEGIN
						DECLARE @ct_transaction_original AS INT = NULL
						SELECT @ct_transaction_original = ttis.ct_transaction_original
							FROM tbTempItemStock ttis	WITH (NOLOCK)
							WHERE	ttis.comp_id	= @comp_id AND
									ttis.tis_guid	= @guid
						IF @ct_transaction_original IS NULL
							BEGIN
								DELETE FROM tbTempItemStock
									WHERE comp_id = @comp_id AND tis_guid = @guid
							END
						ELSE
							BEGIN
								SET @bitSalesTermsDiscountInformed = 'True'
								SELECT	tct.st_id,
										tct.disc_id,
										ISNULL(tct.ccp_id,-1)	[ccp_id],
										0						[pendingItems],	-- MOS 04-2022 para que no explote el truy de la clase
										@bitHASPreInvoiceEmmitedPackingList [bitHASPreInvoiceEmmitedPackingList]
									FROM tbCommercialTransactions tct		WITH (NOLOCK)
									WHERE	tct.comp_id			= @comp_id AND
											tct.ct_transaction	= @ct_transaction_original
							END

					END
			END


			-- -----------------------------------------------------------------------------------------------------<
			-- Verifica si quedaron items NO ingresados por no entrar en la totalidad de items maxima del documento.
			-- -----------------------------------------------------------------------------------------------------<
			DECLARE @bitItemsNotInserted AS INT = 0
			SELECT  @bitItemsNotInserted = COUNT(*)
				FROM	tbItemTransactions tit							WITH (NOLOCK)

				INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
					ON  tct.comp_id			= tit.comp_id
					AND tct.bra_id			= tit.bra_id
					AND tct.ct_transaction	= tit.ct_transaction

				left JOIN tbTaxMovements ttm					WITH (NOLOCK)
					ON	ttm.ct_transaction	= tct.ct_transaction
					AND ttm.bra_id			= tct.bra_id
					AND ttm.comp_id			= tct.comp_id
					AND ttm.it_transaction  = tit.it_transaction

				left JOIN tbtaxname tn							WITH (NOLOCK) --Solo necesito saber el iva a que salio el item
					ON tn.comp_id = ttm.comp_id
					AND tn.tax_id = ttm.tax_id

				left JOIN tbItem ti								WITH (NOLOCK)
					ON ti.comp_id	= tit.comp_id
					AND ti.item_id	= tit.item_id

				left JOIN tbItemTransactionDetails titd			WITH (NOLOCK)
					ON titd.comp_id = tit.comp_id
					AND titd.bra_id = tit.bra_id
					AND titd.ct_transaction = tit.ct_transaction
					AND titd.it_transaction = tit.it_transaction

				inner JOIN tbBranch tb							WITH (NOLOCK)
					ON		TB.comp_id	= TIT.comp_id
						AND TB.bra_id	= TIT.bra_id


				WHERE 	tit.comp_id						= @comp_id
				AND		tit.it_packingInvoiceSelected	= 'true'
				AND		tct.cust_id						= @cust_id
				AND		isnull(tn.tax_class,1)			= 1
				AND		NOT EXISTS (SELECT TOP 1 1
		   								FROM tbTempItemStock ttis		WITH (NOLOCK)
		   								WHERE	ttis.it_transaction = tit.it_transaction AND
		   										ttis.tis_guid		= @guid)

			-- -----------------------------------------------------------------------------------------------------<





			IF @bitSalesTermsDiscountInformed = 'False'
				BEGIN
					SELECT	-1		[st_id],
							-1		[disc_id],
							-1		[ccp_id],
							@bitItemsNotInserted [pendingItems],
							@bitHASPreInvoiceEmmitedPackingList [bitHASPreInvoiceEmmitedPackingList]
				END



		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH



END


GO


-- Esto solo sirve para traer como detalle las FActuras que se incluyen en el remito.  Solo como descripcion.
-- Se usa para remitir facturas con un solo remito.
CREATE  PROCEDURE [dbo].[spTempItemStock_insertData_From_Remito]
(
		@comp_id		INT,
		@lang_id		INT,
		@cust_id		INT,
		@guid			UNIQUEIDENTIFIER,
		@df_id		AS  INT
--		@option			INT
)
AS




BEGIN

/*
-- -----------------------------------------------------------------
-- Testing
-- -----------------------------------------------------------------

	DECLARE		@comp_id		INT,
				@cust_id		INT,
				@guid			UNIQUEIDENTIFIER,
				@option			INT

	SELECT 		@comp_id		= 1,
				@cust_id		= 24300,
				@guid			= 'A75BBDBF-95CA-45D6-87BA-08399482DF15',
				@option			= 903
*/
-- -----------------------------------------------------------------

--SELECT 1 / 0
	BEGIN TRANSACTION
	BEGIN TRY


		-- ------------------------------------
		-- Bloquear la base antes de hacer nada
		-- ------------------------------------
		DECLARE @intLock AS INT
		SELECT	@intLock = tce.sb_id
			FROM tbsysBlockPage4IsoTran  tce
		-- ------------------------------------



		-- Obtiene el Orden de Insercion
		DECLARE @intOrder AS INT
		SELECT	@intOrder = MAX(IsNull(ttis.tis_order,0)) + 100
			FROM tbTempItemStock ttis	WITH (NOLOCK)
				WHERE ttis.tis_guid = @guid



		INSERT INTO tbTempItemStock
		(
			comp_id,				tis_guid,				tis_priority,
			item_id,				tis_itemDesc,			tis_detail,
			curr_id,
			tis_initQty,			tis_qty,
			prli_id,
			tis_price,
			tis_priceInBranchCurrency,
			tax_id,					tis_cost,				tis_costTax,
			stor_id,				doc_id,					tis_CD,
			bra_id,					soh_id,					tis_insertDate,
			[user_id],				aure_id,				aure_itemComposed,
			tis_itemDiscount,		tis_CreditInt,			tis_CreditIntPlus,
			tis_itemDiscountTotal,	tis_totalDiscountTOTAL,	tis_isQuotation,
			tis_isCredit,			tis_IsEditing,			tis_IsEditingCd,
			tis_production,			so_id,					it_transaction,
			tis_note1,
			tis_note2,				tis_function,
			tis_PackagesQty, tis_order,
			ct_transaction_SelectFromPacking
		)

			SELECT
			@comp_id,				@guid,					0,
			null,
			CASE
				WHEN tit.comp_id IS NULL		THEN dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct2.[ct_transaction])
				WHEN tit.comp_id IS NOT NULL	THEN IsNull(NULL,isnull(tidc.id4c_desc, isnull(titd.itm_desc,item.item_desc)))
				ELSE '**'
			END,
			' ',
			tct2.curr_id_transaction,
			0,
			CASE
				WHEN tit.comp_id IS NULL		THEN 1
				WHEN tit.comp_id IS NOT NULL	THEN tit.it_qty
				ELSE 1
			END,
			--1,
			null,
			CASE
				WHEN tit.comp_id IS NULL THEN  dbo.fnGetExchange2 (@comp_id,
																	tct2.ct_ABalance,
																	tct2.ct_ACurrency,
																	tct2.curr_id_transaction,
																	tct2.curr_id4Exchange,
																	tct2.curr_id_transaction,
																	tct2.curr_id4Exchange,
																	'false')
				ELSE							dbo.fnGetExchange2 (@comp_id,					-- x SONNOS, tal vez haya que agregar descuentos u otros para otro enfermo !
																	/*tit.it_qty **/ tit.it_price,
																	tit.curr_id,
																	tct2.curr_id_transaction,
																	tct2.curr_id4Exchange,
																	tct2.curr_id_transaction,
																	tct2.curr_id4Exchange,
																	'false')


			END,
			0,
			NULL, 			0,						null,
			null,			NULL,					tct2.ct_date,
			tct2.bra_id,		NULL,				tct2.ct_date,
			NULL,			NULL,					'FALSE',
			0,				0,		0,
			0,	0,
			'false',
			'false',		'true',					GETDATE(),
			null, 			null,					NULL,
			CASE
				WHEN tit.comp_id IS NOT NULL THEN dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct2.[ct_transaction])
				ELSE NULL
			END,
			CASE
				WHEN tit.comp_id IS NOT NULL THEN item.item_code
				ELSE NULL
			END,
			--null,
			NULL,
			tct2.ct_packagesQty,@intOrder,
			tct2.ct_transaction

			FROM  tbCommercialTransactions tct2			WITH (NOLOCK)

			INNER JOIN tbDocumentsFile		tdf			WITH (NOLOCK)
				ON	tdf.comp_id = @comp_id AND
					tdf.df_id	= @df_id

			INNER JOIN tbBranch tb						WITH (NOLOCK)
				ON	TB.comp_id	= tct2.comp_id
				AND TB.bra_id	= tct2.bra_id

			LEFT JOIN tbItemTransactions		tit			WITH (NOLOCK)
				ON	tit.comp_id					= tct2.comp_id				AND
					tit.ct_transaction			= tct2.ct_transaction		AND
					CASE
						WHEN tdf.df_SaleOrder_insertData_From_Remito_WItems = 1 THEN 1
						ELSE 0
					END = 1
			LEFT JOIN tbItemTransactionDetails titd
				ON	titd.comp_id				= tit.comp_id AND
					titd.it_transaction			= tit.it_transaction

			LEFT JOIN tbItemDescription4Customer tidc
				ON		tidc.comp_id = tit.comp_id
					AND tidc.cust_id = tct2.cust_id
					AND tidc.item_id = tit.item_id

			left join dbo.tbItem							ITEM
				on  item.comp_id			=	tit.comp_id
				AND item.item_id			=	tit.item_id

			WHERE 	tct2.comp_id				= @comp_id
			AND		tct2.cust_id				= @cust_id
			AND		tct2.ct_isSelected			= 'true'
			ORDER BY tct2.ct_transaction,tit.it_order







	COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH

	--SELECT * FROM   tbTempItemStock


END
GO





CREATE PROCEDURE [dbo].[spTempItemStock_insertDataTransactional]
(
	@comp_id			INT,
	@tis_guid			UNIQUEIDENTIFIER,
	@tis_priority		DECIMAL(14,4),
	@item_id			INT,
	@tis_itemDesc		VARCHAR(100),
	@tis_detail			VARCHAR(100),
	@curr_id			INT,
	@tis_initQty		DECIMAL(19,5),
	@tis_qty			DECIMAL(19,5),
	@prli_id			INT,
	@tis_price			DECIMAL(19,6),
	@stor_id			INT,
	@doc_id				INT,
	@bra_id				INT,
	@user_id			INT,
	@insertDate			DATETIME,
	@lastUpdate			DATETIME,
	@tis_cost			DECIMAL(19,5),
	@tis_costTax		INT,
	@soh_id				INT,
	@sod_id				INT,
	@to_associate		BIT,
	@return_value		INT OUTPUT,
	@ret_ErrorCode			INT OUTPUT,
	@ret_ErrorDescription	VARCHAR(200) OUTPUT
)
AS
SET NOCOUNT ON

	SET @return_value			= 0
	SET @ret_ErrorCode			= 0
	SET @ret_ErrorDescription	= ''



/*
DECLARE	@comp_id		int,
		@tis_guid		uniqueidentifier,
		@tis_priority	decimal(14,4),
		@item_id		int,
		@tis_itemDesc	varchar(100),
		@tis_detail		varchar(100),
		@curr_id		int,
		@tis_initQty	decimal(19,5),
		@tis_qty		decimal(19,5),
		@prli_id		int,
		@tis_price		decimal(19,6),
		@stor_id		int,
		@doc_id			int,
		@bra_id			int,
		@user_id		int,
		@insertDate		datetime,
		@lastUpdate		datetime,
		@tis_cost		decimal(19,5),
		@tis_costTax	int,
		@soh_id			int,
		@sod_id			INT,
		@to_associate	BIT,
		@return_value   int

SELECT	@comp_id		= 1,
		@tis_guid		= '8D5AA877-3676-4713-B5BA-D2D842317DE5',
		@tis_priority	= 112,
		@item_id		= 223,
		@tis_itemDesc	= 'Chevrolet Spark  *------------------------------------------------------------------------*',
		@tis_detail		= 'Detalle',
		@curr_id		= 1,
		@tis_initQty	= 1,
		@tis_qty		= 1,
		@prli_id		= 1,
		@tis_price		= 95,
		@stor_id		= 4,
		@doc_id			= 2,
		@bra_id			= 1,
		@user_id		= 1,
		@insertDate		= 2010-04-15,
		@lastUpdate		= 2010-04-15,
		@tis_cost		= 0,
		@tis_costTax	= 0,
		@soh_id			= null,
		@sod_id			= null,
		@to_associate	= 'true'
*/


BEGIN TRY


	DECLARE @wsID AS UNIQUEIDENTIFIER
	SET		@wsID = NEWID()

	EXEC spTempItemStock_insertData
		@comp_id,
		@tis_guid,
		@tis_priority,
		@item_id,
		@tis_itemDesc,
		@tis_detail,
		@curr_id,
		@tis_initQty,
		@tis_qty,
		@prli_id,
		@tis_price,
		@stor_id,
		@doc_id,
		@bra_id,
		@user_id,
		@insertDate,
		@lastUpdate,
		@tis_cost,
		@tis_costTax,
		@soh_id,
		@sod_id,
		@to_associate,
		null,
		'False',
		@wsID ,'',
		-1 ,
		@return_value


END TRY
BEGIN CATCH
	Set @ret_ErrorCode			= -1
	Set	@ret_ErrorDescription	= '1 - ' + ERROR_MESSAGE()
	RETURN
END CATCH
GO



