CREATE  PROCEDURE [dbo].[spTempItemStock_setNewTotal]
(
		@comp_id			INT,
		@bra_id				INT,
		@tis_guid			UNIQUEIDENTIFIER,
		@decActualTotal				AS FLOAT /*DECIMAL(38,10)*/,	-- MOS 11-2021 para mas presicion.
		@decTotalOrPercentaje		AS FLOAT /*DECIMAL(38,10)*/,
		@option				INT
)
AS


BEGIN


	-- --------------------------------------------------
	-- Testing
	-- --------------------------------------------------
	/*
	DECLARE
			@comp_id			INT,
			@bra_id				INT,
			@tis_guid			UNIQUEIDENTIFIER,
			@decActualTotal				DECIMAL(19,5),
			@decTotalOrPercentaje				DECIMAL(19,5),
			@option				INT

	SELECT
			@comp_id			= 1,
			@bra_id				= 1,
			@tis_guid			='0C0A16B6-8333-4FAF-857A-A3AE3C813C55',
			@decActualTotal				= 10,
			@decTotalOrPercentaje				=100,
			@option				= 2
	*/
	-- --------------------------------------------------


	DECLARE @coslis_id			INT,
			@bra_costList_type	INT

	-- -------------------------------------------------
	IF @option = 1				-- Llevar a Importe
	-- -------------------------------------------------
		BEGIN

			DECLARE @intDecimals AS INT
			SET		@intDecimals = 10  -- 8     5   MOS 11-2021, lo puse en 10
			SELECT	@intDecimals = tdf.df_PriceDecimalPlaces
				FROM tbTempItemStock ttis			WITH (NOLOCK)
				INNER JOIN tbDocumentsFile tdf		WITH (NOLOCK)
					ON	tdf.comp_id		= ttis.comp_id	AND
						tdf.df_id		= ttis.df_id
				WHERE	ttis.comp_id	= @comp_id		AND
						ttis.tis_guid	= @tis_guid		AND
						tdf.df_Fiscal_IsFiscalPrinter = 'True'


			IF @decActualTotal = 0 SET @decActualTotal = @decTotalOrPercentaje

			UPDATE dbo.tbTempItemStock	WITH (ROWLOCK)
				SET		tis_price = tis_price * @decTotalOrPercentaje / @decActualTotal   -- @decTotalOrPercentaje / @decActualTotal  Se puso que redondee luego del calculo !!!  11/2018
				WHERE comp_id	= @comp_id
				AND tis_guid	= @tis_guid
			--UPDATE dbo.tbTempItemStock	WITH (ROWLOCK)
			--	SET		tis_price = round(tis_price * @decTotalOrPercentaje / dbo.fnNoZDiv(@decActualTotal) ,@intDecimals)   -- @decTotalOrPercentaje / @decActualTotal  Se puso que redondee luego del calculo !!!  11/2018
			--	WHERE comp_id	= @comp_id
			--	AND tis_guid	= @tis_guid
			-- Si alguien dice que no ajusta exactamente, que no sea FORRO ya que aca pone los decimales exactos
			-- pero al redondear en la factura es cuando no Da.!
			-- Esto suele pasar cuando las cantidades son mayores a Uno en mucho y los precios son muy bajos o con decimales.

		END
	-- -------------------------------------------------
	ELSE IF @option=2			-- MarkUp
	-- -------------------------------------------------
		BEGIN



			SELECT	@coslis_id			= tb.coslis_id,
					@bra_costList_type	= tb.bra_costlist_type

				FROM	tbBranch tb			WITH (NOLOCK)
				WHERE	tb.comp_id	= @comp_id
				AND		tb.bra_id	= @bra_id


			UPDATE	tbTempItemStock		WITH (ROWLOCK)
			SET		tis_price	=	CASE
										WHEN @bra_costList_type = 1 THEN	ticl.coslis_price_aw	* (1+ (convert(decimal(19,6),@decTotalOrPercentaje)/100))
										ELSE								ticl.coslis_price	    * (1+ (convert(decimal(19,6),@decTotalOrPercentaje)/100))
	   		         				END,
	   		        curr_id		= ticl.curr_id
				FROM	tbTempItemStock				ttis
						INNER JOIN tbItemCostList	ticl			WITH (NOLOCK)
						ON ticl.comp_id		= ttis.comp_id
						AND ticl.coslis_id	= @coslis_id
						AND ticl.item_id	= ttis.item_id
				WHERE	ttis.comp_id	= @comp_id
				AND		ttis.tis_guid	= @tis_guid

		END
	-- -------------------------------------------------
	ELSE IF @option=3			-- Profit
	-- -------------------------------------------------
		BEGIN



			SELECT	@coslis_id			= tb.coslis_id,
					@bra_costList_type	= tb.bra_costlist_type
				FROM	tbBranch tb		WITH (NOLOCK)
				WHERE	tb.comp_id	= @comp_id
				AND		tb.bra_id	= @bra_id


			UPDATE	tbTempItemStock				WITH (ROWLOCK)
				SET		tis_price	=	CASE
											WHEN	@bra_costList_type = 1 THEN	ticl.coslis_price_aw	/ dbo.fnNoZDiv( 1- (@decTotalOrPercentaje/100) )
											ELSE								ticl.coslis_price	    / dbo.fnNoZDiv( 1- (@decTotalOrPercentaje/100) )
	   		         					END,
	   		         	curr_id		= ticl.curr_id
				FROM	tbTempItemStock				ttis			--WITH (NOLOCK)
						INNER JOIN tbItemCostList	ticl			WITH (NOLOCK)
						ON ticl.comp_id		= ttis.comp_id
						AND ticl.coslis_id	= @coslis_id
						AND ticl.item_id	= ttis.item_id
				WHERE	ttis.comp_id	= @comp_id
				AND		ttis.tis_guid	= @tis_guid

		END



END
GO





-- =============================================
-- Author:		MOS
-- Create date: 11-2014
-- Description:
-- =============================================
create PROCEDURE [dbo].[spTempItemStock_updateAddData]
	@comp_id	AS INT,
	@guid		AS UNIQUEIDENTIFIER,
	@datFirstPay AS DATETIME,
	@intDayOfMonth AS INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	BEGIN TRY

		-- Estos dos valores son iguales para toda la operacion.
		UPDATE tbTempItemStock
			SET
				tis_loanDateOfFirstPay			= @datFirstPay,
				tis_loanDayOfMonthOfNextPays	= @intDayOfMonth
			WHERE	comp_id		= @comp_id	AND
					tis_guid	= @guid

	END TRY
	BEGIN CATCH
	END CATCH


END
GO






