CREATE PROCEDURE [dbo].[spTempItemStock_UpdateAdditionalData]

(		@comp_id				INT,
		@tis_note1				VARCHAR(100),
		@tis_note2				VARCHAR(100),
		@tis_itemDiscount		DECIMAL(19,4),
		@tis_id					INT,
		@tisExclude4AvailableStock	BIT,
		@tisPending4pod_IdRelation  BIT,
		@tis_itemDiscount2		DECIMAL(19,4)
)
AS

BEGIN


	-- ------------------------------------------------------
	-- Test
	-- ------------------------------------------------------
	/*
	DECLARE    @comp_id				INT,
			@tis_note1				VARCHAR(100),
			@tis_note2				VARCHAR(100),
			@tis_itemDiscountTotal	DECIMAL(19,4),
			@tis_id					int
		SELECT  @comp_id				=1,
			@tis_note1				='XSXSA',
			@tis_note2				='AXZQSQ',
			@tis_itemDiscountTotal	= 10,
			@tis_id					= 532
	*/
	-- ------------------------------------------------------



		DECLARE @soh_bra_id AS INT
		DECLARE @soh_id AS INT
		DECLARE @sod_id AS INT


		SELECT	@soh_bra_id = tmp.bra_id,
				@soh_id		= tmp.soh_id,
				@sod_id		= tmp.sod_id
			FROM tbTempItemStock tmp	WITH (NOLOCK)
			WHERE	tmp.comp_id = @comp_id AND
					tmp.tis_id	= @tis_id


		-- Si se puso que Quede PENDIENTE a relacionar y YA esta relacionado, lo pone en False
		IF @tisPending4pod_IdRelation = 'True'
			BEGIN
				DECLARE		@bitHasRelation		AS BIT	= 'False'
				DECLARE		@posor_POReceived	AS BIT	= 'False'
				SELECT		@posor_POReceived			= ISNULL(posor_POReceived,'False'),
							@bitHasRelation				= 'True'
					FROM tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor WITH (NOLOCK)
					WHERE	tsohpor.comp_id		= @comp_id		AND
							tsohpor.so_bra_id	= @soh_bra_id	AND
							tsohpor.so_soh_id	= @soh_id		AND
							tsohpor.so_sod_id	= @sod_id

				IF @bitHasRelation = 'True'	-- MOS 28-09-2021: Si NO tiene relacion NO debe modificar nada !!!
					BEGIN
						IF @posor_POReceived = 'False'
							BEGIN
								SET @tisPending4pod_IdRelation = 'False'
								SET @tisExclude4AvailableStock = 'True'
							END
						ELSE
							BEGIN
								SET @tisPending4pod_IdRelation = 'False'
								SET @tisExclude4AvailableStock = 'False'
							END
					END
			END



		UPDATE dbo.tbTempItemStock	WITH (rowlock)
		SET
			tis_note1					= @tis_note1,
			tis_note2					= @tis_note2,
			tis_itemDiscount			= @tis_itemDiscount,
			tis_exclude4AvailableStock	= @tisExclude4AvailableStock,
			tis_pending4pod_IdRelation	= @tisPending4pod_IdRelation,
			tis_itemDiscount2			= @tis_itemDiscount2
			WHERE	comp_id		= @comp_id
			AND		tis_id		= @tis_id

	--SELECT * FROM tbTempItemStock ttis




END
GO






-- --------------------------------------------------
-- MOH,MOS
-- Actualiza datos en tempItemStock cuando se divide
-- un item de pedidos
-- --------------------------------------------------


CREATE  PROCEDURE [dbo].[spTempItemStock_updateData]
(

		@tis_id			int,
		@tis_priority	decimal(14,4),
		@item_id		int,
		@tis_itemDesc	varchar(500),
		@tis_detail		varchar(100),
		@curr_id		int,
		@tis_qty		decimal(19,5),
		@prli_id		int,
		@tis_price		decimal(19,6),
		@tis_cost		decimal(19,6),
		@tis_costTax    int,
		@stor_id		int,
		@bra_id			int,
		@doc_id			int,
		@user_id		int,
		@comp_id		INT,
		@tis_isMade		BIT
)

as


BEGIN



	-- -------------------------------------------------------------------------------
	-- Si @bitSaleOrderBlockItemsWithNOPotentialStock = TRUE entonces solo si el item
	-- no tiene ni composicion ni asociacion verifica que tenga SI o SI stock
	-- de no tener bloquea el alta.-
	-- -------------------------------------------------------------------------------
--	DECLARE @bitSaleOrderBlockItemsWithNOPotentialStock AS BIT
--
--	SELECT
--			@bitSaleOrderBlockItemsWithNOPotentialStock	= ISNULL(tb.bra_SaleOrderBlockItemsWithNOPotentialStock,'false')
--			FROM tbBranch tb
--			WHERE tb.bra_id = @bra_id
--
--	IF @bitSaleOrderBlockItemsWithNOPotentialStock = 'True' AND @item_id IS NOT NULL
--		BEGIN
--			DECLARE @intDF_Id AS INT
--			SET @intDF_Id = @doc_id
--			-- si el documento es factura o remito y lo que queda de potencial es menor que la cantidad solicitada, retorna error y no graba nada.-
--			IF dbo.fnGetAStock(@comp_id,@stor_id,@item_id,@tis_priority) < @tis_qty AND ( (SELECT sd_id FROM tbDocumentsFile tdf WHERE tdf.comp_id = @comp_id AND tdf.df_id = @intDF_Id) IN (1,2))
--				BEGIN
--					set	@return_value = -1
--					RETURN
--				END
--		END
	-- -------------------------------------------------------------------------------


	-- -------------------------------------------------------------------------------
	-- Si es una FACTURA de un Remito Pendiente NO permite modificar la cantidad del item
	-- -------------------------------------------------------------------------------
	DECLARE @intDF_Id AS INT
	SET @intDF_Id = @doc_id
	DECLARE @sd_id AS INT = -1
	SELECT @sd_id = tdf.sd_id
		FROM tbDocumentsFile tdf		WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id	AND
				tdf.df_id	= @intDF_Id
	IF @sd_id = 1
		BEGIN
			IF EXISTS(
						SELECT TOP 1  1
							FROM tbTempItemStock ttis	WITH (NOLOCK)
							WHERE	ttis.comp_id	= @comp_id	AND
									ttis.tis_id		= @tis_id	AND
									ttis.tis_qty		<> @tis_qty AND
									ttis.it_transaction IS NOT NULL
					)
			BEGIN
				DECLARE @strError NVARCHAR(2000) = ''
				DECLARE @lang_id AS INT = 2
				SELECT @lang_id = lang_id
					FROM tbCompany tc		WITH (NOLOCK)
					WHERE tc.comp_id = @comp_id

				SELECT @strError = tut.utexts_desc
					FROM tbsysUniqueTexts tut WITH (NOLOCK)
					WHERE	tut.lang_id		= @lang_id AND
							tut.utexts_id	= 729
				RAISERROR (15600,-1,-1, @strError ) --'¦ ATENCIÓN:No se puede modificar la cantidad de un Remito Pendiente de Facturar');
				RETURN -1
			END
		END
	-- -------------------------------------------------------------------------------







	DECLARE @decPrevQTY AS DECIMAL(19,4)

	SELECT		@decPrevQTY = ttis.tis_qty
		FROM	tbTempItemStock ttis		WITH (NOLOCK)
		WHERE	ttis.comp_id	= @comp_id AND
				ttis.tis_id		= @tis_id





	update	dbo.tbTempItemStock		WITH (ROWLOCK)
		set		tis_priority	= @tis_priority,
				item_id			= @item_id,
				tis_itemDesc	= @tis_itemDesc ,
				tis_detail		= @tis_detail,
				curr_id			= @curr_id,
				tis_qty			= @tis_qty,
				prli_id			= @prli_id,
				tis_price		= @tis_price,
				tis_cost		= @tis_cost,
				tis_costTax     = @tis_costTax,
				stor_id			= @stor_id,
				bra_id			= @bra_id,
				doc_id			= @doc_id,
				user_id			= @user_id,
				tis_isMade		= @tis_isMade,
				tis_MercadoLibre_MustUpdateStock = 'True'

		where	tis_id			= @tis_id
			and comp_id			= @comp_id



	IF @decPrevQTY < @tis_qty
		BEGIN
			DELETE FROM tbAssembly_Turns4Assembly	WITH (ROWLOCK)
				WHERE	comp_id = @comp_id AND
						tis_id	= @tis_id
		END

	-- Para que se dispare el trigger y se recalcule este campo.
	UPDATE tbAssembly_Turns4Assembly		WITH (ROWLOCK)
		SET		ta_preAssignedIndex =	CASE
											WHEN	ta_assignedIndex > 0								THEN	ta_assignedIndex
											WHEN	ta_assignedIndex = 0 AND ta_preAssignedIndex > 0	THEN	ta_preAssignedIndex
											ELSE																ta_assignedIndex
										END,
				ta_assignedIndex	= 0
		WHERE	comp_id = @comp_id AND
				tis_id	= @tis_id


END
GO



CREATE PROCEDURE [dbo].[spTempItemStock_UpdateData4PCConfig]
(
	@comp_id	INT,
	@tis_id		INT,
	@guid		UNIQUEIDENTIFIER,
	@control_id	INT,
	@df_id		INT
)
AS

BEGIN


	SET NOCOUNT ON


	DECLARE @df_pcConfigMode						AS INT
	DECLARE @df_pcConfigMode_item_ID4ComposedItem	AS INT
	SELECT  @df_pcConfigMode						= tdf.df_pcConfigMode,
			@df_pcConfigMode_item_ID4ComposedItem	=  tdf.df_pcConfigMode_item_ID4ComposedItem
		FROM tbDocumentsFile tdf	WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @df_id



	UPDATE tbTempItemStock		WITH (ROWLOCK)
	SET
		sod_isFromPCConfigCTRLId	= @control_id,
		tis_order					= CASE
		         					      WHEN	@control_id = 99 THEN 0
		         					      ELSE	tis_order
		         					  END,
		tis_disablePrintInEmmition =  CASE
		                                  WHEN @df_pcConfigMode						 = 3 AND
											   @df_pcConfigMode_item_ID4ComposedItem <> item_id THEN 1
		                                  ELSE							 0
		                              END
	WHERE	comp_id		= @comp_id	AND
			tis_id		= @tis_id	AND
			tis_guid	= @guid

	--IF @control_id = 99
	--	BEGIN
	--		UPDATE tbTempItemStock
	--		SET
	--			tis_order = 0
	--		WHERE	comp_id		= @comp_id	AND
	--				tis_id		= @tis_id	AND
	--				tis_guid	= @guid
	--	END

END

GO






