CREATE PROCEDURE [dbo].[spTempItemStock_UpdateItemExtendedWarranty]
(
	@comp_id					INT,
	@tis_id						INT,
	@guid						UNIQUEIDENTIFIER,
	@item_id_EW					INT,
	@tis_loanNumberOfPays		INT,
	@sdlmt_id					INT,
	@stor_id					INT,
	@sreas_id					INT,
	@EWAddress					NVARCHAR(250),
	@MPFromDate					DATETIME,
	@MPToDate					DATETIME,
	@pApplyType2AllItems		BIT
)

AS

BEGIN

	SET NOCOUNT ON

	DECLARE
		@lItem_Id	INT

	--IF @item_id_EW = -1
	--	SET	@lItem_Id = NULL

	IF @item_id_EW = -1
		SET	@item_id_EW = NULL


	IF @sdlmt_id = -1
		SET @sdlmt_id = 0



	UPDATE tbTempItemStock	WITH (ROWLOCK)
		SET
			item_id_EW						=	CASE
													WHEN @item_id_EW = -1				THEN	item_id_EW
													WHEN @item_id_EW = -2				THEN	NULL
													ELSE										@item_id_EW
												END ,
			tis_loanNumberOfPays			=	CASE
													WHEN @tis_loanNumberOfPays = -1		THEN	tis_loanNumberOfPays
													ELSE										@tis_loanNumberOfPays
												END,
			sdlmt_id						=	CASE
													WHEN @sdlmt_id = -1					THEN	sdlmt_id
													WHEN @sdlmt_id = -2					THEN	NULL
													ELSE										@sdlmt_id
												END,
			stor_id							=	CASE
													WHEN @stor_id = -1					THEN	stor_id
													ELSE										@stor_id
												END,
			sreas_id						=	CASE
													WHEN @sreas_id = -1					THEN	sreas_id
													WHEN @sreas_id = -2					THEN	NULL
													ELSE										@sreas_id
												END,
			sod_EWAddress					=	@EWAddress,
			sod_montlyPaymentFrom			= dbo.fnGetEnd_or_BeginOfDate( @MPFromDate,'False'),
			sod_montlyPaymentTo				= dbo.fnGetEnd_or_BeginOfDate( @MPToDate  ,'True')
		WHERE	comp_id		= @comp_id	AND
				tis_id		= @tis_id	AND
				tis_guid	= @guid



	-- MOS 04-2022: Si dice que ponga a TODOS los items, lo reemplaza en TODOS
	IF @pApplyType2AllItems = 'True'
		BEGIN
			UPDATE tbTempItemStock	WITH (ROWLOCK)
				SET

					sdlmt_id						=	CASE
															WHEN @sdlmt_id = -1					THEN	sdlmt_id
															WHEN @sdlmt_id = -2					THEN	NULL
															ELSE										@sdlmt_id
														END
				WHERE	comp_id		= @comp_id	AND
						tis_guid	= @guid
		END



	---- Estos dos valores son iguales para toda la operacion.
	--UPDATE tbTempItemStock
	--	SET
	--		tis_loanDateOfFirstPay			= @loanDateOfFirstPay,
	--		tis_loanDayOfMonthOfNextPays	= @loanDayOfMonthOfNextPays
	--	WHERE	comp_id		= @comp_id	AND
	--			tis_guid	= @guid


END
GO


