-- --------------------------------------------------
-- MOZ 10-2011
--	10-2011
-- --------------------------------------------------

CREATE  PROCEDURE [dbo].[spTempItemStock_updatePriority]
(
		@comp_id			as int,
		@tis_guid			as uniqueidentifier
		--@stor_id			as int
)

as

/*
DECLARE
		@comp_id			as int,
		@tis_guid			as uniqueidentifier,
		@stor_id			as INT

SELECT
		@comp_id			=1,
		@tis_guid			='9C9EF5E0-72D0-4DC6-9DDE-40D6FFBFCEC9',
		@stor_id			=1

*/

	Declare @counter_id				INT
	DECLARE @stor_id				INT

		Set		@counter_id			=  1

		select @stor_id = stor_id

		From tbTempItemStock		WITH (NOLOCK)
		Where	comp_id				= @comp_id
			and	tis_guid			= @tis_guid

			Declare cursor_TIS_uS
				Cursor LOCAL FAST_FORWARD  For
					Select	tis_priority

						From tbTempItemStock
						Where	comp_id				= @comp_id
							and	tis_guid			= @tis_guid
						Order By tis_priority


			Open cursor_TIS_uS
			Declare @tis_priority as int

			Fetch Next from cursor_TIS_uS
			While @@fetch_status <> -1
				Begin

					Set @tis_priority = 0
					exec dbo.spCounters_getNextValue	@comp_id,
														@stor_id,
														@counter_id,
														@tis_priority output

					Update dbo.tbTempItemStock
						Set tis_priority			= @tis_priority
						Where	comp_id = @comp_id
							and	tis_guid = @tis_guid

					Fetch Next from cursor_TIS_uS

				End
			Close		cursor_TIS_uS
			Deallocate	cursor_TIS_uS

GO








