-- --------------------------------------------------
-- MOS 05-2008
--	10-2008
-- --------------------------------------------------

CREATE  PROCEDURE [dbo].[spTempItemStock_updateStates]
(
		@comp_id			as int,
		@tis_guid			as uniqueidentifier,
		@tis_isQuotation	as bit,
		@tis_isCredit		as bit,
		@stor_id			as int
)

as

/*
DECLARE
		@comp_id			as int,
		@tis_guid			as uniqueidentifier,
		@tis_isQuotation	as bit,
		@tis_isCredit		as bit,
		@stor_id			as int
SELECT
		@comp_id			=1,
		@tis_guid			='4g5rgre6hhyh7725g4r65g4r56grg4r6g4r',
		@tis_isQuotation	='false',
		@tis_isCredit		='false',
		@stor_id			=1
*/


Begin

	Begin Transaction

		Declare @ActualQuotationStatus		as bit
		Declare @ActualStorId				as int
		Declare @bra_id						as int
		Declare @counter_id					as int
		Set		@counter_id					=  1
		Declare @counter_value				as INT
		DECLARE @df_id						AS INT
		DECLARE @bolReloadStorage			AS BIT
		SET		@bolReloadStorage			= 'False'

		Select Top 1
					@ActualQuotationStatus	= tis_isQuotation,
					@bra_id					= bra_id,
					@ActualStorId			= stor_id,
					@df_id					= df_id
			From dbo.tbTempItemStock			WITH (NOLOCK)
			Where	tis_guid				= @tis_guid
				and comp_id					= @comp_id


		SELECT @bolReloadStorage	= IsNull(tdf.df_SalesOrder_ChangeStorOnDFChange,'False')
			FROM tbDocumentsFile tdf	WITH (NOLOCK)
				WHERE	tdf.comp_id		= @comp_id AND
						tdf.df_id		= @df_id


		-- -----------------------------------------------------------------------------------
		-- Si se cambio de Presupuesto a algun otro comprobante o si se cambio de deposito,
		--		se recalcularan las prioridades.
		-- -----------------------------------------------------------------------------------
		If		(@tis_isQuotation = 'false' and @ActualQuotationStatus = 'true')
			or	(@stor_id <> @ActualStorId)
		Begin
			Declare cursor_TIS_uS
				CURSOR LOCAL FAST_FORWARD For
					Select tis_id
						From tbTempItemStock		WITH (NOLOCK)
						Where	comp_id				= @comp_id
							and	tis_guid			= @tis_guid
						Order By tis_priority


			Open cursor_TIS_uS
			Declare @tis_id as int
			Declare @tis_priority as int

			Fetch Next from cursor_TIS_uS	Into @tis_id
			While @@fetch_status <> -1
				Begin

					Set @tis_priority = 0
					exec dbo.spCounters_getNextValue	@comp_id,
												@stor_id,
												@counter_id,
												@tis_priority output

					Update dbo.tbTempItemStock	WITH (ROWLOCK)
						Set tis_priority			=	@tis_priority,
							stor_id					=	CASE	-- Si el documento dice que cambie el deposito de todos los items lo hace. ( Logistica )
															WHEN @bolReloadStorage = 'True' THEN @stor_id
															ELSE stor_id
														END
						Where	comp_id = @comp_id
							and tis_id  = @tis_id

					Fetch Next from cursor_TIS_uS	Into @tis_id

				End
			Close		cursor_TIS_uS
			Deallocate	cursor_TIS_uS

		End
		-- -----------------------------------------------------------------------------------


		Update	dbo.tbTempItemStock		WITH (ROWLOCK)
			Set		tis_isQuotation			= @tis_isQuotation,
					tis_isCredit			= @tis_isCredit
			Where	tis_guid				= @tis_guid
				and comp_id					= @comp_id

	Commit Transaction

End
GO






-- --------------------------------------------------------------
-- MOZ  12-2009
-- Actualiza storage , documento y prioridad
-- --------------------------------------------------------------



CREATE PROCEDURE [dbo].[spTempItemStock_UpdateTransfer2Branch]

(		@comp_id			INT,
		@guid				UNIQUEIDENTIFIER,
		@tis_priority		decimal(14,4),
		@stor_id			INT,
		@df_id_new_forced	INT
)
AS

BEGIN


	SET NOCOUNT ON


	-- ----------------------------------------------------
	-- Test
	-- ----------------------------------------------------
	/*
	DECLARE    @comp_id		INT,
			@guid			UNIQUEIDENTIFIER,
			@tis_priority	decimal(14,4),
			@stor_id		INT,
			@doc_id			int
		SELECT  @comp_id				=1,
				@guid			='',
				@tis_priority	=1,
				@stor_id		=1,
				@doc_id			=1
	*/
	-- ----------------------------------------------------


		--Obtengo el equivalene del documento
		DECLARE @ldf_id_new			INT

		SELECT Top 1 @ldf_id_new = tdf2.df_id
			FROM tbDocumentsFile tdf					WITH (NOLOCK)
			INNER JOIN tbDocumentsFile tdf2				WITH (NOLOCK)
			ON		tdf2.comp_id	= tdf.comp_id
				AND tdf2.sd_id		= tdf.sd_id
				AND tdf2.df_Kindof	= tdf.df_Kindof
			WHERE	tdf.comp_id		= @comp_id
				and tdf2.df_id	   <> tdf.df_id
			ORDER BY tdf2.df_order



	UPDATE dbo.tbTempItemStock	WITH (rowlock	)
		SET tis_priority	= @tis_priority,
			stor_id			= CASE
								 WHEN @stor_id > 0 THEN @stor_id
								 ELSE					stor_id
							  END,
			doc_id			= @ldf_id_new, -- Al Pedo, no le da bola a esto por lo que veo...   MOS   04-2021
			df_id_to		=
							CASE
								WHEN @df_id_new_forced > 0 THEN @df_id_new_forced
								ELSE							NULL
							END
		WHERE	comp_id		= @comp_id
		AND		tis_guid	= @guid


END



GO


-- Retorna el volumen total de los articulos de un determinado guid en una tbTempItemStock
CREATE PROCEDURE [dbo].[spTempItemStock_volumeCalculation]
(
	@comp_id					INT,
	@guid						UNIQUEIDENTIFIER,
	@user_id					INT,
	@item_id                    INT,
	@decQTY                     DECIMAL(19,6)
)
AS

BEGIN

	SET NOCOUNT ON


	DELETE FROM tbVolumeCalculationTMP
		WHERE guid = @guid



    IF @item_id = -1   -- Todos los Items del Pedido
        BEGIN

	        INSERT INTO tbVolumeCalculationTMP(guid,
									   [weight],
									   higth,
									   large,
									   wide,
									   qty,
									   item_desc,
									   item_detail,
									   item_code)

		    SELECT	@guid,
				ISNULL(ti.item_weight,99),
				ISNULL(ti.item_higth,100),
				ISNULL(ti.item_large,100),
				ISNULL(ti.item_wide,100),
				ttis.tis_qty,
				ISNULL(ti.item_desc,''),
				ISNULL(ti.item_detail,''),
				ti.item_code
			FROM tbTempItemStock	ttis	WITH (NOLOCK)
			INNER JOIN tbItem		ti		WITH (NOLOCK)
				ON	ti.comp_id = ttis.comp_id			AND
					ti.item_id = ttis.item_id
			WHERE	ttis.comp_id			= @comp_id	AND
					ttis.tis_guid			= @guid		AND
					ttis.tis_DeliveryCharge = 'False'	AND
					ttis.tis_isEnvioPackItem= 'False'

        END
    ELSE -- Un Item en Particular
    	BEGIN
	        INSERT INTO tbVolumeCalculationTMP(guid,
									   [weight],
									   higth,
									   large,
									   wide,
									   qty,
									   item_desc,
									   item_detail,
									   item_code)

		    SELECT
				TOP 1	-- MOS 03-2024: Segun N1 cuando hacen pruebas ponen dos del mismo articulo en dos renglones diferentes y les da la cot x 2 y no x 1
				@guid,
				ISNULL(ti.item_weight,99),
				ISNULL(ti.item_higth,100),
				ISNULL(ti.item_large,100),
				ISNULL(ti.item_wide,100),
				@decQTY,
				ISNULL(ti.item_desc,''),
				ISNULL(ti.item_detail,''),
				ti.item_code
		    FROM tbItem		ti		WITH (NOLOCK)
			WHERE	ti.comp_id			= @comp_id	AND
					ti.item_id			= @item_id
    	END






	SELECT * FROM dbo.fngetVolumeCalculation(@guid)		-- Para MercadoEnvios.   Arma un Empaquetado de Volumen Total

	SELECT *
		FROM tbVolumeCalculationTMP		WITH (NOLOCK)	-- Para EnvioPack , Otros, informa el volumen SUELTO
		WHERE guid = @guid

	DELETE FROM tbVolumeCalculationTMP
		WHERE guid = @guid

END
GO

CREATE PROCEDURE [dbo].[spTempItemStorage_GetDataByID]
(
	@comp_id	INT,
	@intID		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@intID		INT
			SELECT
				@comp_id	= 1,
				@intID		= 1
		*/
		-- -----------------------------------------
		SELECT
			ttisp.intID,
			ttisp.tmpguid,
			ttisp.item_id,
			ttisp.stor_id,
			ttisp.storp_id,
			ttisp.intqty,
			ttisp.intMaxQty,
			tsp.storp_nick,
			tsp.storp_desc,
			ti.item_code,
			ti.item_desc
			FROM tbTempItemStorage_Positions	AS ttisp	WITH(NOLOCK)
			INNER JOIN tbStoragePositions		AS tsp		WITH(NOLOCK)
				ON	tsp.comp_id		= @comp_id	AND
					tsp.storp_id	= ttisp.storp_id
			INNER JOIN tbItem					AS ti		WITH(NOLOCK)
				ON	ti.comp_id		= @comp_id	AND
					ti.item_id		= ttisp.item_id
			WHERE ttisp.intID = @intID
	END



GO

