CREATE PROCEDURE spTempItemStorage_Positions_Output_getDataByID
(
	@comp_id	INT,
	@intID		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@intID		INT
			SELECT
				@comp_id	= 1,
				@intID		= 1
		*/
		-- ---------------------------------------------------------


		SELECT
			ttispo.intID,
			ttispo.tmpguid,
			ttispo.item_id,
			ttispo.stor_id,
			ttispo.storp_id,
			ttispo.initQty,
			ttispo.maxQty,
			tsp.storp_nick,
			tsp.storp_desc,
