CREATE PROCEDURE [dbo].[spTempItemStorage_Positions_ValidateAssignedQtyBeforeInsert]
(
	@comp_id	INT,
	--@lang_id	INT,
	--@bra_id		INT,
	--@prof_id	INT,
	--@user_id	INT,
	@guid		UNIQUEIDENTIFIER,
	--@item_id	INT,
	--@stor_id	INT,
	@qty		INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@user_id	INT,
				@guid		UNIQUEIDENTIFIER,
				--@item_id	INT,
				--@stor_id	INT,
				@qty		INT
		*/
		-- ----------------------------------------------------

		-- ----------------------------------------
		-- VARIABLE DE TRABAJO
		-- ----------------------------------------
		DECLARE
			@lTotalAssignedQty	INT
		SET @lTotalAssignedQty	= 0
		-- ----------------------------------------

		SELECT
			@lTotalAssignedQty	= SUM(ttisp.intqty)
			FROM tbTempItemStorage_Positions AS ttisp	WITH(NOLOCK)
			WHERE ttisp.tmpguid = @guid

		IF @lTotalAssignedQty = @qty
			BEGIN
				SELECT
					'True'	[IsQtyOk],
					''		[ErrorMessage]
			END
		ELSE
			BEGIN
				SELECT
					'False'																					[IsQtyOk],
					'La suma total de las cantidades asignadas a todas las posiciones pertenecientes </br>
					 al depósito seleccionado, debe ser igual a la cantidad ingresada por el usuario.'		[ErrorMessage]
			END


	END



GO

