CREATE PROCEDURE spTemporarySelection_MarkOrUnmarkItem
(
	@guid	UNIQUEIDENTIFIER,
	@tmp_Id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@guid	UNIQUEIDENTIFIER,
				@tmp_Id	INT
			SELECT
				@guid	= '',
				@tmp_Id	= 1
		*/
		-- -----------------------------------------

		IF EXISTS (SELECT 1
					FROM tbTemporarySelection tts
					WHERE	tts.tmpGUID = @guid AND
							tts.tmpID	= @tmp_Id)
			BEGIN
				DELETE FROM tbTemporarySelection
				WHERE	tmpGUID = @guid		AND
						tmpID	= @tmp_Id
			END
		ELSE
			BEGIN
				INSERT INTO tbTemporarySelection
				(
					tmpGUID,
					tmpID
				)
				VALUES
				(
					@guid,
					@tmp_Id
				)
			END
	END


GO

