			tttmu.stringValue1			[stringValue01],			--Título de la Publicación
			tttmu.stringValue2,			--Permalink de la Publicación
			tttmu.decimalValue1,		--Precio de la Publicación
			tttmu.integerValue1,		--Cantidad
