CREATE PROCEDURE [dbo].[spTemporaryTable4MultipleUse_InsertData4MercadoLibrePublicationsMassiveClone]
(
	@guid				UNIQUEIDENTIFIER,
	@mlp_id				int

)


AS
		SET NOCOUNT ON

		BEGIN

			IF NOT EXISTS (SELECT 1
			               FROM tbTemporaryTable4MultipleUse			tttmu		WITH (NOLOCK)
						   WHERE	tttmu.guidID		= @guid		AND
									tttmu.integerValue1	= @mlp_id)
				BEGIN

					INSERT INTO tbTemporaryTable4MultipleUse
					(
						 guidID,
						 integerValue1,
						 bitValue1
					)
					VALUES
					(
						@guid,
						@mlp_id,
						1
					)

				END

			ELSE

				BEGIN

					DELETE FROM tbTemporaryTable4MultipleUse
					WHERE	guidID			= @guid		AND
							integerValue1	= @mlp_id

				END

		END
GO

CREATE PROCEDURE [dbo].[spTemporaryTable4MultipleUse_InsertData4MercadoLibrePublicationsMassiveCloneByExcel]
(
	@comp_id				INT,
	@guid					UNIQUEIDENTIFIER,
	@MLPublicationID		NVARCHAR(50),
	@MLTitle				NVARCHAR(60),
	@prli_id				INT,
	@stor_id				INT,
	@ItemGuid				UNIQUEIDENTIFIER,
	@mls_id					INT,
	@mlp_listing_type_id	NVARCHAR(100),
	@filter_prli_id			INT,
	@filter_stor_id			INT
)
AS
		SET NOCOUNT ON
		BEGIN

			-- ----------------------------------------------------------------------------------
			DECLARE @objGUID AS UNIQUEIDENTIFIER
			SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)

			DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

			INSERT INTO @tblComplexFilter_Items

				SELECT
					tcf.sl_id
					FROM tbComplexFilter tcf      WITH (NOLOCK)
					WHERE tcf.sl_guid	  = @objGUID      AND
						  tcf.sl_selected = 'True'

			IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @tblComplexFilter_Items
					SELECT ti.item_id
						FROM tbItem ti
						WHERE ti.comp_id = @comp_id
			END
			-- ----------------------------------------------------------------------------------


			-- ------------------------------------------------------------------------------------
			-- SI EXISTE LA PUBLICACION EN EL SISTEMA, LA GRABO, SI NO NO LO HAGO Y DEVUELVO UN
			-- BOOLEAN PARA QUE LE MARQUE CUALES NO PUDO CLONAR
			-- ------------------------------------------------------------------------------------
			DECLARE @ExistsPublication BIT
			SET		@ExistsPublication = 'False'

			IF EXISTS (SELECT 1
						FROM tbMercadoLibre_ItemsPublicados					tmlip	WITH(NOLOCK)
						INNER JOIN @tblComplexFilter_Items					tmp
						ON		tmp.item_id				= tmlip.item_id
						WHERE tmlip.comp_id = @comp_id	AND
							  tmlip.mls_id	= @mls_id	AND
							(
								@mlp_listing_type_id		= '-1'		OR
								tmlip.mlp_listing_type_id	= @mlp_listing_type_id
							)	AND
							(
								@prli_id					= -1		OR
								tmlip.prli_id				= @filter_prli_id
							)	AND
							(
								@stor_id					= -1		OR
								tmlip.stor_id				= @filter_stor_id
							)							AND
							tmlip.mlp_publicationID			= @MLPublicationID)
				BEGIN
					SET @ExistsPublication = 'True'
				END
			-- ------------------------------------------------------------------------------------
			DECLARE @mlp_id	INT
			IF @ExistsPublication = 'True'
				BEGIN
					SELECT
						@mlp_id = tmlip.mlp_id
					FROM tbMercadoLibre_ItemsPublicados						tmlip	WITH(NOLOCK)
					WHERE	tmlip.comp_id			= @comp_id				AND
							tmlip.mlp_publicationID = @MLPublicationID
				END


			IF @ExistsPublication = 'True'
				BEGIN
					IF NOT EXISTS (SELECT 1
								   FROM tbTemporaryTable4MultipleUse			tttmu		WITH (NOLOCK)
								   WHERE	tttmu.guidID		= @guid		AND
											tttmu.stringValue10 = @MLPublicationID)
						BEGIN

							INSERT INTO tbTemporaryTable4MultipleUse
							(
								guidID,
								integerValue1,	--MLP_ID
								integerValue2,	--PRLI_ID
								integerValue3,  --STOR_ID
								stringValue1,	--TITULO
								stringValue10,	--ID DE PUBLICACION (MLA484654564)
								bitValue1
							)
							VALUES
							(
								@guid,
								@mlp_id,
								@prli_id,
								@stor_id,
								@MLTitle,
								@MLPublicationID,
								'True'
							)
							SELECT @ExistsPublication [Exists]
						END

					ELSE

						BEGIN

							--SI YA EXISTE LO BORRO Y LO VUELVO A CARGAR PORQUE PUEDE HABER HABERLE CARGADO OTRA LISTA DE PRECIOS / DEPOSITO
							DELETE FROM tbTemporaryTable4MultipleUse
							WHERE	guidID			= @guid		AND
									stringValue10	= @MLPublicationID

							INSERT INTO tbTemporaryTable4MultipleUse
							(
								guidID,
								integerValue1,	--MLP_ID
								integerValue2,	--PRLI_ID
								integerValue3,  --STOR_ID
								stringValue1,	--TITULO
								stringValue10,	--ID DE PUBLICACION (MLA484654564)
								bitValue1
							)
							VALUES
							(
								@guid,
								@mlp_id,
								@prli_id,
								@stor_id,
								--@price,
								--@decimal2,
								@MLTitle,
								--@ML_Description,
								@MLPublicationID,
								'True'
							)
							SELECT @ExistsPublication [Exists]
					END
				END
			ELSE
				BEGIN
					SELECT @ExistsPublication [Exists]
				END
		END
GO

CREATE PROCEDURE spTemporaryTable4MultipleUse_InsertFullMLPublicationData
(
	@comp_id				INT,
	@guid					UNIQUEIDENTIFIER,
	@title					NVARCHAR(200),
	@permalink				NVARCHAR(200),
	@status					NVARCHAR(50),
