	@id						NVARCHAR(50),
	@accepts_mercadopago	BIT,
	@warranty				NVARCHAR(200),
	@mode					NVARCHAR(200),
	@dimensions				NVARCHAR(200),
	@local_pick_up			BIT,
	@free_shipping			BIT,
	@logistic_type			NVARCHAR(200),
	@store_pick_up			BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------------------------
		-- TESTING
		-- -- ---------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@guid					UNIQUEIDENTIFIER,
				@id						NVARCHAR(50),
				@title					NVARCHAR(200),
				@status					NVARCHAR(50),
				@category_id			NVARCHAR(50),
				@seller_id				NVARCHAR(50),
				@official_store_id		NVARCHAR(50),
				@price					DECIMAL(19,4),
				@available_quantity		INT,
				@sold_quantity			INT,
				@buying_mode			NVARCHAR(50),
				@listing_type_id		NVARCHAR(50),
				@permalink				NVARCHAR(200),
				@accepts_mercadopago	BIT,
				@warranty				NVARCHAR(200),
				@mode					NVARCHAR(200),
				@dimensions				NVARCHAR(200),
				@local_pick_up			BIT,
				@free_shipping			BIT,
				@logistic_type			NVARCHAR(200),
				@store_pick_up			BIT
		*/
		-- ---------------------------------------------------------------------------

		INSERT INTO tbTemporaryTable4MultipleUse
		(
			guidID,				--GuidOfThisPage
			integerValue1,		--@available_quantity
			integerValue2,		--@sold_quantity
			decimalValue1,		--@price
			stringValue1,		--@title
			stringValue2,		--@permalink
			bitValue1,			--@accepts_mercadopago
			bitValue2,			--@local_pick_up
			bitValue3,			--@free_shipping
			cd,
			stringValue10,		--@status
			stringValue11,		--@category_id
			stringValue12,		--@seller_id
			stringValue13,		--@official_store_id
			stringValue14,		--@buying_mode
			stringValue15,		--@listing_type_id
			stringValue16,		--@id
			stringValue17,		--@warranty
			stringValue18,		--@mode
			stringValue19,		--@dimensions
			stringValue20, 		--@logistic_type
			bitValue4			--store_pick_up
		)
		VALUES
		(
			@guid,
			@available_quantity,
			@sold_quantity,
			@price,
			@title,
			@permalink,
			@accepts_mercadopago,
			@local_pick_up,
			@free_shipping	,
			GETDATE(),
			@status,
			@category_id,
			@seller_id,
			@official_store_id,
			@buying_mode,
			@listing_type_id,
			@id,
			@warranty,
			@mode,
			@dimensions,
			@logistic_type,
			@store_pick_up
		)

	END

GO

CREATE PROCEDURE [dbo].[spTemporaryTable4MultipleUse_MarkOrUnmarkAll4MassiveClonePublication]
(
	@comp_id				INT,
	@guid					UNIQUEIDENTIFIER,
	@ItemGuid				UNIQUEIDENTIFIER,
	@mls_id					INT,
	@mlp_listing_type_id	NVARCHAR(100),
	@filter_prli_id			INT,
	@filter_stor_id			INT,
	@MarkOrUnmark			BIT --TRUE = MARCAR // FALSE = DESMARCAR
)
AS
	BEGIN
		SET NOCOUNT ON

		IF @MarkOrUnmark = 'True'
			BEGIN
				-- ----------------------------------------------------------------------------------
				-- BORRO TODO PRIMERO E INSERTO TODO PARA EL GUID
				-- ----------------------------------------------------------------------------------
				DELETE FROM tbTemporaryTable4MultipleUse WHERE guidID = @guid
				-- ----------------------------------------------------------------------------------

				-- ----------------------------------------------------------------------------------
				-- INSERTO TODOS LOS REGISTROS
				-- ----------------------------------------------------------------------------------

				DECLARE @objGUID AS UNIQUEIDENTIFIER
				SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@ItemGuid)

				DECLARE @tblComplexFilter_Items TABLE (Item_Id INT PRIMARY KEY)

				INSERT INTO @tblComplexFilter_Items

					SELECT
						tcf.sl_id
						FROM tbComplexFilter tcf      WITH (NOLOCK)
						WHERE tcf.sl_guid	  = @objGUID      AND
							  tcf.sl_selected = 'True'

				IF @@ROWCOUNT = 0
				BEGIN
					INSERT INTO @tblComplexFilter_Items
						SELECT ti.item_id
							FROM tbItem ti
							WHERE ti.comp_id = @comp_id
				END

				INSERT INTO tbTemporaryTable4MultipleUse
				(
					guidID,
					integerValue1,	--MLP_ID
					integerValue2,	--PRLI_ID
					integerValue3,  --STOR_ID
					stringValue1,	--TITULO
					stringValue10,	--ID DE PUBLICACION (MLA484654564)
					bitValue1
				)
				SELECT
					@guid,
					tmlip.mlp_id,
					tmlip.prli_id,
					tmlip.stor_id,
					tmlip.mlp_itemTitle,
					tmlip.mlp_publicationID,
					'True'
				FROM tbMercadoLibre_ItemsPublicados tmlip
				INNER JOIN @tblComplexFilter_Items					tmp
				ON		tmp.item_id				= tmlip.item_id
				WHERE tmlip.comp_id = @comp_id	AND
						tmlip.mls_id	= @mls_id	AND
					(
						@mlp_listing_type_id		= '-1'		OR
						tmlip.mlp_listing_type_id	= @mlp_listing_type_id
					)	AND
					(
						@filter_prli_id				= -1		OR
						tmlip.prli_id				= @filter_prli_id
					)	AND
					(
						@filter_stor_id				= -1		OR
						tmlip.stor_id				= @filter_stor_id
					)
				-- ----------------------------------------------------------------------------------
			END
		ELSE
			BEGIN
				--BORRO TODO PARA EL GUID
				DELETE FROM tbTemporaryTable4MultipleUse WHERE guidID = @guid
			END
	END
GO



CREATE PROCEDURE spTesting4GridWithButtons
(
	@comp_id	INT
)
--@datefrom	DATETIME,
--@dateto		DATETIME
AS
	SET NOCOUNT ON

		BEGIN

			SELECT
				TOP 5
					' '												[ ],
					CONVERT(VARCHAR,tct.ct_total) +	'|' + CONVERT(VARCHAR,tct.ct_transaction) + '|'	[Data]
			FROM tbCommercialTransactions		tct
			WHERE	tct.comp_id = @comp_id		AND
					tct.sd_id	IN(101,106)
			ORDER BY tct.ct_transaction DESC
					--tct.ct_date BETWEEN @datefrom AND @dateto


		END
GO





create PROCEDURE [dbo].[spTexto_de_paginas]
(
	@lang_id INT,
	@page    INT

)
as
set nocount ON
/*
DECLARE @page    INT,
		@lang_id INT

select @page    = 213,
	   @lang_id = 2
*/
SELECT tp.page_desc [Página de Filtro],
	   tc.ctrl_desc + ' - ' + convert(varchar,tc.ctrl_id) [ctrl_desc / ID],
	   tswn.word_desc [Texto]

FROM tbsysTextsNew ttn

INNER JOIN tbsysPages tp
ON tp.page_id = ttn.page_id


INNER JOIN tbsysControls tc
ON tc.ctrl_id = ttn.ctrl_id
AND tc.[type_id] = 1

INNER JOIN tbSysWordsNew tswn
ON tswn.lang_id    = @lang_id
AND tswn.wordsi_id = ttn.wordsi_id

WHERE ttn.page_id= @page
GO

