CREATE  PROCEDURE [dbo].[spTiendaNube_insertCustomer]
	@comp_id				AS INT,
	@lang_id				AS INT,
	@bra_id					AS INT,
	@guid					AS UNIQUEIDENTIFIER,
	@tn_storeID				AS BIGINT,
	@tn_OrderID				AS BIGINT,
	@cust_id_A				AS INT,
	@cust_id_B				AS INT,
	@customer_id			AS BIGINT,
	@contact_name			AS VARCHAR(250),
	@contact_email			AS VARCHAR(250),
	@contact_phone			AS VARCHAR(250),
	@contact_identification AS VARCHAR(50),
	@billing_address		AS VARCHAR(250),
	@billing_number			AS VARCHAR(250),
	@billing_floor			AS VARCHAR(250),
	@billing_locality		AS VARCHAR(250),
	@billing_zipcode		AS VARCHAR(250),
	@billing_province		AS VARCHAR(100),
	@billing_country		AS VARCHAR(10),
	@user_id				AS INT

AS

BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- Los FORROS de Tienda Nube NO TIENE PENSADO que un PUTO CLIENTE DEBE ser Facturado a algun Numero de documento VALIDO. FORROOOSSS
	-- x eso, si NO mandan el PUTO DNI o CUIT, se dan de alta con numero fiscal  igual al ID Interno del Cliente de TN
	SET @contact_identification = ISNULL(@contact_identification,'')
	SET @contact_identification = dbo.fnStrAllTrim(@contact_identification)

	DECLARE @bitHasDocumentAsID AS BIT = 'False'
	IF  @contact_identification = ''	-- MOS 03-2024: si pone el documento comom ID, NO debe ir a buscar a AFIP
		BEGIN
			SET @contact_identification = CONVERT(VARCHAR(50),@customer_id)
			SET @bitHasDocumentAsID		= 'True'
		END
	SET @contact_identification = dbo.fnStrAllTrim(@contact_identification)

	DECLARE @cust_id		AS INT			= -1
	DECLARE @fc_id			AS INT			= 3 -- Consumidor Final de ARG x Defecto
	DECLARE @strTNT			AS VARCHAR(10)	= 'DNI'
	DECLARE @strCustomerAddress
							AS VARCHAR(200) = ''
	DECLARE @intCountryID	AS INT	= 54
	DECLARE @intStateID		AS INT 	= 54001

	-- MOS 03-2024: puse esto x q TEORICAMENTE Gaston de Badia DICE que le ingresa su dni como cuit...
	DECLARE @strcontact_identification4Search AS VARCHAR(50) = @contact_identification
	SET @strcontact_identification4Search = dbo.fnGetCUITFormatted(@strcontact_identification4Search)	-- MOS 07-2024
	SET @strcontact_identification4Search = REPLACE(@strcontact_identification4Search,'-','')			-- MOS 07-2024
	SET @strcontact_identification4Search = dbo.fnStrAllTrim(@strcontact_identification4Search)
	IF	@bitHasDocumentAsID								= 'False' AND
		DATALENGTH(@strcontact_identification4Search)	= 11			-- SOLO si es un CUIT...
		BEGIN
			SET @fc_id						= 1 -- R Inscripto
			SET @strTNT						= 'CUIT'   -- MOS 07-2024
			SET @contact_identification		= dbo.fnGetCUITFormatted(@contact_identification)
			SELECT	@contact_name			= tta.afip_nombre,
					@fc_id					= tta.afip_fiscalClass
				FROM tbsysTaxAFIP tta	WITH (NOLOCK)
				WHERE tta.afip_cuit			= @strcontact_identification4Search
		END
	ELSE
		BEGIN
			SET @strTNT = 'DNI'	-- MOS 03-2024:estos FORROS de TN deben estar mandando CUIT o CUIL con un puto DNI
			SET @fc_id  = 2		-- y la clase fiscal es Consumidor Final..
		END

	SET @strCustomerAddress			=  dbo.fnstrAlltrim(@billing_address) + ' ' + dbo.fnstrAlltrim(@billing_number) + ' Piso:' + dbo.fnstrAlltrim(@billing_floor)

	IF	@billing_country = 'AR'
		BEGIN
			SET @intCountryID = 54
		END

	SELECT @intStateID			= ts.state_id
		FROM tbsysState AS ts		WITH (NOLOCK)
		WHERE	ts.country_id	= @intCountryID		AND
				ts.state_desc	= @billing_province

	SELECT @cust_id = tc.cust_id
		FROM tbCustomer AS tc	WITH (NOLOCK)
		WHERE	tc.comp_id			= @comp_id AND
				REPLACE(tc.cust_taxNumber,'-','')	= REPLACE(@contact_identification,'-','')		-- MOS 07-2024: puse los replace de - a nada para quye busque con o sin guiones.
	IF @cust_id = -1
		BEGIN
			SELECT @cust_id = tc.cust_id
				FROM tbCustomer AS tc	WITH (NOLOCK)
				WHERE	tc.comp_id			= @comp_id AND
						tc.cust_email		= @contact_email
		END

	-- Si ENCUENTRA al cliente x el ID o x eMail, lo retorna
	IF @cust_id > 0
		BEGIN
			SELECT @cust_id   [cust_id]
			RETURN
		END


	-- Sino, lo da de ALTA
	INSERT INTO tbCustomer		WITH (ROWLOCK)
	(
		comp_id,
		bra_id,
		cust_name,
		cust_name1,
		fc_id,
		cust_taxNumber,
		stcIB_Id,
		cust_taxIBNumber,
		cust_web,
		cust_inactive,
		cust_partnerOf,
		cust_contact,
		cust_address,
		cust_city,
		cust_zip,
		country_id,
		state_id,
		cust_phone1,
		cust_phone2,
		cust_email,
		cust_fax,
		cust_picture,
		sm_id,
		ck_id,
		st_id,
		disc_id,
		dl_id,
		cust_credit_max,
		cust_credit_own,
		curr_id,
		acc_count_id,
		[user_id],
		prli_id,
		stor_id,
		tnt_id,
		ss_id,
		cust_isEditing,
		cust_isEditingCd,
		cust_isEditingUserId,
		cust_annotation,
		cust_judMan,
		cust_note1,
		cust_note2,
		cust_note3,
		cust_note4,
		cust_address4Delivery,
		cust_address4Payments,
		cust_webPassword,
		bra_id4Emmition,
		city_id,
		cust_4InitialValues,
		sm_id_2,
		cust_showstock,
		cust_showpricelist,
		cust_showzerostockitems,
		cust_login,
		cust_login_cd,
		cust_login_ip,
		cust_login_name,
		cust_SaleOrderMaxValue,
		cust_cd,
		fecountry_id,
		fex_cuitID,
		cust_contact4Payments,
		cust_email4Payments,
		cust_contact4Management,
		cust_email4Management,
		cust_contact4Administration,
		cust_email4Administration,
		cust_contact4Logistics,
		cust_email4Logistics,
		act_id,
		cust_SaleOrderDisableConcurrentProc,
		cust_SaleOrderBranchTransfer,
		coslis_id,
		coslis_idB,
		cust_webPending2Verify,
		cust_excludeInCITI,
		stca_id,
		cust_Mailing4CustOverdueDebt_Excluded,
		cust_contact4Alternative,
		cust_email4Alternative,
		cust_contact4RMA,
		cust_email4RMA,
		cust_address4RMA,
		cust_isAvailable4InternalRMA,
		cust_phone4RMA,
		cust_contact4AlternativeII,
		cust_email4AlternativeII,
		rmap_id,
		street_id,
		cust_addressNumber,
		cust_addressAdditional,
		rating_id,
		marst_id,
		cust_isOwner,
		cust_ownerOf,
		cust_remuneration,
		cram_id,
		cust_ramification,
		cust_jobTitle,
		cust_jobAddress,
		cust_jobCity,
		cust_jobCity_Id,
		cust_jobPhone,
		cust_jobName,
		cust_jobPayDate,
		cust_jobAdmissionDate,
		corp_id,
		cust_addressFloor,
		stg_id,
		cust_imageChecksum,
		cust_ratingProcessCheck,
		rating_id_previous,
		rating_id_cd,
		cust_firstname,
		cust_lastName,
		def_id,
		cmde_noAction,
		cust_updatedFromABM,
		-- cust_jobYearInIt -- this column value is auto-generated,
		cust_jobPayIntervalIs15,
		cust_disabled4PersonalLoan,
		cust_birthDay,
		cust_maleOrFemale,
		-- cust_age -- this column value is auto-generated,
		cust_cellPhone,
		cust_lastPaymentDatefromOtherERP,
		cust_MercadoLibreNickName,
		cust_checked,
		cust_excludeOfCustomerMailing,
		user_id4Insert,
		user_id4LastUpdate,
		cust_LastUpdate,
		cust_GBPUrl,
		cust_GBPModules,
		cust_GBPDbName,
		cust_GBPUserQty,
		cust_GBPBranchQty,
		cust_GBPCompanyQty,
		cust_GBPLastURLUpdate,
		cust_GBPCG,
		cust_GBPSN,
		cust_GBPLPD,
		cust_GBPUrl2,
		cust_GBPUrl3,
		cust_GBPDebtorInfo,
		cust_GBPMessage,
		cust_GBPImplementador,
		cust_migrationID,
		cust_MercadoLibreID,
		brag_id,
		ws_internalID,
		cust_GBPCRM_user_id,
		cust_id_related,
		cust_4OnlySign,
		cust_credit_max_Last,
		cust_credit_max_overComeDate,
		MLUser_Id,
		cust_webNickName
	)
	SELECT
			comp_id	,
			bra_id	,
			@contact_name	,
			CONVERT(VARCHAR(50),@customer_id),
			CASE
				WHEN @fc_id IS NOT NULL	THEN @fc_id
				WHEN @strTNT = 'CUIT'		THEN 1
				WHEN @strTNT = 'DNI'		THEN 2
				WHEN @strTNT = 'RUT'		THEN 56001	-- Chile.Persona Natural
				WHEN @strTNT = 'RUN'		THEN 56001	-- Chile.Persona Natural
				ELSE							 2
			END,
			@contact_identification	,
			stcIB_Id	,
			cust_taxIBNumber	,
			cust_web	,
			cust_inactive	,
			cust_partnerOf	,
			cust_contact	,
			CONVERT(NVARCHAR(150),@strCustomerAddress)	,
			CONVERT(NVARCHAR(60),@billing_locality)	,
			@billing_zipcode	,
			@intCountryID	,
			@intStateID	,
			@contact_phone	,				-- MOS 10-2021
			''	,		-- MOS 10-2021
			@contact_email	,
			cust_fax	,
			cust_picture	,
			sm_id	,
			ck_id	,
			st_id	,
			disc_id	,
			dl_id	,
			cust_credit_max	,
			cust_credit_own	,
			curr_id	,
			acc_count_id	,
			[user_id]	,
			prli_id	,
			stor_id	,
			CASE
				WHEN @strTNT = 'CUIT'	THEN 1
				WHEN @strTNT = 'DNI'	THEN 5
				WHEN @strTNT = 'RUT'	THEN 56001	-- RUT-Chile
				WHEN @strTNT = 'RUN'	THEN 56001	-- RUT-Chile
				ELSE						 5
			END	,
			ss_id	,
			cust_isEditing	,
			cust_isEditingCd	,
			cust_isEditingUserId	,
			cust_annotation	,
			cust_judMan	,
			cust_note1	,
			cust_note2	,
			cust_note3	,
			cust_note4	,
			cust_address4Delivery	,
			cust_address4Payments	,
			cust_webPassword	,
			bra_id4Emmition	,
			NULL	,
			cust_4InitialValues	,
			sm_id_2	,
			cust_showstock	,
			cust_showpricelist	,
			cust_showzerostockitems	,
			cust_login	,
			cust_login_cd	,
			cust_login_ip	,
			cust_login_name	,
			cust_SaleOrderMaxValue	,
			GETDATE()	,
			fecountry_id	,
			fex_cuitID	,
			cust_contact4Payments	,
			cust_email4Payments	,
			cust_contact4Management	,
			cust_email4Management	,
			cust_contact4Administration	,
			cust_email4Administration	,
			cust_contact4Logistics	,
			cust_email4Logistics	,
			act_id	,
			cust_SaleOrderDisableConcurrentProc	,
			cust_SaleOrderBranchTransfer	,
			coslis_id	,
			coslis_idB	,
			cust_webPending2Verify	,
			cust_excludeInCITI	,
			stca_id	,
			cust_Mailing4CustOverdueDebt_Excluded	,
			cust_contact4Alternative	,
			cust_email4Alternative	,
			cust_contact4RMA	,
			cust_email4RMA	,
			cust_address4RMA	,
			cust_isAvailable4InternalRMA	,
			cust_phone4RMA	,
			cust_contact4AlternativeII	,
			cust_email4AlternativeII	,
			rmap_id	,
			street_id	,
			cust_addressNumber	,
			cust_addressAdditional	,
			rating_id	,
			marst_id	,
			cust_isOwner	,
			cust_ownerOf	,
			cust_remuneration	,
			cram_id	,
			cust_ramification	,
			cust_jobTitle	,
			cust_jobAddress	,
			cust_jobCity	,
			cust_jobCity_Id	,
			cust_jobPhone	,
			cust_jobName	,
			cust_jobPayDate	,
			cust_jobAdmissionDate	,
			corp_id	,
			cust_addressFloor	,
			stg_id	,
			cust_imageChecksum	,
			cust_ratingProcessCheck	,
			rating_id_previous	,
			rating_id_cd	,
			cust_firstname	,
			CONVERT(NVARCHAR(100),@contact_name)	,
			def_id	,
			cmde_noAction	,
			cust_updatedFromABM	,
			cust_jobPayIntervalIs15	,
			cust_disabled4PersonalLoan	,
			cust_birthDay	,
			cust_maleOrFemale	,
			cust_cellPhone	,
			cust_lastPaymentDatefromOtherERP	,
			CONVERT(VARCHAR(50),@customer_id)	,
			cust_checked	,
			cust_excludeOfCustomerMailing	,
			@user_id	,
			@user_id	,
			GETDATE()	,
			cust_GBPUrl	,
			cust_GBPModules	,
			cust_GBPDbName	,
			cust_GBPUserQty	,
			cust_GBPBranchQty	,
			cust_GBPCompanyQty	,
			cust_GBPLastURLUpdate	,
			cust_GBPCG	,
			cust_GBPSN	,
			cust_GBPLPD	,
			cust_GBPUrl2	,
			cust_GBPUrl3	,
			cust_GBPDebtorInfo	,
			cust_GBPMessage	,
			cust_GBPImplementador	,
			cust_migrationID	,
			cust_MercadoLibreID	,
			brag_id	,
			ws_internalID	,
			cust_GBPCRM_user_id	,
			cust_id_related	,
			cust_4OnlySign	,
			cust_credit_max_Last	,
			cust_credit_max_overComeDate	,
			NULL	,
			@contact_email  /* MOS 05-2020 x MaxGri cust_webNickName	*/
		FROM tbCustomer tc	WITH (NOLOCK)
		WHERE	tc.comp_id = @comp_id AND
				tc.cust_id =	CASE
									WHEN @strTNT = 'CUIT'	THEN @cust_id_A
									WHEN @strTNT = 'DNI'	THEN @cust_id_A
									WHEN @strTNT = 'RUT'	THEN @cust_id_A
									WHEN @strTNT = 'RUN'	THEN @cust_id_A
									ELSE						 @cust_id_A
								END


	SET		@cust_id = IDENT_CURRENT('tbCustomer')



	--actualización de los datos de la tabla de ciudades con los datos ya cargados en customer
	DECLARE @strExecute AS NVARCHAR(4000)
	SET @strExecute = '
	INSERT      INTO tbCities ( comp_id,  country_id,       state_id,         city_desc )
	SELECT      DISTINCT        1      ,  tc.country_id,    tc.state_id,      tc.cust_city
		FROM  tbCustomer  tc	WITH (NOLOCK)
		WHERE
					tc.comp_id = ' + CONVERT(NVARCHAR(10),@comp_id) +  '
		AND         tc.cust_id = ' + CONVERT(NVARCHAR(10),@cust_id) +  '
		AND			not tc.country_id is null
		AND         not tc.state_id         IS NULL
		and         not tc.cust_city  IS NULL
		and         tc.cust_city            <> ''''
		AND         NOT EXISTS (SELECT top 1 1 FROM vwCities tc1 WITH (NOLOCK)
									WHERE tc1.country_id    = tc.country_id		AND
											tc1.state_id      = tc.state_id		AND
											ltrim(rtrim(tc1.city_desc))  = ltrim(rtrim(tc.cust_city))
											COLLATE Modern_Spanish_CI_AI )
					'
	EXEC (@strExecute)

	SET @strExecute = '
						UPDATE      tbCustomer
						SET         city_id = tc2.city_id
							FROM  tbCustomer tc
								INNER JOIN vwCities tc2	WITH (NOLOCK)
									ON    tc2.country_id    = tc.country_id
									AND tc2.state_id  = tc.state_id
									AND ltrim(rtrim(tc2.city_desc))    = ltrim(rtrim(tc.cust_city))
									COLLATE Modern_Spanish_CI_AI
							WHERE
								tc.comp_id = ' + CONVERT(NVARCHAR(10),@comp_id) +  '	AND
								tc.cust_id = ' + CONVERT(NVARCHAR(10),@cust_id) +  '	AND
								tc.city_id IS NULL
										'
	EXEC (@strExecute)




	SELECT	@cust_id   [cust_id]

END



GO

-- ATENCION si se toca algo aca hacerlo tambien en : spSaleOrderWS_insertSaleOrderMercedoLibre y spSaleOrderWS_insertSaleOrder4FullJaus
CREATE PROCEDURE [dbo].[spTiendaNube_insertSaleOrder]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@guid				UNIQUEIDENTIFIER,
	@cust_id			INT,
	@sd_id				INT,
	@dl_id				INT,
	@st_id				INT,
	@disc_id			INT,
	@soh_observation1	NVARCHAR(350),
	@soh_observation2	NVARCHAR(350),
	@soh_observation3	NVARCHAR(350),
	@soh_observation4	NVARCHAR(350),
	@user_id			INT,
	@tn_id				INT,
	@tno_orderID		BIGINT,
	@tno_JSon				VARCHAR(MAX),
	@strDelliveryAddress	VARCHAR(4000),
	@strInternalAnnotation  VARCHAR(100)

)
AS

BEGIN




	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@bra_id				INT,
			@guid				UNIQUEIDENTIFIER,
			@wst_id				INT,
			@cust_id			INT,
			@sd_id				INT

	SELECT	@comp_id			=1,
			@lang_id			=2,
			@bra_id				=1,
			@guid				='6455CD8D-20A5-4966-B027-F5FDF3047D19',
			@wst_id				=10,
			@cust_id			=24288,
			@sd_id				=1

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -------------------------------------------------------------------------------


	SET NOCOUNT ON



	declare @return_value		INT,
			@errormessage		NVARCHAR(1000)

	set		@return_value = 0
	set		@errormessage = ''


	-- MOS 01-2024: x si llega MAS de una vez la misma orden, solo crea el pedido UNA vez
	IF EXISTS(	SELECT TOP 1 1
					FROM tbTiendaNube_Orders AS ttno WITH (NOLOCK)
	          		WHERE	ttno.comp_id		= @comp_id	AND
	          				ttno.tn_id			= @tn_id	AND
	          				ttno.tno_orderID	= @tno_orderID)
		BEGIN
			SET @return_value = -1
			SET @errormessage = 'Order Allready Created / Órden YA Ingresada'
			SELECT	@return_value	[code],
					@errormessage	[error_description]
			RETURN
		END









	--obtenemos el df_id para generar el pedido
	DECLARE @df_id		INT

	SELECT	TOP 1 @df_id	= df_id
		FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
		WHERE	sd_id			= @sd_id
		ORDER BY CASE
					WHEN is4WS = 1 THEN 0
					ELSE				1
				 END,
				 df_order






	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					FROM tbTempItemStock ttis WITH (NOLOCK)
					WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid)

		BEGIN

			SET @return_value = -2
			SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 99

		END

	ELSE IF @df_id IS NULL
			BEGIN

				SET @return_value = -3
				SELECT @errormessage = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = @lang_id AND tut.utexts_id = 91

			END


	--si no hubo errores por stock se genera el pedido
	IF @return_value = 0
		BEGIN

			BEGIN TRANSACTION	-- DEBE ESTAR AFUERA DEL TRY!!!!!!!!

			BEGIN TRY



				DECLARE @rv								INT




				DECLARE @sm_id							INT,
						@curr_id_cust					INT

				SELECT	@sm_id			= tc.sm_id,
						@curr_id_cust	= tc.curr_id
					FROM	tbCustomer		tc	 WITH (NOLOCK)
					WHERE	tc.comp_id		= @comp_id
					AND		tc.cust_id		= @cust_id



				-- obtengo el documento para REMITOS asociado a este documento si es que lo tiene.. .
				DECLARE @intDFId4PackingList AS INT
				SET		@intDFId4PackingList = NULL
				SELECT  @intDFId4PackingList = tdf.df_SaleOrderPL_df_Id
					FROM tbDocumentsFile tdf  WITH (NOLOCK)
					WHERE	tdf.comp_id = @comp_id AND
							tdf.df_id	= @df_id



				DECLARE @curr_id_branch					INT,
						@bra_PriceDecimalPlaces			INT,
						@bra_SaleOrderDisposeLimitDay	INT,
						@country_id						INT,
						@state_id						INT

				SELECT	@curr_id_branch					= tb.curr_id,
						@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
						@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
						@country_id						= tb.country_id,
						@state_id						= tb.state_id
					FROM	tbBranch		tb		 WITH (NOLOCK)
					WHERE	tb.comp_id		= @comp_id
					AND		tb.bra_id		= @bra_id










				/******************************************************************************************/
				CREATE TABLE #tmpGetTotalsData
				(
					t1		INT,
					t2		DECIMAL(18,2),
					t3		DECIMAL(19,6),
					t4		DECIMAL(19,6),
					t5		DECIMAL(19,6),
					t6		DECIMAL(18,2),
					t7		DECIMAL(19,5),
					t8		INT,
					t9		DECIMAL(19,6),
					T10		NVARCHAR(4000),
					TotalNoInterest  DECIMAL(25,6)
				)

				--INSERT INTO #tmpGetTotalsData
					--EXEC spTempItemStock_getDataForWebSite @comp_id, @guid, @ws_id, @cust_id, 3



				-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
				DECLARE	@exchange		DECIMAL(19,6)

				SELECT @exchange = dbo.fnGetExchange(@comp_id,1,@curr_id_branch,@curr_id_cust,0,0,'false')





				-- recuperar los totales generales
				INSERT INTO #tmpGetTotalsData
					EXEC	sptmpTax_calculate
							@comp_id,
							@bra_id,
							@cust_id,
							@guid,
							@curr_id_branch,
							@disc_id,
							@country_id,
							@state_id,
							@st_id,
							@curr_id_branch,
							@curr_id_cust,
							@exchange,
							'false',
							@df_id,
							'true',
							@dl_id,
							0,
							'false',
							'false',
							-1,
							-1 -- @ccp_id No INformado


				DECLARE @total					DECIMAL(19,6),
						@soh_discount			DECIMAL(19,6)

				SELECT	@total			= t2,
						@soh_discount	= ROUND(t4, @bra_PriceDecimalPlaces)
				FROM	#tmpGetTotalsData

				--SELECT	@total, @soh_discount
				/******************************************************************************************/






				DECLARE @getdate		DATETIME
				DECLARE @limitdate		DATETIME
				DECLARE @onlydate		DATETIME

				SET		@getdate	= GETDATE()
				SELECT	@onlydate	= DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
				SET		@limitdate	= @onlydate + @bra_SaleOrderDisposeLimitDay

				/*
				SELECT 	@guid,
						@comp_id,
						@bra_id,
						@onlydate,
						@onlydate,
						@sm_id,
						@cust_id,
						@st_id,
						@disc_id,
						@dl_id,
						@onlydate,
						@limitdate,
						@user_id,
						@getdate,
						@total,
						@df_id,
						@exchange,
						@curr_id_cust
				*/


				EXEC spSaleOrder_insertData
						-1,
						@guid,
						@comp_id,
						@bra_id,
						@onlydate,
						@onlydate,
						@soh_observation1,
						@soh_observation2,
						@soh_observation3,
						@soh_observation4,
						'false',
						@sm_id,
						@cust_id,
						@st_id,
						@disc_id,
						@dl_id,
						null,
						@onlydate,
						@limitdate,
						1,				--+------------------------------------------------------------------------------------
						'A',			--|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
						1,				--+------------------------------------------------------------------------------------
						@user_id,
						'false',
						@getdate,
						@total,
						@df_id,
						5,
						@exchange,
						@curr_id_cust,
						null,
						NULL,
						@return_value = @rv OUTPUT



				EXEC	spSaleOrderHeader_updatePL_df_id
						@comp_id,
						@bra_id,
						@rv,
						@intDFId4PackingList, --null,  MOS 04-2020
						null,
						@soh_discount,
						''



				EXEC	spSaleOrder_updateCurrExchange
						@comp_id,
						@bra_id,
						@rv,
						@curr_id_cust,
						@exchange,
						0 --@decInCash



				UPDATE tbsaleorderheader
					SET soh_internalAnnotation	= @strInternalAnnotation, --'TNu# ' + CONVERT(VARCHAR(25),@tno_orderID),
						ssos_id					= 5,
						soh_deliveryAddress		= @strDelliveryAddress
					WHERE	comp_id = @comp_id	AND
							bra_id	= @bra_id	AND
							soh_id	= @rv


				DELETE FROM tbtmpTax		WHERE tis_guid = @guid
				DELETE FROM tbTempItemStock WHERE tis_guid = @guid



				SET @return_value = @rv
				SET @errormessage = 'SaleOrder OK'


				COMMIT TRANSACTION


				-- Insrta la ORDEN con el JSon Original.
				INSERT INTO tbTiendaNube_Orders
				(
					comp_id,
					tn_id,
					tno_orderID,
					tno_JSon,
					bra_id,
					soh_id,
					cust_id
				)
				VALUES
				(
					@comp_id,
					@tn_id,
					@tno_orderID,
					@tno_JSon,
					@bra_id,
					@rv,
					@cust_id
				)




			END
			TRY BEGIN CATCH
				--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
				ROLLBACK TRANSACTION
				SET @return_value = -1
				SET @errormessage = ERROR_MESSAGE()

			END CATCH

		END


	BEGIN TRY

		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------
		-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
		----------------------------------------------------------------------------------------------------------------
		IF @return_value > 0
		BEGIN



			DECLARE @strMailTo		NVARCHAR(4000)	= '',
					@subject		NVARCHAR(800)	= '',
					@strBody		NVARCHAR(800)	= '',
					@lsm_id			INT



			--recuparamos el email y el vendedor del cliente
			SELECT	@strMailTo		= tc.cust_email,
					@lsm_id				= tc.sm_id
				FROM	tbCustomer							tc		 WITH (NOLOCK)
				WHERE	tc.comp_id			= @comp_id
				AND		tc.cust_id			= @cust_id


--		IF @lsm_id IS NULL
--			SET @strMailTo = @strMailTo + ';' + (SELECT	twsn.ws_email_contact
--													FROM	tbWebSite_Names				twsn
--													WHERE	twsn.comp_id	= @comp_id
--													AND		twsn.ws_id		= @ws_id)
--
--		ELSE
--			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
--													FROM	tbSalesman					ts
--													WHERE	ts.comp_id		= @comp_id
--													AND		ts.sm_id		= @lsm_id)





			--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
			--se recupara el email del vendedor asignado al cliente

			SET @strMailTo = @strMailTo + ';' + (SELECT	ts.sm_email
														FROM	tbSalesman					ts
														WHERE	ts.comp_id		= @comp_id AND
																ts.sm_id		= @lsm_id)

			DECLARE @strFooter AS NVARCHAR(MAX)

			DECLARE @strMailFrom AS NVARCHAR(MAX)
			--SELECT	@subject	= ISNULL(tws.wst_SaleOrderSubject,'Pedido Nro:'),
			--		@strBody	= ISNULL(tws.wst_SaleOrderBody,''),
			--		@strMailFrom= ISNULL(tws.wst_SaleOrderMailFrom,''),
			--		@strFooter  = ISNULL(tws.wst_SaleOrderFooter,'')
			--	FROM tbWebServices tws	 WITH (NOLOCK)
			--	WHERE	tws.comp_id = @comp_id AND
			--			tws.wst_id  = @wst_id



			--agregamos al mensaje que enviaremos al body del email las siguientes partes:
			--número de pedido
			--cliente
			--vendedor si hay un vendedor asignado al clientes
			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

							(SELECT	tut.utexts_desc FROM tbsysUniqueTexts tut
							 WHERE	tut.lang_id = @lang_id AND tut.utexts_id = 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

							(SELECT tswn.word_desc
							 FROM	tbSysWordsNew	tswn	WITH (NOLOCK)
							 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 297) + ' ' + convert(varchar,@cust_id) + ' - ' +
							(SELECT tc.cust_name
							 FROM	tbCustomer		tc	WITH (NOLOCK)
							 WHERE	tc.comp_id = @comp_id AND tc.cust_id = @cust_id)

			IF NOT @lsm_id IS NULL
				BEGIN
					SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +

								(SELECT tswn.word_desc
								 FROM	tbSysWordsNew	tswn		 WITH (NOLOCK)
								 WHERE	tswn.lang_id = @lang_id AND tswn.wordsi_id = 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +
								(SELECT ts.sm_name
								 FROM	tbSalesman		ts			 WITH (NOLOCK)
								 WHERE	ts.comp_id = @comp_id AND ts.sm_id = @lsm_id)
				END


			SET @strBody = @strBody + CHAR(10) + CHAR(13) + ' <br> ' +  @strFooter

			--se envía el correo si se recuperaron direcciones de emails
			IF NOT @strMailTo IS NULL
				BEGIN

					exec spSystem_sendEMail
							@compId						= @comp_id,
							@precipients				= @strMailTo,
							@pcopy_recipients			= null,
							@psubject					= @subject,
							@pbody_format				= 'HTML',
							@pbody						= @strBody,
							@pfile_attachments			= null,
							@pReplyTo					= @strMailFrom,
							@pblind_copy_recipients		= '',
							@pUser_Id					= @user_id

				END

		END
		----------------------------------------------------------------------------------------------------------------
		----------------------------------------------------------------------------------------------------------------

	END TRY
	BEGIN CATCH
		SET @return_value = @return_value
	END CATCH

	-- Deja la auditoria de si se comunico o no TN via webhook para la carga de un pedido.
	BEGIN TRY
		UPDATE tbTiendaNube_Stores
			SET tn_lastWebHookCalled = GETDATE()
			WHERE	comp_id = @comp_id AND
					tn_id	= @tn_id
	END TRY
	BEGIN CATCH
	END CATCH



	--RETURN @return_value
	SELECT	@return_value	[code],
			@errormessage	[error_description]



END
GO





CREATE PROCEDURE [dbo].[spTiendaNube_insertSaleOrderItem]
(
	@comp_id		INT,
	@lang_id		INT,
	@bra_id			INT,
	@guid			UNIQUEIDENTIFIER,
	@stor_id		INT,
	@item_id		INT,
	@prli_id		INT,
	@item_qty		DECIMAL(18,5),
	@tis_price		DECIMAL(19,6),
	@curr_id		INT,
	@decTNCost		DECIMAL(19,4),		-- ACA VIENE EL RE PUTO PRECIO !!!!!!!!!
	@user_id INT
)
AS


BEGIN



	SET NOCOUNT ON

	BEGIN


		-- -------------------------------------------------------------------------------
		-- Testing
		-- -------------------------------------------------------------------------------
		/*
		DECLARE @comp_id	INT,
				@lang_id	INT,
				@bra_id		INT,
				@wst_id		INT,
				@stor_id	INT,
				@item_id	INT,
				@prli_id	INT,
				@item_qty	INT,
				@guid		UNIQUEIDENTIFIER,
				@tis_price		DECIMAL(19,6) = 9999,
				@curr_id		INT = 1,
				@decMLCost		DECIMAL(19,4) = 4444

		SELECT	@comp_id	= 1,
				@lang_id	= 2,
				@bra_id		= 1,
				@wst_id		= 10,
				@stor_id	= 3,
				@item_id	= 256,
				@prli_id	= 1,
				@item_qty	= 2,
				@guid		= '1ADEA5E1-C9B7-4A76-834D-C8919D74E552'
		*/
		-- -------------------------------------------------------------------------------





		BEGIN TRY


			DECLARE @ret_ErrorDescription	VARCHAR(1000)
			SET		@ret_ErrorDescription	= ''



			DECLARE @tis_priority INT
			EXEC spCounters_getNextValue
					@comp_id,
					@stor_id,
					1, --contador prioridades
					@counter_value = @tis_priority OUTPUT



			DECLARE @tis_itemDesc NVARCHAR(100) = 'ATENCIÓN: Artículo NO RELACIONADO'
			SELECT	@tis_itemDesc = ti.item_desc
				FROM	tbItem ti			WITH (NOLOCK)
				WHERE	ti.comp_id	= @comp_id
				AND		ti.item_id	= @item_id



			--DECLARE @curr_id	INT,
			--		@tis_price  DECIMAL(19,5)
			--SELECT	@curr_id	= tpli.curr_id,
			--		@tis_price	= tpli.prli_price
			--FROM	tbPriceListItems tpli
			--WHERE	tpli.comp_id	= @comp_id
			--AND		tpli.prli_id	= @prli_id
			--AND		tpli.item_id	= @item_id



			DECLARE	@getdate	DATETIME
			SET @getdate = GETDATE()


			DECLARE @rv INT

			DECLARE @wsID AS UNIQUEIDENTIFIER
			SET		@wsID = NEWID()

			SET @tis_price = @tis_price / dbo.fnNoZDiv( dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id) )

			-- Saca el Precio SIN IMPUESTOS del artículo
			--IF @item_id IS NOT NULL
				--BEGIN

				--	IF EXISTS(
				--					SELECT 1
				--						FROM tbItemAssociation tia					WITH (NOLOCK)
				--						WHERE	tia.comp_id = @comp_id AND
				--								tia.item_id = @item_id
				--	) -- AND 1 = 2
				--		BEGIN

				--				-- Esto es por si tienen diferentes impuestos cada item por lo que debo sacar un impuesto equivalente para el TOTAL

				--				-- Ver en **wefknjweknwe56423kllkh ya que en TODO logar donde se cargue un combo de esta manera se deberá hacer esto ! ! !
				--				DECLARE @decTaxEquivalent	AS DECIMAL(25,10)	= 0
				--				DECLARE @decTaxCoeficient	AS DECIMAL(25,10)	= 0
				--				DECLARE @intItemsQTY		AS INT				= 0
				--				-- Sumo el TOTAL de articulos
				--				SELECT  @intItemsQTY = @intItemsQTY + (tia.iasso_qty)
				--					FROM tbItemAssociation tia					WITH (NOLOCK)
				--					WHERE	tia.comp_id = @comp_id AND
				--							tia.item_id = @item_id


				--				-- Sumo Algebraicamente todos los IVA
				--				SELECT @decTaxEquivalent = @decTaxEquivalent + (ttn.tax_percentage * tia.iasso_qty)
				--					FROM tbItemAssociation tia					WITH (NOLOCK)
				--					INNER JOIN vwItemTaxesOnlyOneIvaTax  tit					WITH (NOLOCK)
				--						ON	tit.comp_id = tia.comp_id	AND
				--							tit.item_id = tia.item_id_1
				--					INNER JOIN tbTaxName  ttn					WITH (NOLOCK)
				--						ON	ttn.tax_id	= tit.tax_id	AND
				--							ttn.comp_id = tit.comp_id
				--					WHERE	tia.comp_id = @comp_id		AND
				--							tia.item_id = @item_id

				--				-- Sumo Algebraicamente todos los Impuestos Internos
				--				SELECT @decTaxEquivalent = @decTaxEquivalent + (ttn.tax_percentage * tia.iasso_qty)
				--					FROM tbItemAssociation tia										WITH (NOLOCK)
				--					INNER JOIN vwItemTaxesOnlyOneInternalTax  tit					WITH (NOLOCK)
				--						ON	tit.comp_id = tia.comp_id	AND
				--							tit.item_id = tia.item_id_1
				--					INNER JOIN tbTaxName  ttn					WITH (NOLOCK)
				--						ON	ttn.tax_id	= tit.tax_id	AND
				--							ttn.comp_id = tit.comp_id
				--					WHERE	tia.comp_id = @comp_id		AND
				--							tia.item_id = @item_id

				--				SET @decTaxEquivalent = @decTaxEquivalent / dbo.fnNoZDiv(@intItemsQTY)
				--				SET @decTaxCoeficient = @decTaxEquivalent / 100
				--				SET @decTaxCoeficient = @decTaxCoeficient + 1

				--				SET @tis_price = @tis_price / dbo.fnNoZDiv(@decTaxCoeficient)

				--		END
				--	ELSE
				--		BEGIN
				--			SET @tis_price = @tis_price / dbo.fnNoZDiv( dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id) )
				--		END

				--END


			DECLARE @intUserID AS INT = @user_id * -1
			DECLARE @intStorID AS INT = @stor_id * -1	-- INdica que viene de un WS



			EXEC spTempItemStock_insertData
				@comp_id,
				@guid,
				@tis_priority,
				@item_id,
				@tis_itemDesc,
				@tis_itemDesc,
				@curr_id,
				@item_qty,
				@item_qty,
				@prli_id,
				@tis_price,
				@intStorID /*@stor_id*/,
				0,						--@doc_id
				@bra_id,
				@intUserID /*@user_id*/,
				@getdate,				--@insertDate = null,
				@getdate,				--@lastUpdate = null,
				0,						--@tis_cost = null,
				1,						--@tis_costTax = null,
				null,					--@soh_id = null,
				null,					--@sod_id = null,
				'true',					--@to_associate = null,
				null,					--@is_id = null,
				'false',				--@tis_isMade = null,
				@wsID,'',
				-1,
				@return_value = @rv OUTPUT



			--para que no borre los items el depurador
			UPDATE tbTempItemStock	WITH (ROWLOCK)
				SET	tis_IsEditingCd = DATEADD(hour,1,GETDATE())--,
					--sod_MLCost		= ISNULL(@decTNCost,0)

				WHERE tis_id = @rv


			SET		@ret_ErrorDescription	= 'Insert OK'
			--SELECT @rv [code],



		END TRY
		BEGIN CATCH

				Set @rv			= -1
				Set @ret_ErrorDescription	= 'Item_Insert - ' +
					(SELECT
					convert(varchar,ERROR_NUMBER())		+ '-' +
					convert(varchar,ERROR_SEVERITY())	+ '-' +
					convert(varchar,ERROR_STATE())		+ '-' +
					convert(varchar,ERROR_LINE())		+ '-' +
					ERROR_MESSAGE())

		END CATCH


		SELECT	@rv						[code],
				@ret_ErrorDescription	[error_description]

	END

END
GO

CREATE PROCEDURE [dbo].[spTiendaNube_ItemsRelations_GetDataById]
(
	@comp_id	INT,
	@tn_id		INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			ttnir.comp_id,
			ttnir.tn_id,
			ttnir.item_id,
			ttnir.tnr_disabled,
			ttnir.tnr_lastPrice,
			ttnir.tnr_lastExchange,
			ttnir.tnr_lastStock,
			ttnir.tnr_id,
			ttnir.tnr_variationID,
			ttnir.tnr_lastExecError,
			ttns.tn_storeID,
			ttns.tn_useragent,
			ttns.tn_accesTocken,
			ttnir.tnr_relationID,
			ttnir.tnr_LastErrorDescription
			FROM tbTiendaNube_ItemsRelations		ttnir	WITH(NOLOCK)
			INNER JOIN tbTiendaNube_Stores			ttns	WITH(NOLOCK)
			ON	ttns.comp_id		= ttnir.comp_id AND
				ttns.tn_id			= ttnir.tn_id
			WHERE	ttnir.comp_id	= @comp_id		AND
					ttnir.tn_id		= @tn_id		AND
					ttnir.item_id	= @item_id
	END
GO

