CREATE PROCEDURE [dbo].[spTiendaNube_ItemsRelations_GetDataByVariationID]
(
	@comp_id			INT,
	@tn_id				INT,
	@product_id			BIGINT,
	@variation_id		BIGINT
)
AS
	BEGIN

		SET NOCOUNT ON

		DECLARE @intItemID AS INT = -1

		SELECT  @intItemID = ttnir.item_id
			FROM tbTiendaNube_ItemsRelations AS ttnir	WITH (NOLOCK)
			WHERE	ttnir.comp_id			= @comp_id			AND
					ttnir.tn_id				= @tn_id			AND
					ttnir.tnr_id			= @product_id		AND
					ttnir.tnr_variationID	= @variation_id

		IF @intItemID = -1
			BEGIN
				SELECT  @intItemID = ttnir.item_id
					FROM tbTiendaNube_ItemsRelations AS ttnir	WITH (NOLOCK)
					WHERE	ttnir.comp_id			= @comp_id			AND
							ttnir.tn_id				= @tn_id			AND
							ttnir.tnr_variationID	= @variation_id
			END


		SELECT @intItemID

	END
GO

CREATE PROCEDURE [dbo].[spTiendaNube_ItemsRelations_InsertData]
(
	@comp_id			INT,
	@tn_id				INT,
	@item_id			INT,
	@tnr_disabled		BIT,
	@tnr_lastPrice		DECIMAL(19,4),
	@tnr_lastExchange	DECIMAL(19,4),
	@tnr_lastStock		INT,
	@product_id			BIGINT,
	@variant_id			BIGINT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------
		-- TESTING
		-- ------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@tn_id				INT,
				@item_id			INT,
				@tnr_disabled		BIT,
				@tnr_lastPrice		DECIMAL(19,4),
				@tnr_lastExchange	DECIMAL(19,4),
				@tnr_lastStock		INT
		*/
		-- ------------------------------------

		IF NOT EXISTS (SELECT 1 FROM tbTiendaNube_ItemsRelations ttnir WITH (NOLOCK) WHERE ttnir.comp_id = @comp_id AND ttnir.tn_id = @tn_id AND ttnir.item_id = @item_id)
			BEGIN
				INSERT INTO tbTiendaNube_ItemsRelations
				(
					comp_id,
					tn_id,
					item_id,
					tnr_disabled,
					tnr_lastPrice,
					tnr_lastExchange,
					tnr_lastStock,
					tnr_id,
					tnr_variationID,
					tnr_LastUpdate
				)
				VALUES
				(
					@comp_id,
					@tn_id,
					@item_id,
					@tnr_disabled,
					@tnr_lastPrice,
					@tnr_lastExchange,
					@tnr_lastStock,
					@product_id,
					@variant_id,
					GETDATE()
				)
			END
	END
GO

