CREATE PROCEDURE [dbo].[spTMPFiles_AFIPVerifications]
AS
BEGIN
	SET NOCOUNT ON


	---- Si NO hay nada para mandar se va . . .
	IF NOT EXISTS
					(
						SELECT TOP 1  1
							FROM tbAFIPVerifications AS ta		WITH (NOLOCK)
							WHERE ta.ctv_isVerified = 'false'
					)
		BEGIN
			RETURN
		END

	-- ----------------------------------------------------------------------------
	-- Anvio de Mails desde BD
	-- ----------------------------------------------------------------------------
	-- ATENCION:

	DECLARE @Response AS VARCHAR(MAX)

	BEGIN

		DECLARE @Obj		int
		DECLARE @Result		int
		DECLARE @HTTPStatus int
		DECLARE curComp2Check  CURSOR LOCAL FAST_FORWARD FOR
		SELECT 	TOP 1
				tc.comp_id,
				tc.comp_ServerFULLURL2Acces
			FROM tbCompany tc							WITH (NOLOCK)
			INNER JOIN tbbranch	AS tb					WITH (NOLOCK)
				ON tb.comp_id = tc.comp_id
			WHERE
					tb.bra_disabled = 0 AND
					tb.df_id4AFIPConstatacionDeComprobantes IS NOT NULL AND
					dbo.fnStrAllTrim(ISNULL(tc.comp_ServerFULLURL2Acces,'')) <> ''

		DECLARE		@curCompID	AS INT	= -1
		DECLARE		@strIMAPURL AS NVARCHAR(200)
		OPEN		curComp2Check
		FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL
		WHILE @@FETCH_STATUS = 0
			BEGIN

				BEGIN TRY
					SELECT	@strIMAPURL =  @strIMAPURL + 'wfmAFIPVerificationsProcessCaller.aspx?QSCompID=' + CONVERT(NVARCHAR(20),@curCompID)
					SELECT  @Response   =  dbo.clrActivateURL(@strIMAPURL)
					--SELECT @strIMAPURL,@Response
				END TRY
				BEGIN CATCH
				END CATCH

				FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL

			END
		CLOSE		curComp2Check
		DEALLOCATE	curComp2Check

	END
	-- ----------------------------------------------------------------------------




END
GO

