CREATE PROCEDURE [dbo].[spTMPFiles_AIfilesGeneration]
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	BEGIN
		BEGIN TRY

			TRUNCATE TABLE tbIAData_SalesBySubcategoryAndStorageGroup

			DECLARE @intComp_Id			AS INT		= 1
			DECLARE @datFrom			AS DATETIME = DATEADD(MONTH	,-2,GETDATE())
			DECLARE @datTo				AS DATETIME = GETDATE()
			DECLARE @datFromLastYear	AS DATETIME = DATEADD(YEAR	,-1,@datFrom)
			DECLARE @datToLastYear		AS DATETIME = DATEADD(YEAR	,-1,@datTo)
			DECLARE @intStorg_id		AS INT      = 1
			DECLARE @tblStorage			TABLE (stor_id INT PRIMARY KEY)

			DECLARE curBranches CURSOR LOCAL FAST_FORWARD FOR
				SELECT DISTINCT tb.comp_id,
								tb.bra_IAData_storg_id
					FROM tbBranch AS tb	WITH (NOLOCK)
					WHERE	tb.bra_IAData_enabled	= 'True'		AND
							tb.bra_IAData_storg_id	IS NOT NULL		AND
							tb.bra_disabled			= 'False'

			OPEN curBranches

			FETCH NEXT FROM curBranches INTO @intComp_Id,@intStorg_id
			WHILE @@FETCH_STATUS = 0
				BEGIN
					DELETE FROM 	@tblStorage
					INSERT INTO		@tblStorage
					(
						stor_id
					)
						SELECT tsgd.stor_id
							FROM	tbStorageGroupDetail AS tsgd			WITH (NOLOCK)
							WHERE	tsgd.comp_id	= @intComp_Id		AND
									tsgd.storg_id	= @intStorg_id



					;WITH cteTMP (comp_id,storg_id,subcat_id,ic_id,item_id,Qty,state_id,inLiquidationCount) AS
						(
							SELECT	tit.comp_id,
									@intstorg_id			[storg_id],
									ti.subcat_id,
									ti.ic_id,
									tit.item_id,
									SUM(tit.it_qty)			[Qty],
									tct.state_id,
									COUNT(	CASE
												WHEN ti.item_liquidation='True' THEN 1
												ELSE								 NULL
											END	)			[inLiquidationCount]
								FROM tbItemTransactions					AS tit		WITH (NOLOCK)
								INNER JOIN @tblStorage					AS ts
									ON ts.stor_id = tit.stor_id
								INNER JOIN vwItemTransactions_forSales	AS vitfs	WITH (NOLOCK)
									ON	vitfs.comp_id			= tit.comp_id			AND
										vitfs.comp_id			= tit.bra_id			AND
										vitfs.ct_transaction	= tit.ct_transaction	AND
										vitfs.it_transaction	= tit.it_transaction
								INNER JOIN tbcommercialtransactions		AS tct		WITH (NOLOCK)
									ON	tct.comp_id				= tit.comp_id			AND
										tct.bra_id				= tit.bra_id			AND
										tct.ct_transaction		= tit.ct_transaction
								INNER JOIN tbItem						AS ti		WITH (NOLOCK)
									ON	ti.comp_id				= tit.comp_id			AND
										ti.item_id				= tit.item_id
								INNER JOIN tbSubCategory				AS tsc		WITH (NOLOCK)
									ON	tsc.comp_id				= ti.comp_id			AND
										tsc.cat_id				= ti.cat_id				AND
										tsc.subcat_id			= ti.subcat_id
								LEFT JOIN tbItemClass					AS tic		WITH (NOLOCK)
									ON	tic.comp_id				= ti.comp_id AND
										tic.ic_id				= ti.ic_id
								WHERE	tit.comp_id				= @intComp_Id			AND
										vitfs.sd_isCredit		= 'False'				AND
										ti.item_disabled		= 'False'				AND
										tsc.subcat_IAEnabled	= 'True'				AND
										ISNULL(tic.ic_isSelectable,'False') = 'True'	AND
										(
											(ti.item_cd BETWEEN @datFrom AND @datTo)
												OR
											(ti.item_cd BETWEEN @datFromLastYear AND @datToLastYear)
										)
								GROUP BY	tit.comp_id,
											ti.subcat_id,
											ti.ic_id,
											tit.item_id,
											tct.state_id,
											ts.stor_id
								HAVING	dbo.fnGetAStock(tit.comp_id, ts.stor_id,tit.item_id,999999999) > 0
						)
						SELECT	comp_id,
								subcat_id,
								ic_id,
								storg_id,
								state_id,
								SUM(Qty)			[Qty],
								inLiquidationCount
							INTO #tbIAData_SalesBySubcategoryAndStorageGroup
							FROM cteTMP
							GROUP BY comp_id, storg_id, subcat_id,ic_id, state_id 	,inLiquidationCount



						INSERT INTO tbIAData_SalesBySubcategoryAndStorageGroup
						(
							comp_id,
							subcat_id,
							ic_id,
							storg_id,
							state_id,
							QTY,
							inLiquidationCount
						)
							SELECT comp_id, subcat_id,ic_id,storg_id, state_id, SUM(Qty) ,COUNT(inLiquidationCount) - 1
								FROM #tbIAData_SalesBySubcategoryAndStorageGroup
								GROUP BY comp_id, subcat_id,ic_id,storg_id, state_id

						DROP TABLE #tbIAData_SalesBySubcategoryAndStorageGroup

					FETCH NEXT FROM curBranches INTO @intComp_Id,@intStorg_id
				END


			CLOSE curBranches
			DEALLOCATE curBranches

		END TRY
		BEGIN CATCH
		END CATCH
	END

END
GO



