-- Author:		MOS  05-2020
-- =============================================
CREATE PROCEDURE [dbo].[spTMPFiles_CommunityServicesCaller]

AS
BEGIN

	SET NOCOUNT ON;


	DECLARE @strDBName AS nVARCHAR(100)
	SET		@strDBName = db_name()
	DECLARE @URL		VARCHAR(8000)
	DECLARE @Response	varchar(8000)
	DECLARE @XML		xml
	DECLARE @Obj		int
	DECLARE @Result		int
	DECLARE @HTTPStatus int
	DECLARE @ErrorMsg	varchar(MAX)
	DECLARE @comp_id					AS INT
	DECLARE @commc_intervalInMinutes	AS INT = 0
	DECLARE @commc_lastExecute			AS DATETIME = GETDATE()
	DECLARE @commc_id					AS INT

	DECLARE curStoresToProcess CURSOR LOCAL FAST_FORWARD FOR
		SELECT DISTINCT tc.comp_id	,
						tc.comp_ServerFULLURL2Acces,
						CASE
							WHEN ISNULL(tccc.commc_intervalInMinutes,0) > 0 THEN tccc.commc_intervalInMinutes
							ELSE 30
						END,
						ISNULL(tccc.commc_lastExecute,GETDATE()),
						tccc.commc_id
			FROM tbCommunity_ClientConfiguration AS tccc	WITH (NOLOCK)
			INNER JOIN tbCompany AS tc WITH (NOLOCK)
				ON tc.comp_id = tccc.comp_id
			WHERE	tccc.coslis_id	IS NOT NULL AND
					tccc.stor_id	IS NOT NULL AND
					tccc.commc_disabled = 'False'

	OPEN curStoresToProcess
	FETCH NEXT FROM curStoresToProcess INTO @comp_id,
											@URL,
											@commc_intervalInMinutes,
											@commc_lastExecute,
											@commc_id
	WHILE @@FETCH_STATUS = 0
		BEGIN

			IF DATEADD(MINUTE,@commc_intervalInMinutes ,@commc_lastExecute) < GETDATE()
				BEGIN
					-- En realidad la Caller llama a la queue pero con un timeout muy chico para que no atrase al resto de las ejecuciones de este proceso en BAT o JOB
					SELECT	@URL =  @url + '/wfmCommunityServicesCaller.aspx?comp_id=' + dbo.fnStrAllTrim(CONVERT(NVARCHAR(10),@comp_id))
					SELECT  dbo.clrActivateURL(@url)

					UPDATE tbCommunity_ClientConfiguration WITH (ROWLOCK)
						SET	commc_lastExecute = GETDATE()
						WHERE	comp_id		= @comp_id AND
								commc_id	= @commc_id
				END

			FETCH NEXT FROM curStoresToProcess INTO @comp_id,
										@URL,
										@commc_intervalInMinutes,
										@commc_lastExecute,
										@commc_id
		END
	CLOSE		curStoresToProcess
	DEALLOCATE	curStoresToProcess


END
GO

