-- =============================================
CREATE PROCEDURE [dbo].[spTMPFiles_IMAP_getEmails]
AS
BEGIN
	SET NOCOUNT ON

	-- ----------------------------------------------------------------------------
	-- CRM
	-- Chequea eMails IMAP	de todos los habilitados en las Compañias de la Base de Datos
	-- Se libera al toque al llamar a la pagina Caller y queda en proceso en el POOL correspondiente
	-- ----------------------------------------------------------------------------
	-- ATENCION:
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbCompany tc	WITH (NOLOCK)
					WHERE tc.comp_POP3CheckEnabled = 'True'
				)
		BEGIN

			DECLARE @Obj		int
			DECLARE @Result		int
			DECLARE @HTTPStatus int
			DECLARE curComp2Check  CURSOR LOCAL FAST_FORWARD FOR
			SELECT DISTINCT	tumar.comp_id,tc.comp_ServerFULLURL2Acces
				FROM tbUserMailsAccountsRelation tumar				WITH (NOLOCK)
					inner JOIN tbCompany tc							WITH (NOLOCK)
						ON tc.comp_id	= tumar.comp_id
					INNER JOIN tbuser	tu							WITH (NOLOCK)
						ON tu.[user_id] = tumar.[user_id]
				WHERE
						tumar.ue_disabled				= 'False'	AND
						IsNull(tu.user_Blocked,'False') = 'False'	AND
						tc.comp_POP3CheckEnabled		= 'True'

			DECLARE		@curCompID	AS INT	= -1
			DECLARE		@strIMAPURL AS NVARCHAR(200)
			OPEN		curComp2Check
			FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL
			WHILE @@FETCH_STATUS = 0
				BEGIN

					BEGIN TRY
						SELECT	@strIMAPURL =  @strIMAPURL + 'wfmCRM_GetEmailsCaller.aspx?QSCompID=' + CONVERT(NVARCHAR(20),@curCompID)
						SELECT  dbo.clrActivateURL(@strIMAPURL)
					END TRY
					BEGIN CATCH
					END CATCH

					FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL

				END
			CLOSE		curComp2Check
			DEALLOCATE	curComp2Check

		END
	-- ----------------------------------------------------------------------------




END
GO



-- --------------------------------------------------------------
-- MOS
-- Procesos Varios a Ejecutarse frecuentemente.
-- --------------------------------------------------------------


-- Log
-- MOS 05-2024: Saque todas las transacciones que estaban AL PEDO en este punto.
-- MOS 09-2024: Agregue los timestamp para ver que parte tarda.





CREATE pROCEDURE [dbo].[spTMPFiles_IsEditingPurgeStatus]
AS


-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2011-01-18
-- Parte		: S/P Referencia: #1
-- Description	: Se agrega la eliminación de la temporal de RMA
-- =================================================================================================================
BEGIN

	set nocount ON
	--SET LOCK_TIMEOUT 250				MOS 05-2024: NO PONER ACA!!!
	--SET DEADLOCK_PRIORITY LOW			MOS 05-2024: NO PONER ACA!!!
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED

	SET DATEFIRST 7		-- Domingo x Defecto



	SELECT ' Step 000:',GETDATE()



	-- ----------------------------------
	-- Depurar lo muy viejo menor a DOS dias
	-- ----------------------------------
	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD( day, -2, getdate())
	-- ----------------------------------


	DECLARE @bitCanIDoIt AS BIT
	DECLARE @intRowCount AS INT = 0


	-- ----------------------------------
	-- Cierre Diario Automático
	-- A partir de las 00 y hasta las 05
	-- SIEMPRE PRIMERO !!!
	-- ----------------------------------
	DECLARE @bitDaylyCloseDone AS BIT = 'False'
	IF (
			DATEPART(hh,GETDATE()) BETWEEN 0 AND 5
	   )
		BEGIN

			DECLARE @datNewDate				AS DATETIME
			SET		@datNewDate = DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE()))

			IF EXISTS(	SELECT TOP 1 1
		          			FROM tbBranch tb	WITH (NOLOCK)
		          			WHERE	IsNull(tb.bra_CloseDaily_IsAutomatic,'False') = 'True'	AND
		          					IsNull(tb.bra_disabled,'False')='False'					AND
		          					tb.bra_processingDate <> @datNewDate
					  )
				BEGIN

					DECLARE @intCompId				AS INT
					DECLARE @intBraId				AS INT
					DECLARE @intProfile4AutoClose	AS INT
					DECLARE @intUser4AutoClose		AS INT
					DECLARE @intReturnValue			AS INT


					DECLARE curBranchs  CURSOR LOCAL  FAST_FORWARD FOR
						SELECT tb.comp_id,tb.bra_id,tb.bra_CloseDaily_prof_id,tb.bra_CloseDaily_user_id
		          			FROM tbBranch tb	WITH (NOLOCK)
		          			WHERE	tb.bra_CloseDaily_IsAutomatic = 'True'	AND
		        					IsNull(tb.bra_disabled,'False')='False'	AND
		          					tb.bra_processingDate <> @datNewDate
							ORDER BY  bra_id ASC

					OPEN curBranchs
					FETCH NEXT FROM curBranchs			INTO @intCompId,@intBraId,@intProfile4AutoClose,@intUser4AutoClose
					WHILE @@FETCH_STATUS = 0
						BEGIN
							SET  @bitDaylyCloseDone = 'True'
							BEGIN TRY -- MOS 05-2024: Lo puse en un Try x si explota para quie siga con el resto
								EXEC spBranch_updateData	@intCompId,
															@intBraId,
															@datNewDate,
															@intUser4AutoClose,
															@intProfile4AutoClose,
															'True',
															@intReturnValue
							END TRY
							BEGIN CATCH
							END CATCH
							FETCH NEXT FROM curBranchs INTO @intCompId,@intBraId,@intProfile4AutoClose,@intUser4AutoClose
						END
					CLOSE curBranchs
					DEALLOCATE curBranchs
					EXEC spSaleOrderHeader_PurchaseOrderRelation_IntegrityVerification
					--
				END
		END
	-- ----------------------------------



	SELECT ' Step 001:',GETDATE()




	SET LOCK_TIMEOUT 250			--	MOS 05-2024:  PONER ACA!!!  Luego del Cierre Diario
	SET DEADLOCK_PRIORITY LOW		--	MOS 05-2024:  PONER ACA!!!


	-- ----------------------------------
	-- Convertir Pedidos de Monotributo
	-- de B a A           MONOTRIBUTO a A
	-- ----------------------------------
	BEGIN TRY

		IF	DATEPART(hh,GETDATE()) BETWEEN 2 AND 3 AND
			EXISTS(
					SELECT TOP 1 1
						FROM tbCompany AS tc WITH (NOLOCK)
						WHERE comp_convertSOB2A4MonoT = 1
					)
			BEGIN
				--IF EXISTS(
				--			SELECT TOP 1 1
				--				FROM tbSystem_DatabaseVersion AS tsdv  WITH (NOLOCK)
				--				WHERE tsdv.monoTributoB2AConverted = 0
				--			)
					BEGIN
						UPDATE tbSaleOrderHeader
							SET df_id = tdf2.df_id
							FROM tbSaleOrderHeader		soh			WITH (NOLOCK)
							INNER JOIN tbCompany		AS tc2		WITH (NOLOCK)
								ON tc2.comp_id				= soh.comp_id	AND
								tc2.comp_convertSOB2A4MonoT = 1
							INNER JOIN tbDocumentsFile	AS tdf		WITH (NOLOCK)
								ON	tdf.comp_id			= soh.comp_id	AND
									tdf.df_id			= soh.df_id		AND
									tdf.df_Kindof		= 'B'			AND
									tdf.df_Disabled		= 0				AND
									tdf.df_favorite4ML	= 1
							INNER JOIN tbDocumentsFile	AS tdf2		WITH (NOLOCK)
								ON	tdf2.comp_id		= tdf.comp_id	AND
									tdf2.bra_id			= tdf.bra_id	AND
									tdf2.sd_id			= tdf.sd_id		AND
									tdf2.df_Kindof		= 'A'			AND
									tdf2.df_Disabled	= 0				AND
									tdf2.df_favorite4ML					= tdf.df_favorite4ML				AND
									tdf2.df_favorite4WebSite			= tdf.df_favorite4WebSite			AND
									tdf2.df_favorite4fullJaus			= tdf.df_favorite4fullJaus			AND
									tdf2.df_favorite4ChequeRejection	= tdf.df_favorite4ChequeRejection
							INNER JOIN tbCustomer		AS tc		WITH (NOLOCK)
								ON	tc.comp_id	= soh.comp_id	AND
									tc.cust_id	= soh.cust_id	AND
									tc.fc_id			= 3
							WHERE	tdf.sd_id	IN (1,3,4)

						UPDATE tbCompany
							SET	comp_convertSOB2A4MonoT = 0
						SELECT 'Se convirtieron documentos por Monotributo de B a A'
					END
			END

	END TRY
	BEGIN CATCH
	END CATCH
	-- ----------------------------------


	SELECT ' Step 002:',GETDATE()

	-- ----------------------------------
	-- Procesos Nocturnos
	-- ----------------------------------
	SET @bitCanIDoIt = 'False'
	IF (
			DATEPART(hh,GETDATE()) BETWEEN 2 AND 5
	   )
	BEGIN

		EXEC spSystem_LastExecutionControl_CanDoIt -1,
												   -1,
												10849901,
												   20,	-- MOS 02-2022, era cada 10 y lo pase a cada 20.         cada 10 minutos hace el recalculo.!
										 @bitCanIDoIt OUTPUT
		IF @bitCanIDoIt = 'True'
			BEGIN
				EXEC spsystem_dailyDatabaseMaintenance
			END

	END
	-- ----------------------------------


	SELECT ' Step 003:',GETDATE()

	-- ----------------------------------
	-- Procesos Nocturnos
	-- ----------------------------------
	IF (
			DATEPART(hh,GETDATE()) = 2
	   )
	BEGIN

		-- ----------------------------------
		-- Verificacion en tbCheckPortfolio
		-- Paso en Nucleo que algunos valores
		-- tenial alguno de estos campos
		-- en NULL
		-- ----------------------------------
		BEGIN TRY
			IF EXISTS(
						SELECT TOP 1 1
							FROM tbCheckPortfolio			WITH (NOLOCK)
							WHERE
								chp_isOwn			IS NULL OR
								chp_isAvailable		IS NULL OR
								chp_IsPayed			IS NULL OR
								chp_isRejected		IS NULL OR
								chp_isCancelled		IS NULL OR
								chp_isToOrder		IS NULL OR
								chp_isDocument		IS NULL OR
								chp_isNegociated	IS NULL
					)
			BEGIN
				UPDATE tbCheckPortfolio	--WITH (ROWLOCK)
				SET chp_isOwn			= ISNULL(chp_isOwn,'False'),
					chp_isAvailable		= ISNULL(chp_isAvailable,'False'),
					chp_IsPayed			= ISNULL(chp_IsPayed,'False'),
					chp_isRejected		= ISNULL(chp_isRejected,'False'),
					chp_isCancelled		= ISNULL(chp_isCancelled,'False'),
					chp_isToOrder		= ISNULL(chp_isToOrder,'False'),
					chp_isDocument		= ISNULL(chp_isDocument,'False'),
					chp_isNegociated	= ISNULL(chp_isNegociated,'False'),
					chp_Note			= ISNULL(chp_Note,'')
				WHERE
					chp_isOwn			IS NULL OR
					chp_isAvailable		IS NULL OR
					chp_IsPayed			IS NULL OR
					chp_isRejected		IS NULL OR
					chp_isCancelled		IS NULL OR
					chp_isToOrder		IS NULL OR
					chp_isDocument		IS NULL OR
					chp_isNegociated	IS NULL
			END
		END TRY
		BEGIN CATCH
		END CATCH
		-- ----------------------------------


		-- Borra los cheques ingresados en Temporal NO procesados
		BEGIN TRY
			--BEGIN TRANSACTION
				DELETE FROM tbCheckPortfolioTmp		--WITH (ROWLOCK)
					WHERE chpt_isEditingCD < DATEADD(hour,-12,GETDATE())  -- @DeleteTime
			--COMMIT TRANSACTION
			--CHECKPOINT
		END TRY
		BEGIN CATCH
		END CATCH




		-- ------------------------------------------------------------
		-- Repara mierdas de imprtacion de publicaciones
		-- ------------------------------------------------------------
				-- Con esto vemos las publicaciones que tienen MIERDA en el ID de variacion.
				--SELECT DISTINCT tmlip.mlp_publicationID
				--FROM tbMercadoLibre_ItemsPublicadosVariations yy
				--INNER JOIN tbMercadoLibre_ItemsPublicados tmlip
				--ON tmlip.comp_id = yy.comp_id AND tmlip.mlp_id = yy.mlp_id
				--WHERE yy.mlpv_disabled = 0 AND yy.MLVariationID < 999999

				-- Con esto borramos las variaciones deshabilitadas con ID asignado ( sin atributos )
				-- DELETE FROM tbMercadoLibre_ItemsPublicadosVariations WHERE  MLVariationID > 999999 AND mlpv_disabled = 1
		BEGIN TRY
				EXEC('UPDATE  tbMercadoLibre_ItemsPublicadosVariations SET mlpv_disabled = 1 WHERE  mlpv_disabled = 0 AND MLVariationID < 99999')
		END TRY
		BEGIN CATCH
		END CATCH
		-- ------------------------------------------------------------










		BEGIN TRY
			--BEGIN TRANSACTION
				DELETE FROM  tbGlobalChanges_Percentages	WITH (TABLOCK)
					WHERE tmpCD < @deletetime
			--COMMIT TRANSACTION
			--CHECKPOINT
		END TRY
		BEGIN CATCH
		END CATCH


		BEGIN TRY
			--BEGIN TRANSACTION
				DELETE FROM  tbItemTmp	--WITH (TABLOCK)
			--COMMIT TRANSACTION
			--CHECKPOINT
		END TRY
		BEGIN CATCH
		END CATCH

		BEGIN TRY
			--BEGIN TRANSACTION
				DELETE FROM  tbsysprueba	--WITH (TABLOCK)
			--COMMIT TRANSACTION
			--CHECKPOINT
		END TRY
		BEGIN CATCH
		END CATCH


	END
	-- ----------------------------------



	SELECT ' Step 004:',GETDATE()




	-- ----------------------------------
	-- Procesos Horarios
	-- ----------------------------------
	IF (
			DATEPART(mm,GETDATE()) BETWEEN 1 AND 25
			OR
			DATEPART(hh,GETDATE()) BETWEEN 3 AND 3
	   )
		BEGIN




			-- ----------------------------------
			-- Borra Temporales
			-- ----------------------------------
			BEGIN TRY
				--BEGIN TRANSACTION
					DELETE FROM tbTaxMovementsTmp		--WITH (TABLOCK)
						WHERE tmt_isEditingCD	< @DeleteTime

					DELETE FROM tbPurchaseOrderDetailTmp	--WITH (TABLOCK)
						WHERE	pod_PurgeDate	< @DeleteTime

					DELETE FROM tbRMA_Detail_Tmp	--WITH (TABLOCK)
					WHERE		rmadt_purgeDate < @DeleteTime

					DELETE tbAccountTransactionDetailTmp	--WITH (TABLOCK)
						WHERE	acc_purgeDate	< @DeleteTime
				--COMMIT TRANSACTION
				--CHECKPOINT
			END TRY
			BEGIN CATCH
			END CATCH
			-- ----------------------------------

			-- ----------------------------------
			-- Advertencias de CRM
			-- Envia las advertencias los 10
			-- en llamados de los 10 prim min
			-- de cada hora.
			-- ----------------------------------
			BEGIN TRY
					EXEC spCRM_Case_SendNotifications
					EXEC spCRM_Task_SendNotifications
					EXEC spCRM_Call_SendNotifications
					EXEC spCRM_Meet_SendNotifications
			END TRY
			BEGIN CATCH
			END CATCH


		END
	-- ----------------------------------



	SELECT ' Step 005:',GETDATE()



	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- Recalcular stock potencial
	-- para ser usado para ORDEN y ganar
	-- mas velocidad
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	SET @bitCanIDoIt = 'False'
	EXEC spSystem_LastExecutionControl_CanDoIt -1,
											   -1,
										    10901,
										       45,	-- MOS 11-2022, era cada 20 y lo pase a cada 45.         cada 10 minutos hace el recalculo.!
								     @bitCanIDoIt OUTPUT


	IF @bitCanIDoIt = 'True'
		BEGIN

			--  1ro RESETEA a NULL los que se pudiesen haber calculado y  ya no se necesiten calcular
			--BEGIN TRANSACTION
				UPDATE tbItemStorage	--WITH (ROWLOCK)
					SET
						itst_LastAvailableInRelalculation = NULL
					FROM tbItemStorage tis		WITH (NOLOCK)
					INNER JOIN tbStorage ts WITH (INDEX(PK__tbStorage__0F624AF8), NOLOCK)
						ON	ts.comp_id = tis.comp_id AND
							ts.stor_id = tis.stor_id
					WHERE	tis.itst_LastAvailableInRelalculation IS NOT NULL AND
							ts.stor_mustRecalculateAvailableStock = 'False'
			--COMMIT TRANSACTION
			--CHECKPOINT

		END


	SELECT ' Step 006:',GETDATE()

	IF	@bitCanIDoIt = 'True'	 AND
		EXISTS(
					SELECT TOP 1  1
						FROM tbStorage ts	WITH (NOLOCK)
						WHERE ts.stor_mustRecalculateAvailableStock = 'True'
				)
		BEGIN

			-- SELECT ' Lo HIce!!'
			-- Crea una tabla Temporal con los items que tengan stock para que no tenga que verificar todos los articulos
			-- Pone solo 1 item_id
			DECLARE @tbFastSearch TABLE(item_id INT PRIMARY KEY)
			-- ------------------
			-- INserta todos los Items y Combos
			-- ------------------
			INSERT INTO @tbFastSearch
						( item_id )
				SELECT	distinct
						tis.item_id
					FROM tbItemStorage tis					WITH (NOLOCK)
					INNER JOIN tbStorage ts					WITH (NOLOCK)
						ON	ts.comp_id = tis.comp_id	AND
							ts.stor_id = tis.stor_id
					INNER JOIN tbStorageGroupDetail tsgd	WITH (NOLOCK)
					ON	tsgd.comp_id = ts.comp_id AND
						tsgd.stor_id = ts.stor_id
				GROUP BY tis.comp_id,tis.item_id
				HAVING SUM(tis.itst_cant) > 0

				UNION

				SELECT	distinct
									tia.item_id
					FROM tbItemAssociation tia
					INNER JOIN tbItemStorage tis					WITH (NOLOCK)
						ON	tis.comp_id = tia.comp_id					AND
							tis.item_id = tia.item_id_1
					INNER JOIN tbStorage ts					WITH (NOLOCK)
						ON	ts.comp_id = tis.comp_id	AND
							ts.stor_id = tis.stor_id
					INNER JOIN tbStorageGroupDetail tsgd	WITH (NOLOCK)
						ON	tsgd.comp_id = ts.comp_id AND
							tsgd.stor_id = ts.stor_id

					GROUP BY tis.comp_id,tia.item_id
					HAVING SUM(tis.itst_cant) > 0
			-- ------------------


			-- Pone en NULL los que no tienen mov **VER
			--BEGIN TRANSACTION
				UPDATE tbItemStorage	--WITH (ROWLOCK)
					SET
						itst_LastAvailableInRelalculation = NULL
					FROM tbItemStorage tis		WITH (NOLOCK)
					LEFT JOIN @tbFastSearch fs						-- Dejar ACA por Velocidad
						ON fs.item_id = tis.item_id
					INNER JOIN tbStorage ts							WITH (NOLOCK)
						ON	ts.comp_id = tis.comp_id AND
							ts.stor_id = tis.stor_id

					WHERE	tis.itst_LastAvailableInRelalculation IS NOT NULL				AND
							ISNULL(ts.stor_mustRecalculateAvailableStock,'False') = 'True'	AND
							fs.item_id IS NULL
			--COMMIT TRANSACTION
			--CHECKPOINT

			-- Inserta en tbItemStorage un registro si es que no tiene el item
			-- para los depositos que deben hacer recalculo de disponibles.
			SELECT	ti.comp_id,
					ts.stor_id,
					ti.item_id,
					0				[itst_cant],
					GETDATE()		[itst_cd],
					''				[itst_PickingLocation],
					''				[itst_StorageLocation],
					'False'			[itst_updateByInTransitStock],
					NULL			[itst_LastAvailableInRelalculation]
				INTO #tmpItemStorage
				FROM tbItem						ti		WITH (NOLOCK)
				INNER JOIN tbStorage			ts		WITH (NOLOCK)
					ON ti.comp_id = ts.comp_id
				LEFT JOIN tbItemStorage			tis		WITH (NOLOCK)
					ON	tis.comp_id = ts.comp_id AND
						tis.stor_id = ts.stor_id AND
						tis.item_id = ti.item_id
				WHERE	ts.stor_mustRecalculateAvailableStock	= 'True'	AND
						ISNULL(ti.item_disabled,'False')		= 'False'	AND
						tis.itst_cant IS NULL

			IF @@ROWCOUNT > 0
				BEGIN

					INSERT INTO tbItemStorage
					(
						comp_id,
						stor_id,
						item_id,
						itst_cant,
						itst_cd,
						itst_PickingLocation,
						itst_StorageLocation,
						itst_updateByInTransitStock,
						itst_LastAvailableInRelalculation
					)
						SELECT	tis.comp_id,
								tis.stor_id,
								tis.item_id,
								tis.itst_cant ,
								tis.itst_cd,
								tis.itst_PickingLocation,
								tis.itst_StorageLocation,
								tis.itst_updateByInTransitStock,
								tis.itst_LastAvailableInRelalculation
							FROM #tmpItemStorage			tis

					DROP TABLE #tmpItemStorage

				END



			-- Recalcula el potencial para ordenamiento de los depositos que lo necesiten
			--UPDATE tbItemStorage
			SELECT	tis.comp_id,
					tis.stor_id,
					tis.item_id,
					CASE
						WHEN (
								(	ts.stor_IncludeStockOfStorageGroupMembers = 'True'
										AND
									fs.item_id IS NOT NULL
								)
									OR
								 tis.itst_cant > 0
								    OR
								 ti.item_isForAssociation = 'True'
									OR
								 ts.stor_includePurchaseOrderinAvailableStock = 'True'	-- MOS 06-2020 x MArstech
							 )						THEN dbo.fnGetAStock4MaxAssociation(tis.comp_id, tis.stor_id, tis.item_id, 999999999)    -- 08-2018, estaba con fnGetAStock y se paso a fnGetAStock4MaxAssociation, ver tema VELOCIDAD
						ELSE							 0
					END						[itst_LastAvailableInRelalculation]
				INTO #tmpAvailableStock
				FROM tbItemStorage tis					WITH (NOLOCK)
				LEFT JOIN @tbFastSearch fs			-- Dejar ACA por Velocidad
					ON	fs.item_id = tis.item_id
				INNER JOIN tbStorage ts					WITH (NOLOCK)
					ON	ts.comp_id = tis.comp_id AND
						ts.stor_id = tis.stor_id
				INNER JOIN tbItem ti					WITH (NOLOCK)
					ON	ti.comp_id = tis.comp_id AND
						ti.item_id = tis.item_id

				WHERE	ts.stor_mustRecalculateAvailableStock	= 'True'		AND
						ti.item_disabled						= 'False'



			-- Por Velocidad y que no bloquee esta tabla tanto tiempo.
			--BEGIN TRANSACTION
				UPDATE tbItemStorage	--WITH (ROWLOCK)
					SET	itst_LastAvailableInRelalculation = tmp.itst_LastAvailableInRelalculation
					FROM 		tbItemStorage		tis		WITH (NOLOCK)
					INNER JOIN 	#tmpAvailableStock	tmp		--WITH (NOLOCK)
						ON	tmp.comp_id = tis.comp_id AND
							tmp.item_id = tis.item_id AND
							tmp.stor_id = tis.stor_id
					WHERE  IsNull(tis.itst_LastAvailableInRelalculation,0) <> tmp.itst_LastAvailableInRelalculation
			--COMMIT TRANSACTION
			--CHECKPOINT

			DECLARE @tmpStorages4EqualStockStatusTO TABLE(stor_id INT PRIMARY KEY)

			-- Actualiza estado de stock si tiene un DEPOSITO asignado
			IF EXISTS(	SELECT TOP 1 1
							FROM tbStorage ts  WITH (NOLOCK)
			          		WHERE ts.stor_id_FromUpdateIfTrueMyAvailableStock IS NOT NULL)
				BEGIN
					--BEGIN TRANSACTION
						UPDATE tbItemStorage	--WITH (ROWLOCK)
							SET	itst_LastAvailableInRelalculation = CASE
																		WHEN IsNull(ts1.itst_LastAvailableInRelalculation,0) > 0 THEN	(IsNull(ts1.itst_LastAvailableInRelalculation,0) + IsNull(its.itst_LastAvailableInRelalculation,0))
																		ELSE															its.itst_LastAvailableInRelalculation
																	END
							FROM tbItemStorage its		WITH (NOLOCK)
							INNER JOIN tbStorage ts		WITH (NOLOCK)
								ON	ts.comp_id = its.comp_id									AND
									ts.stor_id = its.stor_id
							INNER JOIN #tmpAvailableStock ts1
								ON	ts1.comp_id = ts.comp_id									AND
									ts1.stor_id = ts.stor_id_FromUpdateIfTrueMyAvailableStock	AND
									ts1.item_id = its.item_id
						WHERE ts.stor_id_FromUpdateIfTrueMyAvailableStock IS NOT NULL
					--COMMIT TRANSACTION
					--CHECKPOINT
				END
			--


			-- Actualiza estado de stock si tiene un Grupo de DEPOSITOS asignado
			IF EXISTS(	SELECT TOP 1 1
							FROM tbStorage ts	WITH (NOLOCK)
          					WHERE ts.storg_id_FromUpdateIfTrueMyAvailableStock IS NOT NULL)
				BEGIN
					--BEGIN TRANSACTION
						UPDATE tbItemStorage	--WITH (ROWLOCK)
							SET	itst_LastAvailableInRelalculation = CASE
																		WHEN IsNull(ts1.itst_LastAvailableInRelalculation,0) > 0 THEN	(IsNull(ts1.itst_LastAvailableInRelalculation,0) + IsNull(its.itst_LastAvailableInRelalculation,0))
																		ELSE															its.itst_LastAvailableInRelalculation
																	END
							FROM tbItemStorage its		WITH (NOLOCK)
							INNER JOIN tbStorage ts		WITH (NOLOCK)
								ON	ts.comp_id = its.comp_id									AND
									ts.stor_id = its.stor_id
							INNER JOIN tbStorageGroupDetail tsgd WITH (NOLOCK)
								ON	tsgd.comp_id	= ts.comp_id	AND
									tsgd.storg_id	= ts.storg_id_FromUpdateIfTrueMyAvailableStock AND
									tsgd.stor_id   <> ts.stor_id
							INNER JOIN #tmpAvailableStock ts1
								ON	ts1.comp_id = ts.comp_id	AND
									ts1.stor_id = tsgd.stor_id	AND
									ts1.item_id = its.item_id
							WHERE ts.storg_id_FromUpdateIfTrueMyAvailableStock IS NOT NULL
					--COMMIT TRANSACTION
					--CHECKPOINT
				END
			--

			DROP TABLE #tmpAvailableStock

		END
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	SELECT ' Step 007:',GETDATE()

	-- ---------------------------------------------------------
	-- Envia emails de BD en caso q no se envien mediante la BD
	-- ---------------------------------------------------------
	BEGIN TRY
		EXEC spTMPFiles_SMTP_sendEmails
	END TRY
	BEGIN CATCH
	END CATCH
	-- ---------------------------------------------------------


	SELECT ' Step 008:',GETDATE()

	-- ----------------------------------
	-- Mail de deuda a clientes
	-- entre las 3 y 4 AM
	-- ----------------------------------
	BEGIN TRY
		SET @bitCanIDoIt = 'False'
		EXEC spSystem_LastExecutionControl_CanDoIt -1,
												   -1,
												59723,	-- Mailing de Deuda de Clientes
												  900,	-- MOS 02-2022, se pone que una vez x dia en mayor rango horario verifique si se hizo el mailing de deuda.
										 @bitCanIDoIt OUTPUT
		IF (
				DATEPART(hh,GETDATE()) BETWEEN 7 AND 8
		   )
		BEGIN
			IF EXISTS(	SELECT TOP 1  1
							FROM tbBranch tb		WITH (NOLOCK)
		          			WHERE	IsNull(tb.bra_Mailing4CustOverdueDebt_Available,'False') = 'True' AND
		          					IsNull(tb.bra_disabled,'False')='False')
				BEGIN
					EXEC spCommercialTransactions_BalanceMails -1,-1
				END
		END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ----------------------------------

	SELECT ' Step 009:',GETDATE()

	-- ----------------------------------
	-- Cancela Procesos de ML
	-- con muchos errores
	-- ----------------------------------
	IF (
			DATEPART(hh,GETDATE()) BETWEEN 4 AND 5
	   )
	BEGIN
		--BEGIN TRANSACTION
			UPDATE tbMercadoLibre_updateQueue
				SET mlproc_isCancelled = 'True'
				WHERE	mlproc_isProcessed			= 0 AND
						mlproc_isCancelled			= 0 AND
						mlproc_isWithErrorTryNumber > 10 AND
						mlproc_blockCancell = 'False'	AND
						mlproc_response NOT LIKE '%item.price.freezed_by_deal%'		-- **ewñflm34059230  MOS 04-2023 para que NO borre los que están con error y no procesados por estar en deal
		--COMMIT TRANSACTION
		--CHECKPOINT
	END
	-- ----------------------------------

	SELECT ' Step 010:',GETDATE()

	-- ----------------------------------
	-- Advertencias de CRM
	-- Desde la 0300 a la 0400
	-- ----------------------------------
	SET @bitCanIDoIt = 'False'
	EXEC spSystem_LastExecutionControl_CanDoIt -1,
											   -1,
										    45876,
										       10,	-- cada 10 minutos hace el recalculo.!
								     @bitCanIDoIt OUTPUT

	BEGIN TRY
		IF @bitCanIDoIt = 'True' AND
			(
				DATEPART(hh,GETDATE()) BETWEEN 3 AND 4
		    )
		BEGIN
					DECLARE curBranchs  CURSOR LOCAL  FAST_FORWARD FOR
						SELECT tb.comp_id,tb.bra_id,tb.bra_CloseDaily_prof_id,tb.bra_CloseDaily_user_id
		          			FROM tbBranch tb			WITH (NOLOCK)
		          			WHERE	--IsNull(tb.bra_CloseDaily_IsAutomatic,'False')	= 'True'	AND
		          					IsNull(tb.bra_disabled,'False')					='False'	--AND
		          					--tb.bra_processingDate <> @datNewDate

					OPEN curBranchs
					FETCH NEXT FROM curBranchs INTO @intCompId,@intBraId,@intProfile4AutoClose,@intUser4AutoClose
					WHILE @@FETCH_STATUS = 0
						BEGIN

							EXEC spCRM_AdvertisementsCalculation  @intCompId, @intBraId

							FETCH NEXT FROM curBranchs INTO @intCompId,@intBraId,@intProfile4AutoClose,@intUser4AutoClose
						END
					CLOSE curBranchs
					DEALLOCATE curBranchs
		END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ----------------------------------

	SELECT ' Step 011:',GETDATE()

	-- ----------------------------------
	-- Borra WorkFlows Closed Pendientes
	-- Borra Reclamos Procesados > 6M
	-- ----------------------------------
	BEGIN TRY
		IF (
				DATEPART(hh,GETDATE()) BETWEEN 4 AND 5
		   )
		BEGIN
			--BEGIN TRANSACTION
				DELETE FROM tbWorkflow	WITH (TABLOCK)
					WHERE	claim_id IS NOT NULL					AND
							wf_isProcessed	= 0						AND
							wf_message4		LIKE '%Status:closed%'

				DELETE FROM tbWorkflow	WITH (TABLOCK)
					WHERE	wf_isProcessed = 1 AND
							ABS(DATEDIFF(MONTH,  wf_dateOfAssigned,GETDATE())) > 6 AND
							claim_id IS NOT NULL
			--COMMIT TRANSACTION
			--CHECKPOINT
		END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ----------------------------------



	SELECT ' Step 012:',GETDATE()



	-- ----------------------------------------------------------------------------
	-- Ejecuta el calculo de indicadores si esta definido en compañia.
	-- Es mas que conveniente poner la ejecucion de este sp separada
	-- asi si algun indicador tarda mucho en ejecutarse no hay problemas
	-- de solapamiento
	-- ----------------------------------------------------------------------------
	BEGIN TRY
		IF EXISTS(
					SELECT TOP 1  1
						FROM tbCompany tc	WITH (NOLOCK)
						WHERE tc.comp_controlPanelExecutionWithIsEditing = 'True'
					)
			BEGIN
				EXEC spCheckBoard_ScheduleExecution
			END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ----------------------------------------------------------------------------



	SELECT ' Step 013:',GETDATE()


	-- ----------------------------------------------------------------------------
	-- Llama a las URL de los sistemas para DESPERTAR al IIS
	-- Esto solo se usa en el sistema de GBP Interno con el Modulo 99 Habilitado
	-- ----------------------------------------------------------------------------
	IF (
			DATEPART(hh,GETDATE()) = 5 AND
			DATEPART(mm,GETDATE()) BETWEEN 1 AND 30
	   )
	BEGIN

		DECLARE @strURL		AS NVARCHAR(300)
		DECLARE @strURL2	AS NVARCHAR(300)
		DECLARE @strURL3	AS NVARCHAR(300)
		DECLARE @cust_GBPUrl4webSite AS NVARCHAR(300)

		DECLARE @comp_id	AS INT
		DECLARE @cust_id	AS INT
		DECLARE @strRET		AS NVARCHAR(MAX)

		DECLARE curGBPCustomers  CURSOR LOCAL FAST_FORWARD FOR
			SELECT	tb.comp_id	,
					tb.cust_id	,
					ISNULL(tb.cust_GBPUrl,''),
					ISNULL(tb.cust_GBPUrl2,''),
					ISNULL(tb.cust_GBPUrl3,''),
					ISNULL(tb.cust_GBPUrl4webSite,'')
          		FROM tbCustomer tb	WITH (NOLOCK)
          		WHERE	ISNULL(tb.cust_GBPCG,'')		<> ''		AND
          				(
          					ISNULL(tb.cust_GBPUrl,'')	<> ''
          					OR
          					ISNULL(tb.cust_GBPUrl2,'')	<> ''
          					OR
          					ISNULL(tb.cust_GBPUrl3,'')	<> ''
          					OR
          					ISNULL(tb.cust_GBPUrl4webSite,'') <> ''
          				)
          				AND
          				(
          					dbo.fnGetEnd_or_BeginOfDate(ISNULL(tb.cust_GBPLastURLUpdate,GETDATE()),'False') <> dbo.fnGetEnd_or_BeginOfDate(GETDATE(),'False')
          						OR
          					tb.cust_GBPLastURLUpdate IS NULL
          				)

		OPEN curGBPCustomers
		FETCH NEXT FROM curGBPCustomers INTO	@comp_id,
												@cust_id,
												@strURL,
												@strURL2,
												@strURL3,
												@cust_GBPUrl4webSite
		WHILE @@FETCH_STATUS = 0
			BEGIN

				set @strRET  = dbo.clrActivateURL(@strURL + '/wfmLogin.aspx')
				set @strRET  = dbo.clrActivateURL(@strURL)

				IF ISNULL(@strURL2,'')	<> ''
					BEGIN
						set @strRET  = dbo.clrActivateURL(@strURL2 + '/wfmLogin.aspx')
						set @strRET  = dbo.clrActivateURL(@strURL2)
					END

				IF ISNULL(@strURL3,'')	<> ''
					BEGIN
						set @strRET  = dbo.clrActivateURL(@strURL3 + '/wfmLogin.aspx')
						set @strRET  = dbo.clrActivateURL(@strURL3)
					END

				IF ISNULL(@cust_GBPUrl4webSite,'')	<> ''
					BEGIN
						set @strRET  = dbo.clrActivateURL(@cust_GBPUrl4webSite)
					END

				UPDATE tbcustomer	--WITH (rowlock	)
					SET cust_GBPLastURLUpdate = GETDATE()
					WHERE	comp_id		= @comp_id AND
							cust_id		= @cust_id


				FETCH NEXT FROM curGBPCustomers INTO	@comp_id,
														@cust_id,
														@strURL,
														@strURL2,
														@strURL3,
														@cust_GBPUrl4webSite
			END
		CLOSE curGBPCustomers
		DEALLOCATE curGBPCustomers

	END
