	--CUSTOM_GN_001
	-- ----------------------------------------------------------------------------
	-- Actualiza la tabla que dice si hay articulos disponibles para WEB
	-- ----------------------------------------------------------------------------
	BEGIN TRY
		IF EXISTS(
					SELECT TOP 1  1
						FROM tbWebSiteII_Names twsin			WITH (NOLOCK)
						LEFT JOIN tbTiendaNube_Stores AS ttns	WITH (NOLOCK)
							ON	ttns.comp_id	= twsin.comp_id AND
								ttns.ws_id		= twsin.ws_id
						WHERE	ttns.comp_id IS NULL
					)
			BEGIN -- SITIO WEB ERA CADA 20 Y LO PASE A CADA 60

				SET @bitCanIDoIt = 'False'
				EXEC spSystem_LastExecutionControl_CanDoIt -1,
														   -1,
														10958,
														   120,	-- cada 90 minutos hace el recalculo.!   MOS 11-2022 lo pase de 90 a 120
														@bitCanIDoIt OUTPUT

				IF @bitCanIDoIt = 'True'
					BEGIN
						-- ------------------------------------------
						-- Cada 3 días BORRO y Regenero todo
						-- por posibles cambios en descripciones
						-- , etc entre las 3 y 5 AM
						-- ------------------------------------------
						IF DATEPART(hh,GETDATE())  IN (2,3)
							BEGIN
								DECLARE @bitCanDeleteAll AS BIT = 'False'
								EXEC spSystem_LastExecutionControl_CanDoIt -1,
																		   -1,
																		23958,
																		 10080   ,	-- cada 7 días BORRA por completo esta tabla
															  @bitCanDeleteAll OUTPUT
								IF @bitCanDeleteAll = 'False'
									BEGIN
										SELECT TOP 1  @bitCanDeleteAll = 'True'
											FROM tbWebSiteII_Names AS twsin	WITH (NOLOCK)
											WHERE twsin.ws_deleteItemsDataThisNight = 'True'
										IF @bitCanDeleteAll = 'True'
											BEGIN
												UPDATE tbWebSiteII_Names SET ws_deleteItemsDataThisNight = 'False' WHERE ws_deleteItemsDataThisNight = 'True'
											END
									END
								IF @bitCanDeleteAll = 'True'
									BEGIN
										BEGIN TRY
											WHILE 1 = 1
												BEGIN
													--BEGIN TRANSACTION   MOS 09-2023: Lo saque x q es al pedo ( Creo )
														DELETE TOP (2000) FROM tbWebSiteII_ItemsData					--	WITH (TABLOCK)
														SET @intRowCount = @@ROWCOUNT
													--COMMIT TRANSACTION
													--CHECKPOINT
													IF @intRowCount < 2000 BREAK;
												END
										END TRY
										BEGIN CATCH
										END CATCH
									END
							END
						-- ------------------------------------------


						-- A las dos y pico borra la tabla temporal de recalculo para que se regenere por completo nuevamente.
						-- MOS 08-2021:  NO FUNCIONA x q tiene vistas indexadas.  de ULTIMA reemplazar x Delete
						--IF 	DATEPART(hh,GETDATE())  = 2		 AND
						--	DATEPART(mm,GETDATE()) BETWEEN 1 AND 15
						--	BEGIN
						--		TRUNCATE TABLE tbWebSiteII_ItemsData
						--	END

						-- MOS 09-2023
						--EXEC spTMPFiles_UpdateWebSiteItems
						IF NOT EXISTS (SELECT TOP 1 1 FROM tbcompany WITH (NOLOCK) WHERE comp_blockUpdateWebSiteItems = 1)
							BEGIN
								EXEC spTMPFiles_UpdateWebSiteItemsNew
							END



					END

			END
		ELSE IF EXISTS(
					SELECT TOP 1  1
						FROM tbWebSiteII_Names twsin			WITH (NOLOCK)
						INNER JOIN tbTiendaNube_Stores AS ttns	WITH (NOLOCK)
							ON	ttns.comp_id	= twsin.comp_id AND
								ttns.ws_id		= twsin.ws_id
					)
			BEGIN	-- TIENDA  NUBE

				SET @bitCanIDoIt = 'False'
				EXEC spSystem_LastExecutionControl_CanDoIt -1,
														   -1,
														10958,
														   120,	-- cada 45 minutos hace el recalculo.!
														@bitCanIDoIt OUTPUT

				IF @bitCanIDoIt = 'True'
					BEGIN
						-- A las dos y pico borra la tabla temporal de recalculo para que se regenere por completo nuevamente.
						-- MOS 08-2021:  NO FUNCIONA x q tiene vistas indexadas.  de ULTIMA reemplazar x Delete
						--IF 	DATEPART(hh,GETDATE())  = 2		 AND
						--	DATEPART(mm,GETDATE()) BETWEEN 1 AND 15
						--	BEGIN
						--		TRUNCATE TABLE tbWebSiteII_ItemsData
						--	END

						-- MOS 09-2023
						--EXEC spTMPFiles_UpdateWebSiteItems
						IF NOT EXISTS (SELECT TOP 1 1 FROM tbcompany WITH (NOLOCK) WHERE comp_blockUpdateWebSiteItems = 1)
							BEGIN
								EXEC spTMPFiles_UpdateWebSiteItemsNew
							END

					END

			END




	END TRY
	BEGIN CATCH
	END CATCH
