	--UPDATE tbGBPPublicity --WITH (ROWLOCK)
	--SET	pu_fromDate = dbo.fnGetEnd_or_BeginOfDate(pu_fromDate,'False'),
	--	pu_toDate	= dbo.fnGetEnd_or_BeginOfDate(pu_toDate,'True')



	-- Esta en Verification4UpdateQueue, no hace falta aca
	-- -------------------------------------------------------------------------------
	-- Por las dudas se fuerza a que toda orden con PEDIDO generado no comprometa
	-- stock. Esto igualmente ya lo hace dbo.spMercadoLibre_insertSaleOrder
	-- -------------------------------------------------------------------------------
	--UPDATE  tbMercadoLibre_ordersDetail						WITH (ROWLOCK)
	--	SET mlo_is4AvailableStock = 0
	--	FROM tbMercadoLibre_ordersDetail		tmlod
	--	INNER JOIN tbMercadoLibre_ordersHeader	tmloh		WITH (NOLOCK)
	--	ON	tmloh.comp_id			= tmlod.comp_id		AND
	--		tmloh.mlo_id			= tmlod.mlo_id
	--	WHERE	tmlod.mlo_is4AvailableStock			= 'True'  AND
	--			(
	--			  tmloh.mlo_isSaleOrderGenerated	= 'True'  OR
	--			  tmloh.mlo_isCancelled				= 'True'  OR
	--			  tmloh.mlo_isSaleOrderEmmited      = 'True'  OR
	--			  tmloh.mlo_status					= 'cancelled'
	--			)
	-- -------------------------------------------------------------------------------




	-- vERIFICA eMAILS imap DE SER NECESARIO
	EXEC spTMPFiles_IMAP_getEmails


	SELECT ' Step 017:',GETDATE()


	-- Verifica si tiene que actualizar algo de Comunidad GlobalBluePOint
	EXEC spTMPFiles_CommunityServicesCaller


	SELECT ' Step 018:',GETDATE()

	EXEC spWebSiteII_SQLScriptsScheduleExecution

	SELECT ' Step 019:',GETDATE()


	-- Si tiene el modulo de Constatacion de comprobantes hace las verificaciones pendientes.
	IF DATEPART(hour,GETDATE()) BETWEEN 1 AND 5
		BEGIN
			SET @bitCanIDoIt = 'False'
			EXEC spSystem_LastExecutionControl_CanDoIt -1,
													   -1,
													55456,
				   									 1440,
											 @bitCanIDoIt OUTPUT
			BEGIN TRY
				IF @bitCanIDoIt = 'True'
					BEGIN
						EXEC spTMPFiles_AFIPVerifications
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END


	SELECT ' Step 020:',GETDATE()


	-- Debe calcular: comp_mustCalculate_tbPriceListItemByItemType cada 4 horas
	IF EXISTS(
				SELECT TOP 1 1
					FROM tbCompany AS tc WITH (NOLOCK)
					WHERE comp_mustCalculate_tbPriceListItemByItemType = 'True'
				)
		BEGIN
			SET @bitCanIDoIt = 'False'
			EXEC spSystem_LastExecutionControl_CanDoIt -1,
														-1,
													54674,
				   										240,
												@bitCanIDoIt OUTPUT
			BEGIN TRY
				IF @bitCanIDoIt = 'True'
					BEGIN
						EXEC spTMPFiles_tbPriceListItemByItemType
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END
	ELSE	-- si NO esta habilitado que borre TODA LA MIERDA QUE HICIERON CALCULAR ESTOS HDRMP ENFERMOS DE MIERDA!!
		BEGIN
			TRUNCATE TABLE tbCustomerPriceListBySOItemType
		END


		SELECT ' Step 021:',GETDATE()

		-- ----------------------------------------------------------
		-- Calcula fecha de ultima VENTA del articulo
		-- MOS 09-2022: dohk x wfmSelItem ( ver art con mas de 60 dias sin venta
		-- ----------------------------------------------------------
		IF DATEPART(hour,GETDATE()) between 3 AND 5
			BEGIN
				SET @bitCanIDoIt = 'False'
				EXEC spSystem_LastExecutionControl_CanDoIt -1,
															-1,
														54584,
				   											240,
													@bitCanIDoIt OUTPUT
				BEGIN TRY
					IF @bitCanIDoIt = 'True'
						BEGIN
							UPDATE tbitem
								SET item_daysWithOutSales = (
																SELECT TOP 1  DATEDIFF( DAY,tit.it_cd,GETDATE() )
																	FROM tbItemTransactions AS tit	WITH (NOLOCK)
																	INNER JOIN vwCommercialTransactions_forSalesStatsPlusPackingList AS vct	WITH (NOLOCK)
																		ON	vct.comp_id			= tit.comp_id AND
																			vct.ct_transaction	= tit.ct_transaction
																	WHERE	tit.comp_id			= ti.comp_id AND
																			tit.item_id			= ti.item_id
																	ORDER BY vct.ct_transaction DESC
															)
								FROM tbItem AS ti
								WHERE ti.item_disabled = 0
						END
				END TRY
				BEGIN CATCH
				END CATCH
			END
		-- ----------------------------------------------------------


	SELECT ' Step 022:',GETDATE()




	-- CM y la RPMQTRMP  HDP!!!
	EXEC spSaleOrderHeader_PurchaseOrderRelation_IntegrityVerification


	SELECT ' Step 023:',GETDATE()



	-- ---------------------------------------------------
	-- solo los DOMINGOS completa las Tablas con resumenes para la IA
	-- ---------------------------------------------------
	IF 	DATEPART(hh,GETDATE())  BETWEEN 4 AND 9
			AND
		DATEPART(dw,GETDATE()) = 1
		BEGIN

			SET @bitCanIDoIt = 'False'
			EXEC spSystem_LastExecutionControl_CanDoIt -1,
														-1,
													54585,
				   										240,
												@bitCanIDoIt OUTPUT


			IF @bitCanIDoIt = 'True'
				BEGIN
					EXEC spTMPFiles_AIfilesGeneration
				END

		END
	-- ---------------------------------------------------



	SELECT ' Step 024:',GETDATE()



	-- ---------------------------------------------------
	-- MOS 04-2024: Trata de reprocesar callbackhistory no procesados
	-- ---------------------------------------------------
	SET @bitCanIDoIt = 'False'
	EXEC spSystem_LastExecutionControl_CanDoIt -1,
												-1,
											34567760,
				   								60,
										@bitCanIDoIt OUTPUT

	SELECT ' Step 025:',GETDATE()


	IF @bitCanIDoIt = 'True'
		BEGIN
			EXEC spTMPFiles_MercadoLibreCallbackHistoryUnprocessed_Verifications
		END
	-- ---------------------------------------------------

	SELECT ' Step 026:',GETDATE()

	-- ---------------------------------------------------
	-- MOS 04-2024: no se x q mierda en doubleg habia sof con mlo y soh sin
	--  pongo la reparacion de este tema asi aparecen en edicion de ordenes los pedidos relacionados
	-- ---------------------------------------------------
	BEGIN TRY
		; WITH cteRepareOrders (comp_id,bra_id,soh_id,mlo_id) AS
			(
				SELECT DISTINCT tsod.comp_id, tsod.bra_id, tsod.soh_id, tsod.mlo_id
					FROM tbSaleOrderDetail			AS tsod		WITH (NOLOCK)
					INNER JOIN tbSaleOrderHeader	AS tsoh		WITH (NOLOCK)
						ON	tsoh.comp_id	= tsod.comp_id	AND
							tsoh.bra_id		= tsod.bra_id	AND
							tsoh.soh_id		= tsod.soh_id
					WHERE	tsod.mlo_id IS NOT NULL AND
							tsoh.mlo_id IS NULL
			)
		UPDATE tbSaleOrderHeader
		SET mlo_id = tmp.mlo_id
		FROM tbSaleOrderHeader tsoh	WITH (NOLOCK)
		INNER JOIN cteRepareOrders tmp
			ON	tmp.comp_id = tsoh.comp_id	AND
				tmp.bra_id	= tsoh.bra_id	AND
				tmp.soh_id	= tsoh.soh_id
	END TRY
	BEGIN CATCH
	END CATCH
	-- ---------------------------------------------------


	SELECT ' Step 027:',GETDATE()


	-- ----------------------------------
	-- Borra las variables de sesion
	-- de mas de 2 dias o si no hay
	-- usuarios conectados, limpia la
	-- tabla
	-- ----------------------------------
	-- Si no hay usuarios conectados y son las 3AM y en los 15 primeros minutos, trunca la tabla.-
	IF
		(
			(
				DATEPART(hh,GETDATE())  BETWEEN 1 AND 23      -- MOS 11-2022: Decia 4	 pero si NO hay nadie logeado, que lo borre
			)									AND
		--DATEPART(mi,GETDATE()) <= 30			AND
		NOT EXISTS (
					SELECT TOP 1 1
						FROM tbUser tu WITH (NOLOCK)
						WHERE tu.user_login = 'True'
					)
		)
		--OR
		--@bitDaylyCloseDone = 'True'  MOS 06-2019 x q sino no llegaban a cerrarse los sistemas que estaban abiertos porque se borarba el VS
	BEGIN


		BEGIN TRY
			TRUNCATE TABLE tbSystem_SessionInSQL
		END TRY
		BEGIN CATCH
		END CATCH

		BEGIN TRY
			TRUNCATE TABLE tbSystem_ViewStateInSQL
		END TRY
		BEGIN CATCH
		END CATCH


		BEGIN TRY
			--BEGIN TRANSACTION
				DELETE FROM tbSystem_SessionInSQL		--WITH (ROWLOCK)
			--COMMIT TRANSACTION
			--CHECKPOINT
		END TRY
		BEGIN CATCH
		END CATCH

		BEGIN TRY
			--BEGIN TRANSACTION
				DELETE	FROM tbSystem_ViewStateInSQL	--WITH (ROWLOCK)
			--COMMIT TRANSACTION
			--CHECKPOINT
		END TRY
		BEGIN CATCH
		END CATCH



	END
	-- ----------------------------------

	SELECT ' Step 028:',GETDATE()

	-- Borra el LOG para arrancar el día limpito!  :-)
	IF DATEPART(hour ,GETDATE()) IN (5,6,7)
		BEGIN
			SET @bitCanIDoIt = 'False'
			EXEC spSystem_LastExecutionControl_CanDoIt -1,
													   -1,
													59453,
				   									 900,
											 @bitCanIDoIt OUTPUT
			BEGIN TRY
				IF @bitCanIDoIt = 'True'
					BEGIN
						EXEC spSystem_GenerateDatabaseBackupTruncateLog
					END
			END TRY
			BEGIN CATCH
			END CATCH
		END

	SELECT ' Step 029:',GETDATE()

	-- ---------------------------------------------------
	-- Cada 60 dias hace un reindexado de la base de datos
	-- solo los DOMINGOS de 1 a 10 AM
	-- MOS 09-2024: Pase a 60 dias para que no joda tanto a los discos SSD
	-- ---------------------------------------------------
	IF 	DATEPART(hh,GETDATE())  BETWEEN 1 AND 11
			AND
		DATEPART(dw,GETDATE()) = 1
		BEGIN

			DECLARE @lastDatabaseReindex AS DATETIME
			SELECT TOP 1  @lastDatabaseReindex = ISNULL(tsdv.lastDatabaseReindex,GETDATE()-1000)
				FROM tbSystem_DatabaseVersion tsdv	WITH (NOLOCK)

			IF ABS(DATEDIFF(DAY, GETDATE(), @lastDatabaseReindex)) > 60
				BEGIN
					UPDATE tbSystem_DatabaseVersion
						SET lastDatabaseReindex = dbo.fnGetEnd_or_BeginOfDate( GETDATE(),'False')
					EXEC spSystem_ReindexTables
				END

		END
	-- ---------------------------------------------------


	SELECT ' Step 030:',GETDATE()

	-- ---------------------------------------------------
	-- Saca la marca de depurando pedidos luego de las 8 am
	-- solo los DOMINGOS de 6 a 24
	-- ---------------------------------------------------
	IF 	DATEPART(hh,GETDATE())  BETWEEN 8 AND 23
		BEGIN
			IF EXISTS(	SELECT 1
			          		FROM	tbSystem_DatabaseVersion			WITH (NOLOCK)
			          		WHERE	closeDaily_PurificatingOrders = 1
					 )
			UPDATE tbSystem_DatabaseVersion SET closeDaily_PurificatingOrders = 0
		END
	-- ---------------------------------------------------

	SELECT ' Step 031:',GETDATE()


END
GO

-- =============================================
