-- =============================================
CREATE PROCEDURE [dbo].[spTMPFiles_MercadoLibreStatisticsSendCatInfo]
AS
BEGIN
	SET NOCOUNT ON

	-- ----------------------------------------------------------------------------
	-- MeLi
	-- Informa que categorias deberia escanear el modulo de generacion de estadisticas.
	-- ----------------------------------------------------------------------------
	-- ATENCION:
	IF EXISTS(
				SELECT TOP 1  1
					FROM	tbCompany tc	WITH (NOLOCK)
					WHERE	dbo.fnStrAllTrim(ISNULL(tc.comp_ServerFULLURL2Acces,'')) <> ''
				)
		BEGIN

			DECLARE @Obj		int
			DECLARE @Result		int
			DECLARE @HTTPStatus int
			DECLARE curComp2Check  CURSOR LOCAL FAST_FORWARD FOR
			SELECT DISTINCT	tc.comp_id,tc.comp_ServerFULLURL2Acces
				FROM tbCompany tc							WITH (NOLOCK)
				WHERE	dbo.fnStrAllTrim(ISNULL(tc.comp_ServerFULLURL2Acces,'')) <> ''

			DECLARE		@curCompID		AS INT	= -1
			DECLARE		@strIMAPURL		AS NVARCHAR(200)
			DECLARE		@strIMAPURLExec AS NVARCHAR(200)
			OPEN		curComp2Check
			FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL
			WHILE @@FETCH_STATUS = 0
				BEGIN

					BEGIN TRY
						SELECT	@strIMAPURLExec =  @strIMAPURL + 'wfmMercadoLibre_PublicationStatistics_RecquireCategories.aspx?QSCompID=' + CONVERT(NVARCHAR(20),@curCompID)
						SELECT  dbo.clrActivateURL(@strIMAPURLExec)
					END TRY
					BEGIN CATCH
					END CATCH

					BEGIN TRY
						SELECT	@strIMAPURLExec =  @strIMAPURL + 'wfmMercadoLibre_PublicationsStatistics_UpdatePublicationFromStatisticsCaller.aspx?QSCompID=' + CONVERT(NVARCHAR(20),@curCompID)
						SELECT  dbo.clrActivateURL(@strIMAPURLExec)
					END TRY
					BEGIN CATCH
					END CATCH


					FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL

				END
			CLOSE		curComp2Check
			DEALLOCATE	curComp2Check

		END
	-- ----------------------------------------------------------------------------




END
GO

