-- =============================================
CREATE PROCEDURE [dbo].[spTMPFiles_SMTP_sendEmails]
AS
BEGIN
	SET NOCOUNT ON


	-- Si NO hay nada para mandar se va . . .
	IF NOT EXISTS
					(
						SELECT TOP 1  1
							FROM tbsendEMailQueue AS teq	WITH (NOLOCK)
					)
		BEGIN
			RETURN
		END

	-- ----------------------------------------------------------------------------
	-- Anvio de Mails desde BD
	-- ----------------------------------------------------------------------------
	-- ATENCION:

	DECLARE @Response AS VARCHAR(MAX)

	BEGIN

		DECLARE @Obj		int
		DECLARE @Result		int
		DECLARE @HTTPStatus int
		DECLARE curComp2Check  CURSOR LOCAL FAST_FORWARD FOR
		SELECT	TOP 1 -- MOS 02-2022: Es al Pedo q traiga todas si la pagina manda de todas las compañias...   q la llame solo si hay para mandar y listo...
			 	tc.comp_id,tc.comp_ServerFULLURL2Acces
				FROM tbCompany tc							WITH (NOLOCK)
				INNER JOIN tbsendEMailQueue AS teq			WITH (NOLOCK)	-- MOS 02-2022: q solo la llame si hay algo poara mandar, sino q no moleste al pedo...
					ON teq.comp_id = tc.comp_id
			WHERE
					ISNULL(tc.smtp_sendByDatabaseService,'False')	= 'False'	AND
					dbo.fnStrAllTrim(ISNULL(tc.comp_ServerFULLURL2Acces,'')) <> ''

		DECLARE		@curCompID	AS INT	= -1
		DECLARE		@strIMAPURL AS NVARCHAR(200)
		OPEN		curComp2Check
		FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL
		WHILE @@FETCH_STATUS = 0
			BEGIN

				BEGIN TRY
					SELECT	@strIMAPURL =  @strIMAPURL + 'wfmEMailsFromDatabaseSenderCaller.aspx?QSCompID=' + CONVERT(NVARCHAR(20),@curCompID)
					SELECT  @Response   =  dbo.clrActivateURL(@strIMAPURL)
				END TRY
				BEGIN CATCH
				END CATCH

				FETCH NEXT FROM curComp2Check INTO @curCompID,@strIMAPURL

			END
		CLOSE		curComp2Check
		DEALLOCATE	curComp2Check

	END
	-- ----------------------------------------------------------------------------




END
GO

-- =============================================
-- Author:		MOS
-- Create date: Delirio de FIESA
-- Description:	<Description,,>
-- =============================================


-- Log
-- MOS: 03-2024: Ver que incluya II en los Combos



CREATE PROCEDURE [dbo].[spTMPFiles_tbPriceListItemByItemType]

AS

BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	BEGIN TRY
		TRUNCATE TABLE	tbPriceListItemByItemType
	END TRY
	BEGIN CATCH
		DELETE FROM		tbPriceListItemByItemType
	END CATCH



	-- 1ro pone todos los precios q correspondan al cliente x cada tipo de articulo
	INSERT INTO tbPriceListItemByItemType
		(
			comp_id,
			cust_id,
			item_id,
			tipi_id,
			prli_id,
			tipi_discount,
			combo_price,
			combo_pricePlusTax,
			curr_id
		)
		SELECT	rt.comp_id,
				rt.cust_id,
				ti.item_id,
				rt.tipi_id,
				rt.prli_id,
				it.tipi_discount + rt.cupt_discount,
				tpli.prli_price,
				-- MOS 03-2024: Sumar II al precio BASE y luego el iva sobre el precio base mas los II
				(tpli.prli_price * ISNULL(hdp.tax_coeficient,1))  + (     (tpli.prli_price * ISNULL(hdp.tax_coeficient,1))      * ISNULL(ttn.tax_percentage,0) / 100),
				--OLD tpli.prli_price  + (tpli.prli_price * ISNULL(ttn.tax_percentage,0) / 100),
				tpli.curr_id
		FROM tbCustomerPriceListBySOItemType	rt		WITH (NOLOCK)
		INNER JOIN tbItemType					it		WITH (NOLOCK)
			ON	it.comp_id		= rt.comp_id		AND
				it.tipi_id		= rt.tipi_id
		INNER JOIN tbItem						ti		WITH (NOLOCK)
			ON	ti.comp_id		= rt.comp_id		AND
				ti.tipi_id		= rt.tipi_id
		INNER JOIN tbPriceListItems				tpli	WITH (NOLOCK)
			ON	tpli.comp_id	= rt.comp_id		AND
				tpli.prli_id	= rt.prli_id		AND
				tpli.item_id	= ti.item_id
		LEFT JOIN vwItemTaxesOnlyOneIvaTax AS vitooit	WITH (NOLOCK)
			ON	vitooit.comp_id	= ti.comp_id		AND
				vitooit.item_id = ti.item_id
		LEFT JOIN tbTaxName				   AS ttn		WITH (NOLOCK)
			ON	ttn.comp_id		= vitooit.comp_id	AND
				ttn.tax_id		= vitooit.tax_id
		LEFT JOIN vwItemTaxesOnlyOneInternalTaxByBranch_tbPriceListItemByItemType AS hdp WITH (NOLOCK)
			ON	hdp.comp_id		= ti.comp_id		AND
				hdp.item_id		= ti.item_id
		WHERE	ti.item_disabled			= 0		AND
				ti.item_disabledInPriceList = 0



	-- Insertar TODOS los PADRES de COMBOS que NO esten en la REPUTA TABLA de estos HRDRMP
	INSERT INTO tbPriceListItemByItemType
		(
			comp_id,
			cust_id,
			item_id,
			tipi_id,
			prli_id,
			tipi_discount,
			combo_price,
			combo_pricePlusTax,
			curr_id
		)
			SELECT	DISTINCT
						tmp.comp_id,
						tmp.cust_id,
						tia.item_id,
						ti.tipi_id,
						tc.prli_id,
						0,
						0,
						0,
						tmp.curr_id
				FROM		tbPriceListItemByItemType	AS tmp	WITH (NOLOCK)
				INNER JOIN	tbCustomer					AS tc	WITH (NOLOCK)
					ON	tc.comp_id			= tmp.comp_id AND
						tc.cust_id			= tmp.cust_id
				INNER JOIN	tbItemAssociation			AS tia	WITH (NOLOCK)
					ON	tia.comp_id			= tmp.comp_id AND
						tia.item_id_1		= tmp.item_id
				INNER JOIN	tbItem						AS ti	WITH (NOLOCK)
					ON	ti.comp_id			= tia.comp_id AND
						ti.item_id			= tia.item_id
				LEFT JOIN	tbPriceListItemByItemType	AS tmp2 WITH (NOLOCK)
					ON	tmp2.comp_id = tmp.comp_id	AND
						tmp2.item_id = tia.item_id	AND
						tmp2.cust_id = tmp.cust_id
				WHERE	tmp2.comp_id IS NULL AND
						ti.item_disabled = 'False'	AND
						ti.tipi_id IS NOT NULL		-- SI o SI deben TIPIFICAR a los COMBOS




		-- -----------------------------------------------------------------
		-- Actualizacion de precios de COMBOS
		-- Tener en cuenta q para q esto funcione el cliente SI O SI
		-- deberá tener TODAS las listas asignadas de TODAS las partes de un combo.
		-- Si NO tiene definida una lista para una PARTE de combo toma la lista del CLIENTE.
		-- Si el COMBO NO tiene definida una moneda en su lista, toma la del articulo.
		-- -----------------------------------------------------------------
		;WITH tmpComboPrice AS
			(
				SELECT	pit.comp_id,
						pit.cust_id,
						pit.item_id,
						SUM	(
								dbo.fnGetExchange2(	pit.comp_id,
													CASE
														WHEN tpliPARTS.comp_id				IS NOT NULL	THEN tpliPARTS.prli_price
														WHEN tpliPARTSbyCOMBOList.comp_id	IS NOT NULL	THEN tpliPARTSbyCOMBOList.prli_price
														WHEN tpliPARTSCuLi.comp_id			IS NOT NULL	THEN tpliPARTSCuLi.prli_price
														ELSE 0
													END,
													--ISNULL(tpliPARTS.prli_price,tpliPARTSCuLi.prli_price),
													CASE
														WHEN tpliPARTS.comp_id				IS NOT NULL	THEN tpliPARTS.curr_id
														WHEN tpliPARTSbyCOMBOList.comp_id	IS NOT NULL	THEN tpliPARTSbyCOMBOList.curr_id
														WHEN tpliPARTSCuLi.comp_id			IS NOT NULL	THEN tpliPARTSCuLi.curr_id
														ELSE 0
													END,
													--ISNULL(tpliPARTS.curr_id,tpliPARTSCuLi.curr_id),
													CASE
														WHEN tpliCOMBO.curr_id				IS NOT NULL	THEN tpliCOMBO.curr_id
														WHEN tpliCOMBOCuLi.curr_id			IS NOT NULL	THEN tpliCOMBOCuLi.curr_id
														WHEN ti.curr_id						IS NOT NULL	THEN ti.curr_id
														ELSE												 ti.curr_id
													END,
													--ISNULL(tpliCOMBO.curr_id,ISNULL(tpliCOMBOCuLi.curr_id ,ti.curr_id)),
													0,
													0,
													0,
													'False'
												  )
									*
								tia.iasso_qty
									*
								ISNULL(hdp.tax_coeficient,1)	-- MOS 03-2024: MULTIPLICAR x un coeficiente de II.  Si es NULL poner 1 y sino 1.20 si es el 20 %
									*
								(1-(
									CASE
										WHEN ISNULL(pitPARTS.tipi_discount,0) > ISNULL(tia.itema_discountPercentage4PriceListSUM,0) THEN ISNULL(pitPARTS.tipi_discount,0)
										ELSE ISNULL(tia.itema_discountPercentage4PriceListSUM,0)
									END
									/*ISNULL(pitPARTS.tipi_discount,0)*/	-- MOS 05-2024: Para que los FORROS estos tengan que si el COMBO tiene un descuento MAYOR, tome el del combo. Sale de -- MOS 04-2024: Reunion con Muller
																	 / 100))	-- Debo dejar el descuento YA incluido en el combo y el combo con descuento 0 ya que cada item puede tener un descuento DIFERENTE.
																	-- al FORRO que pida que quiere el PUTO DESCUENTO en el combo se le dice NO PELOTUDO, NO SE PUEDE!!!
							)


																	[comboPrice],
							ISNULL(tpliCOMBO.curr_id,ti.curr_id)	[curr_id]

				FROM  tbPriceListItemByItemType				pit					WITH (NOLOCK)
				INNER JOIN tbCustomer					 AS tc					WITH (NOLOCK)
					ON	tc.comp_id			= pit.comp_id			AND
						tc.cust_id			= pit.cust_id

				INNER JOIN tbItemAssociation			 AS tia					WITH (NOLOCK)
					ON	tia.comp_id			= pit.comp_id			AND
						tia.item_id			= pit.item_id
				INNER JOIN tbItem							AS ti				WITH (NOLOCK)
					ON	ti.comp_id			= pit.comp_id AND
						ti.item_id			= pit.item_id
				LEFT JOIN tbPriceListItemByItemType			AS pitPARTS			WITH (NOLOCK)			-- MOS 04-2024: Reunion con Muller, de aca puedo tomar el descuento de tbItemAssociation en lugar del aquí definido.
					ON	pitPARTS.comp_id	= tia.comp_id			AND
						pitPARTS.item_id	= tia.item_id_1			AND
						pitPARTS.cust_id	= pit.cust_id
				-- Precio de la PARTE segun Definicion de listas por Tipo de Articulo
				LEFT JOIN tbPriceListItems					AS tpliPARTS		WITH (NOLOCK)
					ON	tpliPARTS.comp_id		= pitPARTS.comp_id		AND
						tpliPARTS.prli_id		= pitPARTS.prli_id		AND
						tpliPARTS.item_id		= pitPARTS.item_id



				-- Combo segun Tipo x Cliente
				LEFT JOIN tbPriceListItemByItemType			AS pitCOMBO			WITH (NOLOCK)
					ON	pitCOMBO.comp_id		= tia.comp_id			AND
						pitCOMBO.item_id		= tia.item_id			AND
						pitCOMBO.cust_id		= pit.cust_id
				LEFT JOIN tbPriceListItems					AS tpliCOMBO		WITH (NOLOCK)
					ON	tpliCOMBO.comp_id		= pitCOMBO.comp_id		AND
						tpliCOMBO.prli_id		= pitCOMBO.prli_id		AND
						tpliCOMBO.item_id		= pitCOMBO.item_id
				-- Combo segun Cliente
				LEFT JOIN tbPriceListItems					AS tpliCOMBOCuLi	WITH (NOLOCK)
					ON	tpliCOMBOCuLi.comp_id	= tia.comp_id			AND
						tpliCOMBOCuLi.item_id	= tia.item_id			AND
						tpliCOMBOCuLi.prli_id	= tc.prli_id

				-- Precio de la PARTE segun Definicion de lista del Combo si es que los
				-- ENFERMOS DE MIERDA ponen en la lista del clinete SOLO EL PUTO COMBO y no la REPUTA PARTE
				LEFT JOIN tbPriceListItems					AS tpliPARTSbyCOMBOList	WITH (NOLOCK)
					ON	tpliPARTSbyCOMBOList.comp_id	= tia.comp_id		AND
						tpliPARTSbyCOMBOList.item_id	= tia.item_id_1		AND
						tpliPARTSbyCOMBOList.prli_id	= pitCOMBO.prli_id

				-- Precio de la PARTE de Combo segun Definicion de lista del Cliente  si es que NO relacionaron la parte del combo a ninguna lista del cliente
				LEFT JOIN tbPriceListItems					AS tpliPARTSCuLi	WITH (NOLOCK)
					ON	tpliPARTSCuLi.comp_id	= tia.comp_id		AND
						tpliPARTSCuLi.item_id	= tia.item_id_1		AND
						tpliPARTSCuLi.prli_id	= tc.prli_id

				LEFT JOIN vwItemTaxesOnlyOneInternalTaxByBranch_tbPriceListItemByItemType AS hdp WITH (NOLOCK)
					ON	hdp.comp_id		= pit.comp_id		AND
						hdp.item_id		= pit.item_id

				GROUP BY pit.comp_id,pit.cust_id,pit.item_id,ti.curr_id,tpliCOMBO.curr_id

				---- Precio de la PARTE segun Definicion de lista del Cliente o Combo si es que los
				---- ENFERMOS DE MIERDA ponen en la lista del cliete SOLO EL PUTO COMBO y no la REPUTA PARTE
				--LEFT JOIN tbPriceListItems					AS tpliPARTSCuLi	WITH (NOLOCK)
				--	ON	tpliPARTSCuLi.comp_id	= tia.comp_id		AND
				--		tpliPARTSCuLi.item_id	= tia.item_id_1		AND
				--		tpliPARTSCuLi.prli_id	= ISNULL(pitCOMBO.prli_id ,tc.prli_id)





				--FROM  tbPriceListItemByItemType				pit			WITH (NOLOCK)
				--INNER JOIN tbCustomer					 AS tc			WITH (NOLOCK)
				--	ON	tc.comp_id			= pit.comp_id			AND
				--		tc.cust_id			= pit.cust_id

				--INNER JOIN tbItemAssociation			 AS tia			WITH (NOLOCK)
				--	ON	tia.comp_id			= pit.comp_id			AND
				--		tia.item_id			= pit.item_id
				--INNER JOIN tbItem						 AS ti			WITH (NOLOCK)
				--	ON	ti.comp_id			= pit.comp_id AND
				--		ti.item_id			= pit.item_id
				--LEFT JOIN tbPriceListItemByItemType		pitPARTS	WITH (NOLOCK)
				--	ON	pitPARTS.comp_id	= tia.comp_id			AND
				--		pitPARTS.item_id	= tia.item_id_1			AND
				--		pitPARTS.cust_id	= pit.cust_id
				---- Precio de la PARTE segun Definicion de listas por Tipo de Articulo
				--LEFT JOIN tbPriceListItems				 AS tpliPARTS	WITH (NOLOCK)
				--	ON	tpliPARTS.comp_id		= pitPARTS.comp_id		AND
				--		tpliPARTS.prli_id		= pitPARTS.prli_id		AND
				--		tpliPARTS.item_id		= pitPARTS.item_id
				---- Precio de la PARTE segun Definicion de lista del Cliente
				----LEFT JOIN tbPriceListItems				 AS tpliPARTSCuLi	WITH (NOLOCK)
				----	ON	tpliPARTSCuLi.comp_id	= pitPARTS.comp_id		AND
				----		tpliPARTSCuLi.prli_id	= tc.prli_id			AND
				----		tpliPARTSCuLi.item_id	= pitPARTS.item_id
				--LEFT JOIN tbPriceListItems				 AS tpliPARTSCuLi	WITH (NOLOCK)
				--	ON	tpliPARTSCuLi.comp_id	= tia.comp_id		AND
				--		tpliPARTSCuLi.prli_id	= tc.prli_id			AND
				--		tpliPARTSCuLi.item_id	= tia.item_id_1
				--LEFT JOIN tbPriceListItems				 AS tpliCOMBO	WITH (NOLOCK)
				--	ON	tpliCOMBO.comp_id		= pitPARTS.comp_id		AND
				--		tpliCOMBO.prli_id		= pitPARTS.prli_id		AND
				--		tpliCOMBO.item_id		= pitPARTS.item_id

			)

		-- Pone el precio de los COMBO en base a la suma de los precios de las partes dependiendo de las listas que corresponda cada una.
		UPDATE tbPriceListItemByItemType
			SET combo_price			=  tmp.comboPrice,		-- MOS 04-2024: Reunion con Muller: aca se debería agregar el II para que se vea incluido en el precio NETO
				tipi_discount		= 0,
				combo_pricePlusTax	=  (tmp.comboPrice * ISNULL(hdp.tax_coeficient,1)) + ((tmp.comboPrice * ISNULL(hdp.tax_coeficient,1)) * ISNULL(ttn.tax_percentage,0) / 100)	-- MOS 05-2024: Le agregue los PUTOS II para los FORROS estos: * ISNULL(hdp.tax_coeficient,1)
			FROM tbPriceListItemByItemType pit
			INNER JOIN tmpComboPrice					tmp			WITH (NOLOCK)
				ON	pit.comp_id		= tmp.comp_id AND
					pit.cust_id		= tmp.cust_id AND
					pit.item_id		= tmp.item_id
			LEFT JOIN vwItemTaxesOnlyOneIvaTax4Combo AS vitooitc	WITH (NOLOCK)
			ON	vitooitc.comp_id	= pit.comp_id AND
				vitooitc.item_id	= pit.item_id
			LEFT JOIN tbTaxName					     AS ttn		WITH (NOLOCK)
				ON	ttn.comp_id		= vitooitc.comp_id AND
					ttn.tax_id		= vitooitc.tax_id
			LEFT JOIN vwItemTaxesOnlyOneInternalTaxByBranch_tbPriceListItemByItemType AS hdp WITH (NOLOCK)
				ON	hdp.comp_id		= pit.comp_id		AND
					hdp.item_id		= pit.item_id

		-- -----------------------------------------------------------------











END
GO

