CREATE PROCEDURE [dbo].[spTMPFiles_tbWebSiteII_SizeColorPlusMercadoLibreVariations]

AS



BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- Verifica si tiene algo generado para algun sitio web...
	IF  NOT EXISTS (
						SELECT TOP 1 1
							FROM tbWebSiteII_ItemsData AS twsiid	WITH (NOLOCK)
					)
		BEGIN
			RETURN
		END


	BEGIN TRANSACTION
	BEGIN TRY
		IF DATEPART(hour,GETDATE()) = 3 AND DATEPART(minute,GETDATE()) < 40
			BEGIN
				BEGIN TRY
					TRUNCATE TABLE tbWebSiteII_SizeColorPlusMercadoLibreVariations
				END TRY
				BEGIN CATCH
					DELETE FROM tbWebSiteII_SizeColorPlusMercadoLibreVariations
				END CATCH
			END


		SELECT DISTINCT tmlip.comp_id,
						tmlip.item_id,
						tmlipv.item_id		[item_variation],
						tmlipv.mlpv_id
			INTO #tmpPublications
			FROM tbMercadoLibre_ItemsPublicados					AS tmlip		WITH (NOLOCK)
			INNER JOIN tbMercadoLibre_ItemsPublicadosVariations AS tmlipv		WITH (NOLOCK)
				ON	tmlipv.comp_id	= tmlip.comp_id		AND
					tmlipv.mlp_id	= tmlip.mlp_id
			INNER JOIN tbMercadoLibre_Stores AS tmls							WITH (NOLOCK)
				ON	tmls.comp_id	= tmlipv.comp_id	AND
					tmls.mls_id		= tmlip.mls_id
			INNER JOIN tbWebSiteII_ItemsData AS twsiid							WITH (NOLOCK)
				ON	twsiid.comp_id	= tmlip.comp_id AND
					twsiid.item_id	= tmlip.item_id
			WHERE	tmls.mls_disabled		= 'False'	AND
					tmlip.optval_statusId	= 2			AND
					--tmlip.item_id			<> tmlipv.item_id	AND        MOS 28-10-2021:  Lo saque porque en TP3D NO le ponia el color de la VARIACION q tenia el articulo IGUAL al de la publicacion princpial. ( No recuerdo por que estaba esto puesto )
					tmls.mls_webSiteII_SizeColorFromVariations = 'True'



	----==
	--SELECT * FROM #tmpPublications


		DECLARE
				@comp_id		INT,
				@item_id		INT,
				@item_variation	INT,
				@mlpv_id		INT,
				@sizeDesc		NVARCHAR(200),
				@colorDesc		NVARCHAR(200),
				@mls_id			INT	,
				@mlp_id			INT

		DECLARE curPublicaciones CURSOR LOCAL FAST_FORWARD FOR
			SELECT DISTINCT comp_id,
							item_id,
							item_variation,
							mlpv_id
				FROM #tmpPublications


		OPEN		curPublicaciones

		FETCH NEXT FROM curPublicaciones INTO	@comp_id,
												@item_id,
												@item_variation,
												@mlpv_id

		WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @sizeDesc	= ''
				SET @colorDesc	= ''

				SELECT TOP 1 @colorDesc = tmlipvc.mlat_text4Combos
					FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations AS tmlipvc 	WITH (NOLOCK)
					WHERE	tmlipvc.comp_id = @comp_id	AND
							tmlipvc.mlpv_id = @mlpv_id	AND
							tmlipvc.MLattributeID = 'COLOR'

				SELECT TOP 1 @sizeDesc = tmlipvc.attribute_combinations_name + ' ' + tmlipvc.mlat_text4Combos
					FROM tbMercadoLibre_ItemsPublicadosVariations_Combinations AS tmlipvc 	WITH (NOLOCK)
					WHERE	tmlipvc.comp_id = @comp_id	AND
							tmlipvc.mlpv_id = @mlpv_id	AND
							tmlipvc.MLattributeID <> 'COLOR'

				SELECT TOP 1	@mls_id = tmlip.mls_id,
								@mlp_id = tmlip.mlp_id
					FROM tbMercadoLibre_ItemsPublicadosVariations	AS tmlipvc				WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ItemsPublicados		AS tmlip				WITH (NOLOCK)
						ON	tmlip.comp_id	= tmlipvc.comp_id AND
							tmlip.mlp_id	= tmlipvc.mlp_id
					WHERE	tmlipvc.comp_id = @comp_id	AND
							tmlipvc.mlpv_id = @mlpv_id


				IF	@colorDesc	=  '' AND
					@sizeDesc	<> ''
					BEGIN
						SET @colorDesc = 'Único'
					END

				-- MOS 09-2021 x TP3D
				IF	@sizeDesc	=  '' AND
					@colorDesc  <> 'Único'
					BEGIN
						SET @sizeDesc = 'Único'
					END

				IF	@colorDesc	<> '' AND
					@sizeDesc	<> '' AND
					NOT EXISTS(
									SELECT TOP 1 1
										FROM tbWebSiteII_SizeColorPlusMercadoLibreVariations 	WITH (NOLOCK)
										WHERE	comp_id			= @comp_id AND
												item_id			= @item_id AND
												item_id_child	= @item_variation
							   )      AND
					NOT EXISTS(
									SELECT TOP 1 1
										FROM tbItemSizeColorRelation AS tiscr 					WITH (NOLOCK)
											WHERE	comp_id			= @comp_id AND
													item_id			= @item_id AND
													item_id_child	= @item_variation
							   )



					BEGIN
						INSERT INTO tbWebSiteII_SizeColorPlusMercadoLibreVariations
						(
							comp_id,
							item_id,
							item_id_child,
							color_id,
							color_desc,
							size_id,
							size_desc,
							mls_id,
							mlp_id,
							mlpv_id
						)
						VALUES
						(
							@comp_id,
							@item_id,
							@item_variation,
							-1,
							@colorDesc,
							-1,
							@sizeDesc,
							@mls_id,
							@mlp_id,
							@mlpv_id
						)
					END




				FETCH NEXT FROM curPublicaciones INTO	@comp_id,
														@item_id,
														@item_variation,
														@mlpv_id

			END


		CLOSE		curPublicaciones
		DEALLOCATE	curPublicaciones


		DROP TABLE #tmpPublications



		INSERT INTO tbWebSiteII_SizeColorPlusMercadoLibreVariations(comp_id,
																	item_id,
																	item_id_child,
																	color_id,
																	color_desc,
																	size_id,
																	size_desc)
			SELECT DISTINCT		tiscr.comp_id,
								tiscr.item_id,
								tiscr.item_id_child,
								tiscr.color_id,
								tc.color_desc,
								tiscr.size_id,
								ts.Size_desc
				FROM tbItemSizeColorRelation AS tiscr			WITH (NOLOCK)
				INNER JOIN tbSize AS ts							WITH (NOLOCK)
					ON	ts.comp_id = tiscr.comp_id AND
						ts.Size_id = tiscr.size_id
				INNER JOIN tbColor AS tc						WITH (NOLOCK)
					ON	tc.color_id = tiscr.color_id AND
						tc.comp_id	= tiscr.comp_id
				INNER JOIN tbWebSiteII_ItemsData AS twsiid		WITH (NOLOCK)
					ON	twsiid.comp_id = tiscr.comp_id AND
						twsiid.item_id = tiscr.item_id


			-- ----------------------------------------------------------------------------------------------------------
			-- Para que tengan un indicador de si hay stock en alguna de las variaciones internas en algun sitio web.
			-- Esto es una MIERDA LENTA !
			-- ----------------------------------------------------------------------------------------------------------
			-- x Item Principal
			UPDATE tbWebSiteII_SizeColorPlusMercadoLibreVariations
				SET bestSemaphoreValueInVariations =	CASE
															WHEN twsiid.semaphoreValue > ISNULL(scmv.bestSemaphoreValueInVariations,-1) THEN twsiid.semaphoreValue
															ELSE bestSemaphoreValueInVariations
														END
				FROM tbWebSiteII_SizeColorPlusMercadoLibreVariations scmv	WITH (NOLOCK)
				INNER JOIN tbWebSiteII_ItemsData AS twsiid					WITH (NOLOCK)
					ON	twsiid.comp_id = scmv.comp_id AND
						twsiid.item_id = scmv.item_id

			WHERE	scmv.bestSemaphoreValueInVariations IS NULL OR
					twsiid.semaphoreValue > scmv.bestSemaphoreValueInVariations

			-- x Variaciones
			UPDATE tbWebSiteII_SizeColorPlusMercadoLibreVariations
				SET bestSemaphoreValueInVariations =	CASE
															WHEN twsiid.semaphoreValue > ISNULL(scmv.bestSemaphoreValueInVariations,-1) THEN twsiid.semaphoreValue
															ELSE bestSemaphoreValueInVariations
														END
				FROM tbWebSiteII_SizeColorPlusMercadoLibreVariations scmv	WITH (NOLOCK)
				INNER JOIN tbWebSiteII_ItemsData AS twsiid					WITH (NOLOCK)
					ON	twsiid.comp_id = scmv.comp_id AND
						twsiid.item_id = scmv.item_id_child

			WHERE	scmv.bestSemaphoreValueInVariations IS NULL OR
					twsiid.semaphoreValue > scmv.bestSemaphoreValueInVariations
			-- ----------------------------------------------------------------------------------------------------------

		COMMIT TRANSACTION
--		CHECKPOINT   q lo haga cuando pueda...


	END TRY
	BEGIN CATCH
		ROLLBACK TRANSACTION
	END CATCH



END
GO


