CREATE pROCEDURE [dbo].[spTMPFiles_UpdateWebSiteItems]
AS

-- =================================================================================================================
-- Author		: MOS
-- Updates
-- 09-2023: Deprecated for ever !!!!!!
-- =================================================================================================================
BEGIN

	-- MOS 09-2023: NO LLAMAR DIRECTO A ESTE SP !!!!  YA NO SE COMO MIERDA DECIRLOOOOOOOOOOOOOOOOOOO!!!!!!!!!!!!!!!!
	SELECT 'NO LLAMAR DIRECTO A ESTE SP !!!!  YA NO SE COMO MIERDA DECIRLOOOOOOOOOOOOOOOOOOO!!!!!!!!!!!!!!!!'
	RETURN

	set nocount ON
	-- SET LOCK_TIMEOUT 120000  MOS 03-2023 x adma
	DECLARE @intRowCount AS INT = 0

	SELECT '00. Begin Process:',GETDATE();




	IF NOT EXISTS	(
						SELECT TOP 1 1
							FROM tbWebSiteII_Names AS twsin WITH (NOLOCK)
					)
		BEGIN
			RETURN
		END



	BEGIN TRY
		--BEGIN TRANSACTION



			-- ------------------------------------------------------------------------------------
			-- Si se necesita MATAR los datos de una determinada lista previamente calculados
			-- AYUDA: Esto se usa x ejemplo para MATAR a todos los items que se muestrasn de una DETERMINADA
			-- LIsta
			-- ------------------------------------------------------------------------------------
			IF EXISTS(	SELECT TOP 1 1
							FROM tbWebSiteII_PriceListRelation ii  WITH (NOLOCK)
			          		WHERE ii.wsplr_DeleteItemsFromThieRelation = 1
					 )
				BEGIN
					IF EXISTS(
								SELECT TOP 1 1
									FROM tbWebSiteII_ItemsData				AS twsiid	WITH (NOLOCK)
									INNER JOIN tbWebSiteII_PriceListRelation   tt		WITH (NOLOCK)
															ON	tt.comp_id	= twsiid.comp_id	AND
																tt.ws_id	= twsiid.ws_id		AND
																tt.prli_id	= twsiid.prli_id	AND
																tt.wsplr_DeleteItemsFromThieRelation = 1
						     )
					--BEGIN TRANSACTION
						BEGIN TRY
							SELECT '01. Depurando Relaciones de Listas Deshabilitadas Process:',GETDATE();
							DELETE   tbWebSiteII_ItemsData	--WITH (TABLOCK)
								FROM tbWebSiteII_ItemsData					AS  twsiid	WITH (NOLOCK)
								INNER JOIN tbWebSiteII_PriceListRelation		tt		WITH (NOLOCK)
									ON	tt.comp_id	= twsiid.comp_id	AND
										tt.ws_id	= twsiid.ws_id		AND
										tt.prli_id	= twsiid.prli_id	AND
										tt.wsplr_DeleteItemsFromThieRelation = 1
						END TRY
						BEGIN CATCH
						END CATCH
					--COMMIT TRANSACTION
					--CHECKPOINT
				END
			-- ------------------------------------------------------------------------------------


SELECT '02. Select WEB Items:',GETDATE();



			SELECT	ti.comp_id,
					ti.item_id,
					ti.cat_id,
					ti.subcat_id,
					ti.subcataux_id,
					ti.ic_id
				INTO #tmpItem
				FROM tbItem ti									WITH (NOLOCK)
				INNER JOIN tbCategory tc						WITH (NOLOCK)
					ON	tc.comp_id		= ti.comp_id AND
						tc.cat_id		= ti.cat_id
				INNER JOIN tbSubCategory tsc					WITH (NOLOCK)
					ON	tsc.comp_id		= ti.comp_id AND
						tsc.cat_id		= ti.cat_id  AND
						tsc.subcat_id	= ti.subcat_id
				LEFT JOIN tbSubCategoryAux tsca					WITH (NOLOCK)
					ON	tsca.comp_id		= ti.comp_id AND
						tsca.subcataux_id	= ti.subcataux_id
				WHERE	tc.cat_web			= 'True' AND
						tsc.subcat_web		= 'True' AND
						ti.item_web			= 'True' AND
					   (tsca.comp_id IS NULL OR tsca.subcataux_web = 'True')	AND
						ti.item_disabled	= 'False'

			IF @@ROWCOUNT = 0
				BEGIN
					TRUNCATE TABLE tbWebSiteII_Names
					RETURN
				END



			-- NO, MOS 07-2017, se agrego y saco porque no sirve aca
			--DELETE #tmpItem
			--	FROM #tmpItem tmp
			--	INNER JOIN tbItemSizeColorRelation tis
			--		ON	tis.comp_id			= tmp.comp_id AND
			--			tis.item_id_child	= tmp.item_id


SELECT '03. Select Insert into tbWebSiteII_AutoSelected:',GETDATE()

			TRUNCATE TABLE tbWebSiteII_Items_AutoSelected
			INSERT INTO tbWebSiteII_Items_AutoSelected
			(
				comp_id,
				item_id,
				cat_id,
				subcat_id,
				subcataux_id,
				ic_id
			)
			SELECT	ti.comp_id,
					ti.item_id,
					ti.cat_id,
					ti.subcat_id,
					ti.subcataux_id,
					ti.ic_id
				FROM #tmpItem	ti	 WITH (NOLOCK)


--==
			--WHERE item_id = 113
--==

			DROP TABLE #tmpItem


			-- 2do Paso



			-- ---------------------------------------------------------------------------------------------
			-- Selecciono los articulos que estaban en la vieja vista, la cual de va a borrar.-
			-- ---------------------------------------------------------------------------------------------
			DECLARE @tblStorages	TABLE(	comp_id INT,
											stor_id INT,
											stor_MustRecalculateAvailableStock BIT
											UNIQUE CLUSTERED (comp_id,stor_id)
										 )
			DECLARE @tblItemStorage TABLE(	comp_id INT,
											stor_id INT,
											item_id INT ,
											stockFisico DECIMAL(19,4),
											stockFisicoSG DECIMAL(19,4),
											stockDisponibleSG DECIMAL(19,4),
											itst_LastAvailableInRelalculation decimal(19,4),
											bestSemaphoreValueInVariations INT,
											UNIQUE CLUSTERED (comp_id, stor_id,item_id)
										)

			INSERT INTO @tblStorages(comp_id, stor_id, stor_MustRecalculateAvailableStock)
			SELECT DISTINCT  plr.comp_id, plr.stor_id,ts.stor_mustRecalculateAvailableStock
				FROM tbWebSiteII_PriceListRelation plr		WITH (NOLOCK)
				LEFT JOIN tbStorage ts						WITH (NOLOCK)
					ON	ts.comp_id = plr.comp_id AND
						ts.stor_id = plr.stor_id
				WHERE plr.wsplr_disabled = 0 AND plr.wsplr_DeleteItemsFromThieRelation = 0






SELECT '04. Calculate Item Stock:',GETDATE()


			INSERT INTO @tblItemStorage(	comp_id,
											stor_id,
											item_id,
											stockFisico,
											stockFisicoSG,
											stockDisponibleSG,
											itst_LastAvailableInRelalculation,
											bestSemaphoreValueInVariations
			)
			SELECT	tmp.comp_id,
					tmp.stor_id,
					tas.item_id,
					ISNULL(tis.itst_cant,0),
					dbo.fnGetStockOfStorageGroup4MaxAssociation( tmp.comp_id,tmp.stor_id,tas.item_id),
					/*dbo.fnGetStockOfStorageGroup(tmp.comp_id,tmp.stor_id,tas.item_id)*/  --MOS 02-2021 * BedCollection Combos,
					CASE
						WHEN	tmp.stor_MustRecalculateAvailableStock	= 'True'	AND			--**
								ti.item_isForAssociation				= 'False'	AND
								-- MOS 04-2023
								tis.itst_LastAvailableInRelalculation IS NOT NULL 								THEN tis.itst_LastAvailableInRelalculation
						ELSE																						 dbo.fnGetAStock4MaxAssociation(  tmp.comp_id,tmp.stor_id,tas.item_id,999999999)
					END,
					ISNULL(itst_LastAvailableInRelalculation,0),
					0
				FROM tbWebSiteII_Items_AutoSelected tas WITH (NOLOCK)
				INNER JOIN tbItem					ti	WITH (NOLOCK)
					ON	ti.comp_id = tas.comp_id AND
						ti.item_id = tas.item_id
				INNER JOIN @tblStorages				tmp
					ON tmp.comp_id = tas.comp_id
				LEFT JOIN tbItemStorage				tis	WITH (NOLOCK)
					ON	tis.comp_id = tmp.comp_id AND
						tis.stor_id = tmp.stor_id AND
						tis.item_id = tas.item_id

		-- MOS 04-2023: no se por que MIERDA en el case de abajo SIEMPRE daba -9999999 cuando en esta tabla estaban bien los valores.  lo fuerzoi aca y anda.  SQL y LRPMQTP
		UPDATE @tblItemStorage SET stockDisponibleSG =	CASE
															WHEN stockDisponibleSG >  9999999  THEN  9999999
															WHEN stockDisponibleSG < -9999999  THEN -9999999
															ELSE stockDisponibleSG
														END


--SELECT '@tblItemStorage',* FROM @tblItemStorage

		-- ---------------------------------------------------------------------------------------------------------------
		-- Modulo 104 de talles y colores a MeLi
		-- Si tiene la mierda de mercadolibre, recalcular el campo de stock de variaciones para incluir en la tabla final
		-- ---------------------------------------------------------------------------------------------------------------
		;WITH ctrItemStorage (comp_id,stor_id,item_id,qty) AS (
									SELECT tmp.comp_id,tmp.stor_id,tmp.item_id,SUM(dbo.fnGetAStock4MaxAssociation(tmp.comp_id,tmp.stor_id,tmlipv.item_id ,999999999))
											FROM @tblItemStorage tmp
											INNER JOIN  tbMercadoLibre_ItemsPublicados					AS tmlip		WITH (NOLOCK)
												ON	tmlip.comp_id = tmp.comp_id			AND
													tmlip.item_id = tmp.item_id
											INNER JOIN tbMercadoLibre_Stores							AS tmls			WITH (NOLOCK)
												ON	tmls.comp_id	= tmlip.comp_id		AND
													tmls.mls_id		= tmlip.mls_id
											INNER JOIN tbMercadoLibre_ItemsPublicadosVariations			AS tmlipv		WITH (NOLOCK)
												ON	tmlipv.comp_id	= tmlip.comp_id		AND
													tmlipv.mlp_id	= tmlip.mlp_id
											WHERE	tmls.mls_webSiteII_SizeColorFromVariations = 'True' AND
													tmls.mls_disabled		= 'False'					AND
													tmlip.optval_statusId	= 2							AND
													tmlip.item_id			<> tmlipv.item_id			AND
													tmp.stor_id =	CASE
																		WHEN tmlip.stor_id4StockAvailability IS NOT NULL THEN tmlip.stor_id4StockAvailability
																		ELSE tmls.stor_id4StockAvailability
																	END
											GROUP BY tmp.comp_id,tmp.stor_id,tmp.item_id
								)


		UPDATE @tblItemStorage
			SET bestSemaphoreValueInVariations =
												CASE
													WHEN IsNull(ctr.qty,0) >= ti.item_cantOpt	THEN 4
													WHEN IsNull(ctr.qty,0) >= ti.item_cantMin	THEN 3
													WHEN IsNull(ctr.qty,0) >  0					THEN 2
													ELSE											 1
												END
			FROM @tblItemStorage tmp
			INNER JOIN  ctrItemStorage					AS ctr
				ON	ctr.comp_id = tmp.comp_id			AND
					ctr.stor_id = tmp.stor_id			AND
					ctr.item_id = tmp.item_id
			INNER JOIN tbItem AS ti	WITH (NOLOCK)
				ON	ti.comp_id = tmp.comp_id AND
					ti.item_id = tmp.item_id

--SELECT '@tblItemStorage',* FROM @tblItemStorage WHERE item_id = 9859
		-- ---------------------------------------------------------------------------------------------------------------



			DECLARE @tblData TABLE
				(
				comp_id		int NOT NULL,
				ws_id		UNIQUEIDENTIFIER NOT NULL ,
				item_id		int NOT NULL,
				stor_id		int NOT NULL,
				stock		int NULL,
				stockType	int NULL,
				prli_id		INT NULL,
				--taxCoeficient DECIMAL(25,8)
				INDEX IDX CLUSTERED(comp_id,ws_id,item_id,stor_id,stockType,prli_id)
				)

			--CREATE TABLE #tblData
			--	(
			--	comp_id int NOT NULL,
			--	ws_id	UNIQUEIDENTIFIER NOT NULL ,
			--	item_id int NOT NULL,
			--	stor_id int NOT NULL,
			--	stock int NULL,
			--	stockType	int NULL,
			--	prli_id		INT NULL
			--	)  ON [PRIMARY]

			--CREATE NONCLUSTERED INDEX IX_#tblData ON #tblData
			--	(
			--	comp_id,
			--	item_id,
			--	stor_id
			--	) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]

			--CREATE NONCLUSTERED INDEX IX_#tblDataII ON #tblData
			--	(
			--	comp_id,ws_id,item_id,stor_id,stockType,prli_id
			--	) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]


			SELECT DISTINCT  plr.comp_id, plr.ws_id, plr.stor_id, plr.wsplr_StockType, plr.wsplr_UseFastCheck,plr.prli_id
				INTO #CTEStorage
				FROM tbWebSiteII_PriceListRelation plr		WITH (NOLOCK)
				WHERE plr.wsplr_disabled = 0 AND plr.wsplr_DeleteItemsFromThieRelation = 0



SELECT '05. Inserting Into tblData:',GETDATE()

			insert into @tblData (comp_id,ws_id,item_id,stor_id,stock,StockType,prli_id) --,taxCoeficient)
				SELECT	--distinct
						tpli.comp_id,
						twsiplr.ws_id,
						tpli.item_id,
						twsiplr.stor_id,
						CASE
							WHEN ti.item_NoStockCheck		= 1										THEN 9999999
							WHEN twsiplr.wsplr_StockType	= 0 																					THEN 1	-- Sin Filtro de Stock
							--Uso precalculo rapido para filtrar ( mas velocidad pero puede no incluir algun articulo por 3 minutos aproximadamente )
							WHEN twsiplr.wsplr_UseFastCheck = 'True' AND tmp.itst_LastAvailableInRelalculation > 0 THEN
								CASE
									WHEN twsiplr.wsplr_StockType = 1 AND  tmp.stockFisico        > 0														 THEN 1	-- Stock Fisico
									WHEN twsiplr.wsplr_StockType = 2 AND  tmp.stockFisicoSG      > 0  THEN 1	-- Stock Fisico del Grupo de depositos
									WHEN twsiplr.wsplr_StockType = 3 AND (tmp.stockDisponibleSG  > 0 OR tmp.bestSemaphoreValueInVariations > 1)  THEN 1	-- Stock Fisico del Grupo de depositos
									ELSE 0
								END
							-- Uso calculo on line
							WHEN twsiplr.wsplr_UseFastCheck = 'False'						THEN
								CASE
									WHEN twsiplr.wsplr_StockType = 1 AND  tmp.stockFisico        > 0		THEN 1	-- Stock Fisico
									WHEN twsiplr.wsplr_StockType = 2 AND  tmp.stockFisicoSG      > 0		THEN 1	-- Stock Fisico del Grupo de depositos
									WHEN twsiplr.wsplr_StockType = 3 AND (tmp.stockDisponibleSG  > 0  OR tmp.bestSemaphoreValueInVariations > 1)		THEN 1	-- Stock Fisico del Grupo de depositos
									ELSE 0
								END
							ELSE 0
						END,
						twsiplr.wsplr_StockType,
						twsiplr.prli_id--,
						--dbo.fnGetPriceListItemTaxesCoeficient4Combo(tpli.comp_id,twsin.bra_id,tpli.item_id,tpli.prli_id),tpli.

					FROM tbWebSiteII_Items_AutoSelected tpli	WITH (NOLOCK)
					INNER JOIN	tbItem					ti		WITH (NOLOCK)
						ON	ti.comp_id = tpli.comp_id AND
							ti.item_id = tpli.item_id
					INNER JOIN #CTEStorage				twsiplr	WITH (NOLOCK)
						ON	twsiplr.comp_id = tpli.comp_id

					INNER JOIN @tblItemStorage					tmp
						ON	tmp.comp_id = tpli.comp_id		AND
							tmp.stor_id = twsiplr.stor_id	AND
							tmp.item_id = tpli.item_id



			DROP TABLE #CTEStorage

SELECT '06. Selecting Items :',GETDATE()

			SELECT
					--DISTINCT
					--TOP 90000000
					tpli.comp_id,
					tpli.prli_id,
					tpli.item_id,


					-- -----------------------------------------------
					-- Precio Con o Sin Impuestos Segun Configuracion, corregir en Precio SIN Impuestos si se toca algo aca
					-- -----------------------------------------------
					dbo.fnRoundWebSitePrices(
											  (
												(
													CASE
														WHEN	twsiplr.curr_id IS NULL THEN	tpli.prli_price
														ELSE									dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id,twsiplr.curr_id, 0, 0 , 0 , 'False')
													END

														*
													CASE
														WHEN twsiplr.wsplr_ShowPriceInCero = 1 THEN 0
														ELSE										1
													END
														*
													CASE
														WHEN twm.wsmsp_priceType = 1		THEN ((twm.wsmsp_value / 100) + 1)	-- Multiplica por Coeficiente
														ELSE 1
													END

													*

													CASE
														WHEN twm.wsmsp_priceType = 3		THEN 0	-- Precio NETO, pone en CERO para que lo sume abajo
														ELSE 1
													END

												)
													+
												CASE
													WHEN twm.wsmsp_priceType = 2	OR twm.wsmsp_priceType  = 3	THEN twm.wsmsp_value				-- Suma Precio
													ELSE 0
												END
											  )

											*
												CASE
													WHEN twsiplr.wsplr_ShowPriceWithTaxes = 'True' THEN dbo.fnGetPriceListItemTaxesCoeficient4Combo(tpli.comp_id,twsin.bra_id,tpli.item_id,tpli.prli_id)
													ELSE												1
												END	,twm.wsmsp_priceRoundType
												)															[prli_price],

					-- -----------------------------------------------


					CASE
						WHEN	twsiplr.curr_id IS NULL THEN	tpli.curr_id
						ELSE									twsiplr.curr_id
					END																[curr_id],
					twsiplr.ws_id,
					tis.stockFisicoSG			/*tis.stockFisico 08-2018 Sonnos*/	[itst_cant],
					--CASE
					--	WHEN tis.stockDisponibleSG >= 9999999	THEN  9999999
					--	WHEN tis.stockDisponibleSG <= 9999999	THEN -9999999
					--	ELSE tis.stockDisponibleSG
					--END																[itst_availableQTY],
					tis.stockDisponibleSG											[itst_availableQTY],
					IsNull(tis.itst_LastAvailableInRelalculation,0)					[itst_LastAvailableInRelalculation],
					ti.cat_id,
					ti.subcat_id,
					ti.subcataux_id,
					ti.ic_id,
					CASE
						WHEN	twsiplr.curr_id IS NULL THEN	tc.curr_symbol
						ELSE									tcR.curr_symbol
					END																[currency_symbol],
					CASE
						-- MOS 10-2018
						WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND tis.itst_LastAvailableInRelalculation > 0 AND tis.itst_LastAvailableInRelalculation >= ti.item_cantOpt			THEN 4	-- MOS 06-2017
						WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND tis.itst_LastAvailableInRelalculation > 0 AND tis.itst_LastAvailableInRelalculation >= ti.item_cantMin			THEN 3	-- MOS 06-2017
						WHEN	twsiplr.wsplr_UseFastCheck	 = 1				AND
								tis.itst_LastAvailableInRelalculation >  0		AND
								ti.item_cantOpt = 0								AND
								ti.item_cantMin = 0																																THEN 4  -- MOS 06-2020
						WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND tis.itst_LastAvailableInRelalculation >  0																		THEN 2	-- MOS 06-2017
						WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND ISNULL(tis.itst_LastAvailableInRelalculation,0) <= 0															THEN 1	-- MOS 06-2017
						-- MOS 7-2017
						--WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND IsNull(tis.itst_LastAvailableInRelalculation,0) >= ti.item_cantOpt						THEN 4	-- MOS 06-2017
						--WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND IsNull(tis.itst_LastAvailableInRelalculation,0) >= ti.item_cantMin						THEN 3	-- MOS 06-2017
						--WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND IsNull(tis.itst_LastAvailableInRelalculation,0) >  0									THEN 2	-- MOS 06-2017
						--WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND IsNull(tis.itst_LastAvailableInRelalculation,0) <= 0									THEN 1	-- MOS 06-2017
						WHEN ti.item_cantOpt > 0 AND
							(twsiplr.wsplr_UseFastCheck	 = 0 AND dbo.fnGetAStock4MaxAssociation(ti.comp_id, twsiplr.stor_id, ti.item_id, 89999999)	>= ti.item_cantOpt AND ti.item_cantOpt > 0)	THEN 4
						WHEN ti.item_cantMin > 0 AND
							(twsiplr.wsplr_UseFastCheck	 = 0 AND dbo.fnGetAStock4MaxAssociation(ti.comp_id, twsiplr.stor_id, ti.item_id, 89999999)	>= ti.item_cantMin AND ti.item_cantMin > 0)	THEN 3
						WHEN twsiplr.wsplr_UseFastCheck	 = 0 AND dbo.fnGetAStock4MaxAssociation(ti.comp_id, twsiplr.stor_id, ti.item_id, 89999999)	>  0						THEN
																																								CASE	-- MOS 06-2020
																																									WHEN ti.item_cantOpt = 0 AND ti.item_cantMin = 0 THEN 4
																																									ELSE 2
																																								END
							--2
						ELSE																																 1
						--WHEN IsNull(tis.itst_LastAvailableInRelalculation,0) >= ti.item_cantOpt THEN 4
						--WHEN IsNull(tis.itst_LastAvailableInRelalculation,0) >= ti.item_cantMin THEN 3
						--WHEN IsNull(tis.itst_LastAvailableInRelalculation,0) >  0				THEN 2
						--ELSE																		 1
					END																[semaphoreValue],





					-- -----------------------------------------------
					-- Precio Sin Impuestos
					-- -----------------------------------------------
					CONVERT(DECIMAL(28,4),
					dbo.fnRoundWebSitePrices(
											  (
												(
													(
														CASE
															WHEN	twsiplr.curr_id IS NULL THEN	tpli.prli_price
															ELSE									dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id,twsiplr.curr_id, 0, 0 , 0 , 'False')
														END

															*
														CASE
															WHEN twsiplr.wsplr_ShowPriceInCero = 1 THEN 0
															ELSE										1
														END
															*
														CASE
															WHEN twm.wsmsp_priceType = 1		THEN ((twm.wsmsp_value / 100) + 1)	-- Multiplica por Coeficiente
															ELSE 1
														END

															*

														CASE
															WHEN twm.wsmsp_priceType = 3		THEN 0	-- Precio NETO, pone en CERO para que lo sume abajo
															ELSE 1
														END

													)
														+
													CASE
														WHEN twm.wsmsp_priceType = 2 OR twm.wsmsp_priceType  = 3		THEN twm.wsmsp_value				-- Suma Precio
														ELSE 0
													END
												)
											  )

												*
												CASE
													WHEN twsiplr.wsplr_ShowPriceWithTaxes = 'True' THEN dbo.fnGetPriceListItemTaxesCoeficient4Combo(tpli.comp_id,twsin.bra_id,tpli.item_id,tpli.prli_id) --dbo.fnGetPriceListItemTaxesCoeficient(tpli.comp_id, tpli.item_id)
													ELSE												1
												END
												,twm.wsmsp_priceRoundType
											)

					/
					dbo.fnNoZDiv(
									CASE
										WHEN twsiplr.wsplr_ShowPriceWithTaxes = 'True' THEN dbo.fnGetPriceListItemTaxesCoeficient4Combo(tpli.comp_id,twsin.bra_id,tpli.item_id,tpli.prli_id) --dbo.fnGetPriceListItemTaxesCoeficient(tpli.comp_id, tpli.item_id)
										ELSE												1
									END
								)
							)
																		[prli_priceNOTaxes],
					-- -----------------------------------------------
					tmpCTE.StockType,
					-- -----------------------------------------------
					-- Precio TACHADO Con o Sin Impuestos Segun Configuracion, corregir en Precio SIN Impuestos si se toca algo aca
					-- -----------------------------------------------
					CASE
						WHEN tpliSP.comp_id IS NOT NULL THEN

																dbo.fnRoundWebSitePrices(
																						  (
																							(
																								CASE
																									WHEN	twsiplr.curr_id IS NULL THEN	tpliSP.prli_price
																									ELSE									dbo.fnGetExchange2(tpliSP.comp_id, tpliSP.prli_price, tpliSP.curr_id,twsiplr.curr_id, 0, 0 , 0 , 'False')
																								END

																									*
																								CASE
																									WHEN twsiplr.wsplr_ShowPriceInCero = 1 THEN 0
																									ELSE										1
																								END
																									*
																								CASE
																									WHEN twm.wsmsp_priceType = 1		THEN ((twm.wsmsp_value / 100) + 1)	-- Multiplica por Coeficiente
																									ELSE 1
																								END

																								*

																								CASE
																									WHEN twm.wsmsp_priceType = 3		THEN 0	-- Precio NETO, pone en CERO para que lo sume abajo
																									ELSE 1
																								END

																							)
																								+
																							CASE
																								WHEN twm.wsmsp_priceType = 2	OR twm.wsmsp_priceType  = 3	THEN twm.wsmsp_value				-- Suma Precio
																								ELSE 0
																							END
																						  )

																						*
																							CASE
																								WHEN twsiplr.wsplr_ShowPriceWithTaxes = 'True' THEN dbo.fnGetPriceListItemTaxesCoeficient4Combo(tpli.comp_id,twsin.bra_id,tpli.item_id,tpli.prli_id) --dbo.fnGetPriceListItemTaxesCoeficient(tpliSP.comp_id, tpliSP.item_id)
																								ELSE												1
																							END	,twm.wsmsp_priceRoundType
																							)
						ELSE  0
					END																	[strikeThroughPrice],
					-- -----------------------------------------------
					-- -----------------------------------------------
					-- Precio Sin Impuestos
					-- -----------------------------------------------
					CASE
						WHEN tpliSP.comp_id IS NOT NULL THEN
																dbo.fnRoundWebSitePrices(
																						  (
																							(
																								(
																									CASE
																										WHEN	twsiplr.curr_id IS NULL THEN	tpliSP.prli_price
																										ELSE									dbo.fnGetExchange2(tpliSP.comp_id, tpliSP.prli_price, tpliSP.curr_id,twsiplr.curr_id, 0, 0 , 0 , 'False')
																									END

																										*
																									CASE
																										WHEN twsiplr.wsplr_ShowPriceInCero = 1 THEN 0
																										ELSE										1
																									END
																										*
																									CASE
																										WHEN twm.wsmsp_priceType = 1		THEN ((twm.wsmsp_value / 100) + 1)	-- Multiplica por Coeficiente
																										ELSE 1
																									END

																										*

																									CASE
																										WHEN twm.wsmsp_priceType = 3		THEN 0	-- Precio NETO, pone en CERO para que lo sume abajo
																										ELSE 1
																									END

																								)
																									+
																								CASE
																									WHEN twm.wsmsp_priceType = 2 OR twm.wsmsp_priceType  = 3		THEN twm.wsmsp_value				-- Suma Precio
																									ELSE 0
																								END
																							)
																						  )

																							*
																							CASE
																								WHEN twsiplr.wsplr_ShowPriceWithTaxes = 'True' THEN dbo.fnGetPriceListItemTaxesCoeficient4Combo(tpli.comp_id,twsin.bra_id,tpli.item_id,tpli.prli_id) --dbo.fnGetPriceListItemTaxesCoeficient(tpliSP.comp_id, tpliSP.item_id)
																								ELSE												1
																							END
																							,twm.wsmsp_priceRoundType
																						)

																/
																dbo.fnNoZDiv(
																				CASE
																					WHEN twsiplr.wsplr_ShowPriceWithTaxes = 'True' THEN dbo.fnGetPriceListItemTaxesCoeficient4Combo(tpli.comp_id,twsin.bra_id,tpli.item_id,tpli.prli_id) --dbo.fnGetPriceListItemTaxesCoeficient(tpliSP.comp_id, tpliSP.item_id)
																					ELSE												1
																				END
																			)
						ELSE 0
					END														[strikeThroughPriceNOTaxes]
					-- -----------------------------------------------




				INTO #tmpFile
				FROM dbo.tbPriceListItems tpli								WITH (NOLOCK)




				INNER JOIN dbo.tbWebSiteII_PriceListRelation twsiplr		WITH (NOLOCK)
					ON	twsiplr.comp_id = tpli.comp_id AND
						twsiplr.prli_id = tpli.prli_id

-- comp_id,ws_id,item_id,stor_id,stock,stockType,prli_id
				INNER JOIN @tblData tmpCTE									--WITH (NOLOCK)
					ON	tmpCTE.comp_id		= tpli.comp_id				AND
						tmpCTE.ws_id		= twsiplr.ws_id				AND
						tmpCTE.item_id		= tpli.item_id				AND
						tmpCTE.stor_id		= twsiplr.stor_id			AND
						tmpCTE.stockType	= twsiplr.wsplr_StockType	AND
						tmpCTE.prli_id		= twsiplr.prli_id

				INNER JOIN tbItem ti										WITH (NOLOCK)
					ON	ti.comp_id	= tpli.comp_id	AND
						ti.item_id	= tpli.item_id

				INNER JOIN tbWebSiteII_Names twsin							WITH (NOLOCK)
					ON	twsin.comp_id	= twsiplr.comp_id AND
						twsin.ws_id		= twsiplr.ws_id

				LEFT JOIN tbPriceListItems tpliSP							WITH (NOLOCK)
					ON	tpliSP.comp_id = tpli.comp_id					AND
						tpliSP.prli_id = twsin.prli_id_4strikeThrough	AND
						tpliSP.item_id = tpli.item_id

				INNER JOIN dbo.tbsysCurrency				tc				WITH (NOLOCK)
					ON tc.curr_id = tpli.curr_id

				LEFT  JOIN dbo.tbsysCurrency				tcR				WITH (NOLOCK)
					ON tcR.curr_id = twsiplr.curr_id


				--LEFT JOIN dbo.tbItemStorage					tis				WITH (NOLOCK)
				--	ON	tis.comp_id = twsiplr.comp_id AND
				--		tis.stor_id = twsiplr.stor_id AND
				--		tis.item_id = tpli.item_id


				INNER JOIN @tblItemStorage				tis				--WITH (NOLOCK)
					ON	tis.comp_id = twsiplr.comp_id AND
						tis.stor_id = twsiplr.stor_id AND
						tis.item_id = tpli.item_id


				-- Para saber si YA ESTA como articulo o no.
				-- Solo se usa en el left de abajo para no duplicar filas si un art esta x art y por subcat
				LEFT JOIN tbWebSiteII_microSites			mst			WITH (NOLOCK)
					ON	mst.comp_id				= tpli.comp_id	AND
						mst.ws_id				= twsiplr.ws_id		AND
						mst.item_id				= tpli.item_id		AND
						mst.prli_id				= tpli.prli_id		AND
						mst.wsmsp_isDisabled	= 0
				LEFT JOIN tbWebSiteII_microSites			twm				WITH (NOLOCK)
					ON	twm.comp_id				= twsiplr.comp_id	AND
						twm.ws_id				= twsiplr.ws_id		AND
						twm.prli_id				= tpli.prli_id		AND
						twm.wsmsp_isDisabled	= 'False'			AND
						CASE
							WHEN	twm.comp_id IS NULL				THEN	0
							WHEN	twm.item_id		= ti.item_id	THEN	1
							WHEN	twm.cat_id		= ti.cat_id		AND
									twm.subcat_id	= ti.subcat_id	AND
									mst.comp_id IS NULL				THEN	1
							ELSE											0
						END		= 1

				LEFT JOIN  tbBranchGroupDetail tg		WITH (NOLOCK)		-- MOS   04-2020 x velocidad
					ON	tg.comp_id = ti.comp_id AND
						tg.brag_id = ti.brag_id AND
						tg.bra_id  = twsin.bra_id

				-- Para saber si YA ESTA como articulo o no.
				-- Solo se usa en el left de abajo para no duplicar filas si un art esta x art y por subcat
				WHERE
					twsiplr.wsplr_disabled = 0									AND
					twsiplr.wsplr_DeleteItemsFromThieRelation = 0				AND
					(
						tpli.prli_price								> 0
							OR
						twsiplr.wsplr_ShowPriceInCero				= 1
							OR
						twsiplr.wsplr_IncludeItemsWithPriceInCero	= 1
					)															AND


					(
						tmpCTE.StockType = 0 OR
							( tmpCTE.StockType > 0 AND tmpCTE.Stock > 0 )
					)

						 				AND
					-- Si es un Micrositio SI o SI debe tener cargado un porcentaje o precio adicional
					CASE
						WHEN	twsin.user_id4MicroSites IS NULL									THEN 1
						WHEN	twsin.user_id4MicroSites IS NOT NULL  AND
								twm.comp_id				 IS NOT NULL								THEN 1
						ELSE																			 0
					END	= 1				AND
					-- NUEVO, MOS 21-10-2019: Si hay definidas sucursales o grupos de suc para ese articulo que los tome en cuenta para incluirlos en el sitio web.
					(
						(ti.bra_id IS NULL AND ti.brag_id IS NULL)
							OR
						ti.bra_id = twsin.bra_id
							OR
						tg.comp_id IS NOT NULL
						--EXISTS(
						--		SELECT TOP 1 1
						--			FROM tbBranchGroupDetail tg		WITH (NOLOCK)
						--			WHERE	tg.comp_id = ti.comp_id AND
						--					tg.brag_id = ti.brag_id AND
						--					tg.bra_id  = twsin.bra_id
						--		)
					)



