SELECT '06.02 Indexing #tmpFileIndex :',GETDATE()



			--drop table #tblData
			-- ----------------------------------------------------------------------------------------------



			CREATE NONCLUSTERED INDEX #tmpFileIndex ON #tmpFile
				(
				comp_id,
				ws_id,
				prli_id,
				item_id
				) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]




			-- --------------------------------------------------------------------
			-- Obtengo los ItemID para calcular las descripciones una sola vez
			-- --------------------------------------------------------------------
			DECLARE @tmpItems TABLE(item_id INT PRIMARY KEY)
			INSERT INTO @tmpItems(item_id)
				SELECT DISTINCT item_id
					FROM #tmpFile
			-- --------------------------------------------------------------------


SELECT '06.03 Inserting  @tmpItemDescription :',GETDATE()

			-- --------------------------------------------------------------------
			-- Calculo las descripciones, LO MAS PESADO DE TODO
			-- --------------------------------------------------------------------
			DECLARE @tmpItemDescription TABLE(	item_id				INT PRIMARY KEY,
												itemDescription		CHAR(300),
												itemHTML			VARCHAR(8000))
			INSERT INTO @tmpItemDescription(item_id, itemDescription, itemHTML)
			SELECT
				ti.item_id,
				LTRIM(RTRIM(
				dbo.fnSTRRemoveSpecialCharacters
												(
													CASE
														WHEN ISNULL(ti.item_WebSite_desc,'') <> '' THEN	ti.item_WebSite_desc
														ELSE									ti.item_desc
													END
												)
							))																		[itemDescription],
				CONVERT(VARCHAR(8000),LTRIM(RTRIM(dbo.fnStrStripHTML4TMPFiles(ISNULL(ti.item_descHTML,'')))))	[itemHTML]
				-- MOS 05-2023: Tardaba infinitamente mas con VARCHAR(MAX)...  CyberDyne.    CONVERT(CHAR(890),LTRIM(RTRIM(dbo.fnStrStripHTML(ISNULL(ti.item_descHTML,'')))))	[itemHTML]
				FROM tbItem AS ti					WITH (NOLOCK)
				INNER JOIN @tmpItems tmp
					ON tmp.item_id = ti.item_id
			-- --------------------------------------------------------------------






			--BEGIN TRY
			--	BEGIN TRANSACTION


		SELECT '07. BEGIN Deleting  Items:',GETDATE()		-- que NO deben estar mas
					-- Borra lo modificado
					--BEGIN TRANSACTION
						DELETE FROM tbWebSiteII_ItemsData	--WITH (TABLOCK)
							FROM tbWebSiteII_ItemsData	tbl			--WITH (NOLOCK)
							LEFT JOIN #tmpFile			tmp			WITH (NOLOCK)
								ON	tmp.comp_id = tbl.comp_id	AND
									tmp.ws_id	= tbl.ws_id		AND
									tmp.prli_id = tbl.prli_id	AND
									tmp.item_id	= tbl.item_id
							WHERE	tmp.comp_id IS NULL			--OR
									--(
									--	tmp.prli_price							<> tbl.prli_price							OR
									--	tmp.curr_id								<> tbl.curr_id								OR
									--	tmp.itst_cant							<> tbl.itst_cant							OR
									--	tmp.itst_LastAvailableInRelalculation	<> tbl.itst_LastAvailableInRelalculation	OR
									--	tmp.cat_id								<> tbl.cat_id								OR
									--	tmp.subcat_id							<> tbl.subcat_id							OR
									--	tmp.subcataux_id						<> tbl.subcataux_id							OR
									--	tmp.ic_id								<> tbl.ic_id								OR
									--	tmp.currency_symbol						<> tbl.currency_symbol						OR
									--	tmp.semaphoreValue						<> tbl.semaphoreValue						OR
									--	tmp.prli_priceNOTaxes					<> tbl.prli_priceNOTaxes					OR
									--	tmp.strikeThroughPrice					<> tbl.strikeThroughPrice					OR
									--	tmp.strikeThroughPriceNOTaxes			<> tbl.strikeThroughPriceNOTaxes
									--)
					--COMMIT TRANSACTION
					--CHECKPOINT
		SELECT '07. END Deleting ' + CONVERT(CHAR(20),@@rowcount) + ' Items:',GETDATE()


