		SELECT '07.05 BEGIN Updating Modified Items:',GETDATE()
				--BEGIN TRANSACTION
					UPDATE		tbWebSiteII_ItemsData
						SET
							comp_id								= tmp.comp_id,
							prli_id								= tmp.prli_id,
							item_id								= tmp.item_id,
							prli_price							= tmp.prli_price,
							curr_id								= tmp.curr_id,
							ws_id								= tmp.ws_id,
							itst_cant							= tmp.itst_cant,
							itst_availableQTY					= tmp.itst_availableQTY,
							itst_LastAvailableInRelalculation	= tmp.itst_LastAvailableInRelalculation,
							cat_id								= tmp.cat_id,
							subcat_id							= tmp.subcat_id,
							subcataux_id						= tmp.subcataux_id,
							ic_id								= tmp.ic_id,
							currency_symbol						= tmp.currency_symbol,
							semaphoreValue						= tmp.semaphoreValue,
							prli_priceNOTaxes					= tmp.prli_priceNOTaxes,
							catg_id								= tc.catg_id,
							catg_desc							= ISNULL(tcg.catg_desc,'')					,
							cat_WebSite_desc =
												CASE
													WHEN ISNULL(tc.cat_WebSite_desc,'')  <> '' THEN tc.cat_WebSite_desc
													ELSE tc.cat_desc
												END,
							subcat_WebSite_desc =
												CASE
													WHEN ISNULL(tsc.subcat_WebSite_desc,'') <> '' THEN tsc.subcat_WebSite_desc
													ELSE tsc.subcat_desc
												END,
							subcataux_desc						= ISNULL(tsca.subcataux_desc,'')				,
							strikeThroughPrice					= tmp.strikeThroughPrice,
							strikeThroughPriceNOTaxes			= tmp.strikeThroughPriceNOTaxes,
							item__WebSite_desc =
												CASE
													WHEN dbo.fnStrAllTrim(ISNULL(ti.item_WebSite_desc,'')) <> '' THEN	ti.item_WebSite_desc
													ELSE																ti.item_desc
												END,
							item__WebSite_desc4SEO				= REPLACE(rrr.itemDescription,':',''),
							item__code							= ti.item_code,
							item__vendorCode					= ti.item_vendorCode,
							item__descHTML						= rrr.itemHTML,
							item__annotation1					= CONVERT( VARCHAR(1700), ti.item_annotation1),
							item__annotation2					= CONVERT( VARCHAR(1700), ti.item_annotation2),
							item__made							= ti.item_made,
							item__newness						= ti.item_newness,
							item__liquidation					= ti.item_liquidation,
							_brand_id							= tb.brand_id,
							_brand_desc							= tb.brand_desc,
							StockIndex =
											CASE
												WHEN tmp.semaphoreValue = 4 THEN 1
												WHEN tmp.semaphoreValue = 3 THEN 3
												WHEN tmp.semaphoreValue = 2 THEN 3
												ELSE							 2   -- Esta mierda solo la usa Maxi
											END		,
							item__web_title						= ti.item_web_title,
							item__web_metaKeywords				= ti.item_web_metaKeywords,
							item__web_metaDescription			= ti.item_web_metaDescription
						FROM	tbWebSiteII_ItemsData				tbl WITH (NOLOCK)
						INNER JOIN  #tmpFile						tmp	WITH (NOLOCK)
							ON	tmp.comp_id = tbl.comp_id	AND
								tmp.ws_id	= tbl.ws_id		AND
								tmp.prli_id = tbl.prli_id	AND
								tmp.item_id	= tbl.item_id
						INNER JOIN tbCategory			tc		WITH (NOLOCK)
							ON	tc.comp_id	= tmp.comp_id AND
								tc.cat_id	= tmp.cat_id
						INNER JOIN tbSubCategory		tsc		WITH (NOLOCK)
							ON	tsc.comp_id		= tmp.comp_id AND
								tsc.cat_id		= tmp.cat_id AND
								tsc.subcat_id	= tmp.subcat_id
						INNER JOIN tbItem				ti		WITH (NOLOCK)
							ON	ti.comp_id		= tmp.comp_id AND
								ti.item_id		= tmp.item_id
						INNER JOIN @tmpItemDescription rrr
							ON rrr.item_id = ti.item_id
						LEFT JOIN tbBrand			AS tb		WITH (NOLOCK)
							ON	tb.comp_id		= ti.comp_id AND
								tb.brand_id		= ti.brand_id
						LEFT JOIN tbSubCategoryAux		tsca	WITH (NOLOCK)
							ON	tsca.comp_id		= tmp.comp_id AND
								tsca.subcataux_id	= tmp.subcataux_id
						LEFT JOIN tbCategoryGroup		tcg		WITH (NOLOCK)
							ON	tcg.comp_id = tc.comp_id AND
								tcg.catg_id = tc.catg_id
						WHERE
							(
								tmp.prli_price							<> tbl.prli_price							OR
								tmp.curr_id								<> tbl.curr_id								OR
								tmp.itst_cant							<> tbl.itst_cant							OR
								tmp.itst_availableQTY					<> tbl.itst_availableQTY					OR
								tmp.itst_LastAvailableInRelalculation	<> tbl.itst_LastAvailableInRelalculation	OR
								tmp.cat_id								<> tbl.cat_id								OR
								tmp.subcat_id							<> tbl.subcat_id							OR
								tmp.subcataux_id						<> tbl.subcataux_id							OR
								tmp.ic_id								<> tbl.ic_id								OR
								tmp.currency_symbol						<> tbl.currency_symbol						OR
								tmp.semaphoreValue						<> tbl.semaphoreValue						OR
								tmp.prli_priceNOTaxes					<> tbl.prli_priceNOTaxes					OR
								tmp.strikeThroughPrice					<> tbl.strikeThroughPrice					OR
								tmp.strikeThroughPriceNOTaxes			<> tbl.strikeThroughPriceNOTaxes
							)
					--COMMIT TRANSACTION
					--CHECKPOINT
		SELECT '07.05 END Updating Modified ' + CONVERT(CHAR(20),@@rowcount) + ' Items:',GETDATE()

		SELECT '08. BEGIN Inserting Modified Items:',GETDATE()


					-- Inserta lo actualizado
				--BEGIN TRANSACTION
					INSERT INTO tbWebSiteII_ItemsData
					(
						comp_id,
						prli_id,
						item_id,
						prli_price,
						curr_id,
						ws_id,
						itst_cant,
						itst_availableQTY,
						itst_LastAvailableInRelalculation,
						cat_id,
						subcat_id,
						subcataux_id,
						ic_id,
						currency_symbol,
						semaphoreValue,
						prli_priceNOTaxes,
						catg_id,
						catg_desc,
						cat_WebSite_desc,
						subcat_WebSite_desc,
						subcataux_desc,
						strikeThroughPrice,
						strikeThroughPriceNOTaxes,
						item__WebSite_desc,
						item__WebSite_desc4SEO,
						item__code			,
						item__vendorCode		,
						item__descHTML,
						item__annotation1,
						item__annotation2,
						item__made,
						item__newness,
						item__liquidation,
						_brand_id,
						_brand_desc	,
						StockIndex,
						item__web_title,
						item__web_metaKeywords,
						item__web_metaDescription
					)
					SELECT --DISTINCT
							tmp.comp_id,
							tmp.prli_id,
							tmp.item_id,
							tmp.prli_price,
							tmp.curr_id,
							tmp.ws_id,
							tmp.itst_cant,
							tmp.itst_availableQTY,
							tmp.itst_LastAvailableInRelalculation,
							tmp.cat_id,
							tmp.subcat_id,
							tmp.subcataux_id,
							tmp.ic_id,
							tmp.currency_symbol,
							tmp.semaphoreValue,
							tmp.prli_priceNOTaxes,
							tc.catg_id,
							ISNULL(tcg.catg_desc,'')					[catg_desc],
							CASE
								WHEN ISNULL(tc.cat_WebSite_desc,'')  <> '' THEN tc.cat_WebSite_desc
								ELSE tc.cat_desc
							END,
							CASE
								WHEN ISNULL(tsc.subcat_WebSite_desc,'') <> '' THEN tsc.subcat_WebSite_desc
								ELSE tsc.subcat_desc
							END,
							ISNULL(tsca.subcataux_desc,'')				[subcataux_desc],
							tmp.strikeThroughPrice,
							tmp.strikeThroughPriceNOTaxes,
							CASE
								WHEN dbo.fnStrAllTrim(ISNULL(ti.item_WebSite_desc,'')) <> '' THEN	ti.item_WebSite_desc
