							END,
							CONVERT( CHAR(250),rrr.itemDescription),
							ti.item_code,
							ti.item_vendorCode,
							CONVERT( VARCHAR(8000),rrr.itemHTML),
							CONVERT( VARCHAR(1700), ti.item_annotation1),
							CONVERT( VARCHAR(1700), ti.item_annotation2),
							ti.item_made,
							ti.item_newness,
							ti.item_liquidation,
							tb.brand_id,
							tb.brand_desc,
							CASE
								WHEN tmp.semaphoreValue = 4 THEN 1
								WHEN tmp.semaphoreValue = 3 THEN 3
								WHEN tmp.semaphoreValue = 2 THEN 3
								ELSE							 2   -- Esta mierda solo la usa Maxi
							END,
							ti.item_web_title,
							ti.item_web_metaKeywords,
							ti.item_web_metaDescription
						FROM #tmpFile						tmp	WITH (NOLOCK)
						LEFT JOIN tbWebSiteII_ItemsData	tbl	WITH (NOLOCK)
							ON	tmp.comp_id = tbl.comp_id	AND
								tmp.ws_id	= tbl.ws_id		AND
								tmp.prli_id = tbl.prli_id	AND
								tmp.item_id	= tbl.item_id
						INNER JOIN tbCategory			tc		WITH (NOLOCK)
							ON	tc.comp_id	= tmp.comp_id AND
								tc.cat_id	= tmp.cat_id
						INNER JOIN tbSubCategory		tsc		WITH (NOLOCK)
							ON	tsc.comp_id		= tmp.comp_id AND
								tsc.cat_id		= tmp.cat_id AND
								tsc.subcat_id	= tmp.subcat_id
						INNER JOIN tbItem				ti		WITH (NOLOCK)
							ON	ti.comp_id		= tmp.comp_id AND
								ti.item_id		= tmp.item_id
						INNER JOIN @tmpItemDescription rrr
							ON rrr.item_id = ti.item_id
						LEFT JOIN tbBrand			AS tb		WITH (NOLOCK)
							ON	tb.comp_id		= ti.comp_id AND
								tb.brand_id		= ti.brand_id
						LEFT JOIN tbSubCategoryAux		tsca	WITH (NOLOCK)
							ON	tsca.comp_id		= tmp.comp_id AND
								tsca.subcataux_id	= tmp.subcataux_id
						LEFT JOIN tbCategoryGroup		tcg		WITH (NOLOCK)
							ON	tcg.comp_id = tc.comp_id AND
								tcg.catg_id = tc.catg_id
						WHERE tbl.comp_id IS NULL

					--COMMIT TRANSACTION
					--CHECKPOINT
			SELECT '08 END Inserting ' + CONVERT(CHAR(20),@@rowcount) + ' Items:',GETDATE()





			DROP TABLE #tmpFile


SELECT '09. tbCategoryData:',GETDATE()

		BEGIN TRANSACTION
			DELETE FROM tbWebSiteII_CategoryData	--WITH (ROWLOCK)
			INSERT INTO tbWebSiteII_CategoryData (	comp_id,
													cat_id,
													prli_id,
													itemsInCategory,
													catg_id,
													catg_desc,
													cat_WebSite_desc,
													ws_id
												)
				SELECT		vw.comp_id,
							vw.cat_id,
							vw.prli_id,
							vw.itemsInCategory,
							vw.catg_id,
							vw.catg_desc,
							cat_WebSite_desc =
							CASE
								WHEN ISNULL(tc.cat_WebSite_desc,'')  <> '' THEN tc.cat_WebSite_desc
								ELSE tc.cat_desc
							END,
							--vw.cat_WebSite_desc,
							vw.ws_id
					FROM vwWebSiteII_CategoryData vw	WITH (NOLOCK)
					INNER JOIN tbCategory AS tc			WITH (NOLOCK)
						ON	tc.comp_id	= vw.comp_id AND
							tc.cat_id	= vw.cat_id

				COMMIT TRANSACTION
				--CHECKPOINT



SELECT '10. tbSubCategoryData:',GETDATE()

		BEGIN TRANSACTION
			DELETE FROM tbWebSiteII_SubCategoryData	--WITH (ROWLOCK)
			INSERT INTO tbWebSiteII_subCategoryData (	comp_id,
														cat_id,
														subcat_id,
														prli_id,
														itemsInCategory,
														subcat_WebSite_desc,
														ws_id
													)
				SELECT  vw.comp_id,
						vw.cat_id,
						vw.subcat_id,
						vw.prli_id,
						vw.itemsInCategory,
						CASE		-- MOS 10-2021 x Casablanco, para que si ponen N o Ñ no le duplique la categoria.
							WHEN ISNULL(tsc.subcat_WebSite_desc,'') <> '' THEN tsc.subcat_WebSite_desc
							ELSE tsc.subcat_desc
						END,
						--vw.subcat_WebSite_desc,
						vw.ws_id
					FROM vwWebSiteII_subCategoryData vw		WITH (NOLOCK)
					INNER JOIN tbSubCategory	AS   tsc	WITH (NOLOCK)
						ON	tsc.comp_id		= vw.comp_id	AND
							tsc.cat_id		= vw.cat_id		AND
							tsc.subcat_id	= vw.subcat_id

			COMMIT TRANSACTION
			--CHECKPOINT


		-- ------------------------------------------------------------------------
		-- Si se define un tiempo maximo de los articulos en el carrito, los borra.
		-- ------------------------------------------------------------------------
		DELETE  tbTempItemStock
			FROM tbTempItemStock AS ttis				WITH (NOLOCK)
			INNER JOIN tbWebSiteII_Names AS twsin		WITH (NOLOCK)
				ON	twsin.comp_id		= ttis.comp_id			AND
					twsin.ws_internalID = ttis.ws_internalID	AND
					twsin.ws_maxItemTimeInCart > 0				AND
					DATEADD(minute,twsin.ws_maxItemTimeInCart,ttis.tis_CD) < GETDATE()
		-- ------------------------------------------------------------------------


	END TRY
	BEGIN CATCH
		--ROLLBACK TRANSACTION
		SELECT 'Error',  ERROR_NUMBER() AS ErrorNumber
						,ERROR_SEVERITY() AS ErrorSeverity
						,ERROR_STATE() AS ErrorState
						,ERROR_PROCEDURE() AS ErrorProcedure
						,ERROR_LINE() AS ErrorLine
						,ERROR_MESSAGE() AS ErrorMessage;
	END CATCH



END



