-- ----------------------------------------------------------------------------------------------
-- Pone los descuentos por item segun la politica de descuentos que figura en la tabla de items.-
-- ----------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[sptmpTax_calculate_setDiscountByItem]
(
	@comp_Id				 as	int,
	@bra_Id					 as	int,
	@cust_Id				 as	int,
	@tis_guid				 as	UNIQUEIDENTIFIER)

AS

BEGIN

	SET NOCOUNT ON

	UPDATE tbTempItemStock	WITH (ROWLOCK)
	SET
		tis_itemDiscount =			CASE
										WHEN tpl.prli_isAvailable4DiscountByQTY = 'True' AND ttis.tis_qty >= IsNull(ti.item_comboDisc_Cant6,0) AND IsNull(ti.item_comboDisc_Cant6,0) <> 0 THEN ISNULL(ti.item_comboDisc_Disc6,0)
										WHEN tpl.prli_isAvailable4DiscountByQTY = 'True' AND ttis.tis_qty >= IsNull(ti.item_comboDisc_Cant5,0) AND IsNull(ti.item_comboDisc_Cant5,0) <> 0 THEN ISNULL(ti.item_comboDisc_Disc5,0)
										WHEN tpl.prli_isAvailable4DiscountByQTY = 'True' AND ttis.tis_qty >= IsNull(ti.item_comboDisc_Cant4,0) AND IsNull(ti.item_comboDisc_Cant4,0) <> 0 THEN ISNULL(ti.item_comboDisc_Disc4,0)
										WHEN tpl.prli_isAvailable4DiscountByQTY = 'True' AND ttis.tis_qty >= IsNull(ti.item_comboDisc_Cant3,0) AND IsNull(ti.item_comboDisc_Cant3,0) <> 0 THEN ISNULL(ti.item_comboDisc_Disc3,0)
										WHEN tpl.prli_isAvailable4DiscountByQTY = 'True' AND ttis.tis_qty >= IsNull(ti.item_comboDisc_Cant2,0) AND IsNull(ti.item_comboDisc_Cant2,0) <> 0 THEN ISNULL(ti.item_comboDisc_Disc2,0)
										WHEN tpl.prli_isAvailable4DiscountByQTY = 'True' AND ttis.tis_qty >= IsNull(ti.item_comboDisc_Cant1,0) AND IsNull(ti.item_comboDisc_Cant1,0) <> 0 THEN ISNULL(ti.item_comboDisc_Disc1,0)
										WHEN tpl.prli_isAvailable4DiscountByQTY = 'False'																								  THEN tis_itemDiscount
										ELSE 0
									END
		FROM tbTempItemStock ttis
		INNER JOIN tbitem ti		WITH (NOLOCK)
			ON		ti.comp_id = ttis.comp_id
				AND ti.item_id = ttis.item_id
		INNER JOIN tbPriceList tpl	WITH (NOLOCK)
			ON	tpl.comp_id = ttis.comp_id AND
				tpl.prli_id = ttis.prli_id
	WHERE	--ttis.comp_id	= @comp_Id
		    ttis.tis_guid	= @tis_guid						AND
		    ttis.it_transaction IS NULL						AND  -- MOS 11-09-2019: Para que no acumule descuentos al hacer fc o nc de otra fc.
		   (	ti.item_comboDisc_Disc1 <> 0 OR
				ti.item_comboDisc_Disc2 <> 0 OR
				ti.item_comboDisc_Disc3 <> 0 OR
				ti.item_comboDisc_Disc4 <> 0 OR
				ti.item_comboDisc_Disc5 <> 0 OR
				ti.item_comboDisc_Disc6 <> 0
		   )


END
GO






