CREATE PROCEDURE [dbo].[sptmpTax_getData]
(
	@tis_id			int
)
as


/*
declare @tis_id	int
select @tis_id=231
*/

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	select	tt.[curr_id],
			tt.[tax_id],
			tt.[tm_amount],
			tt.[percentage],
			tt.[tis_id],
			ttn.[tax_forSale],
			ttn.[tax_class]


	FROM [dbo].[tbtmpTax] AS TT					WITH (NOLOCK)
		INNER JOIN [dbo].[tbTaxName] AS TTN		WITH (NOLOCK)
		ON TT.[tax_id] = TTN.[tax_id]

	WHERE TT.[tis_id] = @tis_id

END















GO








CREATE procedure [dbo].[spTranslator_getData]
(
	@lang_id_source		INT,
	@lang_id_destiny	INT,
	@option_text        INT,
	@text				NVARCHAR(MAX) ,
	@Option				INT,
	@cant				INT,
	@chk_pending		INT,
	@Confirm			INT
)
AS



BEGIN




	SET NOCOUNT ON



	------------------------------------------------------------------------------------------------------------
	/*
	DECLARE
		@lang_id_source		INT,
		@lang_id_destiny	INT,
		@option_text        INT,
		@text				VARCHAR(50) ,
		@Option				INT,
		@cant				INT,
		@chk_pending		INT,
		@Confirm			INT



	SELECT
		@lang_id_source		=	2,
		@lang_id_destiny	=	-1,
		@option_text        =	-1,
		@text				=	'',
		@Option				=	2,
		@cant				=	500,
		@chk_pending		=	0,
		@Confirm            =	0
	*/
	------------------------------------------------------------------------------------------------------------



	DECLARE @splitChar CHAR(1)
	SET @splitChar = '.'


	IF @Option = 1 --optionvalues
	BEGIN

		SELECT	Top(@cant)
				convert(VARCHAR,tl.lang_id /*@lang_id_destiny*/)	+ @splitChar +
				convert(varchar,tov.optval_id)		+ @splitChar +
				convert(varchar,tov.optval_class)	+ @splitChar +
				convert(varchar,isnull(tov.optval_order,0)) + @splitChar +
				tl.lang_google_id			[ID],
				tov.optval_desc										[DESC1],
				isnull(tov2.optval_desc,'')							[DESC2],
				isnull(tov2.optval_isTranslated,'False')            [CONF]
				--tl.lang_id

			FROM	tbsysOptionsValues							tov

			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1


			left JOIN tbsysOptionsValues				tov2
				ON	tov2.optval_id		= tov.optval_id
				AND tov2.optval_class	= tov.optval_class
				--AND tov2.optval_order	= tov.optval_order
				AND tov2.lang_id		= tl.lang_id -- @lang_id_destiny

			WHERE	tl.lang_enabled = 'True' AND
					tov.lang_id = @lang_id_source
			AND		(
					(@option_text	= -1 )													OR
					(@option_text	= 0 AND tov2.optval_desc like			@text + '%')	OR
					(@option_text	= 1 AND tov2.optval_desc like '%' +		@text + '%')	OR
					(@option_text	= 2 AND tov2.optval_desc =				@text )			OR
					(@option_text	= 3 AND tov2.optval_desc <>				@text)			OR
					(@option_text	= 4 AND tov2.optval_desc not like '%' + @text + '%')
					)
			AND		(
					(@chk_pending	= -1 )															OR
					(@chk_pending	= 0 AND (dbo.fnStrAllTrim( tov2.optval_desc)  = '' OR tov2.optval_desc is  null))	OR
					(@chk_pending	= 1 AND (tov2.optval_desc <> ''))
					)
			AND		(
    				(@Confirm		= -1 ) OR
					(isnull(tov2.optval_isTranslated,'false') = @Confirm)
					)

	END





	IF @Option = 2 --uniquetexts
	BEGIN

		SELECT	Top(@cant)
				convert(VARCHAR,tl.lang_id /*@lang_id_destiny*/) + @splitChar +
				convert(varchar,tut.utexts_id)+ @splitChar +
				tl.lang_google_id									[ID],
				isnull(tut.utexts_desc,'')							[DESC1],
				isnull(tut2.utexts_desc,'')							[DESC2],
				isnull(tut2.utexts_isTranslated,'False')			[CONF]

		FROM	tbsysUniqueTexts tut

			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1

				LEFT JOIN tbsysUniqueTexts tut2
				ON	tut2.utexts_id	= tut.utexts_id
				AND tut2.lang_id	= tl.lang_id --@lang_id_destiny

		WHERE	tl.lang_enabled = 'True' AND
				tut.lang_id = @lang_id_source
		AND 	(
				(@option_text        	 = -1 ) or
				(@option_text        	 = 0 and tut2.utexts_desc like @text + '%') or
				(@option_text        	 = 1 and tut2.utexts_desc like '%' + @text + '%') or
				(@option_text        	 = 2 and tut2.utexts_desc = @text ) or
				(@option_text        	 = 3 and tut2.utexts_desc <> @text) or
				(@option_text        	 = 4 and tut2.utexts_desc not like '%' + @text + '%')
				)
		AND		(
				(@chk_pending=-1)	OR
				(@chk_pending= 0	and (tut2.utexts_desc = ''  or tut2.utexts_desc is null)) or
				(@chk_pending= 1	and (tut2.utexts_desc <> ''))
				)
		AND		(@Confirm = -1 OR isnull(tut2.utexts_isTranslated,'false') = convert(bit,@Confirm))

	END




	IF @Option = 3 --syswordsnew
	BEGIN

		SELECT  Top(@cant)
				convert(VARCHAR,tl.lang_id /*@lang_id_destiny*/) + @splitChar +
				convert(varchar,tw.wordsi_id)			+ @splitChar +
				tl.lang_google_id						[ID],
				isnull(tw.word_desc,'')								[DESC1],
				isnull(tw2.word_desc,'')							[DESC2],
				isnull(tw2.wordn_isTranslated,'False')				[CONF]

		FROM	tbsysWordsNew					tw
			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1


				left JOIN tbsysWordsNew			tw2
				ON	tw2.wordsi_id	= tw.wordsi_id
				AND tw2.lang_id		= tl.lang_id --@lang_id_destiny


		WHERE	tl.lang_enabled = 'True' AND
				tw.lang_id = @lang_id_source
		AND		(
				(@option_text	= -1 ) or
				(@option_text   =  0 and tw2.word_desc like @text + '%') or
				(@option_text   =  1 and tw2.word_desc like '%' + @text + '%') or
				(@option_text   =  2 and tw2.word_desc = @text ) or
				(@option_text   =  3 and tw2.word_desc <> @text) or
				(@option_text   =  4 and tw2.word_desc not like '%' + @text + '%')
				)
		AND		(
				(@chk_pending	= -1) OR
				(@chk_pending	=  0 and (tw2.word_desc  = '' or tw2.word_desc is null)) OR
				(@chk_pending	=  1 and (tw2.word_desc <> ''))
		)
		AND		(@Confirm = -1 OR isnull(tw2.wordn_isTranslated,'false')  = convert(bit,@Confirm))
		-- MOS 11-2013
		AND    NOT (
						dbo.fnStrAllTrim(tw.word_desc)	= ''	AND
						tw2.word_desc IS NOT NULL				AND
						dbo.fnStrAllTrim(tw2.word_desc) = ''
					)

	END








	IF @Option = 4 ---Menu languaje
	BEGIN

		SELECT	Top(@cant)
				convert(varchar,tl.lang_id /*@lang_id_destiny*/) + @splitChar +
     			convert(varchar,tml.menu_id)			+ @splitChar +
				tl.lang_google_id						[ID],
				isnull(tml.mid_desc,'')								[DESC1],
				isnull(tml2.mid_desc,'')							[DESC2],
				isnull(tml2.mlang_isTranslated,'False')				[CONF]

		  FROM	tbsysMenuLanguage					tml

			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1

				left JOIN tbsysMenuLanguage			tml2
				ON tml2.menu_id		= tml.menu_id
				AND tml2.lang_id	= tl.lang_id --@lang_id_destiny

		WHERE	tl.lang_enabled = 'True' AND
				tml.lang_id = @lang_id_source
		AND		(
				(@option_text        	 = -1 ) or
				(@option_text        	 = 0 and tml2.mid_desc like @text + '%') or
				(@option_text        	 = 1 and tml2.mid_desc like '%' + @text + '%') or
				(@option_text        	 = 2 and tml2.mid_desc = @text ) or
				(@option_text        	 = 3 and tml2.mid_desc <> @text) or
				(@option_text        	 = 4 and tml2.mid_desc not like '%' + @text + '%')
				)
		AND		(
				(@chk_pending=-1)	OR
				(@chk_pending= '0'	and (tml2.mid_desc = '' or tml2.mid_desc is null)) OR
				(@chk_pending= '1'	and (tml2.mid_desc <> '')) -- or tw2.words_desc is not null))
				)
		AND		(@Confirm = -1 OR isnull(tml2.mlang_isTranslated,'false')  = convert(bit,@Confirm))

	END






	IF @Option = 5 ---tbsysHelpPages
	BEGIN

		SELECT  Top(@cant)
				convert(varchar,tl.lang_id /*@lang_id_destiny*/)	+ @splitChar +
				convert(varchar,thp.page_id)		+ @splitChar +
				convert(varchar,thp.table_id)			+ @splitChar +
				tl.lang_google_id						[ID],
				isnull(thp.hp_desc,'')								[DESC1],
				isnull(thp2.hp_desc,'')								[DESC2],
				isnull(thp2.hp_isTranslated,'False')				[CONF]

		FROM	tbsysHelpPages							thp

			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1

				left JOIN tbsysHelpPages				thp2
				ON	thp2.page_id	= thp.page_id
				AND thp2.table_id	= thp.table_id
				AND thp2.lang_id	= tl.lang_id --@lang_id_destiny

		WHERE	tl.lang_enabled = 'True' AND
				thp.lang_id = @lang_id_source
		AND		(
				(@option_text	= -1 ) or
				(@option_text	= 0 and cast(thp2.hp_desc AS NVARCHAR(MAX)) like @text + '%') or
				(@option_text	= 1 and cast(thp2.hp_desc AS NVARCHAR(MAX)) like '%' + @text + '%') or
				(@option_text   = 2 and cast(thp2.hp_desc AS NVARCHAR(MAX)) = @text ) or
				(@option_text   = 3 and cast(thp2.hp_desc AS NVARCHAR(MAX)) <> @text) or
				(@option_text   = 4 and cast(thp2.hp_desc AS NVARCHAR(MAX)) not like '%' + @text + '%')
				)
		AND		(
				(@chk_pending	= -1) OR
				(@chk_pending	= '0' and (cast(thp2.hp_desc AS NVARCHAR(MAX))  = '' or cast(thp2.hp_desc AS NVARCHAR(MAX)) is null)) OR
				(@chk_pending	= '1' and (cast(thp2.hp_desc AS NVARCHAR(MAX)) <> ''))
				)
		AND		(@Confirm = -1 OR isnull(thp2.hp_isTranslated,'false')  = convert(bit,@Confirm))

	END



	IF @Option = 6 --sysGBPUpgrades_Detail
	BEGIN

		SELECT	Top(@cant)
				convert(VARCHAR,tl.lang_id /*@lang_id_destiny*/) + @splitChar +
				convert(varchar,tg.upg_id)			+ @splitChar +
				tl.lang_google_id							[ID],
				isnull(tg.upg_detail,'')							[DESC1],
				isnull(tg2.upg_detail,'')							[DESC2],
				isnull(tg2.optval_isTranslated,'False')				[CONF]

		FROM    tbsysGBPUpgrades tg


			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1

				LEFT JOIN tbsysGBPUpgrades tg2
				ON	tg2.upg_id	= tg.upg_id
				AND tg2.lang_id	= tl.lang_id --@lang_id_destiny


		WHERE	tl.lang_enabled = 'True' AND
				tg.lang_id = @lang_id_source
		AND 	(
				(@option_text        	 = -1 ) or
				(@option_text        	 = 0 and tg2.upg_detail like @text + '%') or
				(@option_text        	 = 1 and tg2.upg_detail like '%' + @text + '%') or
				(@option_text        	 = 2 and tg2.upg_detail = @text ) or
				(@option_text        	 = 3 and tg2.upg_detail <> @text) or
				(@option_text        	 = 4 and tg2.upg_detail not like '%' + @text + '%')
				)
		AND		(
				(@chk_pending=-1)	OR
				(@chk_pending= 0	and (tg2.upg_detail = ''  or tg2.upg_detail is null)) or
				(@chk_pending= 1	and (tg2.upg_detail <> ''))
				)
		--AND		(@Confirm = -1 OR isnull(tg2.optval_isTranslated,'false') = convert(bit,@Confirm))

	END


	IF @Option = 7 --sysGBPUpgrades_Desc
	BEGIN

		SELECT	Top(@cant)
				convert(VARCHAR,tl.lang_id /*@lang_id_destiny*/) + @splitChar +
				convert(varchar,tg.upg_id)			+ @splitChar +
				tl.lang_google_id							[ID],
				isnull(tg.upg_desc,'')								[DESC1],
				isnull(tg2.upg_desc,'')								[DESC2],
				isnull(tg2.optval_isTranslated,'False')				[CONF]

		FROM    tbsysGBPUpgrades tg
			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1

				LEFT JOIN tbsysGBPUpgrades tg2
				ON	tg2.upg_id	= tg.upg_id
				AND tg2.lang_id	= tl.lang_id --@lang_id_destiny


		WHERE	tl.lang_enabled = 'True' AND
				tg.lang_id = @lang_id_source
		AND 	(
				(@option_text        	 = -1 ) or
				(@option_text        	 = 0 and tg2.upg_desc like @text + '%') or
				(@option_text        	 = 1 and tg2.upg_desc like '%' + @text + '%') or
				(@option_text        	 = 2 and tg2.upg_desc = @text ) or
				(@option_text        	 = 3 and tg2.upg_desc <> @text) or
				(@option_text        	 = 4 and tg2.upg_desc not like '%' + @text + '%')
				)
		AND		(
				(@chk_pending=-1)	OR
				(@chk_pending= 0	and (tg2.upg_desc = ''  or tg2.upg_desc is null)) or
				(@chk_pending= 1	and (tg2.upg_desc <> ''))
				)
		AND		(@Confirm = -1 OR isnull(tg.optval_isTranslated,'false') = convert(bit,@Confirm))

	END


	IF @Option = 8 ---Menu languaje ( tooltips )
		BEGIN

			SELECT	Top(@cant)
					convert(varchar,tl.lang_id /*@lang_id_destiny*/) + @splitChar +
     				convert(varchar,tml.menu_id)	+ @splitChar +
				tl.lang_google_id								[ID],
					isnull(tml.mid_tooltip,'')							[DESC1],
					isnull(tml2.mid_tooltip,'')							[DESC2],
					isnull(tml2.mlang_isTranslated,'False')				[CONF]

			  FROM	tbsysMenuLanguage					tml

			LEFT JOIN tbsysLanguage tl
			ON	CASE
					WHEN @lang_id_destiny = -1  AND tl.lang_id <> @lang_id_source   THEN 1
					WHEN @lang_id_destiny <> -1 AND tl.lang_id =  @lang_id_destiny AND tl.lang_id <> @lang_id_source THEN 1
					ELSE 0
				END = 1

					left JOIN tbsysMenuLanguage			tml2
					ON tml2.menu_id		= tml.menu_id
					AND tml2.lang_id	= tl.lang_id --@lang_id_destiny

			WHERE   tl.lang_enabled = 'True' AND
					tml.lang_id = @lang_id_source
			AND	    tml.mid_tooltip <> ''
			AND		(
					(@option_text        	 = -1 ) or
					(@option_text        	 = 0 and tml2.mid_tooltip like @text + '%') or
					(@option_text        	 = 1 and tml2.mid_tooltip like '%' + @text + '%') or
					(@option_text        	 = 2 and tml2.mid_tooltip = @text ) or
					(@option_text        	 = 3 and tml2.mid_tooltip <> @text) or
					(@option_text        	 = 4 and tml2.mid_tooltip not like '%' + @text + '%')
					)
			AND		(
					(@chk_pending=-1)	OR
					(@chk_pending= '0'	and (tml2.mid_tooltip = '' or tml2.mid_tooltip is null)) OR
					(@chk_pending= '1'	and (tml2.mid_tooltip <> '')) -- or tw2.words_desc is not null))
					)
			AND		(@Confirm = -1 OR isnull(tml2.mlang_isTranslated,'false')  = convert(bit,@Confirm))

	END

END
GO








CREATE procedure [dbo].[spTranslator_Update]
(
	@lang_id		INT,
	@Option			INT,
	@DESC2			NVARCHAR(4000),
	@ID				VARCHAR(100),
	@value			BIT,
	@overwrite      BIT
)
AS




SET NOCOUNT ON


------------------------------------------------------------------------------------
-- Testing
------------------------------------------------------------------------------------
/*
DECLARE @lang_id			INT,
		@Option             INT,
		@DESC2				varchar(200),
		@ID					VARCHAR(100),
		@value				BIT,
		@overwrite          BIT


SELECT	@lang_id			=1,
		@Option             =1,
		@DESC2				='Registration Items.',
		@ID					='1.4.132.0',
		@value				='false',
		@overwrite			='false'
*/
------------------------------------------------------------------------------------



DECLARE @id1 INT, @id2 INT, @id3 INT

DECLARE @splitChar CHAR(1)
SET		@splitChar = '.'



/****************************************************************************************/
--tbSysOptionValues

IF @Option = 1
BEGIN
	SET @id1 = dbo.fnSplitPosition(@ID,@splitChar,2)
	SET @id2 = dbo.fnSplitPosition(@ID,@splitChar,3)
	SET @id3 = dbo.fnSplitPosition(@ID,@splitChar,4)


	IF NOT EXISTS(
				   SELECT 1
				   FROM dbo.tbsysOptionsValues tov
				   WHERE tov.optval_id	   = @id1
				   AND   tov.optval_class  = @id2
				   --AND   tov.optval_order  = @id3
				   AND   tov.lang_id	   = dbo.fnSplitPosition(@ID,@splitChar,1)
				  )



		INSERT INTO dbo.tbsysOptionsValues
		(
			lang_id,
			optval_id,
			optval_class,
			optval_desc,
			optval_order,
			optval_isTranslated,
			optval_translateDate
		)
		VALUES
		(
			dbo.fnSplitPosition(@ID,@splitChar,1),
			@id1,
			@id2,
			@dESC2,
			@id3,
			@value,
			GETDATE()
		)

	ELSE

		BEGIN

--		SELECT 'Update',@DESC2,@id
--		SELECT * FROM tbsysOptionsValues tov
--				where optval_id	   = @id1
--				AND   optval_class = @id2
--				--AND   optval_order = @id3
--				AND   lang_id	   = dbo.fnSplitPosition(@ID,@splitChar,1)
--				AND   (isnull(optval_isTranslated,'false') = 'false' OR @overwrite = 'true')


				UPDATE dbo.tbsysOptionsValues

				SET		optval_desc				= @DESC2,
						optval_isTranslated		= @value,
						optval_translateDate	= GETDATE(),
						optval_order			= @id3

				where optval_id	   = @id1
				AND   optval_class = @id2
				--AND   optval_order = @id3
				AND   lang_id	   = dbo.fnSplitPosition(@ID,@splitChar,1)
				AND   (isnull(optval_isTranslated,'false') = 'false' OR @overwrite = 'true')

		END
END

--tbSysOptionValues
/****************************************************************************************/








/****************************************************************************************/
IF @Option = 2 --tbSysUniqueTexts
BEGIN
	SET @id1 = dbo.fnSplitPosition(@ID,@splitChar,2)
	SELECT @id1
	IF NOT EXISTS(
				  SELECT	1
				  FROM		dbo.tbsysUniqueTexts tut
				  WHERE		tut.utexts_id	= @id1
				  AND		tut.lang_id		= dbo.fnSplitPosition(@ID,@splitChar,1)
				 )
	BEGIN
			--SELECT 'a'
			INSERT INTO dbo.tbsysUniqueTexts
			(
				lang_id,
				utexts_id,
				utexts_desc,
				utexts_isTranslated,
				utexts_translateDate
			)
			VALUES
			(
				dbo.fnSplitPosition(@ID,@splitChar,1),
				dbo.fnSplitPosition(@ID,@splitChar,2),
				@dESC2,
				@value,
				GETDATE()
			)

	END
	ELSE
	BEGIN
			--SELECT 'b'
			UPDATE dbo.tbsysUniqueTexts

			SET  utexts_desc			=  @DESC2,
				 utexts_isTranslated	= @value,
				 utexts_translateDate	= GETDATE()

			WHERE utexts_id  = @id1

			AND lang_id    = dbo.fnSplitPosition(@ID,@splitChar,1)
			AND (isnull(utexts_isTranslated,'false') = 'false' OR @overwrite = 'true')

	END
END





/****************************************************************************************/
IF @Option = 3	--tbSysWordsNew
BEGIN

	SET @id1 = dbo.fnSplitPosition(@ID,@splitChar,2)
	SELECT @id1
	IF NOT EXISTS(SELECT	1
				  FROM		dbo.tbsysWordsNew tw
				  WHERE		tw.wordsi_id	= @id1
				  AND		tw.lang_id		= dbo.fnSplitPosition(@ID,@splitChar,1))
	BEGIN
			--SELECT 'a'
			BEGIN TRANSACTION T1
			BEGIN TRY

				INSERT INTO dbo.tbsysWordsNew
				(
					lang_id,
					wordsi_id,
					word_desc,
					wordn_isTranslated,
					wordn_translateDate
				)
				VALUES
				(
					dbo.fnSplitPosition(@ID,@splitChar,1),
					dbo.fnSplitPosition(@ID,@splitChar,2),
					@dESC2,
					@value,
					GETDATE()
				)

				COMMIT TRANSACTION T1
			END TRY
			BEGIN CATCH
				ROLLBACK TRANSACTION T1
			END CATCH
	END
	ELSE
	BEGIN
			--SELECT 'b', dbo.fnSplitPosition(@ID,@splitChar,1)
			UPDATE	dbo.tbsysWordsNew
			SET 	word_desc				= @DESC2,
					wordn_isTranslated		= @value,
					wordn_translateDate		= GETDATE()
			WHERE	wordsi_id				= @id1
			AND		lang_id					= dbo.fnSplitPosition(@ID,@splitChar,1)
			AND     (isnull(wordn_isTranslated,'false') = 'false' OR @overwrite = 'true')

	END
END






/****************************************************************************************/
IF @Option = 4   --tbSysMenuLanguage
	BEGIN
		SET @id1 = dbo.fnSplitPosition(@ID,@splitChar,2)
		DECLARE @desc50		NVARCHAR(50)
		SET @desc50 = @DESC2

		IF NOT EXISTS(
					  SELECT	1
					  FROM		dbo.tbsysMenuLanguage tml
					  WHERE		tml.menu_id = @id1
					  AND		tml.lang_id	= dbo.fnSplitPosition(@ID,@splitChar,1)
					 )
		BEGIN

					INSERT INTO dbo.tbsysMenuLanguage
					(
						lang_id,
						menu_id,
						mid_desc,
						mlang_isTranslated,
						mlang_translateDate

					)
					VALUES
					(
						dbo.fnSplitPosition(@ID,@splitChar,1),
						dbo.fnSplitPosition(@ID,@splitChar,2),
						@desc50,
						@value,
						GETDATE()
					)

		END
		ELSE

				UPDATE dbo.tbsysMenuLanguage

				SET mid_desc			= @desc50,
                    mlang_isTranslated	= @value,
                    mlang_translateDate = GETDATE()

				WHERE	menu_id		= @id1
				AND		lang_id		= dbo.fnSplitPosition(@ID,@splitChar,1)
				AND		(isnull(mlang_isTranslated,'false') = 'false' OR @overwrite = 'true')
	END






/****************************************************************************************/
IF @Option = 5		--tbsysHelpPages
BEGIN

	SET @id1 = dbo.fnSplitPosition(@ID,@splitChar,2)
	SET @id2 = dbo.fnSplitPosition(@ID,@splitChar,3)

	IF NOT EXISTS(
				  SELECT	1
				  FROM		dbo.tbsysHelpPages thp
				  WHERE		thp.page_id		= @id1
				  AND		thp.table_id	= @id2
				  AND		thp.lang_id		= dbo.fnSplitPosition(@ID,@splitChar,1)
				 )
	BEGIN
		INSERT INTO dbo.tbsysHelpPages
		(
			lang_id,
			page_id,
			table_id,
			hp_desc,
			hp_isTranslated,
			hp_translateDate
		)
		VALUES
		(
			dbo.fnSplitPosition(@ID,@splitChar,1),
			dbo.fnSplitPosition(@ID,@splitChar,2),
			dbo.fnSplitPosition(@ID,@splitChar,3),
			@dESC2,
			@value,
			GETDATE()
		)
	END
ELSE
	UPDATE	dbo.tbsysHelpPages
	SET		hp_desc		= @DESC2,
			hp_isTranslated = @value,
			hp_translateDate = GETDATE()
	WHERE	page_id		= @id1
	AND		table_id	= @id2
	AND		lang_id		= dbo.fnSplitPosition(@ID,@splitChar,1)
	AND     (isnull(hp_isTranslated,'false') = 'false' OR @overwrite = 'true')

END
--tbsysHelpPages





