CREATE procedure [dbo].[spTraslator_getData]
(
	@lang_id_source		INT,
	@lang_id_destiny	INT,
	@option_text        INT,
	@text				VARCHAR(50) ,
	@Option				INT,
	@cant				INT,
	@chk_pending		INT,
	@Confirm			INT
)
as
SET NOCOUNT ON

------------------------------------------------------------------------
/*

DECLARE
	@lang_id_source		INT,
	@lang_id_destiny	INT,
	@option_text        INT,
	@text				VARCHAR(50) ,
	@Option				INT,
	@cant				INT,
	@chk_pending		INT,
	@Confirm			INT

SELECT
	@lang_id_source		=	2,
	@lang_id_destiny	=	1,
	@option_text        =	-1,
	@text				=	'',
	@Option				=	6,
	@cant				=	50,
	@chk_pending		=	-1,
	@Confirm            =	-1

*/
------------------------------------------------------------------------


DECLARE @splitChar CHAR(1)
SET @splitChar = '.'


IF @Option = 1 --optionvalues
BEGIN

	SELECT	Top(@cant)
			convert(VARCHAR,@lang_id_destiny)	+ @splitChar +
			convert(varchar,tov.optval_id)		+ @splitChar +
			convert(varchar,tov.optval_class)	+ @splitChar +
			convert(varchar,tov.optval_order)					[ID],
			tov.optval_desc										[DESC1],
			isnull(tov2.optval_desc,'')							[DESC2],
			isnull(tov.optval_isTranslated,'False')             [CONF]

	FROM	tbsysOptionsValues							tov

			left JOIN tbsysOptionsValues				tov2
			ON	tov2.optval_id		= tov.optval_id
			AND tov2.optval_class	= tov.optval_class
			AND tov2.optval_order	= tov.optval_order
			AND tov2.lang_id		= @lang_id_destiny

	WHERE	tov.lang_id = @lang_id_source
	AND		(
			(@option_text	= -1 ) OR
			(@option_text	= 0 and tov2.optval_desc like @text + '%') or
			(@option_text	= 1 and tov2.optval_desc like '%' + @text + '%') or
			(@option_text	= 2 and tov2.optval_desc = @text ) or
			(@option_text	= 3 and tov2.optval_desc <> @text) or
			(@option_text	= 4 and tov2.optval_desc not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending	= -1) OR
			(@chk_pending	= 0 and (tov2.optval_desc  = ''  or tov2.optval_desc is  null))		OR
			(@chk_pending	= 1 and (tov2.optval_desc <> ''))
			)
    AND		(@Confirm = -1 OR isnull(tov2.optval_isTranslated,'false') = convert(bit,@Confirm))

END





IF @Option = 2 --uniquetexts
BEGIN

	SELECT	Top(@cant)
			convert(VARCHAR,@lang_id_destiny) + @splitChar +
			convert(varchar,tut.utexts_id)						[ID],
			isnull(tut.utexts_desc,'')							[DESC1],
			isnull(tut2.utexts_desc,'')							[DESC2],
			isnull(tut.utexts_isTranslated,'False')				[CONF]

	FROM	tbsysUniqueTexts tut
			LEFT JOIN tbsysUniqueTexts tut2
			ON	tut2.utexts_id	= tut.utexts_id
			AND tut2.lang_id	= @lang_id_destiny

	WHERE	tut.lang_id = @lang_id_source
	AND 	(
			(@option_text        	 = -1 ) or
			(@option_text        	 = 0 and tut2.utexts_desc like @text + '%') or
			(@option_text        	 = 1 and tut2.utexts_desc like '%' + @text + '%') or
			(@option_text        	 = 2 and tut2.utexts_desc = @text ) or
			(@option_text        	 = 3 and tut2.utexts_desc <> @text) or
			(@option_text        	 = 4 and tut2.utexts_desc not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending=-1)	OR
			(@chk_pending= 0	and (tut2.utexts_desc = ''  or tut2.utexts_desc is null)) or
			(@chk_pending= 1	and (tut2.utexts_desc <> ''))
			)
	AND		(@Confirm = -1 OR isnull(tut2.utexts_isTranslated,'false') = convert(bit,@Confirm))

END




IF @Option = 3 --syswordsnew
BEGIN

	SELECT  Top(@cant)
		    convert(VARCHAR,@lang_id_destiny) + @splitChar +
			convert(varchar,tw.wordsi_id)						[ID],
			isnull(tw.word_desc,'')								[DESC1],
			isnull(tw2.word_desc,'')							[DESC2],
			isnull(tw.wordn_isTranslated,'False')				[CONF]

	FROM	tbsysWordsNew tw
			left JOIN tbsysWordsNew tw2
			ON	tw2.wordsi_id	= tw.wordsi_id
		    AND tw2.lang_id		= @lang_id_destiny


	WHERE	tw.lang_id = @lang_id_source
	AND		(
			(@option_text	= -1 ) or
			(@option_text   =  0 and tw2.word_desc like @text + '%') or
			(@option_text   =  1 and tw2.word_desc like '%' + @text + '%') or
			(@option_text   =  2 and tw2.word_desc = @text ) or
			(@option_text   =  3 and tw2.word_desc <> @text) or
			(@option_text   =  4 and tw2.word_desc not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending	= -1) OR
			(@chk_pending	=  0 and (tw2.word_desc  = '' or tw2.word_desc is null)) OR
			(@chk_pending	=  1 and (tw2.word_desc <> ''))
	)
	AND		(@Confirm = -1 OR isnull(tw2.wordn_isTranslated,'false')  = convert(bit,@Confirm))

END












IF @Option = 4 ---Menu languaje
BEGIN

	SELECT	Top(@cant)
			convert(varchar,@lang_id_destiny) + @splitChar +
     		convert(varchar,tml.menu_id)						[ID],
			isnull(tml.mid_desc,'')								[DESC1],
			isnull(tml2.mid_desc,'')							[DESC2],
			isnull(tml.mlang_isTranslated,'False')				[CONF]

	  FROM	tbsysMenuLanguage					tml
			left JOIN tbsysMenuLanguage			tml2
			ON tml2.menu_id		= tml.menu_id
			AND tml2.lang_id	= @lang_id_destiny

	WHERE tml.lang_id = @lang_id_source
	AND		(
			(@option_text        	 = -1 ) or
			(@option_text        	 = 0 and tml2.mid_desc like @text + '%') or
			(@option_text        	 = 1 and tml2.mid_desc like '%' + @text + '%') or
			(@option_text        	 = 2 and tml2.mid_desc = @text ) or
			(@option_text        	 = 3 and tml2.mid_desc <> @text) or
			(@option_text        	 = 4 and tml2.mid_desc not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending=-1)	OR
			(@chk_pending= '0'	and (tml2.mid_desc = '' or tml2.mid_desc is null)) OR
			(@chk_pending= '1'	and (tml2.mid_desc <> '')) -- or tw2.words_desc is not null))
			)
	AND		(@Confirm = -1 OR isnull(tml2.mlang_isTranslated,'false')  = convert(bit,@Confirm))

END






IF @Option = 5 ---tbsysHelpPages
BEGIN

	SELECT  Top(@cant)
			convert(varchar,@lang_id_destiny)	+ @splitChar +
			convert(varchar,thp.page_id)		+ @splitChar +
			convert(varchar,thp.table_id)						[ID],
			isnull(thp.hp_desc,'')								[DESC1],
			isnull(thp2.hp_desc,'')								[DESC2],
			isnull(thp.hp_isTranslated,'False')					[CONF]

	FROM	tbsysHelpPages							thp
			left JOIN tbsysHelpPages				thp2
			ON	thp2.page_id	= thp.page_id
			AND thp2.table_id	= thp.table_id
			AND thp2.lang_id	= @lang_id_destiny

	WHERE	thp.lang_id = @lang_id_source
	AND		(
			(@option_text	= -1 ) or
			(@option_text	= 0 and cast(thp2.hp_desc AS NVARCHAR(MAX)) like @text + '%') or
			(@option_text	= 1 and cast(thp2.hp_desc AS NVARCHAR(MAX)) like '%' + @text + '%') or
			(@option_text   = 2 and cast(thp2.hp_desc AS NVARCHAR(MAX)) = @text ) or
			(@option_text   = 3 and cast(thp2.hp_desc AS NVARCHAR(MAX)) <> @text) or
			(@option_text   = 4 and cast(thp2.hp_desc AS NVARCHAR(MAX)) not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending	= -1) OR
			(@chk_pending	= '0' and (cast(thp2.hp_desc AS NVARCHAR(MAX))  = '' or cast(thp2.hp_desc AS NVARCHAR(MAX)) is null)) OR
			(@chk_pending	= '1' and (cast(thp2.hp_desc AS NVARCHAR(MAX)) <> ''))
			)
	AND		(@Confirm = -1 OR isnull(thp2.hp_isTranslated,'false')  = convert(bit,@Confirm))

END



IF @Option = 6 --sysGBPUpgrades_Detail
BEGIN

	SELECT	Top(@cant)
			convert(VARCHAR,@lang_id_destiny) + @splitChar +
			convert(varchar,tg.upg_id)							[ID],
			isnull(tg.upg_detail,'')							[DESC1],
			isnull(tg2.upg_detail,'')							[DESC2],
			isnull(tg.optval_isTranslated,'False')				[CONF]

	FROM    tbsysGBPUpgrades tg
			LEFT JOIN tbsysGBPUpgrades tg2
			ON	tg2.upg_id	= tg.upg_id
			AND tg2.lang_id	= @lang_id_destiny


	WHERE	tg.lang_id = @lang_id_source
	AND 	(
			(@option_text        	 = -1 ) or
			(@option_text        	 = 0 and tg2.upg_detail like @text + '%') or
			(@option_text        	 = 1 and tg2.upg_detail like '%' + @text + '%') or
			(@option_text        	 = 2 and tg2.upg_detail = @text ) or
			(@option_text        	 = 3 and tg2.upg_detail <> @text) or
			(@option_text   	 = 4 and tg2.upg_detail not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending=-1)	OR
			(@chk_pending= 0	and (tg2.upg_detail = ''  or tg2.upg_detail is null)) or
			(@chk_pending= 1	and (tg2.upg_detail <> ''))
			)
	AND		(@Confirm = -1 OR isnull(tg.optval_isTranslated,'false') = convert(bit,@Confirm))

END


IF @Option = 7 --sysGBPUpgrades_Desc
BEGIN

	SELECT	Top(@cant)
			convert(VARCHAR,@lang_id_destiny) + @splitChar +
			convert(varchar,tg.upg_id)							[ID],
			isnull(tg.upg_desc,'')								[DESC1],
			isnull(tg2.upg_desc,'')								[DESC2],
			isnull(tg.optval_isTranslated,'False')				[CONF]

	FROM    tbsysGBPUpgrades tg
			LEFT JOIN tbsysGBPUpgrades tg2
			ON	tg2.upg_id	= tg.upg_id
			AND tg2.lang_id	= @lang_id_destiny


	WHERE	tg.lang_id = @lang_id_source
	AND 	(
			(@option_text        	 = -1 ) or
			(@option_text        	 = 0 and tg2.upg_desc like @text + '%') or
			(@option_text        	 = 1 and tg2.upg_desc like '%' + @text + '%') or
			(@option_text        	 = 2 and tg2.upg_desc = @text ) or
			(@option_text        	 = 3 and tg2.upg_desc <> @text) or
			(@option_text        	 = 4 and tg2.upg_desc not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending=-1)	OR
			(@chk_pending= 0	and (tg2.upg_desc = ''  or tg2.upg_desc is null)) or
			(@chk_pending= 1	and (tg2.upg_desc <> ''))
			)
	--AND		(@Confirm = -1 OR isnull(tg.optval_isTranslated,'false') = convert(bit,@Confirm))

END
GO

CREATE PROCEDURE [dbo].[spTurnManagement_CancelTurn]
(
	@comp_id	INT,
	@tmn_id		INT
)
AS
	BEGIN
		SET NOCOUNT ON

		UPDATE tbTurnManagement
		SET
			tmn_beginDate			= NULL,
			tmn_endDate				= NULL,
			user_id_4BeginProcess	= NULL,
			user_id_4EndProcess		= NULL,
			cust_id					= NULL,
			item_id					= NULL,
			rmah_id					= NULL,
			tmn_note				= NULL
		WHERE	comp_id				= @comp_id AND
				tmn_id				= @tmn_id
	END
GO





create PROCEDURE [dbo].[spTurnManagement_Class_getCombo]

	@comp_id				INT

as
set nocount on

SELECT     	tmnc_id		[id],
			tmnc_desc	[desc]

FROM tbTurnManagement_Class

WHERE  	comp_id			= @comp_id and
		tmnc_disabled   = 'False'

Order BY tmnc_desc
GO

CREATE PROCEDURE [dbo].[spTurnManagement_Class_GetComboByProfile]
(
	@comp_id	INT,
	@prof_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@prof_id	INT
			SELECT
				@comp_id	= 1,
				@prof_id	= 1
		*/
		-- -----------------------------------------

		SELECT DISTINCT
			ttmc.tmnc_id	[Id],
			ttmc.tmnc_desc	[Desc]
			FROM tbTurnManagement_Class					ttmc	WITH(NOLOCK)
			INNER JOIN tbTurnManagement_ClassByProfile	ttmcbp	WITH(NOLOCK)
			ON	ttmcbp.comp_id		= ttmc.comp_id		AND
				ttmcbp.tmnc_id		= ttmc.tmnc_id
			WHERE	ttmc.comp_id	= @comp_id			AND
					ttmcbp.prof_id	= @prof_id			AND
					ISNULL(ttmc.tmnc_disabled,'False')	= 'False'
	END
GO


CREATE PROCEDURE spTurnManagement_ClassByProfile_GetDataById
(
	@comp_id	INT,
	@bra_id		INT,
	@prof_id	INT,
	@tmnc_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@prof_id	INT,
				@tmnc_id	INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@prof_id	= 1,
				@tmnc_id	= 4
		*/
		-- ------------------------------------------------

		SELECT
			ttmcbp.comp_id,
			ttmcbp.bra_id,
			ttmcbp.prof_id,
			ttmcbp.tmnc_id,
			ttmcbp.isDisabled,
			ISNULL(ttmcbp.tmp_enableItem,		'False')	[tmp_enableItem],
			ISNULL(ttmcbp.tmp_enableCustomer,	'False')	[tmp_enableCustomer],
			ISNULL(ttmcbp.tmp_enableSupplier,	'False')	[tmp_enableSupplier],
			ISNULL(ttmcbp.tmp_enableRMA,		'False')	[tmp_enableRMA],
			ISNULL(ttmcbp.tmp_enableBeginData,	'False')	[tmp_enableBeginData],
			ISNULL(ttmcbp.tmp_enableEndData,	'False')	[tmp_enableEndData],
			ISNULL(ttmcbp.tmp_enableNoteUpdate,	'False')	[tmp_enableNoteUpdate]
			FROM tbTurnManagement_ClassByProfile			ttmcbp
			WHERE	ttmcbp.comp_id	= @comp_id				AND
					ttmcbp.bra_id	= @bra_id				AND
					ttmcbp.prof_id	= @prof_id				AND
					ttmcbp.tmnc_id	= @tmnc_id
	END
GO


CREATE procedure [dbo].[spTurnManagement_getData]
(
		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT,
		@date4Turn			DATETIME,
		@tmnc_id			INT,
		@cust_id			INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'

		-- ---------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------
		/*
			DECLARE
				@comp_id		INT,
				@lang_id		INT,
				@bra_id			INT,
				@user_id		INT,
				@prof_id		INT,
				@date4Turn		DATETIME,
				@tmnc_id		INT
			SELECT
				@comp_id		= 1,
				@lang_id		= 2,
				@bra_id			= 1,
				@user_id		= 134,
				@prof_id		= 1,
				@date4Turn		= '2019-04-23',
				@tmnc_id		= 4
		*/
		-- ---------------------------------------------------

		SET DATEFIRST 7		-- Domingo x Defecto
		DECLARE @intDayofweek AS INT
		SET		@intDayofweek = datepart(dw,@date4Turn)


		DECLARE @fromDate4Turn as DATETIME
		DECLARE @toDate4Turn   as DATETIME
		SET		@fromDate4Turn		= dbo.fnGetEnd_or_BeginOfDate(@date4Turn,'False')
		SET		@toDate4Turn	    = dbo.fnGetEnd_or_BeginOfDate(@date4Turn,'True')


		SELECT
			''												[1],	-- MODIFICAR ARTICULO / NOTA
			''												[2],	-- FECHA DE INICIO / FIN CON USUARIOS
			''												[3],	-- BORRAR REGISTRO
			''												[4],	-- IMPRIMIR RMA (SI ES QUE TIENE)
			''												[5],	-- ABRIR RMA
			''												[6],	-- CARGAR RMA A ESTE TURNO
			ttmc.tmnc_desc,
			ttm.tmn_turnDate,
			ISNULL(CONVERT(VARCHAR,tc.cust_id),'')			[cust_id],
			ISNULL(tc.cust_name,'')							[cust_name],
			ISNULL(CONVERT(VARCHAR,ts.supp_id),'')			[supp_id],
			ISNULL(ts.supp_name,'')							[supp_name],
			ISNULL(ti.item_code, '')						[item_code],
			ISNULL(ti.item_desc,'')							[item_desc],

			CASE WHEN ttm.user_id_4BeginProcess IS NULL THEN	''
			ELSE												tu.user_lastname + ',' + tu.user_firstname
			END												[User_4BeginProcess],
			ttm.tmn_beginDate,

			CASE WHEN ttm.user_id_4EndProcess IS NULL THEN	''
			ELSE											tu2.user_lastname + ',' + tu2.user_firstname
			END												[User_4EndProcess],
			ttm.tmn_endDate,
			ttm.rmah_id,
			-- -------------------------------------------------------------------------
			-- NO PONER NADA ANTES DE ESTO, TODOS LOS CAMPOS NUEVOS VAN A CONTINUACiÓN
			-- -------------------------------------------------------------------------
			ttm.tmn_id										[ID]
			FROM tbTurnManagement				ttm		WITH(NOLOCK)
			LEFT JOIN tbCustomer				tc		WITH(NOLOCK)
			ON	tc.comp_id		= ttm.comp_id	AND
				tc.cust_id		= ttm.cust_id
			LEFT JOIN tbSupplier				ts		WITH(NOLOCK)
			ON	ts.comp_id		= ttm.comp_id	AND
				ts.supp_id		= ttm.supp_id
			LEFT JOIN tbItem					ti		WITH(NOLOCK)
			ON	ti.comp_id		= ttm.comp_id	AND
				ti.item_id		= ttm.item_id
			LEFT JOIN tbUser					tu		WITH(NOLOCK)
			ON	tu.[user_id]	= ttm.user_id_4BeginProcess
			LEFT JOIN tbUser					tu2		WITH(NOLOCK)
			ON	tu2.[user_id]	= ttm.user_id_4EndProcess
			INNER JOIN tbTurnManagement_Class	ttmc	WITH(NOLOCK)
			ON	ttmc.comp_id	= ttm.comp_id	AND
				ttmc.tmnc_id	= ttm.tmnc_id
			WHERE	ttm.comp_id										= @comp_id		AND
					ttm.bra_id										= @bra_id		AND
					ttm.tmnc_id										= @tmnc_id		AND
					ttm.tmn_turnDate  BETWEEN @fromDate4Turn AND @toDate4Turn		AND
					(
						@cust_id	= -1 OR
						ttm.cust_id = @cust_id
					)
					ORDER BY ttm.tmn_turnDate

	END
GO

CREATE PROCEDURE [dbo].[spTurnManagement_GetDataByID]
(
	@comp_id	INT,
	@lang_id	INT,
	@tmn_id		INT
)
AS
	BEGIN
