			ttm.tmn_cd,
			ttm.bra_id,
			ttm.cust_id,
			ttm.supp_id,
			ttm.item_id,
			ISNULL(ttm.rmah_id,0)		[rmah_id],
			ttm.tmn_beginDate,
			ttm.tmn_endDate,
			ttm.user_id_4BeginProcess,
			ttm.user_id_4EndProcess,
			ISNULL(ttm.tmn_note,'')		[tmn_note],
			ttm.tmnc_id
		FROM tbTurnManagement			ttm	WITH(NOLOCK)
		WHERE	ttm.comp_id = @comp_id	AND
				ttm.tmn_id	= @tmn_id

	END
GO

