CREATE PROCEDURE [dbo].[spTurnManagement_Turns_GenerateTurns]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@date4Turn			DATETIME,
	@tmnc_id			INT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		--  --------------------------------------------------------------------------------------------------
		-- Testing
		--  --------------------------------------------------------------------------------------------------
		/*
			DECLARE 		@comp_id			INT,
							@lang_id			INT,
							@bra_id				INT,
							@prof_id			INT,
							@user_id			INT,
							@date4Turn			DATETIME

			SELECT			@comp_id			= 1,
							@lang_id			= 2,
							@bra_id				= 1,
							@prof_id			= 1,
							@user_id			= 134,
							@date4Turn			= '2019-04-22'
		*/
		-- --------------------------------------------------------------------------------------------------
		SET DATEFIRST 7 -- Domingo x Defecto
		DECLARE @intDayofweek AS INT
		SET		@intDayofweek	= DATEPART(dw,@date4Turn)
		SET		@date4Turn		= dbo.fnGetEnd_or_BeginOfDate(@date4Turn,'False')

		--==
			--SELECT @intDayofweek, @date4Turn
		--==

		INSERT INTO tbTurnManagement
		(
			comp_id,
			tmn_turnDate,
			bra_id,
			tmnc_id,
			tmn_note
		)
		SELECT	ttmtm.comp_id,
				DATEADD(MINUTE,DATEPART(MINUTE,ttmtm.tmnm_turnTime), DATEADD(HOUR,DATEPART(HOUR,ttmtm.tmnm_turnTime),@date4Turn)) [tmpDateTurn],
				@bra_id,
				@tmnc_id,
				ISNULL(ttmc.tmp_noteMask,'')
			FROM tbTurnManagement_TurnsMask				ttmtm	WITH(NOLOCK)
			INNER JOIN tbTurnManagement_Class			ttmc	WITH(NOLOCK)
			ON	ttmc.comp_id		= ttmtm.comp_id AND
				ttmc.tmnc_id		= ttmtm.tmnc_id
			LEFT JOIN tbCompany_unWorkDays				tcuwd	WITH(NOLOCK)
			ON	tcuwd.comp_id		= ttmtm.comp_id AND
				tcuwd.nld_date		= @date4Turn
			LEFT JOIN tbTurnManagement					ttm		WITH(NOLOCK)
			ON	ttm.comp_id			= @comp_id		AND
				ttm.bra_id			= @bra_id		AND
				ttm.tmn_turnDate	= DATEADD(MINUTE,DATEPART(MINUTE,ttmtm.tmnm_turnTime), DATEADD(HOUR,DATEPART(HOUR,ttmtm.tmnm_turnTime),@date4Turn))
			WHERE	ttmtm.comp_id				= @comp_id		AND
					ttmtm.tmnm_turnDayOfWeek	= @intDayofweek AND
					ttmtm.tmnc_id				= @tmnc_id		AND
					(
						ttmtm.bra_id			= @bra_id
						OR
						ttmtm.bra_id IS NULL
					)										AND
					ttm.comp_id		IS NULL					AND
					tcuwd.comp_id	IS NULL
END

GO


CREATE PROCEDURE [dbo].[spTurnManagement_UpdateData]
(
	@comp_id				INT,
	@tmn_id					INT,
	@user_id_4BeginProcess	INT,
	@user_id_4EndProcess	INT,
	@isAssembled			BIT
)
AS

	BEGIN
		SET NOCOUNT ON
		SET DATEFORMAT 'YMD'
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@tmn_id					INT,
				@user_id_4BeginProcess	INT,
				@user_id_4EndProcess	INT,
				@isAssembled			BIT
			SELECT
				@comp_id				= 1,
				@tmn_id					= 4648,
				@user_id_4BeginProcess	= 134,
				@user_id_4EndProcess	= 134,
				@isAssembled			= 'True'
		*/
		-- ---------------------------------------------
		IF @isAssembled = 'True'
			BEGIN
				UPDATE tbTurnManagement
				SET
					tmn_endDate				= GETDATE(),
					user_id_4EndProcess		= @user_id_4EndProcess
				WHERE	comp_id				= @comp_id AND
						tmn_id				= @tmn_id
			END
		ELSE
			IF @isAssembled = 'False'
				BEGIN
					UPDATE tbTurnManagement
					SET
						tmn_beginDate			= GETDATE(),
						user_id_4BeginProcess	= @user_id_4BeginProcess
					WHERE	comp_id				= @comp_id AND
							tmn_id				= @tmn_id
				END
	END
GO

