CREATE PROCEDURE [dbo].[spUser_getCombo4Authorizacions]
	@comp_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@guid			UNIQUEIDENTIFIER
AS


BEGIN


	-- -------------------------------------------
	-- Testing
	-- -------------------------------------------
	/*
	DECLARE @comp_id		INT
	DECLARE @bra_id			INT
	DECLARE @prof_id		INT
	DECLARE @guid			UNIQUEIDENTIFIER


	SET @comp_id		= 1
	SET @bra_id			= 1
	SET @prof_id		= 2
	SET @guid			= '78095cac-701f-4524-9545-176ff368e34d'
	*/
	-- -------------------------------------------


	set nocount on

	SELECT	distinct
				tu.user_id										[id],
				tu.user_lastname + ', ' + user_firstname		[desc]

		from		dbo.tbUser				tu
		INNER JOIN tbUserCompanyProfile		tucp			WITH (NOLOCK)				-- Todos los Usuarios de ESTA SUCURSAL
			ON	tucp.comp_id	= @comp_id		AND
				tucp.bra_id		= @bra_id		AND
				tucp.[user_id]	= tu.[user_id]

		INNER JOIN tbProfileAuthorization	tpa				WITH (NOLOCK)
			ON	tpa.comp_id		= tucp.comp_id	AND
				tpa.prof_id		= tucp.prof_id

		INNER JOIN tbAutorizationRequest	tar				WITH (NOLOCK)
			ON  tar.comp_id		= tpa.comp_id	AND
				tar.aut_id		= tpa.aut_id

		WHERE	tar.aure_guid	= @guid AND
				tu.user_Blocked = 'False'
		Order By	[desc]


END
GO

CREATE PROCEDURE [dbo].[spUser_GetCombo4TurnManagement]
(
	@comp_id	INT,
	@bra_id		INT,
	@tmnc_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------
		-- TESTING
		-- ---------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@bra_id		INT,
				@tmnc_id	INT,
				@prof_id	INT
			SELECT
				@comp_id	= 1,
				@bra_id		= 1,
				@tmnc_id	= 4,
				@prof_id	= 1
		*/
		-- ---------------------------------------

		DECLARE	@tblProfilesByClass TABLE(
											comp_id			INT,
											bra_id			INT,
											prof_id			INT PRIMARY KEY
										 )
		INSERT INTO @tblProfilesByClass
		(
			comp_id,
			bra_id,
			prof_id
		)
		SELECT DISTINCT
			ttmcbp.comp_id,
			ttmcbp.bra_id,
			ttmcbp.prof_id
		FROM tbTurnManagement_ClassByProfile	ttmcbp	WITH(NOLOCK)
		WHERE	ttmcbp.comp_id	= @comp_id		AND
				ttmcbp.bra_id	= @bra_id		AND
				ttmcbp.tmnc_id	= @tmnc_id

		SELECT
			tu.[user_id] [Id],
			tu.user_lastname + ',' + tu.user_firstname [Desc]
		FROM tbUserCompanyProfile		tucp	WITH(NOLOCK)
		INNER JOIN @tblProfilesByClass	tmp
		ON	tmp.comp_id = tucp.comp_id AND
			tmp.bra_id	= tucp.bra_id AND
			tmp.prof_id = tucp.prof_id
		INNER JOIN tbUser tu					WITH (NOLOCK)
		ON tu.[user_id] = tucp.[user_id]
		WHERE	tucp.comp_id	= @comp_id	AND
				tucp.bra_id		= @bra_id	AND
				tu.user_Blocked = 'False'
	END
GO



-- Todos los Usuarios de ESTA SUCURSAL, que tengan un perfil activo y seleccionable y tengan un usuario relacionado con un vendedor


CREATE PROCEDURE [dbo].[spUser_getCombo4UserID]
	@comp_id		INT,
	@bra_id			INT,
	@prof_id		INT,
	@guid			UNIQUEIDENTIFIER
AS


BEGIN


	-- -------------------------------------------
	-- Testing
	-- -------------------------------------------
	/*
	DECLARE @comp_id		INT
	DECLARE @bra_id			INT
	DECLARE @prof_id		INT
	DECLARE @guid			UNIQUEIDENTIFIER


	SET @comp_id		= 1
	SET @bra_id			= 1
	SET @prof_id		= 2
	SET @guid			= '78095cac-701f-4524-9545-176ff368e34d'
	*/
	-- -------------------------------------------


	set nocount on

	SELECT	distinct
				tu.user_id										[id],
				tu.user_lastname + ', ' + user_firstname		[desc]

		from		dbo.tbUser				tu			 WITH (NOLOCK)
		INNER JOIN tbUserCompanyProfile		tucp		 WITH (NOLOCK)
			ON	tucp.comp_id		= @comp_id		AND
				tucp.bra_id			= @bra_id		AND
				tucp.[user_id]		= tu.[user_id]
		INNER JOIN tbProfile tp							WITH (NOLOCK)
			ON	tp.comp_id			= tucp.comp_id		AND
				tp.prof_id			= tucp.prof_id


		INNER JOIN tbUserSalesmanRelation tusr			WITH (NOLOCK)
			ON	tusr.[user_id]		= tu.[user_id]	AND
				tusr.bra_id			= @bra_id		AND
				tusr.comp_id		= @comp_id
		WHERE	tp.prof_notInDDL	= 'False'		AND
				tp.prof_disabled	= 'False'
		Order By	[desc]


END
GO

