CREATE PROCEDURE [dbo].[spUser_GetComboUsersByAssemblyGroup]
(
	@comp_id	INT,
	@tar_id		INT
)
AS

	SET NOCOUNT ON

		BEGIN
			-- ------------------------
			-- TESTING
			-- ------------------------
			/*
				DECLARE
					@comp_id	INT,
					@tar_id		INT

				SELECT
					@comp_id	= 1,
					@tar_id		= 1
			*/
			-- ------------------------


			--TRAE LOS USUARIOS DE UN GRUPO DE ENSAMBLADO EN PARTICULAR
			SELECT
				tu.[user_id]									[Id],
				tu.user_lastname + ',' + tu.user_firstname		[Desc]

			FROM tbUser								tu

			INNER JOIN tbAssembly_TeamUsersRelation tatur
			ON tatur.[user_id]		= tu.[user_id]

			WHERE	tatur.comp_id	= @comp_id		AND
					tatur.tar_id	= @tar_id

		END

GO









