CREATE  PROCEDURE [dbo].[spUser_getdataById]
(
	@user_id		as	INT,
	@comp_id		AS  INT
)
AS

BEGIN




	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	SET NOCOUNT ON



	SELECT 	user_firstname,
			user_lastname,
			user_lastcompany,
			user_lastprofile,
			user_lastbranch,
			user_nick,
			tu.comp_id,
			ISNULL(user_forceLogout,'False')					[user_forceLogout],
			ISNULL(user_email,'')								[user_email],
			ISNULL(user_disableSessionControl,'False')			[user_disableSessionControl],	--Agregado por STL 24-09-2010
			ISNULL(user_lastwebsite,-1)							[user_lastwebsite],
			ISNULL(user_WebSite_flashdisabled,'false')			[user_WebSite_flashdisabled],


			isnull(user_available4CRM, 'false')					[user_available4CRM],
			isnull(user_available4CRM_UpdateAllTasks,'false')	[user_available4CRM_UpdateAllTasks],
			isnull(user_available4CRM_UpdateAllCalls,'false')	[user_available4CRM_UpdateAllCalls],
			isnull(user_available4CRM_UpdateAllCases,'false')	[user_available4CRM_UpdateAllCases],
			isnull(user_available4CRM_UpdateAllMeets,'false')	[user_available4CRM_UpdateAllMeets],
			isnull(user_available4CRM_DeleteAllTasks,'false')	[user_available4CRM_DeleteAllTasks],
			isnull(user_available4CRM_DeleteAllCalls,'false')	[user_available4CRM_DeleteAllCalls],
			isnull(user_available4CRM_DeleteAllCases,'false')	[user_available4CRM_DeleteAllCases],
			isnull(user_available4CRM_DeleteAllMeets,'false')	[user_available4CRM_DeleteAllMeets],
			isnull(user_available4CRM_InsertTaskFromSO,'false')	[user_available4CRM_InsertTaskFromSO],
			isnull(user_available4CRM_InsertMeetFromSO,'false')	[user_available4CRM_InsertMeetFromSO],
			isnull(user_available4CRM_InsertCallFromSO,'false')	[user_available4CRM_InsertCallFromSO],
			isnull(user_available4CRM_InsertCaseFromSO,'false')	[user_available4CRM_InsertCaseFromSO],
			IsNull(user_ScriptXNoModal,'False')					[user_ScriptXNoModal],
			IsNull(user_FastReportsDisabled,'False')			[user_FastReportsDisabled],
			ISNULL(user_available4CRM_CanReAsignateCase,'False')[user_available4CRM_CanReAsignateCase],
			ISNULL(user_available4CRM_CanReAsignateMeet,'False')[user_available4CRM_CanReAsignateMeet],
			ISNULL(user_available4CRM_CanReAsignateTask,'False')[user_available4CRM_CanReAsignateTask],
			ISNULL(user_available4CRM_CanReAsignateCall, 'False')[user_available4CRM_CanReAsignateCall],
			ISNULL(user_available4CRM_Documents, 'False')		[user_available4CRM_Documents],
			ISNULL(user_available4CRM_UpdateAllNotes,'False')	[user_available4CRM_UpdateAllNotes],
			ISNULL(user_available4CRM_SeeAllNotes,'False')		[user_available4CRM_SeeAllNotes],
			user_passLastChange,
			user_passForceChange,
			ISNULL(user_available4CRM_DeleteAllNotes,'False')	[user_available4CRM_DeleteAllNotes],
			ISNULL(user_available4CRM_DeleteOwnNotes,'False')	[user_available4CRM_DeleteOwnNotes],
			user_fastPass										[user_fastPass],
			user_lastWebSiteII_id,
			user_password,
			IsNull(user_theme,'')								[user_theme],
