			ISNULL(tu.user_googleEmail,'')						[user_googleEmail],
			ISNULL(tu.user_googleClientID,'')					[user_googleClientID],
			ISNULL(tu.user_googleClientSecret,'')				[user_googleClientSecret],
			ISNULL(tu.user_googleRefreshToken,'')				[user_googleRefreshToken],
			ISNULL(tu.user_googleToken,'')						[user_googleToken],
			tu.user_googleTokenValidUp2Date





	FROM 	[tbUser]	tu	WITH (NOLOCK)
	LEFT JOIN tbCompany tc	WITH (NOLOCK)
		ON tc.comp_id = @comp_id

	WHERE 	tu.[USER_ID]	= @user_id




