CREATE PROCEDURE [dbo].[spUser_getDataByNick]
(
	@user_nick		AS VARCHAR(50)
)
AS

BEGIN

	SET NOCOUNT ON

	SET @user_nick = UPPER(@user_nick)

	SELECT	tu.*,
			DB_NAME()												[dbName] ,
			ISNULL(tu.user_login_LastLoginDate,GETDATE() - 100)		[dbLastLogin],
			ISNULL(tu.user_printClass,'True')						[user_printClass]
		FROM 	[tbUser] tu	WITH (NOLOCK)
		WHERE 	UPPER(user_nick)	= @user_nick

END
