CREATE PROCEDURE [dbo].[spUser_getLoggedCount]
(
	@return_value	INT OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON

	select	@return_value	= count(*)
	from	[tbUser]		WITH (NOLOCK)
	where	user_login		= 'True'						AND 
			UPPER(user_nick) <> UPPER('ERPImplementador')	AND
			UPPER(user_nick) <> UPPER('ERPWebDesigner')		AND  
			UPPER(user_nick) <> UPPER('ERPSoporte')			AND
			UPPER(user_nick) <> UPPER('ERPSoporte2')		AND 
			UPPER(user_nick) <> UPPER('ERPAdmin')
			
END




GO
