CREATE  PROCEDURE [dbo].[spUser_getLogin]
(
	@user_nick				varchar(50),	
	@user_password			varchar(1000),
	@user_boolean			BIT,
	@user_login_ip			VARCHAR(20),
	@user_login_name		VARCHAR(50),
	@return_value			INTEGER OUTPUT		
)
AS
BEGIN
	SET NOCOUNT ON
	DECLARE @luser_id INT,
			@luser_login BIT,
			@lIsSysAdmin AS BIT,
			@bitForceChange	AS BIT,
			@user_loginFailBlocked	BIT,
			@user_passwordUSR NVARCHAR(100),
			@user_Blocked BIT			
	SELECT	@luser_id			=[user_id],
			@luser_login		=user_login,
			@lIsSysAdmin		=ISNULL(user_sysAdmin,'False'),
			@bitForceChange		=ISNULL(user_passForceChange,'False'),
			@user_loginFailBlocked	=user_loginFailBlocked,
			@user_passwordUSR		=dbo.fnStrAllTrim(user_password),
			@user_Blocked			=user_Blocked
		FROM	[tbUser]	WITH (NOLOCK)
		WHERE	user_nick			= @user_nick 
	SET @user_password = dbo.fnStrAllTrim(@user_password)
	IF @luser_login = 'true' AND @user_passwordUSR = @user_password	AND UPPER(@user_nick) NOT IN ('ERPADMIN','ERPSOPORTE','ERPSOPORTE2')
		BEGIN
			SET		@return_value	= 2
			SELECT 	u.						[user_id], 
					tut.utexts_desc, 
					tut2.utexts_desc		[utexts_desc2],
					@lIsSysAdmin			[SysAdmin],
					@bitForceChange			[user_passForceChange]
				FROM 	[tbUser]					u				WITH (NOLOCK)
						LEFT JOIN tbsysUniqueTexts	tut				WITH (NOLOCK)
						ON	tut.lang_id		= u.user_lastlanguage
						AND tut.utexts_id	= 7
						LEFT JOIN tbsysUniqueTexts	tut2			WITH (NOLOCK)
						ON	tut2.lang_id	= u.user_lastlanguage
						AND tut2.utexts_id	= 8 
			WHERE 	u.user_nick		= @user_nick
			AND 	u.user_password	= @user_password
			RETURN
		END
	IF @user_Blocked = 'True' OR @luser_id IS NULL
		BEGIN
			SET		@return_value	= -1
			SELECT	-1
		END
	ELSE IF @user_passwordUSR <> @user_password 
		BEGIN
			EXEC spUser_getLoginFailCheck	@luser_id,					
											@user_nick,			
											@user_password,		
											@user_boolean,		
											@user_login_ip,		
											@user_login_name	
			SET		@return_value	= -1
			SELECT	-1			
		END
	ELSE IF @user_passwordUSR = @user_password AND @user_loginFailBlocked = 'True'
		BEGIN
			EXEC spUser_getLoginFailCheck	@luser_id,					
											@user_nick,			
											@user_password,		
											@user_boolean,		
											@user_login_ip,		
											@user_login_name
			IF EXISTS(SELECT 1 FROM tbuser WHERE [user_id]=@luser_id AND user_loginFailBlocked = 'False' )
				BEGIN
					UPDATE	tbUser	WITH (ROWLOCK)
						SET		user_login		= 'True',
								user_login_CD	= GETDATE(),
								user_login_ip	= @user_login_ip,
								user_login_name = @user_login_name
						WHERE	user_nick		= @user_nick	
					-- Permite Entrar
					SET		@return_value	= 0
					SELECT 	@luser_id		[user_id],
							@lIsSysAdmin	[SysAdmin],
							@bitForceChange	[user_passForceChange]	
				END
			ELSE
				BEGIN
					SET		@return_value	= -5
					SELECT	-1
					RETURN						
				END
		END
	ELSE IF @user_passwordUSR = @user_password	
		BEGIN
			SET		@return_value	= 0
			SELECT 	@luser_id		[user_id],
					@lIsSysAdmin	[SysAdmin],
					@bitForceChange	[user_passForceChange]
			--actualizacion para indicar que el usuario se logueo 
			IF (LTRIM(RTRIM(UPPER(@user_nick))) <> UPPER('ERPAdmin')) 
				BEGIN
					UPDATE	tbUser	WITH (ROWLOCK)
						SET		user_login		= 'True',
								user_login_CD	= GETDATE(),
								user_login_ip	= @user_login_ip,
								user_login_name = @user_login_name, 
								user_loginFailCount = 0,
								user_loginFailIndex = 0
						WHERE	user_nick		= @user_nick
						AND 	user_password	= @user_password
						AND		@user_boolean	= 'False'
				END	
			ELSE
				BEGIN
					UPDATE	tbUser	WITH (ROWLOCK)
						SET		user_login		= 'True',
								user_login_CD	= GETDATE(),
								user_login_ip	= @user_login_ip,
								user_login_name = @user_login_name
						WHERE	user_nick		= @user_nick
				END
		END
END

GO

/****/
/**** ATENCION: ESTE PROCEDIMIENTO ESTA BAJO CONTROL DE CRC */
/****/
CREATE  PROCEDURE [dbo].[spUser_getLoginFailCheck]
(
	@user_id				INT,
	@user_nick				varchar(50),
	@user_password			varchar(1000),
	@user_boolean			BIT,
	@user_login_ip			VARCHAR(20),
	@user_login_name		VARCHAR(50)
)
AS
BEGIN


	SET NOCOUNT ON

	DECLARE @luser_login				BIT,
			@luser_login_ip				VARCHAR(20),
			@luser_login_name			VARCHAR(50),
			@lIsSysAdmin				AS BIT,
			@bitForceChange				AS BIT,
			@user_loginFailCount		INT,
			@user_loginFailLastDate		DATETIME,
			@user_loginFailIndex		decimal(19, 4),
			@user_loginFailBlocked		BIT,
			@user_passwordUSR			NVARCHAR(100),
			@user_Blocked				BIT

	SELECT	@luser_login			=	user_login,
			@luser_login_ip			=	user_login_ip,
			@luser_login_name		=	user_login_name,
			@lIsSysAdmin			=	ISNULL(user_sysAdmin,'False'),
			@bitForceChange			=	ISNULL(user_passForceChange,'False'),
			@user_loginFailCount	=	ISNULL(user_loginFailCount,0),
			@user_loginFailLastDate	=	ISNULL(user_loginFailLastDate,GETDATE() - 100),
			@user_loginFailIndex	=	ISNULL(user_loginFailIndex,0),
			@user_loginFailBlocked	=	ISNULL(user_loginFailBlocked,'False')
		FROM	[tbUser]	WITH (NOLOCK)
		WHERE	[user_id]			= @user_id



	INSERT INTO tbUser_loginFail
	(
		-- ulf_id -- this column value is auto-generated,
		[user_id],
		ulf_date,
		ulf_IP,
		ulf_loginFailCount,
		ulf_loginBlocked,
		ulf_loginBlockedReleasePending
	)
	VALUES
	(
		@user_id,
		GETDATE(),
		@user_login_ip,
		@user_loginFailCount + 1,
		CASE
			WHEN @user_loginFailCount > 5 THEN  'True'
			ELSE								'False'
		END,
		CASE
			WHEN @user_loginFailCount = 6 THEN  'True'
			ELSE								'False'
		END
	)

	IF (LTRIM(RTRIM(UPPER(@user_nick))) = UPPER('ERPAdmin'))	OR
	   (LTRIM(RTRIM(UPPER(@user_nick))) = UPPER('ERPSoporte'))	OR
	   (LTRIM(RTRIM(UPPER(@user_nick))) = UPPER('ERPSoporte2'))
		BEGIN
			RETURN
		END

	UPDATE tbuser	WITH (ROWLOCK)
		SET user_loginFailCount		= @user_loginFailCount + 1,
			user_loginFailLastDate	= GETDATE(),
			user_loginFailIndex		= DATEDIFF(minute, @user_loginFailLastDate, GETDATE()) + @user_loginFailIndex,
			user_loginFailBlocked	= CASE
									      WHEN (@user_loginFailCount + 1) > 5 THEN  'True'
										  ELSE										'False'
									  END
		WHERE [USER_ID] = @user_id


	-- Si pasa mas de una hora y no se equivoco demasiadas veces
	SELECT	@user_loginFailCount	=	ISNULL(user_loginFailCount,0),
			@user_loginFailIndex	=	ISNULL(user_loginFailIndex,0),
			@user_loginFailBlocked	=	ISNULL(user_loginFailBlocked,'False')
		FROM	[tbUser]	WITH (NOLOCK)
		WHERE	[user_id]			= @user_id

	IF	@user_loginFailBlocked = 'True'							AND
		DATEDIFF(hour,@user_loginFailLastDate,GETDATE()) > 1	AND
		@user_loginFailIndex							<= 10	AND
		@user_loginFailCount							 < 10
		BEGIN
			UPDATE tbuser	WITH (ROWLOCK)
				SET user_loginFailCount		= 0,
					user_loginFailBlocked	= 'False'
				WHERE [user_id] = @user_id
		END

END
GO
