/**** ATENCION: CONTROL DE CRC */
/****/
CREATE  PROCEDURE [dbo].[spUser_getLoginMobile]
(
	@user_nick				varchar(50),	
	@user_password			varchar(1000),
	@user_boolean			BIT,
	@user_login_ip			VARCHAR(20),
	@user_login_name		VARCHAR(50),
	@return_value			INTEGER OUTPUT		
)
AS
BEGIN
	SET NOCOUNT ON
	DECLARE @luser_id INT,
			@luser_login BIT,
			@lIsSysAdmin AS BIT,
			@bitForceChange	AS BIT,
			@user_loginFailBlocked	BIT,
			@user_passwordUSR NVARCHAR(100),
			@user_Blocked BIT			
	SELECT	@luser_id			=[user_id],
			@luser_login		='False',
			@lIsSysAdmin		=ISNULL(user_sysAdmin,'False'),
			@bitForceChange		=ISNULL(user_passForceChange,'False'),
			@user_loginFailBlocked	=user_loginFailBlocked,
			@user_passwordUSR		=dbo.fnStrAllTrim(user_password),
			@user_Blocked			=user_Blocked
		FROM	[tbUser]	WITH (NOLOCK)
		WHERE	user_nick			= @user_nick 
	SET @user_password = dbo.fnStrAllTrim(@user_password)

	IF @user_Blocked = 'True' OR @luser_id IS NULL
		BEGIN
			SET		@return_value	= -1
			SELECT	-1
		END
	ELSE IF @user_passwordUSR <> @user_password 
		BEGIN
			EXEC spUser_getLoginFailCheck	@luser_id,					
											@user_nick,			
											@user_password,		
											@user_boolean,		
											@user_login_ip,		
											@user_login_name	
			SET		@return_value	= -1
			SELECT	-1			
		END
	ELSE IF @user_passwordUSR = @user_password AND @user_loginFailBlocked = 'True'
		BEGIN
			EXEC spUser_getLoginFailCheck	@luser_id,					
											@user_nick,			
											@user_password,		
											@user_boolean,		
											@user_login_ip,		
											@user_login_name
			IF EXISTS(SELECT 1 FROM tbuser WHERE [user_id]=@luser_id AND user_loginFailBlocked = 'False' )
				BEGIN
					UPDATE	tbUser	WITH (ROWLOCK)
						SET		user_login_Mobile	= 'True',
								user_login_MobileCD	= GETDATE(),
								user_login_MobileIP	= @user_login_ip
						WHERE	user_nick		= @user_nick	
					-- Permite Entrar
					SET		@return_value	= 0
					SELECT 	@luser_id		[user_id],
							@lIsSysAdmin	[SysAdmin],
							@bitForceChange	[user_passForceChange]	
				END
			ELSE
				BEGIN
					SET		@return_value	= -5
					SELECT	-1
					RETURN						
				END
		END
	ELSE IF @user_passwordUSR = @user_password	
		BEGIN
			SET		@return_value	= 0
			SELECT 	@luser_id		[user_id],
					@lIsSysAdmin	[SysAdmin],
					@bitForceChange	[user_passForceChange]
			--actualizacion para indicar que el usuario se logueo 
			IF (LTRIM(RTRIM(UPPER(@user_nick))) <> UPPER('ERPAdmin')) 
				BEGIN
					UPDATE	tbUser	WITH (ROWLOCK)
						SET		user_login_Mobile	= 'True',
								user_login_MobileCD	= GETDATE(),
								user_login_MobileIP	= @user_login_ip
						WHERE	user_nick		= @user_nick
						AND 	user_password	= @user_password
						AND		@user_boolean	= 'False'
				END	
			ELSE
				BEGIN
					UPDATE	tbUser	WITH (ROWLOCK)
						SET		user_login		= 'True',
								user_login_CD	= GETDATE(),
								user_login_ip	= @user_login_ip,
								user_login_name = @user_login_name
						WHERE	user_nick		= @user_nick
				END
		END
END
GO

-- --------------------------------------------------------------------
-- MOS
-- retorna True si se debe pedir clave.
-- Retorna False si algun perfil del usuario, para la sucursal actual
--		   Tiene permiso para autorizar esa clave.
-- --------------------------------------------------------------------

create PROCEDURE [dbo].[spUser_getNeedAuthorization.UnUsed]
	(
		@comp_id				as int,
		@bra_id					as int,
		@user_id				as int,
		@aut_id					as int,
		@bitNeedAuthorization	as bit output
	)
As

/*
Declare @comp_id		as int,
		@bra_id			as int,
		@user_id		as int,
		@aut_id			as int

Set @comp_id = 1
Set	@bra_id	= 1
Set	@user_id = 1
Set	@aut_id	 = 30
*/

Begin

	Set Nocount On

	--Declare @bitNeedAuthorization as bit
	Set		@bitNeedAuthorization = 'False'

	If not Exists(


		Select *
			From dbo.tbProfileAuthorization					PA

			Inner Join dbo.tbUserCompanyProfile				UCP
				On		UCP.comp_id	= PA.comp_id
					and	UCP.prof_id = PA.prof_id
			
		Where	
				PA.comp_id = @comp_id
			and PA.aut_id	= @aut_id
			and UCP.bra_id	= @bra_id
			and UCP.user_Id = @user_id
				 )

	Begin



		If (Select isnull(aut_disabled ,'False')
				From dbo.tbsysAuthorizations						SA
					Left join dbo.tbAuthorizationsQualification		SAQ
					On		SA.aut_id	= SAQ.aut_id
						and SAQ.comp_id = @comp_id	
						and SAQ.bra_id	= @bra_id
				Where	SA.aut_id	= @aut_id
					
			) = 'False'
			Begin
				Set @bitNeedAuthorization = 'true'
			End
				
	End

	--Select @bitNeedAuthorization [NeedAuthorization]

End

			
			GO


CREATE PROCEDURE [dbo].[spUser_HasEnabledProfiles4SupportRequest]
(
	@comp_id	INT,
	@user_id	INT
)
AS

	BEGIN


		-- -----------------------------------------------------------------------------
		-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
		-- -----------------------------------------------------------------------------
		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW
		-- -----------------------------------------------------------------------------


		SET NOCOUNT ON
		-- -------------------------------------------
		-- TESTING
		-- -------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@user_id	INT
			SELECT
				@comp_id	= 1,
				@user_id	= 45
		*/
		-- -------------------------------------------


		SELECT
			COUNT(*)
			FROM tbUserCompanyProfile				tucp		WITH (NOLOCK)
				INNER JOIN tbProfile				tp			WITH (NOLOCK)
					ON	tp.comp_id	= tucp.comp_id	AND
						tp.prof_id	= tucp.prof_id
			WHERE	tucp.comp_id	= @comp_id		AND
					tucp.[user_id]	= @user_id		AND
					tp.prof_enabled4SupportRequest = 'True'


	END
GO







create  PROCEDURE [dbo].[spUser_insertData]
(
	@user_nick				varchar(50),
	@user_firstname			varchar(200),
	@user_lastname			varchar(200),
	@user_email 			varchar(200),
	@user_password			varchar(100),
	@user_lastcompany		int,
	@user_lastprofile		int,
	@user_lasttheme 		varchar(50),
