CREATE pROCEDURE [dbo].[spUSER_IsEditingPurgeStatus]
AS
BEGIN

	set nocount on
	declare @DeleteTime		as	datetime
	set		@DeleteTime		=	DATEADD(minute, -5, getdate())

	UPDATE tbUser	WITH(ROWLOCK)
		SET
			user_login					= 'false',
			user_login_CD				= GETDATE(),
			user_forceLogout			= 'false', 
			user_login_LastLogoutDate	= GETDATE()
		Where   user_login		= 'True'
			and	user_login_CD	< @DeleteTime
			
	-- Por las dudas
	UPDATE tbuser 	WITH(ROWLOCK)
		SET		user_forceLogout	=	'False' 
		WHERE	user_login			=	'False' AND 
				user_forceLogout	=	'True' 
		
END




GO





