CREATE procedure [dbo].[spUser_LoginFail_GetData]
(

		@comp_id			INT,
		@lang_id			INT,
		@bra_id				INT,
		@prof_id			INT,
		@user_id			INT

)
as
SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@user_id			= 1,
				@prof_id			= 1
*/
-------------------------------------------------------------------------------------------

BEGIN

	SELECT
			' '															[ ],		-- Inicializar Usuario
			' '															[ ],		-- Liberar Usuario
			tu.user_lastname + ', ' + tu.user_firstname					[user_name],
			tu.user_nick												[user_nick],
			tu.user_login_CD											[Date],
			tu.[user_id]												[ID]


			FROM	tbUser									tu				WITH (NOLOCK)

			WHERE	isnull(tu.user_loginFailBlocked,'False')	= 'True'		AND
					isnull(tu.user_Blocked,'False')				= 'False'



END
GO





