------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spUser_LoginFail_UpdateData4FreeUser]
(

	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT, -- user que realiza el desbloqueo.
	@user_id_loginFail		INT  -- usuario que va a ser liberado.


)
as
SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@user_id				INT,
				@prof_id				INT,
				@user_id_loginFail		INT


	SELECT		@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@user_id				= 1,
				@prof_id				= 1,
				@user_id_loginFail		= 3
*/
-------------------------------------------------------------------------------------------

BEGIN

		INSERT INTO tbUser_loginFail
		(
				[user_id],
				ulf_date,
				ulf_IP,
				ulf_loginFailCount,
				ulf_loginBlocked,
				ulf_loginBlockedReleasePending,
				user_id_freeBlock
		)

			SELECT
				@user_id_loginFail,
				GETDATE(),
				tu.user_login_ip,
				tu.user_loginFailCount,
				tu.user_loginFailBlocked,
				'False',
				@user_id
				FROM tbUser							tu		WITH (NOLOCK)
				WHERE	tu.[user_id] = @user_id_loginFail


		UPDATE tbUser
			SET
				user_loginFailCount		=  0,
				user_loginFailIndex		=  0,
				user_loginFailBlocked	=  'False'

			WHERE [user_id] = @user_id_loginFail

END
GO





