--Desc: inicializar usuario bloqueado
------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spUser_LoginFail_UpdateData4InitializeUser]
(

	@comp_id				INT,
	@lang_id				INT,
	@bra_id					INT,
	@prof_id				INT,
	@user_id				INT, -- user que realiza el desbloqueo.
	@user_id_loginFail		INT  -- usuario que va a ser liberado.


)
as
SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id				INT,
				@lang_id				INT,
				@bra_id					INT,
				@user_id				INT,
				@prof_id				INT,
				@user_id_loginFail		INT


	SELECT		@comp_id				= 1,
				@lang_id				= 2,
				@bra_id					= 1,
				@user_id				= 1,
				@prof_id				= 1,
				@user_id_loginFail		= 3
*/
-------------------------------------------------------------------------------------------

BEGIN


	Update	dbo.tbUser
		Set		user_forceLogout	= 'True'
		Where	user_id				= @user_id_loginFail




	INSERT INTO tbsysExceptionLog
	(
		ExcDateTime,
		ExcMessage,
		ExcSource,
		ExcStackTrace,
		ExcTargetSite,
		ExcAddInfo,
		[user_id],
		ExcPage
	)
	VALUES
	(
		GETDATE(),
		'Deslogueo forzado de usuario:' + CONVERT(VARCHAR,@user_id_loginFail),
		NULL,
		NULL,
		NULL,
		NULL,
		NULL,
		NULL
	)



declare
	@message	varchar (300),
	@user_desc	varchar (500),
	@maindesc	varchar	(600),
	@date		datetime

select @message = tov.optval_desc from tbsysOptionsValues tov where tov.lang_id = @lang_id and tov.optval_class = 56 and tov.optval_id = 700
select @user_desc = tu.user_nick + ' ' + tu.user_lastname + ',' + tu.user_firstname from tbUser tu where tu.[user_id] = @user_id_loginFail

select @maindesc = @message + ' ' + @user_desc


SET @date = GETDATE()

exec spSecurityLog_insertData
	@comp_id = @comp_id,
	@bra_id = @bra_id,
	@user_id = @user_id,
	@seclog_obs_1 = @maindesc ,
	@seclog_obs_2 = @user_desc,
	@seclog_obs_3 = null,
	@seclog_obs_4 = null,
	@aut_id = null,
	@sysCode_id = 700,
	@menu_id = null,
	@request_ip = null,
	@request_name = null,
	@aure_isok = null,
	@aure_user_id = null,
	@prof_id = @prof_id,
	@aure_id = null,
	@aure_cd = @date,
	@seclog_id1 = null,
	@seclog_id2 = null,
	@seclog_id3 = null,
	@seclog_pageHTML = null,
	@return_value = null

END

GO





