------------------------------------------------------------------------------------------------------

CREATE procedure [dbo].[spUser_LoginFail4Audit_getDatabyFilters]
(

		@comp_id				INT,
		@lang_id				INT,
		@bra_id					INT,
		@prof_id				INT,
		@user_id				INT,			-- USER QUE desbloqueó
		@user_id_loginFail		INT,			-- user que fúe bloqueado
		@datefrom				DATETIME,
		@dateto					DATETIME

)
as
SET NOCOUNT ON

-------------------------------------------------------------------------------------------
/*
	DECLARE 	@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@user_id			INT,
				@prof_id			INT


	SELECT		@comp_id			= 1,
				@lang_id			= 2,
				@bra_id				= 1,
				@user_id			= 1,
				@prof_id			= 1
*/
-------------------------------------------------------------------------------------------

BEGIN

	SET @dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	SELECT

			tuloginFail.user_lastname + ', ' + tuloginFail.user_firstname					[user_nameloginFail],	-- usuario bloqueado
			tulf.ulf_date																	[date],
			tulf.ulf_IP																		[IP],
			tulf.ulf_loginFailCount															[ulf_loginFailCount],
			tu.user_lastname + ', ' + tu.user_firstname										[name],	-- usuario que desbloqueó
			tulf.ulf_id																		[ID]


			FROM tbUser_loginFail							tulf				WITH (NOLOCK)

			INNER JOIN tbUser								tuloginFail			WITH (NOLOCK)
			ON tuloginFail.[user_id] = tulf.[user_id]

			LEFT JOIN tbUser								tu			WITH (NOLOCK)
			ON tu.[user_id]			 = tulf.user_id_freeBlock

			WHERE	tulf.ulf_date BETWEEN @datefrom AND @dateto													AND
					(@user_id_loginFail			= -1 OR tulf.[user_id]				= @user_id_loginFail)		AND -- usuario bloqueado
					(@user_id					= -1 OR tulf.user_id_freeBlock		= @user_id)						-- usuario que desbloqueó


			ORDER BY tulf.ulf_date desc

END
GO

CREATE PROCEDURE spUser_loginRegister_InsertDataForLogout
(
	@comp_id		INT,
	@user_id		INT,
	@user_ipFrom	NVARCHAR(100)
)
AS
	BEGIN
		SET NOCOUNT ON

		--RECUPERO LOS DATOS DEL USUARIO
		DECLARE
			@user_nick		NVARCHAR(100),
			@user_password	NVARCHAR(100)

		SELECT
			@user_nick		= tu.user_nick,
			@user_password	= tu.user_password
			FROM tbUser tu
			WHERE tu.[user_id] = @user_id


		INSERT INTO tbUser_loginRegister
		(
			[user_id],
			usrl_cd,
			user_nickName,
			user_passWord,
