			usrl_isLogout
		)
		VALUES
		(
			@user_id,
			GETDATE(),
			@user_nick,
			@user_password,
			@user_ipFrom,
			'True'
		)

	END
GO





CREATE PROCEDURE [dbo].[spUser_SaleOrderModel2Print_getModel]
(
		@comp_id	INT,
		@bra_id		INT,
		@prof_id	INT,
		@user_id	INT,
		@df_id		INT
)
AS


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------
	SET NOCOUNT ON


	-- ------------------------------
	-- TESTING
	-- ------------------------------
	/*
	DECLARE
		@comp_id	INT,
		@bra_id		INT,
		@prof_id	INT,
		@user_id	INT,
		@df_id		INT


	SELECT
		@comp_id	= 1,
		@bra_id		= 1,
		@prof_id	= 1,
		@user_id	= 134,
		@df_id		= 161
	*/
	-- ------------------------------
	DECLARE
		@lPrintFormat AS INT
	SET @lPrintFormat = 0


			SELECT TOP 1
				@lPrintFormat = isnull(tusomp.bra_SaleOrder_PrintForm,0)
				FROM tbUser_SaleOrderModel2Print tusomp WITH (NOLOCK)
				WHERE	(tusomp.comp_id		= @comp_id	AND
						tusomp.bra_id		= @bra_id	AND
						tusomp.prof_id		= @prof_id	AND
						tusomp.df_id		= @df_id	AND
						tusomp.[user_id]	= @user_id)
				OR
						(tusomp.comp_id		= @comp_id	AND
						tusomp.bra_id		= @bra_id	AND
						tusomp.prof_id		= @prof_id	AND
						tusomp.df_id        IS NULL		AND
						tusomp.[user_id]	= @user_id)

				OR
						(tusomp.comp_id		= @comp_id	AND
						tusomp.bra_id		= @bra_id	AND
						tusomp.prof_id		= @prof_id	AND
						tusomp.df_id        = @df_id	AND
						tusomp.[user_id]	IS NULL)

				OR
						(tusomp.comp_id		= @comp_id	AND
						tusomp.bra_id		= @bra_id	AND
						tusomp.df_id		IS NULL		AND
						tusomp.[user_id]	IS NULL		AND
						tusomp.prof_id		= @prof_id)
				OR
						(tusomp.comp_id		= @comp_id	AND
						tusomp.df_id		IS NULL		AND
						tusomp.[user_id]	IS NULL		AND
						tusomp.prof_id      IS NULL		AND
						tusomp.bra_id		= @bra_id)

				ORDER BY	tusomp.comp_id,
							tusomp.bra_id,
							ISNULL(tusomp.prof_id,9999999),
							ISNULL(tusomp.[user_id],9999999),
							ISNULL(tusomp.df_id,9999999)




			--SELECT @lPrintFormat

			-- RECUPERO DE LOS DOCUMENTOS SI NO ENCUENTRA NADA

			IF @lPrintFormat = 0
				BEGIN
					SELECT
						@lPrintFormat = isnull(tdf.df_SaleOrder_printForm,0)
					FROM tbDocumentsFile tdf	WITH (NOLOCK)
					WHERE	tdf.comp_id = @comp_id	AND
							tdf.df_id	= @df_id
				END


			-- RECUPERO DE LA SUCURSAL SI NO ENCUENTRA NADA

			IF @lPrintFormat = 0
				BEGIN
					SELECT
						@lPrintFormat = tb.bra_SaleOrder_PrintForm
					FROM tbBranch tb		WITH (NOLOCK)
					WHERE	tb.comp_id	= @comp_id AND
							tb.bra_id	= @bra_id
				END


	SELECT @lPrintFormat

END
GO








