		--	WHERE [user_id]		= @user_id

		-- Se hizo esto debido a que si el usuario dejaba abierta una sesion y el session timeout se pasaba,
		-- el page method igualmente seguia actualizando pero no el boton que saca a un usuario del sistema
		-- Esto se daria cuenta de esa situacion y dejaria de actualizar el user_login, por lo que
		-- el isEditingPurgeStatus pondria en falso

		UPDATE tbUser WITH (ROWLOCK)
			SET
				user_login					= @user_isLogged,
				user_login_cd				= GETDATE()
			WHERE [user_id] = @user_id

	END TRY
	BEGIN CATCH
	END CATCH

end
GO







CREATE  PROCEDURE [dbo].[spUser_updatePassword]
(
	@user_id				int,
	@user_password			varchar(100),
	@return_value			INT OUTPUT
)
as
SET NOCOUNT ON


IF EXISTS (	SELECT 1
				FROM tbUser tu
           		WHERE	tu.[user_id]		= @user_id AND
           				tu.user_password	= @user_password)

	SET @return_value = 0

ELSE
BEGIN

	IF EXISTS (	SELECT 1
					FROM tbUser tu
	           		WHERE tu.[user_id]		<> @user_id AND
	           			  tu.user_password	= @user_password
			   )

		SET @return_value = 2

	ELSE
		BEGIN
			update	tbUser
			set		user_password			= @user_password,
					user_login				= 'false',
					user_passLastChange		= GETDATE(),
					user_passForceChange	= 0,
					user_printClass			= 'True'

			where	user_id					= @user_id

			SET @return_value = 1

		END
END
GO






