create PROCEDURE [dbo].[spUserActive_getCombo]
	@comp_id	AS INT,
	@bra_id		AS INT,
	@prof_id	AS INT,
	@lang_id	AS INT
AS

BEGIN

	set nocount on


	IF @prof_id = -1
		BEGIN
			select		user_id										[id],
						user_lastname + ', ' + user_firstname		[desc]

				from		dbo.tbUser WITH (NOLOCK)
				WHERE user_Blocked = 'False'
				Order By	user_lastname,user_firstname

		END
	ELSE
		BEGIN
			select		DISTINCT
						tu.user_id										[id],
						tu.user_lastname + ', ' + tu.user_firstname		[desc]
				INTO #tmpUser
				from		dbo.tbUser tu					WITH (NOLOCK)
				LEFT JOIN tbUserCompanyProfile tucp		WITH (NOLOCK)
					ON	tucp.comp_id	= @comp_id AND
						tucp.[user_id]	= tu.[user_id]
				WHERE (tucp.comp_id IS NOT NULL
						OR
					  tu.user_nick LIKE 'ERP%')
					  AND  tu.user_Blocked = 'False'

				SELECT *
					FROM #tmpUser
					ORDER BY [desc]

		END


END














GO






