CREATE  PROCEDURE [dbo].[spUserCompanyProfile_deleteData]
(
	@comp_id		int,
	@bra_id			int,
	@user_id		int,
	@prof_id		INT,
	@return_value	int OUTPUT
)
AS

BEGIN



	set nocount on


-- -------------------------------------------------------
-- Testing
-- -------------------------------------------------------
	/*
	DECLARE 	@comp_id		int,
		@bra_id			int,
		@user_id		int,
		@prof_id		INT,
		@return_value	bit
	SELECT 	@comp_id		=1,
		@bra_id			=1,
		@user_id		=2,
		@prof_id		=1
	*/
-- -------------------------------------------------------


	--verificar que exista al menos un usuario diferente del gbpadmin asignado al perfil administrador
	--para poder realizar las desasignaciones solicitadas


	-- El perfil a Borrar es de Administrador?
	DECLARE @bitIsAdminProfile AS BIT
	SELECT @bitIsAdminProfile = IsNull(tp.prof_isSA,'False')
		FROM tbProfile tp
		WHERE tp.prof_id = @prof_id

	-- Hay algun usuario en esta compañia que sea administrador, este activo y no sea GBPAdmin en algun perfil?
	DECLARE @intAdministratorUsers AS int
	SELECT  @intAdministratorUsers =	COUNT(1)
		FROM tbUserCompanyProfile tucp
		INNER JOIN tbProfile tp
			ON	tp.comp_id = tucp.comp_id	AND
				tp.prof_id = tucp.prof_id
		INNER JOIN tbuser	tu
			ON tu.[user_id] = tucp.[user_id]
		WHERE	tucp.comp_id	= @comp_id	AND
				tucp.[user_id]	<> 1		AND
				tp.prof_isSA	= 'True'
				AND IsNull(tu.user_Blocked,'False') = 'False'
				AND tu.[user_id] <> @user_id

	-- Cantidad de Perfiles asignados al usuario que se quiere desasignar
	DECLARE @intProfilesAsigned2user AS INT
	SELECT @intProfilesAsigned2user = COUNT(*)
		FROM tbUserCompanyProfile tucp
		INNER JOIN tbBranch tb
			ON tb.bra_id = tucp.bra_id
		WHERE	tucp.comp_id	= @comp_id AND
				tucp.[user_id]	= @user_id AND
				IsNull(tb.bra_disabled,'False') = 'False'


	IF	(		@bitIsAdminProfile = 'False'								OR
			(
				@bitIsAdminProfile = 'True' AND @intAdministratorUsers > 1
			)
		)																	AND
			@intProfilesAsigned2user > 1
		BEGIN
			SET @return_value = 1

			Delete	dbo.tbUserCompanyProfile
			where	comp_id			=		@comp_id
			and		bra_id			=		@bra_id
			and		user_id			=		@user_id
			and		prof_id			=		@prof_id
		END
	ELSE
		SET @return_value = 0

	RETURN














-- Esto es pura MIERDA
--
--
--	IF EXISTS (SELECT 1 FROM dbo.tbProfile tp
--				WHERE	tp.comp_id		=	@comp_id
--				AND		tp.prof_id		=	@prof_id
--				AND		tp.prof_isSA	=	'True')
--		BEGIN
--			--el perfil seleccionado es system administrator
--
--			if exists (SELECT	DISTINCT 1
--						FROM	dbo.tbUserCompanyProfile ucp
--						INNER JOIN tbBranch tb
--							ON tb.bra_id = ucp.bra_id
--						where	ucp.comp_id			=		@comp_id
--						and		ucp.bra_id			=		@bra_id
--						AND		isNull(tb.bra_disabled,'False') = 'False'
--						and		ucp.user_id			<>		@user_id
--						AND		ucp.USER_ID			<>		1
--						and		ucp.prof_id			=		@prof_id)
--																		AND
--				(	SELECT COUNT(*)
--				 		FROM	dbo.tbUserCompanyProfile ucp
--							INNER JOIN tbBranch tb
--								ON tb.bra_id = ucp.bra_id
--							where	ucp.comp_id			=		@comp_id
--							and		ucp.user_id			=		@user_id
--				)	> 1
--				BEGIN
--					--existe al menos un usuario diferente del seleccionado y diferente de gbpadmin
--					--asignado al perfil system administrator por lo tanto se puede desasignar el
--					--perfil del usuario
--					SET @return_value = 1
--
--					Delete	dbo.tbUserCompanyProfile
--					where	comp_id			=		@comp_id
--					and		bra_id			=		@bra_id
--					and		user_id			=		@user_id
--					and		prof_id			=		@prof_id
--
--				END
--			ELSE
--				BEGIN
--					--no existe un usuario diferente del seleccionado y diferente de gbpadmin
--					--asignado al perfil system administrator por lo tanto NO se puede desasignar el
--					--perfil del usuario
--					SET @return_value = 0
--				END
--
--		END
--	ELSE
--		BEGIN
--			--el perfil seleccionado no es system administrator	por lo tantose pueden realizar las
--			--desasignaciones que se requieran
--			SET @return_value = 1
--
--			Delete	dbo.tbUserCompanyProfile
--			where	comp_id			=		@comp_id
--			and		bra_id			=		@bra_id
--			and		user_id			=		@user_id
--			and		prof_id			=		@prof_id
--
--		END
--


END
GO







CREATE  PROCEDURE [dbo].[spUserCompanyProfile_getComboBranch]
(
	@user_id				integer,
	@comp_id				integer
)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	declare @user_id	integer
	select	@user_id = 1
	declare @comp_id	integer
	select	@comp_id = 1
	declare @qty_company	integer
	select	@qty_company	= 10
	*/
	-- ------------------------------------------------------

	select	DISTINCT
			b.bra_id		[id],
			b.bra_desc		[desc]

		from	[tbUserCompanyProfile]		a		WITH (NOLOCK)

			inner join [tbBranch]		b			WITH (NOLOCK)
			on	b.comp_id		= a.comp_id	AND
				b.bra_id		= a.bra_id
			INNER JOIN tbProfile tp					WITH (NOLOCK)
				ON		tp.comp_id = @comp_id
					AND tp.prof_id = a.prof_id


		where	a.user_id			= @user_id
		and		a.comp_id			= @comp_id
		AND		b.bra_disabled		= 0
		AND		tp.prof_notInDDL	= 'False'
		AND		tp.prof_disabled	= 'False'	 --- MOS 01-2017

	ORDER BY b.bra_desc  -- b.bra_id



END
GO








