CREATE PROCEDURE [dbo].[spUserCompanyProfile_getFreeProfiles]
(
	@comp_id			int,
	@user_id			integer,
	@bra_id				integer
)
as

set nocount on
/*
declare 	@comp_id			int,
	        @user_id			integer,
			@bra_id				integer

select		@comp_id			= 1,
			@user_id			= 3,
			@bra_id				= 1
*/

select	prof_id			[id],
		prof_desc		[desc]

from 	tbProfile

where	comp_id		=	@comp_id
and prof_id not in (select	distinct
