					and		a.bra_id			= @bra_id)
order by prof_desc


GO




CREATE  PROCEDURE [dbo].[spUserCompanyProfile_getProfilesDisabledByTime]
(

	@comp_id			INT,
	@user_id			INT,
	@bra_id				INT,
	@prof_id			INT
)
as

BEGIN



	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @intHour		AS INT
	SET		@intHour		= DATEPART(hour,GETDATE())
	DECLARE @intMinute		AS INT
	SET		@intMinute		= DATEPART(minute,GETDATE())

	SET DATEFIRST 7 -- Dom,ingo x Defecto
	DECLARE @intDOW AS INT
	SET		@intDOW = datepart(dw,getdate())

	-- Modificar tambien en [spUserCompanyProfile_getComboProfileOnlyAllowed]
	select	distinct
			b.prof_id	[id],
			b.prof_desc	[desc]

	from	[tbUserCompanyProfile]		a						WITH (NOLOCK)

			inner join [tbProfile]		b						WITH (NOLOCK)
			on
				b.comp_id		= a.comp_id	AND
				b.prof_id		= a.prof_id

	where	a.user_id			= @user_id				AND
			a.comp_id			= @comp_id				AND
			a.bra_id			= @bra_id				AND
			a.prof_id			= @prof_id				AND
			b.prof_notInDDL		= 'False'				AND
			b.prof_disabled		= 'False'				AND		 --- MOS 01-2017

			EXISTS (
							-- Modificar tambien en [spUserCompanyProfile_getComboProfileOnlyAllowed]
							SELECT TOP 1  1
								FROM tbProfileDisabledByTime td		WITH (NOLOCK)
								WHERE	td.comp_id	 = @comp_id																AND
									  ( td.bra_id	 IS NULL		OR  td.bra_id	  = @bra_id							)	AND
									  (	td.prof_id	 = a.prof_id	OR (td.prof_id    IS NULL AND b.prof_isSA <> 'True'))	AND
									  ( td.[user_id] IS NULL OR td.[user_id] = @user_id )									AND
										CASE
											WHEN td.pdt_onSunday		= 'True' AND @intDOW = 1  THEN 1
											WHEN td.pdt_onMonday		= 'True' AND @intDOW = 2  THEN 1
											WHEN td.pdt_onTuesday		= 'True' AND @intDOW = 3  THEN 1
											WHEN td.pdt_onWednesday		= 'True' AND @intDOW = 4  THEN 1
											WHEN td.pdt_onThursday		= 'True' AND @intDOW = 5  THEN 1
											WHEN td.pdt_onFriday		= 'True' AND @intDOW = 6  THEN 1
											WHEN td.pdt_onSaturday		= 'True' AND @intDOW = 7  THEN 1
											ELSE 0
										END = 1														AND
										CASE
											WHEN	@intHour = td.pdt_hour_from AND	@intMinute >=  td.pdt_minute_from	THEN 1
											WHEN	@intHour > td.pdt_hour_from											THEN 1
											ELSE	0
										END	= 1														AND

										CASE
											WHEN	@intHour = td.pdt_hour_to	AND	@intMinute <=  td.pdt_minute_to	THEN 1
											WHEN	@intHour < td.pdt_hour_to										THEN 1
											ELSE	0
										END	= 1														AND
										td.pdt_disabled	= 'False'
						)

	ORDER BY b.prof_desc


END
GO












