CREATE PROCEDURE spUserEntryRegistry_getUserStatus
(
	@comp_id	INT,
	@user_id	INT,
	@bra_id		INT
)
AS
	SET NOCOUNT	ON

		BEGIN

			SELECT
				TOP 1
					tuer.[user_id],
					tuer.uer_isExit
			FROM tbUserEntryRegistry tuer
			WHERE	tuer.comp_id	= @comp_id AND
					tuer.[user_id]	= @user_id AND
					tuer.bra_id		= @bra_id

			ORDER BY tuer.uer_cd DESC

		END
GO



