CREATE PROCEDURE spUserEntryRegistry_UserIsValid
(
	@comp_id		INT,
	@user_nick		VARCHAR(50),
	@user_password	VARCHAR(100)
)
AS
	SET NOCOUNT ON

		BEGIN
			DECLARE
				@IsValid	BIT,
				@user_id	INT
			SET @IsValid	= 'False'
			SET @user_id	= 0

			--SI ESTA BIEN INGRESADO, TIRA TRUE, SINO FALSE Y PONEMOS MENSAJE
			IF EXISTS (SELECT
							1
						FROM tbUser tu
						WHERE	tu.user_nick		= @user_nick	AND
								tu.user_password	= @user_password)

					BEGIN

						SELECT @user_id = tu.[user_id]  FROM tbUser tu WHERE tu.user_nick = @user_nick AND tu.user_password = @user_password
						SET @IsValid = 'True'

					END



			ELSE

					SET @IsValid = 'False'


			SELECT @IsValid, @user_id

		END

GO






CREATE PROCEDURE [dbo].[spUserGetDataByBarCode]
(

	@comp_id					INT,
	@UserBarCode				NVARCHAR(50)

)
AS

BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------------
	-- Testing
	-- ------------------------------------------------------
	/*
	DECLARE	  	@comp_id					INT,
				@UserBarCode				NVARCHAR(50)


	SELECT		@comp_id				= 1,
				@UserBarCode		    = 'LACONCHADETUMADRE'

	*/
	-- ------------------------------------------------------


	DECLARE	@lUser_Id		INT
	DECLARE @strUserName	AS NVARCHAR(2000)
	SET @strUserName = ''


	SET @lUser_Id = -1



	IF EXISTS (SELECT 1 FROM tbUser tu
			   WHERE	tu.user_barCode = @UserBarCode AND
						tu.user_barCode IS NOT NULL	AND
						tu.user_barCode <> '')



					BEGIN

						SELECT @lUser_Id = tu.[user_id]
						  FROM tbUser tu					WITH(NOLOCK)
						WHERE tu.user_barCode = @UserBarCode


					END



	IF @lUser_Id > 0
		BEGIN
			SELECT @strUserName = tu.user_lastname + ', ' + tu.user_firstname
				FROM tbUser tu
				WHERE tu.[user_id] = @lUser_Id
		END


	SELECT @lUser_Id [user_id], @strUserName [user_Name]




END
GO




