ORDER BY tu.user_login_LastLoginDate
GO






CREATE PROCEDURE [dbo].[spUsers_UpdateLastData]
(
	@user_id			AS INT,
	@UserLogOUT			AS BIT,
	@user_nickName		AS NVARCHAR(100),
	@user_passWord		AS NVARCHAR(100),
	@user_ipFrom		AS NVARCHAR(100)
	)

AS
BEGIN

	SET NOCOUNT ON

	IF @UserLogOUT = 'True'
		BEGIN
			UPDATE tbuser
				SET user_login_LastLogoutDate = GETDATE()
				WHERE [user_id]  = @user_id
		END
	ELSE
		BEGIN
			UPDATE tbuser
				SET user_login_LastLogInDate = GETDATE()
				WHERE [user_id]  = @user_id

				INSERT INTO tbUser_loginRegister
				(
					-- usrl_id -- this column value is auto-generated,
					[user_id],
					usrl_cd,
					user_nickName,
					user_passWord,
					user_ipFrom
				)
				VALUES
				(
					@user_id,
					GETDATE(),
					@user_nickName,
					@user_passWord,
					@user_ipFrom
				)

		END


END
GO




