CREATE PROCEDURE [dbo].[spWebGrid_EmmitedChecks]
(
	@comp_id		INT,
	@lang_id		INT,
	@user_id        INT,
	@bra_id			int,
	@header_id		INT, --12/13/...17
	@detail_id		INT,
	@country_id		INT,
	@state_id		INT,
	@date_from		DATETIME,
	@date_to		DATETIME
)
AS
SET NOCOUNT ON
/*
DECLARE		@comp_id		INT,
			@lang_id		INT,
			@user_id        INT,
			@bra_id			int,
			@country_id		INT,
			@state_id		INT,
			@date_from		DATETIME,
			@date_to		DATETIME,
			@header_id      INT,
			@detail_id		INT


SELECT 		@comp_id		= 1,
			@lang_id		= 2,
			@user_id        = 1,
			@bra_id         =-1,
			@country_id		=-1,
			@state_id		=-1,
			@date_from		='01-01-2000',
			@date_to		='31-12-2010',
			@header_id      = 17,
			@detail_id		= 3


DROP TABLE #tmpData

*/
DECLARE @desc VARCHAR(200)

SELECT @desc = (SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
WHERE  tut.utexts_id=1000)

DECLARE @curr_id INT, @curr_symbol VARCHAR(4)

SELECT  @curr_id = tb.curr_id, @curr_symbol = tc.curr_symbol
FROM tbBranch tb INNER JOIN tbsysCurrency tc ON tc.curr_id = tb.curr_id
WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id






SELECT		cu.curr_desc,
			case when @header_id  IN (12,13,14) then tec.ec_EmissionDate
												ELSE tec.ec_PayDate END  [ec_EmissionDate],
			tec.ec_Total,
			tba.ba_desc

INTO		#tmpData

FROM 		tbEmmitedChecks											tec

			INNER JOIN tbBankingAccounts							tba
			ON  tba.comp_id				= tec.comp_id
			AND tba.ba_id				= tec.ba_id

			INNER JOIN dbo.tbsysCurrency							cu
			ON cu.curr_id				=	tec.curr_id


WHERE		tec.comp_id			= @comp_id

and			((@header_id  IN (12,15) and tec.ec_isPaid		=	'false' and	tec.ec_isCancelled	=	'false') OR
			 (@header_id  IN (13,16) and tec.ec_isPaid		=	'true' and	tec.ec_isCancelled	=	'false') OR
			 (@header_id  IN (14,17) and tec.ec_isPaid		=	'false' and	tec.ec_isCancelled	=	'true'))

AND			((@header_id  IN (12,13,14) and tec.ec_EmissionDate	BETWEEN	@date_from AND @date_to) or
			 (@header_id  IN (15,16,17) and tec.ec_PayDate	    BETWEEN	@date_from AND @date_to))

AND			tec.ec_isDocument	=	'false'

AND         (@country_id =-1 OR tec.ec_id = @country_id)




--SELECT * FROM #tmpData

----------------------------------	           ///////////               ---------------------------------------------------------


IF @detail_id = 1 --spWebGrid_EmmitedChecks_BYMD

SELECT 		ISNULL(td.ba_desc,@desc)									[ba_desc],
			YEAR (td.ec_EmissionDate)					[year],
			tov.optval_desc								[month]	,
			DAY (td.ec_EmissionDate)					[day],
			SUM (td.ec_Total)	 [tec_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ec_EmissionDate)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON	sem.lang_id				= @lang_id
			AND [sem].optval_class		= 70
			AND [sem].optval_id			= 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON	[card].lang_id			= @lang_id
			AND [card].optval_class		= 71
			AND [card].optval_id		= (convert(int,month(td.ec_EmissionDate)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON	tri.lang_id				= @lang_id
			AND [tri].optval_class		= 70
			AND [tri].optval_id			= 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON	[card2].lang_id			= @lang_id
			AND [card2].optval_class	= 71
			AND [card2].optval_id		= ABS(DATEPART(quarter, td.ec_EmissionDate)%2-2)


Group By	td.ba_desc,
			YEAR (td.ec_EmissionDate),
		    tov.optval_desc,
			DAY (td.ec_EmissionDate)

Order By	td.ba_desc,
			YEAR (td.ec_EmissionDate),
		    tov.optval_desc,
			DAY (td.ec_EmissionDate)



----------------------------------	           ///////////               ---------------------------------------------------------


IF @detail_id = 2 --spWebGrid_EmmitedChecks_BYQMD



SELECT 		ISNULL(td.ba_desc,@desc)									[ba_desc],
			YEAR (td.ec_EmissionDate)					[year],
			[card2].optval_desc + ' ' + tri.optval_desc [Quarter] ,
			tov.optval_desc								[month]	,
			DAY (td.ec_EmissionDate)					[day],
			SUM (td.ec_Total)	 [tec_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ec_EmissionDate)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON	sem.lang_id				= @lang_id
			AND [sem].optval_class		= 70
			AND [sem].optval_id			= 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON	[card].lang_id			= @lang_id
			AND [card].optval_class		= 71
			AND [card].optval_id		= (convert(int,month(td.ec_EmissionDate)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON	tri.lang_id				= @lang_id
			AND [tri].optval_class		= 70
			AND [tri].optval_id			= 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON	[card2].lang_id			= @lang_id
			AND [card2].optval_class	= 71
			AND [card2].optval_id		= ABS(DATEPART(quarter, td.ec_EmissionDate)%2-2)

Group By	td.ba_desc,
			YEAR (td.ec_EmissionDate),
			[card2].optval_desc,
		    tri.optval_desc,
		    tov.optval_desc,
			DAY (td.ec_EmissionDate)

Order By	td.ba_desc,
			YEAR (td.ec_EmissionDate),
			[card2].optval_desc,
		    tri.optval_desc,
		    tov.optval_desc,
			DAY (td.ec_EmissionDate)

----------------------------------	           ///////////               ---------------------------------------------------------


IF @detail_id = 3 --spWebGrid_EmmitedChecks_BYSD


SELECT 		ISNULL(td.ba_desc,@desc)									[ba_desc],
			YEAR (td.ec_EmissionDate)					[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			DAY (td.ec_EmissionDate)					[day],
			SUM (td.ec_Total)	 [tec_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ec_EmissionDate)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON	sem.lang_id				= @lang_id
			AND [sem].optval_class		= 70
			AND [sem].optval_id			= 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON	[card].lang_id			= @lang_id
			AND [card].optval_class		= 71
			AND [card].optval_id		= (convert(int,month(td.ec_EmissionDate)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON	tri.lang_id				= @lang_id
			AND [tri].optval_class		= 70
			AND [tri].optval_id			= 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON	[card2].lang_id			= @lang_id
			AND [card2].optval_class	= 71
			AND [card2].optval_id		= ABS(DATEPART(quarter, td.ec_EmissionDate)%2-2)


Group By	td.ba_desc,
			YEAR (td.ec_EmissionDate),
			sem.optval_desc,
			[card].optval_desc,
			DAY (td.ec_EmissionDate)

Order By	td.ba_desc,
			YEAR (td.ec_EmissionDate),
			sem.optval_desc,
			[card].optval_desc,
			DAY (td.ec_EmissionDate)



----------------------------------	           ///////////               ---------------------------------------------------------


IF @detail_id = 4 --spWebGrid_EmmitedChecks_CYMD

SELECT 		ISNULL(td.curr_desc,@desc)					[curr_desc],
			YEAR (td.ec_EmissionDate)					[year],
			tov.optval_desc								[month]	,
			DAY (td.ec_EmissionDate)					[day],
			SUM(td.ec_Total)							[tec_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ec_EmissionDate)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON	sem.lang_id				= @lang_id
			AND [sem].optval_class		= 70
			AND [sem].optval_id			= 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON	[card].lang_id			= @lang_id
