			ON	tri.lang_id				= @lang_id
			AND [tri].optval_class		= 70
			AND [tri].optval_id			= 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON	[card2].lang_id			= @lang_id
			AND [card2].optval_class	= 71
			AND [card2].optval_id		= ABS(DATEPART(quarter, td.ec_EmissionDate)%2-2)


Group By	td.curr_desc,
			YEAR (td.ec_EmissionDate),
			[card2].optval_desc ,
			tri.optval_desc,
			tov.optval_desc,
			DAY (td.ec_EmissionDate)

Order By	td.curr_desc,
			YEAR (td.ec_EmissionDate),
			[card2].optval_desc ,
			tri.optval_desc,
			tov.optval_desc,
			DAY (td.ec_EmissionDate)


----------------------------------	           ///////////               ---------------------------------------------------------


IF @detail_id = 6 --spWebGrid_EmmitedChecks_CYSMD

SELECT 		ISNULL(td.curr_desc,@desc)					[curr_desc],
			YEAR (td.ec_EmissionDate)					[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			tov.optval_desc								[month]	,
			DAY (td.ec_EmissionDate)					[day],

			SUM(td.ec_Total)	 [tec_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ec_EmissionDate)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON	sem.lang_id				= @lang_id
			AND [sem].optval_class		= 70
			AND [sem].optval_id			= 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON	[card].lang_id			= @lang_id
			AND [card].optval_class		= 71
			AND [card].optval_id		= (convert(int,month(td.ec_EmissionDate)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON	tri.lang_id				= @lang_id
			AND [tri].optval_class		= 70
			AND [tri].optval_id			= 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON	[card2].lang_id			= @lang_id
			AND [card2].optval_class	= 71
			AND [card2].optval_id		= ABS(DATEPART(quarter, td.ec_EmissionDate)%2-2)


Group By	td.curr_desc,
			YEAR (td.ec_EmissionDate),
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc,
			tov.optval_desc,
			DAY (td.ec_EmissionDate)

Order By	td.curr_desc,
			YEAR (td.ec_EmissionDate),
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc,
			tov.optval_desc,
			DAY (td.ec_EmissionDate)



SELECT tut.utexts_desc + ' ' + @curr_symbol
FROM tbsysUniqueTexts tut
WHERE tut.lang_id = @lang_id AND tut.utexts_id = 224022





GO







CREATE PROCEDURE [dbo].[spWebGrid_Purchase_Branch]
(
	@comp_id		INT,
	@lang_id		INT,
	@user_id        INT,
	@bra_id			int,
	@header_id		INT,
	@detail_id		INT,
	@country_id		INT,
	@state_id		INT,
	@date_from		DATETIME,
	@date_to		DATETIME


)
AS
SET NOCOUNT ON

/*

DECLARE		@comp_id		INT,
			@lang_id		INT,
			@user_id        INT,
			@bra_id			int,
			@country_id		INT,
			@state_id		INT,
			@date_from		DATETIME,
			@date_to		DATETIME,
			@detail_id		INT


SELECT 		@comp_id		= 1,
			@lang_id		= 2,
			@user_id        = 1,
			@bra_id         = 1,
			@country_id		=-1,
			@state_id		=-1,
			@date_from		='01-01-2000',
			@date_to		='31-12-2010',
			@detail_id		= 1



DROP TABLE #tmpData
*/

SELECT	@date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
DECLARE @desc		VARCHAR(200)

DECLARE @curr_id INT, @curr_symbol VARCHAR(4)

SELECT  @curr_id = tb.curr_id, @curr_symbol = tc.curr_symbol
FROM tbBranch tb INNER JOIN tbsysCurrency tc ON tc.curr_id = tb.curr_id
WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id




SELECT	tct.ct_date,
		dbo.fnGetExchange(@comp_id,  tct.ct_total, tct.curr_id_transaction, @curr_id, 0, 0, 'False') [ct_total],
		vctfp.sd_isCredit,
		tb.bra_desc


INTO	#tmpData

FROM	tbCommercialTransactions							tct



	INNER JOIN vwCommercialTransactions_forPurchase			vctfp
	ON	vctfp.comp_id			=	tct.comp_id
	AND vctfp.bra_id			=	tct.bra_id
	AND vctfp.ct_transaction	=	tct.ct_transaction


	INNER JOIN tbBranch										tb
	ON	tb.comp_id				=	tct.comp_id
	AND tb.bra_id				=	tct.bra_id

	INNER JOIN tbUsers4BranchFilter							vubf
	ON	vubf.comp_id			=	tct.comp_id
	AND vubf.bra_id				=	tct.bra_id
	AND vubf.[user_id]			=	@user_id


WHERE		tct.comp_id		= @comp_id
AND         (@bra_id        = -1 OR tb.bra_id      = @bra_id)
AND			tct.ct_date		BETWEEN	@date_from AND @date_to
AND         (@country_id =-1 OR tb.bra_id = @country_id)



----------------------------------	           ///////////               ---------------------------------------------------------


IF @detail_id = 1 --spWebGrid_Purchase_Branch_BYSQ

SELECT 		ISNULL(td.bra_desc,@desc)									[bra_desc],
			YEAR (td.ct_date)							[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			[card2].optval_desc + ' ' + tri.optval_desc [Quarter],

			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON	sem.lang_id				= @lang_id
			AND [sem].optval_class		= 70
			AND [sem].optval_id			= 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON	[card].lang_id			= @lang_id
			AND [card].optval_class		= 71
			AND [card].optval_id		= (convert(int,month(td.ct_date)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON	tri.lang_id				= @lang_id
			AND [tri].optval_class		= 70
			AND [tri].optval_id			= 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON	[card2].lang_id			= @lang_id
			AND [card2].optval_class	= 71
			AND [card2].optval_id		= ABS(DATEPART(quarter,td.ct_date)%2-2)



Group By	td.bra_desc	,
			YEAR (td.ct_date),
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc

Order By	td.bra_desc	,
			YEAR (td.ct_date),
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc

----------------------------------	           ///////////               ---------------------------------------------------------




IF @detail_id = 2 --spWebGrid_Purchase_Branch_BYSQM


SELECT 		ISNULL(td.bra_desc,@desc)								[bra_desc],
			YEAR (td.ct_date)							[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			[card2].optval_desc + ' ' + tri.optval_desc [Quarter],
			tov.optval_desc								[month]		,

			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON	sem.lang_id				= @lang_id
			AND [sem].optval_class		= 70
			AND [sem].optval_id			= 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON	[card].lang_id			= @lang_id
			AND [card].optval_class		= 71
			AND [card].optval_id		= (convert(int,month(td.ct_date)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON	tri.lang_id				= @lang_id
			AND [tri].optval_class		= 70
			AND [tri].optval_id			= 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON	[card2].lang_id			= @lang_id
			AND [card2].optval_class	= 71
			AND [card2].optval_id		= ABS(DATEPART(quarter, td.ct_date)%2-2)


Group By	td.bra_desc	,
			YEAR (td.ct_date),
			tov.optval_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc

Order By	td.bra_desc	,
			YEAR (td.ct_date),
			tov.optval_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc

----------------------------------	           ///////////               ---------------------------------------------------------


IF @detail_id = 3 --spWebGrid_Purchase_Branch_YB


SELECT 		YEAR (td.ct_date)							[year],
			ISNULL(td.bra_desc,@desc)								[bra_desc],
			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

Group By	YEAR (td.ct_date),
			td.bra_desc


Order By	YEAR (td.ct_date),
			td.bra_desc

----------------------------------	           ///////////               ---------------------------------------------------------


