CREATE PROCEDURE [dbo].[spWebGrid_Purchase_CountryState]
(
	@comp_id		INT,
	@lang_id		INT,
	@user_id        INT,
	@bra_id			int,
	@header_id		INT,
	@detail_id		INT,
	@country_id		INT,
	@state_id		INT,
	@date_from		DATETIME,
	@date_to		DATETIME
)
AS
SET NOCOUNT ON

/*
DECLARE		@comp_id		INT,
			@lang_id		INT,
			@country_id		INT,
			@state_id		INT,
			@date_from		DATETIME,
			@date_to		DATETIME,
			@user_id		INT,
			@bra_id			INT,
			@detail_id		INT

SELECT 		@comp_id		=1,
			@lang_id		=2,
			@country_id		=-1,
			@state_id		=-1,
			@date_from		='01-01-2000',
			@date_to		='31-12-2010',
			@user_id		= 1,
			@bra_id         = 1,
			@detail_id		= 1

DROP TABLE #tmpData

*/

SELECT	@date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
DECLARE @desc		VARCHAR(200)

DECLARE @curr_id INT, @curr_symbol VARCHAR(4)

SELECT  @curr_id = tb.curr_id, @curr_symbol = tc.curr_symbol
FROM tbBranch tb INNER JOIN tbsysCurrency tc ON tc.curr_id = tb.curr_id
WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id

SELECT	tct.ct_date,
		dbo.fnGetExchange(@comp_id,  tct.ct_total, tct.curr_id_transaction, @curr_id, 0, 0, 'False') [ct_total],
		vctfs.sd_isCredit,
		tc2.country_desc,
		ts.state_desc

INTO	#tmpData

FROM	tbCommercialTransactions							tct

		INNER JOIN vwCommercialTransactions_forPurchase  	vctfs
		ON	vctfs.comp_id			=	tct.comp_id
		AND vctfs.bra_id			=	tct.bra_id
		AND vctfs.ct_transaction	=	tct.ct_transaction

		INNER JOIN tbSupplier								tc
		ON tc.comp_id				= tct.comp_id
		AND tc.supp_id				 = tct.supp_id

		INNER JOIN tbsysCountry								tc2
		ON	tc2.country_id			=	tc.country_id

		INNER JOIN tbsysState								ts
		ON	ts.country_id			=	tc.country_id
		AND ts.state_id				=	tc.state_id

		INNER JOIN tbUsers4BranchFilter						vubf
		ON	vubf.comp_id			=	tct.comp_id
		AND	vubf.bra_id				=	tct.bra_id
		AND	vubf.[user_id]			=	@user_id


WHERE	tct.comp_id		= @comp_id
AND		(@country_id	= -1 OR	tc2.country_id	= @country_id)
AND		(@state_id		= -1 OR ts.state_id		= @state_id)
AND		tct.ct_date		BETWEEN	@date_from AND @date_to



--SELECT * FROM #tmpData

