CREATE PROCEDURE [dbo].[spWebGrid_Sales_Branch]
(
	@comp_id		INT,
	@lang_id		INT,
	@user_id        INT,
	@bra_id			int,
	@header_id		INT,
	@detail_id		INT,
	@country_id		INT,
	@state_id		INT,
	@date_from		DATETIME,
	@date_to		DATETIME


)
AS
SET NOCOUNT ON
/*
DECLARE		@comp_id		INT,
			@lang_id		INT,
			@user_id        INT,
			@bra_id			int,
			@country_id		INT,
			@state_id		INT,
			@date_from		DATETIME,
			@date_to		DATETIME,
			@detail_id		INT


SELECT 		@comp_id		= 1,
			@lang_id		= 2,
			@user_id        = 1,
			@bra_id         = 1,
			@country_id		=-1,
			@state_id		=-1,
			@date_from		='01-01-2000',
			@date_to		='31-12-2010',
			@detail_id		= 1

DROP TABLE #tmpData

*/



SELECT	@date_to	= dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
DECLARE @desc		VARCHAR(200)

SELECT @desc = (SELECT tut.utexts_desc FROM tbsysUniqueTexts tut
WHERE  tut.utexts_id = 1000)


DECLARE @curr_id INT, @curr_symbol VARCHAR(4)
SELECT  @curr_id = tb.curr_id, @curr_symbol = tc.curr_symbol
FROM tbBranch tb INNER JOIN tbsysCurrency tc ON tc.curr_id = tb.curr_id
WHERE tb.comp_id = @comp_id AND tb.bra_id = @bra_id


SELECT	tct.ct_date,
		dbo.fnGetExchange(@comp_id,  tct.ct_total, tct.curr_id_transaction, @curr_id, 0, 0, 'False') [ct_total],
		vctfs.sd_isCredit,
		tb.bra_desc


INTO	#tmpData

FROM	tbCommercialTransactions							tct

		INNER JOIN vwCommercialTransactions_forSalesStats 	vctfs
		ON	vctfs.comp_id			=	tct.comp_id
		AND vctfs.bra_id			=	tct.bra_id
		AND vctfs.ct_transaction	=	tct.ct_transaction

		INNER JOIN tbBranch										tb
		ON tb.comp_id				=	tct.comp_id
		AND tb.bra_id				=	tct.bra_id

		INNER JOIN vwUsers4BranchFilter						vubf
		ON	vubf.comp_id			=	tct.comp_id
		AND	vubf.bra_id				=	tct.bra_id
		AND	vubf.[user_id]			=	@user_id


WHERE		tct.comp_id		= @comp_id
AND         (@bra_id        = -1 OR tb.bra_id      = @bra_id)
AND			tct.ct_date		BETWEEN	@date_from AND @date_to
AND         (@country_id =-1 OR tb.bra_id = @country_id)


--SELECT * FROM #tmpData

----------------------------------	           ///////////               ---------------------------------------------------------




IF @detail_id = 1 --spWebGrid_Sales_Branch_BYSQ


SELECT 		ISNULL(td.bra_desc,@desc)										[bra_desc],
			YEAR (td.ct_date)												[year],
			[card].optval_desc + ' ' + sem.optval_desc						[half_year],
			[card2].optval_desc + ' ' + tri.optval_desc						[Quarter],

			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
					CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * 1)
				ELSE
					CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
				END)														[ct_total]


FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON sem.lang_id = @lang_id
			AND [sem].optval_class = 70
			AND [sem].optval_id = 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON [card].lang_id = @lang_id
			AND [card].optval_class = 71
			AND [card].optval_id = (convert(int,month(td.ct_date)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON tri.lang_id = @lang_id
			AND [tri].optval_class = 70
			AND [tri].optval_id = 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON [card2].lang_id = @lang_id
			AND [card2].optval_class = 71
			AND [card2].optval_id = ABS(DATEPART(quarter, td.ct_date)%2-2)



Group By	td.bra_desc	,
			YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			DATEPART(quarter, td.ct_date),
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc


Order By	td.bra_desc	,
			YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			DATEPART(quarter, td.ct_date),
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc


----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 2 --spWebGrid_Sales_Branch_BYSQM


SELECT 		ISNULL(td.bra_desc,@desc)								[bra_desc],
			YEAR (td.ct_date)							[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			[card2].optval_desc + ' ' + tri.optval_desc [Quarter],
			tov.optval_desc								[month]		,

			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)										[ct_total]



FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON sem.lang_id = @lang_id
			AND [sem].optval_class = 70
			AND [sem].optval_id = 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON [card].lang_id = @lang_id
			AND [card].optval_class = 71
			AND [card].optval_id = (convert(int,month(td.ct_date)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON tri.lang_id = @lang_id
			AND [tri].optval_class = 70
			AND [tri].optval_id = 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON [card2].lang_id = @lang_id
			AND [card2].optval_class = 71
			AND [card2].optval_id = ABS(DATEPART(quarter, td.ct_date)%2-2)


Group By	td.bra_desc	,
			YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			DATEPART(quarter, td.ct_date),
			tov.optval_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc


Order By	td.bra_desc	,
			YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			DATEPART(quarter, td.ct_date),
			tov.optval_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc


----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 3 --spWebGrid_Sales_Branch_YB

SELECT 		YEAR (td.ct_date)							[year],
			ISNULL(td.bra_desc,@desc)									[bra_desc],
			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)										[ct_total]

FROM 		#tmpData												td


Group By	YEAR (td.ct_date),
			td.bra_desc


Order By	YEAR (td.ct_date),
			td.bra_desc


----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 4 --spWebGrid_Sales_Branch_YMB


	SELECT 	YEAR (td.ct_date)								[year],
			tov.optval_desc									[month]	,
			ISNULL(td.bra_desc,@desc)										[bra_desc],
			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)


Group By	YEAR (td.ct_date),
			tov.optval_desc	,
			td.bra_desc


Order By	YEAR (td.ct_date),
			tov.optval_desc	,
			td.bra_desc

----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 5 --spWebGrid_Sales_Branch_YMDB


SELECT 		YEAR (td.ct_date)							[year],
			tov.optval_desc								[month]	,
			DAY (td.ct_date)							[day],
			ISNULL(td.bra_desc,@desc)								[bra_desc],
			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)


Group By	YEAR (td.ct_date),
			tov.optval_desc	,
			DAY(td.ct_date),
			td.bra_desc

Order By	YEAR (td.ct_date),
			tov.optval_desc	,
			DAY(td.ct_date),
			td.bra_desc


----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 6 --spWebGrid_Sales_Branch_YQB


SELECT 		YEAR (td.ct_date)							[year],
			[card2].optval_desc + ' ' + tri.optval_desc [Quarter],
			ISNULL(td.bra_desc,@desc)								[bra_desc],

			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)										[ct_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON tri.lang_id = @lang_id
			AND [tri].optval_class = 70
			AND [tri].optval_id = 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON [card2].lang_id = @lang_id
			AND [card2].optval_class = 71
			AND [card2].optval_id = ABS(DATEPART(quarter, td.ct_date)%2-2)

Group By	YEAR (td.ct_date),
			DATEPART(quarter, td.ct_date),
			td.bra_desc	,
			[card2].optval_desc ,
			tri.optval_desc


Order By    YEAR (td.ct_date),
			DATEPART(quarter, td.ct_date),
			td.bra_desc	,
			[card2].optval_desc ,
			tri.optval_desc

----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 7 --spWebGrid_Sales_Branch_YSB


SELECT 		YEAR (td.ct_date)							[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			ISNULL(td.bra_desc,@desc)								[bra_desc],
			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

			LEFT JOIN tbsysOptionsValues							[sem]
			ON sem.lang_id = @lang_id
			AND [sem].optval_class = 70
			AND [sem].optval_id = 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON [card].lang_id = @lang_id
			AND [card].optval_class = 71
			AND [card].optval_id = (convert(int,month(td.ct_date)/7) + 1)


Group By	YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			td.bra_desc,
			sem.optval_desc,
			[card].optval_desc


Order By	YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			td.bra_desc,
			sem.optval_desc,
			[card].optval_desc



----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 8 --spWebGrid_Sales_Branch_YSQB

SELECT 		YEAR (td.ct_date)							[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			[card2].optval_desc + ' ' + tri.optval_desc [Quarter],
			ISNULL(td.bra_desc,@desc)								[bra_desc],
			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON sem.lang_id = @lang_id
			AND [sem].optval_class = 70
			AND [sem].optval_id = 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON [card].lang_id = @lang_id
			AND [card].optval_class = 71
			AND [card].optval_id = (convert(int,month(td.ct_date)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON tri.lang_id = @lang_id
			AND [tri].optval_class = 70
			AND [tri].optval_id = 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON [card2].lang_id = @lang_id
			AND [card2].optval_class = 71
			AND [card2].optval_id = ABS(DATEPART(quarter, td.ct_date)%2-2)

Group By	YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			DATEPART(quarter, td.ct_date)	,
			td.bra_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc


Order By	YEAR (td.ct_date),
			convert(int,month(td.ct_date)/7) + 1,
			DATEPART(quarter, td.ct_date)	,
			td.bra_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc


----------------------------------	           ///////////               ---------------------------------------------------------

ELSE IF @detail_id = 9 --spWebGrid_Sales_Branch_YSQMB

SELECT 		YEAR (td.ct_date)							[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			[card2].optval_desc + ' ' + tri.optval_desc [Quarter],
			tov.optval_desc								[month]	,
			ISNULL(td.bra_desc,@desc)									[bra_desc],

			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
			END)	 [ct_total]

FROM 		#tmpData												td

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td.ct_date)

			LEFT JOIN tbsysOptionsValues							[sem]
			ON sem.lang_id = @lang_id
			AND [sem].optval_class = 70
			AND [sem].optval_id = 6

			LEFT JOIN tbsysOptionsValues							[card]
			ON [card].lang_id = @lang_id
			AND [card].optval_class = 71
			AND [card].optval_id = (convert(int,month(td.ct_date)/7) + 1)

			LEFT JOIN tbsysOptionsValues							[tri]
			ON tri.lang_id = @lang_id
			AND [tri].optval_class = 70
			AND [tri].optval_id = 3

			LEFT JOIN tbsysOptionsValues							[card2]
			ON [card2].lang_id = @lang_id
			AND [card2].optval_class = 71
			AND [card2].optval_id = ABS(DATEPART(quarter, td.ct_date)%2-2)


Group By	YEAR (td.ct_date),
			tov.optval_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc ,
			td.bra_desc


Order By	YEAR (td.ct_date),
			tov.optval_desc,
			sem.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc ,
			td.bra_desc




SELECT tut.utexts_desc + ' ' + @curr_symbol
FROM tbsysUniqueTexts tut
WHERE tut.lang_id = @lang_id AND tut.utexts_id = 224022
GO
 
