  CREATE PROCEDURE [dbo].[spWebGrid_Sales_Branch_BYSQM]
  (
  	@comp_id		INT,
  	@lang_id		INT,
  	@user_id        INT,
  	@bra_id			int,
  	@country_id		INT,
  	@state_id		INT,
  	@date_from		DATETIME,
  	@date_to		DATETIME
  )
  AS 
  SET NOCOUNT ON
  /*
  DECLARE		@comp_id		INT,
  			@lang_id		INT,
  			@user_id        INT,
  			@bra_id			int,
  			@country_id		INT,
  			@state_id		INT,
  			@date_from		DATETIME,
  			@date_to		DATETIME
  SELECT 		@comp_id		= 1,
  			@lang_id		= 2,
  			@user_id        = 1,
  			@bra_id         =-1,
  			@country_id		=-1,
  			@state_id		=-1,
  			@date_from		='01-01-2000',
  			@date_to		='31-12-2010'
  */
  SELECT @date_to = dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')
  SELECT 		tb.bra_desc									[bra_desc], 
  			YEAR (tct.ct_date)							[year], 
  			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
  			[card2].optval_desc + ' ' + tri.optval_desc [Quarter],
  			tov.optval_desc								[month]		, 
  			SUM(CASE WHEN vctfs.sd_isCredit = 'False' THEN  
  				 CONVERT(DECIMAL(18,2), ISNULL( tct.ct_total,0)	* 1)
  			ELSE 
  				  CONVERT(DECIMAL(18,2), ISNULL( tct.ct_total,0) * -1) 
  			END)	 [ct_total]		
  FROM 		tbCommercialTransactions								tct
  			INNER JOIN vwCommercialTransactions_forSalesStats		vctfs 
  			ON	vctfs.comp_id			=	tct.comp_id
  			AND vctfs.bra_id			=	tct.bra_id
  			AND vctfs.ct_transaction	=	tct.ct_transaction
  			INNER JOIN tbsysOptionsValues							tov
  			ON	tov.lang_id				=	@lang_id
  			AND tov.optval_class		=	37
  			AND	tov.optval_id			=	MONTH(tct.ct_date)
  			INNER JOIN tbBranch										tb
  			ON tb.comp_id				=	tct.comp_id
  			AND tb.bra_id				=	tct.bra_id
  			INNER JOIN vwUsers4BranchFilter							vubf
  			ON vubf.comp_id				=	tct.comp_id
  			AND vubf.bra_id				=	tct.bra_id
  			AND vubf.[user_id]			=	@user_id
  			LEFT JOIN tbsysOptionsValues							[sem]
  			ON sem.lang_id = @lang_id
  			AND [sem].optval_class = 70
  			AND [sem].optval_id = 6
  			LEFT JOIN tbsysOptionsValues							[card]
  			ON [card].lang_id = @lang_id
  			AND [card].optval_class = 71
  			AND [card].optval_id = (convert(int,month(ct_date)/7) + 1)
  			LEFT JOIN tbsysOptionsValues							[tri]
  			ON tri.lang_id = @lang_id
  			AND [tri].optval_class = 70
  			AND [tri].optval_id = 3
  			LEFT JOIN tbsysOptionsValues							[card2]
  			ON [card2].lang_id = @lang_id
  			AND [card2].optval_class = 71
  			AND [card2].optval_id = ABS(DATEPART(quarter, ct_date)%2-2)		
  WHERE		tct.comp_id		= @comp_id			
  AND         (@bra_id        = -1 OR tb.bra_id      = @bra_id)
  AND			tct.ct_date		BETWEEN	@date_from AND @date_to
  Group By	tb.bra_desc	,
  			YEAR (tct.ct_date),
  			convert(int,month(ct_date)/7) + 1,
  			DATEPART(quarter, ct_date),
  			tov.optval_desc,
  			sem.optval_desc,
  			[card].optval_desc,
  			[card2].optval_desc ,
  			tri.optval_desc 
  Order By	tb.bra_desc	,
  			YEAR (tct.ct_date),
  			convert(int,month(ct_date)/7) + 1,
  			DATEPART(quarter, ct_date),
  			tov.optval_desc
  ---- 
  GO
 
