			sem.optval_desc,
			tov.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc

Order By	td2.dl_name,
			YEAR (td2.ct_date),
			sem.optval_desc,
			tov.optval_desc,
			[card].optval_desc,
			[card2].optval_desc ,
			tri.optval_desc



----------------------------------	           ///////////               ---------------------------------------------------------

IF @detail_id = 3 --spWebGrid_Sales_Delivery_YD


SELECT 		YEAR (td2.ct_date)							[year],
			ISNULL(td2.dl_name,@desc)					[dl_name],
			SUM(CASE WHEN td2.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td2.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td2.ct_total,0) * -1)
			END)										[ct_total]

FROM 		#tmpData												td2

Group By	YEAR (td2.ct_date),
			td2.dl_name

Order By	YEAR (td2.ct_date),
			td2.dl_name


----------------------------------	           ///////////               ---------------------------------------------------------

IF @detail_id = 4 --spWebGrid_Sales_Delivery_YMD

SELECT 		YEAR (td2.ct_date)							[year],
			tov.optval_desc								[month]	,
			ISNULL(td2.dl_name,@desc)		     		[dl_name],
			SUM(CASE WHEN td2.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td2.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td2.ct_total,0) * -1)
			END)										[ct_total]

FROM 		#tmpData												td2

			INNER JOIN tbsysOptionsValues							tov
			ON	tov.lang_id				=	@lang_id
			AND tov.optval_class		=	37
			AND	tov.optval_id			=	MONTH(td2.ct_date)

Group By	YEAR (td2.ct_date),
