			AND [card2].optval_class = 71
			AND [card2].optval_id = ABS(DATEPART(quarter, td2.ct_date)%2-2)


Group By	YEAR (td2.ct_date),
			[card2].optval_desc ,
			tri.optval_desc,
			td2.dl_name


Order By	YEAR (td2.ct_date),
			[card2].optval_desc ,
			tri.optval_desc,
			td2.dl_name


----------------------------------	           ///////////               ---------------------------------------------------------

IF @detail_id = 7 --spWebGrid_Sales_Delivery_YSD


SELECT 		YEAR (td2.ct_date)							[year],
			[card].optval_desc + ' ' + sem.optval_desc	[half_year],
			ISNULL(td2.dl_name,@desc)					[dl_name],
			SUM(CASE WHEN td2.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td2.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td2.ct_total,0) * -1)
