			ON [card2].lang_id = @lang_id
			AND [card2].optval_class = 71
			AND [card2].optval_id = ABS(DATEPART(quarter, td.ct_date)%2-2)





Group By
			YEAR (td.ct_date),
			tri.optval_desc,
			[card2].optval_desc,
			td.st_desc,
			td.sm_name



Order By
			YEAR (td.ct_date),
			tri.optval_desc,
			[card2].optval_desc,
			td.st_desc,
			td.sm_name

--------------- * * * * ----------------------- * * * * * --------------- * * * * -----------

ELSE IF @detail_id = 7  -- [spWebGrid_Sales_Salesterms_Salesman_YS]


SELECT


			YEAR (td.ct_date)							[year],
			ISNULL(td.st_desc,@desc)							        [st_desc],
			ISNULL(td.sm_name,@desc)									[sm_name],
			SUM(CASE WHEN td.sd_isCredit = 'False' THEN
				 CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0)	* 1)
			ELSE
				  CONVERT(DECIMAL(18,2), ISNULL( td.ct_total,0) * -1)
