CREATE PROCEDURE spWebGrid_Sales_Test
(
	@comp_id		INT,
	@lang_id		INT,
	@country_id		INT,
	@state_id		INT,
	@date_from		DATETIME,
	@date_to		DATETIME
)
AS
SET NOCOUNT ON


/*
DECLARE		@comp_id		INT,
			@lang_id		INT,
			@country_id		INT,
			@state_id		INT,
			@date_from		DATETIME,
			@date_to		DATETIME
SELECT 		@comp_id		=1,
			@lang_id		=2,
			@country_id		=-1,
			@state_id		=-1,
			@date_from		='01-01-2000',
			@date_to		='31-12-2010'
*/




SELECT @date_to = dbo.fnGetEnd_or_BeginOfDate(@date_to, 'True')


SELECT 		tc2.country_desc							[country_desc],
			ts.state_desc								[state_desc],
			YEAR (tct.ct_date)							[year]		,
			tov.optval_desc								[month]		,
			tc.cust_name								[cust_name]	,
			CONVERT(DECIMAL(18,2),SUM(tct.ct_total))	[ct_total]

FROM 		tbCommercialTransactions						tct
			INNER JOIN vwCommercialTransactions_forSales	vctfs
			ON	vctfs.comp_id			= tct.comp_id
			AND vctfs.bra_id			= tct.bra_id
			AND vctfs.ct_transaction	= tct.ct_transaction

			INNER JOIN tbCustomer							tc
			ON	tc.comp_id		=	tct.comp_id
			AND tc.cust_id		=	tct.cust_id

			INNER JOIN tbsysCountry							tc2
			ON	tc2.country_id	=	tc.country_id

			INNER JOIN tbsysState							ts
			ON	ts.country_id	=	tc.country_id
			AND ts.state_id		=	tc.state_id

			INNER JOIN tbsysOptionsValues					tov
			ON	tov.lang_id		=	@lang_id
			AND tov.optval_class=	37
			AND	tov.optval_id	=	MONTH(tct.ct_date)


WHERE		tct.comp_id		= @comp_id
AND			(@country_id	= -1 OR	tc.country_id	= @country_id)
AND			(@state_id		= -1 OR tc.state_id		= @state_id)
AND			tct.ct_date		BETWEEN	@date_from AND @date_to


Group By	tc2.country_desc	,
			ts.state_desc		,
			YEAR(tct.ct_date)	,
			tov.optval_desc		,
			tc.cust_name

Order By	tc2.country_desc	,
			ts.state_desc		,
			YEAR(tct.ct_date)	,
			tov.optval_desc		,
			tc.cust_name
GO



-- Ejecuta un Código SQL de hasta 8K que recibe como parámetro en @strParamOUT al JSon recibido en la variable @JSonParameters

CREATE PROCEDURE [dbo].[spWebServices_ExecScripts]
(
	@wst_id				INT,
	@ScriptLabel		VARCHAR(100),
	@JSonParameters		VARCHAR(MAX),
	@strRequestIP		NVARCHAR(50)
)
AS


BEGIN

	-- ----------------------------------------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------------------------------------
	/*
	DECLARE 	@page_id			UNIQUEIDENTIFIER
	SELECT 		@page_id			= '0352be36-5ca2-4b30-be44-8a2020c78c14'

	*/
	-- ----------------------------------------------------------------------------------------------

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 200
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	-- MOS 06-2023: Por seguridad NO se permiten ejecutar SQLScripts con usuario sa
	IF SUSER_NAME() = 'sa' OR SUSER_NAME() = 'SA' OR SUSER_NAME() = 'Sa' OR SUSER_NAME() = 'sA'
		BEGIN
			SELECT 'WARNING: sa user NOT Allowed to execute GlobalBluePoint Scripts.'
			RETURN
		END


	BEGIN TRY



		IF @JSonParameters LIKE '%sp_executesql%'
			BEGIN
				SELECT -5
				RETURN
			END


		-- MOS 02-2022 ( x las dudas que pasen cosas raras en lugar de label.. igual, NO deberia molestar ya que está en un where ...
		SET @ScriptLabel = REPLACE(@ScriptLabel,' ','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'(','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,')','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'"','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'''','')

		SET @strRequestIP = dbo.fnIPCheck(@strRequestIP)
		DECLARE @bitHasScript		AS BIT = 'False'
		DECLARE @strScript4Execute  AS NVARCHAR(MAX)
		SELECT	@strScript4Execute = twsis.wssql_scriptSQL ,
				@bitHasScript = 'True'
			FROM tbWebSiteII_SQLScripts twsis		WITH (NOLOCK)
			WHERE twsis.wssql_label = @ScriptLabel


		IF @strScript4Execute LIKE '%sp_executesql%'
			BEGIN
				SELECT -6
				RETURN
			END

		IF @bitHasScript = 'True'
			BEGIN

				DECLARE @strMessage		AS NVARCHAR(MAX) = @JSonParameters
				DECLARE @param			AS NVARCHAR(100) = N'@strParamOUT nvarchar(MAX) OUTPUT'

				EXEC sp_executesql @strScript4Execute, @param, @strMessage OUTPUT;
				IF @strMessage <> ''
					BEGIN
						SELECT @strMessage
					END
				ELSE
					BEGIN
						SELECT '-9'
					END
			END
		ELSE
			BEGIN
				SELECT '-3'
			END


	END TRY
	BEGIN CATCH
		SELECT '-4',ERROR_MESSAGE()
		RETURN
	END CATCH


END

GO



