CREATE PROCEDURE [dbo].[spWebServices_ExportData]
(
	@comp_id			INT,
	@wst_id				INT,
	@expgr_id			INT
)
AS

BEGIN

	SET NOCOUNT ON


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	DECLARE @user_id AS INT

	SELECT	@user_id = tws.[user_id]
		FROM tbWebServices tws					WITH (NOLOCK)
		WHERE	tws.comp_id = @comp_id AND
				tws.wst_id	= @wst_id



	DECLARE @strQuery2Execute  VARCHAR(8000)
	SET		@strQuery2Execute   = NULL

	SELECT TOP 1
			 @strQuery2Execute  = tcqg.expgr_query
		FROM vwCustomQuery2Grid					tcqg
		INNER JOIN tbUserCompanyProfile			tucp
			ON	tucp.comp_id	= @comp_id		AND
				tucp.[user_id]	= @user_id
		INNER JOIN tbCustomQuery2GridByProfile	tcq
			ON	tcq.comp_id		= @comp_id		AND
				tcq.expgr_id	= tcqg.expgr_id AND
				tcq.prof_id		= tucp.prof_id
		WHERE	tcqg.comp_id    = @comp_id		AND
				tcqg.expgr_id	= @expgr_id


	IF @@ROWCOUNT > 0
		BEGIN

			---------------------------------------------------------------------------------
			--Se saca del query toda instruccion que pueda dañar la base de datos asi como ;, etc.
			---------------------------------------------------------------------------------
			IF	@strQuery2Execute LIKE '%DROP %'		OR
				@strQuery2Execute LIKE '%DELETE %'		OR
				@strQuery2Execute LIKE '%TRUNCATE %'	OR
				@strQuery2Execute LIKE '%ALTER% '		OR
				@strQuery2Execute LIKE '%PROCEDURE %'	OR
				@strQuery2Execute LIKE '%FUNCTION %'
				BEGIN
					SELECT 'SQL NOT ALLOWED!' [GenerationError]
					RETURN
				END
			---------------------------------------------------------------------------------

			EXEC('SELECT ' + @strQuery2Execute)
			RETURN

		END
	ELSE
		BEGIN
			SELECT 'NO REPORT FOUND for the WS User!' [GenerationError]
			return
		END

END
GO


CREATE PROCEDURE [dbo].[spWebServices_getDataById]
(
	 @comp_id INT,
	 @wst_id INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------
		-- TESTING
		-- ------------------------------------------
		 /*
			DECLARE
				@comp_id	INT,
				@wst_id		INT

			SELECT
				@comp_id	=1,
				@wst_id		=10
		 */
		-- ------------------------------------------

		SELECT
			tws.ws_UserName,
			tws.ws_Enabled,
			tws.ws_requestFromValidate,
			tws.[user_id],
			isnull(tws.ML_stor_id,-1)						[ML_stor_id],
			isnull(tws.ML_st_id,-1)							[ML_st_id],
			ISNULL(tws.ML_sd_id,-1)							[ML_sd_id],
			ISNULL(tws.ML_pointOfSale,-1)					[ML_pointOfSale],
			ISNULL(tws.ML_dl_id,-1)							[ML_dl_id],
			ISNULL(tws.ML_prli_id,-1)						[ML_prli_id],
			ISNULL(tws.ML_df_id4Collection,-1)				[ML_df_id4Collection],
			ISNULL(tws.ML_cc_id4Collection,-1)				[ML_cc_id4Collection],
			ISNULL(tws.ML_bra_id,-1)						[ML_bra_id],
			ISNULL(tws.ML_url4Images,'')					[ML_url4Images],
			ISNULL(tws.ML_cust_id,-1)						[ML_cust_id],
			ISNULL(tws.wst_SaleOrderMailFrom,'')			[wst_SaleOrderMailFrom],
			ISNULL(tws.ML_stor_id4ForceInsertItem,-1)		[ML_stor_id4ForceInsertItem],
			ISNULL(tws.wst_allowSQLScript,'False')			[wst_allowSQLScript],
			ISNULL(tws.wst_allowSQLScriptExecute,'False')	[wst_allowSQLScriptExecute],
			ISNULL(tws.wst_allowSQLCustomQuery,'False')		[wst_allowSQLCustomQuery] ,
			ISNULL(tws.stor_id4FullJaus,-1)					[stor_id4FullJaus],
			ISNULL(tws.prli_id4FullJaus,-1)					[prli_id4FullJaus],
			ISNULL(tws.item_id4FullJaus_GE,-1)				[item_id4FullJaus_GE],
			ISNULL(tws.sm_id4FullJaus,-1)					[sm_id4FullJaus],
			ISNULL(tws.st_id4FullJaus,-1)					[st_id4FullJaus],
			ISNULL(tws.bra_id4FullJaus,-1)					[bra_id4FullJaus],
			ISNULL(tws.item_id4FullJaus_NC,-1)				[item_id4FullJaus_NC],
			ISNULL(tws.cc_id4Fulljaus,-1)					[cc_id4Fulljaus],
			ISNULL(tws.ca_id4FullJaus,-1)					[ca_id4FullJaus],
			ISNULL(tws.df_id4Collection4FullJaus,-1)		[df_id4Collection4FullJaus],
			ISNULL(tws.item_id4FullJaus_Discount,-1)		[item_id4FullJaus_Discount]
			FROM tbWebServices								tws WITH (NOLOCK)
			WHERE	tws.comp_id = @comp_id					AND
					tws.wst_id	= @wst_id
	END




GO



