CREATE PROCEDURE [dbo].spWebServices_logIn4PowerBoard
(
	@comp_id				INT,
	@strUserName		VARCHAR(50),
	@strUserPassword	VARCHAR(50)
)
AS


BEGIN

	-- ----------------------------------------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------------------------------------
	/*
	DECLARE 	@page_id			UNIQUEIDENTIFIER
	SELECT 		@page_id			= '0352be36-5ca2-4b30-be44-8a2020c78c14'

	*/
	-- ----------------------------------------------------------------------------------------------

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	BEGIN TRY

		DECLARE @pb_id AS INT = -1

		SELECT @pb_id = twspb.pb_id
			FROM tbWebServices_powerBoard twspb		WITH (NOLOCK)
			WHERE	twspb.comp_id		= @comp_id		AND
					twspb.pb_userName	= @strUserName	AND
					twspb.pb_passWord	= @strUserPassword

		SELECT @pb_id	[ID]
		RETURN

	END TRY
	BEGIN CATCH
		SELECT -1	[ID]
		RETURN
	END CATCH

END

GO





