-- ---------

CREATE PROCEDURE [dbo].[spWebServicesV2_getItemsData]
	@comp_id		AS INT,
	@item_id		AS INT,
	@prli_id		AS INT,
	@stor_id		AS INT,
	@bitALL			AS BIT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @tmpItem TABLE(item_id INT PRIMARY KEY)

	IF @bitALL = 'True'
		BEGIN
			INSERT INTO @tmpItem(item_id)
				SELECT	DISTINCT  item_id
					FROM tbitem  ti
					INNER JOIN tbSubCategory tsc
					ON	tsc.comp_id		= ti.comp_id		AND
						tsc.cat_id		= ti.cat_id			AND
						tsc.subcat_id	= ti.subcat_id
					INNER JOIN tbCategory tc
					ON	tc.comp_id	= ti.comp_id		AND
						tc.cat_id	= ti.cat_id
					WHERE	ti.comp_id		= @comp_id	AND
							ti.item_web		= 'True'	AND
							tsc.subcat_web	= 'True'	AND
							tc.cat_web		= 'True'
		END
	ELSE
		BEGIN
			INSERT INTO @tmpItem(item_id)
				SELECT DISTINCT  ti.item_id
					FROM tbitem  ti
					INNER JOIN tbSubCategory tsc
					ON	tsc.comp_id = ti.comp_id		AND
						tsc.cat_id = ti.cat_id			AND
						tsc.subcat_id = ti.subcat_id
					INNER JOIN tbCategory tc
					ON	tc.comp_id = ti.comp_id			AND
						tc.cat_id = ti.cat_id
					INNER JOIN tbWebServices_ItemUpdateHistory jk
						ON	jk.comp_id = ti.comp_id		AND
							jk.item_id = ti.item_id
					WHERE	ti.comp_id		= @comp_id	AND
							ti.item_web		= 'True'	AND
							tsc.subcat_web	= 'True'	AND
							tc.cat_web		= 'True'


		END


	DECLARE @wsh_id AS INT
	SELECT	@wsh_id = MAX(twsiuh.wsh_id)
		FROM tbWebServices_ItemUpdateHistory twsiuh
		WHERE twsiuh.comp_id = @comp_id


	SELECT	@wsh_id																				[UpdateID],
			ti.comp_id,
			ti.item_id,
			ti.item_code,
			ti.item_desc,
			ti.item_detail,
			ti.item_vendorCode,
			ti.cat_id,
			ti.subcat_id,
			ti.brand_id,
			ti.pres_id,
			ti.item_annotation,
			ti.item_annotation1,
			ti.item_annotation2,
			ti.item_newness,
			ti.item_liquidation,
			ti.item_weight,
			ti.item_volume,
			dbo.fnGetAStock(@comp_id, @stor_id, ti.item_id, 9999999)							[AvailableStock],
			dbo.fnGetAStock4MaxAssociation(@comp_id, @stor_id, ti.item_id, 9999999)				[Stock],
			tpli.prli_price,
			tpli.curr_id,
			tpli.prli_price * dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, ti.item_id)		[prli_pricePlusTax],
			dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id, 1, 0, 0 , 0, 0)		[ARS_price],
			dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id, 1, 0, 0 , 0, 0) * dbo.fnGetPriceListItemTaxesCoeficient(tpli.comp_id, ti.item_id)
																								[ARS_pricePlusTax],
			ISNULL(ti.item_web_groupingCode,'')													[item_web_groupingCode]
	FROM tbItem ti
	INNER JOIN @tmpItem tmp
		ON tmp.item_id = ti.item_id
	INNER JOIN tbPriceListItems tpli
		ON	tpli.comp_id = ti.comp_id AND
			tpli.item_id = ti.item_id AND
			tpli.prli_id = @prli_id
	WHERE ti.comp_id = @comp_id AND
		(@item_id = -1 OR ti.item_id = @item_id)



END
GO



