CREATE PROCEDURE [dbo].[spWebServicesV2_getPCConfig_RelationDataByItem_MaxQtyAssociation]
(
	@comp_id			INT,
	@Item_PCType		INT, --1 Microprocesador / 2 Mother / 4 Memoria / 5 Gabinete
	@item_id			INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ----------------------------------------------------------------------------------------
		-- TESTING
		-- ----------------------------------------------------------------------------------------
		/*
			DECLARE
				@comp_id			INT,
				@Item_PCType			INT, --1 Microprocesador / 2 Mother / 4 Memoria / 5 Gabinete
				@item_id			INT
			SELECT
				@comp_id			= 1,
				@Item_PCType		= 5,
				@item_id			= 697
		*/
		-- ----------------------------------------------------------------------------------------

		-- MICRO
		IF @Item_PCType = 1
			BEGIN
				SELECT
					tipr.item_id,
					--ti.item_code,
					ti.item_desc,
					--tiprt.pcct_desc,
					tipr.maxQTY
				FROM tbItem_PCConfig_Relations				tipr
				INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt
				ON	tiprt.comp_id			= tipr.comp_id	AND
					tiprt.pcct_id			= tipr.pcct_id
				INNER JOIN tbItem							ti
				ON	ti.comp_id				= tipr.comp_id	AND
					ti.item_id				= tipr.item_id
				INNER JOIN tbSubCategory					tsc
				ON	tsc.comp_id				= ti.comp_id	AND
					tsc.cat_id				= ti.cat_id		AND
					tsc.subcat_id			= ti.subcat_id	AND
					tsc.subcat_pcConfigType = 1
				WHERE	tipr.comp_id		= @comp_id		AND
						tipr.pcctr_disabled = 'False'
				ORDER BY ti.item_id
			END

		--MOTHERBOARD
		IF @Item_PCType = 2
			BEGIN
				SELECT
					tipr.item_id,
					--ti.item_code,
					ti.item_desc,
					--tiprt.pcct_desc,
					tipr.maxQTY
				FROM tbItem_PCConfig_Relations				tipr
				INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt
				ON	tiprt.comp_id			= tipr.comp_id	AND
					tiprt.pcct_id			= tipr.pcct_id
				INNER JOIN tbItem							ti
				ON	ti.comp_id				= tipr.comp_id	AND
					ti.item_id				= tipr.item_id
				INNER JOIN tbSubCategory					tsc
				ON	tsc.comp_id				= ti.comp_id	AND
					tsc.cat_id				= ti.cat_id		AND
					tsc.subcat_id			= ti.subcat_id	AND
					tsc.subcat_pcConfigType = 2
				INNER JOIN tbItem_PCConfig_Relations		tipr2
				ON	tipr2.comp_id			= tipr.comp_id	AND
					tipr2.item_id			= @item_id		AND
					tipr2.pcct_id			= tipr.pcct_id
				WHERE	tipr.comp_id		= @comp_id		AND
						tipr.pcctr_disabled = 'False'
				ORDER BY ti.item_id

			END




		--MEMORIA
		IF @Item_PCType = 4
			BEGIN
				SELECT
					tipr.item_id,
					--ti.item_code,
					ti.item_desc,
					--tiprt.pcct_desc,
					--tipr.maxQTY
					tipr2.maxQTY
				FROM tbItem_PCConfig_Relations				tipr
				INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt
				ON	tiprt.comp_id			= tipr.comp_id	AND
					tiprt.pcct_id			= tipr.pcct_id
				INNER JOIN tbItem							ti
				ON	ti.comp_id				= tipr.comp_id	AND
					ti.item_id				= tipr.item_id
				INNER JOIN tbSubCategory					tsc
				ON	tsc.comp_id				= ti.comp_id	AND
					tsc.cat_id				= ti.cat_id		AND
					tsc.subcat_id			= ti.subcat_id	AND
					tsc.subcat_pcConfigType = 4
				INNER JOIN tbItem_PCConfig_Relations		tipr2
				ON	tipr2.comp_id			= tipr.comp_id	AND
					tipr2.item_id			= @item_id		AND
					tipr2.pcct_id			= tipr.pcct_id
				WHERE	tipr.comp_id		= @comp_id		AND
						tipr.pcctr_disabled = 'False'
				ORDER BY ti.item_id
			END

		--GABINETE
		IF @Item_PCType = 5
			BEGIN
				SELECT
					tipr.item_id,
					--ti.item_code,
					ti.item_desc,
					--tiprt.pcct_desc,
					tipr.maxQTY
				FROM tbItem_PCConfig_Relations				tipr
				INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt
				ON	tiprt.comp_id			= tipr.comp_id	AND
					tiprt.pcct_id			= tipr.pcct_id
				INNER JOIN tbItem							ti
				ON	ti.comp_id				= tipr.comp_id	AND
					ti.item_id				= tipr.item_id
				INNER JOIN tbSubCategory					tsc
				ON	tsc.comp_id				= ti.comp_id	AND
					tsc.cat_id				= ti.cat_id		AND
					tsc.subcat_id			= ti.subcat_id	AND
					tsc.subcat_pcConfigType = 5
				INNER JOIN tbItem_PCConfig_Relations		tipr2
				ON	tipr2.comp_id			= tipr.comp_id	AND
					tipr2.item_id			= @item_id		AND
					tipr2.pcct_id			= tipr.pcct_id
				WHERE	tipr.comp_id		= @comp_id		AND
						tipr.pcctr_disabled = 'False'
				ORDER BY ti.item_id
			END

	END

GO



