	@ws_id					INT,
	@cat_id					INT,
	@subcat_id				INT,
	@return_value			INT OUTPUT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id				INT,
			@ws_id					INT,
			@cat_id					INT,
			@subcat_id				INT

SELECT		@comp_id				=1,
