CREATE PROCEDURE [dbo].[spWebSite_ComponentsExclusion_insertData]
(

	@comp_id						INT,
	@swsc_id						INT,
	@swsc_id_outputContainer		INT,
	@wsp_id							INT,
	@swsc_id_ExcludeFromParagraph	INT,
	@chkUpdateNoWSid				BIT

)
AS









BEGIN

	SET NOCOUNT ON



	-- -------------------------------------------------------------------------------
	-- Parametros de Prueba
	-- -------------------------------------------------------------------------------
/*
	DECLARE		@comp_id						INT,
				@swsc_id						INT,
				@swsc_id_outputContainer		INT,
				@wsp_id							INT,
				@swsc_id_ExcludeFromParagraph	INT,
				@chkUpdateNoWSid				BIT,
				@return_value					INT


	SELECT		@comp_id						= 18,
				@swsc_id						= 1,
				@swsc_id_outputContainer		= 1,
				@wsp_id							= 5,
				@swsc_id_ExcludeFromParagraph	= 1,
				@chkUpdateNoWSid				='False'
*/
	-- -------------------------------------------------------------------------------




		-- ----------------------------------------------------------------------
		-- a los int le seteamos null por si le llega -1
		-- ----------------------------------------------------------------------


		if	(@comp_id						= -1)	set	@comp_id						= NULL
		if	(@swsc_id						= -1)	set	@swsc_id						= NULL
		if	(@swsc_id_outputContainer		= -1)	set	@swsc_id_outputContainer		= NULL
		if	(@wsp_id						= -1)	set	@wsp_id							= NULL
		if	(@swsc_id_ExcludeFromParagraph	= -1)	set	@swsc_id_ExcludeFromParagraph	= NULL


		-- ----------------------------------------------------------------------
	--select * from tbWebSite_ComponentsExclusion


	if not exists (	SELECT TOP 1 1
						from tbWebSite_ComponentsExclusion twsc
							where	twsc.comp_id						= @comp_id							and
									twsc.swsc_id						= @swsc_id							and
									twsc.swsc_id_outputContainer		= @swsc_id_outputContainer			and
									twsc.wsp_id							= @wsp_id							and
									twsc.swsc_id_ExcludeFromParagraph	= @swsc_id_ExcludeFromParagraph )
		begin

			select 1

			INSERT INTO tbWebSite_ComponentsExclusion
			(
				comp_id,
				swsc_id,
				swsc_id_outputContainer,
				wsp_id,
				swsc_id_ExcludeFromParagraph
			)
			VALUES
			(
				@comp_id,
				@swsc_id,
				@swsc_id_outputContainer,
				@wsp_id,
				@swsc_id_ExcludeFromParagraph
			)


			--SET @return_value = @@IDENTITY


		end

	--
	--	else
	--
	--
	--	IF exists (SELECT TOP 1 1 from tbWebSite_ComponentsExclusion twsc
	--								where twsc.comp_id =@comp_id
	--								and  twsc.swsc_id = @swsc_id
	--								and twsc.swsc_id_outputContainer = @swsc_id_outputContainer
	--								and twsc.wsp_id=@wsp_id
	--								and twsc.swsc_id_ExcludeFromParagraph = @swsc_id_ExcludeFromParagraph ) and @chkUpdateNoWSid = 'true'
	--		BEGIN
	--
	--
	--				select 2
	--
	--
	--
	--
	--				update tbWebSite_ComponentsExclusion
	--				SET
	--
	--
	--				comp_id							= @comp_id,
	--				swsc_id							= @swsc_id,
	--				swsc_id_outputContainer			= @swsc_id_outputContainer,
	--				wsp_id							= @wsp_id,
	--				swsc_id_ExcludeFromParagraph	= @swsc_id_ExcludeFromParagraph
	--
	--
	--
	--		END
	--





END
GO






