CREATE PROCEDURE [dbo].[spWebSite_Detail_Clone]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id_from		INT,
	@ws_detail_from	INT,
	@ws_id_to		INT,
	@ws_detail_to	INT,
	@desc			NVARCHAR(100)
)
AS

SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------

/*
DECLARE 	@comp_id		INT,
			@lang_id		INT,
			@ws_id_from		INT,
			@ws_detail_from	INT,
			@ws_id_to		INT,
			@ws_detail_to	INT,
			@desc			NVARCHAR(100)


SELECT		@comp_id		=1,
			@lang_id		=2,
			@ws_id_from		=12,
			@ws_detail_from	=2,
			@ws_id_to		=12,
			@ws_detail_to	=3
*/


-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------




		IF @ws_detail_to = -1
		BEGIN

			INSERT INTO tbWebSite_Detail
			(
				comp_id,
				ws_id,
				-- wsdet_id -- this column value is auto-generated,
				wsdet_desc,
				wsdet_disabled,
				wsdet_width
			)
			SELECT	twsd.comp_id,
					@ws_id_to,
					@desc,
					twsd.wsdet_disabled,
					twsd.wsdet_width

			FROM	tbWebSite_Detail twsd
			WHERE	twsd.comp_id	= @comp_id
			AND		twsd.ws_id		= @ws_id_from

			SET @ws_detail_to = @@IDENTITY

		END

		ELSE

		BEGIN

			DELETE FROM tbWebSite_DetailData
			WHERE	comp_id		= @comp_id
			AND		ws_id		= @ws_id_to
			AND		wsdet_id	= @ws_detail_to



			UPDATE	tbWebSite_Detail

			SET		wsdet_desc		= twsd.wsdet_desc,
					wsdet_disabled	= twsd.wsdet_disabled,
					wsdet_width		= twsd.wsdet_width

			FROM	tbWebSite_Detail
					INNER JOIN tbWebSite_Detail			twsd
					ON	twsd.comp_id	= tbWebSite_Detail.comp_id
					AND twsd.ws_id		= @ws_id_from
					AND twsd.wsdet_id	= @ws_detail_from

			WHERE	tbWebSite_Detail.comp_id	= @comp_id
			AND		tbWebSite_Detail.ws_id		= @ws_id_to
			AND		tbWebSite_Detail.wsdet_id	= @ws_detail_to

		END



		INSERT INTO tbWebSite_DetailData
		(
			comp_id,
			ws_id,
			wsdet_id,
			wsdat_order,
			wsdat_data1,
			wsdat_data2,
			wsdat_image_url,
			optval_id,
			wsdat_image_order
		)
		SELECT	twsdd.comp_id,
				@ws_id_to,
				@ws_detail_to,
  				twsdd.wsdat_order,
  				twsdd.wsdat_data1,
  				twsdd.wsdat_data2,
  				twsdd.wsdat_image_url,
  				twsdd.optval_id,
  				twsdd.wsdat_image_order

		FROM	tbWebSite_DetailData				twsdd

		WHERE	twsdd.comp_id	= @comp_id
		AND		twsdd.ws_id		= @ws_id_from
		AND		twsdd.wsdet_id	= @ws_detail_from



END
GO







CREATE Procedure [dbo].[spWebSite_Detail_getCombo]
(
	@comp_id			INT,
	@ws_id			    INT
)
AS
SET NOCOUNT ON


BEGIN


----------------------------------------------
--Parametros de Prueba
----------------------------------------------
/*

	declare	@comp_id			INT,
			@ws_id			    INT



	select	@ws_id  = 21,
			@comp_id = 1

*/
----------------------------------------------
----------------------------------------------



		Select	twsd.wsdet_id	 [Id],
				twsd.wsdet_desc [Desc]

		From tbWebSite_Detail twsd

		WHERE	twsd.comp_id	= @comp_id
		and		(@ws_id = -1 or twsd.ws_id      = @ws_id)

		Order By twsd.wsdet_desc


END
GO







CREATE PROCEDURE [dbo].[spWebSite_Detail_getDataById]
(
	@comp_id		INT,
	@ws_id			INT,
	@wsdet_id		INT
)
AS

SET NOCOUNT ON


BEGIN


-----------------------------------------------------
--Parametros de Prueba
-----------------------------------------------------
/*

DECLARE @comp_id		INT,
		@ws_id			INT,
		@wsdet_id		INT

SELECT  @comp_id		=1,
		@ws_id			=1,
		@wsdet_id		=2


*/
-----------------------------------------------------
-----------------------------------------------------



	SELECT	isnull(twsd.wsdet_desc,'')				wsdet_desc,
			isnull(twsd.wsdet_disabled,'false')		wsdet_disabled,
			isnull(twsd.wsdet_width,0)				wsdet_width,
	      	isnull(twsd.wsdet_cellspacing,0)		wsdet_cellspacing,
	      	isnull(twsd.wsdet_cellpadding,0)		wsdet_cellpadding,
	      	isnull(twsd.wsdet_image_url,'')			wsdet_image_url,
	      	CASE isnull(twsd.wsdet_image_repet,0)
				WHEN 0 THEN 'no-repeat'
				WHEN 1 THEN 'no-repeat'
				WHEN 2 THEN 'repeat'
				WHEN 3 THEN 'repeat-x'
				WHEN 4 THEN 'repeat-y'
			END										wsdet_image_repet

	FROM	tbWebSite_Detail		twsd

	WHERE	twsd.comp_id	= @comp_id
	AND		twsd.ws_id		= @ws_id
	AND		twsd.wsdet_id	= @wsdet_id




END
GO








