	@wsdet_image_repet		INT,
	@return_value			INT OUTPUT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id				INT,
			@ws_id					INT,
			@wsdet_desc				nvarchar(100),
			@wsdet_disabled			BIT,
			@wsdet_width			INT,
