	if	(@comp_id			= -1)	set	@comp_id				= NULL
	if	(@ws_id				= -1)	set	@ws_id					= NULL
	if	(@wsdet_image_repet	= -1)	set	@wsdet_image_repet		= NULL


	-- ----------------------------------------------------------------------


		INSERT INTO tbWebSite_Detail
