CREATE  Procedure [dbo].[spWebSite_DetailData_getDataByFilters]
(
	@comp_id	INT,
	@lang_id	INT,
	@ws_id		INT,
	@wsdet_id	INT
)
AS

SET NOCOUNT ON

BEGIN

	----------------------------------------------
	-- testing
	----------------------------------------------
	/*
		declare	@comp_id	INT,
				@lang_id	INT,
				@ws_id		INT,
				@wsdet_id	INT

		select	@comp_id	= 1,
				@lang_id	= 2,
				@ws_id		= 12,
				@wsdet_id	= 9
	*/
	----------------------------------------------



	SELECT	twsdd.wsdet_id,
			twsdd.wsdat_id,
			twsdd.wsdat_order,
			twsdd.wsdat_data1,
			twsdd.wsdat_data2,
			twsdd.wsdat_image_url,
			isnull(twsdd.optval_id,-1)			[optval_id],
			isnull(tov.optval_desc,'')			[optval_desc],
			twsdd.wsdat_image_order,
			ISNULL(twsdd.wsdat_height,0)		[wsdat_height],
			ISNULL(twsdd.wsdat_width,0)			[wsdat_width],
			ISNULL(twswn.wswn_desc,'')			[wswn_desc],

			twsdd.wsdat_newTable				[wsdat_newTable],
			twsdd.wsdat_newRow					[wsdat_newRow],
			twsdd.wsdat_newCell					[wsdat_newCell],
			twsdd.wsdat_verticalLoad			[wsdat_verticalLoad],

			CASE	WHEN twsdd.wsdat_colspan IS NULL	THEN 1
					WHEN twsdd.wsdat_colspan < 1		THEN 1
					ELSE twsdd.wsdat_colspan			END		[wsdat_colspan],

			CASE	WHEN twsdd.wsdat_rowspan IS NULL	THEN 1
					WHEN twsdd.wsdat_rowspan < 1		THEN 1
					ELSE twsdd.wsdat_rowspan			END		[wsdat_rowspan]


	FROM	tbWebSite_DetailData					twsdd

			LEFT JOIN tbsysOptionsValues			tov
			ON	tov.lang_id			= @lang_id
			AND tov.optval_class	= 140
			AND tov.optval_id		= twsdd.optval_id

			LEFT JOIN tbWebSite_WordsNew			twswn
			ON	twswn.lang_id		= @lang_id
			AND twswn.wswi_id		= twsdd.wsdat_wswi_id


	WHERE	twsdd.comp_id	= @comp_id
	AND		twsdd.ws_id		= @ws_id
	AND		twsdd.wsdet_id	= @wsdet_id
	AND		IsNull(twsdd.wsdat_disabled,'False') = 'False'

	ORDER BY twsdd.wsdat_order


END
GO








