			wsdat_verticalLoad,
			wsdat_colspan,
			wsdat_rowspan,
			wsdat_disabled
		)
		VALUES
		(
			@comp_id,
			@ws_id,
			@wsdet_id,
			@wsdat_order,
			@wsdat_data1,
			@wsdat_data2,
			@wsdat_image_url,
			@optval_id,
			@wsdat_image_order,
			@wsdat_wswi_id,
			@wsdat_height,
			@wsdat_width,
			@wsdat_newTable,
			@wsdat_newRow,
			@wsdat_newCell,
			@wsdat_verticalLoad,
			@wsdat_colspan,
			@wsdat_rowspan,
			@wsdat_disabled
		)

		SET @return_value = @@IDENTITY


END
