CREATE PROCEDURE [dbo].[spWebSite_Files_InsertData]
(
	@ws_fileName			nvarchar(200),
	@ws_fileContent			Image,
	@ws_code				int,
	@ws_fileLenght			decimal(19,0),
	@return_value			INT OUTPUT
)
as

set nocount on


BEGIN

	---------------------------------------------------------------------
	---------------------------------------------------------------------
	/*

	Declare 	@ws_fileName		nvarchar(200),
				@ws_fileContent		Image,
				@ws_code			int,
				@ws_fileLenght		decimal(19,0)

	Select		@ws_fileName		= 'asda',
				@ws_fileContent		= 'dsrt4t',
				@ws_code			= 1,
				@ws_fileLenght		= 123

	*/
	---------------------------------------------------------------------
	---------------------------------------------------------------------


	IF EXISTS (SELECT TOP 1 1 FROM tbWebSite_Files twsf
	           WHERE twsf.ws_fileName = @ws_fileName AND twsf.ws_code = @ws_code)
		BEGIN

			UPDATE	tbWebSite_Files

			SET		ws_fileContent	= @ws_fileContent,
					ws_fileLength	= @ws_fileLenght,
					@return_value	= ws_fileId

			WHERE	ws_fileName		= @ws_fileName
			AND		ws_code			= @ws_code


		END

	ELSE
		BEGIN

			Insert into tbWebSite_Files
			(
				ws_fileName,
				ws_fileContent,
				ws_code,
				ws_fileLength
			)
			VALUES
			(
				@ws_fileName,
				@ws_fileContent,
				@ws_code,
				@ws_fileLenght
			)


			SET @return_value = @@IDENTITY
		END



	-- actualizamos la marca de todos los sitios, para que baje las nuevas
	-- imágenes cargadas online y no haya que esperar a que la marca se actualice
	-- cuando se hace el cierre diario
	UPDATE	tbWebSite_Names
	SET		ws_files2TempUpdated = 'false',
			ws_files2TempUpdated4Development = 'False'



END
GO








CREATE PROCEDURE [dbo].[spWebSite_Files_UpdateData]
(
	@ws_fileName			nvarchar(200),
	@ws_fileContent			Image,
	@ws_code				int,
	@ws_fileLenght			decimal(19,0)
)
as

set nocount on


BEGIN

----------------------------------------------------------
----------------------------------------------------------
/*


	Declare 	@ws_fileName		nvarchar(200),
				@ws_fileContent		Image,
				@ws_code			int,
				@ws_fileLenght		decimal(19,0)

	Select		@ws_fileName		= 'asda',
				@ws_fileContent		= 'dsrt4t',
				@ws_code			= 1,
				@ws_fileLenght		= 123


*/
----------------------------------------------------------
----------------------------------------------------------


		Update tbWebSite_Files
		SET
			ws_fileName = @ws_fileName,
			ws_fileContent = @ws_fileContent,
			ws_code = @ws_code,
			@ws_fileLenght = @ws_fileLenght


		where ws_code = @ws_code
		and ws_fileName = @ws_fileName



END


GO







