CREATE PROCEDURE [dbo].[spWebSite_ItemDetail_getData]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id			INT,
	@item_id		INT,
	@ptyItemShown	INT
)
AS

SET NOCOUNT ON

BEGIN

	-- ----------------------------------------------------------------------
	-- testing
	-- ----------------------------------------------------------------------
	/*
	DECLARE @comp_id		INT,
			@lang_id		INT,
			@ws_id			INT,
			@item_id		INT,
			@ptyItemShown	INT


	SELECT 	@comp_id		=1,
			@lang_id		=2,
			@ws_id			=12,
			@item_id		=256,
			@ptyItemShown	=2
	*/
	-- ----------------------------------------------------------------------


	EXEC spWebSite_Names_getDataById
		@comp_id,
		@lang_id,
		@ws_id


	EXEC spItem_getDataById
		@comp_id,
		@item_id



	DECLARE @wsdet_id	INT

	SELECT	@wsdet_id = CASE
							WHEN @ptyItemShown = 1 THEN twsn.ws_itemdetailformat_all
							WHEN @ptyItemShown = 2 THEN twsn.ws_itemdetailformat_offer
							WHEN @ptyItemShown = 3 THEN twsn.ws_itemdetailformat_newness
						END

	FROM	tbWebSite_Names		twsn

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id



	EXEC spWebSite_DetailData_getDataByFilters
		@comp_id,
		@lang_id,
		@ws_id,
		@wsdet_id



	EXEC spWebSite_Styles_getDataById
		@comp_id,
		@lang_id,
		@ws_id,
		32,
		324,
		-1

END






GO






CREATE PROCEDURE [dbo].[spWebSite_ItemLeading_getDataByWS]
(
	@comp_id	INT,
	@ws_id		INT
)
AS
SET NOCOUNT ON


BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE @comp_id	INT,
		@ws_id		INT

SELECT	@comp_id	= 1,
		@ws_id		= 24
*/

------------------------------------
------------------------------------



	SELECT	top 10
			twsil.item_id,
			SUBSTRING	(CASE WHEN LEN(ISNULL(ti.item_WebSite_desc,'')) > 1
								THEN ISNULL(ti.item_WebSite_desc,'')
								ELSE ISNULL(ti.item_desc,'')
						 END,1,20)		[item_desc]

	FROM	tbWebSite_ItemLeading			twsil

			INNER JOIN tbItem				ti
			ON	ti.comp_id	= twsil.comp_id
			AND ti.item_id	= twsil.item_id

	WHERE	twsil.comp_id	= @comp_id
	AND		twsil.ws_id		= @ws_id

	ORDER BY twsil.ddc_Order


END
GO







CREATE PROCEDURE [dbo].[spWebSite_ItemLeading_InsertData]
(
	@comp_id			INT,
	@item_id			INT,
	@ws_id				INT,
	@ddc_Order			INT,
	@return_value		INT OUTPUT
)
AS
SET NOCOUNT OFF


BEGIN

------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE 	@comp_id			INT,
			@item_id			INT,
			@ws_id				INT,
			@ddc_Order			INT,

SELECT		@comp_id			= 1

*/
------------------------------------
--Parametros de Prueba
------------------------------------

	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@comp_id			= -1)	set	@comp_id				= NULL
	if	(@ws_id				= -1)	set	@ws_id					= NULL
	if	(@item_id			= -1)	set	@item_id				= NULL


	-- ----------------------------------------------------------------------


	insert into tbWebSite_ItemLeading
