		@comp_id,
		@item_id,
		@ws_id,
		@ddc_Order
	)

SET @return_value = @@IDENTITY

END

GO







CREATE PROCEDURE [dbo].[spWebSite_ItemRotator_getData]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id			INT,
	@ith_id			INT
)
AS
SET NOCOUNT ON


BEGIN

------------------------------------
--Parametros de Prueba
------------------------------------

/*

	DECLARE		@comp_id	INT,
				@ws_id		INT,
				@ith_id		INT,
				@lang_id	INT
	SELECT		@comp_id	= 1,
				@ws_id		= 24,
				@lang_id	= 2,
				@ith_id		= 2
*/

------------------------------------
------------------------------------



	SELECT	'<?xml version="1.0" encoding="utf-8"?>'	[firstline],
			'<produtos>' 								[beginrootnode],
			'</produtos>' 								[endrootnode]

	--../Temp/App_Website/ItemRotator' + CONVERT(VARCHAR,@ws_id) + '/Images/'
	SELECT	TOP 7
			'<produto cordefundo="0x'+ SUBSTRING(vwsc1.color_value,2,6) + '" tempo="' + convert(varchar,twsird.itd_timeout) + '">'	[childnode1],
				'<nome		cor="0x' + SUBSTRING(vwsc2.color_value,2,6) + '">' + ti.item_desc + '</nome>'							[childnode2],
				'<descricao cor="0x' + SUBSTRING(vwsc3.color_value,2,6) + '">' + ti.item_detail + '</descricao>'					[childnode3],
				'<label></label>'																									[childnode4],


				CASE	WHEN twsn.ws_showpricelist = 1 THEN --muestra precio
							'<preco		cor="0x' + SUBSTRING(vwsc4.color_value,2,6) + '">' + isnull(ltrim(rtrim(tc.curr_symbol)) + '  ' +
												CONVERT(VARCHAR,convert(decimal(18,2),tpli.prli_price)),'Consultar') + '</preco>'
						WHEN twsn.ws_showpricelist = 0 THEN --no muestra precio
							'<preco		cor="0x' + SUBSTRING(vwsc1.color_value,2,6) + '"></preco>'
						WHEN twsn.ws_showpricelist = 2 THEN --muestra mensaje de llamar/consultar debería sacarlo de tbWebSite_ParagraphComponentsControlsDat-a
							'<preco		cor="0x' + SUBSTRING(vwsc4.color_value,2,6) + '">Consultar</preco>'
				END																													[childnode5],


				'<imagens>'																											[childnode6],
					'<imagem>ItemRotator' + CONVERT(VARCHAR,@ws_id) + '/Images/' + ltrim(rtrim(ti.item_code)) + '.jpg</imagem>'		[childnode7],
				'</imagens>'																										[childnode8],
			'</produto>'																											[childnode9],

			isnull(tii.itimg_image, isnull(ti.item_picture,NULL))																	[item_picture],
			ti.item_code


	FROM	tbWebSite_ItemRotatorDetail				twsird

			INNER JOIN tbWebSite_ItemRotatorHeader	twsirh
			ON	twsirh.comp_id	= twsird.comp_id
			AND twsirh.ith_id	= twsird.ith_id

			INNER JOIN tbItem						ti
			ON	ti.comp_id		= twsird.comp_id
			AND ti.item_id		= twsird.item_id

			INNER JOIN tbWebSite_Names				twsn
			ON	twsn.comp_id	= twsird.comp_id
			AND twsn.ws_id		= twsirh.ws_id


			LEFT JOIN tbItemImages					tii
			ON	tii.comp_id		= twsird.comp_id
			AND tii.item_id		= twsird.item_id
			AND tii.itimg_order = isnull(twsird.itimg_order,99)

			LEFT JOIN tbPriceListItems				tpli
			ON	tpli.comp_id	= twsird.comp_id
			AND tpli.prli_id	= twsn.ws_prli_id
			AND tpli.item_id	= twsird.item_id

			LEFT JOIN tbsysCurrency					tc
			ON	tc.curr_id		= tpli.curr_id

			left JOIN vwWebSite_Colors				vwsc1
			ON	twsird.itd_backcolor = vwsc1.color_id
			AND (vwsc1.lang_id = @lang_id OR vwsc1.lang_id = 0)

			LEFT JOIN vwWebSite_Colors				vwsc2
			ON	twsird.itd_forecolor_item_desc = vwsc2.color_id
			AND (vwsc2.lang_id = @lang_id OR vwsc2.lang_id = 0)

			LEFT JOIN vwWebSite_Colors				vwsc3
			ON	twsird.itd_forecolor_item_detail = vwsc3.color_id
			AND (vwsc3.lang_id = @lang_id OR vwsc3.lang_id = 0)

			LEFT JOIN vwWebSite_Colors				vwsc4
			ON	twsird.itd_backcolor_item_price = vwsc4.color_id
			AND (vwsc4.lang_id = @lang_id OR vwsc4.lang_id = 0)


	WHERE	twsird.comp_id		= @comp_id
	AND		twsirh.ws_id		= @ws_id
	AND		twsird.ith_id		= @ith_id

	AND		not isnull(tii.itimg_image, ti.item_picture) IS NULL


	ORDER BY twsird.itd_order

END

GO








CREATE PROCEDURE [dbo].[spWebSite_ItemRotator_getData4GenerateXML]
(
	@comp_id	INT,
	@ws_id		INT
)
AS
SET NOCOUNT ON

BEGIN

------------------------------------
--Parametros de Prueba
------------------------------------

/*

	DECLARE @comp_id	INT,
			@ws_id		INT
	SELECT	@comp_id	=1,
			@ws_id		=1

*/
------------------------------------
------------------------------------


	SELECT	TOP 1 isnull(twsirh.ith_id,0)		[ith_id]

	FROM	tbWebSite_ItemRotatorHeader twsirh

			LEFT JOIN tbWebSite_ItemRotatorDetail twsird
			ON twsird.comp_id = twsirh.comp_id
			AND	twsird.ith_id = twsirh.ith_id
			AND	ISNULL(twsirh.ith_lastupdate,'2000-01-01') < ISNULL(twsird.itd_lastupdate,'2001-01-01')

	WHERE	twsirh.comp_id	= @comp_id
	AND		twsirh.ws_id	= @ws_id
	AND		twsirh.ith_dataorigin IS NULL




END
GO






CREATE PROCEDURE [dbo].[spWebSite_ItemRotator_getDataById]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id			INT,
	@ith_id			INT
)
AS

SET NOCOUNT ON


BEGIN

	------------------------------------
	--Parametros de Prueba
	------------------------------------
	/*
	DECLARE @comp_id		INT,
			@lang_id		INT,
			@ws_id			INT,
			@ith_id			INT
	SELECT 	@comp_id		=1,
			@lang_id		=2,
			@ws_id			=7,
			@ith_id			=12
	IF NOT OBJECT_ID('tempdb.dbo.#resfinal')		IS NULL DROP TABLE #resfinal
	IF NOT OBJECT_ID('tempdb.dbo.#resfinal2')		IS NULL DROP TABLE #resfinal2
	*/
	------------------------------------
	------------------------------------


	DECLARE	@ith_dataorigin INT,
			@ith_maxitemqty INT

	SELECT	@ith_dataorigin = ISNULL(twsirh.ith_dataorigin,3),
			@ith_maxitemqty = ISNULL(twsirh.ith_maxitemqty,10)

	FROM	tbWebSite_ItemRotatorHeader twsirh

	WHERE	twsirh.comp_id	= @comp_id
	AND		twsirh.ith_id	= @ith_id
	AND		twsirh.ws_id	= @ws_id
	--SELECT	@ith_dataorigin, @ith_maxitemqty




	IF @ith_dataorigin = 1 --recupera datos de tbWebSite_ItemRotatorDetail
	BEGIN

			SELECT	twsird.item_id,
					twsird.itimg_order,
					vwsc1.color_value											[itd_backcolor],
					vwsc2.color_value											[itd_forecolor_item_desc],
					vwsc3.color_value											[itd_forecolor_item_detail],
					vwsc4.color_value											[itd_backcolor_item_price],
					twsird.itd_timeout,
					twsird.itd_order,

					ti.item_code,
					SUBSTRING	(
						CASE when len(ltrim(rtrim(isnull(ti.item_WebSite_desc, ti.item_desc)))) = 0
									THEN ti.item_desc
								ELSE isnull(ti.item_WebSite_desc, ti.item_desc)
						END
								,1,isnull(twsirh.ith_maxlengthitemdesc,50))
																				[item_desc],
					ti.item_detail,

					CASE
						WHEN twsird.itimg_order = 0 THEN	ti.item_picture
						ELSE								tii.itimg_image
					END															[item_image],
					twsirh.ith_timeout


			FROM	tbWebSite_ItemRotatorHeader					twsirh

					INNER JOIN tbWebSite_ItemRotatorDetail		twsird
					ON	twsird.comp_id	= twsirh.comp_id
					AND twsird.ith_id	= twsirh.ith_id

					LEFT JOIN tbItem							ti
					ON	ti.comp_id		= twsird.comp_id
					AND ti.item_id		= twsird.item_id

					LEFT JOIN tbItemImages						tii
					ON	tii.comp_id		= ti.comp_id
					AND tii.item_id		= ti.item_id
					AND tii.itimg_order = twsird.itimg_order

					left JOIN vwWebSite_Colors				vwsc1
					ON	twsird.itd_backcolor = vwsc1.color_id
					AND (vwsc1.lang_id = @lang_id OR vwsc1.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc2
					ON	twsird.itd_forecolor_item_desc = vwsc2.color_id
					AND (vwsc2.lang_id = @lang_id OR vwsc2.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc3
					ON	twsird.itd_forecolor_item_detail = vwsc3.color_id
					AND (vwsc3.lang_id = @lang_id OR vwsc3.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc4
					ON	twsird.itd_backcolor_item_price = vwsc4.color_id
					AND (vwsc4.lang_id = @lang_id OR vwsc4.lang_id = 0)


			WHERE	twsirh.comp_id	= @comp_id
			AND		twsirh.ith_id	= @ith_id

			ORDER BY twsird.itd_order

	END




	IF @ith_dataorigin = 2 --recupera datos de tbWebSite_ItemLeading
	BEGIN

			DECLARE @tableIL		AS TABLE(item_id INT, itd_id INT, row INT)
			DECLARE @tableItemsIL	AS TABLE(item_id INT)


			DECLARE @llitem_id	INT,
					@llmvi_count INT,
					@llitd_id	INT,
					@llitem_count INT,
					@llrn int,
					@llpos INT,


					@llidx		INT,
					@llitem_id_ant INT


			--==============================================================================================
			/*recuperamos la cantidad de registros de diseño de la tbWebSite_ItemRotatorDetail*/
			DECLARE @llitd_count INT
			SELECT	@llitd_count = COUNT(*)
			FROM	tbWebSite_ItemRotatorDetail twsird
			WHERE	twsird.comp_id = @comp_id
			AND		twsird.ith_id = @ith_id
			--SELECT	@llitd_count
			--==============================================================================================




			--==============================================================================================
			--recupramos los artículos destacados
			INSERT INTO @tableItemsIL
			(
				item_id
			)
			SELECT	twsil.item_id

			FROM	tbWebSite_ItemLeading twsil

			WHERE	twsil.comp_id	= @comp_id
			AND		twsil.ws_id		= @ws_id

			ORDER BY twsil.item_id DESC
			--SELECT * FROM @tableItemsIL
			--===============================================================================================



			--==============================================================================================
			--en una tabla local joineamos los diseños con los items más visitados y la gragamos el núemro de línea
			;WITH resultado_total AS
			(
				SELECT 	twsil.item_id, 0 [count],twsird.itd_id,
						ROW_NUMBER() OVER ( ORDER BY twsil.item_id DESC, twsil.item_id, twsird.ith_id ) AS RN

				FROM	tbWebSite_ItemLeading		twsil,
						tbWebSite_ItemRotatorDetail twsird

				WHERE	twsil.comp_id	= @comp_id
				AND		twsil.ws_id		= @ws_id
				AND		twsird.comp_id	= @comp_id
				AND		twsird.ith_id	= @ith_id
			)
			--==============================================================================================



			--==============================================================================================
			--a la tabla anterior le agregamos una columna que agrupa por la cantidad de registro de diseño
			SELECT	item_id,
					[count],
					itd_id,
					rn,
					(((rn-1)%@llitd_count)+1) [pos]
			INTO	#resfinal2
			FROM	resultado_total
			ORDER BY 4
			--SELECT * FROM #resfinal2
			--==============================================================================================




			--==============================================================================================
			--generamos un cursor para poder asociar los items más visitados con los diseños intercalándolos
			DECLARE cursor_IL CURSOR FOR
			SELECT	rf.item_id,
					rf.[count],
					rf.itd_id,rn,
					rf.[pos]

			FROM	#resfinal2  rf
					INNER JOIN @tableItemsIL tim
					ON tim.item_id = rf.item_id

			OPEN cursor_IL

			FETCH cursor_IL INTO @llitem_id, @llmvi_count, @llitd_id, @llrn, @llpos

			SET @llidx			= 1
			SET @llitem_id_ant	= 0

			WHILE @@FETCH_STATUS = 0
			BEGIN

				IF @llidx = @llpos AND @llitem_id_ant <> @llitem_id
				BEGIN
						INSERT INTO @tableIL (item_id, itd_id, row) VALUES (@llitem_id, @llitd_id, @llrn)

						SET @llidx			= @llidx + 1
						SET @llitem_id_ant	= @llitem_id

						IF @llidx > @llitd_count
						BEGIN
							SET @llidx = 1
						END
				END

				FETCH cursor_IL INTO @llitem_id, @llmvi_count, @llitd_id, @llrn, @llpos
			END
			CLOSE cursor_IL
			DEALLOCATE cursor_IL
			--SELECT * FROM @tableMVI tm




			SELECT	ti.item_id, --twsird.item_id,
					twsird.itimg_order,
					vwsc1.color_value											[itd_backcolor],
					vwsc2.color_value											[itd_forecolor_item_desc],
					vwsc3.color_value											[itd_forecolor_item_detail],
					vwsc4.color_value											[itd_backcolor_item_price],
					twsird.itd_timeout,
					twsird.itd_order,

					ti.item_code,
					SUBSTRING	(
						CASE when len(ltrim(rtrim(isnull(ti.item_WebSite_desc, ti.item_desc)))) = 0
									THEN ti.item_desc
								ELSE isnull(ti.item_WebSite_desc, ti.item_desc)
						END
								,1,isnull(twsirh.ith_maxlengthitemdesc,50))
																				[item_desc],

					ti.item_detail,

					CASE
						WHEN twsird.itimg_order = 0 THEN	ti.item_picture
						ELSE								tii.itimg_image
					END															[item_image],
					twsirh.ith_timeout


			FROM	tbWebSite_ItemRotatorHeader					twsirh

					INNER JOIN tbWebSite_ItemRotatorDetail		twsird
					ON	twsird.comp_id	= twsirh.comp_id
					AND twsird.ith_id	= twsirh.ith_id

					INNER JOIN @tableIL							til
					ON	til.itd_id		= twsird.itd_id

					LEFT JOIN tbItem							ti
					ON	ti.comp_id		= twsird.comp_id
					AND ti.item_id		= til.item_id

					LEFT JOIN tbItemImages						tii
					ON	tii.comp_id		= ti.comp_id
					AND tii.item_id		= ti.item_id
					AND tii.itimg_order = twsird.itimg_order

					left JOIN vwWebSite_Colors				vwsc1
					ON	twsird.itd_backcolor = vwsc1.color_id
					AND (vwsc1.lang_id = @lang_id OR vwsc1.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc2
					ON	twsird.itd_forecolor_item_desc = vwsc2.color_id
					AND (vwsc2.lang_id = @lang_id OR vwsc2.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc3
					ON	twsird.itd_forecolor_item_detail = vwsc3.color_id
					AND (vwsc3.lang_id = @lang_id OR vwsc3.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc4
					ON	twsird.itd_backcolor_item_price = vwsc4.color_id
					AND (vwsc4.lang_id = @lang_id OR vwsc4.lang_id = 0)


			WHERE	twsirh.comp_id	= @comp_id
			AND		twsirh.ith_id	= @ith_id

			ORDER BY twsird.itd_order

	END









	IF @ith_dataorigin = 3 --recupera datos de tbWebSite_MostViewedItems
	BEGIN

			DECLARE @tableMVI AS TABLE(item_id INT, itd_id INT, row INT, item_count INT)
			DECLARE @tableItemsMVI AS TABLE(item_id INT)


			DECLARE @litem_id	INT,
					@lmvi_count INT,
					@litd_id	INT,
					@litem_count INT,
					@lrn int,
					@lpos INT,


					@lidx		INT,
					@litem_id_ant INT


			--==============================================================================================
			/*recuperamos la cantidad de registros de diseño de la tbWebSite_ItemRotatorDetail*/
			DECLARE @litd_count INT
			SELECT	@litd_count = COUNT(*)
			FROM	tbWebSite_ItemRotatorDetail twsird
			WHERE	twsird.comp_id = @comp_id
			AND		twsird.ith_id = @ith_id
			--SELECT	@litd_count
			--==============================================================================================




			--==============================================================================================
			--recupramos el top 10 de los más vistos, luego poner este valor en alguna tabla
			INSERT INTO @tableItemsMVI
			(
				item_id
			)
			SELECT	TOP (@ith_maxitemqty) 	twsmvi.item_id

			FROM 	tbWebSite_MostViewedItems twsmvi

			WHERE	twsmvi.comp_id	= @comp_id
			AND		twsmvi.ws_id	= @ws_id

			ORDER BY twsmvi.mvi_count DESC
			--SELECT * FROM @tableItemsMVI
			--===============================================================================================



			--==============================================================================================
			--en una tabla local joineamos los diseños con los items más visitados y la gragamos el núemro de línea
			;WITH resultado_total AS
			(
				SELECT 	twsmvi.item_id, twsmvi.mvi_count,twsird.itd_id,
						ROW_NUMBER() OVER ( ORDER BY twsmvi.mvi_count DESC, twsmvi.item_id, twsird.ith_id ) AS RN

				FROM 	tbWebSite_MostViewedItems twsmvi,
						tbWebSite_ItemRotatorDetail twsird

				WHERE	twsmvi.comp_id = @comp_id
				AND		twsmvi.ws_id = @ws_id
				AND		twsird.comp_id = @comp_id
				AND		twsird.ith_id = @ith_id
			)
			--==============================================================================================



			--==============================================================================================
			--a la tabla anterior le agregamos una columna que agrupa por la cantidad de registro de diseño
			SELECT item_id, mvi_count,itd_id,rn, (((rn-1)%@litd_count)+1) [pos]
			INTO #resfinal
			FROM resultado_total
			ORDER BY 4
			--==============================================================================================




			--==============================================================================================
			--generamos un cursor para poder asociar los items más visitados con los diseños intercalándolos
			DECLARE cursor_MVI CURSOR FOR
			SELECT	rf.item_id,
					rf.mvi_count,
					rf.itd_id,rn,
					rf.[pos]

			FROM	#resfinal  rf
					INNER JOIN @tableItemsMVI tim
					ON tim.item_id = rf.item_id

			OPEN cursor_MVI

			FETCH cursor_MVI INTO @litem_id, @lmvi_count, @litd_id, @lrn, @lpos

			SET @lidx			= 1
			SET @litem_id_ant	= 0

			WHILE @@FETCH_STATUS = 0
			BEGIN

				IF @lidx = @lpos AND @litem_id_ant <> @litem_id
				BEGIN
						INSERT INTO @tableMVI (item_id, itd_id, row, item_count) VALUES (@litem_id, @litd_id, @lrn, @lmvi_count)

						SET @lidx = @lidx + 1
						SET @litem_id_ant = @litem_id

						IF @lidx > @litd_count
						BEGIN
							SET @lidx = 1
						END
				END

				FETCH cursor_MVI INTO @litem_id, @lmvi_count, @litd_id, @lrn, @lpos
			END
			CLOSE cursor_MVI
			DEALLOCATE cursor_MVI
			--SELECT * FROM @tableMVI tm




			SELECT	--twsird.item_id,
					tmvi.item_id,
					twsird.itimg_order,
					vwsc1.color_value											[itd_backcolor],
					vwsc2.color_value											[itd_forecolor_item_desc],
					vwsc3.color_value											[itd_forecolor_item_detail],
					vwsc4.color_value											[itd_backcolor_item_price],
					twsird.itd_timeout,
					twsird.itd_order,

					ti.item_code,
					SUBSTRING	(
						CASE when len(ltrim(rtrim(isnull(ti.item_WebSite_desc, ti.item_desc)))) = 0
									THEN ti.item_desc
								ELSE isnull(ti.item_WebSite_desc, ti.item_desc)
						END
								,1,isnull(twsirh.ith_maxlengthitemdesc,50))
																				[item_desc],
					isnull(ti.item_detail,'')									[item_detail],

					CASE
						WHEN twsird.itimg_order = 0 THEN	ti.item_picture
						ELSE								tii.itimg_image
					END															[item_image],

					isnull(twsirh.ith_timeout,4)								[ith_timeout]


			FROM	tbWebSite_ItemRotatorHeader					twsirh

					INNER JOIN tbWebSite_ItemRotatorDetail		twsird
					ON	twsird.comp_id	= twsirh.comp_id
					AND twsird.ith_id	= twsirh.ith_id

					INNER JOIN @tableMVI						tmvi
					ON	tmvi.itd_id		= twsird.itd_id

					LEFT JOIN tbItem							ti
					ON	ti.comp_id		= twsird.comp_id
					AND ti.item_id		= tmvi.item_id

					LEFT JOIN tbItemImages						tii
					ON	tii.comp_id		= ti.comp_id
					AND tii.item_id		= ti.item_id
					AND tii.itimg_order = twsird.itimg_order

					left JOIN vwWebSite_Colors				vwsc1
					ON	twsird.itd_backcolor = vwsc1.color_id
					AND (vwsc1.lang_id = @lang_id OR vwsc1.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc2
					ON	twsird.itd_forecolor_item_desc = vwsc2.color_id
					AND (vwsc2.lang_id = @lang_id OR vwsc2.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc3
					ON	twsird.itd_forecolor_item_detail = vwsc3.color_id
					AND (vwsc3.lang_id = @lang_id OR vwsc3.lang_id = 0)

					LEFT JOIN vwWebSite_Colors				vwsc4
					ON	twsird.itd_backcolor_item_price = vwsc4.color_id
					AND (vwsc4.lang_id = @lang_id OR vwsc4.lang_id = 0)


			WHERE	twsirh.comp_id	= @comp_id
			AND		twsirh.ith_id	= @ith_id

			AND		NOT (
						CASE
							WHEN twsird.itimg_order = 0 THEN	ti.item_picture
							ELSE								tii.itimg_image
						END
						) IS NULL

			ORDER BY tmvi.item_count DESC, twsird.itd_id


	END




END

GO






CREATE PROCEDURE [dbo].[spWebSite_ItemRotatorDetail_insertData]
(
	@comp_id					INT,
	@ith_id						INT,
	@ws_id						INT,
	@item_id					INT,
	@itimg_order				INT,
	@itd_order					INT,
	@itd_backcolor				INT,
	@itd_forecolor_item_desc	INT,
	@itd_forecolor_item_detail	INT,
	@itd_backcolor_item_price	INT,
	@itd_timeout				INT,
	@itd_lastupdate				DATETIME,
	@return_value				INT OUTPUT
)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id					INT,
			@ith_id						INT,
			@ws_id						INT,
			@item_id					INT,
			@itimg_order				INT,
			@itd_order					INT,
			@itd_backcolor				INT,
			@itd_forecolor_item_desc	INT,
			@itd_forecolor_item_detail	INT,
			@itd_backcolor_item_price	INT,
			@itd_timeout				INT,
			@itd_lastupdate				DATETIME,
			@return_value				INT OUTPUT

SELECT		@comp_id				=1,
			@ith_id				=2,
			@item_id			=1,
			@ws_id					=23

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@comp_id						= -1)	set	@comp_id					= NULL
	if	(@ith_id						= -1)	set	@ith_id						= NULL
	if	(@item_id						= -1)	set	@item_id					= NULL
	if	(@ws_id							= -1)	set	@ws_id						= NULL
	if	(@itd_backcolor					= -1)	set	@itd_backcolor				= NULL
	if	(@itd_forecolor_item_desc		= -1)	set	@itd_forecolor_item_desc	= NULL
	if	(@itd_forecolor_item_detail		= -1)	set	@itd_forecolor_item_detail	= NULL
	if	(@itd_backcolor_item_price		= -1)	set	@itd_backcolor_item_price	= NULL

	-- ----------------------------------------------------------------------



	insert into tbWebSite_ItemRotatorDetail
	(
		comp_id,
		ith_id,
		-- itd_id -- this column value is auto-generated,
		ws_id,
		item_id,
		itimg_order,
		itd_order,
		itd_backcolor,
		itd_forecolor_item_desc,
		itd_forecolor_item_detail,
		itd_backcolor_item_price,
		itd_timeout,
		itd_lastupdate
	)
	VALUES
	(
		@comp_id,
		@ith_id,
		@ws_id,
		@item_id,
		@itimg_order,
		@itd_order,
		@itd_backcolor,
		@itd_forecolor_item_desc,
		@itd_forecolor_item_detail,
		@itd_backcolor_item_price,
		@itd_timeout,
		@itd_lastupdate

	)

	SET @return_value = @@IDENTITY


END
GO







