CREATE PROCEDURE [dbo].[spWebSite_Items_cloneStyles]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id_from		INT,
	@swsc_id_from	INT,
	@ws_id_to		INT,
	@swsc_id_to		INT
)
AS

SET NOCOUNT ON


------------------------------------
--Parametros de Prueba
------------------------------------
/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@ws_id_from		INT,
		@swsc_id_from	INT,
		@ws_id_to		INT,
		@swsc_id_to		INT

SELECT	@comp_id		=1,
		@lang_id		=2,
		@ws_id_from		=23,
		@swsc_id_from	=2,
		@ws_id_to		=23,
		@swsc_id_to		=1
*/

------------------------------------
------------------------------------

-- ==================================================================================================
-- ==================================================================================================

-- swsc_id = 1 -- Items
-- swsc_id = 2 -- Ofertas
-- swsc_id = 3 -- Novedades

-- ==================================================================================================
-- ==================================================================================================

-- TENER EN CUENTA QUE SI AGREGARON REGISTROS EN TBSYSWEBSITE_COMPONENTSCONTROLS SE DEB ACTUALIZAR LA
-- TABLA TBSYSOPTIONSVALUES EN LAS OPTVAL_CLASS = -12, -13, -21, -23, -31, -32

-- ==================================================================================================
-- ==================================================================================================


BEGIN TRANSACTION
BEGIN TRY


	IF @ws_id_from = @ws_id_to AND @swsc_id_from = @swsc_id_to

	BEGIN

		SET @ws_id_from = @ws_id_from

	END

	ELSE

	BEGIN


		--recuperar el id de ParagraphComponentsRelation del componente destino
		DECLARE @wsplr_id	INT

		SELECT TOP 1 @wsplr_id = twspcr.wsplr_id

		FROM	tbWebSite_ParagraphComponentsRelation twspcr

		WHERE	twspcr.comp_id	= @comp_id
		AND 	twspcr.ws_id	= @ws_id_to
		AND		twspcr.swsc_id	= @swsc_id_to
		--SELECT	@wsplr_id





		--se eliminan los registros de ParagraphComponentsControlsData
		DELETE FROM tbWebSite_ParagraphComponentsControlsData
		--SELECT * FROM tbWebSite_ParagraphComponentsControlsData
		WHERE	comp_id		= @comp_id
		AND 	ws_id		= @ws_id_to
		AND		swsc_id		= @swsc_id_to



		--se eliminan los registros de Styles
		DELETE FROM tbWebSite_Styles
		--SELECT * FROM tbWebSite_Styles
		WHERE	comp_id		= @comp_id
		AND 	ws_id		= @ws_id_to
		AND		swsc_id		= @swsc_id_to





		--se arma el optval_class con los valores de swsc_id origen y destino para tener acceso a las relaciones
		--entre los ids	de los tipos de items
		DECLARE @optval_class	INT
		SET @optval_class = ((@swsc_id_from * 10) + @swsc_id_to) * -1
		--SELECT @optval_class





		--insertamos en Styles los valores de swsc_id origen a swsc_id destino

		INSERT INTO tbWebSite_Styles
		(
				comp_id,			ws_id,				swsc_id,			swscc_id,
				fb_id,				color_id,			ff_id,				fs_id,
				td_id,				fw_id,				fz_id,				bc_id,
				wsst_url,			bs_id,				bw_id,				border_type
		)

		SELECT	twss.comp_id,		@ws_id_to,			@swsc_id_to,		tov.optval_order,
				twss.fb_id,			twss.color_id,		twss.ff_id,			twss.fs_id,
				twss.td_id,			twss.fw_id,			twss.fz_id,			twss.bc_id,
				twss.wsst_url,		twss.bs_id,			twss.bw_id,			twss.border_type

		FROM	tbWebSite_Styles					twss

				INNER JOIN tbsysOptionsValues		tov
				ON	tov.optval_class	= @optval_class
				AND tov.optval_id		= twss.swscc_id

		WHERE	twss.comp_id	= @comp_id
		AND 	twss.ws_id		= @ws_id_from
		AND		twss.swsc_id	= @swsc_id_from





		--insertamos en ParagraphComponentsControlsData los valores de swsc_id origen a swsc_id destino

		INSERT INTO tbWebSite_ParagraphComponentsControlsData
		(
				comp_id,				wsplr_id,					swsc_id,
				swscc_id,				wspcc_image_url,			wspcc_flash_url,
				wspcc_wswi_id,			ws_id,						wspcc_href,
				wspcc_height,			wspcc_width,				wspcc_image_repet,
				ith_id,					wspcc_action
		)

		SELECT	twspccd.comp_id, 		@wsplr_id, 					@swsc_id_to,
				tov.optval_order,		twspccd.wspcc_image_url,	twspccd.wspcc_flash_url,
				twspccd.wspcc_wswi_id, 	@ws_id_to,					twspccd.wspcc_href,
				twspccd.wspcc_height,	twspccd.wspcc_width,		twspccd.wspcc_image_repet,
				twspccd.ith_id,			twspccd.wspcc_action

		FROM	tbWebSite_ParagraphComponentsControlsData	twspccd

				LEFT JOIN tbWebSite_WordsNew				twswn
				ON	twswn.lang_id			= @lang_id
				AND twspccd.wspcc_wswi_id	= twswn.wswi_id

				INNER JOIN tbsysOptionsValues				tov
				ON	tov.optval_class		= @optval_class
				AND tov.optval_id			= twspccd.swscc_id

		WHERE	twspccd.comp_id		= @comp_id
		AND 	twspccd.ws_id		= @ws_id_from
		AND		twspccd.swsc_id		= @swsc_id_from

	END


	COMMIT TRANSACTION


END
TRY BEGIN CATCH
	--SELECT ERROR_MESSAGE()
	ROLLBACK TRANSACTION
	--SET @return_value = -1

END CATCH


GO







CREATE PROCEDURE [dbo].[spWebSite_Languages_getDataByFilters]
(
	@comp_id		INT,
	@ws_id			INT
)
AS
SET NOCOUNT ON

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE @comp_id	INT,
		@ws_id		INT

SELECT  @comp_id	=1,
		@ws_id		=6
*/

------------------------------------
------------------------------------


		SELECT	twsl.lang_id,
				twsl.wslang_enabled,
				twsl.wslang_url,
				twsl.wslang_default,
				tl.lang_desc,
				tl.lang_google_id,
				tl.lang_google_desc

		FROM  	tbWebSite_Languages				twsl

				INNER JOIN tbsysLanguage		tl
				ON	tl.lang_id	= twsl.lang_id

		WHERE	twsl.comp_id	= @comp_id
		AND		twsl.ws_id		= @ws_id

		ORDER BY	twsl.wslang_default DESC,
					tl.lang_desc


END
GO







