CREATE PROCEDURE [dbo].[spWebSite_Menu_getData4StartUp]
(
	@comp_id			INT,
	@ws_id				INT
)
AS


SET NOCOUNT ON


/*
DECLARE @comp_id		INT,
		@ws_id			INT

SELECT 	@comp_id		= 1,
		@ws_id			= 28
*/



SELECT	TOP 1
		twsm.wsm_id,
		twsm.wsm_desc,
		isnull(twsm.wsm_link,'')			[wsm_link],

		isnull(twsm.wsm_detail1,'') +
		isnull(twsm.wsm_detail2,'') +
		isnull(twsm.wsm_detail3,'') +
		isnull(twsm.wsm_detail4,'')			[wsm_detail]


FROM	tbWebSite_Menu		twsm

WHERE	twsm.comp_id						= @comp_id
AND		twsm.ws_id							= @ws_id
AND		isnull(twsm.wsm_startup,'false')	= 'true'
AND		ISNULL(twsm.wsm_disabled,'false')	= 'false'

ORDER BY	twsm.wsm_id_sup,
			twsm.wsm_order

GO







CREATE PROCEDURE [dbo].[spWebSite_Menu_getDataById]
(
	@comp_id		INT,
	@ws_id			INT,
	@wsm_id			INT
)
AS


SET NOCOUNT ON

/*
SELECT * FROM tbWebSite_Menu twsm WHERE twsm.ws_id = 28
DECLARE @comp_id		INT,
		@ws_id			INT,
		@wsm_id			INT

SELECT 	@comp_id		= 1,
		@ws_id			= 28,
		@wsm_id			= 22
*/




IF EXISTS	(	SELECT	1
				FROM	tbWebSite_Menu						twsm
				WHERE	twsm.comp_id		= @comp_id
				AND		twsm.ws_id			= @ws_id
				AND		twsm.wsm_id			= @wsm_id
				AND		(
							LEN(isnull(twsm.wsm_link,''))		> 0	OR
							LEN(isnull(twsm.wsm_detail1,'') +
								isnull(twsm.wsm_detail2,'') +
								isnull(twsm.wsm_detail3,'') +
								isnull(twsm.wsm_detail4,''))	> 0	OR
							ISNULL(twsm.wsm_action,0)			> 0
						)
			)


		SELECT	TOP 1
				twsm.wsm_id,
				twsm.wsm_desc,
				isnull(twsm.wsm_link,'')			[wsm_link],

				isnull(twsm.wsm_detail1,'')			[wsm_detail1],
				isnull(twsm.wsm_detail2,'')			[wsm_detail2],
				isnull(twsm.wsm_detail3,'')			[wsm_detail3],
				isnull(twsm.wsm_detail4,'')			[wsm_detail4],
				isnull(twsm.wsm_css, '')			[wsm_css],

				ISNULL(twsm.wsm_action,0)			[wsm_action]

		FROM	tbWebSite_Menu		twsm

		WHERE	twsm.comp_id			= @comp_id
		AND		twsm.ws_id				= @ws_id
		AND		twsm.wsm_id				= @wsm_id

ELSE

		SELECT	TOP 1
				twsm.wsm_id,
				twsm.wsm_desc,
				isnull(twsm.wsm_link,'')			[wsm_link],

				isnull(twsm.wsm_detail1,'')			[wsm_detail1],
				isnull(twsm.wsm_detail2,'')			[wsm_detail2],
				isnull(twsm.wsm_detail3,'')			[wsm_detail3],
				isnull(twsm.wsm_detail4,'')			[wsm_detail4],

				ISNULL(twsm.wsm_action,0)			[wsm_action]

		FROM	tbWebSite_Menu		twsm

		WHERE	twsm.comp_id			= @comp_id
		AND		twsm.ws_id				= @ws_id
		AND		twsm.wsm_startup = 'True'


GO







CREATE PROCEDURE [dbo].[spWebSite_Menu_getDataByIdSup]
(
	@comp_id			INT,
	@ws_id				INT,
	@wsm_id_sup			INT
)
AS


SET NOCOUNT ON


/*
DECLARE @comp_id		INT,
		@ws_id			INT,
		@wsm_id_sup		INT

SELECT 	@comp_id		= 1,
		@ws_id			= 28,
		@wsm_id_sup		= 0
*/



SELECT	twsm.wsm_id,
		twsm.wsm_desc,
		ISNULL(twsm.wsm_link,'')					[wsm_link],
		ISNULL(twsm.wsm_action,0)					[wsm_action],

		(
			SELECT	convert(bit,COUNT(*))

			FROM	tbWebSite_Menu twsm2

			WHERE	twsm2.comp_id						= @comp_id
			AND		twsm2.ws_id							= @ws_id
			AND		isnull(twsm2.wsm_id_sup,0)			= twsm.wsm_id
			AND		isnull(twsm2.wsm_disabled,'false')	= 'false'
		)											[wsn_have_childs]


FROM	tbWebSite_Menu		twsm


WHERE	twsm.comp_id						= @comp_id
AND		twsm.ws_id							= @ws_id
AND		isnull(twsm.wsm_id_sup,0)			= @wsm_id_sup
AND		isnull(twsm.wsm_disabled,'false')	= 'false'


ORDER BY twsm.wsm_order

GO








CREATE PROCEDURE [dbo].[spWebSite_Menu_insertData]
(

	@comp_id					INT,
	@ws_id						INT,
	@wsm_id_sup					INT,
	@wsm_order					INT,
	@wsm_desc					NVARCHAR(200),
	@wsm_link					NVARCHAR(1000),
	@wsm_detail1				NVARCHAR(4000),
	@wsm_detail2				NVARCHAR(4000),
	@wsm_detail3				NVARCHAR(4000),
	@wsm_detail4				NVARCHAR(4000),
	@wsm_startup				BIT,
	@wsm_action					INT,
	@wsm_css					NVARCHAR(200),
	@wsm_disabled				BIT,
	@return_value				INT OUTPUT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id					INT,
			@ws_id						INT,
			@wsm_id_sup					INT,
			@wsm_order					INT,
			@wsm_desc					NVARCHAR(200),
			@wsm_link					NVARCHAR(1000),
			@wsm_detail1				NVARCHAR(4000),
			@wsm_detail2				NVARCHAR(4000),
			@wsm_detail3				NVARCHAR(4000),
			@wsm_detail4				NVARCHAR(4000),
			@wsm_startup				BIT,
			@wsm_action					INT,
			@wsm_css					NVARCHAR(200),
			@wsm_disabled				BIT,


SELECT		@comp_id				=1,
			@ith_desc				='',
			@ith_maxitemqty			=1,
			@ws_id					=23

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@comp_id				= -1)	set	@comp_id			= NULL
	if	(@ws_id					= -1)	set	@ws_id				= NULL
	if	(@wsm_id_sup			= -1)	set	@wsm_id_sup			= NULL
	if	(@wsm_action			= -1)	set	@wsm_action			= NULL







	-- ----------------------------------------------------------------------



	insert into tbWebSite_Menu
	(
		comp_id,
		ws_id,
		-- wsm_id -- this column value is auto-generated,
		wsm_id_sup,
		wsm_order,
		wsm_desc,
		wsm_link,
		wsm_detail1,
		wsm_detail2,
		wsm_detail3,
		wsm_detail4,
		wsm_startup,
		wsm_action,
		wsm_css,
		wsm_disabled
	)
	VALUES
	(

		@comp_id,
		@ws_id,
		NULL,
		@wsm_order,
		@wsm_desc,
		@wsm_link,
		@wsm_detail1,
		@wsm_detail2,
		@wsm_detail3,
		@wsm_detail4,
		@wsm_startup,
		@wsm_action,
		@wsm_css,
		@wsm_disabled

	)


	SET @return_value = @@IDENTITY







--------

--
--
--DECLARE @wsm_id				INT
--	DECLARE @wsm_id_new			INT
--	DECLARE @wsm_id_sup			INT
--	DECLARE @wsm_id_sup_new		INT
--
--
--	DECLARE @tbl_tbWebSite_Menu AS TABLE (wsm_id_ori INT, wsm_id_sup_ori INT, wsm_id_new INT)
--
--
--	DECLARE cursor_tbWebSite_Menu CURSOR FOR
--	SELECT	twss.wsm_id, twss.wsm_id_sup
--	FROM	tbWebSite_Menu twss
--	WHERE	twss.comp_id	= @comp_id
--	AND		twss.ws_id		= @ws_id_from
--
--	ORDER BY twss.wsm_id_sup, twss.wsm_order, twss.wsm_id
--
--
--	OPEN	cursor_tbWebSite_Menu
--
--
--	FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup
--
--
--
--	WHILE @@FETCH_STATUS = 0
--	BEGIN
--
--
--
--		INSERT INTO tbWebSite_Menu
--			(
--				comp_id,			ws_id,				wsm_id_sup,
--				wsm_order,			wsm_desc,			wsm_link,
--				wsm_detail1,		wsm_detail2,		wsm_detail3,		wsm_detail4,
--				wsm_startup,		wsm_action
--			)
--		SELECT	twsm.comp_id,		@ws_id_to,			NULL,
--				twsm.wsm_order,		twsm.wsm_desc,		twsm.wsm_link,
--				twsm.wsm_detail1,	twsm.wsm_detail2,	twsm.wsm_detail3,	twsm.wsm_detail4,
--				twsm.wsm_startup,	twsm.wsm_action
--
--		FROM	tbWebSite_Menu	twsm
--		WHERE	twsm.comp_id	= @comp_id
--		AND		twsm.ws_id		= @ws_id_from
--		AND		twsm.wsm_id		= @wsm_id
--
--
--		SET @wsm_id_new = @@IDENTITY
--
--
--		INSERT INTO @tbl_tbWebSite_Menu
--				(wsm_id_ori,	wsm_id_sup_ori,		wsm_id_new)
--		VALUES	(@wsm_id,		@wsm_id_sup,		@wsm_id_new)
--
--
--		FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup
--
--
--	END
--
--	CLOSE		cursor_tbWebSite_Menu
--	DEALLOCATE	cursor_tbWebSite_Menu
--
--
--
--
--
--
--
--
--	DECLARE cursor_tbWebSite_Menu CURSOR FOR
--	SELECT	twss.wsm_id, twss.wsm_id_sup
--	FROM	tbWebSite_Menu twss
--	WHERE	twss.comp_id	= @comp_id
--	AND		twss.ws_id		= @ws_id_from
--
--	ORDER BY twss.wsm_id_sup, twss.wsm_order, twss.wsm_id
--
--
--
--	OPEN	cursor_tbWebSite_Menu
--
--
--	FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup
--
--
--
--	WHILE @@FETCH_STATUS = 0
--	BEGIN
--
--		--1 leemos el original con el fetch
--
--
--		--2 con los datos del fetch leemos la tabla temporal para saber a que registro de los nuevos insertados se relaciona
--		SELECT	@wsm_id_new				= ttwsm.wsm_id_new
--
--		FROM	@tbl_tbWebSite_Menu ttwsm
--
--		WHERE	ttwsm.wsm_id_ori		= @wsm_id
--		AND		ttwsm.wsm_id_sup_ori	= @wsm_id_sup
--
--
--		--3 con id superior recuperamos a cuál se relaciona en la tabla temporal
--		IF @wsm_id_sup = 0
--
--			SET @wsm_id_sup_new = 0
--
--		ELSE
--
--			SELECT	@wsm_id_sup_new			= isnull(ttwsm.wsm_id_new,0)
--
--			FROM	@tbl_tbWebSite_Menu ttwsm
--
--			WHERE	ttwsm.wsm_id_ori		= @wsm_id_sup
--
--
--
--
--
--		--4 se actualiza el registro insertado con el id sup nuevo obtenido de la tabla temporal
--		UPDATE	tbWebSite_Menu
--
--		SET		wsm_id_sup	=	@wsm_id_sup_new
--
--		WHERE	comp_id	= @comp_id
--		AND		ws_id	= @ws_id_to
--		AND		wsm_id	= @wsm_id_new
--
--
--
--
--		FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup
--
--
--	END
--
--	CLOSE		cursor_tbWebSite_Menu
--	DEALLOCATE	cursor_tbWebSite_Menu
--
--
--
--
--
--
--
--
--
--





--------


END
GO








create PROCEDURE [dbo].[spWebSite_Menu_tmp_insertData]
(

	@wsm_id_ori					INT,
	@wsm_id_sup_ori				INT,
	@wsm_id_new					INT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@wsm_id_ori					INT,
			@wsm_id_sup_ori				INT,
			@wsm_id_new					INT


SELECT		@wsm_id_ori			=1,
			@wsm_id_sup_ori		=1,
			@wsm_id_new			=1

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@wsm_id_ori			= -1)	set	@wsm_id_ori			= NULL
	if	(@wsm_id_sup_ori		= -1)	set	@wsm_id_sup_ori		= NULL
	if	(@wsm_id_new			= -1)	set	@wsm_id_new			= NULL







	-- ----------------------------------------------------------------------



INSERT INTO tbWebSite_Menu_tmp
(
	wsm_id_ori,
	wsm_id_sup_ori,
	wsm_id_new
)
VALUES
(
	@wsm_id_ori,
	@wsm_id_sup_ori,
	@wsm_id_new
)



END
GO








CREATE PROCEDURE [dbo].[spWebSite_Menu_UpdateData_wsm_sup]
(

	@wsm_id_ori					INT,
	@wsm_id_sup_ori				INT,
	@wsm_id_new					INT,
	@ws_id						INT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@wsm_id_ori					INT,
			@wsm_id_sup_ori				INT,
			@wsm_id_new					INT


SELECT		@wsm_id_ori			=1,
			@wsm_id_sup_ori		=1,
			@wsm_id_new			=1

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	declare @wsm_id_sup_new int


	--2 con los datos del fetch leemos la tabla temporal para saber a que registro de los nuevos insertados se relaciona
	SELECT	@wsm_id_new				= ttwsm.wsm_id_new

	FROM	tbWebSite_Menu_tmp ttwsm

	WHERE	ttwsm.wsm_id_ori		= @wsm_id_ori
	AND		ttwsm.wsm_id_sup_ori	= @wsm_id_sup_ori


	--3 con id superior recuperamos a cuá se relaciona en la tabla temporal
	IF @wsm_id_sup_ori = 0

		SET @wsm_id_sup_new = 0

	ELSE

		SELECT	@wsm_id_sup_new			= isnull(ttwsm.wsm_id_new,0)

		FROM	tbWebSite_Menu_tmp ttwsm

		WHERE	ttwsm.wsm_id_ori		= @wsm_id_sup_ori



	--4 se actualiza el registro insertado con el id sup nuevo obtenido de la tabla temporal
	UPDATE	tbWebSite_Menu

	SET		wsm_id_sup	=	@wsm_id_sup_new

	WHERE	ws_id	= @ws_id
	AND		wsm_id	= @wsm_id_new





END
GO








