CREATE PROCEDURE [dbo].[spWebSite_MostViewedItems_updateData]
(
	@comp_id		INT,
	@ws_id			INT,
	@item_id		INT
)
AS
SET NOCOUNT on


BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE @comp_id INT,
		@ws_id INT,
		@item_id INT

SELECT	@comp_id = 1,
		@ws_id = 24,
		@item_id =256

*/

------------------------------------
------------------------------------



		IF EXISTS (SELECT 1 FROM tbWebSite_MostViewedItems twsmvi
				   WHERE twsmvi.comp_id = @comp_id
					AND twsmvi.ws_id = @ws_id
					AND twsmvi.item_id = @item_id)

				UPDATE	tbWebSite_MostViewedItems

				SET		mvi_count		= mvi_count + 1,
						mvi_lastupdated = GETDATE()

				WHERE	comp_id		= @comp_id
				AND		ws_id		= @ws_id
				AND		item_id		= @item_id


		ELSE

				INSERT INTO tbWebSite_MostViewedItems
				(
					comp_id,
					ws_id,
					item_id,
					mvi_count,
					mvi_lastupdated
				)
				VALUES
				(
					@comp_id,
					@ws_id,
					@item_id,
					1,
					GETDATE()
				)



--SELECT * FROM tbWebSite_MostViewedItems twsmvi


END
GO







CREATE PROCEDURE [dbo].[spWebSite_Names_cloneWebSite]
(
	@comp_id				INT,
	@ws_id_from				INT,
	@ws_id_to				INT,
	@ws_desc				NVARCHAR(100)
)
AS

SET NOCOUNT ON


------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE @comp_id		INT,
		@ws_id_from		INT,
		@ws_id_to		INT,
		@ws_desc		NVARCHAR(100)
SELECT	@comp_id		= 1,
		@ws_id_from		= 24,
		@ws_id_to		= 23,
		@ws_desc		= ''
*/

------------------------------------
------------------------------------


BEGIN TRANSACTION
BEGIN TRY



IF @ws_id_to = -1
BEGIN

	INSERT INTO tbWebSite_Names
	(
			comp_id,							ws_desc,								bra_id,
			ws_page_bgcolor_id,					ws_page_bgimage_url,					ws_bgcolor_id,
			ws_bordercolor_id,					ws_borderstyle_id,						ws_borderwidth_id,

			ws_prli_id,							ws_stor_id,								ws_showstock,
			ws_showpricelist,					ws_showzerostockitems,					ws_showcart,
			ws_email_contact,					[user_id],								ws_decimals4Stock,

			ws_decimals4Price,					ws_PotentialStockLimit,					prof_id,
			ws_startuphome,						ws_itemsformat,							ws_showpricewithtax,
			sd_id,								ws_menulevel,							ws_css,

			ws_datashowonitemtab,				ws_showCurrentAccountCustomer,			ws_griddesign_cells,
			ws_griddesign_rows,					ws_griddesign_cellpadding,				ws_griddesign_cellspacing,
			ws_griddesign_maxlength_desc,		ws_itemsformat_all,						ws_itemsformat_newness,

			ws_itemsformat_offer,				ws_change_back_to_fore_onbuttons,		ws_itemdetailformat_all,
			ws_itemdetailformat_newness,		ws_itemdetailformat_offer,				ws_notfound_image_url,
			ws_files2TempUpdated,				ws_maxitemsbyquery,						ws_showitemimageonMycart,

			ws_showcatimageonMenu,				ws_brand_griddesign_cells,				ws_brand_griddesign_rows,
			ws_brand_griddesign_cellpadding,	ws_brand_griddesign_cellspacing,		ws_brand_griddesign_maxlength_desc,

			ws_newclient_option,				ws_newclient_cust_id,					ws_newclient_checkpending,
			ws_newclient_emailcontact,			ws_newclient_phonecontact,				ws_newclient_defaultcountry
	)


	SELECT 	comp_id,							@ws_desc,								bra_id,
			ws_page_bgcolor_id,					ws_page_bgimage_url,					ws_bgcolor_id,
			ws_bordercolor_id,					ws_borderstyle_id,						ws_borderwidth_id,

			ws_prli_id,							ws_stor_id,								ws_showstock,
			ws_showpricelist,					ws_showzerostockitems,					ws_showcart,
			twsn.ws_email_contact,				twsn.[user_id],							twsn.ws_decimals4Stock,

			twsn.ws_decimals4Price,				twsn.ws_PotentialStockLimit,			twsn.prof_id,
			twsn.ws_startuphome,				twsn.ws_itemsformat,					twsn.ws_showpricewithtax,
			twsn.sd_id,							twsn.ws_menulevel,						twsn.ws_css,

			twsn.ws_datashowonitemtab,			twsn.ws_showCurrentAccountCustomer,		twsn.ws_griddesign_cells,
			twsn.ws_griddesign_rows,			twsn.ws_griddesign_cellpadding,			twsn.ws_griddesign_cellspacing,
			twsn.ws_griddesign_maxlength_desc,	twsn.ws_itemsformat_all,				twsn.ws_itemsformat_newness,

			twsn.ws_itemsformat_offer,			twsn.ws_change_back_to_fore_onbuttons,	twsn.ws_itemdetailformat_all,
			twsn.ws_itemdetailformat_newness,	twsn.ws_itemdetailformat_offer,			twsn.ws_notfound_image_url,
			twsn.ws_files2TempUpdated,			twsn.ws_maxitemsbyquery,				twsn.ws_showitemimageonMycart,

			twsn.ws_showcatimageonMenu,			twsn.ws_brand_griddesign_cells,			twsn.ws_brand_griddesign_rows,
			twsn.ws_brand_griddesign_cellpadding,twsn.ws_brand_griddesign_cellspacing,	twsn.ws_brand_griddesign_maxlength_desc,

			twsn.ws_newclient_option,			twsn.ws_newclient_cust_id,				twsn.ws_newclient_checkpending,
			twsn.ws_newclient_emailcontact,		twsn.ws_newclient_phonecontact,			twsn.ws_newclient_defaultcountry


	FROM	tbWebSite_Names twsn

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id_from


	SET @ws_id_to = @@IDENTITY

END

ELSE

BEGIN

	-- WS: Crear SP que haga esto en primer lugar

	DELETE FROM tbWebsite_menu
	WHERE	comp_id = @comp_id
	AND		ws_id	= @ws_id_to

	DELETE FROM tbWebSite_DetailData
	WHERE comp_id = @comp_id
	AND ws_id = @ws_id_to

	DELETE FROM tbWebSite_Detail
	WHERE comp_id = @comp_id
	AND ws_id = @ws_id_to


	DELETE FROM tbWebSite_Styles
	WHERE	comp_id		= @comp_id
	AND		ws_id		= @ws_id_to



	DELETE FROM tbWebSite_ParagraphComponentsControlsData
	WHERE	comp_id = @comp_id
	AND ws_id = @ws_id_to



	DELETE FROM tbWebSite_ParagraphComponentsRelation
	WHERE	comp_id		= @comp_id
	AND		ws_id		= @ws_id_to



	DELETE FROM tbWebSite_SectionParagraphRelation
	WHERE	comp_id		= @comp_id
	AND		ws_id		= @ws_id_to



	DELETE FROM tbWebSite_NameSectionsRelation
	WHERE	comp_id		= @comp_id
	AND		ws_id		= @ws_id_to



	DELETE FROM tbWebSite_Languages
	WHERE	comp_id		= @comp_id
	AND		ws_id		= @ws_id_to

	-- Hasta aca


		-- WS:2
	UPDATE tbWebSite_Names

	SET		bra_id					= twsn.bra_id,
			ws_page_bgcolor_id		= twsn.ws_page_bgcolor_id,
			ws_page_bgimage_url		= twsn.ws_page_bgimage_url,
			ws_bgcolor_id			= twsn.ws_bgcolor_id,
			ws_bordercolor_id		= twsn.ws_bordercolor_id,
			ws_borderstyle_id		= twsn.ws_borderstyle_id,
			ws_borderwidth_id		= twsn.ws_borderwidth_id,
			ws_prli_id				= twsn.ws_prli_id,
			ws_stor_id				= twsn.ws_stor_id,
			ws_showstock			= twsn.ws_showstock,
			ws_showpricelist		= twsn.ws_showpricelist,
			ws_showzerostockitems	= twsn.ws_showzerostockitems,
			ws_showcart				= twsn.ws_showcart,
			ws_email_contact		= twsn.ws_email_contact,
			[user_id]				= twsn.[user_id],
			ws_decimals4Stock		= twsn.ws_decimals4Stock,
			ws_decimals4Price		= twsn.ws_decimals4Price,
			ws_PotentialStockLimit	= twsn.ws_PotentialStockLimit,
			prof_id					= twsn.prof_id,
			ws_startuphome			= twsn.ws_startuphome,
			ws_itemsformat			= twsn.ws_itemsformat,
			ws_showpricewithtax		= twsn.ws_showpricewithtax,
			sd_id					= twsn.sd_id,
			ws_css					= twsn.ws_css,

			ws_menulevel			= twsn.ws_menulevel,

			ws_datashowonitemtab				= twsn.ws_datashowonitemtab,
			ws_showCurrentAccountCustomer		= twsn.ws_showCurrentAccountCustomer,
			ws_griddesign_cells					= twsn.ws_griddesign_cells,
			ws_griddesign_rows					= twsn.ws_griddesign_rows,
			ws_griddesign_cellpadding			= twsn.ws_griddesign_cellpadding,
			ws_griddesign_cellspacing			= twsn.ws_griddesign_cellspacing,
			ws_griddesign_maxlength_desc		= twsn.ws_griddesign_maxlength_desc,
			ws_itemsformat_all					= twsn.ws_itemsformat_all,
			ws_itemsformat_newness				= twsn.ws_itemsformat_newness,
			ws_itemsformat_offer				= twsn.ws_itemsformat_offer,
			ws_change_back_to_fore_onbuttons	= twsn.ws_change_back_to_fore_onbuttons,
			ws_itemdetailformat_all				= twsn.ws_itemdetailformat_all,
			ws_itemdetailformat_newness			= twsn.ws_itemdetailformat_newness,
			ws_itemdetailformat_offer			= twsn.ws_itemdetailformat_offer,
			ws_notfound_image_url				= twsn.ws_notfound_image_url,
			ws_files2TempUpdated				= twsn.ws_files2TempUpdated,
			ws_maxitemsbyquery					= twsn.ws_maxitemsbyquery,
			ws_showitemimageonMycart			= twsn.ws_showitemimageonMycart,

			ws_showcatimageonMenu				= twsn.ws_showcatimageonMenu,
			ws_brand_griddesign_cells			= twsn.ws_brand_griddesign_cells,
			ws_brand_griddesign_rows			= twsn.ws_brand_griddesign_rows,
			ws_brand_griddesign_cellpadding		= twsn.ws_brand_griddesign_cellpadding,
			ws_brand_griddesign_cellspacing		= twsn.ws_brand_griddesign_cellspacing,
			ws_brand_griddesign_maxlength_desc	= twsn.ws_brand_griddesign_maxlength_desc,

			ws_newclient_option					= twsn.ws_newclient_option,
			ws_newclient_cust_id				= twsn.ws_newclient_cust_id,
			ws_newclient_checkpending			= twsn.ws_newclient_checkpending,
			ws_newclient_emailcontact			= twsn.ws_newclient_emailcontact,
			ws_newclient_phonecontact			= twsn.ws_newclient_phonecontact,
			ws_newclient_defaultcountry			= twsn.ws_newclient_defaultcountry


	FROM	tbWebSite_Names						--twn
			INNER JOIN tbWebSite_Names			twsn
			ON	twsn.comp_id		= @comp_id
			AND twsn.ws_id			= @ws_id_from

	WHERE	tbWebSite_Names.comp_id		= @comp_id
	AND		tbWebSite_Names.ws_id		= @ws_id_to



END



	-- WS:3

INSERT INTO tbWebSite_NameSectionsRelation
(	comp_id,
	ws_id,
	wss_id,
	wssr_desc,
	wssr_order,wssr_image_url, wssr_image_repet
)
