FROM	tbWebSite_NameSectionsRelation twsnsr

WHERE	twsnsr.comp_id	= @comp_id
AND		twsnsr.ws_id	= @ws_id_from
--SELECT * FROM tbWebSite_NameSectionsRelation WHERE ws_id=@ws_id_to



	-- WS:4


INSERT INTO tbWebSite_SectionParagraphRelation
(		comp_id,
		ws_id,
		wss_id,
		wsp_id,
		wsspr_order,
		fb_id,		bs_id,			bw_id,
		bc_id,		color_id,		ff_id,
		fz_id,		fs_id,			td_id,
		fw_id,wsspr_image_url, wsspr_image_repet
)
SELECT	comp_id,
		@ws_id_to,
		wss_id,
		wsp_id,
		wsspr_order,
		fb_id,		bs_id,			bw_id,
		bc_id,		color_id,		ff_id,
		fz_id,		fs_id,			td_id, 			fw_id,
		twsspr.wsspr_image_url,
		twsspr.wsspr_image_repet

FROM	tbWebSite_SectionParagraphRelation twsspr

WHERE	twsspr.comp_id	= @comp_id
AND		twsspr.ws_id	= @ws_id_from
--SELECT * FROM tbWebSite_SectionParagraphRelation twsspr WHERE twsspr.ws_id = @ws_id_to




	-- WS:5

INSERT INTO tbWebSite_ParagraphComponentsRelation
(	comp_id,
	wsp_id,
	swsc_id,
	swsc_id_outputContainer,
	wspcr_order,
	wspcr_width,
	wspcr_height,
	wspcr_url,
	wspcr_text_wswi_id,
	ws_id, wspcr_newTable, wspcr_newRow, wspcr_newCell, wspcr_verticalLoad,wspcr_image_repet
)
SELECT	twspcr.comp_id,
		twspcr.wsp_id,
		twspcr.swsc_id,
		twspcr.swsc_id_outputContainer,
		twspcr.wspcr_order,
		twspcr.wspcr_width,
		twspcr.wspcr_height,
		twspcr.wspcr_url,
		twspcr.wspcr_text_wswi_id,
		@ws_id_to, twspcr.wspcr_newTable, twspcr.wspcr_newRow,
		twspcr.wspcr_newCell, twspcr.wspcr_verticalLoad,twspcr.wspcr_image_repet

FROM	tbWebSite_ParagraphComponentsRelation			twspcr

WHERE	twspcr.comp_id	= @comp_id
AND		twspcr.ws_id	= @ws_id_from
--SELECT * FROM tbWebSite_ParagraphComponentsRelation twspcr WHERE twspcr.ws_id = @ws_id_to



	-- WS:6


INSERT INTO tbWebSite_ParagraphComponentsControlsData
(	comp_id,
	wsplr_id,
	swsc_id,
	swscc_id,
	wspcc_image_url,
	wspcc_flash_url,
	wspcc_wswi_id,
	ws_id,
	wspcc_href,
	wspcc_height,
	wspcc_width,
	wspcc_image_repet,
	ith_id,
	wspcc_action
)
SELECT	twspccd.comp_id,
		twspcr2.wsplr_id,
		twspccd.swsc_id,
		twspccd.swscc_id,
      	twspccd.wspcc_image_url,
      	twspccd.wspcc_flash_url,
      	twspccd.wspcc_wswi_id,
		@ws_id_to,
		twspccd.wspcc_href,
		twspccd.wspcc_height,
		twspccd.wspcc_width,
		twspccd.wspcc_image_repet,
		twspccd.ith_id,
		twspccd.wspcc_action

FROM	tbWebSite_ParagraphComponentsControlsData			twspccd

		INNER JOIN tbWebSite_ParagraphComponentsRelation	twspcr
		ON	twspcr.comp_id		= twspccd.comp_id
		AND twspcr.wsplr_id		= twspccd.wsplr_id
		AND twspcr.ws_id		= @ws_id_from

		INNER JOIN tbWebSite_ParagraphComponentsRelation	twspcr2
		ON	twspcr2.comp_id								= twspcr.comp_id
		AND twspcr2.wsp_id								= twspcr.wsp_id
		AND twspcr2.swsc_id								= twspcr.swsc_id
		AND twspcr2.wspcr_order							= twspcr.wspcr_order
		AND isnull(twspcr2.swsc_id_outputContainer,-1)	= isnull(twspcr.swsc_id_outputContainer,-1)
		AND twspcr2.wspcr_width							= twspcr.wspcr_width
		AND twspcr2.wspcr_height						= twspcr.wspcr_height
		AND isnull(twspcr2.wspcr_url,'')				= isnull(twspcr.wspcr_url,'')
		AND isnull(twspcr2.wspcr_text_wswi_id,-1)		= isnull(twspcr.wspcr_text_wswi_id,-1)
		AND twspcr2.ws_id								= @ws_id_to

WHERE	twspccd.comp_id		= @comp_id
AND		twspccd.ws_id		= @ws_id_from



	-- WS:7


INSERT INTO tbWebSite_Styles
(
	comp_id,	ws_id,		swsc_id,	swscc_id,
	fb_id,		color_id,	ff_id,		fs_id,
	td_id,		fw_id,		fz_id,		bc_id,
	wsst_url,	bs_id,		bw_id,		border_type
)
SELECT
	comp_id,	@ws_id_to,	swsc_id,	swscc_id,
	fb_id,		color_id,	ff_id,		fs_id,
	td_id,		fw_id,		fz_id,		bc_id,
	wsst_url,	bs_id,		bw_id,		border_type

FROM	tbWebSite_Styles		twss

WHERE	twss.comp_id	= @comp_id
AND		twss.ws_id		= @ws_id_from
--SELECT * FROM tbWebSite_Styles twss WHERE twss.ws_id = @ws_id_to




	-- WS:8


INSERT INTO tbWebSite_Languages
(
	comp_id,
	ws_id,
	lang_id,
	wslang_enabled,
	wslang_url,
	wslang_default
)
SELECT	twsl.comp_id,
		@ws_id_to,
		twsl.lang_id,
		twsl.wslang_enabled,
      	twsl.wslang_url,
      	twsl.wslang_default

FROM	tbWebSite_Languages twsl

WHERE	twsl.comp_id	= @comp_id
AND		twsl.ws_id		= @ws_id_from



	-- WS:9 y demas....

DECLARE @wsdet_id		INT
DECLARE @wsdet_id_to	INT


DECLARE csr_items_detail CURSOR FOR
SELECT	twsd.wsdet_id
FROM	tbWebSite_Detail twsd
WHERE	twsd.comp_id	= @comp_id
AND		twsd.ws_id		= @ws_id_from



OPEN csr_items_detail

FETCH csr_items_detail INTO @wsdet_id


WHILE @@FETCH_STATUS = 0
BEGIN

	INSERT INTO tbWebSite_Detail
	(
		comp_id,
		ws_id,
		-- wsdet_id -- this column value is auto-generated,
		wsdet_desc,
		wsdet_disabled,
		wsdet_width,
		wsdet_cellspacing,
		wsdet_cellpadding,
		wsdet_image_url,
		wsdet_image_repet
	)
	SELECT twsd.comp_id, @ws_id_to, twsd.wsdet_desc, twsd.wsdet_disabled,
	       twsd.wsdet_width, twsd.wsdet_cellspacing, twsd.wsdet_cellpadding,
	       twsd.wsdet_image_url, twsd.wsdet_image_repet
	FROM tbWebSite_Detail twsd
	WHERE twsd.comp_id = @comp_id
	AND twsd.ws_id = @ws_id_from
	AND twsd.wsdet_id = @wsdet_id

	SET @wsdet_id_to = @@IDENTITY



	INSERT INTO tbWebSite_DetailData
	(
		comp_id,
		ws_id,
		wsdet_id,
		-- wsdat_id -- this column value is auto-generated,
		wsdat_order,
		wsdat_data1,
		wsdat_data2,
		wsdat_image_url,
		optval_id,
		wsdat_image_order,
		wsdat_wswi_id,
		wsdat_height,
		wsdat_width,
		wsdat_newTable, wsdat_newRow, wsdat_newCell,
		wsdat_verticalLoad, wsdat_colspan, wsdat_rowspan
	)
	SELECT twsdd.comp_id, @ws_id_to,
			@wsdet_id_to, twsdd.wsdat_order,
	       twsdd.wsdat_data1, twsdd.wsdat_data2, twsdd.wsdat_image_url,
	       twsdd.optval_id, twsdd.wsdat_image_order, twsdd.wsdat_wswi_id,
	       twsdd.wsdat_height, twsdd.wsdat_width,
	       twsdd.wsdat_newTable,
	       twsdd.wsdat_newRow, twsdd.wsdat_newCell, twsdd.wsdat_verticalLoad,
	       twsdd.wsdat_colspan, twsdd.wsdat_rowspan

	FROM	tbWebSite_DetailData twsdd

	WHERE	twsdd.comp_id	= @comp_id
	AND		twsdd.ws_id		= @ws_id_to
	AND		twsdd.wsdet_id	= @wsdet_id



	FETCH csr_items_detail INTO @wsdet_id

END


CLOSE csr_items_detail
DEALLOCATE csr_items_detail





	----------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @wsm_id				INT
	DECLARE @wsm_id_new			INT
	DECLARE @wsm_id_sup			INT
	DECLARE @wsm_id_sup_new		INT


	DECLARE @tbl_tbWebSite_Menu AS TABLE (wsm_id_ori INT, wsm_id_sup_ori INT, wsm_id_new INT)


	DECLARE cursor_tbWebSite_Menu CURSOR FOR
	SELECT	twss.wsm_id, twss.wsm_id_sup
	FROM	tbWebSite_Menu twss
	WHERE	twss.comp_id	= @comp_id
	AND		twss.ws_id		= @ws_id_from

	ORDER BY twss.wsm_id_sup, twss.wsm_order, twss.wsm_id


	OPEN	cursor_tbWebSite_Menu


	FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup



	WHILE @@FETCH_STATUS = 0
	BEGIN



		INSERT INTO tbWebSite_Menu
			(
				comp_id,			ws_id,				wsm_id_sup,
				wsm_order,			wsm_desc,			wsm_link,
				wsm_detail1,		wsm_detail2,		wsm_detail3,		wsm_detail4,
				wsm_startup,		wsm_action
			)
		SELECT	twsm.comp_id,		@ws_id_to,			NULL,
				twsm.wsm_order,		twsm.wsm_desc,		twsm.wsm_link,
				twsm.wsm_detail1,	twsm.wsm_detail2,	twsm.wsm_detail3,	twsm.wsm_detail4,
				twsm.wsm_startup,	twsm.wsm_action
		FROM	tbWebSite_Menu	twsm
		WHERE	twsm.comp_id	= @comp_id
		AND		twsm.ws_id		= @ws_id_from
		AND		twsm.wsm_id		= @wsm_id


		SET @wsm_id_new = @@IDENTITY


		INSERT INTO @tbl_tbWebSite_Menu
				(wsm_id_ori,	wsm_id_sup_ori,		wsm_id_new)
		VALUES	(@wsm_id,		@wsm_id_sup,		@wsm_id_new)


		FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup


	END

	CLOSE		cursor_tbWebSite_Menu
	DEALLOCATE	cursor_tbWebSite_Menu








	DECLARE cursor_tbWebSite_Menu CURSOR FOR
	SELECT	twss.wsm_id, twss.wsm_id_sup
	FROM	tbWebSite_Menu twss
	WHERE	twss.comp_id	= @comp_id
	AND		twss.ws_id		= @ws_id_from

	ORDER BY twss.wsm_id_sup, twss.wsm_order, twss.wsm_id



	OPEN	cursor_tbWebSite_Menu


	FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup



	WHILE @@FETCH_STATUS = 0
	BEGIN

		--1 leemos el original con el fetch


		--2 con los datos del fetch leemos la tabla temporal para saber a que registro de los nuevos insertados se relaciona
		SELECT	@wsm_id_new				= ttwsm.wsm_id_new

		FROM	@tbl_tbWebSite_Menu ttwsm

		WHERE	ttwsm.wsm_id_ori		= @wsm_id
		AND		ttwsm.wsm_id_sup_ori	= @wsm_id_sup


		--3 con id superior recuperamos a cuá se relaciona en la tabla temporal
		IF @wsm_id_sup = 0

			SET @wsm_id_sup_new = 0

		ELSE

			SELECT	@wsm_id_sup_new			= isnull(ttwsm.wsm_id_new,0)

			FROM	@tbl_tbWebSite_Menu ttwsm

			WHERE	ttwsm.wsm_id_ori		= @wsm_id_sup





		--4 se actualiza el registro insertado con el id sup nuevo obtenido de la tabla temporal
		UPDATE	tbWebSite_Menu

		SET		wsm_id_sup	=	@wsm_id_sup_new

		WHERE	comp_id	= @comp_id
		AND		ws_id	= @ws_id_to
		AND		wsm_id	= @wsm_id_new




		FETCH	cursor_tbWebSite_Menu INTO @wsm_id, @wsm_id_sup


	END

	CLOSE		cursor_tbWebSite_Menu
	DEALLOCATE	cursor_tbWebSite_Menu
	----------------------------------------------------------------------------------------------------------------------------------


	-- FINAL:!!!
	-- WS:   hacer un INSERT si no existe por nombre de archivo y sino un UPDATE (ws_fileName)  (En Update solo los 3 ultimos campos.)
	--dbo.tbWebSite_Files



	COMMIT TRANSACTION


END
TRY BEGIN CATCH
	ROLLBACK TRANSACTION
	--SELECT	ERROR_LINE(), ERROR_MESSAGE()
END CATCH




GO








