CREATE PROCEDURE [dbo].[spWebSite_Names_CloneWebSite_DeleteData]
(

	@ws_id_to				INT

)
AS
SET NOCOUNT ON


BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

	DECLARE		@ws_id_to			INT

	SELECT		@ws_id_to			= 21

*/

-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	DELETE FROM tbWebsite_menu
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebsite_menu_tmp

	DELETE FROM tbWebSite_Detail
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_DetailData
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_Styles
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_ParagraphComponentsControlsData
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_ParagraphComponentsRelation
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_SectionParagraphRelation
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_NameSectionsRelation
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_Languages
	WHERE	ws_id	= @ws_id_to

--	DELETE FROM tbWebSite_Contacts
--	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_MostViewedItems
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_Cat_Subcat_Disabled
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_ItemLeading
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_ItemRotatorDetail
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_ItemRotatorHeader
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_SectionParagraphRelationHidden
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_SectionParagraphRelationStyles
	WHERE	ws_id	= @ws_id_to




	----------------------------------
	--NO TIENEN WS_ID
	----------------------------------


	--tbWebSite_Colors
	--
	--tbWebSite_ComponentsExclusion
	--
	--tbWebSite_Files
	--
	--tbWebSite_Paragraph
	--
	--tbWebSite_Section
	--
	--tbWebSite_WordsIni
	--
	--tbWebSite_WordsNew


	----------------------------------
	----------------------------------

END
GO








------------------------------------------------
------------------------------------------------
-- Leer todas las tablas con el website original
-- GA
------------------------------------------------
------------------------------------------------


CREATE PROCEDURE [dbo].[spWebSite_Names_CloneWebSite_GetData]
(

	@ws_id_from				INT

)
AS
SET NOCOUNT ON


BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

	DECLARE		@ws_id_from			INT

	SELECT		@ws_id_from			= 30

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


			----------------------------------------------------------------
			--tbWebSite_Cat_Subcat_Disabled
			----------------------------------------------------------------

			SELECT  isnull(twscsd.comp_id,-1)						[comp_id],
					isnull(twscsd.ws_id,-1 )						[ws_id],
					isnull(twscsd.cat_subcat_id,-1 )				[cat_subcat_id],
					isnull(twscsd.cat_id,-1)						[cat_id],
					isnull(twscsd.subcat_id,-1)						[subcat_id]

			FROM tbWebSite_Cat_Subcat_Disabled						twscsd

			WHERE twscsd.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Colors
			----------------------------------------------------------------

			SELECT  isnull(twsc.color_id,-1)						[color_id],
					isnull(twsc.color_desc,'')						[color_desc],
					isnull(twsc.color_value,'')						[color_value]

			FROM tbWebSite_Colors									twsc

			----------------------------------------------------------------
			--tbWebSite_ComponentsExclusion
			----------------------------------------------------------------

			SELECT	isnull(twsce.comp_id,-1)						[comp_id],
					isnull(twsce.swsc_id,-1)						[swsc_id],
					isnull(twsce.swsc_id_outputContainer,-1)		[swsc_id_outputContainer],
					isnull(twsce.wsp_id, -1)						[wsp_id],
					isnull(twsce.swsc_id_ExcludeFromParagraph ,-1)	[swsc_id_ExcludeFromParagraph]

			FROM tbWebSite_ComponentsExclusion						twsce


			----------------------------------------------------------------
			--tbWebSite_Contacts
			----------------------------------------------------------------

			SELECT	isnull(twsc.comp_id,-1)							[comp_id],
					isnull(twsc.wsc_id, -1)							[wsc_id],
					isnull(twsc.wsc_name, '')						[wsc_name],
					isnull(twsc.wsc_address,'')						[wsc_address],
					isnull(twsc.wsc_city,'')						[wsc_city],
					isnull(twsc.wsc_state,'')						[wsc_state],
					isnull(twsc.wsc_country,'')					    [wsc_country],
					isnull(twsc.wsc_zip,'')							[wsc_zip],
					isnull(twsc.wsc_phone,'')						[wsc_phone],
					isnull(twsc.wsc_email,'')						[wsc_email],
					isnull(twsc.wsc_business,'')					[wsc_business],
					isnull(twsc.wsc_message,'')						[wsc_message],
					isnull(twsc.wsc_cd,'')							[wsc_cd],
					twsc.ws_id

			FROM tbWebSite_Contacts									twsc

			--WHERE twsc.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Detail
			----------------------------------------------------------------

			SELECT	isnull(twsd.comp_id,-1)							[comp_id],
					twsd.ws_id,
					isnull(twsd.wsdet_id,-1)						[wsdet_id],
					isnull(twsd.wsdet_desc,'')						[wsdet_desc],
					isnull(twsd.wsdet_disabled, 'false')			[wsdet_disabled],
					isnull(twsd.wsdet_width,0)						[wsdet_width],
					isnull(twsd.wsdet_cellspacing,0)				[wsdet_cellspacing],
					isnull(twsd.wsdet_cellpadding,0)				[wsdet_cellpadding],
					isnull(twsd.wsdet_image_url,'')					[wsdet_image_url],
					isnull(twsd.wsdet_image_repet, -1)				[wsdet_image_repet]

			FROM tbWebSite_Detail									twsd

			WHERE twsd.ws_id = @ws_id_from


			----------------------------------------------------------------
			--tbWebSite_DetailData
			----------------------------------------------------------------

			SELECT	isnull(twsdd.comp_id, -1)						[comp_id],
					twsdd.ws_id,
					isnull(twsdd.wsdet_id, -1)						[wsdet_id],
					isnull(twsdd.wsdat_id,-1)						[wsdat_id],
					isnull(twsdd.wsdat_order,0)						[wsdat_order],
					isnull(twsdd.wsdat_data1,'')					[wsdat_data1],
					isnull(twsdd.wsdat_data2,'')					[wsdat_data2],
					isnull(twsdd.wsdat_image_url,'')				[wsdat_image_url],
					isnull(twsdd.optval_id,-1)						[optval_id],
					isnull(twsdd.wsdat_image_order,0)				[wsdat_image_order],
					isnull(twsdd.wsdat_wswi_id, -1)					[wsdat_wswi_id],
					isnull(twsdd.wsdat_height,0)					[wsdat_height],
					isnull(twsdd.wsdat_width,0)					[wsdat_width],
					isnull(twsdd.wsdat_newTable,'false')			[wsdat_newTable],
					isnull(twsdd.wsdat_newRow,'false')				[wsdat_newRow],
					isnull(twsdd.wsdat_newCell,'false')				[wsdat_newCell],
					isnull(twsdd.wsdat_verticalLoad, 'false')		[wsdat_verticalLoad],
					isnull(twsdd.wsdat_colspan,0)					[wsdat_colspan],
					isnull(twsdd.wsdat_rowspan,0)					[wsdat_rowspan],
					isnull(twsdd.wsdat_disabled ,'false')			[wsdat_disabled]

			FROM tbWebSite_DetailData								twsdd

			WHERE twsdd.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Files
			----------------------------------------------------------------

			SELECT  twsf.ws_fileId,
					isnull(twsf.ws_fileName,'')						[ws_fileName],
					twsf.ws_fileContent,
					isnull(twsf.ws_code,-1)							[ws_code],
					isnull(twsf.ws_fileLength,0)					[ws_fileLength]

			FROM tbWebSite_Files									twsf

			----------------------------------------------------------------
			--tbWebSite_ItemLeading
			----------------------------------------------------------------

			SELECT	twsil.comp_id,
					isnull(twsil.item_id,-1)						[item_id],
					isnull(twsil.ddc_id,-1)							[ddc_id],
					twsil.ws_id,
					isnull(twsil.ddc_Order ,0)						[ddc_Order]

			FROM tbWebSite_ItemLeading								twsil

			WHERE twsil.ws_id = @ws_id_from

			--------------------------------------------------------
			--tbWebSite_ItemRotatorDetail
			--------------------------------------------------------

			SELECT	twsird.comp_id,
					isnull(twsird.ith_id, -1)					[ith_id],
					isnull(twsird.itd_id,-1)					[itd_id],
					twsird.ws_id,
					isnull(twsird.item_id,-1)				    [item_id],
					isnull(twsird.itimg_order,0)				[itimg_order],
					isnull(twsird.itd_order,0)					[itd_order],
					isnull(twsird.itd_backcolor, -1)			[itd_backcolor],
					isnull(twsird.itd_forecolor_item_desc,-1)	[itd_forecolor_item_desc],
					isnull(twsird.itd_forecolor_item_detail,-1) [itd_forecolor_item_detail],
					isnull(twsird.itd_backcolor_item_price, -1) [itd_backcolor_item_price],
					isnull(twsird.itd_timeout,0)				[itd_timeout],
					isnull(twsird.itd_lastupdate,'')			[itd_lastupdate]

			FROM tbWebSite_ItemRotatorDetail						twsird

			WHERE twsird.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_ItemRotatorHeader
			----------------------------------------------------------------

			SELECT	twsirh.comp_id,
					isnull(twsirh.ith_id,-1)						[ith_id],
					isnull(twsirh.ith_desc,'')						[ith_desc],
					twsirh.ws_id,
					isnull(twsirh.ith_lastupdate,'')				[ith_lastupdate],
					isnull(twsirh.ith_timeout,0)					[ith_timeout],
					isnull(twsirh.ith_maxlengthitemdesc,0)			[ith_maxlengthitemdesc],
					isnull(twsirh.ith_dataorigin,-1)				[ith_dataorigin],
					isnull(twsirh.ith_maxitemqty,0)					[ith_maxitemqty]

			FROM tbWebSite_ItemRotatorHeader						twsirh

			WHERE twsirh.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Languages
			----------------------------------------------------------------

			SELECT  isnull(twsl.comp_id,-1)							[comp_id],
					isnull(twsl.ws_id,-1)							[ws_id],
					isnull(twsl.lang_id,-1)							[lang_id],
					isnull(twsl.wslang_enabled,'false')				[wslang_enabled],
					isnull(twsl.wslang_url,'')						[wslang_url],
					isnull(twsl.wslang_default ,'false')			[wslang_default]

			FROM tbWebSite_Languages								twsl

			WHERE twsl.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Menu
			----------------------------------------------------------------

			select	isnull(twsm.comp_id, -1)						[comp_id],
					twsm.ws_id,
					isnull(twsm.wsm_id,-1)							[wsm_id],
					isnull(twsm.wsm_id_sup,-1)						[wsm_id_sup],
					isnull(twsm.wsm_order, 0)						[wsm_order],
					isnull(twsm.wsm_desc,'')						[wsm_desc],
					isnull(twsm.wsm_link,'')						[wsm_link],
					isnull(twsm.wsm_detail1,'')						[wsm_detail1],
					isnull(twsm.wsm_detail2, '')					[wsm_detail2],
					isnull(twsm.wsm_detail3,'')						[wsm_detail3],
					isnull(twsm.wsm_detail4,'')						[wsm_detail4],
					isnull(twsm.wsm_startup, 'false')				[wsm_startup],
					isnull(twsm.wsm_action, -1)						[wsm_action],
					isnull(twsm.wsm_css,'')							[wsm_css],
					isnull(twsm.wsm_disabled ,'false')				[wsm_disabled]

			from tbWebSite_Menu										twsm

			where twsm.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_MostViewedItems
			----------------------------------------------------------------

			select	isnull(twsmvi.comp_id,-1)						[comp_id],
					isnull(twsmvi.ws_id,-1)							[ws_id],
					isnull(twsmvi.item_id, -1)						[item_id],
					isnull(twsmvi.mvi_count,-1)						[mvi_count],
					isnull(twsmvi.mvi_lastupdated ,'')			    [mvi_lastupdated]

			from tbWebSite_MostViewedItems							twsmvi

			where twsmvi.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_NameSectionsRelation
			----------------------------------------------------------------

			select	isnull(twsnsr.comp_id,-1)						[comp_id],
					isnull(twsnsr.wssrl_id,-1)						[wssrl_id],
					isnull(twsnsr.ws_id, -1)						[ws_id],
					isnull(twsnsr.wss_id,-1)						[wss_id],
					isnull(twsnsr.wssr_desc, '')					[wssr_desc],
					isnull(twsnsr.wssr_order,0)						[wssr_order],
					isnull(twsnsr.wssr_image_url,'')				[wssr_image_url],
					isnull(twsnsr.wssr_image_repet, -1)				[wssr_image_repet]

			from tbWebSite_NameSectionsRelation						twsnsr

			where twsnsr.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Paragraph
			----------------------------------------------------------------

			select	isnull(twsp.comp_id, -1)						[comp_id],
					isnull(twsp.wsp_id, -1)							[wsp_id],
					isnull(twsp.wsp_desc,'')						[wsp_desc],
					isnull(twsp.wsp_width,0)						[wsp_width],
					isnull(twsp.wsp_align,-1)						[wsp_align],
					isnull(twsp.wsp_inUpdatePanel,'false')			[wsp_inUpdatePanel],
					isnull(twsp.wsp_columnspan,0)					[wsp_columnspan],
					isnull(twsp.wsp_load_orientation_id,'false')	[wsp_load_orientation_id],
					isnull(twsp.wsp_rowspan,0)						[wsp_rowspan]

			from tbWebSite_Paragraph								twsp

			----------------------------------------------------------------
			--tbWebSite_ParagraphComponentsControlsData
			----------------------------------------------------------------

			select	isnull(twspccd.comp_id,-1)			[comp_id],
					isnull(twspccd.wspcc_id,-1)	[wspcc_id],
					isnull(twspccd.wsplr_id,-1)	[wsplr_id],
					isnull(twspccd.swsc_id,-1)	[swsc_id],
					isnull(twspccd.swscc_id,-1)	[swscc_id],
					isnull(twspccd.wspcc_image_url,'')	[wspcc_image_url],
					isnull(twspccd.wspcc_flash_url,'')	[wspcc_flash_url],
					isnull(twspccd.wspcc_wswi_id,-1)	[wspcc_wswi_id],
					twspccd.ws_id,
					isnull(twspccd.wspcc_href,'')	[wspcc_href],
					isnull(twspccd.wspcc_height,0)	[wspcc_height],
					isnull(twspccd.wspcc_width,0)	[wspcc_width],
					isnull(twspccd.wspcc_image_repet,-1)	[wspcc_image_repet],
					isnull(twspccd.ith_id,-1)	[ith_id],
					isnull(twspccd.wspcc_action,-1)	[wspcc_action],
					isnull(twspccd.wspcc_disabled,'false')	[wspcc_disabled]

			from tbWebSite_ParagraphComponentsControlsData			twspccd

			where twspccd.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_ParagraphComponentsRelation
			----------------------------------------------------------------

			select	isnull(comp_id,-1)								[comp_id],
					isnull(wsplr_id ,-1)							[wsplr_id],
					isnull(wsp_id,-1)								[wsp_id],
					isnull(swsc_id,-1)								[swsc_id],
					isnull(swsc_id_outputContainer,-1)				[swsc_id_outputContainer],
					isnull(wspcr_order,0)							[wspcr_order],
					isnull(wspcr_width,0)							[wspcr_width],
					isnull(wspcr_height,0)							[wspcr_height],
					isnull(wspcr_url,'')							[wspcr_url],
					isnull(wspcr_text_wswi_id,-1)					[wspcr_text_wswi_id],
					ws_id,
					CASE
						WHEN wspcr_newTable IS NULL THEN -1
						ELSE wspcr_newTable
					END												[wspcr_newTable],
					isnull(wspcr_newRow,'false')					[wspcr_newRow],
					isnull(wspcr_newCell,'false')					[wspcr_newCell],
					isnull(wspcr_verticalLoad,'false')				[wspcr_verticalLoad],
					isnull(wspcr_image_repet,-1)					[wspcr_image_repet],
					isnull(wspcr_disabled,'false')					[wspcr_disabled]


			from tbWebSite_ParagraphComponentsRelation				twspcr

			where twspcr.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Section
			----------------------------------------------------------------

			select	isnull(twss.comp_id,-1)							[comp_id],
					twss.wss_id										[wss_id],
					isnull(twss.wss_desc, '')						[wss_desc],
					isnull(twss.sws_id ,-1)							[sws_id]

			from tbWebSite_Section									twss

			----------------------------------------------------------------
			--tbWebSite_SectionParagraphRelation
			----------------------------------------------------------------

			select  isnull(comp_id,-1)							[comp_id],
					ws_id,
					isnull(wss_id,-1)							[wss_id],
					isnull(wsp_id,-1)							[wsp_id],
					isnull(wsspr_id,-1)							[wsspr_id],
					isnull(wsspr_order,-1)						[wsspr_order],
					isnull(fb_id,-1)							[fb_id],
					isnull(bs_id,-1)							[bs_id],
					isnull(bw_id,-1)							[bw_id],
					isnull(bc_id,-1)							[bc_id],
					isnull(color_id,-1)							[color_id],
					isnull(ff_id,-1)							[ff_id],
					isnull(fz_id,-1)							[fz_id],
					isnull(fs_id,-1)							[fs_id],
					isnull(td_id,-1)							[td_id],
					isnull(fw_id,-1)							[fw_id],
					isnull(wsspr_image_url,'')					[wsspr_image_url],
					isnull(wsspr_image_repet,-1)				[wsspr_image_repet]

			from tbWebSite_SectionParagraphRelation					twsspr

			where twsspr.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_SectionParagraphRelationHidden
			----------------------------------------------------------------

			select	isnull(comp_id,-1)								[comp_id],
					isnull(wsspr_id,-1)								[wsspr_id],
					isnull(wssprh_id ,-1)							[wssprh_id],
					isnull(wssprh_action,-1)						[wssprh_action],
					ws_id

			from tbWebSite_SectionParagraphRelationHidden			twssprh

			where twssprh.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_SectionParagraphRelationStyles
			----------------------------------------------------------------

			select  isnull(twssprs.comp_id,-1)						[comp_id],
					twssprs.ws_id,
					isnull(twssprs.wsspr_id,-1)						[wsspr_id],
					isnull(twssprs.fb_id,-1)						[fb_id],
					isnull(twssprs.color_id, -1)					[color_id],
					isnull(twssprs.ff_id,-1)						[ff_id],
					isnull(twssprs.fs_id,-1)						[fs_id],
					isnull(twssprs.td_id,-1)						[td_id],
					isnull(twssprs.fw_id,-1)						[fw_id],
					isnull(twssprs.fz_id,-1)						[fz_id],
					isnull(twssprs.bc_id,-1)						[bc_id],
					isnull(twssprs.wsst_url,'')						[wsst_url],
					isnull(twssprs.bs_id, -1)						[bs_id],
					isnull(twssprs.bw_id,-1)						[bw_id]

			from tbWebSite_SectionParagraphRelationStyles			twssprs

			where twssprs.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_Styles
			----------------------------------------------------------------

			select	isnull(twss.comp_id,-1)							[comp_id],
					twss.ws_id,
					isnull(twss.swsc_id, -1)						[swsc_id],
					isnull(twss.swscc_id,-1)						[swscc_id],
					isnull(twss.fb_id, -1)							[fb_id],
					isnull(twss.color_id,-1)						[color_id],
					isnull(twss.ff_id,-1)							[ff_id],
					isnull(twss.fs_id, -1)							[fs_id],
					isnull(twss.td_id,-1)							[td_id],
					isnull(twss.fw_id, -1)							[fw_id],
					isnull(twss.fz_id, -1)							[fz_id],
					isnull(twss.bc_id,-1)							[bc_id],
					isnull(twss.wsst_url,'')						[wsst_url],
					isnull(twss.bs_id,-1)							[bs_id],
					isnull(twss.bw_id,-1)							[bw_id],
					isnull(twss.border_type, -1)					[border_type]

			from tbWebSite_Styles									twss

			where twss.ws_id = @ws_id_from

			----------------------------------------------------------------
			--tbWebSite_WordsIni
			----------------------------------------------------------------

			select	isnull(twswi.wswi_id,-1)						[wswi_id],
					isnull(twswi.wswi_enabled,'false')				[wswi_enabled]

			from tbWebSite_WordsIni									twswi

			----------------------------------------------------------------
			--tbWebSite_WordsNew
			----------------------------------------------------------------

			select	isnull(twswn.lang_id, -1)						[lang_id],
					isnull(twswn.wswi_id,-1)						[wswi_id],
					isnull(twswn.wswn_desc,'')						[wswn_desc]

			from tbWebSite_WordsNew									twswn


			----------------------------------------------------------------
			--tbWebSite_Names
			----------------------------------------------------------------

			SELECT  twsn.ws_id,
					isnull(twsn.ws_desc,'')									[ws_desc],
					isnull(twsn.bra_id,-1)                                  [bra_id],
					isnull(twsn.ws_page_bgcolor_id,-1)						[ws_page_bgcolor_id],
					isnull(twsn.ws_page_bgimage_url,'')						[ws_page_bgimage_url] ,
					isnull(twsn.ws_bgcolor_id,-1)							[ws_bgcolor_id] ,
					isnull(twsn.ws_bordercolor_id,-1)						[ws_bordercolor_id] ,
					isnull(twsn.ws_borderstyle_id,-1)					    [ws_borderstyle_id] ,
					isnull(twsn.ws_borderwidth_id,-1)						[ws_borderwidth_id] ,
					isnull(twsn.ws_prli_id,-1)								[ws_prli_id] ,
					isnull(twsn.ws_stor_id,-1)								[ws_stor_id] ,
					isnull(twsn.ws_showstock,-1)							[ws_showstock] ,
					isnull(twsn.ws_showpricelist,' ')						[ws_showpricelist] ,
					ISNULL(twsn.ws_showzerostockitems,'false')				[ws_showzerostockitems],
					ISNULL(twsn.ws_showcart,'false')						[ws_showcart],
					isnull(twsn.ws_email_contact,' ')						[ws_email_contact] ,
					isnull(twsn.[user_id],-1)								[user_id] ,
					isnull(twsn.ws_decimals4Stock,-1)						[ws_decimals4Stock] ,
					isnull(twsn.ws_decimals4Price,-1)						[ws_decimals4Price] ,
					isnull(twsn.ws_PotentialStockLimit,-1)					[ws_PotentialStockLimit] ,
					isnull(twsn.prof_id,-1)									[prof_id] ,
					isnull(twsn.ws_startuphome,-1)							[ws_startuphome] ,
					isnull(twsn.ws_itemsformat,-1)							[ws_itemsformat] ,
					ISNULL(twsn.ws_showpricewithtax,'false')				[ws_showpricewithtax] ,
					isnull(twsn.ws_menulevel,-1)							[ws_menulevel] ,
					isnull(twsn.ws_css,' ')									[ws_css] ,
					isnull(twsn.sd_id,-1)									[sd_id] ,
					isnull(twsn.ws_datashowonitemtab,-1)					[ws_datashowonitemtab] ,
					ISNULL(twsn.ws_showCurrentAccountCustomer,'false')		[ws_showCurrentAccountCustomer] ,
					isnull(twsn.ws_griddesign_cells,-1)						[ws_griddesign_cells] ,
					isnull(twsn.ws_griddesign_rows,-1)						[ws_griddesign_rows] ,
					isnull(twsn.ws_griddesign_cellpadding,-1)				[ws_griddesign_cellpadding] ,
					isnull(twsn.ws_griddesign_cellspacing,-1)				[ws_griddesign_cellspacing] ,
					isnull(twsn.ws_griddesign_maxlength_desc,-1)			[ws_griddesign_maxlength_desc] ,
					isnull(twsn.ws_itemsformat_all,0)						[ws_itemsformat_all] ,
					isnull(twsn.ws_itemsformat_newness,0)					[ws_itemsformat_newness] ,
					isnull(twsn.ws_itemsformat_offer,0)						[ws_itemsformat_offer] ,
					ISNULL(twsn.ws_change_back_to_fore_onbuttons,'false')	[ws_change_back_to_fore_onbuttons],
					isnull(twsn.ws_itemdetailformat_all,-1)					[ws_itemdetailformat_all] ,
					isnull(twsn.ws_itemdetailformat_newness,-1)				[ws_itemdetailformat_newness] ,
					isnull(twsn.ws_itemdetailformat_offer,-1)				[ws_itemdetailformat_offer] ,
					isnull(twsn.ws_notfound_image_url,' ')					[ws_notfound_image_url] ,
					ISNULL(twsn.ws_files2TempUpdated,'false')				[ws_files2TempUpdated],
					isnull(twsn.ws_maxitemsbyquery,-1)						[ws_maxitemsbyquery] ,
					ISNULL(twsn.ws_showitemimageonMycart,'false')			[ws_showitemimageonMycart],
					ISNULL(twsn.ws_showcatimageonMenu ,'false')				[ws_showcatimageonMenu],
					isnull(twsn.ws_brand_griddesign_cells,-1)				[ws_brand_griddesign_cells] ,
					isnull(twsn.ws_brand_griddesign_rows,-1)				[ws_brand_griddesign_rows] ,
					isnull(twsn.ws_brand_griddesign_cellpadding,0)			[ws_brand_griddesign_cellpadding] ,
					isnull(twsn.ws_brand_griddesign_cellspacing,0)			[ws_brand_griddesign_cellspacing] ,
					isnull(twsn.ws_brand_griddesign_maxlength_desc,50)		[ws_brand_griddesign_maxlength_desc] ,
					ISNULL(twsn.ws_newclient_enable,'false')				[ws_newclient_enable] ,
					isnull(twsn.ws_newclient_cust_id,-1)					[ws_newclient_cust_id] ,
					ISNULL(twsn.ws_newclient_checkpending ,'false')			[ws_newclient_checkpending],
					isnull(twsn.ws_newclient_emailcontact,' ')				[ws_newclient_emailcontact] ,
					isnull(twsn.ws_newclient_phonecontact,' ')				[ws_newclient_phonecontact] ,
					isnull(twsn.ws_newclient_defaultcountry,-1)				[ws_newclient_defaultcountry] ,
					isnull(twsn.ws_newclient_welcometext,' ')				[ws_newclient_welcometext] ,
					isnull(twsn.ws_newclient_nickname_minchars,-1)			[ws_newclient_nickname_minchars] ,
					isnull(twsn.ws_newclient_nickname_maxchars,-1)			[ws_newclient_nickname_maxchars] ,
					isnull(twsn.ws_newclient_password_minchars,-1)			[ws_newclient_password_minchars] ,
					isnull(twsn.ws_newclient_password_maxchars,-1)			[ws_newclient_password_maxchars] ,
					isnull(twsn.ws_newclient_finaltext,' ')					[ws_newclient_finaltext] ,
					isnull(twsn.ws_newclient_emailfrom,' ')					[ws_newclient_emailfrom] ,
					isnull(twsn.ws_seo_title,' ')							[ws_seo_title] ,
					isnull(twsn.ws_seo_keywords,' ')						[ws_seo_keywords] ,
					isnull(twsn.ws_seo_description,' ')						[ws_seo_description] ,
					isnull(twsn.ws_seo_footer,' ')							[ws_seo_footer] ,
					isnull(twsn.ws_seo_comp_desc,' ')						[ws_seo_comp_desc] ,
					isnull(twsn.ws_analytics_code,' ')						[ws_analytics_code] ,
					ISNULL(twsn.ws_files2TempUpdated4Development,'false')	[ws_files2TempUpdated4Development] ,
					isnull(twsn.ws_newclient_option,0)						[ws_newclient_option]

			FROM tbWebSite_Names									twsn

			WHERE twsn.ws_id = @ws_id_from




END
GO







CREATE PROCEDURE [dbo].[spWebSite_Names_deleteData]
(
	@comp_id				INT,
	@ws_id					INT
)
AS
SET NOCOUNT ON


BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------
/*
DECLARE @comp_id		INT,
		@ws_id			INT
SELECT	@comp_id		= 1,
		@ws_id			= 2
*/

------------------------------------
------------------------------------


		DELETE FROM tbWebSite_ParagraphComponentsRelation
		WHERE comp_id = @comp_id AND ws_id = @ws_id

		DELETE FROM tbWebSite_ParagraphComponentsControlsData
		WHERE comp_id = @comp_id AND ws_id = @ws_id

		DELETE FROM tbWebSite_Languages
		WHERE comp_id = @comp_id AND ws_id = @ws_id

		DELETE FROM tbWebSite_NameSectionsRelation
		WHERE comp_id = @comp_id AND ws_id = @ws_id

		DELETE FROM tbWebSite_SectionParagraphRelation
		WHERE comp_id = @comp_id AND ws_id = @ws_id

		DELETE FROM tbWebSite_Styles
		WHERE comp_id = @comp_id AND ws_id = @ws_id

		DELETE FROM tbWebSite_Names
		WHERE comp_id = @comp_id AND ws_id = @ws_id



END
GO







CREATE Procedure [dbo].[spWebSite_Names_getCombo]
(
	@comp_id			INT
)
AS
SET NOCOUNT ON

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------

/*
declare	@ws_id			    INT,
		@comp_id			INT,
		@bra_id				INT

select	@ws_id  = -1,
		@comp_id = 1,
		@bra_id = -1
*/
------------------------------------
------------------------------------

		Select	twsn.ws_id	 [Id],
				twsn.ws_desc [Desc]

		From	tbWebSite_Names			twsn

		WHERE	twsn.comp_id	= @comp_id

		Order By twsn.ws_desc


END
GO







CREATE PROCEDURE [dbo].[spWebSite_Names_getDataById]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id			INT
)
AS
SET NOCOUNT ON

BEGIN

------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE 	@comp_id		INT,
			@lang_id		INT,
			@ws_id			INT
SELECT 		@comp_id		=1,
			@lang_id		=2,
			@ws_id			=23
*/

------------------------------------
------------------------------------


	SELECT	twsn.ws_id,
			twsn.ws_desc,
			isnull(twsn.bra_id,-1)                                  [bra_id],
			tb.bra_desc,


			ISNULL(twsn.ws_prli_id,-1)								[ws_prli_id],
			ISNULL(twsn.ws_stor_id,-1)								[ws_stor_id],
			ISNULL(twsn.ws_showstock,-1)							[ws_showstock],
			ISNULL(twsn.ws_showpricelist,0)							[ws_showpricelist],
			ISNULL(twsn.ws_showzerostockitems,'false')				[ws_showzerostockitems],
			ISNULL(twsn.ws_showcart,'false')						[ws_showcart],

			twsn.ws_page_bgcolor_id,
			ISNULL(tc_page.color_value,'')							[page_bgcolor],
			ISNULL(twsn.ws_page_bgimage_url,'')						[ws_page_bgimage_url],
			twsn.ws_bgcolor_id,
			ISNULL(tc_website.color_value,'')						[website_bgcolor],
			twsn.ws_bordercolor_id,
			twsn.ws_borderstyle_id,
			twsn.ws_borderwidth_id,
			ISNULL(tsbs.bs_desc,'')									[BorderStyle],
			ISNULL(tc_bc.color_value,'')							[OnlyBorderColor],
			--ISNULL(tsbw.bw_desc,'')								[BorderWidth],
			SUBSTRING(ISNULL(tsbw.bw_desc,'0px'),1,CHARINDEX('px',ISNULL(tsbw.bw_desc,'0px'))-1)
																	[BorderWidth],
			LTRIM(RTRIM(ISNULL(tc_bc.color_value,'')	+ ' ' +
						ISNULL(tsbw.bw_desc,'')			+ ' ' +
						ISNULL(tsbs.bs_desc,'')))					[BorderColor]						,
			twsn.ws_email_contact																		,
			twsn.[user_id]																				,
			ISNULL(twsn.prof_id,-1)									[prof_id]							,
			ISNULL(twsn.ws_startuphome,-1)							[ws_startuphome]					,
			ISNULL(twsn.ws_itemsformat,1)							[ws_itemsformat]					,
			ISNULL(twsn.ws_decimals4Stock,0)						[ws_decimals4Stock]					,
			ISNULL(twsn.ws_decimals4Price,0)						[ws_decimals4Price]					,
			isnull(twsn.ws_PotentialStockLimit,0)					[ws_PotentialStockLimit]			,
			ISNULL(twsn.ws_menulevel,2)								[ws_menulevel]						,

			ISNULL(twsn.ws_css,'')									[ws_css]							,
			ISNULL(twsn.ws_datashowonitemtab,1)						[ws_datashowonitemtab]				,
			ISNULL(twsn.ws_showCurrentAccountCustomer,'false')		[ws_showCurrentAccountCustomer]		,


			ISNULL(twsn.ws_griddesign_cells,1)						[ws_griddesign_cells]				,
			ISNULL(twsn.ws_griddesign_rows,1)						[ws_griddesign_rows]				,
			ISNULL(twsn.ws_griddesign_cellpadding,0)				[ws_griddesign_cellpadding]			,
			ISNULL(twsn.ws_griddesign_cellspacing,0)				[ws_griddesign_cellspacing]			,
			ISNULL(twsn.ws_griddesign_maxlength_desc,50)			[ws_griddesign_maxlength_desc]		,

			ISNULL(twsn.ws_itemsformat_all,-1)						[ws_itemsformat_all]				,
			ISNULL(twsn.ws_itemsformat_newness,-1)					[ws_itemsformat_newness]			,
			ISNULL(twsn.ws_itemsformat_offer,-1)					[ws_itemsformat_offer]				,
			ISNULL(twsn.ws_change_back_to_fore_onbuttons,'false')	[ws_change_back_to_fore_onbuttons]	,
			ISNULL(twsn.ws_itemdetailformat_all,0)					[ws_itemdetailformat_all]			,
			ISNULL(twsn.ws_itemdetailformat_newness,0)				[ws_itemdetailformat_newness]		,
			ISNULL(twsn.ws_itemdetailformat_offer,0)				[ws_itemdetailformat_offer]			,
			ISNULL(twsn.ws_showitemimageonMycart,'true')			[ws_showitemimageonMycart]			,

			ISNULL(twsn.ws_files2TempUpdated,'false')				[ws_files2TempUpdated]				,
			ISNULL(twsn.ws_files2TempUpdated4Development,'false')	[ws_files2TempUpdated4Development]	,
			ISNULL(twsn.ws_notfound_image_url,'')					[ws_notfound_image_url]				,
			ISNULL(twsn.ws_showcatimageonMenu,'false')				[ws_showcatimageonMenu]				,

			ISNULL(twsn.ws_brand_griddesign_cells,1)				[ws_brand_griddesign_cells]			,
			ISNULL(twsn.ws_brand_griddesign_rows,1)					[ws_brand_griddesign_rows]			,
			ISNULL(twsn.ws_brand_griddesign_cellpadding,0)			[ws_brand_griddesign_cellpadding]	,
			ISNULL(twsn.ws_brand_griddesign_cellspacing,0)			[ws_brand_griddesign_cellspacing]	,
			ISNULL(twsn.ws_brand_griddesign_maxlength_desc,50)		[ws_brand_griddesign_maxlength_desc],

			twsn.sd_id																					,

			ISNULL(twsn.ws_newclient_enable,				'false')	[ws_newclient_enable]				,
			ISNULL(twsn.ws_newclient_cust_id,				-1)			[ws_newclient_cust_id]				,
			ISNULL(twsn.ws_newclient_checkpending,			'false')	[ws_newclient_checkpending]			,
			ISNULL(twsn.ws_newclient_emailcontact,			'')			[ws_newclient_emailcontact]			,
			ISNULL(twsn.ws_newclient_phonecontact,			'')			[ws_newclient_phonecontact]			,
			ISNULL(twsn.ws_newclient_defaultcountry,		-1)			[ws_newclient_defaultcountry]		,
			ISNULL(twsn.ws_newclient_welcometext,			'')			[ws_newclient_welcometext]			,
			ISNULL(twsn.ws_newclient_nickname_minchars,		5)			[ws_newclient_nickname_minchars]	,
			ISNULL(twsn.ws_newclient_nickname_maxchars,		10)			[ws_newclient_nickname_maxchars]	,
			ISNULL(twsn.ws_newclient_password_minchars,		5)			[ws_newclient_password_minchars]	,
			ISNULL(twsn.ws_newclient_password_maxchars,		10)			[ws_newclient_password_maxchars]	,
			ISNULL(twsn.ws_newclient_finaltext,				'')			[ws_newclient_finaltext]			,
			ISNULL(twsn.ws_newclient_emailfrom,				'')			[ws_newclient_emailfrom]			,

			ISNULL(twsn.ws_seo_title,						'')			[ws_seo_title]						,
			ISNULL(twsn.ws_seo_keywords,					'')			[ws_seo_keywords]					,
			ISNULL(twsn.ws_seo_description,					'')			[ws_seo_description]				,
			ISNULL(twsn.ws_seo_footer,						'')			[ws_seo_footer]						,
			ISNULL(twsn.ws_seo_comp_desc,					'')			[ws_seo_comp_desc]					,
			ISNULL(twsn.ws_analytics_code,					'')			[ws_analytics_code]					,
			ISNULL(twsn.ws_newclient_option,				0)			[ws_newclient_option]				,
			ISNULL(tc.cust_webNickName,						'Guest')	[cust_webNickName]


	FROM	tbWebSite_Names						twsn

			INNER JOIN tbBranch					tb
			ON	tb.comp_id			= twsn.comp_id
			AND tb.bra_id			= twsn.bra_id

			--LEFT JOIN tbsysfontdef_Colors		tc_page		ON tc_page.color_id		= twsn.ws_page_bgcolor_id
			--LEFT JOIN tbsysfontdef_Colors		tc_website	ON tc_website.color_id	= twsn.ws_bgcolor_id
			--LEFT JOIN tbsysfontdef_Colors		tc_bc		ON tc_bc.color_id		= twsn.ws_bordercolor_id

			LEFT JOIN vwWebSite_Colors			tc_page		ON tc_page.color_id		= twsn.ws_page_bgcolor_id	AND (tc_page.lang_id	= @lang_id OR tc_page.lang_id = 0)
			LEFT JOIN vwWebSite_Colors			tc_website	ON tc_website.color_id	= twsn.ws_bgcolor_id		AND (tc_website.lang_id = @lang_id OR tc_page.lang_id = 0)
			LEFT JOIN vwWebSite_Colors			tc_bc		ON tc_bc.color_id		= twsn.ws_bordercolor_id	AND (tc_bc.lang_id		= @lang_id OR tc_page.lang_id = 0)


			LEFT JOIN tbSysBorder_Style			tsbs
			ON	tsbs.bs_id			= twsn.ws_borderstyle_id

			LEFT JOIN tbSysBorder_Width			tsbw
			ON	tsbw.bw_id			= twsn.ws_borderwidth_id

			LEFT JOIN tbCustomer				tc
			ON	tc.comp_id			= twsn.comp_id
			AND tc.cust_id			= twsn.ws_newclient_cust_id



	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id


END
GO

