CREATE PROCEDURE [dbo].[spWebSite_Names_getLayouts]
(
	@comp_id		INT,
	@ws_id			INT
)
AS
SET NOCOUNT ON


BEGIN


------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE @comp_id		INT,
		@ws_id			INT

SELECT 	@comp_id		=1,
		@ws_id			=3
*/

------------------------------------
--Parametros de Prueba
------------------------------------

	SELECT	DISTINCT twsn.ws_desc, twsc.swsc_id, twsc.swsc_desc,
			220		[item_id],
			2		[curr_id],
			2		[prli_id],
			1		[stor_id]

	FROM	tbWebSite_Names twsn
			INNER JOIN tbWebSite_Styles twss
			ON twss.comp_id = twsn.comp_id
			AND twss.ws_id = twsn.ws_id
			INNER JOIN tbsysWebSiteComponents twsc
			ON twsc.swsc_id = twss.swsc_id

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id



END
GO






CREATE PROCEDURE [dbo].[spWebSite_Names_SysCurrency_getCombo]
	(
		@comp_id AS INT,
		@lang_id AS INT,
		@bitAllCurrency AS BIT
	)

as

/*

DECLARE @comp_id AS INT,
		@lang_id AS INT,
		@bitAllCurrency AS BIT


SELECT  @comp_id = 1,
		@lang_id = 2,
		@bitAllCurrency = 'false'
*/


BEGIN

	IF @bitAllCurrency = 'True'
		BEGIN
				SELECT		'-1' [id],
							tut.utexts_desc [desc]
					FROM	tbsysUniqueTexts tut


					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 33

				UNION

					select		sc.curr_id		[id],
							sc.curr_desc	[desc]
					from		dbo.tbSysCurrency  sc

		END
	ELSE
	BEGIN

				SELECT		 '-1' [id],
							tut.utexts_desc [desc]
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 33

				UNION

			select		sc.curr_id		[id],
						sc.curr_desc	[desc]
				from		dbo.tbSysCurrency  sc
				INNER JOIN  tbCurrency2Company tcc
					ON		tcc.curr_id = sc.curr_id
						AND tcc.comp_id = @comp_id
				--Order By	tcc.cc_order
				--ORDER BY [DESC]
		END

END
GO








