			@ws_bordercolor_id					int,
			@ws_borderstyle_id					int,
			@ws_borderwidth_id					int,
			@ws_prli_id							int,
			@ws_stor_id							int,
			@ws_showstock						int,
			@ws_showpricelist					int,
			@ws_showzerostockitems				bit,
			@ws_showcart						bit,
			@ws_email_contact					nchar(100),
			@user_id							int,
			@ws_decimals4Stock					int,
			@ws_decimals4Price					int,
			@ws_PotentialStockLimit				int,
			@prof_id							int,
			@ws_startuphome						int,
			@ws_itemsformat						int,
			@ws_showpricewithtax				bit,
			@ws_menulevel						int,
			@ws_css								nvarchar(200),
			@sd_id								int,
			@ws_datashowonitemtab				int,
			@ws_showCurrentAccountCustomer		bit,
			@ws_griddesign_cells				int,
			@ws_griddesign_rows					int,
			@ws_griddesign_cellpadding			int,
			@ws_griddesign_cellspacing			int,
			@ws_griddesign_maxlength_desc		int,
			@ws_itemsformat_all					int,
			@ws_itemsformat_newness				int,
			@ws_itemsformat_offer				int,
			@ws_change_back_to_fore_onbuttons	bit,
			@ws_itemdetailformat_all			int,
			@ws_itemdetailformat_newness		int,
			@ws_itemdetailformat_offer			int,
			@ws_notfound_image_url				nvarchar(500),
			@ws_files2TempUpdated				bit,
			@ws_maxitemsbyquery					int,
			@ws_showitemimageonMycart			bit,
			@ws_showcatimageonMenu				bit,
			@ws_brand_griddesign_cells			int,
			@ws_brand_griddesign_rows			int,
			@ws_brand_griddesign_cellpadding	int,
			@ws_brand_griddesign_cellspacing	int,
			@ws_brand_griddesign_maxlength_desc int,
			@ws_newclient_enable				bit,
			@ws_newclient_cust_id				int,
			@ws_newclient_checkpending			bit,
			@ws_newclient_emailcontact			nvarchar(100),
			@ws_newclient_phonecontact			nvarchar(100),
