			@ws_newclient_welcometext			nvarchar(500),
			@ws_newclient_nickname_minchars		int,
			@ws_newclient_nickname_maxchars		int,
			@ws_newclient_password_minchars		int,
			@ws_newclient_password_maxchars		int,
			@ws_newclient_finaltext				nvarchar(500),
			@ws_newclient_emailfrom				nvarchar(100),
