CREATE Procedure [dbo].[spWebSite_NameSections_getCombo]
(
	@comp_id			INT,
	@ws_id				INT
)
AS
SET NOCOUNT ON


BEGIN


------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE	@comp_id		INT
SELECT	@comp_id		= 1
*/

------------------------------------
------------------------------------


		SELECT	twsnsr.wss_id		[id],
				twsnsr.wssr_desc	[desc]

		FROM	tbWebSite_NameSectionsRelation twsnsr

		WHERE	twsnsr.comp_id	= @comp_id
		AND		twsnsr.ws_id	= @ws_id

		ORDER BY twsnsr.wssr_desc


END
GO







CREATE PROCEDURE [dbo].[spWebSite_NameSections_getData]
(
	@comp_id		INT,
	@ws_id			INT
)
AS
SET NOCOUNT OFF

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------
/*

DECLARE @comp_id		INT,
		@ws_id			INT

SELECT	@comp_id		=1,
		@ws_id			=2

*/
------------------------------------
------------------------------------

	SELECT  twsnsr.wss_id,
			twsnsr.wssr_desc,
			twsnsr.wssr_order,
			isnull(twsnsr.wssr_image_url,'')		[wssr_image_url],
			CASE isnull(twsnsr.wssr_image_repet,0)
												WHEN 0 THEN 'no-repeat'
												WHEN 1 THEN 'no-repeat'
												WHEN 2 THEN 'repeat'
												WHEN 3 THEN 'repeat-x'
												WHEN 4 THEN 'repeat-y'
      		END										[wssr_image_repet]

	FROM	tbWebSite_NameSectionsRelation twsnsr

	WHERE	twsnsr.comp_id	= @comp_id
	AND		twsnsr.ws_id	= @ws_id

	ORDER BY twsnsr.wssr_order


END
GO







CREATE PROCEDURE [dbo].[spWebSite_NameSections_getData2]
(
	@comp_id		INT,
	@ws_id			INT,
	@action			INT
)
AS


SET NOCOUNT OFF

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------

/*

DECLARE @comp_id		INT,
		@ws_id			INT,
		@action			INT

SELECT	@comp_id		=1,
		@ws_id			=23,
		@action			=5

*/

------------------------------------
------------------------------------


	SELECT  twsnsr.wss_id,
			twsnsr.wssr_desc,
			twsnsr.wssr_order,
			isnull(twsnsr.wssr_image_url,'')		[wssr_image_url],
			CASE isnull(twsnsr.wssr_image_repet,0)
												WHEN 0 THEN 'no-repeat'
												WHEN 1 THEN 'no-repeat'
												WHEN 2 THEN 'repeat'
												WHEN 3 THEN 'repeat-x'
												WHEN 4 THEN 'repeat-y'
      		END										[wssr_image_repet],

      		CASE	WHEN twsnsrh.wsnsh_id IS NULL	THEN 'false'
      												ELSE 'true'
      		END										[isHidden]

	FROM	tbWebSite_NameSectionsRelation twsnsr

			LEFT JOIN tbWebSite_NameSectionsRelationHidden twsnsrh
			ON	twsnsrh.comp_id		= twsnsr.comp_id
			AND twsnsrh.wssrl_id	= twsnsr.wssrl_id
			AND twsnsrh.wsnsh_action= @action

	WHERE	twsnsr.comp_id	= @comp_id
	AND		twsnsr.ws_id	= @ws_id
	/*
	AND		twsnsr.wssrl_id NOT IN (SELECT	twsnsrh.wssrl_id
   									FROM	tbWebSite_NameSectionsRelationHidden twsnsrh
   									WHERE	twsnsrh.comp_id			= @comp_id
									AND		twsnsrh.wssrl_id		= twsnsr.wssrl_id
									AND		twsnsrh.wsnsh_action	= @action)
	*/
	ORDER BY twsnsr.wssr_order


END
GO








CREATE PROCEDURE [dbo].[spWebSite_NameSectionsRelation_insertData]
(

	@comp_id			INT,
	@ws_id				INT,
	@wss_id				INT,
	@wssr_desc			NVARCHAR(500),
	@wssr_order			INT,
	@wssr_image_url		NVARCHAR(500),
	@wssr_image_repet	INT,
	@return_value		INT OUTPUT

)
AS




BEGIN

	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------
	-- Parametros de Prueba
	-- -------------------------------------------------------------------------------
	/*
	DECLARE		@comp_id			INT,
				@ws_id				INT,
				@wss_id				INT,
				@wssr_desc			NVARCHAR(500),
				@wssr_order			INT,
				@wssr_image_url		NVARCHAR(500),
				@wssr_image_repet	INT,
				@return_value		INT


	SELECT		@comp_id				= 18,
				@ws_id					= 1,
				@wss_id					= 20,
				@wssr_desc				= '',
				@wssr_order				= 300,
				@wssr_image_url			= '',
				@wssr_image_repet		= -1
	*/
	-- -------------------------------------------------------------------------------

		-- ----------------------------------------------------------------------
		-- a los int le seteamos null por si le llega -1
		-- ----------------------------------------------------------------------


		if	(@comp_id				= -1)	set	@comp_id			= NULL
		if	(@ws_id					= -1)	set	@ws_id				= NULL
		if	(@wss_id				= -1)	set	@wss_id				= NULL
		if	(@wssr_order			= -1)	set	@wssr_order			= NULL
		if	(@wssr_image_repet		= -1)	set	@wssr_image_repet	= NULL



		-- ----------------------------------------------------------------------



		insert into tbWebSite_NameSectionsRelation
		(
			comp_id,
			-- wssrl_id -- this column value is auto-generated,
			ws_id,
			wss_id,
			wssr_desc,
			wssr_order,
			wssr_image_url,
			wssr_image_repet
		)
		VALUES
		(
			@comp_iD,
			@ws_id,
			@wss_id,
			@wssr_desc,
			@wssr_order,
			@wssr_image_url,
			@wssr_image_repet
		)


		SET @return_value = @@IDENTITY


END
GO







CREATE Procedure [dbo].[spWebSite_Paragraph_getCombo]
(
	@comp_id			INT
)
as
set nocount on

BEGIN

------------------------------------
--Parametros de Prueba
------------------------------------
/*

declare	@comp_id	INT

select	@comp_id	= 1

*/

------------------------------------
------------------------------------


		SELECT	twsp.wsp_id		[Id],
				twsp.wsp_desc	[Desc]

		FROM	tbWebSite_Paragraph twsp

		WHERE	twsp.comp_id = @comp_id

		ORDER BY twsp.wsp_desc



END

GO







CREATE PROCEDURE [dbo].[spWebSite_Paragraph_getData]
(
	@comp_id			INT,
	@ws_id				INT,
	@wss_id				INT
)
AS
SET NOCOUNT OFF

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------
/*

DECLARE @comp_id	INT,
		@ws_id		INT,
		@wss_id		INT

SELECT	@comp_id	=1,
		@ws_id		=2,
		@wss_id		=2

*/
------------------------------------
------------------------------------



		SELECT  twsspr.comp_id,
				twsspr.ws_id,
				twsspr.wss_id,
				twsspr.wsp_id,
				twss.wss_desc,
				twss.sws_id,
				twsst.sws_desc,
				twsp.wsp_desc,
				ISNULL(twsp.wsp_width,0)						[wsp_width],
				twsp.wsp_align,
				twsp.wsp_inUpdatePanel,
				twsp.wsp_columnspan,
				twsspr.wsspr_order,
				ISNULL(twsp.wsp_load_orientation_id,'false')	[wsp_load_orientation_id],
				ISNULL(twsp.wsp_rowspan,1)						[wsp_rowspan],
				ISNULL(twsspr.wsspr_image_url,'')				[wsspr_image_url],
				CASE isnull(twsspr.wsspr_image_repet,0)
													WHEN 0 THEN 'no-repeat'
													WHEN 1 THEN 'no-repeat'
													WHEN 2 THEN 'repeat'
													WHEN 3 THEN 'repeat-x'
													WHEN 4 THEN 'repeat-y'
      			END												[wsspr_image_repet],
				twsspr.wsspr_id


		FROM	tbWebSite_SectionParagraphRelation		twsspr

				LEFT JOIN tbWebSite_Section				twss
				ON	twss.comp_id	= twsspr.comp_id
				AND twss.wss_id		= twsspr.wss_id

				LEFT JOIN tbsysWebSite_SectionType		twsst
				ON	twsst.sws_id	= twss.sws_id

				LEFT JOIN tbWebSite_Paragraph			twsp
				ON	twsp.comp_id	= twsspr.comp_id
				AND twsp.wsp_id		= twsspr.wsp_id

		WHERE	twsspr.comp_id	= @comp_id
		AND		twsspr.ws_id	= @ws_id
		AND		twsspr.wss_id	= @wss_id
		--AND		twsspr.wsp_id	> -1		--dummy para indicar que son datos para párrafos y no para secciones

		ORDER BY twsspr.wsspr_order


END
GO







CREATE PROCEDURE [dbo].[spWebSite_Paragraph_getData2]
(
	@comp_id			INT,
	@ws_id				INT,
	@wss_id				INT,
	@action				INT
)
AS
SET NOCOUNT OFF

BEGIN


------------------------------------
--Parametros de Prueba
------------------------------------

/*

DECLARE @comp_id	INT,
		@ws_id		INT,
		@wss_id		INT

SELECT	@comp_id	=1,
		@ws_id		=2,
		@wss_id		=2

*/
------------------------------------
------------------------------------


	SELECT  twsspr.comp_id,
			twsspr.ws_id,
			twsspr.wss_id,
			twsspr.wsp_id,
			twss.wss_desc,
			twss.sws_id,
			twsst.sws_desc,
			twsp.wsp_desc,
			ISNULL(twsp.wsp_width,0)						[wsp_width],
			twsp.wsp_align,
			twsp.wsp_inUpdatePanel,
			twsp.wsp_columnspan,
			twsspr.wsspr_order,
			ISNULL(twsp.wsp_load_orientation_id,'false')	[wsp_load_orientation_id],
			ISNULL(twsp.wsp_rowspan,1)						[wsp_rowspan],
			ISNULL(twsspr.wsspr_image_url,'')				[wsspr_image_url],
			CASE isnull(twsspr.wsspr_image_repet,0)
												WHEN 0 THEN 'no-repeat'
												WHEN 1 THEN 'no-repeat'
												WHEN 2 THEN 'repeat'
												WHEN 3 THEN 'repeat-x'
												WHEN 4 THEN 'repeat-y'
      		END												[wsspr_image_repet],

      		CASE	WHEN twssprh.wsspr_id IS NULL	THEN 'false'
      												ELSE 'true'
      												END		[isHidden],

			twsspr.wsspr_id


	FROM	tbWebSite_SectionParagraphRelation		twsspr

			LEFT JOIN tbWebSite_Section				twss
			ON	twss.comp_id	= twsspr.comp_id
			AND twss.wss_id		= twsspr.wss_id

			LEFT JOIN tbsysWebSite_SectionType		twsst
			ON	twsst.sws_id	= twss.sws_id

			LEFT JOIN tbWebSite_Paragraph			twsp
			ON	twsp.comp_id	= twsspr.comp_id
			AND twsp.wsp_id		= twsspr.wsp_id

			LEFT JOIN tbWebSite_SectionParagraphRelationHidden	twssprh
			ON	twssprh.comp_id		= twsspr.comp_id
			AND twssprh.wsspr_id	= twsspr.wsspr_id
			AND twssprh.wssprh_action = @action


	WHERE	twsspr.comp_id	= @comp_id
	AND		twsspr.ws_id	= @ws_id
	AND		twsspr.wss_id	= @wss_id
	--AND		twsspr.wsp_id	> -1		--dummy para indicar que son datos para párrafos y no para secciones


	ORDER BY twsspr.wsspr_order

END

GO







CREATE PROCEDURE [dbo].[spWebSite_Paragraph_insertdata]

(

	@comp_id					INT,
	@wsp_id						int,
	@wsp_desc					NVARCHAR(100),
	@wsp_width					INT ,
	@wsp_align					INT,
	@wsp_inUpdatePanel			BIT,
	@wsp_columnspan				INT,
	@wsp_load_orientation_id	BIT,
	@wsp_rowspan				INT,
	@chkUpdateNoWSid			BIT

)

AS




BEGIN



	------------------------------------
	--Parametros de Prueba
	------------------------------------
	/*
	DECLARE @comp_id					INT,
			@wsp_id						int,
			@wsp_desc					NVARCHAR(100),
			@wsp_width					INT ,
			@wsp_align					INT,
			@wsp_inUpdatePanel			BIT,
			@wsp_columnspan				INT,
			@wsp_load_orientation_id	BIT,
			@wsp_rowspan				INT,
			@chkUpdateNoWSid			BIT,
			@return_value				INT


	SELECT	@comp_id					=1,
			@wsp_id						=25,
			@wsp_desc					='Párrafo Vacío',
			@wsp_width					=990 ,
			@wsp_align					=1,
			@wsp_inUpdatePanel			='false',
			@wsp_columnspan				=5,
			@wsp_load_orientation_id	='false',
			@wsp_rowspan				=1,
			@chkUpdateNoWSid			='true'


	*/
	------------------------------------
	------------------------------------


	SET NOCOUNT OFF

		-- ----------------------------------------------------------------------
		-- a los int le seteamos null por si le llega -1
		-- ----------------------------------------------------------------------


		if	(@comp_id			= -1)	set	@comp_id			= NULL
		if	(@wsp_align			= -1)	set	@wsp_align			= NULL



		-- ----------------------------------------------------------------------


	if not exists (	SELECT TOP 1 1
               			from tbWebSite_Paragraph twp
               			WHERE	twp.comp_id = @comp_id AND
               					twp.wsp_id	= @wsp_id)
		begin


			set IDENTITY_INSERT tbWebSite_Paragraph ON

			insert into tbWebSite_Paragraph
			(

				comp_id,
				wsp_id,
				wsp_desc,
				wsp_width,
				wsp_align,
				wsp_inUpdatePanel,
				wsp_columnspan,
				wsp_load_orientation_id,
				wsp_rowspan

			)

			VALUES

			(

				@comp_id,
				@wsp_id,
				@wsp_desc,
				@wsp_width,
				@wsp_align,
				@wsp_inUpdatePanel,
				@wsp_columnspan,
				@wsp_load_orientation_id,
				@wsp_rowspan

			)


			set IDENTITY_INSERT tbWebSite_Paragraph OFF

		end


		else


		IF exists (	SELECT TOP 1 1
						from tbWebSite_Paragraph twp
	           			WHERE	twp.comp_id = @comp_id AND
								twp.wsp_id	= @wsp_id ) and @chkUpdateNoWSid = 'true'
			BEGIN


				update tbWebSite_Paragraph
				SET
					comp_id						= @comp_id,
					wsp_desc					= @wsp_desc,
					wsp_width					= @wsp_width,
					wsp_align					= @wsp_align,
					wsp_inUpdatePanel			= @wsp_inUpdatePanel,
					wsp_columnspan				= @wsp_columnspan,
					wsp_load_orientation_id		= @wsp_load_orientation_id,
					wsp_rowspan					= @wsp_rowspan

				WHERE	comp_id = @comp_id AND
						wsp_id	= @wsp_id



			END

END
GO







CREATE PROCEDURE [dbo].[spWebSite_ParagraphComponents_getCombo]
(
	@comp_id			INT,
	@lang_id			INT,
	@ws_id				INT
)
AS
SET NOCOUNT ON



BEGIN

------------------------------------
--Parametros de Prueba
------------------------------------
/*

DECLARE @comp_id		INT

SELECT	@comp_id		=1

*/
------------------------------------
------------------------------------


	SELECT 	CONVERT(VARCHAR,twspcr.wsplr_id)				[Id],

			twsn.ws_desc									+ ' - ' +
			twsp.wsp_desc									+ ' - ' +
			CONVERT(VARCHAR,ISNULL(twspcr.wspcr_order,0))	+ ' - ' +
			tov.optval_desc									[Desc]

			--twsc.swsc_desc	+ ' - ' +


	FROM	dbo.tbWebSite_ParagraphComponentsRelation		twspcr

			INNER JOIN dbo.tbWebSite_Paragraph				twsp
			ON	twsp.comp_id		= twspcr.comp_id
			AND twsp.wsp_id			= twspcr.wsp_id

			INNER JOIN dbo.tbsysWebSiteComponents			twsc
			ON	twsc.swsc_id		= twspcr.swsc_id

			INNER JOIN tbsysOptionsValues					tov
			ON	tov.lang_id			= @lang_id
			AND tov.optval_id		= twsc.swsc_id
			AND	tov.optval_class	= 101

			INNER JOIN tbWebSite_Names						twsn
			ON	twsn.ws_id			= twspcr.ws_id


	WHERE	twspcr.comp_id	= @comp_id
	AND		twspcr.ws_id	= @ws_id

	ORDER BY	twsn.ws_desc,
				twsp.wsp_desc,
				isnull(twspcr.wspcr_order,0),
				tov.optval_desc



END

GO







CREATE PROCEDURE [dbo].[spWebSite_ParagraphComponents_getData]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id			INT,
	@wsp_id			INT
)
AS

BEGIN



	SET NOCOUNT OFF
	BEGIN

	------------------------------------
	--Parametros de Prueba
	------------------------------------

	/*
	DECLARE @comp_id		INT,
			@lang_id		INT,
			@ws_id			INT,
			@wsp_id			INT

	SELECT	@comp_id		=1,
			@lang_id		=2,
			@ws_id			=2,
			@wsp_id			=6
	*/

	------------------------------------
	------------------------------------

			SELECT	twspcr.comp_id,
					twspcr.wsplr_id,
					twspcr.wsp_id,
					ISNULL(twsp.wsp_desc,'')					[wsp_desc],
					twspcr.swsc_id,
					ISNULL(tov.optval_desc,'')					[swsc_desc],
      				ISNULL(twspcr.swsc_id_outputContainer,-1)	[swsc_id_outputContainer],
      				twspcr.wspcr_order,
      				ISNULL(twspcr.wspcr_width,0)				[wspcr_width],
      				ISNULL(twspcr.wspcr_height,0)				[wspcr_height],
      				ISNULL(twspcr.wspcr_url,'')					[wspcr_url],
      				ISNULL(twswn_hpre.wswn_desc,'')				[wspcr_text]

      				,
      				twspcr.wspcr_newTable						[wspcr_newTable],
      				IsNull(twspcr.wspcr_newRow,'False')			[wspcr_newRow],
      				IsNull(twspcr.wspcr_newCell,'False')		[wspcr_newCell],
      				IsNull(twspcr.wspcr_verticalLoad,'False')	[wspcr_verticalLoad],

      				ISNULL(twspcr.wspcr_url,'')					[wspcr_url],
      				CASE isnull(twspcr.wspcr_image_repet,0)
														WHEN 0 THEN 'no-repeat'
														WHEN 1 THEN 'no-repeat'
														WHEN 2 THEN 'repeat'
														WHEN 3 THEN 'repeat-x'
														WHEN 4 THEN 'repeat-y'
      				END											[wspcr_image_repet]


			FROM	tbWebSite_ParagraphComponentsRelation		twspcr

					LEFT JOIN tbWebSite_Paragraph				twsp
					ON	twsp.comp_id		= twspcr.comp_id
					AND twsp.wsp_id			= twspcr.wsp_id

					LEFT JOIN tbsysWebSiteComponents			twsc
					ON	twsc.swsc_id		= twspcr.swsc_id

					LEFT JOIN tbsysOptionsValues				tov
					ON	tov.lang_id			= @lang_id
					AND tov.optval_id		= twsc.swsc_id
					AND tov.optval_class	= 101

					LEFT JOIN tbWebSite_WordsNew				twswn_hpre
					ON	twswn_hpre.wswi_id	= twspcr.wspcr_text_wswi_id
					AND twswn_hpre.lang_id	= @lang_id


			WHERE	twspcr.comp_id		= @comp_id
			AND		twspcr.wsp_id		= @wsp_id
			AND		twspcr.ws_id		= @ws_id
			AND		IsNull(twspcr.wspcr_disabled,'False') = 'False'


			ORDER BY twspcr.wspcr_order

	END


END
GO








CREATE PROCEDURE [dbo].[spWebSite_ParagraphComponentsControlsData_insertData]
(

		@comp_id			INT,
		@wsplr_id			INT,
		@swsc_id			INT,
		@swscc_id			INT,
		@wspcc_image_url	NVARCHAR(500),
		@wspcc_flash_url	NVARCHAR(500),
		@wspcc_wswi_id		INT,
		@ws_id				INT,
		@wspcc_href			NVARCHAR(500),
		@wspcc_height		INT,
		@wspcc_width		INT,
		@wspcc_image_repet	INT,
		@ith_id				INT,
		@wspcc_action		INT,
		@wspcc_disabled		BIT,
		@return_value		INT OUTPUT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id			INT,
			@ws_id				INT,
			@wss_id				INT,
			@wssr_desc			NVARCHAR(500),
			@wssr_order			INT,
			@wssr_image_url		NVARCHAR(500),
			@wssr_image_repet	INT


SELECT		@comp_id				=1,
			@ith_desc				='',
			@ith_maxitemqty			=1,
			@ws_id					=23

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------

	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@comp_id				= -1)	set	@comp_id			= NULL
	if	(@wsplr_id				= -1)	set	@wsplr_id			= NULL
	if	(@swsc_id				= -1)	set	@swsc_id			= NULL
	if	(@swscc_id				= -1)	set	@swscc_id			= NULL
	if	(@wspcc_wswi_id			= -1)	set	@wspcc_wswi_id		= NULL
	if	(@ws_id					= -1)	set	@ws_id				= NULL
	if	(@wspcc_image_repet		= -1)	set	@wspcc_image_repet	= NULL
	if	(@ith_id				= -1)	set	@ith_id				= NULL
	if	(@wspcc_action			= -1)	set	@wspcc_action		= NULL


	-- ----------------------------------------------------------------------



	insert into tbWebSite_ParagraphComponentsControlsData
	(
		comp_id,

		wsplr_id,
		swsc_id,
		swscc_id,
		wspcc_image_url,
		wspcc_flash_url,
		wspcc_wswi_id,
		ws_id,
		wspcc_href,
		wspcc_height,
		wspcc_width,
		wspcc_image_repet,
		ith_id,
		wspcc_action,
		wspcc_disabled
	)
	VALUES
	(
		@comp_id,
		@wsplr_id,
		@swsc_id,
		@swscc_id,
		@wspcc_image_url,
		@wspcc_flash_url,
		@wspcc_wswi_id,
		@ws_id,
		@wspcc_href,
		@wspcc_height,
		@wspcc_width,
		@wspcc_image_repet,
		@ith_id,
		@wspcc_action,
		@wspcc_disabled
	)

	SET @return_value = @@IDENTITY


END
GO







