CREATE PROCEDURE [dbo].[spWebSite_ParagraphComponentsRelation_insertData]
(

		@comp_id						int,
		@wsp_id							int,
		@swsc_id						int,
		@swsc_id_outputContainer		int,
		@wspcr_order					int,
		@wspcr_width					int,
		@wspcr_height					int,
		@wspcr_url						nvarchar(500),
		@wspcr_text_wswi_id				int,
		@ws_id							int,
		@wspcr_newTable					INT,
		@wspcr_newRow					bit,
		@wspcr_newCell					bit,
		@wspcr_verticalLoad				bit,
		@wspcr_image_repet				int,
		@wspcr_disabled					bit,
		@return_value					INT OUTPUT

)
AS


BEGIN



	-- -------------------------------------------------------------------------------
	-- Parametros de Prueba
	-- -------------------------------------------------------------------------------
	/*

	DECLARE		@comp_id						int,
				@wsp_id							int,
				@swsc_id						int,
				@swsc_id_outputContainer		int,
				@wspcr_order					int,
				@wspcr_width					int,
				@wspcr_height					int,
				@wspcr_url						nvarchar(500),
				@wspcr_text_wswi_id				int,
				@ws_id							int,
				@wspcr_newTable					bit,
				@wspcr_newRow					bit,
				@wspcr_newCell					bit,
				@wspcr_verticalLoad				bit,
				@wspcr_image_repet				int,
				@wspcr_disabled					bit,


	SELECT		@comp_id				=1,
				@ith_desc				='',
				@ith_maxitemqty			=1,
				@ws_id					=23

	*/
	-- -------------------------------------------------------------------------------


	SET NOCOUNT ON

	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------

	--IF  (@wspcr_newTable		    = -1)	SET @wspcr_newTable				= NULL
	if	(@comp_id					= -1)	set	@comp_id					= NULL
	if	(@wsp_id					= -1)	set	@wsp_id						= NULL
	if	(@swsc_id					= -1)	set	@swsc_id					= NULL
	if	(@swsc_id_outputContainer	= -1)	set	@swsc_id_outputContainer	= NULL
	if	(@wspcr_order				= -1)	set	@wspcr_order				= NULL
	if	(@ws_id						= -1)	set	@ws_id						= NULL
	if	(@wspcr_width				= -1)	set	@wspcr_width				= NULL
	if	(@wspcr_height				= -1)	set	@wspcr_height				= NULL
	if	(@wspcr_text_wswi_id		= -1)	set	@wspcr_text_wswi_id			= NULL
	if	(@wspcr_image_repet			= -1)	set	@wspcr_image_repet			= NULL


	-- ----------------------------------------------------------------------



	insert into tbWebSite_ParagraphComponentsRelation
	(
		comp_id,
		-- wsplr_id -- this column value is auto-generated,
		wsp_id,
		swsc_id,
		swsc_id_outputContainer,
		wspcr_order,
		wspcr_width,
		wspcr_height,
		wspcr_url,
		wspcr_text_wswi_id,
		ws_id,
		wspcr_newTable,
		wspcr_newRow,
		wspcr_newCell,
		wspcr_verticalLoad,
		wspcr_image_repet,
		wspcr_disabled
	)
	VALUES
	(
		@comp_id,
		@wsp_id,
		@swsc_id,
		@swsc_id_outputContainer,
		@wspcr_order,
		@wspcr_width,
		@wspcr_height,
		@wspcr_url,
		@wspcr_text_wswi_id,
		@ws_id,
		CASE
			WHEN @wspcr_newTable = -1 THEN NULL
			WHEN @wspcr_newTable = 0  THEN 'False'
			WHEN @wspcr_newTable = 1  THEN 'True'
			ELSE 'False'
		END
		,
		@wspcr_newRow,
		@wspcr_newCell,
		@wspcr_verticalLoad,
		@wspcr_image_repet,
		@wspcr_disabled
	)

	SET @return_value = @@IDENTITY


END
GO








