CREATE PROCEDURE [dbo].[spWebSite_Section_InsertData]
(


	@comp_id		INT,
	@wss_id			INT,
	@wss_desc		NVARCHAR(100),
	@sws_id			INT,
	@chkUpdateNoWSid BIT


)
AS





BEGIN

	------------------------------------
	--Parametros de Prueba
	------------------------------------
	/*

	DECLARE 	@comp_id		INT,
				@wss_id			INT,
				@wss_desc		NVARCHAR(100),
				@sws_id			INT,
				@chkUpdateNoWSid BIT

	SELECT		@comp_id			= 1,
				@wss_id				= 20,
				@wss_desc			='Seccion nueva ga',
				@sws_id				=1,
				@chkUpdateNoWSid	='true'
	*/

	------------------------------------
	--Parametros de Prueba
	------------------------------------

	SET NOCOUNT OFF


		-- ----------------------------------------------------------------------
		-- a los int le seteamos null por si le llega -1
		-- ----------------------------------------------------------------------


		if	(@comp_id			= -1)	set	@comp_id				= NULL
		if	(@sws_id			= -1)	set	@sws_id					= NULL



		-- ----------------------------------------------------------------------


	if not exists (	SELECT TOP 1 1
						from tbWebSite_Section twss
               			WHERE	twss.comp_id	= @comp_id and
               					twss.wss_id		= @wss_id)
		begin

				set IDENTITY_INSERT tbWebSite_Section ON

				insert into tbWebSite_Section
				(
					comp_id,
					wss_id,
					wss_desc,
					sws_id
				)
				VALUES
				(
					@comp_id,
					@wss_id,
					@wss_desc,
					@sws_id
				)

				set IDENTITY_INSERT tbWebSite_Section OFF


		end


		else


		IF exists (	SELECT TOP 1 1
	           			from tbWebSite_Section twss
	           			where	twss.comp_id	= @comp_id AND
	           					twss.wss_id		= @wss_id) and @chkUpdateNoWSid = 'true'
			BEGIN



			update tbWebSite_Section
			SET
				comp_id		= @comp_id,
				wss_desc	= @wss_desc,
				sws_id		= @sws_id

			WHERE	comp_id = @comp_id AND
					wss_id	=  @wss_id


			END



END

GO






CREATE PROCEDURE [dbo].[spWebSite_SectionParagraphRelation_getCombo]
(
	@comp_id		INT,
	@lang_id		INT,
	@ws_id			INT
)
AS

SET NOCOUNT ON


BEGIN


------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE 	@comp_id		INT,
			@lang_id		INT,
			@ws_id			INT

SELECT	    @comp_id		=1,
			@lang_id		=2,
			@ws_id			=1


*/
------------------------------------
------------------------------------

	SELECT	twss.wss_desc + ' - ' + twsp.wsp_desc	[desc],
			twsspr.wsspr_id							[ID]


	FROM	tbWebSite_SectionParagraphRelation		twsspr

			INNER JOIN tbWebSite_Section			twss
			ON	twss.comp_id	= twsspr.comp_id
			AND twss.wss_id		= twsspr.wss_id

			INNER JOIN tbWebSite_Paragraph			twsp
			ON	twsp.wsp_id		= twsspr.wsp_id
			AND twsp.comp_id	= twsspr.comp_id


	WHERE	twsspr.comp_id	= @comp_id
	AND		(@ws_id = -1 or twsspr.ws_id	= @ws_id)


	ORDER BY 1


END
GO







CREATE PROCEDURE [dbo].[spWebSite_SectionParagraphRelation_getDataById]
(
	@comp_id			INT,
	@lang_id			INT,
	@ws_id				INT,
	@wsspr_id			INT
)
AS
SET NOCOUNT ON

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------

/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@ws_id			INT,
		@wsspr_id		INT

SELECT 	@comp_id		=1,
		@lang_id		=2,
		@ws_id			=15,
		@wsspr_id		=187
*/

------------------------------------
------------------------------------





	DECLARE		@WebSiteComponentsControls		NVARCHAR(100),
				@BorderColor					NVARCHAR(100),
				@BorderWidthValue				INT,
				@FontColor						NVARCHAR(50),
				@FontName						NVARCHAR(50),
				@FontSize						NVARCHAR(50),
				@FontStyle						NVARCHAR(50),
				@FontDecoration					NVARCHAR(50),
				@FontWeight						NVARCHAR(50),
				@BackColor						NVARCHAR(50),
				@wspcc_image_url				NVARCHAR(500),
				@wspcc_flash_url				NVARCHAR(500),
				@wswn_desc						NVARCHAR(4000),
				@OnlyBorderColor				NVARCHAR(50),
				@OnlyBorderWith					NVARCHAR(50),
				@OnlyBorderStyle				NVARCHAR(50),
				@lwsplr_id						INT,
				@wspcc_href						NVARCHAR(500)






	SELECT	TOP 1

			--@WebSiteComponentsControls	=ISNULL(tov.optval_desc,twscc.swscc_desc),
			--tb.fb_desc
			@BorderColor				=LTRIM(RTRIM(ISNULL(tc2.color_value,'')	+ ' ' +
													 ISNULL(tsbw.bw_desc,	'')	+ ' ' +
													 ISNULL(tsbs.bs_desc,	''))),
			@BorderWidthValue			=ISNULL(SUBSTRING(tsbw.bw_desc,1,CHARINDEX('px',tsbw.bw_desc)-1),0),
			@FontColor					=ISNULL(tc.color_value,	''),
			@FontName					=ISNULL(tf.ff_desc,		''),
			@FontSize					=ISNULL(ts.fz_desc,		''),
			@FontStyle					=ISNULL(ts2.fs_desc,	''),
			@FontDecoration				=ISNULL(ttd.td_desc,	''),
			@FontWeight					=ISNULL(tw.fw_desc,		''),
			@BackColor					=ISNULL(tbc.color_value,''),

			@OnlyBorderColor			=ISNULL(tc2.color_value,''),
			@OnlyBorderWith				=ISNULL(tsbw.bw_desc,	''),
			@OnlyBorderStyle			=ISNULL(tsbs.bs_desc,	'')

	FROM	tbWebSite_SectionParagraphRelation			twsspr

			--LEFT JOIN tbsysWebSiteComponentsControls	twscc	ON twscc.swsc_id= twss.swsc_id AND twscc.swscc_id = twss.swscc_id
			--LEFT JOIN tbsysOptionsValues				tov		ON tov.lang_id = @lang_id AND tov.optval_id = twscc.swscc_id AND tov.optval_class = 102

			--LEFT JOIN tbsysfontdef_Borders			tb		ON tb.fb_id		= twss.fb_id

			LEFT JOIN vwWebSite_Colors					tc		ON tc.color_id	= twsspr.color_id AND (tc.lang_id = @lang_id OR tc.lang_id = 0)
			LEFT JOIN tbsysfontdef_Family				tf		ON tf.ff_id		= twsspr.ff_id
			LEFT JOIN tbsysfontdef_Size					ts		ON ts.fz_id		= twsspr.fz_id
			LEFT JOIN tbsysfontdef_Style				ts2		ON ts2.fs_id	= twsspr.fs_id
			LEFT JOIN tbsysfontdef_TextDecoration		ttd		ON ttd.td_id	= twsspr.td_id
			LEFT JOIN tbsysfontdef_Weight				tw		ON tw.fw_id		= twsspr.fw_id
			LEFT JOIN vwWebSite_Colors					tbc		ON tbc.color_id	= twsspr.bc_id AND (tbc.lang_id = @lang_id OR tbc.lang_id = 0)

			LEFT JOIN vwWebSite_Colors					tc2		ON tc2.color_id = twsspr.fb_id AND (tc2.lang_id = @lang_id OR tc2.lang_id = 0)
			LEFT JOIN tbSysBorder_Width					tsbw	ON tsbw.bw_id	= twsspr.bw_id
			LEFT JOIN tbSysBorder_Style					tsbs	ON tsbs.bs_id	= twsspr.bs_id

	WHERE	twsspr.comp_id		= @comp_id
	AND		twsspr.ws_id		= @ws_id
	AND		twsspr.wsspr_id		= @wsspr_id
	--AND		twss.swscc_id		= @swscc_id







	--SELECT	TOP 1
	--		@wspcc_image_url			= twspccd.wspcc_image_url,
	--		@wspcc_flash_url			= twspccd.wspcc_flash_url,
	--		@wswn_desc					= twswn.wswn_desc,
	--		@wspcc_href					= twspccd.wspcc_href,
	--		@lwsplr_id					= twspccd.wsplr_id
	--
	--FROM 	tbWebSite_ParagraphComponentsControlsDat-a		twspccd
	--
	--		LEFT JOIN tbWebSite_WordsNew					twswn
	--		ON	twswn.lang_id			= @lang_id
	--		AND twswn.wswi_id			= twspccd.wspcc_wswi_id
	--
	--WHERE	twspccd.comp_id				= @comp_id
	--AND		twspccd.swsc_id				= @swsc_id
	--AND		twspccd.swscc_id			= @swscc_id
	--AND		(twspccd.wsplr_id			= @wsplr_id OR @wsplr_id = -1)
	--AND		twspccd.ws_id				= @ws_id









	SELECT	isnull(@WebSiteComponentsControls,'')		[WebSiteComponentsControls],
			isnull(@BorderColor,'')						[BorderColor],
			isnull(@BorderWidthValue,0)					[BorderWidthValue],
			isnull(@FontColor,'')						[FontColor],
			isnull(@FontName,'')						[FontName],
			isnull(@FontSize,'')						[FontSize],
			isnull(@FontStyle,'')						[FontStyle],
			isnull(@FontDecoration,'')					[FontDecoration],
			isnull(@FontWeight,'')						[FontWeight],
			isnull(@BackColor,'')						[BackColor],
			isnull(@wspcc_image_url,'')					[wspcc_image_url],
			isnull(@wspcc_flash_url,'')					[wspcc_flash_url],
			isnull(@wswn_desc,'')						[wswn_desc],
			isnull(@OnlyBorderColor,'')					[OnlyBorderColor],
			isnull(@OnlyBorderWith,'')					[OnlyBorderWith],
			isnull(@OnlyBorderStyle,'')					[OnlyBorderStyle],
			ISNULL(@wspcc_href,'')						[wspcc_href],
			isnull(@lwsplr_id,0)						[wsplr_id]



END
GO








CREATE PROCEDURE [dbo].[spWebSite_SectionParagraphRelation_getDataForParagraph]
(
	@comp_id			INT,
	@lang_id			INT,
	@ws_id				INT
)
AS
SET NOCOUNT ON


BEGIN

	-- --------------------------------------------------------------------------
	-- testing
	-- --------------------------------------------------------------------------
	/*
	DECLARE	@comp_id			INT,
			@lang_id			INT,
			@ws_id				INT
	SELECT 	@comp_id			=1,
			@lang_id			=2,
			@ws_id				=12
	IF NOT OBJECT_ID('tempdb.dbo.#tmptbWebSite_ParagraphComponentsRelation') IS NULL DROP TABLE #tmptbWebSite_ParagraphComponentsRelation
	*/
	-- --------------------------------------------------------------------------




	--cargo en una tabla los componentes que se pueden/deben asignar al párrafos receptor de eventos
	DECLARE @tblComponentsOmmited	TABLE(swsc_id INT)
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES (  1 ) --Item
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES (  2 ) --ItemOffer
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES (  3 ) --ItemNewness
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES ( 21 ) --ContactUs
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES ( 22 ) --OurCompany
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES ( 16 ) --TreeViewItemsReceptor
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES ( 17 ) --MsgBoxItemDetail
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES ( 26 ) --MsgBoxItemToCart
	INSERT INTO @tblComponentsOmmited ( swsc_id ) VALUES ( 32 ) --ItemDetail
	--SELECT * FROM @tblComponentsOmmited tco




	--cargo en una tabla los párrafos que incluyen los componentes anteriores
	SELECT	distinct twspcr.wsp_id
	INTO	#tmptbWebSite_ParagraphComponentsRelation
	FROM	tbWebSite_ParagraphComponentsRelation twspcr
	WHERE	twspcr.comp_id	= @comp_id
	AND		twspcr.ws_id	= @ws_id
	AND		twspcr.swsc_id	IN (SELECT tco.swsc_id FROM @tblComponentsOmmited tco)
	AND		IsNull(twspcr.wspcr_disabled,'False') = 'False'
	--SELECT * FROM #tmptbWebSite_ParagraphComponentsRelation




	--si el query anterior obtiene datos procesa lo siguiente
	IF @@ROWCOUNT = 1
	BEGIN

		--recupera la cantidad
		SELECT	COUNT(*)	[quantity]

		FROM	tbWebSite_ParagraphComponentsRelation	twspcr

				INNER JOIN tbsysWebSiteComponents		twsc
				ON twsc.swsc_id = twspcr.swsc_id

		WHERE	twspcr.comp_id		=	@comp_id
		AND		twspcr.ws_id		=	@ws_id
		AND		twspcr.wsp_id		IN	(
										SELECT	distinct twspcr.wsp_id
										FROM	tbWebSite_ParagraphComponentsRelation twspcr
										WHERE	twspcr.comp_id	= @comp_id
										AND		twspcr.ws_id	= @ws_id
										AND		twspcr.swsc_id	IN (SELECT tco.swsc_id FROM @tblComponentsOmmited tco)
										)
		AND		NOT twspcr.swsc_id	IN	(SELECT tco.swsc_id FROM @tblComponentsOmmited tco)
		AND		IsNull(twspcr.wspcr_disabled,'False') = 'False'

	END

END
GO








CREATE PROCEDURE [dbo].[spWebSite_SectionParagraphRelation_insertData]
(

		@comp_id						INT,
		@ws_id							INT,
		@wss_id							INT,
		@wsp_id							INT,
		@wsspr_order					INT,
		@fb_id							INT,
		@bs_id							INT,
		@bw_id							INT,
		@bc_id							INT,
		@color_id						INT,
		@ff_id							INT,
		@fz_id							INT,
		@fs_id							INT,
		@td_id							INT,
		@fw_id							INT,
		@wsspr_image_url				NVARCHAR(500),
		@wsspr_image_repet				INT,
		@return_value					INT OUTPUT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id						INT,
			@ws_id							INT,
			@wss_id							INT,
			@wsp_id							INT,
			@wsspr_order					INT,
			@fb_id							INT,
			@bs_id							INT,
			@bw_id							INT,
			@bc_id							INT,
			@color_id						INT,
			@ff_id							INT,
			@fz_id							INT,
			@fs_id							INT,
			@td_id							INT,
			@fw_id							INT,
			@wsspr_image_url				NVARCHAR(500),
			@wsspr_image_repet				INT,

SELECT		@comp_id				=1,
			@ith_desc				='',
			@ith_maxitemqty			=1,
			@ws_id					=23

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@comp_id			= -1)	set	@comp_id				= NULL
	if	(@ws_id				= -1)	set	@ws_id					= NULL
	if	(@wss_id			= -1)	set	@wss_id					= NULL
	if	(@wsp_id			= -1)	set	@wsp_id					= NULL
	if	(@fb_id				= -1)	set	@fb_id					= NULL
	if	(@bs_id				= -1)	set	@bs_id					= NULL
	if	(@bw_id				= -1)	set	@bw_id					= NULL
	if	(@bc_id				= -1)	set	@bc_id					= NULL
	if	(@color_id			= -1)	set	@color_id				= NULL
	if	(@ff_id				= -1)	set	@ff_id					= NULL
	if	(@fz_id				= -1)	set	@fz_id					= NULL
	if	(@fs_id				= -1)	set	@fs_id					= NULL
	if	(@td_id				= -1)	set	@td_id					= NULL
	if	(@fw_id				= -1)	set	@fw_id					= NULL
	if	(@wsspr_image_repet	= -1)	set	@wsspr_image_repet		= NULL

	-- ----------------------------------------------------------------------



	insert into tbWebSite_SectionParagraphRelation
	(
		comp_id,
		ws_id,
		wss_id,
		wsp_id,
		wsspr_order,
		fb_id,
		bs_id,
		bw_id,
		bc_id,
		color_id,
		ff_id,
		fz_id,
		fs_id,
		td_id,
		fw_id,
		wsspr_image_url,
		wsspr_image_repet
	)
	VALUES
	(
		@comp_id,
		@ws_id,
		@wss_id,
		@wsp_id,
		@wsspr_order,
		@fb_id,
		@bs_id,
		@bw_id,
		@bc_id,
		@color_id,
		@ff_id,
		@fz_id,
		@fs_id,
		@td_id,
		@fw_id,
		@wsspr_image_url,
		@wsspr_image_repet
	)

	SET @return_value = @@IDENTITY


END
GO








