CREATE PROCEDURE [dbo].[spWebSite_Styles_getDataById]
(
	@comp_id			INT,
	@lang_id			INT,
	@ws_id				INT,
	@swsc_id			INT,
	@swscc_id			INT,
	@wsplr_id			INT
)
AS

SET NOCOUNT ON

BEGIN


------------------------------------
--Parametros de Prueba
------------------------------------
/*
DECLARE @comp_id		INT,
		@lang_id		INT,
		@ws_id			INT,
		@swsc_id		INT,
		@swscc_id		INT,
		@wsplr_id		INT

SELECT 	@comp_id		=1,
		@lang_id		=2,
		@ws_id			=23,
		@swsc_id		=9,
		@swscc_id		=27,
		@wsplr_id		=1222
*/
------------------------------------
------------------------------------


		SELECT	@wsplr_id = twspccd.wsplr_id
		FROM	tbWebSite_ParagraphComponentsControlsData twspccd
		WHERE	twspccd.comp_id		= @comp_id
		AND		twspccd.ws_id		= @ws_id
		AND		twspccd.swsc_id		= @swsc_id
		AND		twspccd.swscc_id	= @swscc_id
		AND		@wsplr_id			= -10
		AND		isnull(twspccd.wspcc_disabled,'False') = 'False'







	DECLARE		@WebSiteComponentsControls			NVARCHAR(100),
				@BorderColor						NVARCHAR(100),
				@BorderWidthValue					INT,
				@FontColor							NVARCHAR(50),
				@FontName							NVARCHAR(50),
				@FontSize							NVARCHAR(50),
				@FontStyle							NVARCHAR(50),
				@FontDecoration						NVARCHAR(50),
				@FontWeight							NVARCHAR(50),
				@BackColor							NVARCHAR(50),
				@wspcc_image_url					NVARCHAR(500),
				@wspcc_flash_url					NVARCHAR(500),
				@wswn_desc							NVARCHAR(4000),
				@OnlyBorderColor					NVARCHAR(50),
				@OnlyBorderWith						NVARCHAR(50),
				@OnlyBorderStyle					NVARCHAR(50),
				@lwsplr_id							INT,
				@wspcc_href							NVARCHAR(500),
				@wspcc_height						INT,
				@wspcc_width						INT,
				@ws_change_back_to_fore_onbuttons	BIT,
				@wspcc_image_repet					NVARCHAR(15),
				@border_type						INT,
				@ith_id								INT,
				@wspcc_action						INT,
				@fontsizeinpixels					INT





	SELECT	TOP 1

			@WebSiteComponentsControls	=ISNULL(tov.optval_desc,twscc.swscc_desc),
			--tb.fb_desc
			@BorderColor				=LTRIM(RTRIM(ISNULL(tc2.color_value,'')	+ ' ' +
													 ISNULL(tsbw.bw_desc,	'')	+ ' ' +
													 ISNULL(tsbs.bs_desc,	''))),
			@BorderWidthValue			=ISNULL(SUBSTRING(tsbw.bw_desc,1,CHARINDEX('px',tsbw.bw_desc)-1),0),
			@FontColor					=ISNULL(tc.color_value,	''),
			@FontName					=ISNULL(tf.ff_desc,		''),
			@FontSize					=ISNULL(ts.fz_desc,		''),
			@FontStyle					=ISNULL(ts2.fs_desc,	''),
			@FontDecoration				=ISNULL(ttd.td_desc,	''),
			@FontWeight					=ISNULL(tw.fw_desc,		''),
			@BackColor					=ISNULL(tbc.color_value,''),

			@OnlyBorderColor			=ISNULL(tc2.color_value,''),
			@OnlyBorderWith				=ISNULL(tsbw.bw_desc,	''),
			@OnlyBorderStyle			=ISNULL(tsbs.bs_desc,	''),
			@border_type				=ISNULL(twss.border_type,0)


	FROM	tbWebSite_Styles							twss

			LEFT JOIN tbsysWebSiteComponentsControls	twscc	ON twscc.swsc_id= twss.swsc_id AND twscc.swscc_id = twss.swscc_id
			LEFT JOIN tbsysOptionsValues				tov		ON tov.lang_id = @lang_id AND tov.optval_id = twscc.swscc_id AND tov.optval_class = 102

			--LEFT JOIN tbsysfontdef_Borders			tb		ON tb.fb_id		= twss.fb_id

			LEFT JOIN vwWebSite_Colors					tc		ON tc.color_id	= twss.color_id AND (tc.lang_id = @lang_id OR tc.lang_id = 0)
			LEFT JOIN tbsysfontdef_Family				tf		ON tf.ff_id		= twss.ff_id
			LEFT JOIN tbsysfontdef_Size					ts		ON ts.fz_id		= twss.fz_id
			LEFT JOIN tbsysfontdef_Style				ts2		ON ts2.fs_id	= twss.fs_id
			LEFT JOIN tbsysfontdef_TextDecoration		ttd		ON ttd.td_id	= twss.td_id
			LEFT JOIN tbsysfontdef_Weight				tw		ON tw.fw_id		= twss.fw_id
			LEFT JOIN vwWebSite_Colors					tbc		ON tbc.color_id	= twss.bc_id AND (tbc.lang_id = @lang_id OR tbc.lang_id = 0)

			LEFT JOIN vwWebSite_Colors					tc2		ON tc2.color_id = twss.fb_id AND (tc2.lang_id = @lang_id OR tc2.lang_id = 0)
			LEFT JOIN tbSysBorder_Width					tsbw	ON tsbw.bw_id	= twss.bw_id
			LEFT JOIN tbSysBorder_Style					tsbs	ON tsbs.bs_id	= twss.bs_id

	WHERE	twss.comp_id		= @comp_id
	AND		twss.ws_id			= @ws_id
	AND		twss.swsc_id		= @swsc_id
	AND		twss.swscc_id		= @swscc_id




	SET @fontsizeinpixels = CASE
								WHEN @FontSize = 'large'	THEN 18
								WHEN @FontSize = 'larger'	THEN 36
								WHEN @FontSize = 'medium'	THEN 16
								WHEN @FontSize = 'small'	THEN 16
								WHEN @FontSize = 'smaller'	THEN  7
								WHEN @FontSize = 'x-large'	THEN 24
								WHEN @FontSize = 'x-small'	THEN 10
								WHEN @FontSize = 'xx-large' THEN 32
								WHEN @FontSize = 'xx-small' THEN  9
								WHEN @FontSize = '4pt'		THEN  4 / 0.70
								WHEN @FontSize = '5pt'		THEN  5 / 0.70
								WHEN @FontSize = '6pt'		THEN  6 / 0.70
								WHEN @FontSize = '7pt'		THEN  7 / 0.70
								WHEN @FontSize = '8pt'		THEN  8 / 0.70
								WHEN @FontSize = '9pt'		THEN  9 / 0.70
								WHEN @FontSize = '10pt'		THEN 10 / 0.70
								WHEN @FontSize = '11pt'		THEN 11 / 0.70
								WHEN @FontSize = '12pt'		THEN 12 / 0.70
								WHEN @FontSize = '14pt'		THEN 14 / 0.70
								WHEN @FontSize = '16pt'		THEN 16 / 0.70
								WHEN @FontSize = '18pt'		THEN 18 / 0.70
								WHEN @FontSize = '20pt'		THEN 20 / 0.70
								WHEN @FontSize = '22pt'		THEN 22 / 0.70
								WHEN @FontSize = '24pt'		THEN 24 / 0.70
								WHEN @FontSize = '36pt'		THEN 36 / 0.70
								WHEN @FontSize = '48pt'		THEN 48 / 0.70
								ELSE 10
	                        END



	SELECT	TOP 1
			@wspcc_image_url			= twspccd.wspcc_image_url,
			@wspcc_flash_url			= twspccd.wspcc_flash_url,
			@wswn_desc					= twswn.wswn_desc,
			@wspcc_href					= twspccd.wspcc_href,
			@lwsplr_id					= twspccd.wsplr_id,

			@wspcc_height				= twspccd.wspcc_height,
			@wspcc_width				= twspccd.wspcc_width,
			@wspcc_image_repet			=	CASE isnull(twspccd.wspcc_image_repet,0)
												WHEN 0 THEN 'no-repeat'
												WHEN 1 THEN 'no-repeat'
												WHEN 2 THEN 'repeat'
												WHEN 3 THEN 'repeat-x'
												WHEN 4 THEN 'repeat-y'
											END,
			@ith_id						= ISNULL(twspccd.ith_id,-1),
			@wspcc_action				= ISNULL(twspccd.wspcc_action,-1)


	FROM 	tbWebSite_ParagraphComponentsControlsData		twspccd

			LEFT JOIN tbWebSite_WordsNew					twswn
			ON	twswn.lang_id			= @lang_id
			AND twswn.wswi_id			= twspccd.wspcc_wswi_id

	WHERE	twspccd.comp_id				= @comp_id
	AND		twspccd.swsc_id				= @swsc_id
	AND		twspccd.swscc_id			= @swscc_id
	AND		(twspccd.wsplr_id			= @wsplr_id OR @wsplr_id = -1)
	AND		twspccd.ws_id				= @ws_id
	AND		IsNull(twspccd.wspcc_disabled,'False') = 'False'





	SELECT	@ws_change_back_to_fore_onbuttons = twsn.ws_change_back_to_fore_onbuttons

	FROM	tbWebSite_Names			twsn

	WHERE	twsn.comp_id	= @comp_id
	AND		twsn.ws_id		= @ws_id






	SELECT	isnull(@WebSiteComponentsControls,'')				[WebSiteComponentsControls],
			isnull(@BorderColor,'')								[BorderColor],
			isnull(@BorderWidthValue,0)							[BorderWidthValue],
			isnull(@FontColor,'')								[FontColor],
			isnull(@FontName,'')								[FontName],
			isnull(@FontSize,'')								[FontSize],
			isnull(@FontStyle,'')								[FontStyle],
			isnull(@FontDecoration,'')							[FontDecoration],
			isnull(@FontWeight,'')								[FontWeight],
			isnull(@BackColor,'')								[BackColor],
			isnull(@wspcc_image_url,'')							[wspcc_image_url],
			isnull(@wspcc_flash_url,'')							[wspcc_flash_url],
			isnull(@wswn_desc,'')								[wswn_desc],
			isnull(@OnlyBorderColor,'')							[OnlyBorderColor],
			isnull(@OnlyBorderWith,'')							[OnlyBorderWith],
			isnull(@OnlyBorderStyle,'')							[OnlyBorderStyle],
			ISNULL(@wspcc_href,'')								[wspcc_href],
			isnull(@lwsplr_id,0)								[wsplr_id],

			ISNULL(@wspcc_height,0)								[wspcc_height],
			ISNULL(@wspcc_width,0)								[wspcc_width],

			ISNULL(@ws_change_back_to_fore_onbuttons,'false')	[AnimationButtons],
			isnull(@wspcc_image_repet,'')						[wspcc_image_repet],
			isnull(@border_type,0)								[border_type],
			isnull(@ith_id,-1)									[ith_id],
			isnull(@wspcc_action,-1)							[wspcc_action],
			ISNULL(@fontsizeinpixels,1)							[fontsizeinpixels]



END

GO








CREATE PROCEDURE [dbo].[spWebSite_Styles_insertData]
(

		@comp_id						INT,
		@ws_id							INT,
		@swsc_id						INT,
		@swscc_id						INT,
		@fb_id							INT,
		@color_id						INT,
		@ff_id							INT,
		@fs_id							INT,
		@td_id							INT,
		@fw_id							INT,
		@fz_id							INT,
		@bc_id							INT,
		@wsst_url						nvarchar(500),
		@bs_id							INT,
		@bw_id							INT,
		@border_type					INT

)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id						INT,
			@ws_id							INT,
			@swsc_id						INT,
			@swscc_id						INT,
			@fb_id							INT,
			@color_id						INT,
			@ff_id							INT,
			@fs_id							INT,
			@td_id							INT,
			@fw_id							INT,
			@fz_id							INT,
			@bc_id							INT,
			@wsst_url						nvarchar(500),
			@bs_id							INT,
			@bw_id							INT,
			@border_type					INT

SELECT		@comp_id				=1,
			@ith_desc				='',
			@ith_maxitemqty			=1,
			@ws_id					=23

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------




	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------

	if	(@comp_id		= -1)	set	@comp_id			= NULL
	if	(@ws_id			= -1)	set	@ws_id				= NULL
	if	(@swsc_id		= -1)	set	@swsc_id			= NULL
	if	(@swscc_id		= -1)	set	@swscc_id			= NULL
	if	(@fb_id			= -1)	set	@fb_id				= NULL
	if	(@color_id		= -1)	set	@color_id			= NULL
	if	(@ff_id			= -1)	set	@ff_id				= NULL
	if	(@fs_id			= -1)	set	@fs_id				= NULL
	if	(@td_id			= -1)	set	@td_id				= NULL
	if	(@fw_id			= -1)	set	@fw_id				= NULL
	if	(@fz_id			= -1)	set	@fz_id				= NULL
	if	(@bc_id			= -1)	set	@bc_id				= NULL
	if	(@bs_id			= -1)	set	@bs_id				= NULL
	if	(@bw_id			= -1)	set	@bw_id				= NULL
	if	(@border_type	= -1)	set	@border_type		= NULL

	if	(@wsst_url		= '')	set	@wsst_url			= NULL

	-- ----------------------------------------------------------------------



	insert into tbWebSite_Styles
	(
		comp_id,
		ws_id,
		swsc_id,
		swscc_id,
		fb_id,
		color_id,
		ff_id,
		fs_id,
		td_id,
		fw_id,
		fz_id,
		bc_id,
		wsst_url,
		bs_id,
		bw_id,
		border_type
	)
	VALUES
	(
		@comp_id,
		@ws_id,
		@swsc_id,
		@swscc_id,
		@fb_id,
		@color_id,
		@ff_id,
		@fs_id,
		@td_id,
		@fw_id,
		@fz_id,
		@bc_id,
		@wsst_url,
		@bs_id,
		@bw_id,
		@border_type
	)



END
GO








