CREATE PROCEDURE [dbo].[spWebSite_WordsIni_InsertData]
(
	@wswi_id			int,
	@wswi_enabled		bit,
	@chkUpdateNoWSid	bit
)
AS
SET NOCOUNT OFF


BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------
/*

DECLARE 	@wswi_enabled		bit

SELECT		@wswi_enabled		=1

*/


------------------------------------
--Parametros de Prueba
------------------------------------

if not exists (SELECT TOP 1 1 from tbWebSite_WordsIni twsc where twsc.wswi_id = @wswi_id)
	begin


	set IDENTITY_INSERT tbWebSite_WordsIni ON


	insert into tbWebSite_WordsIni
	(
		wswi_id,
		wswi_enabled
	)
	VALUES
	(
		@wswi_id,
		@wswi_enabled
	)

	set IDENTITY_INSERT tbWebSite_WordsIni Off

	end


	else


	IF exists (SELECT TOP 1 1 from tbWebSite_WordsIni twsc where twsc.wswi_id = @wswi_id) and @chkUpdateNoWSid = 'true'
		BEGIN

			UPDATE tbWebSite_WordsIni
			SET
			wswi_enabled = @wswi_enabled

			WHERE wswi_id = @wswi_id


		END



END

GO






