CREATE PROCEDURE [dbo].[spWebSite_WordsNew_getDataByText]
(
	@text			NVARCHAR(50),
	@count			INT,
	@lang_id		INT
)
AS
SET NOCOUNT ON

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------
/*

DECLARE	@text		VARCHAR(50),
		@count		INT,
		@lang_id	INT

SELECT	@text		= 'de',
		@count		= 10,
		@lang_id	= 2

*/
------------------------------------
--Parametros de Prueba
------------------------------------


		SELECT		TOP (@count)
					t.wswn_desc,
					t.wswi_id

		FROM        dbo.tbWebSite_WordsNew			t

		WHERE		t.lang_id	=		@lang_id
		AND			t.wswn_desc	LIKE	@text + '%'

		ORDER BY	t.wswn_desc



END
GO







CREATE PROCEDURE [dbo].[spWebSite_WordsNew_getIdByDesc]
(
	@desc			NVARCHAR(4000),
	@lang_id		INT
)
AS
SET NOCOUNT ON

BEGIN
--primero insertar en dbo.tbSysWordsIni
--recuperar	@@IDENTITY
--insertar en dbo.tbSysWordsNew con lenguaje @lang_id, el id recuperado, la descripción recibida
--devolver el id recuperado


------------------------------------
--Parametros de Prueba
------------------------------------
/*

DECLARE @desc		NVARCHAR(4000),
		@lang_id	int

SET		@desc		='Usuario o password incorrectos',
		@lang_id	=2
*/

------------------------------------
------------------------------------


	IF EXISTS (	SELECT	1
				FROM	    tbWebSite_WordsNew				tswn

				WHERE	tswn.wswn_desc	= @desc
				AND		ASCII(SUBSTRING(tswn.wswn_desc,1,1))					=
										ASCII(SUBSTRING(@desc,1,1))
				AND		ASCII(SUBSTRING(tswn.wswn_desc,LEN(tswn.wswn_desc),1))	=
										ASCII(SUBSTRING(@desc,len(@desc),1))
				AND		tswn.lang_id	= @lang_id )

		BEGIN

			SELECT	top 1 tswn.wswi_id				[ID]
			FROM	tbWebSite_WordsNew				tswn

			WHERE	tswn.wswn_desc	= @desc
			AND		ASCII(SUBSTRING(tswn.wswn_desc,1,1))					=
							ASCII(SUBSTRING(@desc,1,1))
			AND		ASCII(SUBSTRING(tswn.wswn_desc,LEN(tswn.wswn_desc),1))	=
							ASCII(SUBSTRING(@desc,len(@desc),1))
			AND		tswn.lang_id	= @lang_id

		END

	ELSE

		BEGIN

   			DECLARE @id AS INT

			IF len(@desc) > 0
			BEGIN

				INSERT INTO tbWebSite_WordsIni
				(
					wswi_enabled
				)
				VALUES
				(
					'true'
				)


				SET @id = @@IDENTITY


				INSERT INTO tbWebSite_WordsNew
				(
					lang_id,
					wswi_id,
					wswn_desc
				)
				VALUES
				(
					@lang_id,
					@id,
					@desc
				)

			END

			SELECT @id

		END


END
GO







CREATE PROCEDURE [dbo].[spWebSite_WordsNew_InsertData]
(
	@lang_id			INT,
	@wswi_id			INT,
	@wswn_desc			NVARCHAR(4000),
	@chkUpdateNoWSid	bit

)
AS
SET NOCOUNT OFF


BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------
/*

DECLARE 	@lang_id		INT,
			@wswi_id		INT,
			@wswn_desc		NVARCHAR(100)

SELECT		@lang_id			=2,
			@wswi_id			=2

*/


------------------------------------
--Parametros de Prueba
------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@lang_id			= -1)	set	@lang_id				= NULL
	if	(@wswi_id			= -1)	set	@wswi_id				= NULL



	-- ----------------------------------------------------------------------


if not exists (SELECT TOP 1 1 from tbWebSite_WordsNew twsc where twsc.lang_id = @lang_id and twsc.wswi_id = @wswi_id)
	begin

	insert into tbWebSite_WordsNew
	(
		lang_id,
		wswi_id,
		wswn_desc
	)
	VALUES
	(
		@lang_id,
		@wswi_id,
		@wswn_desc
	)

	end


	else


	IF exists (SELECT TOP 1 1 from tbWebSite_WordsNew twsc where twsc.lang_id = @lang_id and twsc.wswi_id = @wswi_id) and @chkUpdateNoWSid = 'true'
		BEGIN


			update tbWebSite_WordsNew
			SET
				lang_id = @lang_id,
				wswi_id = @wswi_id,
				wswn_desc = @wswn_desc

			where lang_id= @lang_id and wswi_id = @wswi_id

end


END

GO








CREATE PROCEDURE [dbo].[spWebSiteColors_InsertData]
(

	@color_id			int,
	@color_desc			nvarchar(200),
	@color_value		nvarchar(10),
	@chkUpdateNoWSid	bit

)



as



set nocount on



begin

---------------------------------------------------------------------
-- Parametros de Prueba
---------------------------------------------------------------------
/*

Declare 	@color_id			int,
			@color_desc			nvarchar(200),
			@color_value		nvarchar(10),
			@chkUpdateNoWSid	bit


Select		@color_desc			= 'da',
			@color_value		= '5656',
			@chkUpdateNoWSid	= 'true',
			@color_id			= 100
*/


---------------------------------------------------------------------
---------------------------------------------------------------------

if not exists (SELECT TOP 1 1 from tbWebSite_Colors twsc where twsc.color_id = @color_id)
	begin


	set IDENTITY_INSERT tbWebSite_Colors ON

		Insert into tbWebSite_Colors
		(
			color_id,
			color_desc,
			color_value
		)

		Values
		(
		  @color_id,
		  @color_desc,
		  @color_value

		)

	set IDENTITY_INSERT tbWebSite_Colors off

	end


	else


	IF exists (SELECT TOP 1 1 from tbWebSite_Colors twsc where twsc.color_id = @color_id) and @chkUpdateNoWSid = 'true'
		BEGIN

			update tbWebSite_Colors

			SET color_desc  = @color_desc,
			    color_value = @color_value

			where color_id = @color_id

		END





end
GO





