CREATE PROCEDURE [dbo].[spWebSiteContacts_insertData]
(
	@comp_id				INT,
	@wsc_name				NVARCHAR (4000),
	@wsc_address			NVARCHAR (4000),
	@wsc_city				NVARCHAR (4000),
	@wsc_state				NVARCHAR (4000),
