	@wsc_zip				NVARCHAR (20),
	@wsc_phone				NVARCHAR (4000),
	@wsc_email				NVARCHAR (4000),
	@wsc_business			NVARCHAR (4000),
	@wsc_message			NVARCHAR (4000),
	@ws_id					INT,
	@return_value			INT OUTPUT
)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id				INT,
			@wsc_name				NVARCHAR (4000),
			@wsc_address			NVARCHAR (4000),
			@wsc_city				NVARCHAR (4000),
			@wsc_state				NVARCHAR (4000),
			@wsc_country			NVARCHAR (4000),
			@wsc_zip				NVARCHAR (20),
			@wsc_phone				NVARCHAR (4000),
			@wsc_email				NVARCHAR (4000),
			@wsc_business			NVARCHAR (4000),
			@wsc_message			NVARCHAR (4000),
			@ws_id					INT

SELECT		@comp_id				=1,
			@wsc_name				='',
			@wsc_address			='',
			@wsc_city				='',
			@wsc_state				='',
			@wsc_country			='',
			@wsc_zip				='',
			@wsc_phone				='',
			@wsc_email				='',
			@wsc_business			='',
			@wsc_message			='',
			@ws_id					2

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@comp_id				= -1)	set	@comp_id						= NULL
	--if	(@ws_id					= -1)	set	@ws_id							= NULL



	-- ----------------------------------------------------------------------



		INSERT INTO tbWebSite_Contacts
		(
			comp_id,
			wsc_name,
			wsc_address,
			wsc_city,
			wsc_state,
			wsc_country,
			wsc_zip,
			wsc_phone,
			wsc_email,
			wsc_business,
			wsc_message,
			wsc_cd
		)
		VALUES
		(
			@comp_id,
			@wsc_name,
			@wsc_address,
			@wsc_city,
			@wsc_state,
			@wsc_country,
			@wsc_zip,
			@wsc_phone,
			@wsc_email,
			@wsc_business,
			@wsc_message,
			GETDATE()
		)

	set	@return_value = @@identity


END
GO








CREATE PROCEDURE [dbo].[spWebSiteFiles_InsertData]
(
	@ws_fileName			nvarchar(200),
	@ws_fileContent			Image,
	@ws_code				int,
	@ws_fileLength			decimal(19,0),
	@chkUpdateNoWSid		bit,
	@return_value			INT OUTPUT
)
as


set nocount on


BEGIN

	---------------------------------------------------------------------
	---------------------------------------------------------------------
	/*

	Declare 	@ws_fileid			int,
				@ws_fileName		nvarchar(200),
				@ws_fileContent		Image,
				@ws_code			int,
				@ws_fileLength		decimal(19,0),
				@chkUpdateNoWSid	bit

	Select		@ws_fileid			= 598,
				@ws_fileName		= 'cssTPaz_Menu.css',
				@ws_fileContent		= NULL,
				@ws_code			= 2,
				@ws_fileLength		= 2971,
				@chkUpdateNoWSid	='false'
*/
	---------------------------------------------------------------------
	---------------------------------------------------------------------

	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@ws_code			= -1)	set	@ws_code				= NULL


	-- ----------------------------------------------------------------------


if not exists (SELECT TOP 1 1 from tbWebSite_Files twsf  WHERE twsf.ws_fileName = @ws_fileName AND twsf.ws_code = @ws_code)
	begin

		Insert into tbWebSite_Files
		(
			ws_fileName,
			ws_fileContent,
			ws_code,
			ws_fileLength
		)
		VALUES
		(
			@ws_fileName,
			@ws_fileContent,
			@ws_code,
			@ws_fileLength
		)


		SET @return_value = @@IDENTITY

end


	else


	IF exists (SELECT TOP 1 1 from tbWebSite_Files twsf  WHERE twsf.ws_fileName = @ws_fileName AND twsf.ws_code = @ws_code) and @chkUpdateNoWSid = 'true'
		BEGIN


			update tbWebSite_Files
			SET
					ws_fileContent		= @ws_fileContent,
					ws_fileLength		= @ws_fileLength,
					@return_value		= ws_fileId

			WHERE	ws_fileName		= @ws_fileName
			AND		ws_code			= @ws_code

		END



UPDATE	tbWebSite_Names
SET		ws_files2TempUpdated				= 'false',
		ws_files2TempUpdated4Development	= 'False'

SET @return_value = 0


END



GO





