CREATE PROCEDURE [dbo].[spWebSiteII_ActivityLOG_insertdata]

(

	@comp_id			INT,
	@bra_id				INT,
	@ws_id				UNIQUEIDENTIFIER,
	@page_id			UNIQUEIDENTIFIER,
	@wsm_url			NVARCHAR(500),
	@wsm_IP				NVARCHAR(50),
	@wsm_cd				DATETIME,
	@wsm_ptyGUIDCookie	VARCHAR(50),
	@cust_id			INT,
	@contact_id			INT,
	@user_id			INT,
	@prli_id			INT,
	@stor_id			INT,
	@st_id				INT,
	@cc_id				INT,
	@ccp_id				INT,
	@lang_id			INT,
	@camp_id			INT,
	@item_id			INT


)

AS

SET NOCOUNT ON

BEGIN



	-------------------------------------------------------------------
	--Parametros de Prueba
	-------------------------------------------------------------------
	/*
	DECLARE
				@comp_id			INT,
				@bra_id				INT,
				@ws_id				UNIQUEIDENTIFIER,
				@page_id			UNIQUEIDENTIFIER,
				@wsm_url			NVARCHAR(500),
				@wsm_IP				NVARCHAR(50),
				@wsm_cd				DATETIME,
				@wsm_ptyGUIDCookie	UNIQUEIDENTIFIER,
				@cust_id			INT,
				@contact_id			INT,
				@user_id			INT,
				@prli_id			INT,
				@stor_id			INT,
				@st_id				INT,
				@cc_id				INT,
				@ccp_id				INT,
				@lang_id			INT,
				@camp_id			INT


	SELECT
				@comp_id				=1,
				@ws_id					='2121dsa-asdsa-sad-adsdsaasd-dwewe2e',
				@page_id				='2121dsa-asdsa-sad-adsdsaasd-dwewe2e',
				@wsm_ptyGUIDCookie		='2121dsa-asdsa-sad-adsdsaasd-dwewe2e',
				@bra_id					=1
	*/
	-------------------------------------------------------------------


	IF @wsm_ptyGUIDCookie	= '00000000-0000-0000-0000-000000000000' SET @wsm_ptyGUIDCookie = NULL
	IF @ws_id				= '00000000-0000-0000-0000-000000000000' SET @ws_id = NULL
	IF @page_id				= '00000000-0000-0000-0000-000000000000' SET @page_id = NULL

	if	(@bra_id			= -1)	set	@bra_id				= NULL
	if	(@cust_id			= -1)	set	@cust_id			= NULL
	if	(@contact_id		= -1)	set	@contact_id			= NULL
	if	(@user_id			= -1)	set	@user_id			= NULL
	if	(@prli_id			= -1)	set	@prli_id			= NULL
	if	(@stor_id			= -1)	set	@stor_id			= NULL
	if	(@st_id				= -1)	set	@st_id				= NULL
	if	(@cc_id				= -1)	set	@cc_id				= NULL
	if	(@ccp_id			= -1)	set	@ccp_id				= NULL
	if	(@lang_id			= -1)	set	@lang_id			= NULL
	if	(@camp_id			= -1)	set	@camp_id			= NULL
	if	(@item_id			= -1)	set	@item_id			= NULL


	INSERT INTO tbWebSiteII_ActivityLOG	WITH (ROWLOCK)
	(
		comp_id,
		bra_id,
		ws_id,
		page_id,
		wsm_url,
		wsm_IP,
		wsm_cd,
		wsm_ptyGUIDCookie,
		cust_id,
		contact_id,
		[user_id],
		prli_id,
		stor_id,
		st_id,
		cc_id,
		ccp_id,
		lang_id,
		camp_id,
		item_id
	)
	VALUES
	(
		@comp_id,
		@bra_id	,
		@ws_id,
		@page_id,
		@wsm_url,
		@wsm_IP,
		GETDATE()		,
		@wsm_ptyGUIDCookie	,
		@cust_id	,
		@contact_id			,
		@user_id,
		@prli_id,
		@stor_id,
		@st_id,
		@cc_id	,
		@ccp_id	,
		@lang_id,
		@camp_id,
		@item_id
	)


END
GO





CREATE PROCEDURE [dbo].[spWebSiteII_Cart_DeleteDataByGuid]
(
	@tis_guid			UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON

	DELETE
		FROM tbTempItemStock
		WHERE tis_guid = @tis_guid

END
GO





CREATE PROCEDURE [dbo].[spWebSiteII_Cart_DeleteDataByItemOrTisId]
(
	@tis_guid			UNIQUEIDENTIFIER,
	@item_id			INT,
	@tis_id				INT
)
AS

BEGIN

	SET NOCOUNT ON

	DECLARE @tis_id_origin AS INT
	SELECT @tis_id_origin = tis_id_origin
		FROM tbTempItemStock
		WHERE tis_guid = @tis_guid
				AND
			( tis_id = @tis_id OR item_id = @item_id )
				AND
			tis_id_origin IS NOT NULL


	DELETE
		FROM tbTempItemStock
		WHERE tis_guid = @tis_guid
				AND
			( tis_id = @tis_id OR item_id = @item_id )

	-- Si era una parte de un equipo que borre a todas
	IF @tis_id_origin IS NOT NULL
		BEGIN

			DELETE
				FROM tbTempItemStock
				WHERE tis_guid = @tis_guid
						AND
					tis_id_origin = @tis_id_origin

		END


END
GO


CREATE PROCEDURE [dbo].[spWebSiteII_Cart_Get_wssql_id_ByGuid]
(
	@tis_guid			UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON

	SELECT	TOP 1
			ISNULL(tdf.wssql_id4WebSiteCart_preSaveSaleOrder,-1)		[wssql_id4WebSiteCart_preSaveSaleOrder],
			ISNULL(tdf.wssql_id4WebSiteCart_postSaveItemCart,-1)		[wssql_id4WebSiteCart_postSaveItemCart]
		FROM tbTempItemStock	   AS tis		WITH (NOLOCK)
		INNER JOIN tbDocumentsFile AS tdf		WITH (NOLOCK)
			ON	tdf.comp_id = tis.comp_id AND
				tdf.df_id	= tis.df_id
		WHERE tis_guid = @tis_guid

END
GO




CREATE PROCEDURE [dbo].spWebSiteII_Cart_GetQTYByTis_ID
(


	@comp_id					INT,
	@tis_id						INT,
	@guid						UNIQUEIDENTIFIER

)
AS


BEGIN

	-- Retorna la Cantidad en que quedó finalmente
	DECLARE @intUpdatedQTY AS DECIMAL(30,2) = 0
	SELECT  @intUpdatedQTY = ttis.tis_qty
		FROM tbTempItemStock AS ttis		WITH (NOLOCK)
		WHERE	comp_id = @comp_id	AND
				tis_id	= @tis_id

	SELECT @intUpdatedQTY


END
GO





CREATE PROCEDURE [dbo].[spWebSiteII_Cart_MinusDataByItemOrTisId]
(
	@tis_guid			UNIQUEIDENTIFIER,
	@item_id			INT,
	@tis_id				INT
)
AS

BEGIN

	SET NOCOUNT ON

	DECLARE @bolIsOK AS BIT
	SELECT @bolIsOK = 'False'

	UPDATE tbTempItemStock
		SET tis_qty = tis_qty - 1
		WHERE tis_guid = @tis_guid
				AND
			( tis_id = @tis_id OR item_id = @item_id )
				AND
			  tis_id_origin IS NULL

	IF @@ROWCOUNT > 0
		BEGIN
			SET @bolIsOK = 'True'
		END


	DELETE FROM tbTempItemStock
		WHERE tis_guid = @tis_guid
				AND
			( tis_id = @tis_id OR item_id = @item_id )
				AND
			  tis_qty <= 0

	IF @@ROWCOUNT > 0
		BEGIN
			SET @bolIsOK = 'True'
		END

	SELECT @bolIsOK [isDeleted]


END
GO




CREATE PROCEDURE [dbo].[spWebSiteII_Cart_SaleOrder_insertDataFromWeb]
	(
	 @comp_id		INT,
	 @lang_id		INT,
	 @guid			UNIQUEIDENTIFIER,
	 @ws_id			UNIQUEIDENTIFIER,
	 @cust_id		INT,
	 @st_id			INT,
	 @dl_id			INT,
	 @disc_id		INT,
	 @ccp_id		INT,
	 @ws_paymentGateWayStatusID		INT,
	 @ws_paymentGateWayReferenceID	UNIQUEIDENTIFIER,
	 @CustIDLogged					INT,
	 @st_id_logged					INT,
	 @dl_id_logged					INT,
	 @obser1						VARCHAR(350),
	 @obser2						VARCHAR(350),
	 @obser3						VARCHAR(350),
	 @obser4						VARCHAR(350),
	 @obserHTML						VARCHAR(MAX),
	 @ssos_id                       INT,
	 @strDeliveryAddress			VARCHAR(4000),
	 @soh_internalAnnotation		VARCHAR(100),
	 @return_value					INT				OUTPUT,
	 @errormessage					NVARCHAR(500)	OUTPUT

	)
AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------
	-- Testing
	-- -----------------------------------------------------------------
	/*
	DECLARE @comp_id   INT,
	@lang_id   INT,
	@guid    UNIQUEIDENTIFIER,
	@ws_id    INT,
	@cust_id   INT,
	@errormessage  varchar(500)
	SELECT @comp_id   =1,
	@lang_id   =2,
	@guid    ='C89F9176-33FC-4BDD-B649-28C40529B15A',
	@ws_id    =14,
	@cust_id   =24288

	IF NOT OBJECT_ID('tempdb.dbo.#tmpGetTotalsData') IS NULL DROP TABLE #tmpGetTotalsData
	*/
	-- -----------------------------------------------------------------


	DECLARE @wsIPFrom AS NVARCHAR(50)
	SET		@wsIPFrom = ''
	SELECT TOP 1 @wsIPFrom = isnull(ttis.ws_IPFrom,'')
		FROM tbTempItemStock ttis WITH (NOLOCK)
		WHERE ttis.tis_guid = @guid


	--declare @return_value int
	set  @return_value = 0
	set  @errormessage = ''



	IF @lang_id < 1 SET @lang_id = 2







	DECLARE @item_id					INT,
			@tis_qty					DECIMAL(19,6),
			@ws_PotentialStockLimit		INT,
			@potential_stock			DECIMAL(19,6),
			@stor_id					INT,
			@bra_id						INT,
			@user_id					INT,
			@prof_id					INT,
			@bra_SaleOrderDisposeLimitDay  INT,
			@tis_priority				DECIMAL(14,4),
			@df_id						INT = NULL ,
			@sd_id						INT,
			@ws_internalID				INT,
			@bra_id_Currency			INT,
			@storg_id					INT



	DECLARE @sm_id	INT = NULL


	--obtenemos valores de tbWebSite_Names
	SELECT	@ws_PotentialStockLimit = 100,   --//twsn.ws_PotentialStockLimit,
			@stor_id				= twsn.stor_id,
			@bra_id					= twsn.bra_id,
			@user_id				= twsn.[user_id],
			@prof_id				= twsn.prof_id,
			@sd_id					= twsn.sd_id,
			@ws_internalID			= twsn.ws_internalID,
			@sm_id					= sm_id,
			@storg_id				= twsn.storg_id
		FROM tbWebSiteII_Names twsn   WITH (NOLOCK)
		WHERE	twsn.comp_id	= @comp_id	AND
				twsn.ws_id		= @ws_id




	SELECT @bra_id_Currency = tb.curr_id
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id



	-- -----------------------------------------------------
	-- Obtiene un tipo de documento valido
	-- -----------------------------------------------------
	--DECLARE @tmpDocuments TABLE(id INT,[desc] NVARCHAR(1000))
	--INSERT INTO @tmpDocuments EXEC spDocumentsFile_GetComboOfCustomerDocuments @comp_id, @bra_id , @cust_id , @prof_id ,@sd_id

	--SELECT TOP 1 @df_id   = tdf.df_id
	-- FROM tbDocumentsFile tdf    WITH (NOLOCK)
	--  INNER JOIN @tmpDocuments tmp
	--   ON tmp.id = tdf.df_id
	-- WHERE tdf.sd_id   = @sd_id
	-- ORDER BY tdf.df_order


	IF @prof_id > 0		-- **wefklnw9874lknlknl  MOS 10-2021 x USA
		BEGIN

			SELECT TOP 1 @df_id = tdf.df_id
				FROM tbDocumentsFileAdditionalByFiscalClass AS dfc	WITH (NOLOCK)
				INNER JOIN tbCustomer						AS tc	WITH (NOLOCK)
					ON	tc.comp_id		= @comp_id		AND
						tc.cust_id		= @cust_id
				INNER JOIN tbDocumentsFile					AS tdf	WITH (NOLOCK)
					ON	tdf.comp_id		= dfc.comp_id	AND
						tdf.df_id		= dfc.df_id
				WHERE	dfc.comp_id		= @comp_id		AND
						dfc.fc_id		= tc.fc_id		AND
						dfc.bra_id		= @bra_id		AND
						dfc.prof_id		= @prof_id		AND
						tdf.sd_id		= @sd_id
				ORDER BY
						CASE
							WHEN tdf.df_favorite4WebSite = 1 THEN 0
							ELSE								  1
						END,
						df_order

		END


	IF @df_id IS NULL
		BEGIN
			SELECT TOP 1 @df_id = df_id
				FROM  dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
				WHERE sd_id   = @sd_id --AND
				--df_pointOfSale = @PointOfSale
				ORDER BY CASE
							WHEN is4WS = 1 THEN 0
							ELSE				1
						 END,
						 df_order
		END


	IF @df_id IS NULL
		BEGIN
			SELECT TOP 1 @df_id = df_id
				FROM  dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
				WHERE sd_id   = @sd_id
				ORDER BY
							CASE
								WHEN is4WS = 1 THEN 0
								ELSE    1
							END,
							df_order
		END


	-- -----------------------------------------------------



	-- Si se admiten nuevos clientes pero estoy conectado como Invitado..
	IF EXISTS (	SELECT TOP 1 1
					FROM tbWebSiteII_Names   twsn   WITH (NOLOCK)

					WHERE twsn.comp_id				= @comp_id
					AND  twsn.ws_id					= @ws_id
					AND  twsn.ws_newCustomerAllowed = 'True'
					AND  twsn.ws_newCustomerCustId	= @cust_id
				)

	BEGIN

		SET @return_value = -14

		SELECT @errormessage = tut.utexts_desc
			FROM tbsysUniqueTexts tut     WITH (NOLOCK)
			WHERE	tut.lang_id		= @lang_id AND
					tut.utexts_id	= 90
		RETURN @return_value

	END



	-- Si NO se admiten nuevos y estoy conectado como invitado...
	IF EXISTS (	SELECT TOP 1  1
					FROM tbWebSiteII_Names   twsn   WITH (NOLOCK)
					WHERE twsn.comp_id				= @comp_id
					AND  twsn.ws_id					= @ws_id
					AND  twsn.ws_newCustomerAllowed = 'False'
					AND  twsn.ws_newCustomerCustId	= @cust_id)

		BEGIN

			SET @return_value = -15

			SELECT @errormessage = tut.utexts_desc
				FROM tbsysUniqueTexts tut     WITH (NOLOCK)
				WHERE	tut.lang_id		= @lang_id	AND
						tut.utexts_id	= 89
			RETURN @return_value

		END



	DECLARE @currId_IncrementByPercent		AS BIT = 'False'
	DECLARE @bitHasIncrementBySalesTerms	AS BIT = 'False'
	SELECT  @bitHasIncrementBySalesTerms =	CASE
	                                     	    WHEN	tst.curr_id_4Increment	IS NOT NULL			AND
	                                     				tst.curr_id_4Increment	<> @bra_id_Currency AND
	                                     				tst.currId_Increment	<> 0 THEN	'True'
	                                     	    ELSE										'False'
	                                     	END,
	        @currId_IncrementByPercent = ISNULL(tst.currId_IncrementByPercent,'False')
		FROM tbSalesTerms tst WITH (NOLOCK)
		WHERE	tst.comp_id = @comp_id AND
				tst.st_id	= @st_id





	--se controla que haya artículos cargados en la temporal
	IF NOT EXISTS (SELECT TOP 1 1
					  FROM tbTempItemStock ttis  WITH (NOLOCK)
					  WHERE ttis.comp_id	= @comp_id AND
							ttis.tis_guid	= @guid)

		BEGIN
			SET @return_value = -1
			SELECT @errormessage = tut.utexts_desc
				FROM tbsysUniqueTexts tut    WITH (NOLOCK)
				WHERE	tut.lang_id		= @lang_id AND
						tut.utexts_id	= 99
			RETURN @return_value
			--SELECT 1
		END

	ELSE

		BEGIN

			IF @df_id IS NULL
				BEGIN
					SET @return_value = -2
					SELECT @errormessage = tut.utexts_desc
						 FROM tbsysUniqueTexts tut   WITH (NOLOCK)
						 WHERE	tut.lang_id		= @lang_id AND
								tut.utexts_id	= 91
					RETURN @return_value
				END

			ELSE

				BEGIN


					-- -----------------------------------------------------------------------------------------------
					-- Colucci
					-- se hace la asignacion dinamica de depositos en base a la disponibilidad y el orden definido en el Grupo de Depositos
					-- -----------------------------------------------------------------------------------------------
					IF @storg_id IS NOT NULL
						BEGIN

							DECLARE @stor_id_ActualAssigned AS INT
							DECLARE @tis_id_ActualAssigned  AS INT
							DECLARE cursor_tisSG CURSOR LOCAL FAST_FORWARD FOR
							SELECT	ttis.item_id,
									ttis.tis_qty,
									ttis.tis_priority,
									ttis.stor_id,
									ttis.tis_id
								 FROM tbTempItemStock   ttis  WITH (NOLOCK)
								 WHERE	ttis.comp_id	= @comp_id	AND
										ttis.tis_guid   = @guid		AND
										--esto se agrega para no controlar stock de los cargos por flete y seguro
										ttis.tis_priority  < 1	AND
										NOT ttis.[user_id]  IS NULL	AND
										ttis.tis_StockStatus < 0



							OPEN cursor_tisSG
							FETCH cursor_tisSG
								INTO @item_id, @tis_qty, @tis_priority,@stor_id_ActualAssigned,@tis_id_ActualAssigned

							WHILE @@FETCH_STATUS = 0
								BEGIN

									DECLARE			@stor_idTMP AS integer = NULL
									SELECT TOP 1	@stor_idTMP = stor_id
										FROM tbStorageGroupDetail AS tsgd	WITH (NOLOCK)
										WHERE	tsgd.comp_id	= @comp_id		AND
												tsgd.storg_id	= @storg_id		AND
												dbo.fnGetAStock4MaxAssociation(tsgd.comp_id,tsgd.stor_id,@item_id,999999999) > 0
										ORDER BY tsgd.storg_order4WebSite	ASC

									IF @stor_idTMP IS NOT NULL
										BEGIN
											UPDATE tbTempItemStock
												SET stor_id = @stor_idTMP
											WHERE	comp_id = @comp_id AND
													tis_id	= @tis_id_ActualAssigned
										END

									FETCH cursor_tisSG
										INTO @item_id, @tis_qty, @tis_priority,@stor_id_ActualAssigned,@tis_id_ActualAssigned
								END
							CLOSE cursor_tisSG
							DEALLOCATE cursor_tisSG


						END
					-- -----------------------------------------------------------------------------------------------




					-- -----------------------------------------------------------------------------------------------
					--se controla que no se supere el porcentaje de stock potencial seteado en tbwebsite_names
					--de lo que se está cargando en el pedido de cada artículo
					-- -----------------------------------------------------------------------------------------------
					DECLARE cursor_tis CURSOR LOCAL FAST_FORWARD FOR
					SELECT	ttis.item_id,
							ttis.tis_qty,
							ttis.tis_priority
						 FROM tbTempItemStock   ttis  WITH (NOLOCK)
						 WHERE	ttis.comp_id	= @comp_id	AND
								ttis.tis_guid   = @guid		AND

					 --esto se agrega para no controlar stock de los cargos por flete y seguro
								ttis.tis_priority  < 1	AND
								NOT ttis.[user_id]  IS NULL	AND
								ttis.tis_StockStatus < 0



					OPEN cursor_tis
					FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority

					WHILE @@FETCH_STATUS = 0 and @return_value = 0
						BEGIN

							SET @potential_stock = dbo.fnGetAStock(@comp_id, @stor_id, @item_id, @tis_priority)


							-- ---------------------------------------------------------------------
							--Si la cantidad a reservar en el pedido (@tis_qty) es mayor que el porcentaje de stock potencial disponible
							--para la venta on line (@potential_stock * @ws_PotentialStockLimit / 100) se muestra un mensaje que le
							--indica al cliente conectado que no hay stock disponible
							-- ---------------------------------------------------------------------
							IF @tis_qty > ((@potential_stock + @tis_qty) * @ws_PotentialStockLimit / 100)
								BEGIN
									SET @return_value = -3

									SELECT @errormessage = tut.utexts_desc + ti.item_code + '-' + ti.item_desc
										FROM tbsysUniqueTexts tut	WITH (NOLOCK)
										INNER JOIN tbItem ti		WITH (NOLOCK)
											ON ti.comp_id = @comp_id	AND
											   ti.item_id = @item_id
										WHERE tut.lang_id	= @lang_id	AND
											  tut.utexts_id = 98
								END


							FETCH cursor_tis INTO @item_id, @tis_qty, @tis_priority
						END
					CLOSE cursor_tis
					DEALLOCATE cursor_tis
					-- -----------------------------------------------------------------------------------------------

					--si no hubo errores por stock se genera el pedido
					IF @return_value = 0

						BEGIN

							BEGIN TRANSACTION
							BEGIN TRY


								--SET @return_value = 0

								DECLARE @lsoh_id						INT,
										--@sm_id							INT,
										@rv								INT,
										--@st_id       INT,
										--@disc_id      INT,
										--@dl_id       INT,
										@total							DECIMAL(19,6),
										@curr_id_branch					INT,
										@curr_id_cust					INT,
										@ExchangeToCustomerCurrency		DECIMAL(38,25),   -- MOS 01-2024 DECIMAL(29,10),
										@soh_discount					DECIMAL(19,6),
										@bra_PriceDecimalPlaces			INT,
										@curr_id4Exchange				INT



								-- obtengo el documento para REMITOS asociado a este documento si es que lo tiene.. .
								DECLARE @bitFijarTipoDeCambio AS BIT = 'False'
								DECLARE @intDFId4PackingList  AS INT
								SET		@intDFId4PackingList	= NULL
								SELECT  @intDFId4PackingList	= tdf.df_SaleOrderPL_df_Id,
										@bitFijarTipoDeCambio	= ISNULL(tdf.df_SaleOrderPersistExchange4WebSite,'False')
									FROM tbDocumentsFile tdf  WITH (NOLOCK)
									WHERE	tdf.comp_id = @comp_id AND
											tdf.df_id	= @df_id


								SELECT	@sm_id			=	CASE
																WHEN @sm_id IS NULL THEN	tc.sm_id
																ELSE						@sm_id
															END,
										@disc_id		= IsNull(@disc_id,tc.disc_id),
										@curr_id_cust	= tc.curr_id
									FROM tbCustomer   tc   WITH (NOLOCK)
									WHERE tc.comp_id	= @comp_id
									AND  tc.cust_id		= @cust_id




								-- Si posee Incrementos por Condicion de Venta se comporta diferente.
								IF @bitHasIncrementBySalesTerms = 'True'
									BEGIN
										-- Modificacion sugerida por Dario de GN
										SELECT	@curr_id_branch					= tb.curr_id,
												@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
												@bra_SaleOrderDisposeLimitDay	= CASE
																						WHEN tb.bra_SaleOrderDisposeLimitDays > 5000 THEN 5000
																						ELSE tb.bra_SaleOrderDisposeLimitDays
																				  END,
												--@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
												--@curr_id4Exchange				= curr_id4Exchange
												@curr_id_cust = curr_id4Exchange -- cambio dario 12/09/2017 para que los pedidos web se aplica el incremento de cotizacion segun condicion de venta
											FROM tbBranch   tb   WITH (NOLOCK)
											WHERE tb.comp_id	= @comp_id
											AND  tb.bra_id		= @bra_id
									END
								ELSE
									BEGIN
										SELECT	@curr_id_branch					= tb.curr_id,
												@bra_PriceDecimalPlaces			= tb.bra_PriceDecimalPlaces,
												--@bra_SaleOrderDisposeLimitDay	= tb.bra_SaleOrderDisposeLimitDays,
												@bra_SaleOrderDisposeLimitDay	= CASE
																						WHEN tb.bra_SaleOrderDisposeLimitDays > 5000 THEN 5000
																						ELSE tb.bra_SaleOrderDisposeLimitDays
																				  END,
												@curr_id4Exchange				= curr_id4Exchange -- agrego dario 12/09/2017 para que los pedidos web se aplica el incremento de cotizacion segun condicion de venta
											FROM tbBranch   tb   WITH (NOLOCK)
											WHERE tb.comp_id	= @comp_id
											AND  tb.bra_id		= @bra_id
									END






								/*
								SELECT  @total = sum(ttis.tis_qty *
								   dbo.fnGetExchange(@comp_id, ttis.tis_price, ttis.curr_id, @curr_id_branch,0,0,'false'))
								FROM tbTempItemStock ttis
								WHERE ttis.comp_id = @comp_id AND ttis.tis_guid = @guid
								*/


								CREATE TABLE #tmpGetTotalsData
								(
								t1  INT,
								t2  DECIMAL(18,2),
								t3  DECIMAL(19,6),
								t4  DECIMAL(19,6),
								t5  DECIMAL(19,6),
								t6  DECIMAL(18,2),
								t7  DECIMAL(19,5),
								t8  INT,
								t9  DECIMAL(19,6),
								T10  NVARCHAR(4000),
								T11  DECIMAL(30,4)
								)

								INSERT INTO #tmpGetTotalsData
									EXEC spWebSiteII_Cart_TaxCalculate @comp_id, @guid, @ws_id, @cust_id, @st_id, @dl_id, -1, @disc_id

								SELECT	@total   = t2,
										@soh_discount = ROUND(t4, @bra_PriceDecimalPlaces)
									FROM #tmpGetTotalsData



								DECLARE @currId_Increment	as Decimal(29,10) = 0

								IF @bitHasIncrementBySalesTerms = 'True'
									BEGIN
										-- Modificacion sugerida por Dario de GN
										declare @ce_exchange		as Decimal(29,10)
										select	@ce_exchange = ce_exchange
											from tbCurrencyExchange		WITH (NOLOCK)
											where curr_id_1 = @curr_id_branch and
												  curr_id_2 = @curr_id_cust
										select @currId_Increment = currId_Increment
											from tbSalesTerms			WITH (NOLOCK)
											where	st_id				= @st_id		and
													curr_id_4Increment	= @curr_id_cust and
													st_disabled			= 0
										IF @currId_IncrementByPercent = 'False'
											BEGIN
												SET @ExchangeToCustomerCurrency = 1 / dbo.fnNoZDiv(@ce_exchange + @currId_Increment)
											END
										ELSE	-- MOS 07-2022 x HDC
											BEGIN
												SET @ExchangeToCustomerCurrency = 1 / dbo.fnNoZDiv(@ce_exchange + (@ce_exchange *  @currId_Increment / 100))
											END

									END
								ELSE
									BEGIN

										SET @ExchangeToCustomerCurrency = dbo.fnGetExchange(@comp_id,1,@curr_id4Exchange,@curr_id_branch,0,0,'false')

										-- ---------------------------------------------
										-- Toma el INCREMENTO por Condicion de Venta  MOS 10-2017
										-- ---------------------------------------------
										select  @currId_Increment = currId_Increment
											from tbSalesTerms	WITH (NOLOCK)
											where	comp_id				= @comp_id	AND
													st_id				= @st_id	and
													curr_id_4Increment	= @curr_id4Exchange AND
													st_disabled			= 0

										SET @ExchangeToCustomerCurrency = @ExchangeToCustomerCurrency + @currId_Increment
										-- ---------------------------------------------

									END





								DECLARE @getdate	DATETIME
								DECLARE @limitdate  DATETIME
								DECLARE @onlydate	DATETIME

								SET  @getdate = GETDATE()
								SELECT @onlydate = DATEADD(dd, 0, DATEDIFF(dd, 0, @getdate))
								SET  @limitdate = @onlydate + @bra_SaleOrderDisposeLimitDay


								DECLARE @floCurrID4FijarTipoDeCambio	AS FLOAT	= 1
								DECLARE @intCurrID4FijarTipoDeCambio	AS INT		= @curr_id_cust
								DECLARE @bitCurrID_InvertirTipoDeCambio AS BIT		= 'False'
								IF @bitFijarTipoDeCambio = 'True'
									BEGIN
										SET @intCurrID4FijarTipoDeCambio = @curr_id4Exchange
										IF  @intCurrID4FijarTipoDeCambio <> @curr_id_branch SET @bitCurrID_InvertirTipoDeCambio = 'True'
									END
								SET @floCurrID4FijarTipoDeCambio =
									CASE
										WHEN @bitCurrID_InvertirTipoDeCambio = 'False' THEN		@ExchangeToCustomerCurrency
										ELSE													1 / dbo.fnNoZDiv(@ExchangeToCustomerCurrency)
									END


								-- ----------------------------------------------
								-- Si hay Cupones Usados sumo 1 a la cantidad usada  -- MOS 08-2020, esto estaba abajo en donde ya no existian mas los datos en tbtempitemstock
								-- ----------------------------------------------
								BEGIN TRY
									;WITH tmpCoupon AS
										(SELECT DISTINCT ttis.wscup_id
											FROM tbTempItemStock ttis		WITH (NOLOCK)
												WHERE	ttis.comp_id	= @comp_id AND
														ttis.tis_guid	= @guid)

									UPDATE tbWebSiteII_DiscountCoupon		WITH (ROWLOCK)
										SET wscup_usedQTY	= ISNULL(wscup_usedQTY,0) + 1,
											wscup_disabled	= CASE
			              										  WHEN wscup_usedQTY = wscup_initQTY THEN	'True'
			              										  ELSE										wscup_disabled
			              									  END
										FROM tbWebSiteII_DiscountCoupon	dc
										INNER JOIN tmpCoupon ttis
											ON	ttis.wscup_id	= dc.wscup_id
										WHERE	dc.comp_id		= @comp_id

								END TRY
								BEGIN CATCH
								END CATCH
								-- ----------------------------------------------


								EXEC spSaleOrder_insertData
									-1,
									@guid,
									@comp_id,
									@bra_id,
									@onlydate,
									@onlydate,
									'',
									'',
									'',
									'',
									'false',
									@sm_id,
									@cust_id,
									@st_id,
									@disc_id,
									@dl_id,
									null,
									@onlydate,
									@limitdate,
									1,    --+------------------------------------------------------------------------------------
									'A',   --|estos 3 campos van así en duro, está igual que en el código de wfmSaleOrder.aspx.vb
									1,    --+------------------------------------------------------------------------------------
									@user_id,
									'false',
									@getdate,
									@total,
									@df_id,
									@ssos_id ,		--5 Pendiente WEB
									@floCurrID4FijarTipoDeCambio	-- MOS 06-2020
									/*@ExchangeToCustomerCurrency*/,
									@intCurrID4FijarTipoDeCambio /*@curr_id_cust  MOS 06-2020*/  , --  NOOOOOOOOO, estaba MALLLLL !!!!!!, dejar con @curr_id_cust !!!!!!   @curr_id4Exchange ,  -- @curr_id_cust,  MOS 10-2017 x GN Dario
									null,
									NULL,
									@return_value = @rv OUTPUT



								EXEC spSaleOrderHeader_updatePL_df_id
									@comp_id,
									@bra_id,
									@rv,
									@intDFId4PackingList,
									null,
									@soh_discount,
									''



								EXEC spSaleOrder_updateCurrExchange
									@comp_id,
									@bra_id,
									@rv,
									@curr_id_cust,
									@ExchangeToCustomerCurrency,
									0 --@decInCash


								IF @ccp_id > 0
									BEGIN
										UPDATE tbsaleorderHeader	WITH (ROWLOCK)
											SET ccp_id = @ccp_id
											WHERE	comp_id = @comp_id	AND
													bra_id	= @bra_id	AND
													soh_id	= @rv
									END

								UPDATE tbsaleorderHeader			WITH (ROWLOCK)
									SET ws_paymentGateWayStatusID		= @ws_paymentGateWayStatusID ,
										ws_paymentGateWayReferenceID	= @ws_paymentGateWayReferenceID,
										ws_internalID					= @ws_internalID,
										ws_cust_Id						= @CustIDLogged,
										ws_IPFrom						= @wsIPFrom,
										ws_st_id						= @st_id_logged,
										ws_dl_id						= @dl_id_logged,
										soh_observation1 = @obser1,
										soh_observation2 = @obser2,
										soh_observation3 = @obser3,
										soh_observation4 = @obser4,
										soh_htmlNote	 = @obserHTML,
										soh_deliveryAddress		= @strDeliveryAddress,
										soh_internalAnnotation	= @soh_internalAnnotation
									WHERE	comp_id = @comp_id	AND
											bra_id	= @bra_id	AND
											soh_id	= @rv



								SET @return_value = @rv


								COMMIT TRANSACTION


							END	TRY
							BEGIN CATCH
								--SELECT ERROR_LINE(), ERROR_MESSAGE(), ERROR_NUMBER()
								ROLLBACK TRANSACTION
								SET @return_value = -10
								SET @errormessage = ERROR_MESSAGE()
							END CATCH

						END

				END

		END



	----------------------------------------------------------------------------------------------------------------
	----------------------------------------------------------------------------------------------------------------
	-- se envía notificación al cliente y al vendedor por medio de emails si se pudo grabar el pedido correctamente
	----------------------------------------------------------------------------------------------------------------
	IF @return_value > 0
		BEGIN

			DECLARE	@precipients		NVARCHAR(MAX),
					@strCopyRecipients  NVARCHAR(MAX),
					@subject			NVARCHAR(MAX),
					@body2				NVARCHAR(MAX),
					@lsm_id				INT


			SET @strCopyRecipients	= ''
			SET @precipients		= ''
			--recuparamos el email y el vendedor del cliente
			DECLARE @strWebLogin AS NVARCHAR(MAX)
			DECLARE @strReplyTo  AS NVARCHAR(MAX)
			SET  @strWebLogin = ''
			SELECT	@precipients  = ISNULL(tc.cust_email,''),
					@lsm_id    = tc.sm_id,
					@strWebLogin  = isnull(tc.cust_webNickName,''),
					@strReplyTo   = ISNULL(ts.sm_email,'')
			   FROM tbCustomer				tc  WITH (NOLOCK)
			   INNER JOIN tbSalesman		ts  WITH (NOLOCK)
					ON	ts.comp_id   = tc.comp_id AND
						ts.sm_id	 = tc.sm_id
			   WHERE	tc.comp_id   = @comp_id	AND
						tc.cust_id   = @cust_id



			--si el cliente no tiene vendedor asignado se recupera el email definido en el website sino
			--se recupara el email del vendedor asignado al cliente
			IF @lsm_id IS NULL
				BEGIN
					SET @strCopyRecipients = @strCopyRecipients + ';' + (SELECT twsn.ws_newCustomerEmailContactEMail
							   FROM tbWebSiteII_Names    twsn  WITH (NOLOCK)
							   WHERE twsn.comp_id = @comp_id
							   AND  twsn.ws_id  = @ws_id)
				END

			ELSE
				BEGIN
					SET @strCopyRecipients = @strCopyRecipients + ';' + (SELECT ts.sm_email
							   FROM tbSalesman     ts    WITH (NOLOCK)
							   WHERE ts.comp_id  = @comp_id
							   AND  ts.sm_id  = @lsm_id)
				END





			-- Si el Login es un email . . .
			IF  dbo.fnEmailCheck(@strWebLogin) = 'True'
				BEGIN
					SET @precipients = @precipients + ';' + @strWebLogin
				END

			DECLARE @ws_blockMail2Customer AS BIT = 'False'
			DECLARE @ws_MailReplyTo		   AS NVARCHAR(250)


			SELECT @strCopyRecipients		=		@strCopyRecipients  + ';' + IsNull(twsn.ws_newSaleOrderMailCollector,''),
				   @ws_blockMail2Customer	= 		ISNULL(twsn.ws_blockMail2Customer,'False'),
				   @ws_MailReplyTo			=       ISNULL(twsn.ws_MailReplyTO,'')
				FROM tbWebSiteII_Names    twsn  WITH (NOLOCK)
				WHERE twsn.comp_id = @comp_id	AND
					  twsn.ws_id   = @ws_id



			IF  dbo.fnEmailCheck(@ws_MailReplyTo) = 'True'
				BEGIN
					SET @strReplyTo = @ws_MailReplyTo
				END


			-- Bloquea Mails a Clientes
			IF @ws_blockMail2Customer = 'True'
				BEGIN
					SET @precipients  = ''
				END


			IF @precipients = '' AND @strCopyRecipients <> ''
				BEGIN
					SET @precipients		= @strCopyRecipients
					SET @strCopyRecipients	= ''
				END




			--recuperamos el subject cargado en tbWebSite_ParagraphComponentsControlsData
			SELECT @subject = NULL
			SELECT @subject    = IsNull(twsn.ws_saleOrder_Mail_Subject,'Confirmación de su Pedido desde Sitio Web')
				FROM tbWebSiteII_Names    twsn  WITH (NOLOCK)
				WHERE twsn.comp_id = @comp_id
				AND  twsn.ws_id  = @ws_id



			--recuperamos el Body Header
			SELECT @body2   = IsNull(twsn.ws_saleOrder_Mail_Body_Header,'')
				FROM tbWebSiteII_Names    twsn  WITH (NOLOCK)
				WHERE twsn.comp_id = @comp_id	AND
					  twsn.ws_id  = @ws_id



			--agregamos al mensaje que enviaremos al body del email las siguientes partes:
			--número de pedido
			--cliente
			--vendedor si hay un vendedor asignado al clientes
			SET @body2 = @body2 + CHAR(10) + CHAR(13) +

			  (SELECT tut.utexts_desc
			   FROM tbsysUniqueTexts tut
			   WHERE tut.lang_id = @lang_id AND tut.utexts_id = 102) + ' ' + CONVERT(VARCHAR,@return_value) + CHAR(10) + CHAR(13) +

			  (SELECT tswn.word_desc
					FROM tbSysWordsNew tswn   WITH (NOLOCK)
					WHERE tswn.lang_id = @lang_id AND tswn.wordsi_id = 297) + ' ' + convert(varchar,@cust_id) + ' - ' +
			  (SELECT tc.cust_name
					FROM tbCustomer  tc
					WHERE tc.comp_id = @comp_id AND tc.cust_id = @cust_id)

			IF NOT @lsm_id IS NULL	SET @body2 = @body2 + CHAR(10) + CHAR(13) +
			  (SELECT tswn.word_desc
					FROM tbSysWordsNew tswn		WITH (NOLOCK)
					WHERE tswn.lang_id = @lang_id AND tswn.wordsi_id = 1631) + ' ' + convert(varchar,@lsm_id) + ' - ' +
			  (SELECT ts.sm_name
					FROM tbSalesman  ts			WITH (NOLOCK)
					WHERE ts.comp_id = @comp_id AND ts.sm_id = @lsm_id)


			DECLARE @strSalesTermsWSText AS NVARCHAR(4000)
			SELECT @strSalesTermsWSText = ISNULL(tst.st_WSSaleOrderConfirmed,'')
				FROM tbSalesTerms tst  WITH (NOLOCK)
				WHERE	tst.comp_id = @comp_id AND
						tst.st_id	= @st_id
			SET @body2 = @body2 + CHAR(10) + CHAR(13) + @strSalesTermsWSText


			DECLARE
			@ItemsTable	NVARCHAR(MAX)
			SET @ItemsTable = ''
			EXEC spSaleOrderDetail_GetHTMLTableOfItems4Mail @comp_id, @lang_id, @bra_id, @return_value, @ItemsTable OUTPUT

			SET @ItemsTable = '<br>' + @ItemsTable

			SELECT @body2 = @body2 + @ItemsTable + '<br>' + '<br>'


			--recuperamos el Body Foter
			SELECT @body2   = @body2 + IsNull(twsn.ws_saleOrder_Mail_Body_Footer,'')
				FROM tbWebSiteII_Names    twsn  WITH (NOLOCK)
				WHERE	twsn.comp_id	= @comp_id  AND
						twsn.ws_id		= @ws_id



			--SELECT @comp_id,@precipients,@subject,@body2
			--se envía el correo si se recuperaron direcciones de emails
			IF NOT @precipients IS NULL
				BEGIN
					EXEC spSystem_sendEMail
						 @comp_id,
						 @precipients,
						 '',
						 @subject,
						 'HTML',
						 @body2,
						 NULL,
						 @strReplyTo,
						 @strCopyRecipients,
						 @user_id
				END
		END
	----------------------------------------------------------------------------------------------------------------
	----------------------------------------------------------------------------------------------------------------



	-- ----------------------------------------------
	-- Recalcula valores del pedido 08-2018 MOS
	-- ----------------------------------------------
	BEGIN TRY
		EXEC spSaleOrder_RecalculateTaxes
			@comp_id ,
			@bra_id,
			@return_value,
			@user_id ,
			2
	END TRY
	BEGIN CATCH
	END CATCH
	-- ----------------------------------------------

	---- ----------------------------------------------
	---- Si hay Cupones Usados sumo 1 a la cantidad usada     MOS 08-2020, se movió mas arriba x q aca ya no hay tbTempItemStock
	---- ----------------------------------------------
	--;WITH tmpCoupon AS
	--	(SELECT DISTINCT ttis.wscup_id
	--		FROM tbTempItemStock ttis		WITH (NOLOCK)
	--			WHERE	ttis.comp_id	= @comp_id AND
	--					ttis.tis_guid	= @guid)

	--UPDATE tbWebSiteII_DiscountCoupon		WITH (ROWLOCK)
	--	SET wscup_usedQTY	= ISNULL(wscup_usedQTY,0) + 1,
	--		wscup_disabled	= CASE
	--		              	      WHEN wscup_usedQTY = wscup_initQTY THEN	'True'
	--		              	      ELSE										wscup_disabled
	--		              	  END
	--	FROM tbWebSiteII_DiscountCoupon	dc
	--	INNER JOIN tmpCoupon ttis
	--		ON	ttis.wscup_id	= dc.wscup_id
	--	WHERE	dc.comp_id		= @comp_id


	---- ----------------------------------------------


	-- ------------------------------------------------------------------------------------------------
	-- MOS 07-2022: Verifica YA AHORA que el nuevo pedido no tenga publicaciones que actualizar.
	-- **wqlknfdlqwn098765gtfc
	-- ------------------------------------------------------------------------------------------------
	BEGIN TRY
		IF EXISTS(
					SELECT TOP 1 1
						FROM tbMercadoLibre_Stores AS tmls	WITH (NOLOCK)
						WHERE	tmls.mls_disabled = 'False' AND
								ABS(DATEDIFF(day, tmls.mls_accessTokenValidUp2Date,GETDATE())) < 2
				)
			BEGIN
				UPDATE tbSaleOrderDetail
					SET	sod_MercadoLibre_MustUpdateStock = 'True'
					FROM tbSaleOrderDetail sod							WITH (NOLOCK)
					INNER JOIN tbMercadoLibre_ItemsPublicados AS tmlip	WITH (NOLOCK)
						ON	tmlip.comp_id	= sod.comp_id AND
							tmlip.item_id	= sod.item_id
					INNER JOIN tbMercadoLibre_Stores		  AS tmls	WITH (NOLOCK)
						ON	tmls.comp_id	= tmlip.comp_id AND
							tmls.mls_id		= tmlip.mls_id
					WHERE
							SOD.comp_id			= @comp_id			AND
							SOD.bra_id			= @bra_id			AND
							SOD.soh_id			= @return_value		AND
							tmls.mls_disabled	 = 'False'		AND
							ABS(DATEDIFF(day, tmls.mls_accessTokenValidUp2Date,GETDATE())) < 2	AND
							tmlip.mlp_Active	= 'True'


				EXEC spSaleOrder_MercadoLibre_VerificarItemsSinStockDisponible @comp_id,@bra_id,@return_value,@guid
				EXEC spSystem_MercadoLibreProcessQueue_4GUID @guid
			END
	END TRY
	BEGIN CATCH
	END CATCH
	-- ------------------------------------------------------------------------------------------------





	RETURN @return_value
	--SELECT @return_value, @errormessage


END
GO







CREATE PROCEDURE [dbo].[spWebSiteII_Cart_TaxCalculate]
(
	@comp_id					INT,
	@tis_guid					UNIQUEIDENTIFIER,
	@ws_id						UNIQUEIDENTIFIER,
	@cust_id					INT,
	@st_id						INT,
	@dl_id						INT,
	@ccp_id						INT,
	@disc_id					INT
)
AS

BEGIN


-- -----------------------------------------------------------------------------
-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
-- -----------------------------------------------------------------------------
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET LOCK_TIMEOUT 300
SET DEADLOCK_PRIORITY NORMAL
-- -----------------------------------------------------------------------------



	SET NOCOUNT ON


	DECLARE	@bra_id				INT,
			@curr_id			INT,
			--@disc_id			INT,
			@country_id			INT,
			@state_id			INT,
			@cust_curr_id		INT,
			@exchange			DECIMAL(29,10),
			@df_id				INT = null,
			@prof_id			INT,
			@sd_id				INT



	-- recuperar datos de website
	SELECT	@bra_id			= twsn.bra_id,
			@curr_id		=	CASE
									WHEN twsn.curr_id4ForceTotal IS NULL THEN	tb.curr_id
									ELSE										twsn.curr_id4ForceTotal
								END,	-- 03-2017 MOS
			@country_id		= tb.country_id,
			@state_id		= tb.state_id,
			@prof_id		= twsn.prof_id,
			@sd_id			= twsn.sd_id

		FROM	tbWebSiteII_Names				twsn	WITH (NOLOCK)
		INNER JOIN tbBranch						tb		WITH (NOLOCK)
			ON	tb.comp_id	= twsn.comp_id
			AND tb.bra_id	= twsn.bra_id
		WHERE	twsn.comp_id	= @comp_id
		AND		twsn.ws_id		= @ws_id



	IF @prof_id > 0		-- **wefklnw9874lknlknl  MOS 10-2021 x USA
		BEGIN

			SELECT TOP 1 @df_id = tdf.df_id
				FROM tbDocumentsFileAdditionalByFiscalClass AS dfc	WITH (NOLOCK)
				INNER JOIN tbCustomer						AS tc	WITH (NOLOCK)
					ON	tc.comp_id		= @comp_id		AND
						tc.cust_id		= @cust_id
				INNER JOIN tbDocumentsFile					AS tdf	WITH (NOLOCK)
					ON	tdf.comp_id		= dfc.comp_id	AND
						tdf.df_id		= dfc.df_id
				WHERE	dfc.comp_id		= @comp_id		AND
						dfc.fc_id		= tc.fc_id		AND
						dfc.bra_id		= @bra_id		AND
						dfc.prof_id		= @prof_id		AND
						tdf.sd_id		= @sd_id
				ORDER BY
						CASE
							WHEN tdf.df_favorite4WebSite = 1 THEN 0
							ELSE								  1
						END,
						df_order

		END



	--obtenemos el df_id para generar el pedido
	IF @df_id IS NULL
		BEGIN
			SELECT	TOP 1 @df_id	= df_id
				FROM 	dbo.fnDocumentsFile_GetDocumentsForCustomers(@comp_id, @bra_id, @cust_id)
				WHERE	sd_id		= @sd_id
				ORDER BY	CASE
								WHEN  is4WS = 1 THEN 0
								ELSE				1
							END,
							df_order
		END

	--SELECT @sd_id, @df_id


	-- recuperar datos del cliente
	SELECT	@disc_id		=	CASE
									WHEN @disc_id = -1	THEN	tc.disc_id
									ELSE						@disc_id
								END,
			@cust_curr_id	= tc.curr_id
		FROM	tbCustomer					tc		WITH (NOLOCK)

		WHERE	tc.comp_id		= @comp_id
		AND		tc.cust_id		= @cust_id



	-- recuperar el tipo de cambio entre la moneda de la sucursal y la moneda del cliente
	SELECT @exchange = dbo.fnGetExchange(@comp_id, 1, @curr_id, @cust_curr_id, 0, 0, 'false')


	-- ---------------------------------
	-- Incremento por Condicion de venta
	-- ---------------------------------
	DECLARE @intCurr_id_4Increment	INT
	DECLARE @decCurrId_Increment	DECIMAL(19,4)

	SELECT	@intCurr_id_4Increment	= tst.curr_id_4Increment,
			@decCurrId_Increment	= tst.currId_Increment
		FROM tbSalesTerms tst WITH (NOLOCK)
		WHERE	tst.comp_id = @comp_id AND
				tst.st_id	= @st_id

	IF	@intCurr_id_4Increment IS NOT NULL AND
		@curr_id <> @intCurr_id_4Increment AND
		@decCurrId_Increment IS NOT NULL
		BEGIN
			SET	   @cust_curr_id	= @intCurr_id_4Increment
			SELECT @exchange		= dbo.fnGetExchange(@comp_id, 1, @cust_curr_id ,@curr_id, 0, 0, 'false') + ISNULL(@decCurrId_Increment,0)
			SET	   @exchange        = 1 / dbo.fnNoZDiv(@exchange)
		END
	-- ---------------------------------




	-- recuperar los totales generales
	EXEC	sptmpTax_calculate
			@comp_id,
			@bra_id,
			@cust_id,
			@tis_guid,
			@curr_id,
			@disc_id,
			@country_id,
			@state_id,
			@st_id,
			@curr_id,
			@cust_curr_id,
			@exchange,
			'false',
			@df_id,
			'true',
			@dl_id,
			0,
			'false',
			'false',
			-1,
			@ccp_id

END
GO



--// -----------------------------------------------------------------------------------------------------
--// CARRITO: Suma o Resta qty a un tis_id
--//    ''' intAction = 0: Actualiza la QTY con la indicada en decQTY
--//    '''           = 1: Suma algebraicamente la cantidad indicada en decQTY
--//    ''' Si la cantidad da 0 borra el tis_id indicado.
--// -----------------------------------------------------------------------------------------------------



CREATE PROCEDURE [dbo].[spWebSiteII_Cart_Update]
(
	@comp_id					INT,
	@ws_id						UNIQUEIDENTIFIER,
	@tis_id						INT,
	@action						INT,		--0: Reemplaza   1: Suma Algrebraicamente
	@decQTY						INT
)
AS

BEGIN

	SET NOCOUNT ON



	-- Se fija si es un Combo
	DECLARE @tis_id_origin AS INT
	SELECT	@tis_id_origin	= tis_id_origin
		FROM tbTempItemStock			WITH (NOLOCK)
		WHERE	tis_id		= @tis_id	AND
				tis_id_origin IS NOT NULL





	-- --------------------------------------------------------------------------------
	-- En Pedidos desde Sitio WEB controla si hay disponible para el pedido actual.
	-- --------------------------------------------------------------------------------
	DECLARE @stor_id		AS INT
	DECLARE @item_id		AS INT
	DECLARE @decActualQTY	AS DECIMAL(29,4)
	SELECT	@stor_id		= ttis.stor_id,
			@item_id		= ttis.item_id,
			@decActualQTY	= ttis.tis_qty
		FROM tbTempItemStock ttis	WITH (NOLOCK)
		WHERE	ttis.comp_id	= @comp_id AND
				ttis.tis_id		= @tis_id



	-- --------------------------------------------------------------------------------
	-- Si llega un pedido de Stock con Decimales y el artículo NO los admite, pide la cantidad inmediata superior.
	-- --------------------------------------------------------------------------------
	IF @decQTY <> CONVERT(INT,@decQTY)
		BEGIN
			IF EXISTS(	SELECT TOP 1  1
	          				FROM tbItem ti	WITH (NOLOCK)
	          				WHERE	ti.comp_id			= @comp_id AND
	          						ti.item_id			= @item_id AND
	          						ti.item_withDecimal = 1
					)
				BEGIN
					SET @decQTY = ROUND(@decQTY,0)
				END
		END
	-- --------------------------------------------------------------------------------






	DECLARE @stor_id4AvailableStock AS INT = -1
	DECLARE @ws_saleOrderBlockUp2AvailableStorage	AS BIT
	DECLARE @ws_saleOrderBlockIfNOTAvailable		AS BIT
	SET     @ws_saleOrderBlockUp2AvailableStorage	= 'False'
	SET     @ws_saleOrderBlockIfNOTAvailable		= 'False'

	SELECT
		@stor_id4AvailableStock					= ISNULL(twsin.stor_id4AvailableStock,@stor_id),
		@ws_saleOrderBlockUp2AvailableStorage	= twsin.ws_saleOrderBlockUp2AvailableStorage,
		@ws_saleOrderBlockIfNOTAvailable		= twsin.ws_saleOrderBlockIfNOTAvailable
		FROM tbWebSiteII_Names twsin		WITH (NOLOCK)
		WHERE	twsin.comp_id	= @comp_id AND
				twsin.ws_id		= @ws_id


	IF	@ws_saleOrderBlockIfNOTAvailable		= 'True' OR
		@ws_saleOrderBlockUp2AvailableStorage	= 'True'

		BEGIN

			DECLARE @decAvailableQTY AS DECIMAL(29,4)
			SET		@decAvailableQTY	= dbo.fnGetAStock4MaxAssociation(@comp_id,@stor_id4AvailableStock/*@stor_id*/,@item_id,899999999)
			DECLARE @decDifferenceQTY AS DECIMAL(29,4)
			SET		@decDifferenceQTY		= @decQTY - @decActualQTY  -- Positivo si pide de MAS y @action es 0


			IF @decAvailableQTY < 0 SET @decAvailableQTY = 0

			-- Sobre Escribe la cantidad y es Mayor a la actual
			IF  @action = 0 AND @decDifferenceQTY > 0
				BEGIN

					IF @decDifferenceQTY > @decAvailableQTY AND @ws_saleOrderBlockIfNOTAvailable		= 'True'
						BEGIN
							SELECT -1
							RETURN
						END

					IF @decDifferenceQTY > @decAvailableQTY AND @ws_saleOrderBlockUp2AvailableStorage	= 'True'
						BEGIN
							SET @decQTY = @decAvailableQTY + @decActualQTY
						END

				END

			-- Si Incrementa y quiere SUMAR
			IF @action = 1 AND @decQTY > 0 -- Suma Algebraicamente
				BEGIN
					IF @decQTY > @decAvailableQTY AND @ws_saleOrderBlockIfNOTAvailable		= 'True'
						BEGIN
							SELECT -2
							RETURN
						END

					IF @decQTY > @decAvailableQTY AND @ws_saleOrderBlockUp2AvailableStorage	= 'True'
						BEGIN
							SET @decQTY = @decAvailableQTY
						END
				END
		END
	-- --------------------------------------------------------------------------------



	UPDATE tbTempItemStock		WITH (ROWLOCK)
		SET
			tis_qty =	CASE
							WHEN @action = 0 THEN @decQTY
							WHEN @action = 1 THEN (tis.tis_qty + @decQTY)
							ELSE tis.tis_qty
			         	END
		FROM tbTempItemStock tis
		where tis.comp_id = @comp_id AND
			  tis.tis_id  = @tis_id

	DECLARE @intRowCount AS INT


	IF @@ROWCOUNT > 0
		BEGIN
			SET @intRowCount = 1
		END
	ELSE
		BEGIN
			SET @intRowCount = -3
		END


	-- Si borro un Combo borra todos los componentes asociados !
	IF @action = 0 AND @decQTY = 0 AND @tis_id_origin IS NOT NULL
		BEGIN
			DELETE
				FROM	tbTempItemStock	WITH (ROWLOCK)
				WHERE 	tis_id_origin = @tis_id_origin
			SELECT @intRowCount = 2		-- Borro un COMBO Completo
		END


	-- Si luego de actualizar la cantidad quedo en CERO borra ese TIS_ID
	DELETE FROM tbTempItemStock		WITH (ROWLOCK)
		WHERE	comp_id = @comp_id	AND
				tis_id	= @tis_id	AND
				tis_qty <= 0


	-- Retorna la Cantidad en que quedó finalmente
	DECLARE @intUpdatedQTY AS DECIMAL(30,2) = 0
	SELECT  @intUpdatedQTY = ttis.tis_qty
		FROM tbTempItemStock AS ttis		WITH (NOLOCK)
		WHERE	comp_id = @comp_id	AND
				tis_id	= @tis_id

	SELECT @intRowCount,@intUpdatedQTY

	RETURN

END
GO



-- Lo usa EnvioPack para poner los Costos y Precios de Venta

CREATE PROCEDURE [dbo].[spWebSiteII_Cart_updatePriceAndCost]
(
	@tis_guid			UNIQUEIDENTIFIER,
	@item_id			INT,
	@decPrice			DECIMAL(26,4),
	@decCost			DECIMAL(26,4),
	@comp_id			INT,
	@curr_id			INT
)
AS

BEGIN

	SET NOCOUNT ON


	DECLARE @intTaxID AS INT = NULL

	SELECT TOP 1 @intTaxID   = ttn.tax_id
	FROM tbItemTaxes		tit		WITH (NOLOCK)
	INNER JOIN tbTaxName	ttn		WITH (NOLOCK)
		ON	ttn.comp_id					= tit.comp_id AND
			ttn.tax_id					= tit.tax_id
		WHERE	tit.comp_id				= @comp_id AND
				tit.item_id				= @item_id AND
				tit.tax_itemComposed	= 'False'
				AND ttn.tax_class		= 1



	UPDATE tbTempItemStock		WITH (ROWLOCK)
		SET tis_cost		= @decCost,
			tis_costTax		= @intTaxID,
			tax_id			= @intTaxID,
			tis_price		= @decPrice,
			curr_id			=	CASE
									WHEN @curr_id > 0 THEN @curr_id
									ELSE				   curr_id
								END
			--tis_DeliveryCharge = 'True'   vER SI HAY Q BORRARLAS DE HACERLO X FUERA PONIENDO ALGUN VALOR EN ESTE CAMPO, SINO VA A INTERFERIR CON dELIVERYcHARGES noRMAL.
		WHERE	tis_guid	= @tis_guid AND
				item_id		= @item_id

END
GO






-- Pone los precios al valor de lista. Se usa para los micrositios.
CREATE PROCEDURE [dbo].[spWebSiteII_Cart_UpdatePrices2List]
(
	@comp_id					INT,
	@tis_guid					UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON


	UPDATE tbTempItemStock	WITH (ROWLOCK	)
		SET tis_price	= tpli.prli_price ,
			curr_id		= tpli.curr_id
		FROM tbTempItemStock tis
		INNER JOIN tbPriceListItems tpli
			ON	tpli.comp_id = tis.comp_id AND
				tpli.prli_id = tis.prli_id AND
				tpli.item_id = tis.item_id
			WHERE tis_guid = @tis_guid

	SELECT 1
	RETURN

END
GO





CREATE PROCEDURE [dbo].[spWebSiteII_Compare_AddItem]
(
	@tis_guid			UNIQUEIDENTIFIER,
	@item_id			INT
)
AS

BEGIN

	SET NOCOUNT ON


	IF	(
			SELECT COUNT(*)
	  			FROM tbWebSiteII_TMPItem4Compare twsitc
				WHERE twsitc.ws_guid = @tis_guid
	) >= 5
	BEGIN
		DELETE TOP(1)
			tbWebSiteII_TMPItem4Compare
			FROM tbWebSiteII_TMPItem4Compare tmp
			WHERE tmp.ws_guid = @tis_guid
	END



	INSERT INTO tbWebSiteII_TMPItem4Compare ( ws_guid, item_id, ws_cd )
		VALUES(@tis_guid,@item_id,GETDATE())




END
GO





