-- No se graba ws_id ya que la tabla se pone con ese valor en el sitio V2
CREATE PROCEDURE [dbo].[spWebSiteII_Contacts_insertData]
(
	@comp_id				INT,
	@wsc_name				NVARCHAR (4000),
	@wsc_address			NVARCHAR (4000),
	@wsc_city				NVARCHAR (4000),
	@wsc_state				NVARCHAR (4000),
	@wsc_country			NVARCHAR (4000),
	@wsc_zip				NVARCHAR (20),
	@wsc_phone				NVARCHAR (4000),
	@wsc_email				NVARCHAR (4000),
	@wsc_business			NVARCHAR (4000),
	@wsc_message			NVARCHAR (4000),
	@ws_id					UNIQUEIDENTIFIER,
	@requestIP				VARCHAR(50),
	@return_value			INT OUTPUT
)
AS


BEGIN

	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------
	-- Parametros de Prueba
	-- -------------------------------------------------------------------------------
	/*

	DECLARE		@comp_id				INT,
				@wsc_name				NVARCHAR (4000),
				@wsc_address			NVARCHAR (4000),
				@wsc_city				NVARCHAR (4000),
				@wsc_state				NVARCHAR (4000),
				@wsc_country			NVARCHAR (4000),
				@wsc_zip				NVARCHAR (20),
				@wsc_phone				NVARCHAR (4000),
				@wsc_email				NVARCHAR (4000),
				@wsc_business			NVARCHAR (4000),
				@wsc_message			NVARCHAR (4000),
				@ws_id					INT

	SELECT		@comp_id				=1,
				@wsc_name				='',
				@wsc_address			='',
				@wsc_city				='',
				@wsc_state				='',
				@wsc_country			='',
				@wsc_zip				='',
				@wsc_phone				='',
				@wsc_email				='',
				@wsc_business			='',
				@wsc_message			='',
				@ws_id					2

	*/
	-- -------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------
	if	(@comp_id	= -1)	set	@comp_id = NULL
	-- ----------------------------------------------------------------------


	DECLARE @conclass_id INT
	SET		@conclass_id = NULL
	SELECT TOP 1 @conclass_id = tcc.conclass_id
		FROM	tbContactClass tcc			WITH (NOLOCK)
		WHERE	tcc.comp_id = @comp_id
		ORDER BY	CASE
						WHEN tcc.conclass_web = 1 THEN	1
						ELSE							2
					END	  ,
					tcc.conclass_desc



	INSERT INTO tbWebSite_Contacts
	(
		comp_id,
		wsc_name,
		wsc_address,
		wsc_city,
		wsc_state,
		wsc_country,
		wsc_zip,
		wsc_phone,
		wsc_email,
		wsc_business,
		wsc_message,
		wsc_cd,
		ws_id,
		conclass_id,
		wsc_requestIP
	)
	VALUES
	(
		@comp_id,
		@wsc_name,
		@wsc_address,
		@wsc_city,
		@wsc_state,
		@wsc_country,
		@wsc_zip,
		@wsc_phone,
		@wsc_email,
		@wsc_business,
		@wsc_message,
		GETDATE(),
		@ws_id,
		@conclass_id,
		@requestIP
	)

	set	@return_value = @@identity


END
GO



