Create PROCEDURE [dbo].[spWebSiteII_CustomerGroup_AddRelations]
(
	@comp_id			INT,
	@custg_id			INT,
	@cust_id			INT
)
AS

BEGIN

	SET NOCOUNT ON


	IF NOT EXISTS(
					SELECT 1
						FROM tbCustomerGroupDetail tcgd
						WHERE	tcgd.comp_id	= @comp_id	AND
								tcgd.custg_id	= @custg_id AND
								tcgd.cust_id	= @cust_id
				)

	BEGIN

		INSERT INTO tbCustomerGroupDetail
		(
			comp_id,
			custg_id,
			cust_id
		)
		VALUES
		(
			@comp_id,
			@custg_id,
			@cust_id
		)


	END


END
GO






create PROCEDURE [dbo].[spWebSiteII_defaultSessionVariableNames_getDataByWebSite]
(
	@comp_id			INT,
	@ws_id				UNIQUEIDENTIFIER

)
AS



BEGIN


	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	SELECT
		isnull(twsidsvn.wsp_variableName,'')		[wsp_variableName],
		isnull(twsidsvn.wsp_variableContent,'')		[wsp_variableContent],
		twsidsvn.wsp_id								[ID]

		FROM tbWebSiteII_defaultSessionVariableNames twsidsvn	WITH (NOLOCK)

		WHERE	twsidsvn.comp_id	= @comp_id			AND
				twsidsvn.ws_id		= @ws_id




END
GO

-- =============================================
-- Author:		MOS
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[spWebSiteII_DiscountCoupon_DiscountCalculate]
	@comp_id		AS INT,
	@ws_id			AS UNIQUEIDENTIFIER,
	@strCode		AS NVARCHAR(50),
	@tis_guid		AS UNIQUEIDENTIFIER,
	@st_id			AS INT,
	@disc_id		AS INT,
	@cc_id			AS INT,
	@ccp_id			AS INT,
	@prli_id		AS INT

AS





BEGIN




	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*
	DECLARE
		@comp_id		AS INT = 1,
		@ws_id			AS UNIQUEIDENTIFIER = '1C807F41-D6FA-48F8-B256-EDD2D7B02919',
		@strCode		AS NVARCHAR(50) = 'netone',
		@tis_guid		AS UNIQUEIDENTIFIER	 = '3C4E91B6-664E-40A7-BF22-4D3B0329E7C6',
		@st_id			AS INT = 1,
		@disc_id		AS INT = 1,
		@cc_id			AS INT = 1,
		@ccp_id			AS INT = 1,
		@prli_id		AS INT = 1
	*/
	-- ----------------------------------------------------------







	SET NOCOUNT ON;



	-- Borro descuentos calculados anteriormente
	UPDATE tbTempItemStock	WITH (ROWLOCK)
		SET tis_itemDiscount	= 0,
			wscup_id			= NULL
		WHERE	comp_id			= @comp_id	AND
				tis_guid		= @tis_guid	AND
				wscup_id IS NOT NULL






	DECLARE curTis CURSOR LOCAL  FAST_FORWARD FOR
		SELECT	ttis.tis_id,
				ttis.item_id
			FROM tbTempItemStock ttis	WITH (NOLOCK)
			WHERE	ttis.comp_id	= @comp_id AND
					ttis.tis_guid	= @tis_guid

	DECLARE @curtis_id		AS INT
	DECLARE @curitem_id		AS INT
	DECLARE @decDiscount	AS DECIMAL(19,4) = 0
	DECLARE @cat_id			AS INT
	DECLARE @subcat_id		AS INT
	DECLARE @brand_id		AS INT
	DECLARE @item_id		AS INT
	DECLARE @wscup_id		AS INT
	DECLARE @wscup_upToPrice	AS DECIMAL(15,2)
	DECLARE @tis_price			AS DECIMAL(19,2)
	DECLARE @tis_priceDiscount	AS DECIMAL(19,2)
	DECLARE @tis_qty			AS DECIMAL(19,2)

	OPEN		curTIS
	FETCH NEXT FROM curTis INTO @curtis_id,@curitem_id
	WHILE @@FETCH_STATUS = 0
		BEGIN

			SELECT	@brand_id = ti.brand_id,
					@cat_id   = ti.cat_id,
					@subcat_id= ti.subcat_id,
					@item_id  = ti.item_id		-- al pedo
				FROM tbItem		ti	WITH (NOLOCK)
				WHERE	ti.comp_id = @comp_id AND
						ti.item_id = @curitem_id

			SET			 @decDiscount			= 0
			SET			 @wscup_id				= NULL



			SELECT TOP 1 @decDiscount			= twsidc.wscup_discountPercentage,
						 @wscup_id				= twsidc.wscup_id,
						 @wscup_upToPrice		= twsidc.wscup_upToPrice
				FROM	tbWebSiteII_DiscountCoupon twsidc	WITH (NOLOCK)
				WHERE	twsidc.comp_id			= @comp_id				AND
						twsidc.ws_id			= @ws_id				AND
						twsidc.wscup_CODE		= @strCode				AND
						twsidc.wscup_disabled	= 'False'				AND
						GETDATE() BETWEEN twsidc.wscup_fromDate AND twsidc.wscup_toDate	AND
						(twsidc.st_id IS NULL	OR twsidc.st_id		= @st_id)			AND
						(twsidc.prli_id IS NULL	OR twsidc.prli_id	= @prli_id)			AND
						(twsidc.disc_id IS NULL OR twsidc.disc_id	= @disc_id)			AND
						(twsidc.cc_id IS NULL	OR twsidc.cc_id		= @cc_id)			AND
						(twsidc.ccp_id IS NULL	OR twsidc.ccp_id	= @ccp_id)			AND
						twsidc.wscup_usedQTY	< twsidc.wscup_initQTY					AND
						(twsidc.cat_id		IS NULL OR twsidc.cat_id	= @cat_id)		AND
						(twsidc.subcat_id	IS NULL OR twsidc.subcat_id = @subcat_id)	AND
						(twsidc.brand_id	IS NULL OR twsidc.brand_id  = @brand_id)	AND
						(twsidc.item_id		IS NULL OR twsidc.item_id	= @item_id)		AND
						CASE

							WHEN 	twsidc.item_id_related1 IS  NULL AND
									twsidc.item_id_related2 IS  NULL AND
									twsidc.item_id_related3 IS  NULL AND
									twsidc.item_id_related4 IS  NULL AND
									twsidc.item_id_related5 IS  NULL		THEN 1


							-- Los 5 relacionados
							WHEN
									twsidc.item_id IS NOT NULL AND
									twsidc.item_id_related1 IS NOT NULL AND
									twsidc.item_id_related2 IS NOT NULL AND
									twsidc.item_id_related3 IS NOT NULL AND
									twsidc.item_id_related4 IS NOT NULL AND
									twsidc.item_id_related5 IS NOT NULL	AND
									EXISTS(	SELECT TOP 1 1
												FROM tbTempItemStock ttis		WITH (NOLOCK)
									       		WHERE	ttis.comp_id				= @comp_id	AND
									       				ttis.tis_guid				= @tis_guid AND
									       				(
									       					(ttis.item_id				= twsidc.item_id_related1 AND
									       					 twsidc.item_id_related1QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related2 AND
									       					 twsidc.item_id_related2QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related3 AND
									       					 twsidc.item_id_related3QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related4 AND
									       					 twsidc.item_id_related4QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related5 AND
									       					 twsidc.item_id_related5QTY <= ttis.tis_qty)
									       				)										AND
														ttis.tis_id				   <> @curtis_id)
																				THEN 1

							-- Los 4 relacionados
							WHEN	twsidc.item_id IS NOT NULL AND
									twsidc.item_id_related1 IS NOT NULL AND
									twsidc.item_id_related2 IS NOT NULL AND
									twsidc.item_id_related3 IS NOT NULL AND
									twsidc.item_id_related4 IS NOT NULL AND
									EXISTS(	SELECT TOP 1 1
												FROM tbTempItemStock ttis		WITH (NOLOCK)
									       		WHERE	ttis.comp_id				= @comp_id	AND
									       				ttis.tis_guid				= @tis_guid AND
									       				(
									       					(ttis.item_id				= twsidc.item_id_related1 AND
									       					 twsidc.item_id_related1QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related2 AND
									       					 twsidc.item_id_related2QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related3 AND
									       					 twsidc.item_id_related3QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related4 AND
									       					 twsidc.item_id_related4QTY <= ttis.tis_qty)
									       				)										AND
														ttis.tis_id				   <> @curtis_id)
																				THEN 1

							-- Los 3 relacionados
							WHEN	twsidc.item_id IS NOT NULL AND
									twsidc.item_id_related1 IS NOT NULL AND
									twsidc.item_id_related2 IS NOT NULL AND
									twsidc.item_id_related3 IS NOT NULL AND
									EXISTS(	SELECT TOP 1 1
												FROM tbTempItemStock ttis		WITH (NOLOCK)
									       		WHERE	ttis.comp_id				= @comp_id	AND
									       				ttis.tis_guid				= @tis_guid AND
									       				(
									       					(ttis.item_id				= twsidc.item_id_related1 AND
									       					 twsidc.item_id_related1QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related2 AND
									       					 twsidc.item_id_related2QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related3 AND
									       					 twsidc.item_id_related3QTY <= ttis.tis_qty)
									       				)										AND
														ttis.tis_id				   <> @curtis_id)
																				THEN 1

							-- Los 2 relacionados
							WHEN	twsidc.item_id IS NOT NULL AND
									twsidc.item_id_related1 IS NOT NULL AND
									twsidc.item_id_related2 IS NOT NULL AND
									EXISTS(	SELECT TOP 1 1
												FROM tbTempItemStock ttis		WITH (NOLOCK)
									       		WHERE	ttis.comp_id				= @comp_id	AND
									       				ttis.tis_guid				= @tis_guid AND
									       				(
									       					(ttis.item_id				= twsidc.item_id_related1 AND
									       					 twsidc.item_id_related1QTY <= ttis.tis_qty)
									       						OR
									       					(ttis.item_id				= twsidc.item_id_related2 AND
       														 twsidc.item_id_related5QTY <= ttis.tis_qty)
									       				)										AND
														ttis.tis_id				   <> @curtis_id)
																				THEN 1


							-- Los 1 relacionados
							WHEN	twsidc.item_id IS NOT NULL AND
									twsidc.item_id_related1 IS NOT NULL AND
									EXISTS(	SELECT TOP 1 1
												FROM tbTempItemStock ttis		WITH (NOLOCK)
									       		WHERE	ttis.comp_id				= @comp_id	AND
									       				ttis.tis_guid				= @tis_guid AND
									       				(
									       					(ttis.item_id				= twsidc.item_id_related1 AND
									       					 twsidc.item_id_related1QTY <= ttis.tis_qty)
									       				)										AND
														ttis.tis_id				   <> @curtis_id)
																				THEN 1






						END = 1
			ORDER BY
						CASE	-- Con que tenga 1 articulo q deba controlar q este relacionado con el principal, gana
							WHEN	twsidc.item_id_related1 IS NOT NULL AND
									twsidc.item_id			IS NOT NULL			THEN	0
							ELSE														1
						END,
						ISNULL(twsidc.cat_id,99999999),
						ISNULL(twsidc.subcat_id,99999999),
						ISNULL(twsidc.item_id,99999999),
						ISNULL(twsidc.brand_id,99999999)



			-- -----------------------------------------------------------------------------------------------------
			-- Si se usa un TOPE MAXIMO de descuento en pesos por cupon, recalcula el % de descuento segun ese tope
			-- -----------------------------------------------------------------------------------------------------
			IF @wscup_upToPrice <> 0
				BEGIN

					SELECT	@tis_price	= ttis.tis_price * ttis.tis_qty,						-- Importe del Renglon * QTY
							@tis_qty	= ttis.tis_qty
						FROM tbTempItemStock AS ttis
						WHERE	ttis.comp_id	= @comp_id		AND
								ttis.tis_id		= @curtis_id

					SELECT @tis_price = @tis_price + tt.tm_amount								-- Impuestos del Renglon * QTY
						FROM tbtmpTax			AS tt		WITH (NOLOCK)
						INNER JOIN tbTaxName	AS ttn		WITH (NOLOCK)
							ON	ttn.comp_id = tt.comp_id	AND
								ttn.tax_id	= tt.tax_id
						WHERE	tt.tis_id	= @curtis_id	AND
								ttn.tax_class = 1

					SET @tis_price			= @tis_price / dbo.fnNoZDiv(@tis_qty)	-- Precio UNITARIO
					SET @tis_priceDiscount	= @tis_price * @decDiscount / 100


					IF @tis_priceDiscount > @wscup_upToPrice
						BEGIN

							-- MOS 09-2022
							SET @decDiscount = @decDiscount * @wscup_upToPrice / dbo.fnNoZDiv(@tis_priceDiscount)

							--SET @decDiscount = (
							--						((@tis_price / dbo.fnNoZDiv(@tis_price - @wscup_upToPrice)) - 1) * 100
							--				   )
						END

				END
			-- -----------------------------------------------------------------------------------------------------



--SELECT @@ROWCOUNT, @decDiscount

			UPDATE tbTempItemStock	WITH (ROWLOCK)
				SET tis_itemDiscount = @decDiscount,
					wscup_id		 = @wscup_id
				WHERE	comp_id				= @comp_id	AND
						tis_id				= @curtis_id


			FETCH NEXT FROM curTis INTO @curtis_id,@curitem_id
		END

	CLOSE		curTIS
	DEALLOCATE	curTIS


END
GO

