CREATE PROCEDURE spWebSiteII_DiscountCoupon_isValidCoupon
	@comp_id		AS INT,
	@ws_id			AS UNIQUEIDENTIFIER,
	@strCode		AS NVARCHAR(50)


AS
BEGIN

	SET NOCOUNT ON;

	IF EXISTS(
				SELECT TOP 1 1
					FROM tbWebSiteII_DiscountCoupon twsidc	WITH (NOLOCK)
					WHERE	twsidc.comp_id			= @comp_id	AND
							twsidc.ws_id			= @ws_id	AND
							twsidc.wscup_CODE		= @strCode	AND
							twsidc.wscup_disabled	= 'False' AND
							twsidc.wscup_usedQTY	< twsidc.wscup_initQTY
			)
		BEGIN
			SELECT 1
			RETURN
		END

   SELECT 0
   RETURN



END
GO



-- Ejecuta un Código SQL de hasta 8K que recibe como parámetro en @strParamOUT al JSon recibido en la variable @JSonParameters

CREATE PROCEDURE [dbo].[spWebSiteII_ExecScripts]
(
	@ws_id				UNIQUEIDENTIFIER,
	@ScriptLabel		VARCHAR(100),
	@JSonParameters		NVARCHAR(MAX),
	@bitIsDevelopment	BIT	,
	@intCustIdLogged	INT,
	@intUserIdLogged	INT,
	@strRequestIP		NVARCHAR(50)
)
AS


BEGIN

	-- ----------------------------------------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------------------------------------
	/*
	DECLARE 	@page_id			UNIQUEIDENTIFIER
	SELECT 		@page_id			= '0352be36-5ca2-4b30-be44-8a2020c78c14'

	*/
	-- ----------------------------------------------------------------------------------------------

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	-- MOS 08-2023: Por seguridad NO se permiten ejecutar SQLScripts con usuario sa
	IF SUSER_NAME() = 'sa' OR SUSER_NAME() = 'SA' OR SUSER_NAME() = 'Sa' OR SUSER_NAME() = 'sA'
		BEGIN
			SELECT 'WARNING: sa user NOT Allowed to execute GlobalBluePoint Scripts.'
			RETURN
		END





	BEGIN TRY


		IF @JSonParameters LIKE '%sp_executesql%'
			BEGIN
				SELECT -5
				RETURN
			END

		-- MOS 02-2022 ( x las dudas que pasen cosas raras en lugar de label.. igual, NO deberia molestar ya que está en un where ...
		SET @ScriptLabel = REPLACE(@ScriptLabel,' ','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'(','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,')','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'"','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'''','')



		SET @strRequestIP			= dbo.fnIPCheck(@strRequestIP)
		DECLARE @bitHasScript		AS BIT = 'False'
		DECLARE @strScript4Execute  AS NVARCHAR(MAX)
		SELECT	@strScript4Execute	= twsis.wssql_scriptSQL ,
				@bitHasScript		= 'True'
			FROM tbWebSiteII_SQLScripts twsis		WITH (NOLOCK)
			WHERE twsis.wssql_label = @ScriptLabel


		-- MOS 12-2022
		IF @strScript4Execute LIKE '%sp_executesql%'
			BEGIN
				SELECT -6
				RETURN
			END

		-- MOS 12-2022
		IF @strScript4Execute LIKE '%sys.databases%'
			BEGIN
				SELECT -16
				RETURN
			END

		-- MOS 12-2022
		IF @strScript4Execute LIKE '%sys.master_files%'
			BEGIN
				SELECT -26
				RETURN
			END


		-- MOS 12-2022
		IF  @strScript4Execute LIKE '%drop da%'		OR
			@strScript4Execute LIKE '%drop  da%'	OR
			@strScript4Execute LIKE '%drop   da%'	OR
			@strScript4Execute LIKE '%drop    da%'	OR
			@strScript4Execute LIKE '%drop	da%'
			BEGIN
				SELECT -36
				RETURN
			END




		IF @bitHasScript = 'True'
			BEGIN

				DECLARE @strMessage		AS NVARCHAR(MAX) = @JSonParameters
				DECLARE @param			AS NVARCHAR(100) = N'@strParamOUT NVARCHAR(MAX) OUTPUT'

				EXEC sp_executesql @strScript4Execute, @param, @strMessage OUTPUT;
				IF @strMessage <> ''
					BEGIN
						SELECT @strMessage
					END
				ELSE
					BEGIN
						SELECT '-9'
					END
			END
		ELSE
			BEGIN
				SELECT '-3'
			END


	END TRY
	BEGIN CATCH
		SELECT '-4'
		RETURN
	END CATCH


END

GO





CREATE PROCEDURE [dbo].spWebSiteII_Favorites_AddItem
(
	@comp_id			INT,
	@ws_id				UNIQUEIDENTIFIER,
	@guid				UNIQUEIDENTIFIER,
	@Item_id			INT,
	@cust_id			INT,
	@note				NVARCHAR(MAX),
	@value				DECIMAL(19,2),
	@IsActive			BIT
)
AS

BEGIN

	SET NOCOUNT ON


	IF @cust_id = -1 SET @cust_id = NULL



	IF NOT EXISTS(
					SELECT 1
						FROM tbWebSiteII_Items_Favorites twsiif		WITH (NOLOCK)
						WHERE	twsiif.comp_id = @comp_id AND
								twsiif.ws_id = @ws_id AND
								twsiif.item_id = @item_id AND
							   (
							   		twsiif.cust_id		= @cust_id
									OR
									twsiif.wsif_guid	= @guid
							   )
				)

		BEGIN

			INSERT INTO tbWebSiteII_Items_Favorites
			(
				comp_id,
				ws_id,
				cust_id,
				wsif_guid,
				wsif_cd,
				item_id,
				wsif_note,
				wsif_value,
				wsif_isActive
			)
			VALUES
			(
				@comp_id,
				@ws_id,
				@cust_id,
				@guid,
				GETDATE(),
				@item_id,
				@note,
				@value,
				@IsActive
			)

		END

	ELSE
		BEGIN


			UPDATE tbWebSiteII_Items_Favorites
				SET
					wsif_note		= @note,
					wsif_value		= @value,
					wsif_isActive	= @IsActive	,
					wsif_ud			= GETDATE()
				WHERE	comp_id = @comp_id AND
						ws_id	= @ws_id AND
						item_id = @item_id AND
					   (	cust_id		= @cust_id
						OR
							wsif_guid	= @guid
					   )

		END

END
GO








CREATE PROCEDURE [dbo].[spWebSiteII_Files_InsertData]
(
	@ws_fileName				nvarchar(200),
	@ws_fileContent				Image,
	@ws_code					int,
	@ws_fileLenght				decimal(19,0),
	@chkOverwriteLocalPages		bit,
	@return_value				INT OUTPUT
)
as

set nocount on


BEGIN

	---------------------------------------------------------------------
	---------------------------------------------------------------------
	/*

	Declare 	@ws_fileName		nvarchar(200),
				@ws_fileContent		Image,
				@ws_code			int,
				@ws_fileLenght		decimal(19,0)

	Select		@ws_fileName		= 'asda',
				@ws_fileContent		= 'dsrt4t',
				@ws_code			= 1,
				@ws_fileLenght		= 123

	*/
	---------------------------------------------------------------------
	---------------------------------------------------------------------


if not exists (	SELECT TOP 1 1
               		from tbWebSite_Files twsf	WITH (NOLOCK)
               		WHERE twsf.ws_fileName = @ws_fileName AND twsf.ws_code = @ws_code)
	begin

		Insert into tbWebSite_Files
		(
			ws_fileName,
			ws_fileContent,
			ws_code,
			ws_fileLength
		)
		VALUES
		(
			@ws_fileName,
			@ws_fileContent,
			@ws_code,
			@ws_fileLenght
		)


		SET @return_value = @@IDENTITY

end


	else


	IF exists (	SELECT TOP 1 1
					from tbWebSite_Files twsf	WITH (NOLOCK)
	           		WHERE twsf.ws_fileName = @ws_fileName AND twsf.ws_code = @ws_code) and @chkOverwriteLocalPages = 'true'
		BEGIN


			update tbWebSite_Files
			SET
					ws_fileContent		= @ws_fileContent,
					ws_fileLength		= @ws_fileLenght,
					@return_value		= ws_fileId

			WHERE	ws_fileName		= @ws_fileName
			AND		ws_code			= @ws_code

		END



UPDATE	tbWebSiteII_Names
SET		ws_files2TempUpdated				= 'false',
		ws_files2TempUpdated4Development	= 'False'

SET @return_value = 0


END


GO

CREATE PROCEDURE spWebSiteII_GetAvailableMasterPages
AS
	BEGIN
		SET NOCOUNT ON
		SELECT
			twsip.comp_id,
			twsip.page_id,
			twsip.page_name,
			twsip.page_seoName,
			twsip.page_html,
			twsip.page_disabled,
			twsip.page_urlEnd,
			twsip.page_title,
			twsip.page_head,
			twsip.page_footer,
			twsip.page_backgroundImage,
			twsip.page_id4HeaderScript,
			twsip.page_id4FooterScript,
			twsip.page_metaKeywords,
			twsip.page_metaDescription,
			twsip.ws_bodyOnLoad,
			twsip.page_idIfNoCustomerLogged,
			twsip.page_idIfNoUserLogged,
			twsip.page_enableImageCheck,
			twsip.page_pageNote4Designer,
			twsip.page_only4DesignMode,
			twsip.page_analyticsCode,
			twsip.page_analyticsCodeIsDisabled,
			twsip.page_analyticsCodePageName4Track,
			twsip.page_exclude4RobotIndex,
			twsip.page_titleScript,
			twsip.page_titleScriptAvailable,
			twsip.page_includeOnSiteMap,
			twsip.page_disableMeta,

			-- NO PONER NADA DEBAJO DE ESTO -----------------------------------------------------------
			twsip.ws_masterPage_TAG,												-- Count -4
			twsip.ws_masterPage_isAvailable4Update,									-- Count -3
			twsip.ws_masterPage_Version,											-- Count -2
			twsip.ws_masterPage_CallUpdateFromMasterPagesMethod						-- Count -1
			-- NO PONER NADA DEBAJO DE ESTO -----------------------------------------------------------

			FROM tbWebSiteII_Pages													twsip	WITH(NOLOCK)
			WHERE	ISNULL(twsip.ws_masterPage_TAG,'')						<> ''	AND
					ISNULL(twsip.ws_masterPage_isAvailable4Update,'False')	= 'True'

	END

GO


