CREATE PROCEDURE [dbo].[spWebSiteII_getLandingPageURL]
(
	@strLandingURL			VARCHAR(400)
)
AS

BEGIN

	SET NOCOUNT ON

	DECLARE @strFinalURL AS VARCHAR(450) = ''

	SELECT TOP 1	twsilp.wsurlm_finalURL								[wsurlm_finalURL],
					ISNULL(twsilp.wsurlm_keepOriginalUrl,'False')		[wsurlm_keepOriginalUrl],
					twsilp.ws_id,
					twsilp.page_id,
					ISNULL(twsin.ws_url,'')								[ws_url],
					ISNULL(twsin.ws_urlEnd,'')							[ws_urlEnd]
		FROM tbWebSiteII_landingPages	AS twsilp	WITH (NOLOCK)
		LEFT JOIN tbWebSiteII_Names		AS twsin	WITH (NOLOCK)
			ON twsin.ws_id = twsilp.ws_id
		LEFT JOIN tbWebSiteII_Pages		AS twsip	WITH (NOLOCK)
			ON twsip.page_id = twsilp.page_id
		WHERE	(
					@strLandingURL LIKE '%' +  twsilp.wsurlm_text1 + '%'
					AND
					@strLandingURL LIKE '%' +  twsilp.wsurlm_text2 + '%'
				)
				OR twsilp.wsurlm_isCatchAll = 'True'		-- debe haber SOLO UNA pagina de catchall para TODOS los sitios web que esten soportados en la BD

		ORDER BY
			CASE
				WHEN twsilp.wsurlm_isCatchAll = 'True' THEN	1
				ELSE										0
			END

	--SELECT  @strFinalURL [finalURL]

END
GO

