-- =============================================
CREATE PROCEDURE spWebSiteII_GetPriceListRelatedOfWebSite
	@comp_id	AS INT,
	@ws_id		AS UNIQUEIDENTIFIER

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	SELECT DISTINCT  twsiplr.prli_id
		FROM tbWebSiteII_PriceListRelation AS twsiplr	 WITH (NOLOCK)
		WHERE	twsiplr.comp_id = @comp_id AND
				twsiplr.ws_id	= @ws_id


END
GO







