CREATE PROCEDURE [dbo].[spWebsiteII_ItemsData_GetDataById]
(
	@comp_id	INT,
	@ws_id		UNIQUEIDENTIFIER,
	@prli_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON

		SELECT
			twsiid.comp_id,
			twsiid.prli_id,
			twsiid.item_id,

			CASE
				WHEN twsiid.prli_priceNOTaxes < dbo.fnGetExchange2(@comp_id,  ISNULL(TPLI.prli_price,0), tpli.curr_id, twsiid.curr_id, 0, 0, 0, 'False') THEN dbo.fnGetExchange2(@comp_id,  TPLI.prli_price, tpli.curr_id, twsiid.curr_id, 0, 0, 0, 'False')
				ELSE twsiid.prli_priceNOTaxes
			END
			/*twsiid.prli_priceNOTaxes*/		[prli_price],
			twsiid.curr_id,
			twsiid.ws_id,
			twsiid.itst_cant,
			twsiid.itst_LastAvailableInRelalculation,
			twsiid.cat_id,
			twsiid.subcat_id,
			twsiid.subcataux_id,
			twsiid.ic_id,
			twsiid.currency_symbol,
			twsiid.semaphoreValue
			FROM tbWebSiteII_ItemsData			twsiid			WITH (NOLOCK)
			INNER JOIN tbPriceListItems			tpli			WITH (NOLOCK)
				ON	TPLI.comp_id = @comp_id AND
					TPLI.prli_id = @prli_id AND
					tpli.item_id = @item_id
			WHERE	twsiid.comp_id	= @comp_id	AND
					twsiid.ws_id	= @ws_id	AND
					twsiid.prli_id	= @prli_id	AND
					twsiid.item_id	= @item_id

	END
GO


CREATE PROCEDURE [dbo].[spWebSiteII_ItemsData_GetItems4TiendaNubeProcessing]
(
	@comp_id	INT,
	@tn_id		INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- --------------------------------------------------
		-- TESTING
		-- --------------------------------------------------
		/*
			DECLARE
				@comp_id	INT
			SELECT
				@comp_id	= 1
		*/
		-- --------------------------------------------------

		SELECT --TOP 1
			--DATOS WEBSITE2 -------------------------------------------------------------------------------------------------------------------
			twsiid.comp_id																					[WebSiteII_CompID],
			twsiid.item_id																					[WebSiteII_ItemID],
			CONVERT(DECIMAL(25,0),twsiid.prli_price)														[WebSiteII_Price],
			twsiid.curr_id																					[WebSiteII_CurrID],
			twsiid.prli_id																					[WebSiteII_PRLIID],
			twsiid.ws_id																					[WebSiteII_WSID],
			--DATOS LISTA DE PRECIOS -----------------------------------------------------------------------------------------------------------
			tpli.curr_id																					[TPLI_curr_id],
			--TIPO DE CAMBIO -------------------------------------------------------------------------------------------------------------------
			dbo.fnGetExchange2(twsiid.comp_id, 1, tpli.curr_id, 1, 0,0,0,'False')							[CurrentExchange],
			--DATOS TIENDANUBE -----------------------------------------------------------------------------------------------------------------
			ttns.comp_id																					[TN_CompID],
			ttns.tn_id																						[TN_TnID],
			ttns.tn_desc																					[TN_tnDesc],
			ttns.tn_useragent																				[TN_userAgent],
			ttns.tn_accesTocken																				[TN_AccessTocken],
			dbo.fnGetAStock4MaxAssociation(ttns.comp_id, ttns.stor_id4Publicate, twsiid.item_id, 99999999)	[TN_Stock],
			--DATOS ARTICULO -------------------------------------------------------------------------------------------------------------------
			ti.item_id																						[TI_ItemID],
			ti.item_code																					[TI_ItemCode],
			ti.item_desc																					[TI_ItemDesc],
			ti.item_descHTML																				[TI_item_descHTML],
			ISNULL(ti.item_higth,0)																			[TI_item_higth],	-- Alto en centímetros
			ISNULL(ti.item_weight,0)/1000																	[TI_item_weight], --Peso en Gramos
			ISNULL(ti.item_large,0)																			[TI_item_large],	--Largo en centímetros
			ISNULL(ti.item_wide,0)																			[TI_item_wide],   --PRODUNDIDAD
			--DATOS TNRELATIONS	----------------------------------------------------------------------------------------------------------------
			ttnir.comp_id																					[TNIR_CompId],
			ttnir.item_id																					[TNIR_ItemId],
			ttnir.tnr_disabled																				[TNIR_Disabled],
			CONVERT(DECIMAL(25,0),ISNULL(ttnir.tnr_lastPrice,0))											[TNIR_LastPrice],
			ISNULL(ttnir.tnr_lastExchange,0)																[TNIR_LastExchange],
			ISNULL(ttnir.tnr_lastStock,0)																	[TNIR_LastStock],
			ISNULL(ttnir.tnr_id,0)																			[TNIR_ProductID],
			ISNULL(ttnir.tnr_variationID,0)																	[TNIR_VariantID],
			ISNULL(ttnir.tnr_lastExecError,'False')															[TNIR_lastExecError],
			ttnir.tnr_relationID																			[TNIR_relationID],
			--ID DE SUBCAT EN TN----------------------------------------------------------------------------------------------------------------
			ISNULL(ttnsbs.tn_categoryID,tsc.tn_categoryID)													[TN_CATEGORY_ID]

			FROM tbWebSiteII_ItemsData					twsiid	WITH(NOLOCK)
			INNER JOIN tbPriceListItems					tpli	WITH(NOLOCK)
				ON	tpli.comp_id		= twsiid.comp_id	AND
					tpli.prli_id		= twsiid.prli_id	AND
					tpli.item_id		= twsiid.item_id
			INNER JOIN tbTiendaNube_Stores				ttns	WITH(NOLOCK)
				ON	ttns.comp_id		= twsiid.comp_id	AND
					ttns.ws_id			= twsiid.ws_id
			INNER JOIN tbItem							ti		WITH(NOLOCK)
				ON	ti.comp_id			= twsiid.comp_id	AND
					ti.item_id			= twsiid.item_id
			INNER JOIN tbSubCategory					tsc		WITH(NOLOCK)
				ON	tsc.comp_id			= ti.comp_id		AND
					tsc.cat_id			= ti.cat_id			AND
					tsc.subcat_id		= ti.subcat_id
			LEFT JOIN tbTiendaNube_SubcategoryByStore AS ttnsbs	WITH (NOLOCK)
				ON	ttnsbs.comp_id		= @comp_id			AND
					ttnsbs.tn_id		= @tn_id			AND
					ttnsbs.cat_id		= ti.cat_id			AND
					ttnsbs.subcat_id	= ti.subcat_id
			LEFT JOIN tbTiendaNube_ItemsRelations		ttnir	WITH(NOLOCK)
				ON	ttnir.comp_id		= ttns.comp_id		AND
					ttnir.tn_id			= ttns.tn_id		AND			-- MOS 10-2023, si tienen mas de una TN hace cualquier mierda...
					ttnir.item_id		= twsiid.item_id
			WHERE	twsiid.comp_id	= @comp_id						AND
					--QUE NO TRAIGA LAS PUBLICACIONES QUE ESTEN PAUSADAS, ASÍ NO PROCESA AL PEDO REGISTROS
					ISNULL(ttnir.tnr_disabled,'False')	= 'False'	AND
					ISNULL(ttns.tn_disabled,'False')	= 'False'	AND
					ttns.tn_id							= @tn_id	AND	-- MOS 10-2023: llama x tienda, si hay mas de una solo debe retornar los items de esa tienda.
					-- ----------------------------------------------------------------------
					-- MOS 04-2022 para que por poner MIERDAS en la conf no hagan cagadas,
					-- por lo que, si ponen una lista en la tienda,
					-- DEBE estar la relacion SI o SI entre la lista y el sitio web.
					ttns.prli_id						= twsiid.prli_id	AND
					-- ----------------------------------------------------------------------
					twsiid.prli_price					> 0					AND	-- STL / MOS 16-11-2023 Para que no publique o actualice artìculos si tiene precio en 0
					ISNULL(ttnsbs.tn_categoryID,tsc.tn_categoryID)			> 0	-- STL / MOS 16-11-2023 Para que no publique o intente publicar articulos que no tienen un id de subcategoria de TN asociado

					-- MOS 02-2024: Si Esta relacionado siempre informa o si NO esta relacionado pero SI tiene stock disponible
					AND
					(
						ttnir.comp_id IS NOT NULL
							OR
						(
							ttnir.comp_id IS NULL
								AND
							twsiid.itst_cant > 0
						)
					)
	END
GO









