CREATE PROCEDURE [dbo].[spWebSiteII_microSites_ExistsData]
(
	@comp_id	INT,
	@ws_id		UNIQUEIDENTIFIER,
	@item_id	INT,
	@cat_id		INT,
	@subcat_id	INT
)
AS

	BEGIN
		SET NOCOUNT ON

		-- ------------------------------------------------
		-- TESTING
		-- ------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@ws_id		UNIQUEIDENTIFIER,
				@item_id	INT,
				@cat_id		INT,
				@subcat_id	INT
			SELECT
				@comp_id	= 1,
				@ws_id		= 'e7bfe3da-ecb7-462a-9c2b-d7566de23857',
				@item_id	= -1,
				@cat_id		= 3,
				@subcat_id	= 3812
		*/
		-- ------------------------------------------------

		DECLARE
			@Exists	BIT

		SET @Exists = 'False'

		IF EXISTS(SELECT 1
					FROM tbWebSiteII_microSites										twsims
				  WHERE twsims.comp_id		= @comp_id								AND
						twsims.ws_id		= @ws_id								AND
						(@item_id			= -1 OR twsims.item_id		= @item_id)	AND
						twsims.cat_id		= @cat_id								AND
						twsims.subcat_id	= @subcat_id)
			BEGIN
				SET @Exists = 'True'
			END

		SELECT @Exists [Result]

	END

GO





