CREATE PROCEDURE [dbo].[spWebSiteII_microSites_Prices_GetDataByFilters]
(
	@comp_id			INT,
	@lang_id			INT,
	@bra_id				INT,
	@prof_id			INT,
	@user_id			INT,
	@ws_id				UNIQUEIDENTIFIER,
	@cat_id				INT ,
	@subcat_id			INT,
	@item_id			INT,
	@datefrom			DATETIME,
	@dateto				DATETIME,
	@option_pricetype	INT,			-- 1 : markup , 2: precio a incrementar,3 : precio sin imp.
	@isdisabled			INT	,			-- -1 todos , 0 No , 1 SI
	@ValueOption		INT,
	@ValueFrom		    DECIMAL(19,6),
	@ValueTo			DECIMAL(19,6),
	@priceRoundType		INT				-- Opcion de redondeo


)
AS


	BEGIN


		SET NOCOUNT ON
		SET DATEFORMAT 'ymd'

		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
		SET LOCK_TIMEOUT 500
		SET DEADLOCK_PRIORITY LOW

		------------------------------------------------------------------------------------

/*
		DECLARE
				@comp_id			INT,
				@lang_id			INT,
				@bra_id				INT,
				@prof_id			INT,
				@user_id			INT,
				@ws_id				UNIQUEIDENTIFIER,
				@cat_id				INT ,
				@subcat_id			INT,
				@item_id			INT,
				@datefrom			DATETIME,
				@dateto				DATETIME,
				@option_pricetype	INT,      -- 1 : markup , 2: precio a incrementar
				@isdisabled			INT	,	  -- -1 todos , 0 No , 1 SI
				@ValueOption		INT,
				@ValueFrom		    DECIMAL(19,6),
				@ValueTo			DECIMAL(19,6)


		SELECT

			@comp_id			= 1,
			@lang_id			= 2,
			@bra_id				= 1,
			@prof_id			= 1,
			@user_id			= 119,
			@ws_id				='E7BFE3DA-ECB7-462A-9C2B-D7566DE23857',
			@cat_id				= -1 ,
			@subcat_id			= -1,
			@item_id			= -1,
			@datefrom			= '01/01/2000',
			@dateto				= '01/01/2018',
			@option_pricetype	= -1,      -- 1 : markup , 2: precio a incrementar
			@isdisabled			= -1	,	  -- -1 todos , 0 No , 1 SI
			@ValueOption		= -1,
			@ValueFrom		    = 0,
			@ValueTo			= 0
*/
	------------------------------------------------------------------------------------
		SET @dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')




		SELECT
			' '												[ ],
			' '												[ ],
			twsin.ws_desc									[ws_desc],
			--tcust.cust_name									[cust_name],
			tc.cat_desc										[cat_desc],
			tsc.subcat_desc									[subcat_desc],
			ti.item_desc									[item_desc],
			tov.optval_desc									[wsmsp_priceType],
			twsims.wsmsp_value								[wsmsp_value],
			twsims.wsmsp_lastUpdate							[wsmsp_lastUpdate],
			twsims.wsmsp_isDisabled							[wsmsp_isDisabled],
			tpl.prli_desc									[prli_desc],
			tov_round.optval_desc							[wsmsp_priceRoundType],
			twsims.wsmsp_id									[ID]

			FROM tbWebSiteII_microSites						twsims	WITH(NOLOCK)

			INNER JOIN tbWebSiteII_Names					twsin	WITH(NOLOCK)
				ON	twsin.comp_id	= twsims.comp_id	AND
					twsin.ws_id		= twsims.ws_id

			LEFT JOIN tbCustomer							tcust	WITH(NOLOCK)
				ON	tcust.comp_id	= twsin.comp_id				AND
					tcust.cust_id	= twsin.cust_id4MicroSites	AND
					twsin.ws_microSite_SO4WebSiteCustomerMicroSite = 'True' --toma el cliente de micrositio

			LEFT JOIN tbCategory							tc		WITH(NOLOCK)
				ON	tc.comp_id		= twsims.comp_id	AND
					tc.cat_id		= twsims.cat_id

			LEFT JOIN tbSubCategory							tsc		WITH(NOLOCK)
				ON	tsc.comp_id		= twsims.comp_id	AND
					tsc.cat_id		= twsims.cat_id		AND
					tsc.subcat_id	= twsims.subcat_id

			 LEFT JOIN tbItem								ti		WITH(NOLOCK)
				ON	ti.comp_id		= twsims.comp_id	AND
					ti.item_id		= twsims.item_id

			INNER JOIN tbsysOptionsValues					tov		WITH(NOLOCK)
				ON	tov.lang_id		 = @lang_id					AND
					tov.optval_id	 = twsims.wsmsp_priceType	AND
					tov.optval_class = 552

			INNER JOIN tbsysOptionsValues					tov_round		WITH(NOLOCK)
				ON	tov_round.lang_id		= @lang_id					AND
					tov_round.optval_id		= twsims.wsmsp_priceRoundType	AND
					tov_round.optval_class	= 676

			LEFT JOIN tbPriceList							tpl		WITH(NOLOCK)
				ON	tpl.comp_id		 = twsims.comp_id			AND
					tpl.prli_id		 = twsims.prli_id

			WHERE	(twsims.comp_id		= @comp_id)											     AND
					--(twsims.ws_id		= @ws_id AND twsin.user_id4MicroSites = @user_id)		 AND --En la pagina principal estan todos los sitios por eso filtramos aca por el user
					(twsims.ws_id		= @ws_id )												 AND
					(@item_id	= -1 or twsims.item_id		= @item_id)						     AND
					(@cat_id	= -1 or twsims.cat_id		= @cat_id)							 AND
					(@subcat_id = -1 or twsims.subcat_id	= @subcat_id)						 AND
					(@priceRoundType = -1 or isnull(twsims.wsmsp_priceRoundType,0)		= @priceRoundType) AND
					(twsims.wsmsp_lastUpdate		BETWEEN		@datefrom	AND	@dateto)		 AND -- fecha de ultima actualizacion
					(@option_pricetype	= -1 or twsims.wsmsp_priceType		= @option_pricetype) AND  -- 1 : markup , 2: precio a incrementar
					(@isdisabled		= -1 or twsims.wsmsp_isDisabled		= @isdisabled)		 AND
					(
					(@ValueOption = -1)														or
					(@ValueOption = 0 and twsims.wsmsp_value = @ValueFrom)						or
					(@ValueOption = 1 and twsims.wsmsp_value > @ValueFrom)						or
					(@ValueOption = 2 and twsims.wsmsp_value < @ValueFrom)						or
					(@ValueOption = 3 and twsims.wsmsp_value between @ValueFrom and @ValueTo)
					)


		ORDER BY twsims.wsmsp_lastUpdate desc
	END


GO






CREATE PROCEDURE [dbo].[spWebSiteII_microSites_Prices_GetDataById]
(
	@comp_id			   INT,
	@wsmsp_id			   INT
)

AS
SET NOCOUNT ON
BEGIN


	SELECT
		twsims.comp_id,
		twsims.wsmsp_id,
		twsims.ws_id,
		twsims.cat_id,
		twsims.subcat_id,
		twsims.item_id,
		twsims.wsmsp_priceType							[wsmsp_priceType],
		twsims.wsmsp_value								[wsmsp_value],
		twsims.wsmsp_lastUpdate							[wsmsp_lastUpdate],
		isnull(twsims.wsmsp_isDisabled,'FALSE')			[wsmsp_isDisabled],
		twsims.prli_id									[prli_id],
		isnull(wsmsp_priceRoundType,0)					[wsmsp_priceRoundType]

	FROM tbWebSiteII_microSites					twsims


	WHERE twsims.comp_id	= @comp_id
	AND   twsims.wsmsp_id	= @wsmsp_id






END

GO





CREATE PROCEDURE [dbo].[spWebSiteII_microSites_Prices_InsertData]
(
	@comp_id			INT,
	@ws_id				UNIQUEIDENTIFIER,
	@cat_id				INT ,
	@subcat_id			INT,
	@item_id			Int,
	@pricetype			Int,
	@value				DECIMAL(25,2),
	@lastupdate			DateTime,
	@isdisabled			BIT,
	@prli_id			INT,
	@priceRoundType		INT,
	@return_value		int output


)
AS


BEGIN

	SET NOCOUNT ON

	IF @item_id = -1
		BEGIN
			SET @item_id = NULL
		END

	IF @item_id IS NOT NULL
		BEGIN
			SET @cat_id		= NULL
			SET @subcat_id	= NULL
		END


	SET @return_value = -1


	BEGIN TRY



		INSERT INTO tbWebSiteII_microSites
		(
			comp_id,
			ws_id,
			cat_id,
			subcat_id,
			item_id,
			wsmsp_priceType,
			wsmsp_value,
			wsmsp_lastUpdate,
			wsmsp_isDisabled,
			prli_id,
			wsmsp_priceRoundType

		)
		VALUES
		(

			@comp_id,
			@ws_id,
			@cat_id,
			@subcat_id,
			@item_id,
			@pricetype,
			@value,
			@lastupdate,
			@isdisabled,
			@prli_id,
			@priceRoundType

		)

		SET @return_value = @@IDENTITY

	END TRY
	BEGIN CATCH
		SET @return_value = -1
	END CATCH

END


GO





CREATE PROCEDURE [dbo].[spWebSiteII_microSites_Prices_UpdateData]
(
	@comp_id			INT,
	@ws_id				UNIQUEIDENTIFIER,
	@cat_id				INT ,
	@subcat_id			INT,
	@item_id			Int,
	@pricetype			Int,
	@value				DECIMAL(25,2),
	@lastupdate			DateTime,
	@isdisabled			BIT,
	@prli_id			INT,
	@wsmsp_id			INT,
	@priceRoundType		INT



)
AS

SET NOCOUNT ON

BEGIN

	IF @item_id = -1
		BEGIN
			SET @item_id = NULL
		END


	IF @item_id IS NOT NULL
		BEGIN
			SET @cat_id		= NULL
			SET @subcat_id	= NULL
		END

	UPDATE tbWebSiteII_microSites
	SET
		comp_id				 = @comp_id,
		ws_id				 = @ws_id,
		cat_id				 = @cat_id,
		subcat_id			 = @subcat_id,
		item_id				 = @item_id,
		wsmsp_priceType		 = @pricetype,
		wsmsp_value			 = @value,
		wsmsp_lastUpdate	 = @lastupdate,
		wsmsp_isDisabled	 = @isdisabled,
		prli_id				 = @prli_id,
		wsmsp_priceRoundType = @priceRoundType

	WHERE
		comp_id		= @comp_id	AND
		wsmsp_id	= @wsmsp_id





END


GO





CREATE PROCEDURE [dbo].[spWebSiteII_microSites_Prices_UpdateData_MassActions]
(

	@comp_id			INT,
	@ws_id				UNIQUEIDENTIFIER,
	@Item_Guid			UNIQUEIDENTIFIER,
	@action				INT,
	@pricetype			INT,
	@value				DECIMAL(25,2),
	@lastupdate			DateTime,
	@isdisabled			BIT,
	@prli_id			INT,
	@priceRoundType		INT
)
AS


BEGIN

	SET NOCOUNT ON

	-- ------------------------------------------------
	-- TESTING
	-- ------------------------------------------------
	/*
		DECLARE
			@comp_id			INT,
			@ws_id				UNIQUEIDENTIFIER,
			@Item_Guid			UNIQUEIDENTIFIER,
			@action				INT,
			@pricetype			INT,
			@value				DECIMAL(25,2),
			@lastupdate			DateTime,
			@isdisabled			BIT,
			@prli_id			INT
		SELECT
			@comp_id			= 1,
			@ws_id				= 'e7bfe3da-ecb7-462a-9c2b-d7566de23857',
			@Item_Guid			= '988C3689-8EF4-4FBF-A6FB-CDA75C71FD63',
			@action				= 1,
			@pricetype			= 1,
			@value				= 1,
			@lastupdate			= '12/08/2016',
			@isdisabled			= 1,
			@prli_id			= 1
	*/
	-- ------------------------------------------------

	DECLARE @objGUID AS UNIQUEIDENTIFIER
	SET @objGUID = CONVERT(UNIQUEIDENTIFIER,@Item_Guid)

	DECLARE @tblComplexFilter_Items TABLE (item_id INT PRIMARY KEY)

	INSERT INTO @tblComplexFilter_Items

		SELECT
			tcf.sl_id
			FROM tbComplexFilter tcf      WITH (NOLOCK)
			WHERE tcf.sl_guid	  = @objGUID      AND
				  tcf.sl_selected = 'True'


		IF @action = 1
			BEGIN
			--ACTUALIZAR O AGREGAR
			DECLARE @litem_id AS INT,@lcat_id AS INT,@lsubcat_id AS INT
			DECLARE cursor_items CURSOR LOCAL FAST_FORWARD FOR

				SELECT	ti.item_id,ti.cat_id, ti.subcat_id
				FROM tbItem										ti
				INNER JOIN @tblComplexFilter_Items				tmp
				ON	tmp.item_id		= ti.item_id
				WHERE ti.comp_id	= @comp_id

			OPEN cursor_items

			-- lectura anticipada del cursor
			FETCH  cursor_items INTO	@litem_id,@lcat_id,@lsubcat_id

			WHILE @@FETCH_STATUS = 0
				BEGIN

					IF EXISTS(SELECT
								1
								FROM tbWebSiteII_microSites										twsims
								WHERE	twsims.comp_id		= @comp_id								AND
										twsims.ws_id		= @ws_id								AND
										twsims.item_id		= @litem_id)
										--								AND
										--twsims.cat_id		= @lcat_id								AND
										--twsims.subcat_id	= @lsubcat_id)
							BEGIN
								--Actualiza
								UPDATE tbWebSiteII_microSites
								SET
									wsmsp_priceType		 = @pricetype,
									wsmsp_value			 = @value,
									wsmsp_lastUpdate	 = @lastupdate,
									wsmsp_isDisabled	 = @isdisabled,
									prli_id				 = @prli_id,
									wsmsp_priceRoundType = @priceRoundType

								WHERE	comp_id		= @comp_id								AND
										ws_id		= @ws_id								AND
										item_id		= @litem_id
										--								AND
										--cat_id		= @lcat_id								AND
										--subcat_id	= @lsubcat_id


							END

					ELSE
							BEGIN
								--Inserta ya que no existe.
								BEGIN TRY
									INSERT INTO tbWebSiteII_microSites
									(
										comp_id,
										ws_id,
										item_id,
										wsmsp_priceType,
										wsmsp_value,
										wsmsp_lastUpdate,
										wsmsp_isDisabled,
										prli_id,
										wsmsp_priceRoundType
									)
									VALUES
									(

										@comp_id,
										@ws_id,
										@litem_id,
										@pricetype,
										@value,
										@lastupdate,
										@isdisabled,
										@prli_id,
										@priceRoundType

									)

								END TRY
							BEGIN CATCH
							END CATCH

							END

					FETCH  cursor_items INTO	@litem_id,@lcat_id,@lsubcat_id

				END

					CLOSE cursor_items
					DEALLOCATE cursor_items
			END

		ELSE
			BEGIN
				--BORRAR

				DECLARE @Ditem_id AS INT,@Dcat_id AS INT,@Dsubcat_id AS INT
				DECLARE cursor_items CURSOR LOCAL FAST_FORWARD FOR

					SELECT	ti.item_id,ti.cat_id, ti.subcat_id
					FROM tbItem										ti
					INNER JOIN @tblComplexFilter_Items				tmp
					ON	tmp.item_id		= ti.item_id
					WHERE ti.comp_id	= @comp_id

				OPEN cursor_items

				-- lectura anticipada del cursor
				FETCH  cursor_items INTO	@Ditem_id,@Dcat_id,@Dsubcat_id

				WHILE @@FETCH_STATUS = 0
					BEGIN

						DELETE
							FROM tbWebSiteII_microSites

							WHERE	comp_id		= @comp_id				AND
									ws_id		= @ws_id				AND
									item_id		= @Ditem_id
									--AND
									--cat_id		= @Dcat_id				AND
									--subcat_id	= @Dsubcat_id


						FETCH  cursor_items INTO	@Ditem_id,@Dcat_id,@Dsubcat_id

					END

					CLOSE cursor_items
					DEALLOCATE cursor_items


			END













END


GO





