CREATE PROCEDURE [dbo].[spWebSiteII_Names_CloneWebSite_GetData]
(
	@ws_id_from				UNIQUEIDENTIFIER
)
AS
SET NOCOUNT ON


BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

	DECLARE		@ws_id_from			UNIQUEIDENTIFIER

	SELECT		@ws_id_from			= 'E7BFE3DA-ECB7-462A-9C2B-D7566DE23857'

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------



	DECLARE @bitEnable4Clone AS BIT = 'False'
	SELECT 	@bitEnable4Clone = ISNULL(twsip.ws_enable4Clone,'False')
		FROM	tbWebSiteII_Names								twsip		WITH (NOLOCK)
		WHERE twsip.ws_id = @ws_id_from


			----------------------------------------------------------------------------------------------------
			--tbWebSite_Files
			----------------------------------------------------------------------------------------------------

			SELECT  twsf.ws_fileId												[ws_fileId],
					isnull(twsf.ws_fileName,'')									[ws_fileName],
					twsf.ws_fileContent											[ws_fileContent],
					isnull(twsf.ws_code,-1)										[ws_code],
					isnull(twsf.ws_fileLength,0)								[ws_fileLength]
				FROM tbWebSite_Files									twsf		WITH (NOLOCK)
				WHERE @bitEnable4Clone = 'True'

			----------------------------------------------------------------------------------------------------
			--tbWebSiteII_Pages
			----------------------------------------------------------------------------------------------------

			select	isnull(twsip.comp_id, -1)									[comp_id],
					twsip.page_id												[page_id],
					isnull(twsip.page_name,'')									[page_name],
					isnull(twsip.page_seoName,'')								[page_seoName],
					isnull(twsip.page_html,'')									[page_html],
					isnull(twsip.page_disabled,'false')							[page_disabled],
					isnull(twsip.page_urlEnd,'')								[page_urlEnd],
					isnull(twsip.page_title,'')									[page_title],
					isnull(twsip.page_head,'')									[page_head],
					isnull(twsip.page_footer,'')								[page_footer],
					isnull(twsip.page_backgroundImage,'')						[page_backgroundImage],
					twsip.page_id4HeaderScript									[page_id4HeaderScript],
					twsip.page_id4FooterScript									[page_id4FooterScript],
					ISNULL(twsip.ws_bodyOnLoad,'')								[ws_bodyOnLoad],
					twsip.page_idIfNoCustomerLogged,
					twsip.page_idIfNoUserLogged,
					isnull(twsip.page_enableImageCheck,'False')					[page_enableImageCheck],
					isnull(twsip.page_pageNote4Designer,'')						[page_pageNote4Designer],
					ISNULL(twsip.page_only4DesignMode,'False')					[page_only4DesignMode],
					ISNULL(twsip.page_analyticsCodeIsDisabled,'False')			[page_analyticsCodeIsDisabled],
					ISNULL(twsip.page_includeOnSiteMap,'False')					[page_includeOnSiteMap]
				FROM	tbWebSiteII_Pages								twsip		WITH (NOLOCK)
				INNER JOIN tbWebSiteII_Names_Pages_Relation				twsinpr		WITH (NOLOCK)
					ON		twsinpr.comp_id = twsip.comp_id		AND
							twsinpr.page_id = twsip.page_id
				WHERE	twsinpr.ws_id		= @ws_id_from AND
						@bitEnable4Clone	= 'True'


			----------------------------------------------------------------------------------------------------
			--tbWebSiteII_Names_Pages_Relation
			----------------------------------------------------------------------------------------------------

			select	isnull(twsinpr.comp_id,-1)									[comp_id],
					twsinpr.ws_id												[ws_id],
					twsinpr.page_id												[page_id]
				FROM tbWebSiteII_Names_Pages_Relation					twsinpr		WITH (NOLOCK)
				where	twsinpr.ws_id		= @ws_id_from AND
						@bitEnable4Clone	= 'True'


			----------------------------------------------------------------------------------------------------
			--tbWebSiteII_Names
			----------------------------------------------------------------------------------------------------

			SELECT	twsin.comp_id												[comp_id],
					twsin.ws_id													[ws_id],
					twsin.lang_id												[lang_id],
					isnull(twsin.ws_desc,'')									[ws_desc],
					isnull(twsin.ws_url,'')										[ws_url],
					isnull(twsin.[user_id],-1)									[user_id],
					isnull(twsin.prof_id,-1)									[prof_id],
					isnull(twsin.prli_id,-1)									[prli_id],
					isnull(twsin.stor_id,-1)									[stor_id],
					isnull(twsin.ws_price_showPlusTax,'false')					[ws_price_showPlusTax],
					isnull(twsin.ws_price_showPrice,'false')					[ws_price_showPrice],
					isnull(twsin.ws_price_showWithDecimals,0)					[ws_price_showWithDecimals],
					twsin.ws_price_force2CurrId									[ws_price_force2CurrId],
					isnull(twsin.ws_stock_showStock,0)							[ws_stock_showStock],
					isnull(twsin.ws_stock_showDecimals,0)						[ws_stock_showDecimals],
					isnull(twsin.ws_newCustomerAllowed,'False')					[ws_newCustomerAllowed],
					isnull(twsin.ws_newCustomerCustId,-1)						[ws_newCustomerCustId],
					isnull(twsin.ws_newCustomerEmailContactName,'')				[ws_newCustomerEmailContactName],
					isnull(twsin.ws_newCustomerEmailContactEMail,'')			[ws_newCustomerEmailContactEMail],
					isnull(twsin.ws_newCustomerWelcomeText,'')					[ws_newCustomerWelcomeText],
					isnull(twsin.ws_newCustomerEmailContactPhone,'')			[ws_newCustomerEmailContactPhone],
					isnull(twsin.ws_analyticsCode,'')							[ws_analyticsCode],
					twsin.page_id												[page_id],
					isnull(twsin.ws_url4Design,'')								[ws_url4Design],
					isnull(twsin.page_parameters,'')							[page_parameters],
					isnull(twsin.ws_urlEnd,'')									[ws_urlEnd],
					isnull(twsin.ws_files2TempUpdated,'False')					[ws_files2TempUpdated],
					isnull(twsin.ws_files2TempUpdated4Development,'False')		[ws_files2TempUpdated4Development],
					isnull(twsin.bra_id,-1)										[bra_id],
					twsin.page_id4HeaderScript									[page_id4HeaderScript],
					twsin.page_id4FooterScript									[page_id4FooterScript],
					twsin.st_id													[st_id],
					twsin.dl_id													[dl_id]


				FROM tbWebSiteII_Names										twsin		WITH (NOLOCK)
				WHERE	twsin.ws_id			= @ws_id_from	AND
						@bitEnable4Clone	= 'True'

				----------------------------------------------------------------------------------------------------
			----------------------------------------------------------------------------------------------------


END
GO







