CREATE PROCEDURE [dbo].[spWebSiteII_Names_getDataByDomain]
(

	@ws_url				NVARCHAR(200),
	@bolIsDesignTime	BIT,
	@ws_id4Test			UNIQUEIDENTIFIER

)
AS



BEGIN


	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	------------------------------------------------------------------------------------------------
	--Parametros de Prueba
	------------------------------------------------------------------------------------------------
	/*

	DECLARE 	@ws_url			NVARCHAR(200)

	SELECT 		@ws_url			= 'http://localhost/gbp/PRINCIPAL/CLASE=1;TEST=2/gbpwst.aspx'

		-- http://localhost/gbp/
	*/
	------------------------------------------------------------------------------------------------


	DECLARE @WS_Id	AS UNIQUEIDENTIFIER
	DECLARE @wsu_id AS INT
	SET @wsu_id = -1


	SELECT	TOP 1	@WS_Id	= twsin.ws_id,
					@wsu_id = IsNull(twsinu.wsu_id,-1)
		FROM	tbWebSiteII_Names								twsin		WITH (NOLOCK)
		LEFT JOIN tbWebSiteII_Names_URLRelated					twsinu		WITH (NOLOCK)
			ON	twsinu.ws_id	=	  twsin.ws_id					AND
				@ws_url			LIKE  '%' + twsinu.ws_url	+ '%'	AND
				@bolIsDesignTime='False'
		WHERE
				twsinu.ws_id IS NOT NULL
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url <> ''  AND	@ws_url		LIKE   twsin.ws_url		+ '%'	)
					OR
				--(@bolIsDesignTime='False' AND							@ws_url		LIKE   twsin.ws_url		+ '%'	)
				--	OR
				(@bolIsDesignTime='False' AND twsin.ws_url1 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url1	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url2 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url2	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url3 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url3	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url4 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url4	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url5 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url5	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url6 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url6	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url7 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url7	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url8 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url8	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url9 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url9	+ '%'	)
					OR
				(@bolIsDesignTime='False' AND twsin.ws_url10 <> '' AND	@ws_url		LIKE  '%' + twsin.ws_url10	+ '%'	)

				-- o en Test
					OR
				(@bolIsDesignTime='True'  AND twsin.ws_id = @ws_id4Test)

	ORDER BY twsinu.wsu_order

	EXEC spWebSiteII_Names_getDataById @WS_Id, @wsu_id


END
GO







CREATE PROCEDURE [dbo].[spWebSiteII_Names_getDataById]
(
	@ws_id			UNIQUEIDENTIFIER,
	@wsu_id			INT
)
AS
SET NOCOUNT ON


BEGIN


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

------------------------------------------------------------------------------------------------
--Parametros de Prueba
------------------------------------------------------------------------------------------------

/*


DECLARE 	@comp_id		INT,
			@lang_id		INT,
			@ws_id			UNIQUEIDENTIFIER

SELECT 		@comp_id		= 1,
			@lang_id		= 2,
			@ws_id			= '0352be36-5ca2-4b30-be44-8a2020c78c14'


*/


------------------------------------------------------------------------------------------------
------------------------------------------------------------------------------------------------


		SELECT	twsin.ws_id,
				IsNull(@wsu_id,-1)									[wsu_id],
				ISNULL(twsin.ws_desc,'')							[ws_desc],
				CASE
					WHEN twsinu.ws_url IS NOT NULL AND twsinu.ws_url <> '' THEN twsinu.ws_url
					ELSE														ISNULL(twsin.ws_url,'')
				END													[ws_url],
				twsin.[user_id],
				twsin.prof_id,
				twsin.prli_id,
				twsin.stor_id,
				ISNULL(twsin.ws_price_showPlusTax,'false')			[ws_price_showPlusTax],
				ISNULL(twsin.ws_price_showPrice,'false')			[ws_price_showPrice],
				twsin.ws_price_showWithDecimals,
				twsin.ws_price_force2CurrId,
				twsin.ws_stock_showStock,
				twsin.ws_stock_showDecimals,
				ISNULL(twsin.ws_newCustomerAllowed,'false')			[ws_newCustomerAllowed],
				twsin.ws_newCustomerCustId,
				ISNULL(twsin.ws_newCustomerEmailContactName,'')		[ws_newCustomerEmailContactName],
				ISNULL(twsin.ws_newCustomerEmailContactEMail,'')	[ws_newCustomerEmailContactEMail],
				ISNULL(twsin.ws_newCustomerWelcomeText,'')			[ws_newCustomerWelcomeText],
				ISNULL(twsin.ws_newCustomerEmailContactPhone,'')	[ws_newCustomerEmailContactPhone],
				ISNULL(twsin.ws_analyticsCode,'')					[ws_analyticsCode],
				twsin.page_id,
				ISNULL(twsin.ws_url4Design,'')						[ws_url4Design],
				ISNULL(twsip.page_name,'')							[page_name],
				ISNULL(twsip.page_seoName,'')						[page_seoName],
				ISNULL(twsin.page_parameters,'')					[page_parameters],
				twsin.tast_id										[tast_id],
				twsin.task_priority									[task_priority],
				twsin.task_user_id									[task_user_id],
				ISNULL(twsin.task_subject,'')						[task_subject],
				twsin.task_bra_id									[task_bra_id],
				twsin.taskt_id										[taskt_id],
				twsin.df_id4Collection								[df_id4Collection],
				twsin.comp_id,
				twsin.cust_id4MicroSites,
				ISNULL(twsin.ws_microSite_SO4WebSiteCustomerMicroSite,'false') [ws_microSite_SO4WebSiteCustomerMicroSite],
				CASE
					WHEN ISNULL(twsin.ws_urlEnd,'') = '' THEN	'gbpws.aspx'
					ELSE										twsin.ws_urlEnd
				END													[ws_urlEnd],
				ISNULL(twsin.ws_MPClientId,'')						[ws_MPClientId],
				ISNULL(twsin.ws_MPClientSecret,'')					[ws_MPClientSecret],
				ISNULL(twsin.lang_id,2)								[lang_id],
				twsin.bra_id,
				ISNULL(twsin.ws_ServerGeneratedAuthorizationCode,'')					[ws_ServerGeneratedAuthorizationCode],
				ISNULL(twsin.ws_accessToken,'')											[ws_accessToken],
				ISNULL(twsin.ws_accessTokenValidUp2Date,DATEADD( DAY,100,GETDATE()))	[ws_accessTokenValidUp2Date],
				ISNULL(twsin.ws_refresh_Token,'')										[ws_refresh_Token],
				GETDATE()																[processDate],
				ISNULL(twsin.ws_loginByCustomerRelationed,'False')						[ws_loginByCustomerRelationed]


		FROM tbWebSiteII_Names						twsin				WITH (NOLOCK)
		LEFT JOIN tbWebSiteII_Names_URLRelated		twsinu				WITH (NOLOCK)
			ON	twsinu.comp_id	= twsin.comp_id AND
				twsinu.wsu_id	= @wsu_id
		LEFT JOIN tbWebSiteII_Pages					twsip				WITH (NOLOCK)
			ON  twsip.comp_id	= twsin.comp_id AND
				twsip.page_id	= twsin.page_id
		WHERE  twsin.ws_id	= @ws_id


END
GO





CREATE PROCEDURE [dbo].[spWebSiteII_Names_UpdateData]
(
		@comp_id								 INT,
		@ws_id									 UNIQUEIDENTIFIER,
		@lang_id								 INT,
		@ws_url									 NVARCHAR(200),
		@user_id								 INT,
		@prof_id								 INT,
		@prli_id								 INT,
		@stor_id								 INT,
		@ws_price_showPlusTax					 BIT,
		@ws_price_showPrice						 BIT,
		@ws_price_showWithDecimals				 INT,
		@ws_price_force2CurrId					 INT,
		@ws_stock_showStock						 INT,
		@ws_stock_showDecimals					 INT,
		@ws_newCustomerAllowed					 BIT,
		@ws_newCustomerCustId					 INT,
		@ws_newCustomerEmailContactName			 NVARCHAR(200),
		@ws_newCustomerEmailContactEMail		 NVARCHAR(200),
		@ws_newCustomerWelcomeText				 NVARCHAR(4000),
		@ws_newCustomerEmailContactPhone		 NVARCHAR(300),
		@ws_analyticsCode						 NVARCHAR(200),
		@page_id								 UNIQUEIDENTIFIER,
		@ws_url4Design							 NVARCHAR(200),
		@page_parameters						 NVARCHAR(500),
		@ws_urlEnd								 NVARCHAR(100),
		@ws_files2TempUpdated					 BIT,
		@ws_files2TempUpdated4Development		 BIT,
		@bra_id									 INT,
		@page_id4HeaderScript					 UNIQUEIDENTIFIER,
		@page_id4FooterScript					 UNIQUEIDENTIFIER,
		@st_id									 INT,
		@dl_id									 INT

)
as

set nocount on

BEGIN

----------------------------------------------------------
----------------------------------------------------------
/*

	Declare		@comp_id								AS INT,
				@ws_id									AS UNIQUEIDENTIFIER,
				@lang_id								AS INT,
				@ws_url									AS NVARCHAR(200),
				@user_id								AS INT,
				@prof_id								AS INT,
				@prli_id								AS INT,
				@stor_id								AS INT,
				@ws_price_showPlusTax					AS BIT,
				@ws_price_showPrice						AS BIT,
				@ws_price_showWithDecimals				AS INT,
				@ws_price_force2CurrId					AS INT,
				@ws_stock_showStock						AS INT,
				@ws_stock_showDecimals					AS INT,
				@ws_newCustomerAllowed					AS BIT,
				@ws_newCustomerCustId					AS INT,
				@ws_newCustomerEmailContactName			AS NVARCHAR(200),
				@ws_newCustomerEmailContactEMail		AS NVARCHAR(200),
				@ws_newCustomerWelcomeText				AS NVARCHAR(4000),
				@ws_newCustomerEmailContactPhone		AS NVARCHAR(300),
				@ws_analyticsCode						AS NVARCHAR(200),
				@page_id								AS UNIQUEIDENTIFIER,
				@ws_url4Design							AS NVARCHAR(200),
				@page_parameters						AS NVARCHAR(500),
				@ws_urlEnd								AS NVARCHAR(100),
				@ws_files2TempUpdated					AS BIT,
				@ws_files2TempUpdated4Development		AS BIT,
				@bra_id									AS INT


	Select		@comp_id							=1,
				@lang_id							=2,
				@bra_id								=1,
				@ws_newCustomerAllowed				=1,
				@ws_newCustomerCustId				=1




*/


----------------------------------------------------------
----------------------------------------------------------



	UPDATE tbWebSiteII_Names
	SET
			comp_id									= @comp_id,
			page_id									= @page_id,
			page_parameters							= @page_parameters,
			ws_urlEnd								= @ws_urlEnd,
			page_id4HeaderScript					= @page_id4HeaderScript,
			page_id4FooterScript					= @page_id4FooterScript

	WHERE	ws_id = @ws_id






END


GO







CREATE Procedure [dbo].[spWebSiteII_Pages_getCombo]


AS
SET NOCOUNT ON

BEGIN
------------------------------------
--Parametros de Prueba
------------------------------------

/*
declare	@ws_id			    INT,
		@comp_id			INT,
		@bra_id				INT

select	@ws_id  = -1,
		@comp_id = 1,
		@bra_id = -1
*/
------------------------------------
------------------------------------

		Select	twsip.page_id	 [Id],
				twsip.page_name [Desc]

		FROM tbWebSiteII_Pages twsip

		Order By twsip.page_name


END
GO





CREATE PROCEDURE [dbo].[spWebSiteII_Pages_getDataById]
(
	@ws_id				UNIQUEIDENTIFIER,
	@wsu_id				INT,
	@page_id			UNIQUEIDENTIFIER,
	@bitIsDevelopment	BIT	,
	@intCustIdLogged	INT,
	@intUserIdLogged	INT,
	@strRequestIP		NVARCHAR(50),
	@strPageSEOName     NVARCHAR(200)
)
AS


BEGIN

-- ----------------------------------------------------------------------------------------------
-- Parametros de Prueba
-- ----------------------------------------------------------------------------------------------
/*

DECLARE 	@page_id			UNIQUEIDENTIFIER

SELECT 		@page_id			= '0352be36-5ca2-4b30-be44-8a2020c78c14'


*/
-- ----------------------------------------------------------------------------------------------

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 1000
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SET @strRequestIP = dbo.fnIPCheck(@strRequestIP)


	-- -----------------------------------------------
	-- Si se busca por NOMBRE de pagina.
	-- Reemplazo  a spWebSiteII_Pages_getDataByName
	IF @strPageSEOName <> ''
		BEGIN
			SET		@page_id = NULL
			SELECT	@page_id = twsip.page_id
				FROM	tbWebSiteII_Pages					twsip		WITH (NOLOCK)
				INNER JOIN tbWebSiteII_Names_Pages_Relation twsinpr		WITH (NOLOCK)
					ON		twsinpr.comp_id = twsip.comp_id AND
							twsinpr.ws_id	= @ws_id		AND
							twsinpr.page_id = twsip.page_id

				WHERE	twsip.page_seoName	= @strPageSEOName   AND
						twsip.page_disabled = 'False'
			--IF @page_id IS NULL
			--	BEGIN
			--		SELECT @page_id = twsip.page_id
			--			FROM	tbWebSiteII_Pages					twsip		WITH (NOLOCK)
			--			WHERE	twsip.page_seoName	= @strPageSEOName   AND
			--					twsip.page_disabled = 'False'
			--	END

		END
	-- -----------------------------------------------


	DECLARE @page_id_alternative AS UNIQUEIDENTIFIER

	-- -----------------------------------------------
	-- 1- Verifica si no hay otra pagina para la IP
	--    desde la que se llamó a la página.
	-- -----------------------------------------------
	SET @page_id_alternative    = NULL
	SELECT TOP 1
				@page_id_alternative = twsipbd.ws_pageAlternative
		FROM	tbWebSiteII_PagesByIP twsipbd				WITH (NOLOCK)
		INNER JOIN tbWebSiteII_IPRanges twsii				WITH (NOLOCK)
			ON	twsii.comp_id	= twsipbd.comp_id AND
				twsii.wsip_id	= twsipbd.wsip_id
		INNER JOIN tbWebSiteII_IPRangesDetail twsiid		WITH (NOLOCK)
			ON	twsiid.comp_id	= twsii.comp_id AND
				twsiid.wsip_id	= twsii.wsip_id
		WHERE	 twsipbd.ws_page	= @page_id				AND
				(
					@strRequestIP >= twsiid.wsipd_fromIP	AND
					@strRequestIP <= twsiid.wsipd_toIP
				)											AND
				twsipbd.wspi_disabled	= 'False'			AND
				twsii.wsip_disabled		= 'False'			AND
				twsiid.wsipd_disabled	= 'False'
	IF @page_id_alternative IS NOT NULL
		BEGIN
			SET @page_id = @page_id_alternative
		END
	-- -----------------------------------------------


	-- -----------------------------------------------
	-- 2- En base a la region, busca una pagina
	--    alternativa por fecha.
	-- -----------------------------------------------
	SET @page_id_alternative    = NULL

	DECLARE @page_idIfNoCustomerLogged AS UNIQUEIDENTIFIER
	SET		@page_idIfNoCustomerLogged  = NULL

	DECLARE @page_idIfNoUserLogged AS UNIQUEIDENTIFIER
	SET		@page_idIfNoUserLogged		= NULL


	SELECT	@page_idIfNoCustomerLogged	= twsip.page_idIfNoCustomerLogged,
			@page_idIfNoUserLogged		= twsip.page_idIfNoUserLogged
		FROM tbWebSiteII_Pages twsip		WITH (NOLOCK)
		WHERE	twsip.page_id		= @page_id	AND
				twsip.page_disabled = 'False'
	IF @page_idIfNoCustomerLogged IS NOT NULL AND @intCustIdLogged < 0
		BEGIN
			SET @page_id = @page_idIfNoCustomerLogged
		END
	IF @page_idIfNoUserLogged IS NOT NULL AND @intUserIdLogged < 0
		BEGIN
			SET @page_id = @page_idIfNoUserLogged
		END


	SELECT @page_id_alternative = twsipbd.ws_pageAlternative
		FROM tbWebSiteII_PagesByDate twsipbd		WITH (NOLOCK)
		WHERE	 twsipbd.ws_page	= @page_id	AND
				(
				 twsipbd.ws_id		= @ws_id
					OR
			     twsipbd.ws_id IS NULL
				)								AND
				(GETDATE() BETWEEN dbo.fnGetEnd_or_BeginOfDate(twsipbd.wspd_fromDate,'False') AND dbo.fnGetEnd_or_BeginOfDate(twsipbd.wspd_toDate,'True')) AND
				twsipbd.wspd_disabled = 'False'

	IF @page_id_alternative IS NOT NULL
		BEGIN
			SET @page_id = @page_id_alternative
		END
	-- -----------------------------------------------




	SELECT	TOP 1
			twsip.comp_id									[comp_id],
			@ws_id											[ws_id],
			IsNull(@wsu_id,-1)								[wsu_id],
			twsip.page_id									[page_id],
			ISNULL(twsip.page_name,'')						[page_name],
			ISNULL(twsip.page_seoName,'')					[page_seoName],
			ISNULL(twsip.page_html,'')						[page_html],
			ISNULL(twsip.page_disabled,'false')				[page_disabled] ,
			ISNULL(twsip.page_urlEnd,'')					[page_urlEnd],
			CASE
				WHEN ISNULL(twsip.page_title,'') <> ''  THEN	ISNULL(twsip.page_title,'')
				ELSE											ISNULL(twsin.ws_page_title,'')
			END												[page_title],
			ISNULL(twsip.page_title_unicode,'')				[page_title_unicode],
			ISNULL(twsip.page_head_mustAppend,'False')		[page_head_mustAppend],
			ISNULL(twsip.page_footer_mustAppend,'False')	[page_footer_mustAppend],
			ISNULL(twsip.page_head,'')						[page_head],
			-- Pasa el HEAD de la URL si lo tiene y sino el de la pagina
			CASE
				WHEN twsinu.wsu_id IS NOT NULL AND
					 twsinu.page_head not LIKE ''						THEN	IsNull(twsinu.page_head,'')	-- Si tiene algo cargado en el NTEXT
				ELSE															ISNULL(twsin.page_head,'')
			END												[page_headWS],
			ISNULL(twsin.page_headReplacedByPage,'False')   [page_headReplacedByPage],

			ISNULL(twsip.page_footer,'')					[page_footer],
			ISNULL(twsin.page_footer,'')					[page_footerWS],
			ISNULL(twsin.page_footerReplacedByPage,'False') [page_footerReplacedByPage],

			ISNULL(twsin.ws_urlEnd,'')						[ws_urlEnd],
			CASE
				WHEN twsinu.wsu_id IS NOT NULL AND
					 twsinu.ws_url IS NOT NULL AND
					 twsinu.ws_url <> ''								THEN	twsinu.ws_url
				ELSE															ISNULL(twsin.ws_url,'')
			END													[ws_url],
			--ISNULL(twsin.ws_url,'')							[ws_url],
			ISNULL(twsin.ws_url4Design,'')					[ws_url4Design],
			ISNULL(twsip.page_backgroundImage,'')			[page_backgroundImage],
			ISNULL(twsin.ws_files2TempUpdated,'False')				[ws_files2TempUpdated],
			ISNULL(twsin.ws_files2TempUpdated4Development,'False')	[ws_files2TempUpdated4Development],
			ISNULL(twsin.prli_id,-1)								[prli_id],
			ISNULL(twsin.stor_id,-1)								[stor_id],
			ISNULL(twsin.bra_id,-1)									[bra_id],
			-- Los HeaderScript y FooterScript los busca: 2-Pagina, 1-URL Adicional, 3-Sitio
			CASE
				WHEN twsinu.page_id4HeaderScript IS NOT NULL THEN twsinu.page_id4HeaderScript
				WHEN twsip.page_id4HeaderScript  IS NOT NULL THEN twsip.page_id4HeaderScript
				WHEN twsin.page_id4HeaderScript  IS NOT NULL THEN twsin.page_id4HeaderScript
				ELSE											  NULL
			END														[page_id4HeaderScript],
			CASE
				WHEN twsinu.page_id4FooterScript IS NOT NULL THEN twsinu.page_id4FooterScript
				WHEN twsip.page_id4FooterScript  IS NOT NULL THEN twsip.page_id4FooterScript
				WHEN twsin.page_id4FooterScript  IS NOT NULL THEN twsin.page_id4FooterScript
				ELSE											  NULL
			END														[page_id4FooterScript],
			ISNULL(twsin.lang_id,-1)								[lang_id],
			ISNULL(twsin.st_id,-1)									[st_id],
			ISNULL(twsin.dl_id,-1)									[dl_id],
			ISNULL(twsin.ws_newCustomerCustId,-1)					[ws_newCustomerCustId],
			ISNULL(twsin.prof_id,-1)								[prof_id],
			ISNULL(twsin.[user_id],-1)								[user_id],
			twsin.ws_newCustomerEmailContactEMail,
			twsin.ws_newCustomerCustId,
			twsin.ws_newCustomerAllowed,
			ISNULL(twsin.ws_newContactEMailDisplayName,'')			[ws_newContactEMailDisplayName],
			ISNULL(twsin.ws_newContactEMailFrom,'')					[ws_newContactEMailFrom],
			twsin.ws_newContactEMailOfManager,
			twsin.ws_newContactEMailSubject,
			twsin.ws_newContactEMailSubject4Manager,
			twsin.ws_newContactEMailBody4Contact,
			twsin.ws_newContactEMailBody4Manager ,
			ISNULL(twsin.page_metaKeywords,'')						[page_metaKeywordsWS],
			ISNULL(twsin.page_metaDescription,'')					[page_metaDescriptionWS],
			ISNULL(twsip.page_metaKeywords,'')						[page_metaKeywords],
			ISNULL(twsip.page_metaDescription,'')					[page_metaDescription],
			ISNULL(twsin.page_metaRevisitDays,'')					[page_metaRevisitDays],
			ISNULL(twsin.ws_TextVariable1,'')						[ws_TextVariable1],
			ISNULL(twsin.ws_TextVariable2,'')						[ws_TextVariable2],
			ISNULL(twsin.ws_TextVariable3,'')						[ws_TextVariable3],
			ISNULL(twsin.ws_TextVariable4,'')						[ws_TextVariable4],
			ISNULL(twsin.ws_TextVariable5,'')						[ws_TextVariable5],
			ISNULL(twsin.ws_TextVariable6,'')						[ws_TextVariable6],
			ISNULL(twsin.ws_TextVariable7,'')						[ws_TextVariable7],
			ISNULL(twsin.ws_TextVariable8,'')						[ws_TextVariable8],
			CASE
				WHEN @bitIsDevelopment = 'True' or twsip.page_analyticsCodeIsDisabled = 'True'
																	THEN ''
				WHEN ISNULL(twsip.page_analyticsCode,'') <> ''		THEN twsip.page_analyticsCode
				WHEN IsNull(twsinu.page_analyticsCode,'') <> ''		THEN twsinu.page_analyticsCode
				ELSE													 ISNULL(twsin.ws_analyticsCode,'')
			END														[ws_analyticsCode],
			ISNULL(twsip.page_analyticsCodeIsDisabled,'False')		[page_analyticsCodeIsDisabled],
			ISNULL(twsip.page_analyticsCodePageName4Track,'')		[page_analyticsCodePageName4Track],
			ISNULL(twsip.ws_bodyOnLoad,'')							[ws_bodyOnLoad],
			twsin.tast_id											[tast_id],
			ISNULL(twsin.task_priority,0)							[task_priority],
			twsin.task_user_id										[task_user_id],
			ISNULL(twsin.task_subject,'')							[task_subject],
			twsin.taskt_id											[taskt_id],
			twsin.task_bra_id										[task_bra_id],
			ISNULL(twsin.ws_taskOnContact,'False')					[ws_taskOnContact],
			/*ISNULL(twsin.ws_disableImageCheck,'False')*/ 'True'	[ws_disableImageCheck],
			ISNULL(twsip.page_enableImageCheck,'False')				[page_enableImageCheck],
			ISNULL(twsip.page_only4DesignMode,'False')				[page_only4DesignMode],
			ISNULL(twsin.ws_faviconName,'')							[ws_faviconName],
			twsin.ws_url											[CanonicalURL],
			ISNULL(twsip.page_exclude4RobotIndex,'False')			[page_exclude4RobotIndex],
			ISNULL(twsip.page_titleScriptAvailable,'False')			[page_titleScriptAvailable],
			ISNULL(twsip.page_titleScript,'')						[page_titleScript],
			IsNull(twsin.sd_id,1)									[sd_id],
			IsNull(twsinu.wsu_is301Redirect,'False')				[wsu_is301Redirect],
			IsNull(twsinu.wsu_disableCanonical,'False')				[wsu_disableCanonical],
			IsNull(twsin.disc_id,-1)								[disc_id],
			IsNull(twsin.wd_designerLogo_enabled,'False')			[wd_designerLogo_enabled],
			IsNull(twsin.wd_designerLogo_link2Page,'')				[wd_designerLogo_link2Page],
			IsNull(twsin.wd_designerLogo_link2Image,'')				[wd_designerLogo_link2Image],
			IsNull(twsin.wd_designerLogo_Tooltip,'')				[wd_designerLogo_Tooltip],
			IsNull(twsin.wd_designerLogo_DesignedBy,'')				[wd_designerLogo_DesignedBy],
			IsNULL(twsin.wd_dataFiscalLogo_enabled,'false')			[wd_dataFiscalLogo_enabled],
			twsin.wd_dataFiscalLogo_link2Page,
			twsin.wd_dataFiscalLogo_link2Image,
			twsin.wd_dataFiscalLogo_Tooltip,
			twsin.wd_dataFiscalLogo_Text,
			ISNULL(twsin.wd_otherLogo_enabled,'False')				[wd_otherLogo_enabled],
			twsin.wd_otherLogo_link2Page,
			twsin.wd_otherLogo_link2Image,
			twsin.wd_otherLogo_Tooltip,
			twsin.wd_otherLogo_Text,
			ISNULL(twsin.prli_idBlocked,'False')					[prli_idBlocked],
			ISNULL(twsip.page_disableMeta,'False')					[page_disableMeta],
			ISNULL(twsin.ws_analytics4OtherCode,'')					[ws_analytics4OtherCode],
			twsin.ws_manage_hidePrices,
			twsin.ws_manage_hidePricesIfNotLogged,
			twsin.ws_manage_showStockSemaphore,
			twsin.ws_manage_showStockQty,
			ISNULL(twsin.ws_usData_phoneNumber,'')			[ws_usData_phoneNumber],
			ISNULL(twsin.ws_usData_eMail,'')				[ws_usData_eMail],
			ISNULL(twsin.ws_usData_serviceTime,'')			[ws_usData_serviceTime],
			ISNULL(twsin.ws_usData_aboutUs,'')				[ws_usData_aboutUs],
			ISNULL(twsin.ws_usData_address,'')				[ws_usData_address],
			ISNULL(twsin.ws_COOptions,0)					[ws_COOptions],
			ISNULL(twsin.ws_style,'')						[ws_style],
			ISNULL(twsin.ws_logo,'')						[ws_logo],
			ISNULL(twsin.user_id4MicroSites,-1)				[user_id4MicroSites],
			ISNULL(twsin.ws_MPClientId,'')					[ws_MPClientId],
			ISNULL(twsin.ws_MPClientSecret,'')				[ws_MPClientSecret],
			ISNULL(twsin.ws_MPNotificationURL,'')			[ws_MPNotificationURL],
			ISNULL(twsin.ws_MPBackURLSuccess,'')			[ws_MPBackURLSuccess],
			ISNULL(twsin.ws_MPBackURLFailure,'')			[ws_MPBackURLFailure],
			ISNULL(twsin.ws_MPBackURLPeding,'')				[ws_MPBackURLPeding],
			ISNULL(twsin.disc_idBlocked,'False')			[disc_idBlocked],
			ISNULL(twsin.st_idBlocked,'False')				[st_idBlocked],
			ISNULL(twsin.ws_microSite_SO4WebSiteCustomerMicroSite,'False')			[ws_microSite_SO4WebSiteCustomerMicroSite],
			isnull(twsin.cust_id4MicroSites,-1)										[cust_id4MicroSites],
			ISNULL(twsin.ws_item_id4OnAccountPayment,-1)							[ws_item_id4OnAccountPayment],
			ISNULL(twsin.curr_id4ForceTotal,-1)										[curr_id4ForceTotal],
			ISNULL(twsin.curr_id,1)													[curr_id],
			ISNULL(twsin.prli_id_4strikeThrough,-1)									[prli_id_4strikeThrough],
			ISNULL(twsip.ws_masterPage_TAG,'')										[ws_masterPage_TAG],
			ISNULL(twsin.ws_masterPage_URLFrom,'')									[ws_masterPage_URLFrom]	,
			ISNULL(twsip.ws_masterPage_CallUpdateFromMasterPagesMethod,'False')		[ws_masterPage_CallUpdateFromMasterPagesMethod]	,
			ISNULL(twsin.dl_idBlocked,'False')										[dl_idBlocked],
			ISNULL(twsin.stor_idBlocked,'False')									[stor_idBlocked]	,
			twsin.ws_imageNoPhoto	,
			ISNULL(twsin.ws_facebookLogin_APPID,'')									[ws_facebookLogin_APPID],
			ISNULL(twsin.ws_googleLogin_ClientID,'')								[ws_googleLogin_ClientID],
			ISNULL(twsin.page_id4MenuCacheExpiresMinutes,10)						[page_id4MenuCacheExpiresMinutes],
			ISNULL(twsip2.page_seoName,'')											[page_seoName4Menu]	,
			ISNULL(twsip.page_freeMenuCache,'False')								[page_freeMenuCache]	,
			ISNULL(twsin.ws_forceHTTPSinProduction,'False')							[ws_forceHTTPSinProduction]	,
			ISNULL(twsin.ws_logEnabled,'')											[ws_logEnabled],
			ISNULL(twsip.page_metaScript,'')										[page_metaScript],
			ISNULL(twsip.page_isAvailable4FileSave,'False')							[page_isAvailable4FileSave],
			ISNULL(twsip.page_fileSaveName,'')										[page_fileSaveName],
			ISNULL(ws_queueEMailSend,'False')										[ws_queueEMailSend],
			ISNULL(twsin.ws_ImageName,'')											[ws_ImageName],
			twsin.ws_metaOGEnabled,
			twsin.ws_metaViewPortEnabled,
			twsin.ws_metaTwitterEnabled,
			ISNULL(twsin.ws_robotsTxt,'')											[ws_robotsTxt]


	FROM tbWebSiteII_Pages twsip							WITH (NOLOCK)

	INNER JOIN tbWebSiteII_Names_Pages_Relation twsinpr		WITH (NOLOCK)
		 ON twsinpr.comp_id = twsip.comp_id AND
			twsinpr.page_id = twsip.page_id

	INNER JOIN tbWebSiteII_Names				twsin		WITH (NOLOCK)
		ON	twsinpr.comp_id	= twsin.comp_id AND
			twsinpr.ws_id	= twsin.ws_id

	LEFT JOIN tbWebSiteII_Names_URLRelated		twsinu		WITH (NOLOCK)
		ON	twsinu.comp_id	= twsin.comp_id AND
			twsinu.wsu_id	= @wsu_id

	LEFT JOIN tbWebSiteII_Pages				 AS twsip2		WITH (NOLOCK)
		ON	twsip2.comp_id = twsin.comp_id AND
			twsip2.page_id = twsin.page_id4Menu



	WHERE
			twsin.ws_id			= @ws_id	AND
			twsip.page_id		= @page_id	AND
			twsip.page_disabled = 'False'	AND
			CASE
				WHEN @bitIsDevelopment = 'False' AND twsinpr.wpr_Only4Development = 'True' THEN 'False'
				ELSE 'True'
			END	= 'true'					AND
			CASE
				WHEN @bitIsDevelopment = 'False' AND twsip.page_only4DesignMode   = 'True' THEN 'False'
				ELSE 'True'
			END	= 'true'


	ORDER BY twsinu.wsu_order



END
GO






