CREATE PROCEDURE [dbo].[spWebSiteII_Pages_getDataByName]
(

	@page_name			NVARCHAR(250)

)
AS




BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	------------------------------------------------------------------------------------------------
	--Parametros de Prueba
	------------------------------------------------------------------------------------------------
	/*
	DECLARE 	@page_name			NVARCHAR(200)
	SELECT 		@page_name			= 'LISTAITEM'
	*/
	------------------------------------------------------------------------------------------------
	------------------------------------------------------------------------------------------------



		SELECT		twsip.comp_id							[comp_id],
					twsip.page_id							[page_id],
					ISNULL(twsip.page_name,'')				[page_name],
					ISNULL(twsip.page_seoName,'')			[page_seoName],
					ISNULL(twsip.page_html,'')				[page_html],
					ISNULL(twsip.page_disabled,'false')		[page_disabled]


		FROM tbWebSiteII_Pages					twsip	 WITH (NOLOCK)


		WHERE	twsip.page_seoName	= @page_name  AND
				twsip.page_disabled = 'False'








END
GO





CREATE PROCEDURE [dbo].[spWebSiteII_Pages_getDataByName2]
(
	@ws_id				UNIQUEIDENTIFIER,
	@wsu_id				INT,
	@page_name			NVARCHAR(300),
	@bitIsDevelopment	BIT	,
	@intCustIdLogged	INT,
	@intUserIdLogged	INT,
	@strRequestIP		NVARCHAR(50),
	@strPageSEOName     NVARCHAR(200)
)
AS


BEGIN

	SET NOCOUNT ON
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	DECLARE @page_id AS UNIQUEIDENTIFIER
	SELECT	@page_id = twsip.page_id
		FROM tbWebSiteII_Names twsin						WITH (NOLOCK)
		INNER JOIN tbWebSiteII_Names_Pages_Relation tws		WITH (NOLOCK)
			ON	tws.comp_id = twsin.comp_id		AND
				tws.ws_id	= twsin.ws_id
		INNER JOIN tbWebSiteII_Pages twsip					WITH (NOLOCK)
			ON	twsip.comp_id = tws.comp_id		AND
				twsip.page_id = tws.page_id
		WHERE	twsin.ws_id			= @ws_id	AND
				twsip.page_seoName	= @page_name


	EXEC spWebSiteII_Pages_getDataById	@ws_id,
										@wsu_id,
										@page_id,
										@bitIsDevelopment,
										@intCustIdLogged,
										@intUserIdLogged,
										@strRequestIP,
										@strPageSEOName



END
GO






