CREATE PROCEDURE [dbo].[spWebSiteII_Pages_insertdata]

(

	@comp_id					INT,
	@page_id					UNIQUEIDENTIFIER,
	@page_name					NVARCHAR(250),
	@page_seoName				NVARCHAR(200),
	@page_html					NTEXT,
	@page_disabled				BIT,
	@page_urlEnd				NVARCHAR(100),
	@page_title					NVARCHAR(500),
	@page_head					NTEXT	,
	@page_footer				NTEXT,
	@page_backgroundImage		NVARCHAR(500),
	@chkOverwriteLocalPages		BIT,
	@page_id4HeaderScript		UNIQUEIDENTIFIER,
	@page_id4FooterScript		UNIQUEIDENTIFIER,

	@ws_bodyOnLoad					NTEXT ,
	@page_idIfNoCustomerLogged		UNIQUEIDENTIFIER,
	@page_idIfNoUserLogged			UNIQUEIDENTIFIER,
	@page_enableImageCheck			BIT,
	@page_pageNote4Designer			NTEXT,
	@page_only4DesignMode			BIT,
	@page_analyticsCodeIsDisabled	BIT,
	@page_includeOnSiteMap			BIT

)

AS


BEGIN



	---------------------------------------------------------------------
	--Parametros de Prueba
	---------------------------------------------------------------------
	/*
	DECLARE @comp_id				INT,
			@page_id				UNIQUEIDENTIFIER,
			@page_name				NVARCHAR(250),
			@page_seoName			NVARCHAR(200),
			@page_html				NVARCHAR,
			@page_disabled			BIT,
			@page_urlEnd			NVARCHAR(100),
			@page_title				NVARCHAR(500),
			@page_head					NVARCHAR,
			@page_footer				NVARCHAR,
			@page_backgroundImage		NVARCHAR(500)


	SELECT	@comp_id					=1,
			@page_id					='2121dsa-asdsa-sad-adsdsaasd-dwewe2e ',
			@page_seoName				='',
			@page_name					='' ,
			@page_disabled				=1
	*/
	---------------------------------------------------------------------

	ALTER TABLE [dbo].[tbWebSiteII_Pages] NOCHECK CONSTRAINT ALL;

	SET NOCOUNT OFF

	IF @page_id4HeaderScript = '00000000-0000-0000-0000-000000000000' SET @page_id4HeaderScript = NULL
	IF @page_id4FooterScript = '00000000-0000-0000-0000-000000000000' SET @page_id4FooterScript = NULL

	IF @page_idIfNoCustomerLogged	= '00000000-0000-0000-0000-000000000000' SET @page_idIfNoCustomerLogged = NULL
	IF @page_idIfNoUserLogged		= '00000000-0000-0000-0000-000000000000' SET @page_idIfNoUserLogged		= NULL



	if	(@comp_id			= -1)	set	@comp_id			= NULL





	IF  NOT EXISTS  (	SELECT TOP 1 1
	               			FROM tbWebSiteII_Pages twsip
               				WHERE	twsip.comp_id = @comp_id AND
               						twsip.page_id = @page_id
					 )
   --     OR
   --     (
   --     	-- Si existe, NO sobreescribe y el NOMBRE de la pagianes diferente a la actual (clono y cambio el texto del nombre de la pagina )
			--EXISTS  (		SELECT TOP 1 1
	  --             				FROM tbWebSiteII_Pages twsip
   --            					WHERE	twsip.comp_id = @comp_id	AND
   --            							twsip.page_id = @page_id
			--		 )
			--AND
			-- NOT EXISTS  (	SELECT TOP 1 1
	  --             				FROM tbWebSiteII_Pages twsip
   --            					WHERE	twsip.comp_id	=	@comp_id	AND
   --            							twsip.page_id	=	@page_id	AND
   --            							twsip.page_name <>	@page_name
			--			 )
   --     	AND
   --     	@chkOverwriteLocalPages = 'false'

   --     )
		BEGIN



			INSERT INTO tbWebSiteII_Pages
			(
				comp_id,
				page_id,
				page_name,
				page_seoName,
				page_html,
				page_disabled,
				page_urlEnd,
				page_title,
				page_head,
				page_footer,
				page_backgroundImage,
				page_id4HeaderScript,
				page_id4FooterScript,

				ws_bodyOnLoad,
				page_idIfNoCustomerLogged,
				page_idIfNoUserLogged,
				page_enableImageCheck,
				page_pageNote4Designer,
				page_only4DesignMode,
				page_analyticsCodeIsDisabled,
				page_includeOnSiteMap
			)
			VALUES
			(
				@comp_id,
				@page_id,
				@page_name,
				@page_seoName,
				@page_html,
				@page_disabled,
				@page_urlEnd,
				@page_title,
				@page_head,
				@page_footer,
				@page_backgroundImage,
				@page_id4HeaderScript,
				@page_id4FooterScript,
				@ws_bodyOnLoad	,
				@page_idIfNoCustomerLogged,
				@page_idIfNoUserLogged			,
				@page_enableImageCheck			,
				@page_pageNote4Designer			,
				@page_only4DesignMode			,
				@page_analyticsCodeIsDisabled	,
				@page_includeOnSiteMap

			)





		END





	else


		IF exists (	SELECT TOP 1 1
						FROM tbWebSiteII_Pages twsip
           				WHERE	twsip.comp_id = @comp_id AND
           						twsip.page_id = @page_id ) and @chkOverwriteLocalPages = 'true'
			BEGIN



				UPDATE tbWebSiteII_Pages
					SET
						comp_id					= @comp_id,
						page_name				= @page_name,
						page_seoName			= @page_seoName,
						page_html				= @page_html,
						page_disabled			= @page_disabled,
						page_urlEnd				= @page_urlEnd,
						page_title				= @page_title,
						page_head				= @page_head,
						page_footer				= @page_footer,
						page_backgroundImage	= @page_backgroundImage,
						page_id4HeaderScript	= @page_id4HeaderScript,
						page_id4FooterScript	= @page_id4FooterScript
					WHERE	comp_id = @comp_id AND
							page_id	= @page_id



			END

	ALTER TABLE [dbo].[tbWebSiteII_Pages] CHECK CONSTRAINT ALL;

END
GO






CREATE PROCEDURE [dbo].[spWebSiteII_Pages_Relation_insertData]
(
	@comp_id					INT,
	@ws_id						UNIQUEIDENTIFIER,
	@page_id					UNIQUEIDENTIFIER,
	@chkOverwriteLocalPages		BIT
)
AS


BEGIN

	SET NOCOUNT ON
	ALTER TABLE [dbo].[tbWebSiteII_Names_Pages_Relation] NOCHECK CONSTRAINT ALL;

	-- -------------------------------------------------------------------------------
	-- Parametros de Prueba
	-- -------------------------------------------------------------------------------
	/*

	DECLARE		@comp_id								INT,
				@ws_id									INT,
				@page_id								INT,
				@chkOverwriteLocalPages					INT

	SELECT		@comp_id								=1,
				@ws_id									=2,
				@page_id								=1,
				@chkOverwriteLocalPages					=1

	*/
	-- -------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------
	if	(@comp_id			= -1)	set	@comp_id				= NULL
	-- ----------------------------------------------------------------------

	if not exists (SELECT TOP 1 1
				   from  tbWebSiteII_Names_Pages_Relation twsf
				   WHERE twsf.ws_id		=  @ws_id		AND
						 twsf.page_id	=  @page_id)
		begin

			INSERT INTO tbWebSiteII_Names_Pages_Relation
			(

				comp_id,
				ws_id,
				page_id

			)
			VALUES
			(
				@comp_id,
				@ws_id,
				@page_id

			)
		END
	ELSE IF exists (SELECT TOP 1 1
					   from  tbWebSiteII_Names_Pages_Relation	twsf
					   WHERE twsf.ws_id				 =  @ws_id		AND
							 twsf.page_id			 =  @page_id)	AND
							 @chkOverwriteLocalPages = 'true'
			BEGIN

				UPDATE tbWebSiteII_Names_Pages_Relation
					SET
						comp_id		= @comp_id,
						ws_id		= @ws_id,
						page_id		= @page_id
					WHERE ws_id		= @ws_id	AND
						  page_id	= @page_id

			END

	ALTER TABLE [dbo].[tbWebSiteII_Names_Pages_Relation] CHECK CONSTRAINT ALL;

END
GO


CREATE PROCEDURE [dbo].[spWebSiteII_Pages_UpdateDataByTag]
(
	@comp_id					INT,
	@ws_id						UNIQUEIDENTIFIER,
	@page_id					UNIQUEIDENTIFIER,
	@strws_masterPage_TAG		NVARCHAR(30),
	@intws_masterPage_Version	INT,
	@page_html					NTEXT,
	@page_head					NTEXT,
	@page_footer				NTEXT,
	@ws_bodyOnLoad				NTEXT
)
AS
	BEGIN
		SET NOCOUNT ON

		-- -------------------------------------------------------
		-- TESTING
		-- -------------------------------------------------------
		/*
			DECLARE
				@comp_id					INT,
				@page_id					UNIQUEIDENTIFIER,
				@strws_masterPage_TAG		NVARCHAR(30),
				@intws_masterPage_Version	INT,
				@page_html					NTEXT,
				@page_head					NTEXT,
				@page_footer				NTEXT,
				@ws_bodyOnLoad				NTEXT
		*/
		-- -------------------------------------------------------


		UPDATE tbWebSiteII_Pages			WITH (ROWLOCK)
			SET
				page_html				= @page_html,
				page_head				= @page_head,
				page_footer				= @page_footer,
				ws_bodyOnLoad			= @ws_bodyOnLoad,
				ws_masterPage_Version	= @intws_masterPage_Version
				FROM 		tbWebSiteII_Pages wsp
			INNER JOIN	tbWebSiteII_Names_Pages_Relation twsinpr		WITH (NOLOCK)
				ON	twsinpr.comp_id = wsp.comp_id	AND
					twsinpr.page_id = wsp.page_id	AND
					twsinpr.ws_id	= @ws_id
			WHERE	wsp.comp_id				= @comp_id	AND
					wsp.ws_masterPage_TAG	= @strws_masterPage_TAG


	END
GO





