-- --------------------------------------------------------------
-- MOS  07-2016
-- Pone campa#a de banner como activa
-- --------------------------------------------------------------

CREATE pROCEDURE [dbo].[spWebSiteII_SpotsCampaignActivation]
AS
-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2011-01-18
-- Parte		: S/P Referencia: #1
-- Description	: Se agrega la eliminación de la temporal de RMA
-- =================================================================================================================
BEGIN

	SET NOCOUNT on

	SELECT		ca.comp_id,
				ca.wsbc_id,
				CA.wsbc_priority,
				ca.ws_id
			INTO #tmpWSCamp
			FROM tbWebSiteII_SpotCampaign CA					WITH (NOLOCK)
			INNER JOIN tbWebSiteII_SpotCampaignRelation re		WITH (NOLOCK)
				ON	re.comp_id = ca.comp_id AND
					re.wsbc_id = ca.wsbc_id
			WHERE	GETDATE() BETWEEN ca.wsbc_fromDate AND ca.wsbc_toDate AND
					ca.wsbc_disabled		= 'False' AND
					re.wsbcr_disabled		= 'False'




		DELETE FROM tmp
			FROM #tmpWSCamp tmp
			INNER JOIN #tmpWSCamp tmp2
				ON  tmp2.ws_id		=	tmp.ws_id	AND
					tmp2.wsbc_id	<>	tmp.wsbc_id
			WHERE	tmp.ws_id = tmp2.ws_id AND
					tmp2.wsbc_priority <= tmp.wsbc_priority



		UPDATE tbWebSiteII_SpotCampaign
			SET wsbc_isActive = 0

		UPDATE tbWebSiteII_SpotCampaign
			SET wsbc_isActive = 'True'
			FROM tbWebSiteII_SpotCampaign tmp					WITH (NOLOCK)
			INNER JOIN #tmpWSCamp tmp2
				ON	tmp2.comp_id = tmp.comp_id AND
					tmp2.wsbc_id = tmp.wsbc_id


		DROP TABLE #tmpWSCamp


END





GO



-- Ejecuta un Código SQL de hasta 8K que recibe como parámetro en @strParamOUT al JSon recibido en la variable @JSonParameters

CREATE  PROCEDURE [dbo].[spWebSiteII_SQLScripts_ExecScripts]
(
	@comp_id			INT,
	@ScriptLabel		VARCHAR(50),
	@JSonParameters		VARCHAR(MAX),
	@strRequestIP		NVARCHAR(50)
)
AS


BEGIN

	-- ----------------------------------------------------------------------------------------------
	-- Test
	-- ----------------------------------------------------------------------------------------------
	/*
	DECLARE 	@page_id			UNIQUEIDENTIFIER
	SELECT 		@page_id			= '0352be36-5ca2-4b30-be44-8a2020c78c14'

	*/
	-- ----------------------------------------------------------------------------------------------

	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 200
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	-- MOS 06-2023: Por seguridad NO se permiten ejecutar SQLScripts con usuario sa
	IF SUSER_NAME() = 'sa' OR SUSER_NAME() = 'SA' OR SUSER_NAME() = 'Sa' OR SUSER_NAME() = 'sA'
		BEGIN
			SELECT 'WARNING: sa user NOT Allowed to execute GlobalBluePoint Scripts.'
			RETURN
		END


	BEGIN TRY



		IF @JSonParameters LIKE '%sp_executesql%'
			BEGIN
				SELECT -5
				RETURN
			END


		-- MOS 02-2022 ( x las dudas que pasen cosas raras en lugar de label.. igual, NO deberia molestar ya que está en un where ...
		SET @ScriptLabel = REPLACE(@ScriptLabel,' ','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'(','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,')','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'"','')
		SET @ScriptLabel = REPLACE(@ScriptLabel,'''','')

		SET @strRequestIP = dbo.fnIPCheck(@strRequestIP)
		DECLARE @bitHasScript		AS BIT = 'False'
		DECLARE @strScript4Execute  AS NVARCHAR(MAX)
		SELECT	@strScript4Execute		= twsis.wssql_scriptSQL ,
				@bitHasScript			= 'True'
			FROM tbWebSiteII_SQLScripts twsis		WITH (NOLOCK)
			WHERE	twsis.comp_id		= @comp_id		AND
					twsis.wssql_label	= @ScriptLabel


		IF @strScript4Execute LIKE '%sp_executesql%'
			BEGIN
				SELECT -6
				RETURN
			END

		IF @bitHasScript = 'True'
			BEGIN

				DECLARE @strMessage		AS NVARCHAR(MAX) = @JSonParameters
				DECLARE @param			AS NVARCHAR(100) = N'@strParamOUT nvarchar(MAX) OUTPUT'

				EXEC sp_executesql @strScript4Execute, @param, @strMessage OUTPUT;
				IF @strMessage <> ''
					BEGIN
						SELECT @strMessage
					END
				ELSE
					BEGIN
						SELECT '-9'
					END
			END
		ELSE
			BEGIN
				SELECT '-3'
			END


	END TRY
	BEGIN CATCH
		SELECT '-4' ,ERROR_MESSAGE()
		RETURN
	END CATCH


END

GO



