CREATE PROCEDURE [dbo].[spWebSiteII_SQLScripts_getDataById]
(
	@comp_id			int,
	@wssql_id			int
)
AS


BEGIN

	set nocount on

	DECLARE @strTimeOut AS NVARCHAR(1000) = ''
	SET @strTimeOut = @strTimeOut + 'SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ' + CHAR(10) + CHAR(13)
	SET @strTimeOut = @strTimeOut + 'SET LOCK_TIMEOUT 250 ' + CHAR(10) + CHAR(13)
	SET @strTimeOut = @strTimeOut + 'SET DEADLOCK_PRIORITY LOW ' + CHAR(10) + CHAR(13)


	SELECT @strTimeOut + REPLACE(REPLACE(ISNULL(tt.wssql_scriptSQL,''),CHAR(13),' '),CHAR(10),' ')			[wssql_scriptSQL],
			tt.wssql_enabled																	[wssql_enabled]
		FROM tbWebSiteII_SQLScripts			tt WITH (NOLOCK)
		WHERE	comp_id = @comp_id AND
				wssql_id = @wssql_id


END
GO




-- =============================================
-- Author:		MOS
-- Create date: 10-2013
-- Description:	<Description,,>
-- =============================================


CREATE PROCEDURE [dbo].[spWebSiteII_SQLScriptsScheduleExecution]
AS

BEGIN


	IF SUSER_NAME() = 'sa' OR SUSER_NAME() = 'SA' OR SUSER_NAME() = 'Sa' OR SUSER_NAME() = 'sA'
		BEGIN
			SELECT 'WARNING: sa user NOT Allowed to execute GlobalBluePoint Scripts.'
			RETURN
		END
	ELSE
		BEGIN
			SELECT 'Executing GlobalBluePoint Scripts'
		END

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	DECLARE @intIndicatorCounterCalculated AS INT
	SET		@intIndicatorCounterCalculated = 0


	SET DATEFIRST 7 -- Dom,ingo x Defecto
	DECLARE @intDOW AS INT
	SET		@intDOW = datepart(dw,getdate())

	-- --------------------------------------------------
	-- Cursor con los Indicadores que se deben calcular
	-- --------------------------------------------------
	DECLARE curSchedule CURSOR LOCAL FAST_FORWARD FOR
	SELECT		tcbs.comp_id,
				tcbs.wssqls_id,
				tcbs.wssql_id,
				tcbs.wssqls_executionMode,
				tcbs.wssqls_executionTime,
				tcbs.wssqls_executionInterval,
				tcbs.wssqls_dayOfMonth,
				tcbs.wssqls_month,
				tcbs.wssqls_limitDate,
				twsiss.wssql_scriptSQL,
				twsiss.wssql_desc
		FROM		tbWebSiteII_SQLScriptsSchedule	tcbs				WITH (NOLOCK)
		INNER JOIN	tbWebSiteII_SQLScripts	AS		twsiss				WITH (NOLOCK)
			ON	tcbs.comp_id	= twsiss.comp_id		AND
				tcbs.wssql_id	= twsiss.wssql_id
		WHERE
				CASE
					WHEN tcbs.wssqls_enabledOnSun	= 'True' AND @intDOW = 1  THEN 'True'
				    WHEN tcbs.wssqls_enabledOnMon	= 'True' AND @intDOW = 2  THEN 'True'
				    WHEN tcbs.wssqls_enabledOnTue	= 'True' AND @intDOW = 3  THEN 'True'
				    WHEN tcbs.wssqls_enabledOnWed	= 'True' AND @intDOW = 4  THEN 'True'
				    WHEN tcbs.wssqls_enabledOnThu	= 'True' AND @intDOW = 5  THEN 'True'
				    WHEN tcbs.wssqls_enabledOnFri	= 'True' AND @intDOW = 6  THEN 'True'
				    WHEN tcbs.wssqls_enabledOnSat	= 'True' AND @intDOW = 7  THEN 'True'
				    ELSE	'False'
				END = 'True'							AND
				tcbs.wssqls_enabled		= 'True'		AND
				twsiss.wssql_enabled	= 'True'		AND
				tcbs.wssqls_limitDate  >= GETDATE()		AND
				CASE
					-- Ejecuta en una Fecha y Hora Determinada
					WHEN tcbs.wssqls_executionMode = 0 AND GETDATE() >= tcbs.wssqls_executionTime AND ISNULL(tcbs.wssqls_lastExecution,DATEADD(YEAR,-10,GETDATE())) < tcbs.wssqls_executionTime		THEN 1
					-- Ejecuta cada N Minutos
					WHEN tcbs.wssqls_executionMode = 1 AND GETDATE() > DATEADD(minute,tcbs.wssqls_executionInterval ,ISNULL(tcbs.wssqls_lastExecution,DATEADD(YEAR,-10,GETDATE())))					THEN 1
					ELSE 0
				END = 1	AND
				(
					tcbs.wssqls_dayOfMonth = 0
						OR
					tcbs.wssqls_dayOfMonth = DATEPART(DAY,GETDATE())
				)	AND
				(
					tcbs.wssqls_month = 0
						OR
					tcbs.wssqls_month = DATEPART(month,GETDATE())
				)



	OPEN curSchedule


	DECLARE @comp_id							AS INT
	DECLARE @wssqls_id							AS INT
	DECLARE @wssql_id							AS INT
	DECLARE @wssqls_executionMode				AS INT
	DECLARE @wssqls_executionTime				AS DATETIME
	DECLARE @wssqls_executionInterval			AS INT
	DECLARE @wssqls_dayOfMonth					AS INT
	DECLARE @wssqls_month						AS INT
	DECLARE @wssqls_limitDate					AS DATETIME
	DECLARE @wssql_desc							   NVARCHAR(250)

	DECLARE @strQuery   AS VARCHAR(MAX)
	DECLARE @datOfBegin	AS DATETIME


	FETCH NEXT FROM curSchedule INTO
									@comp_id,
									@wssqls_id,
									@wssql_id,
									@wssqls_executionMode,
									@wssqls_executionTime,
									@wssqls_executionInterval,
									@wssqls_dayOfMonth,
									@wssqls_month,
									@wssqls_limitDate,
									@strQuery	,
									@wssql_desc

	WHILE @@FETCH_STATUS = 0
		BEGIN

				BEGIN TRY

					-- --------------------------------------------------
					-- Ejecuta el Indicador a Calcular
					-- --------------------------------------------------

					SET @datOfBegin = GETDATE()

					---- Dentro del codigo a ejecutar debo recuperar el Indicador a grabar
					--set @strQuery = (REPLACE (@strQuery,'@intComp_ID'				,convert(varchar,@intComp_Id)))
					--set @strQuery = (REPLACE (@strQuery,'@intCBD_ID'				,convert(varchar,@intCBD_Id)))
					--set @strQuery = (REPLACE (@strQuery,'@intProfile_ID'			,convert(varchar,@intProfileId)))
					--set @strQuery = (REPLACE (@strQuery,'@intUser_ID'				,convert(varchar,@intUserId)))
					--set @strQuery = (REPLACE (@strQuery,'@intBra_ID'				,convert(varchar,@intBraId)))
					--set @strQuery = (REPLACE (@strQuery,'@intBra_ID4ProcessingDate' ,convert(varchar,@intBraId4ProcessingDate)))

					-- --------------------------------------------------
					-- Verifica Instrucciones NO VALIDAS!
					-- --------------------------------------------------
					IF	@strQuery LIKE '%DROP%'			OR
						@strQuery LIKE '%TRUNCATE%'		OR
						@strQuery LIKE '%ALTER%'		OR
						@strQuery LIKE '%CREATE%'		OR
						@strQuery LIKE '%PROCEDURE%'	OR
						@strQuery LIKE '%DBCC%'	OR
						@strQuery LIKE '%FUNCTION%'		OR
						@strQuery LIKE '%EXEC%'			OR
						@strQuery LIKE '%cbdh_LastInserted%'
						BEGIN
							SET @strQuery = 'Select -1'
						END
					-- --------------------------------------------------

					SET @strQuery = 'SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  SET LOCK_TIMEOUT 800; SET DEADLOCK_PRIORITY -6;  ' + @strQuery

					EXEC (@strQuery)

					SET @intIndicatorCounterCalculated = @intIndicatorCounterCalculated + 1
					-- --------------------------------------------------

				-- --------------------------------------------------
				-- Actualiza datos de Ultima Ejecución
				-- --------------------------------------------------
				UPDATE tbWebSiteII_SQLScriptsSchedule
				SET
					wssqls_lastExecution			= GETDATE(),
					wssqls_lastExecutionInMinutes	= DATEDIFF(minute, @datOfBegin , GETDATE()),
					wssqls_ExecutionNote			= 'Scheduled Execution: ' + CONVERT(VARCHAR(100),GETDATE())
					WHERE	comp_id		= @Comp_Id		AND
							wssqls_id	= @wssqls_id
				-- --------------------------------------------------

				SELECT @wssql_desc	[GBPScript],DATEDIFF(minute, @datOfBegin , GETDATE()) [Execution_Minutes]

			END TRY
			BEGIN CATCH
			END CATCH


			FETCH NEXT FROM curSchedule INTO
											@comp_id,
											@wssqls_id,
											@wssql_id,
											@wssqls_executionMode,
											@wssqls_executionTime,
											@wssqls_executionInterval,
											@wssqls_dayOfMonth,
											@wssqls_month,
											@wssqls_limitDate,
											@strQuery,
											@wssql_desc


		END

	CLOSE		curSchedule
	DEALLOCATE	curSchedule

	SELECT @intIndicatorCounterCalculated,' GlobalBluePoint Scripts Executed.'



END
GO





