-- POne el cust ID en todos los registros que tengan solo el cookie y no el cliente asociado
CREATE PROCEDURE [dbo].[spWebSiteII_Tracking_CustomerAssociate]
(
	@comp_id			INT,
	@ws_id				UNIQUEIDENTIFIER,
	@cust_id			INT,
	@hidGuid			UNIQUEIDENTIFIER
)
AS

BEGIN

	SET NOCOUNT ON


	UPDATE tbWebSiteII_SessionTracking
		SET	cust_id = @cust_id
		WHERE	comp_id		= @comp_id	AND
				ws_id		= @ws_id	AND
				wsfl_guid	= @hidGuid	AND
				cust_id		IS NULL



	UPDATE tbWebSiteII_Items_Favorites
		SET		cust_id		= @cust_id
		WHERE	comp_id		= @comp_id AND
				ws_id		= @ws_id AND
				wsif_guid	= @hidGuid AND
				cust_id		IS NULL

	UPDATE tbWebSiteII_DataStorage
		SET		cust_id		= @cust_id
		WHERE	comp_id		= @comp_id AND
				ws_id		= @ws_id AND
				wsfl_guid	= @hidGuid AND
				cust_id		IS NULL


END
GO

