CREATE PROCEDURE [dbo].[spWebSiteItemLeading_getDataByFilters]
(

		@comp_id								Int,
		@item_id								Int,
		@ws_id									Int

)
as
set nocount ON

BEGIN
-----------------------------------------------------------------
/* --poner aqui marca de comentario de comienzo para parametros
-----------------------------------------------------------------

declare		@comp_id								Int,
			@item_id								Int,
			@ws_id									Int


select		@comp_id								= 1,
			@item_id								= -1,
			@ws_id								    = -1

-----------------------------------------------------------------
 */--poner aqui marca de comentario de cierre para parametros
-----------------------------------------------------------------

		SELECT  ' ' [ ], ' ' [ ],
   				ti.item_desc,
				twsn.ws_desc,
				twsil.ddc_Order,
				CONVERT(VARCHAR,twsil.item_id) + ' - ' + CONVERT(VARCHAR,twsil.ws_id) + ' - ' + Convert(Varchar,twsil.ddc_id)  [ID]

		from tbWebSite_ItemLeading				twsil


		Inner Join tbItem						ti
		On  ti.comp_id = twsil.comp_id
		And ti.item_id = twsil.item_id
		--
		--
		inner Join tbWebSite_Names				twsn
		on  twsn.comp_id = twsil.comp_id
		and twsn.ws_id   = twsil.ws_id


		WHERE	twsil.comp_id					        = @comp_id
		And     (@ws_id     = -1 Or twsil.ws_id			= @ws_id)
		AND		(@item_id   = -1 or twsil.item_id       = @item_id)



END
GO








CREATE PROCEDURE [dbo].[spWebSiteItemLeading_getDataById]
(
		@comp_id				Int,
		@item_id				Int,
		@ws_id					Int,
		@ddc_id					int

)
as

set nocount on

BEGIN

-----------------------------------------------------------------
 --poner aqui marca de comentario de comienzo para parametros
-----------------------------------------------------------------
/*

Declare @comp_id				Int,
		@item_id				Int,
		@ws_id					Int,
		@ddc_id					int


Select  @comp_id				= 1,
	    @Item_id			    = 256,
	    @ws_id					= 6,
	    @ddc_id					= 7

*/
-----------------------------------------------------------------
 --poner aqui marca de comentario de cierre para parametros
-----------------------------------------------------------------


		Select twsil.comp_id,
			   twsil.item_id,
			   ti1.item_code,
			   ti1.item_desc,
			   twsil.ddc_Order,
			   twsil.ws_id,
			   twsn.ws_desc



		From tbWebSite_ItemLeading				twsil

		Inner Join tbItem ti1
		On  ti1.comp_id = twsil.comp_id
		And ti1.item_id = twsil.item_id

		left Join tbWebSite_Names				twsn
		on  twsn.comp_id = twsil.comp_id
		and twsn.ws_id   = twsil.ws_id


		Where twsil.comp_id    = @comp_id
		And   twsil.item_id    = @Item_id
		And   twsil.ws_id	   = @ws_id
		And   twsil.ddc_id     = @ddc_id



END
GO








