(
	@ws_id_from				INT,
	@ws_id_to				INT
)
AS

SET NOCOUNT ON




---------------------------------------
-----Parametros de Prueba
---------------------------------------
/*

	DECLARE @ws_id_from		INT,
			@ws_id_to		INT


	SELECT	@ws_id_from		= 24,
			@ws_id_to		= 23

*/
----------------------------------------
----------------------------------------


BEGIN TRANSACTION
BEGIN TRY



BEGIN


	-- WS: Crear SP que haga esto en primer lugar


	DELETE FROM tbWebsite_menu
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_Detail
	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_DetailData
	WHERE	ws_id	= @ws_id_to

