	WHERE	ws_id	= @ws_id_to

	DELETE FROM tbWebSite_SectionParagraphRelationStyles
	WHERE	ws_id	= @ws_id_to




	-- Hasta aca




		-- WS:2
	UPDATE tbWebSite_Names


	SET		bra_id												= twsn.bra_id,
			ws_page_bgcolor_id									= twsn.ws_page_bgcolor_id,
			ws_page_bgimage_url									= twsn.ws_page_bgimage_url,
