CREATE PROCEDURE [dbo].[spWebSiteSectionParagraphRelationHidden_insertData]
(
	@comp_id				INT,
	@wsspr_id				INT,
	@wssprh_action			INT,
	@ws_id					INT,
	@return_value			INT OUTPUT
)
AS
SET NOCOUNT ON

BEGIN



-- -------------------------------------------------------------------------------
-- Parametros de Prueba
-- -------------------------------------------------------------------------------
/*

DECLARE		@comp_id				INT,
			@wsspr_id				INT,
			@wssprh_action			INT,
			@ws_id					INT

SELECT		@comp_id				=1,
			@wsspr_id				=2,
			@wssprh_action			=1,
			@ws_id					=23

*/
-- -------------------------------------------------------------------------------
--
-- -------------------------------------------------------------------------------


	-- ----------------------------------------------------------------------
	-- a los int le seteamos null por si le llega -1
	-- ----------------------------------------------------------------------


	if	(@comp_id			= -1)	set	@comp_id				= NULL
	if	(@wsspr_id			= -1)	set	@wsspr_id				= NULL
	if	(@wssprh_action		= -1)	set	@wssprh_action			= NULL
	if	(@ws_id				= -1)	set	@ws_id					= NULL

	-- ----------------------------------------------------------------------




		INSERT INTO tbWebSite_SectionParagraphRelationHidden
		(
			comp_id,
			wsspr_id,
			-- wssprh_id -- this column value is auto-generated,
			wssprh_action,
			ws_id
		)
		VALUES
		(
			@comp_id,
			@wsspr_id,
			@wssprh_action,
			@ws_id
		)

		SET @return_value = @@IDENTITY


END
GO







CREATE PROCEDURE [dbo].[spWebSiteStyles_updateDataAll]
(
	@comp_id					INT,
	@ws_id						INT,
	@bordercolor_id				INT,
	@borderwidth_id				INT,
	@borderstyle_id				INT,
	@fontcolor_id				INT,
	@fontfamily_id				INT,
	@fontstyle_id				INT,
	@fontdecoration_id			INT,
	@fontweight_id				INT,
	@fontsize_id				INT,
	@backgroundcolor_id			INT
)
AS
SET NOCOUNT ON

BEGIN

----------------------------------------------------------
--Parametros de Prueba
----------------------------------------------------------
/*
DECLARE		@comp_id					INT,
			@ws_id						INT,
			@bordercolor_id				INT,
			@borderwidth_id				INT,
			@borderstyle_id				INT,
			@fontcolor_id				INT,
			@fontfamily_id				INT,
			@fontstyle_id				INT,
			@fontdecoration_id			INT,
			@fontweight_id				INT,
			@fontsize_id				INT,
			@backgroundcolor_id			INT
SELECT 		@comp_id					=1,--
			@ws_id					=2,--
			@bordercolor_id				=-1,--
			@borderwidth_id				=-1,--
			@borderstyle_id				=-1,--
			@fontcolor_id				=-1,--
			@fontfamily_id				=-1,--
			@fontstyle_id				=-1,--
			@fontdecoration_id			=-1,--
			@fontweight_id				=-1,--
			@fontsize_id				=-1,--
			@backgroundcolor_id			=-1--
*/

----------------------------------------------------------
----------------------------------------------------------


		UPDATE	tbWebSite_Styles

		SET		bc_id				= @backgroundcolor_id

		WHERE	comp_id				= @comp_id
		AND		ws_id				= @ws_id
		AND		@backgroundcolor_id	> -1
		AND		NOT bc_id			IS NULL



		UPDATE  tbWebSite_Names

		SET		ws_page_bgcolor_id	= @backgroundcolor_id

		WHERE	comp_id				= @comp_id
		AND		ws_id				= @ws_id
		AND		@backgroundcolor_id	> -1
		AND		NOT ws_page_bgcolor_id IS NULL



		UPDATE  tbWebSite_Names

		SET		ws_bgcolor_id		= @backgroundcolor_id

		WHERE	comp_id				= @comp_id
		AND		ws_id				= @ws_id
		AND		@backgroundcolor_id	> -1
		AND		NOT ws_bgcolor_id	IS NULL












UPDATE	tbWebSite_Styles

SET		bs_id				= @borderstyle_id

WHERE	comp_id				= @comp_id
AND		ws_id				= @ws_id
AND		@borderstyle_id		> -1
AND		NOT bs_id			IS NULL



UPDATE  tbWebSite_Names

SET		ws_borderstyle_id	= @borderstyle_id

WHERE	comp_id				= @comp_id
AND		ws_id				= @ws_id
AND		@borderstyle_id		> -1
AND		NOT ws_borderstyle_id IS NULL









UPDATE	tbWebSite_Styles

SET		bw_id				= @borderwidth_id

WHERE	comp_id				= @comp_id
AND		ws_id				= @ws_id
AND		@borderwidth_id		> -1
AND		NOT bw_id			IS NULL



UPDATE  tbWebSite_Names

