CREATE procedure [dbo].[spWebSiteTranslator_getData]
(
	@lang_id_source		INT,
	@lang_id_destiny	INT,
	@option_text        INT,
	@text				VARCHAR(50) ,
	@cant				INT,
	@chk_pending		INT
)
as
SET NOCOUNT ON


----------------------------------------------------------
--Parametros de Prueba
----------------------------------------------------------

/*

DECLARE
	@lang_id_source		INT,
	@lang_id_destiny	INT,
	@option_text        INT,
	@text				VARCHAR(50),
	@cant				INT,
	@chk_pending		INT

SELECT
	@lang_id_source		=	2,
	@lang_id_destiny	=	1,
	@option_text        =	-1,
	@text				=	'',
	@cant				=	50,
	@chk_pending		=	-1

*/

----------------------------------------------------------
----------------------------------------------------------


DECLARE @splitChar CHAR(1)
SET @splitChar = '.'


BEGIN

	SELECT  Top(@cant)
		    convert(VARCHAR,@lang_id_destiny) + @splitChar +
			convert(varchar,twswn.wswi_id)							[ID],
			isnull(twswn.wswn_desc,'')								[DESC1],
			isnull(twswn2.wswn_desc,'')								[DESC2]

	FROM    tbWebSite_WordsNew						twswn
			left JOIN tbWebSite_WordsNew			twswn2
			ON	twswn2.wswi_id		= twswn.wswi_id
		    AND twswn2.lang_id		= @lang_id_destiny


	WHERE	twswn.lang_id = @lang_id_source
	AND		(
			(@option_text	= -1 ) or
			(@option_text   =  0 and twswn2.wswn_desc like @text + '%') or
			(@option_text   =  1 and twswn2.wswn_desc like '%' + @text + '%') or
			(@option_text   =  2 and twswn2.wswn_desc = @text ) or
			(@option_text   =  3 and twswn2.wswn_desc <> @text) or
			(@option_text   =  4 and twswn2.wswn_desc not like '%' + @text + '%')
			)
	AND		(
			(@chk_pending	= -1) OR
			(@chk_pending	=  0 and (twswn2.wswn_desc  = '' or twswn2.wswn_desc is null)) OR
			(@chk_pending	=  1 and (twswn2.wswn_desc <> ''))
	)

END

GO








CREATE procedure [dbo].[spWebSiteTranslator_Update]
(

	@lang_id		INT,
	@DESC2			NVARCHAR(4000),
	@ID				VARCHAR(100)

)
AS
SET NOCOUNT ON


----------------------------------------------------------
--Parametros de Prueba
----------------------------------------------------------
/*
DECLARE @lang_id			INT,
		@DESC2				varchar(200),
		@ID					VARCHAR(100)




SELECT	@lang_id			=1,
		@DESC2				='All',
		@ID					='1.1'


*/

----------------------------------------------------------
----------------------------------------------------------


DECLARE @id1 INT, @id2 INT, @id3 INT

DECLARE @splitChar CHAR(1)
SET @splitChar = '.'


BEGIN

	SET @id1 = dbo.fnSplitPosition(@ID,@splitChar,2)

	IF NOT EXISTS(SELECT	1
				  FROM		dbo.tbWebSite_WordsNew twswn
				  WHERE		twswn.wswi_id	= @id1
				  AND		twswn.lang_id	= dbo.fnSplitPosition(@ID,@splitChar,1))
	BEGIN
			BEGIN TRANSACTION T1
			BEGIN TRY

				INSERT INTO dbo.tbWebSite_WordsNew
				(
					lang_id,
					wswi_id,
					wswn_desc
				)
				VALUES
				(
					dbo.fnSplitPosition(@ID,@splitChar,1),
					dbo.fnSplitPosition(@ID,@splitChar,2),
					@dESC2
				)

				COMMIT TRANSACTION T1
			END TRY
			BEGIN CATCH
				ROLLBACK TRANSACTION T1
			END CATCH
	END
	ELSE
	BEGIN
			UPDATE	dbo.tbWebSite_WordsNew
			SET 	wswn_desc				= @DESC2
			WHERE	wswi_id					= @id1
			AND		lang_id					= dbo.fnSplitPosition(@ID,@splitChar,1)

	END
END

GO





