		twc.bst_isFinalStatus,
		0														[matchOption],
		twc.bst_chatGPT_hasGeneralQuestion,
		twc.bst_chatGPT_hasGeneralQuestionIntroduction,
		twc.bst_CRM_insertTask_dueDateDays,
		twc.bra_id,
		twc.bst_CRM_insertTask_email_additional,
		twc.bst_CRM_insertTask_priority,
		twc.prof_id,
		twc.sbtse_id,
		ISNULL(twc.bst_requireHumanAnswer,'False')				[bst_requireHumanAnswer],
