END
GO




------------------------------------------------------------------------------------------------------
--Date: 23/08/23
--Author:MOS
--Desc: Este SP basado en el ULTIMO ESTADO busca el proximo estado del BOT que debe ejecutar
------------------------------------------------------------------------------------------------------

CREATE  PROCEDURE [dbo].[spWhatsapp_BOTRules_getDataByIdFROM]
(
		@comp_id				INT ,
		@bst_id					UNIQUEIDENTIFIER,
		@wact_only4Development  BIT,
		@strMessage				VARCHAR(8000),
		@wapn_id				INT,
		@wact_id				INT

)
AS




BEGIN

	SET NOCOUNT ON
	SET DATEFORMAT	'YMD'
	SET DATEFIRST	7	-- Domingo x Defecto





	-- ---------------------------------------------------------------------------------
	-- Test
	-- ---------------------------------------------------------------------------------
	/*
	DECLARE
		@comp_id				INT = 1 ,
		@bst_id					UNIQUEIDENTIFIER = 'C94CA777-C4A5-432B-8A6F-02D82C55B2D2',
		@wact_only4Development  BIT = 'False',
		@strMessage				VARCHAR(8000) = 'Feliz',
		@wapn_id				INT = 12,
		@wact_id				INT	= 32
	*/
	-- ---------------------------------------------------------------------------------



	SET @strMessage = dbo.fnStrAllTrim(@strMessage)

	DECLARE @bst_id_firstRule AS UNIQUEIDENTIFIER = NEWID()
	SELECT	@bst_id_firstRule = twn.bst_id
		FROM tbWhatsapp_Numbers AS twn	WITH (NOLOCK)
		WHERE	twn.comp_id = @comp_id AND
				twn.wapn_id = @wapn_id


	-- Si viene el estado inicial NO SELECCIONABLE, pone en null para que los que en el FROM tienen ese estado sean los que se activen.
	IF @bst_id = @bst_id_firstRule
		BEGIN
			SET @bst_id = NULL
		END

	IF @bst_id IS NOT NULL
		BEGIN
			IF NOT EXISTS	(
								SELECT TOP 1 1
									FROM tbWhatsapp_BOTRules AS twb WITH (NOLOCK)
			               			WHERE	twb.comp_id		= @comp_id AND
				               				twb.bst_idFrom	= @bst_id
								)
				BEGIN
					SET @bst_id = NULL
				END
		END




	DECLARE @cust_id AS INT = NULL
	SELECT	@cust_id = twc.cust_id
		FROM tbWhatsapp_Contacts AS twc WITH (NOLOCK)
		WHERE	twc.comp_id = @comp_id	AND
				twc.wact_id = @wact_id



	-- ATENCIÓN!!!!
	-- Los SP  spWhatsapp_BOTRules_getDataById y spWhatsapp_BOTRules_getDataByIdFROM DEBEN TENER LOS MISMOS CAMPOS !!!!!!!


	SELECT	 TOP 1
		twc.comp_id,
		twc.bst_id,
		twc.bst_desc,
		twc.bst_only4Development,
		twc.ck_id,
		twc.bst_idFrom,
		twc.bst_exactMatch,
		twc.bst_partialMatch,
		twc.bst_noMatch_default,
		twc.bst_botMessage,
		twc.bst_chatGPT_questionWithLastInput,
		twc.bst_chatGPT_questionIntroduction,
		twc.bst_chatGPT_ifAnswerContains,
		twc.bst_chatGPT_ifAnswerContains_bst_id,
		twc.bst_chatGPT_ifAnswerContains2,
		twc.bst_chatGPT_ifAnswerContains2_bst_id,
		twc.bst_chatGPT_ifAnswerContains3,
		twc.bst_chatGPT_ifAnswerContains3_bst_id,
		twc.bst_chatGPT_ifAnswerContains4,
		twc.bst_chatGPT_ifAnswerContains4_bst_id,
		twc.bst_chatGPT_ifAnswerNotContains_bst_id,
		twc.bst_CRM_insertNewTask,
		twc.taskt_id,
		twc.tast_id,
		twc.bst_CRM_insertTask_Subject,
		twc.bst_CRM_insertTask_Desc,
		twc.task_emailAdditional,
		twc.[user_id],
		twc.bsl_executeScript,
		ISNULL(twc.wssql_label,'')									[wssql_label],
		twc.bsl_eMailResponse,
		twc.bsl_eMailFrom,
		twc.bsl_eMailTo,
		twc.bsl_eMailSubject,
		twc.bst_priority,
		twc.bst_isFinalStatus,
		CASE	-- ATENCION: NO CAMBIAR los valores retornados ya que los usa: wfmWhatsapp_webhook
			WHEN twc.bst_id = @bst_id_firstRule															THEN 0	-- Si es la Regla x Defecto, retorna 0
			WHEN twc.bst_exactMatch		<> '' AND twc.bst_exactMatch		    = @strMessage			THEN 1	-- Si hizo Match exacto como dependencia del estado ANTERIOR,	retorna 1
			WHEN twc.bst_partialMatch	<> '' AND twc.bst_partialMatch LIKE '%' + @strMessage + '%'		THEN 3	-- Si hizo Match PARCIAL como dependencia del estado ANTERIOR,	retorna 3
			WHEN twc.bst_noMatch_default = 'True'														THEN 5	-- Si NO hizo Match como dependencia del estado ANTERIOR,		retorna 5
			ELSE																							 9
		END																[matchOption],
		twc.bst_chatGPT_hasGeneralQuestion,
		twc.bst_chatGPT_hasGeneralQuestionIntroduction,
		twc.bst_CRM_insertTask_dueDateDays,
		twc.bra_id,
		twc.bst_CRM_insertTask_email_additional,
		twc.bst_CRM_insertTask_priority,
		twc.prof_id,
		twc.sbtse_id,
		ISNULL(twc.bst_requireHumanAnswer,'False')				[bst_requireHumanAnswer],
		ISNULL(twc.bst_FinalMessage,'')							[bst_FinalMessage]
		FROM tbWhatsapp_BOTRules 			twc			WITH (NOLOCK)
		INNER JOIN tbWhatsapp_Contacts   AS twco		WITH (NOLOCK)
			ON	twco.comp_id			= @comp_id	AND
				twco.wact_id			= @wact_id
		WHERE	twc.comp_id				= @comp_id	AND
				CASE	-- MOS 11-2023: Para que el menu principal pueda ser x fechas, clientes relacionados o no, etc.
					WHEN twc.bst_idFrom		= @bst_id									THEN 1
					WHEN twc.bst_idFrom2	= @bst_id AND twc.bst_idFrom2 IS NOT NULL	THEN 1
					WHEN twc.bst_idFrom3	= @bst_id AND twc.bst_idFrom3 IS NOT NULL	THEN 1
					WHEN twc.bst_idFrom4	= @bst_id AND twc.bst_idFrom4 IS NOT NULL	THEN 1
					WHEN twc.bst_idFrom5	= @bst_id AND twc.bst_idFrom5 IS NOT NULL	THEN 1
					WHEN twc.bst_idFromAll	= 'True'									THEN 1
					WHEN @bst_id IS NULL AND twc.bst_idFrom	= @bst_id_firstRule			THEN 1
					ELSE																	 0
				END				= 1					AND

				--(
				--	twc.bst_idFrom		= @bst_id
				--	OR
				--	(
				--		@bst_id IS NULL
				--		AND
				--		twc.bst_idFrom	= @bst_id_firstRule
				--	)	-- MOS 11-2023: Para que el menu principal pueda ser x fechas, clientes relacionados o no, etc.
				--)									AND
				(
					(twc.bst_exactMatch		<> ''	AND twc.bst_exactMatch		    = @strMessage)
						OR
					(twc.bst_partialMatch	<> ''	AND twc.bst_partialMatch LIKE '%' + @strMessage + '%')
						OR
					 twc.bst_noMatch_default = 'True'
				)									AND
				(
					twc.bst_only4Development = 'False'
					OR
					twc.bst_only4Development = @wact_only4Development
				)									AND
				CASE
					WHEN twc.sbtse_id = 1						   THEN 1	-- Sin filtro de ejecución
					WHEN twc.sbtse_id = 2 AND @cust_id IS NOT NULL THEN 1	-- Ejecutar únicamente si el contacto TIENE un Cliente Relacionado
					WHEN twc.sbtse_id = 3 AND @cust_id IS     NULL THEN 1	-- Ejecutar únicamente si el contacto NO TIENE un Cliente Relacionado
					ELSE												0
				END	= 1								AND
				CASE
					WHEN twc.bst_hasDayOfWeekFilter = 'False'												THEN 1
					WHEN twc.bst_sunday				= 'True' AND DATEPART(weekday,GETDATE()) = 1			THEN 1
					WHEN twc.bst_monday				= 'True' AND DATEPART(weekday,GETDATE()) = 2			THEN 1
					WHEN twc.bst_tuesday			= 'True' AND DATEPART(weekday,GETDATE()) = 3			THEN 1
					WHEN twc.bst_wednesday			= 'True' AND DATEPART(weekday,GETDATE()) = 4			THEN 1
					WHEN twc.bst_thursday			= 'True' AND DATEPART(weekday,GETDATE()) = 5			THEN 1
					WHEN twc.bst_friday				= 'True' AND DATEPART(weekday,GETDATE()) = 6			THEN 1
					WHEN twc.bst_saturday			= 'True' AND DATEPART(weekday,GETDATE()) = 7			THEN 1
					ELSE																						 0
				END				= 1					AND
				CASE
					WHEN twc.bst_hasDayOfMonthFilter	= 'False'											THEN 1
					WHEN twc.bst_DayOfMonthFilter		= DATEPART(DAY,GETDATE())							THEN 1
					ELSE																						 0
				END				= 1					AND
				CASE
					WHEN twc.bst_hasMonthFilter			= 'False'											THEN 1
					WHEN twc.bst_MonthFilter			= DATEPART(MONTH,GETDATE())							THEN 1
					ELSE																						 0
				END				= 1					AND
				CASE
					WHEN twc.waca1_id IS NULL																THEN 1
					WHEN twc.waca1_id = twco.waca1_id														THEN 1
					ELSE																					     0
				END				= 1					AND
				CASE
					WHEN twc.waca2_id IS NULL																THEN 1
					WHEN twc.waca2_id = twco.waca2_id														THEN 1
					ELSE																					     0
				END				= 1					AND
				CASE
					WHEN twc.waca3_id IS NULL																THEN 1
					WHEN twc.waca3_id = twco.waca3_id														THEN 1
					ELSE																					     0
				END				= 1					AND
				CASE
					WHEN twc.waca4_id IS NULL																THEN 1
					WHEN twc.waca4_id = twco.waca4_id														THEN 1
					ELSE																					     0
				END				= 1
		ORDER BY
			CASE
				WHEN twc.bst_idFromAll		= 'True'														THEN 9999 -- en ULTIMO lugar
				WHEN twc.bst_exactMatch		<> '' AND twc.bst_exactMatch		    = @strMessage			THEN 1
				WHEN twc.bst_partialMatch	<> '' AND twc.bst_partialMatch LIKE '%' + @strMessage + '%'		THEN 3
				WHEN twc.bst_noMatch_default = 'True'														THEN 5
				ELSE																							 9
			END

END


	/*
		DATEPART (RESULTADOS)
		-----------------------
		LUNES		= 2
		MARTES		= 3
		MIERCOLES	= 4
		JUEVEs		= 5
		VIERNES		= 6
		SABADO		= 7
		DOMINGO		= 1
		-----------------------
	*/
GO

