CREATE PROCEDURE [dbo].[spWhatsapp_Chats_getIsPending4Envie]
(
	@comp_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT = 1
		*/
		-- -----------------------------------------


	DECLARE @tmpTable TABLE(wach_id INT PRIMARY KEY)


	INSERT INTO @tmpTable(wach_id)
		SELECT		twc.wach_id
			FROM	tbWhatsapp_Chats AS twc	WITH (NOLOCK,INDEX(IX_tbWhatsapp_Chats_Pending4Envie))
			WHERE	twc.wach_isPending4Envie	= 'True'

	UPDATE tbWhatsapp_Chats
		SET wach_isPending4Envie = 0
		FROM tbWhatsapp_Chats	AS tct		WITH (NOLOCK)
		INNER JOIN @tmpTable	AS tt
			ON	tct.wach_id = tt.wach_id



	SELECT	tct.comp_id,
			tct.wach_id,
			tct.wapn_id,
			tct.wact_id,
			tct.wach_cd,
	      	tct.wach_isReception,
	      	tct.wach_isPending4Envie,
	      	tct.wach_isPending4Read,
	      	tct.wach_type,
	      	tct.cust_id,
	      	tct.wach_text,
	      	tct.task_id,
	      	tct.[user_id],
	      	ISNULL(tct.wate_id,-1)					[wate_id],
	      	ISNULL(twc.wact_contactNumber,'')		[wact_contactNumber],
	      	ISNULL(tc.cust_whatsapp,'')				[cust_whatsapp],
	      	ISNULL(twt.wate_template,'')			[wate_template],
	      	ISNULL(twt.wate_type,0)					[wate_type],
	      	ISNULL(twt.wate_LangCode,'')			[wate_LangCode],
	      	twn.wapn_number,
	      	twn.wapn_numberID,
	      	twn.wapn_TOKEN,
	      	ISNULL(tct.wach_fileNameAttach,'')		[wach_fileNameAttach]
		FROM tbWhatsapp_Chats			AS tct		WITH (NOLOCK)
		INNER JOIN @tmpTable			AS tt
			ON	tct.wach_id		= tt.wach_id
		INNER JOIN tbWhatsapp_Numbers	AS twn		WITH (NOLOCK)
			ON	twn.comp_id		= tct.comp_id	AND
				twn.wapn_id		= tct.wapn_id
		LEFT  JOIN tbWhatsapp_Contacts	AS twc		WITH (NOLOCK)
			ON	twc.comp_id		= tct.comp_id	AND
				twc.wact_id		= tct.wact_id
		LEFT  JOIN tbCustomer			AS tc		WITH (NOLOCK)
			ON	tc.comp_id		= tct.comp_id	AND
				tc.cust_id		= tct.cust_id
		LEFT JOIN tbWhatsapp_Templates  AS twt		WITH (NOLOCK)
			ON	twt.comp_id		= tct.comp_id	AND
				twt.wate_id		= tct.wate_id
		ORDER BY	tct.comp_id,
					tct.wach_id






	END
GO

CREATE PROCEDURE [dbo].[spWhatsapp_Chats_getLastChatOfContact]
(
		@comp_id				INT,
		@wapn_id				INT,
		@wact_id				INT

)

AS

BEGIN


	SET NOCOUNT ON

	-- ---------------------------------------------
	-- TESTING
	-- ---------------------------------------------
	/*
		DECLARE
			@comp_id				INT = 1,
			@wapn_id				INT = 1,
			@wact_id				INT = 1
	*/
	-- ---------------------------------------------


	SELECT	TOP 1
			twc.comp_id,
			twc.wapn_id,
			twc.wach_id,
			twc.wach_cd,
			twc.wach_isReception,
			twc.wach_isPending4Envie,
			twc.wach_isPending4Read,
			twc.wach_text,
			twc.wach_type,
			twc.cust_id,
			twc.task_id,
			twc.[user_id],
			twc.wact_id
		FROM tbWhatsapp_Chats AS twc	WITH (NOLOCK)
		WHERE	twc.comp_id = @comp_id AND
				twc.wapn_id = @wapn_id AND
				twc.wact_id = @wact_id
		ORDER BY twc.wach_id DESC



END
GO

