		@wach_text				VARCHAR(8000),
		@cust_id				INT,
		@task_id				INT,
		@user_id				INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------
		-- TESTING
		-- ---------------------------------------------
		/*
			DECLARE
				@comp_id				INT,
				@wapn_id				INT,
				@wach_isReception		BIT,
				@wach_isPending4Envie	BIT,
