		-- ---------------------------------------------



		IF @cust_id = -1 SET @cust_id = NULL
		IF @task_id = -1 SET @task_id = NULL
		IF @user_id = -1 SET @user_id = NULL





		-- ---------------------------------------------
		-- EL SP PROPIAMENTE DICHO
		-- ---------------------------------------------

			INSERT INTO tbWhatsapp_Chats
			(
				comp_id,
				wapn_id,
