			(
				@comp_id,
				@wapn_id,
				@wact_id,
				@wach_isReception,
				@wach_isPending4Envie,
				@wach_isPending4Read,
				@wach_type,
				@wach_text,
				@cust_id,
				@task_id,
				@user_id
			)

		-- ---------------------------------------------

	END
