--Desc: InsertData de Whatsapp_Contacts
------------------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[spWhatsapp_Contacts_InsertData]
(
		@comp_id					INT,
		@wact_contactName			VARCHAR(250),
		@wact_contactNumber			CHAR(16),
		@wapn_id					INT
)
AS
BEGIN

	SET NOCOUNT ON
	-- ---------------------------------------------
	-- TESTING
	-- ---------------------------------------------
	/*
		DECLARE

		SELECT
			ACA VAN LOS PARAMETROS DEL SP CON ASIGNACION DE VALORES
			@comp_id	= 1
	*/
	-- ---------------------------------------------

	DECLARE @wapn_try2RelateCustomer AS BIT = 'False'
	SELECT	@wapn_try2RelateCustomer = ISNULL(twn.wapn_try2RelateCustomer,'False')
		FROM tbWhatsapp_Numbers AS twn	WITH (NOLOCK)
		WHERE	twn.comp_id = @comp_id AND
				twn.wapn_id = @wapn_id


	DECLARE @cust_id AS INT = NULL
	IF @wapn_try2RelateCustomer = 'True'
		BEGIN
			SELECT TOP 1 @cust_id = tc.cust_id
				FROM tbcustomer tc WITH (NOLOCK)
				WHERE	tc.comp_id = @comp_id AND
						tc.cust_whatsapp LIKE '%'  +  dbo.fnStrAllTrim(@wact_contactNumber) +  '%'
				ORDER BY tc.cust_id DESC
		END


	INSERT INTO tbWhatsapp_Contacts
	(
		comp_id,
		wact_contactName,
		wact_contactNumber,
		bst_id,
		cust_id
	)
	VALUES
	(
		@comp_id,
		@wact_contactName,
		@wact_contactNumber,
		NULL,
		@cust_id
	)


END
GO

CREATE PROCEDURE [dbo].[spWhatsapp_Contacts_UpdateBSTID]
(
	@comp_id	INT,
	@wact_id	INT,
	@bst_id		UNIQUEIDENTIFIER,
	@bitClearBST BIT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- -----------------------------------------
		-- TESTING
		-- -----------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@wact_id	INT,
				@bst_id		UNIQUEIDENTIFIER
			SELECT
				@comp_id	= 1,
				@wact_id	= 1,
				@bst_id		= ''
		*/
		-- -----------------------------------------


		IF @bitClearBST = 'False'
			BEGIN
				UPDATE tbWhatsapp_Contacts
					SET
						bst_id		= @bst_id
					WHERE	comp_id = @comp_id AND
							wact_id = @wact_id
			END
		ELSE
			BEGIN
				UPDATE tbWhatsapp_Contacts
					SET
						bst_id		= NULL
					WHERE	comp_id = @comp_id AND
							wact_id = @wact_id
			END


	END



GO




