CREATE PROCEDURE [dbo].[spWhatsapp_GetContactChats4Grid]
(
	@comp_id	INT,
	@wact_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@wact_id	INT
			SELECT
				@comp_id	= 1,
				@wact_id	= 31
		*/
		-- ---------------------------------------------------------------

		SELECT
			twc.wach_type,
			twc.wach_cd,
			twc.wach_text,
			CASE twc.wach_type
				WHEN 1							THEN twc2.wact_contactName
				ELSE								 twn.wapn_desc
			END								[WhoSentIt],
			CASE twc.wach_type
				WHEN 1							THEN 'Respuesta'
				ELSE								 'Mensaje'
			END								[Type],
			ISNULL(	tu.user_lastname + ',' +
					tu.user_firstname,'')	[UserName]	,
			twc.wach_id						[ID]

			FROM tbWhatsapp_Chats				AS twc	WITH(NOLOCK)
			INNER JOIN tbWhatsapp_Numbers		AS twn	WITH(NOLOCK)
				ON	twn.comp_id		= twc.comp_id	AND
					twn.wapn_id		= twc.wapn_id
			INNER JOIN tbWhatsapp_Contacts		AS twc2	WITH(NOLOCK)
				ON	twc2.comp_id	= twc.comp_id	AND
					twc2.wact_id	= twc.wact_id
			LEFT JOIN tbUser					AS tu	WITH(NOLOCK)
				ON	tu.[user_id]	= twc.[user_id]
			WHERE	twc.comp_id = @comp_id		AND
					twc.wact_id = @wact_id
			ORDER BY twc.wach_id DESC

	END
GO

CREATE PROCEDURE [dbo].[spWhatsapp_GetContactInfoByWachID]
(
	@comp_id	INT,
	@wach_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@wach_id	INT
			SELECT
				@comp_id	= 1,
				@wach_id	= 1
		*/
		-- ---------------------------------------------------------------

		DECLARE
			@lwact_id		INT,
			@lwapn_id		INT,
			@lwapn_TOKEN	VARCHAR(300),
			@lwapn_numberID VARCHAR(100)

		-- RECUPERO LOS DATOS DEL CONTACTO
		SELECT
			@lwact_id = twc.wact_id,
			@lwapn_id = twc.wapn_id
			FROM tbWhatsapp_Chats			AS twc	WITH(NOLOCK)
			WHERE	twc.comp_id = @comp_id	AND
					twc.wach_id = @wach_id

		SELECT
			@lwapn_TOKEN	= twn.wapn_TOKEN,
			@lwapn_numberID = twn.wapn_numberID
			FROM tbWhatsapp_Numbers			AS twn	WITH(NOLOCK)
			WHERE	twn.comp_id = @comp_id	AND
					twn.wapn_id = @lwapn_id

		SELECT
			twc.wact_id,
			@lwapn_TOKEN					[wapn_TOKEN],
			@lwapn_numberID					[wapn_numberID],
			twc.wact_contactName,
			twc.wact_contactNumber,
			ISNULL(twc.cust_id,-1)			[cust_id],
			@lwapn_id						[wapn_id]
			FROM tbWhatsapp_Contacts		AS twc WITH(NOLOCK)
			WHERE	twc.comp_id = @comp_id	AND
					twc.wact_id = @lwact_id

	END


GO

CREATE PROCEDURE [dbo].[spWhatsapp_GetContactLastTenMessages]
(
	@comp_id	INT,
	@wact_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ---------------------------------------------------------------
		-- TESTING
		-- ---------------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@wact_id	INT
			SELECT
				@comp_id	= 1,
				@wact_id	= 1
		*/
		-- ---------------------------------------------------------------

		SELECT
			TOP 50
				twc.wach_type,
				CASE twc.wach_type	WHEN 1 THEN 'Respuesta'
				ELSE							'Mensaje'
				END								[Type],
				twc.wach_text
			FROM tbWhatsapp_Chats AS twc	WITH(NOLOCK)
			WHERE	twc.comp_id = @comp_id	AND
					twc.wact_id = @wact_id
			ORDER BY twc.wach_id DESC

	END
GO

CREATE PROCEDURE spWhatsapp_Numbers_getCombo
(
	@comp_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ----------------------------------------
		-- TESTING
		-- ----------------------------------------
		/*
			DECLARE
				@comp_id	INT
			SELECT
				@comp_id	= 1
		*/
		-- ----------------------------------------

