CREATE procedure [dbo].[spWMS_StoragePositions_Labels_getReport]
(
		@comp_id			INT,
		@lang_id			INT,
		@page_id			INT,
		@storp_nick			VARCHAR(50),
		@bra_id				INT,
		@intBranch4Lang		INT
)
as


BEGIN



	SET NOCOUNT ON
	SET DATEFORMAT 'ymd'

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	------------------------------------------------------------------------------
	-- Parametros de Prueba
	------------------------------------------------------------------------------
	/*
	DEcLARE 		@comp_id			INT,
					@lang_id			INT,
					@page_id			INT



	SELECT			@comp_id			=1,
					@lang_id			=2,
					@page_id			=100951,

					@option				=-1

	drop table #tmpLabels
	*/
	------------------------------------------------------------------------------

				SELECT
					ISNULL(tsp.storp_nick,'')				[storp_nick],
					ISNULL(tsp.storp_desc,'')				[storp_desc],
					ISNULL(tsp.storp_note,'')				[storp_note],
					tsp.storp_id							[ID]

				FROM tbStoragePositions						tsp			WITH (NOLOCK)

				WHERE	tsp.comp_id		=   @comp_id			AND
						tsp.storp_nick like @storp_nick + '%'	AND
						tsp.storp_disabled = 0

				exec [spReports_getData3] @comp_id,@intBranch4Lang ,@lang_id, @page_id

				----/* devolución de parámetros recibidos */
				DECLARE @related_page_id INT
				SELECT
					@related_page_id = related_page_id
					FROM tbsysPages								tp
					WHERE tp.page_id = @page_id

				SELECT (SELECT
							tswn.word_desc
							FROM [tbsysTextsNew]		t
							INNER JOIN tbSysWordsNew tswn
							ON	tswn.lang_id	= @lang_id		AND
								tswn.wordsi_id	= t.wordsi_id
      						WHERE
      							t.ctrl_id = 57					and
      							t.[page_id] = @related_page_id	and
      							t.[type_id]	= 1)				[params1]




END
GO



-- MOS   07-2010
-- Se agrego que retorne registros del tipo 2 ademas del tipo 1 que sn autorizaciones.-
-- NO se usan mas los campos del tipo 2
-- se agrego la tabla tbWorkFlow

CREATE PROCEDURE [dbo].[spWorkFlow_getData]
(
	@comp_id			INT,
	@lang_id			INT,
	@prof_id			INT,
	@bra_id				INT,
	@user_id			INT
)
AS

BEGIN

	SET NOCOUNT ON

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	-- -------------------------------------------------------------------------------
	-- Testing
	-- -------------------------------------------------------------------------------
	/*
	DECLARE @comp_id			INT,
			@lang_id			INT,
			@prof_id			INT,
			@bra_id				INT,
			@user_id			INT

	SELECT  @comp_id			= 1,
			@lang_id			= 2,
			@prof_id			= 1,
			@bra_id				= 1,
			@user_id			= 1
	*/
	-- -------------------------------------------------------------------------------


	DECLARE @user_authorization4AllBranchs		BIT,
			@user_authorizationBlock4All		BIT,
			@user_whatsAppReplyEnabled			BIT

	SELECT	@user_authorization4AllBranchs	= ISNULL(tu.user_authorization4AllBranchs,'False'),
			@user_authorizationBlock4All	= IsNull(tu.user_authorizationBlock4All,'False'),
			@user_whatsAppReplyEnabled		= ISNULL(tu.user_whatsAppReplyEnabled,'False')
		FROM	tbUser tu		WITH (NOLOCK)
		WHERE	tu.[user_id] = @user_id


	-- -----------------------------------------------------------------------------------
	-- Pone toodos los Usuarios que esten relacionados con Vendedores de ese Grupo de Vendedores
	-- -----------------------------------------------------------------------------------
	DECLARE @tblUsersForAuthorize TABLE (USER_ID INT PRIMARY KEY CLUSTERED)
	INSERT INTO @tblUsersForAuthorize
		SELECT DISTINCT tusr.[user_id]
			FROM tbUserAuthorizationRelation tuar		WITH (NOLOCK)
--			INNER JOIN tbUser tu
--				on	tu.[user_id]	= tuar.[user_id]
			INNER JOIN tbSalesmanGroup4Salesman  tsg	WITH (NOLOCK)
				ON	tsg.comp_id		= tuar.comp_id		AND
					tsg.sg_id		= tuar.sg_id
			INNER JOIN tbUserSalesmanRelation  tusr		WITH (NOLOCK)
				ON	tusr.comp_id	= tsg.comp_id		AND
					tusr.sm_id		= tsg.sm_id			AND
					tusr.bra_id     = tuar.bra_id4UserSmRelation

			WHERE	tuar.comp_id		= @comp_id			AND
					tuar.[user_id]		= @user_id			AND
					tuar.sg_id			IS NOT NULL			and
					NOT EXISTS(
								SELECT TOP 1  1
									FROM @tblUsersForAuthorize tmp
									WHERE tmp.[USER_ID] = tusr.[user_id]
							)
	-- -----------------------------------------------------------------------------------



	-- -----------------------------------------------------------------------------------
	-- Pone en una temporal TODAS las sucursales de las que tiene permiso para autorizar
	-- -----------------------------------------------------------------------------------
	DECLARE @tblBranchsWithPermission TABLE(bra_id INT PRIMARY KEY CLUSTERED)

	IF 	@user_authorizationBlock4All = 'False'
		BEGIN
			INSERT INTO @tblBranchsWithPermission (bra_id) VALUES (@bra_id)
		END

	IF @user_authorization4AllBranchs = 'True' AND @user_authorizationBlock4All = 'False'
		BEGIN
			--CUSTOM_GN_001
			INSERT INTO @tblBranchsWithPermission  (bra_id)
				SELECT DISTINCT tuar.bra_id
					FROM tbBranch tuar		WITH (NOLOCK)
					WHERE 	tuar.comp_id	= @comp_id		AND
							IsNull(tuar.bra_disabled,0) = 0	AND
							NOT EXISTS(	SELECT TOP 1 	1
                 							FROM  @tblBranchsWithPermission tmp1
	                   						WHERE tmp1.bra_id = tuar.bra_id
										)
			--CUSTOM_GN_002

		END


	-- Si esta el perfil o el usuario definido en la tabla inserta las sucursales en esa tabla como validas para autorizar
	INSERT INTO @tblBranchsWithPermission (bra_id)
		SELECT DISTINCT tbgd.bra_id
			FROM tbUser_authorizationsByBranchGroup tt		WITH (NOLOCK)
			INNER JOIN tbBranchGroupDetail			tbgd	WITH (NOLOCK)
				ON	tbgd.comp_id	= tt.comp_id	AND
					tbgd.brag_id	= tt.brag_id
			WHERE	tt.comp_id = @comp_id AND
					(
						tt.[user_id]= @user_id
							OR
						tt.prof_id	= @prof_id
					)	AND
					NOT EXISTS(	SELECT TOP 1 	1
         							FROM  @tblBranchsWithPermission tmp1
               						WHERE tmp1.bra_id = tbgd.bra_id
							   )





	INSERT INTO @tblBranchsWithPermission  (bra_id)
		SELECT DISTINCT tbgd.bra_id
			FROM tbBranchGroupDetail tbgd					WITH (NOLOCK)
			INNER JOIN tbUserAuthorizationRelation tuar		WITH (NOLOCK)
				ON	tuar.comp_id	= @comp_id		AND
					tuar.[user_id]	= @user_id		AND
					tuar.brag_id    = tbgd.brag_id
			WHERE NOT EXISTS(	SELECT TOP 1 	1
	                 				FROM  @tblBranchsWithPermission tmp1
		                   			WHERE tmp1.bra_id = tbgd.bra_id
							)

	INSERT INTO @tblBranchsWithPermission  (bra_id)
		SELECT DISTINCT tuar.bra_id
			FROM tbUserAuthorizationRelation tuar			WITH (NOLOCK)
			WHERE 	tuar.comp_id	= @comp_id		AND
					tuar.[user_id]	= @user_id		AND
					tuar.bra_id		IS NOT NULL		AND
			        NOT EXISTS(	SELECT TOP 1 	1
	                 				FROM  @tblBranchsWithPermission tmp1
		                   			WHERE tmp1.bra_id = tuar.bra_id
			                   )

	-- -----------------------------------------------------------------------------------





	-- ------------------------------
	-- Autorizaciones Pendientes
	-- ------------------------------

	select	' ' [ ], ' ' [ ], ' ' [ ],
			ar.aure_cd									[aure_cd],
			u.user_firstname + ' ' + u.user_lastname	[name],
			ar.aure_obs_1,
			ar.aure_obs_2,
			ar.aure_obs_3,
			ar.aure_obs_4,
			1											[aure_TypeOfReq],			-- no cambiar

			-- ATENCION, NO PONER NADA DEBAJO DE ESTOS CAMPOS !!!!
			IsNull(ar.aure_Link,'')						[aure_Link],			-- Count - 2
			ar.aure_id															-- Count - 1




	FROM 	dbo.tbProfileAuthorization				pa		WITH (NOLOCK)

			INNER JOIN dbo.tbAutorizationRequest	ar		WITH (NOLOCK)
			on  pa.comp_id	=	ar.comp_id
			AND pa.aut_id	=	ar.aut_id

			inner join dbo.tbProfile				p		WITH (NOLOCK)
			on  pa.comp_id	=	p.comp_id
			AND pa.prof_id  =	p.prof_id

			inner join dbo.tbUser					u		WITH (NOLOCK)
			on  ar.user_id	=	u.user_id

			inner join dbo.tbsysAuthorizations		sa			WITH (NOLOCK)
			on ar.aut_id	=	sa.aut_id

			LEFT JOIN @tblBranchsWithPermission		Aut1
				ON Aut1.bra_id = ar.bra_id

			LEFT JOIN @tblUsersForAuthorize			Aut2
				ON Aut2.[USER_ID] = ar.[user_id]

			LEFT JOIN tbUserAuthorizationBlock4Authorize tuaba	WITH (NOLOCK)
           		ON   	tuaba.comp_id	= ar.comp_id	AND
           				tuaba.bra_id	= ar.bra_id		AND
           				tuaba.aut_id	= ar.aut_id		AND
           				tuaba.[user_id] = @user_id

			INNER JOIN tbUser tuOWN								WITH (NOLOCK)
				ON tuOWN.[user_id] = @user_id


	WHERE 		pa.comp_id						= @comp_id
		AND 	pa.prof_id						= @prof_id
		AND 	ar.aure_isok					= 'P'		--pendientes
		AND (
				Aut1.bra_id		IS NOT NULL
					OR
				Aut2.[USER_ID]	IS NOT NULL
		    )
		AND tuaba.comp_id IS NULL
		AND (
				tuOWN.user_mustAuthorizateOwnAuthorizations = 'False'
					OR
				(
					tuOWN.user_mustAuthorizateOwnAuthorizations = 'True'
						AND
					ar.[user_id] <> @user_id
				)
			)
	-- ------------------------------

UNION ALL

	-- ------------------------------
	-- WORKFLOW
	-- ------------------------------
	SELECT	' ' [ ], ' ' [ ], ' ' [ ],
			tw.wf_dateOfAssigned,
			tu.user_firstname + ' ' + tu.user_lastname [name],
			tw.wf_message1,
			tw.wf_message2 ,
			tw.wf_message3,
			tw.wf_message4,
			CASE
				WHEN tw.wf_type = 6666 THEN -6666			-- no cambiar
				ELSE						2					-- no cambiar
			END					[aure_TypeOfReq],
			IsNull(tw.wf_link,''),				-- Count - 2
			tw.wf_id * -1						-- Count - 1
		FROM tbWorkflow tw			WITH (NOLOCK)
		INNER JOIN tbUser tu		WITH (NOLOCK)
			ON tu.[user_id]			= tw.user_id_assigned
		WHERE	tw.comp_id			= @comp_id				AND
				tw.wf_isProcessed	= 'False'				AND
				(
					tw.user_id_assigned = @user_id
						OR
					tw.prof_id_assigned = @prof_id
						OR
					tw.wf_type			= 6666	-- Si una tienda de MeLi perdio el TOKEN que lo vean TODOS
				)



	UNION ALL

	SELECT	' ' [ ], ' ' [ ], ' ' [ ],
			twc.wach_cd,
			twd.wact_contactName,
			twc.wach_text,
			'' ,
			'',
			'',
			-9999	[aure_TypeOfReq],		-- no cambiar
			'',				-- Count - 2
			twc.wach_id		-- Count - 1
	FROM tbWhatsapp_Chats			AS twc			WITH (NOLOCK)
	INNER JOIN tbWhatsapp_Contacts	AS twd			WITH (NOLOCK)
		ON	twc.comp_id				= twd.comp_id AND
			twc.wact_id				= twd.wact_id
	WHERE	@user_whatsAppReplyEnabled = 'tRUE' AND
			twc.comp_id				= @comp_id	AND
			--twc.[user_id]			= @user_id	AND
			twc.wach_isPending4Read = 'True'


	-- ------------------------------
	ORDER BY [aure_TypeOfReq], [aure_id]--[aure_cd]


END


GO






CREATE PROCEDURE [dbo].[spWorkFlow_getDataById]
(
	@comp_id				int,
	@wf_id					int
)
as
set nocount on


-------------------------------------------------------
-----TESTING--
/*


declare 	@comp_id			int,
			@wf_id				int

select		@comp_id	=1,
			@wf_id		=1

