CREATE PROCEDURE [dbo].[spWorkFlow_getReport]
(
	@comp_id			int,
	@lang_id			int,
	@page_id			int,
	@prof_id			int,
	@aure_isok			int,
	@datefrom			datetime,
	@dateto				datetime,
	@user_id			INT,
	@bra_id				INT,
	@intBranch4Lang		int

)
AS


set nocount on


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



set dateformat 'ymd'

	set	@datefrom = dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	set	@dateto = dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-09-11
-- Parte		: 550
-- Description	: Para poder recuperar todos los datos necesarios correspondientes a las autorizaciones, se cambia
--				  la recuperación de los datos de la tabla tbAutorizationRequest por la tabla tbSecurityLog, ya que
--				  los datos en la tabla tbAutorizationRequest se eliminan una vez que se cierran los pedidos que
--				  generan
-- =================================================================================================================
/*

declare @comp_id			int,
		@lang_id			int,
		@page_id			int,
		@prof_id			int,
		@aure_isok			int,
		@datefrom			datetime,
		@dateto				datetime,
		@user_id			INT,
		@bra_id				INT

select  @comp_id			=1,
		@lang_id			=2,
		@page_id			=10010,
		@prof_id			=-1,
		@aure_isok			=-1,
		@datefrom			='1900-01-01',
		@dateto				='9999-01-01',
		@user_id			=-1,
		@bra_id				= 1

*/




declare @laure_isok  char(2)
select	@laure_isok = case @aure_isok
						when -1 then '-1'
						when  0 then 'A'
						when  1 then 'U'
						when  2 then 'P'
					  END



DECLARE @fun_id INT
SET @fun_id = 1


select	tsl.aure_cd,
		u.user_firstname + ' ' + u.user_lastname							[name],
		ltrim(rtrim(convert(varchar(10),pa.aut_id))) + '-' + sa.aut_desc	[Authorizations],
		tsl.[aure_isok]														[state],
		tsl.seclog_obs_1													[aure_obs_1],
		tsl.seclog_obs_2													[aure_obs_2],
		tsl.seclog_obs_3													[aure_obs_3],
		tsl.aure_id

from	dbo.tbProfileAuthorization					pa

		INNER JOIN tbSecurityLog					tsl		-- Parte: 550
		ON	tsl.comp_id		= pa.comp_id					-- Parte: 550
		AND tsl.aut_id		= pa.aut_id						-- Parte: 550
		AND not tsl.aure_id   IS NULL					    -- Parte: 550

		/*INNER join dbo.tbAutorizationRequest	ar			-- Parte: 550
		on  pa.comp_id	=	ar.comp_id						-- Parte: 550
		AND pa.aut_id	=	ar.aut_id*/						-- Parte: 550

		left join dbo.tbProfile						p
		on  pa.comp_id	=	p.comp_id
		AND pa.prof_id  =	p.prof_id

		left join dbo.tbUser						u
		on  tsl.[user_id]	= u.[user_id]

		left join dbo.tbsysAuthorizations			sa
		on tsl.aut_id		= sa.aut_id

		inner JOIN tbUserCompanyProfile				tucp
		ON  tucp.comp_id   =  pa.comp_id
		and tucp.[user_id] =  tsl.[user_id]
		AND	tucp.prof_id   = pa.prof_id




WHERE 	pa.comp_id		= @comp_id
AND		(@prof_id		= -1	or pa.[prof_id]       = @prof_id)
AND		(@user_id		= -1	or tsl.[user_id]      = @user_id)
AND		(@laure_isok	= '-1'	or tsl.aure_isok	  = @laure_isok)
AND		tsl.[aure_cd]	between @datefrom and @dateto




ORDER BY 1


EXEC [spReports_getData3]@comp_id,@intBranch4Lang, @lang_id,	@page_id


/* devolución de parámetros recibidos */
DECLARE @related_page_id INT
SELECT @related_page_id = related_page_id FROM tbsysPages tp WHERE tp.page_id = @page_id

SELECT
		(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
	 WHERE t.ctrl_id = 2
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params1],

		CASE @prof_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tp.prof_desc
					FROM	tbProfile tp
					WHERE	tp.comp_id= @comp_id AND tp.prof_id= @prof_id)
		END		[params2],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id AND tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 1
      	 --AND t.[lang_id] = @lang_id
      	 AND t.[page_id] = @related_page_id AND t.[type_id]	= 1)		[params3],

		CASE @user_id WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
					(SELECT		tu.user_firstname
					FROM	tbUser tu
					WHERE	tu.[user_id]= @user_id)
		END		[params4],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 177
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params5],
      	 @datefrom [DateParams1],
      	 --convert(varchar,day(@datefrom)) + '/' + convert(varchar,month(@datefrom)) + '/' + convert(varchar,year(@datefrom)) 	[params6],

      	 	(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 384
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params7],

      	 @dateto [DateParams2],

		--convert(varchar,day(@dateto)) + '/' + convert(varchar,month(@dateto)) + '/' + convert(varchar,year(@dateto)) 	[params8],

			(SELECT tswn.word_desc FROM [tbsysTextsNew] t INNER JOIN tbSysWordsNew tswn ON tswn.lang_id = @lang_id and tswn.wordsi_id = t.wordsi_id
      	 WHERE t.ctrl_id = 396
      	 --AND t.[lang_id] = @lang_id
      	 and t.[page_id] = @related_page_id and t.[type_id]	= 1)		[params9],
      	 CASE @aure_isok WHEN -1 THEN
				(SELECT		tut.utexts_desc
					FROM	tbsysUniqueTexts tut
					WHERE	tut.lang_id=@lang_id AND tut.utexts_id = 1)
			ELSE
				(SELECT		tov.optval_desc
					FROM	tbsysOptionsValues tov
					WHERE	tov.optval_class	=	8
					AND		tov.optval_id		=	@aure_isok
					AND		tov.lang_id			=	@lang_id)
		END		[params10]


GO






CREATE  PROCEDURE [dbo].[spWorkFlow_insertData]
(
		@comp_id			int,
		@bra_id				INT,
		@prof_id			INT,
		@aut_id				int,
		@user_id			int, --usuario que solicita la autorización
		@aure_isok			char(1),
		@aure_obs_1			varchar(1000),
		@aure_obs_2			varchar(1000),
		@aure_image			image,
		@aure_obs_3			varchar(1000),
		@aure_obs_4			varchar(1000),
		@sysCode_id			int,
		@aure_user_id		int, --usuario que autoriza la solicitud
		@aure_guid			uniqueidentifier,
		@aure_genericId		int,
		@aure_genericGuid	uniqueidentifier,
		@pageHTML			nTEXT,
		@aure_guid_postBack UNIQUEIDENTIFIER,
		@return_value		int OUTPUT,
		@aure_link			VARCHAR(4000)
)

AS

BEGIN


	set nocount on

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	-- -----------------------------------------------------------------------------

	-- MOS   07-2010
	-- Si la clave esta HABILITADA en la sucursal actual, graba el pedido de autorizacion.-
	-- Si NO esta habilitada entonces no inserta nada.-
	IF (NOT EXISTS (	SELECT 1
						FROM tbAuthorizationsQualification taq
               			WHERE	taq.comp_id			= @comp_id
               				AND taq.bra_id			= @bra_id
               				AND taq.aut_id			= @aut_id
               				AND taq.aut_disabled	= 'true') )
       AND
       -- Verifica que el perfil no este habilitado para autorizar la clave..
       -- de no estarlo, hace el insert.!
       (NOT EXISTS  (SELECT 1
						FROM tbProfileAuthorization tpa
						WHERE	tpa.comp_id = @comp_id
							AND tpa.prof_id = @prof_id
							AND tpa.aut_id  = @aut_id )
		)

		BEGIN

			insert into dbo.tbAutorizationRequest
			(comp_id, aut_id, user_id, aure_cd, aure_isok, aure_obs_1, aure_obs_2,
			aure_image, aure_obs_3, aure_obs_4, sysCode_id, aure_user_id, aure_guid,
			aure_genericId, aure_genericGuid, bra_id,aure_pageHTML,aure_guid_postBack,aure_TypeOfReq,aure_Link)

			values
			(@comp_id, @aut_id, @user_id, getdate(), @aure_isok, @aure_obs_1, @aure_obs_2,
			@aure_image, @aure_obs_3, @aure_obs_4, @sysCode_id, @aure_user_id, @aure_guid,
			@aure_genericId, @aure_genericGuid, @bra_id,@pageHTML,@aure_guid_postBack,2,@aure_link)

			set	@return_value = @@identity

		END

	ELSE
		set	@return_value = 0

END
GO






CREATE PROCEDURE [dbo].[spWorkFlow_UpdateProcessed]
(
	@comp_id				INT,
	@wf_id					INT,
	@user_id				INT
)
AS

BEGIN



	set nocount on


	-------------------------------------------------------
	-----TESTING--
	/*


	declare 	@comp_id				INT,
				@wf_id					INT,
				@user_id				INT

	select		@comp_id	=1,
				@wf_id		=1,
				@user_id	=1

	*/
											 --TESTING-----
	-------------------------------------------------------

	DECLARE @task_id AS INT = NULL
	DECLARE @mlo_id  AS INT = NULL
	SELECT  @task_id = tw.task_id,
		    @mlo_id  = tw.mlo_id
		FROM tbWorkflow AS tw	WITH (NOLOCK)
		where	comp_id		= @comp_id	and
				wf_id		= @wf_id

	UPDATE tbWorkflow	WITH (ROWLOCK)
		SET		wf_isProcessed		= 'True',
				user_id_processed	= @user_id,
				wf_dateOfProcessing = GETDATE()
		where	comp_id		= @comp_id		AND
				wf_isProcessed = 'False'	AND
				(
					wf_id		= @wf_id
					OR
					(@task_id IS NOT NULL	AND task_id = @task_id)
					OR
					(@mlo_id  IS NOT NULL	AND mlo_id  = @mlo_id)
				)




END



GO

CREATE PROCEDURE spWS_ItemImages_GetImagesCountByItemID
(
	@comp_id	INT,
	@item_id	INT
)
AS
	BEGIN
		SET NOCOUNT ON
		-- ------------------------------------------------------
		-- TESTING
		-- ------------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@item_id	INT
			SELECT
				@comp_id	= 1,
				@item_id	= 15549
		*/
		-- ------------------------------------------------------
		SELECT
			COUNT(tii.comp_id)				[TotalImageQty]
			FROM tbItemImages				AS tii WITH(NOLOCK)
			WHERE	tii.comp_id = @comp_id	AND
					tii.item_id = @item_id
	END
GO





