-- =============================================
-- Author:		MOS
-- Create date: 02-2011
-- Description:	Tabla de Dimensiones de
--              Bancos
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_Dimension_Currency]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------

	select
		sc.curr_id,
		sc.curr_desc
		from		dbo.tbSysCurrency  sc	WITH (NOLOCK)
		INNER JOIN  tbCurrency2Company tcc	WITH (NOLOCK)
			ON		tcc.curr_id = sc.curr_id
				AND tcc.comp_id = @comp_id
		Order By	tcc.cc_order
		OPTION ( MAXDOP 1 )
END

GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Dimensiones de
--              Clientes
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_Dimension_Customer]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SELECT	tc.comp_id,
			tc.cust_id,
			tc.cust_name,
			tc.ck_id,
			tc.city_id,
			CASE
				WHEN IsNull(tc.cust_zip,'') = '' THEN '*'
				ELSE tc.cust_zip
			END												[cust_zip]
		FROM tbCustomer tc			WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id
		OPTION ( MAXDOP 1 )

END

GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2020
-- Description:	Tabla de Dimensiones de
--              Potencial de Venta a Clientes
-- =============================================
