	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------


	SELECT	tcsp.comp_id,
			tcsp.cust_id,
			tcsp.cat_id,
			tcsp.subcat_id,
			dbo.fnGetExchange2(tcsp.comp_id, tcsp.pot_total, tcsp.curr_id, tc.curr_id,0,0,0,'False')	[TotalInCompanyCurrency],
			tcsp.pot_total
		FROM tbCustomerSalesPotential	AS tcsp			WITH (NOLOCK)
		INNER JOIN tbCompany			AS tc			WITH (NOLOCK)
			ON tc.comp_id = tcsp.comp_id
		WHERE tcsp.comp_id = @comp_id

	UNION

	SELECT @comp_id,
			-1,
			-1,
			-1,
			0,
			0



END

GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Dimensiones de
--              Clientes
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_Dimension_CustomerByDate]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME

AS
BEGIN


	--SET @datefrom		= DATEADD(MONTH, -2, @datefrom)
	--SET @dateto		= DATEADD(MONTH, 2 , @dateto)

	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SELECT
			DISTINCT
			tc.comp_id,
			tc.cust_id,
			tc.cust_name,
			tc.ck_id,
			tc.city_id,
			CASE
				WHEN IsNull(tc.cust_zip,'') = '' THEN '*'
				ELSE tc.cust_zip
			END												[cust_zip],
			tc.state_id,
			ISNULL(tc.fc_id,-1)								[fc_id]
	FROM tbCustomer tc						WITH (NOLOCK)
	INNER JOIN tbCommercialTransactions tct WITH (NOLOCK)
		ON	tct.comp_id = tc.comp_id AND
			tct.cust_id = tc.cust_id
	WHERE tc.comp_id = @comp_id	AND
		(
			(tct.ct_cd		BETWEEN @datefrom AND @dateto)
				OR
			(tct.ct_date	BETWEEN @datefrom AND @dateto)
		)

UNION

	SELECT
			DISTINCT
			tc.comp_id,
			tc.cust_id,
			tc.cust_name,
			tc.ck_id,
			tc.city_id,
			CASE
				WHEN IsNull(tc.cust_zip,'') = '' THEN '*'
				ELSE tc.cust_zip
			END												[cust_zip],
			tc.state_id,
			ISNULL(tc.fc_id,-1)								[fc_id]
	FROM tbCustomer tc						WITH (NOLOCK)
	INNER JOIN tbRMA_Header trh WITH (NOLOCK)
		ON	trh.comp_id = tc.comp_id AND
			trh.cust_id = tc.cust_id
	INNER JOIN tbRMA_Detail trd	WITH (NOLOCK)
		ON	trd.comp_id = trh.comp_id AND
			trd.rmah_id = trh.rmah_id
	WHERE tc.comp_id = @comp_id	AND
		(
			(trd.rmad_Date_Reception	BETWEEN @datefrom AND @dateto)
				OR
			(trh.rmah_cd				BETWEEN @datefrom AND @dateto)
		)
	OPTION ( MAXDOP 1 )

END

GO





