-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Dimensiones de
--              Items
-- =============================================

CREATE PROCEDURE [dbo].[spzCUBE_Dimension_ItemByDate]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME

AS




BEGIN



	SET DATEFORMAT 'ymd'

	-- -----------------------------------------
	-- Test
	-- -----------------------------------------
	/*
	DECLARE
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
	SELECT
	@comp_id		= 1,
	@bra_id			= 1,
	@user_id		= 1,
	@prof_id		= 1,
	@lang_id		= 2,
	@datefrom		= '2023-01-01',
	@dateto			= '2023-04-30'
	*/
	-- -----------------------------------------






	SET @datefrom   = DATEADD(DAY, -10 , @datefrom)
	SET @dateto		= DATEADD(DAY,  10 , @dateto)

	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')



	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SELECT	DISTINCT
			ti.comp_id,
			ti.item_id,
			ti.item_code,
			ti.item_desc,
			ti.cat_id,
			ti.subcat_id,
			ti.brand_id,
			ti.pres_id
		FROM tbItem ti								WITH (NOLOCK)
		INNER JOIN tbItemTransactions		tit		WITH (NOLOCK,INDEX(IX_tbItemTransactions_4))
			ON	ti.comp_id = tit.comp_id AND
				ti.item_id = ISNULL(tit.item_id,ISNULL(ISNULL(tit.item_idfromPreInvoice,tit.it_item_id_origin)   ,-10))	-- MOS 02-2023 x speed, si tiene el item_id es mas rapido un isnull que un case
							--CASE
							--	WHEN tit.item_id IS NOT NULL				THEN tit.item_id
							--	WHEN tit.item_idfromPreInvoice IS NOT NULL	THEN tit.item_idfromPreInvoice
							--	WHEN tit.it_item_id_origin IS NOT NULL		THEN tit.it_item_id_origin
							--	ELSE										     -10
							--END
		INNER JOIN tbCommercialTransactions tct		WITH (NOLOCK)
			ON	tct.comp_id			= tit.comp_id	AND
				tct.bra_id			= tit.bra_id	AND	-- MOS 02-2023
				tct.ct_transaction	= tit.ct_transaction

		WHERE tit.comp_id = @comp_id	AND
			 (tit.it_cd BETWEEN @datefrom AND @dateto OR tit.it_cd IS NULL)	AND
			  tct.df_id IS NOT NULL
		OPTION ( MAXDOP 1 )

END

GO





