-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Dimensiones de Fechas
--              para Ventas
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_Dimension_Sales_Dates]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------

	-- ATENCION: Si se toca el TOP modificarlo tambien en los SP de FECHAS !!!!
	SELECT			--TOP 1500000    NO USAR TOP, que vallan todas las fechas.!
					tct.comp_id,
					tct.bra_id,
					tct.ct_transaction,
					tct.ct_date,
					tct.ct_payDate,
					month(tct.ct_date)			[ct_dateMonth],
					YEAR(tct.ct_date)			[ct_dateYear]

		FROM tbCommercialTransactions tct						WITH (NOLOCK)

		INNER JOIN tbDocumentsFile tdf							WITH (NOLOCK)
			ON	tdf.comp_id = tct.comp_id	AND
				tdf.bra_id	= tct.bra_id	AND
				tdf.df_id	= tct.df_id


		INNER JOIN vwCommercialTransactions_forSalesStats vctfss		WITH (NOLOCK)
			ON		vctfss.comp_id			= tct.comp_id
				--AND vctfss.bra_id			= tct.bra_id
				AND vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
			ON vubf.comp_id			= tct.comp_id
				AND vubf.bra_id		= tct.bra_id
				AND vubf.[user_id]	= @user_id

		WHERE		tct.comp_id = @comp_id
			AND tct.ct_date BETWEEN @datefrom AND @dateto
			AND tct.sd_id NOT IN (21,23)   -- Sin Saldos iniciales.!!!!!
			AND tdf.df_cubes_ExcludeThisDocument = 'False'
		ORDER BY tct.ct_transaction DESC
		OPTION ( MAXDOP 1 )
END
GO





