-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Hechos para Contabilidad
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_FactTable_Accountant]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	SELECT	tatd.comp_id,
			tatd.bra_id,
			tatd.acc_count_id,				-- Dimension
			tatd.cc_code,					-- Dimension
			tatd.dacc_debit,				-- Metrica
			tatd.dacc_credit,				-- Metrica
			(tatd.dacc_debit - tatd.dacc_credit)  [Balance],
			tath.ag_id,
			tath.ap_id,
			tath.hacc_date,
			IsNull(tatd.acc_detail1,'')															 [acc_detail1],
			tatd.hacc_software	,			-- Como los otros de sysoptionvalues, creo q es 3004
			dbo.fnGetCommercialTransactionDescription(tath.comp_id,@lang_id,tatd.ct_transaction) [Description] -- Dimension
		FROM tbAccountTransactionDetail tatd							WITH (NOLOCK)
		INNER JOIN tbAccountTransactionHead tath						WITH (NOLOCK)
			ON		tath.hacc_transaction	= tatd.hacc_transaction
				AND tath.bra_id				= tatd.bra_id
				AND tath.comp_id			= tatd.comp_id
		left JOIN tbCommercialTransactions tct							WITH (NOLOCK)
			ON		tct.comp_id			= tatd.comp_id
				AND tct.ct_transaction	= tatd.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
						ON vubf.comp_id					= tatd.comp_id
							AND vubf.bra_id				= tatd.bra_id
							AND vubf.[user_id]			= @user_id
							AND vubf.ubf_blocked4Cube	= 'False'

	WHERE		tatd.comp_id = @comp_id
			AND tath.hacc_date BETWEEN @datefrom AND @dateto

	ORDER BY tct.ct_transaction DESC
	OPTION ( MAXDOP 1 )
END
GO





-- =============================================
-- Author:		MOS
-- Create date: 02-2011
-- Description:	Tabla de Hechos para Pedidos
-- =============================================

CREATE PROCEDURE [dbo].[spzCUBE_FactTable_ChequePortfolio]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS


BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


-- --------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------
/*
	DECLARE @comp_id AS INT
	DECLARE @bra_id  AS INT
	SET @comp_id = 1
	SET @bra_id  = 1
*/
-- --------------------------------------------------------------



	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	SELECT	tcp1.comp_id,
			tcp1.chp_id,
			tcp1.bra_id,
			tcp1.ct_transaction,
	      	tcp1.chp_number,
	      	tcp1.chp_total,
	      	tcp1.chp_EmissionDate,
	      	tcp1.chp_PayDate,
	      	tcp1.bn_id,
	      	tcp1.chp_BankBranchDescription,
	      	tcp1.chp_BankBranch,
	      	tcp1.chp_AccountNumber,
	      	tcp1.chp_taxNumber1,
			CASE
				WHEN tcp1.chp_isOwn = 'True' THEN 1
				ELSE 0
			END										[chp_isOwn]
	      	,
	      	CASE
	      		WHEN tcp1.chp_isToOrder = 'True' THEN 1
	      		ELSE 0
	      	END										[chp_isToOrder],
	      	tcp1.curr_id,
	      	CASE
	      		WHEN tcp1.chp_isDocument = 'True' THEN 1
	      		ELSE 0
	      	END										[chp_isDocument],
	      	dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction)
	      											[Receipt],
	      	tct.cust_id,
	      	tc.sm_id
		FROM tbCheckPortfolio tcp1									WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions tct						WITH (NOLOCK)
			ON		tct.comp_id			= tcp1.comp_id
				AND tct.bra_id			= tcp1.bra_id
				AND tct.ct_transaction	= tcp1.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf						WITH (NOLOCK)
					ON vubf.comp_id					= tcp1.comp_id
						AND vubf.bra_id				= tcp1.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'
		left JOIN tbCustomer tc										WITH (NOLOCK)
			ON		tc.comp_id = tct.comp_id
				AND tc.cust_id = tct.cust_id

		WHERE tcp1.comp_id = @comp_id
			AND tcp1.chp_PayDate BETWEEN @datefrom AND @dateto
			AND tcp1.chp_isAvailable = 'True'
			AND tcp1.chp_isCancelled = 'false'
		OPTION ( MAXDOP 1 )

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 10-2018
-- Description:	Tabla de Hechos para CRM
-- =============================================

CREATE PROCEDURE [dbo].[spzCUBE_FactTable_CRM]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS

BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------



	SET DATEFORMAT 'ymd'
	-- ------------------------------------------------
	-- Testing
	-- ------------------------------------------------
	/*
		DECLARE
		@comp_id		AS INT,
		@bra_id			AS INT,
		@user_id		AS INT,
		@prof_id		AS INT,
		@lang_id		AS INT,
		@datefrom		AS DATETIME,
		@dateto			AS DATETIME


		SET @comp_id		= 1
		SET @bra_id			= 1
		SET @user_id		= 1
		SET @prof_id		= 1
		SET @lang_id		= 2
		SET @datefrom		= '2000-11-30'
		SET @dateto			= '2999-11-30'
	*/
	-- ------------------------------------------------



	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	DECLARE @datTODAY AS DATETIME
	SET		@datTODAY = GETDATE()


	SELECT	tct.comp_id,
			tct.task_id,
			tct.bra_id,
			tct.[user_id],
			tct.case_id					[case_id_related],
			tct.cust_id,
	      	tct.contact_id,
	      	tct.tast_id,
	      	tct.curr_id,
	      	tct.taskt_id,
	      	tct.user_id_Last,
	      	tct.cat_id,
	      	tct.subcat_id,
	      	tct.brand_id,
	      	tct.item_id,
	      	tct.supp_id,
	      	tct.pro_id,
	      	tct.user_id_Creator,
	      	tct.user_id_4SupportCreator,
	      	tct.task_id_related,
	      	tct.task_id_related2,
	      	-1							[case_id],
	      	-1							[cast_id],
	      	-1							[caset_id],
	      	1							[intQTY],
	      	CASE
	      		WHEN tcts.tast_isInitialStatus = 'True' THEN 1
	      		WHEN tcts.tast_isFinalStatus   = 'True' THEN 3
	      		ELSE							    2
	      	END							[statusID],
	      	CASE (
					SELECT SUM(
								CASE	tctn.tasknote_isChecked
									WHEN 'False' THEN 1
									ELSE 0
								END
							 )
						FROM tbCRM_TaskNote tctn		WITH (NOLOCK)
						INNER JOIN tbCRM_TaskNoteType tctnt	WITH (NOLOCK)
							ON	tctnt.comp_id		= tctn.comp_id			AND
								tctnt.tasknotet_id	= tctn.tasknotet_id
						WHERE	tctn.comp_id				= tct.comp_id	AND
								tctn.task_id				= tct.task_id	AND
								tctnt.tasknotet_mustCheck	= 'True'
	      		)
	      		WHEN 0 THEN 2
	      		ELSE		1
	      	END 							[noteStatusID],
	      	(
					SELECT COUNT(*)
						FROM tbCRM_TaskNote tctn	WITH (NOLOCK)
						INNER JOIN tbCRM_TaskNoteType tctnt	WITH (NOLOCK)
							ON	tctnt.comp_id		= tctn.comp_id			AND
								tctnt.tasknotet_id	= tctn.tasknotet_id
						WHERE	tctn.comp_id				= tct.comp_id	AND
								tctn.task_id				= tct.task_id	AND
								tctnt.tasknotet_mustCheck	= 'True'
	      	)							[notesQTY2Verify],
	      	(
					SELECT SUM(
								CASE	tctn.tasknote_isChecked
									WHEN 'True' THEN 0
									ELSE 1
								END
							 )
						FROM tbCRM_TaskNote tctn	WITH (NOLOCK)
						INNER JOIN tbCRM_TaskNoteType tctnt	WITH (NOLOCK)
							ON	tctnt.comp_id		= tctn.comp_id			AND
								tctnt.tasknotet_id	= tctn.tasknotet_id
						WHERE	tctn.comp_id				= tct.comp_id	AND
								tctn.task_id				= tct.task_id	AND
								tctnt.tasknotet_mustCheck	= 'True'
	      	)							[notesQTYPending],
	      	tct.task_date4Begin			[beginDate],
	      	tct.task_nextReviewdate		[nextReviewDate],
	      	tct.task_date4End			[endDate],
	        tct.task_priority			[priority],
	        CASE
				WHEN tct.task_date4End > @datTODAY THEN 1
				ELSE									2
	        END							[deadLineID],
	        (
	        ((tct.task_qtyHour * 60) + tct.task_qtyMinutes)
	        +
	        (
	        	SELECT SUM((tctn.tasknote_qtyHour * 60) +  tctn.tasknote_qtyMinutes)
	        		FROM tbCRM_TaskNote AS tctn		WITH (NOLOCK)
	        		WHERE	tctn.comp_id				= tct.comp_id	AND
							tctn.task_id				= tct.task_id
	        )
	        )																		[qtyMinutes],
	        ((tct.task_qtyEstimatedHours * 60) + tct.task_qtyEstimatedMinutes)		[qtyEstimatedMinuites],
	        (
	        	((tct.task_qtyEstimatedHours * 60) + tct.task_qtyEstimatedMinutes) -
				((tct.task_qtyHour * 60) + tct.task_qtyMinutes)
	        )																		[qtyEstimatedMinuitesVariation],
	        tct.task_resolutionCustomerCompliance_Calification						[CalificationID],
	        tct.user_id4Resolution													[user_id4Resolution],
	        tct.task_date4Resolution												[resolutionDate],
	        DATEDIFF(DAY,tct.task_date4End,tct.task_date4Resolution)				[qtyResolutionDifferenceDay],
	      	(
					SELECT COUNT(*)
						FROM tbCRM_TaskNote tctn7	WITH (NOLOCK)
						WHERE	tctn7.comp_id				= tct.comp_id	AND
								tctn7.task_id				= tct.task_id
	      	)																		[notesQTY],
	      	tct.taskatr1_id															[taskatr1_id],
	      	tct.taskatr2_id															[taskatr2_id],
	      	tct.taskatr3_id															[taskatr3_id],
	      	tct.taskatr4_id															[taskatr4_id],
	      	tct.taskatr5_id															[taskatr5_id],
	      	tct.taskatr6_id															[taskatr6_id]
		FROM tbCRM_Task				tct		WITH (NOLOCK)
		INNER JOIN tbCRM_TaskStatus tcts	WITH (NOLOCK)
			ON	tcts.comp_id = tct.comp_id AND
				tcts.tast_id = tct.tast_id
		WHERE	tct.comp_id = @comp_id AND
				tct.task_date4Begin BETWEEN @datefrom AND @dateto


		UNION ALL

		SELECT tcc.comp_id,
			   -1,
			   tcc.bra_id,
			   tcc.[user_id],
			   -1,
			   tcc.cust_id,
		       tcc.contact_id ,
		       -1,
		       tcc.curr_id,
		       -1,
		       tcc.user_id_Last,
		       tcc.cat_id,
		       tcc.subcat_id,
		       tcc.brand_id,
		       tcc.item_id,
		       tcc.supp_id,
		       tcc.pro_id,
		       tcc.user_id_Creator,
		       -1,
		       -1,
		       -1,
		       tcc.case_id,
		       tcc.cast_id,
		       tcc.caset_id,
		       1,
			CASE
	      		WHEN tccs.cast_isInitialStatus = 'True' THEN 1
	      		WHEN tccs.cast_isFinalStatus   = 'True' THEN 3
	      		ELSE							    2
	      	END							[statusID],
	      	  -1						[noteStatusID],
	      	  0							[notesQTY2Verify],
	      	  0							[notesQTYPending],
	      	  tcc.case_date4Begin,
	      	  tcc.case_nextReviewdate,
	      	  tcc.case_date4End,
	      	  0	  ,
	        CASE
				WHEN tcc.case_date4End > @datTODAY THEN 1
				ELSE									2
	        END											[deadLineID]	,
	       (tcc.case_hours * 60)						[qtyMinutes],
	        0      										[qtyEstimatedMinuites],
	        0											[qtyEstimatedMinuitesVariation],
	        -1      	  								[CalificationID],
	        -1											[user_id4Resolution],
	        NULL										[resolutionDate],
	        0											[qtyResolutionDifferenceDay],
	        0											[notesQTY],
	      	NULL										[taskatr1_id],
	      	NULL										[taskatr2_id],
	      	NULL										[taskatr3_id],
	      	NULL										[taskatr4_id],
	      	NULL										[taskatr5_id],
	      	NULL										[taskatr6_id]
			FROM tbCRM_Case				tcc		WITH (NOLOCK)
			INNER JOIN tbCRM_CaseStatus tccs	WITH (NOLOCK)
				ON	tccs.comp_id = tcc.comp_id AND
					tccs.cast_id = tcc.cast_id
			WHERE	tcc.comp_id = @comp_id AND
					tcc.case_date4Begin BETWEEN @datefrom AND @dateto

		OPTION ( MAXDOP 1 )



END
GO





-- =============================================
-- Author:		MOS
-- Create date: 02-2011
-- Description:	Tabla de Hechos para Pedidos
-- =============================================

CREATE PROCEDURE [dbo].[spzCUBE_FactTable_EmmitedChecks]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS


BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------

-- --------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------
/*
	DECLARE @comp_id AS INT
	DECLARE @bra_id  AS INT
	SET @comp_id = 1
	SET @bra_id  = 1
*/
-- --------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	SELECT	tct.comp_id,
			tct.bra_id,						-- Dimension
			tct.ct_transaction,
			tct.ct_date,					-- Dimension - Fecha de Emision
			tec.ec_id,
			tec.ec_Number,					-- Dimension - Numero
			tec.ba_id,						-- Dimension - Cuenta Bancaria - tbBankingAccount
			tec.ec_Total,					-- Metrica - Total
			tec.curr_id,					-- Dimension- Moneda
			tec.ec_PayDate,					-- Dimension - Fecha de Pago
			CASE
	      		WHEN tec.ec_not_to_order = 'True' THEN 1
	      		ELSE 0
	      	END										[chp_isToOrder],	-- Dimension - No a la orden,como en chequeportfolio
	      	CASE
	      		WHEN tec.ec_isDocument = 'True' THEN 1
	      		ELSE 0
	      	END										[chp_isDocument]	-- Dimension - Documento como en cheque portdolio

		FROM tbEmmitedChecks tec										WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions tct							WITH (NOLOCK)
			ON		tct.comp_id			= tec.comp_id
				AND tct.bra_id			= tec.bra_id
				AND tct.ct_transaction	= tec.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
						ON vubf.comp_id					= tec.comp_id
							AND vubf.bra_id				= tec.bra_id
							AND vubf.[user_id]			= @user_id
							AND	vubf.ubf_blocked4Cube	= 'False'

		WHERE tec.comp_id = @comp_id
			AND tec.ec_PayDate BETWEEN @datefrom AND @dateto
		OPTION ( MAXDOP 1 )

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 02-2011
-- Description:	Tabla de Hechos para
--				Articulos - Ventas
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_FactTable_ItemsPurchase]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	SELECT
					tct.comp_id,
					tct.bra_id,
					tct.supp_id,
					tit.it_transaction,
					tit.item_id,
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction)   [Description],
					tct.ct_transaction,
					tct.ct_pointOfSale,
					tct.ct_kindOf,
					tct.cust_id,
					tit.it_qty					* vctfss.PlusOrMinus		[ItemQty],
					tit.it_qty * tit.it_price	* vctfss.PlusOrMinus		[ItemTotal],
					tct.sd_id,
					CASE
						WHEN tit.rmad_id IS NULL THEN 0
						ELSE 1
					END														[isRMA],
					tct.ct_date,
					tct.state_id,
					tct.country_id,
					tit.puco_id,
					tit.stor_id,
					tit.coslis_id,
					tit.coslis_idB,
					tit.it_poh_bra_id,
					tit.it_poh_id


		FROM tbItemTransactions tit									WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions tct						WITH (NOLOCK)
			ON		tct.comp_id				= tit.comp_id
				AND tct.bra_id				= tit.bra_id
				AND tct.ct_transaction		= tit.ct_transaction

		INNER JOIN vwCommercialTransactions_forPurchase  vctfss		WITH (NOLOCK)
			ON		vctfss.comp_id			= tct.comp_id
				AND vctfss.bra_id			= tct.bra_id
				AND vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf						WITH (NOLOCK)
					ON vubf.comp_id					= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'


	WHERE		tct.comp_id = @comp_id
			AND tct.ct_date BETWEEN @datefrom AND @dateto
			AND tct.sd_id >= 100 AND tct.sd_id <= 150

	ORDER BY tct.ct_transaction DESC
	OPTION ( MAXDOP 1 )
END
GO





--=============================================
--Author:		MOS
--Create date: 02-2011
--Description:	Tabla de Hechos para
--				Articulos - Ventas
--=============================================
CREATE PROCEDURE [dbo].[spzCUBE_FactTable_ItemsRMA]
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS
BEGIN


	SET NOCOUNT ON;
	-------------------------------------------------------------------------------
	--Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-------------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-------------------------------------------------------------------------------

	SET DATEFORMAT 'ymd'
	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')




	-- Llena tabla temporal co VENTAS
	DECLARE @tmpSales TABLE(item_id INT ,
							cust_id INT,
							cd DATE,
							qty DECIMAL(19,2),
							bra_id INT,
							entryMode INT,
							cat_id			INT,
							subcat_id		INT,
							subcataux_id INT,
							ic_id INT,
							ic_levelI INT,
							ic_levelII INT,
							ic_levelIII INT,
							ic_levelIV INT,
							ic_levelV INT,
							ic_levelVI INT,
							ic_levelVII INT,
							ic_levelVIII INT,
							item_code NVARCHAR(50)
							 )
	INSERT INTO @tmpSales(	bra_id,
							item_id,
							cust_id,
							cd,
							qty ,
							entryMode,
							cat_id,
							subcat_id ,
							subcataux_id,
							ic_id,
							ic_levelI,
							ic_levelII,
							ic_levelIII,
							ic_levelIV,
							ic_levelV,
							ic_levelVI,
							ic_levelVII,
							ic_levelVIII,
							item_code)
		SELECT
						tit.bra_id,
						tit.item_id												[item_id],
						tct.cust_id,
						tct.ct_date,
						SUM(tit.it_qty					* vctfss.PlusOrMinus)		[ItemQty],
						CASE
							WHEN ti.item_expser = 'True'THEN	2
							ELSE								1
						END														[entryMode],
						ti.cat_id,
						ti.subcat_id,
						ISNULL(ti.subcataux_id,-1)														[subcataux_id],
						ISNULL(ti.ic_id,-1)																[ic_id],
						ISNULL(tic.ic_levelI,-1)														[ic_levelI],
						ISNULL(tic.ic_levelII,-1)														[ic_levelII],
						ISNULL(tic.ic_levelIII,-1)														[ic_levelIII],
						ISNULL(tic.ic_levelIV,-1)														[ic_levelIV],
						ISNULL(tic.ic_levelV,-1)														[ic_levelV],
						ISNULL(tic.ic_levelVI,-1)														[ic_levelVI],
						ISNULL(tic.ic_levelVII,-1)														[ic_levelVII],
						ISNULL(tic.ic_levelVIII,-1)														[ic_levelVIII],
						ti.item_code


			FROM tbItemTransactions tit											WITH (NOLOCK)

			INNER JOIN tbCommercialTransactions tct								WITH (NOLOCK)
				ON		tct.comp_id				= tit.comp_id
					--AND tct.bra_id				= tit.bra_id
					AND tct.ct_transaction		= tit.ct_transaction

			INNER JOIN tbDocumentsFile tdf										WITH (NOLOCK)
				ON	tdf.df_id	= tct.df_id	-- Poner asi, esta Optimizado

			INNER JOIN vwCommercialTransactions_forSalesStats vctfss			WITH (NOLOCK)
				ON		vctfss.comp_id			= tct.comp_id
					AND vctfss.bra_id			= tct.bra_id
					AND vctfss.ct_transaction	= tct.ct_transaction

			INNER JOIN vwItemTransactionsProfitAndMarckup vitpam				WITH (NOLOCK)
				ON		vitpam.comp_id			= tit.comp_id
					AND vitpam.bra_id			= tit.bra_id
					AND vitpam.ct_transaction	= tit.ct_transaction
					AND vitpam.it_transaction   = tit.it_transaction

			INNER JOIN vwItemTransactionsFinalPrice tfp							WITH (NOLOCK) -- OPtimizado para los indices actuales.
				ON	tfp.comp_id					= tit.comp_id			AND
					tfp.it_transaction			= tit.it_transaction

			INNER JOIN tbUsers4BranchFilter vubf								WITH (NOLOCK)
						ON vubf.comp_id					= tct.comp_id
							AND vubf.bra_id				= tct.bra_id
							AND vubf.[user_id]			= @user_id
							AND vubf.ubf_blocked4Cube	= 'False'

			INNER JOIN tbCustomer tc											WITH (NOLOCK)
				ON	tc.comp_id					= tct.comp_id AND
					tc.cust_id					= tct.cust_id

			INNER JOIN tbItem ti												WITH (NOLOCK)
				ON	ti.comp_id	= tit.comp_id AND
					ti.item_id	= tit.item_id

			INNER JOIN tbItemClass tic											WITH (NOLOCK)
				ON	tic.ic_id	= ti.ic_id

		WHERE		tct.comp_id = @comp_id
				AND tct.ct_cd >= @datefrom	AND tct.ct_cd <= @dateto
				AND tdf.df_cubes_ExcludeThisDocument = 'False' --AND 1 = 2

		GROUP BY	tit.bra_id,
					tit.item_id,
					tct.cust_id,
					tct.ct_date,
					ti.item_expser,
					ti.cat_id,
					ti.subcat_id,
					ti.subcataux_id,
					ti.ic_id,
					tic.ic_levelI,
					tic.ic_levelII,
					tic.ic_levelIII,
					tic.ic_levelIV,
					tic.ic_levelV,
					tic.ic_levelVI,
					tic.ic_levelVII,
					tic.ic_levelVIII,
					ti.item_code
	-- FIN Llena tabla temporal co VENTAS
	OPTION ( MAXDOP 1 )

	SET DATEFORMAT 'ymd'
	DECLARE @datDateNotUsedYet AS DATE = '2199-01-01'



	SELECT			CASE
						WHEN trh.cust_id IS NOT NULL THEN 1	-- RMA Clientes
						WHEN trh.supp_id IS NOT NULL THEN 2	-- RMA Proveedores
						ELSE							  0 -- Ventas del Periodo
					END														[Type],
					tit.comp_id,
					tit.bra_id,
					tit.rmah_id,
					tit.item_id												[item_id],
					ISNULL(trh.cust_id,-1)									[cust_id],
					ISNULL(trh.supp_id,-1)									[supp_id],
					0														[sales],
					tit.rmad_qty,
					tit.rmad_originalPrice,
					ISNULL(tit.user_id_Reception,-2)												[user_id_Reception],
					ISNULL(tit.rmad_Date_Reception,@datDateNotUsedYet)								[rmad_Date_Reception],
					ISNULL(tit.user_id_Diagnostic,-2)												[user_id_Diagnostic],
					ISNULL(DATEDIFF(day, tit.rmad_Date_Reception, tit.rmad_Date_Diagnostic),0)		[days4Diagnostic],
					ISNULL(tit.user_id_Proc,-2)														[user_id_Proc],
					ISNULL(DATEDIFF(day, tit.rmad_Date_Reception, tit.rmad_Date_Proc),0)			[days4Proc],
					ISNULL(tit.user_id_Delivery,-2)													[user_id_Delivery],
					ISNULL(DATEDIFF(day, tit.rmad_Date_Reception, tit.rmad_Date_Delivery),0)		[days4Delivery],
					tit.srpt_id,
					tit.bra_id_original,
					CASE
						WHEN tit.is_id IS NULL AND tit.item_id IS		NULL THEN 0			-- Ingreso Manual
						WHEN tit.is_id IS NULL AND tit.item_id IS NOT	NULL THEN 1			-- Ingreso por Articulo
						WHEN tit.is_id IS NOT NULL							 THEN 2			-- Ingreso por Numero de Serie
						ELSE 1
					END																				[entryMode],
					ti.item_code,
					ti.cat_id,
					ti.subcat_id,
					ISNULL(ti.subcataux_id,-1)														[subcataux_id],
					ISNULL(ti.ic_id,-1)																[ic_id],
					ISNULL(tic.ic_levelI,-1)														[ic_levelI],
					ISNULL(tic.ic_levelII,-1)														[ic_levelII],
					ISNULL(tic.ic_levelIII,-1)														[ic_levelIII],
					ISNULL(tic.ic_levelIV,-1)														[ic_levelIV],
					ISNULL(tic.ic_levelV,-1)														[ic_levelV],
					ISNULL(tic.ic_levelVI,-1)														[ic_levelVI],
					ISNULL(tic.ic_levelVII,-1)														[ic_levelVII],
					ISNULL(tic.ic_levelVIII,-1)														[ic_levelVIII],
					tit.rmad_id,
					ISNULL(tit.rmad_Date_Diagnostic,@datDateNotUsedYet)								[rmad_Date_Diagnostic],
					ISNULL(tit.rmad_Date_Proc,@datDateNotUsedYet)									[rmad_Date_Proc],
					ISNULL(tit.rmad_Date_Delivery,@datDateNotUsedYet)								[rmad_Date_Delivery],
					trh.rmah_id


		FROM tbRMA_Detail  tit												WITH (NOLOCK)

		INNER JOIN tbRMA_Header trh											WITH (NOLOCK)
			ON	trh.comp_id = tit.comp_id AND
				trh.rmah_id = tit.rmah_id

		INNER JOIN tbUsers4BranchFilter vubf								WITH (NOLOCK)
					ON vubf.comp_id				= trh.comp_id	AND
					   vubf.bra_id				= trh.bra_id	AND
					   vubf.[user_id]			= @user_id		AND
					   vubf.ubf_blocked4Cube	= 'False'

		LEFT JOIN tbItem ti													WITH (NOLOCK)
			ON	ti.comp_id	= tit.comp_id AND
				ti.item_id	= tit.item_id

		LEFT JOIN tbItemClass tic											WITH (NOLOCK)
			ON	tic.ic_id	= ti.ic_id

	WHERE		tit.comp_id = @comp_id					AND
				tit.rmad_Date_Reception >= @datefrom	AND
				tit.rmad_Date_Reception <= @dateto


	UNION ALL

			SELECT
					0														[Type],
					@comp_id,
					yy.bra_id,
					-1														[rmah_id],
					yy.item_id												[item_id],
					yy.cust_id,
					-1	[supp_id],
					yy.qty													[sales],
					0														[rmad_qty],
					0														[rmad_originalPrice],
					-1														[user_id_Reception],
					yy.cd													[rmad_Date_Reception],
					-1														[user_id_Diagnostic],
					0														[days4Diagnostic],
					-1														[user_id_Proc],
					0														[days4Diagnostic],
					-1														[user_id_Delivery],
					0														[days4Delivery],
					-1														[srpt_id],
					yy.bra_id												,
					yy.entryMode											[entryMode],
					yy.item_code,
					yy.cat_id,
					yy.subcat_id,
					ISNULL(yy.subcataux_id,-1)														[subcataux_id],
					ISNULL(yy.ic_id,-1)																[ic_id],
					ISNULL(yy.ic_levelI,-1)															[ic_levelI],
					ISNULL(yy.ic_levelII,-1)														[ic_levelII],
					ISNULL(yy.ic_levelIII,-1)														[ic_levelIII],
					ISNULL(yy.ic_levelIV,-1)														[ic_levelIV],
					ISNULL(yy.ic_levelV,-1)															[ic_levelV],
					ISNULL(yy.ic_levelVI,-1)														[ic_levelVI],
					ISNULL(yy.ic_levelVII,-1)														[ic_levelVII],
					ISNULL(yy.ic_levelVIII,-1)														[ic_levelVIII],
					0	,
					yy.cd,
					yy.cd,
					yy.cd,
					0																				[rmah_id]


				FROM 	@tmpSales yy

			ORDER BY [Type],[rmad_Date_Reception]
		OPTION ( MAXDOP 1 )


END
GO





-- =============================================
-- Author:		MOS
-- Create date: 02-2011
-- Description:	Tabla de Hechos para
--				Articulos - Ventas
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_FactTable_ItemsSales]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS
BEGIN


	SET NOCOUNT ON;
	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

	SELECT
					tct.comp_id,
					tct.bra_id,
					tit.it_transaction,
					CASE
						WHEN tit.item_id IS NOT NULL				THEN tit.item_id
						WHEN tit.item_idfromPreInvoice IS NOT NULL	THEN tit.item_idfromPreInvoice
						WHEN tit.it_item_id_origin IS NOT NULL		THEN tit.it_item_id_origin
						ELSE										     NULL
					END																					 [item_id],
					-- ti.item_id												[item_id],  --tit.item_id   MOS 12-2021, se agregaron los de Fc Anticipada con su Item_Id o los COMBOS
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction)   [Description],
					tct.ct_transaction,
					tct.ct_pointOfSale,
					tct.ct_kindOf,
					tct.cust_id,
					tit.it_qty					* vctfss.PlusOrMinus		[ItemQty],
					tit.it_qty * tit.it_price	* vctfss.PlusOrMinus		[ItemTotal],
					vitpam.SumOfCost			* vctfss.PlusOrMinus		[ItemTotalCost],
					vitpam.SumOfCostPP			* vctfss.PlusOrMinus		[ItemTotalCostPP],
					vitpam.SumOfCostB			* vctfss.PlusOrMinus		[ItemTotalCostB],
					vitpam.SumOfCostBPP			* vctfss.PlusOrMinus		[ItemTotalCostBPP],
					tct.sm_id,
					tct.disc_id,
					tct.df_id,
					tct.st_id,
					CASE
						WHEN tit.rmad_id IS NULL THEN 0
						ELSE 1
					END														[isRMA],
					tct.ct_date,
					tct.state_id,
					tct.country_id,
					CASE
						WHEN IsNull(tit.it_isMade,'False') = 'True' THEN 1
						ELSE											 0
					END														[isMade],
					tit.it_qty * tfp.PriceWithTaxes * vctfss.PlusOrMinus	[ItemTotalWithTaxes],
					ISNULL(tc.act_id,-1)															[act_id],
					ISNULL(tc.ss_id,-1)																[ss_id],
					tct.dl_id,
					tct.ct_cd,
					ti.item_code,
					tit.it_qty * tit.it_CreditInt		* vctfss.PlusOrMinus						[it_CreditInt],
					tit.it_qty * tit.it_CreditIntPlus	* vctfss.PlusOrMinus						[it_CreditIntPlus],
					tit.it_qty * tfp.TotalTaxes			* vctfss.PlusOrMinus						[ItemTaxes],
					ISNULL(ti.subcataux_id,-1)														[subcataux_id],
					ISNULL(ti.ic_id,-1)																[ic_id],
					ISNULL(tic.ic_levelI,-1)														[ic_levelI],
					ISNULL(tic.ic_levelII,-1)														[ic_levelII],
					ISNULL(tic.ic_levelIII,-1)														[ic_levelIII],
					ISNULL(tic.ic_levelIV,-1)														[ic_levelIV],
					ISNULL(tic.ic_levelV,-1)														[ic_levelV],
					ISNULL(tic.ic_levelVI,-1)														[ic_levelVI],
					ISNULL(tic.ic_levelVII,-1)														[ic_levelVII],
					ISNULL(tic.ic_levelVIII,-1)														[ic_levelVIII],
					ISNULL(tit.prli_id,-1)															[prli_id],
					tit.it_qty * tit.it_priceWithOutOthers	* vctfss.PlusOrMinus					[ItemTotalNoInterest],
					ISNULL(tit.it_MPCost,0)		* vctfss.PlusOrMinus	* tit.it_qty				[it_MPCost],
					ISNULL(tit.it_MECost,0)		* vctfss.PlusOrMinus	* tit.it_qty				[it_MECost],
					ISNULL(tit.it_MLCost,0)		* vctfss.PlusOrMinus	* tit.it_qty				[it_MLCost],
					dbo.fnGetExchange2(tit.comp_id, ISNULL(tcsp.pot_total,0), ISNULL(tcsp.curr_id,tb.curr_id), tb.curr_id,0,0,0,'False')	[CusSalPotBraCurr],
					ti.supp_id


		FROM tbItemTransactions tit											WITH (NOLOCK)

		INNER JOIN tbUsers4BranchFilter vubf								WITH (NOLOCK)
					ON vubf.comp_id					= tit.comp_id
						AND vubf.bra_id				= tit.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'


		INNER JOIN tbCommercialTransactions tct								WITH (NOLOCK)
			ON		tct.comp_id				= tit.comp_id
				AND tct.bra_id				= tit.bra_id
				AND tct.ct_transaction		= tit.ct_transaction



		INNER JOIN tbBranch		AS tb										WITH (NOLOCK)
			ON	tb.comp_id					= tit.comp_id AND
				tb.bra_id					= tit.bra_id



		INNER JOIN vwCommercialTransactions_forSalesStats vctfss			WITH (NOLOCK)
			ON		vctfss.comp_id			= tct.comp_id
				--AND vctfss.bra_id			= tct.bra_id
				AND vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN vwItemTransactionsProfitAndMarckup vitpam				WITH (NOLOCK)
			ON		vitpam.comp_id			= tit.comp_id
				AND vitpam.bra_id			= tit.bra_id
				AND vitpam.ct_transaction	= tit.ct_transaction
				AND vitpam.it_transaction   = tit.it_transaction

		INNER JOIN vwItemTransactionsFinalPrice tfp							WITH (NOLOCK) -- OPtimizado para los indices actuales.
			ON	tfp.comp_id					= tit.comp_id			AND
				tfp.it_transaction			= tit.it_transaction

		INNER JOIN tbDocumentsFile tdf										WITH (NOLOCK)
			ON	tdf.df_id	= tct.df_id	-- Poner asi, esta Optimizado

		INNER JOIN tbCustomer tc											WITH (NOLOCK)
			ON	tc.comp_id					= tct.comp_id AND
				tc.cust_id					= tct.cust_id

		INNER JOIN tbItem ti												WITH (NOLOCK)
			ON	ti.comp_id	= tit.comp_id AND
				--ti.item_id	= ISNULL(tit.item_id,tit.item_idfromPreInvoice) MOS 12-2021
				ti.item_id	=	ISNULL(tit.item_id,ISNULL(ISNULL(tit.item_idfromPreInvoice,tit.it_item_id_origin)   ,-10))	-- MOS 02-2023 x Speed
								--CASE
								--	WHEN tit.item_id IS NOT NULL				THEN tit.item_id
								--	WHEN tit.item_idfromPreInvoice IS NOT NULL	THEN tit.item_idfromPreInvoice
								--	WHEN tit.it_item_id_origin IS NOT NULL		THEN tit.it_item_id_origin
								--	ELSE										     -10
								--END

		INNER JOIN tbItemClass tic											WITH (NOLOCK)
			ON	tic.ic_id	= ti.ic_id

		LEFT JOIN tbCustomerSalesPotential	AS tcsp							WITH (NOLOCK)
			ON	tcsp.comp_id	= tc.comp_id	AND
				tcsp.cust_id	= tc.cust_id	AND
				tcsp.cat_id		= ti.cat_id		AND
				tcsp.subcat_id	= ti.subcat_id


	WHERE		tct.comp_id = @comp_id
			AND tct.ct_cd >= @datefrom	AND tct.ct_cd <= @dateto
			AND tdf.df_cubes_ExcludeThisDocument = 'False'

	ORDER BY tct.ct_transaction DESC
	OPTION ( MAXDOP 1 )




END
GO





-- =============================================
-- Author:		MOS
-- Create date: 03-2012
-- Description:	Tabla de Hechos para PAGOS
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_FactTable_Payments]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')

		-- Otros Pagos x Conceptos
		SELECT	tct.comp_id,
				tct.bra_id,										--*
				tctopd.puco_id								[puco_id],			--*
				IsNull(tctopd.cc_code,tb.cc_code)			[cc_code],			--*
				tct.supp_id,									--*
				tct.ct_transaction,
				tct.ct_date									[Date],
				ISNULL(tct.ct_taxDate,tct.ct_date)			[TaxDate],
				tct.curr_id_transaction		[curr_id],
				tct.[user_id],				--*
				tct.ct_pointOfSale,
				tct.ct_kindOf,
				tct.ct_docNumber,
				tct.country_id,
				tct.state_id ,
				tctop.op_paymentTo			[PayTo],
				tctopd.ctopd_desc			[PayDescription],
				tctopd.ctopd_total			[Total],
				0							[Tax],
				1							[Type]

			FROM tbCommercialTransactions tct								WITH (NOLOCK)

			INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
					ON vubf.comp_id					= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'

			INNER JOIN tbBranch tb											WITH (NOLOCK)
				ON		tb.comp_id = tct.comp_id
					AND tb.bra_id  = tct.bra_id
			INNER JOIN tbCommercialTransactionsOtherPayments tctop			WITH (NOLOCK)
				ON		tctop.comp_id			= tct.comp_id
					AND tctop.ct_transaction	= tct.ct_transaction
			INNER JOIN tbCommercialTransactionsOtherPaymentsDetail tctopd	WITH (NOLOCK)
				ON tctopd.comp_id				= tct.comp_id
					AND tctopd.ct_transaction	= tct.ct_transaction
			WHERE	tct.sd_id = 106	AND
					tct.ct_taxDate BETWEEN @datefrom AND @dateto

	UNION ALL

		-- Pagos no aplicados o con Parciales NO ApLICados
		SELECT	tct.comp_id,
				tct.bra_id,										--*
				tcpa.puco_id									[puco_id],			--*
				tb.cc_code										[cc_code],			--*
				tct.supp_id,									--*
				tct.ct_transaction,
				tct.ct_date										[Date],
				tct.ct_taxDate									[TaxDate],
				tct.curr_id_transaction							[curr_id],
				tct.[user_id],				--*
				tct.ct_pointOfSale,
				tct.ct_kindOf,
				tct.ct_docNumber,
				tct.country_id,
				tct.state_id ,
				ts.supp_name									[PayTo],
				'A Cuenta'										[PayDescription],
				tct.ct_ABalance	* tct.ct_ACurrencyExchange		[Total],
				0												[Tax],
				2												[Type]

			FROM tbCommercialTransactions tct										WITH (NOLOCK)

			INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
					ON vubf.comp_id					= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'

			INNER JOIN tbSupplier ts												WITH (NOLOCK)
				ON		ts.comp_id = tct.comp_id
					AND ts.supp_id = tct.supp_id
			INNER JOIN tbBranch tb													WITH (NOLOCK)
				ON		tb.comp_id = tct.comp_id
					AND tb.bra_id  = tct.bra_id
			INNER JOIN tbCommercialTransactionsPaymentsAdditionals tcpa				WITH (NOLOCK)
				ON		tcpa.comp_id		= tct.comp_id
					AND tcpa.ct_transaction = tct.ct_transaction
			WHERE tct.sd_id = 106
				AND tct.ct_ABalance > 0
				AND
					tct.ct_taxDate BETWEEN @datefrom AND @dateto
				AND NOT EXISTS (SELECT 1
									FROM tbCommercialTransactionsOtherPayments tctop	WITH (NOLOCK)
									WHERE	tctop.comp_id			= tct.comp_id AND
											tctop.ct_transaction	= tct.ct_transaction )


	UNION ALL



		-- Pagos Aplicados a Facturas y saco los importes de las facturas segun el coeficiente
		-- X PurchaseConceptMovements
		SELECT	tct.comp_id,
				tct.bra_id,															--*
				tpcm.puco_id									[puco_id],			--*
				IsNull(tpcm.cc_code,tb.cc_code)					[cc_code],			--*
				tct.supp_id,									--*
				tct.ct_transaction,
				tct.ct_date										[Date],
				tct.ct_taxDate									[TaxDate],
				tct.curr_id_transaction							[curr_id],
				tct.[user_id],				--*
				tct.ct_pointOfSale,
				tct.ct_kindOf,
				tct.ct_docNumber,
				tct.country_id,
				tct.state_id ,
				ts.supp_name																	[PayTo],
				'Aplicados'																		[PayDescription],
				ISNULL((tpcm.pcm_total * tct.ct_ACurrencyExchange),0)
				* ta.appl_coef / 100															[Total],
				ISNULL((Select SUM(ttm.tm_total)
							FROM tbTaxMovements ttm	WITH (NOLOCK)
							WHERE	ttm.comp_id		= tpcm.comp_id
								AND ttm.pcm_id		= tpcm.pcm_id ),0)
						* ta.appl_coef / 100													[Tax],
				3																				[Type]

			FROM tbCommercialTransactions tct									WITH (NOLOCK)

			INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
					ON vubf.comp_id					= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'

			INNER JOIN tbSupplier ts											WITH (NOLOCK)
				ON		ts.comp_id					= tct.comp_id
					AND ts.supp_id					= tct.supp_id
			INNER JOIN tbBranch tb												WITH (NOLOCK)
				ON		tb.comp_id					= tct.comp_id
					AND tb.bra_id					= tct.bra_id
			INNER JOIN tbApplication ta											WITH (NOLOCK)
				ON		ta.comp_id					= tct.comp_id
					AND ta.ct_transaction_destiny	= tct.ct_transaction
			INNER JOIN tbcommercialTransactions tctAppl							WITH (NOLOCK)
				ON		tctAppl.comp_id				= ta.comp_id
					AND tctappl.ct_transaction		= ta.ct_transaction_Source
			LEFT JOIN tbPurchaseConceptMovements tpcm							WITH (NOLOCK)
				ON		tpcm.comp_id		= tctappl.comp_id
					AND tpcm.ct_transaction = tctappl.ct_transaction
			WHERE tct.sd_id = 106
				AND
					tct.ct_taxDate BETWEEN @datefrom AND @dateto
				AND NOT EXISTS (SELECT 1
									FROM tbCommercialTransactionsOtherPayments tctop	WITH (NOLOCK)
									WHERE	tctop.comp_id			= tct.comp_id
										AND tctop.ct_transaction	= tct.ct_transaction )
				--AND tct.ct_transaction = 7569


	UNION ALL

		-- Pagos Aplicados a Facturas y saco los importes de las facturas segun el coeficiente
		-- X PurchaseConceptMovements
		SELECT	tct.comp_id,
				tct.bra_id,										--*
				tit.puco_id										[puco_id],			--*
				tb.cc_code										[cc_code],			--*
				tct.supp_id,									--*
				tct.ct_transaction,
				tct.ct_date										[Date],
				tct.ct_taxDate									[TaxDate],
				tct.curr_id_transaction							[curr_id],
				tct.[user_id],				--*
				tct.ct_pointOfSale,
				tct.ct_kindOf,
				tct.ct_docNumber,
				tct.country_id,
				tct.state_id ,
				ts.supp_name									[PayTo],
				'A Cuenta'										[PayDescription],
				ISNULL((tit.it_qty * tit.it_price * tct.ct_ACurrencyExchange),0)
				* ta.appl_coef / 100							[Total],
				ISNULL((Select SUM(ttm.tm_total)
							FROM tbTaxMovements ttm		WITH (NOLOCK)
							WHERE	ttm.comp_id			= tit.comp_id
								AND ttm.it_transaction	= tit.it_transaction ),0) * ta.appl_coef / 100	[Tax],
				4												[Type]

			FROM tbCommercialTransactions tct								WITH (NOLOCK)

			INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
					ON vubf.comp_id					= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'

			INNER JOIN tbSupplier ts										WITH (NOLOCK)
				ON		ts.comp_id					= tct.comp_id
					AND ts.supp_id					= tct.supp_id
			INNER JOIN tbBranch tb											WITH (NOLOCK)
				ON		tb.comp_id					= tct.comp_id
					AND tb.bra_id					= tct.bra_id
			INNER JOIN tbApplication ta										WITH (NOLOCK)
				ON		ta.comp_id					= tct.comp_id
					AND ta.ct_transaction_destiny	= tct.ct_transaction
			INNER JOIN tbcommercialTransactions tctAppl						WITH (NOLOCK)
				ON		tctAppl.comp_id				= ta.comp_id
					AND tctappl.ct_transaction		= ta.ct_transaction_Source
			LEFT JOIN tbItemTransactions tit								WITH (NOLOCK)
				ON		tit.comp_id			= tctappl.comp_id
					AND tit.ct_transaction	= tctappl.ct_transaction
			WHERE tct.sd_id = 106
				AND
					tct.ct_taxDate BETWEEN @datefrom AND @dateto
				AND NOT EXISTS (SELECT 1
									FROM tbCommercialTransactionsOtherPayments tctop	WITH (NOLOCK)
									WHERE	tctop.comp_id			= tct.comp_id
										AND tctop.ct_transaction	= tct.ct_transaction )
				--AND tct.ct_transaction = 7569
		OPTION ( MAXDOP 1 )



END
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Hechos Analisis de Compras
-- =============================================
CREATE PROCEDURE [dbo].[spzCUBE_FactTable_PurchaseAnalisis]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	DECLARE @datProcessingDate	AS DATETIME
	DECLARE @datFromLastYear	AS DATETIME
	DECLARE @datFromLastSemester AS DATETIME
	DECLARE @datFromLastQuarter  AS DATETIME
	SELECT @datProcessingDate = tb.bra_processingDate
		FROM	tbBranch tb
		WHERE	tb.bra_id = @bra_id

	SET @datFromLastYear		= DATEDIFF(YEAR ,@datProcessingDate,-1)
	SET @datFromLastSemester	= DATEDIFF(month,@datProcessingDate,-6)
	SET @datFromLastQuarter		= DATEDIFF(MONTH,@datProcessingDate,-3)

	SELECT	-- Dimensiones
	--TOP 40
			ti.comp_id,
			ti.item_id,
			ti.bra_id,
			tis.stor_id,
			ti.cat_id,
			ti.subcat_id,
			ti.brand_id,
			ti.pres_id,
			ti.item_desc,
			ti.item_code,

			-- Metricas
			tis.itst_cant																				[StkFis],
			IsNull(dbo.fnGetAStock(ti.comp_id,tis.stor_id,ti.item_id,999999999),0)						[StkPot],
			ti.item_cantOpt - ISNULL( dbo.fnGetAStock(ti.comp_id,tis.stor_id,ti.item_id,999999999),0)	[OptStkFromStkPot],
			IsNull(ti.item_cantOpt - tis.itst_cant,0)													[OptStkFromStk],
			IsNull((SELECT Sum(tpod.pod_qty)
				FROM tbPurchaseOrderDetail tpod				WITH (NOLOCK)
				WHERE	tpod.comp_id = ti.comp_id
					AND tpod.item_id = ti.item_id
					AND tpod.bra_id  = @bra_id
					AND tpod.pod_isProcessed = 'False'),0)														[OCompras],
-- No POner, MOS
			ISNULL((SELECT Sum(tit.it_qty * CASE WHEN tct.sd_id=3 THEN -1 ELSE 1 END )
				FROM tbItemTransactions tit					WITH (NOLOCK)
				INNER JOIN tbCommercialTransactions tct		WITH (NOLOCK)
					ON		tct.comp_id			= tit.comp_id
						AND tct.ct_transaction	= tit.ct_transaction
				INNER JOIN tbDocumentsFile tdf				WITH (NOLOCK)
					ON		tdf.comp_id	= tct.comp_id
						AND tdf.df_id	= tct.df_id
				INNER JOIN tbUsers4BranchFilter vubf		WITH (NOLOCK)
					ON		vubf.comp_id	= tct.comp_id
						AND vubf.bra_id		= tct.bra_id
						AND vubf.[user_id]	= @user_id
						AND vubf.ubf_blocked4Cube = 'False'
				WHERE	tit.comp_id = ti.comp_id
					AND tit.item_id = ti.item_id
					AND tit.stor_id = tis.stor_id
					AND tct.sd_id IN (1,2,3)
					AND tct.ct_date BETWEEN @datefrom AND @dateto
					AND tdf.df_IsInterBranchDocument = 'False')
					,0)																					[SalesByDate],

			ISNULL((SELECT Sum(tit.it_qty * (CASE WHEN tct.sd_id=3 THEN -1 ELSE 1 END))
				FROM tbItemTransactions tit				WITH (NOLOCK)
				INNER JOIN tbCommercialTransactions tct	WITH (NOLOCK)
					ON		tct.comp_id			= tit.comp_id
						AND tct.ct_transaction	= tit.ct_transaction
				INNER JOIN tbDocumentsFile tdf			WITH (NOLOCK)
					ON		tdf.comp_id	= tct.comp_id
						AND tdf.df_id	= tct.df_id
				INNER JOIN tbUsers4BranchFilter vubf	WITH (NOLOCK)
					ON		vubf.comp_id	= tct.comp_id
						AND vubf.bra_id		= tct.bra_id
						AND vubf.[user_id]	= @user_id
						AND vubf.ubf_blocked4Cube = 'False'
				WHERE	tit.comp_id = ti.comp_id
					AND tit.item_id = ti.item_id
					AND tit.stor_id = tis.stor_id
					AND tct.sd_id IN (1,2,3)
					AND tdf.df_IsInterBranchDocument = 'False'
					AND tct.ct_date BETWEEN @datFromLastYear AND @datProcessingDate),0)					[SalesLastYear],

			ISNULL((SELECT Sum(tit.it_qty * (CASE WHEN tct.sd_id=3 THEN -1 ELSE 1 END))
				FROM tbItemTransactions tit
				INNER JOIN tbCommercialTransactions tct
					ON		tct.comp_id			= tit.comp_id
						AND tct.ct_transaction	= tit.ct_transaction
				INNER JOIN tbDocumentsFile tdf
					ON		tdf.comp_id	= tct.comp_id
						AND tdf.df_id	= tct.df_id
				INNER JOIN tbUsers4BranchFilter vubf
					ON		vubf.comp_id	= tct.comp_id
						AND vubf.bra_id		= tct.bra_id
						AND vubf.[user_id]	= @user_id
						AND vubf.ubf_blocked4Cube = 'False'
				WHERE	tit.comp_id = ti.comp_id
					AND tit.item_id = ti.item_id
					AND tit.stor_id = tis.stor_id
					AND tdf.df_IsInterBranchDocument = 'False'
					AND tct.sd_id IN (1,2,3)
					AND tct.ct_date BETWEEN @datFromLastSemester AND @datProcessingDate),0)				[SalesLastSemester],

			ISNULL((SELECT Sum(tit.it_qty * (CASE WHEN tct.sd_id=3 THEN -1 ELSE 1 END))
				FROM tbItemTransactions tit						WITH (NOLOCK)
				INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
					ON		tct.comp_id			= tit.comp_id
						AND tct.ct_transaction	= tit.ct_transaction
				INNER JOIN tbDocumentsFile tdf					WITH (NOLOCK)
					ON		tdf.comp_id	= tct.comp_id
						AND tdf.df_id	= tct.df_id
				INNER JOIN tbUsers4BranchFilter vubf			WITH (NOLOCK)
					ON		vubf.comp_id	= tct.comp_id
						AND vubf.bra_id		= tct.bra_id
						AND vubf.[user_id]	= @user_id
						AND vubf.ubf_blocked4Cube = 'False'
				WHERE	tit.comp_id = ti.comp_id
					AND tit.item_id = ti.item_id
					AND tit.stor_id = tis.stor_id
					AND tdf.df_IsInterBranchDocument = 'False'
					AND tct.sd_id IN (1,2,3)
					AND tct.ct_date BETWEEN @datFromLastQuarter AND @datProcessingDate),0)					[SalesLastQuarter]

		FROM tbItem ti											WITH (NOLOCK)
--		INNER JOIN tbBranch tb
--			ON tb.comp_id = ti.comp_id
		INNER JOIN tbItemStorage tis							WITH (NOLOCK)
			ON		tis.comp_id = ti.comp_id
				AND tis.item_id = ti.item_id
				--AND tis.stor_id = tb.stor_id
	WHERE	ti.item_disabled	= 'False'
		AND ti.comp_id			= @comp_id

		--AND ti.item_id = 220

		OPTION ( MAXDOP 1 )

END
GO






-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Hechos para Ventas
-- =============================================

CREATE PROCEDURE [dbo].[spzCUBE_FactTable_Sales]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS




BEGIN

	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------


	SET DATEFORMAT 'ymd'
	-- ------------------------------------------------
	-- Testing
	-- ------------------------------------------------
	/*
		DECLARE
		@comp_id		AS INT,
		@bra_id			AS INT,
		@user_id		AS INT,
		@prof_id		AS INT,
		@lang_id		AS INT,
		@datefrom		AS DATETIME,
		@dateto			AS DATETIME


		SET @comp_id		= 1
		SET @bra_id			= 1
		SET @user_id		= 1
		SET @prof_id		= 1
		SET @lang_id		= 2
		SET @datefrom		= '2013-11-30'
		SET @dateto			= '2013-11-30'
	*/
	-- ------------------------------------------------


	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	SELECT
					tct.comp_id,
					tct.bra_id,
					dbo.fnGetCommercialTransactionDescription(tct.comp_id,@lang_id,tct.ct_transaction)   [Description],
					tct.ct_transaction,
					tct.ct_pointOfSale,
					tct.ct_kindOf,
					tct.cust_id,
					tct.ct_total	* vctfss.PlusOrMinus												[ct_total],
					(tct.ct_subtotal - tct.ct_discount) * vctfss.PlusOrMinus							[ct_subtotal],
					tct.ct_discount * vctfss.PlusOrMinus												[ct_discount],
					tct.ct_adjust	* vctfss.PlusOrMinus												[ct_adjust],
					tct.ct_taxes	* vctfss.PlusOrMinus												[ct_taxes],
					tct.sm_id,
					tct.disc_id,
					tct.df_id,
					tct.st_id,
					tct.ct_ABalance /
					dbo.fnNoZDiv(tct.ct_ACurrencyExchange) *
					vctfss.PlusOrMinus																	[ct_Pending] ,
					IsNull(tct.ct_packagesQty,0)														[ct_packagesQty],
					ISNULL(vctpam.SumOfCost			* vctfss.PlusOrMinus,0)								[SumOfCost],
					ISNULL(vctpam.SumOfCostPP		* vctfss.PlusOrMinus,0)								[SumOfCostPP],
					ISNULL(vctpam.SumOfCostB		* vctfss.PlusOrMinus,0)								[SumOfCostB],
					ISNULL(vctpam.SumOfCostBPP		* vctfss.PlusOrMinus,0)								[SumOfCostBPP],
					ISNULL(vctpam.SumOfSale			* vctfss.PlusOrMinus,0)								[SumOfSale],
					tct.state_id,
					tct.country_id,
					1																					[Qty],
					IsNull(tct.ct_date,GETDATE())														[ct_date],
					tc.act_id,
					ISNULL(tc.ss_id,-1)																	[ss_id],
					tct.dl_id,
					IsNull(tct.ct_cd,GETDATE())															[ct_cd]


		FROM tbCommercialTransactions tct								WITH (NOLOCK)

		INNER JOIN tbCustomer tc										WITH (NOLOCK)
			ON	tc.comp_id	= tct.comp_id	AND
				tc.cust_id	= tct.cust_id

		INNER JOIN tbDocumentsFile tdf									WITH (NOLOCK)
			ON	tdf.df_id	= tct.df_id	-- Poner asi, esta Optimizado


		INNER JOIN vwCommercialTransactions_forSalesStats vctfss		WITH (NOLOCK)
			ON		vctfss.comp_id			= tct.comp_id
				--AND vctfss.bra_id			= tct.bra_id
				AND vctfss.ct_transaction	= tct.ct_transaction

		INNER JOIN vwCommercialTransactionsProfitAndMarckup vctpam		WITH (NOLOCK)
			ON		vctpam.comp_id			= tct.comp_id
				AND vctpam.bra_id			= tct.bra_id
				AND vctpam.ct_transaction	= tct.ct_transaction

		INNER JOIN tbUsers4BranchFilter vubf							WITH (NOLOCK)
					ON vubf.comp_id					= tct.comp_id
						AND vubf.bra_id				= tct.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'

	WHERE		 tct.comp_id = @comp_id
			AND (tct.ct_date >= @datefrom AND tct.ct_date <= @dateto)
			AND  tdf.df_cubes_ExcludeThisDocument = 'False'

	ORDER BY tct.ct_transaction DESC
	OPTION ( MAXDOP 1 )
END
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Tabla de Hechos para Pedidos
-- =============================================

CREATE PROCEDURE [dbo].[spzCUBE_FactTable_SalesOrders]
	-- Add the parameters for the stored procedure here
	@comp_id		AS INT,
	@bra_id			AS INT,
	@user_id		AS INT,
	@prof_id		AS INT,
	@lang_id		AS INT,
	@datefrom		AS DATETIME,
	@dateto			AS DATETIME
AS


BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	SET LOCK_TIMEOUT 500
	SET DEADLOCK_PRIORITY -10
	-- -----------------------------------------------------------------------------



-- --------------------------------------------------------------
-- Testing
-- --------------------------------------------------------------
/*
	DECLARE @comp_id AS INT
	DECLARE @bra_id  AS INT
	SET @comp_id = 1
	SET @bra_id  = 1
*/
-- --------------------------------------------------------------



	SET @datefrom	= dbo.fnGetEnd_or_BeginOfDate(@datefrom,'False')
	SET @dateto		= dbo.fnGetEnd_or_BeginOfDate(@dateto,'True')


	DECLARE @intCurrId AS INT
	SELECT @intCurrId		= curr_id
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id


	SELECT	tsod.comp_id,
			tsod.bra_id,
			tsod.soh_id,
			tsod.sod_id,
			tsod.item_id,
			tsod.sod_itemDesc,
			tsod.curr_id,
			tsod.prli_id,
			tsod.stor_id,
			tsod.[user_id],
			Case
				when tsod.rmad_id IS NULL OR tsod.rmad_id = 0 THEN 0
				ELSE 1
			END														[IsRma],
			tsoh.soh_cd,
			tsoh.soh_deliveryDate,
			tsoh.soh_lastUpdate,
			tsoh.soh_limitDate,
			tsoh.sm_id,
			tsoh.cust_id,
			tsoh.st_id,
			tsoh.disc_id,
			tsoh.dl_id,
			tsoh.df_id,
			tsoh.ssos_id,
			tsod.sod_itemDiscount			* tdf.PlusOrMinus		[sod_itemDiscount],
			tsoh.soh_packagesQty			* tdf.PlusOrMinus		[soh_packagesQty],
			tsod.sod_qty					* tdf.PlusOrMinus		[sod_qty],
			dbo.fnGetExchange2(@comp_id,
							   tsod.sod_qty * tsod.sod_price,
							   tsod.curr_id,
							   @intCurrId,
							   tsoh.curr_id4Exchange,
							   @intCurrId,
							   tsoh.curr_idExchange,
							   'False')			* tdf.PlusOrMinus	[TotalWNoTax],
			(dbo.fnGetExchange2(@comp_id,
							   (tsod.sod_qty * tsod.sod_price) ,
							   tsod.curr_id,
							   @intCurrId,
							   tsoh.curr_id4Exchange,
							   @intCurrId,
							   tsoh.curr_idExchange,
							   'False')				 +
							   + (	SELECT SUM(tsot.tm_total)
										FROM tbSaleOrderTaxes tsot
							      		WHERE	tsot.comp_id	= tsoh.comp_id
							      			AND tsot.bra_id		= tsoh.bra_id
							      			AND tsot.soh_id		= tsoh.soh_id)
			) * tdf.PlusOrMinus										[TotalWTax],

			case
				when IsNull(tc.cust_inactive,'False')	='false' THEN	0
				ELSE													1
			END																	[cust_inactive],	-- 1- Clientes Activos      2- Clientes Inactivos
			CASE dbo.fnSaleOrderGetStockStatus(@comp_id,tsoh.bra_id,tsoh.soh_id)
				when '1' THEN 1
				WHEN '2' THEN 2
				WHEN '3' THEN 3
				ELSE 3
			END																	[soh_Status],		-- 1- Stock Potencial OK    2- Stock Fisico OK   3- Sin Stock Suficiente
			CASE dbo.fnSaleOrderGetStockStatus_Item(@comp_id,tsoh.bra_id,tsoh.soh_id,tsod.item_id)
				when '1' THEN 1
				WHEN '2' THEN 2
				WHEN '3' THEN 3
				ELSE 3
			END																	[soh_Status_ByItem]		-- 1- Stock Potencial OK    2- Stock Fisico OK   3- Sin Stock Suficiente


		FROM tbSaleOrderDetail tsod							WITH (NOLOCK)
		INNER JOIN tbSaleOrderHeader tsoh					WITH (NOLOCK)
			ON		tsoh.comp_id	= tsod.comp_id
				AND tsoh.bra_id		= tsod.bra_id
				AND tsoh.soh_id		= tsod.soh_id
		INNER JOIN vwDocumentsFile tdf						WITH (NOLOCK)
			ON		tdf.comp_id		= tsoh.comp_id
				AND tdf.df_id		= tsoh.df_id
		INNER JOIN tbItem ti								WITH (NOLOCK)
			ON		ti.comp_id = tsod.comp_id
				AND ti.item_id = tsod.item_id
		INNER JOIN tbCustomer tc							WITH (NOLOCK)
			ON		tc.comp_id = tsoh.comp_id
				AND tc.cust_id = tsoh.cust_id


	INNER JOIN tbUsers4BranchFilter vubf					WITH (NOLOCK)
					ON vubf.comp_id					= tsoh.comp_id
						AND vubf.bra_id				= tsoh.bra_id
						AND vubf.[user_id]			= @user_id
						AND vubf.ubf_blocked4Cube	= 'False'

	WHERE	tsoh.comp_id	= @comp_id							AND
			tsoh.soh_cd		BETWEEN @datefrom AND @dateto
	OPTION ( MAXDOP 1 )

END
GO





