-- =============================================
-- Author:		MOS
-- Description:	Insertar valores de Test en
-- ZTest para poder depurar un SP
-- =============================================
CREATE PROCEDURE spZTest_InsertData
	@strDato			AS VARCHAR(8000),
	@datFecha			AS DATETIME,
	@intPuntaje			AS INT,
	@decValor			AS DECIMAL(18,0),
	@decValorWDecimals	AS DECIMAL(19,6)
AS
BEGIN

	SET NOCOUNT ON;

	INSERT INTO zTest
	(
		dato,
		fecha,
		puntaje,
		valor,
		valorWithDecimal
	)
	VALUES
	(
		@strDato,
		@datFecha,
		@intPuntaje,
		@decValor,
		@decValorWDecimals
	)


END
GO





-- =============================================
-- Author:	Usar para Test Unicamente
