CREATE PROCEDURE [dbo].[tbSaleOrderSerial4Production_MasterSerial_getDataById]
(
    @comp_id				INT,
	@bra_id					INT,
	@soh_id					INT,
	@sod_id					INT,
	@order					INT
)
AS
BEGIN

	SET NOCOUNT ON


