CREATE FUNCTION dbo.fnChar2Hex(@char char(1))
RETURNS char(2)
AS

BEGIN

    DECLARE @hex char(2), @dec int;

    SET @dec=ASCII(@char);

    SET @hex= --- First hex digit:
             SUBSTRING('0123456789ABCDEF', 1+(@dec-@dec%16)/16, 1)+
              --- Second hex digit:
             SUBSTRING('0123456789ABCDEF', 1+(     @dec%16)   , 1);

    RETURN(@hex);
END
GO




