-- Create date:
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION fnCheckBoard_ScheduleExecution
(
	@comp_id AS INT,
	@cbd_id	 AS INT,
	@cbds_id AS INT,
	@intDOW  AS INT
)
RETURNS DATETIME
AS
BEGIN

	DECLARE @datDateOfExecution AS DATETIME
	SET @datDateOfExecution = GETDATE()



	DECLARE @intTypeOfSchedule	AS INT
	DECLARE @intHours			AS INT
	DECLARE @intMinutes			AS INT
	DECLARE @intDay				AS INT
	DECLARE @intMonth			AS INT
	DECLARE @intYear			AS INT
	DECLARE @bitDisabledOnSun	AS BIT
	DECLARE @bitDisabledOnMon	AS BIT
	DECLARE @bitDisabledOnTue	AS BIT
	DECLARE @bitDisabledOnWed	AS BIT
	DECLARE @bitDisabledOnThu	AS BIT
	DECLARE @bitDisabledOnFri	AS BIT
	DECLARE @bitDisabledOnSat	AS BIT
	SELECT		@intTypeOfSchedule	= tcbs.cbds_scheduleType,
				@intHours			= dbo.fnGetMaximumValue( dbo.fnGetMinimumValue( ISNULL(tcbs.cbds_hour,0),23 ),0 ),
				@intMinutes			= dbo.fnGetMaximumValue( dbo.fnGetMinimumValue( ISNULL(tcbs.cbds_minute,0),59 ),0 ),
				@intDay				= dbo.fnGetMaximumValue( dbo.fnGetMinimumValue( ISNULL(tcbs.cbds_day,1),31 ),1 ),
				@intMonth			= dbo.fnGetMaximumValue( dbo.fnGetMinimumValue( ISNULL(tcbs.cbds_month,1),12 ),1 ),
				@intYear			= dbo.fnGetMaximumValue( dbo.fnGetMinimumValue( ISNULL(tcbs.cbds_year,2013),2999 ),2013 ),
				@bitDisabledOnSun	= ISNULL(tcbs.cbds_disabledOnSunday,'False'),
				@bitDisabledOnMon	= ISNULL(tcbs.cbds_disabledOnMonday,'False'),
				@bitDisabledOnTue	= ISNULL(tcbs.cbds_disabledOnTuesday,'False'),
				@bitDisabledOnWed	= ISNULL(tcbs.cbds_disabledOnWednesday,'False'),
				@bitDisabledOnThu	= ISNULL(tcbs.cbds_disabledOnThursday,'False'),
				@bitDisabledOnFri	= ISNULL(tcbs.cbds_disabledOnFriday,'False'),
				@bitDisabledOnSat	= ISNULL(tcbs.cbds_disabledOnSaturday,'False')
		FROM	tbCheckBoard_Schedule tcbs
		WHERE	tcbs.comp_id = @comp_id AND
				tcbs.cbds_id = @cbds_id


	-- ----------------------------------------------------------------
	-- Calcula la fecha y hora en que deberia comenzar a re-calcularse
	-- ----------------------------------------------------------------
	-- Ya viene filtrado si se deshabilita x dia de semana
	-- ----------------------------------------------------------------
	IF @intTypeOfSchedule = 1		-- Diariamente
		BEGIN
			-- Dia de hoy con hora 00:00:00
			SET @datDateOfExecution = dbo.fnGetEnd_or_BeginOfDate(@datDateOfExecution, 'False')
			-- Sumo las Horas   Necesarias
			SET @datDateOfExecution = DATEADD(hour,@intHours, @datDateOfExecution)
			-- Sumo los Minutos Necesarios
			SET @datDateOfExecution = DATEADD(minute,@intMinutes, @datDateOfExecution)
		END
	ELSE IF @intTypeOfSchedule = 2	-- Semanalmente
		BEGIN
			-- Dia de hoy con hora 00:00:00
			SET @datDateOfExecution = dbo.fnGetEnd_or_BeginOfDate(@datDateOfExecution, 'False')
			-- Sumo las Horas   Necesarias
			SET @datDateOfExecution = DATEADD(hour,@intHours, @datDateOfExecution)
			-- Sumo los Minutos Necesarios
			SET @datDateOfExecution = DATEADD(minute,@intMinutes, @datDateOfExecution)
		END
	ELSE IF @intTypeOfSchedule = 3	-- Mensualmente
		BEGIN
			-- Primer dia del mes actual
			SET @datDateOfExecution = DATEADD(dd, -DAY(@datDateOfExecution) + 1, @datDateOfExecution)
			--			DECLARE @intLastDayOfActualMonth AS INT
			--			SET		@intLastDayOfActualMonth = DATEADD(dd, -DAY(DATEADD(mm, 1, GETDATE())), DATEADD(mm, 1, GETDATE()))
			-- Suma los dias correspondientes
			SET @datDateOfExecution = DATEADD(day,@intDay - 1, @datDateOfExecution)

			-- Dia de hoy con hora 00:00:00
			SET @datDateOfExecution = dbo.fnGetEnd_or_BeginOfDate(@datDateOfExecution, 'False')
			-- Sumo las Horas   Necesarias
			SET @datDateOfExecution = DATEADD(hour,@intHours, @datDateOfExecution)
			-- Sumo los Minutos Necesarios
			SET @datDateOfExecution = DATEADD(minute,@intMinutes, @datDateOfExecution)
		END
	ELSE IF @intTypeOfSchedule	= 4 -- Anualmente
		BEGIN
			-- Primer Dia del Año Actual
			SET @datDateOfExecution = DATEADD(yy, DATEDIFF(yy,0,getdate()), 0)
			-- Sumo los Meses
			SET @datDateOfExecution = DATEADD(MONTH,@intMonth - 1, @datDateOfExecution)
			-- Sumo los Dias del Mes
			SET @datDateOfExecution = DATEADD(day,@intDay - 1, @datDateOfExecution)
			-- Dia de hoy con hora 00:00:00
			SET @datDateOfExecution = dbo.fnGetEnd_or_BeginOfDate(@datDateOfExecution, 'False')
			-- Sumo las Horas   Necesarias
			SET @datDateOfExecution = DATEADD(hour,@intHours, @datDateOfExecution)
			-- Sumo los Minutos Necesarios
			SET @datDateOfExecution = DATEADD(minute,@intMinutes, @datDateOfExecution)
			-- Si No es el año actual y es diferente a Cero, cancela
			IF 	DATEPART(yyyy,GETDATE()) <> @intYear AND @intYear <> 0
				BEGIN
					SET @datDateOfExecution = DATEADD(year,2000, @datDateOfExecution)
				END
		END
	ELSE
		BEGIN
			SET @datDateOfExecution = DATEADD(year,2000, @datDateOfExecution)
		END


	RETURN @datDateOfExecution

END
GO




