	ELSE
		BEGIN
			SET @datDateOfExecution = DATEADD(year,2000, @datDateOfExecution)
		END


	RETURN @datDateOfExecution

END
GO


CREATE FUNCTION [dbo].[fnChecksum4Image]
(
	@Data IMAGE
)
RETURNS INT
AS

BEGIN
	DECLARE	@Index INT,
		@MaxIndex INT,
		@SUM BIGINT,
		@Overflow TINYINT

	SELECT	@Index = 1,
		@MaxIndex = DATALENGTH(@Data),
		@SUM = 0

	WHILE @Index <= @MaxIndex
		SELECT	@SUM = (16 * @SUM) ^ SUBSTRING(@Data, @Index, 1),
			@Overflow = @SUM / 4294967296,
			@SUM = @SUM - @Overflow * 4294967296,
			@SUM = @SUM ^ @Overflow,
			@Index = @Index + 200

	IF @SUM > 2147483647
		SET	@SUM = @SUM - 4294967296
	ELSE IF @SUM BETWEEN 32768 AND 65535
		SET	@SUM = @SUM - 65536
	ELSE IF @SUM BETWEEN 128 AND 255
		SET	@SUM = @SUM - 256

	RETURN @SUM
END

GO



CREATE FUNCTION [dbo].fnChecksum4NText
(
	@Data NTEXT
)
RETURNS INT
AS

BEGIN
	DECLARE	@Index INT,
		@MaxIndex INT,
		@SUM BIGINT,
		@Overflow TINYINT

	SELECT	@Index = 1,
		@MaxIndex = DATALENGTH(@Data),
		@SUM = 0

	WHILE @Index <= @MaxIndex
		SELECT	@SUM = (16 * @SUM) ^ ASCII(SUBSTRING(@Data, @Index, 1)),
			@Overflow = @SUM / 4294967296,
			@SUM = @SUM - @Overflow * 4294967296,
			@SUM = @SUM ^ @Overflow,
			@Index = @Index + 1

	IF @SUM > 2147483647
		SET	@SUM = @SUM - 4294967296
	ELSE IF @SUM BETWEEN 32768 AND 65535
		SET	@SUM = @SUM - 65536
	ELSE IF @SUM BETWEEN 128 AND 255
		SET	@SUM = @SUM - 256

	RETURN	@SUM
END
GO





-- =============================================
-- Author:		mos
-- Create date: 10-2010
-- Description:	Retorna la cuenta bancaria
-- =============================================
CREATE FUNCTION [dbo].[fnChequePortfolioPayToBanking]
(
	@comp_id	AS INT,
	@chp_id		AS INT
)
RETURNS VARCHAR(MAX)
AS
BEGIN

	DECLARE @strReturn AS VARCHAR(200)

	SELECT  Top 1 @strReturn = tba.ba_desc
	  FROM tbCheckPortfolioMovements tcpm				WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions tct			WITH (NOLOCK)
		ON	tct.comp_id				= tcpm.comp_id
			AND tct.bra_id			= tcpm.bra_id
			and tct.ct_transaction	= tcpm.ct_transaction

		INNER JOIN tbBankingTransactions tbt			WITH (NOLOCK)
		ON tbt.comp_id = tcpm.comp_id
			AND tbt.ba_id = tcpm.ba_id
			AND tbt.bt_id = tcpm.bt_id

		left JOIN tbBankingAccounts tba					WITH (NOLOCK)
		ON tba.comp_id = tbt.comp_id
			AND tba.ba_id = tbt.ba_id


	WHERE	tcpm.comp_id	= @comp_id
		AND tcpm.chp_id		= @chp_id
		and not tbt.bt_id IS NULL
	ORDER BY tcpm.ct_transaction		DESC

	RETURN IsNull(@strReturn,'')

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 10-2010
-- Description:	Retorna el Proveedor al que se le pago con un cheque dado
-- =============================================
CREATE FUNCTION [dbo].[fnChequePortfolioPayToSupplier]
(
	@comp_id	AS INT,
	@chp_id		AS INT
)
RETURNS VARCHAR(MAX)
AS
BEGIN

	DECLARE @strReturn AS VARCHAR(200)

	SELECT  Top 1 @strReturn = '(' + CONVERT(VARCHAR(10),ts.supp_id) + ') ' + ts.supp_name
	  FROM tbCheckPortfolioMovements tcpm
		INNER JOIN tbCommercialTransactions tct
		ON	tct.comp_id				= tcpm.comp_id
			AND tct.bra_id			= tcpm.bra_id
			and tct.ct_transaction	= tcpm.ct_transaction
		INNER JOIN tbSupplier ts
			ON		ts.comp_id = tct.comp_id
				AND ts.supp_id = tct.supp_id
	WHERE	tcpm.comp_id	= @comp_id
		AND tcpm.chp_id		= @chp_id
		and not tct.supp_id IS NULL
	ORDER BY tcpm.ct_transaction		DESC

	RETURN IsNull(@strReturn,'')

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 10-2010
-- Description:	Retorna el Proveedor al que se le pago con un cheque dado
-- =============================================
create FUNCTION [dbo].[fnChequePortfolioPayToSupplierId]
(
	@comp_id	AS INT,
	@chp_id		AS INT
)
RETURNS integer
AS
BEGIN

	DECLARE @intReturn AS integer

	SELECT  Top 1 @intReturn = tct.supp_id
	  FROM tbCheckPortfolioMovements tcpm
		INNER JOIN tbCommercialTransactions tct
		ON	tct.comp_id				= tcpm.comp_id
			AND tct.bra_id			= tcpm.bra_id
			and tct.ct_transaction	= tcpm.ct_transaction
	WHERE	tcpm.comp_id	= @comp_id
		AND tcpm.chp_id		= @chp_id
		and not tct.supp_id IS NULL
	ORDER BY tcpm.ct_transaction		DESC

	RETURN IsNull(@intReturn,0)

END
GO




