-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	retorna el Codigo de los SP
--				que se usan para los indicadores
--				del Panel de Control.-
--
--				ATENCION.!!!!
--				Se debera respetar la estructura
--				de los SP, poniendo el CODIGO
--				Dentro de los comentarios:
--
--				--BeginControlPanelSqlCode--
--        y     --EndControlPanelSqlCode--
-- =============================================
CREATE FUNCTION fnControlPanelGetSPCode
(
	@SPName AS VARCHAR(2000)			-- Nombre del ControlPanel Stored Procedure
)
RETURNS VARCHAR(MAX)
AS
BEGIN

	DECLARE @cTextoOutput AS VARCHAR(MAX)
	DECLARE @intFrom	  AS INT
	DECLARE @intTo		  AS INT

	Select @cTextoOutput = text from syscomments where id=object_id(@SPName)
	SELECT @intFrom = CHARINDEX('--BeginControlPanelSqlCode--',@cTextoOutput,0) + 29
	SELECT @intTo   = CHARINDEX('--EndControlPanelSqlCode--',@cTextoOutput,0)

	SELECT @cTextoOutput = RTrim(LTrim(SUBSTRING(@cTextoOutput,@intFrom,@intTo - @intFrom)))

	RETURN @cTextoOutput

END
GO

CREATE FUNCTION [dbo].[fnConvertBase64ToString]
(
    @Input_Base64_Value VARCHAR(MAX)
)
RETURNS VARCHAR(MAX)
AS
BEGIN
    RETURN (
		SELECT
			CAST(
                CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@Input_Base64_Value"))', 'VARBINARY(MAX)')
            AS VARCHAR(MAX)
            ) AS RetVal
    )
END
GO

CREATE FUNCTION [dbo].[fnConvertStringToBase64]
(
    @InputString VARCHAR(MAX)
)
RETURNS VARCHAR(MAX)
AS
BEGIN
    RETURN (
		SELECT
			CAST(N'' AS XML).value(
                  'xs:base64Binary(xs:hexBinary(sql:column("bin")))'
                , 'VARCHAR(MAX)'
            )
        FROM (
            SELECT CAST(@InputString AS VARBINARY(MAX)) AS bin
        ) AS RetVal
    )
END;
GO





