CREATE FUNCTION [dbo].[fnCreditQuoteInfo]
(
	@intComp_id						AS INT,
	@intBraId						AS INT,
	@st_id							AS INT,
	@intItemId						AS INT,
	@decPrice						AS DECIMAL(19,4),
	@intQuoteQty					AS INT,
	@intQuoteNumber					AS INT,
	@datFirstPay					AS DATETIME,
	@intDayOfPay					AS INT,
	@decAdvanceOfPay				AS DECIMAL(19,4),
	@bitPriceListNOPublication		AS BIT	,		-- Si esta enb TRUE NO debe tener en cuenta las publicaciones
	@bitOverRidesCreditData			AS BIT,
	@creditI_up2Pays				AS INT,
	@creditI_creditInterest			AS DECIMAL(19,8),
	@creditII_up2Pays				AS INT,
	@creditII_creditInterest		AS DECIMAL(19,8),
	@creditIII_up2Pays				AS INT,
	@creditIII_creditInterest		AS DECIMAL(19,8),
	@creditIV_up2Pays				AS INT,
	@creditIV_creditInterest		AS DECIMAL(19,8),
	@creditOther_creditInterest		AS DECIMAL(19,8),
	@CreditQuotaQtyMaximum			AS INT
)
RETURNS

	@CreditCuote TABLE
	(
		InitialPrice					DECIMAL(19,5) NULL,
		Total							decimal(19,5) NULL,
		AdvanceOfPay					decimal(19,5) NULL,
		CreditQuote						decimal(19,5) NULL,
		QuotePercent					decimal(19,5) NULL,
		CreditPercent					decimal(19,5) NULL,
		DateOfFirstPayment				DATETIME,
		DateOfQuotePayment				DATETIME,
		creditI_up2Pays					INT,
		creditI_creditInterest			DECIMAL(19,8),
		creditII_up2Pays				INT,
		creditII_creditInterest			DECIMAL(19,8),
		creditIII_up2Pays				INT,
		creditIII_creditInterest		DECIMAL(19,8),
		creditIV_up2Pays				INT,
		creditIV_creditInterest			DECIMAL(19,8),
		creditOther_creditInterest		DECIMAL(19,8),
		CreditQuotaQtyMaximum			INT,
		IsPublication					BIT,
		PublicationName					NVARCHAR(200),
		CreditQuoteNoRounded			DECIMAL(19,5),
		credit_creditInterest			DECIMAL(19,5)

	)


AS





BEGIN





	-- ----------------------------------------------------------
	-- Testing
	-- ----------------------------------------------------------
	/*

	SET DATEFORMAT 'ymd'

	DECLARE
	@intComp_id						AS INT,
	@intBraId						AS INT,
	@st_id							AS INT,
	@intItemId						AS INT,
	@decPrice						AS DECIMAL(19,4),
	@intQuoteQty					AS INT,
	@intQuoteNumber					AS INT,
	@datFirstPay					AS DATETIME,
	@intDayOfPay					AS INT,
	@decAdvanceOfPay				AS DECIMAL(19,4),
	@bitPriceListNOPublication		AS BIT	,		-- Si esta enb TRUE NO debe tener en cuenta las publicaciones
	@bitOverRidesCreditData			AS BIT,
	@creditI_up2Pays				AS INT,
	@creditI_creditInterest			AS DECIMAL(19,8),
	@creditII_up2Pays				AS INT,
	@creditII_creditInterest		AS DECIMAL(19,8),
	@creditIII_up2Pays				AS INT,
	@creditIII_creditInterest		AS DECIMAL(19,8),
	@creditIV_up2Pays				AS INT,
	@creditIV_creditInterest		AS DECIMAL(19,8),
	@creditOther_creditInterest		AS DECIMAL(19,8),
	@CreditQuotaQtyMaximum			AS INT


	declare 	@CreditCuote TABLE
	(
		InitialPrice					DECIMAL(19,5) NULL,
		Total							decimal(19,5) NULL,
		AdvanceOfPay					decimal(19,5) NULL,
		CreditQuote						decimal(19,5) NULL,
		QuotePercent					decimal(19,5) NULL,
		CreditPercent					decimal(19,5) NULL,
		DateOfFirstPayment				DATETIME,
		DateOfQuotePayment				DATETIME,
		creditI_up2Pays					INT,
		creditI_creditInterest			DECIMAL(19,8),
		creditII_up2Pays				INT,
		creditII_creditInterest			DECIMAL(19,8),
		creditIII_up2Pays				INT,
		creditIII_creditInterest		DECIMAL(19,8),
		creditIV_up2Pays				INT,
		creditIV_creditInterest			DECIMAL(19,8),
		creditOther_creditInterest		DECIMAL(19,8),
		CreditQuotaQtyMaximum			INT,
		IsPublication					BIT,
		PublicationName					NVARCHAR(200),
		CreditQuoteNoRounded			DECIMAL(19,5),
		credit_creditInterest			DECIMAL(19,5)
	)

	SET @intComp_id						= 1
	SET @intBraId						= 1
	SET @st_id							= 20
	SET @intItemId						= 109328
	SET @decPrice						= 10000
	SET @intQuoteQty					= 8
	SET @intQuoteNumber					= 1
	SET @datFirstPay					= '2016-01-09'
	SET @intDayOfPay					= 8
	SET @decAdvanceOfPay				= 2000
	SET @bitPriceListNOPublication		= 'False'
	SET @bitOverRidesCreditData			= 'False'
	SET @creditI_up2Pays				= 0
	SET @creditI_creditInterest			= 0
	SET @creditII_up2Pays				= 0
	SET @creditII_creditInterest		= 0
	SET @creditIII_up2Pays				= 0
	SET @creditIII_creditInterest		= 0
	SET @creditIV_up2Pays				= 0
	SET @creditIV_creditInterest		= 0
	SET @creditOther_creditInterest		= 0
	SET @CreditQuotaQtyMaximum			= 10

	*/
	-- ----------------------------------------------------------











	IF @bitOverRidesCreditData IS NULL SET @bitOverRidesCreditData = 'False'


	-- Se usa como truco para no tener que pasar mas parametros x todos lados
	-- mandar la cond de venta en negativo si se requiere que el interes sea 0
	DECLARE @bitUSE_CeroPercent AS BIT
	DECLARE @intRoundMode		AS INT
	SET		@intRoundMode		= 1
	SET @bitUSE_CeroPercent = 'False'
	IF @st_id < 0
		BEGIN
			SET @st_id = @st_id * -1
			SET @bitUSE_CeroPercent = 'True'
			SET @intRoundMode		= 2
		END
	--



	DECLARE @sct_id						AS INT

	SET @datFirstPay = dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'False')

	DECLARE @decTotalPaymentQuote AS DECIMAL(19,4)
	SET		@decTotalPaymentQuote = 0

	DECLARE @decTasa					AS DECIMAL(19,8)

	DECLARE @datProcessingDate          AS DATETIME
	DECLARE @intDayOfMonth4BeginPaying  AS INT

	DECLARE @prli_id					AS INT
	DECLARE @bitIsPublication			AS BIT
	DECLARE @strPublicationName			AS NVARCHAR(200)

	SET		@bitIsPublication		= 'False'


	SELECT	@datProcessingDate	= tb.bra_processingDate,
			@prli_id			= IsNull(tb.prli_id4Credit,-1),
			@st_id				= ISNULL(@st_id,tb.st_id4Loan)		-- Si viene en NULL pone la de la sucursal que JAMAS estará en NULL
		FROM dbo.tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id		= @intComp_id AND
				tb.bra_id		= @intBraId


	-- ----------------------------------------------------------------------------------------------------
	-- ATENCION!!!
	-- Si es a#o bisiesto hace que NO SUME dos meses x lo que indica Restar UNO en lugar de poner 1 o 0 !!!
	-- ----------------------------------------------------------------------------------------------------
	DECLARE @bitDiffer2NextMonthMinusONE as BIT
	SET		@bitDiffer2NextMonthMinusONE = 'False'
	IF MONTH(@datProcessingDate) = 2 and DAY(@datProcessingDate) = 29 AND @decAdvanceOfPay <> 0
		BEGIN
			SET @bitDiffer2NextMonthMinusONE = 'True'
		END
	-- ----------------------------------------------------------------------------------------------------


	---- Seteamos el dia de pago segun la cuota a informar requerida
	SET @intDayOfMonth4BeginPaying = @intDayOfPay


	-- Guarda el % forzado de tada para el calculo de cumplirse esa condicion.
	DECLARE @decOriginal_creditI_up2Pays AS DECIMAL(19,8)
	SET		@decOriginal_creditI_up2Pays = @creditI_creditInterest




	-- Obtenemos la tasa del credito segun la cantidad de cuotas informada
	SELECT
			@sct_id			 =				IsNull(tst.sct_id,0),
			@creditI_up2Pays =				CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditI_up2Pays
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditI_up2Pays
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditI_up2Pays
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditI_up2Pays
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditI_up2Pays
												ELSE																							tb.creditI_up2Pays
											END,

			@creditI_creditInterest =		CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditI_creditInterest
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditI_creditInterest
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditI_creditInterest
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditI_creditInterest
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditI_creditInterest
												ELSE																							tb.creditI_creditInterest
											END,
			@creditII_up2Pays =				CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditII_up2Pays
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditII_up2Pays
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditII_up2Pays
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditII_up2Pays
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditII_up2Pays
												ELSE																							tb.creditII_up2Pays
											END,
			@creditII_creditInterest =		CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditII_creditInterest
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditII_creditInterest
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditII_creditInterest
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditII_creditInterest
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditII_creditInterest
												ELSE												tb.creditII_creditInterest
											END,
			@creditIII_up2Pays =			CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditIII_up2Pays
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditIII_up2Pays
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditIII_up2Pays
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditIII_up2Pays
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditIII_up2Pays
												ELSE												tb.creditIII_up2Pays
											END,
			@creditIII_creditInterest =		CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditIII_creditInterest
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditIII_creditInterest
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditIII_creditInterest
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditIII_creditInterest
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditIII_creditInterest
												ELSE												tb.creditIII_creditInterest
											END,
			@creditIV_up2Pays =				CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditIV_up2Pays
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditIV_up2Pays
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditIV_up2Pays
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditIV_up2Pays
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditIV_up2Pays
												ELSE																							tb.creditIV_up2Pays
											END,
			@creditIV_creditInterest =		CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditIV_creditInterest
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditIV_creditInterest
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	tipd.creditIV_creditInterest
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditIV_creditInterest
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditIV_creditInterest
												ELSE																							tb.creditIV_creditInterest
											END,
			@creditOther_creditInterest =	CASE
												WHEN	tst.creditReplaceInterestMasterOption = 'True'									THEN	tst.creditOther_creditInterest
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@creditOther_creditInterest
												WHEN	tst.creditReplaceInterest = 'True'												THEN	tst.creditOther_creditInterest
												WHEN	ti.creditReplaceInterest  = 'True'												THEN	ti.creditOther_creditInterest
												ELSE																							tb.creditOther_creditInterest
											END	,
			@CreditQuotaQtyMaximum		=	CASE
												WHEN	@bitOverRidesCreditData   = 'True'												THEN	@CreditQuotaQtyMaximum
												WHEN    tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN    tipd.CreditQuotaQtyMaximum
												WHEN	ti.creditReplaceInterest = 'True' AND	-- MOS 12-2023 x ticket 20442 de Authogar
														ti.CreditQuotaQtyMaximum > 0													THEN	ti.CreditQuotaQtyMaximum
												WHEN    ti.CreditQuotaQtyMaximum > 0			-- MOS 09-2024 x GrupoHogar ya que arriba se agrego x AUT ti.creditReplaceInterest = 'True'
																																		THEN	ti.CreditQuotaQtyMaximum
												ELSE																							ISNULL(tb.CreditQuotaQtyMaximum,0)
											END	,
			@bitIsPublication			=	CASE
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN	'True'
												ELSE												'False'
											END		,
			@strPublicationName			=	CASE
												WHEN	tipd.comp_id IS NOT NULL AND @bitPriceListNOPublication = 'False'				THEN tiph.pubh_desc
												ELSE											 ''
											END
		FROM dbo.tbItem ti							WITH (NOLOCK)
		INNER JOIN dbo.tbBrand tb					WITH (NOLOCK)
			ON	tb.comp_id	 = ti.comp_id AND
				tb.brand_id  = ti.brand_id
		INNER JOIN dbo.tbSalesTerms tst				WITH (NOLOCK)
			ON	tst.comp_id  = @intComp_id  AND
				tst.st_id	 = @st_id
		-- MOS 21-12-2015
		--LEFT JOIN tbPriceListItems tpli			WITH (NOLOCK)
		--	ON	tpli.comp_id = ti.comp_id AND
		--		tpli.item_id = ti.item_id AND
		--		tpli.prli_id = @prli_id
		LEFT JOIN dbo.vwPriceListItems vpli			WITH (NOLOCK)
			ON	vpli.comp_id = ti.comp_id AND
				vpli.item_id = ti.item_id AND
				vpli.prli_id = @prli_id
		LEFT JOIN dbo.tbItemPublicationDetail tipd	WITH (NOLOCK)
			ON	tipd.comp_id = vpli.comp_id	AND
				tipd.pubh_id = vpli.pubh_id AND
				tipd.pubd_id = vpli.pubd_id
		LEFT JOIN dbo.tbItemPublicationHeader tiph	WITH (NOLOCK)
			ON	tiph.comp_id = vpli.comp_id AND
				tiph.pubh_id = vpli.pubh_id
		WHERE	ti.comp_id	 = @intComp_id AND
				ti.item_id	 = @intItemId

	SET @creditOther_creditInterest = ISNULL(@creditOther_creditInterest,0)

	SET @decTasa =
					CASE
						WHEN @intQuoteQty <= @creditI_up2Pays	THEN	@creditI_creditInterest
						WHEN @intQuoteQty <= @creditII_up2Pays	THEN	@creditII_creditInterest
						WHEN @intQuoteQty <= @creditIII_up2Pays	THEN	@creditIII_creditInterest
						WHEN @intQuoteQty <= @creditIV_up2Pays	THEN	@creditIV_creditInterest
						ELSE											@creditOther_creditInterest
					END
	SET @decTasa = ISNULL(@decTasa,0)


	IF	@bitOverRidesCreditData = 'True' AND
		@creditI_up2Pays		= -1
		BEGIN
			SET @decTasa = @decOriginal_creditI_up2Pays
		END




	-- Se usa en Financiación de Ventas de Terceros.-
	IF @bitUSE_CeroPercent = 'True'
		BEGIN
			SET @decTasa = 0
		END



	DECLARE @decAuxValue1 AS DECIMAL(19,8)
	DECLARE @decAuxValue2 AS DECIMAL(19,8)
	DECLARE @decAuxTasa   AS DECIMAL(19,8)


	-- TRUNCA A DOS DECIMALES!!!!
	SET @decPrice = ROUND(@decPrice,2,2)





	-- ---------------------------------------
	-- Fecha diferida si tiene anticipo
	-- Si la fecha de hoy es 26-08 y quiero que pague los dias 5 la cuota 0 es el 26-8 y la 1 es el 5-10
	-- ---------------------------------------
	DECLARE @intDiffer2NextMonth AS INT
	DECLARE @datTempDate AS DATETIME
	SET		@intDiffer2NextMonth = 0
	IF (@sct_id = 1 OR @sct_id = 3 OR @sct_id = 4)
		BEGIN
			IF @intQuoteNumber = 1 SET @intDayOfMonth4BeginPaying = DAY(@datFirstPay)
			IF @intQuoteNumber > 1
			BEGIN
				SET		@datTempDate = 	DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
										DATEADD(MONTH, /* Cuota UNO */ 1  ,
												DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
										   )   )
				DECLARE @intDaysOfThisMonth AS INT
				SET		@intDaysOfThisMonth = DATEPART(DAY, DATEADD(s,-1,DATEADD(mm, DATEDIFF(m,0,@datTempDate)+1,0)))
				IF DATEDIFF(DAY,@datFirstPay,@datTempDate) < (@intDaysOfThisMonth-4) --28
					BEGIN
						SET @intDiffer2NextMonth = 1
					END
			END

		END

	ELSE IF (@sct_id = 2 OR @sct_id = 4) --AND 1 = 2
		BEGIN
			IF @decAdvanceOfPay <> 0	-- Si tiene Anticipo
				BEGIN
					SET		@datTempDate = 	DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
											DATEADD(MONTH, /* Cuota UNO */ 1  ,
													DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
											   )   )
					DECLARE @intDaysOfThisMonth2 AS INT
					SET		@intDaysOfThisMonth2 = DATEPART(DAY, DATEADD(s,-1,DATEADD(mm, DATEDIFF(m,0,@datTempDate)+1,0)))

					IF DATEDIFF(DAY,@datFirstPay,@datTempDate) < (@intDaysOfThisMonth2 - 4) --pARA Q NO JODA ENTRE LOS MESES DE 31,30,29,28
						BEGIN
							SET @intDiffer2NextMonth = 1
						END
				END
		END
	-- ---------------------------------------


	IF @bitDiffer2NextMonthMinusONE = 'True'	SET @intDiffer2NextMonth = -1



	DECLARE @decNoRoundedQuote AS DECIMAL(29,4)
	SET		@decNoRoundedQuote = 0

	DECLARE @tmpQuoteDay AS DATETIME = @datFirstPay  -- MOS 08-2024 x Auth

	IF @sct_id = 1 -- Cuenta Corriente, Cuotas Iguales
		BEGIN
			SET @decAuxValue1 = @decPrice / dbo.fnNoZDiv(@intQuoteQty)			--33.33
			SET @decAuxValue2 = @decPrice - @decAuxValue1						--66.66
			SET @decAuxTasa   = @decTasa * (@intQuoteQty - 1)					--8
			SET @decAuxValue2 = @decAuxValue2 * ((@decAuxTasa / 100) + 1)		--71.99
			SET @decAuxValue2 = @decAuxValue2 + @decAuxValue1					--105.32
			SET @decAuxValue2 = @decAuxValue2 / dbo.fnNoZDiv(@intQuoteQty)		--35.1
			SET @decNoRoundedQuote = @decAuxValue2
			SET @decAuxValue2 = dbo.fnRoundQuote(@decAuxValue2,	CASE
																	WHEN @intRoundMode = 2 THEN 2  -- Si es Financiacion de terceros lo mantengo, sino va siempre 1
																	ELSE						3
																END)

			-- ---------------------------------------------------------
			-- MOS 08-2024: Auth le calculaba mal la fecha en dias de fin de mes.
			-- ---------------------------------------------------------
			SET @tmpQuoteDay = DATEADD(MONTH,	@intQuoteNumber - 1 /*- 1  + @intDiffer2NextMonth*/,@datFirstPay)
			SET @tmpQuoteDay = DATEFROMPARTS(YEAR(@tmpQuoteDay), MONTH(@tmpQuoteDay), @intDayOfMonth4BeginPaying)
			-- ---------------------------------------------------------


			INSERT INTO @CreditCuote(   InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest )
								VALUES( @decPrice,
										@decAuxValue2 * @intQuoteQty,
										@decAdvanceOfPay,
										@decAuxValue2,
										@decTasa,
										@decAuxTasa,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										@tmpQuoteDay
										--DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
										--	DATEADD(MONTH, @intQuoteNumber - 1 + @intDiffer2NextMonth,
										--			DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
										--	   )   )
															,'True'),
										@decNoRoundedQuote,
										@decTasa
								      )
		END
	ELSE IF @sct_id = 2 -- Anticipo y Cuotas (Anticipo Prorrateado entre los articulos del pedido)
		BEGIN
			--SET @decAuxValue1 = @decPrice / dbo.fnNoZDiv(@intQuoteQty)
			SET @decAuxValue2 = @decPrice - @decAdvanceOfPay
			SET @decAuxTasa   = @decTasa * (@intQuoteQty)
			SET @decAuxValue2 = @decAuxValue2 * ((@decAuxTasa / 100) + 1)
			--SET @decAuxValue2 = @decAuxValue2 + @decAuxValue1
			SET @decAuxValue2 = @decAuxValue2 / dbo.fnNoZDiv(@intQuoteQty)
			SET @decNoRoundedQuote = @decAuxValue2
			SET @decAuxValue2 = dbo.fnRoundQuote(@decAuxValue2,	CASE
																	WHEN @intRoundMode = 2 THEN 2  -- Si es Financiacion de terceros lo mantengo, sino va siempre 1
																	ELSE						3
																END)

			-- ---------------------------------------------------------
			-- MOS 08-2024: Auth le calculaba mal la fecha en dias de fin de mes.
			-- ---------------------------------------------------------
			SET @tmpQuoteDay = DATEADD(MONTH,	@intQuoteNumber /*- 1  + @intDiffer2NextMonth*/,@datFirstPay)
			SET @tmpQuoteDay = DATEFROMPARTS(YEAR(@tmpQuoteDay), MONTH(@tmpQuoteDay), @intDayOfMonth4BeginPaying)
			-- ---------------------------------------------------------

			INSERT INTO @CreditCuote(	InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest )
								VALUES( @decPrice,
									   (@decAuxValue2 * @intQuoteQty) + @decAdvanceOfPay,
										@decAdvanceOfPay,
										@decAuxValue2,
										@decTasa,
										@decAuxTasa,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										@tmpQuoteDay -- MOS 08-2024: Auth le calculaba mal la fecha en dias de fin de mes.
										--DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
										--	DATEADD(MONTH, @intQuoteNumber - 1 + @intDiffer2NextMonth ,
										--			DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
										--	   )   )
															,'True'),
										@decNoRoundedQuote,
										@decTasa
								      )
		END
	ELSE IF @sct_id = 3 -- Cuotas Iguales Sin Anticipo (Se puede diferir el anticipo sin interes hasta 10 dias de la fecha de la factura)
		BEGIN
			SET @decAuxValue1 = @decPrice / dbo.fnNoZDiv(@intQuoteQty)
			SET @decAuxValue2 = @decPrice - @decAuxValue1
			SET @decAuxTasa   = @decTasa * (@intQuoteQty - 1)
			SET @decAuxValue2 = @decAuxValue2 * ((@decAuxTasa / 100) + 1)
			SET @decAuxValue2 = @decAuxValue2 + @decAuxValue1
			SET @decAuxValue2 = @decAuxValue2 / dbo.fnNoZDiv(@intQuoteQty)
			SET @decNoRoundedQuote = @decAuxValue2
			SET @decAuxValue2 =  dbo.fnRoundQuote(@decAuxValue2,CASE
																	WHEN @intRoundMode = 2 THEN 2  -- Si es Financiacion de terceros lo mantengo, sino va siempre 1
																	ELSE						3
																END)


			INSERT INTO @CreditCuote(	InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest )
								VALUES( @decPrice,
										@decAuxValue2 * @intQuoteQty,
										@decAdvanceOfPay,
										@decAuxValue2,
										@decTasa,
										@decAuxTasa,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
											DATEADD(MONTH, @intQuoteNumber - 1 ,
													DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
											   )   )
															,'True'),
										@decNoRoundedQuote,
										@decTasa
								      )
		END

	ELSE IF @sct_id = 4 -- Anticipo Diferido
		BEGIN
			SET @decAdvanceOfPay = 0
			--SET @decAuxValue1 = @decPrice / dbo.fnNoZDiv(@intQuoteQty)
			SET @decAuxValue2 = @decPrice - @decAdvanceOfPay
			SET @decAuxTasa   = @decTasa * (@intQuoteQty)
			SET @decAuxValue2 = @decAuxValue2 * ((@decAuxTasa / 100) + 1)
			--SET @decAuxValue2 = @decAuxValue2 + @decAuxValue1
			SET @decAuxValue2 = @decAuxValue2 / dbo.fnNoZDiv(@intQuoteQty)
			SET @decNoRoundedQuote = @decAuxValue2
			SET @decAuxValue2 = dbo.fnRoundQuote(@decAuxValue2,	CASE
																	WHEN @intRoundMode = 2 THEN 2  -- Si es Financiacion de terceros lo mantengo, sino va siempre 1
																	ELSE						3
																END)

			INSERT INTO @CreditCuote(	InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest
									)
								VALUES( @decPrice,
									   (@decAuxValue2 * @intQuoteQty) + @decAdvanceOfPay,
										@decAdvanceOfPay,
										@decAuxValue2,
										@decTasa,
										@decAuxTasa,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
											DATEADD(MONTH, @intQuoteNumber - 1 + @intDiffer2NextMonth ,
													DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
											   )   )
															,'True'),
										@decNoRoundedQuote,
										@decTasa
								      )
		END



	-- SI NO HAY CREDITO, NO CALCULA INTERESES.!!!
	ELSE IF @sct_id = 5 OR @sct_id = 0
		BEGIN
			-- No se debe generar cuotas
			DECLARE @NoHagoNada AS integer


			INSERT INTO @CreditCuote(	InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest )
								VALUES( @decPrice,
									    @decPrice,
										0,
										@decPrice,
										0,
										0,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
											DATEADD(MONTH, @intQuoteNumber - 1 ,
													DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
											   )   )
															,'True'),
										@decPrice,
										0
								      )


		END

	ELSE IF @sct_id = 20 -- Cuotas con Interés desde la Primera Cuota
		BEGIN
			--SET @decAuxValue1 = @decPrice / dbo.fnNoZDiv(@intQuoteQty)
			SET @decAuxValue2 = @decPrice - @decAdvanceOfPay
			SET @decAuxTasa   = @decTasa * (@intQuoteQty)
			SET @decAuxValue2 = @decAuxValue2 * ((@decAuxTasa / 100) + 1)
			--SET @decAuxValue2 = @decAuxValue2 + @decAuxValue1
			SET @decAuxValue2 = @decAuxValue2 / dbo.fnNoZDiv(@intQuoteQty)
			SET @decNoRoundedQuote = @decAuxValue2
			SET @decAuxValue2 = dbo.fnRoundQuote(@decAuxValue2,@intRoundMode)


			-- ---------------------------------------------------------
			-- MOS 08-2024: Auth le calculaba mal la fecha en dias de fin de mes.
			-- ---------------------------------------------------------
			SET @tmpQuoteDay = DATEADD(MONTH,	@intQuoteNumber - 1 /*- 1  + @intDiffer2NextMonth*/,@datFirstPay)
			SET @tmpQuoteDay = DATEFROMPARTS(YEAR(@tmpQuoteDay), MONTH(@tmpQuoteDay), @intDayOfMonth4BeginPaying)
			-- ---------------------------------------------------------

			INSERT INTO @CreditCuote(	InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest )
								VALUES( @decPrice,
									   (@decAuxValue2 * @intQuoteQty) + @decAdvanceOfPay,
										@decAdvanceOfPay,
										@decAuxValue2,
										@decTasa,
										@decAuxTasa,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										@tmpQuoteDay	-- MOS 08-2024
										--DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
										--	DATEADD(MONTH, @intQuoteNumber - 1 ,
										--			DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
										--	   )   )
															,'True'),
										@decNoRoundedQuote,
										@decTasa
								      )
		END

	ELSE IF @sct_id = 21 -- Anticipo y Cuotas con Interés desde la Primera Cuota
		BEGIN
			SET @decAuxValue2 = @decPrice - @decAdvanceOfPay
			SET @decAuxTasa   = @decTasa * (@intQuoteQty)
			SET @decAuxValue2 = @decAuxValue2 * ((@decAuxTasa / 100) + 1)
			--SET @decAuxValue2 = @decAuxValue2 + @decAuxValue1
			SET @decAuxValue2 = @decAuxValue2 / dbo.fnNoZDiv(@intQuoteQty)
			SET @decNoRoundedQuote = @decAuxValue2
			SET @decAuxValue2 = dbo.fnRoundQuote(@decAuxValue2,@intRoundMode)


			-- ---------------------------------------------------------
			-- MOS 08-2024: Auth le calculaba mal la fecha en dias de fin de mes.
			-- ---------------------------------------------------------
			SET @tmpQuoteDay = DATEADD(MONTH,	@intQuoteNumber /*- 1  + @intDiffer2NextMonth*/,@datFirstPay)
			SET @tmpQuoteDay = DATEFROMPARTS(YEAR(@tmpQuoteDay), MONTH(@tmpQuoteDay), @intDayOfMonth4BeginPaying)
			-- ---------------------------------------------------------

			INSERT INTO @CreditCuote(	InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest )
								VALUES( @decPrice,
									   (@decAuxValue2 * @intQuoteQty) + @decAdvanceOfPay,
										@decAdvanceOfPay,
										@decAuxValue2,
										@decTasa,
										@decAuxTasa,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										@tmpQuoteDay -- MOS 08-2024
										--DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
										--	DATEADD(MONTH, @intQuoteNumber - 1 ,
										--			DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
										--	   )   )
															,'True'),
										@decNoRoundedQuote,
										@decTasa
								      )
		END

	ELSE IF @sct_id = 25 -- 25- Cuotas con Interés ANUAL Directo ( Tasa * 12 )
		BEGIN
			SET @decAuxValue2 = @decPrice - @decAdvanceOfPay
			SET @decAuxTasa   = @decTasa * 12 -- para llevar a Tasa ANUAL Directa
			SET @decAuxValue2 = @decAuxValue2 * ((@decAuxTasa / 100) + 1)
			--SET @decAuxValue2 = @decAuxValue2 + @decAuxValue1
			SET @decAuxValue2 = @decAuxValue2 / dbo.fnNoZDiv(@intQuoteQty)
			SET @decNoRoundedQuote = @decAuxValue2
			SET @decAuxValue2 = dbo.fnRoundQuote(@decAuxValue2,@intRoundMode)

			INSERT INTO @CreditCuote(	InitialPrice,
										Total,
										AdvanceOfPay,
										CreditQuote,
										QuotePercent,
										CreditPercent,
										DateOfFirstPayment,
										DateOfQuotePayment,
										CreditQuoteNoRounded,
										credit_creditInterest )
								VALUES( @decPrice,
									   (@decAuxValue2 * @intQuoteQty) + @decAdvanceOfPay,
										@decAdvanceOfPay,
										@decAuxValue2,
										@decTasa,
										@decAuxTasa,
										dbo.fnGetEnd_or_BeginOfDate(@datFirstPay,'True'),
										dbo.fnGetEnd_or_BeginOfDate(
										DATEADD(DAY, @intDayOfMonth4BeginPaying - 1,
											DATEADD(MONTH, @intQuoteNumber - 1 ,
													DATEADD(MONTH, DATEDIFF(MONTH, 0, @datFirstPay), 0)
											   )   )
															,'True'),
										@decNoRoundedQuote,
										@decTasa
								      )
		END




	-- FIN IF ------------------------------------------------------


	UPDATE @CreditCuote
		SET creditI_up2Pays				= @creditI_up2Pays,
			creditI_creditInterest		= @creditI_creditInterest,
			creditII_up2Pays			= @creditII_up2Pays,
			creditII_creditInterest		= @creditII_creditInterest,
			creditIII_up2Pays			= @creditIII_up2Pays,
			creditIII_creditInterest	= @creditIII_creditInterest,
			creditIV_up2Pays			= @creditIV_up2Pays,
			creditIV_creditInterest		= @creditIV_creditInterest,
			creditOther_creditInterest	= @creditOther_creditInterest,
			CreditQuotaQtyMaximum		= @CreditQuotaQtyMaximum,
			IsPublication				= @bitIsPublication,
			PublicationName				= @strPublicationName


	RETURN

END
GO




-- ----------------
-- STL
-- ----------------
CREATE FUNCTION [dbo].[fnCRM_GetCustomerEmailByCallType]
(
	@comp_id	int,
	@cust_id	int,
	@callt_id	INT,
	@callst_id	INT,
	@call_id	INT,
	@user_id	INT
)



RETURNS NVARCHAR(MAX)
AS

BEGIN

	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
	/*
		declare			@comp_id	int,
						@cust_id	int,
						@callst_id	int,
						@callt_id	int
		select			@comp_id	=1,
						@cust_id	=24294,
						@callst_id	=1,
						@callt_id	=1
	*/
	-- ---------------------------------------------------


	-- ---------------------------------------------
	-- Adicionales
	-- ---------------------------------------------
	DECLARE @strEMail		AS NVARCHAR(MAX)
	DECLARE @strCC			AS NVARCHAR(MAX)
	DECLARE @strUserMail	AS NVARCHAR(MAX)

	SET @strEMail		= ''
	SET @strCC			= ''
	SET @strUserMail	= ''



	-- ---------------------------------------------
	-- Mail al Usuario
	-- ---------------------------------------------
	SELECT  @strUserMail = dbo.fnstrEmailCheck(tu.user_email)
		FROM tbCRM_Call					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_CallType		tctt								WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.Callt_id				= @Callt_id		AND
				tctt.callt_eMail2User   	= 'True'
		INNER JOIN tbCRM_CallStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.callst_id				= @callst_id    AND
				tcts.callst_eMail2User      = 'True'
		INNER JOIN tbUser tu												WITH (NOLOCK)
			ON tu.[user_id] = tct.[user_id]
		WHERE	tct.comp_id = @comp_id AND
				tct.Call_id = @Call_id
	-- ---------------------------------------------




	DECLARE @strEMailCustomer	AS NVARCHAR(MAX)
	DECLARE @strEMailCompras	AS NVARCHAR(MAX)
	DECLARE @bitAddAlternative	AS BIT
	SET		@strEMailCustomer	= ''
	SELECT @strEMailCustomer	= '' +
							CASE
							    WHEN	tcct.callt_mail2Customer			= 'True' AND
										tcct.callt_mail2Customer_Tipe_1		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.callt_mail2Customer			= 'True' AND
										tcct.callt_mail2Customer_Tipe_2		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Payments)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.callt_mail2Customer			= 'True' AND
										tcct.callt_mail2Customer_Tipe_3		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Management)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.callt_mail2Customer			= 'True' AND
										tcct.callt_mail2Customer_Tipe_4		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Administration)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.callt_mail2Customer			= 'True' AND
										tcct.callt_mail2Customer_Tipe_5		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Logistics)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.callt_mail2Customer			= 'True' AND
										tcct.callt_mail2Customer_Tipe_6		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Alternative)
							    ELSE ''
							END +	';',
			@bitAddAlternative = tcct.callt_mail2Customer_Tipe_1AsAlternative,
			@strEMailCompras   = tc.cust_email

		FROM tbCustomer							tc					WITH (NOLOCK)
		INNER JOIN tbCRM_CallType				tcct				WITH (NOLOCK)
			ON	tcct.comp_id				= @comp_id		AND
				tcct.callt_id				= @callt_id		AND
				tcct.callt_mail2Customer	= 'True'
		INNER JOIN tbCRM_CallStatus				tccs				WITH (NOLOCK)
			ON	tccs.comp_id				= @comp_id		AND
				tccs.callst_id				= @callst_id	AND
				tccs.callst_mail2Customer	= 'true'
	WHERE	tc.comp_id = @comp_id AND
			tc.cust_id = @cust_id



	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF (@strEMailCustomer  = ';' OR @strEMailCustomer = '') AND @bitAddAlternative = 'True'
		BEGIN
			SET @strEMailCustomer = @strEMailCompras
		END
	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF @strEMailCustomer = ';' SET @strEMailCustomer = ''


	-- ---------------------------------------------
	-- Contacto
	-- ---------------------------------------------
	DECLARE @strMailContact AS NVARCHAR(MAX)
	SET		@strMailContact = ''
	SELECT  @strMailContact = dbo.fnstrEmailCheck(tc.contact_email)
		FROM tbCRM_Call					tct								WITH (NOLOCK)
		INNER JOIN tbContact tc											WITH (NOLOCK)
			ON	tc.comp_id		= tct.comp_id AND
				tc.contact_id	= tct.contact_id
		INNER JOIN tbCRM_CallType				tcmt					WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.callt_id				= @callt_id		AND
				tcmt.callt_mail2Contact		= 'True'
		INNER JOIN tbCRM_CallStatus				tcms					WITH (NOLOCK)
			ON	tcms.comp_id				= @comp_id		AND
				tcms.callst_id				= @callst_id	AND
				tcms.callst_mail2Contact	= 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.call_id = @call_id
	-- ---------------------------------------------

	-- ---------------------------------------------
	-- Adicional
	-- ---------------------------------------------
	DECLARE @strMailAdditional AS NVARCHAR(MAX)
	SELECT  @strMailAdditional = ''
	SELECT  @strMailAdditional = dbo.fnstrEmailCheck(tct.call_emailAdditional)
		FROM tbCRM_Call					tct								WITH (NOLOCK)
		INNER JOIN tbCRM_CallType				tcmt					WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.callt_id				= @callt_id		AND
				tcmt.callt_mail2Additional	= 'True'
		INNER JOIN tbCRM_CallStatus				tcms					WITH (NOLOCK)
			ON	tcms.comp_id				= @comp_id		AND
				tcms.callst_id				= @callst_id	AND
				tcms.callst_mail2Additional	= 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.call_id = @call_id
	-- ---------------------------------------------


	-- ---------------------------------------------
	-- CCO
	-- ---------------------------------------------
	DECLARE @strMailCCO AS NVARCHAR(MAX)
	SELECT  @strMailCCO = ''
	SELECT  @strMailCCO = dbo.fnstrEmailCheck(tcts.callst_eMailCCO)
		FROM tbCRM_Call					tct								WITH (NOLOCK)
		INNER JOIN tbCRM_CallType				tcmt					WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.callt_id				= @callt_id		AND
				tcmt.callt_withEmailCCO	= 'True'
		INNER JOIN tbCRM_CallStatus		tcts							WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.callst_id				= @callst_id		AND		--*
				tcts.callst_eMailCCO	IS NOT NULL				AND
				tcts.callst_eMailCCO    <> ''
		WHERE	tct.comp_id = @comp_id AND
				tct.call_id = @call_id
	-- ---------------------------------------------




	-- -------------------------------------------
	-- Selecciona los mails adicionales a copiar.-
	-- -------------------------------------------

	-- -----------------------------
	-- Obtiene en una Temporal los Grupos de Usuarios a los que pertenece el usuario Asignado
	-- -----------------------------
	DECLARE @tmpTable AS TABLE(crmug_id INT PRIMARY KEY)
	INSERT INTO @tmpTable(crmug_id)
		SELECT DISTINCT tcugd.crmug_id
			FROM tbCRM_UserGroupsDetail tcugd
			WHERE	tcugd.comp_id	= @comp_id AND
					tcugd.[user_id] = @user_id
	-- -----------------------------

	SELECT @strCC = @strCC + CASE
										 WHEN CHARINDEX(dbo.fnstrEmailCheck(tu.user_email),dbo.fnstrEmailCheck(@strCC)) = 0  THEN	dbo.fnstrEmailCheck(tu.user_email)
										 ELSE																							''
									 END +	';'

		FROM tbCRM_UserGroupsDetail						tcugd		WITH (NOLOCK)
		INNER JOIN @tmpTable tmpt
			ON tmpt.crmug_id = tcugd.crmug_id
		INNER JOIN tbCRM_UserGroups						tcug		WITH (NOLOCK)
			ON	tcug.comp_id	= tcugd.comp_id		AND
				tcug.crmug_id	= tcugd.crmug_id
		INNER JOIN tbUser								tu			WITH (NOLOCK)
			ON tu.[user_id] = tcugd.[user_id]
		INNER JOIN tbCRM_CallStatus				tccs				WITH (NOLOCK)
			ON	tccs.comp_id					= @comp_id		AND
				tccs.callst_id					= @callst_id	AND
				tccs.callst_eMailChanges2Group	= 'true'
		WHERE	tcug.crmug_disabled		= 'False'		AND
				tcugd.crmugd_disabled	= 'False'		AND
				tcugd.crmugd_4Call		= 'True'		AND
				tu.user_email			IS NOT NULL		AND
				tu.user_email			<> ''			AND
				tcugd.crmugd_4Call_MailsOfGroupChanges = 'True'	AND
			   (tcugd.callt_id			= @callt_id OR tcugd.callt_id IS NULL)

	-- -------------------------------------------
	-- Elimina Posibles Repeticiones
	-- -------------------------------------------
	SET @strcc = REPLACE(@strCC,@strEMailCustomer,'')
	SET @strcc = REPLACE(@strCC,@strMailContact,'')
	SET @strcc = REPLACE(@strCC,@strMailAdditional,'')

	SET @strMailCCO = REPLACE(@strMailCCO,@strEMailCustomer,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailContact,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailAdditional,'')
	-- -------------------------------------------

	SET @strCC = dbo.fnstrEmailCheck(@strCC)
	-- -------------------------------------------


	-- -------------------------------------------
	-- Saca el From
	-- -------------------------------------------
	DECLARE		@strMailFrom AS NVARCHAR(1000)
	SELECT		@strMailFrom = dbo.fnstrEmailCheck(tu.user_email)
		FROM	tbUser tu
		WHERE	tu.[user_id] = @user_id
	-- -------------------------------------------




	SET @strEMail = dbo.fnstrEmailCheck(@strUserMail + ';' + @strEMailCustomer		+ ';' + @strMailContact + ';' + @strMailAdditional) +
					'|' + dbo.fnstrEmailCheck(@strCC)			+
					'|' + dbo.fnstrEmailCheck(@strMailCCO)	+
					'|' + dbo.fnstrEmailCheck(@strMailFrom)
	-- ---------------------------------------------

	RETURN (@strEMail)

end

GO







-- ----------------
-- MOS
-- ----------------
CREATE FUNCTION [dbo].[fnCRM_GetCustomerEmailByCaseType]
(
	@comp_id	int,
	@cust_id	int,
	@caset_id	INT,
	@cast_id	INT,
	@case_id	INT,
	@user_id	INT
)


RETURNS NVARCHAR(MAX)
AS


BEGIN

	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
	/*
		declare			@comp_id	int,
						@cust_id	int,
						@caset_id	int,
						@cast_id	int
		select			@comp_id	=1,
						@cust_id	=24294,
						@caset_id	=1,
						@cast_id	=1
	*/
	-- ---------------------------------------------------


	-- ---------------------------------------------
	-- Adicionales
	-- ---------------------------------------------
	DECLARE @strEMail		AS NVARCHAR(MAX)
	DECLARE @strCC			AS NVARCHAR(MAX)
	DECLARE @strUserMail	AS NVARCHAR(MAX)

	SET @strEMail		= ''
	SET @strCC			= ''
	SET @strUserMail	= ''


	-- ---------------------------------------------
	-- Mail al Usuario
	-- ---------------------------------------------
	SELECT  @strUserMail = dbo.fnstrEmailCheck(tu.user_email)
		FROM tbCRM_Case					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_CaseType		tctt								WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.Caset_id				= @Caset_id		AND
				tctt.Caset_eMail2User   	= 'True'
		INNER JOIN tbCRM_CaseStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.cast_id				= @cast_id	    AND
				tcts.cast_eMail2User        = 'True'
		INNER JOIN tbUser tu												WITH (NOLOCK)
			ON tu.[user_id] = tct.[user_id]
		WHERE	tct.comp_id = @comp_id AND
				tct.Case_id = @Case_id
	-- ---------------------------------------------




	DECLARE @strEMailCustomer	AS NVARCHAR(MAX)
	DECLARE @strEMailCompras	AS NVARCHAR(MAX)
	DECLARE @bitAddAlternative	AS BIT
	SET		@strEMailCustomer	= ''
	SELECT  @strEMailCustomer	= '' +
							CASE
							    WHEN	tcct.caset_mail2Customer			= 'True' AND
										tcct.casett_mail2Customer_Tipe_1	= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.caset_mail2Customer			= 'True' AND
										tcct.casett_mail2Customer_Tipe_2	= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Payments)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.caset_mail2Customer			= 'True' AND
										tcct.casett_mail2Customer_Tipe_3	= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Management)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.caset_mail2Customer			= 'True' AND
										tcct.casett_mail2Customer_Tipe_4	= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Administration)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.caset_mail2Customer			= 'True' AND
										tcct.casett_mail2Customer_Tipe_5	= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Logistics)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcct.caset_mail2Customer			= 'True' AND
										tcct.casett_mail2Customer_Tipe_6	= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Alternative)
							    ELSE ''
							END +	';',
			@bitAddAlternative = tcct.casett_mail2Customer_Tipe_1AsAlternative,
			@strEMailCompras   = tc.cust_email

		FROM tbCustomer tc											WITH (NOLOCK)
		INNER JOIN tbCRM_CaseType tcct								WITH (NOLOCK)
			ON	tcct.comp_id				= @comp_id		AND
				tcct.caset_id				= @caset_id		AND
				tcct.caset_mail2Customer	= 'True'
		INNER JOIN tbCRM_CaseStatus tccs							WITH (NOLOCK)
			ON	tccs.comp_id				= @comp_id		AND
				tccs.cast_id				= @cast_id		AND
				tccs.cast_mail2Customer		= 'True'
	WHERE	tc.comp_id = @comp_id AND
			tc.cust_id = @cust_id


	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF (@strEMailCustomer  = ';' OR @strEMailCustomer = '') AND @bitAddAlternative = 'True'
		BEGIN
			SET @strEMailCustomer = @strEMailCompras
		END
	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF @strEMailCustomer = ';' SET @strEMailCustomer = ''


	-- ---------------------------------------------
	-- Contacto
	-- ---------------------------------------------
	DECLARE @strMailContact AS NVARCHAR(MAX)
	SET		@strMailContact = ''
	SELECT  @strMailContact = dbo.fnstrEmailCheck(tc.contact_email)
		FROM tbCRM_Case					tct							WITH (NOLOCK)
		INNER JOIN tbContact tc										WITH (NOLOCK)
			ON	tc.comp_id		= tct.comp_id AND
				tc.contact_id	= tct.contact_id
		INNER JOIN tbCRM_CaseType				tcmt				WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.caset_id				= @caset_id		AND
				tcmt.caset_mail2Contact		= 'True'
		INNER JOIN tbCRM_CaseStatus				tcms				WITH (NOLOCK)
			ON	tcms.comp_id				= @comp_id		AND
				tcms.cast_id				= @cast_id	AND
				tcms.cast_mail2Contact		= 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.case_id = @case_id
	-- ---------------------------------------------

	-- ---------------------------------------------
	-- Adicional
	-- ---------------------------------------------
	DECLARE @strMailAdditional AS NVARCHAR(MAX)
	SELECT  @strMailAdditional = ''
	SELECT  @strMailAdditional = dbo.fnstrEmailCheck(tct.case_emailAdditional)
		FROM tbCRM_Case					tct
		INNER JOIN tbCRM_CaseType				tcmt				WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.caset_id				= @caset_id		AND
				tcmt.caset_mail2Additional	= 'True'
		INNER JOIN tbCRM_CaseStatus				tcms				WITH (NOLOCK)
			ON	tcms.comp_id				= @comp_id		AND
				tcms.cast_id				= @cast_id	AND
				tcms.cast_mail2Additional	= 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.case_id = @case_id
	-- ---------------------------------------------


	-- ---------------------------------------------
	-- CCO
	-- ---------------------------------------------
	DECLARE @strMailCCO AS NVARCHAR(MAX)
	SELECT  @strMailCCO = ''
	SELECT  @strMailCCO = dbo.fnstrEmailCheck(tcts.cast_eMailCCO)
		FROM tbCRM_Case					tct
		INNER JOIN tbCRM_CaseType				tcmt				WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.caset_id				= @caset_id		AND
				tcmt.casett_withEmailCCO	= 'True'
		INNER JOIN tbCRM_CaseStatus		tcts						WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.cast_id				= @cast_id		AND
				tcts.cast_eMailCCO	IS NOT NULL				AND
				tcts.cast_eMailCCO    <> ''
		WHERE	tct.comp_id = @comp_id AND
				tct.case_id = @case_id
	-- ---------------------------------------------




	-- -------------------------------------------
	-- Selecciona los mails adicionales a copiar.-
	-- -------------------------------------------

	-- -----------------------------
	-- Obtiene en una Temporal los Grupos de Usuarios a los que pertenece el usuario Asignado
	-- -----------------------------
	DECLARE @tmpTable AS TABLE(crmug_id INT PRIMARY KEY)
	INSERT INTO @tmpTable(crmug_id)
		SELECT DISTINCT tcugd.crmug_id
			FROM tbCRM_UserGroupsDetail tcugd
			WHERE	tcugd.comp_id	= @comp_id AND
					tcugd.[user_id] = @user_id
	-- -----------------------------


	SELECT @strCC = @strCC + CASE
										 WHEN CHARINDEX(dbo.fnstrEmailCheck(tu.user_email),dbo.fnstrEmailCheck(@strCC)) = 0  THEN	dbo.fnstrEmailCheck(tu.user_email)
										 ELSE																							''
									 END +	';'

		FROM tbCRM_UserGroupsDetail						tcugd		WITH (NOLOCK)
		INNER JOIN @tmpTable tmpt
			ON tmpt.crmug_id = tcugd.crmug_id
		INNER JOIN tbCRM_UserGroups						tcug		WITH (NOLOCK)
			ON	tcug.comp_id	= tcugd.comp_id		AND
				tcug.crmug_id	= tcugd.crmug_id
		INNER JOIN tbUser								tu			WITH (NOLOCK)
			ON tu.[user_id] = tcugd.[user_id]
		INNER JOIN tbCRM_CaseStatus tccs							WITH (NOLOCK)
			ON	tccs.comp_id					= @comp_id		AND
				tccs.cast_id					= @cast_id		AND
				tccs.cast_eMailChanges2Group	= 'True'
		WHERE	tcug.crmug_disabled		= 'False'		AND
				tcugd.crmugd_disabled	= 'False'		AND
				tcugd.crmugd_4Case		= 'True'		AND
				tu.user_email			IS NOT NULL		AND
				tu.user_email			<> ''			AND
				tcugd.crmugd_4Case_MailsOfGroupChanges	= 'True'	AND
			   (tcugd.caset_id			= @caset_id OR tcugd.caset_id IS NULL)

	-- -------------------------------------------
	-- Elimina Posibles Repeticiones
	-- -------------------------------------------
	SET @strcc = REPLACE(@strCC,@strEMailCustomer,'')
	SET @strcc = REPLACE(@strCC,@strMailContact,'')
	SET @strcc = REPLACE(@strCC,@strMailAdditional,'')

	SET @strMailCCO = REPLACE(@strMailCCO,@strEMailCustomer,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailContact,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailAdditional,'')
	-- -------------------------------------------

	SET @strCC = dbo.fnstrEmailCheck(@strCC)
	-- -------------------------------------------



	-- -------------------------------------------
	-- Saca el From
	-- -------------------------------------------
	DECLARE		@strMailFrom AS NVARCHAR(1000)
	SELECT		@strMailFrom = dbo.fnstrEmailCheck(tu.user_email)
		FROM	tbUser tu
		WHERE	tu.[user_id] = @user_id
	-- -------------------------------------------




	SET @strEMail = dbo.fnstrEmailCheck(@strUserMail + ';' + @strEMailCustomer		+ ';' + @strMailContact + ';' + @strMailAdditional) +
					'|' + dbo.fnstrEmailCheck(@strCC)			+
					'|' + dbo.fnstrEmailCheck(@strMailCCO)	+
					'|' + dbo.fnstrEmailCheck(@strMailFrom)
	-- ---------------------------------------------

	RETURN (@strEMail)


end

GO




-- ----------------
-- MOS
-- ----------------
CREATE FUNCTION [dbo].[fnCRM_GetCustomerEmailByMeetType]
(
	@comp_id	int,
	@cust_id	int,
	@meett_id	INT,
	@meetst_id	INT,
	@meet_id	INT,
	@user_id	INT
)

RETURNS NVARCHAR(MAX)
AS

BEGIN

	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
	/*
		declare			@comp_id	int,
						@cust_id	int,
						@meetst_id	int,
						@meett_id	int
		select			@comp_id	=1,
						@cust_id	=24294,
						@meetst_id	=1,
						@meett_id	=1
	*/
	-- ---------------------------------------------------


	-- ---------------------------------------------
	-- Adicionales
	-- ---------------------------------------------
	DECLARE @strEMail		AS NVARCHAR(MAX)
	DECLARE @strCC			AS NVARCHAR(MAX)
	DECLARE @strUserMail	AS NVARCHAR(MAX)

	SET @strEMail		= ''
	SET @strCC			= ''
	SET @strUserMail	= ''


	-- ---------------------------------------------
	-- Mail al Usuario
	-- ---------------------------------------------
	SELECT  @strUserMail = dbo.fnstrEmailCheck(tu.user_email)
		FROM tbCRM_Meet					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_MeetType		tctt								WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.Meett_id				= @Meett_id		AND
				tctt.Meett_eMail2User   	= 'True'
		INNER JOIN tbCRM_MeetStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.meetst_id				= @meetst_id	AND
				tcts.meetst_eMail2User      = 'True'
		INNER JOIN tbUser tu												WITH (NOLOCK)
			ON tu.[user_id] = tct.[user_id]
		WHERE	tct.comp_id = @comp_id AND
				tct.Meet_id = @Meet_id
	-- ---------------------------------------------



	DECLARE @strEMailCustomer	AS NVARCHAR(MAX)
	DECLARE @strEMailCompras	AS NVARCHAR(MAX)
	DECLARE @bitAddAlternative	AS BIT
	SET		@strEMailCustomer	= ''
	SELECT  @strEMailCustomer   = '' +
							CASE
							    WHEN	tcmt.meett_mail2Customer			= 'True' AND
										tcmt.meett_mail2Customer_Tipe_1		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcmt.meett_mail2Customer			= 'True' AND
										tcmt.meett_mail2Customer_Tipe_2		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Payments)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcmt.meett_mail2Customer			= 'True' AND
										tcmt.meett_mail2Customer_Tipe_3		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Management)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcmt.meett_mail2Customer			= 'True' AND
										tcmt.meett_mail2Customer_Tipe_4		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Administration)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcmt.meett_mail2Customer			= 'True' AND
										tcmt.meett_mail2Customer_Tipe_5		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Logistics)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tcmt.meett_mail2Customer			= 'True' AND
										tcmt.meett_mail2Customer_Tipe_6		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Alternative)
							    ELSE ''
							END +	';',
			@bitAddAlternative = tcmt.meett_mail2Customer_Tipe_1AsAlternative,
			@strEMailCompras   = tc.cust_email

		FROM tbCustomer							tc								WITH (NOLOCK)
		INNER JOIN tbCRM_MeetType				tcmt							WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.meett_id				= @meett_id		AND
				tcmt.meett_mail2Customer	= 'True'
		INNER JOIN tbCRM_MeetStatus				tcms							WITH (NOLOCK)
			ON	tcms.comp_id				= @comp_id		AND
				tcms.meetst_id				= @meetst_id	AND
				tcms.meetst_mail2Customer	= 'True'
	WHERE	tc.comp_id = @comp_id AND
			tc.cust_id = @cust_id

	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF (@strEMailCustomer  = ';' OR @strEMailCustomer = '') AND @bitAddAlternative = 'True'
		BEGIN
			SET @strEMailCustomer = @strEMailCompras
		END
	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF @strEMailCustomer = ';' SET @strEMailCustomer = ''


	-- ---------------------------------------------
	-- Contacto
	-- ---------------------------------------------
	DECLARE @strMailContact AS NVARCHAR(MAX)
	SET		@strMailContact = ''
	SELECT  @strMailContact = dbo.fnstrEmailCheck(tc.contact_email)
		FROM tbCRM_Meet					tct									WITH (NOLOCK)
		INNER JOIN tbContact tc												WITH (NOLOCK)
			ON	tc.comp_id		= tct.comp_id AND
				tc.contact_id	= tct.contact_id
		INNER JOIN tbCRM_MeetType				tcmt						WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.meett_id				= @meett_id		AND
				tcmt.meett_mail2Contact	= 'True'
		INNER JOIN tbCRM_MeetStatus				tcms						WITH (NOLOCK)
			ON	tcms.comp_id				= @comp_id		AND
				tcms.meetst_id				= @meetst_id	AND
				tcms.meetst_mail2Contact	= 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.meet_id = @meet_id
	-- ---------------------------------------------

	-- ---------------------------------------------
	-- Adicional
	-- ---------------------------------------------
	DECLARE @strMailAdditional AS NVARCHAR(MAX)
	SELECT  @strMailAdditional = ''
	SELECT  @strMailAdditional = dbo.fnstrEmailCheck(tct.meet_emailAdditional)
		FROM tbCRM_Meet					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_MeetType				tcmt						WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.meett_id				= @meett_id		AND
				tcmt.meett_mail2Additional	= 'True'
		INNER JOIN tbCRM_MeetStatus				tcms						WITH (NOLOCK)
			ON	tcms.comp_id				= @comp_id		AND
				tcms.meetst_id				= @meetst_id	AND
				tcms.meetst_mail2Additional	= 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.meet_id = @meet_id
	-- ---------------------------------------------


	-- ---------------------------------------------
	-- CCO
	-- ---------------------------------------------
	DECLARE @strMailCCO AS NVARCHAR(MAX)
	SELECT  @strMailCCO = ''
	SELECT  @strMailCCO = dbo.fnstrEmailCheck(tcts.meetst_eMailCCO)
		FROM tbCRM_Meet					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_MeetType				tcmt						WITH (NOLOCK)
			ON	tcmt.comp_id				= @comp_id		AND
				tcmt.meett_id				= @meett_id		AND
				tcmt.meett_withEmailCCO		= 'True'
		INNER JOIN tbCRM_MeetStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.meetst_id				= @meetst_id		AND		--*
				tcts.meetst_eMailCCO	IS NOT NULL				AND
				tcts.meetst_eMailCCO    <> ''
		WHERE	tct.comp_id = @comp_id AND
				tct.meet_id = @meet_id
	-- ---------------------------------------------




	-- -------------------------------------------
	-- Selecciona los mails adicionales a copiar.-
	-- -------------------------------------------

	-- -----------------------------
	-- Obtiene en una Temporal los Grupos de Usuarios a los que pertenece el usuario Asignado
	-- -----------------------------
	DECLARE @tmpTable AS TABLE(crmug_id INT PRIMARY KEY)
	INSERT INTO @tmpTable(crmug_id)
		SELECT DISTINCT tcugd.crmug_id
			FROM tbCRM_UserGroupsDetail tcugd
			WHERE	tcugd.comp_id	= @comp_id AND
					tcugd.[user_id] = @user_id
	-- -----------------------------


	SELECT @strCC = @strCC + CASE
										 WHEN CHARINDEX(dbo.fnstrEmailCheck(tu.user_email),dbo.fnstrEmailCheck(@strCC)) = 0  THEN	dbo.fnstrEmailCheck(tu.user_email)
										 ELSE																							''
									 END +	';'

		FROM tbCRM_UserGroupsDetail						tcugd		WITH (NOLOCK)
		INNER JOIN @tmpTable tmpt
			ON tmpt.crmug_id = tcugd.crmug_id
		INNER JOIN tbCRM_UserGroups						tcug		WITH (NOLOCK)
			ON	tcug.comp_id	= tcugd.comp_id		AND
				tcug.crmug_id	= tcugd.crmug_id
		INNER JOIN tbUser								tu			WITH (NOLOCK)
			ON tu.[user_id] = tcugd.[user_id]
		INNER JOIN tbCRM_MeetStatus				tcms				WITH (NOLOCK)
			ON	tcms.comp_id					= @comp_id		AND
				tcms.meetst_id					= @meetst_id	AND
				tcms.meetst_eMailChanges2Group	= 'True'
		WHERE	tcug.crmug_disabled		= 'False'		AND
				tcugd.crmugd_disabled	= 'False'		AND
				tcugd.crmugd_4Meet		= 'True'		AND
				tu.user_email			IS NOT NULL		AND
				tu.user_email			<> ''			AND
				tcugd.crmugd_4Meet_MailsOfGroupChanges = 'True'	 AND
			   (tcugd.meett_id			= @meett_id OR tcugd.meett_id IS NULL)

	-- -------------------------------------------
	-- Elimina Posibles Repeticiones
	-- -------------------------------------------
	SET @strcc = REPLACE(@strCC,@strEMailCustomer,'')
	SET @strcc = REPLACE(@strCC,@strMailContact,'')
	SET @strcc = REPLACE(@strCC,@strMailAdditional,'')

	SET @strMailCCO = REPLACE(@strMailCCO,@strEMailCustomer,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailContact,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailAdditional,'')
	-- -------------------------------------------

	SET @strCC = dbo.fnstrEmailCheck(@strCC)
	-- -------------------------------------------


	-- -------------------------------------------
	-- Saca el From
	-- -------------------------------------------
	DECLARE		@strMailFrom AS NVARCHAR(1000)
	SELECT		@strMailFrom = dbo.fnstrEmailCheck(tu.user_email)
		FROM	tbUser tu
		WHERE	tu.[user_id] = @user_id
	-- -------------------------------------------




	SET @strEMail = dbo.fnstrEmailCheck(@strUserMail + ';' + @strEMailCustomer		+ ';' + @strMailContact + ';' + @strMailAdditional) +
					'|' + dbo.fnstrEmailCheck(@strCC)			+
					'|' + dbo.fnstrEmailCheck(@strMailCCO)	+
					'|' + dbo.fnstrEmailCheck(@strMailFrom)
	-- ---------------------------------------------

	RETURN (@strEMail)

end

GO




-- ----------------
-- MOS: retornar mail a enviar al Cliente, Contacto y Mail Adicional segun lo diga el tipo correspodiente
-- ----------------
CREATE FUNCTION [dbo].[fnCRM_GetCustomerEmailByTaskType]
(
	@comp_id	int,
	@cust_id	int,
	@taskt_id	INT,
	@tast_id	INT,
	@task_id	INT,
	@user_id	INT
)


RETURNS NVARCHAR(MAX)
AS


BEGIN

	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
	/*
		declare			@comp_id	int,
						@cust_id	int,
						@taskt_id	int,
						@tast_id	int
		select			@comp_id	=1,
						@cust_id	=24294,
						@taskt_id	=1,
						@tast_id	=1
	*/
	-- ---------------------------------------------------



	-- ---------------------------------------------
	-- Adicionales
	-- ---------------------------------------------
	DECLARE @strEMail		AS NVARCHAR(MAX)
	DECLARE @strCC			AS NVARCHAR(MAX)
	DECLARE @strUserMail	AS NVARCHAR(MAX)
	DECLARE @user_id4lastUpdate AS INT = NULL
	SET @strEMail		= ''
	SET @strCC			= ''
	SET @strUserMail	= ''


	-- ---------------------------------------------
	-- Mail al Usuario
	-- ---------------------------------------------
	SELECT  @strUserMail					= dbo.fnstrEmailCheck(tu.user_email) +
																CASE -- Para que copie tambien al usuario INICIAL solo si es de soporte GBP
																	WHEN tct.user_id_4SupportCreator IS NULL OR	-- si NO vino de Soporte GBP
																		 tuc.[user_id] IS NULL				 OR -- Si no tiene usuario creador
																		 tct.[user_id] = tct.user_id_Creator THEN	''	-- Si el usuario creador es el mismo del actual
																	ELSE											';' + dbo.fnstrEmailCheck(tuc.user_email)
																END,
			@user_id4lastUpdate				= ISNULL(tct.user_id4lastUpdate,tct.[user_id])

		FROM tbCRM_Task					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_TaskType		tctt								WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.taskt_id				= @taskt_id		AND
				tctt.taskt_eMail2User   	= 'True'
		INNER JOIN tbCRM_TaskStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.tast_id				= @tast_id		AND
				tcts.tast_eMail2User        = 'True'
		INNER JOIN tbUser	tu												WITH (NOLOCK)
			ON tu.[user_id] = tct.[user_id]
		LEFT JOIN tbUser	tuc												WITH (NOLOCK)
			ON tuc.[user_id] = tct.user_id_Creator
		WHERE	tct.comp_id = @comp_id AND
				tct.task_id = @task_id
	-- ---------------------------------------------







	DECLARE @strEMailCustomer	AS NVARCHAR(MAX)
	DECLARE @strEMailCompras	AS NVARCHAR(MAX)
	DECLARE @bitAddAlternative	AS BIT
	SET		@strEMailCustomer	= ''
	SELECT	@strEMailCustomer	= '' +
							CASE
							    WHEN	tctt.taskt_mail2Customer			= 'True' AND
										tctt.taskt_mail2Customer_Tipe_1		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tctt.taskt_mail2Customer			= 'True' AND
										tctt.taskt_mail2Customer_Tipe_2		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Payments)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tctt.taskt_mail2Customer			= 'True' AND
										tctt.taskt_mail2Customer_Tipe_3		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Management)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tctt.taskt_mail2Customer			= 'True' AND
										tctt.taskt_mail2Customer_Tipe_4		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Administration)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tctt.taskt_mail2Customer			= 'True' AND
										tctt.taskt_mail2Customer_Tipe_5		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Logistics)
							    ELSE ''
							END	+	';' +
							CASE
							    WHEN	tctt.taskt_mail2Customer			= 'True' AND
										tctt.taskt_mail2Customer_Tipe_6		= 'True'		THEN dbo.fnstrEmailCheck(tc.cust_email4Alternative)
							    ELSE ''
							END +	';',
			@bitAddAlternative = tctt.taskt_mail2Customer_Tipe_1AsAlternative,
			@strEMailCompras   = dbo.fnstrEmailCheck(tc.cust_email)

		FROM tbCustomer				tc										WITH (NOLOCK)
		INNER JOIN tbCRM_TaskType	tctt									WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.taskt_id				= @taskt_id		AND
				tctt.taskt_mail2Customer	= 'True'				--*
		INNER JOIN tbCRM_TaskStatus tcts									WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.tast_id				= @tast_id		AND		--*
				tcts.tast_mail2Customer		= 'True'
		WHERE	tc.comp_id = @comp_id AND
				tc.cust_id = @cust_id

	--*
	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF (@strEMailCustomer  = ';' OR @strEMailCustomer = '') AND @bitAddAlternative = 'True'
		BEGIN
			SET @strEMailCustomer = @strEMailCompras
		END
	SET @strEMailCustomer = dbo.fnstrEmailCheck(@strEMailCustomer)
	IF @strEMailCustomer = ';' SET @strEMailCustomer = ''


	-- ---------------------------------------------
	-- Contacto
	-- ---------------------------------------------
	DECLARE @strMailContact AS NVARCHAR(MAX)
	SET		@strMailContact = ''
	SELECT  @strMailContact = dbo.fnstrEmailCheck(tc.contact_email)
		FROM tbCRM_Task					tct									WITH (NOLOCK)
		INNER JOIN tbContact tc												WITH (NOLOCK)
			ON	tc.comp_id		= tct.comp_id AND
				tc.contact_id	= tct.contact_id
		INNER JOIN tbCRM_TaskType		tctt								WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.taskt_id				= @taskt_id		AND
				tctt.taskt_mail2Contact	= 'True'
		INNER JOIN tbCRM_TaskStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.tast_id				= @tast_id		AND
				tcts.tast_mail2Contact = 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.task_id = @task_id
	-- ---------------------------------------------

	-- ---------------------------------------------
	-- Adicional
	-- ---------------------------------------------
	DECLARE @strMailAdditional AS NVARCHAR(MAX)
	SELECT  @strMailAdditional = ''
	SELECT  @strMailAdditional = dbo.fnstrEmailCheck(tct.task_emailAdditional)
		FROM tbCRM_Task					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_TaskType		tctt								WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.taskt_id				= @taskt_id		AND
				tctt.taskt_mail2Additional	= 'True'				--*
		INNER JOIN tbCRM_TaskStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.tast_id				= @tast_id		AND		--*
				tcts.tast_mail2Additional	= 'True'
		WHERE	tct.comp_id = @comp_id AND
				tct.task_id = @task_id
	-- ---------------------------------------------


	-- ---------------------------------------------
	-- CCO
	-- ---------------------------------------------
	DECLARE @strMailCCO AS NVARCHAR(MAX)
	SELECT  @strMailCCO = ''
	SELECT  @strMailCCO = dbo.fnstrEmailCheck(tcts.tast_eMailCCO)
		FROM tbCRM_Task					tct									WITH (NOLOCK)
		INNER JOIN tbCRM_TaskType		tctt								WITH (NOLOCK)
			ON	tctt.comp_id				= @comp_id		AND
				tctt.taskt_id				= @taskt_id		AND
				tctt.taskt_withEmailCCO		= 'True'				--*
		INNER JOIN tbCRM_TaskStatus		tcts								WITH (NOLOCK)
			ON	tcts.comp_id				= @comp_id		AND
				tcts.tast_id				= @tast_id		AND		--*
				tcts.tast_eMailCCO	IS NOT NULL				AND
				tcts.tast_eMailCCO  <> ''
		WHERE	tct.comp_id = @comp_id AND
				tct.task_id = @task_id
	-- ---------------------------------------------




	-- -------------------------------------------
	-- Selecciona los mails adicionales a copiar.-
	-- -------------------------------------------

	-- -----------------------------
	-- Obtiene en una Temporal los Grupos de Usuarios a los que pertenece el usuario Asignado
	-- -----------------------------
	DECLARE @tmpTable AS TABLE(crmug_id INT PRIMARY KEY)
	INSERT INTO @tmpTable(crmug_id)
		SELECT DISTINCT tcugd.crmug_id
			FROM tbCRM_UserGroupsDetail tcugd		WITH (NOLOCK)
			WHERE	tcugd.comp_id	= @comp_id AND
					tcugd.[user_id] = @user_id
	-- -----------------------------

	SELECT @strCC = @strCC + CASE
										 WHEN CHARINDEX(dbo.fnstrEmailCheck(tu.user_email),dbo.fnstrEmailCheck(@strCC)) = 0  THEN	dbo.fnstrEmailCheck(tu.user_email)
										 ELSE																							''
									 END +	';'

		FROM tbCRM_UserGroupsDetail						tcugd		WITH (NOLOCK)
		INNER JOIN @tmpTable tmpt
			ON tmpt.crmug_id = tcugd.crmug_id
		INNER JOIN tbCRM_UserGroups						tcug		WITH (NOLOCK)
			ON	tcug.comp_id	= tcugd.comp_id		AND
				tcug.crmug_id	= tcugd.crmug_id
		INNER JOIN tbUser								tu			WITH (NOLOCK)
			ON tu.[user_id] = tcugd.[user_id]
		INNER JOIN tbCRM_TaskStatus tcts							WITH (NOLOCK)
			ON	tcts.comp_id					= @comp_id		AND
				tcts.tast_id					= @tast_id		AND		--*
				tcts.tast_eMailChanges2Group	= 'True'
		WHERE	tcug.crmug_disabled		= 'False'		AND
				tcugd.crmugd_disabled	= 'False'		AND
				tcugd.crmugd_4Task		= 'True'		AND
				tu.user_email			IS NOT NULL		AND
				tu.user_email			<> ''			AND
				tcugd.crmugd_4Task_MailsOfGroupChanges = 'True'	AND
			   (tcugd.taskt_id			= @taskt_id OR tcugd.taskt_id IS NULL)

	-- -------------------------------------------
	-- Elimina Posibles Repeticiones
	-- -------------------------------------------
	SET @strcc = REPLACE(@strCC,@strEMailCustomer,'')
	SET @strcc = REPLACE(@strCC,@strMailContact,'')
	SET @strcc = REPLACE(@strCC,@strMailAdditional,'')

	SET @strMailCCO = REPLACE(@strMailCCO,@strEMailCustomer,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailContact,'')
	SET @strMailCCO = REPLACE(@strMailCCO,@strMailAdditional,'')
	-- -------------------------------------------

	SET @strCC = dbo.fnstrEmailCheck(@strCC)
	-- -------------------------------------------


	-- -------------------------------------------
	-- Saca el From
	-- -------------------------------------------
	DECLARE		@strMailFrom AS NVARCHAR(1000)
	SELECT		@strMailFrom = dbo.fnstrEmailCheck(tu.user_email)
		FROM	tbUser tu	WITH (NOLOCK)
		WHERE	tu.[user_id] = @user_id4lastUpdate	-- MOS 06-2024: Estaba en user_id pero para que se sepa QUIEN lo manda debe ser del ultimo asignado.
	-- -------------------------------------------




	SET @strEMail = dbo.fnstrEmailCheck(@strUserMail + ';' + @strEMailCustomer		+ ';' + @strMailContact + ';' + @strMailAdditional) +
					'|' + dbo.fnstrEmailCheck(@strCC)			+
					'|' + dbo.fnstrEmailCheck(@strMailCCO)	+
					'|' + dbo.fnstrEmailCheck(@strMailFrom)
	-- ---------------------------------------------

	RETURN (@strEMail)

end

GO





-- =============================================
-- Author:		MOS
-- Create date: 10-2008
-- Description:	retorna Estado de Balance de
--				un cliente en una moneda
--				en una TABLA
-- =============================================
CREATE FUNCTION [dbo].[fnCustomer_getBalanceStatus]
(
	@comp_id					as	int,
	@curr_id					as	int,
	@cust_id					as	int,
	@user_id					AS  INT,			-- USUARIO EN NEGATIVO: Solo para la Sucursal Actual
	@branchProcessingDate		as DATETIME,
	@bra_id						AS INT,
	@soh_id						AS INT				-- -2: No calcula nada para este cliente en particular;   -4: Solo calcula balance y nada de cartera, pedidos, etc.
)
RETURNS

	@balanceStatus TABLE
	(
		cust_credit_max					decimal(19,5) NULL,
		cust_credit_own					decimal(19,5) NULL,
		cust_credit_cheque_own_used		decimal(19,5) NULL,
		cust_credit_cheque_3rd_used		decimal(19,5) NULL,
		cust_credit_SaleOrder			decimal(19,5) NULL,
		cust_credit_balance				decimal(19,5) NULL,
		cust_credit_balance_OverCome	decimal(19,5) NULL,
		cust_credit_balance_OverComeWithTolerance
										decimal(19,5) NULL,
		cust_credit_balance_NotOverCome	decimal(19,5) NULL,
		cust_DocumentsOnDebt			INT,
		cust_DocumentsOvercomeOnDebt	INT,
		cust_id							INT
	)

AS

BEGIN
	-- Fill the table variable with the rows for your result set

	-- ---------------------------------------------------------------------------------------
	-- Si @user_id viene en NEGATIVO filtrar por los comprobantes de esta sucursal unicamente.
	-- ---------------------------------------------------------------------------------------
	DECLARE @bitOnly4ThisBranch AS BIT = 'False'
	IF @user_id < 0
		BEGIN
			SET @bitOnly4ThisBranch = 'True'
			SET @user_id = @user_id * -1
		END


	DECLARE		@tblBranchs TABLE(bra_id INT PRIMARY KEY)
	INSERT INTO @tblBranchs(bra_id)
		SELECT DISTINCT vubf.bra_id
			FROM 	dbo.tbUsers4BranchFilter	vubf		WITH (NOLOCK)
			WHERE	vubf.comp_id		= @comp_id		AND
					vubf.[user_id]		= @user_id

	IF @bitOnly4ThisBranch = 'True'
		BEGIN
			DELETE FROM @tblBranchs WHERE bra_id <> @bra_id
		END

	DECLARE @bitSaleOrderPendingByTotalOfSOH AS BIT = 'False'
	IF @bra_id = -20
		BEGIN
			SET @bra_id = -1
			SET @bitSaleOrderPendingByTotalOfSOH = 'True'
		END

	-- ---------------------------------------------------------------------------------------




	Declare @cust_credit_max					as Decimal(19,5)
	Declare @cust_credit_own					as Decimal(19,5)
	Declare @cust_credit_cheque_3rd_used		as Decimal(19,5)
	Declare @cust_credit_cheque_own_used		as Decimal(19,5)
	Declare @cust_credit_SaleOrder				as Decimal(19,5)
	Declare @decBalance							as Decimal(19,5)
	Declare @decBalanceOverCome					as Decimal(19,5)
	Declare @decBalanceOverComeWithTolerance	as Decimal(19,5)
	DECLARE @intDocumentsOnDebt					AS INT
	DECLARE @intDocumentsOvercomeOnDebt			AS INT
	SET		@intDocumentsOvercomeOnDebt = 0


	DECLARE @bra_Credit_AssumeValuesAcreditDays AS INT
	SET @bra_Credit_AssumeValuesAcreditDays = 4
	SELECT @bra_Credit_AssumeValuesAcreditDays = tb.bra_Credit_AssumeValuesAcreditDays
		FROM dbo.tbBranch tb		WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id


	-- Terminarlo, solo se hizo esto para cuando se lo necesite !
	DECLARE @bolOnlyCalculateBalance AS BIT
	SET		@bolOnlyCalculateBalance = 'False'
	IF		@soh_id = -4 SET @bolOnlyCalculateBalance = 'True'


										 -- ATENCION!!!!!!
	IF @cust_id > 0 and @soh_id <> -2    -- Para que si se hace un Cross-Apply contra esta tabla
									     -- y se quiere que ande rapido en algun cliente sin calcular nada
										 --  se pone el soh_id en -2 y listo
		BEGIN

			-- -------------------------------------------------------------------
			-- Credito Maximo del Cliente
			-- -------------------------------------------------------------------
			Select	@cust_credit_max = dbo.fnGetExchange2(@comp_id, cust_credit_max,ISNULL(cust_credit_Curr_Id,curr_id),@curr_id,0,0,0,'false'),
					@cust_credit_own = dbo.fnGetExchange2(@comp_id, cust_credit_own,ISNULL(cust_credit_Curr_Id,curr_id),@curr_id,0,0,0,'false')
				From dbo.tbCustomer		WITH (NOLOCK)
				Where	comp_id = @comp_id
					and	cust_id	= @cust_id


			-- -------------------------------------------------------------------
			-- Pendientes en Cuenta Corriente
			-- -------------------------------------------------------------------
			SELECT  @decBalance			= 0
			IF @soh_id <> -3
				BEGIN
					Select	@decBalance			= Sum(dbo.fnGetExchange2(@comp_id,
																	 CASE
																		WHEN tctl.comp_id IS NOT NULL AND
																			 tctl.ctl_payDate	> @branchProcessingDate				THEN tctl.ct_ABalance
																		When tctl.comp_id IS NULL AND
																			 ct.ct_payDate			> @branchProcessingDate			Then CT.ct_ABalance
																		Else	0
																	 End,
																	 CT.ct_ACurrency,
																	 @curr_id,
																	 0,
																	 0,
																	 0,
																	 'False'
																	 ) *
 																	 Case CTS.sd_isCredit
 																		 When  'True' Then  -1
																		 Else				 1
																	 End
												   )
													,
							@decBalanceOverCome	= Sum(dbo.fnGetExchange2(@comp_id,
																	 CASE
																		WHEN	tctl.comp_id IS NOT NULL AND
																				tctl.ctl_payDate	<=  @branchProcessingDate	THEN tctl.ct_ABalance
																		When	tctl.comp_id IS NULL AND
																				ct.ct_payDate		<=  @branchProcessingDate	Then CT.ct_ABalance
																		Else	0
																	 End,
																	 CT.ct_ACurrency,
																	 @curr_id,
																	 0,
																	 0,
																	 0,
																	 'False'
																	 ) *
 																	 Case CTS.sd_isCredit
 																		 When  'True' Then  -1
																		 Else				 1
																	 End
												   )
													,
							@decBalanceOverComewithTolerance	= Sum(dbo.fnGetExchange2(@comp_id,
																	 CASE
																		WHEN	tctl.comp_id IS NOT NULL AND
																				DATEADD(day, tdf.df_Authorization_37_DaysTolerance,tctl.ctl_payDate)	<=  @branchProcessingDate	THEN tctl.ct_ABalance
																		When	tctl.comp_id IS NULL AND
																				DATEADD(day, tdf.df_Authorization_37_DaysTolerance,ct.ct_payDate)		<=  @branchProcessingDate	Then CT.ct_ABalance
																		Else	0
																	 End,
																	 CT.ct_ACurrency,
																	 @curr_id,
																	 0,
																	 0,
																	 0,
																	 'False'
																	 ) *
 																	 Case CTS.sd_isCredit
 																		 When  'True' Then  -1
																		 Else				 1
																	 End
												   ),
							@intDocumentsOnDebt = COUNT(ct.comp_id),
							@intDocumentsOvercomeOnDebt = SUM(
															CASE
																WHEN ct.ct_payDate	<=  @branchProcessingDate AND CTS.PlusOrMinus > 0	THEN 1
																ELSE 0
															END
														   )

						From dbo.tbCommercialTransactions					CT			WITH (NOLOCK)
						Inner join dbo.vwCommercialTransactions_forSales	CTS			WITH (NOLOCK)
							On		CTS.comp_id			= CT.comp_id
								and CTS.ct_transaction	= CT.ct_transaction
						INNER JOIN @tblBranchs tmp
							ON tmp.bra_id = ct.bra_id
						--INNER JOIN tbUsers4BranchFilter						vubf		WITH (NOLOCK)
						--	ON vubf.comp_id				= ct.comp_id
						--	AND vubf.bra_id				= ct.bra_id
						--	AND vubf.[user_id]			= @user_id
						INNER JOIN dbo.tbDocumentsFile						tdf			WITH (NOLOCK)
							ON	tdf.comp_id = ct.comp_id	AND
								tdf.bra_id	= ct.bra_id		AND
								tdf.df_id	= ct.df_id
						LEFT JOIN dbo.tbCommercialTransactionsLoan				tctl		WITH (NOLOCK)
							ON	tctl.comp_id		= CT.comp_id	AND
								tctl.ct_transaction = CT.ct_transaction
						Inner join dbo.tbBranch								BRA			WITH (NOLOCK)
							On		BRA.comp_id		= @comp_id
								and BRA.bra_id		= CT.bra_id

						Where	CT.comp_id			= @comp_id
							and CT.ct_ABalance		<> 0
							and	CT.cust_id			= @cust_id
							and CTS.sd_isInBalance	= 'True'
							-- MOS 01-2023: Sin recibo anulado o recibo anulado contraparte.  tambien se saca la anulacion de aplicacion de recibos anulados.
							AND ct.sd_id <> 56
							AND ct.sd_id <> 66

				END




			-- -------------------------------------------------------------------
			-- Pedidos Pendientes
			-- -------------------------------------------------------------------
			-- ATENCION:   si se toca esta parte ponerlo tambien n el SP del mismo nombre.!!!
			SET @cust_credit_SaleOrder			= 0
			IF @soh_id <> -3 AND @bolOnlyCalculateBalance = 'False'
				BEGIN

					IF @bitSaleOrderPendingByTotalOfSOH = 'False'
						BEGIN
							Select @cust_credit_SaleOrder = Sum(sod_qty *	dbo.fnGetExchange2(   @comp_id,
																								 SOD.sod_price,
																								 SOD.curr_id,
																								 @curr_id,
																								 0,
																								 0,
																								 0,
																								 'False'
																)
																		*	CASE
																				WHEN td.sd_isCredit = 'true' THEN -1
																				ELSE 1
																			END
																)

								From dbo.tbSaleOrderDetail			SOD					WITH (NOLOCK)
								Inner Join dbo.tbSaleOrderHeader	SOH					WITH (NOLOCK)
									On		SOH.comp_id = SOD.comp_id
										and	SOH.bra_id	= SOD.bra_id
										and SOH.soh_id	= SOD.soh_id
								INNER JOIN dbo.tbDocumentsFile tdf							WITH (NOLOCK)
									ON	tdf.comp_id = soh.comp_id AND
										tdf.df_id	= soh.df_id
								INNER JOIN dbo.tbsysDocuments td							WITH (NOLOCK)
									ON td.sd_id = tdf.sd_id
								--INNER JOIN tbUsers4BranchFilter vubf					WITH (NOLOCK)
								--	ON vubf.comp_id		= soh.comp_id
								--	AND vubf.bra_id		= soh.bra_id
								--	AND vubf.[user_id]	= @user_id
								INNER JOIN @tblBranchs tmp
									ON tmp.bra_id = soh.bra_id
								Where	SOH.comp_id		= @comp_id
									and SOH.cust_id		= @cust_id
									and soh_quotation	= 'False'
									AND td.sd_isInBalance = 'True'
									AND NOT (sod.comp_id = @comp_id and sod.bra_id = @bra_id AND sod.soh_id = @soh_id)
									--AND (soh.bra_id <> @bra_id AND soh.soh_id <> @soh_id) -- MOS: 08-2011 Para que no tome en cuenta Este Pedido en especial.-


							Select @cust_credit_SaleOrder = @cust_credit_SaleOrder +
								ISNULL(Sum(
											dbo.fnGetExchange2(  @comp_id,
																 tm_total,
																 curr_id,
																 @curr_id,
																 0,
																 0,
																 0,
																 'False'
																)

									*
												CASE
													WHEN td.sd_isCredit = 'true' THEN -1
													ELSE 1
												END
									),0)
								From dbo.tbSaleOrderTaxes			SOD					WITH (NOLOCK)
								Inner Join dbo.tbSaleOrderHeader	SOH					WITH (NOLOCK)
									On		SOH.comp_id = SOD.comp_id
										and	SOH.bra_id	= SOD.bra_id
										and SOH.soh_id	= SOD.soh_id
								INNER JOIN dbo.tbDocumentsFile tdf							WITH (NOLOCK)
									ON	tdf.comp_id = soh.comp_id AND
										tdf.df_id	= soh.df_id
								INNER JOIN dbo.tbsysDocuments td							WITH (NOLOCK)
									ON td.sd_id = tdf.sd_id
								INNER JOIN @tblBranchs tmp
									ON tmp.bra_id = soh.bra_id
								--INNER JOIN tbUsers4BranchFilter vubf					WITH (NOLOCK)
								--	ON vubf.comp_id		= soh.comp_id
								--	AND vubf.bra_id		= soh.bra_id
								--	AND vubf.[user_id]	= @user_id
								Where	SOH.comp_id		= @comp_id
									and SOH.cust_id		= @cust_id
									and soh_quotation	= 'False'
									AND td.sd_isInBalance = 'True'
									AND NOT (sod.comp_id = @comp_id and sod.bra_id = @bra_id AND sod.soh_id = @soh_id)
									--AND (soh.bra_id <> @bra_id AND soh.soh_id <> @soh_id) -- MOS: 08-2011 Para que no tome en cuenta Este Pedido en especial.-

						END
					ELSE
						BEGIN
							-- MOS 09-2024: x los FORROS de DG ticket 22371 q querian el total SIN DESCUENTOS
							Select @cust_credit_SaleOrder = SUM( soh.soh_total * td.sd_plusOrminus )
								From dbo.tbSaleOrderHeader			soh					WITH (NOLOCK)
								INNER JOIN dbo.tbDocumentsFile tdf							WITH (NOLOCK)
									ON	tdf.comp_id = soh.comp_id AND
										tdf.df_id	= soh.df_id
								INNER JOIN dbo.tbsysDocuments td							WITH (NOLOCK)
									ON td.sd_id = tdf.sd_id
								--INNER JOIN tbUsers4BranchFilter vubf					WITH (NOLOCK)
								--	ON vubf.comp_id		= soh.comp_id
								--	AND vubf.bra_id		= soh.bra_id
								--	AND vubf.[user_id]	= @user_id
								INNER JOIN @tblBranchs tmp
									ON tmp.bra_id = soh.bra_id
								Where	SOH.comp_id		= @comp_id
									and SOH.cust_id		= @cust_id
									and soh_quotation	= 'False'
									AND td.sd_isInBalance = 'True'
									AND NOT (soh.comp_id = @comp_id and soh.bra_id = @bra_id AND soh.soh_id = @soh_id)
						END












				END

			-- -------------------------------------------------------------------
			-- Pendientes en Cartera  o de Acreditacion
			-- -------------------------------------------------------------------
			-- ATENCION !!
			-- Si se toca algo aqui tocar tembien en **BalanceStatus (Buscarlo en la DB)
			IF @bolOnlyCalculateBalance = 'False'
				BEGIN


					Select	@cust_credit_cheque_3rd_used = Sum(dbo.fnGetExchange2(@comp_id,
																			 Case chp_isOwn
																				When 'False' Then CP.chp_total
																				Else			 0
																			 End,
																			 CP.curr_id,
																			 @curr_id,
																			 0,
																			 0,
																			 0,
																			 'False'
																			 )
															  )
																		,
							@cust_credit_cheque_own_used = Sum(dbo.fnGetExchange2(@comp_id,
																			 Case chp_isOwn
																				When 'True' Then CP.chp_total
																				Else			 0
																			 End,
																			 CP.curr_id,
																			 @curr_id,
																			 0,
																			 0,
																			 0,
																			 'False'
																			 )
															)

						From dbo.tbCheckPortfolio					CP				WITH (NOLOCK)
						INNER JOIN dbo.tbBranch tb										WITH (NOLOCK)
							ON	tb.comp_id				= cp.comp_id AND
								tb.bra_id				= cp.bra_id_PortFolio
						inner Join dbo.tbCommercialTransactions		CT				WITH (NOLOCK)
							On		CT.comp_id			= CP.comp_id
								and CT.ct_transaction	= CP.ct_transaction

						Inner Join dbo.vwCheckPortfolio_AllPayPending CPOP			WITH (NOLOCK)
							On		(CPOP.comp_id		= CP.comp_id
								and CPOP.chp_id			= CP.chp_id)
						INNER JOIN @tblBranchs tmp
							ON tmp.bra_id = cp.bra_id
						--INNER JOIN tbUsers4BranchFilter				vubf			WITH (NOLOCK)
						--	ON vubf.comp_id				= cp.comp_id
						--	AND vubf.bra_id				= cp.bra_id
						--	AND vubf.[user_id]			= @user_id
						Where  CP.comp_id				= @comp_id
							and CT.cust_id				= @cust_id
							AND (	(cpop.isSold='false' AND cpop.isPayed2Supplier = 'False')
								  OR
									(
										(cpop.isSold='True' OR cpop.isPayed2Supplier = 'True') AND cp.chp_PayDate > (@branchProcessingDate - @bra_Credit_AssumeValuesAcreditDays)  -- Si fueron vendidos toma en cuenta una semana mas de plazo para liberar el credito
									)
								)

				END
					-- -------------------------------------------------------------------





			Insert  @balanceStatus
				(	cust_credit_max,
					cust_credit_own,
					cust_credit_cheque_own_used,
					cust_credit_cheque_3rd_used,
					cust_credit_SaleOrder,
					cust_credit_balance,
					cust_credit_balance_OverCome,
					cust_credit_balance_OverComeWithTolerance,
					cust_credit_balance_NotOverCome,
					cust_id,
					cust_DocumentsOnDebt,
					cust_DocumentsOvercomeOnDebt
				)
				Values
				(	IsNull(@cust_credit_max,0),
					IsNull(@cust_credit_own,0),
					IsNull(@cust_credit_cheque_own_used,0),
					IsNull(@cust_credit_cheque_3rd_used,0),
					IsNull(@cust_credit_SaleOrder,0),
					IsNull(@decBalance,0) + IsNull(@decBalanceOverCome,0),
					IsNull(@decBalanceOverCome,0),
					ISNULL(@decBalanceOverComeWithTolerance,0),
					IsNull(@decBalance,0),
					@cust_id,
					@intDocumentsOnDebt,
					@intDocumentsOvercomeOnDebt
				)

		END
	else
		BEGIN
			Insert  @balanceStatus
						(	cust_credit_max,
							cust_credit_own,
							cust_credit_cheque_own_used,
							cust_credit_cheque_3rd_used,
							cust_credit_SaleOrder,
							cust_credit_balance,
							cust_credit_balance_OverCome,
							cust_credit_balance_OverComeWithTolerance,
							cust_credit_balance_NotOverCome,
							cust_id,
							cust_DocumentsOnDebt,
							cust_DocumentsOvercomeOnDebt
						)
						Values
						(	0,
							0,
							0,
							0,
							0,
							0,
							0,
							0,
							0,
							@cust_id,
							0,
							0
						)
		END

	RETURN
END
GO





-- =============================================
-- Author:		MOS
-- Create date: 08-2020
-- Description:	Retorna una tabla con las rows
--				disponibles para la sucursal
--				para efectuar notas de credito
--				o notas de debito.
-- =============================================
CREATE FUNCTION [dbo].[fnDocumentsFile_GetDocumentsForChequeRejection]
(
	@comp_id			int ,
	@bra_id				int ,
	@cust_id			int
)
RETURNS TABLE
AS
RETURN
(
	SELECT 	DF.df_id ,
			DF.df_desc ,
			VDF.sd_isCreditNote,
			VDF.sd_isDebitNote,
			DF.df_order,
			df.sd_id,
			df.df_favorite4ChequeRejection

	FROM 	dbo.tbDocumentsFile					DF						WITH (NOLOCK)
		Inner Join dbo.vwsysDocuments_forSaleOrder	VDF						WITH (NOLOCK)
			On VDF.sd_id		=	DF.sd_id
	WHERE 	DF.comp_id			=	@comp_id
		AND DF.bra_id			=	@bra_id
		AND DF.df_Disabled		= 'False'
		AND CASE
				WHEN df.sd_id = 4												THEN 1
				WHEN df.sd_id = 21 AND df.df_favorite4ChequeRejection = 'True'	THEN 1
				ELSE 0
			END = 1
		AND	(dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id) )	like '%' + DF.df_kindOf  + '%'  )


)
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Retorna una tabla con las rows
--				disponibles para la sucursal
--				para efectuar algun documento del tipo sd_id
-- =============================================
CREATE FUNCTION [dbo].[fnDocumentsFile_GetDocumentsForCustomers]
(
	@comp_id			int ,
	@bra_id				int ,
	@cust_id			int
)
RETURNS TABLE
AS
RETURN
(
	SELECT 	DF.df_id ,
			DF.df_desc ,
			DF.df_order,
			df.sd_id,
			df.df_pointOfSale,
			CASE
			    WHEN df.df_favorite4ML		= 1  THEN	1
			    ELSE									0
			END											[is4ML],
			CASE
			    WHEN df.df_favorite4WebSite = 1  THEN	1
			    ELSE									0
			END											[is4WS],
			CASE
			    WHEN df.df_favorite4fullJaus = 1  THEN	1
			    ELSE									0
			END											[is4FJ]		,
			ISNULL(df.mls_id,-1)						[mls_id],
			ISNULL(df.df_is4mlo4FulFillment,'False')	[df_is4mlo4FulFillment]



	FROM 	dbo.tbDocumentsFile					DF				WITH (NOLOCK)
		Inner Join dbo.vwsysDocuments_forSaleOrder	VDF				WITH (NOLOCK)
			On VDF.sd_id		=	DF.sd_id
	WHERE 	DF.comp_id			=	@comp_id
		AND DF.bra_id			=	@bra_id
		AND DF.df_Disabled		= 'False'
		AND	(LTRIM(RTRIM( dbo.fnGetFiscalCustomer_KindOf(@cust_id) ))	like '%' + DF.df_kindOf  + '%'  )
		--AND ( VDF.sd_isCreditNote = 'True' or  VDF.sd_isDebitNote = 'True' )



)
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Retorna una tabla con las rows
--				disponibles para la sucursal
--				para efectuar notas de credito
--				o notas de debito.
-- =============================================
CREATE FUNCTION [dbo].[fnDocumentsFile_GetDocumentsForDebitCreditNotes]
(
	@comp_id			int ,
	@bra_id				int ,
	@cust_id			int
)
RETURNS TABLE
AS
RETURN
(
	SELECT 	DF.df_id ,
			DF.df_desc ,
			VDF.sd_isCreditNote,
			VDF.sd_isDebitNote,
			DF.df_order,
			CASE
				WHEN df.sd_id IN (43,44) THEN 1
				ELSE 0
			END								[Is4ExchangeDifference],
			CASE
			    WHEN df.df_favorite4ML		= 1  THEN	1
			    ELSE									0
			END											[is4ML],
			CASE
			    WHEN df.df_favorite4WebSite = 1  THEN	1
			    ELSE									0
			END											[is4WS],
			CASE
			    WHEN df.df_favorite4fullJaus = 1  THEN	1
			    ELSE									0
			END											[is4FJ]	,
			ISNULL(df.mls_id,-1)						[mls_id]	,
			ISNULL(df.df_is4mlo4FulFillment,'False')	[df_is4mlo4FulFillment]

	FROM 	dbo.tbDocumentsFile					DF						WITH (NOLOCK)
	Inner Join dbo.vwsysDocuments_forSaleOrder	VDF						WITH (NOLOCK)
		On VDF.sd_id		=	DF.sd_id
	WHERE 	DF.comp_id			=	@comp_id
		AND DF.bra_id			=	@bra_id
		AND DF.df_Disabled		= 'False'
		AND	(dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id) )	like '%' + DF.df_kindOf  + '%'  )
		AND ( VDF.sd_isCreditNote = 'True' or  VDF.sd_isDebitNote = 'True' )

)
GO





-- =============================================
-- Author:		MOS
-- Create date: 05-2013
-- Description:	Retorna una tabla con las rows
--				disponibles para la sucursal
--				para efectuar FACTURAS
-- =============================================
CREATE FUNCTION [dbo].[fnDocumentsFile_GetDocumentsForInvoices]
(
	@comp_id			int ,
	@bra_id				int ,
	@cust_id			int
)
RETURNS TABLE
AS
RETURN
(
	SELECT 	DF.df_id ,
			DF.df_desc ,
			VDF.sd_isCreditNote,
			VDF.sd_isDebitNote,
			DF.df_order


	FROM 	dbo.tbDocumentsFile					DF					WITH (NOLOCK)
		Inner Join dbo.vwsysDocuments_forSaleOrder	VDF					WITH (NOLOCK)
			On VDF.sd_id		=	DF.sd_id
	WHERE 	DF.comp_id			=	@comp_id
		AND DF.bra_id			=	@bra_id
		AND DF.df_Disabled		= 'False'
		AND	(dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id) )	like '%' + DF.df_kindOf  + '%'  )
		AND ( VDF.sd_id = 1 )

)
GO





-- =============================================
-- Author:		MOS
-- Create date: 05-2013
-- Description:	Retorna una tabla con las rows
--				disponibles para la sucursal
--				para efectuar FACTURAS
-- =============================================
CREATE FUNCTION [dbo].[fnDocumentsFile_GetDocumentsForPackingList]
(
	@comp_id			int ,
	@bra_id				int ,
	@cust_id			int
)
RETURNS TABLE
AS
RETURN
(
	SELECT	TOP 10000
			DF.df_id ,
			DF.df_desc ,
			VDF.sd_isCreditNote,
			VDF.sd_isDebitNote,
			DF.df_order


		FROM 	dbo.tbDocumentsFile					DF					WITH (NOLOCK)
			Inner Join dbo.vwsysDocuments_forSaleOrder	VDF				WITH (NOLOCK)
				On VDF.sd_id		=	DF.sd_id
		WHERE 	DF.comp_id			=	@comp_id
			AND DF.bra_id			=	@bra_id
			AND DF.df_Disabled		= 'False'
			-- MOS 26-01-2022 x SecOne en Capacitacion
			--AND	(dbo.fnStrAllTrim( dbo.fnGetFiscalCustomer_KindOf(@cust_id) )	like '%' + DF.df_kindOf  + '%'  )
			AND ( VDF.sd_id = 2 )
		ORDER BY DF.df_order

)
GO



CREATE FUNCTION [dbo].[fnEmailCheck](@strEmail NVARCHAR(4000))
--Returns true if the string is a valid email address.
RETURNS bit
as
BEGIN
     DECLARE @valid bit
     IF @strEmail IS NOT NULL
          SET @strEmail = LOWER(@strEmail)
          SET @valid = 0
          IF @strEmail like '[a-z,0-9,_,-]%@[a-z,0-9,_,-]%.[a-z][a-z]%'
             AND LEN(@strEmail) = LEN(dbo.fnStripNonEmail(@strEmail))
             AND @strEmail NOT like '%@%@%'
             AND CHARINDEX('.@',@strEmail) = 0
             AND CHARINDEX('..',@strEmail) = 0
             AND CHARINDEX(',',@strEmail) = 0
             AND RIGHT(@strEmail,1) between 'a' AND 'z'
               SET @valid=1
     RETURN @valid
END
GO









CREATE FUNCTION [dbo].[fnGetAFIPChecksumVerification]
(
	@code		VARCHAR(200)
)
RETURNS INT
WITH EXECUTE AS CALLER
AS



BEGIN

-- ----------------------------------------------------------------
-- Testing
-- ----------------------------------------------------------------
/*
	DECLARE		@code	VARCHAR(200)
	SELECT		@code = '12345678901234567890134567890123456789'   --'111111111112233334444444444444455555555'
*/
-- ----------------------------------------------------------------

	DECLARE		@digit	INT,
				@index	INT,
				@sumPar	INT,
				@sumImpar INT


	if ISNUMERIC(@code) = 1 AND not dbo.fnStrAT('.', @code,1) > 0 AND not dbo.fnStrAT(',', @code,1) > 0
		BEGIN


			--===================================================================================
			--Paso 1: recuperamos la sumatoria de de los números en las posiciones impares y lo multiplicamos por 3
			SET @sumPar = 0
			SET @index = 1
			WHILE @index <= LEN(ltrim(rtrim(@code)))
			BEGIN
				SET @sumPar = @sumPar + CONVERT(INT, SUBSTRING(@code,@index,1))
				SET @index = @index + 2
			END
			SET @sumPar = @sumPar * 3
			--===================================================================================



			--===================================================================================
			--Paso 2: recuperamos la sumatoria de de los números en las posiciones pares
			SET @sumImpar = 0
			SET @index = 2
			WHILE @index <= LEN(ltrim(rtrim(@code)))
			BEGIN
				SET @sumImpar = @sumImpar + CONVERT(INT, SUBSTRING(@code,@index,1))
				SET @index = @index + 2
			END
			--===================================================================================



			--===================================================================================
			--Paso 3: sumatoria de los valores obtenidoes en los Pasos 1 y 2
			SET @sumPar = @sumPar + @sumImpar
			--===================================================================================



			--===================================================================================
			--Paso 4: obtenemos el menor número que sumado al valor del Paso 3 sea múltiplo de 10
			SET @digit = 0
			WHILE ((@sumPar + @digit)%10) <> 0
			BEGIN
				SET @digit = @digit + 1
			END
			--===================================================================================
		END
	ELSE
		BEGIN
			SET @digit = 0
		END

--==
--select @digit
--==

	RETURN (select @digit)

END

GO




