-- ----------------
-- MOS
-- ----------------

CREATE FUNCTION [dbo].[fnGetAStock]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	int,
	@priority	decimal(14,4) = 9999999999.9999
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS




BEGIN





-- ---------------------------------------------------
-- Testing
-- ---------------------------------------------------
/*
	declare			@comp_id	int,
					@stor_id	int,
					@item_id	int,
					@priority	decimal(14,4)
	select			@comp_id	=1,
					@stor_id	=3,
					@item_id	=485,
					@priority	=9999999999
*/
-- ---------------------------------------------------


	IF @stor_id IS NULL SET @stor_id = -10


	-- ----------------------------------------------------------------------------------------------------
	-- si el Item Id viene en negativo asume que es ese articulo y NO toma en cuenta el grupo de depositos.
	-- ----------------------------------------------------------------------------------------------------
	DECLARE @bolOnlyOneStorage AS BIT
	SET		@bolOnlyOneStorage = 'False'
	IF @item_id < 0
		BEGIN
			SET @item_id = @item_id * -1
			SET @bolOnlyOneStorage = 'True'
		END
	-- ----------------------------------------------------------------------------------------------------


	-- Si el articulo NO controla Stock retorna siempre un potencial de 99999999
	IF EXISTS(
				SELECT TOP 1 1
					FROM dbo.tbitem		WITH (NOLOCK,INDEX(IX_tbItem_NoStockCheck))
					WHERE	comp_id				= @comp_id	AND
							item_id				= @item_id	AND
							item_NoStockCheck	= 'True'
				)
		BEGIN
			RETURN( 99999999 )
		END




	Declare @nAStock		as decimal(19,5)
	Declare @bit4Production AS BIT

	IF @priority < 0	-- Si se quiere saber los items que tienen pedidos de produccion asociados y esta funcion es llamada por la funcion [fnGetAStock4Composition] que manda la prioridad multiplicada por -1
		BEGIN
			SET  @bit4Production	= 'True'
			SET @priority			= -1 * @priority
		END
	ELSE
		BEGIN
			SET  @bit4Production	= 'False'
		END

	DECLARE @bitIncludePurchaseOrders AS BIT
	SET		@bitIncludePurchaseOrders = 'False'

	-- ----------------------------------------------------------------------------------------------
	-- POngo en una Tabla los Depositos que debere tener en cuenta para el calculo de stock potencial
	-- ----------------------------------------------------------------------------------------------
	DECLARE @tblStorage AS TABLE(intStorageId INT PRIMARY KEY)
	IF @bolOnlyOneStorage = 'True' AND @stor_id > 0 -- Solo del deposito, no del grupo...
		BEGIN
			INSERT INTO @tblStorage(intStorageId) VALUES (@stor_id)
		END

	ELSE IF @stor_id = -1
		BEGIN
			INSERT INTO @tblStorage(intStorageId)		SELECT ts.stor_id
															FROM dbo.tbStorage ts		WITH (NOLOCK)
			                                   				WHERE	ts.comp_id		= @comp_id AND
			                                   						ts.stor_web4ALL = 'True'
		END
	ELSE
		BEGIN
			-- ----------------------------------------------------------------------------------
			-- NOTA, un deposito SOLO puede pertenecer a un grupo de Depositos para POTENCIAL!!!!
			-- Para que se incluya todo el grupo a un grupo de depositos debe tener el campo
			-- stor_IncludeStockOfStorageGroupMembers en TRUE
			-- ----------------------------------------------------------------------------------
			DECLARE @intStorageGroups AS INT
			SET		@intStorageGroups = NULL
			--SELECT Top 1 @intStorageGroups = tsgd.storg_id
			--	FROM tbStorageGroupDetail tsgd		WITH (NOLOCK)
			--	INNER JOIN tbStorageGroup tsg		WITH (NOLOCK)
			--		ON	tsg.comp_id		= tsgd.comp_id	AND
			--			tsg.storg_id	= tsgd.storg_id
         	--	WHERE	tsgd.comp_id	= @comp_id		AND
         	--			tsgd.stor_id	= @stor_id
			--  ORDER BY tsg.storg_order,tsgd.storg_order
			-- ----------------------------------------------------------------------------------
			DECLARE @bitIncludeStorageGroups BIT
			SELECT	@bitIncludeStorageGroups =	CASE
													WHEN ts.storg_id IS NULL THEN 'False'
													ELSE IsNull(ts.stor_IncludeStockOfStorageGroupMembers,'False')
												END,
					@intStorageGroups		 = ts.storg_id,
					@bitIncludePurchaseOrders= ts.stor_includePurchaseOrderinAvailableStock
				FROM dbo.tbStorage ts					WITH (NOLOCK)
				WHERE	ts.comp_id = @comp_id AND
						ts.stor_id = @stor_id

			INSERT INTO @tblStorage(intStorageId)
				VALUES (@stor_id)

			IF @bitIncludeStorageGroups = 'True'
				BEGIN
					INSERT INTO @tblStorage(intStorageId)
						SELECT Distinct tsgd.stor_id
							FROM dbo.tbStorageGroupDetail tsgd		WITH (NOLOCK)
							WHERE	tsgd.comp_id	=  @comp_id				AND
									--tsgd.stor_id IS NOT NULL				AND
									tsgd.storg_id	=  @intStorageGroups	AND
									tsgd.stor_id	<> @stor_id
				END
		END
	-- ----------------------------------------------------------------------------------------------





			select	@nAStock =	(		-- Stock Fisico
									   (
										select	isnull(sum(it.itst_cant),0)					-- Stock Fisico
											From	dbo.tbItemStorage		it		WITH (NOLOCK,INDEX(IX_tbItemStorage_1L))	 -- MOS 12-2022  --WITH (NOLOCK)
											INNER JOIN @tblStorage ttst
												ON ttst.intStorageId = it.stor_id
											Where	it.comp_id	= @comp_id	AND
													it.item_id	= @item_id
									   )
										*	CASE
												WHEN @bit4Production='true' THEN 0
												ELSE							 1
										 	END		-- Si se pide la cantidad de pedidos del item Padre, es solo los pedidos sin el stock.
										)

								  -     -- RMA que descuentan Stock potencial
								        (
								        	SELECT ISNULL(SUM(trd.rmad_qty),0)
								        		FROM dbo.tbRMA_Detail trd	WITH (NOLOCK,INDEX(IX_tbRMA_Detail_IncludeInPotentialStock))
								        		INNER JOIN @tblStorage ttst
								        			ON ttst.intStorageId = trd.stor_id
								        		WHERE	trd.comp_id							= @comp_id AND
								        				trd.item_id							= @item_id AND
								        				trd.srpt_id							= 1        AND
								        				trd.rmad_IncludeInPotentialStock	= 1
								        )

								  -     -- RMA, Articulos Adicionales
								        (
								        	SELECT ISNULL(SUM(trd.rmaa_qty),0)
								        		FROM dbo.tbRMA_Detail_AddItems  trd	WITH (NOLOCK,INDEX(IX_tbRMA_Detail_AddItems_is4AvailableStock))
								        			INNER JOIN @tblStorage ttst
								        				ON ttst.intStorageId = trd.stor_id
								        		WHERE	trd.comp_id				= @comp_id AND
								        				trd.item_id				= @item_id AND
								        				trd.is4AbailableStock	= 1
								        )

								  -     -- MercadoLibre, Pendientes de Generar un Pedido
								        (
								        	SELECT ISNULL(SUM(trd.mlo_quantity),0)
								        		FROM dbo.tbMercadoLibre_ordersDetail   trd	WITH (NOLOCK,INDEX(IX_tbMercadoLibre_ordersDetail_mlo_is4AvailableStock))
								        				INNER JOIN @tblStorage ttst
								        					ON ttst.intStorageId = trd.stor_id
								        			WHERE	trd.comp_id					= @comp_id AND
								        					trd.item_id					= @item_id AND
								        					trd.mlo_is4AvailableStock	= 1

								        )

								  -		-- Pedidos Pendientes

										(select	isnull(sum((
																sod.sod_qty - dbo.fnGetAStock_Produced(sod.comp_id,sod.soh_id,sod.sod_id)
														   )
														   *					-- Pedidos que no se estan Editando
														   sysdoc.sd_plusOrminus	-- MOS 07-2021 x speed
															--Case
															--	When sysdoc.sd_isCredit = 'True' Then -1
															--	Else 1
															--End
															),0)
											From	dbo.tbSaleOrderDetail	sod			WITH (NOLOCK,INDEX(IX_tbSaleOrderDetail__4GetAStock))	-- MOS 06-2023: puse indice forzado que tiene TODOS los campos que se usan en esta query
											INNER JOIN @tblStorage ttst
												ON ttst.intStorageId = sod.stor_id
											INNER JOIN dbo.tbSaleOrderHeader tsoh		WITH (NOLOCK,INDEX(IX_tbSaleOrderHeader__4GetAStock))	-- MOS 06-2023:  OJO, si se llega a usar otro campo en esta quety de tbsaleorderheader, ponerlo SI O SI en este indice!!!!
												ON	tsoh.comp_id	= sod.comp_id
												AND tsoh.bra_id		= sod.bra_id
												AND tsoh.soh_id		= sod.soh_id
											INNER JOIN dbo.tbDocumentsFile tdf			WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
												ON	tdf.comp_id = tsoh.comp_id AND
													tdf.df_id	= tsoh.df_id
											INNER JOIN dbo.tbsysDocuments sysdoc		WITH (NOLOCK,INDEX(IX_tbsysDocuments_4getAStock))
												ON sysdoc.sd_id = tdf.sd_id

											Where	sod.comp_id							= @comp_id
												and	sod.item_id							= @item_id
												AND sod.sod_exclude4AvailableStock		= 'False'
												and	sysdoc.sd_isQuotation				= 0				-- MOS 07-2021
												AND tdf.df_exclude4AvailableStock		= 'False'		-- MOS 21-10-2019
												and	(
														CASE
															WHEN sod.sod_isEditing = 'False' THEN	'True'
															WHEN sod.sod_isEditing IS NULL   THEN	'True'
															-- Cuando se borro el item en el pedido o se modifico su cantidad.!!!!			-- NO PONER COMO LEFT, en este caso es MAS rapido así ! ! !
															WHEN sod.sod_isEditing = 'True' AND		NOT EXISTS	(	SELECT TOP 1 1		-- Se verificó y no pone mas lento, son POCAS las rows q cumplen esto y no salen x el 1er case
																														FROM dbo.tbTempItemStock ttis				WITH (NOLOCK) -- OJO
															                                               				WHERE	ttis.comp_id	= sod.comp_id
															                                               					AND ttis.bra_id		= sod.bra_id
															                                               					AND ttis.soh_id		= sod.soh_id
															                                               					AND ttis.sod_id		= sod.sod_id
																															--AND ttis.tis_qty	= sod.sod_qty
																										)
																							THEN 'True'
															ELSE 'False'
														END	= 'True'
													--isnull(sod.sod_isEditing,'false')	= 'False'
													)
												and	 sod.sod_priority	<= @priority
												--and	not sod.sod_priority	> @priority  MOS 04-2021
												AND 	CASE
															WHEN @bit4Production = 'False' AND tdf.sd_id = 80 THEN 'False'--'False'   -- Aca chequea que entre por el padre en un pedido de produccion.  NO debe contarlo
															WHEN @bit4Production = 'True'  AND tdf.sd_id = 80 THEN 'true'
															WHEN @bit4Production = 'False'					  THEN 'true'
															ELSE				   'False'
														END	= 'True'
														-- Esto ultimo para asegurarme que no se toma en cuenta un pedido de produccion del mismo item (Padres de tbItemComposition)
														-- OJO con esto que puede hacer re lento todo!!!!!!!!

										)

									-	-- Pedidos Editandose

										(select isnull(sum( 					-- Pedidos que SI se estan editando
															Case
																When tis.tis_isCredit = 1 Then -1
																Else 1
															END
															*
															CASE
																-- Si es un Item Nuevo
																WHEN tis.sod_id is NULL				THEN tis.tis_qty
																-- Si es un Item Modificado lo suma arriba
																WHEN tis.tis_qty = tsod.sod_qty		THEN tis.tis_qty
																ELSE dbo.fnTempItemStock_getQtyBySOD(tis.comp_id,tis.bra_id,tis.soh_id,tis.sod_id,tis.tis_qty,tsod.sod_qty)
															END
														   ),0)
											From	dbo.tbTempItemStock		tis		WITH (NOLOCK)
											INNER JOIN @tblStorage ttst
												ON ttst.intStorageId = tis.stor_id
											INNER JOIN dbo.tbDocumentsFile tdf		WITH (NOLOCK,INDEX(IX_tbDocumentsFile_4getAStock))
												ON	tdf.comp_id = tis.comp_id and
													tdf.df_id	= tis.df_id
											LEFT JOIN dbo.tbSaleOrderDetail tsod	WITH (NOLOCK,INDEX(IX_tbSaleOrderDetail_sod_qtyV2))
												ON		tsod.comp_id	= tis.comp_id
													AND tsod.bra_id		= tis.bra_id
													AND tsod.soh_id		= tis.soh_id
													AND tsod.sod_id		= tis.sod_id

											Where	tis.comp_id							= @comp_id
												and	tis.item_id							= @item_id
												--and	tis.stor_id							= @stor_id
												AND tdf.df_exclude4AvailableStock		= 'False'		-- MOS 21-10-2019
												AND tis.tis_exclude4AvailableStock		= 'False'
												AND tis.it_transaction					IS null
												and	tis_isQuotation				 = 'False'
												and	 (	 tis.tis_priority <= @priority  )
												--and	NOT (	 tis.tis_priority >	 @priority  )  MOS 04-2021
												AND 	CASE
															WHEN @bit4Production = 'False' AND tdf.sd_id  = 80 THEN 'False'   -- Aca chequea que entre por el padre en un pedido de produccion.  NO debe contarlo
															WHEN @bit4Production = 'True'  AND tdf.sd_id  = 80 THEN 'true'
															WHEN @bit4Production = 'False'					   THEN 'true'
															ELSE				   'False'
														END	= 'True'

										)

	-- --------------------------------------
	-- Verifica Stock de tbItemComposition
	-- --------------------------------------
	-- MOS 04-2021 x performance se reemplaza fnGetAStock4Composition por lo unico que hace
	SELECT @nAStock = @nAStock + (  IsNull(dbo.fnGetAStock(@comp_id,@stor_id,tic.item_id,(-1 * @priority)),0)   * tic.icomp_qty  /*dbo.fnGetAStock4Composition(@comp_id,@stor_id,tic.item_id,@priority)*/ )	-- Solo suma si es NEGATIVO.!
		FROM dbo.tbItemComposition	tic			WITH (NOLOCK)
		INNER JOIN tbItem			ti			WITH (NOLOCK,INDEX(IX_tbItem_NoStockCheckV2))
			ON	ti.comp_id = tic.comp_id	AND
				ti.item_id = tic.item_id
		WHERE	tic.comp_id		= @comp_id	AND
				tic.item_id     <> @item_id	AND
				tic.item_id_1	= @item_id	AND
				ti.item_NoStockCheck = 'False'	AND
				ti.item_disabled = 'False'

	--IF EXISTS(	SELECT TOP 1 1
	--          		FROM dbo.tbItemComposition tic		WITH (NOLOCK)
	--				WHERE	tic.comp_id		= @comp_id AND
	--						tic.item_id_1	= @item_id
	--		)
	--	BEGIN
	--		SELECT @nAStock = @nAStock + (dbo.fnGetAStock4Composition(@comp_id,@stor_id,tic.item_id,@priority) * tic.icomp_qty)	-- Solo suma si es NEGATIVO.!
	--			FROM dbo.tbItemComposition	tic			WITH (NOLOCK)
	--			INNER JOIN tbItem			ti			WITH (NOLOCK)
	--				ON	ti.comp_id = tic.comp_id	AND
	--					ti.item_id = tic.item_id
	--			WHERE	tic.comp_id		= @comp_id	AND
	--					tic.item_id     <> @item_id	AND
	--					tic.item_id_1	= @item_id	AND
	--					ti.item_NoStockCheck = 'False'

	--	END
	-- --------------------------------------



	-- --------------------------------------
	-- Verifica Transferencias Internas
	-- --------------------------------------
	if ( @bit4Production='False' )
		BEGIN
			SELECT @nAStock = (@nAStock - tstt.stt_qty)
				FROM dbo.tbStorage_TransferTransactions tstt WITH (NOLOCK,INDEX(IX_tbStorage_TransferTransactions_getAStock))
				INNER JOIN @tblStorage tmp
					ON tmp.intStorageId = tstt.stor_id_From
				WHERE	tstt.comp_id				= @comp_id	AND
						tstt.item_id				= @item_id	AND
						tstt.stt_isCompleted		= 'False'	AND
						tstt.stt_isRejected			= 'False'	AND
						tstt.stt_isRequestPending	= 'False'
		END
	-- --------------------------------------



	IF @bitIncludePurchaseOrders = 'True' AND @bit4Production='False'
		BEGIN

			DECLARE @decPurchaseOrders AS DECIMAL(19,4)
			SET		@decPurchaseOrders = 0
			SELECT	@decPurchaseOrders = SUM(tpod.pod_qty)
				FROM dbo.tbPurchaseOrderDetail tpod					WITH (NOLOCK,INDEX(IX_tbPurchaseOrderDetail_4getAStock))
				INNER JOIN dbo.tbPurchaseOrderHeader tpoh			WITH (NOLOCK,INDEX(IX_tbPurchaseOrderHeader_4getAStock))
					ON	tpoh.comp_id		= tpod.comp_id	AND
						tpoh.bra_id			= tpod.bra_id	AND
						tpoh.poh_id			= tpod.poh_id
				WHERE	tpod.comp_id						= @comp_id	AND
						tpod.item_id						= @item_id	AND
						tpod.pod_includeInAvailableStock	= 1			AND
						tpod.pod_isProcessed				= 0			AND
						tpoh.poh_quotation					= 0

			SET @nAStock = (@nAStock + IsNull(@decPurchaseOrders,0))
			--SET @nAStock = @nAStock
			--SET @nAStock =  IsNull(@decPurchaseOrders,0)
		END




	RETURN (select @nAStock)

end

GO





-- =============================================
-- Author:		<Author,,Name>
-- Create date: Se usa para saber de un determinado pedido cuantos YA fueropn Producidos.
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnGetAStock_Produced]
(
	@comp_id AS INT,
	@soh_id AS INT,
	@sod_id AS INT
)
RETURNS INT	WITH SCHEMABINDING	-- MOS 11-2021 x speed
AS
BEGIN

	RETURN IsNull((	SELECT COUNT(*)
						FROM dbo.tbSaleOrderSerialProduced tsp		WITH (NOLOCK)	--WITH (NOLOCK,INDEX(IX3_tbSaleOrderSerialProduced))
	               		WHERE	tsp.comp_id = @comp_id AND
	               				tsp.soh_id	= @soh_id AND
	               				tsp.sod_id	= @sod_id ),0)

END
GO








-- ----------------
-- MOS
-- ----------------

CREATE FUNCTION [dbo].[fnGetAStock2StringOfMyItemSelectionStorages]
(
	@comp_id	int,
	@bra_id		INT,
	@prof_id	INT,
	@user_id	INT,
	@stor_id	int,
	@item_id	int
)


RETURNS NVARCHAR(4000)
WITH EXECUTE AS CALLER
AS

BEGIN

	DECLARE @strReturn AS NVARCHAR(4000)
	SET @strReturn = ''

	-- Stocks de sus depositos en la seleccion de articulos separados por LF y CR
	DECLARE @decTOTAL AS DECIMAL(29,0)
	SET		@decTOTAL = 0



    SELECT @strReturn = @strReturn +
						ts.stor_desc + '.:' +
						CONVERT(NVARCHAR(20), CONVERT(DECIMAL(29,0), dbo.fnGetAStock(@comp_id, ts.stor_id, @item_id, 899999999))) + CHAR(13) + CHAR(10),
		   @decTOTAL  = @decTOTAL + dbo.fnGetAStock(@comp_id, ts.stor_id, @item_id, 899999999)
		FROM tbItemSelection tis			WITH (NOLOCK)
		INNER JOIN tbStorage ts				WITH (NOLOCK)
			ON	ts.comp_id		= tis.comp_id	AND
				ts.stor_id		= tis.stor_id
		WHERE	tis.comp_id		= @comp_id		AND
				tis.bra_id		= @bra_id		AND
				tis.prof_id		= @prof_id		AND
				tis.stor_id		IS NOT NULL		AND
				tis.stor_id     <> @stor_id		AND
				tis.is_disabled = 'False'
		GROUP BY ts.stor_id, ts.stor_desc, tis.is_order
		HAVING dbo.fnGetAStock(@comp_id, ts.stor_id, @item_id, 899999999) > 0
		ORDER BY tis.is_order



	SET @strReturn = @strReturn + ' | ' + CONVERT(NVARCHAR(20),@decTOTAL)


	RETURN @strReturn

END

GO





-- MOS
-- No usar directamente esta funcion salvo que MOS autorice.!!!!   solo la usa funGetAStock para sacar el potencial si es que tiene composicion.-

CREATE FUNCTION [dbo].[fnGetAStock4Composition]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	int,
	@priority	decimal(14,4) = 9999999999.9999
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS
BEGIN

	DECLARE @decAStock AS DECIMAL(19,4)
	SET		@decAStock = IsNull(dbo.fnGetAStock(@comp_id,@stor_id,@item_id,(-1 * @priority)),0)

	RETURN	@decAStock

END
GO





-- MOS 07-2016
-- Retorna el MAXIMO disponible de Itens en Combo
-- Se usa por ejemplo para ML

CREATE FUNCTION [dbo].[fnGetAStock4MaxAssociation]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	int,
	@priority	decimal(14,4)
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS
BEGIN

	DECLARE		@decAStock AS DECIMAL(19,4)
	SET			@decAStock = 999999999999
	--+10
	-- MOS 05-2013: Se puso el INT para que de siempre como ENTERO
	SELECT @decAStock = CONVERT(INT,dbo.fnGetMinimumValue(@decAStock,
											  IsNull(dbo.fnGetAStock(@comp_id,@stor_id,tic.item_id_1,@priority),0) / tic.iasso_qty -- MOS 01-2023: Al ser abajo en el filtro > 0 es al pedo llamar al nozdiv./ dbo.fnNoZDiv(tic.iasso_qty)
											 ))
		FROM tbItemAssociation  tic	WITH (NOLOCK)
			WHERE	tic.comp_id = @comp_id	AND
					tic.item_id = @item_id	AND
					tic.iasso_qty > 0		-- MOS Datasoft tema Notebboks  04-2020



	IF			@decAStock = 999999999999
		BEGIN
			SET @decAStock = dbo.fnGetAStock(@comp_id, @stor_id, @item_id, @priority)
		END


	RETURN @decAStock

END
GO





-- MOS 07-2016
-- Retorna el MAXIMO disponible de Itens en Combo
