-- MOS
-- retorna de todas las partes cual es el MINIMO stock que posee para producir

CREATE FUNCTION [dbo].[fnGetAStock4MaxComposition]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	int,
	@priority	decimal(14,4)
)


RETURNS decimal(25,5)	WITH EXECUTE AS CALLER
AS
BEGIN

	DECLARE @decAStock AS DECIMAL(25,5)
	SET		@decAStock = 999999999999


	SELECT @decAStock = CONVERT(INT,dbo.fnGetMinimumValue(@decAStock,
											  IsNull(dbo.fnGetAStock(@comp_id,@stor_id,tic.item_id_1,@priority),0) / tic.icomp_qty	-- se saco el nozdiv y se armo asi por velocidad
											 ))
		FROM tbItemComposition tic	WITH (NOLOCK)
		WHERE	tic.comp_id = @comp_id	AND
				tic.item_id = @item_id	AND
				tic.icomp_qty <> 0

	--SELECT @decAStock = dbo.fnGetMinimumValue(@decAStock,
	--										  IsNull(dbo.fnGetAStock(@comp_id,@stor_id,tic.item_id_1,@priority),0) / dbo.fnNoZDiv(tic.icomp_qty)
	--										 )
	--	FROM tbItemComposition tic	WITH (NOLOCK)
	--	WHERE	tic.comp_id = @comp_id AND
	--			tic.item_id = @item_id


	RETURN @decAStock

END
GO








-- ----------------
-- MOS
-- ----------------

CREATE FUNCTION [dbo].[fnGetAStock4Producteca]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	int,
	@priority	decimal(14,4) = 9999999999.9999
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS




BEGIN





-- ---------------------------------------------------
-- Testing
-- ---------------------------------------------------
/*
	declare			@comp_id	int,
					@stor_id	int,
					@item_id	int,
					@priority	decimal(14,4)
	select			@comp_id	=1,
					@stor_id	=3,
					@item_id	=485,
					@priority	=9999999999
*/
-- ---------------------------------------------------


	IF @stor_id IS NULL SET @stor_id = -10


	-- ----------------------------------------------------------------------------------------------------
	-- si el Item Id viene en negativo asume que es ese articulo y NO toma en cuenta el grupo de depositos.
	-- ----------------------------------------------------------------------------------------------------
	DECLARE @bolOnlyOneStorage AS BIT
	SET		@bolOnlyOneStorage = 'False'
	IF @item_id < 0
		BEGIN
			SET @item_id = @item_id * -1
			SET @bolOnlyOneStorage = 'True'
		END
	-- ----------------------------------------------------------------------------------------------------


	-- Si el articulo NO controla Stock retorna siempre un potencial de 99999999
	IF EXISTS(
				SELECT 1
					FROM dbo.tbitem		WITH (NOLOCK)
					WHERE	comp_id				= @comp_id	AND
							item_id				= @item_id	AND
							item_NoStockCheck	= 'True'
				)
		BEGIN
			RETURN( 99999999 )
		END




	Declare @nAStock		as decimal(19,5)
	Declare @bit4Production AS BIT

	IF @priority < 0	-- Si se quiere saber los items que tienen pedidos de produccion asociados y esta funcion es llamada por la funcion [fnGetAStock4Composition] que manda la prioridad multiplicada por -1
		BEGIN
			SET  @bit4Production	= 'True'
			SET @priority			= -1 * @priority
		END
	ELSE
		BEGIN
			SET  @bit4Production	= 'False'
		END

	DECLARE @bitIncludePurchaseOrders AS BIT
	SET @bitIncludePurchaseOrders = 'False'

	-- ----------------------------------------------------------------------------------------------
	-- POngo en una Tabla los Depositos que debere tener en cuenta para el calculo de stock potencial
	-- ----------------------------------------------------------------------------------------------
	DECLARE @tblStorage AS TABLE(intStorageId INT PRIMARY KEY)
	IF @bolOnlyOneStorage = 'True' AND @stor_id > 0 -- Solo del deposito, no del grupo...
		BEGIN
			INSERT INTO @tblStorage(intStorageId) VALUES (@stor_id)
		END

	ELSE IF @stor_id = -1
		BEGIN
			INSERT INTO @tblStorage(intStorageId)		SELECT ts.stor_id
															FROM dbo.tbStorage ts		WITH (NOLOCK)
			                                   				WHERE	ts.comp_id		= @comp_id AND
			                                   						ts.stor_web4ALL = 'True'
		END
	ELSE
		BEGIN
			-- ----------------------------------------------------------------------------------
			-- NOTA, un deposito SOLO puede pertenecer a un grupo de Depositos para POTENCIAL!!!!
			-- Para que se incluya todo el grupo a un grupo de depositos debe tener el campo
			-- stor_IncludeStockOfStorageGroupMembers en TRUE
			-- ----------------------------------------------------------------------------------
			DECLARE @intStorageGroups AS INT
			SET @intStorageGroups = NULL
			--SELECT Top 1 @intStorageGroups = tsgd.storg_id
			--	FROM tbStorageGroupDetail tsgd		WITH (NOLOCK)
			--	INNER JOIN tbStorageGroup tsg		WITH (NOLOCK)
			--		ON	tsg.comp_id		= tsgd.comp_id	AND
			--			tsg.storg_id	= tsgd.storg_id
         	--	WHERE	tsgd.comp_id	= @comp_id		AND
         	--			tsgd.stor_id	= @stor_id
			--  ORDER BY tsg.storg_order,tsgd.storg_order
			-- ----------------------------------------------------------------------------------
			DECLARE @bitIncludeStorageGroups BIT
			SELECT	@bitIncludeStorageGroups =	CASE
													WHEN ts.storg_id IS NULL THEN 'False'
													ELSE IsNull(ts.stor_IncludeStockOfStorageGroupMembers,'False')
												END,
					@intStorageGroups		 = ts.storg_id,
					@bitIncludePurchaseOrders= ts.stor_includePurchaseOrderinAvailableStock
				FROM dbo.tbStorage ts					WITH (NOLOCK)
				WHERE	ts.comp_id = @comp_id AND
						ts.stor_id = @stor_id

			INSERT INTO @tblStorage(intStorageId)
				VALUES (@stor_id)

			IF @bitIncludeStorageGroups = 'True'
				BEGIN
					INSERT INTO @tblStorage(intStorageId)
						SELECT Distinct tsgd.stor_id
							FROM dbo.tbStorageGroupDetail tsgd		WITH (NOLOCK)
							WHERE	tsgd.comp_id	=  @comp_id				AND
									--tsgd.stor_id IS NOT NULL				AND
									tsgd.storg_id	=  @intStorageGroups	AND
									tsgd.stor_id	<> @stor_id
				END
		END
	-- ----------------------------------------------------------------------------------------------





			select	@nAStock =	(		-- Stock Fisico
									   (
										select	isnull(sum(it.itst_cant),0)					-- Stock Fisico
											From	dbo.tbItemStorage		it
											INNER JOIN @tblStorage ttst
												ON ttst.intStorageId = it.stor_id
											Where	it.comp_id	= @comp_id
												--and	it.stor_id  = @stor_id
												and	it.item_id	= @item_id
									   )
										* CASE WHEN @bit4Production='true' THEN 0 ELSE 1 END		-- Si se pide la cantidad de pedidos del item Padre, es solo los pedidos sin el stock.
										)

								  -     -- RMA que descuentan Stock potencial
								        (
								        	SELECT ISNULL(SUM(trd.rmad_qty),0)
								        		FROM dbo.tbRMA_Detail trd	WITH (NOLOCK)
								        		INNER JOIN @tblStorage ttst
								        			ON ttst.intStorageId = trd.stor_id
								        	WHERE	trd.comp_id = @comp_id AND
								        			trd.item_id = @item_id AND
								        			--trd.stor_id = @stor_id AND
								        			trd.srpt_id = 1        AND
								        			trd.rmad_IncludeInPotentialStock = 'True'
								        )

								  -		-- Pedidos Pendientes

										(select	isnull(sum((sod.sod_qty - dbo.fnGetAStock_Produced(sod.comp_id,sod.soh_id,sod.sod_id)) *					-- Pedidos que no se estan Editando
															Case
																When sysdoc.sd_isCredit = 'True' Then -1
																Else 1
															End
															),0)
											From	dbo.tbSaleOrderDetail	sod			WITH (NOLOCK)

											INNER JOIN dbo.tbSaleOrderHeader tsoh		WITH (NOLOCK)
												ON	tsoh.comp_id	= sod.comp_id
												AND tsoh.bra_id		= sod.bra_id
												AND tsoh.soh_id		= sod.soh_id
											INNER JOIN dbo.tbDocumentsFile tdf			WITH (NOLOCK)
												ON	--tdf.comp_id = tsoh.comp_id AND
													tdf.df_id	= tsoh.df_id
											INNER JOIN dbo.tbsysDocuments sysdoc		WITH (NOLOCK)
												ON sysdoc.sd_id = tdf.sd_id
											INNER JOIN @tblStorage ttst
												ON ttst.intStorageId = sod.stor_id
											Where	sod.comp_id							= @comp_id
												and	sod.item_id							= @item_id
												AND ISNULL(tsoh.soh_MLId,'') = ''
												--and	sod.stor_id							= @stor_id
												and	sysdoc.sd_isQuotation				= 'False'
												and	(
														CASE
															WHEN sod.sod_isEditing = 'False' THEN	'True'
															WHEN sod.sod_isEditing IS NULL   THEN	'True'
															-- Cuando se borro el item en el pedido o se modifico su cantidad.!!!!
															WHEN sod.sod_isEditing = 'True' AND		NOT EXISTS	(	SELECT 1
																														FROM dbo.tbTempItemStock ttis				WITH (NOLOCK) -- OJO
															                                               				WHERE	ttis.comp_id	= sod.comp_id
															                                               					AND ttis.bra_id		= sod.bra_id
															                                               					AND ttis.soh_id		= sod.soh_id
															                                               					AND ttis.sod_id		= sod.sod_id
																															--AND ttis.tis_qty	= sod.sod_qty
																										)
																							THEN 'True'
															ELSE 'False'
														END	= 'True'
													--isnull(sod.sod_isEditing,'false')	= 'False'
													)
												and	not sod.sod_priority	> @priority
												AND 	CASE
															WHEN @bit4Production = 'False' AND tdf.sd_id = 80 THEN 'False'--'False'   -- Aca chequea que entre por el padre en un pedido de produccion.  NO debe contarlo
															WHEN @bit4Production = 'True'  AND tdf.sd_id = 80 THEN 'true'
															WHEN @bit4Production = 'False'					  THEN 'true'
															ELSE				   'False'
														END	= 'True'
														-- Esto ultimo para asegurarme que no se toma en cuenta un pedido de produccion del mismo item (Padres de tbItemComposition)
														-- OJO con esto que puede hacer re lento todo!!!!!!!!

										)

									-	-- Pedidos Editandose

										(select isnull(sum( 					-- Pedidos que SI se estan editando
															Case
																When tis.tis_isCredit = 1 Then -1
																Else 1
															END
															*
															CASE
																-- Si es un Item Nuevo
																WHEN tis.sod_id is NULL				THEN tis.tis_qty
																-- Si es un Item Modificado lo suma arriba
																WHEN tis.tis_qty = tsod.sod_qty		THEN tis.tis_qty
																ELSE dbo.fnTempItemStock_getQtyBySOD(tis.comp_id,tis.bra_id,tis.soh_id,tis.sod_id,tis.tis_qty,tsod.sod_qty)
															END
														   ),0)
											From	dbo.tbTempItemStock		tis		WITH (NOLOCK)
											INNER JOIN @tblStorage ttst
												ON ttst.intStorageId = tis.stor_id
											INNER JOIN dbo.tbDocumentsFile tdf		WITH (NOLOCK)
												ON	--tdf.comp_id = tis.comp_id and
													tdf.df_id	= tis.df_id
											LEFT JOIN dbo.tbSaleOrderDetail tsod	WITH (NOLOCK)
												ON		tsod.comp_id	= tis.comp_id
													AND tsod.bra_id		= tis.bra_id
													AND tsod.soh_id		= tis.soh_id
													AND tsod.sod_id		= tis.sod_id
											LEFT JOIN dbo.tbSaleOrderHeader tsoh	WITH (NOLOCK)
												ON		tsoh.comp_id	= tsod.comp_id
													AND tsoh.bra_id		= tsod.bra_id
													AND tsoh.soh_id		= tsod.soh_id

											Where	tis.comp_id							= @comp_id
												and	tis.item_id							= @item_id
												AND ISNULL(tsoh.soh_MLId,'')			= ''
												--and	tis.stor_id							= @stor_id
												AND tis.it_transaction					IS null
												and	tis_isQuotation				 = 'False'
												and	NOT (	 tis.tis_priority >	 @priority  )
												AND 	CASE
															WHEN @bit4Production = 'False' AND tdf.sd_id  = 80 THEN 'False'   -- Aca chequea que entre por el padre en un pedido de produccion.  NO debe contarlo
															WHEN @bit4Production = 'True'  AND tdf.sd_id  = 80 THEN 'true'
															WHEN @bit4Production = 'False'					   THEN 'true'
															ELSE				   'False'
														END	= 'True'

										)

	-- --------------------------------------
	-- Verifica Stock de tbItemComposition
	-- --------------------------------------
	IF EXISTS(	SELECT 1
	          		FROM dbo.tbItemComposition tic		WITH (NOLOCK)
					WHERE	tic.item_id_1	= @item_id
						AND tic.comp_id		= @comp_id)
		BEGIN
			SELECT @nAStock = @nAStock + (dbo.fnGetAStock4Composition(@comp_id,@stor_id,tic.item_id,@priority) * tic.icomp_qty)	-- Solo suma si es NEGATIVO.!
				FROM dbo.tbItemComposition	tic			WITH (NOLOCK)
				INNER JOIN tbItem			ti			WITH (NOLOCK)
					ON	ti.comp_id = tic.comp_id	AND
						ti.item_id = tic.item_id
				WHERE	tic.comp_id		= @comp_id	AND
						tic.item_id_1	= @item_id	AND
						tic.item_id     <> @item_id	AND
						ti.item_NoStockCheck = 'False'

		END
	-- --------------------------------------



	-- --------------------------------------
	-- Verifica Transferencias Internas
	-- --------------------------------------
	if ( @bit4Production='False' )
		BEGIN
			SELECT @nAStock = (@nAStock - tstt.stt_qty)
				FROM dbo.tbStorage_TransferTransactions tstt WITH (NOLOCK)
				INNER JOIN @tblStorage tmp
					ON tmp.intStorageId = tstt.stor_id_From
				WHERE	tstt.comp_id				= @comp_id	AND
						tstt.item_id				= @item_id	AND
						tstt.stt_isCompleted		= 'False'	AND
						tstt.stt_isRejected			= 'False'	AND
						tstt.stt_isRequestPending	= 'False'
		END
	-- --------------------------------------



	IF @bitIncludePurchaseOrders = 'True' AND @bit4Production='False'
		BEGIN

			DECLARE @decPurchaseOrders AS DECIMAL(19,4)
			SET @decPurchaseOrders = 0
			SELECT @decPurchaseOrders = SUM(tpod.pod_qty)
				FROM dbo.tbPurchaseOrderDetail tpod					WITH (NOLOCK)
				INNER JOIN dbo.tbPurchaseOrderHeader tpoh			WITH (NOLOCK)
					ON	tpoh.comp_id		= tpod.comp_id	AND
						tpoh.bra_id			= tpod.bra_id	AND
						tpoh.poh_id			= tpod.poh_id
				WHERE	tpod.comp_id		= @comp_id	AND
						tpoh.poh_quotation	= 'False'	AND
						tpod.pod_isProcessed= 'False'	AND
						tpod.item_id		= @item_id
			SET @nAStock = (@nAStock + IsNull(@decPurchaseOrders,0))
			--SET @nAStock = @nAStock
			--SET @nAStock =  IsNull(@decPurchaseOrders,0)
		END




	RETURN (select @nAStock)

end

GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2009
-- Description:	Redondea segun la presicion de la sucursal
-- =============================================
CREATE FUNCTION fnGetBranchDecimalPlaces
	(
		@comp_id	as int,
		@bra_Id		as int
	)
RETURNS int

AS
BEGIN

	Return( Select IsNull(bra_TransactionDecimalPlaces ,2)
				From	dbo.tbBranch
				Where	comp_id		  = @comp_id
					and bra_id	      = @bra_id
		  )
END
GO






CREATE FUNCTION [dbo].[fnGetCheckPortfolio_ImportCuit]
(

	@comp_id				AS  INT,
	@lang_id				as  INT,
	@ba_id					AS  INT,
	@chp_taxNumber1			AS	varchar(50),
	@chp_taxNumber2			AS	varchar(50),
	@chp_taxNumber3			AS	varchar(50),
	@ltext_importe			AS  VARCHAR(80),
	@ltext_cantidad			AS	VARCHAR(80)

)


RETURNS NVARCHAR(4000)


AS




BEGIN






	-- ---------------------------------------------------
	-- Testing
	-- ---------------------------------------------------
/*

	declare		@comp_id				AS  INT,
				@lang_id				as  INT,
				@ba_id					AS  INT,
				@chp_taxNumber1			AS	varchar(50),
				@chp_taxNumber2			AS	varchar(50),
				@chp_taxNumber3			AS	varchar(50)


	select		@comp_id = 1 ,
				@lang_id = 2,
				@ba_id   = 31,
				@chp_taxNumber1='20544848896',
				@chp_taxNumber2='',
				@chp_taxNumber3=''
*/
	-- ---------------------------------------------------


	DECLARE @strQty_Val_cuit AS NVARCHAR(4000)

	SET @strQty_Val_cuit = ''





	SELECT @strQty_Val_cuit = ( select  @ltext_cantidad+ ' ' + + convert(varchar,count(*)) + ' ' + @ltext_importe + ' ' + + convert(varchar,isnull(sum(tcp1.chp_total),0)) [Importe]

									from tbCheckPortfolio						tcp1		WITH (NOLOCK)

									inner join tbCheckPortfolioMovements		tcpm		WITH (NOLOCK)
									on  tcpm.comp_id		= tcp1.comp_id AND
										tcpm.chp_id			= tcp1.chp_id  and
										tcpm.mm_isCancelled = 'False'

									inner join tbBranch							tb			WITH (NOLOCK)
									on  tb.bra_id		= tcp1.comp_id AND
										tb.bra_id		= tcp1.bra_id_PortFolio

									where	tcp1.comp_id			= @comp_id   and
									     	tcpm.ba_id				= @ba_id	 and
									        tcp1.chp_isNegociated   = 'True'	 and
									   	   (tcp1.chp_PayDate		>=	tb.bra_processingDate - 3 )

									and	(
											isnull(tcp1.chp_taxNumber1,'') = @chp_taxNumber1 or isnull(tcp1.chp_taxNumber1,'') = @chp_taxNumber2 or isnull(tcp1.chp_taxNumber1,'') = @chp_taxNumber3 OR
								    		isnull(tcp1.chp_taxNumber2,'') = @chp_taxNumber1 or isnull(tcp1.chp_taxNumber2,'') = @chp_taxNumber2 or isnull(tcp1.chp_taxNumber2,'') = @chp_taxNumber3 OR
											isnull(tcp1.chp_taxNumber3,'') = @chp_taxNumber1 or isnull(tcp1.chp_taxNumber3,'') = @chp_taxNumber2 or isnull(tcp1.chp_taxNumber3,'') = @chp_taxNumber3
										)
								)


	--*test*--
	--SELECT @strQty_Val_cuit
	--*test*--


	RETURN @strQty_Val_cuit

END


GO

-- =================================MOS<Author,,Name>
-- Create date: 05-2020
-- Description:	basado en : [spCollection_getTotals]
-- Retorna los Intereses x Mora que se deben
-- generar junto al cupon de pago
-- =============================================
CREATE FUNCTION [dbo].[fnGetCollectionInterest]
(
		@comp_id			AS INT,
		@ct_transaction		AS INT,
		@ctl_id				AS INT
)
RETURNS DECIMAL(19,2)
AS
BEGIN

	DECLARE @decInterest4QuoteMora DECIMAL(19,2)
	SET		@decInterest4QuoteMora = 0
	SET		@decInterest4QuoteMora =
		isnull((
				SELECT	convert(decimal(18,2),round(sum(round(	CASE
																	WHEN tctl.comp_id IS NOT NULL THEN  tctl.ct_ABalance
																	ELSE								ct.ct_ABalance
																END
															  ,2) *
						ct.[ct_ACurrencyExchange] *
						CASE
							WHEN
								(
									CASE
										WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
										ELSE tctl.ctl_payDate
									END < tb.bra_processingDate
								)
									AND
								(
									(
										DATEDIFF(DAY,	CASE
													   		WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
													   		ELSE tctl.ctl_payDate
														END,tb.bra_processingDate
												)
											-
										dbo.fngetDiasDePandemia2(CASE
																	WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																	ELSE tctl.ctl_payDate
																END,
																tb.bra_processingDate,
																tdf.df_pandemyDaysFrom,
																tdf.df_pandemyDaysTo)
									)

											>

													CASE
														WHEN tctl.comp_id IS NULL THEN	tst.st_collectionInterestFromDays
														ELSE							tst.st_collectionLoanInterestFromDays
													END
								)
									THEN
											(
												(
												CASE
													WHEN tctl.comp_id IS NULL THEN tst.st_collectionInterest
													ELSE tst.st_collectionLoanInterest
												END
													/ 30
												)
												*
												(
													DATEDIFF(DAY,	CASE
																   		WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   		ELSE tctl.ctl_payDate
																	END,tb.bra_processingDate)
														-
													dbo.fngetDiasDePandemia2(CASE
																   				WHEN tctl.comp_id IS NULL THEN ct.ct_payDate
																   				ELSE tctl.ctl_payDate
																   			END,
																   			tb.bra_processingDate,
																			tdf.df_pandemyDaysFrom,
																			tdf.df_pandemyDaysTo)
												)
											) / 100
							ELSE			0
						END
					),2))

		from	tbCommercialTransactions								ct						WITH (NOLOCK)
		INNER JOIN tbDocumentsFile									AS tdf						WITH (NOLOCK)
			ON	tdf.comp_id = ct.comp_id	AND
				tdf.bra_id	= ct.bra_id		AND
				tdf.df_id	= ct.df_id
		INNER JOIN tbBranch											AS tb						WITH (NOLOCK)
			ON	tb.comp_id	= ct.comp_id AND
				tb.bra_id	= ct.bra_id
		INNER JOIN tbSalesTerms tst																WITH (NOLOCK)
			ON	tst.comp_id = ct.comp_id AND
				tst.st_id	= ct.st_id

		inner join dbo.vwCommercialTransactions_forSales				VCTFS					WITH (NOLOCK)
			on	VCTFS.comp_id					=	ct.comp_id
			and VCTFS.bra_id					=	ct.bra_id
			and VCTFS.ct_transaction			=	ct.ct_transaction
		LEFT JOIN tbCommercialTransactionsLoan							tctl					WITH (NOLOCK)
			ON	tctl.comp_id		= ct.comp_id			AND
				tctl.ct_transaction = ct.ct_transaction
		WHERE	ct.comp_id			= @comp_id			AND
				ct.ct_transaction	= @ct_transaction	AND
				(@ctl_id IS NULL OR (tctl.ctl_id = @ctl_id))
		),0)







	-- --------------------------------------------------------------------------
	-- Si es que hay algun interes busca el documento asociado al debito
	-- y el articulo para poder generar el pedido
	-- si no lo encuentra pone el interes en CERO
	-- --------------------------------------------------------------------------
	DECLARE @df_id		AS INT
	DECLARE @bra_id		AS INT
	DECLARE @cust_id	AS INT
	SELECT --@df_id	= tct.df_id,
		   @bra_id	= tct.bra_id,
		   @cust_id	= tct.cust_id
		FROM tbCommercialTransactions AS tct	WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction


	-- Obtiene el Recibo mediante el cual esta la conf de Intereses.
	SELECT @df_id = tdf.df_id
		FROM tbDocumentsFile AS tdf	WITH (NOLOCK)
			WHERE	tdf.comp_id		= @comp_id	AND
					tdf.bra_id		= @bra_id	AND
					tdf.sd_id		= 6			AND
					tdf.df_Collection_item_id4InterestDebit IS NOT NULL AND
					tdf.df_Disabled = 0


	DECLARE @df_Collection_Interest_Minimum AS DECIMAL(19,4)
	DECLARE @decInterestTaxes			AS DECIMAL(19,2)
	SET		@decInterestTaxes			= 0
	DECLARE @df_id4Interest				AS INT
	DECLARE @item_id4Interest			AS INT
	IF	@decInterest4QuoteMora				<> 0
		BEGIN

			SELECT
			       @item_id4Interest				= tdf.df_Collection_item_id4InterestDebit,
			       @df_Collection_Interest_Minimum	= tdf.df_Collection_Interest_Minimum
				FROM tbDocumentsFile tdf				WITH (NOLOCK)
				WHERE	tdf.comp_id = @comp_id AND
						tdf.df_id	= @df_id

			SELECT @df_id4Interest =  tdf.df_id
				FROM fnDocumentsFile_GetDocumentsForDebitCreditNotes(@comp_id, @bra_id, @cust_id) tdf
				INNER JOIN tbDocumentsFile tdf2			WITH (NOLOCK)
					ON	tdf2.comp_id	= @comp_id AND
						tdf2.df_id		= tdf.df_id
				WHERE	tdf.sd_isDebitNote						= 1		AND
						tdf.Is4ExchangeDifference				= 0		AND
						tdf2.df_Collection_Interest_isDebitNoteDocument = 1
				ORDER BY tdf.df_order



			-- Si NO estan configurados que NO calcule los Intereses !
			IF @df_id4Interest		IS NULL OR
			   @item_id4Interest	IS NULL
				BEGIN
					SET @decInterest4QuoteMora				= 0
				END

			-- Si el MINIMO INteres es mayor que lo calculado lo pone en CERO
			IF @df_Collection_Interest_Minimum > (@decInterest4QuoteMora )
				BEGIN
					SET @decInterest4QuoteMora				= 0
				END

				DECLARE @decCoefAux AS DECIMAL(25,6)
				SET @decCoefAux = dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id4Interest)

				SET @decInterestTaxes = (
											(
												@decInterest4QuoteMora
											 )
										 * @decCoefAux
										)

										-
										(
											@decInterest4QuoteMora
										 )
		END

	RETURN ISNULL(@decInterest4QuoteMora,0)	+  ISNULL(@decInterestTaxes,0)

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 08-2008
-- Description:	Retorna el Texto Descriptivo
--				de una CT
-- =============================================
CREATE FUNCTION [dbo].[fnGetCommercialTransactionDescription]
(
	@comp_id			as int,
	@lang_id			as int,
	@ct_transaction		as int
)
RETURNS nvarchar(50)	WITH SCHEMABINDING
AS
BEGIN

	-- Declare the return variable here
	DECLARE @strReturnValue			as varchar(50)
	Declare @strKindOf				as varchar(30)
	Declare @sd_id					as int
	Declare @strDocument			as varchar(20)
	DECLARE @strNickName			AS NVARCHAR(4)
	Declare @df_pointOfSale			as int
	Declare @ct_docNumber			as varchar(40)
	Declare @df_id					as INT
	DECLARE @bitIncludePointOfSale	AS BIT
	DECLARE @bitAvailable4BranchTransfer AS BIT

	SET @strNickName = ''

	Select @df_id					= ct.df_id ,
		   @df_pointOfSale			= ct.ct_pointOfSale,
		   @ct_docNumber			= ct.ct_docNumber,
		   @sd_id					= ct.sd_id,
		   @strKindOf				=	CASE
											WHEN tb.country_id = 54 THEN ct.ct_Kindof
											ELSE ''
										END,
		   @bitIncludePointOfSale		= td.sd_IncludePointOfSale,
		   @bitAvailable4BranchTransfer = tdf.df_isInterBranchDocument,
		   @strDocument					= LTrim(RTrim(a.optval_desc)),
		   @strNickName					= tdf.df_nickName

		From dbo.tbCommercialTransactions	ct		WITH (NOLOCK)

		INNER JOIN dbo.tbBranch tb						WITH (NOLOCK)

			ON	tb.comp_id		= ct.comp_id AND
				tb.bra_id		= ct.bra_id

		INNER JOIN dbo.tbsysDocuments			td		WITH (NOLOCK)
		ON td.sd_id = ct.sd_id

		LEFT JOIN dbo.tbDocumentsFile tdf				WITH (NOLOCK)
			ON		tdf.comp_id = ct.comp_id
				AND tdf.bra_id  = ct.bra_id
				AND tdf.df_id	= ct.df_id

		INNER JOIN dbo.tbsysOptionsValues A			WITH (NOLOCK)
			ON 		A.lang_id		= @lang_id
				and A.optval_class	= 6
				and A.optval_id		= ct.sd_id

		Where   ct.comp_id			= @comp_id
			and ct.ct_transaction	= @ct_transaction

	Set @strKindOf = IsNull(@strKindOf,'*')

	-- Saca la descripcion del comprobante
	--	Select @strDocument = LTrim(RTrim(optval_desc))
	--		From dbo.tbsysOptionsValues A
	--		Where   A.lang_id		= @lang_id
	--			and A.optval_class	= 6
	--			and A.optval_id		= @sd_id

		Set @strDocument	= Isnull(@strDocument,'*')
		IF	@strNickName	<> '' SET @strDocument = @strNickName
		IF	@bitAvailable4BranchTransfer = 'True' AND @sd_id = 1 OR @sd_id = 2 SET @strDocument    = @strDocument + 't'


		-- ---------------------------------
		IF	@bitIncludePointOfSale = 'True'
			Set @strReturnValue =	@strDocument + ' ' +
									@strKindOf + ' ' +
									dbo.PadString(@df_pointOfSale,'0',5) + '-' +
									dbo.PadString(@ct_docNumber,'0',
									CASE
										WHEN @sd_id < 10  THEN	8
										ELSE					10
									END
												 )

		ELSE
			Set @strReturnValue =	@strDocument + ' ' + dbo.PadString(@ct_docNumber,'0',15)
		-- ---------------------------------

		Set @strReturnValue = IsNull(@strReturnValue,'-')

	RETURN @strReturnValue

END
GO





