-- =============================================
CREATE FUNCTION [dbo].[fnGetCommercialTransactionRelatedCT]
(
	@comp_id			as int,
	@lang_id			as int,
	@ct_transaction		as int
)
RETURNS varchar(50)
AS
BEGIN

	SELECT @ct_transaction = ct_transaction_PackingList
		FROM dbo.tbCommercialTransactions tct
		WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id
			AND tct.ct_transaction	= @ct_transaction

	RETURN dbo.fnGetCommercialTransactionDescription(@comp_id,@lang_id,@ct_transaction)

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 08-2008
-- Description:	Retorna el Texto Descriptivo
--				de una CT
-- =============================================
CREATE FUNCTION [dbo].[fnGetCommercialTransactionSaleOrderDescription]
(
	@comp_id			as int,
	@lang_id			as int,
	@ct_transaction		as int
)
RETURNS varchar(50)
AS
BEGIN

	-- Declare the return variable here
	DECLARE @strReturnValue			as varchar(50)
	Declare @strKindOf				as varchar(30)
	Declare @sd_id					as int
	Declare @strDocument			as varchar(20)
	Declare @df_pointOfSale			as int
	Declare @ct_docNumber			as varchar(40)
	Declare @df_id					as INT
	DECLARE @bitIncludePointOfSale	AS bit


	Select @df_id					= ct.df_id ,
		   @df_pointOfSale			= ct.ct_soh_bra_id,
		   @ct_docNumber			= ct.ct_soh_id,
		   @sd_id					= 1001,
		   @strKindOf				= 'X',
		   @bitIncludePointOfSale	= 'True'

		From dbo.tbCommercialTransactions	ct			WITH (NOLOCK)
		INNER JOIN dbo.tbsysDocuments			td			WITH (NOLOCK)
		ON td.sd_id = ct.sd_id
		Where   comp_id			= @comp_id
			and ct_transaction	= @ct_transaction

	Set @strKindOf = IsNull(@strKindOf,'*')

	-- Saca la descripcion del comprobante
	Select @strDocument = LTrim(RTrim(optval_desc))
		From dbo.tbsysOptionsValues A
		WITH (NOLOCK)
		Where   A.lang_id		= @lang_id
			and A.optval_class	= 6
			and A.optval_id		= @sd_id

		Set @strDocument	= Isnull(@strDocument,'*')


		Set @strReturnValue =	@strDocument + ' ' +
								@strKindOf + ' ' +
								dbo.PadString(@df_pointOfSale,'0',4) + '-' +
								dbo.PadString(@ct_docNumber,'0',10)


		Set @strReturnValue = IsNull(@strReturnValue,'-')

	RETURN @strReturnValue

END
GO





-- =============================================
-- Author:		MOS
-- Description:	Retorna el valor correspondiente
-- segun sea el parametro pasado.
-- Se usa solo para que queden mas prolijos
-- algunos Stored Procedures complicados.-
-- @intSubTotalOrUtility
-- =============================================
CREATE FUNCTION [dbo].[fnGetCommissionBySubtotalOrUtility]
(
	@intSubTotalOrUtility	as int,
	@intCostOrCostAW		as int,
	@decSubtotal			as decimal(19,6),
	@decCost				as decimal(19,6),
	@decCostAW				as decimal(19,6),
	@decQty					as decimal(19,6),
	@decPercentaje			as decimal(19,6),
	@decSubtotalWithTaxes	AS DECIMAL(19,6)
)

RETURNS decimal(19,6)

AS
BEGIN


Return(
	Case
		When @intSubTotalOrUtility = 0								Then  @decSubtotal				 * @decQty	* @decPercentaje / 100
		When @intSubTotalOrUtility = 1 And @intCostOrCostAW = 0		Then (@decSubtotal - @decCost)   * @decQty	* @decPercentaje / 100
		When @intSubTotalOrUtility = 1 And @intCostOrCostAW = 1		Then (@decSubtotal - @decCostAW) * @decQty  * @decPercentaje / 100
		When @intSubTotalOrUtility = 2								Then  @decSubtotalWithTaxes 	 * @decQty  * @decPercentaje / 100
		Else 0
	End
	  )
END
GO





create FUNCTION [dbo].[fnGetCostListItemTaxesPercentage4Combo]
(
	@comp_id			INT,
	@bra_id				INT,
	@item_id			INT,
	@coslis_id			INT

)
RETURNS DECIMAL(30,8)
AS

BEGIN

	IF EXISTS(
					SELECT TOP 1 1
						FROM tbItemAssociation	tia					WITH (NOLOCK)
						INNER JOIN tbItem		ti					WITH (NOLOCK)
							ON	ti.comp_id = tia.comp_id	AND
								ti.item_id = tia.item_id
						WHERE	tia.comp_id = @comp_id		AND
								tia.item_id = @item_id		AND
								ti.item_ifHasItemAssociationSumPrices = 'True'
	)
		BEGIN	-- SOLO SI ES UN COMBO QUE SUMA LOS PRECIOS Y COSTOS DE LAS PARTES, PARA QUE RETORNE EL COEFICIENTE EQUIVALENTE DE IMPUESTOS DE TODAS SUS PARTES.-

				-- Esto es por si tienen diferentes impuestos cada item por lo que debo sacar un impuesto equivalente para el TOTAL

				-- Ver en **wefknjweknwe56423kllkh ya que en TODO logar donde se cargue un combo de esta manera se deberá hacer esto ! ! !
				DECLARE @decTotalImpuestos  AS DECIMAL(25,10)	= 0
				DECLARE @decTotalNeto	    AS DECIMAL(25,10)	= 0
				DECLARE @intItemsQTY		AS INT				= 0
				-- Sumo el TOTAL de articulos
				SELECT  @intItemsQTY = @intItemsQTY + (tia.iasso_qty)
					FROM tbItemAssociation tia					WITH (NOLOCK)
					WHERE	tia.comp_id = @comp_id AND
							tia.item_id = @item_id


				-- Sumo Algebraicamente todos los IVA
				SELECT @decTotalImpuestos = @decTotalImpuestos + (ttn.tax_percentage * tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.coslis_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') / 100   ),
					   @decTotalNeto      = @decTotalNeto      + (tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.coslis_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') )
					FROM tbItemAssociation				tia		WITH (NOLOCK)
					INNER JOIN tbBranch					tb		WITH (NOLOCK)
						ON	tb.comp_id	= @comp_id		AND
							tb.bra_id	= @bra_id
					INNER JOIN vwItemTaxesOnlyOneIvaTax4Combo tit		WITH (NOLOCK)	-- DEBE SER UNA SOLO PARA COMBOS Q TRAIGA EL COMPOSED SI EXISTE Y SINO EL NORMAL
																						-- aconsejo ante cambios de tbitemtaxes actualizar una tabla q tenga los imuestos sin combo y otra los con combo
						ON	tit.comp_id = tia.comp_id	AND
							tit.item_id = tia.item_id_1
					INNER JOIN tbTaxName				ttn		WITH (NOLOCK)
						ON	ttn.tax_id	= tit.tax_id	AND
							ttn.comp_id = tit.comp_id
					INNER JOIN tbItemCostList			tpli	WITH (NOLOCK)
						ON	tpli.comp_id = @comp_id		AND
							tpli.coslis_id = @coslis_id		AND
							tpli.item_id = tia.item_id_1
					WHERE	tia.comp_id = @comp_id		AND
							tia.item_id = @item_id

				-- Sumo Algebraicamente todos los Impuestos Internos
				SELECT @decTotalImpuestos = @decTotalImpuestos + (ttn.tax_percentage * tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.coslis_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') / 100 )
					FROM tbItemAssociation tia								WITH (NOLOCK)
					INNER JOIN tbBranch					tb					WITH (NOLOCK)
						ON	tb.comp_id	= @comp_id		AND
							tb.bra_id	= @bra_id
					INNER JOIN vwItemTaxesOnlyOneInternalTax  tit			WITH (NOLOCK)
						ON	tit.comp_id = tia.comp_id	AND
							tit.item_id = tia.item_id_1
					INNER JOIN tbTaxName  ttn								WITH (NOLOCK)
						ON	ttn.tax_id	= tit.tax_id	AND
							ttn.comp_id = tit.comp_id
					INNER JOIN tbItemCostList			tpli				WITH (NOLOCK)
						ON	tpli.comp_id = @comp_id		AND
							tpli.coslis_id = @coslis_id		AND
							tpli.item_id = tia.item_id_1
					WHERE	tia.comp_id = @comp_id		AND
							tia.item_id = @item_id


				RETURN (( ( (@decTotalImpuestos + @decTotalNeto) / dbo.fnNoZDiv(@decTotalNeto)) -1) * 100)
		END
	ELSE
		BEGIN
			RETURN ((dbo.fnNoZDiv( dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id) ) -1) *100 )
		END

	RETURN -1


END
GO





-- MOS 07-2024: Retorna el CUIT formateado, lo manden como lo manden si es q es un CUIT ( 11 caracteres )
CREATE FUNCTION [dbo].[fnGetCUITFormatted]
(
		@strCUIT VARCHAR(50)
)
RETURNS VARCHAR(50)
AS
BEGIN

	SET @strCUIT = REPLACE(@strCUIT,'-','')
	SET @strCUIT = REPLACE(@strCUIT,'.','')
	SET @strCUIT = REPLACE(@strCUIT,'/','')
	SET @strCUIT = dbo.fnStrAllTrim(@strCUIT)

	IF DATALENGTH(@strCUIT) = 11
		BEGIN
			SET @strCUIT = LEFT(@strCUIT, 2) + '-' + SUBSTRING(@strCUIT, 3, 8) + '-' + RIGHT(@strCUIT, 1);
		END

	RETURN @strCUIT

END
GO






CREATE FUNCTION [dbo].[fnGetDateFromLang]
(
    @date		DATETIME,
    @lang_id	INT
)
RETURNS VARCHAR(10)	WITH SCHEMABINDING
AS
BEGIN

    DECLARE @style INT
	SET @style  = (SELECT
					CASE @lang_id
						WHEN 1 THEN 101
						WHEN 2 THEN 103
						ELSE		103
					END)

    RETURN(convert(varchar,@date,@style))

END
GO






create FUNCTION [dbo].fnGetDateTimeAMPMFromLang
(
    @date		DATETIME,
    @lang_id	INT
)
RETURNS NVARCHAR(100)
AS
BEGIN

    DECLARE @style INT
	SET @style  = (SELECT
					CASE @lang_id
						WHEN 1 THEN 101
						WHEN 2 THEN 103
						ELSE		103
					END)

    RETURN	convert(varchar,@date,@style) + ' ' +
			CASE
				WHEN DATEPART(hour,@date) < 12 THEN 'AM'
				ELSE 'PM'
			END

END
GO






