(
    @date		DATETIME,
    @lang_id	INT
)
RETURNS NVARCHAR(100)
AS
BEGIN

    DECLARE @style INT
	SET @style  = (SELECT
					CASE @lang_id
						WHEN 1 THEN 101
						WHEN 2 THEN 103
						ELSE		103
					END)

    RETURN	convert(varchar,@date,@style) + ' ' +
