-- =============================================
-- Author:		MOS  05-2020
-- Create date: Dias a descontar DENTRO de la Pandemia
-- Esta &%$&%$ habria que sacarla NI BIEN se pueda ya que hace pesado todo al &%$&%$.
-- Si llega a molestarle a otro ponerla x configuracion.
-- =============================================
CREATE FUNCTION [dbo].[fngetDiasDePandemia]
(
	@paymentDay		AS DATETIME,
	@processingDate AS DATETIME
)
RETURNS INT
AS
BEGIN

	DECLARE @intPandemyDays AS INT = 0

	DECLARE @datPandemyBegin AS DATETIME = '2020-03-15'
	DECLARE @datPandemyEnd   AS DATETIME = '2020-05-30'

	SELECT @datPandemyBegin = dbo.fnGetEnd_or_BeginOfDate(@datPandemyBegin,'False')
	SELECT @datPandemyEnd	= dbo.fnGetEnd_or_BeginOfDate(@datPandemyEnd,'True')

	IF @paymentDay BETWEEN @datPandemyBegin AND @datPandemyEnd
		BEGIN
			SET @intPandemyDays = DATEDIFF(DAY,@paymentDay,@datPandemyEnd)
		END

	IF @paymentDay < @datPandemyBegin
		BEGIN
			SET @intPandemyDays = DATEDIFF(DAY,@datPandemyBegin,@datPandemyEnd)
		END

	RETURN @intPandemyDays

END
GO


-- =============================================
-- Author:		MOS  05-2020
-- Create date: Dias a descontar DENTRO de la Pandemia
-- Esta &%$&%$ habria que sacarla NI BIEN se pueda ya que hace pesado todo al &%$&%$.
-- Si llega a molestarle a otro ponerla x configuracion.
-- =============================================
CREATE FUNCTION [dbo].[fngetDiasDePandemia2]
(
	@paymentDay		AS DATETIME,
	@processingDate AS DATETIME,
	@datPandemyBegin AS DATETIME,
	@datPandemyEnd   AS DATETIME
)
RETURNS INT
AS
BEGIN

	IF @datPandemyBegin IS NULL RETURN 0
	IF @datPandemyEnd	IS NULL RETURN 0

	DECLARE @intPandemyDays AS INT = 0

	SELECT @datPandemyBegin = dbo.fnGetEnd_or_BeginOfDate(@datPandemyBegin,'False')
	SELECT @datPandemyEnd	= dbo.fnGetEnd_or_BeginOfDate(@datPandemyEnd,'True')

	IF @paymentDay BETWEEN @datPandemyBegin AND @datPandemyEnd
		BEGIN
			SET @intPandemyDays = DATEDIFF(DAY,@paymentDay,@datPandemyEnd)
		END

	IF @paymentDay < @datPandemyBegin
		BEGIN
			SET @intPandemyDays = DATEDIFF(DAY,@datPandemyBegin,@datPandemyEnd)
		END

	RETURN @intPandemyDays

END
GO



CREATE  FUNCTION fnGetEAN_CheckDigit
(
    @barcode    varchar(20)
)
RETURNS CHAR(1)
AS
BEGIN
    DECLARE
        @chk_digit    int,
        @chk        int

    DECLARE    @num TABLE
    (
        num    int
    )

    IF    LEN(@barcode) NOT IN (7, 12)
    BEGIN
        RETURN     NULL
    END

    INSERT INTO @num
    SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL  SELECT  5 UNION ALL SELECT  6 UNION ALL
    SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12

    SELECT    @chk_digit = SUM(CONVERT(int, SUBSTRING(@barcode, LEN(@barcode) - num + 1, 1)) * CASE WHEN num % 2 = 1 THEN 3 ELSE 1 END)
    FROM    @num
    WHERE    num    <= LEN(@barcode)

    SELECT    @chk_digit = (10 - (@chk_digit % 10)) % 10

     RETURN  CHAR(ASCII('0') + @chk_digit)
END
GO



Create  FUNCTION [dbo].[fnGetEAN_Encode4EAN13]
(
   @tcString AS NVARCHAR(20),
   @tlCheckd AS BIT
)
RETURNS NVARCHAR(20)
AS
BEGIN


	DECLARE		@lcLat		NCHAR(1),
				@lcMed		NCHAR(1),
				@lcRet		NVARCHAR(20),
				@lcJuego	NCHAR(1),
				@lcIni		NCHAR(1),
				@lcResto	NVARCHAR(20),
				@lcCod		NVARCHAR(20),
				@lnI		int,
				@lnChecksum	DECIMAL(19,4),
				@lnAux		DECIMAL(19,4)

	DECLARE		@tbJuego	TABLE( id INT,valor NVARCHAR(20))
	DECLARE 	@lnPri		DECIMAL(19,4)




	SET @lcRet = dbo.fnstrAlltrim(@tcString)

	IF	LEN(@lcRet) < 12
		BEGIN
			SET @lcRet = DBO.fnStrPADL(  DBO.fnStrAllTrim(@lcRet),13,'0')
		END

 --IF LEN(@lcRet)<>12
 --     RETURN ""
 --ENDIF




	IF LEN(@lcRet) < 13
		BEGIN
			SET @lcRet = @lcRet + DBO.fnGetEAN_CheckDigit(	@lcRet )
		END


	IF @tlCheckd = 'True'
		BEGIN
			RETURN @lcRet
		END

	SET @lnPri		= DBO.fnGetOnlyNumbers(LEFT(@lcRet, 1))

	INSERT INTO @tbJuego(id, valor) VALUES (1,'AAAAAACCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (2,'AABABBCCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (3,'AABBABCCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (4,'AABBBACCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (5,'ABAABBCCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (6,'ABBAABCCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (7,'ABBBAACCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (8,'ABABABCCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (9,'ABABBACCCCCC')
	INSERT INTO @tbJuego(id, valor) VALUES (10,'ABBABACCCCCC')


	SET @lcIni		= CHAR(@lnPri+35)
	SET @lcLat		= CHAR(33)
	SET @lcMed		= CHAR(45)
	SET @lcResto	= SUBSTRING(@lcRet, 2, 12)


	SET @lnI		= 1


	WHILE @lnI <= 12
		BEGIN
			set @lcJuego = SUBSTRING(
									( SELECT tmp.valor FROM @tbJuego tmp WHERE tmp.id = (@lnPri+1))
									, @lnI, 1)


			SET @lcResto =
			CASE
				WHEN @lcJuego = 'A' THEN  STUFF(@lcResto, @lnI, 1, CHAR( dbo.fnGetOnlyNumbers(SUBSTRING(@lcResto, @lnI, 1))+48))
				WHEN @lcJuego = 'B' THEN  STUFF(@lcResto, @lnI, 1, CHAR( dbo.fnGetOnlyNumbers(SUBSTRING(@lcResto, @lnI, 1))+65))
				WHEN @lcJuego = 'C' THEN  STUFF(@lcResto, @lnI, 1, CHAR( dbo.fnGetOnlyNumbers(SUBSTRING(@lcResto, @lnI, 1))+97))
				ELSE ''
			END



			SET @lnI = @lnI + 1
		END

	SET @lcCod = @lcIni+@lcLat+SUBSTRING(@lcResto, 1, 6)+@lcMed+SUBSTRING(@lcResto, 7, 6)+@lcLat


	return @lcCod

END
GO
