CREATE FUNCTION [dbo].[fnGetEnd_or_BeginOfDate]
(
    @date	DATETIME,
    @end	BIT					-- True = Ultima Hora, False Primera Hora
)
RETURNS DATETIME	WITH SCHEMABINDING
AS
BEGIN

    DECLARE @ldate DATETIME

	SELECT	@ldate	=
			CASE
				WHEN	@end = 'True'
					THEN DATEADD(millisecond,950,DATEADD(second,59,DATEADD(minute,59,DATEADD(hour,23,DATEADD(DAY,DATEDIFF(DAY,0,@date),0)))))
					ELSE DATEADD(DAY,DATEDIFF(DAY,0,@date),0)
				END

    RETURN(@ldate)

END
GO



  -- =============================================
  -- Author:		MOS
  -- Create date: 06-2008
  -- Updated      07-2009
  -- Description:	Retorna el Importe en la moneda
  --              solicitada
  -- PARAMETROS:
  --	@Ammount					Importe a Convertir
  --	@curr_id_1					Desde Moneda
  --	@curr_id_2					Hasta Moneda
  --	@forcedExchangeCurrency		Moneda del tipo de cambio Opcional
  --	@forcedExchange				Tipo de Cambio Opcional. Si es 0 NO LO USA
  --	@purchaseExchange   		Convertir a Tipo de Cambio Comprador
  -- =============================================
  CREATE FUNCTION [dbo].[fnGetExchange]
  (
  	@comp_id				as int	,
  	@Ammount				as Decimal(38,18),
  	@curr_id_1				as int ,
  	@curr_id_2				as int ,
  	@forcedExchangeCurrency as int,
  	@forcedExchange			as decimal(38,18),
  	@purchaseExchange   	as BIT
  )
  RETURNS Decimal(38,18)	WITH SCHEMABINDING
  AS
  BEGIN

  	-- -----------------------------------------------------------------
  	-- OJO, si la moneda de origen es diferenre a la que tiene definido
  	-- el tipo de cambio temporal, se pone a la cotizacion x defecto
  	-- O Sea:  @forcedExchangeCurrency debe ser = @curr_id_1 para que
  	--		   funcione.-
  	-- -----------------------------------------------------------------

	-- -----------------------------------------------------------------
	-- Si es la misma moneda retorna el importe sin hacer nada adicional
	-- 02-2010
	IF @curr_id_1 = @curr_id_2 OR @Ammount = 0
		BEGIN
			RETURN @Ammount
		END

	-- -----------------------------------------------------------------

  	If @forcedExchange <> 0 and (@forcedExchangeCurrency <> @curr_id_1)
  		Begin
  			Set @forcedExchange = 0
  		End

  	Return dbo.fnGetExchange2(
  							@comp_id,
  							@Ammount,
  							@curr_id_1,
  							@curr_id_2,
  							@forcedExchangeCurrency ,
  							@curr_id_2,
  							@forcedExchange,
  							@purchaseExchange
      						)
  END
GO





    -- =============================================
    -- Author:		MOS
    -- Create date: 06-2008
    -- Description:	Retorna el Importe en la moneda
    --              solicitada
    -- PARAMETROS:
    --	@Ammount					Importe a Convertir
    --	@curr_id_1					Desde Moneda
    --	@curr_id_2					Hasta Moneda
    --	@forcedExchangeCurrency1	Moneda DESDE del tipo de cambio Opcional
    --	@forcedExchangeCurrency2	Moneda HASTA del tipo de cambio Opcional
    --	@forcedExchange				Tipo de Cambio Opcional. Si es 0 NO LO USA
    --	@purchaseExchange   		Convertir a Tipo de Cambio Comprador
    -- =============================================
    CREATE FUNCTION [dbo].[fnGetExchange2]
    (
    	@comp_id					as int	,
    	@Ammount					as Decimal(38,18),
    	@curr_id_1					as int ,
    	@curr_id_2					as int ,
    	@forcedExchangeCurrency1	as int,
    	@forcedExchangeCurrency2	as int,
    	@forcedExchange				as decimal(38,18),
    	@purchaseExchange   		as BIT
    )
    RETURNS Decimal(38,18)	WITH SCHEMABINDING
    BEGIN
  	-- -----------------------------------------------------------------
  	-- Si es la misma moneda retorna el importe sin hacer nada adicional
  	-- 02-2010
  	IF @curr_id_1 = @curr_id_2 or @Ammount = 0
  		BEGIN
  			RETURN @Ammount
  		END

  	-- -----------------------------------------------------------------
    	DECLARE @decCalculatedExchange	AS FLOAT --DECIMAL(38,15)
    	DECLARE @returmAmmount			AS FLOAT = @Ammount				-- sino esta MIERDA si se hacia 1/70 cortaba a los 6 decimales si se multiplicaba abajo por @ammount en lugar de @returmAmmount
    	-- Toma el tipo de cambio forzado de 1 u otra manera
    	IF (@forcedExchange <> 0 AND ( (@curr_id_1 = @forcedExchangeCurrency1 AND @curr_id_2 = @forcedExchangeCurrency2) OR (@curr_id_1 = @forcedExchangeCurrency2 AND @curr_id_2 = @forcedExchangeCurrency1) ))
    		BEGIN
    			SET @decCalculatedExchange =
    				CASE
    					WHEN @curr_id_1 = @forcedExchangeCurrency1 AND @curr_id_2 = @forcedExchangeCurrency2 THEN @forcedExchange
    					WHEN @curr_id_1 = @forcedExchangeCurrency2 AND @curr_id_2 = @forcedExchangeCurrency1 THEN 1 /	CASE
    																														WHEN @forcedExchange = 0 THEN	1
    																														ELSE							@forcedExchange
    																													END--					dbo.fnNoZDiv(@forcedExchange)
    				END
    		END
    	ELSE
    		-- Se Calcula el tipo de cambio desde la Base de Datos.
  			BEGIN
  				select	@decCalculatedExchange =
  									Case
  										When @purchaseExchange = 'False' and  curr_id_1 =  @curr_id_1 Then (1 /		CASE
  																														WHEN	ce_exchange = 0			 THEN 1
  																														ELSE								  ce_exchange
  																													END		/*dbo.fnNoZDiv( ce_exchange)*/)
  										When @purchaseExchange = 'False' and  curr_id_1 <> @curr_id_1 Then      ce_exchange
  										When @purchaseExchange = 'True'	 and  curr_id_1 =  @curr_id_1 Then (1 /		CASE
  																														WHEN	ce_exchange_purchase = 0 THEN 1
  																														ELSE								  ce_exchange_purchase
  																													END		/*dbo.fnNoZDiv(ce_exchange_purchase )*/)
  										When @purchaseExchange = 'True'	 and  curr_id_1 <> @curr_id_1 Then      ce_exchange_purchase
  									End
  						from		dbo.tbCurrencyExchange	WITH (NOLOCK)
  						where		comp_id =	@comp_id
  								And (
  											(curr_id_1 = @curr_id_1		-- Aca esta pudiendo hacer un table scan
  										And  curr_id_2 = @curr_id_2)	-- Ver si no seria bueno separar en 2
  									OR									-- Busquedas con un Isnull o algo así
  											(curr_id_1 = @curr_id_2
  										And  curr_id_2 = @curr_id_1)
  									)
  			END

    	-- No se usa mas dado que es muy costoso llamar de una funcion a otra.
    	-- RETURN isnull(@Ammount * dbo.fngetExchangecoeficient(@comp_id,@curr_id_1,@curr_id_2,@decCalculatedExchange,@purchaseExchange) , 0)

    	RETURN isnull(@returmAmmount * @decCalculatedExchange, 0)
    	-- se uso @returmAmmount como FLOAT ya que si se la usaba como decimal DABA ERROR al truncar a 6 decimales el calculo, por ejemplo: 1 / 70 no respetando los decimales del tipo de datos Decimal.
    	-- Esto es seguro una CAGADA por tema Performance.
    END
    ----
  ----
GO







