--
  -- =============================================
  -- Author:		MOS
  -- Create date: 06-2008
  -- Updated 07-2009
  -- Description:	Retorna el tipo de cambio
  --
  --  *.ATENCION.*
  --	JAMAS USAR ESTA FUNCION.!!!!!!!!!!!!!!!!!!!
  --  OjO   OjO    Ojo.!     OjO    OjO
  --
  -- =============================================
  -- 02-2010: Funcion Incluida en Código
  --
  CREATE FUNCTION [dbo].[fnGetExchangeCoeficient]
  (
  	@comp_id			int	,
  	@curr_id_1			int ,
  	@curr_id_2			int ,
  	@forcedExchange		decimal(29,10),
  	@purchaseExchange   bit
  )
  RETURNS Decimal(29,10)
  AS
  BEGIN



  	Declare @decExchange  as Decimal(29,10)
  	Declare @tmpCurr_id_1 as int
  	If @curr_id_1 = @curr_id_2
  		BEGIN
  			Set @decExchange = 1
  		END

  	Else
  		Begin
  			If (@forcedExchange <> 0)
  				Begin
  					Set @decExchange = @forcedExchange
  				End
  			ELSE
  				BEGIN


  					select	@decExchange =
  										Case
  											When @purchaseExchange = 'False' and  curr_id_1 =  @curr_id_1 Then (1 / ce_exchange)
  											When @purchaseExchange = 'False' and  curr_id_1 <> @curr_id_1 Then      ce_exchange
  											When @purchaseExchange = 'True'	 and  curr_id_1 =  @curr_id_1 Then (1 / ce_exchange_purchase )
  											When @purchaseExchange = 'True'	 and  curr_id_1 =  @curr_id_1 Then      ce_exchange_purchase
  										End
  							from		dbo.tbCurrencyExchange		WITH (NOLOCK)
  							where		comp_id		= @comp_id
  									And curr_id_1	= @curr_id_2
  									And curr_id_2	= @curr_id_1

					IF @decExchange IS NULL
						BEGIN
  							select	@decExchange =
  												Case
  													When @purchaseExchange = 'False' and  curr_id_1 =  @curr_id_1 Then (1 / ce_exchange)
  													When @purchaseExchange = 'False' and  curr_id_1 <> @curr_id_1 Then      ce_exchange
  													When @purchaseExchange = 'True'	 and  curr_id_1 =  @curr_id_1 Then (1 / ce_exchange_purchase )
  													When @purchaseExchange = 'True'	 and  curr_id_1 =  @curr_id_1 Then      ce_exchange_purchase
  												End
  									from		dbo.tbCurrencyExchange		WITH (NOLOCK)
  									where		comp_id		= @comp_id
  											And curr_id_1	= @curr_id_1
  											And curr_id_2	= @curr_id_2
						END



  				END
  		END


	-- Return the result of the function
	RETURN @decExchange


  END
  ----
GO





-- =============================================
-- Author:		Retirna un coeficiente en base a 4 niveles de descuento
-- Create date: 08-2011
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnGetFinalDiscountCoeficient]
(
	@decDiscount1	as DECIMAL(19,4),
	@decDiscount2	as DECIMAL(19,4),
	@decDiscount3	as DECIMAL(19,4),
	@decDiscount4	as DECIMAL(19,4)
)
RETURNS DECIMAL(30,10)	WITH SCHEMABINDING
AS
BEGIN

	DECLARE @decCoeficient AS DECIMAL(30,8)

    set @decCoeficient=100-(IsNull(@decDiscount1,0))
    set @decCoeficient=@decCoeficient-(@decCoeficient/100)*IsNull(@decDiscount2,0)
    set @decCoeficient=@decCoeficient-(@decCoeficient/100)*IsNull(@decDiscount3,0)
    set @decCoeficient=@decCoeficient-(@decCoeficient/100)*IsNull(@decDiscount4,0)
    set @decCoeficient=(100 - @decCoeficient)/100

	-- Return the result of the function
	RETURN (1-@decCoeficient)

END


GO



