-- =============================================
-- Author: Pasted By MOS
-- Create date: 04-2009
-- Description:	Retorna el año mas la semana
-- fiscal de una fecha especificada.-
-- =============================================

CREATE function fnGetFiscalWeek (@startMonth varchar(2), @myDate datetime)
	returns int
as
begin
	declare @firstWeek datetime
	declare @weekNum int
	declare @year int
	set @year = datepart(year, @myDate)+1
	--Get 4th day of month of next year, this will always be in week 1
	set @firstWeek = convert(datetime, str(@year)+@startMonth+'04', 102)
	--Retreat to beginning of week
	set @firstWeek = dateadd(day, (1-datepart(dw, @firstWeek)), @firstWeek)
	while @myDate < @firstWeek --Repeat the above steps but for previous year
		begin
		  set @year = @year - 1
		  set @firstWeek = convert(datetime, str(@year)+@startMonth+'04', 102)
		  set @firstWeek = dateadd(day, (1-datepart(dw, @firstWeek)), @firstWeek)
		end
	set @weekNum = (@year*100)+((datediff(day, @firstweek, @myDate)/7)+1)
	return @weekNum
end

GO







CREATE FUNCTION [dbo].[fnGetFormula]
(
	@formula	AS  NVARCHAR(MAX),
	@type		AS	INT
)
RETURNS nvarchar(MAX)
AS
BEGIN

	Declare  @ret_formula as nvarchar(MAX)

	SET @ret_formula = @formula

	DECLARE @dato VARCHAR(100)

	DECLARE cursor_terminos CURSOR LOCAL FAST_FORWARD FOR
	SELECT	tov.optval_desc
		FROM	tbsysOptionsValues	tov
		WHERE	tov.lang_id			= -1
		AND		tov.optval_class	= -1

	OPEN cursor_terminos

	FETCH cursor_terminos INTO @dato

	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF @type =  1
			SELECT @ret_formula  = REPLACE(@ret_formula, @dato, dbo.fngettermino(@dato))
		ELSE
			SELECT @ret_formula  = REPLACE(@ret_formula, @dato, '1')

		FETCH cursor_terminos INTO @dato

	END

	CLOSE cursor_terminos
	DEALLOCATE cursor_terminos

	Return @ret_formula

END





GO


CREATE FUNCTION [dbo].[fnGetGuaranteeDaysInYearsAndMonths]
(

	@comp_id				AS  INT,
	@lang_id				AS  INT,
	@item_id				AS  INT

)
RETURNS NVARCHAR(4000)
AS

	BEGIN
		-- -----------------------------------------------------
		-- TESTING
		-- -----------------------------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@item_id	INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@item_id	= 492
		*/
		-- -----------------------------------------------------





		-- -----------------------------------------------------
		-- VARIABLES DE TRABAJO
		-- -----------------------------------------------------
			DECLARE
				@intGuaranteeDays	INT,
				@strMessage		VARCHAR(1000)
		-- -----------------------------------------------------



		-- -----------------------------------------------------
		-- RECUPERO LOS DIAS DE GARANTÍA DEL ARTÍCULO
		-- -----------------------------------------------------
			SELECT
				@intGuaranteeDays = ISNULL(ti.item_guarantee,0)
				FROM tbItem						ti
				WHERE	ti.comp_id = @comp_id	AND
						ti.item_id = @item_id
		-- -----------------------------------------------------

		-- -----------------------------------------------------
		-- RECUPERAMOS LAS LEYENDAS PARA ARMAR EL TEXTO
		-- -----------------------------------------------------
			DECLARE
				@strYear	VARCHAR(100),
				@strYearP	VARCHAR(100),
				@strMonth	VARCHAR(100),
				@strMonthP	VARCHAR(100)

			SET @strYear	= ''
			SET @strYearP	= ''
			SET @strMonth	= ''
			SET @strMonthP	= ''

			--AÑOS
			SELECT
				@strYearP			= tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30833
			--MESES
			SELECT
				@strMonthP			= tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 30834

			--AÑO
			SELECT
				@strYear			= tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 300046

			--MES
			SELECT
				@strMonth			= tut.utexts_desc
			FROM tbsysUniqueTexts				tut
			WHERE	tut.lang_id		= @lang_id	AND
					tut.utexts_id	= 300047

		-- -----------------------------------------------------



		DECLARE @intMonthRemainingOfYEARS	AS INT
		DECLARE @intDaysRemainingOfYEARS	AS DECIMAL(10,4)
		DECLARE @intYEARS					AS INT
		DECLARE @intMonth					AS INT

		SET @intYEARS					= CONVERT(INT, @intGuaranteeDays / 365)
		SET @intDaysRemainingOfYEARS	= @intGuaranteeDays - (@intYEARS * 365)
		SET @intMonth					= 0
		IF  @intDaysRemainingOfYEARS > 0
			BEGIN
				SET @intMonth = CEILING(@intDaysRemainingOfYEARS / 30)
			END



		-- -----------------------------------------------------
		-- SACAMOS LA DIFERENCIA PARA EXPRESARLA EN AÑOS Y MESES
		-- -----------------------------------------------------
			--ANTES RESTABA 1 en cada renglón, según ejemplo de internet
			--http://www.sqlservercentral.com/Forums/Topic1223326-392-1.aspx
			--[Years ]        = DATEDIFF(YEAR,0,ET-ST),
			--[Months]        = DATEPART(MONTH,ET-ST)
			SELECT
				@strMessage =
								CASE
									WHEN @intYEARS	= 0					THEN	''
									ELSE	CASE
												WHEN @intYEARS = 1		THEN	CONVERT(VARCHAR,@intYEARS)	+ ' ' + @strYear
												ELSE										CONVERT(VARCHAR,@intYEARS)	+ ' ' + @strYearP
											END
								END
																				+ ' ' +
								CASE
									WHEN @intMonth		= 0				THEN	''
									ELSE	CASE
												WHEN @intMonth   = 1	THEN	CONVERT(VARCHAR,@intMonth) + ' ' + @strMonth
												ELSE										CONVERT(VARCHAR,@intMonth) + ' ' + @strMonthP
											END
								END


		-- -----------------------------------------------------

		RETURN @strMessage

	END
GO





-- =============================================
-- Author:		MOS
-- Create date: 07-2010
-- Description:	Retorna Despachos de un
-- it_transaction.-
-- =============================================


-- Log:
-- MOS 07-2024 x JFC: 22092




CREATE FUNCTION [dbo].[fnGetImportData_Custom]
(
	@compId			AS INT,
	@braId			AS INT,
	@ct_transaction	AS INT,
	@it_transaction AS INT
)

RETURNS NVARCHAR(4000)	--WITH SCHEMABINDING

AS
BEGIN

	DECLARE @strImportData_Custom AS NVARCHAR(4000)
	SET @strImportData_Custom = ''
	DECLARE @bitHasPackingListRelated AS BIT = 'True'	-- MOS 11-2022 x MF

	SELECT	@strImportData_Custom = @strImportData_Custom + '*' +
									dbo.fnAddStringIfNotExists(@strImportData_Custom, IsNull(ITID.impData_Custom_local,ISNULL(tid.impData_Custom_local,''))) + '*' +
									dbo.fnAddStringIfNotExists(@strImportData_Custom, IsNull(IMPORT.impData_Custom,'')),
			@bitHasPackingListRelated = CASE
											WHEN tit.it_transaction_original IS NOT NULL THEN 'True'
											-- MOS 11-2022 x MF
											ELSE											  'False'
											--ELSE												@bitHasPackingListRelated
										END
		FROM dbo.tbItemTransactionImportData		ITID	WITH (NOLOCK)
		INNER JOIN dbo.tbItemTransactions			 AS tit		WITH (NOLOCK)
			ON	tit.comp_id			= ITID.comp_id			AND
				tit.bra_id			= ITID.bra_id			AND
				tit.ct_transaction	= ITID.ct_transaction	AND
				tit.it_transaction	= ITID.it_transaction
		Left Join 	dbo.tbImport						IMPORT	WITH (NOLOCK)
			ON	IMPORT.comp_id			=	@compid
			and	IMPORT.import_id		=	ITID.import_id
		LEFT JOIN tbImportData						 AS tid		WITH (NOLOCK)		-- MOS 07-2024 x JFC: 22092
			ON	tid.comp_id				=	@compId			AND
				tid.impData_id			=	itid.impData_id
		Where	ITID.comp_id			=	@compId
			and	ITID.bra_id				=   @braId
			and ITID.ct_transaction		=	@ct_transaction
			and ITID.it_transaction		=	@it_transaction


	-- Si viene de la Facturacion de Remito, pone los datos relacionados al REMITO
	IF @bitHasPackingListRelated = 'True'
		BEGIN
			SELECT
				-- MOS 11-2022 x MF
				--@strImportData_Custom = @strImportData_Custom + '*'+ dbo.fnAddStringIfNotExists(@strImportData_Custom, IsNull(tid.impData_Custom_local,''))
				@strImportData_Custom = @strImportData_Custom + '*'+ dbo.fnAddStringIfNotExists(@strImportData_Custom,
																									CASE
																										WHEN IsNull(tid.impData_Custom_local,'') <> '' THEN tid.impData_Custom_local
																										WHEN IsNull(ITID.impData_Number_local,'') <> '' THEN ITID.impData_Number_local
																										ELSE ''
																									END
																							    )
				FROM		dbo.tbItemTransactions			 AS tit			WITH (NOLOCK)
				INNER JOIN	dbo.tbItemTransactionImportData		ITID		WITH (NOLOCK)
					ON	ITID.comp_id			= tit.comp_id			AND
						ITID.it_transaction		= tit.it_transaction_original
				INNER JOIN dbo.tbImportData						tid			WITH (NOLOCK)
					ON	tid.comp_id		= itid.comp_id AND
						tid.impData_id	= itid.impData_id
				INNER JOIN dbo.tbCommercialTransactions		 AS tct			WITH (NOLOCK)
					ON	tct.comp_id				= itid.comp_id AND
						tct.ct_transaction		= itid.ct_transaction
				Where	tit.comp_id				=	@compId
					and	tit.bra_id				=   @braId
					and tit.ct_transaction		=	@ct_transaction
					and tit.it_transaction		=	@it_transaction
					AND tct.sd_id				=   2   -- Remito


		END

	-- ---------------------------------------------------------
	-- Saca los * repetidos de la consulta de arriba
	-- ---------------------------------------------------------
	DECLARE @intLength AS INT = -1
	WHILE LEN(@strImportData_Custom) <> @intLength
		BEGIN
			SET @intLength	= LEN(@strImportData_Custom)
			SET @strImportData_Custom = REPLACE(@strImportData_Custom,'**','*')
		END
	SET		@intLength		= -1
	WHILE LEN(@strImportData_Custom) <> @intLength
		BEGIN
			SET @intLength	= LEN(@strImportData_Custom)
			SET @strImportData_Custom = REPLACE(@strImportData_Custom,' ','')
		END
	-- ---------------------------------------------------------




	RETURN @strImportData_Custom

END


GO





-- =============================================
-- Author:		MOS
-- Create date: 07-2010
-- Description:	Retorna Despachos de un
-- it_transaction.-
-- =============================================
CREATE FUNCTION [dbo].[fnGetImportData_ExpDate]
(
	@compId			AS INT,
	@braId			AS INT,
	@ct_transaction	AS INT,
	@it_transaction AS INT
)

RETURNS NVARCHAR(4000)	--WITH SCHEMABINDING

AS
BEGIN

	DECLARE @strImportData_ExpDate AS NVARCHAR(4000)
	SET		@strImportData_ExpDate = ''

	DECLARE @bitHasPackingListRelated AS BIT = 'True'

	SELECT  @strImportData_ExpDate = @strImportData_ExpDate + '*' + dbo.fnAddStringIfNotExists(@strImportData_ExpDate, CONVERT(NVARCHAR(30),tid.impData_ExpirationDate,111)),
			@bitHasPackingListRelated = CASE
											WHEN tit.it_transaction_original IS NOT NULL THEN	'True'
											-- MOS 11-2022 x MF
											ELSE												'False'
											--ELSE												@bitHasPackingListRelated
										END
		FROM dbo.tbItemTransactionImportData		ITID		WITH (NOLOCK)
		INNER JOIN dbo.tbItemTransactions			 AS tit		WITH (NOLOCK)
			ON	tit.comp_id			= ITID.comp_id			AND
				tit.bra_id			= ITID.bra_id			AND
				tit.ct_transaction	= ITID.ct_transaction	AND
				tit.it_transaction	= ITID.it_transaction
		INNER JOIN dbo.tbImportData						tid			WITH (NOLOCK)
			ON	tid.comp_id		= itid.comp_id AND
				tid.impData_id	= itid.impData_id

		Where	ITID.comp_id			=	@compId
			and	ITID.bra_id				=   @braId
			and ITID.ct_transaction		=	@ct_transaction
			and ITID.it_transaction		=	@it_transaction


	-- Si viene de la Facturacion de Remito, pone los datos relacionados al REMITO
	IF @bitHasPackingListRelated = 'True'
		BEGIN
			SELECT	@strImportData_ExpDate = @strImportData_ExpDate + '*' + dbo.fnAddStringIfNotExists(@strImportData_ExpDate, CONVERT(NVARCHAR(30),tid.impData_ExpirationDate,111))
				FROM		dbo.tbItemTransactions			 AS tit			WITH (NOLOCK)
				INNER JOIN	dbo.tbItemTransactionImportData		ITID		WITH (NOLOCK)
					ON	ITID.comp_id			= tit.comp_id			AND
						ITID.it_transaction		= tit.it_transaction_original
				INNER JOIN dbo.tbImportData						tid			WITH (NOLOCK)
					ON	tid.comp_id		= itid.comp_id AND
						tid.impData_id	= itid.impData_id
				INNER JOIN dbo.tbCommercialTransactions		 AS tct			WITH (NOLOCK)
					ON	tct.comp_id				= itid.comp_id AND
						tct.ct_transaction		= itid.ct_transaction
				Where	tit.comp_id				=	@compId
					and	tit.bra_id				=   @braId
					and tit.ct_transaction		=	@ct_transaction
					and tit.it_transaction		=	@it_transaction
					AND tct.sd_id				=   2   -- Remito


		END

	IF @strImportData_ExpDate <> '' SET @strImportData_ExpDate = @strImportData_ExpDate + '(yyyymmdd)'

	RETURN @strImportData_ExpDate

END


GO





-- =============================================
-- Author:		MOS
-- Create date: 07-2010
-- Description:	Retorna Despachos de un
-- it_transaction.-
-- =============================================
CREATE FUNCTION [dbo].[fnGetImportData_From]
(
	@compId			AS INT,
	@braId			AS INT,
	@ct_transaction	AS INT,
	@it_transaction AS INT
)
RETURNS NVARCHAR(4000)	--WITH SCHEMABINDING

AS

BEGIN

	DECLARE @strImportData_From AS NVARCHAR(4000)
	SET		@strImportData_From = ''

	DECLARE @bitHasPackingListRelated AS BIT = 'True'

	SELECT  @strImportData_From			=	@strImportData_From + '*' +
											dbo.fnAddStringIfNotExists(@strImportData_From, IsNull(tid.impData_From,'')) + '*' +
											dbo.fnAddStringIfNotExists(@strImportData_From, IsNull(IMPORT.impData_from,'')),
			@bitHasPackingListRelated	=	CASE
												WHEN tit.it_transaction_original IS NOT NULL THEN	'True'
											-- MOS 11-2022 x MF
												ELSE												'False'
												--ELSE												@bitHasPackingListRelated
											END
		FROM dbo.tbItemTransactionImportData		ITID			WITH (NOLOCK)
		INNER JOIN dbo.tbItemTransactions			 AS tit		WITH (NOLOCK)
			ON	tit.comp_id			= ITID.comp_id			AND
				tit.bra_id			= ITID.bra_id			AND
				tit.ct_transaction	= ITID.ct_transaction	AND
				tit.it_transaction	= ITID.it_transaction
		INNER JOIN dbo.tbImportData						tid			WITH (NOLOCK)
			ON	tid.comp_id		= itid.comp_id AND
				tid.impData_id	= itid.impData_id
		Left Join 	dbo.tbImport					IMPORT			WITH (NOLOCK)
			ON	IMPORT.comp_id			=	@compid
			and	IMPORT.import_id		=	ITID.import_id
		Where	ITID.comp_id			=	@compId
			and	ITID.bra_id				=   @braId
			and ITID.ct_transaction		=	@ct_transaction
			and ITID.it_transaction		=	@it_transaction


	-- Si viene de la Facturacion de Remito, pone los datos relacionados al REMITO
	IF @bitHasPackingListRelated = 'True'
		BEGIN
			SELECT	@strImportData_From = @strImportData_From + '*' + dbo.fnAddStringIfNotExists(@strImportData_From, IsNull(tid.impData_From,''))
				FROM		dbo.tbItemTransactions			 AS tit			WITH (NOLOCK)
				INNER JOIN	dbo.tbItemTransactionImportData		ITID		WITH (NOLOCK)
					ON	ITID.comp_id			= tit.comp_id			AND
						ITID.it_transaction		= tit.it_transaction_original
				INNER JOIN dbo.tbImportData						tid			WITH (NOLOCK)
					ON	tid.comp_id		= itid.comp_id AND
						tid.impData_id	= itid.impData_id
				INNER JOIN dbo.tbCommercialTransactions		 AS tct			WITH (NOLOCK)
					ON	tct.comp_id				= itid.comp_id AND
						tct.ct_transaction		= itid.ct_transaction
				Where	tit.comp_id				=	@compId
					and	tit.bra_id				=   @braId
					and tit.ct_transaction		=	@ct_transaction
					and tit.it_transaction		=	@it_transaction
					AND tct.sd_id				=   2   -- Remito


		END

	-- ---------------------------------------------------------
	-- Saca los * repetidos de la consulta de arriba
	-- ---------------------------------------------------------
	DECLARE @intLength AS INT = -1
	WHILE LEN(@strImportData_From) <> @intLength
		BEGIN
			SET @intLength	= LEN(@strImportData_From)
			SET @strImportData_From = REPLACE(@strImportData_From,'**','*')
		END
	SET		@intLength		= -1
	WHILE LEN(@strImportData_From) <> @intLength
		BEGIN
			SET @intLength	= LEN(@strImportData_From)
			SET @strImportData_From = REPLACE(@strImportData_From,' ','')
		END
	-- ---------------------------------------------------------


	RETURN @strImportData_From

END


GO





