-- =============================================
-- Author:		MOS
-- Create date: 07-2010
-- Description:	Retorna Aduana y Despacho por
-- it_transaction.-
-- =============================================
create FUNCTION [dbo].[fnGetImportDataByItemTransaction]
(
	@compId			AS INT,
	@braId			AS INT,
	@ct_transaction	AS INT,
	@it_transaction	AS INT
)
RETURNS

	@tblImportData
		TABLE (
			    comp_id				 INT,
			    bra_id				 INT,
			    ct_transaction		 INT,
			    it_transaction		 INT,
				ImportData_Number    VARCHAR(4000),
				ImportData_Custom    VARCHAR(4000)
		)	WITH SCHEMABINDING

AS

BEGIN

	DECLARE @strImportData_Number AS VARCHAR(4000)
	DECLARE @strImportData_Custom AS VARCHAR(4000)
	SET @strImportData_Number = ''
	SET @strImportData_Custom = ''


	SELECT @strImportData_Number = @strImportData_Number +  IsNull(IMPORT.impData_number,IsNull(ITID.impData_Number_local,'')),
		   @strImportData_Custom = @strImportData_Custom +  IsNull(IMPORT.impData_Custom,IsNull(ITID.impData_Custom_local,''))
		FROM dbo.tbItemTransactionImportData		ITID					WITH (NOLOCK)

		Left Join 	dbo.tbImport						IMPORT				WITH (NOLOCK)
			ON	IMPORT.comp_id			=	@compid
			and	IMPORT.import_id		=	ITID.import_id

		Where	ITID.comp_id			=	@compId
			and	ITID.bra_id				=   @braId
			and ITID.ct_transaction		=	@ct_transaction
			and ITID.it_transaction		=	@it_transaction


	INSERT INTO @tblImportData
	(
		comp_id,
		bra_id,
		ct_transaction,
		it_transaction,
		ImportData_Number,
		ImportData_Custom
	)
	VALUES
	(	@compId,
		@braId,
		@ct_transaction,
		@it_transaction,
		@strImportData_Number,
		@strImportData_Custom
	)

	RETURN

END


GO





-- =============================================
-- Author:		MOS
-- Retorna si se puede tomar un numero de serie de diferente deposito
-- al que el numero tiene asignado.!
-- =============================================
CREATE FUNCTION [dbo].[fnGetIsItemSerial4DifStorage]
	(
		@intComp_ID AS INT,
		@intBra_ID	as int
	)
RETURNS bit
AS
BEGIN

	return
		(
		SELECT IsNull(tb.bra_SaleOrderSerials4DifStorage,'False')
			FROM tbBranch tb						WITH (NOLOCK)

			WHERE	tb.comp_id	= @intComp_ID
				AND	tb.bra_id	= @intBra_ID
		)

END
GO



-- =============================================
-- Author:		STL
-- Create date: 18-05-2015
-- Description:	Devuelve 1 si el Artículo está
-- en una publicación activa o 0 si el mismo no
-- se encuentra en ninguna publicación vigente
-- =============================================
CREATE FUNCTION [dbo].[fnGetItemActivePublicationsStatus]
(
	-- Add the parameters for the function here
	@comp_id	INT,
	@item_id	INT
)
RETURNS BIT
AS
BEGIN
	-- Declare the return variable here
	DECLARE @bitResult	AS BIT

	IF EXISTS (SELECT
					TOP 1
						1
				FROM tbItemPublicationDetail			tipd		WITH (NOLOCK)
					INNER JOIN tbItemPublicationHeader	tiph		WITH (NOLOCK)
						ON	tiph.comp_id = tipd.comp_id AND
							tiph.pubh_id = tipd.pubh_id

				WHERE	tipd.comp_id		= @comp_id AND
						tipd.item_id		= @item_id AND
						tiph.pubh_disabled	= 'False'
				ORDER BY tiph.pubh_id DESC)
		BEGIN
			SELECT @bitResult = 'True'
		END
	ELSE
		BEGIN
			SELECT @bitResult = 'False'
		END


	-- Return the result of the function
	RETURN @bitResult

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 08-2013
-- Description:	Obtiene el % de comision x articulo
-- =============================================
CREATE FUNCTION [dbo].[fnGetItemCustomCommission4Sales]
	(
		@comp_id	as int,
		@bra_Id		as INT,
		@cust_id	AS INT,
		@cat_id		AS INT,
		@subcat_id	AS INT,
		@item_id	AS INT,
		@brand_id	AS INT,
		@sm_id		AS INT,
		@st_id		AS INT,
		@prli_id	AS INT,
		@date		AS DATETIME,
		@markUp		AS DECIMAL(19,4)
	)
RETURNS DECIMAL(19,4)

AS
BEGIN

	DECLARE @decCommission AS DECIMAL(19,4)
	SET @decCommission = NULL

	SELECT TOP 1 @decCommission = tccs.coma_percentage
		FROM tbCustomCommission4Sales tccs				WITH (NOLOCK)
--		LEFT JOIN tbItem ti
--			ON	ti.comp_id = @comp_id AND
--				ti.item_id = @item_id
		WHERE	tccs.comp_id = @comp_id										AND
			   (tccs.bra_id		IS NULL	OR tccs.bra_id		= @bra_Id)		AND
			   (tccs.cust_id	IS NULL OR tccs.cust_id		= @cust_id)		AND
			   (tccs.item_id	IS NULL OR tccs.item_id		= @item_id)		AND
			   (tccs.cat_id		IS NULL OR tccs.cat_id		= @cat_id)		AND
			   (tccs.subcat_id	IS NULL OR tccs.subcat_id	= @subcat_id)	AND
			   (tccs.brand_id	IS NULL OR tccs.brand_id	= @brand_id)	AND
			   (tccs.sm_id		IS NULL OR tccs.sm_id		= @sm_id)		AND
			   (tccs.st_id		IS NULL OR tccs.st_id		= @st_id)		AND
			   (tccs.prli_id	IS NULL OR tccs.prli_id		= @prli_id)		AND
			   (@date BETWEEN tccs.coma_dateFrom AND tccs.coma_dateTo)		AND
			   ((tccs.coma_markUpFrom >= 0 AND tccs.coma_markUpTo <> 0 AND (@markUp BETWEEN tccs.coma_markUpFrom AND tccs.coma_markUpTo)) OR
			    (tccs.coma_markUpFrom = 0 AND tccs.coma_markUpTo = 0)
			   ) AND
				tccs.coma_disabled = 'False'
		ORDER BY tccs.coma_order

	IF @decCommission IS NULL
		BEGIN
			SELECT @decCommission = IsNull(ti.item_commission,0)
				FROM tbItem ti				WITH (NOLOCK)
			WHERE	ti.comp_id = @comp_id AND
					ti.item_id = @item_id

		END

	RETURN @decCommission

END
GO




-- =============================================
-- Author:		MOS
-- Create date: 08-2015
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnGetItemTransactions]
(
	-- Add the parameters for the function here
	@comp_id		AS INT,
	@ct_transaction AS INT
)
RETURNS nVARCHAR(4000)
AS
BEGIN

	DECLARE @strReturn	AS NVARCHAR(4000)
	DECLARE @bra_id		AS INT

	SET @strReturn = ''


	SELECT		@bra_id = bra_id
		FROM	tbCommercialTransactions tct				WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction



	SELECT	@strReturn	= @strReturn + ISNULL(titd.itm_desc,ti.item_desc) + ' * ' + ISNULL(tpc.puco_desc,'') + CHAR (13) + CHAR (10)
		FROM tbItemTransactions tit								WITH (NOLOCK)
		LEFT JOIN tbitem ti										WITH (NOLOCK)
			ON	ti.comp_id			= tit.comp_id AND
				ti.item_id			= tit.item_id
		LEFT JOIN tbItemTransactionDetails titd					WITH (NOLOCK)
			ON	titd.comp_id		= tit.comp_id			AND
				titd.bra_id			= tit.bra_id			AND
				titd.ct_transaction = tit.ct_transaction	AND
				titd.it_transaction = tit.it_transaction
		LEFT JOIN tbPurchaseConcept		tpc						WITH (NOLOCK)
		ON	tpc.comp_id = tit.comp_id AND
			tpc.puco_id = tit.puco_id
		WHERE	tit.comp_id			= @comp_id				AND
				tit.ct_transaction	= @ct_transaction




	SELECT @strReturn	= @strReturn + tpc.puco_desc + CHAR (13) + CHAR (10)
		FROM tbPurchaseConceptMovements tpcm					WITH (NOLOCK)
		INNER JOIN tbPurchaseConcept tpc						WITH (NOLOCK)
			ON	tpc.comp_id = tpcm.comp_id AND
				tpc.puco_id = tpcm.puco_id
		WHERE	tpcm.comp_id		= @comp_id AND
				tpcm.ct_transaction = @ct_transaction



	--SELECT  @strReturn = @strReturn + '- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -' + CHAR (13) + CHAR (10)
	SELECT  @strReturn = @strReturn + ISNULL(tctn.ctn_note1,'') + CHAR (13) + CHAR (10)
		FROM tbCommercialTransactionNotes tctn					WITH (NOLOCK)
		WHERE	tctn.comp_id		= @comp_id			AND
				tctn.bra_id			= @bra_id			AND
				tctn.ct_transaction = @ct_transaction


	RETURN @strReturn

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 07-2010
-- Description:	Retorna Despachos de un
-- it_transaction.-
-- =============================================
CREATE FUNCTION [dbo].[fnGetItemTransactionSerial]
(
	@compId			AS INT,
	@braId			AS INT,
	@ct_transaction	AS INT,
	@it_transaction AS INT
)

RETURNS VARCHAR(8000)

AS
BEGIN

	DECLARE @strSerialNumbers AS VARCHAR(8000)
	SET		@strSerialNumbers = ''


	SELECT	@strSerialNumbers = @strSerialNumbers + ' '+	dbo.fnStrAllTrim(	CONVERT(varchar(100),
																				CASE
																					WHEN LEN(@strSerialNumbers) < 7850 THEN dbo.fnAddStringIfNotExists(@strSerialNumbers, tis.is_serial)
																					ELSE  ''
																				END)
																			)



		FROM tbItemTransactionSerials	ITID	WITH (NOLOCK)
		INNER JOIN tbItemSerials		tis		WITH (NOLOCK)
			ON	tis.comp_id				=   ITID.comp_id AND
				tis.is_id				=   ITID.is_id
		Where	ITID.comp_id			=	@compId
			and	ITID.bra_id				=   @braId
			and ITID.ct_transaction		=	@ct_transaction
			and ITID.it_transaction		=	@it_transaction


	RETURN @strSerialNumbers

END


GO




-- =============================================================
-- Author:		MOS original- este modificado ga
-- Create date: 16-11-2015
-- Description:	<Description, ,> Solo los articulos, no la nota
-- =============================================================
CREATE FUNCTION [dbo].[fnGetItemTransactionsOnlyItems]
(
	-- Add the parameters for the function here
	@comp_id		AS INT,
	@ct_transaction AS INT
)
RETURNS nVARCHAR(4000)
AS
BEGIN

	DECLARE @strReturn	AS NVARCHAR(4000)
	DECLARE @bra_id		AS INT

	SET @strReturn = ''


	SELECT		@bra_id = bra_id
		FROM	tbCommercialTransactions tct					WITH (NOLOCK)
		WHERE	tct.comp_id			= @comp_id AND
				tct.ct_transaction	= @ct_transaction



	SELECT	@strReturn	= @strReturn + ISNULL(titd.itm_desc,ti.item_desc) + CHAR (13) + CHAR (10)
		FROM tbItemTransactions tit								WITH (NOLOCK)
		LEFT JOIN tbitem ti										WITH (NOLOCK)
			ON	ti.comp_id			= tit.comp_id AND
				ti.item_id			= tit.item_id
		LEFT JOIN tbItemTransactionDetails titd					WITH (NOLOCK)
			ON	titd.comp_id		= tit.comp_id			AND
				titd.bra_id			= tit.bra_id			AND
				titd.ct_transaction = tit.ct_transaction	AND
				titd.it_transaction = tit.it_transaction
		WHERE	tit.comp_id			= @comp_id				AND
				tit.ct_transaction	= @ct_transaction


	RETURN @strReturn

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 12-2009
-- Description:	partner of
-- fnGetSerialNumber4Incremental
-- =============================================
CREATE FUNCTION [dbo].[fnGetLenSerTrueNumber]
(
	@strSerial AS NVARCHAR(50)
)
RETURNS INT
AS
BEGIN


declare @intCounter		AS INT
declare @intLen			as integer     --Local nLen := Len(cNumero)
declare @intNumero		AS int
declare @strTSerial		as nvarchar(50)   --Local cTNumero

SET @intCounter = 1
SET @intNumero = 0
SET @intLen = LEN(@strSerial)



WHILE @intCounter <= @intLen AND (@intNumero <= 7)  -- Para que no de error de mas de 9 dígitos con tipo de datos INT
BEGIN
    set @strTSerial = Right(@strSerial,1)
    If isnumeric(@strTSerial)  = 1
		BEGIN
			set @intNumero = @intNumero + 1
		END
    Else
        break

    set @strSerial = Left(@strSerial,Len(@strSerial)-1)

END

Return(@intNumero)

END
GO





