-- =============================================
-- Author:		MOS
-- Create date:
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnGetPriceFromCost]
(
	@comp_id		AS INT,
	@bra_id			AS INT,
	@item_id		AS INT,
	@decCost		AS DECIMAL(19,5),
	@curr_id4Cost	AS INT,
	@decDiscount1	AS DECIMAL(19,4),
	@decDiscount2	AS DECIMAL(19,4),
	@decDiscount3	AS DECIMAL(19,4),
	@decDiscount4	AS DECIMAL(19,4),
	@decSurcharge1	AS DECIMAL(19,4),
	@decSurcharge2	AS DECIMAL(19,4),
	@decSurcharge3	AS DECIMAL(19,4),
	@decSurcharge4	AS DECIMAL(19,4),
	@decMarkup1     AS DECIMAL(25,8),
	@decMarkup2     AS DECIMAL(25,8),
	@curr_id4Spot	AS INT,
	@curr_id4Price  AS INT
)

RETURNS

	@tblPrices TABLE
	(
		comp_id							INT,
		item_id							INT,
		CostWithAppliences				DECIMAL(19,5),
		CostWithAppliencesNoTaxes		DECIMAL(19,5),
		Price4Spot						decimal(19,5) NULL,
		Price4List						DECIMAL(19,5) NULL,
		Price4SpotNoTaxes				decimal(19,5) NULL,
		Price4ListNoTaxes				DECIMAL(19,5) NULL
	)
AS
BEGIN


	DECLARE @decItemTaxCoeficient AS DECIMAL(30,8)
	SET		@decItemTaxCoeficient = dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id)

	DECLARE @bra_costPriceEdition_decimalPLaces		AS INT
	DECLARE @bra_costPriceEdition_decimals2Round	AS INT

	SELECT @bra_costPriceEdition_decimalPLaces	= IsNull(tb.bra_costPriceEdition_decimalPLaces,4),
	       @bra_costPriceEdition_decimals2Round = IsNull(tb.bra_costPriceEdition_decimals2Round,4)
		FROM dbo.tbBranch tb				WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id AND
				tb.bra_id	= @bra_id

	DECLARE @decFinalCostNoTaxes	AS DECIMAL(19,5)
	DECLARE @decFinalCost			AS DECIMAL(19,5)
	SET @decFinalCostNoTaxes =	@decCost *
								dbo.fnGetFinalDiscountCoeficient(@decDiscount1,@decDiscount2,@decDiscount3,@decDiscount4) *
								dbo.fnGetFinalDiscountCoeficient(-@decSurcharge1,-@decSurcharge2,-@decSurcharge3,-@decSurcharge4)
	SET @decFinalCost		 =	@decFinalCostNoTaxes * @decItemTaxCoeficient




	DECLARE @decPrice4List AS DECIMAL(19,4)
	DECLARE @decPrice4Spot AS DECIMAL(19,5)

	SET @decPrice4Spot = @decFinalCost + (@decFinalCost * @decMarkup1 / 100)
	SET @decPrice4List = @decFinalCost + (@decFinalCost * @decMarkup2 / 100)


	-- Redondea y pasa a moneda de la lista de precios
	SET @decPrice4List = dbo.fnGetExchange2(@comp_id, @decPrice4List, @curr_id4Cost, @curr_id4Price, 0,0, 0, 'False')
	SET @decPrice4List = Round(@decPrice4List, @bra_costPriceEdition_decimals2Round,@bra_costPriceEdition_decimalPLaces)

	-- Redondea y pasa a moneda de la lista de Contado
	SET @decPrice4Spot = dbo.fnGetExchange2(@comp_id, @decPrice4Spot, @curr_id4Cost, @curr_id4Spot, 0,0, 0, 'False')
	SET @decPrice4Spot = Round(@decPrice4Spot, @bra_costPriceEdition_decimals2Round,@bra_costPriceEdition_decimalPLaces)


	INSERT INTO @tblPrices(	comp_id,
							item_id,
							CostWithAppliences,
							CostWithAppliencesNoTaxes,
							Price4List,
							Price4ListNoTaxes,
							Price4Spot,
							Price4SpotNoTaxes
						)
		VALUES
						(
							@comp_id,
							@item_id,
							@decFinalCost,
							@decFinalCostNoTaxes,
							@decPrice4List,
							@decPrice4List / dbo.fnNoZDiv(@decItemTaxCoeficient),
							@decPrice4Spot,
							@decPrice4Spot / dbo.fnNoZDiv(@decItemTaxCoeficient)
						)


	return
END
GO




CREATE FUNCTION [dbo].[fnGetPriceListItemTaxes]
(
	@comp_id			INT,
	@item_id			INT,
	@decPrice			DECIMAL(19,4)
)
RETURNS DECIMAL(19,4)
AS

BEGIN

	DECLARE @decItemTaxes AS DECIMAL(19,4)
	SET @decItemTaxes = 0

	SELECT @decItemTaxes = @decPrice * ttn.tax_percentage / 100
		FROM vwItemTaxesOnlyOneIvaTax vi				WITH (NOLOCK)
		INNER JOIN tbTaxName ttn						WITH (NOLOCK)
		ON		ttn.comp_id = vi.comp_id AND
				ttn.tax_id	= vi.tax_id
		WHERE	vi.comp_id	= @comp_id AND
				vi.item_id	= @item_id

	SELECT @decItemTaxes = @decItemTaxes + ( @decPrice * ttn.tax_percentage / 100)
		FROM vwItemTaxesOnlyOneInternalTax  vi			WITH (NOLOCK)
		INNER JOIN tbTaxName ttn						WITH (NOLOCK)
		ON		ttn.comp_id = vi.comp_id AND
				ttn.tax_id	= vi.tax_id
		WHERE	vi.comp_id	= @comp_id AND
				vi.item_id	= @item_id

	RETURN @decItemTaxes

END
GO




CREATE FUNCTION [dbo].[fnGetPriceListItemTaxesCoeficient]
(
	@comp_id			INT,
	@item_id			INT
)
RETURNS DECIMAL(30,8)
AS

BEGIN

	DECLARE @decItemTaxesPercent AS DECIMAL(30,8)
	SET		@decItemTaxesPercent	= 0

	SELECT @decItemTaxesPercent = IsNull(ttn.tax_percentage,0)
		FROM dbo.vwItemTaxesOnlyOneIvaTax vi			WITH (NOLOCK)
		INNER JOIN dbo.tbTaxName ttn					WITH (NOLOCK)
		ON		ttn.comp_id = vi.comp_id AND
				ttn.tax_id	= vi.tax_id
		WHERE	vi.comp_id	= @comp_id AND
				vi.item_id	= @item_id


	SELECT @decItemTaxesPercent = @decItemTaxesPercent +  IsNull(ttn.tax_percentage,0)
		FROM dbo.vwItemTaxesOnlyOneInternalTax  vi		WITH (NOLOCK)
		INNER JOIN dbo.tbTaxName ttn					WITH (NOLOCK)
		ON		ttn.comp_id = vi.comp_id AND
				ttn.tax_id	= vi.tax_id
		WHERE	vi.comp_id	= @comp_id AND
				vi.item_id	= @item_id

	SET @decItemTaxesPercent = (@decItemTaxesPercent / 100) + 1

	RETURN ISNULL(@decItemTaxesPercent,0)

END
GO





CREATE FUNCTION [dbo].[fnGetPriceListItemTaxesCoeficient4Combo]
(
	@comp_id			INT,
	@bra_id				INT,
	@item_id			INT,
	@prli_id			INT

)
RETURNS DECIMAL(30,8)
AS

BEGIN

	IF EXISTS(
					SELECT TOP 1 1
						FROM tbItemAssociation	tia					WITH (NOLOCK)
						INNER JOIN tbItem		ti					WITH (NOLOCK)
							ON	ti.comp_id = tia.comp_id	AND
								ti.item_id = tia.item_id
						WHERE	tia.comp_id = @comp_id		AND
								tia.item_id = @item_id		AND
								ti.item_ifHasItemAssociationSumPrices = 'True'
	)
		BEGIN	-- SOLO SI ES UN COMBO QUE SUMA LOS PRECIOS Y COSTOS DE LAS PARTES, PARA QUE RETORNE EL COEFICIENTE EQUIVALENTE DE IMPUESTOS DE TODAS SUS PARTES.-

				-- Esto es por si tienen diferentes impuestos cada item por lo que debo sacar un impuesto equivalente para el TOTAL

				-- Ver en **wefknjweknwe56423kllkh ya que en TODO logar donde se cargue un combo de esta manera se deberá hacer esto ! ! !
				DECLARE @decTotalImpuestos  AS DECIMAL(25,10)	= 0
				DECLARE @decTotalNeto	    AS DECIMAL(25,10)	= 0
				DECLARE @intItemsQTY		AS INT				= 0
				-- Sumo el TOTAL de articulos
				SELECT  @intItemsQTY = @intItemsQTY + (tia.iasso_qty)
					FROM tbItemAssociation tia					WITH (NOLOCK)
					WHERE	tia.comp_id = @comp_id AND
							tia.item_id = @item_id


				-- Sumo Algebraicamente todos los IVA
				SELECT @decTotalImpuestos = @decTotalImpuestos + (ttn.tax_percentage * tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.prli_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') / 100   ),
					   @decTotalNeto      = @decTotalNeto      + (tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.prli_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') )
					FROM tbItemAssociation				tia		WITH (NOLOCK)
					INNER JOIN tbBranch					tb		WITH (NOLOCK)
						ON	tb.comp_id	= @comp_id		AND
							tb.bra_id	= @bra_id
					INNER JOIN vwItemTaxesOnlyOneIvaTax4Combo tit		WITH (NOLOCK)	-- DEBE SER UNA SOLO PARA COMBOS Q TRAIGA EL COMPOSED SI EXISTE Y SINO EL NORMAL
																						-- aconsejo ante cambios de tbitemtaxes actualizar una tabla q tenga los imuestos sin combo y otra los con combo
						ON	tit.comp_id = tia.comp_id	AND
							tit.item_id = tia.item_id_1
					INNER JOIN tbTaxName				ttn		WITH (NOLOCK)
						ON	ttn.tax_id	= tit.tax_id	AND
							ttn.comp_id = tit.comp_id
					INNER JOIN tbPriceListItems			tpli	WITH (NOLOCK)
						ON	tpli.comp_id = @comp_id		AND
							tpli.prli_id = @prli_id		AND
							tpli.item_id = tia.item_id_1
					WHERE	tia.comp_id = @comp_id		AND
							tia.item_id = @item_id

				-- Sumo Algebraicamente todos los Impuestos Internos
				SELECT @decTotalImpuestos = @decTotalImpuestos + (ttn.tax_percentage * tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.prli_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') / 100 )
					FROM tbItemAssociation tia								WITH (NOLOCK)
					INNER JOIN tbBranch					tb					WITH (NOLOCK)
						ON	tb.comp_id	= @comp_id		AND
							tb.bra_id	= @bra_id
					INNER JOIN vwItemTaxesOnlyOneInternalTax  tit			WITH (NOLOCK)
						ON	tit.comp_id = tia.comp_id	AND
							tit.item_id = tia.item_id_1
					INNER JOIN tbTaxName  ttn								WITH (NOLOCK)
						ON	ttn.tax_id	= tit.tax_id	AND
							ttn.comp_id = tit.comp_id
					INNER JOIN tbPriceListItems			tpli				WITH (NOLOCK)
						ON	tpli.comp_id = @comp_id		AND
							tpli.prli_id = @prli_id		AND
							tpli.item_id = tia.item_id_1
					WHERE	tia.comp_id = @comp_id		AND
							tia.item_id = @item_id


				RETURN  ( (@decTotalImpuestos + @decTotalNeto) / dbo.fnNoZDiv(@decTotalNeto))
		END
	ELSE
		BEGIN
			RETURN dbo.fnNoZDiv( dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id) )
		END

	RETURN -1


END
GO





create FUNCTION [dbo].[fnGetPriceListItemTaxesPercentage4Combo]
(
	@comp_id			INT,
	@bra_id				INT,
	@item_id			INT,
	@prli_id			INT

)
RETURNS DECIMAL(30,8)
AS

BEGIN

	IF EXISTS(
					SELECT TOP 1 1
						FROM tbItemAssociation	tia					WITH (NOLOCK)
						INNER JOIN tbItem		ti					WITH (NOLOCK)
							ON	ti.comp_id = tia.comp_id	AND
								ti.item_id = tia.item_id
						WHERE	tia.comp_id = @comp_id		AND
								tia.item_id = @item_id		AND
								ti.item_ifHasItemAssociationSumPrices = 'True'
	)
		BEGIN	-- SOLO SI ES UN COMBO QUE SUMA LOS PRECIOS Y COSTOS DE LAS PARTES, PARA QUE RETORNE EL COEFICIENTE EQUIVALENTE DE IMPUESTOS DE TODAS SUS PARTES.-

				-- Esto es por si tienen diferentes impuestos cada item por lo que debo sacar un impuesto equivalente para el TOTAL

				-- Ver en **wefknjweknwe56423kllkh ya que en TODO logar donde se cargue un combo de esta manera se deberá hacer esto ! ! !
				DECLARE @decTotalImpuestos  AS DECIMAL(25,10)	= 0
				DECLARE @decTotalNeto	    AS DECIMAL(25,10)	= 0
				DECLARE @intItemsQTY		AS INT				= 0
				-- Sumo el TOTAL de articulos
				SELECT  @intItemsQTY = @intItemsQTY + (tia.iasso_qty)
					FROM tbItemAssociation tia					WITH (NOLOCK)
					WHERE	tia.comp_id = @comp_id AND
							tia.item_id = @item_id


				-- Sumo Algebraicamente todos los IVA
				SELECT @decTotalImpuestos = @decTotalImpuestos + (ttn.tax_percentage * tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.prli_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') / 100   ),
					   @decTotalNeto      = @decTotalNeto      + (tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.prli_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') )
					FROM tbItemAssociation				tia		WITH (NOLOCK)
					INNER JOIN tbBranch					tb		WITH (NOLOCK)
						ON	tb.comp_id	= @comp_id		AND
							tb.bra_id	= @bra_id
					INNER JOIN vwItemTaxesOnlyOneIvaTax4Combo tit		WITH (NOLOCK)	-- DEBE SER UNA SOLO PARA COMBOS Q TRAIGA EL COMPOSED SI EXISTE Y SINO EL NORMAL
																						-- aconsejo ante cambios de tbitemtaxes actualizar una tabla q tenga los imuestos sin combo y otra los con combo
						ON	tit.comp_id = tia.comp_id	AND
							tit.item_id = tia.item_id_1
					INNER JOIN tbTaxName				ttn		WITH (NOLOCK)
						ON	ttn.tax_id	= tit.tax_id	AND
							ttn.comp_id = tit.comp_id
					INNER JOIN tbPriceListItems			tpli	WITH (NOLOCK)
						ON	tpli.comp_id = @comp_id		AND
							tpli.prli_id = @prli_id		AND
							tpli.item_id = tia.item_id_1
					WHERE	tia.comp_id = @comp_id		AND
							tia.item_id = @item_id

				-- Sumo Algebraicamente todos los Impuestos Internos
				SELECT @decTotalImpuestos = @decTotalImpuestos + (ttn.tax_percentage * tia.iasso_qty * dbo.fnGetExchange2(@comp_id, ISNULL(tpli.prli_price,0),tpli.curr_id,tb.curr_id,0,0,0,'False') / 100 )
					FROM tbItemAssociation tia								WITH (NOLOCK)
					INNER JOIN tbBranch					tb					WITH (NOLOCK)
						ON	tb.comp_id	= @comp_id		AND
							tb.bra_id	= @bra_id
					INNER JOIN vwItemTaxesOnlyOneInternalTax  tit			WITH (NOLOCK)
						ON	tit.comp_id = tia.comp_id	AND
							tit.item_id = tia.item_id_1
					INNER JOIN tbTaxName  ttn								WITH (NOLOCK)
						ON	ttn.tax_id	= tit.tax_id	AND
							ttn.comp_id = tit.comp_id
					INNER JOIN tbPriceListItems			tpli				WITH (NOLOCK)
						ON	tpli.comp_id = @comp_id		AND
							tpli.prli_id = @prli_id		AND
							tpli.item_id = tia.item_id_1
					WHERE	tia.comp_id = @comp_id		AND
							tia.item_id = @item_id


				RETURN (( ( (@decTotalImpuestos + @decTotalNeto) / dbo.fnNoZDiv(@decTotalNeto)) -1) * 100)
		END
	ELSE
		BEGIN
			RETURN ((dbo.fnNoZDiv( dbo.fnGetPriceListItemTaxesCoeficient(@comp_id, @item_id) ) -1) *100 )
		END

	RETURN -1


END
GO




CREATE FUNCTION [dbo].[fnGetPriceListItemWithTaxes]
(
	@comp_id			INT,
	@item_id			INT,
	@intPrLiID			INT,
	@intCurrID			INT
)
RETURNS DECIMAL(19,4)
AS

BEGIN


	DECLARE @decPrice DECIMAL(19,6)
	DECLARE @curr_id  INT
	SELECT  @decPrice	= IsNull(tpli.prli_price,0),
			@curr_id	= ISNULL(tpli.curr_id,@intCurrID)
		FROM	tbPriceListItems tpli	WITH (NOLOCK)
		WHERE	tpli.comp_id = @comp_id		AND
				tpli.prli_id = @intPrLiID	AND
				tpli.item_id = @item_id


	DECLARE @decItemTaxes AS DECIMAL(19,4)
	SET		@decItemTaxes = 0


	-- IVA
	SELECT @decItemTaxes = ISNULL(@decPrice * ttn.tax_percentage / 100,0)
		FROM vwItemTaxesOnlyOneIvaTax vi			WITH (NOLOCK)
		INNER JOIN tbTaxName ttn					WITH (NOLOCK)
		ON		ttn.comp_id = vi.comp_id AND
				ttn.tax_id	= vi.tax_id
		WHERE	vi.comp_id	= @comp_id AND
				vi.item_id	= @item_id
	-- Impuestos Internos
	SELECT @decItemTaxes = @decItemTaxes + isnull(( @decPrice * ttn.tax_percentage / 100),0)
		FROM vwItemTaxesOnlyOneInternalTax  vi		WITH (NOLOCK)
		INNER JOIN tbTaxName ttn					WITH (NOLOCK)
		ON		ttn.comp_id = vi.comp_id AND
				ttn.tax_id	= vi.tax_id
		WHERE	vi.comp_id	= @comp_id AND
				vi.item_id	= @item_id



	SET @decPrice = dbo.fnGetExchange2(@comp_id,@decItemTaxes + @decPrice , @curr_id,@intCurrID, 0,0,0,'False')

	RETURN ISNULL(@decPrice,0)

END
GO





