CREATE FUNCTION [dbo].[fnGetProfitOfSaleOrder]
(
	@comp_id					INT,
	@bra_id						INT,
	@tis_id						INT,
	@guid						UNIQUEIDENTIFIER,
	@forcedExchangeCurrency		INT,
    @forcedExchange				DECIMAL(19,5),
    @option						INT

)
RETURNS Decimal(38,15)
AS

BEGIN

/*
	DECLARE @comp_id					INT,
	@bra_id						INT,
	@tis_id						INT,
	@guid						UNIQUEIDENTIFIER,
	@forcedExchangeCurrency		INT,
    @forcedExchange				DECIMAL(19,5),
    @option						INT
    SELECT @comp_id				=1,
	@bra_id						=1,
	@tis_id						=6935,
	@guid						='04B3DBB8-206E-4C4F-9D43-E5A28836D69D',
	@forcedExchangeCurrency		=1,
    @forcedExchange				=1,
    @option						=1


*/


	DECLARE @lcoslis_id INT,
			@lcoslist_type BIT,
			@lbra_curr_id INT

	SELECT	@lcoslis_id			= tb.coslis_id,
			@lcoslist_type		= tb.bra_costlist_type,
			@lbra_curr_id		= tb.curr_id
		FROM	tbBranch tb			WITH (NOLOCK)
		WHERE	tb.bra_id		= @bra_id


	DECLARE @returnvalue_Profit DECIMAL(38,15)
	DECLARE @returnvalue_Markup DECIMAL (38,15)
	SET @returnvalue_Markup = 0
	SET @returnvalue_Profit = 0




	select @returnvalue_Markup =
			CASE WHEN ttis.item_id IS NULL THEN
				--convert(varchar,
					CONVERT(DECIMAL(19,2),
					CASE WHEN ttis.tis_cost = 0 THEN 0
					ELSE
					((ttis.tis_priceInBranchCurrency /
						dbo.fnGetExchange2(ttis.comp_id,ttis.tis_cost,@lbra_curr_id, ttis.curr_id, @forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
					) - 1) * 100
					END)--)
					--+ ' %-'
			ELSE
				--convert(varchar,
				CONVERT(DECIMAL(19,2),
					CASE WHEN @lcoslist_type = 'false'
					THEN case when isnull(ticl.coslis_price,0) = 0 THEN 0
						 ELSE
	 					 ((ttis.tis_priceInBranchCurrency /
							dbo.fnGetExchange2(ttis.comp_id,ticl.coslis_price,ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
						 ) - 1) * 100
						 END
					ELSE case when isnull(ticl.coslis_price_aw,0) = 0 THEN 0
						 ELSE
	 					 ((ttis.tis_priceInBranchCurrency /
							dbo.fnGetExchange2(ttis.comp_id,ticl.coslis_price_aw,ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
						 ) - 1) * 100
						 END
					END)--)
					--+ ' %'
			END														,


			@returnvalue_Profit =
			CASE WHEN ttis.item_id IS NULL THEN
				--convert(varchar,
				CONVERT(DECIMAL(19,2),
					CASE WHEN ttis.tis_cost = 0 THEN 0
					ELSE
					((dbo.fnGetExchange2(ttis.comp_id,ttis.tis_cost,@lbra_curr_id, ttis.curr_id, @forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
					/ ttis.tis_priceInBranchCurrency) -1) * -100
					END)--)
					--+ ' %'
			ELSE
				--convert(varchar,
				CONVERT(DECIMAL(19,2),
					CASE WHEN @lcoslist_type = 'false'
					THEN case when ttis.tis_priceInBranchCurrency = 0 THEN 0
						 ELSE
						 ((dbo.fnGetExchange2(ttis.comp_id,isnull(ticl.coslis_price,0),ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
						 / ttis.tis_priceInBranchCurrency) -1) * -100
						 END
					ELSE case when ttis.tis_priceInBranchCurrency = 0 THEN 0
						 ELSE
						 ((dbo.fnGetExchange2(ttis.comp_id,isnull(ticl.coslis_price_aw,0),ticl.curr_id,@lbra_curr_id,@forcedExchangeCurrency, @lbra_curr_id, @forcedExchange,'false')
						 / ttis.tis_priceInBranchCurrency) -1) * -100

						 END
					END)--)
					--+ ' %'
			END



			FROM	tbTempItemStock						ttis		WITH (NOLOCK)
			LEFT JOIN tbItem					ti					WITH (NOLOCK)
			ON	ti.item_id		= ttis.item_id
			AND ti.comp_id		= ttis.comp_id

			LEFT JOIN tbItemCostList			ticl				WITH (NOLOCK)
			ON	ticl.comp_id	= ti.comp_id
			AND ticl.item_id	= ti.item_id
			AND ticl.coslis_id	= @lcoslis_id

			LEFT JOIN tbItemCostListName		ticln				WITH (NOLOCK)
			ON	ticln.comp_id	= ticl.comp_id
			AND ticln.coslis_id = ticl.coslis_id


	WHERE	ttis.comp_id	= @comp_id
	AND		ttis.tis_id		= @tis_id
	AND		ttis.tis_guid	= @guid


	DECLARE @returnvalue DECIMAL(38,15)
	IF @option = 1
	 set @returnvalue = @returnvalue_Markup
	--SELECT @returnvalue_Markup
	ELSE
		set @returnvalue = @returnvalue_Profit
		--SELECT @returnvalue_Profit


	RETURN @returnvalue
	--SELECT @returnvalue
END
GO





CREATE FUNCTION [dbo].[fnGetPurchaseDiscount]
	(
		@comp_id	INT,
		@pd_id		INT,
		@option		INT		-- 1: Reglas de Actualizacion de Precios, 2: Edicion Configurable de Precios, 3: Orden de Compra, 4: Ingreso de Fc de Compra

	)
returns
	@temptable TABLE (
						decCoeficient4Discount					DECIMAL(19,4),
						decCoeficient4Bonification				DECIMAL(19,4),
						decCoeficient4BonificationCN			DECIMAL(19,4),
						decCoeficient4Discount4Total			DECIMAL(19,4),
						decCoeficient4Bonification4Total		DECIMAL(19,4),
						decCoeficient4BonificationCN4Total		DECIMAL(19,4)
	)	WITH SCHEMABINDING
as

BEGIN

		INSERT INTO @temptable
		(
			decCoeficient4Discount,
			decCoeficient4Bonification,
			decCoeficient4BonificationCN
		)
		SELECT
				CASE
					WHEN @option = 1 AND tpd.pd_discount_apply4PriceListActualizationRules			= 'True' THEN tpd.pd_discountCoeficient
					WHEN @option = 2 AND tpd.pd_discount_apply4PriceCostEdition						= 'True' THEN tpd.pd_discountCoeficient
					WHEN @option = 3 AND tpd.pd_discount_apply4PurchaseOrder						= 'True' THEN tpd.pd_discountCoeficient
					WHEN @option = 4 AND tpd.pd_discount_apply4PurchaseDocs							= 'True' THEN tpd.pd_discountCoeficient
					ELSE																				  0
				END,
				CASE
					WHEN @option = 1 AND tpd.pd_bonification_apply4PriceListActualizationRules		= 'True' THEN tpd.pd_bonificationCoeficient
					WHEN @option = 2 AND tpd.pd_bonification_apply4PriceCostEdition					= 'True' THEN tpd.pd_bonificationCoeficient
					WHEN @option = 3 AND tpd.pd_bonification_apply4PurchaseOrder					= 'True' THEN tpd.pd_bonificationCoeficient
					WHEN @option = 4 AND tpd.pd_bonification_apply4PurchaseDocs						= 'True' THEN tpd.pd_bonificationCoeficient
					ELSE																				  0
				END,
				CASE
					WHEN @option = 1 AND tpd.pd_bonificationCN_apply4PriceListActualizationRules	= 'True' THEN tpd.pd_bonificationCNCoeficient
					WHEN @option = 2 AND tpd.pd_bonificationCN_apply4PriceCostEdition				= 'True' THEN tpd.pd_bonificationCNCoeficient
					WHEN @option = 3 AND tpd.pd_bonificationCN_apply4PurchaseOrder					= 'True' THEN tpd.pd_bonificationCNCoeficient
					WHEN @option = 4 AND tpd.pd_bonificationCN_apply4PurchaseDocs					= 'True' THEN tpd.pd_bonificationCNCoeficient
					ELSE																				  0
				END
			FROM dbo.tbPurchaseDiscount tpd		WITH (NOLOCK)
		WHERE	tpd.comp_id			= @comp_id	AND
				tpd.pd_id			= @pd_id	AND
				tpd.pd_isDisabled	= 'False'


		UPDATE @temptable
			SET	decCoeficient4Discount4Total		= 1-decCoeficient4Discount,
				decCoeficient4Bonification4Total	= 1-decCoeficient4Bonification,
				decCoeficient4BonificationCN4Total	= 1-decCoeficient4BonificationCN


	return


END
GO


CREATE FUNCTION [dbo].[fnGetPurchaseLote2Buy]
(
	@comp_id		INT,
	@itemid			INT,
	@qtySuggested	DECIMAL(19,4)
)
RETURNS INT
AS

BEGIN

	DECLARE @item_purchaseLote AS INT = 0

	SELECT  @item_purchaseLote = ti.item_purchaseLote
		FROM tbItem AS ti WITH (NOLOCK)
		WHERE	ti.comp_id = @comp_id AND
				ti.item_id = @itemid


	IF @item_purchaseLote = 0 RETURN @qtySuggested

	IF @qtySuggested = 0 SET  @qtySuggested = 1

	SET @qtySuggested = CEILING( CONVERT(FLOAT(20),@qtySuggested / @item_purchaseLote)) * @item_purchaseLote	-- Indica comprar MULTIPLOS del Lote de Compra

	RETURN @qtySuggested

END




GO











create FUNCTION [dbo].[fnGetPurchaseOrderState]
(
	@comp_id		int,
	@bra_id			int,
	@poh_id			int
)
RETURNS int
WITH EXECUTE AS CALLER
AS
BEGIN

return
(
select	isnull(sum(convert(int,pod_isprocessed)) * count(*),-1) [processed_value]
from
(
select	distinct poh.poh_id, pod.pod_isprocessed
from	dbo.[tbPurchaseOrderHeader]					poh
		inner join dbo.[tbPurchaseOrderDetail]		pod
		on	poh.comp_id	= pod.comp_id
		and	poh.bra_id	= pod.bra_id
		and	poh.poh_id	= pod.poh_id

where	poh.comp_id	= @comp_id
and		poh.bra_id	= @bra_id
and		poh.poh_id	= @poh_id
) [table]
)

END
GO







