create FUNCTION [dbo].[fnGetReciprocoIfNeed]
(


	@decNumber AS DECIMAL(23,8)


)


RETURNS DECIMAL(23,8)

AS


BEGIN


	IF @decNumber < 1 AND @decNumber <> 0
		BEGIN
			SET @decNumber = 1 / @decNumber
		END

	RETURN @decNumber

END

GO





