-- =============================================
-- Author:		MOS
-- Create date: 12-2009
-- Description:	Genera numeros de serie
-- incrementales para la serializacion
-- incremental.-
-- =============================================
CREATE FUNCTION [dbo].[fnGetSerialNumber4Incremental]
(
	@strOriginalSerialNumber	AS nVARCHAR(50),
	@nIncrementFromOriginal		AS INT
)
RETURNS NVARCHAR(50)
AS
BEGIN

DECLARE @intTotalLen	AS INT
declare @intLen			AS INT
declare @strLen			AS NVARCHAR(50)
declare @intValor		AS INT
declare @strRet			AS NVARCHAR(50)

SET @intTotalLen			= LEN(@strOriginalSerialNumber)
--set @nIncrementFromOriginal = @nIncrementFromOriginal - 1

set @intLen		= dbo.fnGetLenSerTrueNumber(@strOriginalSerialNumber)    --//Len(aStr(nCant))+2
set @strLen		= Right(@strOriginalSerialNumber,@intLen)
set @intValor	= CONVERT(int,@strLen)
set @intValor	= @intValor + @nIncrementFromOriginal
SET @strRet     = CONVERT(NVARCHAR,@intValor)
SET @strRet     = dbo.fnstrpadl( CONVERT(NVARCHAR,@intValor),dbo.fnmax(@intLen,LEN(@strRet)),'0')
set @strRet		= Substring(@strOriginalSerialNumber,1,@intTotalLen-@intLen) + @strRet  --dbo.fnStrPadl(CONVERT(nvarchar(50),@intValor),@intLen,'0')
--v_Serie2(@strRet)
Return(@strRet)

END
GO







-- ------------------------------------------------------------------
-- MOS 05-2008
-- ------------------------------------------------------------------
-- ATENCION!!!!
--
-- NO usar grupos de depositos con esta funcion.
-- Si hace falta hacer una fnGetFStock copiando la
-- estructura de fnGetAStock

CREATE FUNCTION [dbo].[fnGetStock] ( @comp_id int,
									@stor_id int,
									@item_id int )

RETURNS decimal (19,5)
WITH EXECUTE AS CALLER
AS
BEGIN



	-- Si el articulo NO controla Stock retorna siempre un potencial de 99999999
	IF EXISTS(
				SELECT 1
					FROM tbitem		WITH (NOLOCK)
					WHERE	comp_id				= @comp_id	AND
							item_id				= @item_id	AND
							item_NoStockCheck	= 'True'
				)
		BEGIN
			RETURN( 99999999 )
		END


	Declare @decValor decimal(19,5)

	IF @stor_id = -1
		BEGIN
			Select	@decValor		= Sum(itst_cant)
				From	tbItemStorage tb	WITH (NOLOCK)
				INNER JOIN tbStorage ts
				WITH (NOLOCK)
					ON		ts.comp_id = tb.comp_id
						AND ts.stor_id = tb.stor_id
				Where	tb.comp_id	= @comp_id
					AND	tb.item_id	= @item_id
					AND IsNull(ts.stor_web4ALL,'False') = 'True'

		END
	ELSE
		BEGIN
			Select	@decValor		= itst_cant
				From	tbItemStorage tb		WITH (NOLOCK)
				Where	tb.comp_id	= @comp_id
					AND	tb.stor_id	= @stor_id
					AND	tb.item_id	= @item_id
		END

	if @decValor IS NULL
		set @decValor = 0

	RETURN (select @decValor)

end



GO








-- Solo lo usa spItem_GetDaTA PARA wsBasicQuery, NO USARLO PARA NADA MAS!!!!!   es una MIERDAAA
CREATE FUNCTION [dbo].[fnGetStock4AllStorages]
(
	@comp_id int,
	@stor_id int,
	@item_id int
)

RETURNS decimal (19,5)
WITH EXECUTE AS CALLER
AS
BEGIN


	-- Si el articulo NO controla Stock retorna siempre un potencial de 99999999
	IF EXISTS(
				SELECT 1
					FROM tbitem		WITH (NOLOCK)
					WHERE	comp_id				= @comp_id	AND
							item_id				= @item_id	AND
							item_NoStockCheck	= 'True'
				)
		BEGIN
			RETURN( 99999999 )
		END


	Declare @valor decimal(19,5)

	Select	@valor		= sum(itst_cant)
	From	tbItemStorage tb
	Where	tb.comp_id	= @comp_id
	AND		(tb.stor_id	= @stor_id OR @stor_id = -1)
	AND		tb.item_id	= @item_id

	if @@rowcount = 0
		set @valor = 0

	RETURN (select @valor)

end



GO





-- MOS
-- retorna de todas las partes cual es el MINIMO stock que posee para producir

CREATE FUNCTION [dbo].[fnGetStock4MaxComposition]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	int,
	@priority	decimal(14,4)
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS
BEGIN

	DECLARE @decAStock AS DECIMAL(19,4)
	SET @decAStock = 999999999999

	SELECT @decAStock = dbo.fnGetMinimumValue(@decAStock,
											  IsNull(dbo.fnGetStockOfStorageGroup(@comp_id,@stor_id,tic.item_id_1),0) / dbo.fnNoZDiv(tic.icomp_qty)
											 )
		FROM tbItemComposition tic	WITH (NOLOCK)
		WHERE	tic.comp_id = @comp_id AND
				tic.item_id = @item_id

	RETURN @decAStock

END
GO







-- ------------------------------------------------------------------
-- MOS 09-2013
-- ------------------------------------------------------------------
-- ATENCION!!!!
--
-- NO usar grupos de depositos con esta funcion.
-- Se graba el campo ya con la fnGetAStock en spTMPFILES_Isediting...

CREATE FUNCTION [dbo].[fnGetStockAvailable] (	@comp_id int,
												@stor_id int,
												@item_id int )

RETURNS decimal (19,5)
WITH EXECUTE AS CALLER
AS
BEGIN



	-- Si el articulo NO controla Stock retorna siempre un potencial de 99999999
	IF EXISTS(
				SELECT TOP 1  1
					FROM tbitem		WITH (NOLOCK)
					WHERE	comp_id				= @comp_id	AND
							item_id				= @item_id	AND
							item_NoStockCheck	= 'True'
				)
		BEGIN
			RETURN( 99999999 )
		END

	Declare @decValor decimal(19,5)


		BEGIN
			Select	@decValor		= tb.itst_LastAvailableInRelalculation
				From	tbItemStorage tb	WITH (NOLOCK)
				Where	tb.comp_id	= @comp_id
					AND	tb.stor_id	= @stor_id
					AND	tb.item_id	= @item_id
		END

	if @decValor IS NULL
		set @decValor = 0

	RETURN (select @decValor)

end



GO








