CREATE FUNCTION [dbo].[fnGetStockHistory]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	INT,
	@dateFrom   DATETIME		-- recordar pasarlo asi: dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'True')
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS

BEGIN


-- ---------------------------------------------------
-- Testing
-- ---------------------------------------------------
/*
	declare			@comp_id	int,
					@stor_id	int,
					@item_id	int,
					@priority	decimal(14,4)
	select			@comp_id	=1,
					@stor_id	=3,
					@item_id	=485,
					@priority	=9999999999
*/
-- ---------------------------------------------------

	--SELECT @dateFrom = dbo.fnGetEnd_or_BeginOfDate(@dateFrom,'True')

	DECLARE @nAStock AS DECIMAL(19,5)
	SELECT  @nAStock = NULL

	SELECT TOP 1 @nAStock = tis.ith_Qty
		FROM tbItemStorageHistory4CloseDaily tis WITH (NOLOCK)
		WHERE	tis.comp_id = @comp_id AND
				tis.stor_id = @stor_id AND
				tis.item_id = @item_id AND
				tis.ith_cd <= @dateFrom
		ORDER BY tis.ith_cd DESC

	RETURN  IsNull(@nAStock,0)

end

GO




-- ------------------------------------------------------------------
-- MOS 05-2008
-- ------------------------------------------------------------------
-- ATENCION!!!!
--
-- Retorna el Stock de un posible GRUPO de depositos si esta definido,
-- sino retorna el del deposito informado.-

CREATE FUNCTION [dbo].[fnGetStockOfStorageGroup] ( @comp_id int,
												  @stor_id int,
												  @item_id int )

RETURNS decimal (19,5)
WITH EXECUTE AS CALLER
AS
BEGIN

	IF @stor_id IS NULL SET @stor_id = -10

	-- ----------------------------------------------------------------------------------------------------
	-- si el Item Id viene en negativo asume que es ese articulo y NO toma en cuenta el grupo de depositos.
	-- ----------------------------------------------------------------------------------------------------
	DECLARE @bolOnlyOneStorage AS BIT
	SET		@bolOnlyOneStorage = 'False'
	IF @item_id < 0
		BEGIN
			SET @item_id = @item_id * -1
			SET @bolOnlyOneStorage = 'True'
		END
	-- ----------------------------------------------------------------------------------------------------



	-- ----------------------------------------------------------------------------------------------
	-- POngo en una Tabla los Depositos que debere tener en cuenta para el calculo de stock potencial
	-- ----------------------------------------------------------------------------------------------
	DECLARE @tblStorage AS TABLE(intStorageId INT PRIMARY KEY CLUSTERED)

	IF @bolOnlyOneStorage = 'True' AND @stor_id > 0 -- Solo del deposito, no del grupo...
		BEGIN
			INSERT INTO @tblStorage(intStorageId) VALUES (@stor_id)
		END

	ELSE IF @stor_id = -1
		BEGIN
			INSERT INTO @tblStorage(intStorageId)		SELECT /*DISTINCT*/  ts.stor_id
															FROM dbo.tbStorage ts		WITH (NOLOCK)
			                                   				WHERE	ts.comp_id		= @comp_id AND
			                                   						ts.stor_web4ALL = 'True'
		END
	ELSE
		BEGIN
			-- ----------------------------------------------------------------------------------
			-- NOTA, un deposito SOLO puede pertenecer a un grupo de Depositos para POTENCIAL!!!!
			-- Para que se incluya todo el grupo a un grupo de depositos debe tener el campo
			-- stor_IncludeStockOfStorageGroupMembers en TRUE
			-- ----------------------------------------------------------------------------------
			DECLARE @intStorageGroups AS INT
			SET		@intStorageGroups = NULL
			--SELECT Top 1 @intStorageGroups = tsgd.storg_id
			--	FROM tbStorageGroupDetail tsgd
			--	WITH (NOLOCK)
			--      		WHERE	tsgd.comp_id = @comp_id AND
			--      				tsgd.stor_id = @stor_id
			-- ----------------------------------------------------------------------------------
			DECLARE @bitIncludeStorageGroups BIT
			SELECT	@bitIncludeStorageGroups =	CASE
													WHEN ts.storg_id IS NULL THEN 'False'
													ELSE IsNull(ts.stor_IncludeStockOfStorageGroupMembers,'False')
												END,
					@intStorageGroups		 = ts.storg_id
				FROM dbo.tbStorage ts	WITH (NOLOCK)
			WHERE	ts.comp_id = @comp_id AND
					ts.stor_id = @stor_id

			INSERT INTO @tblStorage(intStorageId)		SELECT Distinct ts.stor_id
			                                   				FROM dbo.tbStorage ts					WITH (NOLOCK)
			                                   				LEFT JOIN dbo.tbStorageGroupDetail tsgd	WITH (NOLOCK)
																ON  tsgd.comp_id  = @comp_id AND
																	tsgd.storg_id = @intStorageGroups
				                                   			WHERE	 ts.comp_id = @comp_id AND
				                                   					 --ts.stor_id IS NOT NULL AND
				                                   					(ts.stor_id = @stor_id OR
				                                   						(	tsgd.stor_id IS NOT NULL	AND
				                                   							ts.stor_id <> @stor_id		AND
				    														ts.stor_id = tsgd.stor_id   AND
				                                   							@bitIncludeStorageGroups = 'True'
				                                   						)
				                                   					)
		END
	-- ----------------------------------------------------------------------------------------------



	Declare @decValor decimal(19,5)

	Select	@decValor		= Sum(itst_cant)
		From	dbo.tbItemStorage tb	WITH (NOLOCK)
--		INNER JOIN tbStorage ts
--			ON		ts.comp_id = tb.comp_id	AND
--					ts.stor_id = tb.stor_id
		INNER JOIN @tblStorage tbls
			ON tbls.intStorageId = tb.stor_id
		Where	tb.comp_id	= @comp_id AND
				tb.item_id	= @item_id


	--if @decValor IS NULL
	--	set @decValor = 0

	RETURN ISNULL(@decValor,0)

end




GO





-- MOS 07-2016
-- Retorna el MAXIMO disponible de Itens en Combo
-- Se usa por ejemplo para ML

CREATE FUNCTION [dbo].[fnGetStockOfStorageGroup4MaxAssociation]
(
	@comp_id	int,
	@stor_id	int,
	@item_id	int
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS
BEGIN

	DECLARE @decAStock AS DECIMAL(19,4)
	SET @decAStock = 999999999999


	SELECT @decAStock = CONVERT(INT,dbo.fnGetMinimumValue(@decAStock,
											  IsNull(dbo.fnGetStockOfStorageGroup(@comp_id,@stor_id,tic.item_id_1),0) / dbo.fnNoZDiv(tic.iasso_qty)
											 ))
		FROM tbItemAssociation  tic	WITH (NOLOCK)
			WHERE	tic.comp_id = @comp_id	AND
					tic.item_id = @item_id	AND
					tic.iasso_qty > 0		-- MOS Datasoft tema Notebboks  04-2020



	IF @decAStock = 999999999999
		BEGIN
			SET @decAStock = dbo.fnGetStockOfStorageGroup(@comp_id, @stor_id, @item_id)
		END


	RETURN @decAStock

END
GO







