-- =============================================
-- Author:		MOS
-- Create date: 09/2008
-- =============================================
CREATE FUNCTION [dbo].[fnGetTaxPercentage]
(
	@comp_id			as int       ,
	@bra_id				as int		 ,
	@tax_id				as int		 ,
	@country_id_ori		as int = NULL, --OPTIONAL
	@country_id_des		as int = NULL, --OPTIONAL
	@state_id_ori		as int = NULL, --OPTIONAL
	@state_id_des		as int = NULL, --OPTIONAL
	@cust_id		    AS INT = NULL
)
RETURNS Decimal(19,6)
AS
BEGIN


	-- Declare the return variable here
	DECLARE @decPercentage		as decimal(19,6)
	DECLARE @tax_IsIBPerception AS BIT
	DECLARE @taxName AS VARCHAR(100)
	DECLARE @intTaxCountry AS INT
	DECLARE @intTaxState   AS INT


	SELECT @tax_IsIBPerception	= ISNULL(ttc.taxcl_isPerception,'false'),
		   @taxName				= ttn.tax_desc,
		   @intTaxCountry		= ttc.country_id,
		   @intTaxState			= ttc.state_id
		FROM tbTaxName ttn	WITH (NOLOCK)
		INNER JOIN tbsysTaxClass ttc	WITH (NOLOCK)
		ON ttc.tax_class = ttn.tax_class
	WHERE		ttn.comp_id = @comp_id
			and	ttn.tax_id  = @tax_id
			AND ttc.taxcl_isPerception='true'
			AND ttc.taxcl_isIB = 'true'


	-- ---------------------------------------------------------------------------------
	-- Si no hay definido un pais de origen supone que no hay definido ni un
	-- pais y provincia de origen ni de destino, por lo que pone el pais y provincia
	-- de origen como dice la sucursal.
	-- ---------------------------------------------------------------------------------
	If @country_id_ori Is Null or @country_id_ori = 0
		Begin
			Select @country_id_ori = country_id
				From dbo.tbBranch	WITH (NOLOCK)
				Where   comp_id    = @comp_id
					and bra_id     = @bra_id
			Set @country_id_des    = @country_id_ori

			Select @state_id_ori   = state_id
				From dbo.tbBranch	WITH (NOLOCK)
				Where   comp_id    = @comp_id
					and bra_id     = @bra_id
			Set @state_id_des      = @state_id_ori

		End
		-- ---------------------------------------------------------------------------------

	-- ---------------------------------------------------------------------------------
	-- Si tiene definido un impuesto para una determinada provincia y pais de origen
	-- y destino, los busca.  Ademas busca si hay definidos percepciones que van con el pais
	-- y provincia del cliente y el cliente esta en la tabla tbTaxIBCustomers_ForSales
	-- con el pais y provincia de destino.!
	-- ---------------------------------------------------------------------------------
	SELECT Top 1 @decPercentage = tax_porcent
		From dbo.tbTax_Ori_Des	tod	WITH (NOLOCK)
		Where   tod.comp_id			= @comp_id
			and tod.tax_id			= @tax_id
			AND (tod.bra_id IS NULL OR tod.bra_id = @bra_id )
			and tod.country_id_ori	= @country_id_ori
			and tod.state_id_ori	= @state_id_ori and
				(   (tod.state_id_des			= @state_id_des
					  and tod.country_id_des	= @country_id_des)
				 OR (	@tax_IsIBPerception = 'true' and
				 		exists (SELECT 1
									FROM tbTaxIBCustomers_ForSales ttifs	WITH (NOLOCK)
									WHERE	ttifs.comp_id		= @comp_id
										AND ttifs.cust_id		= @cust_id
										AND ttifs.state_id		= tod.state_id_des
										AND ttifs.country_id	= tod.country_id_des
							  )
				 	)
				)
	ORDER BY IsNull(tod.bra_id,99999999)
	-- ---------------------------------------------------------------------------------

	-- ---------------------------------------------------------------------------------
	-- MOS, 12-2008: Si no encuentra su impuesto, pone el % definido en tbTaxName.-
	-- ---------------------------------------------------------------------------------
	If isnull(@decPercentage,-1) = -1
		Begin
			SELECT @decPercentage = tax_percentage
				From dbo.tbTaxName	WITH (NOLOCK)
				Where	comp_id   = @comp_id
					and	tax_id    = @tax_id
		End

	SET @decPercentage = ISNULL(@decPercentage,0)
	-- ---------------------------------------------------------------------------------


	-- Return the result of the function
	RETURN @decPercentage

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 12/2013
-- =============================================
CREATE FUNCTION [dbo].[fnGetTaxPercentage4Suppliers]
(
	@comp_id			as int       ,
	@bra_id				as int		 ,
	@tax_id				as int		 ,
	@country_id_ori		as int = NULL, --OPTIONAL
	@country_id_des		as int = NULL, --OPTIONAL
	@state_id_ori		as int = NULL, --OPTIONAL
	@state_id_des		as int = NULL, --OPTIONAL
	@supp_id		    AS INT = NULL
)
RETURNS Decimal(19,6)
AS
BEGIN




--RETURN(20)

	-- Declare the return variable here
	DECLARE @decPercentage		as decimal(19,6)
	DECLARE @tax_IsIBPerception AS BIT
	DECLARE @taxName AS VARCHAR(100)
	DECLARE @intTaxCountry AS INT
	DECLARE @intTaxState   AS INT


	SELECT @tax_IsIBPerception	= ISNULL(ttc.taxcl_isPerception,'false'),
		   @taxName				= ttn.tax_desc,
		   @intTaxCountry		= ttc.country_id,
		   @intTaxState			= ttc.state_id
		FROM tbTaxName ttn					WITH (NOLOCK)
		INNER JOIN tbsysTaxClass ttc		WITH (NOLOCK)
			ON ttc.tax_class = ttn.tax_class
		WHERE		ttn.comp_id				= @comp_id
				and	ttn.tax_id				= @tax_id
				AND ttc.taxcl_isPerception	= 'true'
				AND ttc.taxcl_isIB			= 'true'


	SELECT @intTaxCountry		= ttn.country_id,
		   @intTaxState			= ttn.state_id
		FROM tbTaxName ttn		WITH (NOLOCK)
	WHERE		ttn.comp_id = @comp_id
			and	ttn.tax_id  = @tax_id


	-- MOS: 03-2015
	-- Verifica si aplica el impuesto al pais y provincia del proveedor segun lo que esta configurado en el mismo impuesto.!!
	IF @intTaxCountry IS NOT NULL
		BEGIN
			DECLARE @intSuppCountry AS INT
			DECLARE @intSuppState	AS INT
			SELECT	@intSuppCountry = ts.country_id,
					@intSuppState	= ts.state_id
				FROM tbSupplier ts		WITH (NOLOCK)
				WHERE	ts.comp_id = @comp_id AND
						ts.supp_id = @supp_id



			IF @intSuppCountry <> @intTaxCountry
				BEGIN
					RETURN 0
				END

			IF @intTaxState IS NOT NULL
				BEGIN
					IF @intTaxState <> @intSuppState
						BEGIN
							RETURN 0
						END
				END
		END




	-- ---------------------------------------------------------------------------------
	-- Si no hay definido un pais de origen supone que no hay definido ni un
	-- pais y provincia de origen ni de destino, por lo que pone el pais y provincia
	-- de origen como dice la sucursal.
	-- ---------------------------------------------------------------------------------
	If @country_id_ori Is Null or @country_id_ori = 0
		Begin
			Select @country_id_ori = country_id
				From dbo.tbBranch						WITH (NOLOCK)
				Where   comp_id    = @comp_id
					and bra_id     = @bra_id
			Set @country_id_des    = @country_id_ori

			Select @state_id_ori   = state_id
				From dbo.tbBranch						WITH (NOLOCK)
				Where   comp_id    = @comp_id
					and bra_id     = @bra_id
			Set @state_id_des      = @state_id_ori

		End
		-- ---------------------------------------------------------------------------------



	-- ---------------------------------------------------------------------------------
	-- MOS, 12-2013: Si no encuentra su impuesto, pone el % definido en tbTaxName.-
	-- ---------------------------------------------------------------------------------
	If isnull(@decPercentage,-1) = -1
		Begin
			SELECT @decPercentage = tax_percentage
				From dbo.tbTaxName tn		WITH (NOLOCK)
				Where	tn.comp_id   = @comp_id		AND
						tn.tax_id    = @tax_id		AND
						(
							(tn.country_id IS NULL OR tn.country_id = @country_id_ori)
							AND
							(tn.state_id   IS NULL OR tn.state_id   = @state_id_ori)
						)
		End

	SET @decPercentage = ISNULL(@decPercentage,0)
	-- ---------------------------------------------------------------------------------



	-- Return the result of the function
	RETURN @decPercentage

END
GO




-- OK/100


CREATE FUNCTION [dbo].[fnGetTEA]
(
	@decTotalPriceOfLOAN	DECIMAL(19,6),  --  Precio de cuota x cantidad de cuotas
	@decPriceList			DECIMAL(19,6),  --  Precio de Lista
	@intQuoteQTY			INT				-- Cantidad de cuotas
)
RETURNS DECIMAL(19,4)
AS

BEGIN

	DECLARE @decTEA AS DECIMAL(19,2)

	--SET		@decTEA = (((@decTotalPriceOfLOAN/dbo.fnNoZDiv(@decPriceList))-1)/ dbo.fnNoZDiv( @intQuoteQTY))*12*100
	SET		@decTEA = POWER(
						(1 + (
							CASE
								--WHEN 1 = 2 THEN 1
								WHEN ABS(dbo.fnGetTEM(@decTotalPriceOfLOAN,@decPriceList,@intQuoteQTY)) > 1000 THEN 0
								ELSE dbo.fnGetTEM(@decTotalPriceOfLOAN,@decPriceList,@intQuoteQTY)
							END
							/100))
						,12) - 1
	RETURN ISNULL(@decTEA,0) * 100

END
GO








-- Coeficiente en % de Financiacion Total
CREATE FUNCTION [dbo].[fnGetTEM]
(
	@decTotalPriceOfLOAN	DECIMAL(19,6),  --  Precio de cuota x cantidad de cuotas
	@decPriceList			DECIMAL(19,6),  --  Precio de Lista
	@intQuoteQTY			INT				-- Cantidad de cuotas
)
RETURNS DECIMAL(19,4)
AS

BEGIN

	DECLARE @decTEM AS DECIMAL(19,2)

	SET		@decTEM = dbo.fnGetTNA(@decTotalPriceOfLOAN,@decPriceList,@intQuoteQTY) / 12

	RETURN ISNULL(@decTEM,0)

END
GO







CREATE FUNCTION [dbo].[fnGetTermino]
(
	@termino as nvarchar(4000)
)
RETURNS nvarchar(4000)
AS
BEGIN

	Declare  @ret_termino as nvarchar(4000)

--	SELECT @ret_termino =
--			CASE ltrim(rtrim(@termino))
--				WHEN '@PF_ITEM_STOCK'	THEN	' dbo.fnGetAStock(@comp_id, @stor_id, item_id, 999) '
--				WHEN '@PF_ITEM_QTYMIN1' THEN	' item_qtyMin1 '
--				WHEN '@PF_ITEM_QTYMIN2' THEN	' item_qtyMin2 '
--				WHEN '@PF_ITEM_QTYMIN3' THEN	' item_qtyMin3 '
--				ELSE ''
--			END


	SELECT	@ret_termino = tov.optval_desc

	FROM	tbsysOptionsValues				tov

			INNER JOIN tbsysOptionsValues	tov2
			ON tov.lang_id		= tov2.lang_id
			AND tov.optval_id	= tov2.optval_id

	WHERE	tov.lang_id			= -1
	AND		tov.optval_class	= -2
	AND		tov2.optval_class	= -1
	AND		LTRIM(RTRIM(tov2.optval_desc))	= LTRIM(RTRIM(@termino))


	Return @ret_termino

END





GO







-- Coeficiente en % de Financiacion Total
CREATE FUNCTION [dbo].[fnGetTNA]
(
	@decTotalPriceOfLOAN	DECIMAL(19,6),  --  Precio de cuota x cantidad de cuotas
	@decPriceList			DECIMAL(19,6),  --  Precio de Lista
	@intQuoteQTY			INT				-- Cantidad de cuotas
)
RETURNS DECIMAL(19,4)
AS

BEGIN

	DECLARE @decTNA AS DECIMAL(19,2)

	SET		@decTNA = ((@decTotalPriceOfLOAN / dbo.fnNoZDiv(@decPriceList) ) - 1) / dbo.fnNoZDiv(@intQuoteQTY) * 12

	RETURN ISNULL(@decTNA,0) * 100

END
GO


