-- MOS
-- ----------------

CREATE FUNCTION [dbo].[fnGetTotalWithOutRetentions]
(
	@comp_id		AS INT,
	@decTotal		AS DECIMAL(19,6),
	@ct_transaction	AS INT
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS
BEGIN

	DECLARE @decRetentions AS DECIMAL(19,4)
	SET		@decRetentions = 0

	SELECT @decRetentions = SUM(ttm.tm_total)
		FROM tbTaxMovements ttm							WITH (NOLOCK)
		INNER JOIN tbTaxName ttn						WITH (NOLOCK)
			ON	ttn.comp_id = ttm.comp_id AND
				ttn.tax_id	= ttm.tax_id
		INNER JOIN vwsysTaxClassALL_Retentions kk		WITH (NOLOCK)
			ON kk.tax_class = ttn.tax_class
		WHERE	ttm.comp_id			= @comp_id AND
				ttm.ct_transaction	= @ct_transaction


	RETURN @decTotal - ISNULL(@decRetentions,0)

END

GO







