-- MOS
-- ----------------

Create FUNCTION [dbo].[fnGetTotalWithOutTaxes]
(
	@decTotal		AS DECIMAL(19,6),
	@decTAXPercent	AS DECIMAL(19,6)
)


RETURNS decimal(19,5)
WITH EXECUTE AS CALLER
AS
BEGIN

	IF @decTAXPercent <> 0
		BEGIN
			RETURN @decTotal / ((@decTAXPercent / 100) + 1)
		END

	RETURN @decTotal

END

GO





