-- Calcula el menor volumen para embalar articulos vendidos
CREATE FUNCTION [dbo].[fngetVolumeCalculation]
(@guid AS UNIQUEIDENTIFIER)
returns @temptable TABLE (
							[weight]	decimal(25, 6) NULL,
							[higth]		decimal(25, 6) NULL,
							[large]		decimal(25, 6) NULL,
							[wide]		decimal(25, 6) NULL
)	WITH SCHEMABINDING
AS
BEGIN


	DECLARE @totalWeight	AS DECIMAL(25,6) = 0
	DECLARE @totalHigth		AS DECIMAL(25,6) = 0
	DECLARE @totalLarge		AS DECIMAL(25,6) = 0
	DECLARE @totalWide		AS DECIMAL(25,6) = 0

	DECLARE @weight	AS DECIMAL(25,6) = 0
	DECLARE @higth	AS DECIMAL(25,6) = 0
	DECLARE @large	AS DECIMAL(25,6) = 0
	DECLARE @wide	AS DECIMAL(25,6) = 0
	DECLARE @qty	AS DECIMAL(25,6) = 0


	DECLARE curItems CURSOR LOCAL FAST_FORWARD FOR
		SELECT  tmp.[weight],
				tmp.[higth],
				tmp.[large],
				tmp.[wide],
				tmp.[qty]
			FROM dbo.tbVolumeCalculationTMP tmp WITH (NOLOCK)
			WHERE [guid] = @guid

	OPEN		curItems

	DECLARE @tmpMessureMin AS DECIMAL(25,6) = 0
	DECLARE @tmpMessureMid AS DECIMAL(25,6) = 0
	DECLARE @tmpMessureMax AS DECIMAL(25,6) = 0
	DECLARE @tmpWeight	   AS DECIMAL(25,6) = 0
	DECLARE @tmpFile          TABLE(tmpMessure DECIMAL(25,6))


	FETCH NEXT FROM curItems INTO @weight,@higth,@large,@wide,@qty
	WHILE @@FETCH_STATUS = 0
		BEGIN
			DELETE FROM @tmpFile
			INSERT INTO @tmpFile(tmpMessure) VALUES (@higth)
			INSERT INTO @tmpFile(tmpMessure) VALUES (@large)
			INSERT INTO @tmpFile(tmpMessure) VALUES (@wide)

			SELECT
					@tmpMessureMin	= CASE
					              	      WHEN ROW_NUMBER() OVER (Order by tmpMessure ASC) = 1 THEN tmp.tmpMessure
					              	      ELSE	@tmpMessureMin
					              	  END,
					@tmpMessureMid	= CASE
					              	      WHEN ROW_NUMBER() OVER (Order by tmpMessure ASC) = 2 THEN tmp.tmpMessure
					              	      ELSE	@tmpMessureMid
					              	  END,
					@tmpMessureMax	= CASE
					              	      WHEN ROW_NUMBER() OVER (Order by tmpMessure ASC) = 3 THEN tmp.tmpMessure
					              	      ELSE	@tmpMessureMax
					              	  END
				FROM @tmpFile	tmp
				ORDER BY tmp.tmpMessure ASC


			DECLARE @tmpWide	AS DECIMAL(25,6) = 0
			DECLARE @tmpLarge	AS DECIMAL(25,6) = 0


			SET @tmpWide  =	CASE
								WHEN @tmpMessureMid <= @tmpMessureMax THEN	@tmpMessureMid
								ELSE										@tmpMessureMax
							END
			SET @tmpLarge = CASE
								WHEN @tmpMessureMid <= @tmpMessureMax THEN	@tmpMessureMax
								ELSE										@tmpMessureMid
							END


			SET @totalHigth = @totalHigth + (@tmpMessureMin * @qty)
			SET @totalWide  = 	CASE
									WHEN @tmpWide > @totalWide THEN @tmpWide
									ELSE							@totalWide
								END


			SET @totalLarge  = 	CASE
									WHEN @tmpLarge > @totalLarge THEN @tmpLarge
									ELSE							  @totalLarge
								END

			SET @totalWeight = @totalWeight + (@weight * @qty)


			FETCH NEXT FROM curItems INTO @weight,@higth,@large,@wide,@qty
		END
	CLOSE		curItems
	DEALLOCATE	curItems

    INSERT INTO @temptable([weight], higth, large, wide) VALUES(@totalWeight, @totalHigth, @totalLarge, @totalWide)

	RETURN
END
GO





CREATE FUNCTION [dbo].[fnGetWarrantyDays]
(
	@processingDate		DATETIME,
	@intOffsetDays		INT,
	@intWarrantyDays	INT,
	@intOptionReturn	INT		-- 1- Desde, 2- Hasta, Otro: Desde - Hasta
)
RETURNS NVARCHAR(100)
AS

BEGIN


	IF @intOffsetDays	IS NULL	SET @intOffsetDays		= 0
	IF @intWarrantyDays IS NULL SET @intWarrantyDays	= 0

	IF @intOffsetDays	> 20000	SET @intOffsetDays		= 5000
	IF @intWarrantyDays > 20000 SET @intWarrantyDays	= 5000



	DECLARE @strReturn AS NVARCHAR(100)
	SET		@processingDate = dbo.fnGetEnd_or_BeginOfDate(@processingDate,'False')
	SET		@processingDate = DATEADD(DAY, @intOffsetDays,  @processingDate)
	SET		@strReturn		= CONVERT(NVARCHAR(50), @processingDate, 103 )

	SET		@processingDate = DATEADD(DAY, @intWarrantyDays,  @processingDate)



	IF @intOptionReturn <> 1
		BEGIN
			SET	@strReturn			= @strReturn + ' - '
			IF	@intOptionReturn	= 2 SET @strReturn = '' -- Si solo pido HASTA entonces limpio el Desde
			SET	@strReturn			= @strReturn + CONVERT(NVARCHAR(50), @processingDate, 103 )
		END

	RETURN @strReturn

END
GO





CREATE FUNCTION [dbo].[fnGetWarrantyUp2Date]
(
	@processingDate		DATETIME,
	@intOffsetDays		INT,
	@intWarrantyDays	INT
)
RETURNS DATETIME
AS

BEGIN


	IF @intOffsetDays	IS NULL	SET @intOffsetDays		= 0
	IF @intWarrantyDays IS NULL SET @intWarrantyDays	= 0

	DECLARE @datReturn AS DATETIME
	SET		@processingDate = dbo.fnGetEnd_or_BeginOfDate(@processingDate,'False')
	SET		@processingDate = DATEADD(DAY, @intOffsetDays,  @processingDate)
	SET		@processingDate = DATEADD(DAY, @intWarrantyDays,  @processingDate)

	SET	@datReturn			= dbo.fnGetEnd_or_BeginOfDate(@processingDate,'True')

	RETURN @datReturn

END

GO







CREATE FUNCTION [dbo].[fnGetWordsCutByChar]
(
	@strToCut				NVARCHAR(4000),
	@Delimiter				NVARCHAR(2),
	@maxlenght				INT
)
RETURNS  					NVARCHAR(4000)
AS

BEGIN

	/*
	DECLARE @strToCut				NVARCHAR(4000),
			@Delimiter				NVARCHAR(2),
			@maxlenght				INT
	SELECT	@strToCut				= 'Citroen C4 Hatchback 2.1i Exclusive BVA   Test Item',
			@Delimiter				= ' ',
			@maxlenght				= 15
	*/


	DECLARE @strFinal				NVARCHAR(4000),
			@string2				NVARCHAR(4000),
			@idxDelimiterPosition	INT,
			@strWordCut				NVARCHAR(4000),
			@DelimiterLenght		INT,
			@strWordToCut			NVARCHAR(4000),
			@cut					BIT



	SET @strFinal = ''

	SET @string2 = REPLACE (ltrim(rtrim(@strToCut)), @Delimiter, '%$&')
    --SELECT @string2

    SET @DelimiterLenght = LEN('%$&') - 1 --longitud del delimitador - 1

    if len(@strToCut)<1 or @strToCut is null  RETURN @strToCut

	SET @cut = 'true'




	WHILE @cut = 'true'
	BEGIN

		SET @cut = 'false'

		SELECT @idxDelimiterPosition = 1


		WHILE @idxDelimiterPosition!= 0
		BEGIN

			SET @idxDelimiterPosition = CHARINDEX('%$&',@String2)
	        --select @idxDelimiterPosition, @string2

--			SET @strWordToCut = CASE
--									WHEN @idxDelimiterPosition = 0 THEN @String2
--									WHEN @idxDelimiterPosition = 1 THEN	left(@String2, @idxDelimiterPosition)
--									ELSE								left(@String2, @idxDelimiterPosition - 1)
--								END

			IF @idxDelimiterPosition!=0
        		SET @strWordToCut = left(@String2, @idxDelimiterPosition - 1)
			ELSE
        		SET @strWordToCut = @String2
			--SELECT @strWordToCut


    		IF LEN(@strWordToCut) > @maxlenght
    		BEGIN
    			SET @strWordCut =
     				SUBSTRING(@strWordToCut,1,@maxlenght) + @Delimiter +
					SUBSTRING(@strWordToCut,@maxlenght+1,LEN(@strWordToCut)- @maxlenght)
				SET @cut = 'true'
			END
    		ELSE
    			SET @strWordCut = @strWordToCut



			if(len(@strWordCut)>0)
				SET @strFinal = @strFinal + @strWordCut + @Delimiter


			--SELECT @String2,LEN(@String2),@idxDelimiterPosition,@DelimiterLenght

			IF @idxDelimiterPosition >= @DelimiterLenght
				SET @String2 = RIGHT(@String2,len(@String2) - @idxDelimiterPosition - @DelimiterLenght)
			ELSE
				IF @idxDelimiterPosition = 1
					SET @String2 = right(@String2,len(@String2) - @idxDelimiterPosition - @DelimiterLenght)


			IF LEN(@String2) = 0 BREAK

		END

		IF @cut = 'true'
		BEGIN
			SET @string2 = REPLACE (@strFinal, @Delimiter, '%$&')
			SET @strFinal = ''
		END

    END



    SET @strFinal = LTRIM(RTRIM(@strFinal))

    IF RIGHT(@strFinal, LEN(@Delimiter)) = @Delimiter
       SET @strFinal = LEFT(@strFinal, LEN(@strFinal)-LEN(@Delimiter))

    --SELECT @strFinal
	RETURN @strFinal

END
GO



CREATE FUNCTION [dbo].[fnIPCheck]
(
	@strIP AS NVARCHAR(50)
)
RETURNS NVARCHAR(50)
AS

BEGIN


	SET @strIP = dbo.fnStrAllTrim(ISNULL(@strIP,''))

	IF @strIP <> ''
		BEGIN
			SET @strIP =
					dbo.fnStrPADL( dbo.fnSplitPosition(@strIP,'.',1),3,'0') + '.' +
					dbo.fnStrPADL( dbo.fnSplitPosition(@strIP,'.',2),3,'0') + '.' +
					dbo.fnStrPADL( dbo.fnSplitPosition(@strIP,'.',3),3,'0') + '.' +
					dbo.fnStrPADL( dbo.fnSplitPosition(@strIP,'.',4),3,'0')
		END

	RETURN isnull(@strIP,'')

END
GO




