CREATE FUNCTION [dbo].[fnItem_getDataByText_getStock]
(
	-- Add the parameters for the function here
	@decNumber		AS DECIMAL(19,4),
	@decLength		AS INT				/*Puede ser 2 o 3 */
)
RETURNS VARCHAR(4)
AS
BEGIN


	IF @decNumber IS NULL SET @decNumber = 0
	DECLARE @strReturn AS VARCHAR(30)



	IF @decLength = 2		AND @decNumber > 99
		BEGIN
			SET @strReturn = '+9'
		END
	ELSE IF @decLength = 3	AND @decNumber > 999
		BEGIN
			SET @strReturn = '+99'
		END

	ELSE
		BEGIN
			SET @strReturn = convert( VARCHAR ,CONVERT(DECIMAL(10,0),@decNumber))
			SET @strReturn = dbo.fnStrPADL(@strReturn,8,'0')
			SET @strReturn = RIGHT(@strReturn,@decLength)
		END

--RIGHT( dbo.fnStrPADL(convert( VARCHAR ,CONVERT(DECIMAL(10,0), ROUND (ISNULL(dbo.fnGetAStock(@comp_id,@intStoreIdAdditional,ti.item_id,999999999),0),0))),08,'0'),2)

	RETURN ISNULL(@strReturn,'')

END
GO




