CREATE FUNCTION [dbo].[fnItem_getDataByText_getTaxPercentage]
(
	-- Add the parameters for the function here
	@Comp_Id		AS INT,
	@Item_Id		AS INT				/*Puede ser 2 o 3 */
)
RETURNS DECIMAL(19,5)
AS
BEGIN

	DECLARE @decPercentage AS DECIMAL(19,5)
	SET		@decPercentage = 0

		SELECT   @decPercentage = ttn.tax_percentage
			from vwItemTaxesOnlyOneIvaTax				vitooit		WITH (NOLOCK)
			inner JOIN tbTaxName						ttn			WITH (NOLOCK)
