-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnItemClass4tbItem_getCombo]
(
	@comp_id		INT,
	@ic_id			INT
)
RETURNS NVARCHAR(200)
AS
BEGIN

	DECLARE @strOption AS NVARCHAR(MAX)
	DECLARE @ic_id_aux AS INT
	DECLARE @strOptionAux AS NVARCHAR(MAX)
	SET @strOption = ''

	-- Nivel 1 hacia arriba

	SET @strOptionAux = ''
	SELECT	@strOptionAux	= tic.ic_desc,
			@ic_id_aux		= tic.ic_id_sup
		FROM tbItemClass tic
		WHERE	tic.comp_id = @comp_id AND
				tic.ic_id	= @ic_id

	IF @strOptionAux <> ''
		BEGIN
			IF LEN(@strOptionAux) > 25
				BEGIN
					SET @strOptionAux = SUBSTRING(@strOptionAux,0,25) + '...'
				END
			ELSE
				BEGIN
					SET @strOptionAux = dbo.fnStrPADR(@strOptionAux,28,'.')
				END
			SET @strOption = @strOptionAux + '->' + @strOption
		END


	SET @ic_id = @ic_id_aux

	-- Nivel 2 hacia arriba

	SET @strOptionAux = ''
	SELECT	@strOptionAux	= tic.ic_desc,
			@ic_id_aux		= tic.ic_id_sup
		FROM tbItemClass tic
		WHERE	tic.comp_id = @comp_id AND
				tic.ic_id	= @ic_id

	IF @strOptionAux <> ''
		BEGIN
			IF LEN(@strOptionAux) > 25
				BEGIN
					SET @strOptionAux = SUBSTRING(@strOptionAux,0,25) + '...'
				END
			ELSE
				BEGIN
					SET @strOptionAux = dbo.fnStrPADR(@strOptionAux,28,'.')
				END
			SET @strOption = @strOptionAux + '->' + @strOption
		END

	SET @ic_id = @ic_id_aux

	-- Nivel 3 hacia arriba

	SET @strOptionAux = ''
	SELECT	@strOptionAux	= tic.ic_desc,
			@ic_id_aux		= tic.ic_id_sup
		FROM tbItemClass tic
		WHERE	tic.comp_id = @comp_id AND
				tic.ic_id	= @ic_id

	IF @strOptionAux <> ''
		BEGIN
			IF LEN(@strOptionAux) > 25
				BEGIN
					SET @strOptionAux = SUBSTRING(@strOptionAux,0,25) + '...'
				END
			ELSE
				BEGIN
					SET @strOptionAux = dbo.fnStrPADR(@strOptionAux,28,'.')
				END
			SET @strOption = @strOptionAux + '->' + @strOption
		END

	SET @ic_id = @ic_id_aux


	-- Nivel 4 hacia arriba

	SET @strOptionAux = ''
	SELECT	@strOptionAux	= tic.ic_desc,
			@ic_id_aux		= tic.ic_id_sup
		FROM tbItemClass tic
		WHERE	tic.comp_id = @comp_id AND
				tic.ic_id	= @ic_id

	IF @strOptionAux <> ''
		BEGIN
			IF LEN(@strOptionAux) > 25
				BEGIN
					SET @strOptionAux = SUBSTRING(@strOptionAux,0,25) + '...'
				END
			ELSE
				BEGIN
					SET @strOptionAux = dbo.fnStrPADR(@strOptionAux,28,'.')
				END
			SET @strOption = @strOptionAux + '->' + @strOption
		END

	SET @ic_id = @ic_id_aux



	RETURN @strOption

END
GO



