-- =============================================
CREATE FUNCTION [dbo].[fnItemComposition2_ManodeObra_color]
(
	-- Add the parameters for the function here
	@comp_id AS INT,
	@bra_id  as int,
	@item_id AS INT,
	@item_id_labor AS INT
)
RETURNS nvarchar(100)
AS
BEGIN


	declare @lManodeObra_color	 nvarchar(100)


	SET @lManodeObra_color = (SELECT top 1 tc.color_desc
							FROM tbItemComposition										tic			WITH (NOLOCK)

							INNER JOIN tbItem											ti			WITH (NOLOCK)
							ON  ti.comp_id   = tic.comp_id
							AND ti.item_id   = tic.item_id

							INNER JOIN tbColor											tc			WITH (NOLOCK)
							ON  tc.comp_id   = tic.comp_id
							AND tc.color_id  = tic.color_id

						  	WHERE ti.comp_id   = @comp_id
							AND  (ti.item_id   = @item_id)
							AND  (ti.bra_id = @bra_id or ( ti.bra_id is null))
							AND   tic.item_id_1 = @item_id_labor)



	RETURN isnull(@lManodeObra_color,'')

END
GO



