-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnItemComposition2_ManodeObra_GastosFijos]
(
	-- Add the parameters for the function here
	@comp_id		AS INT,
	@bra_id			as int,
	@item_id		AS INT,
	@item_id_labor  AS INT,
	@list_id		AS INT,
	@gastosfijos	AS DECIMAL(19,4)
)
RETURNS decimal(19,4)
AS
BEGIN


	declare @lGastosFijos		 decimal(19,4)


	SET @lGastosFijos = (SELECT dbo.fnItemComposition2_ManodeObra_qty(@comp_id,@bra_id,@item_id,@item_id_labor,@list_id)* dbo.fnItemComposition2_ManodeObra_price(@comp_id,@bra_id, @item_id,@item_id_labor,@list_id) * @GastosFijos /100

	)
	RETURN isnull(@lGastosFijos,0)

END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnItemComposition2_ManodeObra_price]
(
	-- Add the parameters for the function here
	@comp_id AS INT,
	@bra_id  as int,
	@item_id AS INT,
	@item_id_labor AS INT,
	@list_id AS INT
)
RETURNS decimal(19,4)
AS
BEGIN

	DECLARE @lManodeObra_price	 decimal(19,4)
	set @lManodeObra_price = (select top 1 ticl.coslis_price FROM tbItemComposition									tic			WITH (NOLOCK)
																INNER JOIN tbItem								ti			WITH (NOLOCK)
													ON  ti.comp_id   = tic.comp_id
													AND ti.item_id   = tic.item_id

													INNER JOIN tbItem											ti2			WITH (NOLOCK)
													ON  ti2.comp_id	 = tic.comp_id
													AND ti2.item_id	 = tic.item_id_1

													LEFT JOIN tbItemCostList									ticl		WITH (NOLOCK)
													ON  ticl.comp_id	= tic.comp_id
													And ticl.coslis_id	= @list_id
													AND ticl.item_id	= ti2.item_id



													WHERE ti.comp_id = @comp_id
													AND  (ti.item_id   = @item_id)
													AND  (ti.bra_id = @bra_id or ( ti.bra_id is null))
													AND   tic.item_id_1 = @item_id_labor)

	RETURN isnull(@lManodeObra_price,0)

END
GO



