-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnItemComposition2_ManodeObra_PriceList_Price_Parcial]
(
	-- Add the parameters for the function here
	@comp_id AS INT,
	@bra_id  as int,
	@item_id AS INT,
	@item_id_labor AS INT,
	@prli_id AS INT,
	@DescuentoGral AS DECIMAL(19,4)

)
RETURNS decimal(19,4)
AS
BEGIN

	DECLARE @lManodeObra_prli_price	 decimal(19,4)
	set @lManodeObra_prli_price = (		select top 1 tpli.prli_price

										FROM tbItemComposition							tic			WITH (NOLOCK)

										INNER JOIN tbItem								ti			WITH (NOLOCK)
										ON  ti.comp_id   = tic.comp_id
										AND ti.item_id   = tic.item_id

										INNER JOIN tbItem								ti2			WITH (NOLOCK)
										ON  ti2.comp_id	 = tic.comp_id
										AND ti2.item_id	 = tic.item_id_1

										LEFT JOIN tbPriceListItems						tpli		WITH (NOLOCK)
										ON  tpli.comp_id	= tic.comp_id
										AND tpli.prli_id	= @prli_id
										AND tpli.item_id	= ti.item_id



										WHERE ti.comp_id = @comp_id
										AND  (ti.item_id   = @item_id)
										AND  (ti.bra_id = @bra_id or ( ti.bra_id is null))
										AND   tic.item_id_1 = @item_id_labor

									)

	RETURN  isnull(@lManodeObra_prli_price,0) - ((isnull(@lManodeObra_prli_price,0) * isnull(@DescuentoGral,0)) / 100)

END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnItemComposition2_ManodeObra_qty]
(
	-- Add the parameters for the function here
	@comp_id AS INT,
	@bra_id  as int,
	@item_id AS INT,
	@item_id_labor AS INT,
	@list_id AS INT
)
RETURNS decimal(19,4)
AS
BEGIN


	declare @lManodeObra_qty	 decimal(19,4)


	-- Cantidad de MO
	set @lManodeObra_qty = (select top 1 tic.icomp_qty

	                        FROM tbItemComposition										tic	WITH (NOLOCK)

							INNER JOIN tbItem											ti	WITH (NOLOCK)
							ON  ti.comp_id   = tic.comp_id
							AND ti.item_id   = tic.item_id

							INNER JOIN tbItem											ti2	WITH (NOLOCK)
							ON  ti2.comp_id	 = tic.comp_id
							AND ti2.item_id	 = tic.item_id_1

							LEFT JOIN tbItemCostList									ticl WITH (NOLOCK)
							ON  ticl.comp_id	= tic.comp_id
							And ticl.coslis_id	= @list_id
							AND ticl.item_id	= ti2.item_id


							WHERE ti.comp_id = @comp_id
							AND   ti.item_id   = @item_id
							AND  (ti.bra_id = @bra_id or ( ti.bra_id is null))
							AND   tic.item_id_1 = @item_id_labor
						)





	RETURN isnull(@lManodeObra_qty,0)

END
GO



CREATE FUNCTION [dbo].[fnItemStoragePhoto]
(
	@comp_id		INT,
	@it_transaction	INT
)
RETURNS NVARCHAR(500)
AS

BEGIN

	DECLARE @strReturn AS NVARCHAR(500)
	SET		@strReturn = ''

	SELECT		@strReturn = @strReturn +
				'(' + Convert(nvarchar(10),ts.stor_id) +
				')'	+
				ts.stor_desc + ':' +
				Convert(nvarchar(10),convert(DECIMAL(10,0), tisp.itstp_cant)) + ' | '
		FROM tbItemStoragePhoto tisp
		INNER JOIN tbStorage ts
			ON	ts.comp_id = tisp.comp_id AND
				ts.stor_id = tisp.stor_id
		WHERE	tisp.comp_id		= @comp_id AND
				tisp.it_transaction = @it_transaction


	RETURN @strReturn


END
GO





