Create FUNCTION [dbo].[fnReadfileAsTable]
(
@Path VARCHAR(255),
@Filename VARCHAR(100)
)
RETURNS
@File TABLE
(
[LineNo] int identity(1,1),
line varchar(8000))

AS
BEGIN

DECLARE  @objFileSystem int
        ,@objTextStream int,
		@objErrorObject int,
		@strErrorMessage Varchar(1000),
	    @Command varchar(1000),
	    @hr int,
		@String VARCHAR(8000),
		@YesOrNo INT

select @strErrorMessage='opening the File System Object'
EXECUTE @hr = sp_OACreate  'Scripting.FileSystemObject' , @objFileSystem OUT


if @HR=0 Select @objErrorObject=@objFileSystem, @strErrorMessage='Opening file "'+@path+'\'+@filename+'"',@command=@path+'\'+@filename

if @HR=0 execute @hr = sp_OAMethod   @objFileSystem  , 'OpenTextFile'
	, @objTextStream OUT, @command,1,false,0--for reading, FormatASCII

WHILE @hr=0
	BEGIN
	if @HR=0 Select @objErrorObject=@objTextStream,
		@strErrorMessage='finding out if there is more to read in "'+@filename+'"'
	if @HR=0 execute @hr = sp_OAGetProperty @objTextStream, 'AtEndOfStream', @YesOrNo OUTPUT

	IF @YesOrNo<>0  break
	if @HR=0 Select @objErrorObject=@objTextStream,
		@strErrorMessage='reading from the output file "'+@filename+'"'
	if @HR=0 execute @hr = sp_OAMethod  @objTextStream, 'Readline', @String OUTPUT
	INSERT INTO @file(line) SELECT @String
	END

if @HR=0 Select @objErrorObject=@objTextStream,
	@strErrorMessage='closing the output file "'+@filename+'"'
if @HR=0 execute @hr = sp_OAMethod  @objTextStream, 'Close'


if @hr<>0
	begin
	Declare
		@Source varchar(255),
		@Description Varchar(255),
		@Helpfile Varchar(255),
		@HelpID int

	EXECUTE sp_OAGetErrorInfo  @objErrorObject,
		@source output,@Description output,@Helpfile output,@HelpID output
	Select @strErrorMessage='Error whilst '
			+coalesce(@strErrorMessage,'doing something')
			+', '+coalesce(@Description,'')
	insert into @File(line) select @strErrorMessage
	end
EXECUTE  sp_OADestroy @objTextStream
	-- Fill the table variable with the rows for your result set

	RETURN
END
GO


-- MOS: 03-2020: No se si se usa pero si da error es poir falta de permisos, NO USARLA !!!   en todo caso hacer una CLR ya que SQL no soporta esto
-- o ver esto y hacerlo así:  https://codingsight.com/t-sql-regular-expression-like-operator-and-its-use-cases/


CREATE FUNCTION [dbo].[fnRegularExpressionCheck] (@strSource varchar(5000),
												 @strRegexp varchar(1000),
												 @bitIgnoreCase bit = 0 )
RETURNS INT
AS
BEGIN

	DECLARE @hr			integer
	DECLARE @objRegExp	integer
	DECLARE @objMatches integer
	DECLARE @objMatch	integer
	DECLARE @count		integer
	DECLARE @results	bit





	EXEC @hr = sp_OACreate 'VBScript.RegExp', @objRegExp OUTPUT
	IF @hr <> 0
		BEGIN
			SET @results = 0
			RETURN @results
		END




	EXEC @hr = sp_OASetProperty @objRegExp, 'Pattern', @strRegexp
	IF @hr <> 0
		BEGIN
			SET @results = 0
			RETURN @results
		END



	EXEC @hr = sp_OASetProperty @objRegExp, 'Global', false
	IF @hr <> 0
		BEGIN
			SET @results = 0
				RETURN @results
		END





	EXEC @hr = sp_OASetProperty @objRegExp, 'IgnoreCase', @bitIgnoreCase
	IF @hr <> 0
		BEGIN
			SET @results = 0
			RETURN @results
		END

	EXEC @hr = sp_OAMethod @objRegExp, 'Test', @results OUTPUT, @strSource




	IF @hr <> 0
		BEGIN
			SET @results = 0
			RETURN @results
	END




	EXEC @hr = sp_OADestroy @objRegExp
	IF @hr <> 0
		BEGIN
			SET @results = 0
			RETURN @results
		END



	RETURN @results
END


-- See more at: http://www.sqlteam.com/article/regular-expressions-in-t-sql#sthash.KdablPYd.dpuf
GO


-- =============================================
-- Author:		STL
-- Create date: 24-05-2016
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnRMA_GetHTMLTable4StatusChanges]
(
	@comp_id	INT,
	@lang_id	INT,
	@rmah_id	INT,
	@rmad_id	INT
)

RETURNS NVARCHAR(MAX)
AS
	BEGIN

		-- ------------------------------
		-- TESTING
		-- ------------------------------
		/*
			DECLARE
				@comp_id	INT,
				@lang_id	INT,
				@rmah_id	INT,
				@rmad_id	INT
			SELECT
				@comp_id	= 1,
				@lang_id	= 2,
				@rmah_id	= 1032,
				@rmad_id	= 15
		*/
		-- ------------------------------

		DECLARE
			@tableBegin	VARCHAR(30),
			@tableEnd	VARCHAR(30),
			@table		VARCHAR(4000),
			@FinalTable	NVARCHAR(MAX)

		SET @tableBegin = '<table>'
		SET @tableEnd	= '</table>'
		SET @table		= ''
		SET @FinalTable	= ''


		SELECT
			@table = @table + ' ' +
			'<tr><td width="400px">'						+ '   ' +
			CONVERT(VARCHAR,trdah.rmadh_cd,103)				+ '   ' +
			--'</td>'										+ '   ' +
			--'<td width="100px">'							+ '   ' +
			tov.optval_desc									+ '   ' +
			--'</td>'										+ '   ' +
			--'<td width="100px">'							+ '   ' +
			tu.user_lastname + ',' + tu.user_firstname		+ '   ' +
			'</td></tr>'
			FROM tbRMA_Detail_AttributesHistory				trdah
				INNER JOIN tbsysOptionsValues				tov
					ON	tov.lang_id			= @lang_id		AND
						tov.optval_id		= trdah.srpt_id	AND
						tov.optval_class	= 109
				INNER JOIN tbUser							tu
					ON	tu.[user_id]		= trdah.[user_id]
			WHERE	trdah.comp_id			= @comp_id		AND
					trdah.rmah_id			= @rmah_id		AND
					trdah.rmad_id			= @rmad_id
			ORDER BY trdah.rmadh_cd DESC

		SET @FinalTable  = @tableBegin + ISNULL(@table,'') + @tableEnd

		RETURN (@FinalTable)
	END
GO




-- =============================================
-- Author:		MOS
