CREATE FUNCTION fnRMAHeader_getReportDetail_GetNC_Rm
(
	@comp_id AS INT,
	@rmah_id AS INT,
	@rmad_id AS INT,
	@lang_id AS INT
)
RETURNS NVARCHAR(50)
AS
BEGIN

	DECLARE @strReturn AS NVARCHAR(50)
	SET @strReturn = ''

	SELECT  TOP 1
			@strReturn = dbo.fnGetCommercialTransactionDescription(tit.comp_id,@lang_id,tit.ct_transaction)
		FROM  tbItemTransactions tit			WITH (NOLOCK)
		INNER JOIN tbCommercialTransactions tct
			ON	tct.comp_id			= tit.comp_id			AND
				tct.bra_id			= tit.bra_id			AND
				tct.ct_transaction	= tit.ct_transaction	AND
				tct.sd_id IN (2,3)
		WHERE 	tit.comp_id = @comp_id		AND
				tit.rmah_id = @rmah_id		AND
				tit.rmad_id = @rmad_id

	RETURN @strReturn

END
GO




