create FUNCTION [dbo].[fnRound250Cents] ( @decNumber AS DECIMAL(25,8) )
RETURNS DECIMAL(25,8)
AS
BEGIN

	IF  ROUND(@decNumber,0) < @decNumber			RETURN ROUND(@decNumber,0) + 0.5
	ELSE IF Floor(@decNumber)  + 0.5 = @decNumber	RETURN @decNumber
	ELSE IF ROUND(@decNumber,0) > @decNumber		RETURN ROUND(@decNumber,0)
	ELSE											RETURN @decNumber

	RETURN @decNumber

END

GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnRoundByMultiple]
(
	@decAmount			DECIMAL(25,6),
	@intMultiple		INT,
	@intOption			INT
)
RETURNS DECIMAL(25,6)
AS
BEGIN

	IF @intMultiple = 0 SET @intMultiple = 1	-- MOS 05-2024: Para que NO explote si dejan 0 en @intMultiple


	IF @intOption		= 1
		RETURN  ROUND(  @decAmount / @intMultiple, 0) * @intMultiple
	ELSE IF @intOption	= 2
		RETURN  CEILING(@decAmount / @intMultiple)	  * @intMultiple
	ELSE IF @intOption	= 3
		RETURN  FLOOR(  @decAmount / @intMultiple)	  * @intMultiple

	RETURN @decAmount

END
GO




CREATE FUNCTION [dbo].[fnRoundQuote]
(
	@decNumber	AS DECIMAL(25,8),
	@intMode	AS INT
)
RETURNS DECIMAL(25,8)	WITH SCHEMABINDING
AS
BEGIN

	IF		@intMode = 1	-- a 50 Centavos
		BEGIN
			IF		ROUND(@decNumber,0) < @decNumber		RETURN ROUND(@decNumber,0) + 0.5
			ELSE IF Floor(@decNumber)  + 0.5 = @decNumber	RETURN @decNumber
			ELSE IF ROUND(@decNumber,0) > @decNumber		RETURN ROUND(@decNumber,0)
			ELSE											RETURN @decNumber
		END
	ELSE IF @intMode = 2	-- a Enteros para ABAJO ( Authogar ) en Financiacion de 3ros
		BEGIN
			RETURN  Floor(@decNumber + 0.03)  -- Los 0.03 es portque a veces tiraba para abajo por unos centavos lo que no debe pasar.  SEGUIRLO DE CERCA !!!
		END
	ELSE IF @intMode = 3	-- Redondea para arriba SIEMPRE a ENTEROS
		BEGIN

			IF ( @decNumber - FLOOR(@decNumber) ) > 0.5
				BEGIN
					RETURN CEILING(@decNumber)
				END
			ELSE
				BEGIN
					RETURN FLOOR(@decNumber)
				END

		END
	RETURN @decNumber

END

GO




CREATE FUNCTION [dbo].[fnRoundWebSitePrices]
(
	@decNumber	AS DECIMAL(25,4),
	@intMode	AS INT
)
RETURNS DECIMAL(25,4)
AS
BEGIN

	IF		@intMode = 0	-- Sin Redondear
		BEGIN
			RETURN @decNumber
		END
	ELSE IF @intMode = 1	-- Redondear a Precio Final ENTERO
		BEGIN
			RETURN  CEILING(@decNumber)
		END
	ELSE IF @intMode = 2	-- Redondear a Precio Final COMERCIAL
		BEGIN

			RETURN (ROUND(@decNumber,-1)-1)

		END
	ELSE IF @intMode = 3	-- Redondear a Precio Final COMERCIAL  ( NO se usa ahora !!! )
		BEGIN

			RETURN (ROUND(@decNumber,-1)-1)

		END
	RETURN @decNumber

END

GO





-- =============================================
-- Author:		MOS
-- Create date: 04-2011
-- Description:	Obtiene color de un pedido en funcion del stock
--  1- tiene stock potencial
--  2- tiene stock fisico
--  3- No tiene stock fisico de algun item
-- =============================================
CREATE FUNCTION [dbo].[fnSaleOrderGetStockStatus]
(
		@intCompId AS INT,
		@intBraId AS INT,
		@intSOHId AS INT
)
RETURNS CHAR(1)
AS
BEGIN

	DECLARE @bitWithFisicalStock	AS BIT
	DECLARE @bitWithPotentialStock	AS BIT
	DECLARE @intStatus				AS INT

	SET  @bitWithFisicalStock	= 'True'
	SET	 @bitWithPotentialStock = 'True'

	SELECT	@bitWithPotentialStock =	CASE
											WHEN @bitWithPotentialStock = 'true' and dbo.fnGetAStock( @intCompId,tsod.stor_id,tsod.item_id,tsod.sod_priority) < 0 THEN 'False'
											ELSE @bitWithPotentialStock
										END,
			@bitWithFisicalStock =		CASE
											WHEN @bitWithFisicalStock = 'true' and dbo.fnGetStock(  @intCompId,tsod.stor_id,tsod.item_id ) < tsod.sod_qty /* MOS 06-2022 para que si NO tiene fisico lo ponga en ROJO 0*/ THEN 'False'
											ELSE @bitWithFisicalStock
										END

		FROM tbSaleOrderDetail tsod				WITH (NOLOCK)
		--INNER JOIN tbItemStorage tis			WITH (NOLOCK)
		--	ON		tis.comp_id = tsod.comp_id
		--		AND tis.item_id = tsod.item_id
		--		AND tis.stor_id = tsod.stor_id
		WHERE	tsod.comp_id	= @intCompId
			AND tsod.bra_id		= @intBraId
			AND tsod.soh_id		= @intSOHId
			AND not tsod.item_id IS NULL

	SET @intStatus = '1'
	IF @bitWithFisicalStock = 'False'
		BEGIN
			set @intStatus = '3'
		END
	ELSE
		BEGIN
			IF @bitWithPotentialStock = 'False'
				BEGIN
					SET @intStatus = '2'
				END
		END

	RETURN @intStatus

END


GO





-- =============================================
-- Author:		MOS
-- Create date: 04-2011
-- Description:	Obtiene color de un pedido en funcion del stock
--  1- tiene stock potencial
--  2- tiene stock fisico
--  3- No tiene stock fisico de algun item
-- por ITEM
-- =============================================
CREATE FUNCTION [dbo].[fnSaleOrderGetStockStatus_Item]
(
		@intCompId AS INT,
		@intBraId AS INT,
		@intSOHId AS INT,
		@intItemId AS INT
)
RETURNS CHAR(1)
AS
BEGIN

	DECLARE @bitWithFisicalStock	AS BIT
	DECLARE @bitWithPotentialStock	AS BIT
	DECLARE @intStatus				AS INT

	SET  @bitWithFisicalStock	= 'True'
	SET	 @bitWithPotentialStock = 'True'

	SELECT	@bitWithPotentialStock =	CASE
											WHEN @bitWithPotentialStock = 'true' and dbo.fnGetAStock( @intCompId,tis.stor_id,tsod.item_id,tsod.sod_priority) < 0 THEN 'False'
											ELSE @bitWithPotentialStock
										END,
			@bitWithFisicalStock =		CASE
											WHEN @bitWithFisicalStock = 'true' and dbo.fnGetStock(  @intCompId,tis.stor_id,tsod.item_id ) < 0 THEN 'False'
											ELSE @bitWithFisicalStock
										END

		FROM tbSaleOrderDetail tsod			WITH (NOLOCK)
		INNER JOIN tbItemStorage tis		WITH (NOLOCK)
			ON		tis.comp_id = tsod.comp_id
				AND tis.item_id = tsod.item_id
				AND tis.stor_id = tsod.stor_id
		WHERE	tsod.comp_id	= @intCompId
			AND tsod.bra_id		= @intBraId
			AND tsod.soh_id		= @intSOHId
			AND tsod.item_id    = @intItemId

	SET @intStatus = '1'
	IF @bitWithFisicalStock = 'False'
		BEGIN
			set @intStatus = '3'
		END
	ELSE
		BEGIN
			IF @bitWithPotentialStock = 'False'
				BEGIN
					SET @intStatus = '2'
				END
		END

	RETURN @intStatus

END


GO





-- =============================================
-- Author:		MOS
-- Create date: 02-2013
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION fnSaleOrderHistory_GetUserName
(
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT
)
RETURNS NVARCHAR(30)
AS
BEGIN

	IF @comp_id IS NULL RETURN ''

	DECLARE @userId AS INT

	SELECT TOP 1 @userId	= tsohh.[user_id]
		FROM tbSaleOrderHeaderHistory tsohh
	WHERE	tsohh.comp_id	= @comp_id	AND
			tsohh.bra_id	= @bra_id	AND
			tsohh.soh_id	= @soh_id
		ORDER BY tsohh.sohh_id DESC

	IF @userId IS NULL RETURN ''

	RETURN	(SELECT tu.user_lastname + ',' + tu.user_firstname
				FROM tbUser tu
	      		WHERE tu.[user_id] = @userId
			)
END
GO





-- =============================================
-- Author:		GA
-- Create date: 27-12-2018
-- Description:	Retorna un decimal en string
-- con 2 ceros a la derecha como decimales
-- Ejemplo:
-- 1222.33  quedaria a 15->  000000000122233
-- =============================================

CREATE FUNCTION [dbo].[fnSIAP_ConvertDate2StringAAAAMM]
(
	@datValue			AS DATETIME,
	@strSeparator		AS CHAR(1)
)
RETURNS NVARCHAR(100)
AS
BEGIN

	IF @strSeparator IS NULL SET @strSeparator = ''

	SET @strSeparator = dbo.fnStrAllTrim(@strSeparator)


	DECLARE @strReturnValue AS NVARCHAR(15)

	SET @strReturnValue =	dbo.fnStrPADL(convert(Varchar(4),datepart(Year	,@datValue)),4,'0')		+ @strSeparator +
							dbo.fnStrPADL(convert(Varchar(2),datepart(Month	,@datValue)),2,'0')		+ @strSeparator

	RETURN dbo.fnStrAllTrim(REPLACE( @strReturnValue,' ',''))

END
GO





