-- =============================================
-- Author:		MOS
-- Create date: 01-2014
-- Description:	Retorna un decimal en string
-- con 2 ceros a la derecha como decimales
-- Ejemplo:
-- 1222.33  quedaria a 15->  000000000122233
-- =============================================
CREATE FUNCTION [dbo].[fnSIAP_ConvertDecimal2String]
(
	@decValue			AS DECIMAL(19,6),
	@intLarge			AS INT
)
RETURNS NVARCHAR(100)
AS
BEGIN

	DECLARE @intSign AS INT
	SET @intSign =	CASE
						WHEN @decValue < 0 THEN -1
						ELSE					 1
					END

	SET @decValue = ABS(@decValue)


	IF @decValue IS NULL SET @decValue = 0
	SET @decValue = ROUND(@decValue,2)

	DECLARE @strReturnValue AS NVARCHAR(100)
	SET		@strReturnValue = CONVERT(NVARCHAR,convert(decimal(19,2),@decValue))

	SET @strReturnValue = REPLACE(@strReturnValue,',','')
	SET @strReturnValue = REPLACE(@strReturnValue,'.','')
	SET @strReturnValue = dbo.fnStrPADL(@strReturnValue, @intLarge - 1, '0')

	-- Pone el Signo a la izquierda
	IF @intSign = 1
		BEGIN
			SET @strReturnValue = '0' + @strReturnValue
		END
	ELSE
		BEGIN
			SET @strReturnValue = '-' + @strReturnValue
		END

	RETURN dbo.fnStrAllTrim( @strReturnValue )

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 01-2014
