CREATE FUNCTION [dbo].[fnSIAP_ConvertString2FIXLength2]
(
	@strValue			AS NVARCHAR(1000),
	@intLength			AS INT,
	@strChar			AS CHAR
)
RETURNS NVARCHAR(1000)
AS
BEGIN

	IF @strValue IS NULL  SET @strValue = ''

	SET @strValue = dbo.fnStrAllTrim(@strValue)
	SET @strValue = SUBSTRING(@strValue,1,@intLength)
	SET @strValue = dbo.fnStrAllTrim(@strValue)
	SET @strValue = dbo.fnStrPADL(@strValue,@intLength,@strChar)


	RETURN @strValue

END
GO






      CREATE FUNCTION [dbo].[fnSplitPosition]
      (
            @Expression VARCHAR(max)
          , @Delimiter  VARCHAR(max)
          , @INDEX      INT
      )
      RETURNS VARCHAR(max)	WITH SCHEMABINDING
      AS
      BEGIN
          DECLARE @RETURN  VARCHAR(max)
          DECLARE @Pos     INT
          DECLARE @PrevPos INT
          DECLARE @I       INT

          -- SELECT dbo.fnSplit('4.55.108.2','.', 2)

          IF @Expression IS NULL OR @Delimiter IS NULL OR DATALENGTH(@Delimiter) = 0 OR @INDEX < 1

              SET @RETURN = NULL

          ELSE IF @INDEX = 1 BEGIN

              SET @Pos = CHARINDEX(@Delimiter, @Expression, 1)

              IF @Pos > 0
				BEGIN
					SET @RETURN = LEFT(@Expression, @Pos - 1)
				END
			  ELSE
			  	BEGIN
			  		SET @RETURN = @Expression
			  	END


          END ELSE BEGIN

              SET @Pos = 0

              SET @I = 0


              WHILE (@Pos > 0 AND @I < @INDEX) OR @I = 0 BEGIN
                  SET @PrevPos = @Pos
                  SET @Pos = CHARINDEX(@Delimiter, @Expression, @Pos + DATALENGTH(@Delimiter))

                  SET @I = @I + 1
              END


              IF @Pos = 0 AND @I = @INDEX
                  SET @RETURN = SUBSTRING(@Expression, @PrevPos + DATALENGTH(@Delimiter), DATALENGTH(@Expression))
              ELSE IF @Pos = 0 AND @I <> @INDEX
                  SET @RETURN = NULL
              ELSE
                  SET @RETURN = SUBSTRING(@Expression, @PrevPos + DATALENGTH(@Delimiter), @Pos - @PrevPos - DATALENGTH(@Delimiter))
          END

          RETURN @RETURN

      END
GO





CREATE FUNCTION [dbo].[fnSplitTable](@String varchar(8000), @Delimiter char(2))
returns @temptable TABLE (items varchar(8000))
as
begin
    declare @idx				int
    declare @slice				varchar(8000)
    DECLARE @DelimiterLenght	INT

    SET @DelimiterLenght = LEN(RTRIM(LTRIM(@Delimiter))) - 1 --longitud del delimitador - 1

    select @idx = 1
        if len(@String)<1 or @String is null  return

    while @idx!= 0
    begin
        set @idx = charindex(ltrim(rtrim(@Delimiter)),@String)
        if @idx!=0
            set @slice = left(@String,@idx - 1)
        else
            set @slice = @String

        if(len(@slice)>0)
            insert into @temptable(Items) values(@slice)

        set @String = right(@String,len(@String) - @idx - @DelimiterLenght)
        if len(@String) = 0 break
    end
return
end
GO





CREATE FUNCTION [dbo].[fnSplitTableWithSpaces](@String varchar(8000), @Delimiter char(1))
returns @temptable TABLE (items varchar(8000))
as
begin
    declare @idx				int
    declare @slice				varchar(8000)
    DECLARE @DelimiterLenght	INT

    SET @DelimiterLenght = 0 --LEN(RTRIM(LTRIM(@Delimiter))) - 1 --longitud del delimitador - 1

    select @idx = 1
    if len(@String)<1 or @String is null  return

    SET @String = LTRIM(RTRIM(@String))

    while @idx!= 0
    begin
        set @idx = charindex(@Delimiter,@String)
        if @idx!=0
            set @slice = left(@String,@idx - 1)
        else
            set @slice = @String

        if(len(@slice)>0)
            insert into @temptable(Items) values(@slice)

        set @String = right(@String,len(@String) - @idx - @DelimiterLenght)
        if len(@String) = 0 break
    end
return
end
GO






-- ADDROMANNUMBERS() User-Defined Function is written just FYA
-- Returns the result of addition, subtraction, multiplication or division of two Roman numbers
-- Author:  Igor Nikiforov,  Montreal,  EMail: udfs@sympatico.ca ,  25 April 2005 or XXV April MMV :-)
-- ADDROMANNUMBERS(@tcRomanNumber1, @tcRomanNumber2, @tcOperator) Return Values varchar(75)
-- Parameters @tcRomanNumber1 varchar(15) Roman number
-- @tcRomanNumber2 varchar(15) Roman number, @tcOperator char(1) operator
-- Example
-- select dbo.ADDROMANNUMBERS('I','I',default)                       -- Displays II
-- select dbo.ADDROMANNUMBERS('MMMDCCCLXXXVIII','MDCCCLXXXVIII','-') -- Displays MM
-- select dbo.ADDROMANNUMBERS('DCCCLXXXVIII','VIII',default)         -- Displays DCCCXCVI
-- select dbo.ADDROMANNUMBERS('DCCCLXXXVIII','VIII','*')             -- Displays Out of range, must be between 1 and 3999
-- select dbo.ADDROMANNUMBERS('MMMDCCCLXXXVIII','II','/')            -- Displays MCMXLIV
-- See also ROMANTOARAB(), ARABTOROMAN()
CREATE function fnStrADDROMANNUMBERS(@tcRomanNumber1 varchar(15), @tcRomanNumber2 varchar(15), @tcOperator char(1)='+' )
returns varchar(75)
   begin
      declare @lcResult varchar(75)
      if @tcOperator in ('+','-','*','/')
        begin
          declare @lnN1 int, @lnN2 int
          select @lnN1 = dbo.ROMANTOARAB(@tcRomanNumber1),  @lnN2 = dbo.ROMANTOARAB(@tcRomanNumber2)
          if @lnN1 < 0
            set @lcResult = 'Wrong first roman number'
          else
            if @lnN2 < 0
              set @lcResult = 'Wrong second roman number'
            else
              begin
                select @lcResult =
                case @tcOperator
                  when '+' then dbo.ARABTOROMAN(@lnN1 + @lnN2)
                  when '-' then dbo.ARABTOROMAN(@lnN1 - @lnN2)
                  when '*' then dbo.ARABTOROMAN(@lnN1 * @lnN2)
                  when '/' then dbo.ARABTOROMAN(@lnN1 / @lnN2)
                end
              end
        end
      else
        set @lcResult = 'Wrong third parameter, must be +,-,*,/'

    return @lcResult
  end

GO





