CREATE FUNCTION [dbo].[fnSTRContactJoin]
(
	-- Add the parameters for the function here
	@strContact1 AS NVARCHAR(2000),
	@strContact2 AS NVARCHAR(2000),
	@strContact3 AS NVARCHAR(2000),
	@strContact4 AS NVARCHAR(2000),
	@strContact5 AS NVARCHAR(2000)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN

	DECLARE @strContacts AS NVARCHAR(MAX)
	SET @strContacts = ''


	IF @strContact1 IS NULL
		BEGIN
			SET @strContact1 = ''
		END

	IF @strContact2 IS NULL
		BEGIN
			SET @strContact2 = ''
		END

	IF @strContact3 IS NULL
		BEGIN
			SET @strContact3 = ''
		END

	IF @strContact4 IS NULL
		BEGIN
			SET @strContact4 = ''
		END

	IF @strContact5 IS NULL
		BEGIN
			SET @strContact5 = ''
		END


	IF @strContact1 IS NOT NULL AND @strContact1 <> ''
		BEGIN
			SET @strContacts = @strContacts + dbo.fnStrAllTrim( @strContact1 )
		END

	IF @strContact2 IS NOT NULL AND @strContact2 <> ''
		BEGIN
			IF @strContacts <> ''
				BEGIN
					SET @strContacts = @strContacts + ', '
				END
			SET @strContacts = @strContacts + dbo.fnStrAllTrim( @strContact2 )
		END

	IF @strContact3 IS NOT NULL AND @strContact3 <> ''
		BEGIN
			IF @strContacts <> ''
				BEGIN
					SET @strContacts = @strContacts + ', '
				END
			SET @strContacts = @strContacts + dbo.fnStrAllTrim( @strContact3 )
		END

	IF @strContact4 IS NOT NULL AND @strContact4 <> ''
		BEGIN
			IF @strContacts <> ''
				BEGIN
					SET @strContacts = @strContacts + ', '
				END
			SET @strContacts = @strContacts + dbo.fnStrAllTrim( @strContact4 )
		END

	IF @strContact5 IS NOT NULL AND @strContact5 <> ''
		BEGIN
			IF @strContacts <> ''
				BEGIN
					SET @strContacts = @strContacts + ', '
				END
			SET @strContacts = @strContacts + dbo.fnStrAllTrim( @strContact5 )
		END

	RETURN @strContacts

END
GO



-- Elimina duplicados de una lista enviada con un delimitador determinado
-- Se usa por ejemplo para eliminar emails duplicados de una lista.
CREATE FUNCTION [dbo].[fnSTRDistinctList]
(
@strList4DeleteDuplicates		VARCHAR(MAX),
@strDelimiter					CHAR,
@strListAdditional4Delete AS	VARCHAR(MAX)
)
RETURNS	VARCHAR(MAX)
AS
BEGIN

	DECLARE @strReturn	AS NVARCHAR(MAX)
	DECLARE @ParsedList TABLE
								(
								Item VARCHAR(MAX)
								)

	DECLARE @strList4DeleteDuplicates1 VARCHAR(MAX),
			@Pos INT,
			@rList VARCHAR(MAX)

	SET @strList4DeleteDuplicates = LTRIM(RTRIM(@strList4DeleteDuplicates)) + @strDelimiter
	SET @pos = CHARINDEX(@strDelimiter, @strList4DeleteDuplicates, 1)
	WHILE @pos > 0
		BEGIN
			SET @strList4DeleteDuplicates1	= LTRIM(RTRIM(LEFT(@strList4DeleteDuplicates, @pos - 1)))
			IF  @strList4DeleteDuplicates1 <> ''	INSERT	INTO @ParsedList
														VALUES (CAST(@strList4DeleteDuplicates1 AS VARCHAR(MAX)))
			SET @strList4DeleteDuplicates	= SUBSTRING(@strList4DeleteDuplicates, @pos+1, LEN(@strList4DeleteDuplicates))
			SET @pos						= CHARINDEX(@strDelimiter, @strList4DeleteDuplicates, 1)
		END

	-- Borrar las que no me interesan
	DELETE FROM @ParsedList
		FROM @ParsedList pl
		WHERE pl.Item IN (SELECT * FROM fnSplitTable(@strListAdditional4Delete, @strDelimiter) fst)

	SELECT @rlist	= COALESCE(@rlist+@strDelimiter,'') + item
		FROM (	SELECT DISTINCT Item
					FROM @ParsedList) t

	SET @strReturn	= dbo.fnStrAllTrim(IsNull(@rlist,'')) + @strDelimiter
	IF @strReturn	= @strDelimiter SET @strReturn = ''
	SET @strReturn  = dbo.fnStrAllTrim(@strReturn)
	RETURN @strReturn

END
GO




-- ----------------
-- MOS
-- Sirve para intentar arrglar mierdas que cargan los clientes
-- ----------------
CREATE FUNCTION [dbo].[fnstrEmailCheck]
(
	@strEmail NVARCHAR(4000)
)


RETURNS NVARCHAR(4000)
AS

BEGIN

	DECLARE @intCounter AS INT

	IF @strEmail IS NULL SET @strEmail = ''
	SET @strEMail = REPLACE(@strEMail, ',',';')
	SET @strEMail = REPLACE(@strEMail, '(','')
	SET @strEMail = REPLACE(@strEMail, ')','')
	SET @strEMail = dbo.fnStrAllTrim(@strEmail)

	SET @intCounter = 0

	WHILE @intCounter < 15
		BEGIN
			SET @strEMail = REPLACE(@strEMail, ';;',';')
			SET @strEMail = REPLACE(@strEMail, '; ',';')
			SET @strEMail = REPLACE(@strEMail, ' ;',';')
			SET @strEMail = REPLACE(@strEMail, ' ','')
			SET @intCounter = @intCounter + 1
		END



	IF CHARINDEX(';',@strEmail) = 1
		BEGIN
			SET @strEmail = SUBSTRING(@strEmail,2, LEN(@strEmail))
		END

	SET @strEMail = dbo.fnStrAllTrim(@strEmail)

	WHILE @intCounter < 15
		BEGIN
			SET @strEMail = REPLACE(@strEMail, ';;',';')
			SET @strEMail = REPLACE(@strEMail, '; ',';')
			SET @strEMail = REPLACE(@strEMail, ' ;',';')
			SET @strEMail = REPLACE(@strEMail, ' ','')
			SET @intCounter = @intCounter + 1
		END

	SET @strEMail = dbo.fnStrAllTrim(@strEmail)

	RETURN @strEmail

END
GO





