CREATE FUNCTION fnSysExportData_getARCIBA20
(
	@decTM_subtotal AS DECIMAL(19,4),
	@decPercentage  AS DECIMAL(10,2),
	@decSavedTax    AS DECIMAL(19,2)	--100.79

)
RETURNS DECIMAL(19,2)
AS
BEGIN

	DECLARE @decAux AS DECIMAL(19,4)
	SET @decAux = round(@decTM_subtotal * @decPercentage / 100,2) --100.78
	--SET @decAux = @decSavedTax - @decAux

	RETURN @decAux

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 07-2009
-- Description:	retorna el Codigo de los SP
--
--				--BeginSPSqlCode--
--        y     --EndSPSqlCode--
-- =============================================
CREATE FUNCTION [dbo].[fnSystem_GetScriptFromBegin]
(
	@SPName AS VARCHAR(2000)			-- Nombre del ControlPanel Stored Procedure
)
RETURNS VARCHAR(MAX)
AS
BEGIN

	DECLARE @cTextoOutput AS VARCHAR(MAX)
	DECLARE @intFrom	  AS INT
	DECLARE @intTo		  AS INT



	Select @cTextoOutput = text from syscomments where id=object_id(@SPName)
	SELECT @intFrom = CHARINDEX('--BeginSPSqlCode--',@cTextoOutput,0) + 29
	SELECT @intTo   = CHARINDEX('--EndSPSqlCode--',@cTextoOutput,0)

	SELECT @cTextoOutput = RTrim(LTrim(SUBSTRING(@cTextoOutput,@intFrom,@intTo - @intFrom)))

	RETURN @cTextoOutput

END
GO




-- =============================================
-- Author:		MOS
-- Create date: 11-2013
-- Description:	Reemplaza los chr 10 por BR si
--  se da cuenta que no es un texto html
-- =============================================
CREATE FUNCTION [dbo].[fnSystem_sendEMail_SetBody2HTML]
(
	@strBody AS NVARCHAR(MAX)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN


	SET @strBody = ISNULL(@strBody,'')

	IF not @strBody LIKE '%<%'
		BEGIN
			SET @strBody = dbo.fnStrAllTrim(@strBody)
			SET @strBody = REPLACE(@strBody,CHAR(10),'<BR>')
		END

	RETURN @strBody

END
GO





-- =============================================
