-- Create date: <Create Date, ,> 01-2013
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnSysWordsNew_GetText]
(
	-- Add the parameters for the function here
	@lang_id		INT,
	@country_id		INT,
	@wordsi_id		INT
)
RETURNS NVARCHAR(4000)
AS
BEGIN

	DECLARE @intWordsi_id AS INT

	SELECT @intWordsi_id = tswnrbc.wordsi_idByCountry
		FROM tbSysWordsNewReplaceByCountry tswnrbc				WITH (NOLOCK)
	WHERE	tswnrbc.wordsi_id	= @wordsi_id AND
			tswnrbc.country_id	= @country_id

	IF @intWordsi_id IS NULL
		BEGIN
			SET @intWordsi_id = @wordsi_id
		END


	RETURN (	SELECT tswn.word_desc
					FROM tbSysWordsNew tswn						WITH (NOLOCK)
	        		WHERE	tswn.lang_id	= @lang_id AND
	        				tswn.wordsi_id	= @intWordsi_id
			)


END
GO





-- =============================================
-- Author:		MOS
-- Create date: 04-2009
-- Description:	Retorna la Percepcion o
--				retencion para un CUIT
-- =============================================
CREATE FUNCTION [dbo].[fnTaxARBA]
(
	@strCuit AS VARCHAR(100),
	@bitRetPercepcionOrRetencion AS BIT
)
RETURNS DECIMAL(19,4)
AS
BEGIN

	DECLARE @Percentaje AS DECIMAL(19,4)

	IF @bitRetPercepcionOrRetencion = 'true'
		 	SELECT @Percentaje = cast( replace(tta.arba_percepcion,',','.' ) AS DECIMAL(19,4))
				FROM tbsysTaxARBA tta					WITH (NOLOCK)
		 		WHERE tta.arba_cuit = @strCuit
	ELSE
		 	SELECT @Percentaje = cast( replace(tta.arba_retencion,',','.' ) AS DECIMAL(19,4))
				FROM tbsysTaxARBA tta					WITH (NOLOCK)
		 		WHERE tta.arba_cuit = @strCuit


  RETURN @Percentaje

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 11-2008
-- Description:	Retorna solo el total de Impuestos Internos
--				de un renglon de un comprobante
-- =============================================
CREATE FUNCTION [dbo].[fnTaxMovements_InternalTaxOfItemTransaction]
(
	@comp_id		as int,
	@bra_id			as int,
	@ct_transaction as int,
	@it_transaction as int
)
RETURNS decimal(19,5)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @itemInternalTax as decimal(19,5)

	-- Add the T-SQL statements to compute the return value here
	SELECT @itemInternalTax = sum(tm_total)
		From dbo.tbTaxMovements							TXMO					WITH (NOLOCK)

		Join dbo.tbTaxName								TXNAME					WITH (NOLOCK)
			On	TXNAME.comp_id			=	TXMO.comp_id
			and	TXNAME.tax_id			=	TXMO.tax_id

		Join dbo.vwsysTaxClassInternalTax_ALL			STC						WITH (NOLOCK)
			On	STC.tax_class			=	TXNAME.tax_class


		Where
				TXMO.comp_id			=   @comp_id
			and TXMO.bra_id				=	@bra_id
			and TXMO.ct_transaction		=	@ct_transaction
			and TXMO.it_transaction		=	@it_transaction



	-- Return the result of the function
	RETURN IsNull(@itemInternalTax,0)

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 11-2008
-- Description:	Retorna solo el total de IInt
--				de un renglon de un comprobante
-- =============================================
CREATE FUNCTION [dbo].[fnTaxMovements_InternalTaxPercentageOfItemTransaction]
(
	@comp_id		as int,
	@bra_id			as int,
	@ct_transaction as int,
	@it_transaction as int
)
RETURNS decimal(19,5)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @itemPercentage as decimal(19,5)

	-- Add the T-SQL statements to compute the return value here
	SELECT Top 1 @itemPercentage = percentaje
		From dbo.tbTaxMovements							TXMO				WITH (NOLOCK)

		Join dbo.tbTaxName							TXNAME					WITH (NOLOCK)
			On	TXNAME.comp_id			=	TXMO.comp_id
			and	TXNAME.tax_id			=	TXMO.tax_id

		Join dbo.vwsysTaxClassInternalTax_ALL 	STC							WITH (NOLOCK)
			On	STC.tax_class			=	TXNAME.tax_class


		Where
				TXMO.comp_id			=   @comp_id
			and TXMO.bra_id				=	@bra_id
			and TXMO.ct_transaction		=	@ct_transaction
			and TXMO.it_transaction		=	@it_transaction



	-- Return the result of the function
	RETURN IsNull(@itemPercentage,0)

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 11-2008
-- Description:	Retorna solo el total de IVA
--				de un renglon de un comprobante
-- =============================================
create FUNCTION [dbo].[fnTaxMovements_IvaDescriptionOfItemTransaction]
(
	@comp_id		as int,
	@bra_id			as int,
	@ct_transaction as int,
	@it_transaction as int
)
RETURNS NVARCHAR(250)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @tax_desc as NVARCHAR(250)

	-- Add the T-SQL statements to compute the return value here
	SELECT Top 1 @tax_desc = TXNAME.tax_desc
		From dbo.tbTaxMovements							TXMO			WITH (NOLOCK)

		Join dbo.tbTaxName							TXNAME				WITH (NOLOCK)
			On	TXNAME.comp_id			=	TXMO.comp_id
			and	TXNAME.tax_id			=	TXMO.tax_id

		Join dbo.vwsysTaxClassIVA_Taxes			STC						WITH (NOLOCK)
			On	STC.tax_class			=	TXNAME.tax_class


		Where
				TXMO.comp_id			=   @comp_id
			and TXMO.bra_id				=	@bra_id
			and TXMO.ct_transaction		=	@ct_transaction
			and TXMO.it_transaction		=	@it_transaction



	-- Return the result of the function
	RETURN IsNull(@tax_desc,'')

END
GO





-- =============================================
-- Author:		MOS
-- Create date: 11-2008
-- Description:	Retorna solo el total de IVA
--				de un  comprobante
-- =============================================
CREATE FUNCTION [dbo].[fnTaxMovements_IVAOfCommercialTransaction]
(
	@comp_id		as int,
	@bra_id			as int,
	@ct_transaction as int
)
RETURNS decimal(19,5)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @decIVATax as decimal(19,5)

	-- Add the T-SQL statements to compute the return value here
	SELECT @decIVATax = sum(tm_total)
		From dbo.tbTaxMovements							TXMO				WITH (NOLOCK)

		Join dbo.tbTaxName								TXNAME				WITH (NOLOCK)
			On	TXNAME.comp_id			=	TXMO.comp_id
			and	TXNAME.tax_id			=	TXMO.tax_id

		Join dbo.vwsysTaxClassIVA_Taxes 	STC								WITH (NOLOCK)
			On	STC.tax_class			=	TXNAME.tax_class


		Where
				TXMO.comp_id			=   @comp_id
			and TXMO.bra_id				=	@bra_id
			and TXMO.ct_transaction		=	@ct_transaction




	-- Return the result of the function
	RETURN IsNull(@decIVATax,0)

END
GO





