-- =============================================
-- Author:		MOS
-- Create date: 04-2011
-- Description:	Retorna el IVA de un item
--
-- =============================================
CREATE FUNCTION [dbo].[fntbTempItemStock_getIVA]
(
	@comp_id			as int,
	@bra_id				as int,
	@tis_id				as INT,
	@tax_id				AS INT,
	@decExchange		AS DECIMAL(19,6),
	@decQTY				AS DECIMAL(19,6)
)
RETURNS DECIMAL(23,6)
AS
BEGIN

	DECLARE @decReturn AS DECIMAL(23,6)
	DECLARE @decTax		AS DECIMAL(19,2)
	DECLARE @bitPlusIva AS BIT
	SELECT @bitPlusIva = isNull(tb.bra_SaleOrderPricePlusTax,'False')
		FROM dbo.tbBranch tb			WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id



		SET @decReturn =
				ISNULL((SELECT SUM(tt.tm_amount)
						FROM dbo.tbtmpTax tt				WITH (NOLOCK)
						INNER JOIN dbo.tbTaxName ttn		WITH (NOLOCK)
							ON		ttn.comp_id = @comp_id
								AND ttn.tax_id	= IsNull(tt.tax_id,@tax_id)
			      		WHERE	tt.comp_id		= @comp_id
			      			AND tt.tis_id		= @tis_id
			      			AND ttn.tax_class	= 1
			      ),0)


	SET @decReturn = @decReturn / dbo.fnNoZDiv( @decExchange )
	SET @decReturn = @decReturn / dbo.fnNoZDiv( @decQTY )
	RETURN @decReturn

END
GO





-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fnTempItemStock_getQtyBySOD]
(
	-- Add the parameters for the function here
	@comp_id	INT,
	@bra_id		INT,
	@soh_id		INT,
	@sod_id		INT,
	@tis_qty	DECIMAL(19,4),
	@sod_qty	DECIMAL(19,4)
)
RETURNS DECIMAL(19,4)	WITH SCHEMABINDING

AS
BEGIN

	DECLARE @decTempItemStockTotalOdSOD AS DECIMAL(19,4)
	SELECT  @decTempItemStockTotalOdSOD = SUM(ttis.tis_qty)
		FROM dbo.tbTempItemStock ttis		WITH (NOLOCK)
		WHERE	ttis.comp_id	= @comp_id
			AND ttis.bra_id		= @bra_id
			AND ttis.soh_id		= @soh_id
			AND ttis.sod_id		= @sod_id


	IF @decTempItemStockTotalOdSOD = @sod_qty RETURN @tis_qty
	IF @decTempItemStockTotalOdSOD < @sod_qty RETURN @sod_qty
	RETURN @tis_qty --@decTempItemStockTotalOdSOD

END
GO






-- ATENCION!!!!
-- NO USAR MAS, se usa fnUserNeedAuthorizationByProfile
-- Decide el Insert si corresponde o no corresponde
-- =============================================
-- Author:		MOS
-- Create date: 10-2008
-- Retorna si hay que autorizar o no segun
-- el usuario que llama.-
-- =============================================
CREATE FUNCTION [dbo].[fnUserNeedAuthorization]
(
	@comp_id		as integer,
	@bra_id			as integer,
	@user_id		as integer,
	@aut_id			as integer
)

RETURNS bit AS

BEGIN

	If not Exists(

		Select 1
			From dbo.tbProfileAuthorization					PA		WITH (NOLOCK)

			Inner Join dbo.tbUserCompanyProfile				UCP		WITH (NOLOCK)
				On		UCP.comp_id	= PA.comp_id
					and	UCP.prof_id = PA.prof_id
			--INNER JOIN tbuser tu									WITH (NOLOCK)
			--	ON tu.[user_id] = @user_id

		Where
				PA.comp_id  = @comp_id
			and PA.aut_id	= @aut_id
			and UCP.bra_id	= @bra_id
			and UCP.user_Id = @user_id
			--AND tu.user_mustAuthorizateOwnAuthorizations = 'False'
				 )

	Begin
		Return 'True'
	End

	Return 'False'

END

GO






-- ATENCION!!!!
-- NO USAR MAS
-- Decide el Insert si corresponde o no corresponde
-- =============================================
-- Author:		MOS
-- Create date: 10-2013
-- Retorna si hay que autorizar o no segun
-- el usuario que llama.-
-- =============================================
CREATE FUNCTION [dbo].[fnUserNeedAuthorizationByProfile]
(
	@comp_id		as int,
	@bra_id			as int,
	@user_id		as int,
	@aut_id			as int,
	@prof_id		AS INT
)

RETURNS bit AS

BEGIN


	IF EXISTS(
				-- Si con que tenga algun perfil asignado que permita autorizar esa clave en la sucursal alcanza
				SELECT 1
					FROM tbUser tu	WITH (NOLOCK)
					WHERE	tu.[user_id]											 = @user_id AND
							ISNULL(tu.user_authorization4AllProfileInBranch,'False') = 'True'
			)
		BEGIN

			If not Exists(

				Select 1
					From dbo.tbProfileAuthorization					PA		WITH (NOLOCK)

					Inner Join dbo.tbUserCompanyProfile				UCP		WITH (NOLOCK)
						On		UCP.comp_id	= PA.comp_id
							and	UCP.prof_id = PA.prof_id

				Where
						PA.comp_id  = @comp_id
					and PA.aut_id	= @aut_id
					and UCP.bra_id	= @bra_id
					and UCP.user_Id = @user_id
						 )

			Begin
				Return 'True'
			End

		END
	ELSE
		BEGIN

			If  NOT Exists(
						-- O si si o si debe poder autorizarla con su perfil actual en la sucursal actual
						Select 1
							From dbo.tbProfileAuthorization					PA		WITH (NOLOCK)
							Where
									PA.comp_id  = @comp_id	AND
									PA.aut_id	= @aut_id	AND
									pa.prof_id  = @prof_id
					)

			Begin
				Return 'True'
			End

		END

	Return 'False'


END

GO





