create FUNCTION [dbo].[PadRightString]
(
	@strString varchar(50),
	@PadWith char(1),
	@PadLength int
)

RETURNS varchar(50) AS

BEGIN

declare @strPad_String varchar(50)

Set @strString = RTrim(LTrim(Cast(@strString as varchar)))

SELECT @strPad_String = @strString + ISNULL(REPLICATE(@PadWith, @PadLength - len(ISNULL(@strString ,0))), '')

RETURN @strPad_String

END

GO





