CREATE FUNCTION [dbo].[setOnlyTime] ( @newTime datetime )
RETURNS datetime
WITH EXECUTE AS CALLER
AS
BEGIN
RETURN (convert(datetime,'1753-01-01 '+convert(varchar,@newTime,108)))
END
GO






create FUNCTION [dbo].[udfMinimumDate] (
    @x DATETIME,
    @y DATETIME
) RETURNS DATETIME
AS
BEGIN
    DECLARE @z DATETIME

    IF @x <= @y
        SET @z = @x
    ELSE
        SET @z = @y

    RETURN(@z)
END
GO
