-- MOS  01-2011
-- Retorna el Nombre de la entidad relacionada a commercialTransactions.

CREATE VIEW [dbo].[vwAccountant_ctTransactionGetNames]
AS

SELECT	tct.comp_id,
		tct.bra_id,
		tct.ct_transaction,
		CASE
			WHEN not tct.cust_id IS NULL THEN  tc.cust_name + '->(' + Cast(tc.cust_id AS NVARCHAR)  + ')'
			WHEN not tct.supp_id IS NULL THEN  ts.supp_name + '->(' + Cast(ts.supp_id AS NVARCHAR)  + ')'
			WHEN not tct.ba_id   IS NULL THEN  tba.ba_desc  + '->(' + Cast(tba.ba_id  AS NVARCHAR)  + ')'
			ELSE ''
		END									[Name]
	FROM tbCommercialTransactions tct
	LEFT JOIN tbCustomer tc
		ON		tc.comp_id = tct.comp_id
			AND tc.cust_id = tct.cust_id
	LEFT JOIN tbSupplier ts
		ON		ts.comp_id = tct.comp_id
			and	ts.supp_id = tct.supp_id
	LEFT JOIN tbBankingAccounts tba
		ON		tba.comp_id = tct.comp_id
			AND tba.ba_id	= tct.ba_id

GO






