-- MOS
-- 10-2008
-- Union de tbBankingTransactionTypes (usuarios) + tbsysBankingTransactionTypes
CREATE VIEW [dbo].[vwBankingTransactionTypes]
AS

	Select	comp_id,
			btt_id,
			btt_desc,
			btt_isCredit,
			CASE
				WHEN btt_isCredit = 'TRUE' THEN 1
				ELSE -1
			END						[PlusOrMinus]
		From dbo.tbBankingTransactionTypes			WITH (NOLOCK)

	Union


	Select	null [comp_id],
			btt_id,
			btt_desc,
			btt_isCredit,
			CASE
				WHEN btt_isCredit = 'TRUE' THEN 1
				ELSE -1
			END						[PlusOrMinus]

		From dbo.tbsysBankingTransactionTypes		WITH (NOLOCK)


GO



CREATE VIEW [dbi].[vwbi_Branch]
AS
SELECT
			dbo.tbBranch.comp_id,
			dbo.tbBranch.bra_id,
			dbo.tbBranch.bra_desc,
			dbo.tbBranch.bra_MainDesc,
			dbo.tbBranch.country_id,
			dbo.tbAccountantGroup.ag_desc,
			dbo.tbBranch.bra_taxNumber

FROM        dbo.tbBranch															WITH (NOLOCK)

			LEFT JOIN dbo.tbAccountantGroup											WITH (NOLOCK)
			ON dbo.tbBranch.comp_id		= dbo.tbAccountantGroup.comp_id		AND
			   dbo.tbBranch.ag_id		= dbo.tbAccountantGroup.ag_id

GO




CREATE VIEW [dbi].[vwbi_commercialTransactions_Sales]
AS
SELECT

				tic.ct_date, tic.ct_transaction, tic.comp_id, tic.bra_id, dbo.tbDocumentsFile.df_desc, dbo.fnGetCommercialTransactionDescriptionNSB(tic.comp_id, 2, tic.ct_transaction) AS Comprob,
				tic.ct_kindOf, tic.ct_pointOfSale, tic.ct_docNumber,
                dbo.tbsysDocuments.sd_plusOrminus, tic.ct_taxDate, tic.ct_payDate, tic.ct_dfExchange, tic.cust_id,
                tic.user_id, dbo.tbUser.user_firstname + N'  ' + dbo.tbUser.user_lastname AS user_name, tic.ct_cd, tic.ct_subtotal, tic.ct_total,
                tic.ct_discount, tic.ct_adjust, tic.ct_taxes, tic.ct_ACurrencyExchange, tic.ct_ATotal, tic.ct_ABalance,
                tic.ct_ACurrency, tic.sm_id, dbo.tbSalesman.sm_name, tic.dl_id, dbo.tbDelivery.dl_name, tic.st_id, dbo.tbSalesTerms.st_desc,
                tic.sd_id, tic.country_id, dbo.tbsysCountry.country_desc, tic.state_id, ts.state_desc, tic.disc_id,
                dbo.tbDiscount.disc_desc, tic.ct_discountPlanCoeficient, tic.ct_soh_id


FROM            dbo.tbCommercialTransactions	 AS tic						WITH (NOLOCK)

				INNER JOIN dbo.tbSalesTerms									WITH (NOLOCK)
                ON  tic.comp_id		= dbo.tbSalesTerms.comp_id AND
					tic.st_id		= dbo.tbSalesTerms.st_id

                INNER JOIN dbo.tbSalesman									WITH (NOLOCK)
                ON  tic.comp_id		= dbo.tbSalesman.comp_id AND
					tic.sm_id		= dbo.tbSalesman.sm_id

                INNER JOIN dbo.tbsysDocuments								WITH (NOLOCK)
                ON  tic.sd_id		= dbo.tbsysDocuments.sd_id

                INNER JOIN dbo.tbDelivery									WITH (NOLOCK)
                ON  tic.comp_id		= dbo.tbDelivery.comp_id AND
					tic.dl_id		= dbo.tbDelivery.dl_id

                INNER JOIN dbo.tbUser										WITH (NOLOCK)
                ON tic.user_id		= dbo.tbUser.user_id

                INNER JOIN dbo.tbDocumentsFile								WITH (NOLOCK)
                ON tic.df_id		= dbo.tbDocumentsFile.df_id AND
                tic.bra_id			= dbo.tbDocumentsFile.bra_id AND
                tic.comp_id			= dbo.tbDocumentsFile.comp_id

                INNER JOIN dbo.tbsysCountry									WITH (NOLOCK)
                ON tic.country_id	= dbo.tbsysCountry.country_id

                INNER JOIN tbsysState AS								ts WITH (NOLOCK)
                ON	ts.country_id	= tic.country_id AND
					ts.state_id		= tic.state_id

                INNER JOIN dbo.tbDiscount									WITH (NOLOCK)
                ON tic.comp_id		= dbo.tbDiscount.comp_id AND
                tic.disc_id			= dbo.tbDiscount.disc_id


WHERE        (tic.ct_date > DATEADD(yy, - 3, GETDATE()))
GO



CREATE VIEW [dbi].[vwbi_Compras]
AS
SELECT tit.comp_id, tct.ct_date, tit.item_id, tit.it_qty, tit.it_price, tit.it_priceOfCost, tit.ct_transaction, dbo.fnGetCommercialTransactionDescriptionNSB(tit.comp_id, 2, tit.ct_transaction) AS Comprob, tct.ct_kindOf, tct.ct_pointOfSale, tct.ct_docNumber,
                  tct.bra_id, tct.cust_id, tct.supp_id, tit.stor_id, tct.user_id, tit.it_exchangeToBranchCurrency, tct.ct_soh_id, tct.sm_id, tct.dl_id, ts.country_id, ts.state_id, ti.pres_id, vit.vw_itemUnitPriceWithTaxes, vitooit.tax_id, tct.st_id, tit.it_transaction
FROM     dbo.tbItemTransactions AS tit INNER JOIN
                  dbo.tbCommercialTransactions AS tct ON tct.comp_id = tit.comp_id AND tct.bra_id = tit.bra_id AND tct.ct_transaction = tit.ct_transaction INNER JOIN
                  dbo.vwCommercialTransactions_forPurchase_All AS vctfs ON vctfs.comp_id = tct.comp_id AND vctfs.bra_id = tct.bra_id AND vctfs.ct_transaction = tct.ct_transaction INNER JOIN
                  dbo.vwItemTransactions AS vit ON vit.comp_id = tit.comp_id AND vit.bra_id = tit.bra_id AND vit.ct_transaction = tit.ct_transaction AND vit.it_transaction = tit.it_transaction INNER JOIN
                  dbo.tbItem AS ti ON ti.item_id = tit.item_id AND ti.comp_id = tit.comp_id INNER JOIN
                  dbo.vwItemTaxesOnlyOneIvaTax AS vitooit ON vitooit.comp_id = ti.comp_id AND vitooit.item_id = ti.item_id LEFT OUTER JOIN
                  dbo.tbSupplier AS ts ON ts.comp_id = tct.comp_id AND ts.supp_id = tct.supp_id
GO


CREATE VIEW [dbi].[vwbi_Customer]
AS
SELECT dbo.tbcustomer.cust_cd,
       dbo.tbcustomer.cust_id,
       dbo.tbcustomer.cust_name,
       dbo.tbcustomer.cust_name1,
       dbo.tbcustomer.cust_taxnumber,
       dbo.tbcustomer.cust_inactive,
       dbo.tbcustomer.cust_address,
       dbo.tbcustomer.cust_city,
       dbo.tbcustomer.cust_zip,
       dbo.tbcustomer.country_id,
       dbo.tbsyscountry.country_desc,
       dbo.tbcustomer.state_id,
       dbo.tbsysstate.state_desc,
       dbo.tbcustomer.cust_email,
       dbo.tbcustomer.disc_id,
       dbo.tbdiscount.disc_desc,
       dbo.tbdiscount.disc_coef,
       dbo.tbcustomer.cust_credit_max,
       dbo.tbcustomer.cust_credit_own,
       dbo.tbcustomer.curr_id,
       dbo.tbsyscurrency.curr_desc,
       dbo.tbcustomer.acc_count_id,
       dbo.tbcustomer.prli_id,
       dbo.tbsalesector.ss_desc   AS Cliente_Area,
       dbo.tbcustomerkind.ck_name AS Cliente_Clase,
       dbo.tbdelivery.dl_name     AS Cliente_Transporte
FROM   dbo.tbdiscount WITH (nolock)
       RIGHT OUTER JOIN dbo.tbcustomer WITH (nolock)
                     ON dbo.tbdiscount.comp_id = dbo.tbcustomer.comp_id
                        AND dbo.tbdiscount.disc_id = dbo.tbcustomer.disc_id
       INNER JOIN dbo.tbsyscurrency WITH (nolock)
               ON dbo.tbcustomer.curr_id = dbo.tbsyscurrency.curr_id
       LEFT OUTER JOIN dbo.tbcustomerkind WITH (nolock)
                    ON dbo.tbcustomer.comp_id = dbo.tbcustomerkind.comp_id
                       AND dbo.tbcustomer.ck_id = dbo.tbcustomerkind.ck_id
       LEFT OUTER JOIN dbo.tbdelivery WITH (nolock)
                    ON dbo.tbcustomer.dl_id = dbo.tbdelivery.dl_id
       LEFT OUTER JOIN dbo.tbsysstate WITH (nolock)
                       INNER JOIN dbo.tbsyscountry WITH (nolock)
                               ON dbo.tbsysstate.country_id =
                                  dbo.tbsyscountry.country_id
                    ON dbo.tbcustomer.country_id = dbo.tbsysstate.country_id
                       AND dbo.tbcustomer.state_id = dbo.tbsysstate.state_id
       LEFT OUTER JOIN dbo.tbsalesector
                    ON dbo.tbcustomer.comp_id = dbo.tbsalesector.comp_id
                       AND dbo.tbcustomer.ss_id = dbo.tbsalesector.ss_id
GO




