CREATE VIEW [dbi].[vwbi_item]
AS
SELECT
				item.item_LastUpdate, item.item_disabled, item.comp_id, item.bra_id, item.item_NoStockCheck, item.item_not4Sale, item.item_id,
				item.item_code, item.item_desc, item.item_detail, item.item_vendorCode,
                dbo.tbCategoryGroup.catg_id, dbo.tbCategoryGroup.catg_desc, item.cat_id, dbo.tbCategory.cat_desc,
                item.subcat_id, dbo.tbSubCategory.subcat_desc, item.subcataux_id, dbo.tbSubCategoryAux.subcataux_desc, item.brand_id,
                dbo.tbBrand.brand_desc, item.supp_id, dbo.tbSupplier.supp_name, item.pres_id, item.curr_id,
                dbo.tbPresentation.pres_desc, item.item_upb, item.item_upp, item.item_cantMin, item.item_cantOpt, item.item_repositionTime,
                item.item_disabledInPriceList, item.item_mult, item.item_commission, item.item_guarantee,
                item.item_expser, item.item_made, item.item_web, item.item_annotation, item.item_annotation1, item.item_annotation2,
                item.acc_count_id, item.item_newness, item.item_liquidation, item.item_weight, item.item_volume,
                item.item_wide, item.item_large, item.item_higth, item.item_expean, item.item_outlet, item.ic_id, item.brag_id,
                item.item_markup_1, item.item_markup_2, item.item_markup_3, item.item_markup_4, item.item_markup_5,
                item.item_markup_6, item.item_markup_7, item.item_markup_8, item.item_markup_9, item.item_markup_10,
                item.item_markup_11, item.item_markup_12, item.item_markup_13, item.item_markup_14, item.item_markup_15, item.item_markup_16,item_isForAssociation

FROM            dbo.tbItem AS item											WITH (NOLOCK)

				INNER JOIN dbo.tbCategory									WITH (NOLOCK)
                ON	dbo.tbCategory.comp_id	= item.comp_id AND
					dbo.tbCategory.cat_id	= item.cat_id

                LEFT JOIN dbo.tbSupplier									WITH (NOLOCK)
                ON	dbo.tbSupplier.comp_id = item.comp_id AND
					dbo.tbSupplier.supp_id = item.supp_id

                INNER JOIN dbo.tbPresentation								WITH (NOLOCK)
                ON  item.comp_id				= dbo.tbPresentation.comp_id AND
                    item.pres_id				= dbo.tbPresentation.pres_id

                LEFT OUTER JOIN dbo.tbSubCategory							WITH (NOLOCK)
                ON  dbo.tbSubCategory.comp_id	= item.comp_id			AND
                dbo.tbSubCategory.cat_id		= item.cat_id			AND
                 dbo.tbSubCategory.subcat_id	= item.subcat_id

                LEFT OUTER JOIN dbo.tbSubCategoryAux						WITH (NOLOCK)
                ON dbo.tbSubCategoryAux.comp_id		= item.comp_id		AND
                dbo.tbSubCategoryAux.subcataux_id	= item.subcataux_id


                INNER JOIN dbo.tbBrand										WITH (NOLOCK)
                ON item.comp_id				= dbo.tbBrand.comp_id	AND
				   item.brand_id			= dbo.tbBrand.brand_id

                LEFT OUTER JOIN dbo.tbItemClass								WITH (NOLOCK)
                ON	dbo.tbItemClass.comp_id = item.comp_id			AND
					dbo.tbItemClass.ic_id = item.ic_id

                LEFT OUTER JOIN dbo.tbCategoryGroup							WITH (NOLOCK)
                ON dbo.tbCategory.comp_id = dbo.tbCategoryGroup.comp_id AND
                dbo.tbCategory.catg_id	  = dbo.tbCategoryGroup.catg_id
GO





