CREATE VIEW [dbi].[vwbi_ItemStock]
AS

SELECT
		ITST.item_id																		[item_id]
		,ITST.item_code																		[item_code]
		,ITST.item_desc																		[item_desc]
		,ITST.stor_id																		[stor_id]
		,ITST.stor_desc																		[stor_desc]
		,isnull(TIS.itst_cant,0)															[Stock_Actual]
		,dbo.fnGetAStock4MaxAssociation(ITST.comp_id, ITST.stor_id, ITST.item_id, 99999999)	[Stock_Disponible]

from
	(select
		TS.comp_id
		, TS.stor_id
		, TS.stor_desc
		, TI.item_id
		,ti.item_code
		, ti.item_desc
	from tbItem TI
		cross apply tbStorage TS) AS ITST
		LEFT join tbItemStorage TIS
		ON
			TIS.comp_id = ITST.comp_id AND
			TIS.stor_id = ITST.stor_id AND
			TIS.item_id = ITST.item_id

GO




CREATE view [dbi].[vwbi_itemSubCategory]
AS

	SELECT	tc.comp_id,
			tc.cat_id,
			tc.subcat_id,
			tc.subcat_desc,
	      	tc.subcat_necessary,
	      	tc.subcat_enough
		FROM tbSubCategory AS tc	WITH (NOLOCK)

GO


CREATE VIEW [dbi].[vwbi_itemTransactions_Sales]
AS
SELECT
				tct.ct_date, tic.ct_transaction, tic.it_transaction, tct.dl_id, tct.st_id, tct.sd_id, dbo.tbBranch.bra_MainDesc, tct.ct_discountPlanCoeficient,
				tct.ct_soh_id, ISNULL(tic.item_id, tic.item_idfromPreInvoice) AS item_id,
				tic.it_transaction_NoStockDiscount, tic.it_qty, tic.it_priceWithOutOthers, tic.it_price, dbo.fnGetPriceListItemTaxesCoeficient(tic.comp_id, tic.item_id) AS IVACoef,
				tic.curr_id, dbo.tbsysCurrency.curr_symbol,
				tct.ct_dfExchangeOriginal, tct.ct_ACurrencyExchange, tic.it_exchangeToBranchCurrency, tic.it_priceOfCost,
				tic.it_priceOfCostPP, tic.it_priceOfCostLastPurchase, tic.it_priceBOfCost, tic.it_priceBOfCostPP,
				tic.it_priceBOfCostLastPurchase, tic.it_OriginalPrice, tic.it_OriginalPriceCurrency, tic.stor_id, tic.it_storePrevious, tic.prli_id,
				tic.byor_id, tic.it_cd, tic.it_order, tic.it_guarantee, tic.it_itemDiscountTotal, tic.it_totalDiscountTotal,
				tic.it_CreditInt, tic.it_CreditIntPlus, tic.it_note1, tic.it_note2, tic.it_cancelled, tic.it_priceB, tic.it_isMade, tic.coslis_id,
				tic.coslis_idB, tic.supp_id, tic.camp_id, tic.it_transaction_originalEW, tic.it_IsInternalTransfer,
				tic.it_IsFastStockAdjustment, tic.it_IsStockAdjustment, tic.it_IsStockControl, tic.it_NoStockCheck, tic.it_surcharge1, tic.it_surcharge2,
				tic.it_surcharge3, tic.it_surcharge4, tic.it_isPCConfig, tic.item_idfromPreInvoice, tic.it_MLCost,
				tic.it_isCompensed, tic.ws_price, tic.ws_curr_Id, tic.mlo_id, tic.it_MPCost, tic.it_MECost, tic.tis_itemDiscountPlan,
				tic.it_itemDiscount, tic.it_exchangeToOriginalPriceCurrency, tic.it_Discount1, tic.it_Discount2, tic.it_Discount3,
				tic.it_Discount4, tic.it_deliveryDate, tic.it_isProduction, tic.it_isAssociation,
				tic.it_isAssociationGroup, tic.it_packingInvoiceSelected, SD.sd_plusOrminus


FROM            dbo.tbCommercialTransactions			AS tct		WITH (NOLOCK)

				INNER JOIN dbo.tbItemTransactions		AS tic		WITH (NOLOCK)
				ON tic.comp_id			= tct.comp_id
				AND tic.bra_id			= tct.bra_id
				AND tic.ct_transaction	= tct.ct_transaction

				INNER JOIN dbo.tbsysCurrency						WITH (NOLOCK)
				ON tic.curr_id			= dbo.tbsysCurrency.curr_id

				INNER JOIN dbo.tbsysDocuments			AS SD		WITH (NOLOCK)
				ON tct.sd_id			= SD.sd_id

                INNER JOIN dbo.tbBranch								WITH (NOLOCK)
                ON  tic.comp_id			= dbo.tbBranch.comp_id
                AND tic.bra_id			= dbo.tbBranch.bra_id

WHERE        (tct.ct_date > DATEADD(yy, - 3, GETDATE())) AND (SD.sd_isSales = 'True')
GO


CREATE VIEW [dbi].[vwbi_PlanDeCuentas]
AS
  SELECT COALESCE (TITULO.titulo_id, TITULO.rubro_id, TITULO.nivel_1_id,
                   TITULO.nivel_2_id, TITULO.nivel_3_id, TITULO.nivel_4_id,
                   TITULO.nivel_5_id,
                   dbo.vwaccountant_onlyimputableaccounts.acc_count_id)
            AS titulo_id,
         COALESCE (TITULO.rubro_id, TITULO.nivel_1_id, TITULO.nivel_2_id,
         TITULO.nivel_3_id, TITULO.nivel_4_id, TITULO.nivel_5_id,
         dbo.vwaccountant_onlyimputableaccounts.acc_count_id)
            AS rubro_id,
         COALESCE (TITULO.nivel_1_id, TITULO.nivel_2_id, TITULO.nivel_3_id,
         TITULO.nivel_4_id, TITULO.nivel_5_id,
         dbo.vwaccountant_onlyimputableaccounts.acc_count_id)
            AS nivel_1_id,
         COALESCE (TITULO.nivel_2_id, TITULO.nivel_3_id, TITULO.nivel_4_id,
         TITULO.nivel_5_id, dbo.vwaccountant_onlyimputableaccounts.acc_count_id)
            AS
         nivel_2_id,
         COALESCE (TITULO.nivel_3_id, TITULO.nivel_4_id, TITULO.nivel_5_id,
         dbo.vwaccountant_onlyimputableaccounts.acc_count_id)
            AS nivel_3_id,
         COALESCE (TITULO.nivel_4_id, TITULO.nivel_5_id,
         dbo.vwaccountant_onlyimputableaccounts.acc_count_id)
            AS nivel_4_id,
         COALESCE (TITULO.nivel_5_id,
         dbo.vwaccountant_onlyimputableaccounts.acc_count_id)
            AS nivel_5_id,
         dbo.vwaccountant_onlyimputableaccounts.acc_count_id,
         COALESCE (TITULO.rubro_desc, TITULO.nivel_1_desc, TITULO.nivel_2_desc,
         TITULO.nivel_3_desc, TITULO.nivel_4_desc, TITULO.nivel_5_desc,
         dbo.vwaccountant_onlyimputableaccounts.acc_desc)
            AS rubro_desc,
         COALESCE (TITULO.nivel_1_desc, TITULO.nivel_2_desc,
         TITULO.nivel_3_desc,
         TITULO.nivel_4_desc, TITULO.nivel_5_desc,
         dbo.vwaccountant_onlyimputableaccounts.acc_desc)
            AS nivel_1_desc,
         COALESCE (TITULO.nivel_2_desc, TITULO.nivel_3_desc,
         TITULO.nivel_4_desc,
         TITULO.nivel_5_desc, dbo.vwaccountant_onlyimputableaccounts.acc_desc)
            AS
         nivel_2_desc,
         COALESCE (TITULO.nivel_3_desc, TITULO.nivel_4_desc,
         TITULO.nivel_5_desc,
         dbo.vwaccountant_onlyimputableaccounts.acc_desc)
            AS nivel_3_desc,
         COALESCE (TITULO.nivel_4_desc, TITULO.nivel_5_desc,
         dbo.vwaccountant_onlyimputableaccounts.acc_desc)
            AS nivel_4_desc,
         COALESCE (TITULO.nivel_5_desc,
         dbo.vwaccountant_onlyimputableaccounts.acc_desc)
                                                  AS nivel_5_desc,
         COALESCE (TITULO.rubro_codigo, TITULO.nivel_1_codigo,
         TITULO.nivel_2_codigo,
         TITULO.nivel_3_codigo, TITULO.nivel_4_codigo,
         dbo.vwaccountant_onlyimputableaccounts.acc_code)
            AS rubro_Codigo,
         COALESCE (TITULO.nivel_1_codigo, TITULO.nivel_2_codigo,
         TITULO.nivel_3_codigo,
         TITULO.nivel_4_codigo, dbo.vwaccountant_onlyimputableaccounts.acc_code)
            AS
         nivel_1_Codigo,
         COALESCE (TITULO.nivel_2_codigo, TITULO.nivel_3_codigo,
         TITULO.nivel_4_codigo,
         dbo.vwaccountant_onlyimputableaccounts.acc_code)
            AS nivel_2_Codigo,
         COALESCE (TITULO.nivel_3_codigo, TITULO.nivel_4_codigo,
         dbo.vwaccountant_onlyimputableaccounts.acc_code)
            AS nivel_3_Codigo,
         COALESCE (TITULO.nivel_4_codigo,
         dbo.vwaccountant_onlyimputableaccounts.acc_code)
            AS nivel_4_Codigo,
         dbo.vwaccountant_onlyimputableaccounts.acc_code
  FROM   (SELECT NIVEL_5.acc_count_id AS titulo_id,
                 RUBRO.acc_count_id   AS rubro_id,
                 RUBRO.acc_desc       AS rubro_desc,
                 RUBRO.acc_code       AS rubro_Codigo,
                 NIVEL_1.acc_count_id AS nivel_1_id,
                 NIVEL_1.acc_desc     AS nivel_1_desc,
                 NIVEL_1.acc_code     AS nivel_1_Codigo,
                 NIVEL_2.acc_count_id AS nivel_2_id,
                 NIVEL_2.acc_desc     AS nivel_2_desc,
                 NIVEL_2.acc_code     AS nivel_2_Codigo,
                 NIVEL_3.acc_count_id AS nivel_3_id,
                 NIVEL_3.acc_desc     AS nivel_3_desc,
                 NIVEL_3.acc_code     AS nivel_3_Codigo,
                 NIVEL_4.acc_count_id AS nivel_4_id,
                 NIVEL_4.acc_desc     AS nivel_4_desc,
                 NIVEL_4.acc_code     AS nivel_4_Codigo,
                 NIVEL_5.acc_count_id AS nivel_5_id,
                 NIVEL_5.acc_desc     AS nivel_5_desc,
                 NIVEL_5.acc_code
          FROM   dbo.tbaccountant AS RUBRO WITH (nolock)
                 LEFT OUTER JOIN dbo.tbaccountant AS NIVEL_1
                              ON RUBRO.acc_count_id = NIVEL_1.acc_count_sum
                                 AND NIVEL_1.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_2
                         ON NIVEL_1.acc_count_id = NIVEL_2.acc_count_sum
                            AND NIVEL_2.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_3
                         ON NIVEL_2.acc_count_id = NIVEL_3.acc_count_sum
                            AND NIVEL_3.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_4
                         ON NIVEL_3.acc_count_id = NIVEL_4.acc_count_sum
                            AND NIVEL_4.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_5
                         ON NIVEL_4.acc_count_id = NIVEL_5.acc_count_sum
                            AND NIVEL_5.acc_imputable = 0
          WHERE  ( Isnumeric(RUBRO.acc_count_sum) = 0 )
          UNION ALL
          SELECT NIVEL_4.acc_count_id AS titulo_id,
                 RUBRO.acc_count_id   AS rubro_id,
                 RUBRO.acc_desc       AS rubro_desc,
                 RUBRO.acc_code       AS rubro_Codigo,
                 NIVEL_1.acc_count_id AS nivel_1_id,
                 NIVEL_1.acc_desc     AS nivel_1_desc,
                 NIVEL_1.acc_code     AS nivel_1_Codigo,
                 NIVEL_2.acc_count_id AS nivel_2_id,
                 NIVEL_2.acc_desc     AS nivel_2_desc,
                 NIVEL_2.acc_code     AS nivel_2_Codigo,
                 NIVEL_3.acc_count_id AS nivel_3_id,
                 NIVEL_3.acc_desc     AS nivel_3_desc,
                 NIVEL_3.acc_code     AS nivel_3_Codigo,
                 NIVEL_4.acc_count_id AS nivel_4_id,
                 NIVEL_4.acc_desc     AS nivel_4_desc,
                 NIVEL_4.acc_code     AS nivel_4_Codigo,
                 NULL                 AS nivel_5_id,
                 NULL                 AS nivel_5_desc,
                 NULL                 AS NIVEL_5_ACC_CODE
          FROM   dbo.tbaccountant AS RUBRO
                 LEFT OUTER JOIN dbo.tbaccountant AS NIVEL_1
                              ON RUBRO.acc_count_id = NIVEL_1.acc_count_sum
                                 AND NIVEL_1.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_2
                         ON NIVEL_1.acc_count_id = NIVEL_2.acc_count_sum
                            AND NIVEL_2.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_3
                         ON NIVEL_2.acc_count_id = NIVEL_3.acc_count_sum
                            AND NIVEL_3.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_4
                         ON NIVEL_3.acc_count_id = NIVEL_4.acc_count_sum
                            AND NIVEL_4.acc_imputable = 0
          WHERE  ( Isnumeric(RUBRO.acc_count_sum) = 0 )
          UNION ALL
          SELECT NIVEL_3.acc_count_id AS titulo_id,
                 RUBRO.acc_count_id   AS rubro_id,
                 RUBRO.acc_desc       AS rubro_desc,
                 RUBRO.acc_code       AS rubro_Codigo,
                 NIVEL_1.acc_count_id AS nivel_1_id,
                 NIVEL_1.acc_desc     AS nivel_1_desc,
                 NIVEL_1.acc_code     AS nivel_1_Codigo,
                 NIVEL_2.acc_count_id AS nivel_2_id,
                 NIVEL_2.acc_desc     AS nivel_2_desc,
                 NIVEL_2.acc_code     AS nivel_2_Codigo,
                 NIVEL_3.acc_count_id AS nivel_3_id,
                 NIVEL_3.acc_desc     AS nivel_3_desc,
                 NIVEL_3.acc_code     AS nivel_3_Codigo,
                 NULL                 AS nivel_4_id,
                 NULL                 AS nivel_4_desc,
                 NULL                 AS nivel_4_Codigo,
                 NULL                 AS nivel_5_id,
                 NULL                 AS nivel_5_desc,
                 NULL                 AS NIVEL_5_ACC_CODE
          FROM   dbo.tbaccountant AS RUBRO
                 LEFT OUTER JOIN dbo.tbaccountant AS NIVEL_1
                              ON RUBRO.acc_count_id = NIVEL_1.acc_count_sum
                                 AND NIVEL_1.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_2
                         ON NIVEL_1.acc_count_id = NIVEL_2.acc_count_sum
                            AND NIVEL_2.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_3
                         ON NIVEL_2.acc_count_id = NIVEL_3.acc_count_sum
                            AND NIVEL_3.acc_imputable = 0
          WHERE  ( Isnumeric(RUBRO.acc_count_sum) = 0 )
          UNION ALL
          SELECT NIVEL_2.acc_count_id AS titulo_id,
                 RUBRO.acc_count_id   AS rubro_id,
                 RUBRO.acc_desc       AS rubro_desc,
                 RUBRO.acc_code       AS rubro_Codigo,
                 NIVEL_1.acc_count_id AS nivel_1_id,
                 NIVEL_1.acc_desc     AS nivel_1_desc,
                 NIVEL_1.acc_code     AS nivel_1_Codigo,
                 NIVEL_2.acc_count_id AS nivel_2_id,
                 NIVEL_2.acc_desc     AS nivel_2_desc,
                 NIVEL_2.acc_code     AS nivel_2_Codigo,
                 NULL                 AS nivel_3_id,
                 NULL                 AS nivel_3_desc,
                 NULL                 AS nivel_3_Codigo,
                 NULL                 AS nivel_4_id,
                 NULL                 AS nivel_4_desc,
                 NULL                 AS nivel_4_Codigo,
                 NULL                 AS nivel_5_id,
                 NULL                 AS nivel_5_desc,
                 NULL                 AS NIVEL_5_ACC_CODE
          FROM   dbo.tbaccountant AS RUBRO
                 LEFT OUTER JOIN dbo.tbaccountant AS NIVEL_1
                              ON RUBRO.acc_count_id = NIVEL_1.acc_count_sum
                                 AND NIVEL_1.acc_imputable = 0
                 INNER JOIN dbo.tbaccountant AS NIVEL_2
                         ON NIVEL_1.acc_count_id = NIVEL_2.acc_count_sum
                            AND NIVEL_2.acc_imputable = 0
          WHERE  ( Isnumeric(RUBRO.acc_count_sum) = 0 )
          UNION ALL
          SELECT NIVEL_1.acc_count_id AS titulo_id,
                 RUBRO.acc_count_id   AS rubro_id,
                 RUBRO.acc_desc       AS rubro_desc,
                 RUBRO.acc_code       AS rubro_Codigo,
                 NIVEL_1.acc_count_id AS nivel_1_id,
                 NIVEL_1.acc_desc     AS nivel_1_desc,
                 NIVEL_1.acc_code     AS nivel_1_Codigo,
                 NULL                 AS nivel_2_id,
                 NULL                 AS nivel_2_desc,
                 NULL                 AS nivel_2_Codigo,
                 NULL                 AS nivel_3_id,
                 NULL                 AS nivel_3_desc,
                 NULL                 AS nivel_3_Codigo,
                 NULL                 AS nivel_4_id,
                 NULL                 AS nivel_4_desc,
                 NULL                 AS nivel_4_Codigo,
 NULL                 AS nivel_5_id,
                 NULL                 AS nivel_5_desc,
                 NULL                 AS NIVEL_5_ACC_CODE
          FROM   dbo.tbaccountant AS RUBRO
                 LEFT OUTER JOIN dbo.tbaccountant AS NIVEL_1
                              ON RUBRO.acc_count_id = NIVEL_1.acc_count_sum
                                 AND NIVEL_1.acc_imputable = 0
          WHERE  ( Isnumeric(RUBRO.acc_count_sum) = 0 )
          UNION ALL
          SELECT acc_count_id AS titulo_id,
                 acc_count_id AS rubro_id,
                 acc_desc     AS rubro_desc,
                 acc_code     AS rubro_Codigo,
                 NULL         AS nivel_1_id,
                 NULL         AS nivel_1_desc,
                 NULL         AS nivel_1_Codigo,
                 NULL         AS nivel_2_id,
                 NULL         AS nivel_2_desc,
                 NULL         AS nivel_2_Codigo,
                 NULL         AS nivel_3_id,
                 NULL         AS nivel_3_desc,
                 NULL         AS nivel_3_Codigo,
                 NULL         AS nivel_4_id,
                 NULL         AS nivel_4_desc,
                 NULL         AS nivel_4_Codigo,
                 NULL         AS nivel_5_id,
                 NULL         AS nivel_5_desc,
                 NULL         AS NIVEL_5_ACC_CODE
          FROM   dbo.tbaccountant AS RUBRO
          WHERE  ( Isnumeric(acc_count_sum) = 0 )) AS TITULO
         RIGHT OUTER JOIN dbo.vwaccountant_onlyimputableaccounts
                       ON TITULO.titulo_id =
                          dbo.vwaccountant_onlyimputableaccounts.acc_count_sum

GO



