--- vwbi_Ventasdetalle
--- 18/10/22 Se ajusta LEFT JOIN con listas de precios (ya que las ventas de concepto no tienen lista de precios)
--- 18/10/22 sE AJUSTA LEFT JOIN con grupos contables (ya que no todas las sucursales tienen grupo contable)

CREATE VIEW [dbi].[vwbi_VentasDetalle]
AS
SELECT tct.bra_id,
       DF.df_desc,
       SD.sd_desc,
       CASE
         WHEN SD.sd_id IN ( '1', '3', '4', '31', '33' )
              AND DF.df_saleorder_invoicefirstpacking_df_id IS NULL THEN
         'Vta c/Remito'
         WHEN SD.sd_id = '1'
              AND DF.df_saleorder_invoicefirstpacking_df_id IS NOT NULL THEN
         'Vta Anticipada'
         WHEN DF.sd_id = '2'
              AND DF.df_saleorder_isinvoicefirstpacking = 1 THEN
         'Rem s/FC Antic'
         WHEN DF.sd_id = '2'
              AND DF.df_isinterbranchdocument = 1 THEN 'Remito Inter'
         WHEN DF.sd_id = '2'
              AND DF.df_packinginvoicepend = 0 THEN 'Rem No fact'
         WHEN DF.sd_id = '2'
              AND tit.it_packinginvoicepend = 1 THEN 'Rem Pend FC'
         WHEN SD.sd_id IN ( '43', '44' ) THEN 'Dif Cambio'
         ELSE 'Otros'
       END
       AS TipoOper,
       CURR_ct_ACurr.curr_symbol
       AS ct_ACur,
       tct.ct_dfexchangeoriginal,
       tct.ct_acurrencyexchange,
       tct.ct_dfexchange,
       CURR_ct_ACurr.curr_symbol
       AS it_Curr,
       CURR_it_OriginalPrice.curr_symbol
       AS it_originalPriceCurrency,
       dbo.tbpricelist.prli_desc,
       tit.it_exchangetobranchcurrency,
       DF.df_nickname,
       DF.df_printername,
	   dbo.fnGetCommercialTransactionDescriptionNSB( tit.comp_id, 2,tit.ct_transaction)  [Comprob],
       tct.ct_kindof
	   AS ct_kindOf,
       dbo.Padstring(DF.df_pointofsale, '0', 5)
       AS df_pointOfSale,
       tct.ct_docnumber,
       SD.sd_plusorminus,
       tct.ct_taxdate
	   AS ct_taxDate,
       tct.ct_paydate
	   AS ct_payDate,
       tct.cust_id,
       tct.user_id,
       USR.user_firstname + N'  ' + USR.user_lastname
       AS user_name,
       tct.ct_cd,
       tct.ct_discount,
       tct.ct_adjust,
       tct.ct_taxes,
       tct.ct_atotal,
       tct.ct_abalance,
       tct.sm_id,
       SM.sm_name,
       tct.dl_id,
       DEL.dl_name,
       ST.st_desc,
       tct.sd_id,
       tct.country_id,
       tct.state_id,
       tct.disc_id,
       DISC.disc_desc,
       tct.ct_discountplancoeficient,
       tct.ct_soh_id,
       tct.ct_date,
       tit.ct_transaction,
       tit.it_transaction,
       tct.st_id,
       Isnull(tit.item_id, tit.item_idfrompreinvoice)
       AS item_id,
       tit.stor_id,
       STOR.stor_desc,
       tit.it_transaction_nostockdiscount,
       tit.it_qty,
       tit.it_pricewithoutothers
	   AS it_priceWithOutOthers,
       tit.it_price,
       Isnull(vTaxIva.total, 0)
       AS Tax_Iva,
       Isnull(vTaxNoIva.total, 0)
       AS Tax_NoIva,
         CASE
          WHEN tit.it_price = 0 OR tit.it_qty=0 THEN 1
		  ELSE
		  ROUND(1 + (Isnull(vTaxIva.total, 0)/ (tit.it_price * tit.it_qty)),2)
		  END
       AS IVACoef,
	   CASE
          WHEN tit.it_price = 0 OR tit.it_qty=0 THEN 1
		  ELSE
		  ROUND(1 + (Isnull(vTaxNoIva.total, 0)+ Isnull(vTaxIva.total, 0)/ (tit.it_price * tit.it_qty)),2)
		  END
       AS TaxCoef,
       tit.it_priceofcost,
       tit.it_priceofcostpp,
       tit.it_priceofcostlastpurchase,
       tit.it_pricebofcost,
       tit.it_pricebofcostpp,
       tit.it_pricebofcostlastpurchase,
       tit.it_originalprice,
       tit.it_storeprevious,
       tit.byor_id,
       tit.it_cd,
       tit.it_order,
       tit.it_guarantee,
       tit.it_itemdiscounttotal,
       tit.it_totaldiscounttotal,
       tit.it_creditint,
       tit.it_creditintplus,
       tit.it_note1,
       tit.it_note2,
       tit.it_cancelled,
       tit.it_priceb,
       tit.it_ismade,
       tit.coslis_id,
       tit.coslis_idb,
       tit.supp_id,
       tit.camp_id,
       tit.it_transaction_originalew,
       tit.it_isinternaltransfer,
       tit.it_isfaststockadjustment,
       tit.it_isstockadjustment,
       tit.it_isstockcontrol,
       tit.it_nostockcheck,
       tit.it_surcharge1,
       tit.it_surcharge2,
       tit.it_surcharge3,
       tit.it_surcharge4,
       tit.it_ispcconfig,
       tit.item_idfrompreinvoice,
       tit.it_mlcost,
       tit.it_iscompensed,
       tit.ws_price,
       tit.ws_curr_id,
       Isnull(tit.mlo_id, tct.mlo_id)
       AS mlo_id,
       tit.it_mpcost,
	   tit.it_mecost,
       tit.tis_itemdiscountplan,
       tit.it_itemdiscount,
       tit.it_exchangetooriginalpricecurrency,
       tit.it_discount1,
       tit.it_discount2,
       tit.it_discount3,
       tit.it_discount4,
       tit.it_deliverydate,
       tit.it_isproduction,
       tit.it_isassociation,
       tit.it_isassociationgroup,
       COALESCE (tit.it_item_id_origin, tit.item_id, tit.item_idfrompreinvoice)
       AS
       combo_o_item_id
FROM   dbo.tbcommercialtransactions AS tct WITH (nolock)
       INNER JOIN dbo.tbitemtransactions AS tit WITH (nolock)
               ON tit.comp_id = tct.comp_id
                  AND tit.bra_id = tct.bra_id
                  AND tit.ct_transaction = tct.ct_transaction
       INNER JOIN dbo.tbsyscurrency AS CURR_ct_ACurr WITH (nolock)
               ON tct.ct_acurrency = CURR_ct_ACurr.curr_id
       INNER JOIN dbo.tbsysdocuments AS SD WITH (nolock)
               ON tct.sd_id = SD.sd_id
       INNER JOIN dbo.tbbranch AS BRA WITH (nolock)
               ON tit.comp_id = BRA.comp_id
                  AND tit.bra_id = BRA.bra_id
       INNER JOIN dbo.tbdocumentsfile AS DF WITH (nolock)
               ON tct.comp_id = DF.comp_id
                  AND tct.bra_id = DF.bra_id
                  AND tct.df_id = DF.df_id
       INNER JOIN dbo.tbsalesman AS SM WITH (nolock)
               ON SM.sm_id = tct.sm_id
       INNER JOIN dbo.tbsalesterms AS ST WITH (nolock)
               ON ST.comp_id = tct.comp_id
                  AND ST.st_id = tct.st_id
       INNER JOIN dbo.tbuser AS USR WITH (nolock)
               ON USR.user_id = tct.user_id
       INNER JOIN dbo.tbdelivery AS DEL WITH (nolock)
               ON DEL.comp_id = tct.comp_id
                  AND DEL.dl_id = tct.dl_id
       INNER JOIN dbo.tbdiscount AS DISC WITH (nolock)
               ON DISC.comp_id = tct.comp_id
                  AND DISC.disc_id = tct.disc_id
       INNER JOIN dbo.tbsyscurrency AS CURR_it WITH (nolock)
               ON tit.curr_id = CURR_it.curr_id
       INNER JOIN dbo.tbsyscurrency AS CURR_it_OriginalPrice WITH (nolock)
               ON tit.it_originalpricecurrency = CURR_it_OriginalPrice.curr_id
       LEFT OUTER JOIN dbo.tbaccountantgroup AS AG WITH (nolock)
               ON BRA.comp_id = AG.comp_id
                  AND BRA.ag_id = AG.ag_id
       LEFT OUTER JOIN dbo.tbpricelist WITH (nolock)
               ON tit.comp_id = dbo.tbpricelist.comp_id
                  AND tit.prli_id = dbo.tbpricelist.prli_id
       LEFT OUTER JOIN dbo.vwtaxmovements_noivatax AS vTaxNoIva WITH (nolock)
                    ON tit.comp_id = vTaxNoIva.comp_id
                       AND tit.bra_id = vTaxNoIva.bra_id
                       AND tit.ct_transaction = vTaxNoIva.ct_transaction
                       AND tit.it_transaction = vTaxNoIva.it_transaction
       LEFT OUTER JOIN dbo.vwtaxmovements_totalivatax AS vTaxIva WITH (nolock)
                    ON tit.comp_id = vTaxIva.comp_id
                       AND tit.bra_id = vTaxIva.bra_id
                       AND tit.it_transaction = vTaxIva.it_transaction
                       AND tit.ct_transaction = vTaxIva.ct_transaction
       LEFT OUTER JOIN dbo.tbstorage AS STOR WITH (nolock)
                    ON tit.comp_id = STOR.comp_id
    AND tit.stor_id = STOR.stor_id
WHERE  ( SD.sd_id IN ( '1', '2', '3', '4',
                       '31', '33', '43', '44', '52' ) )
       AND ( tct.ct_docnumber <> '' )
GO




