-- MOS : 10-2008

CREATE VIEW [dbo].[vwCheckPortfolio_AllPayPending]	WITH SCHEMABINDING
AS




	-- Valores en Cartera o Pendientes de acreditacion
	Select     DISTINCT
			   cp.comp_id,
			   cp.chp_id,
			   IsNull(cp.chp_isNegociated,'False')						[isSold],
			   CASE
					WHEN tcpm.chp_id IS NULL  THEN 'False'
					ELSE 'True'
			   END				[isPayed2Supplier]
		From   dbo.tbCheckPortfolio			CP					WITH (NOLOCK)
		--bra_id, ct_transaction, mm_isCancelled, svtt_id, ba_id, bt_id
		LEFT JOIN dbo.tbCheckPortfolioMovements tcpm				WITH (NOLOCK)  -- Para ver si es un cheque salido en una orden de pago a un proveedor.-
			ON		tcpm.comp_id		= cp.comp_id
				AND tcpm.chp_id			= cp.chp_id
				AND tcpm.svtt_id		IN (30,40) --(tcpm.svtt_id		= 30  OR tcpm.svtt_id		= 40)  -- Depositados o entregados
				AND tcpm.mm_isCancelled = 'False'
		Where	(
					CP.chp_isAvailable	= 'True'	AND
					cp.chp_IsPayed		= 'false'	AND
					cp.chp_isRejected	= 'False'	AND
					cp.chp_isCancelled	= 'False'
				)
				OR
				(
					CP.chp_isAvailable	= 'False'	AND
					cp.chp_isNegociated	= 'True'
				)
				OR
				(NOT tcpm.chp_id IS NULL)	-- MOS: 01-2011   esto puede hacer que demoreeeeee
--			-- Se saco que no existan en el select de abajo ya que demoraba demasiado

--UNION
--
--	-- Valores VENDIDOS
--	SELECT		comp_id,
--				chp_id,
--				tbt.bt_Sold		[isSold],
--				'False'			[isPayed2Supplier]
--		FROM tbBankingTransactions tbt
--		WHERE	tbt.btt_id			= 1000020
--			AND tbt.bt_Sold			= 'true'
--			AND tbt.bt_isCancelled	= 'false'


GO






