CREATE view [dbo].[vwCities]		 AS


	select	tc.comp_id,
			tc.country_id,
			tc.state_id,
			tc.city_id,
			tc.city_desc,
			tc.city_zip,
			0		[city_Order],
			tc.city_desc COLLATE Modern_Spanish_CI_AI	[city_desc_collated],
			tc.city_zip	 COLLATE Modern_Spanish_CI_AI	[city_zip_collated]
		from	dbo.tbCities tc	WITH (NOLOCK)

	UNION all

	select	-1,
			tsc.country_id,
			tsc.state_id,
			tsc.city_id,
			tsc.city_desc,
			tsc.city_zip,
			1,
			tsc.city_desc	COLLATE Modern_Spanish_CI_AI		[city_desc_collated],
			tsc.city_zip	COLLATE Modern_Spanish_CI_AI		[city_zip_collated]
		from	dbo.tbSysCities tsc	WITH (NOLOCK)





GO



-- MOS 06-2014 cambio union por UNION ALL

CREATE view [dbo].[vwCollection]
AS
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-09-11
-- Parte		: 542
-- Description	: Se agrega la fecha de depósito en el campo type para los cheques
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-12-09
-- Parte		: 723
-- Description	: Se agregan los datos de cheques de terceros
-- =================================================================================================================



/****************************************************************************************/
/***   EFECTIVO   ***********************************************************************/
/****************************************************************************************/
SELECT 	cmt.comp_id,
		cmt.bra_id,
		cmt.bra_id										[bra_id_PortFolio],
		cmt.ct_transaction,
		'1'												[class],
		sov.lang_id										[lang_id],
		sov.optval_desc									[description],
		cmt.mm_desc										[type],
		cmt.mm_total									[amount],
		c.curr_desc										[currency],
		c.[curr_symbol]									[curr_symbol],
		c.curr_id										[curr_id],
		''												[desc],
		cmt.mm_BranchCurrencyExchange					[CurrencyExchange],
		'false'											[chp_isRejected],
		tct.ct_date										[Date],
		1												[GroupClass],
		-1												[tm_transaction],
		cmt.mm_id										[ID],
		-1												[cc_id],
		-1												[ccp_id],
		-1												[chp_id],
		-1												[ec_id],
		-1												[ba_id],
		-1												[ccm_id]
FROM 	dbo.tbMoneyMovements 							cmt		WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions tct					WITH (NOLOCK)
			ON	tct.comp_id			= cmt.comp_id AND
				tct.ct_transaction	= cmt.ct_transaction
		inner join dbo.[tbsysOptionsValues]				sov		WITH (NOLOCK)
			ON 	sov.optval_id			= 1
			AND sov.optval_class		= 40

		left join dbo.[tbsysCurrency]					c		WITH (NOLOCK)
			on	c.curr_id				= cmt.curr_id

WHERE 	not cmt.ct_transaction		is Null
/****************************************************************************************/



UNION	ALL



/****************************************************************************************/
/***   CHEQUES    ***********************************************************************/
/****************************************************************************************/
SELECT 	chpt.comp_id,
		chpt.bra_id,
		chpt.bra_id_PortFolio,
		chpt.ct_transaction,
		'2'												[class],
		sov.lang_id										[lang_id],
		sov.optval_desc									[description],
		'Nº:' + convert(varchar,chpt.chp_number) + '/' +
		tut.utexts_desc + convert(varchar,chpt.chp_PayDate,103)	-- Parte : 542
														[type],
		chpt.chp_total									[amount],
		c.curr_desc										[currency],
		c.[curr_symbol]									[curr_symbol],
		c.curr_id										[curr_id],
		bn.bn_name										[desc],
		chpt.chp_BranchCurrencyExchange					[CurrencyExchange],
		isnull(chpt.chp_isRejected,'false')				[chp_isRejected],
		chpt.chp_PayDate								[Date],
		2,
		-1												[tm_transaction],
		chpt.chp_id										[ID],
		-1												[cc_id],
		-1												[ccp_id],
		chpt.chp_id										[chp_id],
		-1												[ec_id],
		-1												[ba_id],
		-1												[ccm_id]


from	dbo.tbCheckPortfolio							chpt	WITH (NOLOCK)


		inner join dbo.[tbsysOptionsValues]				sov		WITH (NOLOCK)
		on	sov.optval_id			= 2
		and sov.optval_class		= 40

		left join dbo.tbBanksName						bn		WITH (NOLOCK)
		on	bn.comp_id				= chpt.comp_id
		and bn.bn_id				= chpt.bn_id

		left join dbo.[tbsysCurrency]					c		WITH (NOLOCK)
		on	c.curr_id				= chpt.curr_id

		LEFT JOIN tbsysUniqueTexts						tut		WITH (NOLOCK)		-- Parte		: 542		WITH (NOLOCK)
		ON tut.utexts_id			= 14					-- Parte		: 542
		AND tut.lang_id				= sov.lang_id			-- Parte		: 542

where	chpt.chp_isDocument			= 'False'
and		not chpt.ct_transaction		is null
/****************************************************************************************/




UNION	ALL



select	chpt.comp_id,
		chpt.bra_id,
		chpt.bra_id											[bra_id_PortFolio],
		chpt.ct_transaction,
		'3'													[class],
		sov.lang_id											[lang_id],
		sov.optval_desc										[description],
		'Doc. - ' + convert(varchar,chpt.chp_number)		[type],
		chpt.chp_total										[amount],
		c.curr_desc											[currency],
		c.[curr_symbol]										[curr_symbol],
		c.curr_id											[curr_id],
		chp_DocumentDescription								[desc],
		chpt.chp_BranchCurrencyExchange						[CurrencyExchange],
		'false'												[chp_isRejected],
		chpt.chp_PayDate									[Date] ,
		3,
		-1													[tm_transaction],
		chpt.chp_id											[ID],
		-1													[cc_id],
		-1													[ccp_id],
		chpt.chp_id											[chp_id],
		-1													[ec_id],
		-1													[ba_id],
		-1													[ccm_id]


from	dbo.tbCheckPortfolio								chpt		WITH (NOLOCK)

		inner join dbo.[tbsysOptionsValues]					sov		WITH (NOLOCK)
		on	sov.optval_id		= 3
		and sov.optval_class	= 40

		left join dbo.[tbsysCurrency]						c		WITH (NOLOCK)
		on	c.curr_id	= chpt.curr_id

where	chpt.chp_isDocument = 'True'
and		not chpt.ct_transaction  is null



UNION	ALL



select	ccmt.comp_id,
		ccmt.bra_id,
		ccmt.bra_id											[bra_id_PortFolio],
		ccmt.ct_transaction,
		'4'													[class],
		sov.lang_id											[lang_id],
		sov.optval_desc										[description],
		convert(varchar,cc.cc_desc)							[type],
		ccmt.ccm_Total										[amount],
		c.curr_desc											[currency],
		c.[curr_symbol]										[curr_symbol],
		c.curr_id											[curr_id],
		substring(ccmt.ccm_cardNumber,1,4) + '-' +
		substring(ccmt.ccm_cardNumber,5,4) + '-' +
		substring(ccmt.ccm_cardNumber,9,4) + '-' +
		substring(ccmt.ccm_cardNumber,13,4) 				[desc],
		ccmt.ccm_BranchCurrencyExchange						[CurrencyExchange],
		'false'												[chp_isRejected],
		tct.ct_date											[Date],
		4,
		-1													[tm_transaction],
		ccmt.ccm_id											[ID],
		ccmt.cc_id											[cc_id],
		ccmt.ccp_id											[ccp_id],
		-1													[chp_id],
		-1													[ec_id],
		-1													[ba_id],
		ccmt.ccm_id											[ccm_id]



from	dbo.tbCreditCardMovements							ccmt	WITH (NOLOCK)

		INNER JOIN tbCommercialTransactions tct						WITH (NOLOCK)
			ON	tct.comp_id			= ccmt.comp_id AND
				tct.ct_transaction	= ccmt.ct_transaction

		inner join dbo.[tbsysOptionsValues]					sov		WITH (NOLOCK)
		on	sov.optval_id		= 4
		and sov.optval_class	= 40

		left join 	dbo.tbCreditCard						cc		WITH (NOLOCK)
		on cc.comp_id	= ccmt.comp_id
		and cc.cc_id	= ccmt.cc_id

		left join dbo.tbsysCurrency							c		WITH (NOLOCK)
		on c.curr_id	= cc.curr_id

where	not ccmt.[ct_transaction] is null



UNION	ALL



/****************************************************************************************/
/***   TRANSACCIONES BANCARIAS **********************************************************/
/****************************************************************************************/
select	btt.comp_id,
		btt.bra_id,
		btt.bra_id											[bra_id_PortFolio],
		btt.ct_transaction,
		'5'													[class],
		sov.lang_id											[lang_id],
		sov.optval_desc										[description],
		btt.bt_note											[type],
		btt.[bt_total]										[amount],
		c.curr_desc											[currency],
		c.[curr_symbol]										[curr_symbol],
		c.curr_id											[curr_id],
		ba.ba_desc											[desc],
		btt.bt_BranchCurrencyExchange						[CurrencyExchange],
		'false'												[chp_isRejected],
		btt.bt_imputationDate								[Date]	,
		btt.ba_id,
		-1													[tm_transaction],
		btt.bt_id											[ID],
		-1													[cc_id],
		-1													[ccp_id],
		-1													[chp_id],
		-1													[ec_id],
		btt.ba_id											[ba_id],
		-1													[ccm_id]


from	dbo.tbBankingTransactions					btt		WITH (NOLOCK)

		inner join dbo.[tbsysOptionsValues]			sov		WITH (NOLOCK)
		on	sov.optval_id		= 5
		and sov.optval_class	= 40

		left join dbo.tbBankingAccounts				ba		WITH (NOLOCK)
		on ba.comp_id	= btt.comp_id
		and ba.ba_id	= btt.ba_id

		left join dbo.tbBankingTransactionTypes		btty	WITH (NOLOCK)
		on btty.comp_id	= btt.comp_id
		and btty.btt_id	= btt.btt_id

		left join dbo.[tbsysCurrency]				c		WITH (NOLOCK)
		on	c.curr_id	= btt.curr_id

where	not btt.[ct_transaction] is NULL

AND		btt.ec_id IS NULL		-- 2010-08-17 - MOH - para que no traiga los banking transaction que están relacionados
								-- a cheques propios, ya que se obtienen en esta vista por la clase '7'
/****************************************************************************************/



UNION	ALL



select	tm.[comp_id],
		tm.bra_id,
		tm.bra_id								[bra_id_PortFolio],
		tm.ct_transaction,
		'100'									[class],
		sov.lang_id								[lang_id],
		sov.optval_desc							[description],
		tn.[tax_desc]							[type],
		case tm.[curr_id]
			when ct.[ct_ACurrency] then tm.[tm_total]
			else						tm.[tm_total] * ct.[ct_ACurrencyExchange]
		end										[amount],
		sc.curr_desc							[currency],
		sc.[curr_symbol]						[curr_symbol],
		sc.curr_id								[curr_id],
		tm.[tm_docNumber]						[desc],
		tm.tm_exchangeToBranchCurrency			[CurrencyExchange],
		'false'									[chp_isRejected],
		tm.tm_cd								[Date]		,
		100,
		tm.tm_transaction						[tm_transaction],
		tm.[tax_id]								[ID],
		-1										[cc_id],
		-1										[ccp_id],
		-1										[chp_id],
		-1										[ec_id],
		-1												[ba_id],
		-1												[ccm_id]


	from	dbo.[tbTaxMovements]					tm	WITH (NOLOCK)

			inner join dbo.[tbsysOptionsValues]		sov	WITH (NOLOCK)
			on	sov.optval_id		= 100
			and sov.optval_class	= 40

			inner join dbo.[tbTaxName]				tn	WITH (NOLOCK)
			on	tn.[comp_id]		= tm.[comp_id]
			and	tn.[tax_id]			= tm.[tax_id]

			inner join dbo.[tbsysTaxClass]			stc	WITH (NOLOCK)
			on	stc.[tax_class]			= tn.[tax_class]
			and stc.[taxcl_isRetention] = 'True'

			inner join dbo.[tbsysCurrency]			sc	WITH (NOLOCK)
			on	sc.[curr_id]		= tm.[curr_id]

			inner join dbo.[tbCommercialTransactions] ct	WITH (NOLOCK)
			on	ct.[comp_id]		= tm.[comp_id]
			and ct.[bra_id]			= tm.[bra_id]
			and ct.[ct_transaction] = tm.[ct_transaction]

	WHERE 	not tm.[ct_transaction] is NULL


UNION	ALL


/****************************************************************************************/
/***   CHEQUES PROPIOS EMITIDOS  ********************************************************/
/****************************************************************************************/
SELECT	tec.comp_id													,
		tec.bra_id													,
		tec.bra_id									[bra_id_PortFolio],
		tec.ct_transaction											,
		'7'											[class]			,
		sov.lang_id									[lang_id]		,
		sov.optval_desc								[description]	,
		tba.ba_desc									[type]			,
		tec.ec_Total								[amount]		,
		c.curr_desc									[currency]		,
		c.curr_symbol								[curr_symbol]	,
		tec.curr_id									[curr_id]		,
		tec.ec_Note									[desc]			,
		tec.ec_exchangeToBranchCurrency				[CurrencyExchange],
		'false'										[chp_isRejected],
		tec.ec_PayDate								[Date],
		tec.ba_id,
		-1											[tm_transaction],
		tec.ec_id									[ID],
		-1											[cc_id],
		-1											[ccp_id],
		-1											[chp_id],
		tec.ec_id									[ec_id],
		tec.ba_id									[ba_id],
		-1												[ccm_id]


FROM	tbEmmitedChecks								tec	WITH (NOLOCK)

		inner join dbo.[tbsysOptionsValues]			sov		WITH (NOLOCK)
		on	sov.optval_id		=	7
		and sov.optval_class	=	40

		INNER JOIN dbo.tbBankingAccounts			tba		WITH (NOLOCK)
		ON	tba.comp_id			=	tec.comp_id
		AND	tba.ba_id			=	tec.ba_id

		left join dbo.[tbsysCurrency]				c		WITH (NOLOCK)
		on	c.curr_id			=	tba.curr_id

WHERE 	not tec.[ct_transaction] is NULL
/****************************************************************************************/


-- =================================================================================================================
-- Parte		: 723
UNION	ALL


/****************************************************************************************/
/***   CHEQUES DE TERCEROS   ************************************************************/
/****************************************************************************************/
SELECT	tcpm.comp_id													,
		tcpm.bra_id														,
		tcpm.bra_id									[bra_id_PortFolio],
		tcpm.ct_transaction												,
		'10'										[class]				,
		sov.lang_id									[lang_id]			,
		sov.optval_desc								[description]		,
		'Nº:' + tcp1.chp_number						[type]				,
		tcp1.chp_total								[amount]			,
		c.curr_desc									[currency]			,
		c.curr_symbol								[curr_symbol]		,
		tcp1.curr_id								[curr_id]			,
		tcp1.chp_Note								[desc]				,
		tcp1.chp_BranchCurrencyExchange				[CurrencyExchange]	,
		'false'										[chp_isRejected],
		tcp1.chp_PayDate							[Date],
		10,
		-1											[tm_transaction],
		tcp1.chp_id									[ID],
		-1											[cc_id],
		-1											[ccp_id],
		tcp1.chp_id									[chp_id],
		-1											[ec_id],
		-1											[ba_id],
		-1												[ccm_id]


FROM	tbCheckPortfolioMovements					tcpm	WITH (NOLOCK)

		INNER JOIN tbCheckPortfolio					tcp1		WITH (NOLOCK)
		ON	tcp1.comp_id		= tcpm.comp_id
		AND tcp1.chp_id			= tcpm.chp_id

		INNER JOIN tbCommercialTransactions			tct		WITH (NOLOCK)
		ON	tct.ct_transaction	= tcpm.ct_transaction
		AND tct.comp_id			= tcpm.comp_id
		AND tct.bra_id			= tcpm.bra_id
		AND not tct.supp_id		IS NULL


		inner join dbo.[tbsysOptionsValues]			sov		WITH (NOLOCK)
		on	sov.optval_id		=	10
		and sov.optval_class	=	40

		left join dbo.[tbsysCurrency]				c		WITH (NOLOCK)
		on	c.curr_id			=	tcp1.curr_id

--WHERE 	not tec.[ct_transaction] is NULL
/****************************************************************************************/
-- =================================================================================================================


UNION ALL



/****************************************************************************************/
/***   Cuenta Contable*******************************************************************/
/****************************************************************************************/
SELECT 	tam.comp_id,
		tct.bra_id,
		tct.bra_id										[bra_id_PortFolio],
		tam.ct_transaction,
		'6'												[class],
		sov.lang_id										[lang_id],
		sov.optval_desc									[description],
		ta.acc_desc										[type],
		tam.atcm_total									[amount],
		c.curr_desc										[currency],
		c.[curr_symbol]									[curr_symbol],
		c.curr_id										[curr_id],
		''												[desc],
		1												[CurrencyExchange],
		'false'											[chp_isRejected],
		tct.ct_date										[Date],
		6												[GroupClass],
		-1												[tm_transaction],
		tam.atcm_id										[ID],
		-1												[cc_id],
		-1												[ccp_id],
		-1												[chp_id],
		-1												[ec_id],
		-1												[ba_id],
		-1												[ccm_id]


FROM 	dbo.tbAccountantMovements AS tam 						WITH (NOLOCK)

		INNER JOIN tbAccountant					 AS ta				WITH (NOLOCK)
			ON	ta.comp_id		= tam.comp_id AND
				ta.acc_count_id = tam.acc_count_id
		INNER JOIN tbCommercialTransactions tct					WITH (NOLOCK)
			ON	tct.comp_id			= tam.comp_id AND
				tct.ct_transaction	= tam.ct_transaction
		inner join dbo.[tbsysOptionsValues]				sov		WITH (NOLOCK)
			ON 	sov.optval_id			= 6
			AND sov.optval_class		= 40

		left join dbo.[tbsysCurrency]					c		WITH (NOLOCK)
			on	c.curr_id				= tam.curr_id

WHERE 	not tam.ct_transaction		is Null
/****************************************************************************************/




GO




CREATE view [dbo].[vwCollectionTmp]	--   NO PONERWITH SCHEMABINDING
as


select	'1'											[class],
		sov.lang_id									[lang_id],
		sov.optval_desc								[description],
		cmt.cmt_guid								[guid],
		ca.ca_desc									[type],
		cmt.cmt_amount								[amount],
		c.curr_desc									[currency],
		c.curr_id									[curr_id],
		cmt.cmt_desc								[desc],
		GETDATE()									[payDate],
		cmt.cmt_id									[ID]

from	dbo.tbCashMovementsTmp						cmt				WITH (NOLOCK)

		inner join dbo.tbsysOptionsValues			sov				WITH (NOLOCK)
		on	sov.optval_id		= 1
		and sov.optval_class	= 40

		left join dbo.tbCashNumbers					cn				WITH (NOLOCK)
		on cn.comp_id	= cmt.comp_id
		and cn.cn_id	= cmt.cn_id

		left join dbo.tbCashAccountant				ca				WITH (NOLOCK)
		on ca.comp_id	= cmt.comp_id
		and ca.ca_id	= cmt.ca_id

		left join dbo.tbsysCurrency				c					WITH (NOLOCK)
		on	c.curr_id	= cmt.curr_id


union



select	'2'											[class],
		sov.lang_id									[lang_id],
		sov.optval_desc								[description],
		chpt.chpt_guid								[guid],
		convert(varchar,chpt.chpt_isOwn)			[type],
		chpt.chpt_total								[amount],
		c.curr_desc									[currency],
		c.curr_id									[curr_id],
		bn.bn_name + '- Nº:' + chpt.chpt_number		[desc],
		CHPT.chpt_PayDate							[payDate],
		chpt.chpt_id								[ID]

from	dbo.tbCheckPortfolioTmp						chpt			WITH (NOLOCK)

		inner join dbo.tbsysOptionsValues			sov				WITH (NOLOCK)
		on	sov.optval_id		= 2
		and sov.optval_class	= 40

		left join dbo.tbBanksName					bn				WITH (NOLOCK)
		on bn.comp_id			= chpt.comp_id
		and bn.bn_id			= chpt.bn_id

		left join dbo.tbsysCurrency				c					WITH (NOLOCK)
		on	c.curr_id			= chpt.curr_id

where	chpt.chpt_isDocument	= 'False'



union



select	'3'													[class],
		sov.lang_id											[lang_id],
		sov.optval_desc										[description],
		chpt.chpt_guid										[guid],
		'Doc. - ' + convert(varchar,chpt.chpt_number)		[type],
		chpt.chpt_total										[amount],
		c.curr_desc											[currency],
		c.curr_id											[curr_id],
		chpt_DocumentDescription							[desc],
		CHPT.chpt_PayDate									[payDate],
		chpt.chpt_id										[ID]

from	dbo.tbCheckPortfolioTmp								chpt		WITH (NOLOCK)

		inner join dbo.tbsysOptionsValues					sov			WITH (NOLOCK)
		on	sov.optval_id		= 3
		and sov.optval_class	= 40

		left join dbo.tbsysCurrency						c				WITH (NOLOCK)
		on	c.curr_id	= chpt.curr_id

where	chpt.chpt_isDocument = 'True'



union



select	'4'													[class],
		sov.lang_id											[lang_id],
		sov.optval_desc										[description],
		ccmt.ccmt_guid										[guid],
		convert(varchar,cc.cc_desc)							[type],
		ccmt.ccmt_Total										[amount],
		c.curr_desc											[currency],
		c.curr_id											[curr_id],
		substring(ccmt.ccmt_cardNumber,1,4) + '-' +
		substring(ccmt.ccmt_cardNumber,5,4) + '-' +
		substring(ccmt.ccmt_cardNumber,9,4) + '-' +
		substring(ccmt.ccmt_cardNumber,13,4) 				[desc],
		GETDATE()											[payDate],
		ccmt.ccmt_id										[ID]


from	dbo.tbCreditCardMovementsTmp						ccmt			WITH (NOLOCK)

		inner join dbo.tbsysOptionsValues					sov				WITH (NOLOCK)
		on	sov.optval_id		= 4
		and sov.optval_class	= 40

		left join 	dbo.tbCreditCard						cc				WITH (NOLOCK)
		on cc.comp_id			= ccmt.comp_id
		and cc.cc_id			= ccmt.cc_id

		left join dbo.tbsysCurrency							c				WITH (NOLOCK)
		on c.curr_id			= cc.curr_id



union



select	'5'											[class],
		sov.lang_id									[lang_id],
		sov.optval_desc								[description],
		btt.btt_guid								[guid],
		dbo.fnStrAllTrim(IsNull(btty.btt_desc,'')) + ' ' +
		CASE
			WHEN tbvbtc.v4c_id IS NOT NULL  THEN 'VOU:' + ISNULL(tbvbtc.v4c_transactionNumber,'') + ' ' + CONVERT(NVARCHAR,tbvbtc.v4c_transferDate,106)
			ELSE ''
		END
													[type],
		btt.btt_total								[amount],
		c.curr_desc									[currency],
		c.curr_id									[curr_id],
		ba.ba_desc									[desc],
		btt.btt_imputationDate						[payDate],
		btt.bttmp_id								[ID]

from	dbo.tbBankingTransactionsTmp				btt						WITH (NOLOCK)

		inner join dbo.tbsysOptionsValues			sov						WITH (NOLOCK)
		on	sov.optval_id		= 5
		and sov.optval_class	= 40

		LEFT JOIN dbo.tbBankingVouchers4BanckTransferCollection tbvbtc		WITH (NOLOCK)
			ON	tbvbtc.comp_id	= btt.comp_id AND
				tbvbtc.v4c_id	= btt.v4c_id

		left join dbo.tbBankingAccounts				ba						WITH (NOLOCK)
		on ba.comp_id	= btt.comp_id
		and ba.ba_id	= btt.ba_id

		left join dbo.tbBankingTransactionTypes		btty					WITH (NOLOCK)
		on btty.comp_id	= btt.comp_id
		and btty.btt_id	= btt.btt_id

		left join dbo.tbsysCurrency				c							WITH (NOLOCK)
		on	c.curr_id	= btt.curr_id


UNION


select	'6'											[class],
		sov.lang_id									[lang_id],
		sov.optval_desc								[description],
		tamt.atcmTmp_guid							[guid],
		ta.acc_desc									[type],
		tamt.atcm_total								[amount],
		c.curr_desc									[currency],
		c.curr_id									[curr_id],
		tamt.atcm_reference							[desc],
		GETDATE()									[payDate],
		tamt.atcmTmp_id								[ID]

from	dbo.tbAccountantMovementsTMP				AS tamt				WITH (NOLOCK)

		inner join dbo.tbsysOptionsValues			sov					WITH (NOLOCK)
		on	sov.optval_id		= 6
		and sov.optval_class	= 40

		INNER JOIN dbo.tbAccountant					 AS ta				WITH (NOLOCK)
			ON	ta.comp_id		= tamt.comp_id AND
				ta.acc_count_id = tamt.acc_count_id

		left join dbo.tbsysCurrency				c						WITH (NOLOCK)
		on	c.curr_id	= tamt.curr_id





GO






-- MOS  09-2008
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas

CREATE VIEW [dbo].[vwCommercialTransactions_forBanking]
AS
SELECT			 A.comp_id,
				 A.bra_id,
				 A.ct_transaction,
                 B.sd_isCredit,
				 B.sd_isQuotation,
                 B.sd_isReceipt,
                 B.sd_isTaxable,
                 B.sd_isInBalance,
				 A.supp_id,
				 A.cust_id
	FROM         dbo.tbCommercialTransactions A
	INNER JOIN   dbo.tbsysDocuments			  B			WITH (NOLOCK)
			ON   A.sd_id = B.sd_id
	WHERE   B.sd_isBanking = 'True'

GO





-- STL
-- 05-04-2010
-- Union de tbCommercialTransactions + tbsysDocuments (Liq. de Tarjeta + Dep. en Efectivo + Mov. de Crédito y Débito)
CREATE VIEW [dbo].[vwCommercialTransactions_forBankingTransactions]
AS

	SELECT
		td.sd_id,
		tct.ct_transaction,
		td.sd_isCredit,
		1					[Is_Paid],
		tct.ba_id

	FROM tbCommercialTransactions tct

		INNER JOIN tbsysDocuments td
		ON td.sd_id = tct.sd_id

	WHERE
		tct.sd_id IN (140,	--Imputaciones Bancarias - (Entrada)
					  141,	--Imputaciones Bancarias - (Salida)
					  142)	--Liquidación de T. de Crédito

--
--	/*Esto hace referencia a las Liquidaciones de Tarjeta de Crédito y a los Depósitos en Efectivo*/
--		(tct.sd_id = 140)
--	OR	(tct.sd_id = 141)
--	OR	(tct.sd_id = 142)
--	/*--------------Acá hacemos referencia a los Movimientos de Crédito y de Débito---------------*/
--	OR	((tct.sd_id BETWEEN 200 AND 299))


GO












-- MOS  09-2008
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas

CREATE VIEW [dbo].[vwCommercialTransactions_forPurchase]	WITH SCHEMABINDING
AS
SELECT			 A.comp_id,
				 A.bra_id,
				 A.ct_transaction,
                 B.sd_isCredit,
				 B.sd_isQuotation,
                 B.sd_isReceipt,
                 B.sd_isTaxable,
                 B.sd_isInBalance,
				 A.supp_id,
				 A.cust_id,
				 A.sd_id,
				 B.sd_isAnnulment,
				 b.sd_plusOrminus					[PlusOrMinus]	-- MOS 05-2021 x Speed
				 --CASE WHEN b.sd_isCredit='true' THEN -1 ELSE 1 END [PlusOrMinus]
	FROM         dbo.tbCommercialTransactions A
	INNER JOIN   dbo.tbsysDocuments			  B			--WITH (NOLOCK) MOS 08-2023 para q ande con el nuevo indice de la vista
			ON   A.sd_id = B.sd_id
	WHERE   B.sd_isPurchase  = 'True'
		AND b.sd_isInBalance = 'True'
		AND A.sd_id IN (101,103,104,106,130,140,141,142,121,123,125,131,151,152,153,154,156,161,162,163,164,166,180,190,128,129)



GO








-- MOS  09-2008
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas

CREATE VIEW [dbo].[vwCommercialTransactions_forPurchase_All]
