-- MOS  09-2008
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas

CREATE VIEW [dbo].[vwCommercialTransactions_forPurchase_TaxEngine] WITH SCHEMABINDING
AS
SELECT			 A.comp_id,
				 A.bra_id,
				 A.ct_transaction,
                 B.sd_isCredit,
				 B.sd_isQuotation,
                 B.sd_isReceipt,
                 B.sd_isTaxable,
                 B.sd_isInBalance,
				 A.supp_id,
				 A.cust_id,
				 A.sd_id,
				 B.sd_isAnnulment,
				 b.sd_plusOrminus					[PlusOrMinus]	-- MOS 05-2021 x Speed
				 --CASE WHEN b.sd_isCredit='true' THEN -1 ELSE 1 END [PlusOrMinus]
	FROM         dbo.tbCommercialTransactions A
	INNER JOIN   dbo.tbsysDocuments			  B
		ON   A.sd_id			= B.sd_id
	INNER JOIN dbo.tbBranch tb
		ON		tb.comp_id		= a.comp_id
			AND tb.bra_id		= a.bra_id
	WHERE   B.sd_isPurchase		= 'True'

		AND	(
				  A.sd_id  IN (101,103,104,106,130,131/*MOS 07-2017*/, /* + L.Tarjeta de Credito*/142, /* Extracto Bancario (Resumen) */ 143,144 /* Se agrego por lio en NUCLEO con extractos resumen mal cargados, solo ellos lo usan*/ )
			  OR
				--( A.sd_id  IN (140,141,142) AND IsNull(tb.bra_Reports_TaxEngine4Purchase_IncludeBanking,'False') = 'True')
				  ( A.sd_id  IN (140,141) AND tb.bra_Banks_InputOutputCharges_DisableInTaxEngine='False' )
			)



GO







/*
Es igual que vwCommercialTransactions_forPurchase pero que filtra sólo las notas de crédito
*/

CREATE VIEW [dbo].[vwCommercialTransactions_forPurchaseCreditNotes]
AS

SELECT		A.comp_id			,
			A.bra_id			,
			A.ct_transaction	,
			B.sd_isCredit		,
			B.sd_isQuotation	,
			B.sd_isReceipt		,
			B.sd_isTaxable		,
			B.sd_isInBalance	,
			A.supp_id			,
			A.cust_id

FROM        dbo.tbCommercialTransactions		A			WITH (NOLOCK)

			INNER JOIN dbo.tbsysDocuments		B			WITH (NOLOCK)
			ON		A.sd_id		=	B.sd_id

WHERE		B.sd_isPurchase		=	'True'
AND			B.sd_id				=	103


GO





-- MOS  09-2008
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas

--  SI SE MODIFICA ESTA VISTA HAY QUE CREAR NUEVAMENTE ESTE INDICE PARA dbGBP
--  El actualizador ejecuta el sp spSystem_GenerateIndexViews que las crea automaticamente en caso de ser necesarias.-
--	CREATE UNIQUE CLUSTERED INDEX CIX_vwCommercialTransactions_forSalesII
--		ON vwCommercialTransactions_forSales( comp_id, ct_transaction)

CREATE VIEW [dbo].[vwCommercialTransactions_forSales] WITH SCHEMABINDING
AS
SELECT			 A.comp_id,
				 A.bra_id,
				 A.ct_transaction,
                 B.sd_isCredit,
				 B.sd_isQuotation,
                 B.sd_isReceipt,
                 B.sd_isTaxable,
                 B.sd_isInBalance,
				 B.sd_isPackingList,
				 A.supp_id,
				 A.cust_id,
				 A.sd_id,
				 B.sd_isAnnulment,
				 -- Para no tener que hacer otro join con tbsysdocuments si ya lo hace aca
				 -- y poder multiplicar directamente por este campo.-
				 b.sd_plusOrminus					[PlusOrMinus]	-- MOS 05-2021 x Speed
				 --CASE
					--WHEN b.sd_isCredit='true' THEN -1
					--ELSE							1
				 --END								[PlusOrMinus]

	FROM         dbo.tbCommercialTransactions A				--WITH (NOLOCK)
	INNER JOIN   dbo.tbsysDocuments			  B				--WITH (NOLOCK)
			ON   B.sd_id = A.sd_id
	WHERE	B.sd_isSales	 = 'True'
		And B.sd_isInBalance = 'True'
		And ((A.cust_id IS NOT NULL) or (A.supp_id IS NOT NULL))
		and A.ct_docNumber <> ''


GO





-- MOS  09-2008
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas

CREATE VIEW [dbo].[vwCommercialTransactions_forSales_TaxEngine] WITH SCHEMABINDING
AS
SELECT			 A.comp_id,
				 A.bra_id,
				 A.ct_transaction,
                 B.sd_isCredit,
				 B.sd_isQuotation,
                 B.sd_isReceipt,
                 B.sd_isTaxable,
                 B.sd_isInBalance,
				 B.sd_isPackingList,
				 A.supp_id,
				 A.cust_id,
				 A.sd_id,
				 B.sd_isAnnulment,
				 -- Para no tener que hacer otro join con tbsysdocuments si ya lo hace aca
				 -- y poder multiplicar directamente por este campo.-
				 b.sd_plusOrminus					[PlusOrMinus]	-- MOS 05-2021 x Speed
				 --CASE WHEN b.sd_isCredit='true' THEN -1 ELSE 1 END [PlusOrMinus]

	FROM         dbo.tbCommercialTransactions A
	INNER JOIN	 dbo.tbDocumentsFile		  tdf
		ON	tdf.comp_id = A.comp_id AND
			tdf.bra_id	= A.bra_id	AND
			tdf.df_id	= A.df_id
	INNER JOIN   dbo.tbsysDocuments			  B
			ON   B.sd_id = A.sd_id
	WHERE	B.sd_isSales	 = 'True'
		And B.sd_isInBalance = 'True'
		And ((A.cust_id IS NOT NULL) or (A.supp_id IS NOT NULL))
		and A.ct_docNumber <> ''
		AND
			(
				A.sd_id IN (1,3,4,6,13,31,33,43,44)
				OR
				tdf.df_taxEngineForceInclude = 'True'
			)





GO









-- MOS  05-2009
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas (Comprobantes de VENTAS, para estadisticas)  OJO!!!!!

CREATE VIEW [dbo].[vwCommercialTransactions_forSalesStats] WITH SCHEMABINDING
AS
SELECT			 A.comp_id,
				 A.bra_id,
				 A.ct_transaction,
                 B.sd_isCredit,
				 B.sd_isQuotation,
                 B.sd_isReceipt,
                 B.sd_isTaxable,
                 B.sd_isInBalance,
				 B.sd_isPackingList,
				 A.supp_id,
				 A.cust_id,
				 A.sd_id,
				 -- Para no tener que hacer otro join con tbsysdocuments si ya lo hace aca
				 -- y poder multiplicar directamente por este campo.-
				 --CASE WHEN b.sd_isCredit='true' THEN -1 ELSE 1 END [PlusOrMinus]
				 b.sd_plusOrminus					[PlusOrMinus]	-- MOS 05-2021 x Speed

	FROM         dbo.tbCommercialTransactions A
	INNER JOIN   dbo.tbsysDocuments			  B			--WITH (NOLOCK)
			ON   A.sd_id = B.sd_id
	WHERE   B.sd_isPurchase = 'False'
		And B.sd_isQuotation = 'False'
		And ((A.cust_id IS NOT NULL) or (A.supp_id IS NOT NULL))
		and A.ct_docNumber <> ''
		AND B.sd_isReceipt = 'False'
		and b.sd_isInBalance = 'True'


GO


-- MOS  05-2009
-- Solo se ven las Ventas, se usa para hacer inner join con tbCommercialTransactions
-- y asi filtrar solo ventas (Comprobantes de VENTAS, para estadisticas)  OJO!!!!!

CREATE VIEW [dbo].[vwCommercialTransactions_forSalesStatsPlusPackingList] WITH SCHEMABINDING
AS
SELECT			 A.comp_id,
				 A.bra_id,
				 A.ct_transaction,
                 B.sd_isCredit,
				 B.sd_isQuotation,
                 B.sd_isReceipt,
                 B.sd_isTaxable,
                 B.sd_isInBalance,
				 B.sd_isPackingList,
				 A.supp_id,
				 A.cust_id,
				 -- Para no tener que hacer otro join con tbsysdocuments si ya lo hace aca
				 -- y poder multiplicar directamente por este campo.-
				 --CASE WHEN b.sd_isCredit='true' THEN -1 ELSE 1 END [PlusOrMinus]
				 b.sd_plusOrminus					[PlusOrMinus]	-- MOS 05-2021 x Speed

	FROM         dbo.tbCommercialTransactions A
	INNER JOIN   dbo.tbsysDocuments			  B
			ON   A.sd_id = B.sd_id
	WHERE   B.sd_isPurchase = 'False'
		And B.sd_isQuotation = 'False'
		And ((A.cust_id IS NOT NULL) or (A.supp_id IS NOT NULL))
		and A.ct_docNumber <> ''
		AND B.sd_isReceipt = 'False'
		and (
				b.sd_isInBalance	= 'True'	OR
				A.sd_id				= 2			OR
				A.sd_id				= 12			--#16082018STL agregado para Authogar porque no le traía los Remitos de Entrada
			)



GO




-- MOS  09-2008
-- Relacion entre Facturas y Remitos Pendientes de Facturar
--


CREATE VIEW [dbo].[vwCommercialTransactions_PackingInvoicePending_InvoiceRelation] WITH SCHEMABINDING
AS


	SELECT	tctn.comp_id,
			tctn.ct_transaction	[ct_transaction_invoice],
			tit.it_transaction	[it_transaction_invoice],
			tit2.ct_transaction [ct_transaction_packingListOriginal],
			tit2.it_transaction [it_transaction_packingListOriginal]
		FROM dbo.tbCommercialTransactions AS tctn				WITH (NOLOCK)
		INNER JOIN dbo.tbItemTransactions AS tit				WITH (NOLOCK)
			ON  tit.comp_id			= tctn.comp_id	AND
				tit.bra_id			= tctn.bra_id	AND
				tit.ct_transaction	= tctn.ct_transaction
		INNER JOIN dbo.tbItemTransactions AS tit2				WITH (NOLOCK)
			ON	tit2.comp_id		= tit.comp_id AND
				tit2.it_transaction = tit.it_transaction_original
		WHERE tctn.sd_id = 1


GO










CREATE VIEW [dbo].[vwCommercialTransactions_PaymentOnAccount] WITH SCHEMABINDING
AS


SELECT	A.comp_id,
		A.bra_id,
		A.ct_transaction,
		B.sd_isCredit,
		B.sd_isQuotation,
		B.sd_isReceipt,
		B.sd_isTaxable,
		B.sd_isInBalance,
		B.sd_isPackingList,
		A.supp_id,
		A.cust_id

FROM	dbo.tbCommercialTransactions		A

		INNER JOIN	dbo.tbsysDocuments		B
		ON   A.sd_id = B.sd_id

WHERE   (
			((B.[sd_isCredit]		= 'True' OR b.sd_isReceipt = 'True')
and			B.[sd_isInBalance]		= 'True'
and			B.[sd_isPurchase]		= 'True'
			)
			or

			((B.[sd_isCredit]		= 'True' OR b.sd_isReceipt = 'True')
	and		B.[sd_isInBalance]		= 'True'
	and		B.[sd_isPurchase]		= 'False'
			)
		)

and		((A.cust_id IS NOT NULL)	or (A.supp_id IS NOT NULL))
and		A.ct_docNumber		<> ''



GO








CREATE VIEW [dbo].[vwCommercialTransactions_PaymentsWithEmmitedCheque] WITH SCHEMABINDING
AS




	SELECT	tct.comp_id,
			tct.ct_transaction,
			SUM(tec.ec_Total)	[ct_totalEC],
			COUNT_BIG(*)		[dummy4Index]
		FROM dbo.tbCommercialTransactions tct
		INNER JOIN dbo.tbEmmitedChecks tec
			ON	tec.comp_id			= tct.comp_id AND
				tec.ct_transaction	= tct.ct_transaction
		WHERE tct.sd_id = 106
		GROUP BY tct.comp_id,tct.ct_transaction

GO



CREATE VIEW [dbo].[vwCommercialTransactions_PaymentsWithRetentions] WITH SCHEMABINDING
AS


	SELECT	tct.comp_id,
			tct.ct_transaction,
			SUM(ISNULL(ttm.tm_total,0))	[ct_totalRET],
			COUNT_BIG(*)			[dummy4Index]
		FROM dbo.tbCommercialTransactions tct
		INNER JOIN dbo.tbTaxMovements ttm
			ON	ttm.comp_id			= tct.comp_id	AND
				ttm.ct_transaction	= tct.ct_transaction
		INNER JOIN dbo.tbTaxName AS ttn
			ON	ttn.tax_id			= ttm.tax_id	AND
				ttn.comp_id			= ttm.comp_id
		--INNER JOIN dbo.tbsysTaxClass AS ttc
		--	ON	ttc.tax_class		= ttn.tax_class
		WHERE	tct.sd_id = 106						AND
				ttn.tax_class BETWEEN 200 AND 299		-- Se saco lo que esta REM ya que molestaba con el actualizador ya que trataba de borrar datos de tbsysTaxClass que estaban en una vista INDEXADA ( Esta Vista )
				--ttc.taxcl_isRetention = 'True'
		GROUP BY tct.comp_id,tct.ct_transaction

GO





-- MOS  03-2009
-- Trae las Facturas Aplicadas por la ct_transaction de una OP con los % aplicados y la fecha de la OP
-- MOS  03-2010

CREATE VIEW [dbo].[vwCommercialTransactions_PayOrdersApplications2Invoices]
AS

SELECT			 PayOrd.ct_taxDate  [PaymentDate],
				 Invoices.comp_id,
				 Invoices.ct_transaction,
				 Invoices.supp_id,
				 Appl.appl_coef,
				 Appl.appl_total,
				 Appl.ct_transaction_destiny

	FROM         dbo.tbCommercialTransactions									PayOrd		WITH (NOLOCK)
	INNER JOIN   dbo.tbsysDocuments												SysDoc		WITH (NOLOCK)
			ON   PayOrd.sd_id				= SysDoc.sd_id
	INNER JOIN   dbo.tbApplication												Appl		WITH (NOLOCK)
		ON		Appl.comp_id				= PayOrd.comp_id
			AND Appl.ct_transaction_Destiny	= PayOrd.ct_transaction
	INNER JOIN   dbo.tbCommercialTransactions									Invoices	WITH (NOLOCK)
		ON		Invoices.comp_id			= Appl.comp_id
			AND Invoices.ct_transaction		= Appl.ct_transaction_Source

	WHERE		SysDoc.sd_isCredit   = 'true'
			AND SysDoc.sd_isReceipt  = 'true'
			AND SysDoc.sd_isPurchase = 'true'
			AND PayOrd.sd_id = 106






GO






-- MOS  09-2008
-- Relacion entre Facturas ANTICIPADAS y Remitos
--


CREATE VIEW [dbo].[vwCommercialTransactions_preInvoice_PackingListRelation] WITH SCHEMABINDING
AS


-- Remitos de Facturas Anticipadas con su HIstorial
SELECT	tctn.comp_id,
		tctn.bra_id,
		tctn.ct_transaction	[ct_transaction_preInvoice],
		tit.it_transaction  [it_transaction_preInvoice],
		tit2.ct_transaction [ct_transaction_packingList],
		tit2.it_transaction	[it_transaction_packingList],
		tit2.it_soh_id		[soh_id],
		tit2.it_sod_id		[sod_id],
		tsodh.sod_initQty	[sod_initialQTY],
		ISNULL(tsodh.sod_initQty,0) - ISNULL(tsodh.sod_qty,0)
							[sod_pendingQTY],
		tsohh.sohh_id		[sohh_id],
		1					[unionType]

	FROM		dbo.tbCommercialTransactions	AS tctn		WITH (NOLOCK)
	INNER JOIN	dbo.tbDocumentsFile				AS tdf		WITH (NOLOCK)
		ON	tdf.comp_id					= tctn.comp_id		AND
			tdf.bra_id					= tctn.bra_id		AND
			tdf.df_id					= tctn.df_id
	INNER JOIN	dbo.tbItemTransactions			AS tit		WITH (NOLOCK)
		ON  tit.comp_id					= tctn.comp_id		AND
			tit.bra_id					= tctn.bra_id		AND
			tit.ct_transaction			= tctn.ct_transaction
	INNER JOIN  dbo.tbItemTransactions			AS tit2		WITH (NOLOCK)
		ON	tit2.comp_id				= tit.comp_id		AND
			tit2.it_soh_id				= tit.it_soh_id		AND
			tit2.it_sod_id				= tit.it_sod_id
	LEFT JOIN dbo.tbSaleOrderHeaderHistory		AS tsohh	WITH (NOLOCK)
		ON	tsohh.comp_id				= tit2.comp_id		AND
			tsohh.bra_id				= tit2.bra_id		AND
			tsohh.soh_id				= tit2.it_soh_id	AND
			tsohh.sohh_TypeOfHistory	= 10				AND
			tsohh.sohh_isPackingOfPreInvoice = 'True'
	LEFT JOIN dbo.tbSaleOrderDetailHistory		AS tsodh	WITH (NOLOCK)
		ON	tsodh.comp_id				= tsohh.comp_id		AND
			tsodh.bra_id				= tsohh.bra_id		AND
			tsodh.soh_id				= tsohh.soh_id		AND
			tsodh.sohh_id				= tsohh.sohh_id		AND
			tsodh.sod_id				= tit2.it_sod_id
	WHERE	tctn.sd_id = 1									AND				-- Es Factura
			tdf.df_SaleOrder_InvoiceFirstPacking_df_id  IS NOT NULL AND		-- es Factura Anticipada
			tit2.ct_transaction <> tit.ct_transaction


	UNION

-- Facturas Anticipadas con su Pedido de Remito
SELECT	tctn.comp_id,
		tsod.bra_id,
		tctn.ct_transaction	[ct_transaction_preInvoice],
		tit.it_transaction  [it_transaction_preInvoice],
		NULL				[ct_transaction_packingList],
		NULL				[it_transaction_packingList],
		tsod.soh_id			[soh_id],
		tsod.sod_id			[sod_id],
		tsod.sod_initQty	[sod_initialQTY],
		tsod.sod_qty		[sod_pendingQTY],
		NULL				[sohh_id],
		2					[unionType]
	FROM		dbo.tbCommercialTransactions	AS tctn		WITH (NOLOCK)
	INNER JOIN	dbo.tbItemTransactions			AS tit		WITH (NOLOCK)
		ON  tit.comp_id			= tctn.comp_id	AND
			tit.bra_id			= tctn.bra_id	AND
			tit.ct_transaction	= tctn.ct_transaction
	INNER JOIN dbo.tbSaleOrderDetail			AS tsod		WITH (NOLOCK)
		ON	tsod.comp_id	= tit.comp_id		AND
			tsod.soh_id		= tit.it_soh_id		AND
			tsod.sod_id		= tit.it_sod_id
	INNER JOIN dbo.tbSaleOrderHeader			AS tsoh		WITH (NOLOCK)
		ON	tsoh.comp_id	= tsod.comp_id		AND
			tsoh.bra_id		= tsod.bra_id		AND
			tsoh.soh_id		= tsod.soh_id
	INNER JOIN	dbo.tbDocumentsFile				AS tdf2		WITH (NOLOCK)
		ON	tdf2.comp_id = tsoh.comp_id			AND
			tdf2.bra_id	 = tsoh.bra_id			AND
			tdf2.df_id	 = tsoh.df_id
	WHERE	tctn.sd_id								= 1		AND		-- Es Factura
			tdf2.df_SaleOrder_IsInvoiceFirstPacking = 'True'		-- Es Pedido de Remito de Fc Anticipada



UNION

-- Pedido de Factura Anticipada con Factura PENDIENTE de emitir
SELECT	tsoh.comp_id,
		tsoh.bra_id,
		NULL				[ct_transaction_preInvoice],
		NULL				[it_transaction_preInvoice],
		NULL				[ct_transaction_packingList],
		NULL				[it_transaction_packingList],
		tsod.soh_id			[soh_id],
		tsod.sod_id			[sod_id],
		tsod.sod_initQty	[sod_initialQTY],
		tsod.sod_qty		[sod_pendingQTY],
		NULL				[sohh_id],
		3					[unionType]
	FROM	dbo.tbSaleOrderDetail				AS tsod		WITH (NOLOCK)
	INNER JOIN dbo.tbSaleOrderHeader			AS tsoh		WITH (NOLOCK)
		ON	tsoh.comp_id	= tsod.comp_id		AND
			tsoh.bra_id		= tsod.bra_id		AND
			tsoh.soh_id		= tsod.soh_id
	INNER JOIN	dbo.tbDocumentsFile				AS tdf2		WITH (NOLOCK)
		ON	tdf2.comp_id = tsoh.comp_id			AND
			tdf2.bra_id	 = tsoh.bra_id			AND
			tdf2.df_id	 = tsoh.df_id
	WHERE	tdf2.sd_id								= 1		AND			-- Es Factura
			tdf2.df_SaleOrder_InvoiceFirstPacking_df_id  IS NOT NULL	-- Es Pedido de Remito de Fc Anticipada


GO




CREATE view [dbo].[vwCommercialTransactionsProfitAndMarckup]
AS


SELECT	tct.comp_id,
		tct.bra_id,
		tct.ct_transaction,
		--tit.it_transaction,
		dbo.fnGetMarkUp( Sum(tit.it_qty * tit.it_priceOfCost),Sum(tit.it_qty * tit.it_price))		[MarkUp],
		dbo.fnGetProfit( Sum(tit.it_qty * tit.it_priceOfCost),Sum(tit.it_qty * tit.it_price))		[Profit],
		dbo.fnGetMarkUp( Sum(tit.it_qty * tit.it_priceBOfCost),Sum(tit.it_qty * tit.it_price))		[MarkUpB],
		dbo.fnGetProfit( Sum(tit.it_qty * tit.it_priceBOfCost),Sum(tit.it_qty * tit.it_price))		[ProfitB],
		dbo.fnGetMarkUp( Sum(tit.it_qty * tit.it_priceOfCostPP),Sum(tit.it_qty * tit.it_price))		[MarkUpPPPP],
		dbo.fnGetProfit( Sum(tit.it_qty * tit.it_priceOfCostPP),Sum(tit.it_qty * tit.it_price))		[ProfitPPP],
		dbo.fnGetMarkUp( Sum(tit.it_qty * tit.it_priceBOfCostPP),Sum(tit.it_qty * tit.it_price))	[MarkUpBPPPP],
		dbo.fnGetProfit( Sum(tit.it_qty * tit.it_priceBOfCostPP),Sum(tit.it_qty * tit.it_price))	[ProfitBPPP],
		Sum(tit.it_qty * tit.it_priceOfCost)	[SumOfCost],
		Sum(tit.it_qty * tit.it_priceOfCostPP)	[SumOfCostPP],
		Sum(tit.it_qty * tit.it_priceBOfCost)	[SumOfCostB],
		Sum(tit.it_qty * tit.it_priceBOfCostPP)	[SumOfCostBPP],
		Sum(tit.it_qty * tit.it_price)			[SumOfSale]
	FROM tbCommercialTransactions tct							WITH (NOLOCK)
	INNER JOIN tbItemTransactions tit							WITH (NOLOCK)
		ON		tit.comp_id			= tct.comp_id
			AND tit.bra_id			= tct.bra_id
			AND tit.ct_transaction	= tct.ct_transaction
	WHERE tit.it_deliveryCharge = 0
	GROUP BY
		tct.comp_id,tct.bra_id,tct.ct_transaction



GO



-- Retorna articulos disponibles para FullJaus
CREATE view [dbo].[vwCommunity_ItemsData]
AS

	SELECT ti.comp_id,ti.item_id
		FROM  tbItem				   ti				WITH (NOLOCK)
		INNER JOIN tbCategory		AS tc				WITH (NOLOCK)
			ON	tc.comp_id		= ti.comp_id	AND
				tc.cat_id		= ti.cat_id
		INNER JOIN tbSubCategory	AS tsc				WITH (NOLOCK)
			ON	tsc.comp_id		= ti.comp_id	AND
				tsc.cat_id		= ti.cat_id		AND
				tsc.subcat_id	= ti.subcat_id
		WHERE	ti.item_isAvailable4Community		= 'True'  AND
				tc.cat_isAvailable4Community		= 'True'  AND
				tsc.subcat_isAvailable4Community	= 'True'  AND
				ti.item_disabled					= 'False'




GO







CREATE view [dbo].[vwCostPricePercentRelation]
AS


SELECT TOP 10000
	   tcppr.comp_id, tcppr.bra_id, tcppr.coslis_id, tcppr.prli_id,
       tcppr.coslis_isAW, tcppr.ItemPercentNumber, tcppr.cppr_RecalculatePercent,
       tcppr.cppr_order, tcppr.cppr_matchCosts, tcppr.cppr_wucPriceModeFinal,
       tcppr.cppr_wucCostModeFinal
	FROM dbo.tbCostPricePercentRelation tcppr
	ORDER BY tcppr.cppr_order

GO





