-- ---------------------------------------------------------------
-- MOS
-- 07-2011
-- Retorna las Percepciones disponibles para efectuar al Cliente
-- DE INGRESOS BRUTOS:!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
-- ---------------------------------------------------------------
CREATE VIEW [dbo].[vwCustomer_PerceptionAvailable]
AS

SELECT ts.comp_id, ts.cust_id,vtc.tax_class
	FROM tbCustomer ts																WITH (NOLOCK)
	LEFT JOIN tbsysTaxClass ttc														WITH (NOLOCK)
		ON ttc.state_id = ts.state_id AND ttc.country_id = ts.country_id
	LEFT JOIN vwsysTaxClassALL_Perceptions vtc										WITH (NOLOCK)
		ON vtc.tax_class = ttc.tax_class
WHERE vtc.tax_class IS NOT NULL AND ts.stcIB_Id IN (1,10)

UNION

SELECT ts.comp_id, ts.cust_id,vtc.tax_class
	FROM tbCustomer  ts																WITH (NOLOCK)
	LEFT JOIN tbTaxIBCustomers_ForSales ttifp										WITH (NOLOCK)
		ON ttifp.comp_id = ts.comp_id AND ttifp.cust_id = ts.cust_id
	LEFT JOIN tbsystaxclass ttc1													WITH (NOLOCK)
		ON ttc1.state_id = ttifp.state_id AND ttc1.country_id = ttifp.country_id
	Left join vwsysTaxClassALL_Perceptions vtc										WITH (NOLOCK)
		ON vtc.tax_class = ttc1.tax_class
WHERE vtc.tax_class IS NOT NULL AND ts.stcIB_Id IN (1,10)
GO





CREATE VIEW [dbo].[vwCustomerFilterByUser] --WITH SCHEMABINDING
AS


	--recupera los clientes del vendedor y la sucursal de tbCustomerFilterByUser
	SELECT 	tc.comp_id,
			tc.cust_id,
			tc.bra_id						[cust_bra_id],   -- MOS
			tc.sm_id,
			tcf.bra_id						[cfbu_bra_id],
			isnull(tcf.[user_id],-1)		[user_id]
	FROM	dbo.tbCustomer														tc				WITH (NOLOCK)
			INNER join dbo.tbCustomerFilterByUser								tcf				WITH (NOLOCK)
			ON	tcf.comp_id		= tc.comp_id
			AND (tcf.sm_id		= tc.sm_id	OR tc.sm_id IS NULL)		-- MOS
			AND (tcf.bra_id		= tc.bra_id OR tc.bra_id IS NULL)		-- MOS




GO







