-- MOS  01-2011
-- Retorna el 1 o -1 para multiplicar en select dependiendo si suma o resta.-

CREATE VIEW [dbo].[vwDocumentsFile]
AS


SELECT	tdf.comp_id,
		tdf.df_id,
		CASE
			WHEN td.sd_isCredit = 'True' THEN -1
			ELSE 1
		END												[PlusOrMinus]
	FROM tbDocumentsFile tdf					WITH (NOLOCK)
	INNER JOIN tbsysDocuments td				WITH (NOLOCK)
		ON td.sd_id = tdf.sd_id
GO






