				ti.item_disabled				= 'False'




GO






CREATE VIEW [dbo].[vwGAddresses]
AS



SELECT	50						[table_id],
		'dl_address'			[field_name],
		td.comp_id,
		td.dl_id				[id],
		td.dl_name				[name],
		td.dl_address			[address],
		td.dl_city				[city],
		td.dl_zip				[zip],
		tsc.country_desc		[country],
		tss.state_desc			[state],
		td.dl_phone				[phone1],
		''						[phone2],
		''						[fax],
		''						[email],
		td.dl_Web				[web]
FROM	tbDelivery				td																			WITH (NOLOCK)
		LEFT JOIN tbsysCountry	tsc WITH (NOLOCK) ON  tsc.country_id = td.country_id
		LEFT JOIN tbsysState	tss WITH (NOLOCK) ON  tss.country_id = td.country_id AND tss.state_id = td.state_id

UNION

SELECT  40, 'cust_address',		tc.comp_id,			tc.cust_id,		tc.cust_name,
		tc.cust_address,		tc.cust_city,		tc.cust_zip,
		tsc.country_desc,		tss.state_desc,
		tc.cust_phone1,			tc.cust_phone2,		tc.cust_fax,
		tc.cust_email,			tc.cust_web
FROM	tbCustomer				tc			WITH (NOLOCK)
		LEFT JOIN tbsysCountry	tsc WITH (NOLOCK) ON tsc.country_id = tc.country_id
		LEFT JOIN tbsysState	tss WITH (NOLOCK) ON tss.state_id	= tc.state_id AND tss.country_id = tc.country_id

UNION

SELECT	95, 'supp_address',		ts.comp_id,			ts.supp_id,		ts.supp_name,
		ts.supp_address,		ts.supp_city,		ts.supp_zip,
		tsc.country_desc,		tss.state_desc,
		ts.supp_Phone1,			ts.supp_Phone2,		ts.supp_fax,
      	ts.supp_email,			''
FROM	tbSupplier				ts	WITH (NOLOCK)
		LEFT JOIN tbsysCountry	tsc WITH (NOLOCK) ON tsc.country_id = ts.country_id
		LEFT JOIN tbsysState	tss WITH (NOLOCK) ON tss.state_id = ts.state_id AND tss.country_id = ts.country_id

UNION

SELECT	84, 'tbSalesman',		ts. comp_id,		ts.sm_id,		ts.sm_name,
		ts.sm_address,			ts.sm_city,			ts.sm_zip,
		tsc.country_desc,		tss.state_desc,
		'',						'',					'',
		ts.sm_email,			''
FROM	tbSalesman				ts	WITH (NOLOCK)
		LEFT JOIN tbsysCountry	tsc WITH (NOLOCK) ON tsc.country_id = ts.country_id
		LEFT JOIN tbsysState	tss WITH (NOLOCK) ON tss.state_id = ts.state_id AND tss.country_id = ts.country_id

UNION

SELECT	60, 'tbBranch',			tb.comp_id,			tb.bra_id,		tb.bra_desc,
		tb.bra_address,			'',					tb.bra_zip,
		tsc.country_desc,		tss.state_desc,
      	tb.bra_phone,			'',					'',
      	'',						''
FROM	tbBranch				tb	WITH (NOLOCK)
		LEFT JOIN tbsysCountry	tsc WITH (NOLOCK) ON tsc.country_id = tb.country_id
		LEFT JOIN tbsysState	tss WITH (NOLOCK) ON tss.state_id = tb.state_id AND tss.country_id = tb.country_id
GO






