CREATE view [dbo].[vwItemCostList] WITH SCHEMABINDING
	AS


	SELECT	ticl.comp_id,
			ticl.item_id,
			ticl.coslis_id,
			CASE
				WHEN tip.comp_id IS NULL	THEN ticl.coslis_price
											ELSE tipd.pubd_cost
			END															[coslis_price],

			CASE
				WHEN tip.comp_id IS NULL	THEN ticl.coslis_price_aw
											ELSE tipd.pubd_cost
			END															[coslis_price_aw],
			CASE
				WHEN tip.comp_id IS NULL	THEN ticl.curr_id
											ELSE tipd.curr_idCost
			END															[curr_id],
			CASE
				WHEN tip.comp_id IS NULL	THEN 'False'
											ELSE 'True'
			END															[isPublication],
			tip.bra_id,
			tip.pubh_id


		FROM dbo.tbItemCostList ticl						WITH (NOLOCK)
		LEFT JOIN dbo.tbItemPublicationActiveItems tip		WITH (NOLOCK)
			ON	tip.comp_id		= ticl.comp_id	AND
				tip.item_id		= ticl.item_id	AND
				tip.coslis_id	= ticl.coslis_id
		LEFT JOIN dbo.tbItemPublicationDetail tipd			WITH (NOLOCK)
			ON	tipd.comp_id    = tip.comp_id	AND
				tipd.pubh_id	= tip.pubh_id	AND
				tipd.pubd_id	= tip.pubd_id




GO






