 --1 Microprocesador / 2 Mother / 4 Memoria / 5 Gabinete



CREATE VIEW [dbo].[vwItemget_PCConfig_RelationDataByItem_MaxQtyAssociation]
AS


	-- MICRO


			SELECT
				1					[pcPartType],
				tipr.comp_id,
				tipr.item_id,
				ti.item_desc,
				tipr.maxQTY	,
				tipr.item_id		[item_id_Master]
			FROM tbItem_PCConfig_Relations				tipr	WITH (NOLOCK)
			INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt	WITH (NOLOCK)
			ON	tiprt.comp_id			= tipr.comp_id	AND
				tiprt.pcct_id			= tipr.pcct_id
			INNER JOIN tbItem							ti		WITH (NOLOCK)
			ON	ti.comp_id				= tipr.comp_id	AND
				ti.item_id				= tipr.item_id
			INNER JOIN tbSubCategory					tsc		WITH (NOLOCK)
			ON	tsc.comp_id				= ti.comp_id	AND
				tsc.cat_id				= ti.cat_id		AND
				tsc.subcat_id			= ti.subcat_id	--AND
--				tsc.subcat_pcConfigType = 1
			LEFT JOIN tbSubCategoryAux							tsca	WITH (NOLOCK)
				ON	tsca.comp_id		= ti.comp_id					AND
					tsca.subcataux_id	= ti.subcataux_id
			WHERE	tipr.pcctr_disabled = 'False'	AND
					(
						tsc.subcat_pcConfigType		= 1 OR
						tsca.subcat_pcConfigType	= 1
					)



		UNION ALL

	--MOTHERBOARD

			SELECT
				2					[pcPartType],
				tipr.comp_id,
				tipr.item_id,
				ti.item_desc,
				tipr.maxQTY,
				tipr2.item_id		[item_id_Master]
			FROM tbItem_PCConfig_Relations				tipr	WITH (NOLOCK)
			INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt	WITH (NOLOCK)
			ON	tiprt.comp_id			= tipr.comp_id	AND
				tiprt.pcct_id			= tipr.pcct_id
			INNER JOIN tbItem							ti	WITH (NOLOCK)
			ON	ti.comp_id				= tipr.comp_id	AND
				ti.item_id				= tipr.item_id
			INNER JOIN tbSubCategory					tsc	WITH (NOLOCK)
			ON	tsc.comp_id				= ti.comp_id	AND
				tsc.cat_id				= ti.cat_id		AND
				tsc.subcat_id			= ti.subcat_id	--AND
				-- tsc.subcat_pcConfigType = 2
			LEFT JOIN tbSubCategoryAux							tsca	WITH (NOLOCK)
				ON	tsca.comp_id		= ti.comp_id					AND
					tsca.subcataux_id	= ti.subcataux_id
			INNER JOIN tbItem_PCConfig_Relations		tipr2	WITH (NOLOCK)
			ON	tipr2.comp_id			= tipr.comp_id	AND
				--tipr2.item_id			= @item_id		AND
				tipr2.pcct_id			= tipr.pcct_id
			WHERE	tipr.pcctr_disabled = 'False'	 AND
					(
						tsc.subcat_pcConfigType = 2 OR
						tsca.subcat_pcConfigType = 2
					)





		UNION ALL

	--MEMORIA

			SELECT
				4					[pcPartType],
				tipr.comp_id,
				tipr.item_id,
				ti.item_desc,
				tipr.maxQTY,
				tipr2.item_id		[item_id_Master]
			FROM tbItem_PCConfig_Relations				tipr	WITH (NOLOCK)
			INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt	WITH (NOLOCK)
			ON	tiprt.comp_id			= tipr.comp_id	AND
				tiprt.pcct_id			= tipr.pcct_id
			INNER JOIN tbItem							ti	WITH (NOLOCK)
			ON	ti.comp_id				= tipr.comp_id	AND
				ti.item_id				= tipr.item_id
			INNER JOIN tbSubCategory					tsc	WITH (NOLOCK)
			ON	tsc.comp_id				= ti.comp_id	AND
				tsc.cat_id				= ti.cat_id		AND
				tsc.subcat_id			= ti.subcat_id	--AND
				--tsc.subcat_pcConfigType = 4
			LEFT JOIN tbSubCategoryAux							tsca	WITH (NOLOCK)
				ON	tsca.comp_id		= ti.comp_id					AND
					tsca.subcataux_id	= ti.subcataux_id
			INNER JOIN tbItem_PCConfig_Relations		tipr2	WITH (NOLOCK)
			ON	tipr2.comp_id			= tipr.comp_id	AND
				--tipr2.item_id			= @item_id		AND
				tipr2.pcct_id			= tipr.pcct_id
			WHERE	tipr.pcctr_disabled = 'False'	AND
					(
						tsc.subcat_pcConfigType		= 4 OR
						tsca.subcat_pcConfigType	= 4
					)




	UNION ALL

	--GABINETE

			SELECT
				5					[pcPartType],
				tipr.comp_id,
				tipr.item_id,
				ti.item_desc,
				tipr.maxQTY,
				tipr2.item_id		[item_id_Master]
			FROM tbItem_PCConfig_Relations				tipr	WITH (NOLOCK)
			INNER JOIN tbItem_PCConfig_RelationsTypes	tiprt	WITH (NOLOCK)
			ON	tiprt.comp_id			= tipr.comp_id	AND
				tiprt.pcct_id			= tipr.pcct_id
			INNER JOIN tbItem							ti	WITH (NOLOCK)
			ON	ti.comp_id				= tipr.comp_id	AND
				ti.item_id				= tipr.item_id
			INNER JOIN tbSubCategory					tsc	WITH (NOLOCK)
			ON	tsc.comp_id				= ti.comp_id	AND
				tsc.cat_id				= ti.cat_id		AND
				tsc.subcat_id			= ti.subcat_id	--AND
				-- tsc.subcat_pcConfigType = 5
			LEFT JOIN tbSubCategoryAux							tsca	WITH (NOLOCK)
				ON	tsca.comp_id		= ti.comp_id					AND
					tsca.subcataux_id	= ti.subcataux_id
			INNER JOIN tbItem_PCConfig_Relations		tipr2	WITH (NOLOCK)
			ON	tipr2.comp_id			= tipr.comp_id	AND
				--tipr2.item_id			= @item_id		AND
				tipr2.pcct_id			= tipr.pcct_id
			WHERE	tipr.pcctr_disabled = 'False'	AND
					(
						tsc.subcat_pcConfigType		= 5 OR
						tsca.subcat_pcConfigType	= 5
					)




GO







-- ----------------------------------------------
-- MOS: 10-2010
-- Se usa para items asociados de LEF
-- Si el campo bra_SaleOrderItemCompByMarkUp esta en True
-- se debe hacer un join contra esta vista y sacar el
-- costo de la lista de costos o costos aw segun diga Branch
-- y sumarle el Marckup informado en {esta vista.
-- ----------------------------------------------
CREATE VIEW [dbo].[vwItemPriceByCostByActRules]
AS

SELECT	--TOP 1
		it.comp_id,
		it.item_id,
		ticlar.clr_coslis_id_Updated		[coslis_id],
		ticlar.clr_destiny_prli_id			[prli_id],
		case ticlar.clr_coefficient
			WHEN 1 THEN it.item_markup_1
			WHEN 2 THEN it.item_markup_2
			WHEN 3 THEN it.item_markup_3
			WHEN 4 THEN it.item_markup_4
			WHEN 5 THEN it.item_markup_5
			WHEN 6 THEN it.item_markup_6
			WHEN 7 THEN it.item_markup_7
			WHEN 8 THEN it.item_markup_8
			WHEN 9 THEN it.item_markup_9
			WHEN 10 THEN it.item_markup_10
			WHEN 11 THEN it.item_markup_11
			WHEN 12 THEN it.item_markup_12
			WHEN 13 THEN it.item_markup_13
			WHEN 14 THEN it.item_markup_14
			WHEN 15 THEN it.item_markup_15
			WHEN 16 THEN it.item_markup_16
		END									[MarkUp_N]
	FROM tbItem it														WITH (NOLOCK)
	INNER JOIN tbItemCostListActualizationRules ticlar					WITH (NOLOCK)
	ON		ticlar.comp_id		= it.comp_id
		AND ticlar.subcat_id	= it.subcat_id
WHERE	ticlar.clr_originListType	= 4					-- Lista de Costos Actualizada
	AND ticlar.clr_destinyListType	= 1					-- Lista de Ventas Actualizada
	AND convert( INT ,isnull(ticlar.clr_coefficient,0)) BETWEEN 1 AND 8			-- Solo si tienen valor de 1 a 8
	AND ticlar.clr_actMethod		= 2					-- Multiplicar por un Coeficiente


GO










CREATE  VIEW [dbo].[vwItemPublicationHeader]
AS


	SELECT	DISTINCT
			tb.comp_id,
			tiph.pubh_id,
			--tb.bra_processingDate,
			tiph.bra_id,
			tiph.st_id,
			tiph.pubh_order

		FROM tbBranch tb								WITH (NOLOCK)
		INNER JOIN tbItemPublicationHeader tiph			WITH (NOLOCK)
			ON	tiph.comp_id						= tb.comp_id						AND
				tb.bra_processingDate BETWEEN tiph.pubh_fromDate AND tiph.pubh_toDate	AND
				tiph.pubh_disabled					= 'False'							AND
				tiph.pubh_isAvailable4Publication	= 'True'
		WHERE
				tb.bra_disabled						= 'False'	AND
			   (tb.bra_processingDate BETWEEN tiph.pubh_fromDate AND tiph.pubh_toDate)


GO








-- MOS 08-2012
-- Retorna el estado de parentezco de los items con respecto a Talles y Colores.
-- Master=1: es un articulo PADRE de talles y colores: PRINCIPAL
-- Slave=1: es un Hijo o articulo final con tale y color.-

CREATE VIEW [dbo].[vwItems_ParentStatus] WITH SCHEMABINDING
AS

SELECT	-- DISTINCT MOs 03/2016
		ti.comp_id,
		ti.item_id,
		CASE
			WHEN ITMaster.comp_id IS NULL THEN 0
			ELSE 1
		END								[Master],
		CASE
			WHEN ITSlave.comp_id IS NULL THEN 0
			ELSE 1
		END								[Slave],
		COUNT_BIG(*)					[Cuenta]

	FROM dbo.tbItem ti											WITH (NOLOCK)

	LEFT JOIN dbo.tbItemSizeColorRelation ITMaster				WITH (NOLOCK)
		ON		ITMaster.comp_id = ti.comp_id
			AND ITMaster.item_id = ti.item_id
	LEFT JOIN dbo.tbItemSizeColorRelation ITSlave				WITH (NOLOCK)
		ON		ITSlave.comp_id = ti.comp_id
			AND ITSlave.item_id_child = ti.item_id
GROUP BY
		ti.comp_id,
		ti.item_id,
		ITSlave.comp_id,
		ITMaster.comp_id


GO








CREATE VIEW [dbo].vwItems_PurchaseOrderTotals
AS



	SELECT	tpod.comp_id,
			tpod.item_id,
			SUM(tpod.pod_qty)	[qty]
		FROM tbPurchaseOrderDetail tpod	WITH (NOLOCK)
		INNER JOIN tbPurchaseOrderHeader tpoh
			ON	tpoh.comp_id	= tpod.comp_id	AND
				tpoh.bra_id		= tpod.bra_id	AND
				tpoh.poh_id		= tpod.poh_id
	WHERE	tpod.pod_isProcessed='False'  AND
			tpoh.poh_quotation = 'False'
	GROUP BY tpod.comp_id,tpod.item_id

GO










