-- MOS
-- 08-2009
-- Retorna el Importe Neto y Final de cada Item de tbItemTransactions.

CREATE VIEW [dbo].[vwItemTransactions]
AS

SELECT	tit.comp_id,
		tit.bra_id,
		tit.ct_transaction,
		tit.it_transaction,
		tit.curr_id,																					-- Se saco vw_itemSubtotal   MOS 04-2010
		isnull(SUM(ttm.tm_total),0)													[vw_itemTaxes],		-- Ex vw_taxSubtotal		 MOS 04-2010


		--se modificó esta columna ya que el ttm.tm_total está calculado para la cantiad * el precio MOH 15-06/2010
		--cálculo anterior: tit.it_price				+ isnull(SUM(ttm.tm_total),0)		[vw_itemUnitPriceWithTaxes],
		tit.it_price				+ (isnull(SUM(ttm.tm_total),0) / dbo.fnNoZDiv(tit.it_qty))	[vw_itemUnitPriceWithTaxes],


		--se modificó esta columna ya que el ttm.tm_total está calculado para la cantiad * el precio MOH 15-06/2010
		--cálculo anterior: tit.it_qty * ( tit.it_price + isnull(SUM(ttm.tm_total),0))		[vw_itemTotal]
		(tit.it_qty * tit.it_price) + isnull(SUM(ttm.tm_total),0)					[vw_itemTotal],

		tit.it_qty *	CASE
							WHEN td.sd_isPurchase='false' AND td.sd_isCredit='false' THEN -1
							WHEN td.sd_isPurchase='false' AND td.sd_isCredit='True'  THEN  1
							WHEN td.sd_isPurchase='True'  AND td.sd_isCredit='false' THEN  1
							WHEN td.sd_isPurchase='True'  AND td.sd_isCredit='True'  THEN -1
						END
																					[vw_qty]

FROM	dbo.tbItemTransactions								tit				WITH (NOLOCK)
		INNER JOIN dbo.tbCommercialTransactions tct							WITH (NOLOCK)
			ON		tct.comp_id			= tit.comp_id
				AND tct.bra_id			= tit.bra_id
				AND tct.ct_transaction	= tit.ct_transaction
		INNER JOIN dbo.tbsysDocuments td									WITH (NOLOCK)
			ON td.sd_id = tct.sd_id
		LEFT JOIN dbo.tbTaxMovements						ttm				WITH (NOLOCK)
			ON	ttm.comp_id			= tit.comp_id
			AND ttm.bra_id			= tit.bra_id
			AND ttm.ct_transaction	= tit.ct_transaction
			AND ttm.it_transaction	= tit.it_transaction


GROUP BY	tit.comp_id,
			tit.bra_id,
			tit.ct_transaction,
			tit.it_transaction,
			tit.curr_id,
			tit.it_qty,
			tit.it_price,
			td.sd_isPurchase,
			td.sd_isCredit




GO






-- ----------------------------------------------------
-- MOS 09-2008
--
-- Se usa para poder calcular mas rapidamente
-- Movimientos de Stock sin tenes que saber cual suma
-- o cual resta, solo hay que multiplicar por el
-- campo vwToForward si es para calcular hacia adelante
-- o vwToBack si es para calcular hacia atras
-- ----------------------------------------------------
CREATE View [dbo].[vwItemTransactions_forPurchase]
AS
-- =================================================================================================================
-- Author		: MOH
-- Update Date	: 2010-10-14
-- Parte		: 616 - ver detalle de funcionalidad en wfmPurchaseDocs
-- Description	: No se recuperan los registros de tbItemTransactions que tienen el campo
--				  it_transaction_NoStockDiscount = 'true'
-- =================================================================================================================



Select  IT.comp_id,
		IT.bra_id,
        IT.ct_transaction,
		IT.it_transaction,
		SD.sd_isCredit,
		SD.sd_isPurchase,
		Case
			When SD.sd_isCredit = 'False' Then -1
			When SD.sd_isCredit = 'True'  Then  1
		End				[vwToBack],
		Case
			When SD.sd_isCredit = 'False' Then  1
			When SD.sd_isCredit = 'True'  Then -1
		End				[vwToForward]

	From	dbo.tbItemTransactions			IT


	INNER JOIN	tbCommercialTransactions	CT
	WITH (NOLOCK)
		ON		IT.comp_id			= CT.comp_id
			AND IT.bra_id			= CT.bra_id
			AND IT.ct_transaction	= CT.ct_transaction
	INNER JOIN  dbo.tbsysDocuments			SD
	WITH (NOLOCK)
		ON		CT.sd_id			= SD.sd_id

	Where   SD.sd_isPurchase  = 'True'
		AND SD.sd_isQuotation = 'False'
		AND ISNULL(IT.it_transaction_NoStockDiscount,'false') = 'false'		--2010-10-14 - MOH - Parte: 616



GO







-- ----------------------------------------------------
-- MOS 09-2008
--
-- Se usa para poder calcular mas rapidamente
-- Movimientos de Stock sin tenes que saber cual suma
-- o cual resta, solo hay que multiplicar por el
-- campo vwToForward si es para calcular hacia adelante
-- o vwToBack si es para calcular hacia atras
-- ----------------------------------------------------
CREATE View [dbo].[vwItemTransactions_forSales]		WITH SCHEMABINDING
AS
Select  IT.comp_id,
		IT.bra_id,
        IT.ct_transaction,
		IT.it_transaction,
		SD.sd_isCredit,
		SD.sd_isPurchase,
		IT.it_isProduction,
		IT.it_isAssociation,
		IT.it_isAssociationGroup,
		Case
			When SD.sd_isCredit = 'False' Then  1
			When SD.sd_isCredit = 'True'  Then -1
		End				[vwToBack],
		Case
			When SD.sd_isCredit = 'False' Then -1
			When SD.sd_isCredit = 'True'  Then  1
		End				[vwToForward]

	From	dbo.tbItemTransactions			IT

	INNER JOIN	dbo.tbCommercialTransactions	CT
	WITH (NOLOCK)
		ON		IT.comp_id			= CT.comp_id
			AND IT.bra_id			= CT.bra_id
			AND IT.ct_transaction	= CT.ct_transaction
	INNER JOIN  dbo.tbsysDocuments			SD
	WITH (NOLOCK)
		ON		CT.sd_id			= SD.sd_id

	Where   SD.sd_isPurchase									= 'False'
		and SD.sd_isQuotation									= 'False'
		AND IsNull(it.it_transaction_NoStockDiscount,'False')	= 'False'


GO






