-- ----------------------------------------------------
-- MOS 09-2008
--
-- Se usa para poder calcular mas rapidamente
-- Movimientos de Stock sin tenes que saber cual suma
-- o cual resta, solo hay que multiplicar por el
-- campo vwToForward si es para calcular hacia adelante
-- o vwToBack si es para calcular hacia atras
-- ----------------------------------------------------
CREATE View [dbo].[vwItemTransactions_forStockMovementsCalculations]	WITH SCHEMABINDING
AS
Select  IT.comp_id,
		IT.bra_id,
        IT.ct_transaction,
		IT.it_transaction,
		SD.sd_isCredit,
		SD.sd_isPurchase,
		Case
			When SD.sd_isPurchase = 'True'  and SD.sd_isCredit = 'False' Then -1
			When SD.sd_isPurchase = 'True'  and SD.sd_isCredit = 'True'  Then  1
			When SD.sd_isPurchase = 'False' and SD.sd_isCredit = 'False' Then  1
			When SD.sd_isPurchase = 'False' and SD.sd_isCredit = 'True'  Then -1
		End				[vwToBack],
		Case
			When SD.sd_isPurchase = 'True'  and SD.sd_isCredit = 'False' Then  1
			When SD.sd_isPurchase = 'True'  and SD.sd_isCredit = 'True'  Then -1
			When SD.sd_isPurchase = 'False' and SD.sd_isCredit = 'False' Then -1
			When SD.sd_isPurchase = 'False' and SD.sd_isCredit = 'True'  Then  1
		End				[vwToForward]

	From	dbo.tbItemTransactions			IT

	INNER JOIN	dbo.tbCommercialTransactions	CT
		ON		CT.comp_id			= IT.comp_id		AND
				CT.bra_id			= IT.bra_id			AND
				CT.ct_transaction	= IT.ct_transaction
	INNER JOIN  dbo.tbsysDocuments			SD
		ON		CT.sd_id			= SD.sd_id

	Where 	SD.sd_isQuotation					= 'False'	AND
			it.it_transaction_NoStockDiscount	= 'False'





GO









CREATE view [dbo].[vwItemTransactionsFinalPrice]
AS


SELECT
		tit.comp_id,
		tit.it_transaction,
		(tit.it_qty)									[ITQty],
		tit.it_price + SUM((IsNull(ttm.tm_total,0) /	CASE
															WHEN tit.it_qty = 0 THEN 1
															ELSE tit.it_qty
														END
						   ))	[PriceWithTaxes],
					   SUM((IsNull(ttm.tm_total,0) /	CASE
														    WHEN tit.it_qty = 0 THEN 1
														    ELSE tit.it_qty
														END
						   ))	[TotalTaxes]

	FROM tbItemTransactions tit			WITH (NOLOCK)
	LEFT JOIN tbTaxMovements ttm		WITH (NOLOCK)
		ON	ttm.it_transaction	= tit.it_transaction
	GROUP BY tit.comp_id,tit.it_transaction,tit.it_qty,tit.it_price

GO







-- =================================================================================================================
-- Author		: MOS
-- Description	: Retorna si hay algun item pendiente de facturacion.-
-- =================================================================================================================

CREATE view [dbo].[vwItemTransactionsPackingPending]	WITH SCHEMABINDING
AS


SELECT
		tit.comp_id,
		tit.bra_id,
		tit.ct_transaction,
		tit.it_packingInvoicePend,
		COUNT_BIG(*)		[dummy]
	FROM dbo.tbItemTransactions tit						--WITH (NOLOCK)
	WHERE tit.it_packingInvoicePend = 'True'
	GROUP BY
		tit.comp_id,
		tit.bra_id,
		tit.ct_transaction,
		tit.it_packingInvoicePend

GO


CREATE view [dbo].[vwItemTransactionsProfitAndMarckup]
AS


SELECT	tit.comp_id,
		tit.bra_id,
		tit.ct_transaction,
	    tit.it_transaction,
		dbo.fnGetMarkUp( (tit.it_qty * tit.it_priceOfCost),(tit.it_qty * tit.it_price))			[MarkUp],
		dbo.fnGetProfit( (tit.it_qty * tit.it_priceOfCost),(tit.it_qty * tit.it_price))			[Profit],
		dbo.fnGetMarkUp( (tit.it_qty * tit.it_priceBOfCost),(tit.it_qty * tit.it_price))		[MarkUpB],
		dbo.fnGetProfit( (tit.it_qty * tit.it_priceBOfCost),(tit.it_qty * tit.it_price))		[ProfitB],
		dbo.fnGetMarkUp( (tit.it_qty * tit.it_priceOfCostPP),(tit.it_qty * tit.it_price))		[MarkUpPPPP],
		dbo.fnGetProfit( (tit.it_qty * tit.it_priceOfCostPP),(tit.it_qty * tit.it_price))		[ProfitPPP],
		dbo.fnGetMarkUp( (tit.it_qty * tit.it_priceBOfCostPP),(tit.it_qty * tit.it_price))		[MarkUpBPPPP],
		dbo.fnGetProfit( (tit.it_qty * tit.it_priceBOfCostPP),(tit.it_qty * tit.it_price))		[ProfitBPPP],
		dbo.fnGetMarkUp( (tit.it_qty * tit.it_priceOfCostPP),(tit.it_qty * (tit.it_price - tit.it_CreditInt)))		[MarkUpPPPPSI],  --		Para Liquidacion de Comisiones
		(tit.it_qty * tit.it_priceOfCost)	[SumOfCost],
		(tit.it_qty * tit.it_priceOfCostPP)	[SumOfCostPP],
		(tit.it_qty * tit.it_priceBOfCost)	[SumOfCostB],
		(tit.it_qty * tit.it_priceBOfCostPP)[SumOfCostBPP],
		(tit.it_qty * tit.it_price)			[SumOfSale],
		(tit.it_priceOfCost)	[Cost],
		(tit.it_priceOfCostPP)	[CostPP],
		(tit.it_priceBOfCost)	[CostB],
		(tit.it_priceBOfCostPP) [CostBPP],
		(tit.it_qty)			[ITQty],
		(tit.it_price)			[Price]

	FROM tbItemTransactions tit			WITH (NOLOCK)


GO







