		where	m.menu_id = mp.menu_id		and		m.ptype_id = 25),'') +

		--heigth4
		isnull((select	t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 26),'') +

		--heigth5
		isnull((select	t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 34),'') +

		isnull((select	t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 27),'') +

		isnull((select	t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 28),'') +

		isnull((select	t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 29),'') +

		isnull((select	t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 30),'') +


/*
		DUPLICADOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO
		ESTO ES UNA MIERDAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
		isnull((select	t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
				inner join tbsysparameterstype				t
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 27),'')  +
*/






		isnull((SELECT t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 42),'')  +


		isnull((SELECT t.ptype_desc + '=' + convert(varchar,v.id) + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 43),'')  +


		isnull((SELECT t.ptype_desc + '=' + convert(varchar,v.id) + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 44),'') +

		isnull((SELECT t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 45),'') +

		isnull((SELECT t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 46),'') +

		isnull((SELECT t.ptype_desc + '=' + v.[desc] + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 47),'') +

		isnull((SELECT t.ptype_desc + '=' + replace(v.[desc],'=','#') + ','
		from	tbsysmenuparameters							m
		WITH (NOLOCK)
				inner join tbsysparameterstype				t
				WITH (NOLOCK)
				on	m.ptype_id		= t.ptype_id
				inner join vwSysParametersTypeValuesClear	v
				WITH (NOLOCK)
				on	v.[type_id]		= m.[ptype_id]
				and	v.id			= m.ptypevalue_id
		where	m.menu_id = mp.menu_id		and		m.ptype_id = 48),'')


				[parameters]

from	tbsysmenuparameters		mp

--WHERE mp.menu_id = 73
GO

create view vwMercadoLibre_ordersMessages as
(
	select  *
	FROM tbMercadoLibre_ordersMessages
		WHERE MLdate < DATEADD(MONTH,-8,GETDATE())
)
GO


-- MOS 12-2023: PUse los indices forzados.  si se pone ento, SACARLOS y borrar los indices.

CREATE view [dbo].[vwPaymentsHow] --  NO PONER !!!  WITH SCHEMABINDING
as



/* movimientos de efectivo */

select	'1'											[class]				,
		tmm.comp_id									[comp_id]			,
		sov.lang_id									[lang_id]			,
		tmm.ct_transaction							[ct_transaction]	,

		sov.optval_desc								[description]		,
		tmm.mm_desc									[type]				,
		tmm.mm_total								[amount]			,
		c.curr_desc									[currency]			,
		c.curr_id									[curr_id]			,
		tmm.mm_BranchCurrencyExchange				[exchange]			,
		tct.ct_date									[Date],
		1											[GroupClass],
		tmm.mm_id									[ID]


from	dbo.tbMoneyMovements						tmm				WITH (NOLOCK)

		INNER JOIN dbo.tbCommercialTransactions			tct				WITH (NOLOCK)
			ON		tct.comp_id			= tmm.comp_id
				AND tct.ct_transaction	= tmm.ct_transaction

		inner join dbo.[tbsysOptionsValues]			sov				WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 1
		and sov.optval_class	= 40

		left join dbo.[tbsysCurrency]				c				WITH (NOLOCK)
		on	c.curr_id			= tmm.curr_id

UNION all

/* cheques emitidos */
Select  '2'						,
		tec.comp_id				,
		sov.lang_id				,
		tec.ct_transaction		,

		sov.optval_desc			,
		tec.ec_Number + ' / ' + tba.ba_desc + ' / ' +

		REPLACE(dbo.fnGetDateFromLang(tec.ec_EmissionDate, sov.lang_id),'/','-'),

		/*
		convert(varchar,day(tec.ec_EmissionDate)) + '-' +
		convert(varchar,month(tec.ec_EmissionDate)) + '-' +
		convert(varchar,year(tec.ec_EmissionDate)),--convert(varchar(10),convert(datetime,tec.ec_EmissionDate, 102)),
		*/

		tec.ec_Total			,
		c.curr_desc				,
		tec.curr_id				,
		tec.ec_exchangeToBranchCurrency,
		tec.ec_PayDate			[Date],
		tec.ba_id,
		tec.ec_id


From	dbo.tbEmmitedChecks tec									WITH (NOLOCK,INDEX(IX_tbEmmitedChecks_ec_isDocument))

		inner join dbo.[tbsysOptionsValues]			sov		WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 7
		and sov.optval_class	= 40

		left join dbo.[tbsysCurrency]				c		WITH (NOLOCK)
		on	c.curr_id			= tec.curr_id

		Left Join dbo.tbBankingAccounts tba						WITH (NOLOCK)
		On tba.comp_id = tec.comp_id
		And tba.ba_id = tec.ba_id

Where tec.ec_isDocument='false'

UNION all

-- Cheques de Terceros
SELECT TOP 10000000	'3'				   ,
		chp.comp_id					   ,
		sov.lang_id					   ,
		chp.ct_transaction			   ,

		sov.optval_desc				   ,
		IsNull(tbn.bn_name,'') + ' #' + convert(varchar,chp.chp_number) ,
		chp.chp_total				   ,
		c.curr_desc					   ,
		c.curr_id					   ,
		chp.chp_BranchCurrencyExchange ,
		chp.chp_PayDate				[Date],
		3,
		chp.chp_id


from	dbo.tbCheckPortfolio								chp			WITH (NOLOCK,INDEX(IX_tbCheckPortfolio_chp_isDocument_chp_isOwn))

		inner join dbo.[tbsysOptionsValues]					sov			WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 2
		and sov.optval_class	= 40

		left join dbo.[tbsysCurrency]						c			WITH (NOLOCK)
		on	c.curr_id	= chp.curr_id

		LEFT JOIN dbo.tbBanksName tbn										WITH (NOLOCK)
		ON	tbn.comp_id = chp.comp_id AND
			tbn.bn_id	= chp.bn_id

where	chp.chp_isDocument = 'False'
And		chp.chp_isOwn	   = 'True'
ORDER BY chp.chp_isInProcess_Order, chp.chp_id

UNION all

select	'4'									,
		chpt.comp_id						,
		sov.lang_id							,
		chpt.ct_transaction					,
		sov.optval_desc						,
		IsNull(tbn.bn_name,'') + ' #' + convert(varchar,chpt.chp_number)	,
		chpt.chp_total						,
		c.curr_desc							,
		c.curr_id							,
		chpt.chp_BranchCurrencyExchange		,
		chpt.chp_PayDate			[Date],
		4,
		chpt.chp_id


from	dbo.tbCheckPortfolio								chpt		WITH (NOLOCK,INDEX(IX_tbCheckPortfolio_chp_isDocument_chp_isOwn))

		inner join dbo.[tbsysOptionsValues]					sov			WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 0
		and sov.optval_class	= 28

		left join dbo.[tbsysCurrency]						c			WITH (NOLOCK)
		on	c.curr_id	= chpt.curr_id

		LEFT JOIN dbo.tbBanksName tbn					WITH (NOLOCK)
		ON	tbn.comp_id = chpt.comp_id AND
			tbn.bn_id	= chpt.bn_id

Where	chpt.chp_isDocument = 'False'
and		chpt.chp_isOwn		= 'False'


UNION ALL


select	'5'													,
		chp.comp_id											,
		sov.lang_id											,
		chp.ct_transaction									,

		sov.optval_desc										,
		convert(varchar,chp.chp_number)						,
		chp.chp_total										,
		c.curr_desc											,
		c.curr_id											,
		chp.chp_BranchCurrencyExchange						,
		chp.chp_PayDate					[Date],
		5,
		chp.chp_id


from	dbo.tbCheckPortfolio								chp			WITH (NOLOCK,INDEX(IX_tbCheckPortfolio_chp_isDocument))

		inner join dbo.[tbsysOptionsValues]					sov				WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 3
		and sov.optval_class	= 40

		left join dbo.[tbsysCurrency]						c				WITH (NOLOCK)
		on	c.curr_id	= chp.curr_id

where	chp.chp_isDocument = 'True'


UNION ALL


/* transferencias bancarias*/
select	'6'											,
		btt.comp_id									,
		sov.lang_id									,
		btt.ct_transaction							,

		sov.optval_desc								,
		Isnull(btty.btt_desc,'') + '/' +
			--CASE WHEN len(isnull(btty.btt_desc,'')) > 0 AND len(isnull(btt.bt_note,'')) > 0 THEN '//' ELSE '' END +
			isnull(btt.bt_note,'') + '/' +
				isnull(ba.ba_desc,'')		[btt_desc]	,
		btt.bt_total								,
		c.curr_desc									,
		c.curr_id									,
		btt.bt_BranchCurrencyExchange				,
		btt.bt_imputationDate				[Date],
		btt.ba_id,
		btt.bt_id


from	dbo.tbBankingTransactions				btt				WITH (NOLOCK,INDEX(IX_tbBankingTransactions))

		inner join dbo.[tbsysOptionsValues]			sov			WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 5
		and sov.optval_class	= 40

		left join dbo.tbBankingAccounts				ba			WITH (NOLOCK)
		on ba.comp_id	= btt.comp_id
		and ba.ba_id	= btt.ba_id

		left join dbo.tbBankingTransactionTypes		btty		WITH (NOLOCK)
		on btty.comp_id	= btt.comp_id
		and btty.btt_id	= btt.btt_id

		left join dbo.[tbsysCurrency]				c				WITH (NOLOCK)
		on	c.curr_id	= btt.curr_id

WHERE   btt.btt_id <> 1000001


UNION ALL


select	'7'													,
		tccm.comp_id										,
		sov.lang_id											,
		tccm.ct_transaction									,

		sov.optval_desc										,
		convert(varchar,tccm.ccm_cardNumber)				,
		tccm.ccm_Total										,
		c.curr_desc											,
		c.curr_id											,
		tccm.ccm_BranchCurrencyExchange						,
		tct.ct_date								[Date],
		tccm.cc_id,
		tccm.ccm_id


from	dbo.tbCreditCardMovements							tccm			WITH (NOLOCK)


		INNER JOIN dbo.tbCommercialTransactions tct								WITH (NOLOCK)
			ON		tct.comp_id			= tccm.comp_id
				AND tct.ct_transaction	= tccm.ct_transaction

		inner join dbo.[tbsysOptionsValues]					sov				WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 4
		and sov.optval_class	= 40

		left join dbo.[tbsysCurrency]						c				WITH (NOLOCK)
		on	c.curr_id	= tccm.curr_id



UNION ALL

/* documentos emitidos */
Select  '8'						,
		tec.comp_id				,
		sov.lang_id				,
		tec.ct_transaction		,

		sov.optval_desc			,
		tec.ec_Note				,
		tec.ec_Total			,
		c.curr_desc				,
		tec.curr_id				,
		tec.ec_exchangeToBranchCurrency,
		tec.ec_PayDate			[Date],
		tec.ba_id,
		tec.ec_id


From	dbo.tbEmmitedChecks tec											WITH (NOLOCK,INDEX(IX_tbEmmitedChecks_ec_isDocument))

		inner join dbo.[tbsysOptionsValues]			sov					WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 8
		and sov.optval_class	= 40

		left join dbo.[tbsysCurrency]				c					WITH (NOLOCK)
		on	c.curr_id			= tec.curr_id

WHERE	tec.ec_isDocument		= 'true'

UNION ALL

select	'9'													,
		tcpm.comp_id										,
		sov.lang_id											,
		tcpm.ct_transaction									,

		sov.optval_desc										,
		convert(varchar,tcp1.chp_number )					,

		tcp1.chp_total,
		c.curr_desc											,
		c.curr_id											,
		tcp1.chp_BranchCurrencyExchange						,
		tcp1.chp_PayDate /*tct.ct_date*/							[Date],
		9,
		tcpm.chpm_id


from	dbo.tbCheckPortfolioMovements					tcpm			WITH (NOLOCK)

		left JOIN dbo.tbCommercialTransactions tct							WITH (NOLOCK)
			ON		tct.comp_id			= tcpm.comp_id
				AND tct.ct_transaction	= tcpm.ct_transaction


		inner join dbo.[tbsysOptionsValues]				sov				WITH (NOLOCK,INDEX(IX_tbsysOptionsValues_Id_Class))
		on	sov.optval_id		= 9
		and sov.optval_class	= 40

		Inner Join dbo.tbCheckPortfolio						tcp1			WITH (NOLOCK)
		On  tcp1.comp_id=tcpm.comp_id
		And tcp1.chp_id=tcpm.chp_id

		left join dbo.[tbsysCurrency]					c				WITH (NOLOCK)
		on	c.curr_id	= tcp1.curr_id


GO




CREATE view [dbo].[vwPaymentsTmp]
as




/* movimientos de efectivo */
select	'1'											[class],
		sov.lang_id									[lang_id],
		sov.optval_desc								[description],
		cmt.cmt_guid								[guid],
		ca.ca_desc									[type],
		cmt.cmt_amount								[amount],
		c.curr_desc									[currency],
		c.curr_id									[curr_id],
		cmt.cmt_desc								[desc],
		GETDATE()									[emissionDate],
		GETDATE()									[Date],
		cmt.cmt_id									[ID]

	from	dbo.tbCashMovementsTmp						cmt	WITH (NOLOCK)

			inner join dbo.[tbsysOptionsValues]			sov	WITH (NOLOCK)
			on	sov.optval_id		= 1
			and sov.optval_class	= 40

			left join dbo.tbCashNumbers					cn	WITH (NOLOCK)
			on cn.comp_id	= cmt.comp_id
			and cn.cn_id	= cmt.cn_id

			left join dbo.tbCashAccountant				ca	WITH (NOLOCK)
			on ca.comp_id	= cmt.comp_id
			and ca.ca_id	= cmt.ca_id

			left join dbo.[tbsysCurrency]				c	WITH (NOLOCK)
			on	c.curr_id	= cmt.curr_id


union


/* cheques propios */
select	'2'											[class],
		sov.lang_id									[lang_id],
		sov.optval_desc								[description],
		tect.ect_guid								[guid],
        convert(varchar,tect.ect_Number)			[type],
		tect.ect_Total								[amount],
		c.curr_desc									[currency],
		c.curr_id									[curr_id],
		tba.ba_desc									[desc],
		tect.ect_EmissionDate						[emissionDate],
		tect.ect_PayDate							[Date],
		tect.ect_id									[ID]

	from	dbo.tbEmmitedChecksTmp						tect	WITH (NOLOCK)

			inner join dbo.[tbsysOptionsValues]			sov		WITH (NOLOCK)
			on		sov.optval_id		= 7
			and		sov.optval_class	= 40

			left join dbo.tbBankingAccounts				tba		WITH (NOLOCK)
			on		tba.comp_id			= tect.comp_id
			and		tba.ba_id			= tect.ba_id

			left join dbo.[tbsysCurrency]				c		WITH (NOLOCK)
			on		c.curr_id			= tect.curr_id



union


/* cheques de terceros/valores en cartera */
select	'4'													[class],
		sov.lang_id											[lang_id],
		sov.optval_desc										[description],
		chpt.chp_guid										[guid],
		'Doc. - ' + convert(varchar,chpt.chp_number)		[type],
		chpt.chp_total										[amount],
		c.curr_desc											[currency],
		c.curr_id											[curr_id],
		chpt.chp_DocumentDescription						[desc],
		chpt.chp_EmissionDate								[emissionDate],
		chpt.chp_PayDate									[Date],
		chpt.chp_id											[ID]

	from	dbo.tbCheckPortfolio								chpt	WITH (NOLOCK)

			inner join dbo.[tbsysOptionsValues]					sov		WITH (NOLOCK)
			on	sov.optval_id		= 0
			and sov.optval_class	= 28

			left join dbo.[tbsysCurrency]						c		WITH (NOLOCK)
			on	c.curr_id	= chpt.curr_id





union



/* documentos */
select	'3'													[class],
		sov.lang_id											[lang_id],
		sov.optval_desc										[description],
		chpt.chpt_guid										[guid],
		'Doc. - ' + convert(varchar,chpt.chpt_number)		[type],
		chpt.chpt_total										[amount],
		c.curr_desc											[currency],
		c.curr_id											[curr_id],
		chpt_DocumentDescription							[desc],
		chpt.chpt_EmissionDate								[emissionDate],
		chpt.chpt_PayDate									[Date],
		chpt.chpt_id										[ID]

	from	dbo.tbCheckPortfolioTmp								chpt	WITH (NOLOCK)

			inner join dbo.[tbsysOptionsValues]					sov		WITH (NOLOCK)
			on	sov.optval_id		= 3
			and sov.optval_class	= 40

			left join dbo.[tbsysCurrency]						c		WITH (NOLOCK)
			on	c.curr_id	= chpt.curr_id

	where	chpt.chpt_isDocument = 'True'




union


/* transacciones bancarias */
select	'5'											[class],
		sov.lang_id									[lang_id],
		sov.optval_desc								[description],
		btt.btt_guid								[guid],
		btty.btt_desc								[type],
		btt.btt_total								[amount],
		c.curr_desc									[currency],
		c.curr_id									[curr_id],
		ba.ba_desc									[desc],
		btt.btt_imputationDate						[emissionDate],
		btt.btt_imputationDate						[Date],
		btt.bttmp_id								[ID]

	from	dbo.tbBankingTransactionsTmp				btt			WITH (NOLOCK)

			inner join dbo.[tbsysOptionsValues]			sov			WITH (NOLOCK)
			on	sov.optval_id		= 5
			and sov.optval_class	= 40

			left join dbo.tbBankingAccounts				ba			WITH (NOLOCK)
			on ba.comp_id	= btt.comp_id
			and ba.ba_id	= btt.ba_id

			left join dbo.tbBankingTransactionTypes		btty		WITH (NOLOCK)
			on btty.comp_id	= btt.comp_id
			and btty.btt_id	= btt.btt_id

			left join dbo.[tbsysCurrency]				c			WITH (NOLOCK)
			on	c.curr_id	= btt.curr_id



GO






