-- Lista de Precios que pone el precio de PUBLICACION si esta publicado y activo en el dia.
CREATE view [dbo].[vwPriceListItems]	WITH SCHEMABINDING
	AS


	SELECT	tpli.comp_id,
			tpli.item_id,
			tpli.prli_id,
			CASE
				WHEN tip.comp_id IS NULL					THEN	tpli.prli_price
				WHEN tip.prli_id4inCash = tpli.prli_id		THEN	tipd.pubd_priceInCash
				ELSE												tipd.pubd_price4Loan
			END																			[prli_price],
			CASE
				WHEN tip.comp_id IS NULL					THEN	tpli.curr_id
				WHEN tip.prli_id4inCash = tpli.prli_id		THEN	tipd.curr_idInCash
				ELSE												tipd.curr_id4Loan
			END																			[curr_id],
			CASE
				WHEN tip.comp_id IS NULL	THEN 'False'
											ELSE 'True'
			END															[isPublication],
			tip.bra_id,
			tipd.pubh_id,
			tipd.pubd_id	,
			CASE
				WHEN tip.comp_id IS NOT NULL THEN	tip.pubd_cd
				ELSE								tpli.prli_updatedAt
			END															[lastUpdate]


		FROM dbo.tbPriceListItems tpli						WITH (NOLOCK)
		--INNER JOIN tbItem ti								WITH (NOLOCK)
		--	ON	ti.comp_id = tpli.comp_id AND
		--		ti.item_id = tpli.item_id
		LEFT JOIN dbo.tbItemPublicationActiveItems tip
			ON	tip.comp_id			= tpli.comp_id	AND
				tip.item_id			= tpli.item_id	AND
				(
					tip.prli_id4inCash	= tpli.prli_id
				  OR
					tip.prli_id4Loan	= tpli.prli_id
				)
		LEFT JOIN dbo.tbItemPublicationDetail tipd			WITH (NOLOCK)
			ON	tipd.comp_id    = tip.comp_id	AND
				tipd.pubh_id	= tip.pubh_id	AND
				tipd.pubd_id	= tip.pubd_id




GO










CREATE view [dbo].[vwPurchaseDocs]
as

	-- ---------------------------------------------------------------------------------
	-- Vista que retorna los datos a mostrar en la grilla de wfmPurchaseDocs
	-- ---------------------------------------------------------------------------------


	-- ================================================================================================================================
	-- 2011-06-03 - MOH - TN: S/N  Ref: #1
	-- Se agregó en el query que retona los datos de los artículos el total adicional, esto es para mostrarlo en los totales de la
	-- carga de comprobantes de compra (wfmPurchaseDocs.aspx) y con este total poder realizar una nueva validación de totales
	-- ================================================================================================================================



	-- ITEMS
	SELECT 	tis.tis_guid [guid],
			CASE							-- MOS 05-2015
				WHEN tis.poh_id IS NULL OR tis.pod_id IS NULL THEN '1'
				ELSE '2'
			END														[class],
			I.item_code												[code],
			i.item_desc												[desc],
			tis.tis_qty												[qty],
			tis.tis_price											[price],
			tis.curr_id,
			tis.tax_id,
			convert(decimal(24,6),(tis.tis_qty * tis.tis_price))	[total],
			tax.tax_desc											[tax_desc],
			tpc.puco_desc											[puco_desc],
			convert(decimal(24,6),(tis.tis_qty * tis.tis_PriceB))	[totalB],		-- Ref: #1	,
			ISNULL(ts.stor_desc,'')									[stor_desc],
			tis.tis_Discount1										[Discount1],
			tis.tis_Discount2										[Discount2],
			tis.tis_Discount3										[Discount3],
			tis.tis_Discount4                                       [Discount4],
			tis.tis_surcharge1										[SurCharge1],
			tis.tis_surcharge2										[SurCharge2],
			tis.tis_surcharge3										[SurCharge3],
			tis.tis_surcharge4										[SurCharge4],
			tis.tis_id												[ID]

	from	dbo.tbItemTransactionsTmp			tis		WITH (NOLOCK)

			LEFT JOIN dbo.tbItem				I		WITH (NOLOCK)
			ON  I.comp_id	= tis.comp_id
			AND I.item_id	= tis.item_id

			LEFT JOIN tbStorage ts						WITH (NOLOCK)
				ON	ts.comp_id = tis.comp_id AND
					ts.stor_id = tis.stor_id

			LEFT JOIN dbo.tbTaxName				tax		WITH (NOLOCK)
			ON	tax.comp_id	= tis.comp_id
			AND tax.tax_id	= tis.tax_id

			LEFT JOIN tbPurchaseConcept			tpc		WITH (NOLOCK)
			ON	tis.comp_id = tpc.comp_id
			AND tis.puco_id = tpc.puco_id




	-- ---------------------------------------------------------------------------------

Union

	-- CONCEPTOS
	select	pcmt.pcmt_guid [guid],
			'3'														[class],
			''														[code],
			case when pcmt.pcmt_note1 <> '' THEN pcmt.pcmt_note1 + '-' ELSE '' END +
			case when pcmt.pcmt_note2 <> '' THEN pcmt.pcmt_note2 + '-' ELSE '' END + cc.cc_desc		[desc],
			null													[qty],
			null													[price],
			pcmt.curr_id,
		    pcmt.tax_id,
			pcmt.pcmt_total											[total],
			''														[tax_desc],
			tpc.puco_desc											[puco_desc],
			NULL													[totalB],	-- Ref: #1
			''									[stor_desc],
			0									[Discount1],
			0									[Discount2],
			0									[Discount3],
			0									[Discount4],
			0									[SurCharge1],
			0									[SurCharge2],
			0									[SurCharge3],
			0									[SurCharge4],
			pcmt.pcmt_id											[ID]

	from	dbo.tbPurchaseConceptMovementsTmp	pcmt		WITH (NOLOCK)

			LEFT JOIN dbo.tbCostCenter			cc			WITH (NOLOCK)
			ON	cc.comp_id		= pcmt.comp_id
			AND cc.cc_code		= pcmt.cc_code

			LEFT JOIN tbPurchaseConcept			tpc			WITH (NOLOCK)
			ON	tpc.comp_id		= pcmt.comp_id
			AND tpc.puco_id		= pcmt.puco_id

	-- ---------------------------------------------------------------------------------

Union

	-- IMPUESTOS
	select	tmt.tmt_guid [guid],
			'4'									[class],
			''									[code],
			tax.tax_desc						[desc],
			null								[qty],
			null								[price],
			tmt.curr_id,
			tmt.tax_id,
			tmt.tmt_total						[total],
			''									[tax_desc],
			tpc.puco_desc						[puco_desc],
			NULL								[totalB],	-- Ref: #1
			''									[stor_desc],
			0									[Discount1],
			0									[Discount2],
			0									[Discount3],
			0									[Discount4],
			0									[SurCharge1],
			0									[SurCharge2],
			0									[SurCharge3],
			0									[SurCharge4],
			tmt.tmt_transaction					[ID]


	from	dbo.tbTaxMovementsTmp				tmt			WITH (NOLOCK)

			LEFT JOIN dbo.tbTaxName				tax			WITH (NOLOCK)
			ON	tax.comp_id		= tmt.comp_id
			AND tax.tax_id		= tmt.tax_id

			LEFT JOIN tbPurchaseConcept			tpc			WITH (NOLOCK)
			ON	tmt.comp_id		= tpc.comp_id
			AND tmt.puco_id		= tpc.puco_id

	Where	tmt.isCalculated	= 'False'

	-- ---------------------------------------------------------------------------------

Union

	-- IMPUESTOS Calculados
	select	tmtC.tmt_guid [guid],
			'5'									[class],
			''									[code],
			tax.tax_desc						[desc],
			null								[qty],
			null								[price],
			tmtC.curr_id,
			tmtC.tax_id,
			sum(tmtC.tmt_total)					[total],
			''									[tax_desc],
			tpc.puco_desc						[puco_desc],
			null								[totalB],	-- Ref: #1
			''									[stor_desc],
			0									[Discount1],
			0									[Discount2],
			0									[Discount3],
			0									[Discount4],
			0									[SurCharge1],
			0									[SurCharge2],
			0									[SurCharge3],
			0									[SurCharge4],

			0 /*tmtC.tmt_transaction*/			[ID]


	from	dbo.tbTaxMovementsTmp				tmtC			WITH (NOLOCK)

			LEFT JOIN dbo.tbTaxName				tax				WITH (NOLOCK)
			ON	tax.comp_id		= tmtC.comp_id
			AND tax.tax_id		= tmtC.tax_id

			LEFT JOIN tbPurchaseConcept			tpc				WITH (NOLOCK)
			ON	tmtC.comp_id	= tpc.comp_id
			AND tmtC.puco_id	= tpc.puco_id

	WHERE	tmtC.isCalculated	= 'True'


	Group By tax.tax_desc,tmtc.curr_id,tmtc.tax_id,tmtc.tmt_guid,tpc.puco_desc




GO



CREATE VIEW [dbo].[vwSaleOrderHeaderHistory_OnlyLastSaleOrder]
AS

	WITH tmpSaleOrderHeaderHistory(comp_id,sohh_id) AS (

	SELECT	tstgr.comp_id,MAX(tstgr.sohh_id)
		FROM tbSaleOrderHeaderHistory tstgr				WITH (NOLOCK)
		GROUP BY tstgr.comp_id, tstgr.bra_id, tstgr.soh_id
	)

	SELECT tsohh.*
		FROM tmpSaleOrderHeaderHistory		tmp				WITH (NOLOCK)
		INNER JOIN tbSaleOrderHeaderHistory tsohh			WITH (NOLOCK)
		ON	tsohh.comp_id =  tmp.comp_id AND
			tsohh.sohh_id = tmp.sohh_id





GO






