-- MOS
-- 01-2010
-- Retorna la Descripcion del Proveedor

CREATE VIEW [dbo].[vwSupplier]
AS


SELECT	tct.comp_id,
		tct.bra_id,
		tct.ct_transaction,
		tct.supp_id									[supp_id],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_name
			WHEN  tctop.op_paymentTo	IS NOT NULL THEN tctop.op_paymentTo
			ELSE  ts.supp_name
		END											[supp_name],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_address
			ELSE  ts.supp_address
		END											[supp_address],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_city
			ELSE  ts.supp_city
		END											[supp_city],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_zip
			ELSE  ts.supp_zip
		END											[supp_zip],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_phone1
			ELSE  ts.supp_Phone1
		END											[supp_Phone1],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_email
			ELSE  ts.supp_email
		END											[supp_email],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.country_id
			ELSE  ts.country_id
		END											[country_id],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.state_id
			ELSE  ts.state_id
		END											[state_id],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_TaxNumber
			ELSE  ts.supp_taxNumber
		END											[supp_taxNumber],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.fc_id
			ELSE  ts.fc_id
		END											[fc_id],
		CASE
			WHEN  tct.suppa_id			IS NOT NULL THEN tsa.suppa_contact
			ELSE  ts.supp_contact
		END											[supp_contact],
		ts.supp_excludeFromTaxReport



	FROM tbCommercialTransactions tct
	INNER JOIN tbBranch tb
		ON	tb.comp_id	= tct.comp_id AND
			tb.bra_id	= tct.bra_id
	INNER JOIN tbSupplier ts
	ON		ts.comp_id				= tct.comp_id	AND
			ts.supp_id				= tct.supp_id
	LEFT JOIN tbCommercialTransactionsOtherPayments tctop
		ON	tctop.comp_id			= tct.comp_id	AND
		    tctop.bra_id			= tct.bra_id	AND
		    tctop.ct_transaction	= tct.ct_transaction
	LEFT JOIN tbSupplierAssociated tsa
		ON	tsa.comp_id				= tct.comp_id AND
			tsa.supp_id				= tct.supp_id AND
			tsa.suppa_id			= tct.suppa_id




GO







-- ---------------------------------------------------------------
-- MOS
-- 07-2011
-- Retorna las Retenciones disponibles para efectuar al proveedor
-- de INGRESOS BRUTOS:!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
-- ---------------------------------------------------------------
CREATE VIEW [dbo].[vwSupplier_RetentionsAvailable]
AS

	SELECT	ts.comp_id,
			ts.supp_id,
			vtc.tax_class
		FROM tbSupplier ts										WITH (NOLOCK)
		LEFT JOIN tbsysTaxClass ttc								WITH (NOLOCK)
			ON	ttc.state_id	= ts.state_id AND
				ttc.country_id	= ts.country_id
		LEFT JOIN vwsysTaxClassALL_Retentions vtc				WITH (NOLOCK)
			ON vtc.tax_class	= ttc.tax_class
		WHERE vtc.tax_class IS NOT NULL AND ts.stcIB_Id IN (1,10,20)	-- 20 se agrego el 04-2016 x MOS

UNION

	SELECT  ts.comp_id,
			ts.supp_id,
			vtc.tax_class
		FROM tbSupplier ts										WITH (NOLOCK)
		LEFT JOIN tbTaxIBSuppliers_ForPayment ttifp				WITH (NOLOCK)
			ON	ttifp.comp_id	= ts.comp_id AND
				ttifp.supp_id	= ts.supp_id
		LEFT JOIN tbsystaxclass ttc1							WITH (NOLOCK)
			ON	ttc1.state_id	= ttifp.state_id AND
				ttc1.country_id = ttifp.country_id
		Left join vwsysTaxClassALL_Retentions vtc				WITH (NOLOCK)
			ON vtc.tax_class = ttc1.tax_class
		WHERE	vtc.tax_class IS NOT NULL AND
				ts.stcIB_Id IN (1,10,20)

GO








