-- 01-2009
-- Retorna solo los ID que se usan
-- para PREPARAR un PEDIDO
-- Tener en cuenta ademas de filtrar
-- de tbDocumentsfile los pedidos
-- que tienen needPreparation en True.
-- -----------------------------------

CREATE VIEW [dbo].[vwsysSaleOrderStatus_ForPreparation]
AS

SELECT     ssos_id
	FROM   dbo.tbsysSaleOrderStatus					WITH (NOLOCK)
	Where  ssos_isForPreparation = 'True'


GO






