CREATE VIEW [dbo].[vwsysTaxClassALL]
AS

Select			tax_class,
				taxcl_desc

	From        dbo.tbsysTaxClass       STC		WITH (NOLOCK)


GO







-- MOS  10-2008
-- Solo se ven las Percepciones

CREATE VIEW [dbo].[vwsysTaxClassALL_Perceptions] WITH SCHEMABINDING
												--  SI SE MODIFICA ESTA VISTA HAY QUE CREAR NUEVAMENTE ESTE INDICE PARA dbGBP en [spSystem_GenerateDatabaseUpdateIndex4Views]
AS

Select			tax_class,
				taxcl_desc

	From        dbo.tbsysTaxClass       STC				--WITH (NOLOCK)

	Where
			    STC.taxcl_isPerception	= 'True'
			and STC.taxcl_isRetention	= 'False'

GO






-- MOS  10-2008
-- Solo se ven las Retenciones

