CREATE view [dbo].[vwTaxMovements_IVAFirstTax]
AS
-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2010-11
-- Parte		:
-- Description	: Retorna 1 iva por cada it_transaction
-- =================================================================================================================



SELECT	DISTINCT
		(ttm.comp_id),
		ttm.bra_id,
		ttm.ct_transaction,
		ttm.it_transaction,
		ttm.tax_id

	FROM tbTaxMovements ttm				WITH (NOLOCK)
	INNER JOIN tbTaxName ttn			WITH (NOLOCK)
		ON		ttn.comp_id		= ttm.comp_id
			AND ttn.tax_id		= ttm.tax_id
WHERE ttn.tax_class = 1   -- IVA
GO









CREATE view [dbo].[vwTaxMovements_IVATax]
AS
-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2015-06
-- Parte		:
-- Description	: Retorna 1 iva por cada it_transaction
-- =================================================================================================================



SELECT
		ttm.comp_id,
		ttm.bra_id,
		ttm.tm_transaction,
		ttm.ct_transaction,
		ttm.it_transaction,
		ttm.tax_id

	FROM tbTaxMovements ttm				WITH (NOLOCK)
	INNER JOIN tbTaxName ttn			WITH (NOLOCK)
		ON		ttn.comp_id		= ttm.comp_id
			AND ttn.tax_id		= ttm.tax_id
	WHERE ttn.tax_class = 1   -- IVA


GO









CREATE view [dbo].[vwTaxMovements_NoIVATax]
AS
-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2011-02
-- Parte		:
-- Description	: Retorna el total de Impuestos que NO sean IVA por cada ItemTransaction
-- =================================================================================================================

SELECT
		ttm.comp_id,
		ttm.bra_id,
		ttm.it_transaction,
		ttm.ct_transaction,
		SUM(ttm.tm_total)		[Total]

	FROM tbTaxMovements ttm						WITH (NOLOCK)
	INNER JOIN tbTaxName ttn					WITH (NOLOCK)
		ON		ttn.comp_id		= ttm.comp_id
			AND ttn.tax_id		= ttm.tax_id
	WHERE ttn.tax_class <> 1   -- NO IVA
	GROUP BY	ttm.comp_id,
				ttm.bra_id,
				ttm.it_transaction,
				ttm.ct_transaction


GO









CREATE view [dbo].[vwTaxMovements_PerceptionsIIBBTax]
AS
-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2015-06
-- Parte		:
-- Description	: Retorna Percepciones de IIBB
-- =================================================================================================================



SELECT
		ttm.comp_id,
		ttm.bra_id,
		ttm.ct_transaction,
		ttm.it_transaction,
		ttm.tax_id

	FROM tbTaxMovements ttm				WITH (NOLOCK)
	INNER JOIN tbTaxName ttn			WITH (NOLOCK)
		ON		ttn.comp_id		= ttm.comp_id
			AND ttn.tax_id		= ttm.tax_id
	INNER JOIN tbsysTaxClass ttc
		ON ttc.tax_class = ttn.tax_class
	WHERE	ttc.taxcl_isPerception	= 'True' AND
			ttc.taxcl_isIB			= 'True'


GO







CREATE view [dbo].[vwTaxMovements_TotalIVATax]
AS
-- =================================================================================================================
-- Author		: MOS
-- Update Date	: 2011-02
-- Parte		:
-- Description	: Retorna el total de IVA por cada ItemTransaction
-- =================================================================================================================

SELECT
		ttm.comp_id,
		ttm.bra_id,
		ttm.it_transaction,
		ttm.ct_transaction,
		SUM(ttm.tm_total)		[Total]

	FROM tbTaxMovements ttm						WITH (NOLOCK)
	INNER JOIN tbTaxName ttn					WITH (NOLOCK)
		ON		ttn.comp_id		= ttm.comp_id
			AND ttn.tax_id		= ttm.tax_id
	WHERE ttn.tax_class = 1   -- IVA
	GROUP BY	ttm.comp_id,
				ttm.bra_id,
				ttm.it_transaction,
				ttm.ct_transaction

GO

