-- NO SE USA MAS, DESHABILITADA X CODIGO !!!!!!!
-- Esto genera la tabla tbWebSiteII_ItemsData cada 5 minutos


-- MOS
-- Retorna los precios en las monedas relacionadas a los sitios web para cada lista de precios configurada.
CREATE view [dbo].[vwWebSiteII_ItemsData]
AS




	SELECT
			--DISTINCT
			TOP 90000000
			tpli.comp_id,
			tpli.prli_id,
			tpli.item_id,
			-- Precio Con o Sin Impuestos Segun Configuracion, corregir en Precio SIN Impuestos si se toca algo aca
			(
				(
				CASE
					WHEN	twsiplr.curr_id IS NULL THEN	tpli.prli_price
					ELSE									dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id,twsiplr.curr_id, 0, 0 , 0 , 'False')
				END

					*
				CASE
					WHEN twsiplr.wsplr_ShowPriceInCero = 1 THEN 0
					ELSE										1
				END
					*
				CASE
					WHEN twm.wsmsp_priceType = 1		THEN ((twm.wsmsp_value / 100) + 1)	-- Multiplica por Coeficiente
					ELSE 1
				END
				)
					+
				CASE
					WHEN twm.wsmsp_priceType = 2		THEN twm.wsmsp_value				-- Suma Precio
					ELSE 0
				END
			)
			*
			CASE
				WHEN twsiplr.wsplr_ShowPriceWithTaxes = 'True' THEN dbo.fnGetPriceListItemTaxesCoeficient(tpli.comp_id, tpli.item_id)
				ELSE												1
			END																[prli_price],
			-- Precio Con o Sin Impuestos Segun Configuracion






			CASE
				WHEN	twsiplr.curr_id IS NULL THEN	tpli.curr_id
				ELSE									twsiplr.curr_id
			END																[curr_id],
			twsiplr.ws_id,
			IsNull(tis.itst_cant,0)											[itst_cant],
			IsNull(tis.itst_LastAvailableInRelalculation,0)					[itst_LastAvailableInRelalculation],
			twsiias.cat_id,
			twsiias.subcat_id,
			twsiias.subcataux_id,
			twsiias.ic_id,
			CASE
				WHEN	twsiplr.curr_id IS NULL THEN	tc.curr_symbol
				ELSE									tcR.curr_symbol
			END																[currency_symbol],
			CASE
				WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND tis.itst_LastAvailableInRelalculation > 0 AND tis.itst_LastAvailableInRelalculation >= ti.item_cantOpt			THEN 4	-- MOS 06-2017
				WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND tis.itst_LastAvailableInRelalculation > 0 AND tis.itst_LastAvailableInRelalculation >= ti.item_cantMin			THEN 3	-- MOS 06-2017
				WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND tis.itst_LastAvailableInRelalculation >  0																		THEN 2	-- MOS 06-2017
				WHEN twsiplr.wsplr_UseFastCheck	 = 1 AND ISNULL(tis.itst_LastAvailableInRelalculation,0) <= 0															THEN 1	-- MOS 06-2017
				WHEN twsiplr.wsplr_UseFastCheck	 = 0 AND dbo.fnGetAStock(ti.comp_id, twsiplr.stor_id, ti.item_id, 89999999)	>= ti.item_cantOpt							THEN 4
				WHEN twsiplr.wsplr_UseFastCheck	 = 0 AND dbo.fnGetAStock(ti.comp_id, twsiplr.stor_id, ti.item_id, 89999999)	>= ti.item_cantMin							THEN 3
				WHEN twsiplr.wsplr_UseFastCheck	 = 0 AND dbo.fnGetAStock(ti.comp_id, twsiplr.stor_id, ti.item_id, 89999999)	>  0										THEN 2
				ELSE																																						 1
			END																[semaphoreValue],

			-- Precio Sin Impuestos
			(
				(
				CASE
					WHEN	twsiplr.curr_id IS NULL THEN	tpli.prli_price
					ELSE									dbo.fnGetExchange2(tpli.comp_id, tpli.prli_price, tpli.curr_id,twsiplr.curr_id, 0, 0 , 0 , 'False')
				END

					*
				CASE
					WHEN twsiplr.wsplr_ShowPriceInCero = 1 THEN 0
					ELSE										1
				END
					*
				CASE
					WHEN twm.wsmsp_priceType = 1		THEN ((twm.wsmsp_value / 100) + 1)	-- Multiplica por Coeficiente
					ELSE 1
				END
				)
					+
				CASE
					WHEN twm.wsmsp_priceType = 2		THEN twm.wsmsp_value				-- Suma Precio
					ELSE 0
				END
			)															[prli_priceNOTaxes]
			-- Precio Sin Impuestos

		FROM dbo.tbPriceListItems tpli								WITH (NOLOCK)

		INNER JOIN tbItem ti										WITH (NOLOCK)
			ON	ti.comp_id	= tpli.comp_id	AND
				ti.item_id	= tpli.item_id

		INNER JOIN dbo.tbWebSiteII_Items_AutoSelected twsiias		WITH (NOLOCK)
			ON	twsiias.comp_id = tpli.comp_id AND
				twsiias.item_id = tpli.item_id

		INNER JOIN dbo.tbWebSiteII_PriceListRelation twsiplr		WITH (NOLOCK)
			ON	twsiplr.comp_id = tpli.comp_id AND
				twsiplr.prli_id = tpli.prli_id

		INNER JOIN tbWebSiteII_Names twsin							WITH (NOLOCK)
			ON	twsin.comp_id	= twsiplr.comp_id AND
				twsin.ws_id		= twsiplr.ws_id

		INNER JOIN dbo.tbsysCurrency				tc				WITH (NOLOCK)
			ON tc.curr_id = tpli.curr_id

		LEFT  JOIN dbo.tbsysCurrency				tcR				WITH (NOLOCK)
			ON tcR.curr_id = twsiplr.curr_id


		LEFT JOIN dbo.tbItemStorage					tis				WITH (NOLOCK)
			ON	tis.comp_id = twsiplr.comp_id AND
				tis.stor_id = twsiplr.stor_id AND
				tis.item_id = tpli.item_id



		-- Para saber si YA ESTA como articulo o no.
		-- Solo se usa en el left de abajo para no duplicar filas si un art esta x art y por subcat
		LEFT JOIN tbWebSiteII_microSites			mst			WITH (NOLOCK)
			ON	mst.comp_id				= twsiias.comp_id	AND
				mst.ws_id				= twsiplr.ws_id		AND
				mst.item_id				= tpli.item_id		AND
				mst.prli_id				= tpli.prli_id		AND
				mst.wsmsp_isDisabled	= 0
		LEFT JOIN tbWebSiteII_microSites			twm				WITH (NOLOCK)
			ON	twm.comp_id				= twsiplr.comp_id	AND
				twm.ws_id				= twsiplr.ws_id		AND
				twm.prli_id				= tpli.prli_id		AND
				twm.wsmsp_isDisabled	= 'False'			AND
				CASE
					WHEN	twm.comp_id IS NULL				THEN	0
					WHEN	twm.item_id		= ti.item_id	THEN	1
					WHEN	twm.cat_id		= ti.cat_id		AND
							twm.subcat_id	= ti.subcat_id	AND
							mst.comp_id IS NULL				THEN	1
					ELSE											0
				END		= 1
		-- Para saber si YA ESTA como articulo o no.
		-- Solo se usa en el left de abajo para no duplicar filas si un art esta x art y por subcat




		WHERE
			tpli.prli_price > 0 AND
			CASE
				WHEN twsiplr.wsplr_StockType = 0 																					THEN 1	-- Sin Filtro de Stock
				--Uso precalculo rapido para filtrar ( mas velocidad pero puede no incluir algun articulo por 3 minutos aproximadamente )
				WHEN twsiplr.wsplr_UseFastCheck = 'True' AND tis.itst_LastAvailableInRelalculation > 0 THEN
					CASE
						WHEN twsiplr.wsplr_StockType = 1 AND tis.itst_cant > 0														 THEN 1	-- Stock Fisico
						WHEN twsiplr.wsplr_StockType = 2 AND dbo.fnGetStockOfStorageGroup(tpli.comp_id,tis.stor_id,tis.item_id) > 0  THEN 1	-- Stock Fisico del Grupo de depositos
						WHEN twsiplr.wsplr_StockType = 3 AND dbo.fnGetAStock(  tpli.comp_id,tis.stor_id,tis.item_id,999999999)  > 0  THEN 1	-- Stock Fisico del Grupo de depositos
						ELSE 0
					END
				-- Uso calculo on line
				WHEN twsiplr.wsplr_UseFastCheck = 'False'						THEN
					CASE
						WHEN twsiplr.wsplr_StockType = 1 AND tis.itst_cant > 0	THEN 1	-- Stock Fisico
						WHEN twsiplr.wsplr_StockType = 2 AND dbo.fnGetStockOfStorageGroup(tpli.comp_id,tis.stor_id,tis.item_id) > 0  THEN 1	-- Stock Fisico del Grupo de depositos
						WHEN twsiplr.wsplr_StockType = 3 AND dbo.fnGetAStock(  tpli.comp_id,tis.stor_id,tis.item_id,999999999)  > 0  THEN 1	-- Stock Fisico del Grupo de depositos
						ELSE 0
					END
				ELSE 0
			END = 1				AND
			-- Si es un Micrositio SI o SI debe tener cargado un porcentaje o precio adicional
			CASE
				WHEN	twsin.user_id4MicroSites IS NULL									THEN 1
				WHEN	twsin.user_id4MicroSites IS NOT NULL  AND
						twm.comp_id				 IS NOT NULL								THEN 1
				ELSE																			 0
			END	= 1



		ORDER BY twm.item_id DESC




















GO





-- MOS
-- Retorna los precios en las monedas relacionadas a los sitios web para cada lista de precios configurada.
CREATE view [dbo].[vwWebSiteII_ItemsImages]
AS



	SELECT	11									[imageType]	,
			ti.comp_id,
			ti.item_id,
			convert(nvarchar(200),ti.item_WebSite_url4Image1)			[imageCodeOrURL]
