			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image1 <> ''
		UNION
	SELECT	 12,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image2
		FROM tbWebSiteII_ItemsData twsiid			WITH (NOLOCK)
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image2 <> ''
		UNION
	SELECT	 13,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image3
		FROM tbWebSiteII_ItemsData twsiid			WITH (NOLOCK)
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image3 <> ''
		UNION
	SELECT	 14,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image4
		FROM tbWebSiteII_ItemsData twsiid			WITH (NOLOCK)
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image4 <> ''
		UNION
	SELECT	 15,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image5
		FROM tbWebSiteII_ItemsData twsiid			WITH (NOLOCK)
		INNER JOIN tbItem ti						WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image5 <> ''
		UNION
	SELECT	 16,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image6
		FROM tbWebSiteII_ItemsData twsiid		WITH (NOLOCK)
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image6 <> ''
		UNION
	SELECT	 17,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image7
		FROM tbWebSiteII_ItemsData twsiid		WITH (NOLOCK)
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image7 <> ''
		UNION
	SELECT	 18,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image8
		FROM tbWebSiteII_ItemsData twsiid		WITH (NOLOCK)
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image8 <> ''
		UNION
	SELECT	 19,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image9
		FROM tbWebSiteII_ItemsData twsiid		WITH (NOLOCK)
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image9 <> ''
		UNION
	SELECT	 20,ti.comp_id, ti.item_id,ti.item_WebSite_url4Image10
		FROM tbWebSiteII_ItemsData twsiid		WITH (NOLOCK)
		INNER JOIN tbItem ti					WITH (NOLOCK)
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		WHERE ti.item_WebSite_url4Image10 <> ''
		UNION


	SELECT	 1,ti.comp_id, ti.item_id,ti.item_code
		FROM tbWebSiteII_ItemsData twsiid
		INNER JOIN tbItem ti
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
	WHERE ti.item_picture IS NOT NULL
	UNION
	SELECT	 2,ti.comp_id, ti.item_id,CONVERT(nvarchar(50),tii.itimg_id)
		FROM tbWebSiteII_ItemsData twsiid
		INNER JOIN tbItem ti
			ON	ti.comp_id = twsiid.comp_id AND
				ti.item_id = twsiid.item_id
		INNER JOIN tbItemImages tii
			ON	tii.comp_id = ti.comp_id AND
				tii.item_id = ti.item_id
		WHERE	tii.itimg_image IS NOT NULL AND
				tii.itimg_disabled = 'False'




GO




-- MOS
-- Retorna los Items relacionados de talle y color
CREATE view [dbo].[vwWebSiteII_itemSizeColor]	WITH SCHEMABINDING
AS

	SELECT
			ti.comp_id,
			ti.item_id,
			tiscr.item_id_child			[itemID4SizeColor],
			tc.color_id,
			tc.color_desc,
			tc.color_code ,
			ts.Size_id,
			ts.Size_desc,
			ts.Size_code,
			twsiid.ws_id,
			twsiid.prli_id,
			tiscr.iscr_id
	FROM	   dbo.tbItem							ti			--WITH (NOLOCK)
	INNER JOIN dbo.tbWebSiteII_ItemsData			twsiid		--WITH (NOLOCK)
		ON	twsiid.comp_id = ti.comp_id AND
			twsiid.item_id = ti.item_id
	INNER JOIN dbo.tbItemSizeColorRelation			tiscr		--WITH (NOLOCK)
	ON	tiscr.comp_id = ti.comp_id AND
		tiscr.item_id = ti.item_id
	--INNER JOIN dbo.tbitem							tir			--WITH (NOLOCK)
	--	ON	tir.comp_id = tiscr.comp_id AND
	--		tir.item_id = tiscr.item_id_child
	INNER JOIN dbo.tbColor							tc			--WITH (NOLOCK)
		ON	tc.comp_id	= tiscr.comp_id AND
			tc.color_id = tiscr.color_id
	INNER JOIN dbo.tbSize							ts			--WITH (NOLOCK)
	ON	ts.comp_id = tiscr.comp_id AND
		ts.Size_id = tiscr.size_id
	--WHERE	tir.item_disabled	= 0 AND -- MOS 03-2021: Ya no los tiene por el Inner Join de tbWebSiteII_ItemsData
	--		ti.item_disabled	= 0



GO




-- MOS
-- Retorna los Items relacionados de talle y color
CREATE view [dbo].[vwWebSiteII_itemSizeColor_getOnlyFather]
AS

	SELECT	DISTINCT
			ti.comp_id,
			ti.item_id

	FROM tbItem									ti			WITH (NOLOCK)
