GO






-- MOS
-- Retorna los Items relacionados de talle y color mas variaciones de mercadolibre
CREATE   view [dbo].[vwWebSiteII_itemSizeColorPlusMeLi]
AS

	SELECT
			ti.comp_id,
			ti.item_id,
			tiscr.item_id_child			[itemID4SizeColor],
			ISNULL(tc.color_id,-1)		AS color_id,
			tiscr.color_desc,
			ISNULL(tc.color_code,'MeliCode_' + CONVERT(VARCHAR(10),tiscr.mlpv_id))	AS Color_code ,
			tiscr.size_id,
			tiscr.size_desc,
			ISNULL(ts.Size_code ,'MeLiSize_'  + CONVERT(VARCHAR(10),tiscr.mlpv_id))		AS Size_code,
			twsiid.ws_id,
			twsiid.prli_id,
			twsiid.StockIndex,
			twsiid.semaphoreValue
	FROM tbItem									ti			WITH (NOLOCK)
	INNER JOIN tbWebSiteII_ItemsData			twsiid		WITH (NOLOCK)
		ON	twsiid.comp_id = ti.comp_id AND
			twsiid.item_id = ti.item_id
	INNER JOIN tbWebSiteII_SizeColorPlusMercadoLibreVariations AS tiscr		WITH (NOLOCK)
	ON	tiscr.comp_id = ti.comp_id AND
		tiscr.item_id = ti.item_id
	INNER JOIN tbitem							tir			WITH (NOLOCK)
		ON	tir.comp_id = tiscr.comp_id AND
			tir.item_id = tiscr.item_id_child
	LEFT JOIN tbColor							tc			WITH (NOLOCK)
		ON	tc.comp_id	= tiscr.comp_id AND
			tc.color_id = tiscr.color_id
	LEFT JOIN tbSize							ts			WITH (NOLOCK)
	ON	ts.comp_id = tiscr.comp_id AND
		ts.Size_id = tiscr.size_id
	WHERE	tir.item_disabled	= 0 AND
			ti.item_disabled	= 0



GO














-- MOS
-- Retorna los Stocks Disponiblers para la venta
CREATE view [dbo].[vwWebSiteII_ItemsStock]
AS

	WITH vwTMP AS (
		SELECT	tis.comp_id,
				tis.stor_id,
				tis.item_id,
				tis.itst_cant,
				dbo.fnGetAStock(tis.comp_id, tis.stor_id, tis.item_id, 999999999)   [AvailableStockOfStorageGroup],
				dbo.fnGetStockOfStorageGroup(tis.comp_id, tis.stor_id, tis.item_id)	[PhisicalStockOfStorageGroup],
				--tis.itst_LastAvailableInRelalculation,
				ti.item_cantOpt														[OptimalStock],
				ti.item_cantMin														[MinimalStock]

			FROM tbItemStorage							tis			WITH (NOLOCK)
			INNER JOIN tbWebSiteII_Items_AutoSelected	twsiias		WITH (NOLOCK)
				ON	twsiias.comp_id = tis.comp_id AND
					twsiias.item_id = tis.item_id
			INNER JOIN tbitem							ti			WITH (NOLOCK)
				ON	ti.comp_id = tis.comp_id AND
					ti.item_id = tis.item_id
	)

	SELECT	tis.comp_id,
			tis.stor_id,
			tis.item_id,
			tis.itst_cant,
			tis.AvailableStockOfStorageGroup,
			tis.PhisicalStockOfStorageGroup,
			CASE
				WHEN IsNull(AvailableStockOfStorageGroup,0) >= OptimalStock		THEN 4
				WHEN IsNull(AvailableStockOfStorageGroup,0) >= MinimalStock		THEN 3
				WHEN IsNull(AvailableStockOfStorageGroup,0) >  0				THEN 2
				ELSE																 1
			END																[semaphoreValue],

			CASE
				WHEN AvailableStockOfStorageGroup > OptimalStock THEN	1
				WHEN AvailableStockOfStorageGroup < OptimalStock THEN	3
				ELSE													2
			END																		[StockIndex]
		FROM vwTMP tis	WITH (NOLOCK)






GO



CREATE view [dbo].[vwWebSiteII_SaleOrderDetail]
AS


SELECT
	tsoh.comp_id,
	tsoh.bra_id,
	tsoh.soh_id,
	twsin.ws_id,
	tsod.sod_qty																	[qty],
	tsod.sod_price																	[unitPrice],
	td.disc_coef * 100																[saleOrderDiscountPercentage],
	tsod.sod_itemDiscount															[itemDiscountPercentage],
	tsod.sod_discountByTotal	/	dbo.fnNoZDiv(	CASE
														WHEN tsod.curr_id = tsoh.soh_Currency4Total THEN  tsoh.soh_exchange2Currency4Total
														ELSE											 1
													END
										)											[totalDiscountBySaleOrder],
	tsod.sod_discountByTotal	/	dbo.fnNoZDiv(	CASE
														WHEN tsod.curr_id = tsoh.soh_Currency4Total THEN  tsoh.soh_exchange2Currency4Total
														ELSE											 1
													END
										)	* (1+ (ISNULL(ttn.tax_percentage,0) / 100))			[totalDiscountBySaleOrderPlusTaxes],
	tsod.sod_discountByItem		/	dbo.fnNoZDiv(	CASE
														WHEN tsod.curr_id = tsoh.soh_Currency4Total THEN  tsoh.soh_exchange2Currency4Total
														ELSE											 1
													END
										)											[totalDiscountByItem],
	tsod.sod_discountByItem		/	dbo.fnNoZDiv(	CASE
														WHEN tsod.curr_id = tsoh.soh_Currency4Total THEN  tsoh.soh_exchange2Currency4Total
														ELSE											 1
													END
										)	* (1+ (ISNULL(ttn.tax_percentage,0) / 100))			[totalDiscountByItemPlusTaxes],
	tsod.sod_priceNeto																[itemTotalWithOutTaxes],
	tsod.sod_priceNeto + (	SELECT SUM(tsot.tm_total )
								FROM tbSaleOrderTaxes tsot
	                      		WHERE	tsot.comp_id	= tsod.comp_id	AND
	                      				tsot.bra_id		= tsod.bra_id	AND
	                      				tsot.soh_id		= tsod.soh_id	AND
	                      				tsot.sod_id		= tsod.sod_id

						 )
						/	dbo.fnNoZDiv(	CASE
												WHEN tsod.curr_id = tsoh.soh_Currency4Total THEN  tsoh.soh_exchange2Currency4Total
												ELSE											 1
											END
										)
						/ dbo.fnNoZDiv(tsod.sod_qty)


																					[itemTotalWithTaxes],
	tc.curr_symbol																	[itemTotalCurrencyDesc],
	tc.curr_id																		[itemTotalCurrency],
	ti.item_id,
	ti.item_code,
	CASE
	    WHEN ISNULL(ti.item_WebSite_desc,'') <> ''  THEN ti.item_WebSite_desc
	    ELSE											 ISNULL(ti.item_desc,'Item Manual')
	END																				[item_desc],
	tsoh.soh_Currency4Total,
	tsoh.soh_exchange2Currency4Total,
	CASE
		--WHEN tsod.curr_id = twsin.curr_id4ForceTotal											THEN	tsod.sod_priceNeto
		WHEN tb.curr_id   = twsin.curr_id4ForceTotal AND tsod.curr_id = tsoh.soh_Currency4Total THEN	tsod.sod_priceNeto * dbo.fnNoZDiv(tsoh.soh_exchange2Currency4Total)
		ELSE																							tsod.sod_priceNeto
	END																				[itemTotalWithOutTaxesInWebSiteCurrency],
	CASE
		--WHEN tsod.curr_id = twsin.curr_id4ForceTotal											THEN	tsod.sod_priceNeto
		WHEN tb.curr_id   = twsin.curr_id4ForceTotal AND tsod.curr_id = tsoh.soh_Currency4Total THEN	--tsod.sod_priceNeto * dbo.fnNoZDiv(tsoh.soh_exchange2Currency4Total)
				(
					tsod.sod_priceNeto + (	SELECT SUM(tsot.tm_total )
									FROM tbSaleOrderTaxes tsot
	                      			WHERE	tsot.comp_id	= tsod.comp_id	AND
	                      					tsot.bra_id		= tsod.bra_id	AND
	                      					tsot.soh_id		= tsod.soh_id	AND
	                      					tsot.sod_id		= tsod.sod_id

							 )
							/	dbo.fnNoZDiv(	CASE
													WHEN tsod.curr_id = tsoh.soh_Currency4Total THEN  tsoh.soh_exchange2Currency4Total
													ELSE											 1
												END
											)
							/ dbo.fnNoZDiv(tsod.sod_qty)
				) * dbo.fnNoZDiv(tsoh.soh_exchange2Currency4Total)

		ELSE
				(
					tsod.sod_priceNeto + (	SELECT SUM(tsot.tm_total )
									FROM tbSaleOrderTaxes tsot
	                			WHERE	tsot.comp_id	= tsod.comp_id	AND
	                      					tsot.bra_id		= tsod.bra_id	AND
	                      					tsot.soh_id		= tsod.soh_id	AND
	                      					tsot.sod_id		= tsod.sod_id

							 )
							/	dbo.fnNoZDiv(	CASE
													WHEN tsod.curr_id = tsoh.soh_Currency4Total THEN  tsoh.soh_exchange2Currency4Total
													ELSE											 1
												END
											)
							/ dbo.fnNoZDiv(tsod.sod_qty)
				)

	END																				[itemTotalWithTaxesInWebSiteCurrency],
	TC2.curr_desc																	[curr_descInWebSiteCurrency],
	TC2.curr_symbol																	[curr_symbolInWebSiteCurrency]








	FROM tbSaleOrderDetail						tsod		WITH (NOLOCK)
	INNER JOIN tbSaleOrderHeader				tsoh		WITH (NOLOCK)
	ON	tsoh.comp_id	= tsod.comp_id	AND
		tsoh.bra_id		= tsod.bra_id	AND
		tsoh.soh_id		= tsod.soh_id
	INNER JOIN tbsysCurrency					tc			WITH (NOLOCK)
		ON  tc.curr_id	= tsod.curr_id
	INNER JOIN tbDiscount						td			WITH (NOLOCK)
		ON	td.comp_id	= tsoh.comp_id	AND
			td.disc_id	= tsoh.disc_id
	INNER JOIN tbBranch							tb			WITH (NOLOCK)
		ON	tb.comp_id	= tsoh.comp_id	AND
			tb.bra_id	= tsoh.bra_id
	INNER JOIN tbsysCurrency				 AS tc2			WITH (NOLOCK)
		ON  TC2.curr_id = TB.curr_id
	LEFT JOIN tbItem							ti			WITH (NOLOCK)
		ON	ti.comp_id	= tsod.comp_id	AND
			ti.item_id	= tsod.item_id
	INNER JOIN tbWebSiteII_Names				twsin		WITH (NOLOCK)
		ON twsin.comp_id = tsoh.comp_id
	LEFT JOIN tbTaxName							ttn			WITH (NOLOCK)
		ON	ttn.comp_id = tsod.comp_id	AND
			ttn.tax_id	= tsod.tax_id4IVA


GO





CREATE view [dbo].[vwWebSiteII_SaleOrderHeader]
AS

SELECT
	h.comp_id,
	h.bra_id,
	h.soh_id,
	twsin.ws_id,
	CONVERT(VARCHAR(11),h.soh_cd,105)																		[createDate],
	CONVERT(VARCHAR(11),h.soh_deliveryDate,105)																[deliveryDate],
	vsos.ssos_desc,
	vsos.ssos_isInCommercial																				[isInCommercial],
	vsos.ssos_isForPreparation																				[isForPreparation],
	vsos.ssos_isOkforEmmition																				[isOkforEmmition],
	vsos.ssos_isWebPending																					[isWebPending],
	LTRIM(RTRIM(isnull(tc.curr_symbol,''))) + ' ' +
	CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),h.soh_total))														[strTotalInBranchCurrency],
	LTRIM(RTRIM(isnull(tc2.curr_symbol,''))) + ' ' + CONVERT(VARCHAR,CONVERT(DECIMAL(19,2),h.soh_Atotal))	[strTotalInBranchCurrency4Exchange],

	CASE
		WHEN twsin.curr_id4ForceTotal = tb.curr_id4Exchange THEN	CONVERT(DECIMAL(19,2),h.soh_Atotal)
		ELSE														CONVERT(DECIMAL(19,2),h.soh_total)
	END																										[totalWebSiteCurrency],
	CASE
		WHEN twsin.curr_id4ForceTotal = tb.curr_id4Exchange THEN	tb.curr_id4Exchange
		ELSE														tb.curr_id
	END																										[webSiteCurrencyID],
	CASE
		WHEN twsin.curr_id4ForceTotal = tb.curr_id4Exchange THEN	c.curr_symbol
		ELSE														tc.curr_symbol
	END																										[webSiteCurrencySymbol],
	dbo.fnGetSaleOrderNumber(h.comp_id,h.bra_id,h.soh_id)													[saleOrderNumber],
	h.soh_Currency4Total,
	h.soh_exchange2Currency4Total,
	vsos.lang_id																							[lang_id]
	FROM tbSaleOrderHeader				h				WITH (NOLOCK)
	INNER JOIN tbbranch					tb				WITH (NOLOCK)
		ON	tb.comp_id	= h.comp_id AND
			tb.bra_id	= h.bra_id
	INNER JOIN tbsysCurrency			tc				WITH (NOLOCK)
		ON	tc.curr_id		= tb.curr_id
	INNER JOIN tbsysCurrency			tc2				WITH (NOLOCK)
		ON	tc2.curr_id		= tb.curr_id4Exchange
	INNER JOIN tbsysSaleOrderStatus		ss				WITH (NOLOCK)
		ON ss.ssos_id = h.ssos_id
	INNER JOIN tbWebSiteII_Names		twsin			WITH (NOLOCK)
		ON twsin.comp_id = h.comp_id
	LEFT JOIN tbsysCurrency				c				WITH (NOLOCK)
		ON c.curr_id = twsin.curr_id4ForceTotal

	INNER JOIN tbsysCurrency			j				WITH (NOLOCK)
		ON j.curr_id = h.soh_Currency4Total
	INNER JOIN vwSaleOrderStatus		vsos			WITH (NOLOCK)
		ON	vsos.comp_id	= h.comp_id
		AND vsos.bra_id		= h.bra_id
		AND vsos.soh_id		= h.soh_id AND
			vsos.lang_id = twsin.lang_id







GO




-- MOS
-- Retorna las Categorias con Articulos Asociados Doisponibles
CREATE view [dbo].[vwWebSiteII_salesTerms] WITH SCHEMABINDING
AS


SELECT	DISTINCT
		tst.comp_id,
		CASE
			WHEN tcclp.st_id IS NULL THEN	tst.st_id
			ELSE 							tcclp.st_id
		END												[st_id],
		tst.st_id										[st_id_Original],					-- ID de COndicion de Venta
		CASE
			WHEN ISNULL(tst.st_webSiteDecription,'') = '' THEN	tst.st_desc
			ELSE											tst.st_webSiteDecription
		END										[st_desc],				-- Descripcion WEB de la COndicion de Venta
		tcclp.ccp_id,													-- ID de Plan de PAgos
		CASE
			WHEN ISNULL(tcclp.ccp_desc,ISNULL(tst.st_webSiteDecription,'')) = '' THEN tst.st_desc
			ELSE																 ISNULL(tcclp.ccp_desc,ISNULL(tst.st_webSiteDecription,''))
		END
						[ccp_desc],				-- Descripcion del Plan de Pagos
		ISNULL(tcclp.spgw_id,0)					[spgw_id],				-- ID de GateWay de Pagos (tbsysPaymentGateway)
		ISNULL(tcclp.ccp_PaymentsQty,0)			[ccp_PaymentsQty],		-- Cantidad de Cuotas
		tcclp.brag_id,
		ISNULL(tst.st_MPEnabled,'False')		[st_MPEnabled],
		ISNULL(tst.NPS_Enabled,'False')			[NPS_Enabled],
		ISNULL(tst.VISATP_Enabled,'False')		[VISATP_Enabled]
	FROM  dbo.tbSalesTerms							tst			WITH (NOLOCK)
	LEFT JOIN dbo.tbCreditCard						tcc			WITH (NOLOCK)
		ON	tcc.comp_id	= tst.comp_id AND
			tcc.cc_id	= tst.cc_id
	LEFT JOIN dbo.tbCreditCardLoanPlan				tcclp		WITH (NOLOCK)
		ON	tcclp.comp_id = tcc.comp_id	AND
			tcclp.cc_id	= tcc.cc_id
	WHERE
			tst.st_disabled				= 'False'			AND
			tst.st_available4WebSite	= 'True'			AND
			ISNULL(tcclp.ccp_disabled,'False')			= 'False'			AND
			ISNULL(tcc.cc_disabled,'False')				= 'False'










GO












-- MOS
-- Retorna los spots activos segun la campa#a seleccionada.a.
CREATE view [dbo].[vwWebSiteII_Spots]
AS

	SELECT	TOP 10000
		ca.ws_id,
		re.wsbcr_type								[Type],
		spo.wsban_desc								[Desc],
		spo.wsban_imageNameWithExtension			[imageName],
		spo.wsban_note								[Note],
		spo.wsban_url								[URL],
		spo.wsban_order								[Order],
		re.wsbcr_openModeText						[openMode]
		FROM tbWebSiteII_SpotCampaign ca						WITH (NOLOCK)
		INNER JOIN tbWebSiteII_SpotCampaignRelation re			WITH (NOLOCK)
			ON	re.comp_id			= ca.comp_id	AND
				re.wsbc_id			= ca.wsbc_id
		INNER JOIN tbWebSiteII_Spots spo						WITH (NOLOCK)
			ON	spo.comp_id			= re.comp_id	AND
				spo.wsban_id		= re.wsban_id
		WHERE	ca.wsbc_isActive	= 'True'		AND
				ca.wsbc_disabled	= 'False'		AND
				re.wsbcr_disabled	= 'False'
		ORDER BY spo.wsban_order












GO




