-- MOS
-- Retorna las Categorias con Articulos Asociados Doisponibles
CREATE view [dbo].[vwWebSiteII_subCategoryData] --WITH SCHEMABINDING
AS

	SELECT  vwi.comp_id,
			vwi.cat_id,
			vwi.subcat_id,
			vwi.prli_id,
			COUNT_BIG(*)	[itemsInCategory],
			vwi.subcat_WebSite_desc,
			vwi.ws_id
		FROM dbo.tbWebSiteII_ItemsData vwi	WITH (NOLOCK)
		GROUP BY vwi.comp_id,
				 vwi.cat_id,
				 vwi.subcat_id,
				 vwi.prli_id,
				 vwi.subcat_WebSite_desc,
				 vwi.ws_id

GO


-- MOS
-- Vista con campos precalculados para sitio web
-- select * from tbTempItemStock
-- Select * from vwWebSiteII_tempItemStock

CREATE view [dbo].[vwWebSiteII_tempItemStock] --WITH SCHEMABINDING
AS


SELECT	tis.comp_id,
		tis.tis_id,
		tis.tis_guid,
		tis.item_id,
		ISNULL(ti.item_code,'')												[item_code],
		tis.tis_itemDesc,
		tis.tis_detail,
		tis.tis_qty,
		tis.prli_id,
		tis.stor_id,

		-- Precio TOTAL sin Intereses sumados
		tis.tis_priceInBranchCurrency,
		Convert( DECIMAL(19,4), ROUND(( tis.tis_priceInBranchCurrency 	+ dbo.fntbTempItemStock_getIVA(tis.comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,tis.tis_priceInBranchCurrency / dbo.fnNoZDiv( tis.tis_priceInBranchCurrency ),tis.tis_qty )
										),tdf.df_PriceDecimalPlaces )	 )					[tis_priceInBranchCurrencyWithTaxesNoDiscount],


		Convert( DECIMAL(19,4), ROUND(( tis.tis_priceInBranchCurrency 	+ dbo.fntbTempItemStock_getIVA(tis.comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,tis.tis_priceInBranchCurrency / dbo.fnNoZDiv( tis.tis_priceInBranchCurrency ),tis.tis_qty )
									- (((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv( tis.tis_priceInBranchCurrency / dbo.fnNoZDiv(tis.tis_priceInBranchCurrency )) ) / dbo.fnNoZDiv(tis.tis_qty) )	),tdf.df_PriceDecimalPlaces )	 )					[tis_priceInBranchCurrencyWithTaxes],

		-- Precio TOTAL con Intereses sumados
		tis.tis_totalPriceInBranchCurrency,
		Convert( DECIMAL(19,4), ROUND(( tis.tis_totalPriceInBranchCurrency 	+ dbo.fntbTempItemStock_getIVA(tis.comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,tis.tis_totalPriceInBranchCurrency / dbo.fnNoZDiv( tis.tis_totalPriceInBranchCurrency ),tis.tis_qty )
									- (((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv( tis.tis_totalPriceInBranchCurrency / dbo.fnNoZDiv(tis.tis_totalPriceInBranchCurrency )) ) / dbo.fnNoZDiv(tis.tis_qty) )	),tdf.df_PriceDecimalPlaces )	 )		[tis_totalPriceInBranchCurrencyWithTaxes],

		Convert( DECIMAL(19,4), ROUND(( tis.tis_totalPriceInBranchCurrency 	+ dbo.fntbTempItemStock_getIVA(tis.comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,tis.tis_totalPriceInBranchCurrency / dbo.fnNoZDiv( tis.tis_totalPriceInBranchCurrency ),tis.tis_qty )
										),tdf.df_PriceDecimalPlaces )	 )		[tis_totalPriceInBranchCurrencyWithTaxesNoDiscount],

		-- Precio NETO mas IVA del Item
		Convert( DECIMAL(19,4), ROUND( tis.tis_PriceInBranchCurrency * dbo.fnGetPriceListItemTaxesCoeficient4Combo(tis.comp_id,tis.bra_id,tis.item_id,tis.prli_id) ,tdf.df_PriceDecimalPlaces))
																				[tis_OriginalPriceInBranchCurrencyWithTaxes],

		-- -----------------------------------------------------------------------------------------------------------
		-- Descuento Mas IVA:[tis_OriginalPriceInBranchCurrencyWithTaxes] - [tis_totalPriceInBranchCurrencyWithTaxes]
		-- -----------------------------------------------------------------------------------------------------------
		(
				Convert( DECIMAL(19,4), ROUND( tis.tis_PriceInBranchCurrency * dbo.fnGetPriceListItemTaxesCoeficient4Combo(tis.comp_id,tis.bra_id,tis.item_id,tis.prli_id) ,tdf.df_PriceDecimalPlaces))
		)
			-
		(		Convert( DECIMAL(19,4), ROUND(( tis.tis_totalPriceInBranchCurrency 	+ dbo.fntbTempItemStock_getIVA(tis.comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,tis.tis_totalPriceInBranchCurrency / dbo.fnNoZDiv( tis.tis_totalPriceInBranchCurrency ),tis.tis_qty )
									- (((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv( tis.tis_totalPriceInBranchCurrency / dbo.fnNoZDiv(tis.tis_totalPriceInBranchCurrency )) ) / dbo.fnNoZDiv(tis.tis_qty) )	),tdf.df_PriceDecimalPlaces )	 )
		)

																				[tis_DiscountPlusTaxes],
		-- -----------------------------------------------------------------------------------------------------------
		-- -----------------------------------------------------------------------------------------------------------
		-- Descuento Mas IVA:[tis_OriginalPriceInBranchCurrencyWithTaxes] - [tis_totalPriceInBranchCurrencyWithTaxes]
		-- -----------------------------------------------------------------------------------------------------------

		tis.tis_qty *
		(
		(
				Convert( DECIMAL(19,4), ROUND( tis.tis_PriceInBranchCurrency * dbo.fnGetPriceListItemTaxesCoeficient4Combo(tis.comp_id,tis.bra_id,tis.item_id,tis.prli_id) ,tdf.df_PriceDecimalPlaces))
		)
			-
		(		Convert( DECIMAL(19,4), ROUND(( tis.tis_totalPriceInBranchCurrency 	+ dbo.fntbTempItemStock_getIVA(tis.comp_id,tis.bra_id,tis.tis_id,tis.tis_costTax,tis.tis_totalPriceInBranchCurrency / dbo.fnNoZDiv( tis.tis_totalPriceInBranchCurrency ),tis.tis_qty )
									- (((tis.tis_itemDiscountTotal + tis.tis_totalDiscountTOTAL) / dbo.fnNoZDiv( tis.tis_totalPriceInBranchCurrency / dbo.fnNoZDiv(tis.tis_totalPriceInBranchCurrency )) ) / dbo.fnNoZDiv(tis.tis_qty) )	),tdf.df_PriceDecimalPlaces )	 )
		)
		)

																				[tis_DiscountPlusTaxesTOTAL],
		-- -----------------------------------------------------------------------------------------------------------


		tis.tis_cd,
		tis.tis_CreditInt,
		tis.tis_CreditIntPlus,
		tis.tis_itemDiscount,
		tis.tis_itemDiscountTotal,
		tis.tis_totalDiscountTOTAL,
		ISNULL(tis.tis_isParentAssociate,'False')							[tis_isParentAssociate],
		CASE
			WHEN tis.tis_isParentAssociate = 'False' AND tis_id_origin IS NOT NULL THEN convert(bit,1)
			ELSE																		convert(bit,0)
		END																	[tis_isChildAssociate],
		CASE
			WHEN tis.tis_id_origin IS NOT NULL THEN CONVERT(BIT,1)
			ELSE									CONVERT(BIT,0)
		END																	[isItemAsociation],
		ISNULL(ti.item_WebSite_desc	,tis_itemDesc)							[item_WebSite_desc],
		ISNULL(ti.item_desc			,tis_itemDesc)							[item_desc],
		ISNULL(tis.tis_DeliveryCharge,'False')								[tis_isDeliveryCharge],
		dbo.fnGetAStock(tis.comp_id, tis.stor_id, tis.item_id, 99999999)	[availableStock],
		ti.item_detail, ti.item_vendorCode, ti.item_upb, ti.item_annotation, ti.item_annotation1,
		ti.item_annotation2, ti.item_web, ti.item_newness, ti.item_liquidation,
		ti.item_weight, ti.item_volume, ti.item_large, ti.item_wide, ti.item_higth,
		tc.cat_id, tc.cat_desc,
		tsc.subcat_id, tsc.subcat_desc,
		tb.brand_id, tb.brand_desc,
		tis.item_id_EW,
		tis.tis_idOfThisEW,
		tis.tis_itemIDOfThisEW,
		ISNULL(tis.ws_IPFrom,'')											[ws_IPFrom],
		-- Es una Garantia Extendida ?
		CASE
			WHEN tis.item_id_EW IS NULL AND tis.tis_idOfThisEW IS NOT NULL THEN convert(bit,1)
			ELSE																		convert(bit,0)
		END																	[tis_isExtendedWarranty],
		-- Tiene asociada una Garantia Extendida ?
		CASE
			WHEN tis.item_id_EW IS NOT NULL AND tis.tis_idOfThisEW IS NULL THEN convert(bit,1)
			ELSE																		convert(bit,0)
		END																	[tis_hasExtendedWarranty]	,
		-- El Articulo tiene disponibles para asociar Garantias Extendidas ?
		CASE
			WHEN EXISTS(	SELECT TOP 1 tiew.comp_id
			            		FROM tbItemExtendedWarranty tiew
			            		WHERE tb.comp_id = tis.comp_id AND tiew.item_id = tis.item_id
						)  THEN convert(bit,1)
			ELSE convert(bit,0)
		END																	[tis_itemHasExtendedWarranty],
		tis.tis_order,
		tis.tis_isEnvioPackItem,
		tis.wscup_id


	FROM dbo.tbTempItemStock					tis							WITH (NOLOCK)
	LEFT JOIN dbo.tbitem						ti							WITH (NOLOCK)
	ON	ti.comp_id		= tis.comp_id AND
		ti.item_id		= tis.item_id
	INNER JOIN dbo.tbDocumentsFile				tdf							WITH (NOLOCK)
		ON	tdf.comp_id = tis.comp_id AND
			tdf.df_id	= tis.df_id

	LEFT JOIN tbCategory tc							WITH (NOLOCK)
		ON	tc.comp_id	= ti.comp_id		AND
			tc.cat_id	= ti.cat_id

	LEFT JOIN tbSubCategory tsc						WITH (NOLOCK)
		ON	tsc.comp_id		= ti.comp_id	AND
			tsc.cat_id		= ti.cat_id		AND
			tsc.subcat_id	= ti.subcat_id

	LEFT JOIN tbBrand tb							WITH (NOLOCK)
		ON	tb.comp_id		= ti.comp_id	AND
			tb.brand_id		= ti.brand_id














GO










create VIEW [dbo].[vwzPecas___________________________________________]
AS

SELECT 1 [1]
GO








CREATE VIEW [dbo].[vwzPecas_APLICA]
AS


SELECT	ta.comp_id								[COMPANIA],
		ta.ct_transaction_Source				[NUMREL_O],
		ta.ct_transaction_destiny				[NUMREL_D],
		convert(decimal(19,6),ta.appl_coef)		[PORAPL],
		convert(decimal(19,2),ta.appl_total)	[IMPAPL],
		ta.appl_id								[INTERNO]

FROM	tbApplication ta
GO









create VIEW [dbo].[vwzPecas_AREAS]
AS


SELECT	tss.comp_id				[COMPANIA],
		tss.ss_id				[AREA],
		tss.ss_desc				[NOMBRE]

FROM	tbSaleSector tss
GO









CREATE VIEW [dbo].[vwzPecas_ARTICULOS]
AS


SELECT	ti.comp_id				[COMPANIA],
		tb.bra_id				[CLISUC],
		ti.item_id				[CODAR],
		ti.item_desc			[NOMBRE],
		ti.cat_id				[CODRUB],
		ti.subcat_id			[CODSUB],
		ti.brand_id				[CODMAR],
		isnull(dbo.fnGetExchange(ti.comp_id,ticl.coslis_price,ticl.curr_id,tb.curr_id,0,0,'false'),0)		[COSTO],
		isnull(dbo.fnGetExchange(ti.comp_id,ticl.coslis_price_aw,ticl.curr_id,tb.curr_id,0,0,'false'),0)	[COSTOPPP],
		tis.itst_cant			[STOCK1],
		0						[STOCK2],
		0						[STOCK3],
		0						[STOCK4],
		0						[STOCK5],
		'   '					[FABRICA],
      	ti.pres_id				[CODPRES],
      	tb.coslis_id			[CODDEPOSITO],
      	ti.item_markup_1		[MARKUP1],
      	ti.item_markup_2		[MARKUP2],
      	ti.item_markup_3		[MARKUP3]

FROM	tbItem								ti

		LEFT JOIN tbBranch					tb
		ON	tb.comp_id		= ti.comp_id

		LEFT JOIN tbItemCostList			ticl
		ON  ticl.comp_id	= ti.comp_id
		AND ticl.coslis_id	= tb.coslis_id
		AND ticl.item_id	= ti.item_id

		LEFT JOIN tbItemStorage				tis
		ON	tis.comp_id		= ti.comp_id
		AND tis.item_id		= ti.item_id
		AND tis.stor_id		= tb.stor_id


GO









Create VIEW [dbo].[vwzPecas_ASIENTO_DETALLE]
AS


SELECT	tatd.comp_id									[COMPANIA],
		tatd.dacc_transaction							[NUMERO],
		DATEADD(dd,0,DATEDIFF(dd,0,tatd.dacc_cd))		[FECHA],
		tatd.acc_detail1								[LEYENDA1],
		tatd.acc_detail2								[LEYENDA2],
      	tatd.acc_count_id								[CUENTA],

      	CASE
      		WHEN tatd.dacc_debit	> 0 THEN 'DEB'
      		WHEN tatd.dacc_credit	> 0 THEN 'HAB'
      	END												[TIPO],

      	CASE
      		WHEN tatd.dacc_debit	> 0 THEN tatd.dacc_debit
      		WHEN tatd.dacc_credit	> 0 THEN tatd.dacc_credit
      	END												[IMPORTE],

      	tatd.ct_transaction								[NUMREL],
      	tatd.cc_code									[CENTROCOSTO]

FROM	tbAccountTransactionDetail tatd


GO









CREATE VIEW [dbo].[vwzPecas_CENTROS_COSTOS]
AS


SELECT	tcc.comp_id			[COMPANIA],
		tcc.cc_code			[CENTROCOSTO],
		tcc.cc_desc			[NOMBRE]

FROM	tbCostCenter tcc


GO









CREATE VIEW [dbo].[vwzPecas_CLIENTES]
AS


SELECT	tc.comp_id					[COMPANIA],
		tc.cust_id					[CODCLI],
		tc.cust_name				[NOMBRE],
		tc.country_id				[CODPAIS],
		tc.state_id					[COSPROV],
		tc.fc_id					[TIPOIVA],
		tc.dl_id					[CODREP],
		tc.sm_id					[CODVEN],
		tc.ck_id					[CODLIN],
		tc.prli_id					[LISTA],
		tc.cust_zip					[CODPOSTAL],
		tc.cust_name1				[NOMBRE_ALT],
		tc.cust_address				[DOMICILIO],
		tc.cust_phone1				[TELEFONO],
		tc.cust_email				[EMAIL],
		ISNULL(tc2.city_desc,'')	[CIUDAD]

FROM	tbCustomer tc

		LEFT JOIN tbCities tc2
		ON	tc2.country_id	= tc.country_id
		AND tc2.state_id	= tc.state_id
		AND tc2.city_id		= tc.city_id


GO









CREATE VIEW [dbo].[vwzPecas_COBRANZAS]
AS


SELECT	tct.comp_id												[COMPANIA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_date))				[FECHA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_payDate))				[FECHAVTO],
		tct.df_id												[TICOMP],
		ltrim(rtrim(tct.ct_kindOf))								[TIPOCOMP],
		tct.ct_pointOfSale										[SUCURSAL],
		ltrim(rtrim(tct.ct_docNumber))							[NUMERO],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_total,tct.curr_id_transaction,tb.curr_id,0,0,'false') -
			dbo.fnGetExchange(tct.comp_id,tct.ct_discount,tct.curr_id_transaction,tb.curr_id,0,0,'false')
			)													[NETO],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_total,tct.curr_id_transaction,tb.curr_id,0,0,'false')
			)													[IMPORTE],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_ABalance,tct.ct_ACurrency,tb.curr_id,tct.ct_ACurrency,tct.ct_ACurrencyExchange,'false')
			)													[SALDO],
		tct.sm_id												[CODVEN],
		tct.dl_id												[CODREP],
		tct.cust_id												[CODCLI],
		0														[PORGAN],
		tct.ct_transaction										[NUMREL],
		0														[CLISUC],
		0														[COSTO],
		tc.ss_id												[AREA],
		tc.country_id											[CODPAIS],
		tc.state_id												[CODPROV],
		0														[BULTOS],
		''														[ENTIDAD],
		tct.[user_id]											[OPERADOR],
		0														[TERMINAL],
		0														[GANACIA],
		tc.ck_id												[CODLIN],
		tct.st_id												[CONDVTA]


FROM	tbCommercialTransactions		tct

		INNER JOIN tbBranch				tb
		ON	tb.comp_id		= tct.comp_id
		AND tb.bra_id		= tct.bra_id

		INNER JOIN tbCustomer			tc
		ON	tc.comp_id		= tct.comp_id
		AND tc.cust_id		= tct.cust_id

WHERE	tct.sd_id IN (6,13)


GO






CREATE VIEW [dbo].[vwzPecas_CODIGOS_POSTALES]
AS


SELECT	DISTINCT
		tc.comp_id			[COMPANIA],
		tc.cust_zip			[CODPOSTAL],
		tc.cust_zip			[NOMBRE]

FROM	tbCustomer tc

WHERE	NOT tc.cust_zip IS NULL
AND		LEN(tc.cust_zip) > 0

UNION

SELECT	DISTINCT
		tc.comp_id			[COMPANIA],
		tc.supp_zip			[CODPOSTAL],
		tc.supp_zip			[NOMBRE]

FROM	tbSupplier tc

WHERE	NOT tc.supp_zip IS NULL
AND		LEN(tc.supp_zip) > 0


GO







create VIEW [dbo].[vwzPecas_COMPANIA]
AS


SELECT	tc.comp_id			[COMPANIA],
		tc.comp_desc		[NOMBRE]

FROM	tbCompany tc
GO









CREATE VIEW [dbo].[vwzPecas_COMPRAS]
AS


SELECT	tct.comp_id												[COMPANIA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_date))				[FECHA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_payDate))				[FECHAVTO],
		tct.sd_id												[TICOMP],
		ltrim(rtrim(tct.ct_kindOf))								[TIPOCOMP],
		tct.ct_pointOfSale										[SUCURSAL],
		ltrim(rtrim(tct.ct_docNumber))							[NUMERO],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_total,tct.curr_id_transaction,tb.curr_id,0,0,'false') -
			dbo.fnGetExchange(tct.comp_id,tct.ct_discount,tct.curr_id_transaction,tb.curr_id,0,0,'false')
			)													[NETO],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_total,tct.curr_id_transaction,tb.curr_id,0,0,'false')
			)													[IMPORTE],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange2(tct.comp_id,tct.ct_ABalance,tct.ct_ACurrency,tb.curr_id,tct.ct_ACurrency,tb.curr_id,tct.ct_ACurrencyExchange,'false')
			)													[SALDO],
		tct.supp_id												[CODPRO],
		tct.ct_transaction										[NUMREL],
		tct.puco_id												[CODCON],
		0														[CLISUC],
		ts.country_id											[CODPAIS],
		ts.state_id												[CODPROV]


FROM	tbCommercialTransactions		tct

		INNER JOIN vwCommercialTransactions_forPurchase vctfp
		ON vctfp.comp_id = tct.comp_id
		AND vctfp.bra_id = tct.bra_id
		AND vctfp.ct_transaction = tct.ct_transaction

		INNER JOIN tbBranch				tb
		ON	tb.comp_id		= tct.comp_id
		AND tb.bra_id		= tct.bra_id

		INNER JOIN tbSupplier ts
		ON	ts.comp_id		= tct.comp_id
		AND ts.supp_id		= tct.supp_id

--WHERE	tct.sd_id IN (6,13)


GO






