CREATE VIEW [dbo].[vwzPecas_FECHAS]
AS


SELECT	tct.comp_id																	[COMPANIA],
		tct.ct_transaction															[NUMREL],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_date))									[FECHA],
		YEAR	(tct.ct_date)														[ANO],
		MONTH	(tct.ct_date)														[MES],
		DAY		(tct.ct_date)														[DIA],
		DATEPART(weekday,tct.ct_date)												[DIASEM],
		DATEPART(week,tct.ct_date)													[SEMANA],
		CASE WHEN DAY(tct.ct_date) < 15 THEN 1 ELSE 2 END * MONTH(tct.ct_date)		[QUINCENA],
		DATEPART(quarter,tct.ct_date)												[TRIMESTRE],
		CASE WHEN DATEPART(quarter,tct.ct_date) < 3 THEN 1 ELSE 2 END				[SEMESTRE],
		CONVERT(char(8),tct.ct_date,108)											[HORA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_payDate))									[FECHAVTO],
		MONTH	(tct.ct_payDate)													[MESVTO],
		YEAR	(tct.ct_payDate)													[ANOVTO]

FROM	tbCommercialTransactions tct


GO









