CREATE VIEW [dbo].[vwzPecas_MOVSTK]
AS



SELECT	tit.comp_id												[COMPANIA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_date))				[FECHA],
		tit.item_id												[CODAR],
		CONVERT(DECIMAL(20,4),tit.it_qty)						[CANT],
		CONVERT(DECIMAL(18,4),tit.it_price)						[PRECIO],
		CONVERT(DECIMAL(18,4),tit.it_priceOfCost)				[COSTO],
		CONVERT(DECIMAL(18,4),vitpam.MarkUp)					[GANANCIA],
		CONVERT(DECIMAL(18,4),vitpam.Profit)					[PROFIT],
		tit.ct_transaction										[NUMREL],
		tct.sd_id												[TICOMP],
		LTRIM(RTRIM(tct.ct_kindOf))								[TIPOCOMP],
		tct.ct_pointOfSale										[SUCURSAL],
		LTRIM(RTRIM(tct.ct_docNumber))							[NUMERO],
		'false'													[COMVEN],
		tct.bra_id												[CLISUC],
		tct.cust_id												[CODCLI],
		tct.supp_id												[CODPRO],
		tit.stor_id												[CODDEPOSITO],
		tct.[user_id]											[CODOP],
		CONVERT(DECIMAL(18,6),tit.it_exchangeToBranchCurrency)	[COTIZACION],
		'false'													[RMA],
		tct.ct_soh_id											[NUMPED],
		ti.cat_id												[CODRUB],
		ti.subcat_id											[CODSUB],
		ti.brand_id												[CODMAR],
		tct.sm_id												[CODVEN],
		tct.dl_id												[CODREP],
		tc.country_id											[CODPAIS],
		tc.state_id												[CODPROV],
		ti.pres_id												[CODPRES],
		tc.ck_id												[CODLIN],
		CONVERT(DECIMAL(18,6),vit.vw_itemUnitPriceWithTaxes)	[PRECIOFINAL],
		CONVERT(DECIMAL(18,6),vitpam.Cost)						[COSTOFINAL],
		CONVERT(DECIMAL(18,6),vitpam.CostPP)					[COSTOFINALPP],
		CONVERT(DECIMAL(18,6),vitooit.tax_id)					[PORCENTAJE_IVA],
		tct.[user_id]											[OPERADOR],
		tc.ss_id												[AREA],
		tct.st_id												[CONDVTA],
		CONVERT(DECIMAL(20,4),0)								[CANT_RMA],
		tit.it_transaction										[NUMREL_STK]


FROM	tbItemTransactions									tit

		INNER JOIN tbCommercialTransactions					tct
		ON	tct.comp_id				= tit.comp_id
		AND tct.bra_id				= tit.bra_id
		AND tct.ct_transaction		= tit.ct_transaction

		INNER JOIN vwCommercialTransactions_forSales		vctfs
		ON	vctfs.comp_id			= tct.comp_id
		AND vctfs.bra_id			= tct.bra_id
		AND vctfs.ct_transaction	= tct.ct_transaction

		INNER JOIN vwItemTransactions						vit
		ON	vit.comp_id				= tit.comp_id
		AND vit.bra_id				= tit.bra_id
		AND vit.ct_transaction		= tit.ct_transaction
		AND vit.it_transaction		= tit.it_transaction

		INNER JOIN vwItemTransactionsProfitAndMarckup		vitpam
		ON	vitpam.comp_id			= tit.comp_id
		AND vitpam.bra_id			= tit.bra_id
		AND vitpam.ct_transaction	= tit.ct_transaction
		AND vitpam.it_transaction	= tit.it_transaction

		LEFT JOIN tbItem									ti
		ON	ti.item_id				= tit.item_id
		AND ti.comp_id				= tit.comp_id

		LEFT JOIN vwItemTaxesOnlyOneIvaTax					vitooit
		ON	vitooit.comp_id			= ti.comp_id
		AND vitooit.item_id			= ti.item_id

		LEFT JOIN tbCustomer								tc
		ON	tc.comp_id				= tct.comp_id
		AND tc.cust_id				= tct.cust_id

GO








CREATE VIEW [dbo].[vwzPecas_MOVSTK_COMPRAS]
AS



SELECT	tit.comp_id												[COMPANIA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_date))				[FECHA],
		tit.item_id												[CODAR],
		CONVERT(DECIMAL(20,4),tit.it_qty)						[CANT],
		CONVERT(DECIMAL(18,4),tit.it_price)						[PRECIO],
		CONVERT(DECIMAL(18,4),tit.it_priceOfCost)				[COSTO],
		CONVERT(DECIMAL(18,4),vitpam.MarkUp)					[GANANCIA],
		CONVERT(DECIMAL(18,4),vitpam.Profit)					[PROFIT],
		tit.ct_transaction										[NUMREL],
		tct.sd_id												[TICOMP],
		LTRIM(RTRIM(tct.ct_kindOf))								[TIPOCOMP],
		tct.ct_pointOfSale										[SUCURSAL],
		LTRIM(RTRIM(tct.ct_docNumber))							[NUMERO],
		'false'													[COMVEN],
		tct.bra_id												[CLISUC],
		tct.cust_id												[CODCLI],
		tct.supp_id												[CODPRO],
		tit.stor_id												[CODDEPOSITO],
		tct.[user_id]											[CODOP],
		CONVERT(DECIMAL(18,6),tit.it_exchangeToBranchCurrency)	[COTIZACION],
		'false'													[RMA],
		tct.ct_soh_id											[NUMPED],
		ti.cat_id												[CODRUB],
		ti.subcat_id											[CODSUB],
		ti.brand_id												[CODMAR],
		tct.sm_id												[CODVEN],
		tct.dl_id												[CODREP],
		ts.country_id											[CODPAIS],
		ts.state_id												[CODPROV],
		ti.pres_id												[CODPRES],
		0														[CODLIN],
		CONVERT(DECIMAL(18,6),vit.vw_itemUnitPriceWithTaxes)	[PRECIOFINAL],
		CONVERT(DECIMAL(18,6),vitpam.Cost)						[COSTOFINAL],
		CONVERT(DECIMAL(18,6),vitpam.CostPP)					[COSTOFINALPP],
		CONVERT(DECIMAL(18,6),vitooit.tax_id)					[PORCENTAJE_IVA],
		tct.[user_id]											[OPERADOR],
		0														[AREA],
		tct.st_id												[CONDVTA],
		CONVERT(DECIMAL(20,4),0)								[CANT_RMA],
		tit.it_transaction										[NUMREL_STK]


FROM	tbItemTransactions									tit

		INNER JOIN tbCommercialTransactions					tct
		ON	tct.comp_id				= tit.comp_id
		AND tct.bra_id				= tit.bra_id
		AND tct.ct_transaction		= tit.ct_transaction

		INNER JOIN vwCommercialTransactions_forPurchase 	vctfs
		ON	vctfs.comp_id			= tct.comp_id
		AND vctfs.bra_id			= tct.bra_id
		AND vctfs.ct_transaction	= tct.ct_transaction

		INNER JOIN vwItemTransactions						vit
		ON	vit.comp_id				= tit.comp_id
		AND vit.bra_id				= tit.bra_id
		AND vit.ct_transaction		= tit.ct_transaction
		AND vit.it_transaction		= tit.it_transaction

		INNER JOIN vwItemTransactionsProfitAndMarckup		vitpam
		ON	vitpam.comp_id			= tit.comp_id
		AND vitpam.bra_id			= tit.bra_id
		AND vitpam.ct_transaction	= tit.ct_transaction
		AND vitpam.it_transaction	= tit.it_transaction

		INNER JOIN tbItem									ti
		ON	ti.item_id				= tit.item_id
		AND ti.comp_id				= tit.comp_id

		INNER JOIN vwItemTaxesOnlyOneIvaTax					vitooit
		ON	vitooit.comp_id			= ti.comp_id
		AND vitooit.item_id			= ti.item_id

		LEFT JOIN tbSupplier								ts
		ON	ts.comp_id				= tct.comp_id
		AND ts.supp_id				= tct.supp_id

GO









