CREATE VIEW [dbo].[vwzPecas_ORDENES_DE_COMPRA]
AS


SELECT	tpoh.comp_id											[COMPANIA],
		tpoh.poh_id												[NUMORD],
		tpoh.supp_id											[CODPRO],
		tpod.item_id											[CODAR],
		convert(decimal(18,2),tpod.pod_qty)						[CANTIDAD],
		convert(decimal(17,2),tpod.pod_price)					[IMPORTE],
		DATEADD(dd,0,DATEDIFF(dd,0,tpoh.poh_cd))				[FECHA],
		DATEADD(dd,0,DATEDIFF(dd,0,tpoh.poh_deliveryDate))		[ENTREGA],
		tpod.pod_id												[INTERNO]


FROM	tbPurchaseOrderHeader						tpoh

		INNER JOIN tbPurchaseOrderDetail			tpod
		ON	tpod.poh_id			= tpoh.poh_id
		AND tpod.comp_id		= tpoh.comp_id
		AND tpod.bra_id			= tpoh.bra_id
GO









