		DATEADD(dd,0,DATEDIFF(dd,0,tsoh.soh_cd))			[FECHA],
		DATEADD(dd,0,DATEDIFF(dd,0,tsoh.soh_deliveryDate))	[ENTREGA],
		CONVERT(DECIMAL(18,2),tsod.sod_qty)					[CANTIDAD],
		tsod.item_id										[CODAR],
		tsoh.sm_id											[CODVEN],
		tsod.sod_id											[INTERNO]


FROM	tbSaleOrderHeader					tsoh

		INNER JOIN tbSaleOrderDetail		tsod
		ON	tsod.bra_id			= tsoh.bra_id
		AND tsod.comp_id		= tsoh.comp_id
		AND tsod.soh_id			= tsoh.soh_id
GO







