CREATE VIEW [dbo].[vwzPecas_VENTAS]
AS



SELECT	tct.comp_id												[COMPANIA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_date))				[FECHA],
		DATEADD(dd,0,DATEDIFF(dd,0,tct.ct_payDate))				[FECHAVTO],
		tct.sd_id												[TICOMP],
		ltrim(rtrim(tct.ct_kindOf))								[TIPOCOMP],
		tct.ct_pointOfSale										[SUCURSAL],
		ltrim(rtrim(tct.ct_docNumber))							[NUMERO],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_total,tct.curr_id_transaction,tb.curr_id,0,0,'false') -
			dbo.fnGetExchange(tct.comp_id,tct.ct_discount,tct.curr_id_transaction,tb.curr_id,0,0,'false')
			)													[NETO],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_total,tct.curr_id_transaction,tb.curr_id,0,0,'false')
			)													[IMPORTE],
		CONVERT(DECIMAL(17,2),
			dbo.fnGetExchange(tct.comp_id,tct.ct_ABalance,tct.ct_ACurrency,tb.curr_id,tct.ct_ACurrency,tct.ct_ACurrencyExchange,'false')
			)													[SALDO],
		tct.sm_id												[CODVEN],
		tct.dl_id												[CODREP],
		tct.cust_id												[CODCLI],
		CONVERT(DECIMAL(18,6),0)								[PORGAN],
		tct.ct_transaction										[NUMREL],
		tct.bra_id												[CLISUC],
		CONVERT(DECIMAL(17,2),0)								[COSTO],
		''														[ZONA],
		tc.ss_id												[AREA],
		tc.country_id											[CODPAIS],
		tc.state_id												[CODPROV],
		CONVERT(DECIMAL(17,4),0)								[BULTOS],
		0														[ENTIDAD],
		tct.[user_id]											[OPERADOR],
		0														[TERMINAL],
		CONVERT(DECIMAL(17,4),vctpam.Profit)					[GANANCIA],
		tc.ck_id												[CODLIN],
		tct.st_id												[CONDVTA]



FROM	tbCommercialTransactions							tct

		INNER JOIN vwCommercialTransactions_forSales		vctfs
		ON	vctfs.comp_id			= tct.comp_id
		AND vctfs.bra_id			= tct.bra_id
		AND vctfs.ct_transaction	= tct.ct_transaction

		INNER JOIN vwCommercialTransactionsProfitAndMarckup vctpam
		ON vctpam.comp_id			= vctfs.comp_id
		AND vctpam.bra_id			= vctfs.bra_id
		AND vctpam.ct_transaction	= vctfs.ct_transaction

		INNER JOIN tbBranch									tb
		ON  tb.comp_id				= tct.comp_id
		AND tb.bra_id				= tct.bra_id

		INNER JOIN tbCustomer								tc
		ON	tc.comp_id				= tct.comp_id
		AND tc.cust_id				= tct.cust_id

GO
