-- =============================================
-- Author:		MOS
-- Create date: 08-2013
-- Description:	Si se trata de poner como NO imputable una cuenta que ya tiene asientos la deja de nuevo como SI IMPUTABLE
-- =============================================
CREATE TRIGGER trAccountant
   ON  tbAccountant
   AFTER UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @acc_count_id	AS INT,
			@comp_id		AS INT,
			@acc_imputable  AS BIT,
			@acc_count_sum	AS INT

	SELECT	@comp_id		= comp_id,
			@acc_count_id	= acc_count_id,
			@acc_imputable	= acc_imputable,
			@acc_count_sum  = acc_count_sum
	FROM INSERTED

	IF @acc_imputable = 'False' AND
		(EXISTS(
				SELECT 1
					FROM	tbAccountTransactionDetail			tatd
					WHERE	tatd.comp_id		= @comp_id		AND
							tatd.acc_count_id	= @acc_count_id
		        )
		 OR
		 EXISTS(
				SELECT 1
					FROM	tbAccountTransactionDetailTMP		tatd
					WHERE	tatd.comp_id		= @comp_id		AND
							tatd.acc_count_id	= @acc_count_id

		       )
		)
		BEGIN

			-- Vuelvo a dejarla como IMPUTABLE
			UPDATE tbAccountant
				SET
						acc_imputable	= 'True'
				WHERE	comp_id			= @comp_id		AND
						acc_count_id	= @acc_count_id

			-- SI ALGUNA SUMARIZABA EN ESTA CUENTA SE SACA LA SUMARIZACION:!!
			UPDATE tbAccountant
				SET
						acc_count_sum	= @acc_count_sum
				WHERE	comp_id			= @comp_id		AND
						acc_count_sum	= @acc_count_id

		END



END
GO

