CREATE TRIGGER [dbo].[trAccountTransactionHead_hacc_2ndCurrencyExchange]
						   ON  [dbo].[tbAccountTransactionHead]
AFTER INSERT
AS
BEGIN


	DECLARE @decCurrencyExchange	AS decimal(19,4)
	DECLARE @compid					AS INT
	DECLARE @bra_id					AS INT
	DECLARE @intCompanyCurrency		AS INT
	DECLARE @intBranchCurrency		AS INT
	DECLARE @intCompany2ndCurrency	AS INT
	DECLARE @intHacc_transaction	AS INT
	DECLARE @intDacc_transaction	AS INT

	SELECT	@decCurrencyExchange = hacc_2ndCurrencyExchange,
			@compid				 = comp_id,
			@bra_id				 = bra_id,
			@intHacc_transaction = hacc_transaction,
			@intDacc_transaction = hacc_transaction
		FROM INSERTED

	SELECT @intCompanyCurrency		= curr_id ,
		   @intCompany2ndCurrency	= curr_id_2ndCurrency
		FROM tbCompany	WITH (NOLOCK)
		WHERE comp_id				= @compid

	SELECT @intBranchCurrency		= curr_id
		FROM tbBranch	WITH (NOLOCK)
		WHERE comp_id	= @compid
			AND bra_id	= @bra_id

	IF ISNULL(@decCurrencyExchange,-1) = -1
		BEGIN
			Set @decCurrencyExchange = dbo.fnGetExchange(@compid,1, @intCompanyCurrency, @intCompany2ndCurrency,0,0,'false')
			UPDATE tbAccountTransactionHead
				SET
					hacc_2ndCurrencyExchange = @decCurrencyExchange
				WHERE	comp_id = @compid
					AND bra_id = @bra_id
					AND hacc_transaction = @intHacc_transaction

		END


	-- pone el numero ORIGINAL de alta del asiento !!!
	-- Se debe mantener luego de una renumeracion.
	UPDATE tbAccountTransactionHead
		SET hacc_originalNumber = hacc_number
		WHERE	comp_id				= @compid	AND
				bra_id				= @bra_id	AND
				hacc_transaction	= @intHacc_transaction


END
GO


