-- IMPORTANTE LEER 16-01-2020
-- STL
-- SAQUE QUE HAGA CANTIDAD POR INDEX ASSEMBLY PORQUE A CADA REGISTRO DEL TURNO LE ESTABA PONIENDO
-- EL INDICE TOTAL DE TODOS LOS ARTICULOS, CON CANTIDAD 1 NO HABIA PROBLEMA, PERO AL HACERLO CON 2 O MAS
-- UNIDADES LE PONIA EL TOTAL DE INDICE A CADA UNA, POR EJEMPLO
-- ARTICULO A - INDICE DE ARMADO = 2
-- SI HAGO VENTA POR 3 UNIDADES Y CARGO 3 TURNOS
-- AL VER EL INDICE DE CADA TURNO ERA 6 Y NO 2 YA QUE HACIA CANTIDAD * INDICE PARA CADA UNO
--*********************************************************************************************************


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trAssembly_Turns4Assembly]
   ON  [dbo].[tbAssembly_Turns4Assembly]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id		INT
	DECLARE @ta_id			INT
	DECLARE @tis_id			INT
	DECLARE @sod_id			INT
	DECLARE @ta_isManual    BIT
	DECLARE @item_id		INT


	SELECT	@comp_id		= comp_id,
			@ta_id			= ta_id,
			@tis_id			= tis_id,
			@sod_id			= sod_id,
			@ta_isManual	= ISNULL(ta_isManual,'False'),
			@item_id		= item_id
		FROM INSERTED


	DECLARE @decTotalIndex AS DECIMAL(19,4)
	SET		@decTotalIndex = 0

	IF EXISTS (
				SELECT 1
					FROM tbTempItemStock ttis	WITH (NOLOCK)
					WHERE	ttis.comp_id	= @comp_id AND
							ttis.tis_id		= @tis_id
				)
		BEGIN
			SELECT		@decTotalIndex	= ti.item_AssemblyIndex --ttis.tis_qty * ti.item_AssemblyIndex
				FROM	tbTempItemStock ttis	WITH (NOLOCK)
				INNER JOIN tbItem ti			WITH (NOLOCK)
					ON	ti.comp_id = ttis.comp_id AND
						ti.item_id = ttis.item_id
				WHERE	ttis.comp_id	= @comp_id AND
						ttis.tis_id		= @tis_id
		END

	ELSE IF EXISTS(
					SELECT 1
						FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
						WHERE	tsod.comp_id	= @comp_id AND
								tsod.sod_id		= @sod_id
					)
		BEGIN
			SELECT		@decTotalIndex	= ti.item_AssemblyIndex --tsod.sod_qty * ti.item_AssemblyIndex
				FROM tbSaleOrderDetail tsod		WITH (NOLOCK)
				INNER JOIN tbItem ti			WITH (NOLOCK)
					ON	ti.comp_id = tsod.comp_id AND
						ti.item_id = tsod.item_id
				WHERE	tsod.comp_id	= @comp_id AND
						tsod.sod_id		= @sod_id
		END


	IF @ta_isManual = 'True'
		BEGIN
			SELECT @decTotalIndex  = ti.item_AssemblyIndex
				FROM tbItem ti		WITH (NOLOCK)
				WHERE	ti.comp_id = @comp_id AND
						ti.item_id = @item_id

		END



	UPDATE tbAssembly_Turns4Assembly	WITH (ROWLOCK)
		SET	ta_assignedIndex =	CASE
									WHEN	@decTotalIndex = 0 THEN
																		CASE
																			WHEN ISNULL(ta_preAssignedIndex,0) <> 0 THEN  ta_preAssignedIndex
																			WHEN ISNULL(ta_assignedIndex,0)    <> 0 THEN  ta_assignedIndex
																			ELSE										  @decTotalIndex
																		END
									ELSE								@decTotalIndex
								END

		WHERE	comp_id = @comp_id AND
				ta_id	= @ta_id


END
GO





