-- =============================================



CREATE TRIGGER [dbo].[trAuthorizationRequest]
   ON  [dbo].[tbAutorizationRequest]
   AFTER INSERT,UPDATE
AS


BEGIN
SET NOCOUNT ON
-- =================================================================================================================
-- Update Date	: 2010-09-11
-- Parte		: 550
-- Description	: Para poder recuperar todos los datos necesarios correspondientes a las autorizaciones, se agregaron
--				  los campos aure_id y aure_cd a la tabla tbSecurityLog, que ahora se deben recuperar para actualizar
--				  la tabla correspondiente
-- =================================================================================================================


	DECLARE		@comp_id				INT,
				@aure_id				INT,
				@aut_id					INT,
				@user_id				INT, --usuario que solicita la autorización
				@aure_isok				CHAR	(1),
				@aure_obs_1				VARCHAR (1000),
				@aure_obs_2				VARCHAR (1000),
				@aure_obs_3				VARCHAR (1000),
				@aure_obs_4				VARCHAR (1000),
				@sysCode_id				INT,
				@aure_user_id			INT, --usuario que autoriza la solicitud
				@aure_genericId			INT,
				@bra_id					INT,
				@prof_id				INT,
				@aure_cd				DATETIME,	-- Parte: 550
				@aure_isEditingCdOld	DATETIME,	-- Parte: 550
				@aure_isEditingCdNew	DATETIME,	-- Parte: 550
				@aure_TypeOfReq			INT



	-- ---------------------------------------------------------------------
	-- Mailing de Autorizaciones
	-- ---------------------------------------------------------------------
	DECLARE
		--VARIABLES DE TRABAJO DE LO QUE SE VA A MODIFICAR
		@comp_id_Inserted			INT,
		@aure_id_Inserted			INT,
		@aut_id_Inserted			INT,
		@bra_id_Inserted			INT,
		@aure_isok_Inserted			CHAR(1),
		@aure_obs_1_Inserted		NVARCHAR(1000),
		@aure_obs_2_Inserted		NVARCHAR(1000),
		@aure_obs_3_Inserted		NVARCHAR(1000),
		@aure_obs_4_Inserted		NVARCHAR(1000),
		@aure_pageHTMLIsSaved		BIT,
		@aure_pageHTMLIsMailSended	bit

		SET @aure_obs_1_Inserted	= ''
		SET	@aure_obs_2_Inserted	= ''
		SET	@aure_obs_3_Inserted	= ''
		SET	@aure_obs_4_Inserted	= ''
	------------------------------------------------------

	------------------------------------------------------
	--DATOS DE DELETED
	------------------------------------------------------
	DECLARE
		--VARIABLES DE TRABAJO DE LO QUE ESTABA GRABADO
		@comp_id_Deleted		INT,
		@bra_id_Deleted			INT,
		@aure_id_Deleted		INT,
		@aure_isok_Deleted		CHAR(1),
		@aure_pageHTML			nvarchar(MAX)


		SELECT
			@comp_id_Deleted		= comp_id,
			@bra_id_Deleted			= bra_id,
			@aure_id_Deleted		= aure_id,
			@aure_isok_Deleted		= IsNull(aure_isok,'-'),
			@aure_isEditingCdOld	= aure_isEditingCd
		FROM DELETED
	------------------------------------------------------

										-- Parte: 550

	------------------------------------------------------
	-- Datos de INSERTED
	------------------------------------------------------
	SELECT	@comp_id					= 	comp_id			,
			@aure_id					=	aure_id			,
			@aut_id						=	aut_id			,
			@user_id					=	[user_id]		,
			@aure_isok					=	IsNull(aure_isok,'*')		,
			@aure_obs_1					=	aure_obs_1		,
			@aure_obs_2					=	aure_obs_2		,
			@aure_obs_3					=	aure_obs_3		,
			@aure_obs_4					=	aure_obs_4		,
			@sysCode_id					=	sysCode_id		,
			@aure_user_id				=	aure_user_id	,
			@aure_genericId				=	aure_genericId	,
			@bra_id						=	bra_id			,
			@prof_id					=	prof_id			,
			@aure_cd					=	aure_cd			,	-- Parte: 550
			@aure_isEditingCdNew		=	aure_isEditingCd,    -- Parte: 550
			@aure_TypeOfReq				=   aure_TypeOfReq,
			@comp_id_Inserted			=	comp_id,
			@aure_id_Inserted			=	aure_id,
			@aut_id_Inserted			=	aut_id,
			@bra_id_Inserted			=	bra_id,
			@aure_isok_Inserted			=	aure_isok,
			@aure_obs_1_Inserted		=	ISNULL(aure_obs_1,''),
			@aure_obs_2_Inserted		=	ISNULL(aure_obs_2,''),
			@aure_obs_3_Inserted		=	ISNULL(aure_obs_3,''),
			@aure_obs_4_Inserted		=	ISNULL(aure_obs_4,''),
			@aure_pageHTMLIsSaved		=	ISNULL(aure_pageHTMLIsSaved,'False'),
			@aure_pageHTMLIsMailSended	=	ISNULL(aure_pageHTMLIsMailSended,'False')
	FROM	INSERTED
	-- ------------------------------------------------------



	IF @aure_id IS NULL RETURN


	-- ------------------------------------------------------
	--se actualiza la tabla tbSecurityLog sólo si se aprobó o se desaprobó la autorización solicitada,
	--esto es que esté informado el @aure_user_id, y que que los valores del campo aure_isEditing
	--anterior y posterior sean iguales, esto se hace para que cada vez que se actualice el aure_isEditing
	--no se actualice esta tabla
	-- ------------------------------------------------------
	IF	NOT @aure_user_id IS NULL AND
		@aure_isok <> @aure_isok_Deleted
		BEGIN
			DECLARE @rv						INT,
					@seclog_pageHTML		NVARCHAR(MAX),
					@seclog_pageHTMLplus	NVARCHAR(MAX)



			SELECT	@seclog_pageHTML		= tar.aure_pageHTML,
					@seclog_pageHTMLplus	= IsNull(tar.aure_pageHTMLPlus,'')
				FROM	tbAutorizationRequest		tar			WITH (NOLOCK)
				WHERE	tar.comp_id			= @comp_id
				AND		tar.aure_id			= @aure_id



			EXEC	spSecurityLog_insertData
					@comp_id		,
					@bra_id			,
					@user_id		,
					@aure_obs_1		,
					@aure_obs_2		,
					@aure_obs_3		,
					@aure_obs_4		,
					@aut_id			,
					@sysCode_id		,
					NULL		  	,
					NULL			,
					NULL			,
					@aure_isok		,
					@aure_user_id	,
					@prof_id		,
					@aure_id		,
					@aure_cd		,
					NULL		  	,
					NULL			,
					NULL		  	,
					@seclog_pageHTML,
					@return_value = @rv OUTPUT


			UPDATE tbSecurityLog
				SET	seclog_pageHTMLPlus = @seclog_pageHTMLplus
				WHERE	comp_id		= @comp_id		and
						bra_id		= @bra_id		and
						[user_id]	= @user_id 		AND
						seclog_id	= @rv

		END
	-- ------------------------------------------------------



	----------------------------------------------------------
	--variables para el formateo del html email
	----------------------------------------------------------
	DECLARE	@MailTable							NVARCHAR(MAX),
			@MailEndTable						NVARCHAR(MAX),
			@Mailsubject						NVARCHAR(MAX),
			@MailbodyHeader						NVARCHAR(MAX),
			@Mailbody							NVARCHAR(MAX),
			@MailbodyFooter						NVARCHAR(MAX),
			@MailImageSRC						NVARCHAR(MAX),
			@MailUserOfRequest					NVARCHAR(2000),
			@MailUserOfAutorizarion				NVARCHAR(2000),
			@MailAuthorizationType				NVARCHAR(2000),
			@User_Mail_Origin					NVARCHAR(MAX),
			@CopyRecipients						NVARCHAR(MAX),
			@aure_remoteGUID					UNIQUEIDENTIFIER,
			@lang_id							INT
	DECLARE @comp_ServerFULLURL2Acces			AS NVARCHAR(1000)
	DECLARE @user_email							AS NVARCHAR(1000)
	DECLARE @autm_Subject						AS NVARCHAR(1000)
	DECLARE @autm_Top							AS NVARCHAR(4000)
	DECLARE @autm_Bottom						AS NVARCHAR(4000)
	DECLARE @autm_cco							AS NVARCHAR(1000)
	DECLARE @autm_originalURL					AS NVARCHAR(1000)
	DECLARE @comp_authorizationMail_fromEmail	AS NVARCHAR(1000)
	DECLARE @user_id_4Authorize					AS INT
	DECLARE @btnAutorize						AS NVARCHAR(MAX)
	DECLARE @btnAutorizeText					AS NVARCHAR(100)
	DECLARE @btnNOAutorize						AS NVARCHAR(MAX)
	DECLARE @btnNOAutorizeText					AS NVARCHAR(100)
	----------------------------------------------------------



	---------------------------------------------------------------------------------------------------------------------
	-- MAIL DE SOLICITUD DE AUTORIZACION
	---------------------------------------------------------------------------------------------------------------------
	IF	@aure_TypeOfReq				= 1			AND
		@aure_pageHTMLIsSaved		= 'True'	AND
		@aure_pageHTMLIsMailSended	= 'False'
		BEGIN



			DECLARE curAuthorizationMailing CURSOR LOCAL FAST_FORWARD FOR
				SELECT	CASE
				      	    WHEN tabm.autm_originalURL IS NOT NULL AND tabm.autm_originalURL <> '' THEN tabm.autm_originalURL
				      	    ELSE tc.comp_ServerFULLURL2RemoteAccess
				      	END	collate database_default,
						tu.user_email,
						tabm.autm_Subject,
						tabm.autm_Top,
						tabm.autm_Bottom,
						tabm.autm_cco,
						tabm.autm_originalURL				collate database_default	,
						tc.comp_authorizationMail_fromEmail	collate database_default,
						tu.[user_id],
						tar.aure_remoteGUID,
						tu.user_lastlanguage,
						ISNULL(tur.user_lastname,'*') + ' ' + ISNULL(tur.user_firstname,'*')
				FROM tbAutorizationRequest tar					WITH (NOLOCK)
				INNER JOIN tbAutorizationByMail tabm			WITH (NOLOCK)
					ON	tabm.comp_id= tar.comp_id	AND
						tabm.bra_id = tar.bra_id	AND
						tabm.aut_id = tar.aut_id
				INNER JOIN tbCompany tc							WITH (NOLOCK)
					ON	tc.comp_id	= tabm.comp_id
				INNER JOIN tbUser tu							WITH (NOLOCK)
					ON tu.[user_id] = tabm.[user_id]
				LEFT JOIN tbUser  tur							WITH (NOLOCK)
					ON tur.[user_id]= tar.[user_id]
				WHERE	tar.comp_id			= @comp_id			AND
						tar.aure_id			= @aure_id_Inserted	AND
						tabm.autm_disabled	= 'False'			AND
						tu.user_email		<> ''				AND
						ISNULL(tc.comp_authorizationMail_fromEmail,'')  <> ''	AND
						ISNULL(tc.comp_ServerFULLURL2Acces,'')			<> ''	AND
						tc.comp_disabled = 0									AND
						(
							dbo.fnStrAllTrim(ISNULL(tabm.autm_isok,'')) = ''
								OR
							ISNULL(tabm.autm_isok,'') = @aure_isok_Inserted
						)



			OPEN curAuthorizationMailing
			FETCH NEXT FROM curAuthorizationMailing
				INTO	@comp_ServerFULLURL2Acces,
						@user_email,
						@autm_Subject,
						@autm_Top,
						@autm_Bottom,
						@autm_cco,
						@autm_originalURL ,
						@comp_authorizationMail_fromEmail,
						@user_id_4Authorize,
						@aure_remoteGUID,
						@lang_id,
						@MailUserOfRequest

			WHILE @@FETCH_STATUS = 0
				BEGIN


					SET @lang_id = ISNULL(@lang_id,2)
					SELECT @btnAutorizeText = tut.utexts_desc
						FROM tbsysUniqueTexts tut			WITH (NOLOCK)
						WHERE tut.lang_id = @lang_id AND tut.utexts_id = 50022


					SELECT @btnNOAutorizeText = tut.utexts_desc
								FROM tbsysUniqueTexts tut			WITH (NOLOCK)
								WHERE tut.lang_id = @lang_id AND tut.utexts_id = 50023



					SELECT @MailUserOfRequest =  tut.utexts_desc  + ' ' + @MailUserOfRequest
								FROM tbsysUniqueTexts tut			WITH (NOLOCK)
								WHERE tut.lang_id = @lang_id AND tut.utexts_id = 52006


					-- ------------------------------------------------------------------
					-- Envio del mail de autorizacion.									-
					-- ------------------------------------------------------------------
					--
					---------------------------------------------------------------------------------------------------------------------
					--ARMADO DE LA TABLA DEL MAIL
					---------------------------------------------------------------------------------------------------------------------
					SELECT @Mailsubject  = @autm_Subject
					SELECT @MailImageSRC = tut.utexts_desc
						FROM tbsysUniqueTexts tut			WITH (NOLOCK)
						WHERE tut.lang_id = -1 AND tut.utexts_id = 100

					SET @MailTable		= '<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">'

					SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
										  '<b>' + @Mailsubject + '</b><br /><br /><br />'

					SET @MailEndTable = + '</table>'

					SET @MailbodyFooter = '</div>'




					-- Boton Autorizar
					SET @btnAutorize = @comp_ServerFULLURL2Acces + 'wfmAutorizationByMail.aspx?' + 'VSA=1&VSU=' + CONVERT(NVARCHAR(15),@user_id_4Authorize) + '&VSG=' + CONVERT(NVARCHAR(50),@aure_remoteGUID)   + '&VSL=' + CONVERT(NVARCHAR(10),@lang_id)
					SET @btnAutorize = '<a target="_blank" style="background-color:LightGreen; font-family:Verdana; font-size:medium; font-weight:bold" href="' + @btnAutorize + '" > ' + @btnAutorizeText + ' </a>'
					-- Boton NO Autorizar
					SET @btnNOAutorize = @comp_ServerFULLURL2Acces + 'wfmAutorizationByMail.aspx?' + 'VSA=2&VSU=' + CONVERT(NVARCHAR(15),@user_id_4Authorize) + '&VSG=' + CONVERT(NVARCHAR(50),@aure_remoteGUID) + '&VSL=' + CONVERT(NVARCHAR(10),@lang_id)
					SET @btnNOAutorize = '<a target="_blank" style="background-color:Red; font-family:Verdana; font-size:medium; font-weight:bold" href="' + @btnNOAutorize + '" > ' + @btnNOAutorizeText + ' </a>'





					----------------------------------------------------------
					--ARMADO DEL BODY CON LOS DATOS DE LA TABLA INSERTED
					----------------------------------------------------------
					SET @Mailbody = ''
					SET @MailBody =

						'<tr><td  style="border-radius:4px;" align="left"> <b>'		+   @MailUserOfRequest collate database_default  + '</b></td> </tr>' + ' ' +
						'<tr><td  style="border-radius:4px;" align="center">'		+	@btnAutorize collate database_default + '  &nbsp; &nbsp; &nbsp; &nbsp;  ' +  @btnNOAutorize collate database_default  + '</td> </tr>' + ' ' +


						'<tr><td  style="border-radius:4px;" align="center">'		+
							@aure_obs_1_Inserted		+ ' ' +
						'</td><tr><td  style="border-radius:4px;" align="center">'	+
							@aure_obs_2_Inserted		+ ' ' +
						'</td></tr><td  style="border-radius:4px;" align="center">' +
							@aure_obs_3_Inserted		+ ' ' +
						'</td><tr><td  style="border-radius:4px;" align="center">'	+
							@aure_obs_4_Inserted		+ ' ' +
						'</td></tr><td  style="border-radius:4px;" align="center">' +
							(SELECT
								RTRIM(CAST(tar.aure_pageHTML AS NVARCHAR(MAX)))
								FROM tbAutorizationRequest tar		WITH (NOLOCK)
								WHERE	tar.comp_id = @comp_id_Inserted	AND
										tar.aure_id	= @aure_id_Inserted)	 + ' ' +
						'</td></tr>' + ' ' +
						'</td></tr><td  style="border-radius:4px;" align="center">' +
							(SELECT
								RTRIM(CAST(tar.aure_pageHTMLPlus AS NVARCHAR(MAX)))
								FROM tbAutorizationRequest tar		WITH (NOLOCK)
								WHERE	tar.comp_id = @comp_id_Inserted	AND
										tar.aure_id	= @aure_id_Inserted)	 + ' ' +
						'</td></tr>'

					SET @Mailbody = @MailTable			+ ' ' +
									@Mailbody			+ ' ' +
									@MailEndTable		+ ' ' +
									@MailbodyFooter
					---------------------------------------------------------------------------------------------------------------------


					SET @Mailbody = @autm_Top + '<br>' + @Mailbody + '<br>' + @autm_Bottom



					SET @User_Mail_Origin = @comp_authorizationMail_fromEmail
					SET	@CopyRecipients	  = @autm_cco


					----------------------------------------------------------
					--ENVIAMOS EL MAIL A LOS DESTINATARIOS CORRESPONDIENTES
					----------------------------------------------------------
					exec spSystem_sendEMail
						@compId					= @comp_id_Inserted,
						@precipients			= @user_email ,
						@pcopy_recipients		= NULL,
						@psubject				= @Mailsubject,
						@pbody_format			= 'HTML',
						@pbody					= @Mailbody,
						@pfile_attachments		= @MailImageSRC,
						@pReplyTo				= @comp_authorizationMail_fromEmail,
						@pblind_copy_recipients = @CopyRecipients	,
						@pUser_Id				= @user_id
					----------------------------------------------------------


					-- Marca como ya enviadas las solicitudes de email.-
					UPDATE tbAutorizationRequest
						SET	aure_pageHTMLIsMailSended = 'True'
					WHERE	comp_id = @comp_id AND
							aure_id = @aure_id_Inserted


					-- ------------------------------------------------------------------

					FETCH NEXT FROM curAuthorizationMailing
						INTO	@comp_ServerFULLURL2Acces,
								@user_email,
								@autm_Subject,
								@autm_Top,
								@autm_Bottom,
								@autm_cco,
								@autm_originalURL ,
								@comp_authorizationMail_fromEmail,
								@user_id_4Authorize,
								@aure_remoteGUID,
								@lang_id,
								@MailUserOfRequest
				END

			CLOSE		curAuthorizationMailing
			DEALLOCATE	curAuthorizationMailing




		END

	-- ---------------------------------------------------------------------------------------------------------------------









	---------------------------------------------------------------------------------------------------------------------
	-- Envio de mail avisando que se autorizó una clave
	---------------------------------------------------------------------------------------------------------------------
	IF	@aure_TypeOfReq		= 1			AND
		@aure_isok_Deleted	= 'P'		AND
		@aure_isok_Inserted = 'A'

		BEGIN


			------------------------------------------------------------
			--RECUPERAMOS EL MAIL A QUIEN ENVIAR
			------------------------------------------------------------
			IF EXISTS (SELECT TOP 1  1
						   FROM tbAutorizationMailing				tam			WITH (NOLOCK)
						   INNER JOIN tbCompany					 AS tc			WITH (NOLOCK)
							ON tc.comp_id = tam.comp_id
						   WHERE	tc.comp_disabled = 0			AND
									tam.comp_id = @comp_id_Inserted	AND
									tam.bra_id  = @bra_id_Inserted  AND
									tam.aut_id	= @aut_id_Inserted)

				BEGIN






					---------------------------------------------------------------------------------------------------------------------
					--ARMADO DE LA TABLA DEL MAIL
					---------------------------------------------------------------------------------------------------------------------
					SELECT @Mailsubject  = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = 2  AND tut.utexts_id = 224039
					SELECT @MailImageSRC = tut.utexts_desc FROM tbsysUniqueTexts tut WHERE tut.lang_id = -1 AND tut.utexts_id = 100

					SET @MailTable		= '<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040">'

					SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
										  '<b>' + @Mailsubject + '</b><br /><br /><br />'

					SET @MailEndTable = + '</table>'

					SET @MailbodyFooter = '</div>'

					----------------------------------------------------------
					--ARMADO DEL BODY CON LOS DATOS DE LA TABLA INSERTED
					----------------------------------------------------------
					SET @MailAuthorizationType	= ''
					SET @MailUserOfAutorizarion = '-*,*-'
					SET @MailUserOfRequest		= '-*,*-'

					SELECT	@MailUserOfAutorizarion = isnull(tu.user_lastname,'*') + ', ' + isnull(tu.user_firstname,'*'),
							@lang_id				= tu.user_lastlanguage,
							@MailUserOfRequest		= isnull(tur.user_lastname,'*') + ', ' + isnull(tur.user_firstname,'*')
						FROM tbAutorizationRequest tar			WITH (NOLOCK)
						INNER JOIN tbuser tu					WITH (NOLOCK)
							ON tu.[user_id]		= tar.aure_user_id
						INNER JOIN tbUser tur					WITH (NOLOCK)
							ON tur.[user_id]	= tar.[user_id]
						WHERE	tar.comp_id		= @comp_id_Inserted	AND
								tar.aure_id		= @aure_id_Inserted

					SELECT		@MailUserOfAutorizarion	=  tut.utexts_desc + ' ' + @MailUserOfAutorizarion
						FROM	tbsysUniqueTexts tut			WITH (NOLOCK)
						WHERE	tut.lang_id			= @lang_id AND
								tut.utexts_id = 52007

					SELECT		@MailUserOfRequest	=  tut.utexts_desc + ' ' + @MailUserOfRequest
						FROM	tbsysUniqueTexts tut			WITH (NOLOCK)
						WHERE	tut.lang_id			= @lang_id AND
								tut.utexts_id = 52006


					IF (
						SELECT tar.aure_isok
							FROM tbAutorizationRequest tar			WITH (NOLOCK)
										WHERE	tar.comp_id = @comp_id_Inserted	AND
												tar.aure_id	= @aure_id_Inserted
						) = 'A'
						BEGIN
							SELECT @MailAuthorizationType = tut.utexts_desc
								FROM tbsysUniqueTexts tut			WITH (NOLOCK)
								WHERE tut.lang_id = @lang_id AND tut.utexts_id = 52008
						END
					ELSE
						BEGIN
							SELECT @MailAuthorizationType = tut.utexts_desc
								FROM tbsysUniqueTexts tut			WITH (NOLOCK)
								WHERE tut.lang_id = @lang_id AND tut.utexts_id = 52009
						END




					SET @Mailbody = ''
					SET @MailBody =
						'<tr><td  style="border-radius:4px;" align="left"> <b>'		+   @MailUserOfRequest		collate database_default  + '</b></td> </tr>' + ' ' +
						'<tr><td  style="border-radius:4px;" align="left"> <b>'		+   @MailUserOfAutorizarion collate database_default  + '</b></td> </tr>' + ' ' +
						'<tr><td  style="border-radius:4px;" align="left"> <b>'		+   @MailAuthorizationType  collate database_default  + '</b></td> </tr>' + ' ' +
						'<tr><td  style="border-radius:4px;" align="center">'		+
							@aure_obs_1_Inserted		+ ' ' +
						'</td><tr><td  style="border-radius:4px;" align="center">'	+
							@aure_obs_2_Inserted		+ ' ' +
						'</td></tr><td  style="border-radius:4px;" align="center">' +
							@aure_obs_3_Inserted		+ ' ' +
						'</td><tr><td  style="border-radius:4px;" align="center">'	+
							@aure_obs_4_Inserted		+ ' ' +
						'</td></tr><td  style="border-radius:4px;" align="center">' +
							(SELECT
								RTRIM(CAST(tar.aure_pageHTML AS NVARCHAR(MAX)))
								FROM tbAutorizationRequest tar			WITH (NOLOCK)
								WHERE	tar.comp_id = @comp_id_Inserted	AND
										tar.aure_id	= @aure_id_Inserted)	 + ' ' +
						'</td></tr>' + ' ' +
						'</td></tr><td align="center">' +
							(SELECT
								RTRIM(CAST(tar.aure_pageHTMLPlus AS NVARCHAR(MAX)))
								FROM tbAutorizationRequest tar			WITH (NOLOCK)
								WHERE	tar.comp_id = @comp_id_Inserted	AND
										tar.aure_id	= @aure_id_Inserted)	 + ' ' +
						'</td></tr>'

					SET @Mailbody = @MailTable			+ ' ' +
									@Mailbody			+ ' ' +
									@MailEndTable		+ ' ' +
									@MailbodyFooter


					---------------------------------------------------------------------------------------------------------------------




					SELECT
						@User_Mail_Origin = ISNULL(tam.autm_email,''),
						@CopyRecipients	  = ISNULL(tam.autm_emailcco,''),
						@Mailsubject	  = CASE
						            	        WHEN tam.autm_desc IS NOT NULL AND tam.autm_desc <> '' THEN tam.autm_desc
						            	        ELSE	@Mailsubject
						            	    END
					FROM tbAutorizationMailing				tam				WITH (NOLOCK)
					WHERE	tam.comp_id = @comp_id_Inserted	AND
							tam.bra_id	= @bra_id_Inserted	AND
							tam.aut_id	= @aut_id_Inserted


					----------------------------------------------------------
					--ENVIAMOS EL MAIL A LOS DESTINATARIOS CORRESPONDIENTES
					----------------------------------------------------------
					exec spSystem_sendEMail
						@compId					= @comp_id_Inserted,
						@precipients			= @User_Mail_Origin,
						@pcopy_recipients		= NULL,
						@psubject				= @Mailsubject,
						@pbody_format			= 'HTML',
						@pbody					= @Mailbody,
						@pfile_attachments		= @MailImageSRC,
						@pReplyTo				= NULL,
						@pblind_copy_recipients = @CopyRecipients	,
						@pUser_Id				= @user_id
					----------------------------------------------------------
				END
		END

	-- ---------------------------------------------------------------------------------------------------------------------


END
GO



-- =============================================
-- Author:		MOS
-- Create date: 01-2011
-- Description:	Pone como Minimo DOS Decimales.!
-- =============================================
CREATE TRIGGER [dbo].[trBranch]
   ON  [dbo].[tbBranch]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @intDecimalPlaces	AS INT
	DECLARE @intBraId			AS INT
	DECLARE @intCompId			AS INT
	DECLARE @bra_lastUpdateNew	AS DATETIME
	DECLARE @bra_lastUpdateOld	AS DATETIME

    SELECT	@intDecimalPlaces	= IsNull(bra_TransactionDecimalPlaces,0) ,
			@intCompId			= comp_id,
			@intBraId			= bra_id,
			@bra_lastUpdateNew	= bra_lastUpdate
		FROM INSERTED

	SELECT	@bra_lastUpdateOld	= bra_lastUpdate
		FROM DELETED

	UPDATE tbBranch
		SET	bra_TransactionDecimalPlaces =	CASE
												WHEN @intDecimalPlaces < 0 THEN 2
												ELSE							bra_TransactionDecimalPlaces
											END,
			bra_logoUpdated =				CASE
												WHEN @bra_lastUpdateNew <> @bra_lastUpdateOld THEN	0
												ELSE												bra_logoUpdated
											END,
			bra_ABM_topRows =				CASE
												WHEN bra_ABM_topRows > 500 THEN 500
												ELSE 							bra_ABM_topRows
											END,
			bra_ABM_refreshSeconds	=		CASE
												WHEN bra_ABM_refreshSeconds < 1800 THEN 1800
												ELSE bra_ABM_refreshSeconds
											END
		WHERE	comp_id = @intCompId
			AND bra_id	= @intBraId



	IF not exists (	SELECT 1
						FROM tbBranch	 tb WITH (NOLOCK)
	               		WHERE tb.comp_id = @intCompId AND tb.bra_disabled = 0)
		BEGIN
			UPDATE tbBranch
				SET bra_disabled = 0
				WHERE	comp_id = @intCompId
					AND bra_id	= @intBraId
		END


END
GO




-- =============================================
-- Author:	MOS
-- Create date: 01-2014
-- Description:	Para mantener la tabla tbUsers4BranchFilter Actualizada
-- =============================================
CREATE TRIGGER [dbo].[trBranch2]
   ON  [dbo].[tbBranch]
   AFTER INSERT,DELETE,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	BEGIN TRANSACTION


		-- ATENCION
		-- Modificar tambien en trigger de tbBranch, trUserCompanyProfile y spBranch_UpdateData y tbUsers4BranchFilter_Users2BlockCubes
	   DELETE FROM tbUsers4BranchFilter
	   INSERT INTO tbUsers4BranchFilter
						(
							comp_id,
							bra_id,
							[user_id],
							ubf_blocked4Cube
						)
						SELECT DISTINCT		tucp.comp_id,
											tucp.bra_id,
											tucp.user_id,
											'False'
								FROM tbUserCompanyProfile tucp					WITH (NOLOCK)
								INNER JOIN tbBranch tb							WITH (NOLOCK)
									ON	tb.comp_id	= tucp.comp_id AND
										tb.bra_id	= tucp.bra_id
								WHERE tb.bra_disabled = 0

		-- Bloquea usuarios para CUBOS.
		UPDATE tbUsers4BranchFilter
			SET	ubf_blocked4Cube = 'True'
			FROM tbUsers4BranchFilter me							WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter_Users2BlockCubes me2	WITH (NOLOCK)
				ON	me2.comp_id		= me.comp_id	AND
					me2.bra_id		= me.bra_id		AND
					me2.[user_id]	= me.[user_id]

		-- **sdgfwetg78
		DELETE tbUsers4BranchFilter
			FROM tbUsers4BranchFilter	tbl	WITH (NOLOCK)
			INNER JOIN tbBranch			tb	WITH (NOLOCK)
				ON	tb.comp_id	= tbl.comp_id AND
					tb.bra_id	= tbl.bra_id
			WHERE tb.bra_disabled = 1



		COMMIT TRANSACTION

END
GO



-- =============================================
-- Author:		MOS
-- Create date: 07/2014
-- Description:	Fuerza a actualizar Imagenes
--				en WebSite
-- =============================================


CREATE TRIGGER [dbo].[trBrand]
   ON  [dbo].[tbBrand]
   AFTER INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id	AS INT
	DECLARE @brand_id	AS INT

	SELECT	@comp_id	= comp_id,
			@brand_id	= brand_id
		FROM INSERTED

	IF EXISTS(
			SELECT 1
			FROM tbBrand  tc
				WHERE	tc.comp_id	= @comp_id		AND
						tc.brand_id	= @brand_id		AND
						tc.brand_image IS NOT NULL	AND
						(
							tc.brand_imageChecksum IS NULL
							OR
							tc.brand_imageChecksum <> dbo.fnChecksum4Image(tc.brand_image)
						)
				)
	BEGIN

		UPDATE tbWebSiteII_Names
			SET	ws_files2TempUpdated = 'False',
				ws_files2TempUpdated4Development = 'False'

		UPDATE tbbrand
			SET brand_imageChecksum = dbo.fnChecksum4Image(brand_image)
			WHERE	comp_id		= @comp_id		AND
					brand_id	= @brand_id

	END

END





