-- =============================================
-- Author:		MOS
-- Create date: 07/2014
-- Description:	Fuerza a actualizar Imagenes
--				en WebSite
-- =============================================
CREATE TRIGGER [dbo].[trCategory]
   ON  [dbo].[tbCategory]
   AFTER INSERT,UPDATE
AS

BEGIN

	SET NOCOUNT ON;


	DECLARE @comp_id AS INT
	DECLARE @cat_id  AS INT
	DECLARE @catg_id_new AS INT
	DECLARE @catg_id_old AS INT
	DECLARE @cat_AssignCatg_id2Items AS BIT = 'False'

	SELECT	@comp_id					= comp_id,
			@cat_id						= cat_id,
			@catg_id_new				= catg_id ,
			@cat_AssignCatg_id2Items	= ISNULL(cat_AssignCatg_id2Items,'False')
		FROM INSERTED

	SELECT	@catg_id_old= catg_id
		FROM DELETED

	-- --------------------------------------
	-- MOS 11-2021, para el FORRO de NG de C1
	-- el Viejo Pelotudo quiere poder filtrar
	-- x grupo de categorias en el articulo
	-- y si no se le hace deja de pagar
	-- como hace SIEMPRE ya que es un RHDRMP
	-- NG y la recvoncha de tu madre!
	-- --------------------------------------
	--IF (@catg_id_new IS NULL AND @catg_id_old IS NOT NULL)
	--	OR
	--   (@catg_id_new IS NOT NULL AND @catg_id_old IS NULL)
	--    OR
	--    @catg_id_new <> @catg_id_old
	--    OR
	  IF  @cat_AssignCatg_id2Items = 'True'
		BEGIN
			IF @catg_id_new IS NULL
				BEGIN
					UPDATE tbitem
						SET catg_id = NULL
						FROM tbItem ti				WITH (NOLOCK)
						WHERE	ti.comp_id	= @comp_id		AND
								ti.cat_id	= @cat_id		AND
								ti.catg_id IS NOT NULL
				END
			ELSE
				BEGIN
					UPDATE tbitem
						SET catg_id = tc.catg_id
						FROM tbItem ti				WITH (NOLOCK)
						INNER JOIN tbCategory AS tc	WITH (NOLOCK)
							ON	tc.cat_id	= ti.cat_id AND
								tc.comp_id	= ti.comp_id
						WHERE	ti.comp_id	= @comp_id	AND
								ti.cat_id   = @cat_id	AND
								(
									ti.catg_id <> tc.catg_id
										OR
									ti.catg_id IS NULL
								)
				END

		END

	IF @cat_AssignCatg_id2Items = 'True'
		BEGIN
			UPDATE tbcategory
				SET cat_AssignCatg_id2Items = 0
				WHERE	comp_id = @comp_id AND
						cat_id	= @cat_id
		END
	-- --------------------------------------





	IF EXISTS(
			SELECT TOP 1 1
			FROM tbCategory  tc	WITH (NOLOCK)
				WHERE	tc.comp_id	= @comp_id		AND
						tc.cat_id	= @cat_id		AND
						tc.cat_image IS NOT NULL	AND
						(
							tc.cat_imageChecksum IS NULL
							OR
							tc.cat_imageChecksum <> dbo.fnChecksum4Image(tc.cat_image)
						)
				)
	BEGIN

		UPDATE tbWebSiteII_Names
			SET	ws_files2TempUpdated				= 'False',
				ws_files2TempUpdated4Development	= 'False'

		UPDATE tbCategory
			SET cat_imageChecksum	= dbo.fnChecksum4Image(cat_image)
			WHERE	comp_id			= @comp_id		AND
					cat_id			= @cat_id

	END

END

--BEGIN

--	SET NOCOUNT ON;

--	DECLARE @comp_id AS INT
--	DECLARE @cat_id  AS INT

--	SELECT	@comp_id	= comp_id,
--			@cat_id		= cat_id FROM INSERTED

--	IF EXISTS(
--			SELECT 1
--				FROM tbCategory tc
--				WHERE	tc.comp_id	= @comp_id	AND
--						tc.cat_id	= @cat_id	AND
--						tc.cat_image IS NOT NULL
--				)
--	BEGIN
--		UPDATE tbWebSiteII_Names
--			SET	ws_files2TempUpdated = 'False',
--				ws_files2TempUpdated4Development = 'False'
--	END

--END
GO





-- =============================================
-- Author:		MOS
-- Create date: 02-2013
-- Description:	Actualiza por si hay algo q lo ponga en NULL
-- =============================================
CREATE TRIGGER [dbo].[trCheckPortfolio]
   ON  [dbo].[tbCheckPortfolio]
   AFTER INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id	AS INT
	DECLARE @chp_id		AS INT
	DECLARE @chp_isRejected		AS BIT
	DECLARE @chp_isCancelled	AS BIT
	DECLARE @chp_isAvailable	AS BIT
	DECLARE @chp_IsPayed		AS BIT
	DECLARE @chp_isToOrder		AS BIT
	DECLARE @chp_isNegociated	AS BIT
	DECLARE @chp_isOwn			AS BIT
	DECLARE @chp_isInProcessOld AS BIT
	DECLARE @chp_isInProcessNew AS BIT
	DECLARE @chp_isEditingOld AS BIT
	DECLARE @chp_isEditingNew AS BIT



	SELECT	@comp_id			= comp_id,
			@chp_id				= chp_id,
			@chp_isRejected		= chp_isRejected,
			@chp_isCancelled	= chp_isCancelled,
			@chp_isAvailable	= chp_isAvailable,
			@chp_IsPayed		= chp_IsPayed,
			@chp_isToOrder		= chp_isToOrder,
			@chp_isNegociated	= chp_isNegociated,
			@chp_isOwn			= chp_isOwn,
			@chp_isInProcessNew = chp_isInProcess,
			@chp_isEditingNew	= chp_isEditing
		FROM INSERTED

	SELECT	@chp_isInProcessOld = chp_isInProcess,
			@chp_isEditingOld   = chp_isEditing
		FROM DELETED


	IF @chp_isRejected IS NULL
		BEGIN
			UPDATE tbcheckPortfolio
    			SET chp_isRejected	= 'False'
				FROM tbCheckPortfolio tcp1
			WHERE	comp_id			= @comp_id	and
					chp_id			= @chp_id
		END

	IF @chp_isCancelled IS NULL
		BEGIN
			UPDATE tbcheckPortfolio
    			SET chp_isCancelled	= 'False'
				FROM tbCheckPortfolio tcp1
			WHERE	comp_id			= @comp_id	and
					chp_id			= @chp_id
		END

	IF @chp_isAvailable IS NULL
		BEGIN
			UPDATE tbcheckPortfolio
    			SET chp_isAvailable	= 'False'
				FROM tbCheckPortfolio tcp1
			WHERE	comp_id			= @comp_id	and
					chp_id			= @chp_id
		END

	IF @chp_IsPayed IS NULL
			BEGIN
				UPDATE tbcheckPortfolio
    				SET chp_IsPayed	= 'False'
					FROM tbCheckPortfolio tcp1
				WHERE	comp_id			= @comp_id	and
						chp_id			= @chp_id
			END

	IF @chp_isToOrder IS NULL
			BEGIN
				UPDATE tbcheckPortfolio
    				SET chp_isToOrder	= 'False'
					FROM tbCheckPortfolio tcp1
				WHERE	comp_id			= @comp_id	and
						chp_id			= @chp_id
			END


	IF @chp_isNegociated IS NULL
			BEGIN
				UPDATE tbcheckPortfolio
    				SET chp_isNegociated	= 'False'
					FROM tbCheckPortfolio tcp1
				WHERE	comp_id			= @comp_id	and
						chp_id			= @chp_id
			END

	IF @chp_isOwn IS NULL
			BEGIN
				UPDATE tbcheckPortfolio
    				SET chp_isOwn	= 'False'
					FROM tbCheckPortfolio tcp1
				WHERE	comp_id			= @comp_id	and
						chp_id			= @chp_id
			END


	-- Si se selecciono para depositar o pagar a proveedor, graba el nuevo orden.
	-- Se usa para que la impresion salga en el mismo ordeen de la carga.
	IF	@chp_isInProcessNew IS NOT NULL AND
		@chp_isInProcessOld IS NOT NULL AND
		@chp_isInProcessNew = 'True'	AND
		@chp_isInProcessOld = 'False'
		BEGIN

			DECLARE @intOrder AS INT
			SET @intOrder = 0
			EXEC spCounters_getNextValue
										@comp_id		= @comp_id,
										@auxiliary_id	= -1,
										@counter_id		= 23459,
										@counter_value	= @intOrder OUTPUT


			UPDATE tbcheckPortfolio
    				SET chp_isInProcess_Order	= @intOrder
					FROM tbCheckPortfolio tcp1
				WHERE	tcp1.comp_id			= @comp_id	and
						tcp1.chp_id				= @chp_id
		END


	-- Si se selecciono para depositar o pagar a proveedor, graba el nuevo orden.
	-- Se usa para que la impresion salga en el mismo ordeen de la carga.
	IF	@chp_isEditingNew IS NOT NULL AND
		@chp_isEditingOld IS NOT NULL AND
		@chp_isEditingNew = 'True'	AND
		@chp_isEditingOld = 'False'
		BEGIN

			DECLARE @intOrder1 AS INT
			SET @intOrder1 = 0
			EXEC spCounters_getNextValue
										@comp_id		= @comp_id,
										@auxiliary_id	= -1,
										@counter_id		= 23459,
										@counter_value	= @intOrder1 OUTPUT


			UPDATE tbcheckPortfolio
    				SET chp_isInProcess_Order	= @intOrder1
					FROM tbCheckPortfolio tcp1
				WHERE	tcp1.comp_id			= @comp_id	and
						tcp1.chp_id				= @chp_id
		END



END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER trColor
   ON  tbColor
   AFTER INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


    -- Si el CODIGO es NULL pone el ID en el Codigo
    DECLARE @comp_id	AS INT
    DECLARE @color_id	AS INT
    DECLARE @color_code AS NVARCHAR(10)

    SELECT	@comp_id	= comp_id,
			@color_id	= color_id,
			@color_code = color_code
		FROM INSERTED

	IF @color_code = ''
		BEGIN
			UPDATE tbColor
				SET
						color_code	= convert(nvarchar(10),color_id)
				WHERE	comp_id		= @comp_id AND
						color_id	= @color_id
		END




END
GO







-- =============================================
-- Author:		MOS
-- Create date: 10-2009
-- Description:	Graba la Fecha de Procesamiento
-- =============================================
CREATE TRIGGER [dbo].[trCommercialTransactions]
   ON  [dbo].[tbCommercialTransactions]
   AFTER INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id					AS  INT
	DECLARE @sd_id						AS  INT
	DECLARE @bra_id						AS  INT
	DECLARE @branchCurrency				AS  INT
	DECLARE @ct_transaction				AS	INT
	DECLARE @processingDate				AS	DATETIME
	DECLARE @ct_adjust					AS	DECIMAL(19,6)
	DECLARE @ct_ACurrency				AS  INT
	DECLARE @ct_ACurrencyExchange		AS	DECIMAL(35,15)
	DECLARE @curr_id4Exchange			AS  INT
	DECLARE @ct_curr_IdExchange			AS	DECIMAL(35,15)
	DECLARE @companyCurrency			AS  INT
	DECLARE @branch2CompanyCurrencyExchange AS DECIMAL(35,15)
	DECLARE @ct_cd						AS DATETIME

	DECLARE @supp_id					AS INT
	DECLARE @cust_id					AS INT
	DECLARE @ba_id						AS INT
	DECLARE @fc_id						AS INT
	DECLARE	@def_id						AS INT

	SELECT	@comp_id				= comp_id,
			@bra_id					= bra_id,
			@ct_transaction			= ct_transaction,
			@ct_adjust				= ct_adjust,
			@ct_ACurrency			= ct_ACurrency,
			@ct_ACurrencyExchange	= ct_ACurrencyExchange ,
			@companyCurrency		= ct_CompanyCurrency,
			@branch2CompanyCurrencyExchange = ct_branch2CompanyCurrencyExchange,
			@branchCurrency			= curr_id_transaction,
			@ct_curr_IdExchange     = ct_curr_IdExchange,
			@ct_cd					= ct_cd,
			@sd_id					= sd_id,
			@fc_id					= fc_id,
			@cust_id				= cust_id,
			@supp_id				= supp_id,
			@ba_id					= ba_id,
			@def_id					= def_id
		FROM INSERTED

	SELECT @processingDate		= tb.bra_processingDate ,
		   @curr_id4Exchange	= tb.curr_id4Exchange
		FROM tbBranch tb	WITH (NOLOCK)
		WHERE	tb.comp_id	= @comp_id
			AND tb.bra_id	= @bra_id


	-- ----------------------------------------------
	-- MOS 02-2016
	-- Pone la Clase Fiscal ACTUAL
	-- ----------------------------------------------
	IF @fc_id IS NULL
		BEGIN

			IF @fc_id IS NULL AND @cust_id IS NOT NULL
				BEGIN
					SELECT	@fc_id = fc_id
						FROM tbCustomer tc			WITH (NOLOCK)
						WHERE	tc.comp_id = @comp_id AND
								tc.cust_id = @cust_id
				END

			IF @fc_id IS NULL AND @supp_id IS NOT NULL
				BEGIN
					SELECT @fc_id = fc_id
						FROM tbSupplier ts			WITH (NOLOCK)
						WHERE	ts.comp_id = @comp_id AND
								ts.supp_id = @supp_id
				END

			IF @fc_id IS NULL AND @ba_id IS NOT NULL
				BEGIN
					SELECT	@fc_id = tba.fc_id
						FROM tbBankingAccounts tba			WITH (NOLOCK)
							WHERE	tba.comp_id = @comp_id AND
									tba.ba_id	= @ba_id
				END


		END
	-- ----------------------------------------------

		IF @def_id IS NULL
			BEGIN
				SELECT		@def_id		= tc.def_id
					FROM tbCustomer tc  WITH (NOLOCK)
					WHERE	tc.comp_id	= @comp_id AND
							tc.cust_id	= @cust_id
			END



		-- ----------------------------------------------
		-- Si la moneda es igual a la del cliente o no esta definida, guardo el tipo de cambio con respecto al cliente.
		-- ----------------------------------------------
		IF not @ct_curr_IdExchange IS NULL
			BEGIN
				SET @ct_curr_IdExchange = @ct_curr_IdExchange
				-- No Hacer Nada si ya esta grabado.!
			END
		ELSE
			IF IsNull(@curr_id4Exchange,@ct_ACurrency) = 	@ct_ACurrency
				BEGIN
					SET @curr_id4Exchange   = @ct_ACurrency
					SET @ct_curr_IdExchange = @ct_ACurrencyExchange
				END
			ELSE
				-- Si la moneda es igual a la de la compañia, guardo el tipo de cambio ya grabado con respecto a la compañia.-
				IF @curr_id4Exchange		= @companyCurrency
					BEGIN
						SET @curr_id4Exchange   = @companyCurrency
						SET @ct_curr_IdExchange = @branch2CompanyCurrencyExchange
					END
			-- Calculo el tipo de cambio a la moneda informada en tbBranch, ya que no es igual ni a la del cliente ni
			-- a la de la compañia.-
				ELSE
					BEGIN
						SET @ct_curr_IdExchange = dbo.fnGetExchange2(@comp_id,1, @branchCurrency,@curr_id4Exchange,0,0,0,'false')
					END
		-- ----------------------------------------------




	UPDATE tbCommercialTransactions
		SET
			ct_processingDate	= CASE
		                 			  WHEN ct_processingDate IS NULL THEN @processingDate
		                 			  ELSE ct_processingDate
		                 		  END,
			ct_AAdjust			= @ct_adjust / dbo.fnNoZDiv(@ct_ACurrencyExchange), -- MOS 28-07-2010

			-- -----------------------------------------------------------------------------
			-- MOS 07-2023: Espero que NO sea una cagada, x MR y MFix
			--              El problema era que si el Proveedor estaba en YUANES cambiaba el valor de curr_id4Exchange de Yuanes a Dolares ( ponia 2 )
			curr_id4Exchange	=	CASE
										WHEN sd_id < 100 THEN	@curr_id4Exchange
										ELSE					 curr_id4Exchange
									END ,
			ct_curr_IdExchange	=	CASE
										WHEN sd_id < 100 THEN	@ct_curr_IdExchange
										ELSE					 ct_curr_IdExchange
									END,
			--curr_id4Exchange	= @curr_id4Exchange,
			--ct_curr_IdExchange	= @ct_curr_IdExchange,
			-- -----------------------------------------------------------------------------
			ct_cd				= CASE
		     						  WHEN @ct_cd IS NULL  THEN @processingDate
		     						  ELSE @ct_cd
		     					  END,
			fc_id				=  @fc_id,
			def_id				=  @def_id

		WHERE   comp_id			= @comp_id
			AND bra_id			= @bra_id
			AND ct_transaction	= @ct_transaction





	-- ------------------------------------------------
	-- Recalcula Cuotas de Compras
	-- ------------------------------------------------
	IF @sd_id > 100 AND @sd_id < 140
		BEGIN
			EXEC spCommercialTransactionsPurchaseLoan_RecalculateBalance @comp_id, @ct_transaction
		END
	-- ------------------------------------------------

END





GO





CREATE TRIGGER [dbo].[trCommercialTransactionsDelivery]
	ON [dbo].[tbCommercialTransactionsDelivery]
	AFTER UPDATE
AS
BEGIN

	SET NOCOUNT ON

	BEGIN TRY


			DECLARE @comp_id		AS INT
			DECLARE @bra_id			AS INT
			DECLARE @ct_transaction	AS INT
			DECLARE @strEmailTo		AS VARCHAR(8000)
			DECLARE @strEmailFrom	AS VARCHAR(8000)
			DECLARE @Comp_desc		AS VARCHAR(100)
			DECLARE @text1			AS VARCHAR(200)
			DECLARE @text2			AS VARCHAR(200)
			DECLARE @text3			AS VARCHAR(200)
			DECLARE @delivery		AS VARCHAR(200)
			DECLARE @note1			AS VARCHAR(200)
			DECLARE @note2			AS VARCHAR(200)
			DECLARE @note3			AS VARCHAR(200)
			DECLARE @note4			AS VARCHAR(200)
			DECLARE @Mailsubject	AS NVARCHAR(MAX)
			DECLARE @user_id		AS INT

			SELECT	@comp_id		= comp_id,
					@bra_id			= bra_id,
					@ct_transaction	= ct_transaction,
					@user_id		= user_id4LastUpdate
			FROM	INSERTED


		-- -------------------------------------------------------------------
		-- Envia emails, hacerlo ya que no anda
		-- -------------------------------------------------------------------
			IF EXISTS (SELECT TOP 1 	1
					   FROM		DELETED D
								INNER JOIN INSERTED I
								ON  D.comp_id			= I.comp_id
								--and D.bra_id			= I.bra_id
								and D.ct_transaction	= I.ct_transaction
					   WHERE	isnull(D.ctd_isDelivered,'false') = 'False'
						AND		IsNull(I.ctd_isDelivered,'False') = 'True')
			BEGIN

				-- -------------------------------------
				-- OBTENEMOS EL LENGUAGE DE LA SUCURSAL
				-- -------------------------------------
				DECLARE
					@lang_id	INT

				SELECT
					@lang_id = tb.lang_id
					FROM tbBranch					tb			WITH (NOLOCK)
					WHERE	tb.comp_id	= @comp_id	AND
							tb.bra_id	= @bra_id
				-- -------------------------------------

				-- -----------------------------------------------------------------------------------------------------------------------------
				-- DELIVERY DATA
				-- -----------------------------------------------------------------------------------------------------------------------------
				DECLARE
					@eMailWhenDelivered			BIT,
					@eMailWhenDeliveredHead		NVARCHAR(MAX),
					@eMailWhenDeliveredFooter	NVARCHAR(MAX),
					@DocDesc					VARCHAR(200),
					@Remito						VARCHAR(200)

				SELECT
					@strEmailTo					= ISNULL(tc.cust_email,'') + ';' + ISNULL(tc.cust_email4Logistics,''),
					@delivery					= td.dl_name,
					@DocDesc					= dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id,tct.ct_transaction),
					@Remito						= dbo.fnGetCommercialTransactionDescription(@comp_id, @lang_id, tct.ct_transaction_PackingList),
					@eMailWhenDelivered			= ISNULL(td.dl_eMailWhenDelivered,'False'),
					@eMailWhenDeliveredHead		= ISNULL(td.dl_eMailWhenDeliveredHead,''),
					@eMailWhenDeliveredFooter	= ISNULL(td.dl_eMailWhenDeliveredFooter,''),
					@strEmailFrom				= CASE
														WHEN ISNULL(td.dl_eMailWhenDeliveredFromEmail,'') <> '' THEN ISNULL(td.dl_eMailWhenDeliveredFromEmail,'')
														ELSE													     ts.sm_email
												  END,
					@Mailsubject				=	CASE
														WHEN ISNULL(td.dl_eMailWhenDeliveredSubject,'') <> '' THEN td.dl_eMailWhenDeliveredSubject
														ELSE														'Aviso de Envío'
													END
				FROM tbCommercialTransactions			tct		WITH (NOLOCK)

				INNER JOIN tbDelivery					td		WITH (NOLOCK)
					ON	td.comp_id			= tct.comp_id	AND
						td.dl_id			= tct.dl_id
				INNER JOIN tbCustomer tc						WITH (NOLOCK)
					ON	tc.comp_id = tct.comp_id AND
						tc.cust_id = tct.cust_id

				INNER JOIN tbSalesman				AS ts		WITH (NOLOCK)
					ON	ts.comp_id	= tct.comp_id AND
						ts.sm_id	= tct.sm_id


				WHERE	tct.comp_id			= @comp_id		AND
						tct.ct_transaction	= @ct_transaction
				-- -----------------------------------------------------------------------------------------------------------------------------
				SET @strEmailTo = dbo.fnstrEmailCheck(@strEmailTo)


				IF dbo.fnStrAllTrim(REPLACE(REPLACE(@strEmailTo,';',''),' ','')) = ''  RETURN



				-- ----------------------------------
				-- COMP_DESC
				-- ----------------------------------
				SELECT @Comp_desc = '' --tc.comp_desc   NOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO
					FROM tbCompany tc		WITH (NOLOCK)
					WHERE tc.comp_id	= @comp_id
				-- ----------------------------------

				-- ----------------------------------
				-- TEXT1
				-- ----------------------------------
				SELECT
					@text1 = tut.utexts_desc
					FROM tbsysUniqueTexts tut		WITH (NOLOCK)
					WHERE tut.utexts_id = '224001' AND
						  tut.lang_id	= @lang_id
				-- ----------------------------------

				-- ----------------------------------
				-- TEXT2
				-- ----------------------------------
				SELECT
					@text2 = tut.utexts_desc
					FROM tbsysUniqueTexts tut		WITH (NOLOCK)
					WHERE tut.utexts_id = '224002'AND
						  tut.lang_id	= @lang_id
				-- ----------------------------------


				-- ---------------------------------------------
				-- NOTES
				-- ---------------------------------------------
				SELECT
					@note1 = tctd.ctd_note1,
					@note2 = tctd.ctd_note3,
					@note3 = tctd.ctd_note3,
					@note4 = tctd.ctd_note4
					FROM tbCommercialTransactionsDelivery tctd		WITH (NOLOCK)
					WHERE	tctd.comp_id		= @comp_id
					AND		tctd.ct_transaction = @ct_transaction
				-- ---------------------------------------------

				SET @text1 = ISNULL(@text1,'')
				SET @text2 = ISNULL(@text2,'')
				SET @delivery = ISNULL(@delivery,'')

				DECLARE @body		AS NVARCHAR(MAX)
				DECLARE @body2		AS NVARCHAR(MAX)

				SET @body	= @text1
				SET @body2	= @text2 + ': ' + @delivery  + ' <br/>' + ISNULL(@note1,'') + ' <br/>' + ISNULL(@note2,'') + ' <br/>' + ISNULL(@note3,'') + ' <br/>' + ISNULL(@note4,'')

				-- ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
				-- ENVIO DE MAIL
				-- VARIABLES PARA EL FORMATO DEL HTML DEL MAIL
					DECLARE	@MailTable							NVARCHAR(MAX),
							@MailEndTable						NVARCHAR(MAX),
							@MailbodyHeader						NVARCHAR(MAX),
							@Mailbody							NVARCHAR(MAX),
							@MailbodyFooter						NVARCHAR(MAX),
							@MailImageSRC						NVARCHAR(MAX)

					SELECT @MailImageSRC = tut.utexts_desc
						FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						WHERE tut.lang_id = -1 AND tut.utexts_id = 100

					SET @MailTable = '<table style="font-family:Verdana;font-size:x-small;color:Black;border-radius:8px;cellpadding="3" cellspacing="5" border="6"  BORDERCOLOR="#666666" BORDERCOLORLIGHT="#8c8c8c" BORDERCOLORDARK="#404040" >'

					SET	@MailbodyHeader	= '<div style="font-family:Verdana;font-size:x-small;text-decoration:none;color:#000000;">' +
										  '<b>' + @body + '</b><br /><br /><br />'


					SET @Mailbody = ''
					SET @MailBody =

								'<tr><td style="border-radius:4px;"  align="center">'			+ ' ' +
									@body2							+ ' ' +
								'</td></tr><tr><td style="border-radius:4px;"  align="center">' + ' ' +
									'Documento:' + ' ' + @DocDesc	+ ' ' +
								'</td></tr><tr><td style="border-radius:4px;"  align="center">' + ' ' +
									'Guía/Remito:'	+ ' ' + @Remito		+ ' ' +
								'</td></tr>'


				SET @MailEndTable = + '</table>'

				SET @MailbodyFooter = '</div>'

				IF NOT LEN(@eMailWhenDeliveredHead) > 0
					SET @eMailWhenDeliveredHead = ''
				IF NOT LEN(@eMailWhenDeliveredFooter) > 0
					SET @eMailWhenDeliveredFooter = ''

				SET @Mailbody = ISNULL(@MailbodyHeader,'') + ' ' +
								ISNULL(@eMailWhenDeliveredHead,'') + ' ' +
								ISNULL(@MailTable,'') + ' ' +
								ISNULL(@Mailbody,'') +
								ISNULL(@MailEndTable,'') + ' ' +
								ISNULL(@eMailWhenDeliveredFooter,'') + ' ' +
								ISNULL(@MailbodyFooter,'')

				--SELECT @Mailbody



				-- SI LO REQUIERE, ENVÍA EL MAIL
				IF @eMailWhenDelivered = 'True'
					BEGIN
						IF (NOT @strEmailTo IS NULL) AND (NOT @strEmailFrom = '') AND @strEmailTo <> ';' AND @strEmailTo <> ''
							BEGIN


								EXEC spSystem_sendEMail
									@compId						= @comp_id,
									@precipients				= @strEmailTo,
									@pcopy_recipients			= '',
									@psubject					= @Mailsubject /*@body*/,
									@pbody_format				= 'HTML',
									@pbody						= @Mailbody,
									@pfile_attachments			= NULL,
									@pReplyTo					= @strEmailFrom,
									@pblind_copy_recipients		= '',
									@pUser_Id					= @user_id

							END
					END
				-- ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			END


	END TRY
	BEGIN CATCH
	END CATCH


END
GO



-- =============================================
