-- =============================================
-- Author:		MOS
-- Create date: 06-2009
-- Description:	Cuando se crea una nueva
-- 	compañia, carga las tablas necesarias para
-- 	poder acceder a la misma por primera vez.
-- =============================================
CREATE TRIGGER [dbo].[trCompany]
   ON  [dbo].[tbCompany]
   AFTER INSERT
AS
BEGIN

	SET NOCOUNT ON

	DECLARE @comp_id		AS INT
	DECLARE @curr_id		AS INT
	DECLARE @prof_id		AS INT
	DECLARE @user_id		AS INT
	DECLARE @bra_id			AS INT
	DECLARE @intCACID		AS INT
	DECLARE @comp_id2Clone	AS INT


	DECLARE @df_id			AS INT --ga
	DECLARE @dfd_id			AS INT --ga

	SELECT	@comp_id		= comp_id,
			@curr_id		= curr_id,
			@user_id		= USER_ID,
			@comp_id2Clone	= comp_id2Clone
		FROM INSERTED


	IF @comp_id2Clone IS NULL  -- MOS: Puse x ABM que nunca llegue en NULL


		-- --------------------------------------------------------------
		BEGIN -- NO se clonan datos!!!!
		-- --------------------------------------------------------------



			-- Inserta una Sucursal
			INSERT INTO dbo.tbBranch
			(
				comp_id,
				-- bra_id -- this column value is auto-generated,
				bra_desc,
				bra_MainDesc,
				curr_id,
				bra_processingDate
			)
				VALUES
					(@comp_id,
					'New',
					'New',
					@curr_id,
					GETDATE())

			SET @bra_id = @@IDENTITY


			-- Inserta un Perfil
			INSERT INTO tbProfile
			(
				comp_id,
				-- prof_id -- this column value is auto-generated,
				prof_desc,
				prof_isSA
			)
				VALUES
					(@comp_id,
					 'Administrator',
					 'false')

			SELECT @prof_id = @@IDENTITY

			-- Inserta relacion User-Company-Profile
			EXEC dbo.spUserCompanyProfile_insertData @comp_id,
													 @bra_id,
													 @user_id,
													 @prof_id



			-- Asigna opciones de menu al perfil creado
			EXEC spMenuGrants_insertData
				@comp_id = @comp_id,
				@prof_id = @prof_id,
				@menu_id = 0,
				@level   = 0


		   -- Lista de Costos
		   INSERT INTO tbItemCostListName
		   (
   			comp_id,
   			coslis_desc,
   			coslis_PPPOnlyIfMinor
		   )
		   VALUES
		   (
   			@comp_id,
   			'New C#1',
   			0
		   )
		   -- Lista de Ventas
		   INSERT INTO tbPriceList
		   (
   			comp_id,
   			prli_desc,
   			prili_AuthorizationRequired,
   			prli_commission,
   			prli_commission_byReceive,
   			prli_wfmPriceCostFullUpdate_CreateDestinyPrice
		   )
		   VALUES
		   (
   			@comp_id,
   			'New S#1',
   			0,
   			0,
   			0,
   			0
		   )


		   -- Cuentas de caja
		   INSERT INTO tbCashAccountantCategories
		   (
   			comp_id,
   			cac_desc,
   			cac_PrintOrder
		   )
		   VALUES
		   (
   			@comp_id,
   			'New',
   			0
		   )

		   SET @intCACID = @@IDENTITY

			-- Cuentas de caja
			INSERT INTO tbCashAccountant
			(
				comp_id,
				cac_id,
				ca_desc
			)
			VALUES
			(
				@comp_id,
				@intCACID,
