			INSERT INTO tbProfile
			(
				comp_id,
				prof_desc,
				prof_isSA,
				prof_BlockMyUsers,
				prof_notInDDL,
				prof_hideExchange,
				prof_id2Clone,
				prof_disabled
			)
			SELECT	@comp_id,
					tp.prof_desc,
					tp.prof_isSA,
					tp.prof_BlockMyUsers,
					tp.prof_notInDDL,
					tp.prof_hideExchange,
					tp.prof_id	,
					'False'
				FROM	tbProfile tp
				WHERE	tp.comp_id			= @comp_id2Clone AND
						tp.prof_disabled	= 'False'


			SELECT TOP 1
						@prof_id		= tp.prof_id
				FROM	tbProfile tp
				WHERE	tp.comp_id		= @comp_id AND
						tp.prof_isSA	= 'True'


			-- Inserta relacion User-Company-Profile
			EXEC dbo.spUserCompanyProfile_insertData @comp_id,
													 @bra_id,
													 @user_id,
													 @prof_id


			-- Menues a Perfiles
			INSERT INTO tbMenuGrants
			(
				comp_id,
				prof_id,
				menu_id
			)
			SELECT	@comp_id,
					tp.prof_id,
					tmg.menu_id
				FROM tbMenuGrants tmg
				INNER JOIN tbProfile tp
					ON	tp.comp_id			= @comp_id AND
						tp.prof_id2Clone	= tmg.prof_id
				WHERE	tmg.comp_id = @comp_id2Clone									AND
						NOT EXISTS (	SELECT 1
                   							FROM tbMenuGrants tmg2
                   							WHERE	tmg2.comp_id = @comp_id		AND
                   									tmg2.prof_id = tp.prof_id	AND
                   									tmg2.menu_id = tmg.menu_id  )		AND
                   			EXISTS(		SELECT 1
                   			       			FROM tbsysMenu tm
                   			       			WHERE	tm.menu_id	= tmg.menu_id)



