		   INSERT INTO tbCurrency2Company
		   (
   			comp_id,
   			curr_id,
   			cc_order,
   			cc_order4Customer
		   )
			SELECT	@comp_id ,
					tcc.curr_id,
					tcc.cc_order,
					tcc.cc_order4Customer
				FROM tbCurrency2Company tcc
				WHERE tcc.comp_id = @comp_id2Clone



			INSERT INTO tbAccountant
			(
				comp_id,
				acc_code,
				acc_desc,
				acc_imputable,
				acc_count_sum,
				acc_column,
				acc_enable4CostCenter,
				acc_count_idOriginal4Clone,
				acc_code4CompanyClone
			)
			SELECT	@comp_id,
					ta.acc_code,
					ta.acc_desc,
					ta.acc_imputable,
					NULL,
					ta.acc_column,
					ta.acc_enable4CostCenter,
					ta.acc_count_id ,
					sat.acc_code4CompanyClone
				FROM tbAccountant ta
				INNER JOIN tbaccountant sat
				 ON sat.acc_count_id	= ta.acc_count_sum
				WHERE ta.comp_id = @comp_id2Clone


			UPDATE tbaccountant
				SET acc_count_sum =	(	SELECT tt.acc_count_id
				                   			FROM tbaccountant tt
				                   			WHERE	tt.comp_id		= @comp_id						AND
				          					tt.acc_code		= tmp.acc_code4CompanyClone
				                   	)
				FROM tbaccountant tmp
				WHERE	tmp.comp_id						= @comp_id	AND
						tmp.acc_code4CompanyClone		IS NOT NULL AND
						tmp.acc_code4CompanyClone		<> ''



			UPDATE tbdocumentsfile
				SET df_id4CompanyClone  = NULL
			UPDATE tbdocumentsfile
				SET df_id4CompanyClone  = df_id
				WHERE comp_id			= @comp_id2Clone



