			-- Como el PUTO trigger solo se ejecuta para el primer documento copiado...
			INSERT INTO tbTaxByDocumentsFile(	comp_id		, bra_id		, tax_id		, df_id	)
				SELECT							ttn.comp_id	, tdf.bra_id	, ttn.tax_id	, tdf.df_id
					FROM tbTaxName ttn
					INNER JOIN tbDocumentsFile tdf
						ON tdf.comp_id		= ttn.comp_id
					WHERE	ttn.comp_id		= @comp_id	AND
							ttn.tax_class	= 1			AND
							NOT EXISTS (SELECT 1
											FROM tbTaxByDocumentsFile ttbdf
											WHERE	ttbdf.comp_id	= ttn.comp_id	AND
													ttbdf.bra_id	= tdf.bra_id	AND
													ttbdf.tax_id	= ttn.tax_id	AND
													ttbdf.df_id		= tdf.df_id )



