			-- Lo asigna por Trigger!!!
			-- Como un trigger de trigger solo se dispara en el primer registro debemos asignar el resto manualmente!!
			-- tbDocumentsFileByProfile: Con el nuevo perfil @prof_id
			INSERT INTO tbDocumentsFileByProfile
			(
				comp_id,
				bra_id,
				prof_id,
				df_id
			)
			SELECT DISTINCT
					@comp_id,
					@bra_id,
					tp.prof_id,
					tdf.df_id
				FROM tbDocumentsFile tdf
				INNER JOIN tbProfile tp
					ON tp.comp_id	= tdf.comp_id
				WHERE tdf.comp_id	= @comp_id and not EXISTS(SELECT 1
																FROM tbDocumentsFileByProfile tmp
																WHERE	tmp.comp_id = @comp_id		AND
																		tmp.bra_id	= @bra_id		AND
																		tmp.prof_id = tp.prof_id	AND
																		tmp.df_id	= tdf.df_id )


			-- Carga los Controles por Perfil
			INSERT INTO tbControlProfiles
			(
				comp_id,
				bra_id,
				prof_id,
				page_id,
				ctrl_id,
				[type_id],
				prop_id,
				fun_id
			)
			SELECT DISTINCT
					@comp_id,
					@bra_id,
					tp.prof_id,
					tdf.page_id,
					tdf.ctrl_id,
					tdf.[type_id],
					tdf.prop_id,
					tdf.fun_id
				FROM tbControlProfiles tdf
				INNER JOIN tbProfile tp
					ON	tp.comp_id			= @comp_id AND
						tp.prof_id2Clone	= tdf.prof_id
				WHERE tdf.comp_id = @comp_id2Clone and not EXISTS(	SELECT 1
																		FROM tbControlProfiles tmp
																		WHERE	tmp.comp_id		= @comp_id		AND
																				tmp.bra_id		= @bra_id		AND
																				tmp.prof_id		= tp.prof_id	AND
																				tmp.page_id		= tdf.page_id	AND
																				tmp.ctrl_id		= tdf.ctrl_id	AND
																				tmp.[type_id]	= tdf.[type_id]	AND
																				tmp.prop_id		= tdf.prop_id	AND
																				tmp.fun_id		= tdf.fun_id	 )



			-- Autorizaciones por Perfil.
			INSERT INTO tbProfileAuthorization
			(
				comp_id,
				prof_id,
				aut_id,
