			UPDATE tbTaxEngineName_Taxes
				SET	tent_id4CompanyClone = NULL

			UPDATE tbTaxEngineName_Taxes
				SET	tent_id4CompanyClone = tent_id
				WHERE comp_id = @comp_id2Clone


			-- tbTaxEngineName_Taxes : Usando tax_id_Original4Clone para saber cuales taxes eran de la original como en tbTaxByFiscalClass ( no esta probado !)
			SELECT
					ten.comp_id,
					ten.ten_id,
					ttn.tax_id,
					tent.tent_columnName,
					tent.tent_newRow,
					tent.tent_printSubtotal,
					tent.tent_column,
					tent.tent_printTAXSubTot,
					tent.tent_FilterByValue,
					tent.tent_isHidden,
					NULL
					/*
					(SELECT ttent.tent_id
						FROM tbTaxEngineName_Taxes ttent
						WHERE ttent.tent_id4CompanyClone = tent.tent_id4Summary)*/
					[tent_id4Summary]
				INTO #tbTaxEngineName_Taxes
				FROM tbTaxEngineName ten
				INNER JOIN tbTaxEngineName_Taxes tent
					ON  tent.ten_id = ten.ten_id4CompanyClone
				INNER JOIN tbTaxName ttn
					ON ttn.tax_id_Original4Clone = tent.tax_id AND ttn.comp_id = @comp_id
				WHERE ten.comp_id = @comp_id


