					td.arba_cot_Counter,
					td.arba_cot_isAvailable,
					td.dl_deliveryType_pickUpNow,
					td.dl_deliveryType_warns4PickUp,
					td.dl_deliveryType_deliver,
					td.dl_deliveryType_warns4Deliver,
					td.dl_deliveryType_wait4GuarantorSignature,
					td.dl_deliveryType_wait4OwnerSignature,
					td.dl_deliveryType_wait4PurchaseOrderArrival,
					td.dl_deliveryType_other,
					td.dl_webSiteDecription,
					td.dl_webSiteNote,
					td.dl_eMailWhenDelivered,
					td.dl_eMailWhenDeliveredHead,
					td.dl_eMailWhenDeliveredFooter,
					td.dl_eMailWhenDeliveredFromEmail

			FROM tbDelivery td
			WHERE td.comp_id = @comp_id2Clone

			--GAEnd--------------------------------------



			-- Tipos de Cambio
			INSERT INTO tbCurrencyExchange
			(
				comp_id,
				curr_id_1,
				curr_id_2,
				ce_exchange,
				ce_exchange_purchase,
				ce_lastUpdate
			)
				SELECT	@comp_id,
						tce.curr_id_1,
						tce.curr_id_2,
						tce.ce_exchange,
						tce.ce_exchange_purchase,
						tce.ce_lastUpdate
				FROM tbCurrencyExchange tce
				WHERE tce.comp_id = @comp_id2Clone



			INSERT INTO tbRMA_Priority
			(
				comp_id,
				rmap_desc
			)
				SELECT	@comp_id,
						tt.rmap_desc
					FROM tbRMA_Priority tt
					WHERE tt.comp_id = @comp_id2Clone


			INSERT INTO tbCustomerCreditRating
			(
				comp_id,
				rating_desc,
				brag_id,
				rating_isAvailable4Initial,
				rating_isInitial_days,
				rating_isAvailable4Default,
				rating_defaultDaysFrom,
				rating_defaultDaysTo,
				rating_defaultTotalFrom,
				rating_defaultTotalTo,
				rating_isAvailable4okCredit,
				rating_okCreditAvgSaleFrom,
				rating_okCreditAvgSaleTo,
				rating_okCreditAvgDefaultDaysFrom,
				rating_okCreditAvgDefaultDaysTo,
				rating_disabled,
				rating_AlertOnInfo,
				rating_isAvailable4NoProcess
			)
			SELECT  @comp_id,  tt.rating_desc,NULL,
			       tt.rating_isAvailable4Initial, tt.rating_isInitial_days,
			       tt.rating_isAvailable4Default, tt.rating_defaultDaysFrom,
			       tt.rating_defaultDaysTo, tt.rating_defaultTotalFrom,
			       tt.rating_defaultTotalTo, tt.rating_isAvailable4okCredit,
			       tt.rating_okCreditAvgSaleFrom, tt.rating_okCreditAvgSaleTo,
			       tt.rating_okCreditAvgDefaultDaysFrom,
			       tt.rating_okCreditAvgDefaultDaysTo, tt.rating_disabled,
			       tt.rating_AlertOnInfo, tt.rating_isAvailable4NoProcess
				FROM tbCustomerCreditRating tt
				WHERE comp_id = @comp_id2Clone


			INSERT INTO tbActivity
			(
				comp_id,
				act_desc
			)
			SELECT	@comp_id,
					ta.act_desc
				FROM tbActivity ta
				WHERE ta.comp_id = @comp_id2Clone



			INSERT INTO tbCustomerDefaultLevel
			(
				comp_id,
				def_desc,
				def_disabled
			)
			SELECT	@comp_id,
					tcdl.def_desc,
					tcdl.def_disabled
				FROM tbCustomerDefaultLevel tcdl
				where tcdl.comp_id = @comp_id2Clone


		END




END
GO



-- =============================================
-- Author:		MOS
-- Create date: 06-2015
-- Description:	Si algun tarado deshabilita todas las compañias no lo va a dejar hacerlo.
-- =============================================
CREATE TRIGGER [dbo].[trCompanyUpdated]
   ON  [dbo].[tbCompany]
   AFTER UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    DECLARE @comp_id AS INT
    SELECT  @comp_id = comp_id
		FROM INSERTED

	-- si deshabilite todas las copmpa#ias, habilito x defecto la actual mia ( anti pelotudos )
    IF NOT EXISTS(
    			SELECT TOP 1 1
    				FROM tbCompany tc		WITH (NOLOCK)
    				WHERE	tc.comp_id		<> @comp_id AND
    						tc.comp_disabled = 'False'
              )
		BEGIN
			UPDATE tbcompany
				SET		comp_disabled	= 'False'
				WHERE	comp_id			= @comp_id
		END

	DELETE FROM tbCompanyFastConfigs

	INSERT INTO tbCompanyFastConfigs
	(
		comp_id,
		comp_disableMinusSearch
	)
	SELECT	comp_id,
			ISNULL(tc.comp_disableMinusSearch,0)
		FROM tbCompany AS tc	WITH (NOLOCK)



END
GO

