CREATE TRIGGER trCostPricePercentRelation
   ON  tbCostPricePercentRelation
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id	AS INT,
			@bra_id		AS INT,
			@coslis_id	AS INT,
			@prli_id	AS INT,
			@ItemPercentNumber AS INT


	SELECT	@comp_id	= comp_id,
			@bra_id		= bra_id,
			@coslis_id	= coslis_id,
			@prli_id	= prli_id,
			@ItemPercentNumber = ItemPercentNumber
		FROM INSERTED

	IF @ItemPercentNumber = 0		-- Si NO va relacionado debe RECALCULAR sino EXPLOTA.  Se hizo para GN   11-2021
		BEGIN
			UPDATE tbCostPricePercentRelation
				SET cppr_RecalculatePercent = 1
				WHERE	comp_id		= @comp_id		AND
						bra_id		= @bra_id		AND
						coslis_id	= @coslis_id	AND
						prli_id		= @prli_id
		END


END
GO





-- =============================================
-- Author:		MOS
-- Create date: 05-2013
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER trCounters
   ON  tbCounters
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @intCompId			AS INT
	DECLARE @intCounterId		AS INT
	DECLARE @intCounterValue	AS INT
	SELECT @intCounterId	= counter_id,
		   @intCounterValue = counter_value,
		   @intCompId       = comp_id
	FROM inserted

	IF @intCounterId = 500 AND @intCounterValue < 100
		BEGIN

			DECLARE @intLastCTTransaction AS INT
			IF @intLastCTTransaction IS NULL SET @intLastCTTransaction = 1000

			SELECT TOP 1 @intLastCTTransaction = tct.ct_transaction
				FROM tbCommercialTransactions tct
				ORDER BY tct.ct_transaction DESC
			SET @intLastCTTransaction = @intLastCTTransaction + 1000

			UPDATE tbCounters
				SET
					counter_value = @intLastCTTransaction
				WHERE	comp_id		= @intCompId AND
						counter_id	= @intCounterId

		END

    -- Insert statements for trigger here

END
GO

