-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER	trCreditCard
   ON			tbCreditCard
   AFTER INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @DECIDIRBP_enabled	AS BIT
	DECLARE @cc_MPIsEnabled		AS BIT
	DECLARE @comp_id			AS INT
	DECLARE @cc_id				AS INT

	SELECT	@comp_id			= comp_id,
			@cc_id				= cc_id,
			@cc_MPIsEnabled		= cc_MPIsEnabled,
			@DECIDIRBP_enabled	= DECIDIRBP_enabled
		FROM INSERTED




	IF @DECIDIRBP_enabled = 'True' AND @cc_MPIsEnabled = 'True'
		BEGIN

			RAISERROR (15600,-1,-1, '<hr/>ATENCIÓN: NO se pueden tener relacionados botones de pago de dos plataformas diferentes en una misma Tarjeta de Crédito<hr/>');

			UPDATE tbCreditCard
				SET DECIDIRBP_enabled	= 'False',
					cc_MPIsEnabled		= 'False'
				WHERE	comp_id			= @comp_id AND
						cc_id			= @cc_MPIsEnabled

		END







END
GO





