create TRIGGER [dbo].[trCRM_Call1]
   ON  [dbo].[tbCRM_Call]
   AFTER INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id		AS INT
	DECLARE @Call_id		AS INT
	DECLARE @user_id		AS INT
	DECLARE @user_idlast	AS INT

	SELECT
			@user_idlast	= [USER_ID]
		FROM DELETED

	SELECT
			@comp_id		= comp_id,
			@Call_id		= Call_id,
			@user_id		= [USER_ID]
	FROM INSERTED


	IF @user_id <> @user_idlast
		BEGIN
			IF @user_idlast IS NULL
				BEGIN
					SET @user_idlast = @user_id
				END
			UPDATE tbCRM_Call
				SET
					user_id_Last	= @user_idlast
			WHERE	comp_id			= @comp_id AND
					Call_id			= @Call_id
		END


END
GO


