											curr_id,
											user_id_lastUpdate
										  )

			SELECT	tcc.comp_id,			tcc.case_id,		tcc.bra_id,				tcc.case_subject,
					tcc.case_desc,			tcc.cast_id,		tcc.case_resolution,	tcc.case_hours,
