-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trCustomerFamily]
   ON  [dbo].[tbCustomerFamily]
   AFTER INSERT,UPDATE
AS

BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


    -- Insert statements for trigger here
	DECLARE @cust_id				AS INT
	DECLARE @city_id				AS INT
	DECLARE @comp_id				AS INT
	DECLARE @street_id				AS INT
	DECLARE @cust_addressNumber		AS INT
	DECLARE @cust_cust_addressFloor AS NVARCHAR(10)
	DECLARE @cust_addressAdditional	AS NVARCHAR(2000)
	DECLARE @city_desc				AS NVARCHAR(2000)
	DECLARE @cust_address			AS NVARCHAR(2000)
	DECLARE @strError				AS NVARCHAR(500)

	SET @city_desc		= ''
	SET @cust_address	= ''

	SELECT	@comp_id				= comp_id,
			@cust_id				= cust_id,
			@city_id				= city_id,
			@street_id				= street_id,
			@cust_addressNumber		= cust_addressNumber,
			@cust_cust_addressFloor = custf_addressFloor,
			@cust_addressAdditional	= custf_addressAdditional
		FROM INSERTED


	DECLARE @lang_id AS INT
	SELECT @lang_id = tc.lang_id
		FROM tbCompany tc	  WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id

	IF @city_id IS NULL OR @city_id <= 0
		BEGIN

			-- '<br><br><br> <B>ATENCIÓN:<br> No se indicó Ninguna Ciudad / Localidad.<br> Si el alta automática de ciudades está deshabilitada podrá configurarlo en la solapa Varios del archivo de Sucursales!</b>'
			SELECT @strError =  '|' +  tut.utexts_desc
				FROM tbsysUniqueTexts tut
				WHERE	tut.utexts_id	= 351		AND
						tut.lang_id		= @lang_id
			RAISERROR (15600,-1,-1, @strError);
			RETURN

		END


	SELECT		@city_desc = vc.city_desc
		FROM	vwCities vc					WITH (NOLOCK)
		WHERE	vc.city_id = @city_id


	IF @street_id IS NOT NULL
		BEGIN
			SELECT @cust_address		= tcs.street_desc
				FROM	tbCities_Streets  tcs
           		WHERE	tcs.comp_id		= @comp_id AND
           				tcs.street_id	= @street_id
           	SET @cust_address = @cust_address + ' ' + CONVERT(NVARCHAR(30),@cust_addressNumber)
           	SET @cust_address = @cust_address + ' ' + CONVERT(NVARCHAR(10),@cust_cust_addressFloor)
           	SET @cust_address = @cust_address + ' ' + @cust_addressAdditional
		END


    UPDATE tbCustomerFamily
		SET
    		custf_city =		CASE
    							WHEN @city_desc = ''	 THEN	custf_city
    							ELSE							@city_desc
    						END  ,
    		custf_address =  CASE
    		                    WHEN @cust_address = ''  THEN	custf_address
    		                    ELSE							@cust_address
    		                END
		WHERE	comp_id = @comp_id AND
				cust_id = @cust_id








END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trDeliveryCharges]
   ON  [dbo].[tbDeliveryCharges]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id		AS INT
	DECLARE @dlc_id			AS INT
	DECLARE @dlc_upToWeight AS DECIMAL(19,4)
	SELECT	@comp_id		= comp_id,
			@dlc_id			= dlc_id,
			@dlc_upToWeight = dlc_upToWeight
		FROM INSERTED



	UPDATE tbDeliveryCharges			WITH (ROWLOCK)
		SET city_id = NULL
		WHERE	comp_id = @comp_id	AND
				dlc_id	= @dlc_id	AND
				city_id = 0


	UPDATE tbDeliveryCharges			WITH (ROWLOCK)
		SET dlc_upToWeight =	CASE
			                	    WHEN @dlc_upToWeight = 0 THEN	9999999999
			                	    ELSE							dlc_upToWeight
			                	END
		WHERE	comp_id = @comp_id	AND
				dlc_id	= @dlc_id


END
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER trDeliveryPackingListRelation
   ON  tbDeliveryPackingListRelation
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @df_id		AS INT
	DECLARE @dl_id		AS INT

	SELECT	@comp_id	= comp_id,
			@df_id		= df_id,
			@dl_id		= dl_id,
			@bra_id		= bra_id
		FROM INSERTED

	IF NOT EXISTS(	-- Si NO es un Remito lo borra
					SELECT 1
						FROM tbDocumentsFile tdf	WITH (NOLOCK)
						WHERE	tdf.comp_id = @comp_id	AND
								tdf.df_id	= @df_id	AND
								tdf.sd_id   = 2
					)

		BEGIN
			DELETE
				FROM tbDeliveryPackingListRelation
				WHERE	comp_id = @comp_id	AND
						bra_id	= @bra_id	AND
						dl_id	= @dl_id	AND
						df_id	= @df_id
		END


END
GO





-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER trDiscount
   ON  tbDiscount
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    DECLARE @intCompID AS INT
    DECLARE @intDiscID AS INT
    DECLARE @decDesc1  AS DECIMAL(19,4)
    DECLARE @decDesc2  AS DECIMAL(19,4)
    DECLARE @decDesc3  AS DECIMAL(19,4)
    DECLARE @decDesc4  AS DECIMAL(19,4)
    SELECT  @intCompID = up.comp_id,
			@intDiscID = up.disc_id,
			@decDesc1  = disc_percentage1,
			@decDesc2  = disc_percentage2,
			@decDesc3  = disc_percentage3,
			@decDesc4  = disc_percentage4
		FROM INSERTED UP

    DECLARE		@decCoefDesc AS DECIMAL(19,6)
    SET         @decCoefDesc=100-(@decDesc1)
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc2
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc3
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc4
    SET         @decCoefDesc=(100 - @decCoefDesc)/100



    UPDATE tbDiscount
	    SET
       	disc_coef = @decCoefDesc
    WHERE	comp_id = @intCompID
		AND disc_id = @intDiscID


END
GO





-- =============================================
-- Author:		MOS
--				02-2013
-- =============================================
CREATE TRIGGER [dbo].[trDocumentsFile]
   ON  [dbo].[tbDocumentsFile]
   AFTER INSERT

AS
BEGIN
	SET NOCOUNT ON;


	DECLARE @comp_id AS INT
	DECLARE @bra_id	 AS INT
	DECLARE @df_id	 AS INT

	Select	@comp_id	= comp_id,
			@bra_id		= bra_id,
			@df_id		= df_id
		From INSERTED

	INSERT INTO tbTaxByDocumentsFile
	(
		comp_id,
		bra_id,
		tax_id,
		df_id
	)
		SELECT	@comp_id,
				@bra_id,
				ttn.tax_id,
				@df_id
			FROM tbTaxName ttn
--			INNER JOIN vwsysTaxClassIVA_Taxes vtcit
--				ON vtcit.tax_class = ttn.tax_class
		WHERE	ttn.comp_id							= @comp_id	and
				IsNull(ttn.tax_disabled,'False')	= 'False'	AND
				ttn.tax_ForSale						= 'True'



	-- ----------------------------------------------------------------------
	-- Pone el documento asignado a los perfiles que sean administradores
	-- ----------------------------------------------------------------------
	INSERT INTO tbDocumentsFileByProfile
	(
		comp_id,
		bra_id,
		prof_id,
		df_id
	)
	SELECT	@comp_id,
			@bra_id,
			tp.prof_id,
			@df_id
		FROM tbProfile tp
		WHERE tp.prof_isSA = 'True' AND tp.comp_id = @comp_id
	-- ----------------------------------------------------------------------


END
GO





-- =============================================
-- Author:		MOS
--				02-2013
-- =============================================
CREATE TRIGGER [dbo].[trDocumentsFile4InvoiceFirstPacking]
   ON  [dbo].[tbDocumentsFile]
   AFTER INSERT,update

AS
BEGIN
	SET NOCOUNT ON;


	-- ------------------------------------
	-- MOS 03-2022
	-- Para que NO haga toda esta mierda cada vez que se incrementa un numero.
	-- ------------------------------------
	DECLARE @bitIsFromABM AS BIT = 'False'
	IF	(UPDATE(df_LastUpdate))
		BEGIN
			SET @bitIsFromABM = 'true'
		END
	IF @bitIsFromABM = 'False' RETURN
	-- ------------------------------------



	DECLARE @comp_id		AS INT
	DECLARE @bra_id			AS INT
	DECLARE @df_id			AS INT
	DECLARE @df_desc		AS NVARCHAR(50)
	DECLARE @df_Disabled	AS BIT
	DECLARE @df_id4MiPymeDocument	AS INT
	DECLARE @df_enableSaveAndProcessNow				AS BIT = 'False'
	DECLARE @df_SaleOrderEmittion_DeletePendingSO	AS BIT = 'False'
	DECLARE @df_isManualEmitting					AS BIT = 'False'


	Select	@comp_id	= comp_id,
			@bra_id		= bra_id,
			@df_id		= df_id,
			@df_desc	= df_desc,
			@df_Disabled= df_Disabled,
			@df_id4MiPymeDocument = df_id4MiPymeDocument
		From INSERTED


	-- ----------------------------------------------------------
	-- Verificaciones para Facturacion Adelantada
	-- ----------------------------------------------------------
	DECLARE @sd_id									AS INT
	DECLARE @df_SaleOrder_InvoiceFirstPacking_df_id AS INT
	DECLARE @df_SaleOrder_IsInvoiceFirstPacking		AS BIT
	DECLARE @df_3rdSales_isAvailable4RegisterSale	AS BIT
	DECLARE @df_3rdSales_item_id4Sale				AS INT
	DECLARE @df_3rdSales_item_id4Loan				AS INT
	--DECLARE @df_3rdSales_df_id4DebitNote			AS INT
	DECLARE @df_3rdSales_isDebitNoteDocument		AS BIT
	DECLARE @bra_saleOrder_InvoiceFromPackingWithOriginalExchange AS BIT

	DECLARE @df_isElectronicInvoice			AS BIT = 'False'
	DECLARE @df_isElectronicInvoiceChile	AS BIT = 'False'

	DECLARE @df_Fiscal_IsFiscalPrinter		AS BIT = 'False'
	DECLARE @df_CAEA_isAvailable			AS BIT = 'False'




	SELECT @sd_id = sd_id ,
		   @df_SaleOrder_InvoiceFirstPacking_df_id	= tdf.df_SaleOrder_InvoiceFirstPacking_df_id,
		   @df_SaleOrder_IsInvoiceFirstPacking		= IsNull(tdf.df_SaleOrder_IsInvoiceFirstPacking,'False'),
		   @df_3rdSales_isAvailable4RegisterSale	= df_3rdSales_isAvailable4RegisterSale,
		   @df_3rdSales_item_id4Sale				= df_3rdSales_item_id4Sale,
		   @df_3rdSales_item_id4Loan				= df_3rdSales_item_id4Loan,
		   --@df_3rdSales_df_id4DebitNote			= df_3rdSales_df_id4DebitNote,
		   @df_3rdSales_isDebitNoteDocument			= df_3rdSales_isDebitNoteDocument,
		   @bra_saleOrder_InvoiceFromPackingWithOriginalExchange = bra_saleOrder_InvoiceFromPackingWithOriginalExchange,
		   @df_isElectronicInvoice					= ISNULL(tdf.df_isElectronicInvoice,'False'),
		   @df_isElectronicInvoiceChile				= ISNULL(df_electronicInvoiceChile_enabled,'False'),
		   @df_Fiscal_IsFiscalPrinter				= ISNULL(tdf.df_Fiscal_IsFiscalPrinter,'False'),
		   @df_CAEA_isAvailable						= ISNULL(tdf.df_CAEA_isAvailable,'False'),
		   @df_enableSaveAndProcessNow				= ISNULL(df_enableSaveAndProcessNow,'False'),
		   @df_SaleOrderEmittion_DeletePendingSO	= ISNULL(df_SaleOrderEmittion_DeletePendingSO,'False'),
		   @df_isManualEmitting						= ISNULL(df_isManualEmitting,'False')
		FROM tbDocumentsFile tdf		WITH (NOLOCK)
	WHERE	tdf.comp_id = @comp_id AND
			tdf.df_id	= @df_id

	-- Si no es un Remito y dice q viene de fc. anticipada, lo pone en FALSE
	IF @sd_id <> 2 AND @df_SaleOrder_IsInvoiceFirstPacking = 'True'
		BEGIN
			UPDATE tbdocumentsfile
				SET df_SaleOrder_IsInvoiceFirstPacking = 'False'
			WHERE	comp_id = @comp_id AND
					df_id	= @df_id
		END
	-- Si NO es una factura y tiene un doc asignado como remito a emitir anticipadamente O
	IF @sd_id <> 1 AND @df_SaleOrder_InvoiceFirstPacking_df_id IS NOT NULL
		BEGIN
			UPDATE tbdocumentsfile
				SET df_SaleOrder_InvoiceFirstPacking_df_id = NULL
			WHERE	comp_id = @comp_id AND
					df_id	= @df_id
		END

	-- Si es una factura y el documento NO es un remito o NO es de la misma sucursal, lo desactiva inmediatamente.
	DECLARE @sd_id_Packing AS INT
	DECLARE @bra_id_Packing AS INT
	DECLARE @df_SaleOrder_IsInvoiceFirstPacking_Packing AS BIT




	SELECT	@sd_id_Packing =	tdf.sd_id,
			@bra_id_Packing=	tdf.bra_id,
			@df_SaleOrder_IsInvoiceFirstPacking_Packing = IsNull(tdf.df_SaleOrder_IsInvoiceFirstPacking,'False')
		FROM tbDocumentsFile tdf		WITH (NOLOCK)
		WHERE	tdf.comp_id = @comp_id AND
				tdf.df_id	= @df_SaleOrder_InvoiceFirstPacking_df_id

	IF @sd_id = 1 AND (@bra_id <> @bra_id_Packing OR @sd_id_Packing <> 2 OR @df_SaleOrder_IsInvoiceFirstPacking_Packing = 'False')
		BEGIN
			UPDATE tbdocumentsfile
				SET df_SaleOrder_InvoiceFirstPacking_df_id = NULL
			WHERE	comp_id = @comp_id AND
					df_id	= @df_id
		END
	-- ----------------------------------------------------------

	-- ----------------------------------------------------------
	-- NO se puede Guardar y Procesar y Borrar los Pendientes
	-- al mismo tiempo
	-- ----------------------------------------------------------
	IF	@df_enableSaveAndProcessNow					= 'True' AND
		@df_SaleOrderEmittion_DeletePendingSO		= 'True'
		BEGIN
			UPDATE tbdocumentsfile
				SET df_enableSaveAndProcessNow = 'False'
			WHERE	comp_id = @comp_id AND
					df_id	= @df_id
		END
	-- ----------------------------------------------------------


	-- ----------------------------------------------------------
	-- NO se puede Guardar y Procesar y Documento MANUAL
	-- al mismo tiempo
	-- ----------------------------------------------------------
	IF	@df_enableSaveAndProcessNow					= 'True' AND
		@df_isManualEmitting						= 'True'
		BEGIN
			UPDATE tbdocumentsfile
				SET df_enableSaveAndProcessNow = 'False'
			WHERE	comp_id = @comp_id AND
					df_id	= @df_id
		END
	-- ----------------------------------------------------------





	-- ----------------------------------------------------------
	-- Financiacion para Ventas de terceros
	-- ----------------------------------------------------------
	DECLARE @bitError AS BIT
	SET		@bitError = 'False'
	IF @df_3rdSales_isAvailable4RegisterSale = 'True'
		BEGIN

			IF	@df_3rdSales_item_id4Sale IS NULL			OR
				@df_3rdSales_item_id4Loan IS NULL			OR
				--@df_3rdSales_df_id4DebitNote IS NULL		OR
				@df_3rdSales_isDebitNoteDocument = 'True'	OR
				NOT EXISTS(
							SELECT TOP 1  1
				       			FROM tbDocumentsFile tdf	WITH (NOLOCK)
				       			WHERE	tdf.comp_id							= @comp_id	AND
				       					tdf.bra_id							= @bra_id	AND
				       					tdf.sd_id							= 4			AND	-- ND
				       					tdf.df_3rdSales_isDebitNoteDocument = 'True'
						   )
				BEGIN
					SET @bitError = 'True'
				END

		END

	IF	@df_3rdSales_isDebitNoteDocument = 'True'
		BEGIN
			IF 	@df_3rdSales_item_id4Loan IS NOT NULL		OR
				@df_3rdSales_item_id4Sale IS NOT NULL		OR
				--@df_3rdSales_df_id4DebitNote IS NOT NULL	OR
				@df_3rdSales_isAvailable4RegisterSale = 'True'
				BEGIN
					SET @bitError = 'True'
				END
		END

	IF @bitError = 'True'
		BEGIN
			UPDATE tbdocumentsfile	WITH(ROWLOCK)
				SET df_3rdSales_isAvailable4RegisterSale	= 'False',
					df_3rdSales_isDebitNoteDocument			= 'False'
			WHERE	comp_id = @comp_id AND
					df_id	= @df_id
		END

	-- ----------------------------------------------------------


								--BEGIN
								--	-- '<br><br><br> <B>ATENCIÓN:<br>Falta ingresar el Código Postal.</b> <br> Numeraciones Permitidas:'
								--	SELECT @strError = tut.utexts_desc
								--		FROM tbsysUniqueTexts tut
								--		WHERE	tut.utexts_id	= 350		AND
								--				tut.lang_id		= @lang_id

								--	RAISERROR (15600,-1,-1, @strError);
								--	RETURN
								--END


	IF @bra_saleOrder_InvoiceFromPackingWithOriginalExchange = 'True'
		BEGIN
			UPDATE tbdocumentsfile  WITH(ROWLOCK)
				SET df_saleOrder_InvoiceFromPackingWithOriginalPriceDiscount	= 'False'
				WHERE	comp_id = @comp_id AND
						df_id	= @df_id
		END



	-- ----------------------------------------------------------
	-- Pone (*) al final si esta deshabilitado
	-- ----------------------------------------------------------
	SET @df_desc			= REPLACE(@df_desc,'(*)','')
	IF  @df_Disabled		= 'True'
		BEGIN
			IF LEN(dbo.fnStrAllTrim(@df_desc)) <= 46
				BEGIN
					SET @df_desc	= dbo.fnStrPADR(dbo.fnStrAllTrim(@df_desc),46,' ') + '(*)'
				END
		END

	UPDATE tbdocumentsfile
		SET		df_desc = @df_desc
		WHERE	comp_id = @comp_id AND
				df_id	= @df_id

	-- ----------------------------------------------------------


	DECLARE @lang_id AS INT
	SELECT @lang_id = tc.lang_id
		FROM tbCompany tc  WITH (NOLOCK)
		WHERE tc.comp_id = @comp_id

	-- ----------------------------------------------------------
	-- Verifica que no haya mas de 1 estado fiscal al mismo tiempo
	-- ----------------------------------------------------------
	DECLARE @intCounterFiscalOptions	AS INT = 0
	DECLARE @strError					AS NVARCHAR(1000)
	IF @df_isElectronicInvoice		= 'True' SET @intCounterFiscalOptions = @intCounterFiscalOptions + 1
	IF @df_isElectronicInvoiceChile	= 'True' SET @intCounterFiscalOptions = @intCounterFiscalOptions + 1
	IF @df_Fiscal_IsFiscalPrinter	= 'True' SET @intCounterFiscalOptions = @intCounterFiscalOptions + 1
	IF @df_CAEA_isAvailable			= 'True' SET @intCounterFiscalOptions = @intCounterFiscalOptions + 1

	IF @intCounterFiscalOptions > 1
		BEGIN
			SELECT @strError = '|' + tut.utexts_desc
				FROM tbsysUniqueTexts tut	WITH (NOLOCK)
				WHERE	tut.utexts_id	= 730		AND
						tut.lang_id		= @lang_id
			RAISERROR (15600,-1,-1, @strError);
			RETURN
		END
	-- ----------------------------------------------------------



	IF	@df_id4MiPymeDocument IS NOT NULL AND
		NOT EXISTS(
				SELECT TOP 1  1
					FROM tbDocumentsFile		tdf
					INNER JOIN tbDocumentsFile	tdf2
						ON	tdf2.comp_id	= tdf.comp_id			AND
							tdf2.df_id		= @df_id4MiPymeDocument
				WHERE	tdf.comp_id = @comp_id						AND
						tdf.df_id	= @df_id						AND
						--tdf.df_pointOfSale	= tdf2.df_pointOfSale	AND
						tdf.df_Kindof		= tdf2.df_Kindof		AND
						tdf.bra_id			= tdf2.bra_id			AND
						tdf.df_electronicInvoiceFCCredito_Enabled	= 'False'		AND
						tdf2.df_electronicInvoiceFCCredito_Enabled	= 'True'		AND
						tdf.sd_id								    = tdf2.sd_id


				)
		BEGIN
			UPDATE tbDocumentsFile
				SET df_id4MiPymeDocument = NULL
				WHERE	comp_id = @comp_id AND
						df_id	= @df_id
		END
















END
GO

