-- =============================================
-- Author:		MOS
-- Create date: 05-2012
-- Description:	<Description,,>
-- =============================================
CREATE  TRIGGER [dbo].[trImportData]
   ON [dbo].[tbImportData]
   AFTER  INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @impData_Custom_local	AS NVARCHAR(MAX)
	DECLARE @impData_Number_local	AS NVARCHAR(MAX)
	DECLARE @impData_Origin			AS NVARCHAR(MAX)
	DECLARE	@impData_From			AS NVARCHAR(MAX)
	DECLARE @impdata_Stamp			AS NVARCHAR(MAX)


	DECLARE @intCompId				AS INT
	DECLARE @CloneLastCustomDataIfIsBlank AS BIT
	DECLARE @intCTTransaction		AS INT
	DECLARE @intImpDataId			AS INT
	DECLARE @intItemId				AS INT
	DECLARE @strImData_Number_Local	AS NVARCHAR(MAX)
	SELECT	@intImpDataId			= impdata_id,
			@intCompId				= comp_id ,
			@intItemId				= item_id,
			@strImData_Number_Local = IsNull(impData_Number_local,''),
			@intCTTransaction		= ct_transaction
		FROM INSERTED



	SELECT @CloneLastCustomDataIfIsBlank = IsNull(tb.bra_PurDoc_CloneLastCustomDataIfIsBlank,'False')
		FROM tbCommercialTransactions tct
		INNER JOIN tbBranch tb
			ON		tb.comp_id		= tct.comp_id
				AND tb.bra_id		= tct.bra_id
		WHERE	tct.comp_id			= @intCompId
			AND tct.ct_transaction	= @intCTTransaction

	IF @strImData_Number_Local = '' AND @CloneLastCustomDataIfIsBlank = 'True'
		BEGIN

			-- ------------------------------------------------------------------------------------------
			-- Obtiene el Numero de despacho del Ultimo Despacho si es que no esta informado al ingreso.-
			-- ------------------------------------------------------------------------------------------
			SELECT TOP 1	@impData_Custom_local	= IsNull(tid.impData_Custom_local,''),
							@impData_Number_local	= IsNull(tid.impData_Number_local,''),
							@impData_Origin			= IsNull(tid.impData_Origin,''),
							@impData_From			= IsNull(tid.impData_From,''),
							@impdata_Stamp			= IsNull(tid.impdata_Stamp,'')

				FROM tbImportData tid
				WHERE
						tid.comp_id = @intCompId
					and tid.item_id = @intItemId
					AND IsNull(tid.impData_Number_local,'') <> ''
				ORDER BY tid.impData_id DESC
			-- ------------------------------------------------------------------------------------------

			-- ------------------------------------------------------------------------------------------
			-- Asigna el Ultimo Numero al despacho recien actualizado.-
			-- ------------------------------------------------------------------------------------------
			IF @impData_Number_local <> ''
			BEGIN
				UPDATE tbimportdata
				SET impData_Custom_local	= @impData_Custom_local,
					impData_Number_local	= @impData_Number_local,
					impData_Origin			= @impData_Origin,
					impData_From			= @impData_From,
					impdata_Stamp			= @impdata_Stamp
				WHERE	comp_id		= @intCompId
					AND impData_id	= @intImpDataId
					AND item_id		= @intItemId
			END
			-- ------------------------------------------------------------------------------------------



		END



END
GO






-- =============================================
-- Author:		MOS
--				10-2008
-- Create date: Inserta el IVA x defecto en
--				tbItemTaxes solo en el INSERT
-- =============================================
CREATE TRIGGER [dbo].[trItemAfterInsert]
   ON  [dbo].[tbItem]
   AFTER INSERT

AS
BEGIN
	SET NOCOUNT ON;


	DECLARE @item_idA AS INT,
			@comp_idA AS INT


	SELECT	@comp_idA = comp_id,
			@item_idA = item_id
		FROM INSERTED

	-- ----------------------------------------
	-- Inserta el IVA seleccionado en el ABM
	-- ----------------------------------------
    Insert dbo.tbItemTaxes
		(	comp_id,
			item_id,
			tax_id,
			bra_id,
			tax_itemComposed
		)
		Select	comp_id,
				item_id,
				item_trigger_tax_id,
				NULL,
				'false'
			From INSERTED


	-- ----------------------------------------
	-- Por si alguno queda mal
	-- ----------------------------------------
	UPDATE tbItemTaxes WITH (ROWLOCK)
		SET tax_class = ttn.tax_class
		FROM tbItemTaxes AS tit
		INNER JOIN tbTaxName AS ttn
			ON	ttn.tax_id	= tit.tax_id AND
				ttn.comp_id = tit.comp_id
		WHERE	tit.comp_id = @comp_idA	AND
				tit.item_id = @item_idA	AND
				tit.tax_class IS NULL
	-- ----------------------------------------

	DECLARE @strError AS NVARCHAR(1000)

	-- ---------------------------------------------------------------
	-- Inserta las listas de precios iniciales
	-- ---------------------------------------------------------------
	BEGIN TRY

		-- Inserta Valores Iniciales en las listas de precios de venta definidas
		INSERT INTO tbPriceListItems
		(
			comp_id,
			prli_id,
			item_id,
			prli_price,
			curr_id
		)
		(
			SELECT  DISTINCT ticliv.comp_id,
							 ticliv.prli_id ,
							 it.item_id,
							 isnull(it.item_tmpPriceOfSale,0),
							 CASE
								WHEN ticliv.curr_id IS NULL THEN	it.curr_id
								ELSE								ticliv.curr_id
							 END
				FROM vwItemCostListInitialValues ticliv						WITH (NOLOCK)
					INNER JOIN INSERTED	it
						ON		 it.comp_id		= ticliv.comp_id
							AND (it.cat_id		= ticliv.cat_id		OR ticliv.cat_id	IS NULL)
							AND (it.subcat_id	= ticliv.subcat_id	OR ticliv.subcat_id IS NULL)
							AND (it.brand_id	= ticliv.brand_id	OR ticliv.brand_id	IS NULL)
							AND it.item_isChildOfSizeColor <> 'True'
					INNER JOIN tbPriceList		ticln						WITH (NOLOCK)
						ON		ticln.comp_id	= ticliv.comp_id
							AND ticln.prli_id   = ticliv.prli_id
		)

	END TRY
	BEGIN CATCH
		SET @strError = '<br/>ERROR: ' + ISNULL(ERROR_MESSAGE(),'') + '<br/> Error intentando insertar Valores Iniciales para Listas de Precios, Verificar la Configuración.'
		RAISERROR (15600,-1,-1, @strerror);
	END CATCH



	BEGIN TRY

		-- Inserta Valores Iniciales en las listas de precios de Costo definidas
		INSERT INTO tbItemCostList
		(
			comp_id,
			coslis_id,
			item_id,
			coslis_price,
			coslis_price_aw,
			curr_id
		)
		(
			SELECT  DISTINCT ticliv.comp_id,
							 ticliv.coslis_id,
							 it.item_id,
							 isnull(it.item_tmpPriceOfCost,0),
							 isnull(it.item_tmpPriceOfCost,0),
							 CASE
								WHEN ticliv.curr_id IS NULL THEN	it.curr_id
								ELSE								ticliv.curr_id
							 END
				FROM vwItemCostListInitialValues ticliv						WITH (NOLOCK)
					INNER JOIN INSERTED	it
						ON		 it.comp_id		= ticliv.comp_id
							AND (it.cat_id		= ticliv.cat_id OR ticliv.cat_id IS NULL)
							AND (it.subcat_id	= ticliv.subcat_id OR ticliv.subcat_id IS NULL)
							AND (it.brand_id	= ticliv.brand_id OR ticliv.brand_id IS NULL)
							AND it.item_isChildOfSizeColor <> 'True'
					INNER JOIN tbItemCostListName ticln						WITH (NOLOCK)
						ON		ticln.comp_id	= ticliv.comp_id
							AND ticln.coslis_id = ticliv.coslis_id
		)

	END TRY
	BEGIN CATCH
		SET @strError = '<br/>ERROR: ' + ISNULL(ERROR_MESSAGE(),'') + '<br/> Error intentando insertar Valores Iniciales para Listas de Costos, Verificar la Configuración.'
		RAISERROR (15600,-1,-1, @strerror);
	END CATCH
	-- ---------------------------------------------------------------


	-- ---------------------------------------------------------------
	-- Si la cat y subcat es WEB que lo ponga automaticamente en WEB
	-- ---------------------------------------------------------------
	DECLARE @comp_id	AS INT
	DECLARE @item_id	AS INT
	DECLARE @pd_id		AS INT
	DECLARE @bitIsWeb	AS BIT
	DECLARE @supp_id	AS INT
	DECLARE @plm_id		AS INT
	SELECT	@comp_id = comp_id,
			@item_id = item_id,
			@pd_id	 = pd_id,
			@plm_id  = plm_id,
			@supp_id = supp_id
		FROM INSERTED

	SET @bitIsWeb = 'False'
	SELECT
		@bitIsWeb =
					CASE
					    WHEN tc.cat_web = 'True' OR tsc.subcat_web = 'True' THEN	'True'
					    ELSE														'False'
					END
		FROM tbItem ti								WITH (NOLOCK)
		INNER JOIN tbCompany	tco					WITH (NOLOCK)
			ON tco.comp_id		= ti.comp_id
		INNER JOIN tbCategory	tc					WITH (NOLOCK)
			ON	tc.comp_id		= ti.comp_id	AND
				tc.cat_id		= ti.cat_id
		INNER JOIN tbSubCategory tsc				WITH (NOLOCK)
			ON	tsc.comp_id		= ti.comp_id	AND
				tsc.cat_id		= ti.cat_id		AND
				tsc.subcat_id	= ti.subcat_id
		WHERE tco.comp_itemInsertBlockWEB <> 'True'

	IF @bitIsWeb = 'True'
		BEGIN
			UPDATE tbitem		WITH (ROWLOCK)
				SET item_web = 'True'
			WHERE	comp_id = @comp_id			AND
					item_id = @item_id
		END
	-- ---------------------------------------------------------------


END









GO





-- =============================================
-- Author:		MOS
--				02-2'13
-- =============================================
CREATE TRIGGER [dbo].[trItemAfterInsertAndUpdate]
   ON  [dbo].[tbItem]
   AFTER INSERT,UPDATE

AS
BEGIN
	SET NOCOUNT ON;

	IF @@NESTLEVEL > 20	-- 19-11-2020: Bonomo, no se x q cuernos se arma una recursividad. No logre encontrarlo x eso la limito acá.  Aparentemente solo pasa en Bonomo
		BEGIN
			RETURN
		END


	-- MOS 09-2023: 19713, decia q a las 3 se le disparaban reglas de act.
	IF UPDATE(item_daysWithOutSales)
		BEGIN
			RETURN
		END



	DECLARE @intItemId AS INT
	DECLARE @intCompId AS INT
	DECLARE @decWide AS DECIMAL(21,9)
	DECLARE @decLarge AS DECIMAL(21,9)
	DECLARE @dechigth AS DECIMAL(21,9)
	DECLARE @item_id					AS INT
	DECLARE @comp_id					AS INT
	DECLARE @item_expser				AS BIT
	DECLARE @item_expean				AS BIT
	DECLARE @item_EANInternalRequired	AS BIT
	DECLARE @item_NoStockCheck			AS BIT
	DECLARE @item_code					AS NVARCHAR(50)
	DECLARE @item_codeAlternative		AS NVARCHAR(50)
	DECLARE @decVolumen					AS DECIMAL(21,9)
	DECLARE @pd_id		AS INT
	DECLARE @bitIsWeb	AS BIT
	DECLARE @supp_id	AS INT
	DECLARE @plm_id		AS INT
	DECLARE @item_ifHasItemAssociationSumPrices AS BIT = 'False'


	DECLARE @item_markup_1				AS DECIMAL(19,8)
	DECLARE @item_markup_2				AS DECIMAL(19,8)
	DECLARE @item_markup_3				AS DECIMAL(19,8)
	DECLARE @item_markup_4				AS DECIMAL(19,8)
	DECLARE @item_markup_5				AS DECIMAL(19,8)
	DECLARE @item_markup_6				AS DECIMAL(19,8)
	DECLARE @item_markup_7				AS DECIMAL(19,8)
	DECLARE @item_markup_8				AS DECIMAL(19,8)
	DECLARE @item_markup_9				AS DECIMAL(19,8)
	DECLARE @item_markup_10				AS DECIMAL(19,8)
	DECLARE @item_markup_11				AS DECIMAL(19,8)
	DECLARE @item_markup_12				AS DECIMAL(19,8)
	DECLARE @item_markup_13				AS DECIMAL(19,8)
	DECLARE @item_markup_14				AS DECIMAL(19,8)
	DECLARE @item_markup_15				AS DECIMAL(19,8)
	DECLARE @item_markup_16				AS DECIMAL(19,8)


	DECLARE @item_markupOLD_1			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_2			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_3			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_4			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_5			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_6			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_7			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_8			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_9			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_10			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_11			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_12			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_13			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_14			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_15			AS DECIMAL(19,8)
	DECLARE @item_markupOLD_16			AS DECIMAL(19,8)
	DECLARE @strItem_Desc				AS VARCHAR(500)
	DECLARE @bitIsFromABM				AS BIT = 'False'
	DECLARE @OLDitem_lastUpdate			AS DATETIME
	DECLARE @NEWitem_lastUpdate			AS DATETIME



	Select	@comp_id					= comp_id,
			@item_id					= item_id,
			@item_expser				= item_expser,
			@item_expean				= item_expean,
			@item_NoStockCheck			= item_NoStockCheck,
			@item_EANInternalRequired	= isnull(item_EANInternalRequired,'False'),
			@item_code					= item_code,
			@item_codeAlternative		= dbo.fnStrAllTrim (ISNULL(item_codeAlternative,'')),
			@intItemId					= item_id,
			@intCompId					= comp_id,
			@decWide					= item_wide,
			@decLarge					= item_large,
			@dechigth					= item_higth,
			@pd_id						= pd_id,
			@plm_id						= plm_id,
			@supp_id					= supp_id,
			@item_ifHasItemAssociationSumPrices = item_ifHasItemAssociationSumPrices,
			@item_markup_1				= item_markup_1,
			@item_markup_2				= item_markup_2,
			@item_markup_3				= item_markup_3,
			@item_markup_4				= item_markup_4,
			@item_markup_5				= item_markup_5,
			@item_markup_6				= item_markup_6,
			@item_markup_7				= item_markup_7,
			@item_markup_8				= item_markup_8,
			@item_markup_9				= item_markup_9,
			@item_markup_10				= item_markup_10,
			@item_markup_11				= item_markup_11,
			@item_markup_12				= item_markup_12,
			@item_markup_13				= item_markup_13,
			@item_markup_14				= item_markup_14,
			@item_markup_15				= item_markup_15,
			@item_markup_16				= item_markup_16,
			@strItem_Desc				= item_desc,
			@NEWitem_lastUpdate			= ISNULL(item_lastUpdate,GETDATE())
		From INSERTED


	-- --------------------------------------------------------------------------------------------
	-- MOS 02-2022: Verifica si fue act la descripcion para actualizar la tabla de busqueda rapida.
	-- --------------------------------------------------------------------------------------------
	DECLARE @bitIs_item_desc_Updated AS BIT = 'false'
	IF UPDATE(item_desc)
		BEGIN
			SET @bitIs_item_desc_Updated = 'True'
		END
	-- --------------------------------------------------------------------------------------------


	-- Toma los VIEJOS antes de actualizar
	SELECT
			@item_markupOLD_1				= item_markup_1,
			@item_markupOLD_2				= item_markup_2,
			@item_markupOLD_3				= item_markup_3,
			@item_markupOLD_4				= item_markup_4,
			@item_markupOLD_5				= item_markup_5,
			@item_markupOLD_6				= item_markup_6,
			@item_markupOLD_7				= item_markup_7,
			@item_markupOLD_8				= item_markup_8,
			@item_markupOLD_9				= item_markup_9,
			@item_markupOLD_10				= item_markup_10,
			@item_markupOLD_11				= item_markup_11,
			@item_markupOLD_12				= item_markup_12,
			@item_markupOLD_13				= item_markup_13,
			@item_markupOLD_14				= item_markup_14,
			@item_markupOLD_15				= item_markup_15,
			@item_markupOLD_16				= item_markup_16,
			@OLDitem_lastUpdate				= ISNULL(item_lastUpdate,@NEWitem_lastUpdate)
			FROM DELETED


	-- ------------------------------------
	-- MOS 02-2022 x Arg e INgreso de Compras.
	-- Para que NO JODA en cosas que disparan triggers o actualizan un item y NO se quiere que haga nada acá.
	-- ------------------------------------
	IF	(UPDATE(item_lastUpdate))   --@OLDitem_lastUpdate <> @NEWitem_lastUpdate
		BEGIN
			SET @bitIsFromABM = 'true'
		END
	-- MOS 06-2022: Para q regenere asociaciones, precios, etc.   Ponerlo si algo tiene q disparar recalculo de combos.
	DECLARE @bitIsFromPROCESS AS BIT = 'False'
	IF	UPDATE(item_lastUpdate_byProcess)			OR
		UPDATE(item_isForAssociation)				OR
		UPDATE(item_isForAssociation_canEditGroup)	OR
		UPDATE(item_isChildOfSizeColor)
		--@OLDitem_lastUpdate <> @NEWitem_lastUpdate
		BEGIN
			SET @bitIsFromABM		= 'True'
			SET @bitIsFromPROCESS	= 'True'
		END
	-- ------------------------------------


	SET @decVolumen = IsNull(@decWide,0) * IsNull(@decLarge,0) * IsNull(@dechigth,0)






	-- ----------------------------------------------
	-- Si el articulo tiene numeros de serie tomados
	-- vuelve a activarlo
	-- ----------------------------------------------
	DECLARE @bitMustEXPSerInTrue AS BIT
	IF @bitIsFromABM = 'True'
		BEGIN
			SET		@bitMustEXPSerInTrue = 'False'
			IF EXISTS(	SELECT TOP 1 1
          					FROM tbSaleOrderSerials tsos			WITH (NOLOCK)
          					INNER JOIN tbItemSerials tis			WITH (NOLOCK)
          						ON	tis.comp_id							= tsos.comp_id	AND
          							tis.is_id							= tsos.is_id
          					INNER JOIN tbCompany tc					WITH (NOLOCK)
          						ON tc.comp_id							= tsos.comp_id
          					WHERE	tsos.comp_id						= @comp_id		AND
          							tis.item_id							= @item_id		AND
          							tc.comp_item_expser_controlDisabled = 'False'
				 )
			BEGIN
				SET		@bitMustEXPSerInTrue = 'True'
				--UPDATE tbitem WITH (ROWLOCK)
				--	SET item_expser = 'True'
				--	WHERE	comp_id = @comp_id AND
				--			item_id = @item_id
			END
		END
	-- ----------------------------------------------


	-- ----------------------------------------------
	-- Actualiza ultimo item modificado y
	-- verificacion que no sea ean y serie al mismo tiempo
	-- ----------------------------------------------
	IF @bitIsFromABM = 'True'
		BEGIN
			UPDATE tbitem	WITH (ROWLOCK)
				SET item_expean = CASE
										WHEN @item_NoStockCheck		= 'True'			     THEN 'False'
										WHEN @item_expser = 'True' AND @item_expean = 'True' THEN 'False'
										ELSE item_expean
									END,
					item_RecentlyUpdated	= 'True',
					item_code4web			= REPLACE(REPLACE(item_code,'/','--'),'\','--'),
					itemCAR_PatentNumber	= UPPER(itemCAR_PatentNumber),
					item_expser				=	CASE
													WHEN @item_NoStockCheck		= 'True'		THEN 'False'
													WHEN @bitMustEXPSerInTrue	= 'True'		THEN 'True'
													ELSE item_expser
												END ,
					item_volume				=	CASE
													WHEN IsNull(@dechigth,0) <> 0 AND isNull(@decWide,0) <> 0 AND IsNull(@decLarge,0) <> 0 AND item_volume <> @decVolumen THEN @decVolumen
													ELSE item_volume
												END,
					--item_descHTMLStripped	= CONVERT(CHAR(800),LTRIM(RTRIM(dbo.fnStrStripHTML(ISNULL(item_descHTML,''))))) ,
					item_desc				=	CASE
													WHEN dbo.fnStrAllTrim(ISNULL(item_desc,'')) = '' THEN	'No Description'
													ELSE													item_desc
												END


			WHERE	comp_id = @comp_id AND
					item_id = @item_id
		END
	-- ----------------------------------------------


	--IF @item_NoStockCheck = 'True'
	--	BEGIN
	--		UPDATE tbitem	WITH (ROWLOCK)
	--			SET item_expean = 0,
	--				item_expser = 0
	--		WHERE	comp_id = @comp_id AND
	--				item_id = @item_id
	--	END




	-- -------------------------------------------------------------------
	-- Actualiza Medidas
	-- -------------------------------------------------------------------
	--DECLARE @intItemId AS INT
	--DECLARE @intCompId AS INT
	--DECLARE @decWide AS DECIMAL(21,9)
	--DECLARE @decLarge AS DECIMAL(21,9)
	--DECLARE @dechigth AS DECIMAL(21,9)
	--SELECT  @intItemId	=	item_id,
	--		@intCompId	=	comp_id,
	--		@decWide	=	item_wide,
	--		@decLarge	=	item_large,
	--		@dechigth	=	item_higth
	--	FROM INSERTED

	--IF IsNull(@dechigth,0) <> 0 AND isNull(@decWide,0) <> 0 AND IsNull(@decLarge,0) <> 0
	--	BEGIN
	--		--DECLARE @decVolumen AS DECIMAL(21,9)
	--		--SET @decVolumen = IsNull(@decWide,0) * IsNull(@decLarge,0) * IsNull(@dechigth,0)
	--		--IF @decVolumen <> 0
	--		BEGIN
	--			UPDATE tbitem	WITH (ROWLOCK)
	--				SET		item_volume = @decVolumen
	--				WHERE	item_id		= @intItemId AND
	--						comp_id		= @intCompId AND
	--						item_volume <> @decVolumen
	--		END

	--	END
	-- -------------------------------------------------------------------



	-- ---------------------------------------------------------------------------
	-- Si se modifico una imagen setea al sitio web para que recargue
	-- las imagenes nuevamente
	-- ---------------------------------------------------------------------------
	IF @bitIsFromABM = 'True'
		BEGIN

			SET NOCOUNT ON;


			IF EXISTS(
					SELECT TOP 1  1
					FROM tbItem  tc			WITH (NOLOCK)
						WHERE	tc.comp_id	= @comp_id		AND
								tc.item_id	= @item_id		AND
								tc.item_picture IS NOT NULL	AND
								(
									tc.item_imageChecksum IS NULL
									OR
									tc.item_imageChecksum <> dbo.fnChecksum4Image(tc.item_picture)
								)
						)
			BEGIN

				UPDATE tbWebSiteII_Names	WITH (ROWLOCK)
					SET	ws_files2TempUpdated				= 'False',
						ws_files2TempUpdated4Development	= 'False'

				UPDATE tbItem				WITH (ROWLOCK)
					SET item_imageChecksum	= dbo.fnChecksum4Image(item_picture)
					WHERE	comp_id			= @comp_id		AND
							item_id			= @item_id


			END

		END

	-- ---------------------------------------------------------------------------




	-- ---------------------------------------------------------------------------
	-- Pone que este fue el ultimo articulo modificado
	-- ---------------------------------------------------------------------------
	IF @bitIsFromABM = 'True'
		BEGIN
			UPDATE tbitem		WITH (ROWLOCK)
				SET		item_lastChanged	= 'False'
				WHERE	comp_id				= @comp_id AND
						item_lastChanged	= 'True'
			UPDATE tbItem		WITH (ROWLOCK)
				SET		item_lastChanged	= 'True',
						item_desc			= REPLACE(item_desc,'|','/')
				WHERE	comp_id				= @comp_id		AND
						item_id				= @item_id
		END
	-- ---------------------------------------------------------------------------






	-- ---------------------------------------------------------------------------
	-- si no requiere EAN pone en falso la generacion de ean interno!
	-- ---------------------------------------------------------------------------
	IF	@bitIsFromABM				= 'True'	AND
		@item_EANInternalRequired	= 'True'	AND
		@item_expean				= 'False'
		BEGIN
			UPDATE tbitem	WITH (ROWLOCK)
				SET item_EANInternalRequired = 'false'
				WHERE	comp_id = @comp_id AND
						item_id = @item_id
		END
	-- ---------------------------------------------------------------------------

	-- ---------------------------------------------------------------------------
	-- Si necesita generar EAN interno lo hace.!
	-- ---------------------------------------------------------------------------
	IF	@bitIsFromABM				= 'True'	AND
		@item_EANInternalRequired	= 'True'	AND
		@item_expean				= 'True'	AND
								NOT EXISTS (	SELECT TOP 1  1
													FROM tbItemEAN tie	WITH (NOLOCK)
													WHERE	tie.comp_id				= @comp_id AND
															tie.item_id				= @item_id AND
															tie.ie_isInternalEAN	= 'True')
		BEGIN
			INSERT INTO tbItemEAN	WITH (ROWLOCK)
			(
				comp_id,
				-- ie_id -- this column value is auto-generated,
				item_id,
				ie_ean,
				ie_isDUC,
				ie_DUNQty,
				ie_Force2InternalNewEAN,
				ie_isInternalEAN
			)
			VALUES
			(
				@comp_id,
				@item_id,
				substring(convert(nvarchar(100),NEWID()),1,15),
				'False',
				1,
				'true',
				'False'
			)
		END
	-- ---------------------------------------------------------------------------

	DECLARE @strError	as NVARCHAR(1000)
	DECLARE @lang_id	AS INT = 2



	IF	@bitIsFromABM				= 'True' AND
		EXISTS(	SELECT TOP 1  1
					FROM tbItem ti WITH (NOLOCK)
      				WHERE	ti.comp_id = @comp_id AND
      						ti.item_id = @item_id AND
      						ti.item_isEW = 'True' AND
      						ti.insu_id IS NULL
      		)

		BEGIN

			SELECT  @lang_id = tc.lang_id
				FROM tbCompany tc  WITH (NOLOCK)
				WHERE tc.comp_id = @comp_id

			SELECT  @strError =  '|' + tut.utexts_desc
				FROM tbsysUniqueTexts tut				WITH (NOLOCK)
				WHERE	tut.utexts_id	= 372		AND
						tut.lang_id		= @lang_id

			RAISERROR (15600,-1,-1, @strError);
			RETURN
		END

-- RX-470P-4SDF5
	-- ---------------------------------------------------
	-- Verifica que el Codigo no sea un ItemEAN
	-- ---------------------------------------------------
	DECLARE @strItemEanrror AS NVARCHAR(1000)
	SET		@strItemEanrror = ''

	IF @bitIsFromABM		= 'True'
		BEGIN
			SELECT	@strItemEanrror = '(' + tie.item_code + ') ' + tie.item_desc
      			FROM tbItemEAN  ti		WITH (NOLOCK)
      			INNER JOIN tbitem tie	WITH (NOLOCK)
      				ON	tie.comp_id = ti.comp_id	AND
      					tie.item_id = ti.item_id
					WHERE	ti.comp_id = @comp_id	AND
							ti.ie_ean  = @item_code
			IF ISNULL(@strItemEanrror,'') <> ''
				BEGIN
					-- '<br><br><br> <B>ATENCIÓN:<br>ATENCIÓN, el código de artículo seleccionado ya existe en Códigos EAN Adicionales de Artículos.</b>

					SELECT  @strError = '|' +  tut.utexts_desc
						FROM tbsysUniqueTexts tut				WITH (NOLOCK)
						WHERE	tut.utexts_id	= 450		AND
								tut.lang_id		= @lang_id
					SET @strError = @strError + @strItemEanrror
					RAISERROR (15600,-1,-1, @strError );
					RETURN
				END
		END





	-- MOS: 01-2022 x Sergio
	-- ---------------------------------------------------
	-- Verifica que el Codigo Alternativo NO este repetido
	-- en un ItemEAN o en otro articulo o en el codigo de otro articulo
	-- ---------------------------------------------------
	IF (@item_codeAlternative <> '' AND @bitIsFromABM = 'True' AND @bitIsFromPROCESS = 'False')
		BEGIN
			IF     (
						SELECT TOP 1 tc.comp_enableItemCodeAlternativeCheck
							FROM tbCompany AS tc	WITH (NOLOCK)
							WHERE tc.comp_id = @comp_id
			) = 'True'
				BEGIN


					SET		@strItemEanrror =	''
					SELECT	TOP 1
							@strItemEanrror =	CASE
													WHEN tie.ie_ean IS NOT NULL AND tie.ie_ean  = @item_codeAlternative THEN 'EAN+(' + ISNULL(tie.ie_ean,'') + ' ItemID:'+ CONVERT(NVARCHAR(10),ISNULL(tie.item_id,0)) + ') <br/> '
													ELSE ''
												END
												 +
												'ItemID('+  CONVERT(NVARCHAR(10),ISNULL(ti.item_id,0))+')'
      					FROM		tbitem ti		WITH (NOLOCK)
      					LEFT JOIN	tbItemEAN  tie	WITH (NOLOCK)
      						ON	tie.comp_id = ti.comp_id	AND
      							tie.item_id = ti.item_id
							WHERE	ti.comp_id = @comp_id	AND
									(
										(@item_id IS NOT NULL AND tie.item_id <> @item_id AND tie.ie_ean				= @item_codeAlternative)
											OR
										(@item_id IS NOT NULL AND ti.item_id <> @item_id  AND ti.item_code				= @item_codeAlternative)
										OR
										(@item_id IS NOT NULL AND ti.item_id <> @item_id  AND ti.item_codeAlternative	= @item_codeAlternative)
									)

					IF ISNULL(@strItemEanrror,'') <> '' --OR 1 = 1
						BEGIN
							-- '<br><br><br> <B>ATENCIÓN:<br>ATENCIÓN, el código de artículo seleccionado ya existe en Códigos EAN Adicionales de Artículos.</b>

							SELECT  @strError = '|' +  tut.utexts_desc
								FROM tbsysUniqueTexts tut				WITH (NOLOCK)
								WHERE	tut.utexts_id	= 455		AND
										tut.lang_id		= @lang_id
							SET @strError = @strError + @strItemEanrror
							RAISERROR (15600,-1,-1, @strError );
							RETURN
						END
				END
		END



	-- ---------------------------------------------------
	-- Actualiza datos de Hijos de Talles y Colores
	-- ---------------------------------------------------
	IF	@bitIsFromABM = 'True' AND
		EXISTS (SELECT TOP 1 1 /*DISTINCT 1 MOS 12-2016 */
				FROM	tbItemSizeColorRelation tiscr		WITH (NOLOCK)
				WHERE	tiscr.comp_id = @Comp_id
				AND		tiscr.item_id = @Item_id)
		BEGIN

    		DECLARE @litem_id_child				INT,
    				@liscr_Coeficient4Price		DECIMAL(19,4)

    		--declaración de cursor para recuperar los items hijos y los coeficientes
    		DECLARE cursor_childs CURSOR LOCAL  FAST_FORWARD FOR
    			SELECT	tiscr.item_id_child,
    					tiscr.iscr_Coeficient4Price
    				FROM	tbItemSizeColorRelation		tiscr				WITH (NOLOCK)
    				WHERE	tiscr.comp_id = @Comp_id
    				AND		tiscr.item_id = @Item_id	AND
    						tiscr.item_id_child			IS NOT NULL AND
    						tiscr.iscr_Coeficient4Price IS NOT NULL


    		OPEN cursor_childs

    		FETCH NEXT FROM cursor_childs INTO @litem_id_child, @liscr_Coeficient4Price

    		WHILE @@FETCH_STATUS = 0
    		BEGIN


				UPDATE tbitem	WITH (ROWLOCK)

					SET tbitem.item_purOrd_Disc1			= ti2.item_purOrd_Disc1,
						tbitem.item_purOrd_Disc2			= ti2.item_purOrd_Disc2,
						tbitem.item_purOrd_Disc3			= ti2.item_purOrd_Disc3,
						tbitem.item_purOrd_Disc4			= ti2.item_purOrd_Disc4,
						tbitem.item_purOrd_surcharge1		= ti2.item_purOrd_surcharge1,
						tbitem.item_purOrd_surcharge2		= ti2.item_purOrd_surcharge2,
						tbitem.item_purOrd_surcharge3		= ti2.item_purOrd_surcharge3,
						tbitem.item_purOrd_surcharge4		= ti2.item_purOrd_surcharge4,
						tbitem.item_markup_1				= ti2.item_markup_1,
						tbitem.item_markup_2				= ti2.item_markup_2,
						tbitem.item_markup_3				= ti2.item_markup_3,
						tbitem.item_markup_4				= ti2.item_markup_4,
						tbitem.item_markup_5				= ti2.item_markup_5,
						tbitem.item_markup_6				= ti2.item_markup_6,
						tbitem.item_markup_7				= ti2.item_markup_7,
						tbitem.item_markup_8				= ti2.item_markup_8,
						tbitem.item_markup_9				= ti2.item_markup_9,
						tbitem.item_markup_10				= ti2.item_markup_10,
						tbitem.item_markup_11				= ti2.item_markup_11,
						tbitem.item_markup_12				= ti2.item_markup_12,
						tbitem.item_markup_13				= ti2.item_markup_13,
						tbitem.item_markup_14				= ti2.item_markup_14,
						tbitem.item_markup_15				= ti2.item_markup_15,
						tbitem.item_markup_16				= ti2.item_markup_16,
						tbitem.creditI_up2Pays				= ti2.creditI_up2Pays,
						tbitem.creditI_creditInterest		= ti2.creditI_creditInterest,
						tbitem.creditII_up2Pays				= ti2.creditII_up2Pays,
						tbitem.creditII_creditInterest		= ti2.creditII_creditInterest,
						tbitem.creditIII_up2Pays			= ti2.creditIII_up2Pays,
						tbitem.creditIII_creditInterest		= ti2.creditIII_creditInterest,
						tbitem.creditIV_up2Pays				= ti2.creditIV_up2Pays,
						tbitem.creditIV_creditInterest		= ti2.creditIV_creditInterest,
						tbitem.creditOther_creditInterest	= ti2.creditOther_creditInterest,
						tbitem.creditReplaceInterest		= ti2.creditReplaceInterest,
						tbitem.sdlmt_id						= ti2.sdlmt_id,
						tbitem.CreditQuotaQtyMaximum		= ti2.CreditQuotaQtyMaximum,
						tbitem.item_liquidation				= ti2.item_liquidation,
						tbitem.item_liquidationPlus			= ti2.item_liquidationPlus,
						tbitem.item_newness					= ti2.item_newness,
						tbitem.brand_id						= ti2.brand_id,
						tbitem.supp_id						= ti2.supp_id,
						tbItem.ic_id						= ti2.ic_id
					FROM tbItem					--WITH (NOLOCK)
					INNER JOIN tbItem ti2		WITH (NOLOCK)
						ON	ti2.comp_id = @Comp_id AND
							ti2.item_id = @Item_id
					WHERE	tbitem.comp_id	= @Comp_id AND
							tbitem.item_id	= @litem_id_child



    			FETCH  NEXT FROM  cursor_childs INTO @litem_id_child, @liscr_Coeficient4Price

    		END

    		CLOSE cursor_childs
    		DEALLOCATE cursor_childs


		END
	-- ---------------------------------------------------

	-- ---------------------------------------------------
	-- Si tiene asociaciones para COMBOS no debe ser
	-- serializable ni solicitar EAN
	-- ---------------------------------------------------
	DECLARE			@item_id_associated AS INT = NULL
	IF	@bitIsFromABM = 'True'
		BEGIN
			SELECT TOP 1
					@item_id_associated = tia.item_id_1
				FROM tbItemAssociation	tia   WITH (NOLOCK)
				INNER JOIN tbItem		ti	  WITH (NOLOCK)
				ON	ti.comp_id = tia.comp_id AND
					ti.item_id = tia.item_id_1
				WHERE	tia.comp_id = @comp_id	AND
						tia.item_id = @item_id	AND
						ti.item_disabled = 'False'



			IF @item_id_associated IS NOT NULL
				BEGIN
					UPDATE tbitem
						SET item_expser					= 0,
							item_expean					= 0,
							item_isForAssociation		= 'True'
						WHERE	comp_id = @comp_id AND
								item_id = @item_id


					-- -------------------------------------------------------------------------------------------
					-- Esto es para que si hice una asociacion y luego pongo el item principal
					-- como que tome los precios de los hijos asociados, x trigger de los hijos, lo haga!
					-- -------------------------------------------------------------------------------------------
					DECLARE @intCosLisID	AS INT = -1
					DECLARE @intPrLiID		AS INT = -1

					IF @item_ifHasItemAssociationSumPrices = 'True'
						BEGIN

							DECLARE curUPdateCost CURSOR LOCAL FAST_FORWARD FOR
								SELECT ticl.coslis_id
									FROM tbItemCostList ticl					WITH (NOLOCK)
									WHERE	ticl.comp_id = @comp_id					AND
											ticl.item_id = @item_id_associated
							OPEN curUPdateCost
							FETCH NEXT FROM curUPdateCost INTO @intCosLisID
							WHILE @@FETCH_STATUS = 0
								BEGIN
									IF @@NESTLEVEL < 30	-- 19-11-2020: Bonomo, no se x q cuernos se arma una recursividad. No logre encontrarlo x eso la limito acá.  Aparentemente solo pasa en Bonomo
										BEGIN
											UPDATE tbItemCostList
												SET	coslis_price	= coslis_price
												WHERE	comp_id		= @comp_id				AND
														item_id		= @item_id_associated	AND
														coslis_id	= @intCosLisID
										END
									FETCH NEXT FROM curUPdateCost INTO @intCosLisID
								END
							CLOSE		curUPdateCost
							DEALLOCATE	curUPdateCost


							DECLARE curUPdatePrice CURSOR LOCAL  FAST_FORWARD FOR
								SELECT tpli.prli_id
									FROM tbPriceListItems tpli 						WITH (NOLOCK)
									WHERE	tpli.comp_id = @comp_id					AND
											tpli.item_id = @item_id_associated
							OPEN curUPdatePrice
							FETCH NEXT FROM curUPdatePrice INTO @intPrLiID
							WHILE @@FETCH_STATUS = 0
								BEGIN
									UPDATE tbPriceListItems
										SET		prli_price	= prli_price
										WHERE	comp_id		= @comp_id				AND
												item_id		= @item_id_associated	AND
												prli_id		= @intPrLiID
									FETCH NEXT FROM curUPdatePrice INTO @intPrLiID
								END
							CLOSE		curUPdatePrice
							DEALLOCATE	curUPdatePrice




						END
					ELSE
						BEGIN

							DECLARE curUPdateCost CURSOR LOCAL FAST_FORWARD FOR
								SELECT ticl.coslis_id
									FROM tbItemCostList ticl					WITH (NOLOCK)
									INNER JOIN	tbItem AS ti					WITH (NOLOCK)
										ON  ti.comp_id = @comp_id					AND
											ti.item_id = @item_id
									WHERE	ticl.comp_id = @comp_id					AND
											ticl.item_id = @item_id_associated		AND
											ti.item_isForAssociation_triggerRules4NOPriceListSUM = 'True'
							OPEN curUPdateCost
							FETCH NEXT FROM curUPdateCost INTO @intCosLisID
							WHILE @@FETCH_STATUS = 0
								BEGIN
									UPDATE tbItemCostList
										SET	coslis_price	= coslis_price
										WHERE	comp_id		= @comp_id				AND
												item_id		= @item_id_associated	AND
												coslis_id	= @intCosLisID
									FETCH NEXT FROM curUPdateCost INTO @intCosLisID
								END
							CLOSE		curUPdateCost
							DEALLOCATE	curUPdateCost
						END
					-- -------------------------------------------------------------------------------------------



				END
			ELSE
				BEGIN
					UPDATE tbitem
						SET	item_isForAssociation		= 'False'
						WHERE	comp_id = @comp_id AND
								item_id = @item_id
				END
		END
	-- ---------------------------------------------------



	IF @bitIsFromABM = 'True'
		BEGIN
			EXEC spWebServices_ItemUpdateHistory @comp_id,@item_id
		END






	-- ---------------------------------------------------------------
	-- Dispara Reglas x actualizacion de Incrementos
	-- Dispara Reglas x actualizacion de Descuento
	-- Dispara Reglas x actualizacion de Proveedor
	-- ---------------------------------------------------------------
	IF @bitIsFromABM = 'True'
		BEGIN
			SET		@pd_id = NULL
			SELECT	@pd_id = ts.pd_id
				FROM tbSupplier ts		WITH (NOLOCK)
				WHERE	ts.comp_id = @comp_id AND
						ts.supp_id = @supp_id

			DECLARE @litem_id	AS INT,
					@coslis_id	AS INT
			DECLARE cursor_UpdateCostLis CURSOR LOCAL  FAST_FORWARD FOR

			SELECT ticl.coslis_id, ticl.item_id
				FROM tbPriceListMarkup					 plm			WITH (NOLOCK)
				INNER JOIN tbItemCostList				 ticl			WITH (NOLOCK)
				ON ticl.comp_id		= plm.comp_id	AND
				   ticl.coslis_id	= plm.coslis_id AND
				   ticl.item_id		= @item_id
				INNER JOIN tbItemCostListName		ticln				WITH (NOLOCK)
					ON	ticln.comp_id	= ticl.comp_id	AND
						ticln.coslis_id = ticl.coslis_id
				WHERE plm.comp_id	= @Comp_ID		AND
					  plm.plm_id	= @plm_id		AND
					  ticl.item_id	= @item_id		AND
					  ticln.coslis_triggerOnItemAndSupplierUpdates	= 'True'

			UNION

			SELECT ticl.coslis_id, ticl.item_id
				FROM	tbItemCostList				ticl				WITH (NOLOCK)
				INNER JOIN tbItemCostListName		ticln				WITH (NOLOCK)
					ON	ticln.comp_id	= ticl.comp_id	AND
						ticln.coslis_id = ticl.coslis_id
				INNER JOIN tbPurchaseDiscount		tpd					WITH (NOLOCK)
				ON ticl.comp_id		= tpd.comp_id	AND
				   ticl.coslis_id	= tpd.coslis_id
				WHERE	tpd.comp_id		= @comp_id	AND
						tpd.pd_id		= @pd_id	AND
						ticl.item_id	= @item_id	AND
						ticln.coslis_triggerOnItemAndSupplierUpdates	= 'True'

			UNION

			SELECT ticl.coslis_id, ticl.item_id
				FROM	tbItemCostList				ticl				WITH (NOLOCK)
				INNER JOIN tbItemCostListName		ticln				WITH (NOLOCK)
					ON	ticln.comp_id	= ticl.comp_id	AND
						ticln.coslis_id = ticl.coslis_id
				INNER JOIN tbPurchaseDiscount		tpd					WITH (NOLOCK)
				ON ticl.comp_id		= tpd.comp_id	AND
				   ticl.coslis_id	= tpd.coslis_id
				WHERE	tpd.comp_id		= @comp_id	AND
						tpd.pd_id		= @pd_id	AND
						ticl.item_id	= @item_id	AND
						ticln.coslis_triggerOnItemAndSupplierUpdates	= 'True'


			OPEN cursor_UpdateCostLis

			-- lectura anticipada del cursor
			FETCH  NEXT FROM  cursor_UpdateCostLis
				INTO	@litem_id,
						@coslis_id

			WHILE @@FETCH_STATUS = 0
				BEGIN

					UPDATE		tbItemCostList									--WITH (ROWLOCK)
						SET		coslis_price = coslis_price --+ 0.01
						FROM	tbItemCostList				ticl
						WHERE	ticl.comp_id	= @comp_id		AND
								ticl.item_id	= @litem_id		AND
								ticl.coslis_id	= @coslis_id

					FETCH  NEXT FROM  cursor_UpdateCostLis
						INTO	@litem_id,
								@coslis_id

				END
			CLOSE		cursor_UpdateCostLis
			DEALLOCATE	cursor_UpdateCostLis

		END

	-- ---------------------------------------------------------------




	-- ---------------------------------------------------------------
	-- Dispara Reglas x actualizacion de Incrementos
