	-- ---------------------------------------------------------------
	-- Si se modiufica un markup y esta habilitado en COSTOS,
	-- se ejecutan las reglas de actualizacion de precios asociadas
	-- ---------------------------------------------------------------
	IF	@bitIsFromABM = 'True'	AND
		(
			( @item_markup_1 <> @item_markupOLD_1 OR @item_markupOLD_1 IS NULL )
			OR
			( @item_markup_2 <> @item_markupOLD_2 OR @item_markupOLD_2 IS NULL )
			OR
			( @item_markup_3 <> @item_markupOLD_3 OR @item_markupOLD_3 IS NULL )
			OR
			( @item_markup_4 <> @item_markupOLD_4 OR @item_markupOLD_4 IS NULL )
			OR
			( @item_markup_5 <> @item_markupOLD_5 OR @item_markupOLD_5 IS NULL )
			OR
			( @item_markup_6 <> @item_markupOLD_6 OR @item_markupOLD_6 IS NULL )
			OR
			( @item_markup_7 <> @item_markupOLD_7 OR @item_markupOLD_7 IS NULL )
			OR
			( @item_markup_8 <> @item_markupOLD_8 OR @item_markupOLD_8 IS NULL )
			OR
			( @item_markup_9 <> @item_markupOLD_9 OR @item_markupOLD_9 IS NULL )
			OR
			( @item_markup_10 <> @item_markupOLD_10 OR @item_markupOLD_10 IS NULL )
			OR
			( @item_markup_11 <> @item_markupOLD_11 OR @item_markupOLD_11 IS NULL )
			OR
			( @item_markup_12 <> @item_markupOLD_12 OR @item_markupOLD_12 IS NULL )
			OR
			( @item_markup_13 <> @item_markupOLD_13 OR @item_markupOLD_13 IS NULL )
			OR
			( @item_markup_14 <> @item_markupOLD_14 OR @item_markupOLD_14 IS NULL )
			OR
			( @item_markup_15 <> @item_markupOLD_15 OR @item_markupOLD_15 IS NULL )
			OR
			( @item_markup_16 <> @item_markupOLD_16 OR @item_markupOLD_16 IS NULL )
		)

		BEGIN

			DECLARE curCostList4Update CURSOR LOCAL  FAST_FORWARD FOR
				SELECT ticl.coslis_id
					FROM tbItemCostList				ticl		WITH (NOLOCK)
					INNER JOIN tbItemCostListName	ticln		WITH (NOLOCK)
						ON	ticln.comp_id	= ticl.comp_id		AND
							ticln.coslis_id = ticl.coslis_id
					WHERE	ticl.comp_id	= @comp_id			AND
							ticl.item_id	= @item_id			AND
							ticln.coslis_triggerOnItemAndSupplierUpdates = 'True'

    		OPEN 	curCostList4Update

			FETCH  NEXT FROM  curCostList4Update
				INTO	@coslis_id

    		WHILE @@FETCH_STATUS = 0
    			BEGIN

					UPDATE		tbItemCostList									--WITH (ROWLOCK)
						SET		coslis_price = coslis_price --+ 0.01
						FROM	tbItemCostList				ticl
						WHERE	ticl.comp_id	= @comp_id		AND
								ticl.item_id	= @item_id		AND
								ticl.coslis_id	= @coslis_id

					FETCH  NEXT FROM  curCostList4Update
						INTO	@coslis_id
    			END


    		CLOSE curCostList4Update
    		DEALLOCATE curCostList4Update


		END
	-- ---------------------------------------------------------------

	-- NO, hacerlo ante la solicitud al ws !!! EXEC spTableLastUpdate_updateData @comp_id, 30,@item_id, null,null,null

	-- --------------------------------------
	-- Para el PUTO sp de FullJaus y LRPMQLP
	-- Si se ve que molesta, sacarlo y que se caguen
	-- --------------------------------------
	IF @bitIsFromABM = 'True'
		BEGIN
			BEGIN TRY
				INSERT INTO tbItemsUpdated(item_id) VALUES (@item_id)
			END TRY
			BEGIN CATCH
			END CATCH
			--SELECT 1 / 0
		END
	-- --------------------------------------




	-- --------------------------------------
	-- Actualiza la tabla de Busquedas Rapidas con y sin acentos
	-- --------------------------------------
	IF	(@bitIsFromABM = 'True' OR @bitIs_item_desc_Updated = 'True') AND
		@intCompId IS NOT NULL AND
		@intItemId IS NOT NULL
		BEGIN
			IF NOT EXISTS (
								SELECT TOP 1 1
									FROM tbItem_FastestSearch AS tifs	WITH (NOLOCK)
									WHERE	tifs.comp_id = @intCompId AND
											tifs.item_id = @intItemId
						)
				BEGIN
					INSERT INTO tbItem_FastestSearch
					(
						comp_id,
						item_id,
						item_desc
					)
					VALUES
					(
						@intCompId,
						@intItemId,
						@strItem_Desc
					)
				END
			ELSE
				BEGIN
					UPDATE tbItem_FastestSearch
						SET		item_desc	= @strItem_Desc
						WHERE	comp_id		= @intCompId   AND
								item_id		= @intItemId
				END

		END
	-- --------------------------------------



	-- --------------------------------------
	-- MOS 11-2021, para el FORRO de NG de C1
	-- el Viejo Pelotudo quiere poder filtrar
	-- x grupo de categorias en el articulo
	-- y si no se le hace deja de pagar
	-- como hace SIEMPRE ya que es un RHDRMP
	-- NG y la recvoncha de tu madre!
	-- --------------------------------------
	IF @bitIsFromABM = 'True'
		BEGIN
			UPDATE tbitem
				SET catg_id = tc.catg_id
				FROM tbItem ti				WITH (NOLOCK)
				INNER JOIN tbCategory AS tc	WITH (NOLOCK)
					ON	tc.cat_id	= ti.cat_id AND
						tc.comp_id	= ti.comp_id
				WHERE	ti.comp_id	= @comp_id AND
						ti.item_id	= @item_id
		END
	-- --------------------------------------



END


































GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trItemAssociation]
   ON  [dbo].[tbItemAssociation]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @intCompID AS INT
	DECLARE @intItemID AS INT
	DECLARE @intItemID_Associated AS INT

	SELECT	@intCompID				= comp_id,
			@intItemID				= item_id,
			@intItemID_Associated	= item_id_1
		FROM INSERTED



	-- ---------------------------------------------------------------
	-- Listas de COSTO habilitadas
	-- ---------------------------------------------------------------
	DECLARE @curCompID		AS INT
	DECLARE @curCosLis_ID	AS INT
	DECLARE @curItem_Id		AS INT

	DECLARE curCostList CURSOR LOCAL FAST_FORWARD  FOR
		SELECT	ticl.comp_id,
				ticl.coslis_id,
				ticl.item_id
		FROM tbItemCostList				AS ticl			WITH (NOLOCK)
		INNER JOIN tbItemCostListName	AS ticln		WITH (NOLOCK)
			ON	ticln.comp_id		= ticl.comp_id		AND
				ticln.coslis_id		= ticl.coslis_id
		WHERE	ticl.comp_id	= @intCompID AND
				ticl.item_id	= @intItemID_Associated	AND
				ticln.coslis_enableComboChangesRecalculation = 'True'


	OPEN		curCostList
	FETCH NEXT FROM curCostList	INTO @curCompID,
									 @curCosLis_ID,
									 @curItem_Id
	WHILE @@FETCH_STATUS = 0
		BEGIN

			UPDATE tbItemCostList	WITH (ROWLOCK)
				SET coslis_price		= coslis_price,
					coslis_lastUpdate	= GETDATE()
				WHERE	comp_id		= @curCompID	AND
						coslis_id	= @curCosLis_ID AND
						item_id		= @curItem_Id


			FETCH NEXT FROM curCostList	INTO @curCompID,
											 @curCosLis_ID,
											 @curItem_Id
		END
	CLOSE		curCostList
	DEALLOCATE	curCostList
	-- ---------------------------------------------------------------




	-- ---------------------------------------------------------------
	-- Listas de PRECIOS habilitadas
	-- ---------------------------------------------------------------
	DECLARE @curPrLi_ID	AS INT

	DECLARE curPriceList CURSOR LOCAL FAST_FORWARD  FOR
		SELECT	ticl.comp_id,
				ticl.prli_id,
				ticl.item_id
		FROM tbPriceListItems			AS ticl			WITH (NOLOCK)
		INNER JOIN tbPriceList			AS ticln		WITH (NOLOCK)
			ON	ticln.comp_id		= ticl.comp_id		AND
				ticln.prli_id		= ticl.prli_id
		WHERE	ticl.comp_id	= @intCompID AND
				ticl.item_id	= @intItemID_Associated	AND
				ticln.prli_enableComboChangesRecalculation = 'True'


	OPEN		curPriceList
	FETCH NEXT FROM curPriceList	INTO @curCompID,
										 @curPrLi_ID,
										 @curItem_Id
	WHILE @@FETCH_STATUS = 0
		BEGIN

			UPDATE tbPriceListItems	WITH (ROWLOCK)
				SET		prli_price  = prli_price
				WHERE	comp_id		= @curCompID	AND
						prli_id		= @curPrLi_ID	AND
						item_id		= @curItem_Id


			FETCH NEXT FROM curPriceList	INTO @curCompID,
												 @curPrLi_ID,
												 @curItem_Id
		END
	CLOSE		curPriceList
	DEALLOCATE	curPriceList
	-- ---------------------------------------------------------------


	-- MOS 06-2022
  	UPDATE tbitem
		SET item_lastUpdate_byProcess = GETDATE()
		WHERE	comp_id = @intCompID AND
				item_id = @intItemID



END
GO

