-- =============================================
-- Author:		MOS
-- Create date: 03-2014
-- Description:	Solo puede haber un root
-- =============================================
CREATE TRIGGER [dbo].[trItemClass]
   ON  [dbo].[tbItemClass]
   AFTER  INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id			AS INT
	DECLARE @ic_id				AS INT
	DECLARE @ic_isRoot			AS BIT
	DECLARE @ic_id_sup			AS INT
	DECLARE @ic_isSelectable	AS BIT

	SELECT	@comp_id		 = comp_id,
			@ic_id			 = ic_id,
			@ic_isRoot		 = ic_isRoot,
			@ic_id_sup		 = ic_id_sup,
			@ic_isSelectable = ic_isSelectable
		FROM INSERTED


	-- No puede haber un NO Seleccionable con articulos YA ASOCIADOS
	IF	@ic_isSelectable = 'False' AND
		EXISTS(	SELECT 1
		       		FROM tbitem tmp
		       		WHERE	tmp.comp_id = @comp_id AND
		       				tmp.ic_id	= @ic_id
			  )
		BEGIN
			UPDATE tbItemClass
			SET			ic_isSelectable = 'True'
				WHERE	comp_id =	@comp_id AND
						ic_id	=	@ic_id
			SET @ic_isSelectable = 'True'
		END


	-- No puede ser seleccionable si tiene alguna relacionada a el
	IF	@ic_isSelectable = 'True' AND
		EXISTS(	SELECT 1
		       		FROM tbItemClass  tmp
		       		WHERE	tmp.comp_id		= @comp_id AND
		       				tmp.ic_id_sup	= @ic_id
			  )
		BEGIN
			UPDATE tbItemClass
			SET			ic_isSelectable = 'False'
				WHERE	comp_id =	@comp_id AND
						ic_id	=	@ic_id
			SET @ic_isSelectable = 'False'
		END


	-- No puede ser seleccionable si tiene alguna relacionada a el
	IF	@ic_isSelectable = 'True' AND  @ic_id_sup IS NULL
		BEGIN
			UPDATE tbItemClass
			SET			ic_isSelectable = 'False'
				WHERE	comp_id =	@comp_id AND
						ic_id	=	@ic_id
			SET @ic_isSelectable = 'False'
		END


	-- No puede haber un ROOT que apunte a un id de nivel superior
	IF @ic_isRoot = 'True' AND @ic_id_sup IS NOT NULL
		BEGIN
			UPDATE tbItemClass
			SET			ic_isRoot = 'False'
				WHERE	comp_id =	@comp_id AND
						ic_id	=	@ic_id
			SET @ic_isRoot = 'False'
		END

	-- Si es ROOT saca cualquier otro ROOT que este definido.
	IF @ic_isRoot = 'True'
		BEGIN
			UPDATE tbItemClass
				SET	ic_isRoot = 0
				WHERE	comp_id =	@comp_id AND
						ic_id	<>	@ic_id
		END



	-- -------------------------------------------
	-- Pone el Nivel de la clase actualmente
	-- asignada para TODAS las clases de esta
	-- compa#ia
	-- -------------------------------------------
	DECLARE @curIC_Id AS INT
	DECLARE curItemClass  CURSOR LOCAL FAST_FORWARD  FORWARD_ONLY FOR
		SELECT ic.ic_id
			FROM tbitemclass ic
			WHERE	ic.comp_id		= @comp_id AND
					ic.ic_isRoot	= 'False'

	OPEN curItemClass
	FETCH NEXT FROM curItemClass INTO @curIC_Id
	WHILE @@FETCH_STATUS = 0
		BEGIN


			DECLARE
						@intMyLevel		AS INT				,
						@strIcIdString	AS VARCHAR(4000)	,
						@intICIdRoot	AS INT


			SET @intMyLevel		= 0
			SET @strIcIdString	= ''
			SET @intICIdRoot	= NULL

			exec spItemClassLevelContructor @comp_id, @curIC_Id, @intMyLevel OUTPUT, @strIcIdString OUTPUT, @intICIdRoot OUTPUT


			CREATE TABLE #tblTemp(	intID		INT IDENTITY(1,1),
									ic_id		INT,
									ic_level	INT)

			--DECLARE #tblTemp AS TABLE(intID		INT IDENTITY(1,1),
			--						  ic_id		INT,
			--						  ic_level	INT)

			INSERT INTO #tblTemp
			(
				ic_id
			)
			SELECT tmp.items
				FROM dbo.fnSplitTable(@strIcIdString,';') tmp

			DECLARE @RowCount AS INT
			SET		@RowCount = @@ROWCOUNT

			UPDATE #tblTemp SET ic_level = @RowCount - intID




			--SELECT * FROM #tblTemp ORDER BY intID DESC
			--select @intMyLevel, @strIcIdString, @intICIdRoot


			IF @intICIdRoot IS NOT NULL
				BEGIN
					UPDATE tbItemClass
					SET
						ic_ownLevel		= (SELECT MAX(tmp.ic_level)	FROM #tblTemp tmp),
						ic_levelRoot	= @intICIdRoot,
						ic_levelI		= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 1) ,
						ic_levelII		= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 2) ,
						ic_levelIII		= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 3) ,
						ic_levelIV		= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 4) ,
						ic_levelV		= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 5) ,
						ic_levelVI		= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 6) ,
						ic_levelVII		= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 7) ,
						ic_levelVIII	= (SELECT tmp.ic_id	FROM #tblTemp tmp WHERE tmp.ic_level = 8)
						WHERE	comp_id = @comp_id AND
								ic_id	= @curIC_Id
				END


			DROP TABLE #tblTemp

			FETCH NEXT FROM curItemClass INTO @curIC_Id
		END
	CLOSE curItemClass
	DEALLOCATE curItemClass
	-- -------------------------------------------







END
GO




-- =============================================
-- Author:		MOS
-- Create date: 08-2013
-- Description:	Si se modifica la composicion
-- automaticamente se abre nuevamente el pedido.
-- =============================================
CREATE TRIGGER  trItemComposition
   ON  tbItemComposition
   AFTER  INSERT,DELETE,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    DECLARE @comp_id	AS INT
    DECLARE @item_id	AS INT

    SELECT	@comp_id = comp_id,
			@item_id = item_id
		FROM INSERTED

	IF @comp_id IS NULL
		BEGIN
			SELECT	@comp_id = comp_id,
					@item_id = item_id
				FROM DELETED
		END

    IF @comp_id IS NOT NULL
		BEGIN
			UPDATE tbSaleOrderHeader
				SET
					ssos_id = 20
				FROM tbSaleOrderHeader			soh
				INNER JOIN tbSaleOrderDetail	sod
					ON	sod.comp_id = soh.comp_id AND
						sod.bra_id  = soh.bra_id  AND
						sod.soh_id	= soh.soh_id
				INNER JOIN tbDocumentsFile tdf
					ON	tdf.comp_id = soh.comp_id AND
						tdf.df_id	= soh.df_id
				WHERE	soh.comp_id = @comp_id AND
						sod.item_id = @item_id AND
						tdf.sd_id	= 80
		END



END
GO


CREATE TRIGGER [dbo].[trItemCostList]
	ON [dbo].[tbItemCostList]
	AFTER INSERT, UPDATE, DELETE
AS

BEGIN


	SET NOCOUNT ON

	DECLARE @comp_id			AS INT
	DECLARE @coslis_id			AS INT
	DECLARE @item_id			AS INT
	DECLARE @curr_id			AS INT
	DECLARE @decLastCost		AS DECIMAL(19,6)
	DECLARE @bitDisabled4Rules	AS BIT
	DECLARE @coslis_blockLastUpdate4Rules AS BIT
	DECLARE @user_id			AS INT
	DECLARE @coslis_lastUpdate  AS DATETIME


	DECLARE @coslis_priceNew		AS DECIMAL(19,6)
	DECLARE @coslis_price_awNew		AS DECIMAL(19,6)
	DECLARE @curr_idNew				AS INT
	DECLARE @coslis_disabled4Rules  AS BIT = 'False'

	SELECT	@comp_id						= comp_id,
			@coslis_id						= coslis_id,
			@item_id						= item_id,
			@decLastCost					= coslis_price,
			@bitDisabled4Rules				= coslis_disabled4Rules,
			@coslis_blockLastUpdate4Rules	= ISNULL(coslis_blockLastUpdate4Rules,'False'),
			@user_id						= user_id_lastUpdate,
			@coslis_lastUpdate				= coslis_lastUpdate,
			@coslis_priceNew				= coslis_price,
			@coslis_price_awNew				= coslis_price_aw,
			@curr_idNew						= curr_id,
			@coslis_disabled4Rules			= coslis_disabled4Rules
	FROM	INSERTED


	-- ------------------------------------------------
	-- Si la actualizacion por ejemplo de Edicion Conf de Precios NO actualizó nada igual se dispara el trigger con NULL en todos lkos valores de Inserted ya que NO actualizó en realidad ningun registro.
	-- Esto pasa por ejemplo haciendo un Update por comp, item, y ademas en el where comparando si un valor adicional varió.  Si NO se actualiza ningun rtegistro se dispara un trigger con NULL en INSERTED.
	-- ------------------------------------------------
	IF @comp_id IS NULL
		BEGIN
			RETURN
		END
	-- ------------------------------------------------


	DECLARE @coslis_price4History		AS DECIMAL(19,6)
	DECLARE @coslis_price_aw4History	AS DECIMAL(19,6)
	DECLARE @curr_id4History			AS INT
	SELECT	@coslis_price4History		= coslis_price,
			@coslis_price_aw4History	= coslis_price_aw,
			@curr_id4History			= curr_id
		FROM DELETED



	-- -------------------------------------------------------------------------------------
	-- ATENCIÓN:
	-- Esto se pone para que SI o SI saque el disabled4Rules por mas que salte algun error.
	-- -------------------------------------------------------------------------------------
	BEGIN TRY




			-- Se hace un CURSOR ya que si tiro un update no se porque no se disparan los Triggers.-


			-- ATENCION, hacerlo como en VENTAS que NO se hsa esta mierda y es mucho mas rapido !!!!!
			-- POner que no dispare Trigger otra vez
			-- Actualiza el Ultimo Costo antes de setear el Nuevo.-
			UPDATE tbItemCostList		WITH (ROWLOCK)
				SET
				coslist_UpdateNumber		= IsNull(coslist_UpdateNumber,0) + 1,
				coslis_price_PreLastUpdate	= (
												SELECT TOP 1 ticlh.iclh_price
														FROM tbItemCostListHistory ticlh		WITH (NOLOCK)
														WHERE	ticlh.comp_id	= @comp_id
															AND ticlh.coslis_id = @coslis_id
															AND ticlh.item_id	= @item_id
														ORDER BY ticlh.iclh_id DESC
											),
				curr_id_PreLastUpdate		= (
												SELECT TOP 1 ticlh.curr_id
														FROM tbItemCostListHistory ticlh		WITH (NOLOCK)
														WHERE	ticlh.comp_id	= @comp_id
															AND ticlh.coslis_id = @coslis_id
															AND ticlh.item_id	= @item_id
														ORDER BY ticlh.iclh_id DESC
											  ),
				coslis_lastUpdate			= GETDATE()

			WHERE		comp_id		= @comp_id
					AND coslis_id	= @coslis_id
					AND item_id		= @item_id



			IF @coslis_blockLastUpdate4Rules = 'False'
				BEGIN
					EXEC spCostlistActualizationRules @comp_id,	@coslis_id,	@item_id, 'False', @bitDisabled4Rules
				END


			-- MOS: 02-2020, se pasó a SP para poder usarlo en varios lugares.
			EXEC spCostlistActualizationRules_SetComboCosts @comp_id,@item_id,@coslis_id,@user_id

			---- ----------------------------------------------------------------------------------------------
			---- Si tiene Articulos Asociados pone el costo del KIT como la suma de los costos de las partes.
			---- ----------------------------------------------------------------------------------------------
