			--				UPDATE	tbItemCostList		WITH (ROWLOCK)
			--					SET		coslis_price		= @coslis_price,
			--							coslis_price_aw		= @coslis_price_aw,
			--							coslis_cd			= GETDATE(),
			--							user_id_lastUpdate  = @user_id,
			--							coslis_lastUpdate	= GETDATE()

			--					WHERE	comp_id		= @comp_id
			--					AND		coslis_id	= @coslis_id
			--					AND		item_id		= @curItemID






			--				FETCH NEXT FROM curItemAssociation INTO @curItemID

			--			END


			--			CLOSE		curItemAssociation
			--			DEALLOCATE	curItemAssociation

			--	END
			---- ----------------------------------------------------------------------------------------------



			-- ------------------------------------------
			-- Lo que ANTES hacia el trigger de history
			-- ------------------------------------------
			IF	@comp_id IS NOT NULL AND
			(
				@coslis_price4History		<> @coslis_priceNew	 		OR
				@coslis_price4History		IS NULL 					OR
				@coslis_price_aw4History	<> @coslis_price_awNew		OR
				@coslis_price_aw4History	IS NULL						OR
				@curr_id4History			<> @curr_idNew				OR
				@curr_id4History			IS NULL
			)
				BEGIN

					declare @counter_value INT = 0
					-- En el actualizador se va a poner con Lote -1 lo ACTUAL ya que desde ahora en la historia SIEMPRE va a estar TODO, hasta la ultima actualizacion ACTUAL.
					-- Exec dbo.spCounters_getNextValue  @comp_id,  1, 6, @counter_value output

					INSERT INTO  tbItemCostListHistory
						(	comp_id ,
							coslis_id ,
							item_id ,
							iclh_lote ,
							iclh_price ,
							iclh_price_aw ,
							curr_id ,
							iclh_cd,
							user_id_lastUpdate )

						SELECT
							@comp_id,
							@coslis_id,
							@item_id,
							0,
							@coslis_priceNew,
							@coslis_price_awNew,
							@curr_idNew,
							GETDATE(),
							@user_id


				END


			-- Graba el historial para los forros de DS q no se para que MIERDA lo quieren
			IF DB_NAME() LIKE '%_TIU' AND @comp_id IS NOT NULL
				BEGIN
					DELETE FROM tbWebServices_ItemUpdateHistory	WITH (ROWLOCK)
						WHERE	comp_id = @comp_id AND
								item_id = @item_id

					INSERT INTO tbWebServices_ItemUpdateHistory(comp_id, item_id, wsh_cd)
					VALUES(@comp_id, @item_id, GETDATE())
				END
			--EXEC spWebServices_ItemUpdateHistory @comp_id,@item_id

			-- ------------------------------------------


	END TRY
	BEGIN CATCH
	END CATCH
	-- -------------------------------------------------------------------------------------





	-- -----------------------------------------------------------
	-- Saca Bloqueo de Ejecucion de Reglas de Actualizacion
	-- -----------------------------------------------------------
	UPDATE tbItemCostList		WITH (ROWLOCK)
		SET	coslis_disabled4Rules			= 'False',
			coslis_blockLastUpdate4Rules	= 'False',
			user_id_lastUpdate				= NULL			-- si no se actualizo AHORA el usuario, antes quedaba hasta q otro lo actualice.  Ahora va directo al historial.
		WHERE	comp_id		= @comp_id		AND
				coslis_id	= @coslis_id	AND
				item_id		= @item_id
	-- -----------------------------------------------------------




	-- ---------------------------------------------------
	-- Actualiza datos de Hijos de Talles y Colores
	-- ---------------------------------------------------
	IF EXISTS (SELECT TOP  1	1	-- DISTINCT 1  MOS 03-2021
				FROM	tbItemSizeColorRelation tiscr	 WITH (NOLOCK)
				WHERE	tiscr.comp_id = @Comp_id
				AND		tiscr.item_id = @Item_id)
    BEGIN

    	DECLARE @litem_id_child				INT,
    			@liscr_Coeficient4Price		DECIMAL(19,4)

    	--declaración de cursor para recuperar los items hijos y los coeficientes
    	DECLARE cursor_childs4trItemCostList CURSOR LOCAL FAST_FORWARD FOR
    		SELECT	tiscr.item_id_child,
    				tiscr.iscr_Coeficient4Price
    			FROM	tbItemSizeColorRelation		tiscr				WITH (NOLOCK)
    			WHERE	tiscr.comp_id = @Comp_id
    			AND		tiscr.item_id = @Item_id	AND
    					tiscr.item_id_child IS NOT NULL AND
    					tiscr.iscr_Coeficient4Price IS NOT NULL


    	OPEN cursor_childs4trItemCostList

    	FETCH  cursor_childs4trItemCostList INTO @litem_id_child, @liscr_Coeficient4Price

    	WHILE @@FETCH_STATUS = 0
    	BEGIN


			IF NOT EXISTS (	SELECT TOP 1  1
			               		FROM tbItemCostList ticl	WITH (NOLOCK)
			               		WHERE	ticl.comp_id	= @comp_id		AND
			               				ticl.coslis_id	= @coslis_id	AND
			               				ticl.item_id	= @litem_id_child
			)
				BEGIN

					INSERT INTO tbItemCostList
					(
						comp_id,
						coslis_id,
						item_id,
						coslis_price,
						coslis_price_aw,
						curr_id
					)
						VALUES(@comp_id,@coslis_id,@litem_id_child,0,0,1)
				END

			UPDATE tbItemCostList		WITH (ROWLOCK)
				SET
					tbItemCostList.coslis_price					= ti2.coslis_price,
					tbItemCostList.coslis_price_aw				= ti2.coslis_price_aw,
					tbItemCostList.curr_id						= ti2.curr_id,
					tbItemCostList.coslis_price_Original		= ti2.coslis_price_Original,
					tbItemCostList.coslis_price_Disc1			= ti2.coslis_price_Disc1,
					tbItemCostList.coslis_price_Disc2			= ti2.coslis_price_Disc2,
					tbItemCostList.coslis_price_Disc3			= ti2.coslis_price_Disc3,
					tbItemCostList.coslis_price_Disc4			= ti2.coslis_price_Disc4,
					tbItemCostList.user_id_lastUpdate			= ti2.user_id_lastUpdate,
					tbItemCostList.coslis_disabled4Rules		= ti2.coslis_disabled4Rules,
					tbItemCostList.coslis_blockLastUpdate4Rules = ti2.coslis_blockLastUpdate4Rules,
					tbItemCostList.coslis_lastUpdate			= GETDATE()

				FROM tbItemCostList

				INNER JOIN tbItemCostList ti2	WITH (NOLOCK)
					ON	ti2.comp_id		= @Comp_id			AND
						ti2.item_id		= @Item_id			AND
						ti2.coslis_id	= @coslis_id

				WHERE	tbItemCostList.comp_id	= @Comp_id			AND
						tbItemCostList.item_id	= @litem_id_child	AND
						tbItemCostList.coslis_id= @coslis_id

    		FETCH  cursor_childs4trItemCostList INTO @litem_id_child, @liscr_Coeficient4Price

    	END

    	CLOSE cursor_childs4trItemCostList
    	DEALLOCATE cursor_childs4trItemCostList


	END
	-- ---------------------------------------------------



END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trItemEAN]
   ON  [dbo].[tbItemEAN]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    DECLARE @comp_id AS INT
    DECLARE @item_id AS INT
    DECLARE @ie_id	 AS INT
    DECLARE @ie_ean  AS NVARCHAR(50)
    DECLARE @ie_Force2InternalNewEAN AS BIT
    DECLARE @strError AS NVARCHAR(500)

    SELECT	@comp_id = comp_id,
			@ie_id   = ie_id,
			@item_id = item_id,
			@ie_ean	 = ie_ean,
			@ie_Force2InternalNewEAN = IsNull(ie_Force2InternalNewEAN,'False')
		FROM INSERTED


    DECLARE @strSerial	AS NVARCHAR(100)
    DECLARE @strItem	AS NVARCHAR(100)




    IF @ie_Force2InternalNewEAN = 'False'
		BEGIN

			SET @strSerial = ''
			SET @strItem   = ''
			SELECT @strItem = 'on Item / en Artículo ID:' + CONVERT(NVARCHAR(10), ti.item_id)
				FROM tbitem ti
			WHERE	 ti.comp_id = @comp_id AND
					(	ti.item_code			= @ie_ean	OR
						ti.item_vendorCode		= @ie_ean	OR
						ti.item_codeAlternative = @ie_ean)

			SELECT @strSerial =  'Serial # on Item / # Serie en Artículo ID:' + CONVERT(NVARCHAR(10), tis.item_id)
				FROM tbItemSerials tis
				WHERE	tis.comp_id		= @comp_id AND
						tis.is_serial	= @ie_ean


			IF @strSerial <> '' OR @strItem <> ''
				BEGIN

					DELETE FROM tbItemEAN
						WHERE	comp_id = @comp_id AND
								ie_id	= @ie_id

					SET @strError =  '| <b> * El código  EAN ya existe como: Código de Artículo, Código del Proveedor, Código Alternativo o Número de Serie <br> <br> * The EAN code already exists as Item Code, Supplier Code, Alternate Code or Serial Number <br> <br> <br>' + @strItem + '<br> <br> <br>' + @strSerial + '</b>'
					RAISERROR (15600,-1,-1, @strError);
					RETURN
				END
		END

	ELSE

		BEGIN

			DECLARE @strEANNEW AS NVARCHAR(20)
			SET @strEANNEW = ''
			SELECT @strEANNEW = dbo.fnStrAllTrim(CONVERT(NVARCHAR(20), ISNULL(tc.comp_EANInternalNumberRange,'') ) )
				FROM tbCompany tc
				WHERE tc.comp_id = @comp_id

			IF LEN(@strEANNEW) = 4
				BEGIN
					UPDATE tbcompany
						SET comp_EANInternalNumber	=  IsNull(comp_EANInternalNumber,0) + 1
						WHERE comp_id				=  @comp_id

					SELECT @strEANNEW		=   @strEANNEW + dbo.fnstrpadl( dbo.fnStrAllTrim(CONVERT(NVARCHAR(20), ISNULL(tc.comp_EANInternalNumber,'') )), 8,'0')
						FROM tbCompany tc
						WHERE tc.comp_id	= @comp_id

					DECLARE @strCheckDigit AS CHAR(1)
					SET @strCheckDigit = NULL
					set @strCheckDigit = dbo.fnGetEAN_CheckDigit(@strEANNEW)
					IF @strCheckDigit IS NULL
						BEGIN
							DELETE FROM tbItemEAN
								WHERE	comp_id = @comp_id AND
										ie_id	= @ie_id
							SET @strError = '| <b> * Cálculo de Dígito verificador ERRONEO, verificar la configuración EAN en Archivo de Compañía <br> <br> * Check digit calculation WRONG, verify configuration file EAN Company <br> <br> <br>' + @strItem + '<br> <br> <br>' + @strSerial + '</b>'
							RAISERROR (15600,-1,-1, @strError);
							RETURN
						END
					ELSE
						BEGIN
							SET @strEANNEW = @strEANNEW + @strCheckDigit
						END

				END
			ELSE	-- no esta definida la cabecera, error
				BEGIN
					DELETE FROM tbItemEAN
						WHERE	comp_id = @comp_id AND
								ie_id	= @ie_id
					SET @strError =  '| <b> * No está definido el rango de comienzo de EAN en el archivo de Compañías o no es de 4 dígitos <br> <br> * Is not defined range EAN beginning of the file Companies or not 4 digits <br> <br> <br>' + @strItem + '<br> <br> <br>' + @strSerial + '</b>'
					RAISERROR (15600,-1,-1, @strError);
					RETURN
				END


			-- Verifica que no exista el numero generado
			SET @strSerial	= ''
			SET @strItem	= ''
			SET @ie_ean		= @strEANNEW

			SELECT @strItem = 'on Item / en Artículo ID:' + CONVERT(NVARCHAR(10), ti.item_id) + ' # ' + @strEANNEW
				FROM tbitem ti
			WHERE	 ti.comp_id = @comp_id AND
					(	ti.item_code			= @ie_ean	OR
						ti.item_vendorCode		= @ie_ean	OR
						ti.item_codeAlternative = @ie_ean)

			SELECT @strSerial =  'Serial # on Item / # Serie en Artículo ID:' + CONVERT(NVARCHAR(10), tis.item_id) + ' # ' + @strEANNEW
				FROM tbItemSerials tis
				WHERE	tis.comp_id		= @comp_id AND
						tis.is_serial	= @ie_ean


			SELECT @strSerial =  'on Item EAN / en EAN del Artículo ID:' + CONVERT(NVARCHAR(10), tis.item_id) + ' # ' + @strEANNEW
				FROM tbitemean tis
				WHERE	tis.comp_id		= @comp_id AND
						tis.ie_ean	= @ie_ean

			IF @strSerial <> '' OR @strItem <> ''
				BEGIN

					DELETE FROM tbItemEAN
						WHERE	comp_id = @comp_id AND
								ie_id	= @ie_id

					SET @strError =  '| <b> * El código  EAN ya existe como: Código de Artículo, Código del Proveedor, Código Alternativo o Número de Serie <br> <br> * The EAN code already exists as Item Code, Supplier Code, Alternate Code or Serial Number <br> <br> <br>' + @strItem + '<br> <br> <br>' + @strSerial + '</b>'
					RAISERROR (15600,-1,-1, @strError);
					RETURN
				END
			-- Verifica que no exista el numero generado

			UPDATE tbItemEAN
				SET
					ie_ean					= @strEANNEW,
					ie_isInternalEAN		= 'True',
					ie_Force2InternalNewEAN = 'False'
				WHERE	comp_id = @comp_id AND
						ie_id	= @ie_id


		END

END
GO



-- =============================================
-- Author:		MOS
-- Create date: 07/2014
-- Description:	Fuerza a actualizar Imagenes
--				en WebSite
-- =============================================
CREATE TRIGGER [dbo].[trItemImages]
   ON  [dbo].[tbItemImages]
   AFTER INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id	AS INT
	DECLARE @item_id	AS INT
	DECLARE @itimg_id	AS INT

	SELECT	@comp_id	= comp_id,
			@item_id	= item_id,
			@itimg_id   = itimg_id
		FROM INSERTED



BEGIN



	IF EXISTS(
			SELECT 1
			FROM tbItemImages  tc
				WHERE	tc.comp_id	= @comp_id		AND
						tc.item_id	= @item_id		AND
						tc.itimg_id = @itimg_id		AND
						tc.itimg_image IS NOT NULL	AND
						(
							tc.itimg_imageChecksum IS NULL
							OR
							tc.itimg_imageChecksum <> dbo.fnChecksum4Image(tc.itimg_image)
						)
				)
		BEGIN

			UPDATE tbWebSiteII_Names	WITH (ROWLOCK)
				SET	ws_files2TempUpdated				= 'False',
					ws_files2TempUpdated4Development	= 'False'

			UPDATE tbItemImages			WITH (ROWLOCK)
				SET itimg_imageChecksum	= dbo.fnChecksum4Image(itimg_image),
					itimg_imageUpdated = 1
				WHERE	comp_id			= @comp_id		AND
						item_id			= @item_id		AND
						itimg_id		= @itimg_id

		END
	ELSE
		BEGIN
		UPDATE tbItemImages	WITH (ROWLOCK)
			SET itimg_imageUpdated = 1
			WHERE	comp_id			= @comp_id		AND
					item_id			= @item_id		AND
					itimg_id		= @itimg_id

		END
END


	--IF EXISTS(
	--		SELECT 1
	--		FROM tbItemImages  tc
	--			WHERE	tc.comp_id	= @comp_id		AND
	--					tc.item_id	= @item_id		AND
	--					tc.itimg_id = @itimg_id		AND
	--					tc.itimg_image IS NOT NULL
	--			)
	--BEGIN
	--	UPDATE tbWebSiteII_Names
	--		SET	ws_files2TempUpdated = 'False',
	--			ws_files2TempUpdated4Development = 'False'
	--END

END
GO



