-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trItemPublicationDetail]
   ON  [dbo].[tbItemPublicationDetail]
   AFTER  DELETE   --,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	-- --------------------------------------------------------------
	-- Esto tambien va en el Otro Trigger de esta tabla, al final !!!
	-- --------------------------------------------------------------
	DECLARE @comp_id						AS INT
	DECLARE @pubh_id						AS INT
	-- 1ro para Actualizaciones
	SELECT  @comp_id	= comp_id,
			@pubh_id	= pubh_id
		FROM INSERTED

	IF	@pubh_id IS NOT NULL AND
		EXISTS(
				SELECT TOP 1  1
					FROM vwItemPublicationHeader viph	WITH (NOLOCK)
					WHERE	viph.comp_id = @comp_id AND
							viph.pubh_id = @pubh_id
				)
		BEGIN
			EXEC spItemPublicationActiveItems @comp_id
		END


	IF @pubh_id IS NULL
		BEGIN
			SELECT  @comp_id	= comp_id,
					@pubh_id	= pubh_id
				FROM DELETED
			-- 2do para Bajas
			IF  @pubh_id IS NOT NULL AND
				EXISTS(
						SELECT TOP 1  1
							FROM vwItemPublicationHeader viph	WITH (NOLOCK)
							WHERE	viph.comp_id = @comp_id AND
									viph.pubh_id = @pubh_id
						)
				BEGIN
					EXEC spItemPublicationActiveItems @comp_id
				END
		END
	-- --------------------------------------------------------------

END
GO




-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trItemPublicationDetailINSERT]
   ON  [dbo].[tbItemPublicationDetail]
   AFTER INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here
    -- VARIABLES DE TRABAJO
    DECLARE
    	@comp_id	INT,
    	@pubh_id	INT,
    	@pubd_id	INT,
    	@item_id	INT,
    	@bra_id		INT,
    	@pubd_isItemUpdated		BIT  -- Si fue una actualizacion directa del HIJO que no actualice con los datos del padre !!

    --OBTENEMOS LAS CLAVES YA INSERTADAS
    SELECT
		@comp_id			= comp_id,
		@pubh_id			= pubh_id,
		@pubd_id			= pubd_id,
		@item_id			= item_id,
		@pubd_isItemUpdated = ISNULL(pubd_isItemUpdated,'False')
		FROM Inserted

    --OBTENEMOS LA SUCURSAL DE LA HEADER
    SELECT
		@bra_id	=	tiph.bra_id4Config
		FROM tbItemPublicationHeader	tiph		WITH (NOLOCK)
		WHERE	tiph.comp_id = @comp_id	AND
				tiph.pubh_id = @pubh_id



	-- ------------------------------------------------------------------------
	-- VARIABLES DE ACTUALIZACION
	-- ------------------------------------------------------------------------

		DECLARE
			@coslis_price					DECIMAL(19,4),
			@creditI_up2Pays				INT,
			@creditI_creditInterest			DECIMAL(19,4),
			@creditII_up2Pays				INT,
			@creditII_creditInterest		DECIMAL(19,4),
			@creditIII_up2Pays				INT,
			@creditIII_creditInterest		DECIMAL(19,4),
			@creditIV_up2Pays				INT,
			@creditIV_creditInterest		DECIMAL(19,4),
			@item_purOrd_Disc1				DECIMAL(18,4),
			@item_purOrd_Disc2				DECIMAL(18,4),
			@item_purOrd_Disc3				DECIMAL(18,4),
			@item_purOrd_Disc4				DECIMAL(18,4),
			@item_purOrd_surcharge1			DECIMAL(18,4),
			@item_purOrd_surcharge2			DECIMAL(18,4),
			@item_purOrd_surcharge3			DECIMAL(18,4),
			@item_purOrd_surcharge4			DECIMAL(18,4),
			@prli_idInCash					INT,
			@item_markup_1					DECIMAL(19,8),
			@prli_priceInCash				DECIMAL(19,4),
			@curr_idInCash					INT,
			@prli_id4Loan					INT,
			@item_markup_2					DECIMAL(19,8),
			@prli_price4Loan				DECIMAL(19,4),
			@curr_id4Loan					INT,
			@coslis_id						INT,
			@curr_idCost					INT,
			@CreditQuotaQtyMaximum			INT

	-- ------------------------------------------------------------------------





	-- ------------------------------------------------------------------------
	-- Busca si es un HIJO de talles y colores para poner los valores del PADRE
	-- ------------------------------------------------------------------------
	DECLARE @item_Id2Search AS INT
	SET		@item_Id2Search = @item_id
	DECLARE @bitIsChild		AS BIT
	SET		@bitIsChild		= 'False'

	SELECT	 TOP 1
			 @item_Id2Search	= tiscr.item_id,
			 @bitIsChild		= 'True'
		FROM tbItemSizeColorRelation tiscr			WITH (NOLOCK)
		WHERE	tiscr.comp_id		= @comp_id AND
				tiscr.item_id_child = @item_id AND
				tiscr.iscr_Enabled  = 'True'
	-- ------------------------------------------------------------------------


	IF @bitIsChild = 'False' AND @pubd_isItemUpdated = 'False'
		BEGIN

			--CARGAMOS LOS CAMPOS A ACTUALIZAR
			SELECT
				@creditI_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditI_up2Pays ELSE ISNULL(tb.creditI_up2Pays,0) END,
				--@creditI_up2Pays				= ti.creditI_up2Pays,
				@creditI_creditInterest			= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditI_creditInterest ELSE ISNULL(tb.creditI_creditInterest,0) END,
				--@creditI_creditInterest		= ti.creditI_creditInterest,

				@creditII_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditII_up2Pays ELSE ISNULL(tb.creditII_up2Pays,0) END,
				--@creditII_up2Pays				= ti.creditII_up2Pays,
				@creditII_creditInterest		= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditII_creditInterest ELSE ISNULL(tb.creditII_creditInterest,0) END,
				--@creditII_creditInterest		= ti.creditII_creditInterest

				@creditIII_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditIII_up2Pays ELSE ISNULL(tb.creditIII_up2Pays,0) END,
				--@creditIII_up2Pays				= ti.creditIII_up2Pays,
				@creditIII_creditInterest		= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditIII_creditInterest ELSE ISNULL(tb.creditIII_creditInterest,0) END,
				--@creditIII_creditInterest		= ti.creditIII_creditInterest

				@creditIV_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditIV_up2Pays ELSE ISNULL(tb.creditIV_up2Pays,0) END,
				--@creditIV_up2Pays				= ti.creditIV_up2Pays,
				@creditIV_creditInterest		= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditIV_creditInterest ELSE ISNULL(tb.creditIV_creditInterest,0) END,
				--@creditIV_creditInterest		= ti.creditIV_creditInterest

				@item_purOrd_Disc1				= ti.item_purOrd_Disc1,
				@item_purOrd_Disc2				= ti.item_purOrd_Disc2,
				@item_purOrd_Disc3				= ti.item_purOrd_Disc3,
				@item_purOrd_Disc4				= ti.item_purOrd_Disc4,
				@item_purOrd_surcharge1			= ti.item_purOrd_surcharge1,
				@item_purOrd_surcharge2			= ti.item_purOrd_surcharge2,
				@item_purOrd_surcharge3			= ti.item_purOrd_surcharge3,
				@item_purOrd_surcharge4			= ti.item_purOrd_surcharge4,
				@item_markup_1					= ti.item_markup_1,
				@item_markup_2					= ti.item_markup_2,

				@CreditQuotaQtyMaximum			= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.CreditQuotaQtyMaximum ELSE ISNULL(tb.CreditQuotaQtyMaximum,0) END
				--ti.CreditQuotaQtyMaximum

				FROM tbItem								ti	WITH (NOLOCK)

				INNER JOIN tbBrand					AS	tb	WITH(NOLOCK)
				ON	tb.comp_id		= ti.comp_id	AND
					tb.brand_id		= ti.brand_id


				WHERE	ti.comp_id			= @comp_id		AND
						ti.item_id			= @item_Id2Search


			SELECT TOP 1
				@coslis_id						= tb.coslis_id,
				@curr_idCost					= ticl.curr_id,
				@coslis_price					= ticl.coslis_price,

				@prli_idInCash					= tb.prli_id4CreditInCash,
				@prli_priceInCash				= tpliInCash.prli_price,
				@curr_idInCash					= tpliInCash.curr_id,

				@prli_id4Loan					= tb.prli_id4Credit,
				@prli_price4Loan				= tpliCredit.prli_price,
				@curr_id4Loan					= tpliCredit.curr_id
				FROM tbBranch tb				WITH (NOLOCK)
				--CONTADO
				LEFT JOIN tbPriceListItems				tpliInCash		WITH (NOLOCK)
					ON	tpliInCash.comp_id	= tb.comp_id	AND
						tpliInCash.item_id	= @item_id		AND
						tpliInCash.prli_id	= tb.prli_id4CreditInCash
				--LISTA
				LEFT JOIN tbPriceListItems				tpliCredit		WITH (NOLOCK)
					ON	tpliCredit.comp_id	= tb.comp_id	AND
						tpliCredit.item_id	= @item_id		AND
						tpliCredit.prli_id	= tb.prli_id4Credit
				--COSTOS
				LEFT JOIN tbItemCostList				ticl			WITH (NOLOCK)
					ON	ticl.comp_id	= tb.comp_id	AND
						ticl.item_id	= @item_id		AND
						ticl.coslis_id	= tb.coslis_id

				WHERE	tb.comp_id				= @comp_id		AND
						tb.bra_id				= @bra_id



			UPDATE tbItemPublicationDetail
			SET
				pubd_cost					= @coslis_price,
				creditI_up2Pays				= @creditI_up2Pays,
				creditI_creditInterest		= @creditI_creditInterest,
				creditII_up2Pays			= @creditII_up2Pays,
				creditII_creditInterest		= @creditII_creditInterest,
				creditIII_up2Pays			= @creditIII_up2Pays,
				creditIII_creditInterest	= @creditIII_creditInterest,
				creditIV_up2Pays			= @creditIV_up2Pays,
				creditIV_creditInterest		= @creditIV_creditInterest,
				item_purOrd_Disc1			= @item_purOrd_Disc1,
				item_purOrd_Disc2			= @item_purOrd_Disc2,
				item_purOrd_Disc3			= @item_purOrd_Disc3,
				item_purOrd_Disc4			= @item_purOrd_Disc4,
				item_purOrd_surcharge1		= @item_purOrd_surcharge1,
				item_purOrd_surcharge2		= @item_purOrd_surcharge2,
				item_purOrd_surcharge3		= @item_purOrd_surcharge3,
				item_purOrd_surcharge4		= @item_purOrd_surcharge4,
				prli_idInCash				= @prli_idInCash,
				item_markup_1				= @item_markup_1,
				pubd_priceInCash			= @prli_priceInCash,
				curr_idInCash				= @curr_idInCash,
				prli_id4Loan				= @prli_id4Loan,
				item_markup_2				= @item_markup_2,
				pubd_price4Loan				= @prli_price4Loan,
				curr_id4Loan				= @curr_id4Loan,
				coslis_id					= @coslis_id,
				curr_idCost					= @curr_idCost,
				CreditQuotaQtyMaximum		= @CreditQuotaQtyMaximum,
				pubd_isItemUpdated			= 'False'

			WHERE	comp_id					= @comp_id AND
					pubh_id					= @pubh_id AND
					pubd_id					= @pubd_id AND
					item_id					= @item_id

		END


	IF @bitIsChild = 'False' AND @pubd_isItemUpdated = 'True'
		BEGIN
			UPDATE tbItemPublicationDetail
			SET		pubd_isItemUpdated			= 'False'

			WHERE	comp_id					= @comp_id AND
					pubh_id					= @pubh_id AND
					pubd_id					= @pubd_id AND
					item_id					= @item_id
		END

	-- Si es HIJO actualiza con los datos del PADRE siempre y cuando el trigger actualizo al PADRE y no a un hijo
	IF @bitIsChild = 'True' AND @pubd_isItemUpdated = 'False'
		BEGIN


			-- Busca las listas que debe actualizar segun la definicion de la publicacion
			SELECT TOP 1
				@coslis_id						= tb.coslis_id,
				@curr_idCost					= ticl.curr_id,
				@coslis_price					= ticl.coslis_price,

				@prli_idInCash					= tb.prli_id4CreditInCash,
				@prli_priceInCash				= tpliInCash.prli_price,
				@curr_idInCash					= tpliInCash.curr_id,

				@prli_id4Loan					= tb.prli_id4Credit,
				@prli_price4Loan				= tpliCredit.prli_price,
				@curr_id4Loan					= tpliCredit.curr_id
				FROM tbBranch tb										WITH (NOLOCK)
				--CONTADO
				LEFT JOIN tbPriceListItems				tpliInCash		WITH (NOLOCK)
					ON	tpliInCash.comp_id	= tb.comp_id	AND
						tpliInCash.item_id	= @item_id		AND
						tpliInCash.prli_id	= tb.prli_id4CreditInCash
				--LISTA
				LEFT JOIN tbPriceListItems				tpliCredit		WITH (NOLOCK)
					ON	tpliCredit.comp_id	= tb.comp_id	AND
						tpliCredit.item_id	= @item_id		AND
						tpliCredit.prli_id	= tb.prli_id4Credit
				--COSTOS
				LEFT JOIN tbItemCostList				ticl			WITH (NOLOCK)
					ON	ticl.comp_id	= tb.comp_id	AND
						ticl.item_id	= @item_id		AND
						ticl.coslis_id	= tb.coslis_id

				WHERE	tb.comp_id				= @comp_id		AND
						tb.bra_id				= @bra_id


			DECLARE @bitFatherInPublication		AS BIT
			SET		@bitFatherInPublication		= 'False'

			-- Busca datos del Padre en la actual publicacion
			SELECT
				@creditI_up2Pays				= ti.creditI_up2Pays,
				@creditI_creditInterest			= ti.creditI_creditInterest,
				@creditII_up2Pays				= ti.creditII_up2Pays,
				@creditII_creditInterest		= ti.creditII_creditInterest,
				@creditIII_up2Pays				= ti.creditIII_up2Pays,
				@creditIII_creditInterest		= ti.creditIII_creditInterest,
				@creditIV_up2Pays				= ti.creditIV_up2Pays,
				@creditIV_creditInterest		= ti.creditIV_creditInterest,
				@item_purOrd_Disc1				= ti.item_purOrd_Disc1,
				@item_purOrd_Disc2				= ti.item_purOrd_Disc2,
				@item_purOrd_Disc3				= ti.item_purOrd_Disc3,
				@item_purOrd_Disc4				= ti.item_purOrd_Disc4,
				@item_purOrd_surcharge1			= ti.item_purOrd_surcharge1,
				@item_purOrd_surcharge2			= ti.item_purOrd_surcharge2,
				@item_purOrd_surcharge3			= ti.item_purOrd_surcharge3,
				@item_purOrd_surcharge4			= ti.item_purOrd_surcharge4,
				@item_markup_1					= ti.item_markup_1,
				@item_markup_2					= ti.item_markup_2,
				@CreditQuotaQtyMaximum			= ti.CreditQuotaQtyMaximum,
				@bitFatherInPublication			= 'True',

				@coslis_id						= ti.coslis_id,
				@curr_idCost					= ti.curr_idCost,
				@coslis_price					= ti.pubd_cost,

				@prli_idInCash					= ti.prli_idInCash,
				@prli_priceInCash				= ti.pubd_priceInCash,
				@curr_idInCash					= ti.curr_idInCash,

				@prli_id4Loan					= ti.prli_id4Loan,
				@prli_price4Loan				= ti.pubd_price4Loan,
				@curr_id4Loan					= ti.curr_id4Loan

				FROM tbItemPublicationDetail			ti	WITH (NOLOCK)
				WHERE	ti.comp_id					= @comp_id AND
						ti.pubh_id					= @pubh_id AND
						--ti.pubd_id					= @pubd_id AND
						item_id						= @item_Id2Search

			-- Si no los encuentra busca los del articulo Padre
			IF @bitFatherInPublication = 'False'
				BEGIN

					SELECT
						@creditI_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditI_up2Pays ELSE ISNULL(tb.creditI_up2Pays,0) END,
						--@creditI_up2Pays				= ti.creditI_up2Pays,
						@creditI_creditInterest			= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditI_creditInterest ELSE ISNULL(tb.creditI_creditInterest,0) END,
						--@creditI_creditInterest			= ti.creditI_creditInterest,

						@creditII_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditI_up2Pays ELSE ISNULL(tb.creditII_up2Pays,0) END,
						--@creditII_up2Pays				= ti.creditII_up2Pays,
						@creditII_creditInterest		= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditII_creditInterest ELSE ISNULL(tb.creditII_creditInterest,0) END,
						--@creditII_creditInterest		= ti.creditII_creditInterest,

						@creditIII_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditI_up2Pays ELSE ISNULL(tb.creditIII_up2Pays,0) END,
						--@creditIII_up2Pays				= ti.creditIII_up2Pays,
						@creditIII_creditInterest		= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditIII_creditInterest ELSE ISNULL(tb.creditIII_creditInterest,0) END,
						--@creditIII_creditInterest		= ti.creditIII_creditInterest,

						@creditIV_up2Pays				= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditI_up2Pays ELSE ISNULL(tb.creditIV_up2Pays,0) END,
						--@creditIV_up2Pays				= ti.creditIV_up2Pays,
						@creditIV_creditInterest		= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.creditIV_creditInterest ELSE ISNULL(tb.creditIV_creditInterest,0) END,
						--@creditIV_creditInterest		= ti.creditIV_creditInterest,

						@item_purOrd_Disc1				= ti.item_purOrd_Disc1,
						@item_purOrd_Disc2				= ti.item_purOrd_Disc2,
						@item_purOrd_Disc3				= ti.item_purOrd_Disc3,
						@item_purOrd_Disc4				= ti.item_purOrd_Disc4,
						@item_purOrd_surcharge1			= ti.item_purOrd_surcharge1,
						@item_purOrd_surcharge2			= ti.item_purOrd_surcharge2,
						@item_purOrd_surcharge3			= ti.item_purOrd_surcharge3,
						@item_purOrd_surcharge4			= ti.item_purOrd_surcharge4,
						@item_markup_1					= ti.item_markup_1,
						@item_markup_2					= ti.item_markup_2,
						@CreditQuotaQtyMaximum			= CASE WHEN ISNULL(ti.creditReplaceInterest,'False') = 'True' THEN ti.CreditQuotaQtyMaximum ELSE ISNULL(tb.CreditQuotaQtyMaximum,0) END
						--ti.CreditQuotaQtyMaximum

						FROM tbItem							ti	WITH (NOLOCK)
						INNER JOIN tbBrand			AS	tb	WITH(NOLOCK)
						ON	tb.comp_id					= ti.comp_id	AND
							tb.brand_id					= ti.brand_id
						WHERE	ti.comp_id				= @comp_id		AND
								ti.item_id				= @item_Id2Search

				END





			UPDATE tbItemPublicationDetail		WITH (ROWLOCK)
			SET
				pubd_cost					= @coslis_price,
				creditI_up2Pays				= @creditI_up2Pays,
				creditI_creditInterest		= @creditI_creditInterest,
				creditII_up2Pays			= @creditII_up2Pays,
				creditII_creditInterest		= @creditII_creditInterest,
				creditIII_up2Pays			= @creditIII_up2Pays,
				creditIII_creditInterest	= @creditIII_creditInterest,
				creditIV_up2Pays			= @creditIV_up2Pays,
				creditIV_creditInterest		= @creditIV_creditInterest,
				item_purOrd_Disc1			= @item_purOrd_Disc1,
				item_purOrd_Disc2			= @item_purOrd_Disc2,
				item_purOrd_Disc3			= @item_purOrd_Disc3,
				item_purOrd_Disc4			= @item_purOrd_Disc4,
				item_purOrd_surcharge1		= @item_purOrd_surcharge1,
				item_purOrd_surcharge2		= @item_purOrd_surcharge2,
				item_purOrd_surcharge3		= @item_purOrd_surcharge3,
				item_purOrd_surcharge4		= @item_purOrd_surcharge4,
				prli_idInCash				= @prli_idInCash,
				item_markup_1				= @item_markup_1,
				pubd_priceInCash			= @prli_priceInCash,
				curr_idInCash				= @curr_idInCash,
				prli_id4Loan				= @prli_id4Loan,
				item_markup_2				= @item_markup_2,
				pubd_price4Loan				= @prli_price4Loan,
				curr_id4Loan				= @curr_id4Loan,
				coslis_id					= @coslis_id,
				curr_idCost					= @curr_idCost,
				CreditQuotaQtyMaximum		= @CreditQuotaQtyMaximum,
				pubd_isItemUpdated			= 'False'

			WHERE	comp_id					= @comp_id AND
					pubh_id					= @pubh_id AND
					pubd_id					= @pubd_id AND
					item_id					= @item_id


		END


	IF @bitIsChild = 'True' AND @pubd_isItemUpdated = 'True'
		BEGIN
			UPDATE tbItemPublicationDetail	WITH (ROWLOCK)
				SET		pubd_isItemUpdated			= 'False'
				WHERE	comp_id					= @comp_id AND
						pubh_id					= @pubh_id AND
						pubd_id					= @pubd_id AND
						item_id					= @item_id
		END


	-- --------------------------------------------------------------
	-- Esto tambien va en el Otro Trigger de esta tabla, al final !!!
	-- --------------------------------------------------------------
	IF EXISTS(
				SELECT TOP 1  1
					FROM vwItemPublicationHeader viph		WITH (NOLOCK)
					WHERE	viph.comp_id = @comp_id AND
							viph.pubh_id = @pubh_id
				)
		BEGIN
			EXEC spItemPublicationActiveItems @comp_id
		END
	-- --------------------------------------------------------------


END
GO



