CREATE TRIGGER trItemSerials
   ON  tbItemSerials
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id AS INT
	DECLARE @is_id	 AS int
	SELECT @comp_id = comp_id,
		   @is_id   = is_id
		FROM INSERTED

	UPDATE tbItemSerials
		SET	is_cd = GETDATE()
		WHERE	comp_id = @comp_id
			AND is_id	= @is_id

END
GO








CREATE TRIGGER [dbo].[trItemSizeColorRelation]
   ON  [dbo].[tbItemSizeColorRelation]
   AFTER  INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON

	DECLARE @lComp_id					INT,
			@lItem_id					INT,
			@lItem_id_child				INT,
			@lIscr_Coeficient4Price		DECIMAL(19,4),
			@liscr_Enabled				BIT

	/*
    SELECT	@lComp_id					= 1,
			@lItem_id					= 228,
			@lItem_id_child				= 342,
			@lIscr_Coeficient4Price		= 10
	*/

	-- recuperamos los valores insertados o modificados en la tabla [tbItemSizeColorRelation]
    SELECT	@lComp_id					= comp_id,
			@lItem_id					= item_id,
			@lItem_id_child				= item_id_child,
			@lIscr_Coeficient4Price		= ISNULL(iscr_Coeficient4Price,0),
			@liscr_Enabled				= iscr_Enabled
	FROM INSERTED


	-- Si un coeficiente esta en 0 NO debe estar habilitado.-
	IF @liscr_Enabled = 'True' and @lIscr_Coeficient4Price = 0
		BEGIN
			UPDATE tbItemSizeColorRelation
				SET	iscr_Enabled		= 'False'
				WHERE	comp_id			= @lComp_id AND
						item_id_child	= @lItem_id_child
			SET @liscr_Enabled			= 'False'
			SET @lIscr_Coeficient4Price = 0
		END




	-- ------------------------------------------------------------------------------------------------------
	-- Calculamos los precios de todos los hijos pqrq cada lista en la que el padre tenga un precio cargado!
	-- ------------------------------------------------------------------------------------------------------

	--si se obtuvo un item_id hijo válido, procesamos
	IF NOT @lItem_id_child IS NULL
		BEGIN

    		DECLARE @lprli_id			INT,
    				@lprli_price		DECIMAL(19,5),
    				@lcurr_id			INT,
    				@lbra_id			INT

    		--declaración de cursor para recuperar las listas de precios del item padre
    		DECLARE cursor_childs4trItemSizeColorRelation CURSOR FAST_FORWARD FOR
    			SELECT	tpli.prli_id,
    					tpli.prli_price,
    					tpli.curr_id,
    					tpli.bra_id

    				FROM	tbPriceListItems tpli		WITH (NOLOCK)

    				WHERE	tpli.comp_id = @lComp_id
    				AND		tpli.item_id = @lItem_id


    		OPEN cursor_childs4trItemSizeColorRelation

    		FETCH cursor_childs4trItemSizeColorRelation INTO @lprli_id,	@lprli_price, @lcurr_id, @lbra_id

    		WHILE @@FETCH_STATUS = 0
    		BEGIN

    			--verificación para saber si el registro a procesar ya existe en la lista de precios
    			IF EXISTS (SELECT DISTINCT 1
    						   FROM tbPriceListItems tpli
    						   WHERE tpli.comp_id = @lComp_id
    							AND tpli.prli_id = @lPrli_id
    							AND tpli.item_id = @litem_id_child)
    				BEGIN

						--si ya existe se ejecuta un update del item hijo aplicando el coeficiente
						--multiplicado por la el precio de venta del padre
						UPDATE tbPriceListItems

						SET		prli_price	= @lPrli_price * @liscr_Coeficient4Price,
								curr_id		= @lCurr_id,
								bra_id		= @lBra_id

						WHERE	comp_id		= @lComp_id
						AND		item_id		= @litem_id_child
						AND		prli_id		= @lPrli_id

    				END
    			ELSE
    				BEGIN

						--si no existe se ejecuta un insert del item hijo aplicando el coeficiente
						--multiplicado por la el precio de venta del padre
						INSERT INTO tbPriceListItems
							(		comp_id,
									prli_id,
									item_id,
									prli_price,
									curr_id,
									bra_id,
									prli_cd		)
						VALUES
    						(		@lComp_id,
    								@lPrli_id,
    								@litem_id_child,
    								@lPrli_price * @liscr_Coeficient4Price,
    								@lCurr_id,
    								@lBra_id,
    								GETDATE())

    				END


    			FETCH cursor_childs4trItemSizeColorRelation INTO @lprli_id,	@lprli_price, @lcurr_id, @lBra_id

    		END

    		CLOSE cursor_childs4trItemSizeColorRelation
    		DEALLOCATE cursor_childs4trItemSizeColorRelation


		END
	-- ------------------------------------------------------------------------------------------------------


END






GO




