		--	WHERE tit.comp_id = @comp_id


		-- Esto es para alguna mierda de auditoria por algun FORRO de mierda que alucinaba que algo estaba mal
		-- La re concha de su madre !!!
		--INSERT INTO tbItemStorageUpdates	WITH (ROWLOCK)
		--(
		--	comp_id,
		--	-- itsa_id -- this column value is auto-generated,
		--	item_id,
		--	stor_id,
		--	itsa_storePrevious,
		--	itsa_cd,
		--	it_transaction,
		--	itsa_actualQty
		--)
		--VALUES
		--(
		--	@comp_id,
		--	@item_id,
		--	@stor_id,
		--	@qty,
		--	GETDATE(),
		--	@it_transaction,
		--	@actualQty
		--)



	-- Verifica si el articulo NO descuenta stock y de ser asi pone en CERO su stock asociado
	IF @stor_id IS NOT NULL AND @item_id IS NOT NULL
		BEGIN

			IF EXISTS(	SELECT TOP 1 1
	          				FROM tbItem ti	WITH (NOLOCK)
	          				WHERE	ti.comp_id				= @comp_id AND
	          						ti.item_id				= @item_id AND
	          						ti.item_NoStockCheck	= 'True')
				BEGIN

					IF EXISTS(	SELECT TOP 1 1
					          		FROM tbStorage ts	WITH (NOLOCK)
					          		WHERE	ts.comp_id				= @comp_id AND
					          				ts.stor_id				= @stor_id AND
											ts.stor_NoStockCheck	= 'True')
						BEGIN


							IF EXISTS(	SELECT TOP 1  1
						          		FROM tbCompany ti	WITH (NOLOCK)
	          								WHERE	ti.comp_id				= @comp_id AND
	          										ti.comp_NoStockCheck	= 'True')
								BEGIN
									UPDATE tbItemStorage	WITH (ROWLOCK)
										SET		itst_cant	= 0
										WHERE	comp_id		= @comp_id AND
												stor_id		= @stor_id AND
												item_id		= @item_id
								END
						END
				END
		END


		--EXEC spWebServices_ItemUpdateHistory @comp_id,@item_id


		-- NO, hacerlo ante la solicitud al ws !!! EXEC spTableLastUpdate_updateData @comp_id, 596,@item_id,NULL,@stor_id,null



	END TRY
	BEGIN CATCH
	END CATCH


	-- --------------------------------------
	-- Para el PUTO sp de FullJaus y LRPMQLP
	-- Si se ve que molesta, sacarlo y que se caguen
	-- --------------------------------------
	BEGIN TRY
		INSERT INTO tbItemsUpdated(item_id) VALUES (@item_id)
	END TRY
	BEGIN CATCH
	END CATCH
	-- --------------------------------------




END
GO




-- =============================================
-- Si se insewrta algo se deshabilkita al deposito
-- para totalizar stock
-- =============================================
CREATE TRIGGER [dbo].[trItemTransactions]
   ON [dbo].[tbItemTransactions]
   AFTER  INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;


	-- Si se ingresa algun mov de deposito se debe des-habilitar al mismo para ser totalizador de transferencias
	DECLARE @comp_id		AS INT
	DECLARE @stor_id		AS INT
	DECLARE @item_id		AS INT
	DECLARE @it_transaction AS INT

	SELECT	@comp_id		= tmp.comp_id,
			@stor_id		= tmp.stor_id,
			@item_id		= tmp.item_id,
			@it_transaction = tmp.it_transaction
		FROM INSERTED	tmp



	-- Si se ingresa algun mov de deposito se debe des-habilitar al mismo para ser totalizador de transferencias
	IF @stor_id IS NOT NULL
		BEGIN

			-- MOS: 12-2019.  Si se hace un mov en un deposito de totales de transferencias NO se desactiva mas el depósito
			--                y se marca el movimiento como que NO descontó stock y fue por un error de hacer un mov de stock en un deposito de totales de transferencias pendientes de recibir.
			IF EXISTS(	SELECT TOP 1 1
							FROM tbStorage ts	WITH (NOLOCK)
							WHERE	ts.comp_id									= @comp_id AND
					          		ts.stor_id									= @stor_id AND
									ts.stor_isAvailable4BranchTransferTotalizer	= 'True'
					)
				BEGIN
					UPDATE tbItemTransactions		WITH (ROWLOCK)
						SET	it_NoStockCheck							= 'True',
							it_isInBranchTransferTotalizerStorage	= 'True'
						WHERE	comp_id			= @comp_id AND
								it_transaction	= @it_transaction
				END


			--UPDATE tbstorage	WITH (ROWLOCK)
			--	SET stor_isAvailable4BranchTransferTotalizer = 0
			--WHERE 	comp_id = @comp_id AND
			--		stor_id = @stor_id AND
			--		stor_isAvailable4BranchTransferTotalizer = 1

		END





	-- Verifica si el articulo NO descuenta stock y de ser asi pone en CERO su stock asociado
	IF @stor_id IS NOT NULL AND @item_id IS NOT NULL
		BEGIN

			IF EXISTS(	SELECT TOP 1 1
	          				FROM tbItem ti	WITH (NOLOCK)
	          				WHERE	ti.comp_id				= @comp_id AND
	          						ti.item_id				= @item_id AND
	          						ti.item_NoStockCheck	= 'True')
				BEGIN

					IF EXISTS(	SELECT TOP 1 1
					          		FROM tbStorage ts	WITH (NOLOCK)
					          		WHERE	ts.comp_id				= @comp_id AND
					          				ts.stor_id				= @stor_id AND
											ts.stor_NoStockCheck	= 'True')
						BEGIN

							IF EXISTS(	SELECT TOP 1 1
						          		FROM tbCompany ti	WITH (NOLOCK)
	          								WHERE	ti.comp_id				= @comp_id AND
	          										ti.comp_NoStockCheck	= 'True')
								BEGIN

									-- Lo hace ademas en trigger de tbItemStorage
									UPDATE tbItemStorage		WITH (ROWLOCK)
										SET		itst_cant	= 0
										WHERE	comp_id		= @comp_id AND
												stor_id		= @stor_id AND
												item_id		= @item_id

									UPDATE tbItemTransactions		WITH (ROWLOCK)
										SET	it_NoStockCheck		= 'True'
										WHERE	comp_id			= @comp_id AND
												it_transaction	= @it_transaction
								END
						END
				END
		END


END
GO




-- =============================================
-- Por cada it_transaction guarda la foto del
-- Stock que tenia para ese articulo en los
-- depositos que tiene habilitados
-- =============================================
CREATE TRIGGER [dbo].[trItemTransactions2]
   ON [dbo].[tbItemTransactions]
   AFTER  INSERT
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id		AS INT
	DECLARE @it_transaction AS INT
	DECLARE @item_id		AS INT
	DECLARE @stor_id		AS INT

	SELECT
			@comp_id			= comp_id,
			@it_transaction		= it_transaction,
			@item_id			= item_id,
			@stor_id			= stor_id
		FROM INSERTED

	INSERT INTO tbItemStoragePhoto	WITH (ROWLOCK)
	(
		comp_id,
		it_transaction,
		stor_id,
		itstp_cant
	)
		SELECT	tis.comp_id,
				@it_transaction,
				tis.stor_id,
				tis.itst_cant
			FROM tbItemStorage tis			WITH (NOLOCK)
			INNER JOIN tbStorage ts			WITH (NOLOCK)
				ON	ts.comp_id = tis.comp_id AND
					ts.stor_id = tis.stor_id
			WHERE	tis.comp_id							= @comp_id AND
					tis.item_id							= @item_id AND
					ts.stor_savePhotoOnITTransaction	= 'True'   AND
					tis.itst_cant <> 0  -- MOS 12-2019 x Auth

END
GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	controla que el recibo sea el correcto
-- =============================================
create TRIGGER [dbo].[trMercadoLibre_Stores]
   ON  [dbo].[tbMercadoLibre_Stores]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here


	-- ------------------------------------------------------------------------------------
	-- Si son actualizaciones de estos codigos que llegan directo desde ML no da error
	-- Declaracion de variables, ver mas abajo esto !
	-- ------------------------------------------------------------------------------------
	DECLARE @bitIsFromML AS BIT = 'False'
	DECLARE @mls_ServerGeneratedAuthorizationCodeOLD AS NVARCHAR(200)
	DECLARE @mls_ServerGeneratedAuthorizationCodeNEW AS NVARCHAR(200)
	DECLARE @mls_accessTokenOLD						 AS NVARCHAR(200)
	DECLARE @mls_accessTokenNEW						 AS NVARCHAR(200)
	DECLARE @mls_forcePublicationStatus2PausedOLD	 AS BIT
	DECLARE @mls_forcePublicationStatus2PausedNEW    AS BIT
	DECLARE @curr_id								 AS INT
	DECLARE @prli_id4secondUpdate					 AS INT
	DECLARE @prli_id								 AS INT
	-- ------------------------------------------------------------------------------------


	DECLARE @intStoreIdOld AS INT = NULL
	SELECT  @intStoreIdOld							 = mls_id,
			@mls_ServerGeneratedAuthorizationCodeOLD = mls_ServerGeneratedAuthorizationCode,
			@mls_accessTokenOLD						 = mls_accessToken,
			@mls_forcePublicationStatus2PausedOLD    = ISNULL(mls_forcePublicationStatus2Paused,'False'),
			@curr_id								 = curr_id
		FROM DELETED






	DECLARE @intCompID	AS INT
	DECLARE @intBraID	AS INT
	DECLARE @intDFId	AS INT
	DECLARE @MLUserID	AS INT
	DECLARE @intUserID  AS INT
	DECLARE @intST_Id	AS INT
	DECLARE @cust_id_4newCustomersA AS INT
	DECLARE @cust_id_4newCustomersB AS INT
	DECLARE @mls_id		AS INT
	DECLARE @item_id4UserPayDelivery AS INT
	DECLARE @cc_id4UserPayDelivery   AS INT
	SELECT
			@intCompID	= comp_id,
			@mls_id		= mls_id,
			@intBraID	= bra_id,
			@intDFId	= df_id4MPCollection,
			@MLUserID	= MLUser_Id,
			@intUserID  = [user_id],
			@intST_Id	= st_id,
			@cust_id_4newCustomersA					 = cust_id_4newCustomersA,
			@cust_id_4newCustomersB					 = cust_id_4newCustomersB,
			@mls_ServerGeneratedAuthorizationCodeNEW = mls_ServerGeneratedAuthorizationCode,
			@mls_accessTokenNEW						 = mls_accessToken,
			@item_id4UserPayDelivery				 = item_id4UserPayDelivery,
			@cc_id4UserPayDelivery					 = cc_id4UserPayDelivery,
			@mls_forcePublicationStatus2PausedNEW    = ISNULL(mls_forcePublicationStatus2Paused,'False'),
			@prli_id4secondUpdate					 = ISNULL(prli_id4secondUpdate,-1),
			@prli_id								 = ISNULL(prli_id,-1)
		FROM INSERTED


	IF @curr_id IS NULL	-- Si es un ALTA, RETURN  MOS 09-06-2019
		BEGIN
			DECLARE @strExec AS NVARCHAR(MAX)
			SET @strExec =
					'	UPDATE tbmercadolibre_stores
							SET		mls_updatePublicationAttributesFromML = 1
			      			WHERE	comp_id = ' + CONVERT(NVARCHAR(10),@intCompID) + ' AND
			      					mls_id  = ' + CONVERT(NVARCHAR(10),@mls_id)
			EXEC(@strExec)
			RETURN
		END


	IF @mls_id IS NULL
		BEGIN
			RETURN
		END


	IF	( @item_id4UserPayDelivery	IS NULL AND @cc_id4UserPayDelivery IS NOT NULL )
			OR
		( @cc_id4UserPayDelivery 	IS NULL AND @item_id4UserPayDelivery IS NOT NULL )
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b> Si se selecciona un Artículo para Gastos de Envío o una Tarjeta de Crédito en la solapa MercadoEnvios se debe verificar que los DOS tengan una selección válida. <br/>   POR FAVOR LEER DETENIDAMENTE LAS AYUDAS ! ! !');
		END


	IF	@prli_id4secondUpdate = @prli_id AND @prli_id4secondUpdate IS NOT NULL
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b> La lista de Precios y la Lista de Precios ADICIONAL configurada en la solapa de Actualizaciones Bidireccionales NO PUEDE SER LA MISMA ! ! !');
		END





	-- ------------------------------------------------------------------------------------
	-- Si son actualizaciones de estos codigos que llegan directo desde ML no da error
	-- ------------------------------------------------------------------------------------
	IF (ISNULL(@mls_ServerGeneratedAuthorizationCodeOLD,'') <> ISNULL(@mls_ServerGeneratedAuthorizationCodeNEW,''))
		OR
	   (ISNULL(@mls_accessTokenOLD,'') <> ISNULL(@mls_accessTokenNEW,''))
		BEGIN
			SET @bitIsFromML = 'True'
		END

	IF @bitIsFromML = 'True' -- asi x si se agregan mas adelanto cosas raras
		BEGIN
			RETURN
		END
	-- ------------------------------------------------------------------------------------


	-- ------------------------------------------------------------------------------------
	-- Para poder editar  una tienda o MeLi o Bot de Pago deben estar adquiridos.
	-- ------------------------------------------------------------------------------------
	IF 	(
			SELECT dbo.clrGetAM(tc.comp_id,66, tc.comp_am , CONVERT(NVARCHAR(50), tc.comp_guid))
			FROM tbCompany tc
			WHERE tc.comp_id = @intCompID
		) = 0
		AND
		(
			SELECT dbo.clrGetAM(tc.comp_id,65, tc.comp_am , CONVERT(NVARCHAR(50), tc.comp_guid))
			FROM tbCompany tc
			WHERE tc.comp_id = @intCompID
		) = 0
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b> El Módulo de MercadoLibre© o Botones de Pago NO han sido adquirido, consulte con su distribuidor.');
		END
	-- ------------------------------------------------------------------------------------

	DECLARE @intBraIDOfReceipt	AS INT
	DECLARE @intSD_ID			AS INT
	SELECT	@intBraIDOfReceipt	= tdf.bra_id,
			@intSD_ID			= tdf.sd_id
		FROM tbDocumentsFile tdf
		WHERE	tdf.comp_id = @intCompID AND
				tdf.df_id	= @intDFId


	IF @intBraID <> @intBraIDOfReceipt OR @intSD_ID <> 6
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b>El Documento seleccionado NO es un Recibo Automático o NO pertenece a la sucursal configurada para esta tienda.');
		END


	IF not (@MLUserID > 0)
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b>NO se ha ingresado un ID de Usuario de MercadoLibre.');
		END


	IF NOT EXISTS(	SELECT 1
	              		FROM tbCashNumber4Branch4User tcnbu		WITH (NOLOCK)
	              		WHERE	tcnbu.comp_id	= @intCompID AND
	              				tcnbu.bra_id	= @intBraID AND
	              				tcnbu.[user_id] = @intUserID)
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b> El Usuario del sistema asociado a la tienda NO tiene una caja relacionada en la sucursal asociada a la tienda.');
		END




	IF NOT EXISTS(
				SELECT 1
					FROM tbSalesTerms		tst					WITH (NOLOCK)
					INNER JOIN tbCreditCard tcc					WITH (NOLOCK)
					ON		tcc.comp_id = tst.comp_id AND
							tcc.cc_id	= tst.cc_id
					WHERE	tst.comp_id = @intCompID	AND
							tst.st_id	= @intST_Id		AND
							(tcc.bra_id IS NULL OR tcc.bra_id = @intBraID)
				)
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b> La Condición de venta DEBE tener una tarjeta de crédito asociada convenientemente llamada: MERCADOPAGO vía MERCADOLIBRE');
		END


	IF @cust_id_4newCustomersA IS NULL OR @cust_id_4newCustomersB IS NULL
		BEGIN
			RAISERROR (15600,-1,-1,  '| <b>ATENCIÓN:</b> Falta ingresar un Cliente BASE para documentos tipo A o para Documentos tipo B');
		END



	IF @intStoreIdOld IS NULL	-- Si es un ALTA borra los Access Tokens Guardados !
		BEGIN
			UPDATE tbMercadoLibre_Stores
				SET mls_ServerGeneratedAuthorizationCode = '',
					mls_accessToken = '',
					mls_accessTokenValidUp2Date = NULL,
					mls_refresh_Token = ''
				WHERE	comp_id = @intCompID	 AND
						mls_id	= @mls_id

		END



	-- ------------------------------------------------------------------
	-- Si cambió el estado de Forzado a Pausar TODAS las publicaciones
	-- ------------------------------------------------------------------
	IF @mls_forcePublicationStatus2PausedOLD <> @mls_forcePublicationStatus2PausedNEW
		BEGIN
			IF @mls_forcePublicationStatus2PausedNEW = 'True'
				BEGIN
					UPDATE tbMercadoLibre_ItemsPublicados			WITH (ROWLOCK)
						SET mlp_lastStatusID = optval_statusId
						WHERE	comp_id = @intCompID AND
								mls_id	= @mls_id
					UPDATE tbMercadoLibre_ItemsPublicados			WITH (ROWLOCK)
						SET optval_statusId = 6
						WHERE	comp_id = @intCompID AND
								mls_id	= @mls_id
				END
			ELSE
				BEGIN
					UPDATE tbMercadoLibre_ItemsPublicados			WITH (ROWLOCK)
						SET optval_statusId =	CASE
													WHEN mlp_lastStatusID IS NOT NULL THEN mlp_lastStatusID
													ELSE optval_statusId
												END
						WHERE	comp_id			= @intCompID AND
								mls_id			= @mls_id	 AND
								optval_statusId = 6
				END
		END
	-- ------------------------------------------------------------------


	-- ------------------------------------------------------------------
	-- Pone en el sistema de GBP el ID de tienda para que funcione
	-- el PUTO Middleware que pidieron los nabos de Meli para que ellos
	-- puedan tener sus re putas estadisticas metiendo MIERDA en el
	-- medio al PEDO.
	-- ------------------------------------------------------------------
	BEGIN TRY
		EXEC spMercadoLibre_GBPMeLiID4url_InsertData2WS
	END TRY
	BEGIN CATCH
	END CATCH
	-- ------------------------------------------------------------------



END
GO



-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER trPriceList
   ON  tbPriceList
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	DECLARE @comp_id				AS INT
	DECLARE @prli_id				AS INT
	DECLARE @prli_disabled			AS BIT
	DECLARE @prli_disabledConfirm	AS BIT

	SELECT	@comp_id = comp_id,
			@prli_id = prli_id,
			@prli_disabled			= ISNULL(prli_disabled,'False'),
			@prli_disabledConfirm	= ISNULL(prli_disabledConfirm,'False')
		FROM INSERTED


	-- Solo la marca como deshabilitada si los dos checks estan en TRUE
	IF NOT (@prli_disabled = 'True' AND @prli_disabledConfirm = 'True')
		BEGIN
			UPDATE tbPriceList
			SET	prli_disabled			= 'False',
				prli_disabledConfirm	= 'False'
			WHERE	comp_id = @comp_id AND
					prli_id = @prli_id
		END


END
GO



CREATE TRIGGER [dbo].[trPriceListItems]
   ON  [dbo].[tbPriceListItems]
   AFTER  INSERT,UPDATE
AS


BEGIN

	SET NOCOUNT ON

	-- -------------------------------------------------------------------------------------------------------------------------
	-- Sirve para detectar Triggers Anidados ya que solo va a variar si es que es una actualizacion generada desde un trigger.!
	-- -------------------------------------------------------------------------------------------------------------------------
	DECLARE @intLevel AS INT
	SET		@intLevel = @@NESTLEVEL
	-- -------------------------------------------------------------------------------------------------------------------------



	DECLARE @lComp_id					INT,
			@lBra_id					INT,
			@lPrli_id					INT,
			@lItem_id					INT,
			@lCurr_id					INT,
			@lPrli_price				DECIMAL(29,5),
			@bitDisabled4Rules			AS BIT,
			@prli_lastModuleUpdate      AS INT = 0,
			@user_id				    AS INT = NULL,
			@prli_lastRuleUpdate		AS DATETIME

	-- ----------------------------------------------------------
	-- Testing
	-- -- -------------------------------------------------------
	/*
    SELECT	@lComp_id					= 1,
			@lBra_id					= 1,
			@lPrli_id					= 1,
			@lItem_id					= 228,
			@lCurr_id					= 1,
			@lPrli_price				= 80
	*/
	-- ---------------------------------------------------------

	-- recuperamos los valores insertados o modificados en la tabla [tbPriceListItems]
    SELECT	@lComp_id					= comp_id,
			@lBra_id					= bra_id,
			@lPrli_id					= prli_id,
			@lItem_id					= item_id,
			@lCurr_id					= curr_id,
			@lPrli_price				= prli_price,
			@bitDisabled4Rules			= prli_disabled4Rules,
			@prli_lastModuleUpdate		= prli_lastModuleUpdate,
			@user_id					= user_id_lastUpdate,
			@prli_lastRuleUpdate		= prli_lastRuleUpdate
		FROM INSERTED


	-- ------------------------------------------------
	-- Si la actualizacion por ejemplo de Edicion Conf de Precios NO actualizó nada igual se dispara el trigger con NULL en todos lkos valores de Inserted ya que NO actualizó en realidad ningun registro.
	-- Esto pasa por ejemplo haciendo un Update por comp, item, y ademas en el where comparando si un valor adicional varió.  Si NO se actualiza ningun rtegistro se dispara un trigger con NULL en INSERTED.
	-- ------------------------------------------------
	IF @lComp_id IS NULL
		BEGIN
			RETURN
		END

	IF @prli_lastModuleUpdate = 90 SET @intLevel = 0	-- MOS 05-2023: **fejnwe9875654po x MR y LPMQLP a GT, los forros quieren que al cambiar DESDE el abm tambien se ejecute, no solo x cambio dese la BD.  LRCDTPM!!!!!!!!!	como desde el erp el nivel es mayor ( concurrencia ) no se ejecutaba a proposito.
	-- ------------------------------------------------



	DECLARE @decLastPrice  AS DECIMAL(19,5)
	DECLARE @intLastCurrId AS INT
	SET		@decLastPrice	= 0
	SET		@intLastCurrId	= -1
	SELECT	@decLastPrice	= prli_price,
			@intLastCurrId	= curr_id
		FROM DELETED


	-- -------------------------------------------------------------------------------------
	-- ATENCIÓN:
	-- Esto se pone para que SI o SI saque el disabled4Rules por mas que salte algun error.
	-- -------------------------------------------------------------------------------------
	BEGIN TRY




			-- -----------------------------------------------------------
			-- POner que no distare Trigger otra vez
			-- Grabar la moneda y Precio Nateriores
			-- -----------------------------------------------------------

			IF @intLastCurrId <> -1
				BEGIN


					IF @decLastPrice <> @lPrli_price OR @intLastCurrId <> @lCurr_id
						BEGIN
							UPDATE tbPriceListItems
								SET
									prli_price_PreLastUpdate	= @decLastPrice,
									curr_id_PreLastUpdate		= @intLastCurrId,
									prli_triggerUpdateCD		= GETDATE(),
									prli_updatedAt				= GETDATE(),
									prli_lastRuleUpdate			= NULL
								WHERE	comp_id = @lComp_id AND
										prli_id = @lPrli_id AND
										item_id = @lItem_id
						END
				END
			-- -----------------------------------------------------------





			-- -----------------------------------------------------------
			-- Actualiza Precios de Padres de COMBOS
			-- -----------------------------------------------------------
			IF @prli_lastModuleUpdate	<> 30   -- Si NO viene del MISMO
				BEGIN
					EXEC spCostlistActualizationRules_SetComboPrices @lComp_id,
																	 @lPrli_id,
																	 @lItem_id,
																	 @lBra_id
				END
			-- -----------------------------------------------------------




		-- MOS 01-2020, estaba al FINAL despues de las reglas y lo pase aca ya que el proximo if con el level
		-- si cambaiba un precio x carga manual en bed collection
		-- daba nivel 4 y salia








			-- -----------------------------------------------------------
			-- Graba el Historial
			-- -----------------------------------------------------------
			IF 	@decLastPrice	IS NULL			OR
				@decLastPrice <> @lPrli_price	OR
				@intLastCurrId IS NULL			OR
				@intLastCurrId <> @lCurr_id
				BEGIN

					INSERT INTO tbPriceListHistory
							(
								comp_id,
								prli_id,
								item_id,
								plh_lote,
								plh_price,
								curr_id,
								plh_cd,
								user_id_lastUpdate,
								plh_ruleUpdate
							)
							SELECT
								@lComp_id ,
								@lPrli_id,
								@lItem_id,
								0,
								@lPrli_price,
								@lCurr_id,
								GETDATE(),
								@user_id,
								CASE
									WHEN @prli_lastRuleUpdate IS NOT NULL  THEN 1
									ELSE								        0
								END

					-- Graba el historial para los forros de DS q no se para que MIERDA lo quieren
					IF DB_NAME() LIKE '%_TIU' AND @lcomp_id IS NOT NULL
						BEGIN
							DELETE FROM tbWebServices_ItemUpdateHistory	WITH (ROWLOCK)
								WHERE	comp_id = @lcomp_id AND
										item_id = @litem_id

							INSERT INTO tbWebServices_ItemUpdateHistory(comp_id, item_id, wsh_cd)
							VALUES(@lcomp_id, @litem_id, GETDATE())
						END
				END
			-- -----------------------------------------------------------


			-- -----------------------------------------------------------
			-- Recalcula MarkUps de Articulos si es que esta definido
			-- -----------------------------------------------------------
			IF	NOT
				(
					@prli_lastModuleUpdate	= 10		-- Edicion Configurable de Precios
						OR
					@prli_lastModuleUpdate	= 20		-- Reglas de Actualización
				)
				BEGIN
					-- @lCurr_id
					-- @lPrli_price
					-- @lItem_id
					DECLARE @decCost			AS DECIMAL(35,15)
					DECLARE @decCostAW			AS DECIMAL(35,15)
					DECLARE @intCurrIDCost		AS INT
					DECLARE @intItemMarkUp		AS INT
					DECLARE @intCosLis_ID		AS INT
					DECLARE @plmr_fromAW		AS BIT
					DECLARE @plmr_disableDiscountAndSurcharge4Cost AS BIT
					DECLARE @decMarkUp			AS DECIMAL(35,15)
					DECLARE @decFinalCost		AS DECIMAL(35,15)
					DECLARE @decDiscount1		AS DECIMAL(35,15)	= NULL
					DECLARE @decDiscount2		AS DECIMAL(35,15)
					DECLARE @decDiscount3		AS DECIMAL(35,15)
					DECLARE @decDiscount4		AS DECIMAL(35,15)
					DECLARE @decSurcharge1		AS DECIMAL(35,15)
					DECLARE @decSurcharge2		AS DECIMAL(35,15)
					DECLARE @decSurcharge3		AS DECIMAL(35,15)
					DECLARE @decSurcharge4		AS DECIMAL(35,15)





					DECLARE curPriceList4MarkUpRecalculation CURSOR LOCAL FAST_FORWARD FOR
						SELECT	tl.item_markup,
								tl.coslis_id,
								tl.plmr_fromAW,
								tl.plmr_disableDiscountAndSurcharge4Cost
							FROM tbPriceList4MarkUpRecalculation	tl		WITH (NOLOCK)
							WHERE	tl.comp_id		= @lComp_id AND
									tl.prli_id		= @lPrli_id AND
									tl.isDisabled	= 'False'


					OPEN		curPriceList4MarkUpRecalculation

					FETCH NEXT FROM curPriceList4MarkUpRecalculation
						INTO	@intItemMarkUp,
								@intCosLis_ID,
								@plmr_fromAW,
								@plmr_disableDiscountAndSurcharge4Cost

					WHILE @@FETCH_STATUS = 0
						BEGIN


							IF @decDiscount1 IS NULL  -- Para optimizar y que lo cargue solo una vez
								BEGIN
									SELECT	@decDiscount1 = ISNULL(item_purOrd_Disc1,0),
											@decDiscount2 = ISNULL(item_purOrd_Disc2,0),
											@decDiscount3 = ISNULL(item_purOrd_Disc3,0),
											@decDiscount4 = ISNULL(item_purOrd_Disc4,0),
											@decSurcharge1= ISNULL(item_purOrd_surcharge1,0),
											@decSurcharge2= ISNULL(item_purOrd_surcharge2,0),
											@decSurcharge3= ISNULL(item_purOrd_surcharge3,0),
											@decSurcharge4= ISNULL(item_purOrd_surcharge4,0)
										FROM tbitem		WITH (NOLOCK)
										WHERE	comp_id = @lComp_id AND
												item_id = @lItem_id
								END



							SELECT	@decCost		= ISNULL(ticl.coslis_price,0),
									@decCostAW		= ISNULL(ticl.coslis_price_aw,0),
									@intCurrIDCost	= ISNULL(ticl.curr_id,-1)
								FROM tbItemCostList ticl WITH (NOLOCK)
								WHERE	ticl.comp_id	= @lComp_id		AND
										ticl.coslis_id	= @intCosLis_ID AND
										ticl.item_id	= @lItem_id


							-- VErifica si PUEDE hacerlo
							IF @intItemMarkUp BETWEEN 1 AND 16
								BEGIN
									IF @intCurrIDCost > 0 AND
										( (@plmr_fromAW = 'False' AND @decCost > 0) OR (@plmr_fromAW = 'True' AND @decCostAW > 0) )	AND
										@lPrli_price > 0
										BEGIN

											SELECT @decFinalCost = dbo.fnNoZDiv(CASE
																					WHEN @plmr_fromAW = 'True' THEN  @decCostAW
																					ELSE							 @decCost
																				END)
											IF @plmr_disableDiscountAndSurcharge4Cost = 'False'
												BEGIN
													SELECT @decFinalCost = @decFinalCost * dbo.fnGetFinalDiscountCoeficient(@decDiscount1,@decDiscount2,@decDiscount3,@decDiscount4)
													SELECT @decFinalCost = @decFinalCost * dbo.fnGetFinalDiscountCoeficient(-@decSurcharge1,-@decSurcharge2,-@decSurcharge3,-@decSurcharge4)
												END

											SELECT @decMarkUp =	(
																	(
																		dbo.fnGetExchange2(@lComp_id,@lPrli_price,@lCurr_id,@intCurrIDCost,0,0,0,'False')
																		/
																		@decFinalCost
																	) - 1
																) * 100


											IF @intItemMarkUp = 1
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_1 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 2
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_2 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 3
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_3 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 4
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_4 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 5
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_5 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 6
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_6 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 7
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_7 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 8
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_8 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 9
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_9 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 10
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_10 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 11
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_11 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 12
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_12 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 13
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_13 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 14
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_14 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 15
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_15 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

											IF @intItemMarkUp = 16
												BEGIN
													UPDATE tbitem	WITH (ROWLOCK)
														SET item_markup_16 = @decMarkUp
														WHERE	comp_id = @lComp_id AND
																item_id = @lItem_id
												END

										END
								END


							FETCH NEXT FROM curPriceList4MarkUpRecalculation
								INTO	@intItemMarkUp,
										@intCosLis_ID,
										@plmr_fromAW,
										@plmr_disableDiscountAndSurcharge4Cost
						END


					CLOSE		curPriceList4MarkUpRecalculation
					DEALLOCATE	curPriceList4MarkUpRecalculation

				END
			-- -----------------------------------------------------------



		-- MOS 01-2020





			-- -------------------------------------------------------------------------------------------------------------------------
			-- es por mierdas de Authogar con Triggers de Padres, Hijos y LPM
			-- Sirve para detectar Triggers Anidados ya que solo va a variar si es que es una actualizacion generada desde un trigger.!
			-- -------------------------------------------------------------------------------------------------------------------------
			IF /*@@NESTLEVEL*/ @intLevel > 2    -- Si lo ejecuta el sistema es 2, Si se hace del SQL es 3,,, HDPPPPPPPP
			BEGIN
				-- -----------------------------------------------------------
				-- Saca Bloqueo de Ejecucion de Reglas de Actualizacion
				-- -----------------------------------------------------------
				IF EXISTS(	SELECT TOP 1  1
								FROM tbPriceListItems tpli	WITH (NOLOCK)
								WHERE	tpli.comp_id		= @lComp_id AND
										tpli.prli_id		= @lPrli_id AND
										tpli.item_id		= @lItem_id	AND
										tpli.prli_disabled4Rules = 'True'
						)
					BEGIN
						UPDATE tbPriceListItems
							SET	prli_disabled4Rules = 'False'
							WHERE	comp_id		= @lComp_id AND
									prli_id		= @lPrli_id AND
									item_id		= @lItem_id
					END

				-- -----------------------------------------------------------
				RETURN
			END
			-- -------------------------------------------------------------------------------------------------------------------------


			-- -----------------------------------------------------------------------------
			-- si el item actualizado existe en tbItemSizeColorRelation es padre, procesamos
			-- -----------------------------------------------------------------------------
			IF EXISTS (SELECT TOP 1 1--DISTINCT 1  MOS 06-2020
						FROM	tbItemSizeColorRelation tiscr	WITH (NOLOCK)
						WHERE	tiscr.comp_id = @lComp_id
						AND		tiscr.item_id = @lItem_id)
				BEGIN

    				DECLARE @litem_id_child				INT,
    						@liscr_Coeficient4Price		DECIMAL(19,4)

    				--declaración de cursor para recuperar los items hijos y los coeficientes
    				DECLARE cursor_childs4trPriceListItems CURSOR LOCAL FAST_FORWARD FOR
    					SELECT	tiscr.item_id_child,
    							tiscr.iscr_Coeficient4Price

    					FROM	tbPriceListItems						tpli				WITH (NOLOCK)
    							INNER JOIN tbItemSizeColorRelation		tiscr				WITH (NOLOCK)
    							ON	tiscr.comp_id = tpli.comp_id
    							AND tiscr.item_id = tpli.item_id		AND
    								tiscr.item_id_child			IS NOT NULL		AND
    								tiscr.iscr_Coeficient4Price IS NOT NULL

    					WHERE	tpli.comp_id = @lComp_id
    					AND		tpli.item_id = @lItem_id
    					AND		tpli.prli_id = @lPrli_id

    				OPEN cursor_childs4trPriceListItems

    				FETCH cursor_childs4trPriceListItems INTO @litem_id_child, @liscr_Coeficient4Price

    				WHILE @@FETCH_STATUS = 0
    				BEGIN

    					--verificación para saber si el registro a procesar ya existe en la lista de precios
    					IF EXISTS (SELECT TOP 1 1 --DISTINCT 1  MOS 06-2020
    								   FROM tbPriceListItems tpli					WITH (NOLOCK)
    								   WHERE tpli.comp_id  = @lComp_id
    									AND  tpli.prli_id  = @lPrli_id
    									AND  tpli.item_id  = @litem_id_child)
    						BEGIN

								--si ya existe se ejecuta un update del item hijo aplicando el coeficiente
								--multiplicado por la el precio de venta del padre
								UPDATE tbPriceListItems		WITH (ROWLOCK)

									SET		prli_price	= @lPrli_price * @liscr_Coeficient4Price,
											curr_id		= @lCurr_id,
											bra_id		= @lBra_id

									WHERE	comp_id		= @lComp_id
									AND		item_id		= @litem_id_child
									AND		prli_id		= @lPrli_id

    						END
    					ELSE
    						BEGIN

								--si no existe se ejecuta un insert del item hijo aplicando el coeficiente
								--multiplicado por la el precio de venta del padre
								INSERT INTO tbPriceListItems
									(		comp_id,
											prli_id,
											item_id,
											prli_price,
											curr_id,
											bra_id,
											prli_cd		)
								VALUES
    								(		@lComp_id,
    										@lPrli_id,
    										@litem_id_child,
    										@lPrli_price * @liscr_Coeficient4Price,
    										@lCurr_id,
    										@lBra_id,
    										GETDATE())

    						END




    					FETCH cursor_childs4trPriceListItems INTO @litem_id_child, @liscr_Coeficient4Price

    				END

    				CLOSE cursor_childs4trPriceListItems
    				DEALLOCATE cursor_childs4trPriceListItems



				END
			-- -----------------------------------------------------------------------------



			-- -----------------------------------------------------------
			-- Reglas de Actualizacion de Precios
			-- -----------------------------------------------------------
				BEGIN

					EXEC spCostlistActualizationRules @lComp_id,	@lPrli_id,	@lItem_id, 'True', @bitDisabled4Rules

				END

			-- -----------------------------------------------------------



	END TRY
	BEGIN CATCH
	END CATCH
	-- -------------------------------------------------------------------------------------




	-- -----------------------------------------------------------
	-- Saca Bloqueo de Ejecucion de Reglas de Actualizacion
	-- -----------------------------------------------------------
	UPDATE tbPriceListItems	WITH (ROWLOCK)
		SET	prli_disabled4Rules		= 'False',
			prli_lastModuleUpdate	= 0,		-- NO SACAR
			user_id_lastUpdate		= NULL,
			prli_lastRuleUpdate		= NULL
		WHERE	comp_id		= @lComp_id AND
				prli_id		= @lPrli_id AND
				item_id		= @lItem_id
	-- -----------------------------------------------------------


	--  NO, hacerlo MANUAL cuando PIDEN los datos x WS  EXEC spTableLastUpdate_updateData @lcomp_id, 109,@litem_id, @lPrli_id,null,@user_id


	-- --------------------------------------
	-- Para el PUTO sp de FullJaus y LRPMQLP
	-- Si se ve que molesta, sacarlo y que se caguen
	-- --------------------------------------
	BEGIN TRY
		INSERT INTO tbItemsUpdated(item_id) VALUES (@lItem_id)
	END TRY
	BEGIN CATCH
	END CATCH
	-- --------------------------------------






	-- --------------------------------------
	-- **wqefkln910247dñsl654weqrf
	-- Si hay alguna publicacion con LIsta Para MShops
	-- que sea la que cambió, dejar una marca
	-- para que el job de verifications genere una act de precios.
	-- Por ahi haya que hacer algo como esto
	-- con algun tipo de actualizacion de precios
	-- que NO EJECUTE este trigger !!!
	-- --------------------------------------
	BEGIN TRY
		IF EXISTS(	SELECT TOP 1 1
		          		FROM tbMercadoLibre_ItemsPublicados AS tmlip	WITH (NOLOCK,INDEX(IX_tbMercadoLibre_ItemsPublicados_prli_id4MercadoShop))
		          		WHERE	tmlip.comp_id				= @lComp_id AND
		          				tmlip.item_id				= @lItem_id AND
		          				tmlip.prli_id4MercadoShop	= @lPrli_id
		         )
			BEGIN

				UPDATE tbMercadoLibre_ItemsPublicados
					SET mlp_mustUpdate_prli_id4MercadoShop = 'True'
					WHERE	comp_id				= @lComp_id	AND
							item_id				= @lItem_id AND
							prli_id4MercadoShop = @lPrli_id

			END
	END TRY
	BEGIN CATCH
	END CATCH
	-- --------------------------------------




END
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trPriceListMarkup]
   ON  [dbo].[tbPriceListMarkup]
   AFTER  UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- -----------------------------------------------------------------------------
	-- Para prevenir que alguien haga un query que mate la base para todo el resto.!
	-- -----------------------------------------------------------------------------
	--SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
	--SET LOCK_TIMEOUT 500
	--SET DEADLOCK_PRIORITY LOW
	-- -----------------------------------------------------------------------------



    DECLARE @intCompID AS INT
    DECLARE @intPLM_Id AS INT

    SELECT	@intCompID = comp_id,
			@intPLM_Id = plm_id
		FROM INSERTED

	-- -------------------------------------------------------------------------------------------------------
	-- hacer aca una sobreescritura de los costos de todos los articulos que tengan definido este markup.
	-- sobreescribir la lista de costos definida en este descuento. para que se disparen las reglas de act
	-- -------------------------------------------------------------------------------------------------------

	DECLARE @litem_id AS INT,@lplm_id AS INT

	DECLARE cursor_UpdateCostLis CURSOR FAST_FORWARD FOR

	SELECT	ti.item_id,
		CASE
			WHEN ti.plm_id IS NOT NULL  THEN ti.plm_id
			ELSE						    -1
		END									[plm_id]
		FROM tbItem				ti		WITH (NOLOCK)
		WHERE
			ti.comp_id	= @intCompID AND
 			ti.plm_id	= @intPLM_Id

	OPEN cursor_UpdateCostLis

	-- lectura anticipada del cursor
	FETCH  cursor_UpdateCostLis
		INTO	@litem_id,
				@lplm_id

	WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @lplm_id > 0
				BEGIN

					UPDATE  tbItemCostList										WITH (ROWLOCK)
						SET		coslis_price = coslis_price
						FROM tbPriceListMarkup					 plm			WITH (NOLOCK)
						INNER JOIN tbItemCostList				 ticl
						ON ticl.comp_id		= plm.comp_id	AND
						   ticl.coslis_id	= plm.coslis_id AND
						   ticl.item_id		= @litem_id
						WHERE plm.comp_id	= @intCompID AND
							  plm.plm_id	= @lplm_id

				END

			FETCH  cursor_UpdateCostLis
				INTO	@litem_id,
						@lplm_id

		END

	CLOSE cursor_UpdateCostLis
	DEALLOCATE cursor_UpdateCostLis
	-- -------------------------------------------------------------------------------------------------------




END
GO






-- =============================================
-- Author:		MOS
-- Create date: 10-2009
-- Description:	Verifica que el Perfil 1 SIEMPRE
-- sea Administrador.
-- =============================================
CREATE TRIGGER trProfile
   ON  tbProfile
   AFTER UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @prof_isSa AS BIT
	DECLARE @comp_id AS INT
	declare @prof_id AS INT
	SELECT	@prof_isSa	= prof_isSA,
			@comp_id	= comp_id,
			@prof_id	= prof_id
		FROM INSERTED

	IF UPDATE(prof_isSa) AND @prof_isSa = 'false'
	BEGIN
		IF not EXISTS(	SELECT 1
							FROM tbProfile tp
		              		WHERE	tp.comp_id	= @comp_id
		              			AND tp.prof_isSA='true'
		              			AND tp.prof_id <> @prof_id )
			BEGIN
				UPDATE tbProfile
				SET
					prof_isSA = 'true'
					WHERE	comp_id = @comp_id
						AND prof_id = @prof_id
			END
	END

END

GO







-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trPurchaseDiscount]
   ON  [dbo].[tbPurchaseDiscount]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

 -- NUEVO

	-- Descuentos
    DECLARE @intCompID AS INT
    DECLARE @intPDId   AS INT
    DECLARE @decDesc1  AS DECIMAL(19,4)
    DECLARE @decDesc2  AS DECIMAL(19,4)
    DECLARE @decDesc3  AS DECIMAL(19,4)
    DECLARE @decDesc4  AS DECIMAL(19,4)
    DECLARE @pd_discountCoeficientOLD		AS DECIMAL(30,10)
    DECLARE @pd_bonificationCoeficientOLD	AS DECIMAL(30,10)
    DECLARE @pd_bonificationCNCoeficientOLD	AS DECIMAL(30,10)
    DECLARE @pd_discountCoeficientNEW		AS DECIMAL(30,10)
    DECLARE @pd_bonificationCoeficientNEW	AS DECIMAL(30,10)
    DECLARE @pd_bonificationCNCoeficientNEW	AS DECIMAL(30,10)

    DECLARE @pd_discount_apply4PurchaseOrderOLD			AS BIT
    DECLARE @pd_bonification_apply4PurchaseOrderOLD		AS BIT
    DECLARE @pd_bonificationCN_apply4PurchaseOrderOLD	AS BIT
    DECLARE @pd_isDisabledOLD							AS BIT

    DECLARE @pd_discount_apply4PurchaseOrderNEW			AS BIT
    DECLARE @pd_bonification_apply4PurchaseOrderNEW		AS BIT
    DECLARE @pd_bonificationCN_apply4PurchaseOrderNEW	AS BIT
    DECLARE @pd_isDisabledNEW							AS BIT



    SELECT  @intCompID = up.comp_id,
			@intPDId   = up.pd_id,
			@decDesc1  = pd_discount1,
			@decDesc2  = pd_discount2,
			@decDesc3  = pd_discount3,
			@decDesc4  = pd_discount4,
			@pd_discountCoeficientOLD					= pd_discountCoeficient,
			@pd_bonificationCoeficientOLD				= pd_bonificationCoeficient,
			@pd_bonificationCNCoeficientOLD				= pd_bonificationCNCoeficient,
			@pd_discount_apply4PurchaseOrderOLD			= pd_discount_apply4PurchaseOrder,
			@pd_bonification_apply4PurchaseOrderOLD		= pd_bonification_apply4PurchaseOrder,
			@pd_bonificationCN_apply4PurchaseOrderOLD	= pd_bonificationCN_apply4PurchaseOrder,
			@pd_isDisabledOLD							= pd_isDisabled
		FROM INSERTED UP


    SELECT 	@pd_discount_apply4PurchaseOrderNEW			= pd_discount_apply4PurchaseOrder,
			@pd_bonification_apply4PurchaseOrderNEW		= pd_bonification_apply4PurchaseOrder,
			@pd_bonificationCN_apply4PurchaseOrderNEW	= pd_bonificationCN_apply4PurchaseOrder,
			@pd_isDisabledNEW							= pd_isDisabled
		FROM deleted UP




    DECLARE		@decCoefDesc AS DECIMAL(19,6)
    SET         @decCoefDesc=100-(@decDesc1)
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc2
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc3
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc4
    SET         @decCoefDesc=(100 - @decCoefDesc)/100


	SET @pd_discountCoeficientNEW = @decCoefDesc

    UPDATE tbPurchaseDiscount
	    SET
       	pd_discountCoeficient = @decCoefDesc
    WHERE	comp_id = @intCompID
		AND pd_id	= @intPDId




	-- Bonificaciones
    SELECT  @decDesc1  = pd_bonification1,
			@decDesc2  = pd_bonification2,
			@decDesc3  = pd_bonification3,
			@decDesc4  = pd_bonification4
		FROM INSERTED UP

    SET         @decCoefDesc=100-(@decDesc1)
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc2
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc3
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc4
    SET         @decCoefDesc=(100 - @decCoefDesc)/100


	SET @pd_bonificationCoeficientNEW = @decCoefDesc

    UPDATE tbPurchaseDiscount
	    SET
       	pd_bonificationCoeficient = @decCoefDesc
    WHERE	comp_id = @intCompID
		AND pd_id	= @intPDId




	-- Bonificaciones por Nota de Crédito
    SELECT  @decDesc1  = pd_bonificationCN1,
			@decDesc2  = pd_bonificationCN2,
			@decDesc3  = 0,
			@decDesc4  = 0
		FROM INSERTED UP

    SET         @decCoefDesc=100-(@decDesc1)
    SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc2
    --SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc3
    --SET         @decCoefDesc=@decCoefDesc-(@decCoefDesc/100)*@decDesc4
    SET         @decCoefDesc=(100 - @decCoefDesc)/100

	SET @pd_bonificationCNCoeficientNEW = @decCoefDesc

    UPDATE tbPurchaseDiscount
	    SET
       	pd_bonificationCNCoeficient = @decCoefDesc
    WHERE	comp_id = @intCompID
		AND pd_id	= @intPDId


	-- NO ANDA ESTO, funciona con los 3 primeros pero no con los iuultimos 4
	-- Si NO hubo ningun cambio de coeficientes sale sin actualizar reglas ni costos.
	--IF  @pd_discountCoeficientOLD					= @pd_discountCoeficientNEW					AND
	--    @pd_bonificationCoeficientOLD				= @pd_bonificationCoeficientNEW				AND
	--    @pd_bonificationCNCoeficientOLD				= @pd_bonificationCNCoeficientNEW			AND
	--	@pd_discount_apply4PurchaseOrderNEW			= @pd_discount_apply4PurchaseOrderOLD		AND
	--	@pd_bonification_apply4PurchaseOrderNEW		= @pd_bonification_apply4PurchaseOrderOLD	AND
	--	@pd_bonificationCN_apply4PurchaseOrderNEW	= @pd_bonificationCN_apply4PurchaseOrderOLD	AND
	--	@pd_isDisabledNEW							= @pd_isDisabledOLD
	--   BEGIN
	--   		RETURN
	--   END







	-- -------------------------------------------------------------------------------------------------------
	-- hacer aca una sobreescritura de los costos de todos los articulos que tengan definido este descuento y de los que sus proveedores lo tengan tambien definido.
	-- sobreescribir la lista de costos definida en este descuento.
	-- -------------------------------------------------------------------------------------------------------

	DECLARE @litem_id AS INT,@lpd_id AS INT

	DECLARE cursor_UpdateCostLis CURSOR FAST_FORWARD FOR

	SELECT	ti.item_id,
		CASE
			WHEN ti.pd_id IS NOT NULL  THEN ti.pd_id
			WHEN ts.pd_id IS NOT NULL  THEN ts.pd_id
			ELSE						    -1
		END									[pd_id]
		FROM tbItem				ti		WITH (NOLOCK)
		LEFT JOIN tbSupplier	ts		WITH (NOLOCK)
			ON	ts.comp_id = ti.comp_id AND
				ts.supp_id = ti.supp_id
		WHERE
				ti.comp_id = @intCompID AND
	 			(
	 				ti.pd_id = @intPDId
	 					OR
	 				ts.pd_id = @intPDId
	 			)
		--WHERE	ti.pd_id IS NOT NULL OR			-- MOS 09/2017, solo para el descuento por compras que se acaba de modificar, no para TODOS como estaba antes.
		--		ts.pd_id IS NOT NULL

	OPEN cursor_UpdateCostLis

	-- lectura anticipada del cursor
	FETCH NEXT FROM  cursor_UpdateCostLis
		INTO	@litem_id,
				@lpd_id

	WHILE @@FETCH_STATUS = 0
		BEGIN
--SELECT 1 / 0
			UPDATE		tbItemCostList									WITH (ROWLOCK)
				SET		coslis_price = coslis_price --+ 0.01
				FROM	tbItemCostList				ticl
				INNER JOIN tbPurchaseDiscount		tpd					WITH (NOLOCK)
				ON ticl.comp_id		= tpd.comp_id	AND
				   ticl.coslis_id	= tpd.coslis_id

				WHERE	tpd.comp_id		= @intCompID AND
						tpd.pd_id		= @lpd_id	 AND
						ticl.item_id	= @litem_id

			FETCH NEXT FROM  cursor_UpdateCostLis
				INTO	@litem_id,
						@lpd_id

		END

	CLOSE cursor_UpdateCostLis
	DEALLOCATE cursor_UpdateCostLis
	-- -------------------------------------------------------------------------------------------------------


END
GO


-- =============================================
-- Author:		<Author,,Name>
