-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trPurchaseOrderDetail]
   ON  [dbo].[tbPurchaseOrderDetail]
   AFTER INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here


	-- UNa vez desrelacionado aca abajo, con el nuevo ID de OC, recorrer los pedidos del mas prioritario al menos y si da x cantidad relacionarlo y sacar el tilde de pend de relacionar y si NO da la cantidad, dividir el item, no hacer nada y volver a correrr desde el inicio.
	-- deje guardado el pod_idFrom para saber cual es el NUEVO renglon y los que saca de la o compra vieja que los ponga en el nuevo renglon.  pensar opciones pasra vewr si puedo de una reemplazar el pod de la relacion x el nuevo pod y listo., esto x cantidades.   x ahi deberia dividir el pedido segun las cantidades.  jugar con eso mentalmente a ver si funca.


	-- spPurchaseOrderDetail_update_SaleOrderHeader_PurchaseOrderRelation
	-- Poner el integrity en el isediting para q lo haga siempre, no solo al cerrar una sucursal ( diario )


	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @poh_id		AS INT
	DECLARE @pod_id		AS INT
	DECLARE @item_id	AS INT
	DECLARE @pod_qty	AS DECIMAL(19,4)
	DECLARE @pod_qtyOLD	AS DECIMAL(19,4)
	DECLARE @poh_quotation			AS BIT = 'False'
	DECLARE @pod_isProcessed		AS BIT = 'False'
	DECLARE @lpod_isProcessed		AS BIT = 'False'
	DECLARE @poh_estDeliveryDate	AS DATETIME
	DECLARE @pod_id_from			AS INT = NULL
	SELECT	@comp_id			= comp_id,
			@bra_id				= bra_id,
			@poh_id				= poh_id,
			@item_id			= item_id,
			@pod_qty			= pod_qty,
			@pod_id				= pod_id,
			@pod_isProcessed	= ISNULL(pod_isProcessed,'False'),
			@pod_id_from		= pod_id_from
		FROM INSERTED

	SELECT	@lpod_isProcessed	= ISNULL(pod_isProcessed,'False'),
			@pod_qtyOLD			= ISNULL(pod_qty,0)
		FROM DELETED




	DECLARE @bitIsUpdated_pod_id_from AS BIT   = 'False'
	--IF	@pod_id_from IS NOT NULL AND
	--	@pod_id_from > 0  --UPDATE(pod_id_from_CD)
	IF	UPDATE(pod_id_from_CD)
		BEGIN
			SET @bitIsUpdated_pod_id_from = 'True'
		END



	DECLARE @decTotalRecived	AS DECIMAL(25,6)
	DECLARE @decTotalUnRecived	AS DECIMAL(25,6)
	DECLARE @decTotalWithTax    AS DECIMAL(25,6)

	SELECT
			@decTotalWithTax = SUM(	dbo.fnGetPriceListItemTaxesCoeficient(tpod.comp_id, tpod.item_id) *	tpod.pod_price * tpod.pod_qty * dbo.fnGetFinalDiscountCoeficient(tpod.pod_Discount1,tpod.pod_Discount2,tpod.pod_Discount3,tpod.pod_Discount4) * dbo.fnGetFinalDiscountCoeficient(-tpod.pod_surcharge1,-tpod.pod_surcharge2,-tpod.pod_surcharge3,-tpod.pod_surcharge4) ),
			@decTotalRecived =
								SUM(CASE
										WHEN tpod.pod_isProcessed = 'True' THEN							tpod.pod_price * tpod.pod_qty * dbo.fnGetFinalDiscountCoeficient(tpod.pod_Discount1,tpod.pod_Discount2,tpod.pod_Discount3,tpod.pod_Discount4) * dbo.fnGetFinalDiscountCoeficient(-tpod.pod_surcharge1,-tpod.pod_surcharge2,-tpod.pod_surcharge3,-tpod.pod_surcharge4)
										ELSE 0
	      							END),
			@decTotalUnRecived =
								SUM(CASE
										WHEN tpod.pod_isProcessed = 'True' THEN 0
										ELSE															tpod.pod_price * tpod.pod_qty * dbo.fnGetFinalDiscountCoeficient(tpod.pod_Discount1,tpod.pod_Discount2,tpod.pod_Discount3,tpod.pod_Discount4) * dbo.fnGetFinalDiscountCoeficient(-tpod.pod_surcharge1,-tpod.pod_surcharge2,-tpod.pod_surcharge3,-tpod.pod_surcharge4)
	      							END)
		FROM tbPurchaseOrderDetail				tpod	WITH (NOLOCK)
		WHERE	tpod.comp_id	= @comp_id		AND
				tpod.bra_id		= @bra_id		AND
				tpod.poh_id		= @poh_id



	SELECT    	@poh_quotation		=	tpoh.poh_quotation,
				@poh_estDeliveryDate=	ISNULL(tpoh.poh_estDeliveryDate,getdate())
		FROM tbPurchaseOrderDetail				tpod	WITH (NOLOCK)
		INNER JOIN tbPurchaseOrderHeader AS		tpoh	WITH (NOLOCK)
			ON	tpoh.comp_id	= tpod.comp_id	AND
				tpoh.bra_id		= tpod.bra_id	AND
				tpoh.poh_id		= tpod.poh_id
		WHERE	tpod.comp_id	= @comp_id		AND
				tpod.bra_id		= @bra_id		AND
				tpod.poh_id		= @poh_id

	DECLARE @decTotal AS DECIMAL(19,4)
	SET		@decTotal = @decTotalRecived + @decTotalUnRecived

	DECLARE @decCoeficientPendingOfrecive AS DECIMAL(19,10)
	SET		@decCoeficientPendingOfrecive = @decTotalUnRecived / dbo.fnNoZDiv(@decTotal)


	UPDATE tbpurchaseOrderHeader		WITH (ROWLOCK)
		SET poh_pendingCoeficient	= @decCoeficientPendingOfrecive ,
			poh_taxCoeficient		= @decTotalWithTax / dbo.fnNoZDiv(@decTotal)
		WHERE	comp_id = @comp_id	AND
				bra_id	= @bra_id	AND
				poh_id	= @poh_id







		--INSERT INTO zTest
		--(
		--	-- id -- this column value is auto-generated
		--	dato,
		--	bdato
		--)
		--VALUES
		--(
		--	'@pod_isProcessed',
		--	@pod_isProcessed
		--)


		--INSERT INTO zTest
		--(
		--	-- id -- this column value is auto-generated
		--	dato,
		--	valorWithDecimal
		--)
		--VALUES
		--(
		--	'@pod_qty',
		--	@pod_qty
		--)

		--INSERT INTO zTest
		--(
		--	-- id -- this column value is auto-generated
		--	dato,
		--	valorWithDecimal
		--)
		--VALUES
		--(
		--	'@pod_qtyOLD',
		--	@pod_qtyOLD
		--)

		--INSERT INTO zTest
		--(
		--	-- id -- this column value is auto-generated
		--	dato,
		--	bdato
		--)
		--VALUES
		--(
		--	'@bitIsUpdated_pod_id_from',
		--	@bitIsUpdated_pod_id_from
		--)

		--INSERT INTO zTest
		--(
		--	-- id -- this column value is auto-generated
		--	dato,
		--	valorWithDecimal
		--)
		--VALUES
		--(
		--	'@pod_id',
		--	@pod_id
		--)



	-- MOS 07-2022 x CM
	-- ---------------------------------------------------------
	-- Si NO esta procesada y se BAJO x algo la cantidad
	-- y tiene pedidos relacionados, debe verificar que
	-- si hay MAS relacionados que la cantidad actual,
	-- debe des-relacionarlos por fecha de entrega del ultimo al primero
	-- y dejar los pedidos con el tilde de pendiente a relacionar y no
	-- incluir en disponible puestos.
	-- ---------------------------------------------------------
	IF	--@pod_isProcessed = 'False'	AND
		@pod_qty < @pod_qtyOLD		AND
		@bitIsUpdated_pod_id_from = 'False'		-- no debe hacerlo con el nuevo renglon insertado ya que cuando haga el UPDATE de la cantidad del renglon recibido parcial debe hacer esta MIERDA
		BEGIN



			IF EXISTS	(
							SELECT TOP 1 1
								FROM tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor	WITH (NOLOCK)
								WHERE	tsohpor.comp_id		= @comp_id	AND
										tsohpor.po_bra_id	= @bra_id	AND
										tsohpor.po_poh_id	= @poh_id	AND
										tsohpor.po_pod_id	= @pod_id
						)
			BEGIN




		--INSERT INTO zTest
		--(
		--	-- id -- this column value is auto-generated
		--	dato,
		--	bdato
		--)
		--VALUES
		--(
		--	'ENTRO?',
		--	'True'
		--)


				DECLARE @curcomp_id		AS INT
				DECLARE @curposor_id	AS INT
				DECLARE @curso_bra_id	AS INT
				DECLARE @curso_soh_id	AS INT
				DECLARE @curso_sod_id	AS INT
				DECLARE @curso_sod_qty	AS DECIMAL(19,4) = 0
				DECLARE @qtyRELATED		AS DECIMAL(19,4) = 0
				DECLARE @qtyPOD_New		AS DECIMAL(19,4) = 0
				DECLARE @intBRA_Id_New  AS INT			 = 0
				DECLARE @intPOH_Id_New  AS INT			 = 0
				DECLARE @intPOD_Id_New  AS INT			 = 0


				-- x ejemplo, tenia 10 en la OC y la bajaron a 4, debe dejar 4 en la relacion original y dividir el pedido en 4 y 6 ( nuevo ) y relacionar los 6 al nuevo item de la OC dividida.
				-- Entonces me quedarian los 6 en @intPOD_Id_New
				-- obtengo la OC ORIGINAL de esta PUTA DIVISION!!!!
				-- **lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!
				SELECT		TOP 1
							@intBRA_Id_New		= tpod.bra_id,
							@intPOH_Id_New		= tpod.poh_id,
							@intPOD_Id_New		= tpod.pod_id,
							@qtyPOD_New			= tpod.pod_qty	-- -- Cantodad que tengo que reasignar de la nueva OC (POD_ID ) generada
					FROM	tbPurchaseOrderDetail AS tpod	WITH (NOLOCK)
					WHERE	tpod.comp_id		= @comp_id	AND
							tpod.pod_id_from	= @pod_id
					ORDER BY tpod.pod_id DESC

				SELECT	@qtyRELATED = ISNULL(SUM(tsod.sod_qty),0)
					FROM tbSaleOrderHeader_PurchaseOrderRelation	AS tsohpor	WITH (NOLOCK)
					INNER JOIN tbSaleOrderDetail					AS tsod		WITH (NOLOCK)
						ON	tsod.comp_id		= tsohpor.comp_id	AND
							tsod.bra_id			= tsohpor.so_bra_id AND
							tsod.soh_id			= tsohpor.so_soh_id AND
							tsod.sod_id			= tsohpor.so_sod_id
					WHERE	tsohpor.comp_id		= @comp_id			AND
							tsohpor.po_bra_id	= @bra_id			AND
							tsohpor.po_poh_id	= @poh_id			AND
							tsohpor.po_pod_id	= @pod_id




				IF @pod_qty < @qtyRELATED
					BEGIN

						DECLARE curSORelated CURSOR LOCAL FORWARD_ONLY FOR
							SELECT	tsohpor.comp_id,
									tsohpor.posor_id,
									tsohpor.so_bra_id,
									tsohpor.so_soh_id,
									tsohpor.so_sod_id,
									tsod.sod_qty
								FROM tbSaleOrderHeader_PurchaseOrderRelation	AS tsohpor	WITH (NOLOCK)
								INNER JOIN tbSaleOrderDetail					AS tsod		WITH (NOLOCK)
									ON	tsod.comp_id		= tsohpor.comp_id	AND
										tsod.bra_id			= tsohpor.so_bra_id AND
										tsod.soh_id			= tsohpor.so_soh_id AND
										tsod.sod_id			= tsohpor.so_sod_id
								WHERE	tsohpor.comp_id		= @comp_id			AND
										tsohpor.po_bra_id	= @bra_id			AND
										tsohpor.po_poh_id	= @poh_id			AND
										tsohpor.po_pod_id	= @pod_id
								ORDER BY tsod.sod_itemDeliveryDate DESC



							OPEN			curSORelated
							FETCH NEXT FROM curSORelated INTO
								@curcomp_id,
								@curposor_id,
								@curso_bra_id,
								@curso_soh_id,
								@curso_sod_id,
								@curso_sod_qty
							WHILE @@FETCH_STATUS = 0	AND
								  @pod_qty		 < @qtyRELATED
								BEGIN

									IF ISNULL(@qtyPOD_New,0) = 0
										BEGIN
											-- Envio eMail con los Cambios
											BEGIN TRY
												INSERT INTO tbsendEMailQueue(comp_id,
																			 [user_id],
																			 replyTo,
																			 sendTo,
																			 [subject],
																			 body,
																			 displayName,
																			 sq_cd)
													SELECT	tb.comp_id,
															tb.user_id_ProcessingDate,
															tb.bra_purchaseOrder_eMail4UnRelation2SO,
															tb.bra_purchaseOrder_eMail4UnRelation2SO,
															'Orden de Compra: ' + CONVERT(VARCHAR(10),ort.po_bra_id) + '-' + CONVERT(VARCHAR(10),ort.po_poh_id) + ' Modificada',
															'Orden de Compra: ' + CONVERT(VARCHAR(10),ort.po_bra_id) + '-' + CONVERT(VARCHAR(10),ort.po_poh_id) + ' Modificada <br/>' +
															'Artículo: ' + ti.item_code + ' - ' + ti.item_desc + ' desvinculado del Pedido:' + CONVERT(VARCHAR(10),ort.so_bra_id) + '-' + CONVERT(VARCHAR(10),ort.so_soh_id) + ' <br/>' +
															'Cliente: ('   + CONVERT(VARCHAR(10),tc.cust_id) + ') ' + tc.cust_name,
															tb.bra_purchaseOrder_eMail4UnRelation2SO,
															GETDATE()
														FROM tbBranch										AS tb	WITH (NOLOCK)
														INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation	AS ort	WITH (NOLOCK)
															ON	ort.comp_id		= @curcomp_id	AND
																ort.posor_id	= @curposor_id
														INNER JOIN tbPurchaseOrderDetail					AS tpod	WITH (NOLOCK)
															ON	tpod.comp_id	= ort.comp_id	AND
																tpod.bra_id		= ort.po_bra_id AND
																tpod.poh_id		= ort.po_poh_id AND
																tpod.pod_id		= ort.po_pod_id
														INNER JOIN tbSaleOrderHeader						AS tsoh	WITH (NOLOCK)
															ON	tsoh.comp_id	= ort.comp_id	AND
																tsoh.bra_id		= ort.so_bra_id AND
																tsoh.soh_id		= ort.so_soh_id
														INNER JOIN tbCustomer								AS tc	WITH (NOLOCK)
															ON	tc.comp_id		= tsoh.comp_id	AND
																tc.cust_id		= tsoh.cust_id
														INNER JOIN tbItem									AS ti	WITH (NOLOCK)
															ON	ti.comp_id		= tpod.comp_id	AND
																ti.item_id		= tpod.item_id
														WHERE	tb.comp_id		= @curcomp_id	AND
																tb.bra_id		= @curso_bra_id	AND
																ISNULL(tb.bra_purchaseOrder_eMail4UnRelation2SO,'') <> ''

											END TRY
											BEGIN CATCH
											END CATCH
											-- Envio eMail con los Cambios


											-- Borro la relacion
											DELETE FROM tbSaleOrderHeader_PurchaseOrderRelation
												WHERE	comp_id		= @curcomp_id	AND
														posor_id	= @curposor_id

											-- POngo el pedido como pendiente a relacionar nuevamente
											UPDATE tbSaleOrderDetail
												SET sod_pending4pod_IdRelation = 'True',
													sod_exclude4AvailableStock = 'True'
												WHERE	comp_id		= @curcomp_id	AND
														bra_id		= @curso_bra_id AND
														soh_id		= @curso_soh_id AND
														sod_id		= @curso_sod_id

											-- Descuento la cantidad del PEDIDO a la cant relacionada para ver que esten relacionadas SOLO la cantidad que puede tener relacionado este renglon.
											SET @qtyRELATED = ISNULL(@qtyRELATED,0) - ISNULL(@curso_sod_qty,0)

										END
									ELSE IF ISNULL(@qtyPOD_New,0) <> 0	-- Si puedo Reasignar    **lwqhf973249%&$#%$#%lkjnlkh  CM y LRCDTPM!
										BEGIN

											-- Si la cantidad de Pedido es menor o igual a la de la OC NUEVA pendiente de relacionar.
											IF @qtyPOD_New >= @curso_sod_qty
												BEGIN

													-- Borro la relacion VIEJA
													DELETE FROM tbSaleOrderHeader_PurchaseOrderRelation
														WHERE	comp_id		= @curcomp_id	AND
																posor_id	= @curposor_id

													INSERT INTO tbSaleOrderHeader_PurchaseOrderRelation	(
																comp_id,
													            so_bra_id,
													            so_soh_id,
													            so_sod_id,
													            po_bra_id,
													            po_poh_id,
													            po_pod_id,
													            posor_POReceived)
														VALUES(
																@curcomp_id,
																@curso_bra_id,
																@curso_soh_id,
																@curso_sod_id,
																@intBRA_Id_New,
																@intPOH_Id_New,
																@intPOD_Id_New,
																'False'
															  )

													SET @qtyRELATED = ISNULL(@qtyRELATED,0) - ISNULL(@curso_sod_qty,0)
													SET @qtyPOD_New = ISNULL(@qtyPOD_New,0) - ISNULL(@curso_sod_qty,0)
												END
											ELSE
												BEGIN

													DECLARE @intSOD_IdofNewSalrOrderDetail AS INT = 0
													-- dividir el pedido en la cantidad que me queda para asignar y generar lo mismo con el nuevo sod
													-- NO BORRO la relacion vieja y divido el RECONTRA REPUTO PEDIDO de estos HIJOS DE RE MIL PUTAS
													-- NO hay que tocar los campos del pedido ya que el nuevo pedido y el viejo siguen relacionados IGUALES y mas abajo al que se recibio se lo va a ajustar.
													EXEC spSaleOrderDetail_divideSaleOrderbySOD_Id  @curcomp_id,
																									@curso_bra_id,
																									@curso_soh_id,
																									@curso_sod_id,
																									@qtyPOD_New,
																									@intSOD_IdofNewSalrOrderDetail OUTPUT


													INSERT INTO tbSaleOrderHeader_PurchaseOrderRelation	(
																comp_id,
													            so_bra_id,
													            so_soh_id,
													            so_sod_id,
													            po_bra_id,
													            po_poh_id,
													     po_pod_id)
														VALUES(
																@curcomp_id,
																@curso_bra_id,
																@curso_soh_id,
																@intSOD_IdofNewSalrOrderDetail,
																@intBRA_Id_New,
																@intPOH_Id_New,
																@intPOD_Id_New
															  )

													SET @qtyRELATED = ISNULL(@qtyRELATED,0) - ISNULL(@qtyPOD_New,0)
													SET @qtyPOD_New = 0													--ISNULL(@qtyPOD_New,0) - ISNULL(@qtyPOD_New,0)

												END

											-- Descuento la cantidad del PEDIDO a la cant relacionada para ver que esten relacionadas SOLO la cantidad que puede tener relacionado este renglon.


										END






									FETCH NEXT FROM curSORelated INTO
										@curcomp_id,
										@curposor_id,
										@curso_bra_id,
										@curso_soh_id,
										@curso_sod_id,
										@curso_sod_qty
								END

							CLOSE		curSORelated
							DEALLOCATE	curSORelated
					END
			END
		END
	-- ---------------------------------------------------------



	-- ---------------------------------------------------------
	-- Asocia Pedidos PENDIENTES de relacionar a una OC.
	-- ---------------------------------------------------------
	IF	@poh_quotation				= 'False' AND
		@pod_isProcessed			= 'False' AND
		@pod_qty					> 0		  AND
		@bitIsUpdated_pod_id_from	= 'False'		--**sldkfnqw52353&%&%$#safdqwnqwfr			(Debe hacerse con NUEVAS ordenes de compra y no con divididas x recibir parcial)
		BEGIN
			EXEC spPurchaseOrderDetail_update_SaleOrderHeader_PurchaseOrderRelation @comp_id,@bra_id,@poh_id,@pod_id,@item_id,@pod_qty
		END
	-- ---------------------------------------------------------


	-- ---------------------------------------------------------
	-- Al RECIBIR una Orden de Compra de cualquier manera,
	-- se debe poner como NO excluido de disponible a todos
	-- los PEDIDOS que esten relacionados a la misma.
	-- **GFG23940723094723njm
	-- ---------------------------------------------------------
	IF	@lpod_isProcessed <> @pod_isProcessed	AND
		@pod_isProcessed  = 'True'
		BEGIN
			UPDATE tbsaleorderdetail
				SET sod_pending4pod_IdRelation	= 0,
					sod_exclude4AvailableStock	= 0,
					sod_itemDeliveryDate		=	CASE	-- MOS 01-2022 Claudia 14495
														WHEN @poh_estDeliveryDate > tsod.sod_itemDeliveryDate THEN @poh_estDeliveryDate
														WHEN @poh_estDeliveryDate < tsod.sod_itemDeliveryDate THEN tsod.sod_itemDeliveryDate
														ELSE @poh_estDeliveryDate
													END

				FROM tbsaleorderdetail tsod										WITH (NOLOCK)
				INNER JOIN tbSaleOrderHeader_PurchaseOrderRelation AS tsohpor	WITH (NOLOCK)
					ON	tsohpor.comp_id		= tsod.comp_id AND
						tsohpor.so_bra_id	= tsod.bra_id AND
						tsohpor.so_soh_id	= tsod.soh_id AND
						tsohpor.so_sod_id	= tsod.sod_id
				WHERE	tsohpor.comp_id		= @comp_id	AND
						tsohpor.po_bra_id	= @bra_id	AND
						tsohpor.po_poh_id	= @poh_id	AND
						tsohpor.po_pod_id	= @pod_id

				UPDATE tbSaleOrderHeader_PurchaseOrderRelation
					SET posor_POReceived = 'True'
					WHERE	comp_id		 = @comp_id	AND
							po_bra_id	 = @bra_id	AND
							po_poh_id	 = @poh_id	AND
							po_pod_id	 = @pod_id


		END
	-- ---------------------------------------------------------




END
GO




