-- =============================================
CREATE TRIGGER [dbo].[trRMA_Detail]
   ON  [dbo].[tbRMA_Detail]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here

    DECLARE @comp_id	AS INT,
			@rmah_id	AS INT,
			@rmad_id	AS INT,
			@rmad_IncludeInPotentialStock AS BIT

    SELECT	@comp_id = comp_id,
			@rmah_id = rmah_id,
			@rmad_id = rmad_id,
			@rmad_IncludeInPotentialStock = ISNULL(rmad_IncludeInPotentialStock,'False')
		FROM INSERTED



    IF @rmad_IncludeInPotentialStock = 'True'
		BEGIN
			IF EXISTS(
						SELECT TOP 1 1
							FROM tbRMA_Header trh	WITH (NOLOCK)
						WHERE	trh.comp_id = @comp_id	AND
								trh.rmah_id = @rmah_id	AND
								trh.cust_id IS NULL
					)
				BEGIN
					UPDATE tbRMA_Detail	WITH (ROWLOCK)
						SET
							rmad_IncludeInPotentialStock = 'False'
					WHERE	comp_id = @comp_id AND
							rmah_id = @rmah_id AND
							rmad_id = @rmad_id
				END
		END



END
GO

