-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trSalesTerms]
   ON  [dbo].[tbSalesTerms]
   AFTER INSERT,UPDATE

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here



    DECLARE @st_id AS INT

    DECLARE @comp_id AS INT

    DECLARE @st_CreditIsAvailable AS BIT
    DECLARE @cc_id				  AS INT
	DECLARE @st_MEEnabled		  AS BIT
	DECLARE @st_ME_dl_id		  AS INT
	DECLARE @st_collectionDiscountsAvailable AS BIT = 'False'
	DECLARE @st_collectionPaymentsAvailable  AS BIT = 'False'

    SELECT @comp_id				 = comp_id,
		   @st_id				 = st_id,
		   @st_CreditIsAvailable = st_CreditIsAvailable,
		   @cc_id				 = cc_id,
		   @st_MEEnabled		 = ISNULL(st_MEEnabled,'False'),
		   @st_ME_dl_id			 = st_ME_dl_id,
		   @st_collectionDiscountsAvailable = st_collectionDiscountsAvailable,
		   @st_collectionPaymentsAvailable  = st_collectionPaymentsAvailable
    FROM inserted


	IF @st_collectionDiscountsAvailable = 'True' AND @st_collectionPaymentsAvailable = 'True'
		BEGIN
			UPDATE tbSalesTerms
				SET		st_collectionDiscountsAvailable = 'False',
						st_collectionPaymentsAvailable	= 'False'
				WHERE comp_id	= @comp_id AND
					  st_id		= @st_id
		END


    IF @st_CreditIsAvailable = 'False'

		BEGIN
			UPDATE tbSalesTerms
				SET		sct_id = 0
				WHERE comp_id	= @comp_id AND
					  st_id		= @st_id

		END

	IF @cc_id IS NOT NULL AND @st_CreditIsAvailable = 'True'
		BEGIN
			UPDATE tbSalesTerms
				SET		st_CreditIsAvailable = 'False'
				WHERE comp_id	= @comp_id AND
					  st_id		= @st_id
		END

	IF @st_MEEnabled = 'True' AND @st_ME_dl_id IS NULL
		BEGIN
			UPDATE tbSalesTerms
				SET		st_MEEnabled = 'False'
				WHERE comp_id	= @comp_id AND
					  st_id		= @st_id
		END



END
GO



