CREATE TRIGGER [dbo].[trSubCategory]
   ON  [dbo].[tbSubCategory]
   AFTER INSERT,UPDATE
AS

BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id	AS INT
	DECLARE @cat_id		AS INT
	DECLARE @subcat_id	AS INT

	SELECT	@comp_id	= comp_id,
			@cat_id		= cat_id,
			@subcat_id  = subcat_id
		FROM INSERTED

	IF EXISTS(
			SELECT 1
			FROM tbSubCategory  tc
				WHERE	tc.comp_id	= @comp_id		AND
						tc.cat_id	= @cat_id		AND
						tc.subcat_id= @subcat_id	AND
						tc.subcat_image IS NOT NULL	AND
						(
							tc.subcat_imageChecksum IS NULL
							OR
							tc.subcat_imageChecksum <> dbo.fnChecksum4Image(tc.subcat_image)
						)
				)
	BEGIN

		UPDATE tbWebSiteII_Names
			SET	ws_files2TempUpdated				= 'False',
				ws_files2TempUpdated4Development	= 'False'

		UPDATE tbSubCategory
			SET subcat_imageChecksum	= dbo.fnChecksum4Image(subcat_image)
			WHERE	comp_id			= @comp_id		AND
					cat_id			= @cat_id		AND
					subcat_id		= @subcat_id

	END

END



