-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trSupplier]
  ON  [dbo].[tbSupplier]
   AFTER INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here
	DECLARE @supp_id AS integer
	DECLARE @city_id AS integer
	DECLARE @comp_id AS integer
	DECLARE @supp_zip				AS NVARCHAR(50)
	DECLARE @strError				AS NVARCHAR(500)
	DECLARE @supp_updatedFromABM    AS BIT

	SELECT	@supp_id				= supp_id,
			@city_id				= city_id,
			@comp_id				= comp_id,
			@supp_zip				= supp_zip,
			@supp_updatedFromABM    = supp_updatedFromABM
		FROM INSERTED

		SET @supp_updatedFromABM	= ISNULL(@supp_updatedFromABM,'False')



	IF @supp_updatedFromABM = 'True'
		BEGIN

			DECLARE @lang_id AS INT
			SELECT @lang_id = tc.lang_id
				FROM tbCompany tc WITH (NOLOCK)
				WHERE tc.comp_id = @comp_id


			IF @city_id IS NULL OR @city_id <= 0
				BEGIN

					-- '<br><br><br> <B>ATENCIÓN:<br> No se indicó Ninguna Ciudad / Localidad.<br> Si el alta automática de ciudades está deshabilitada podrá configurarlo en la solapa Varios del archivo de Sucursales!</b>'
					SELECT @strError =  '|' + tut.utexts_desc
						FROM tbsysUniqueTexts tut		WITH (NOLOCK)
						WHERE	tut.utexts_id	= 351		AND
								tut.lang_id		= @lang_id
					RAISERROR (15600,-1,-1, @strError);
					RETURN

				END


			UPDATE tbSupplier
				SET
    				supp_city = (	SELECT TOP 1 vc.city_desc
    		             				FROM vwCities vc  WITH (NOLOCK)
    		             				WHERE vc.city_id = @city_id )
				WHERE supp_id = @supp_id



			IF EXISTS(	-- Si falta cargarle el Codigo POstal pone el que tiene cargado el cliente.
						SELECT 1
							FROM tbCities tc WITH (NOLOCK)
							WHERE	tc.city_id = @city_id AND
									tc.city_zip IS NULL
						)

				BEGIN
					UPDATE tbCities
						SET
							city_zip  = @supp_zip
						WHERE city_id = @city_id
				END

		END



	-- ---------------------------------------------------------------
	-- Dispara Reglas x actualizacion de Proveedor
	-- ---------------------------------------------------------------
	DECLARE @litem_id	AS INT,
			@coslis_id	AS INT
	DECLARE cursor_UpdateCostLis CURSOR FAST_FORWARD FOR
	SELECT  ticl.item_id,
			ticl.coslis_id
		FROM	tbItemCostList				ticl
		INNER JOIN tbItemCostListName		ticln
			ON	ticln.comp_id	= ticl.comp_id	AND
				ticln.coslis_id = ticl.coslis_id
		INNER JOIN tbitem					ti					WITH (NOLOCK)
			ON	ti.comp_id	= ticl.comp_id	AND
				ti.item_id	= ticl.item_id
		INNER JOIN tbSupplier				ts					WITH (NOLOCK)
			ON	ts.comp_id	= ticl.comp_id	AND
				ts.supp_id	= ti.supp_id
		INNER JOIN tbPurchaseDiscount		tpd					WITH (NOLOCK)
			ON	tpd.comp_id		= ts.comp_id	AND
				tpd.pd_id		= ts.pd_id
		WHERE	ticln.comp_id									= @comp_id		AND
				ticln.coslis_triggerOnItemAndSupplierUpdates	= 'True'		AND
				ti.supp_id										= @supp_id		AND
				ticl.coslis_id									= tpd.coslis_id


	OPEN cursor_UpdateCostLis

	-- lectura anticipada del cursor
	FETCH  NEXT FROM  cursor_UpdateCostLis
		INTO	@litem_id,
				@coslis_id

	WHILE @@FETCH_STATUS = 0
		BEGIN

			UPDATE		tbItemCostList									WITH (ROWLOCK)
				SET		coslis_price = coslis_price --+ 0.01
				FROM	tbItemCostList				ticl
				WHERE	ticl.comp_id	= @comp_id		AND
						ticl.item_id	= @litem_id		AND
						ticl.coslis_id	= @coslis_id

			FETCH  NEXT FROM  cursor_UpdateCostLis
				INTO	@litem_id,
						@coslis_id

		END
	CLOSE		cursor_UpdateCostLis
	DEALLOCATE	cursor_UpdateCostLis
	-- ---------------------------------------------------------------




END
GO




