CREATE TRIGGER trsysHelpPages
   ON  tbsysHelpPages
   AFTER UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @page_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @table_id	AS INT


	SELECT	@page_id	= page_id,
			@lang_id	= lang_id,
			@table_id	= table_id
		FROM INSERTED

	IF @lang_id = 2
		BEGIN
			DELETE FROM tbsysHelpPages
				WHERE	page_id = @page_id	AND
						lang_id <> 2		AND
						(table_id IS NULL OR table_id = @table_id)
		END




END
GO

