-- =============================================
-- Author:		MOS
-- Create date: Actualiza valores para comparar en el ABM de Clientes y Proveedores
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER trsysTaxAFIP
   ON  tbsysTaxAFIP
   AFTER UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @strCUIT AS CHAR(11)
	DECLARE @intFiscalClass AS int
	SELECT	@strCUIT = afip_cuit ,
			@intFiscalClass = afip_fiscalClass
		FROM INSERTED


	IF @intFiscalClass = 1
		BEGIN
			UPDATE tbsysTaxAFIP
			SET
				afip_impiva = 'AC',
				afip_impmon = 'NI'
			WHERE afip_cuit = @strCUIT
		END


	IF @intFiscalClass = 3
		BEGIN
			UPDATE tbsysTaxAFIP
			SET
				afip_impiva = 'NI',
				afip_impmon = 'Z'
			WHERE afip_cuit = @strCUIT
		END

	IF @intFiscalClass = 4
		BEGIN
			UPDATE tbsysTaxAFIP
			SET
				afip_impiva = 'EX',
				afip_impmon = 'NI'
			WHERE afip_cuit = @strCUIT
		END



END
GO

-- =============================================
-- Author:		MOS
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER trTableFieldsDisabled4Profiles
   ON  tbTableFieldsDisabled4Profiles
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here
	DECLARE
		@comp_id		AS INT,
		@bra_id			AS INT,
		@prof_id		AS INT,
		@table_id		AS INT,
		@field_id		AS INT,
		@order4Grid		AS INT

	SELECT
		@comp_id	= comp_id,
		@bra_id		= bra_id,
		@prof_id	= prof_id,
		@table_id	= table_id,
		@field_id	= field_id,
		@order4Grid = order4Grid
		FROM INSERTED


	DECLARE @bitMustClear AS BIT
	SET		@bitMustClear = 'False'

	IF @order4Grid > 0
		BEGIN
			SET @bitMustClear = 'True'
		END

	DECLARE @lastField AS INT
	SELECT TOP 1 @lastField = tf.field_id
		FROM tbsysFields tf
		WHERE tf.table_id = @table_id
		ORDER BY tf.field_order DESC

	IF @lastField = @field_id
		BEGIN
			SET @bitMustClear = 'True'
		END



	IF UPPER((
			SELECT tf.field_name
	            FROM tbsysFields tf
				WHERE tf.table_id = @table_id AND tf.field_id = @field_id )) = 'COMP_ID'
		BEGIN
			SET @bitMustClear = 'True'
		END


	IF @bitMustClear = 'True'
		BEGIN
			UPDATE tbTableFieldsDisabled4Profiles
				SET order4Grid = 0
				WHERE	comp_id		= @comp_id	AND
						bra_id		= @bra_id	AND
						prof_id		= @prof_id	AND
						table_id	= @table_id AND
						field_id	= @field_id
		END



END
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trTaxEngineName_Taxes]
   ON  [dbo].[tbTaxEngineName_Taxes]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


    DECLARE @comp_id		INT,
			@tent_id		INT,
			@ten_id			INT

	SELECT  @comp_id		= comp_id,
			@tent_id		= tent_id,
			@ten_id			= ten_id
		FROM INSERTED


    -- En compañia se pone a mano en TRUE este campo para que deje imprimir en multirenglon los impuestos bajo mail solicitandolo y sabiend que puede traer problemas con los resumenes
    IF EXISTS(
				SELECT 1
					FROM tbcompany tc
					WHERE	comp_id													= @comp_id AND
							ISNULL(tc.comp_enableTaxEngineWithMultipleRows,'False') = 'False'
			 )

		BEGIN

			-- Si es de VENTAS pone que NO puede ser en un nuevo renglon
			UPDATE tbTaxEngineName_Taxes
				SET
					tent_newRow = 0
				FROM tbTaxEngineName_Taxes tmp
				INNER JOIN tbTaxEngineName tten
					ON	tten.comp_id	= tmp.comp_id		AND
						tten.ten_id		= tmp.ten_id
				WHERE	tmp.tent_id			=	@tent_id	AND
						tten.ten_isPurchase = 0				AND
						tmp.tent_newRow		= 1


		END

END
GO





