CREATE TRIGGER [dbo].[trTaxName]
   ON  [dbo].[tbTaxName]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id		AS INT
	DECLARE @tax_id			AS INT
	DECLARE @per_4AllItems	AS BIT
	DECLARE @tax_class		AS INT
	SELECT	@comp_id		= comp_id,
			@tax_id			= tax_id,
			@per_4AllItems	= per_4AllItems,
			@tax_class		= tax_class
		FROM INSERTED


	-- Si es IVA NO se puede calcular para TODOS los Articulos !!!
	IF	@tax_class		= 1 AND
		@per_4AllItems	= 'True'
		BEGIN
			UPDATE tbtaxname
				SET per_4AllItems = 'False'
				WHERE	comp_id = @comp_id AND
						tax_id	= @tax_id
		END

	UPDATE tbtaxname
		SET city_id = NULL
		WHERE	comp_id = @comp_id	AND
				tax_id	= @tax_id	AND
				city_id = 0


END
GO

