   ON  tbTiendaNube_Stores
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @intSitesNoAT AS INT = 0

	SELECT @intSitesNoAT = COUNT(*)
		FROM tbTiendaNube_Stores ttns
		WHERE isnull(ttns.tn_accesTocken,'') = ''

