			RETURN
		END

END
GO





CREATE TRIGGER [dbo].[trUser]
	   ON  [dbo].[tbUser]
	   AFTER INSERT
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @user_id	AS INT
	DECLARE @comp_id	AS INT
	DECLARE @bra_id		AS INT
	DECLARE @prof_id	AS INT
	DECLARE @lang_id	AS INT
	DECLARE @cn_id		AS INT
	DECLARE @sm_id		AS INT

	SELECT	@user_id	= USER_ID,
			@comp_id	= user_lastcompany,
			@bra_id		= user_lastbranch,
			@prof_id	= user_lastprofile,
			@sm_id		= sm_id,
			@cn_id		= cn_id
		FROM INSERTED


	INSERT INTO tbUserCompanyProfile
	(
		comp_id,
		bra_id,
		[user_id],
		prof_id
	)
	VALUES
	(
		@comp_id,
		@bra_id,
		@user_id,
		@prof_id
	)

	-- Busca la sucursal asignada a la caja seleccionada
	DECLARE @intBraId4Cash	AS INT
	DECLARE @intCompId4Cash AS INT
	SELECT	@intBraId4Cash	= tcn.bra_id,
			@intCompId4Cash = tcn.comp_id
		FROM tbCashNumbers tcn
		WHERE tcn.cn_id = @cn_id

	IF	@cn_id			IS NOT NULL AND
		@intCompId4Cash = @comp_id
		BEGIN

			-- Si la sucursald de la caja es diferente a la dada de alta, da de alta en perfiles x sucursal a la de la caja.
			IF @intBraId4Cash IS NOT NULL AND @intBraId4Cash <> @bra_id
				BEGIN
					INSERT INTO tbUserCompanyProfile
					(
						comp_id,
						bra_id,
						[user_id],
						prof_id
					)
					VALUES
					(
						@comp_id,
						@intBraId4Cash,
						@user_id,
						@prof_id
					)
				END

			-- INserta la caja habilitada x sucursal.
			INSERT INTO tbCashNumber4Branch4User
			(
				comp_id,
				bra_id,
				cn_id,
				[user_id],
				re_order
			)
			VALUES
			(
				@comp_id,
				@intBraId4Cash,
				@cn_id,
				@user_id,
				1
			)


		END

	-- Si tiene vendedor asignado, da de alta la relacion de usuario-vendedor.
	DECLARE @intCompID4Salesman AS INT
	SELECT @intCompID4Salesman = comp_id
		FROM tbSalesman ts
		WHERE ts.sm_id = @sm_id

	-- Da de alta en Vendedores Asignados a Usuarios
	IF @sm_id IS NOT NULL AND @comp_id = @intCompID4Salesman
		BEGIN
			INSERT INTO tbUserSalesmanRelation
			(
				comp_id,
				bra_id,
				[user_id],
				sm_id
			)
			VALUES
			(
				@comp_id,
				@bra_id,
				@user_id,
				@sm_id
			)
		END

	-- Da de alta en Filtro de Clientes para ABM x Vendedor
	IF @sm_id IS NOT NULL AND @comp_id = @intCompID4Salesman
		BEGIN
			INSERT INTO tbCustomerFilterByUser
			(
				comp_id,
				[user_id],
				sm_id,
				bra_id
			)
			VALUES
			(
				@comp_id,
				@user_id,
				@sm_id,
				@bra_id
			)
		END


END
GO



-- =============================================
-- Author:		MOS
-- Description:	Desbloquea a GBPMaster ya que es
--              el unico usuario que debe estar
--              siempre accesible por cualquier
--              error que cometa el usuario.!!!
-- =============================================
CREATE TRIGGER [dbo].[trUser2]
   ON  [dbo].[tbUser]
   AFTER  INSERT,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @user_id		AS INT
	DECLARE @user_nick		AS VARCHAR(50)
	DECLARE @comp_id		AS INT
	DECLARE @bra_id			AS INT
	DECLARE @prof_id		AS INT
	DECLARE @lang_id		AS INT
	DECLARE @cn_id			AS INT
	DECLARE @sm_id			AS INT
	DECLARE @user_Blocked	AS BIT

	SELECT	@user_id		= USER_ID,
			@user_nick		= user_nick,
			@user_Blocked	= user_Blocked,
			@comp_id		= user_lastcompany,
			@bra_id			= user_lastbranch,
			@prof_id		= user_lastprofile,
			@sm_id			= sm_id,
			@cn_id			= cn_id
		FROM INSERTED


	IF @user_Blocked = 'True' AND @user_id = 1 AND @user_nick = 'ERPAdmin'
		BEGIN
			UPDATE tbuser SET user_Blocked = 'False' WHERE USER_ID = 1
		END




END
GO




-- =============================================
-- Author:	MOS
-- Create date: 01-2014
-- Description:	Para mantener la tabla tbUsers4BranchFilter Actualizada
-- =============================================
CREATE TRIGGER [dbo].[trUserCompanyProfile]
   ON  [dbo].[tbUserCompanyProfile]
   AFTER INSERT,DELETE,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	BEGIN TRANSACTION

		-- ATENCION
		-- Modificar tambien en trigger de tbBranch, trUserCompanyProfile y spBranch_UpdateData y trUsers4BranchFilter_Users2BlockCubes
	   DELETE FROM tbUsers4BranchFilter
	   INSERT INTO tbUsers4BranchFilter
						(
							comp_id,
							bra_id,
							[user_id],
							ubf_blocked4Cube
						)
						SELECT DISTINCT		tucp.comp_id,
											tucp.bra_id,
											tucp.user_id,
											'False'
								FROM tbUserCompanyProfile tucp					WITH (NOLOCK)
								INNER JOIN tbBranch tb							WITH (NOLOCK)
									ON	tb.comp_id	= tucp.comp_id AND
										tb.bra_id	= tucp.bra_id
								WHERE tb.bra_disabled = 0

		-- Bloquea usuarios para CUBOS.
		UPDATE tbUsers4BranchFilter
			SET	ubf_blocked4Cube = 'True'
			FROM tbUsers4BranchFilter me							WITH (NOLOCK)
			INNER JOIN tbUsers4BranchFilter_Users2BlockCubes me2	WITH (NOLOCK)
				ON	me2.comp_id		= me.comp_id	AND
					me2.bra_id		= me.bra_id		AND
					me2.[user_id]	= me.[user_id]



		-- **sdgfwetg78
		DELETE tbUsers4BranchFilter
			FROM tbUsers4BranchFilter	tbl
			INNER JOIN tbBranch			tb
				ON	tb.comp_id	= tbl.comp_id AND
					tb.bra_id	= tbl.bra_id
			WHERE tb.bra_disabled = 1


	COMMIT TRANSACTION

END
GO





