create TRIGGER [dbo].[trWebSite_Languages]
ON  [dbo].[tbWebSite_Languages]
AFTER INSERT, UPDATE
AS
BEGIN
	SET NOCOUNT ON


	DECLARE @comp_id		INT
	DECLARE @ws_id			INT
	DECLARE @lang_id		INT
	DECLARE @default		BIT


	SELECT	@comp_id	=	comp_id			,
			@ws_id		=	ws_id			,
			@lang_id	=	lang_id			,
			@default	=	wslang_default
	FROM	INSERTED


	IF @default = 'true'
	BEGIN

		UPDATE	tbWebSite_Languages

		SET		wslang_default	=	'false'

		WHERE	comp_id			=	@comp_id
		AND		ws_id			=	@ws_id
		AND		lang_id			<>	@lang_id

	END


END
GO

