BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @comp_id							AS INT
	DECLARE @page_id							AS UNIQUEIDENTIFIER
	DECLARE @ws_masterPage_isAvailable4Update	AS BIT
	DECLARE @ws_masterPage_Version				AS INT
	DECLARE @ws_masterPage_TAG					AS NVARCHAR(30)

	SELECT
		@comp_id								= comp_id,
		@page_id								= page_id,
		@ws_masterPage_isAvailable4Update		= isnull(ws_masterPage_isAvailable4Update,'False'),
		@ws_masterPage_Version					= ISNULL(ws_masterPage_Version,0),
		@ws_masterPage_TAG						= ISNULL(ws_masterPage_TAG,'')
		FROM INSERTED

	IF	@ws_masterPage_isAvailable4Update = 'True' AND
		@ws_masterPage_TAG <> ''
		BEGIN
			UPDATE	tbWebSiteII_Pages
				SET ws_masterPage_Version = @ws_masterPage_Version + 1
				WHERE	comp_id = @comp_id AND
						page_id = @page_id
		END


END
GO

