GO

CREATE TRIGGER [dbo].[trWebSiteII_SpotCampaignRelation]
   ON  [dbo].[tbWebSiteII_SpotCampaignRelation]
   AFTER INSERT,DELETE,UPDATE
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @comp_id			AS INT
	DECLARE @wsbcr_openMode		AS INT
	DECLARE @wsbc_id			AS INT
	DECLARE @wsban_id			AS INT
	DECLARE @wsbcr_type			AS INT
	DECLARE @wsbcr_openModeText AS NVARCHAR(10)

	SELECT
			@comp_id		= comp_id,
			@wsbc_id		= wsbc_id,
			@wsban_id		= wsban_id,
			@wsbcr_type		= wsbcr_type,
			@wsbcr_openMode = wsbcr_openMode
		FROM INSERTED


	UPDATE tbWebSiteII_SpotCampaignRelation
		SET wsbcr_openModeText =	CASE
										WHEN @wsbcr_openMode = 0 THEN '_Self'
										WHEN @wsbcr_openMode = 1 THEN '_blank'
										ELSE						  '_self'
									END
		WHERE	comp_id		= @comp_id		AND
				wsbc_id		= @wsbc_id		AND
				wsban_id	= @wsban_id		AND
				wsbcr_type	= @wsbcr_type


	EXEC spWebSiteII_SpotsCampaignActivation

END
GO

