-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE TRIGGER [dbo].[trWebSiteII_SQLScripts]
   ON  [dbo].[tbWebSiteII_SQLScripts]
   AFTER  INSERT,UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	DECLARE @comp_id			AS INT
	DECLARE @wssql_id			AS INT
	DECLARE @wssql_Label		AS NVARCHAR(300)
	DECLARE @wssql_scriptSQL	AS NVARCHAR(MAX)
	SELECT	@comp_id			= comp_id,
			@wssql_id			= wssql_id,
			@wssql_scriptSQL	= wssql_scriptSQL,
			@wssql_Label		= wssql_Label
		FROM INSERTED

	SET		@wssql_scriptSQL = REPLACE(@wssql_scriptSQL,'EXECUTE ','EXE-UTE ')
	SET		@wssql_scriptSQL = REPLACE(@wssql_scriptSQL,'EXEC ','EXE-C ')
	SET		@wssql_scriptSQL = REPLACE(@wssql_scriptSQL,'Exec ','EXE-C ')

	IF @wssql_scriptSQL LIKE '%inetpub\hosting%'				SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%GlobalBluePoint.ImagesImport%'	SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%GlobalBluePoint.%'				SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%EXECUTE%' AND
	   @wssql_Label NOT LIKE '%powerboard%'						SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%EXEC %'							SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%WINDOWS%'						SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%DATABASE%'						SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'

	IF @wssql_scriptSQL LIKE '%DATTRUSTWORTHY%'					SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%RECONFIGURE%'					SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%sp_configure%'					SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%EXTERNAL_ACCESS%'				SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%DROP%'							SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%ALTER %'							SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%IMPERSONATE%'					SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%DBCC%'							SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%C:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%D:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%E:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%F:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'

	IF @wssql_scriptSQL LIKE '%V:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '% S:%'							SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%W:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%Y:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'
	IF @wssql_scriptSQL LIKE '%Z:%'								SET @wssql_scriptSQL = '--El Sqript Contiene Comandos NO Permitidos.'

	UPDATE tbWebSiteII_SQLScripts
		SET wssql_scriptSQL = @wssql_scriptSQL
		WHERE	comp_id		= @comp_id AND
				wssql_id	= @wssql_id


END
GO
